window.SAN_KHOA_DATA = [{"id": "SK-01", "chapter": "Chương 1. Sản thường", "folder": "01_San_thuong", "title": "Khung chậu nữ về phương diện sản khoa", "author": "Ths. Bùi Thị Thanh Tuyền", "word_count": 2175, "line_count": 142, "key_numbers": ["1,5 cm", "10 cm", "10,5 cm", "11 cm", "12 cm", "12,5 cm", "13 cm", "13,5 cm", "17,5 cm", "22,5 cm", "25,5 cm", "27,5 cm", "4 cm", "4cm", "7 cm", "9,5 cm"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["KHUNG CHẬU NỮ VỀ PHƯƠNG DIỆN SẢN KHOA", "Ths. Bùi Thị Thanh Tuyền"], "bullets": []}, {"heading": "3. Mô tả được chức năng sinh lý của đáy chậu nữ.", "paragraphs": ["Khung chậu là bộ phận có liên quan nhiều nhất trong cơ chế đẻ, thai nhi từ tử cung đi ra ngoài phải đi qua một ống hình trụ cong do các xương tạo thành gọi là khung xương chậu."], "bullets": []}, {"heading": "1. CẤU TẠO VÀ HÌNH THỂ", "paragraphs": ["Khung chậu được cấu tạo bởi 4 xương:", "Xương cánh chậu là 2 xương dẹt to, hình cánh quạt. Mặt trong có đường vô danh chia xương chậu ra làm 2 phần: phần trên gọi là đại khung hay khung chậu lớn, phần dưới gọi là tiểu khung hay khung chậu nhỏ.", "Xương cùng có 5 đốt, đốt trên cùng nhô cao gọi là mỏm nhô. Xương cùng có mặt trước lồi, mặt sau lõm và 2 bờ hai bên.", "Xương cụt có từ 4 đến 6 đốt, cũng có các mặt như xương cùng.", "Bốn xương của khung chậu được khớp với nhau bởi 4 khớp xương, phía trước là khớp mu, phía sau là khớp cùng - cụt, 2 bên là 2 khớp cùng - chậu. Đó là những khớp bán động cho nên các đường kính của khung chậu có thể thay đổi khi chuyển dạ."], "bullets": ["-  Phía trước và hai bên là 2 xương chậu.", "-  Phía sau ở trên là xương cùng và ở dưới là xương cụt."]}, {"heading": "2. ĐẠI KHUNG", "paragraphs": ["Về phương diện sản khoa, đại khung không quan trọng lắm, tuy nhiên nếu đại khung hẹp thì cũng ảnh hưởng đến tiểu khung."], "bullets": []}, {"heading": "2.1. Các đường kính của đại khung (đường kính ngoài)", "paragraphs": [], "bullets": ["- Đường kính trước sau (đường kính Baudeloque): đi từ gai đốt sống thắt lưng thứ 5 đến bờ trên xương mu, đường kính này đo được là 17,5 cm (người Việt Nam).", "- Đường kính lưỡng gai: nối 2 gai chậu trước trên = 22,5 cm.", "- Đường kính lưỡng mào: nối 2 điểm xa nhất của 2 mào chậu = 25,5 cm.", "- Đường kính lưỡng ụ: nối 2 ụ lớn của xương đùi = 27,5 cm."]}, {"heading": "2.2. Hình trám Michaelis", "paragraphs": ["Nối 4 điểm:", "Kết quả:"], "bullets": ["- Ở trên là gai đốt sống thắt lưng thứ 5 (L5).", "- Hai bên là hai gai chậu sau trên.", "- Dưới là đỉnh của nếp liên mông.", "-  Đường kính dọc = 11 cm.", "-  Đường kính ngang = 10 cm.", "-  Đường kính ngang cắt đường kính dọc làm 2 phần: trên 4cm, dưới 7 cm."]}, {"heading": "2.3. Ứng dụng lâm sàng", "paragraphs": ["Trên lâm sàng người ta dùng compa Baudelocque để đo các đường kính ngoài của khung chậu. Nếu các đường kính ngoài nhỏ nhiều thì các đường kính trong cũng hẹp theo, nếu hình trám Michaelis không cân đối thì sẽ có khung chậu méo.", "A.                                          B.                                       C.", "Hình 1.  Dùng compa Baudelocque để đo các đường kính ngoài khung chậu", "A. Đường kính trước sau B. Đường kính lưỡng ụ ngồi  C. Đường kính lưỡng gai"], "bullets": []}, {"heading": "3. TIỂU KHUNG", "paragraphs": ["Tiểu khung rất quan trọng về phương diện sản khoa. Thai lọt hay không là do các đường kính của tiểu khung quyết định. Tiểu khung là một ống xương hình trụ, hơi cong, mặt lõm quay ra phía trước.", "Tiểu khung gồm có 3 phần hay 3 eo:"], "bullets": ["- Thành trước của tiểu khung là chiều cao của khớp vệ = 4 cm.", "- Thành sau là độ dài của xương cùng xương cụt khoảng 12,5 cm.", "- Hai thành bên hẹp dần từ trên xuống dưới nhất là ở gần gai hông nhưng sau đó lại rộng ra.", "- Mặt phẳng đi qua eo trên gọi là mặt phẳng lọt.", "- Mặt phẳng đi qua eo dưới gọi là mặt phẳng sổ."]}, {"heading": "3.1. Eo trên", "paragraphs": ["Eo trên có hình tim."], "bullets": []}, {"heading": "3.1.1. Giới hạn", "paragraphs": [], "bullets": ["- Phía trước là bờ trên của xương mu.", "- Phía sau là mõm nhô.", "- Hai bên là 2 gờ vô danh."]}, {"heading": "3.1.2. Các đường kính của eo trên", "paragraphs": ["Eo trên hoàn toàn bằng xương nên các đường kính của eo trên không thay đổi và còn gọi là đường kính trong của khung chậu.", "Hình 2. Các đường kính trước sau của eo trên", "A. Mỏm nhô - thượng mu;   B. Mỏm nhô - hậu mu;   C. Mỏm nhô - hạ mu", "Về phương diện thực hành bao giờ cũng phải đo đường kính này để biết khung chậu rộng hay hẹp, trên lâm sàng ta chỉ đo được đường kính mỏm nhô - hạ mu (đường kính lâm sàng) nhưng khi thai lọt bắt buộc phải qua đường kính mỏm nhô - hậu mu (đường kính hữu dụng).", "Vậy muốn tìm đường kính mỏm nhô - hậu mu ta lấy đường kính mỏm nhô - hạ mu trừ đi 1,5 cm (1,5 cm là độ dài trung bình của xương mu).", "Hình 3. Đường kính eo trên"], "bullets": ["- Đường kính trước sau:", "+ Đường kính mỏm nhô - thượng mu = 11 cm.", "+ Đường kính mỏm nhô - hạ mu = 12 cm.", "+ Đường kính mỏm  nhô - hậu mu = 10,5 cm.", "- Đường kính chéo: đi từ khớp cùng chậu mỗi bên đến dải chậu lược bên kia.", "+ Đường kính chéo trái  = 12,5 cm (thai thường lọt).", "+ Đường kính chéo phải = 12 cm.", "- Đường kính ngang:", "+ Ngang tối đa      =  13,5 cm (ít giá trị, vì gần mỏm nhô)", "+ Ngang hữu ích = 13 cm (đường kính này cắt đường kính trước sau tại điểm giữa)."]}, {"heading": "3.2. Eo giữa", "paragraphs": ["Eo giữa có hình ống."], "bullets": []}, {"heading": "3.2.1. Giới hạn", "paragraphs": [], "bullets": ["- Phía trước là bờ dưới khớp mu.", "- Phía sau là mặt trước xương cùng II - III.", "- Hai bên là 2 gai toạ."]}, {"heading": "3.2.2. Các đường kính", "paragraphs": ["Đường kính của eo giữa quan trọng nhất là đường kính lưỡng gai hông = 10,5 cm, đường kính này thường để xác định sự xuống của ngôi. Trên lâm sàng người ta lấy đường liên gai hông (vị trí 0) để xem ngôi đã lọt qua eo trên hay chưa."], "bullets": []}, {"heading": "3.3. Eo dưới", "paragraphs": ["Eo dưới có hình trám."], "bullets": []}, {"heading": "3.3.1. Giới hạn", "paragraphs": [], "bullets": ["- Phía trước là bờ dưới của xương mu.", "- Phía sau là đỉnh của xương cụt.", "- Hai bên là hai ụ ngồi."]}, {"heading": "3.3.2. Các đường kính", "paragraphs": [], "bullets": ["- Đường kính trước sau: đường kính mỏn cụt - hạ mu = 9,5 cm, đường kính này ít quan trọng vì có thể dãn đến 12 cm.", "- Đường kính ngang: đường kính lưỡng ụ ngồi = 10,5 - 11 cm. Đây là đường kính quan trọng nhất của eo dưới. Nếu đường kính này hẹp thì thai sẽ không sổ được."]}, {"heading": "4. XẾP LOẠI KHUNG CHẬU", "paragraphs": ["Trên thực tế có nhiều dạng khung chậu khác nhau và cũng có nhiều cách xếp loại khung chậu. Sau đây là cách xếp loại khung chậu theo Caldwell-Moloy:", ". Khung chậu dạng nữ", "Thường thấy nhất ở phụ nữ. Đây là loại khung chậu có hình dạng đều đặn, đường kính từ trục giữa ra trước và ra sau gần bằng nhau. Nhìn toàn diện khung chậu loại này có hình bầu dục ngang, đường kính ngang lớn hơn đường kính trước sau một ít. Gai hông không nhọn.", "Hình 4. Khung chậu dạng nữ", ". Khung chậu dạng nam", "Giống khung chậu đàn ông. Khung chậu dạng này có đường kính từ trục giữa ra trước dài hơn ra sau rõ rệt. Nhìn toàn diện khung chậu dạng này có hình quả tim, phần sau hơi phẳng, mõn nhô gồ ra phía trước, gai hông nhọn.", "Hình 5. Khung chậu dạng nam", ". Khung chậu dạng hầu", "Giống như khung chậu loài khỉ. Eo trên hình bầu dục theo hướng trước sau. Dạng khung chậu này có đường kính ngang nhỏ hơn đường kính trước sau, hai gai hông nhọn, xương cùng dài.", "Hình 6. Khung chậu dạng vượn người", ". Khung chậu dẹt", "Eo trên dạng hình thận, dạng khung chậu này có đường kính ngang lớn hơn rõ rệt so với đường kính trước sau. Xương cùng ngắn và ngửa ra sau.", "Hình 7. Khung chậu dạng dẹt"], "bullets": []}, {"heading": "5. THỦ THUẬT ĐO KHUNG CHẬU", "paragraphs": ["Khám khung chậu của một sản phụ ở những tháng cuối của thai kỳ hay mới bắt đầu chuyển dạ để ước lượng xem khung chậu có đủ rộng hay không để tiên lượng cho cuộc sinh là một điều hết sức quan trọng. Tuy nhiên trên lâm sàng người ta chỉ có thể đo một vài đường kính của khung  chậu mà thôi, các đường kính còn lại chỉ có thể được đánh giá, ước lượng một cách tương đối chứ không thể có số đo cụ thể, chính xác.", "Khám đại khung: đo các đường kính ngoài của khung chậu và hình trám Michaelis như đã nêu ở trên.", "Khám tiểu khung: lần lượt khám eo trên, eo giữa, eo dưới.", "Eo trên, ta đo đường kính trước sau (đường kính nhô- hạ mu). Đánh giá gờ vô danh, bình thường ta chỉ sờ được khoảng 1/2 đường vô danh, nếu sờ hơn 2/3 đường vô danh thì có khả năng là hẹp đường kính ngang eo trên.", "Hình 8.  Thủ thuật khám eo trên (đo đường kính nhô hậu mu)", "Eo giữa, đánh giá đường kính ngang bằng cách khám hai gai hông nhô nhiều hay ít. Đánh giá độ cong của xương cùng, nếu mặt trước của xương cùng cong quá hay phẳng quá cũng không tốt.", "Eo dưới, đo đường kính ngang tức là đường kính lưỡng ụ ngồi. Đo góc vòm vệ, bình thường góc này phải trên 85o."], "bullets": []}, {"heading": "6.1. Giải phẫu đáy chậu", "paragraphs": ["Khung chậu được bao bọc mặt ngoài, mặt trong bởi các cơ và cân. Lỗ trên (eo trên) thông với ổ bụng. Lỗ dưới (eo dưới) có những tổ chức cơ mỡ, da, bịt lại gọi là đáy chậu.", "Đáy chậu gồm tất cả các phần mềm cân, cơ, dây chằng, bịt lỗ dưới của khung chậu.", "Đáy chậu có hình trám, giới hạn phía trước là xương mu, hai bên là hai ụ ngồi, phía sau là đỉnh xương cụt.", "Đường kính lưỡng ụ ngồi chia đáy chậu làm hai phần:", "Nam và nữ có cấu tạo đáy chậu sau giống nhau nhưng đáy chậu trước thì khác nhau. Từ sâu ra nông, đáy chậu gồm ba tầng. Tầng sâu, tầng giữa và tầng nông. Mỗi tầng gồm có cơ và được bao bọc bởi một lớp cân riêng.", "Các cơ nâng hậu môn, cơ ngang nông, cơ ngang sâu, cơ hành hang, cơ khít âm môn, cơ thắt hậu môn và cơ thắt niệu đạo đều bám vào nút thớ trung tâm đáy chậu (nút thớ trung tâm là một cơ và sợi nằm giữa ống hậu môn và cơ của tầng sinh môn trước).", "Hình 9. Đáy chậu"], "bullets": ["-\tPhần trước gọi là đáy chậu trước (đáy chậu niệu sinh dục).", "-\tPhần sau gọi là đáy chậu sau (đáy chậu hậu môn).", "- Tầng sâu: gồm có cơ nâng hậu môn và cơ ngồi cụt, được bao bọc bởi hai lá của cân tầng sinh môn sâu.", "- Tầng giữa: gồm cơ ngang sâu và cơ thắt niệu đạo. Cả hai cơ này đều ở đáy chậu trước và được bao bọc bởi hai lá cân của đáy chậu giữa.", "- Tầng nông: gồm 5 cơ là cơ hành hang, cơ ngồi hang, cơ ngang nông, cơ khít âm môn và cơ thắt hậu môn. Cơ thắt hậu môn nằm ở đáy chậu sau, bốn cơ còn lại đều ở đáy chậu trước."]}, {"heading": "6.2. Chức năng sinh lý của đáy chậu", "paragraphs": ["Đáy chậu có nhiệm vụ nâng đỡ các tạng trong tiểu khung (bàng quang, tử cung, âm đạo, trực tràng). Khi đẻ, đáy chậu phải giãn mỏng và mở ra để cho ngôi thai đi qua. Khi thai qua eo dưới, ngôi phải đi qua đáy chậu mới sổ được. Trong giai đoạn sổ thai, nếu đáy chậu không giãn nở tốt sẽ bị rách và có thể  tổn thương đến nút thớ trung tâm. Để tránh tổn thương này trong lúc đẻ người ta chủ động cắt tầng sinh môn, nhất là ở người con so, đặc biệt là con so lớn tuổi (do tầng sinh môn rắn chắc).", "Trong trường hợp tầng sinh môn bị nhão do sinh nhiều lần, hoặc bị rách mà không khâu phục hồi dễ dẫn đến sa sinh dục sau này."], "bullets": []}], "raw_text": "KHUNG CHẬU NỮ VỀ PHƯƠNG DIỆN SẢN KHOA\nThs. Bùi Thị Thanh Tuyền\nMục tiêu học tập\n1. Mô tả cấu tạo và hình thể một khung xương chậu nữ.\n2. Kể ra được các đường kính của đại khung và tiểu khung.\n3. Mô tả được chức năng sinh lý của đáy chậu nữ.\n\nKhung chậu là bộ phận có liên quan nhiều nhất trong cơ chế đẻ, thai nhi từ tử cung đi ra ngoài phải đi qua một ống hình trụ cong do các xương tạo thành gọi là khung xương chậu.\n\n1. CẤU TẠO VÀ HÌNH THỂ\nKhung chậu được cấu tạo bởi 4 xương:\n-  Phía trước và hai bên là 2 xương chậu.\n-  Phía sau ở trên là xương cùng và ở dưới là xương cụt.\nXương cánh chậu là 2 xương dẹt to, hình cánh quạt. Mặt trong có đường vô danh chia xương chậu ra làm 2 phần: phần trên gọi là đại khung hay khung chậu lớn, phần dưới gọi là tiểu khung hay khung chậu nhỏ.\nXương cùng có 5 đốt, đốt trên cùng nhô cao gọi là mỏm nhô. Xương cùng có mặt trước lồi, mặt sau lõm và 2 bờ hai bên.\nXương cụt có từ 4 đến 6 đốt, cũng có các mặt như xương cùng.\nBốn xương của khung chậu được khớp với nhau bởi 4 khớp xương, phía trước là khớp mu, phía sau là khớp cùng - cụt, 2 bên là 2 khớp cùng - chậu. Đó là những khớp bán động cho nên các đường kính của khung chậu có thể thay đổi khi chuyển dạ.\n2. ĐẠI KHUNG\nVề phương diện sản khoa, đại khung không quan trọng lắm, tuy nhiên nếu đại khung hẹp thì cũng ảnh hưởng đến tiểu khung.\n2.1. Các đường kính của đại khung (đường kính ngoài)\n- Đường kính trước sau (đường kính Baudeloque): đi từ gai đốt sống thắt lưng thứ 5 đến bờ trên xương mu, đường kính này đo được là 17,5 cm (người Việt Nam).\n- Đường kính lưỡng gai: nối 2 gai chậu trước trên = 22,5 cm.\n- Đường kính lưỡng mào: nối 2 điểm xa nhất của 2 mào chậu = 25,5 cm.\n- Đường kính lưỡng ụ: nối 2 ụ lớn của xương đùi = 27,5 cm.\n2.2. Hình trám Michaelis\nNối 4 điểm:\n- Ở trên là gai đốt sống thắt lưng thứ 5 (L5).\n- Hai bên là hai gai chậu sau trên.\n- Dưới là đỉnh của nếp liên mông.\nKết quả:\n-  Đường kính dọc = 11 cm.\n-  Đường kính ngang = 10 cm.\n-  Đường kính ngang cắt đường kính dọc làm 2 phần: trên 4cm, dưới 7 cm.\n2.3. Ứng dụng lâm sàng\nTrên lâm sàng người ta dùng compa Baudelocque để đo các đường kính ngoài của khung chậu. Nếu các đường kính ngoài nhỏ nhiều thì các đường kính trong cũng hẹp theo, nếu hình trám Michaelis không cân đối thì sẽ có khung chậu méo.\n\n\nA.                                          B.                                       C.\nHình 1.  Dùng compa Baudelocque để đo các đường kính ngoài khung chậu\nA. Đường kính trước sau B. Đường kính lưỡng ụ ngồi  C. Đường kính lưỡng gai\n3. TIỂU KHUNG\nTiểu khung rất quan trọng về phương diện sản khoa. Thai lọt hay không là do các đường kính của tiểu khung quyết định. Tiểu khung là một ống xương hình trụ, hơi cong, mặt lõm quay ra phía trước.\n- Thành trước của tiểu khung là chiều cao của khớp vệ = 4 cm.\n- Thành sau là độ dài của xương cùng xương cụt khoảng 12,5 cm.\n- Hai thành bên hẹp dần từ trên xuống dưới nhất là ở gần gai hông nhưng sau đó lại rộng ra.\n- Mặt phẳng đi qua eo trên gọi là mặt phẳng lọt.\n- Mặt phẳng đi qua eo dưới gọi là mặt phẳng sổ.\nTiểu khung gồm có 3 phần hay 3 eo:\n3.1. Eo trên\nEo trên có hình tim.\n3.1.1. Giới hạn\n- Phía trước là bờ trên của xương mu.\n- Phía sau là mõm nhô.\n- Hai bên là 2 gờ vô danh.\n3.1.2. Các đường kính của eo trên\nEo trên hoàn toàn bằng xương nên các đường kính của eo trên không thay đổi và còn gọi là đường kính trong của khung chậu.\n- Đường kính trước sau:\n+ Đường kính mỏm nhô - thượng mu = 11 cm.\n+ Đường kính mỏm nhô - hạ mu = 12 cm.\n+ Đường kính mỏm  nhô - hậu mu = 10,5 cm.\n\nHình 2. Các đường kính trước sau của eo trên\nA. Mỏm nhô - thượng mu;   B. Mỏm nhô - hậu mu;   C. Mỏm nhô - hạ mu\n\nVề phương diện thực hành bao giờ cũng phải đo đường kính này để biết khung chậu rộng hay hẹp, trên lâm sàng ta chỉ đo được đường kính mỏm nhô - hạ mu (đường kính lâm sàng) nhưng khi thai lọt bắt buộc phải qua đường kính mỏm nhô - hậu mu (đường kính hữu dụng).\nVậy muốn tìm đường kính mỏm nhô - hậu mu ta lấy đường kính mỏm nhô - hạ mu trừ đi 1,5 cm (1,5 cm là độ dài trung bình của xương mu).\n- Đường kính chéo: đi từ khớp cùng chậu mỗi bên đến dải chậu lược bên kia.\n+ Đường kính chéo trái  = 12,5 cm (thai thường lọt).\n+ Đường kính chéo phải = 12 cm.\n\n\nHình 3. Đường kính eo trên\n- Đường kính ngang:\n+ Ngang tối đa      =  13,5 cm (ít giá trị, vì gần mỏm nhô)\n+ Ngang hữu ích = 13 cm (đường kính này cắt đường kính trước sau tại điểm giữa).\n3.2. Eo giữa\nEo giữa có hình ống.\n3.2.1. Giới hạn\n- Phía trước là bờ dưới khớp mu.\n- Phía sau là mặt trước xương cùng II - III.\n- Hai bên là 2 gai toạ.\n3.2.2. Các đường kính\nĐường kính của eo giữa quan trọng nhất là đường kính lưỡng gai hông = 10,5 cm, đường kính này thường để xác định sự xuống của ngôi. Trên lâm sàng người ta lấy đường liên gai hông (vị trí 0) để xem ngôi đã lọt qua eo trên hay chưa.\n3.3. Eo dưới\nEo dưới có hình trám.\n3.3.1. Giới hạn\n- Phía trước là bờ dưới của xương mu.\n- Phía sau là đỉnh của xương cụt.\n- Hai bên là hai ụ ngồi.\n3.3.2. Các đường kính\n- Đường kính trước sau: đường kính mỏn cụt - hạ mu = 9,5 cm, đường kính này ít quan trọng vì có thể dãn đến 12 cm.\n- Đường kính ngang: đường kính lưỡng ụ ngồi = 10,5 - 11 cm. Đây là đường kính quan trọng nhất của eo dưới. Nếu đường kính này hẹp thì thai sẽ không sổ được.\n\n4. XẾP LOẠI KHUNG CHẬU\nTrên thực tế có nhiều dạng khung chậu khác nhau và cũng có nhiều cách xếp loại khung chậu. Sau đây là cách xếp loại khung chậu theo Caldwell-Moloy:\n. Khung chậu dạng nữ\nThường thấy nhất ở phụ nữ. Đây là loại khung chậu có hình dạng đều đặn, đường kính từ trục giữa ra trước và ra sau gần bằng nhau. Nhìn toàn diện khung chậu loại này có hình bầu dục ngang, đường kính ngang lớn hơn đường kính trước sau một ít. Gai hông không nhọn.\n\nHình 4. Khung chậu dạng nữ\n. Khung chậu dạng nam\nGiống khung chậu đàn ông. Khung chậu dạng này có đường kính từ trục giữa ra trước dài hơn ra sau rõ rệt. Nhìn toàn diện khung chậu dạng này có hình quả tim, phần sau hơi phẳng, mõn nhô gồ ra phía trước, gai hông nhọn.\n\nHình 5. Khung chậu dạng nam\n. Khung chậu dạng hầu\nGiống như khung chậu loài khỉ. Eo trên hình bầu dục theo hướng trước sau. Dạng khung chậu này có đường kính ngang nhỏ hơn đường kính trước sau, hai gai hông nhọn, xương cùng dài.\n\nHình 6. Khung chậu dạng vượn người\n\n. Khung chậu dẹt\nEo trên dạng hình thận, dạng khung chậu này có đường kính ngang lớn hơn rõ rệt so với đường kính trước sau. Xương cùng ngắn và ngửa ra sau.\n\nHình 7. Khung chậu dạng dẹt\n5. THỦ THUẬT ĐO KHUNG CHẬU\nKhám khung chậu của một sản phụ ở những tháng cuối của thai kỳ hay mới bắt đầu chuyển dạ để ước lượng xem khung chậu có đủ rộng hay không để tiên lượng cho cuộc sinh là một điều hết sức quan trọng. Tuy nhiên trên lâm sàng người ta chỉ có thể đo một vài đường kính của khung  chậu mà thôi, các đường kính còn lại chỉ có thể được đánh giá, ước lượng một cách tương đối chứ không thể có số đo cụ thể, chính xác.\nKhám đại khung: đo các đường kính ngoài của khung chậu và hình trám Michaelis như đã nêu ở trên.\nKhám tiểu khung: lần lượt khám eo trên, eo giữa, eo dưới.\nEo trên, ta đo đường kính trước sau (đường kính nhô- hạ mu). Đánh giá gờ vô danh, bình thường ta chỉ sờ được khoảng 1/2 đường vô danh, nếu sờ hơn 2/3 đường vô danh thì có khả năng là hẹp đường kính ngang eo trên.\n\nHình 8.  Thủ thuật khám eo trên (đo đường kính nhô hậu mu)\nEo giữa, đánh giá đường kính ngang bằng cách khám hai gai hông nhô nhiều hay ít. Đánh giá độ cong của xương cùng, nếu mặt trước của xương cùng cong quá hay phẳng quá cũng không tốt.\nEo dưới, đo đường kính ngang tức là đường kính lưỡng ụ ngồi. Đo góc vòm vệ, bình thường góc này phải trên 85o.\n6. ĐÁY CHẬU\n6.1. Giải phẫu đáy chậu\nKhung chậu được bao bọc mặt ngoài, mặt trong bởi các cơ và cân. Lỗ trên (eo trên) thông với ổ bụng. Lỗ dưới (eo dưới) có những tổ chức cơ mỡ, da, bịt lại gọi là đáy chậu.\nĐáy chậu gồm tất cả các phần mềm cân, cơ, dây chằng, bịt lỗ dưới của khung chậu.\nĐáy chậu có hình trám, giới hạn phía trước là xương mu, hai bên là hai ụ ngồi, phía sau là đỉnh xương cụt.\nĐường kính lưỡng ụ ngồi chia đáy chậu làm hai phần:\n-\tPhần trước gọi là đáy chậu trước (đáy chậu niệu sinh dục).\n-\tPhần sau gọi là đáy chậu sau (đáy chậu hậu môn).\nNam và nữ có cấu tạo đáy chậu sau giống nhau nhưng đáy chậu trước thì khác nhau. Từ sâu ra nông, đáy chậu gồm ba tầng. Tầng sâu, tầng giữa và tầng nông. Mỗi tầng gồm có cơ và được bao bọc bởi một lớp cân riêng.\n- Tầng sâu: gồm có cơ nâng hậu môn và cơ ngồi cụt, được bao bọc bởi hai lá của cân tầng sinh môn sâu.\n- Tầng giữa: gồm cơ ngang sâu và cơ thắt niệu đạo. Cả hai cơ này đều ở đáy chậu trước và được bao bọc bởi hai lá cân của đáy chậu giữa.\n- Tầng nông: gồm 5 cơ là cơ hành hang, cơ ngồi hang, cơ ngang nông, cơ khít âm môn và cơ thắt hậu môn. Cơ thắt hậu môn nằm ở đáy chậu sau, bốn cơ còn lại đều ở đáy chậu trước.\nCác cơ nâng hậu môn, cơ ngang nông, cơ ngang sâu, cơ hành hang, cơ khít âm môn, cơ thắt hậu môn và cơ thắt niệu đạo đều bám vào nút thớ trung tâm đáy chậu (nút thớ trung tâm là một cơ và sợi nằm giữa ống hậu môn và cơ của tầng sinh môn trước).\n\nHình 9. Đáy chậu\n6.2. Chức năng sinh lý của đáy chậu\nĐáy chậu có nhiệm vụ nâng đỡ các tạng trong tiểu khung (bàng quang, tử cung, âm đạo, trực tràng). Khi đẻ, đáy chậu phải giãn mỏng và mở ra để cho ngôi thai đi qua. Khi thai qua eo dưới, ngôi phải đi qua đáy chậu mới sổ được. Trong giai đoạn sổ thai, nếu đáy chậu không giãn nở tốt sẽ bị rách và có thể  tổn thương đến nút thớ trung tâm. Để tránh tổn thương này trong lúc đẻ người ta chủ động cắt tầng sinh môn, nhất là ở người con so, đặc biệt là con so lớn tuổi (do tầng sinh môn rắn chắc).\nTrong trường hợp tầng sinh môn bị nhão do sinh nhiều lần, hoặc bị rách mà không khâu phục hồi dễ dẫn đến sa sinh dục sau này.\nCâu hỏi: 1. Hình thể, các đường kính đại khung?\n2. Các đường kính của tiểu khung và ý nghĩa của nó?\n3. Cấu tạo giải phẫu và chức năng sinh lý đáy chậu?", "priority": "Trung bình"}, {"id": "SK-02", "chapter": "Chương 1. Sản thường", "folder": "01_San_thuong", "title": "Sinh lý phụ khoa", "author": "Bs.CKII Nguyễn Thị Tuyết", "word_count": 3399, "line_count": 140, "key_numbers": ["0,05mm", "0,1mm", "0,5g", "10 cm", "11 cm", "14 ngày", "20 tuần", "28 ngày", "2cm", "35 ngày", "6 ngày", "60ml", "72 giờ"], "key_drugs": ["oxytocin"], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["SINH LÝ PHỤ KHOA", "Bs.CKII Nguyễn Thị Tuyết"], "bullets": []}, {"heading": "4. Liệt kê được các thời kỳ hoạt động sinh dục của người phụ nữ", "paragraphs": ["Sinh lý phụ khoa thể hiện tất cả những vấn đề có liên quan đến những thay đổi về tính chất sinh dục và hoạt động sinh dục của người phụ nữ. Nếu kinh nguyệt là một biểu hiện bên ngoài rõ ràng của một phần hoạt động sinh sản ở người phụ nữ, thì bên trong cơ thể có một sự phối hợp chặt chẽ và vô cùng phức tạp của hệ thống nội tiết sinh sản, vùng dưới đồi, tuyến yên, buồng trứng. Các hormon buồng trứng một mặt tác động trực tiếp lên phần của cơ quan sinh dục như tử cung, cổ tử cung, vòi trứng, âm hộ, âm đạo, tuyến vú, mặt khác lại tác động trở lại vùng dưới đồi tuyến yên tạo thành cơ chế hồi tác. Khi có một rối loạn bất kỳ của quá trình hoạt động này sẽ dẫn đến các bệnh lý phụ khoa cũng như ảnh hưởng đến chức năng sinh sản."], "bullets": []}, {"heading": "1.1. Vùng dưới đồi", "paragraphs": ["Trung khu sinh dục của vùng dưới đồi nằm trong nền của trung não, phía trên giao thoa thị giác, gồm một nhóm các nhân thần kinh giàu mạch máu, có khả năng chế tiết hormon. Nhân trên thị chế tiết vasopressin, nhân bên thất chế tiết oxytocin, các chất này được các sợi thần kinh dẫn xuống thùy sau tuyến yên.", "Củ xám, nhân bụng giữa, nhân lưng giữa và nhân cung tiết ra các hormon giải phóng. Trong số đó có các hormon giải phóng gonadotropin, gọi tắt là GnRH (Gonadotropin Releasing Hormon)."], "bullets": []}, {"heading": "1.2. Tuyến yên", "paragraphs": ["Tuyến yên nằm trong hố yên, nặng khoảng 0,5g, có hai thùy. Thùy trước là một tuyến nội tiết nên còn được gọi là tuyến yên tuyến (adenohypophysis). Thùy sau là một mô giống thần kinh, còn được gọi là tuyến yên thần kinh (neurohypophysis), không phải là tuyến nội tiết. Về phương diện hoạt động sinh dục, thùy trước tuyến yên chế tiết các hormon hướng sinh dục kích thích các tuyến sinh dục, đồng thời chế tiết prolactin kích thích tuyến vú. Hai hormon hướng sinh dục là FSH và LH đều là glycoprotein.", "FSH và LH có các đường cong chế tiết trong chu kỳ kinh gần như song song với nhau và có đỉnh cao vào trước phóng noãn một ngày. Tuy nhiên, đỉnh FSH không cao đột ngột như đỉnh LH, cũng không tăng nhiều như đỉnh LH. Vào trước ngày phóng noãn, đỉnh LH có khi đạt trị số gấp tới 5-10 lần. Vào nửa sau của vòng kinh, trị số của FSH hơi thấp hơn so với nửa đầu của vòng kinh. Nồng độ LH vài ngày trước phóng noãn có thể tăng nhanh đột ngột, đạt đỉnh cao trước phóng noãn một ngày, sau đó lại giảm nhanh, xuống mức như trước khi phóng noãn."], "bullets": ["- FSH (Follicle Stimulating Hormon) kích thích nang noãn của buồng trứng phát triển và trưởng thành.", "- LH (Luteinizing Hormon) kích thích nang noãn trưởng thành phóng noãn, kích thích hình thành hoàng thể và kích thích hoàng thể chế tiết.", "- Prolactin là một hormon kích thích tuyến vú tiết sữa."]}, {"heading": "1.3. Buồng trứng", "paragraphs": ["Buồng trứng là tuyến sinh dục nữ, có 2 buồng trứng hình bầu dục nằm hai bên, kích thước 4x2x1 cm; có hai chức năng: Chức năng ngoại tiết tạo noãn và chức năng nội tiết tạo các hormon sinh dục.", "Buồng trứng có rất nhiều nang noãn. Số lượng các nang noãn này giảm rất nhanh theo thời gian. Khi còn là thai nhi ở tuổi thai 20 tuần, hai bên buồng trứng có 1,5 - 2 triệu nang noãn nguyên thủy. Nhưng khi em bé gái ra đời, số lượng các nang noãn này đã giảm xuống rất nhiều, chỉ còn chừng 200.000 - 300.000, nghĩa là giảm đi khoảng 10 lần trong thời gian 20 tuần. Vào tuổi dậy thì, số lượng nang noãn chỉ còn 20.000 - 30.000. Sự giảm số lượng các nang noãn là do các nang noãn bị thoái triển teo đi, các nang còn lại cũng trên đà thoái triển nhưng chậm hơn. Nếu những noãn nằm trong các nang này được thụ tinh muộn thì phôi được hình thành có thể có khả năng phát triển kém. Buồng trứng không có khả năng sản sinh những nang noãn mới.", "Hình 1. Trục dưới đồi - tuyến yên - sinh dục"], "bullets": []}, {"heading": "1.3.1. Hoạt động sinh sản", "paragraphs": ["Nang noãn nguyên thủy có đường kính 0,05mm. Dưới tác dụng của FSH, nang noãn lớn lên, chín. Nang noãn chín còn gọi là nang De Graaf, có đường kính 1,5-2cm. Noãn chứa trong nang này cũng chín và chịu tác dụng phân bào. Noãn chín có đường kính 0,1mm (100 micromet).", "Trong mỗi chu kỳ kinh thường chỉ có một nang noãn phát triển để trở thành nang De Graaf. Đó là nang nhạy nhất trong vòng kinh ấy. Nang này phát triển từ một nang đã đang phát triển dở dang từ cuối vòng kinh trước.", "Nang noãn chín là một nang có hốc với các thành phần:", "Dưới tác dụng của LH, nang noãn càng chín nhanh, lồi ra phần ngoại vi của buồng trứng rồi vỡ, phóng noãn ra ngoài. Đó là hiện tượng phóng noãn. Cũng dưới tác dụng của LH, phần còn lại của nang noãn tại buồng trứng dần dần biến thành hoàng thể. Vào cuối vòng kinh, khi LH trong máu giảm xuống, hoàng thể teo đi, để lại sẹo trắng, gọi là vật trắng hay bạch thể."], "bullets": ["- Vỏ nang ngoài làm bởi các sợi liên kết, thực sự chỉ có tác dụng bọc lấy nang.", "- Vỏ nang trong có nhiều mạch máu, là một tuyến nội tiết, có khả năng chế tiết estrogen.", "- Màng tế bào hạt có tới 10-15 lớp tế bào hạt.", "- Noãn trưởng thành đã giảm phân, có 22 nhiễm sắc thể thường và một nhiễm sắc thể giới X.", "- Hốc nang chứa dịch nang trong đó có estrone."]}, {"heading": "1.3.2. Hoạt động nội tiết", "paragraphs": ["Các tế bào hạt và những tế bào của vỏ nang trong chế tiết ra 3 hormon chính: estrogen, progesteron và androgen. Các hormon này là hormon sinh dục, có nhân steron nên còn được gọi là steroid sinh dục.", "Nang noãn có thể coi là một đơn vị hoạt động của buồng trứng cả về phương diện sinh sản, cả về phương diện nội tiết. Thật vậy, nang noãn chín có khả năng phóng ra một noãn chín để thụ tinh được. Các hormon của nang noãn và của hoàng thể đủ để làm thay đổi niêm mạc tử cung giúp cho trứng làm tổ. Và nếu như người phụ nữ không thụ thai thì cũng đủ gây được kinh nguyệt."], "bullets": ["- Vỏ nang trong chế tiết estrogen.", "- Các tế bào hạt của hoàng thể chế tiết progesteron.", "- Các tế bào của rốn buồng trứng chế tiết androgen."]}, {"heading": "2.1. Estrogen", "paragraphs": ["Đối với niêm mạc tử cung", "Đối với cổ tử cung"], "bullets": ["- Đối với cơ tử cung", "+ Làm phát triển cơ tử cung do làm tăng độ lớn, độ dài các sợi cơ.", "+ Làm tăng nhạy cảm của cơ tử cung đối với oxytoxin và các nhân tố gây co tử cung.", "+ Kích thích phân bào, gây quá sản niêm mạc tử cung, ung thư niêm mạc tử cung.", "+ Khi tụt đột ngột làm bong niêm mạc tử cung, gây chảy máu kinh nguyệt.", "+ Làm tăng tiết, làm trong và loãng chất nhầy cổ tử cung, làm mở cổ tử cung khiến tinh trùng dễ xâm nhập lên đường sinh dục trên của người phụ nữ.", "- Đối với âm đạo", "+ Làm phát triển và làm dày biểu mô âm đạo", "+ Làm biểu mô âm đạo chứa Glycogen. Trực khuẩn Doderlein có trong âm đạo biến glycogen này thành acid lactic, khiến pH âm đạo toan tính, ngăn cản phát triển của các vi khuẩn gây bệnh.", "- Đối với âm hộ", "+ Làm phát triển các môi của âm hộ", "+ Làm phát triển và chế tiết các tuyến Skene và Bartholin của âm hộ", "- Đối với vú", "+ Làm phát triển các tuyến sữa và mô đệm của vú, khiến vú nở nang", "- Các tác dụng khác", "+ Giữ nước, giữ Kali, gây phù.", "+ Kích thích tình dục.", "+ Làm căng các dây thanh âm khiến tiếng nói có âm sắc cao", "+ Giúp giữ Canxi ở xương, đỡ loãng xương."]}, {"heading": "2.2. Progesteron", "paragraphs": [], "bullets": ["- Đối với cơ tử cung", "+ Làm mềm cơ tử cung, giảm nhạy với oxytoxin và các nhân tố gây co", "+ Hiệp đồng với estrogen, làm tăng phát triển cơ tử cung", "- Đối với niêm mạc tử cung", "+ Làm teo niêm mạc tử cung", "+ Hiệp đồng với estrogen, làm niêm mạc tử cung chế tiết. Hiệp đồng tốt nhất khi tỷ lệ estrogen/progesteron là 1/10.", "- Đối với cổ tử cung", "+ Ức chế chế tiết chất nhầy", "- Đối với âm đạo", "+ Làm phát triển biểu mô âm đạo", "- Đối với vú", "+ Làm phát triển ống dẫn sữa", "+ Hiệp đồng với estrogen làm phát triển toàn diện vú", "- Các tác dụng khác", "+ Lợi niệu", "+ Tăng thân nhiệt 0.3-0.5oC"]}, {"heading": "3. SINH LÝ CHU KỲ KINH NGUYỆT", "paragraphs": ["Trong chu kỳ kinh nguyệt bình thường, các hormon được tiết ra có tính chu kỳ, trật tự. Song song với sự tiết hormon này, niêm mạc tử cung tăng sinh nhằm chuẩn bị cho sự làm tổ của phôi."], "bullets": []}, {"heading": "3.1. Chu kỳ kinh nguyệt", "paragraphs": ["Ở người, chu kỳ kinh nguyệt có thể được phân chia thành hai phần: chu kỳ buồng trứng và chu kỳ tử cung. Chu kỳ buồng trứng được phân chia thành giai đoạn nang noãn và giai đoạn hoàng thể, chu kỳ tử cung được phân chia thành giai đoạn tăng sinh và giai đoạn chế tiết tương ứng và hành kinh."], "bullets": []}, {"heading": "3.1.1. Chu kỳ buồng trứng", "paragraphs": [], "bullets": ["- Giai đoạn nang noãn: Cơ chế điều hòa ngược của hormon thúc đẩy sự phát triển có tính trật tự của một nang noãn vượt trội. Nang này trưởng thành vào giữa chu kỳ và chuẩn bị cho sự phóng noãn. Thời gian trung bình của giai đoạn nang noãn là 10-14 ngày. Sự thay đổi của thời gian giai đoạn nang noãn chịu trách nhiệm cho hầu hết của những thay đổi trong toàn bộ chu kỳ.", "- Giai đoạn hoàng thể: Tính từ lúc phóng noãn đến lúc bắt đầu hành kinh, kéo dài trung bình 14 ngày."]}, {"heading": "3.1.2. Chu kỳ tử cung", "paragraphs": ["Sau khi hành kinh, màng rụng đáy gồm các tuyến nguyên thuỷ và mô đệm ít, đặc nằm sát cơ tử cung. Giai đoạn tăng sinh đặc trưng bởi sự nguyên phân liên tục của màng rụng chức năng tương ứng với sự tăng nồng độ estrogen trong tuần hoàn. Lúc bắt đầu giai đoạn tăng sinh, niêm mạc tử cung tương đối mỏng. Sự thay đổi rõ nét trong thời kỳ này là sự phát triển của các tuyến nội mạc ban đầu thẳng, hẹp và ngắn thành các cấu trúc dài hơn và cuộn xoắn.", "Trong một chu kỳ 28 ngày điển hình, sự phóng noãn xảy ra vào ngày thứ 14. Trong vòng 48-72 giờ sau phóng noãn, sự khởi phát chế tiết progesteron tạo nên sự thay đổi biểu hiện mô học của niêm mạc tử cung sang giai đoạn chế tiết. Giai đoạn chế tiết đặc trưng bởi ảnh hưởng của progesteron cùng với estrogen tác động lên tế bào.", "Ngày 6-7 sau phóng noãn, hoạt động chế tiết các tuyến đạt cực đại và nội mạc đã được chuẩn bị tối ưu cho sự làm tổ của phôi. Cùng với sự tăng phù nề mô đệm tối đa vào cuối pha chế tiết, các động mạch xoắn có thể nhìn thấy rõ ràng rồi dài dần và cuộn lại. Khoảng ngày 2 trước khi hành kinh, có sự gia tăng đáng kể số lượng lymphocyte đa nhân di chuyển vào từ hệ thống mạch máu. Sự xâm nhập bạch cầu báo trước sự suy sụp của mô đệm niêm mạc và khởi phát hành kinh.", "Khi không có sự làm tổ của phôi, sự chế tiết của các tuyến ngừng lại và xảy ra sự phá vỡ không đều lớp màng rụng chức năng. Kết quả làm bong lớp niêm mạc này, gây nên hành kinh. Sự thoái hoá của hoàng thể và tụt giảm đột ngột các sản phẩm chế tiết estrogen và progesteron là nguyên nhân của bong niêm mạc.", "Một chu kỳ kinh nguyệt bình thường kéo dài 21-35 ngày, thời gian hành kinh 2-6 ngày và lượng máu mất trung bình 20-60ml.", "Hình 2. Thay đổi hormon, chu kỳ buồng trứng", "và niêm mạc tử cung trong chu kỳ kinh nguyệt bình thường"], "bullets": ["- Giai đoạn tăng sinh", "- Giai đoạn chế tiết", "- Hành kinh"]}, {"heading": "3.2.6. Lượng estrogen bắt đầu giảm ngay trước phóng noãn, tiếp tục giảm trong giai đoạn hoàng thể sớm. Cho đến giữa giai đoạn hoàng thể, estrogen bắt đầu tăng trở lại do hoàng thể tiết ra.", "paragraphs": ["Lượng progesteron tăng nhanh chóng sau phóng noãn và có thể được xem như là một dấu hiệu của sự phóng noãn.", "Cả estrogen và progesteron vẫn còn tăng trong thời gian tồn tại của hoàng thể. Sau đó, hàm lượng của chúng giảm khi hoàng thể thoái hóa, vì thế tạo ra một giai đoạn cho chu kỳ kế tiếp."], "bullets": []}, {"heading": "4. CÁC THỜI KỲ HOẠT ĐỘNG SINH DỤC Ở PHỤ NỮ", "paragraphs": ["Cuộc đời hoạt động sinh dục của người phụ nữ được chia làm bốn thời kỳ."], "bullets": []}, {"heading": "4.1. Thời kỳ trẻ em (trước dậy thì)", "paragraphs": ["Trong tuổi thiếu niên, buồng trứng ở trong giai đoạn im lặng về mặt nội tiết, mặc dù về mặt hình thái người ta cũng phát hiện được sự trưởng thành và sự thoái hoá của nang noãn. Tuy vậy các biến đổi hình thái này không đi kèm với hoạt động nội tiết của buồng trứng. Trong thời kỳ này cũng không có sự phát triển của nang noãn đến giai đoạn nang trội hoặc hình thành hoàng thể. Sự im lặng của buồng trứng về mặt nội tiết là do sự “chưa chín muồi của vùng dưới đồi“."], "bullets": []}, {"heading": "4.2. Giai đoạn dậy thì", "paragraphs": ["Chức năng nội tiết của buồng trứng bắt đầu hoạt động khi các tế bào thần kinh sản xuất GnRH của vùng dưới đồi đã có thể bắt đầu giải phóng GnRH một cách đồng bộ và theo xung nhịp vào hệ thống động mạch cửa tuyến yên"], "bullets": []}, {"heading": "4.2.1. Sự phát triển vú", "paragraphs": ["Estrogen bắt đầu được chế tiết từ buồng trứng có tác dụng lâm sàng thấy được đầu tiên thông qua sự phát triển vú. Núm vú nổi rõ, tiếp theo là sự phát triển mô tuyến vú, tăng sinh biểu mô ống tuyến và thuỳ tuyến dưới tác dụng của estrogen và prolactin."], "bullets": []}, {"heading": "4.2.2. Sự phát triển lông mu", "paragraphs": ["Tiếp sau vú là sự phát triển lông mu và lông nách, chủ yếu là dưới tác dụng của androgen. Các androgen này một phần có nguồn gốc buồng trứng, một phần từ tuyến thượng thận và một phần thông qua chuyển hoá ở ngoại vi."], "bullets": []}, {"heading": "4.2.3. Sự tăng trưởng cơ thể", "paragraphs": ["Khoảng một năm sau, sau dấu hiệu dậy thì đầu tiên sẽ xuất hiện sự tăng trưởng cơ thể mạnh mẽ. Các steroid sinh dục tác dụng trên tuyến yên làm gia tăng mạnh sự chế tiết các nội tiết tố tăng trưởng cũng như tăng chế tiết IGF-1 tại gan. Trong điều kiện này chiều cao có thể tăng trong mỗi năm đến 10 cm. Sau đó nồng độ các nội tiết tố vẫn tiếp tục tăng và có tác dụng trực tiếp lên các vùng phát triển của sụn. Cuối cùng là sự cốt hoá và kết thúc quá trình tăng trưởng chiều cao."], "bullets": []}, {"heading": "4.2.4. Sự hành kinh", "paragraphs": ["Lần hành kinh đầu tiên diễn ra vào khoảng một năm sau sự tăng trưởng dậy thì. Trên nguyên tắc cần xem lần hành kinh đầu tiên này là hậu quả của sự sụt giảm estrogen đơn thuần do không có hiện tượng phóng noãn. Về sau sẽ xuất hiện các chu kỳ kinh có phóng noãn với sự hình thành và hoạt động của hoàng thể."], "bullets": []}, {"heading": "4.2.5. Sự thay đổi cơ quan sinh dục", "paragraphs": ["Dưới ảnh hưởng của các nội tiết tố sinh dục sẽ xuất hiện các biến đổi tương ứng của bộ phận sinh dục trong và ngoài. Độ dài âm đạo tăng dần đến khoảng 11 cm. Biểu mô âm đạo tăng sinh và dày lên. Do gia tăng khuẩn chí Lactobacillus lưu trú, pH âm đạo sẽ giảm xuống dưới 4,0. Môi lớn và môi nhỏ dày lên, vùng gò mu tập trung nhiều mỡ, âm vật cũng to ra."], "bullets": []}, {"heading": "4.3. Thời kỳ hoạt động sinh dục", "paragraphs": ["Tiếp theo tuổi dậy thì là thời kỳ hoạt động sinh dục, kéo dài đến khi mãn kinh. Trong thời kỳ này, người phụ nữ thường hành kinh đều đặn, tỉ lệ vòng kinh có phóng noãn tăng lên do hoạt động nội tiết của trục dưới đồi - tuyến yên - buồng trứng đã được hoàn chỉnh. Người phụ nữ có thể thụ thai được.", "Trong thời kỳ này, các tính chất sinh dục phụ cũng như toàn cơ thể của người phụ nữ vẫn tiếp tục phát triển đến mức tối đa. Thời kỳ hoạt động sinh dục kéo dài 30 - 35 năm."], "bullets": []}, {"heading": "4.4. Thời kỳ mãn kinh", "paragraphs": ["Mãn kinh là tình trạng không còn hành kinh của người phụ nữ. Nếu một thiếu nữ chưa hành kinh là do vùng dưới đổi hoạt động chưa chín muồi, thì một người phụ nữ không hành kinh ở tuổi mãn kinh là do buồng trứng đã suy kiệt, không còn nhạy cảm trước sự kích thích của các hormon hướng sinh dục, nên không còn chế tiết đủ hormon sinh dục. Kể từ khi mãn kinh, người phụ nữ không còn khả năng có thai nữa."], "bullets": []}], "raw_text": "SINH LÝ PHỤ KHOA\nBs.CKII Nguyễn Thị Tuyết\n\nMục tiêu học tập\n1. Mô tả được các chức năng của hệ thống vùng dưới đồi - tuyến yên - buồng trứng\n2. Xác định được tác dụng của các hormon sinh dục nữ\n3. Trình bày được các tính chất của kinh nguyệt\n4. Liệt kê được các thời kỳ hoạt động sinh dục của người phụ nữ\n\nSinh lý phụ khoa thể hiện tất cả những vấn đề có liên quan đến những thay đổi về tính chất sinh dục và hoạt động sinh dục của người phụ nữ. Nếu kinh nguyệt là một biểu hiện bên ngoài rõ ràng của một phần hoạt động sinh sản ở người phụ nữ, thì bên trong cơ thể có một sự phối hợp chặt chẽ và vô cùng phức tạp của hệ thống nội tiết sinh sản, vùng dưới đồi, tuyến yên, buồng trứng. Các hormon buồng trứng một mặt tác động trực tiếp lên phần của cơ quan sinh dục như tử cung, cổ tử cung, vòi trứng, âm hộ, âm đạo, tuyến vú, mặt khác lại tác động trở lại vùng dưới đồi tuyến yên tạo thành cơ chế hồi tác. Khi có một rối loạn bất kỳ của quá trình hoạt động này sẽ dẫn đến các bệnh lý phụ khoa cũng như ảnh hưởng đến chức năng sinh sản.\n\n1. HỆ THỐNG VÙNG DƯỚI ĐỒI - TUYẾN YÊN - BUỒNG TRỨNG\n1.1. Vùng dưới đồi\nTrung khu sinh dục của vùng dưới đồi nằm trong nền của trung não, phía trên giao thoa thị giác, gồm một nhóm các nhân thần kinh giàu mạch máu, có khả năng chế tiết hormon. Nhân trên thị chế tiết vasopressin, nhân bên thất chế tiết oxytocin, các chất này được các sợi thần kinh dẫn xuống thùy sau tuyến yên.\nCủ xám, nhân bụng giữa, nhân lưng giữa và nhân cung tiết ra các hormon giải phóng. Trong số đó có các hormon giải phóng gonadotropin, gọi tắt là GnRH (Gonadotropin Releasing Hormon).\n1.2. Tuyến yên\nTuyến yên nằm trong hố yên, nặng khoảng 0,5g, có hai thùy. Thùy trước là một tuyến nội tiết nên còn được gọi là tuyến yên tuyến (adenohypophysis). Thùy sau là một mô giống thần kinh, còn được gọi là tuyến yên thần kinh (neurohypophysis), không phải là tuyến nội tiết. Về phương diện hoạt động sinh dục, thùy trước tuyến yên chế tiết các hormon hướng sinh dục kích thích các tuyến sinh dục, đồng thời chế tiết prolactin kích thích tuyến vú. Hai hormon hướng sinh dục là FSH và LH đều là glycoprotein.\n- FSH (Follicle Stimulating Hormon) kích thích nang noãn của buồng trứng phát triển và trưởng thành.\n- LH (Luteinizing Hormon) kích thích nang noãn trưởng thành phóng noãn, kích thích hình thành hoàng thể và kích thích hoàng thể chế tiết.\n- Prolactin là một hormon kích thích tuyến vú tiết sữa.\nFSH và LH có các đường cong chế tiết trong chu kỳ kinh gần như song song với nhau và có đỉnh cao vào trước phóng noãn một ngày. Tuy nhiên, đỉnh FSH không cao đột ngột như đỉnh LH, cũng không tăng nhiều như đỉnh LH. Vào trước ngày phóng noãn, đỉnh LH có khi đạt trị số gấp tới 5-10 lần. Vào nửa sau của vòng kinh, trị số của FSH hơi thấp hơn so với nửa đầu của vòng kinh. Nồng độ LH vài ngày trước phóng noãn có thể tăng nhanh đột ngột, đạt đỉnh cao trước phóng noãn một ngày, sau đó lại giảm nhanh, xuống mức như trước khi phóng noãn.\n1.3. Buồng trứng\nBuồng trứng là tuyến sinh dục nữ, có 2 buồng trứng hình bầu dục nằm hai bên, kích thước 4x2x1 cm; có hai chức năng: Chức năng ngoại tiết tạo noãn và chức năng nội tiết tạo các hormon sinh dục.\nBuồng trứng có rất nhiều nang noãn. Số lượng các nang noãn này giảm rất nhanh theo thời gian. Khi còn là thai nhi ở tuổi thai 20 tuần, hai bên buồng trứng có 1,5 - 2 triệu nang noãn nguyên thủy. Nhưng khi em bé gái ra đời, số lượng các nang noãn này đã giảm xuống rất nhiều, chỉ còn chừng 200.000 - 300.000, nghĩa là giảm đi khoảng 10 lần trong thời gian 20 tuần. Vào tuổi dậy thì, số lượng nang noãn chỉ còn 20.000 - 30.000. Sự giảm số lượng các nang noãn là do các nang noãn bị thoái triển teo đi, các nang còn lại cũng trên đà thoái triển nhưng chậm hơn. Nếu những noãn nằm trong các nang này được thụ tinh muộn thì phôi được hình thành có thể có khả năng phát triển kém. Buồng trứng không có khả năng sản sinh những nang noãn mới.\n\nHình 1. Trục dưới đồi - tuyến yên - sinh dục\n1.3.1. Hoạt động sinh sản\nNang noãn nguyên thủy có đường kính 0,05mm. Dưới tác dụng của FSH, nang noãn lớn lên, chín. Nang noãn chín còn gọi là nang De Graaf, có đường kính 1,5-2cm. Noãn chứa trong nang này cũng chín và chịu tác dụng phân bào. Noãn chín có đường kính 0,1mm (100 micromet).\nTrong mỗi chu kỳ kinh thường chỉ có một nang noãn phát triển để trở thành nang De Graaf. Đó là nang nhạy nhất trong vòng kinh ấy. Nang này phát triển từ một nang đã đang phát triển dở dang từ cuối vòng kinh trước.\nNang noãn chín là một nang có hốc với các thành phần:\n- Vỏ nang ngoài làm bởi các sợi liên kết, thực sự chỉ có tác dụng bọc lấy nang.\n- Vỏ nang trong có nhiều mạch máu, là một tuyến nội tiết, có khả năng chế tiết estrogen.\n- Màng tế bào hạt có tới 10-15 lớp tế bào hạt.\n- Noãn trưởng thành đã giảm phân, có 22 nhiễm sắc thể thường và một nhiễm sắc thể giới X.\n- Hốc nang chứa dịch nang trong đó có estrone.\nDưới tác dụng của LH, nang noãn càng chín nhanh, lồi ra phần ngoại vi của buồng trứng rồi vỡ, phóng noãn ra ngoài. Đó là hiện tượng phóng noãn. Cũng dưới tác dụng của LH, phần còn lại của nang noãn tại buồng trứng dần dần biến thành hoàng thể. Vào cuối vòng kinh, khi LH trong máu giảm xuống, hoàng thể teo đi, để lại sẹo trắng, gọi là vật trắng hay bạch thể.\n\n1.3.2. Hoạt động nội tiết\nCác tế bào hạt và những tế bào của vỏ nang trong chế tiết ra 3 hormon chính: estrogen, progesteron và androgen. Các hormon này là hormon sinh dục, có nhân steron nên còn được gọi là steroid sinh dục.\n- Vỏ nang trong chế tiết estrogen.\n- Các tế bào hạt của hoàng thể chế tiết progesteron.\n- Các tế bào của rốn buồng trứng chế tiết androgen.\nNang noãn có thể coi là một đơn vị hoạt động của buồng trứng cả về phương diện sinh sản, cả về phương diện nội tiết. Thật vậy, nang noãn chín có khả năng phóng ra một noãn chín để thụ tinh được. Các hormon của nang noãn và của hoàng thể đủ để làm thay đổi niêm mạc tử cung giúp cho trứng làm tổ. Và nếu như người phụ nữ không thụ thai thì cũng đủ gây được kinh nguyệt.\n\n2. TÁC DỤNG CỦA CÁC HORMON SINH DỤC NỮ\n2.1. Estrogen\n- Đối với cơ tử cung\n+ Làm phát triển cơ tử cung do làm tăng độ lớn, độ dài các sợi cơ.\n+ Làm tăng nhạy cảm của cơ tử cung đối với oxytoxin và các nhân tố gây co tử cung.\nĐối với niêm mạc tử cung\n+ Kích thích phân bào, gây quá sản niêm mạc tử cung, ung thư niêm mạc tử cung.\n+ Khi tụt đột ngột làm bong niêm mạc tử cung, gây chảy máu kinh nguyệt.\nĐối với cổ tử cung\n+ Làm tăng tiết, làm trong và loãng chất nhầy cổ tử cung, làm mở cổ tử cung khiến tinh trùng dễ xâm nhập lên đường sinh dục trên của người phụ nữ.\n- Đối với âm đạo\n+ Làm phát triển và làm dày biểu mô âm đạo\n+ Làm biểu mô âm đạo chứa Glycogen. Trực khuẩn Doderlein có trong âm đạo biến glycogen này thành acid lactic, khiến pH âm đạo toan tính, ngăn cản phát triển của các vi khuẩn gây bệnh.\n- Đối với âm hộ\n+ Làm phát triển các môi của âm hộ\n+ Làm phát triển và chế tiết các tuyến Skene và Bartholin của âm hộ\n- Đối với vú\n+ Làm phát triển các tuyến sữa và mô đệm của vú, khiến vú nở nang\n- Các tác dụng khác\n+ Giữ nước, giữ Kali, gây phù.\n+ Kích thích tình dục.\n+ Làm căng các dây thanh âm khiến tiếng nói có âm sắc cao\n+ Giúp giữ Canxi ở xương, đỡ loãng xương.\n2.2. Progesteron\n- Đối với cơ tử cung\n+ Làm mềm cơ tử cung, giảm nhạy với oxytoxin và các nhân tố gây co\n+ Hiệp đồng với estrogen, làm tăng phát triển cơ tử cung\n- Đối với niêm mạc tử cung\n+ Làm teo niêm mạc tử cung\n+ Hiệp đồng với estrogen, làm niêm mạc tử cung chế tiết. Hiệp đồng tốt nhất khi tỷ lệ estrogen/progesteron là 1/10.\n- Đối với cổ tử cung\n+ Ức chế chế tiết chất nhầy\n- Đối với âm đạo\n+ Làm phát triển biểu mô âm đạo\n- Đối với vú\n+ Làm phát triển ống dẫn sữa\n+ Hiệp đồng với estrogen làm phát triển toàn diện vú\n- Các tác dụng khác\n+ Lợi niệu\n+ Tăng thân nhiệt 0.3-0.5oC\n\n3. SINH LÝ CHU KỲ KINH NGUYỆT\nTrong chu kỳ kinh nguyệt bình thường, các hormon được tiết ra có tính chu kỳ, trật tự. Song song với sự tiết hormon này, niêm mạc tử cung tăng sinh nhằm chuẩn bị cho sự làm tổ của phôi.\n3.1. Chu kỳ kinh nguyệt\nỞ người, chu kỳ kinh nguyệt có thể được phân chia thành hai phần: chu kỳ buồng trứng và chu kỳ tử cung. Chu kỳ buồng trứng được phân chia thành giai đoạn nang noãn và giai đoạn hoàng thể, chu kỳ tử cung được phân chia thành giai đoạn tăng sinh và giai đoạn chế tiết tương ứng và hành kinh.\n3.1.1. Chu kỳ buồng trứng\n- Giai đoạn nang noãn: Cơ chế điều hòa ngược của hormon thúc đẩy sự phát triển có tính trật tự của một nang noãn vượt trội. Nang này trưởng thành vào giữa chu kỳ và chuẩn bị cho sự phóng noãn. Thời gian trung bình của giai đoạn nang noãn là 10-14 ngày. Sự thay đổi của thời gian giai đoạn nang noãn chịu trách nhiệm cho hầu hết của những thay đổi trong toàn bộ chu kỳ.\n- Giai đoạn hoàng thể: Tính từ lúc phóng noãn đến lúc bắt đầu hành kinh, kéo dài trung bình 14 ngày.\n3.1.2. Chu kỳ tử cung\n- Giai đoạn tăng sinh\nSau khi hành kinh, màng rụng đáy gồm các tuyến nguyên thuỷ và mô đệm ít, đặc nằm sát cơ tử cung. Giai đoạn tăng sinh đặc trưng bởi sự nguyên phân liên tục của màng rụng chức năng tương ứng với sự tăng nồng độ estrogen trong tuần hoàn. Lúc bắt đầu giai đoạn tăng sinh, niêm mạc tử cung tương đối mỏng. Sự thay đổi rõ nét trong thời kỳ này là sự phát triển của các tuyến nội mạc ban đầu thẳng, hẹp và ngắn thành các cấu trúc dài hơn và cuộn xoắn.\n- Giai đoạn chế tiết\nTrong một chu kỳ 28 ngày điển hình, sự phóng noãn xảy ra vào ngày thứ 14. Trong vòng 48-72 giờ sau phóng noãn, sự khởi phát chế tiết progesteron tạo nên sự thay đổi biểu hiện mô học của niêm mạc tử cung sang giai đoạn chế tiết. Giai đoạn chế tiết đặc trưng bởi ảnh hưởng của progesteron cùng với estrogen tác động lên tế bào.\nNgày 6-7 sau phóng noãn, hoạt động chế tiết các tuyến đạt cực đại và nội mạc đã được chuẩn bị tối ưu cho sự làm tổ của phôi. Cùng với sự tăng phù nề mô đệm tối đa vào cuối pha chế tiết, các động mạch xoắn có thể nhìn thấy rõ ràng rồi dài dần và cuộn lại. Khoảng ngày 2 trước khi hành kinh, có sự gia tăng đáng kể số lượng lymphocyte đa nhân di chuyển vào từ hệ thống mạch máu. Sự xâm nhập bạch cầu báo trước sự suy sụp của mô đệm niêm mạc và khởi phát hành kinh.\n- Hành kinh\nKhi không có sự làm tổ của phôi, sự chế tiết của các tuyến ngừng lại và xảy ra sự phá vỡ không đều lớp màng rụng chức năng. Kết quả làm bong lớp niêm mạc này, gây nên hành kinh. Sự thoái hoá của hoàng thể và tụt giảm đột ngột các sản phẩm chế tiết estrogen và progesteron là nguyên nhân của bong niêm mạc.\nMột chu kỳ kinh nguyệt bình thường kéo dài 21-35 ngày, thời gian hành kinh 2-6 ngày và lượng máu mất trung bình 20-60ml.\n\nHình 2. Thay đổi hormon, chu kỳ buồng trứng\nvà niêm mạc tử cung trong chu kỳ kinh nguyệt bình thường\n3.2. Những thay đổi của hormon\n3.2.1. Lúc bắt đầu mỗi chu kỳ kinh nguyệt, lượng hormon sinh dục đang giảm thấp từ cuối giai đoạn hoàng thể của chu kỳ trước.\n3.2.2. Với sự thoái hóa của hoàng thể, FSH bắt đầu tăng và một đoàn hệ nang noãn đang phát triển được tuyển chọn. Mỗi nang này tiết ra estrogen khi chúng phát triển trong giai đoạn nang noãn. Chính estrogen kích thích niêm mạc tử cung tăng trưởng.\n3.2.3. Lượng estrogen đang tăng tạo ra cơ chế điều hòa ngược âm tính lên sự tiết FSH của tuyến yên. FSH bắt đầu giảm vào giữa giai đoạn nang noãn. Trái lại, LH được kích thích bởi lượng estrogen được tiết ra trong suốt giai đoạn nang noãn.\n3.2.4. Cuối giai đoạn nang noãn, trước khi rụng trứng, các thụ thể của LH hiện diện ở lớp tế bào hạt điều chỉnh sự tiết progesteron.\n3.2.5. Đỉnh LH xuất hiện sau một mức độ kích thích vừa đủ của estrogen. Đây là nguyên nhân cơ bản của sự phóng noãn. Sự phóng noãn là mốc cho sự chuyển tiếp từ giai đoạn nang noãn sang giai đoạn hoàng thể.\n3.2.6. Lượng estrogen bắt đầu giảm ngay trước phóng noãn, tiếp tục giảm trong giai đoạn hoàng thể sớm. Cho đến giữa giai đoạn hoàng thể, estrogen bắt đầu tăng trở lại do hoàng thể tiết ra.\nLượng progesteron tăng nhanh chóng sau phóng noãn và có thể được xem như là một dấu hiệu của sự phóng noãn.\nCả estrogen và progesteron vẫn còn tăng trong thời gian tồn tại của hoàng thể. Sau đó, hàm lượng của chúng giảm khi hoàng thể thoái hóa, vì thế tạo ra một giai đoạn cho chu kỳ kế tiếp.\n\n4. CÁC THỜI KỲ HOẠT ĐỘNG SINH DỤC Ở PHỤ NỮ\nCuộc đời hoạt động sinh dục của người phụ nữ được chia làm bốn thời kỳ.\n4.1. Thời kỳ trẻ em (trước dậy thì)\nTrong tuổi thiếu niên, buồng trứng ở trong giai đoạn im lặng về mặt nội tiết, mặc dù về mặt hình thái người ta cũng phát hiện được sự trưởng thành và sự thoái hoá của nang noãn. Tuy vậy các biến đổi hình thái này không đi kèm với hoạt động nội tiết của buồng trứng. Trong thời kỳ này cũng không có sự phát triển của nang noãn đến giai đoạn nang trội hoặc hình thành hoàng thể. Sự im lặng của buồng trứng về mặt nội tiết là do sự “chưa chín muồi của vùng dưới đồi“.\n4.2. Giai đoạn dậy thì\nChức năng nội tiết của buồng trứng bắt đầu hoạt động khi các tế bào thần kinh sản xuất GnRH của vùng dưới đồi đã có thể bắt đầu giải phóng GnRH một cách đồng bộ và theo xung nhịp vào hệ thống động mạch cửa tuyến yên\n4.2.1. Sự phát triển vú\nEstrogen bắt đầu được chế tiết từ buồng trứng có tác dụng lâm sàng thấy được đầu tiên thông qua sự phát triển vú. Núm vú nổi rõ, tiếp theo là sự phát triển mô tuyến vú, tăng sinh biểu mô ống tuyến và thuỳ tuyến dưới tác dụng của estrogen và prolactin.\n4.2.2. Sự phát triển lông mu\nTiếp sau vú là sự phát triển lông mu và lông nách, chủ yếu là dưới tác dụng của androgen. Các androgen này một phần có nguồn gốc buồng trứng, một phần từ tuyến thượng thận và một phần thông qua chuyển hoá ở ngoại vi.\n4.2.3. Sự tăng trưởng cơ thể\nKhoảng một năm sau, sau dấu hiệu dậy thì đầu tiên sẽ xuất hiện sự tăng trưởng cơ thể mạnh mẽ. Các steroid sinh dục tác dụng trên tuyến yên làm gia tăng mạnh sự chế tiết các nội tiết tố tăng trưởng cũng như tăng chế tiết IGF-1 tại gan. Trong điều kiện này chiều cao có thể tăng trong mỗi năm đến 10 cm. Sau đó nồng độ các nội tiết tố vẫn tiếp tục tăng và có tác dụng trực tiếp lên các vùng phát triển của sụn. Cuối cùng là sự cốt hoá và kết thúc quá trình tăng trưởng chiều cao.\n4.2.4. Sự hành kinh\nLần hành kinh đầu tiên diễn ra vào khoảng một năm sau sự tăng trưởng dậy thì. Trên nguyên tắc cần xem lần hành kinh đầu tiên này là hậu quả của sự sụt giảm estrogen đơn thuần do không có hiện tượng phóng noãn. Về sau sẽ xuất hiện các chu kỳ kinh có phóng noãn với sự hình thành và hoạt động của hoàng thể.\n4.2.5. Sự thay đổi cơ quan sinh dục\nDưới ảnh hưởng của các nội tiết tố sinh dục sẽ xuất hiện các biến đổi tương ứng của bộ phận sinh dục trong và ngoài. Độ dài âm đạo tăng dần đến khoảng 11 cm. Biểu mô âm đạo tăng sinh và dày lên. Do gia tăng khuẩn chí Lactobacillus lưu trú, pH âm đạo sẽ giảm xuống dưới 4,0. Môi lớn và môi nhỏ dày lên, vùng gò mu tập trung nhiều mỡ, âm vật cũng to ra.\n4.3. Thời kỳ hoạt động sinh dục\nTiếp theo tuổi dậy thì là thời kỳ hoạt động sinh dục, kéo dài đến khi mãn kinh. Trong thời kỳ này, người phụ nữ thường hành kinh đều đặn, tỉ lệ vòng kinh có phóng noãn tăng lên do hoạt động nội tiết của trục dưới đồi - tuyến yên - buồng trứng đã được hoàn chỉnh. Người phụ nữ có thể thụ thai được.\nTrong thời kỳ này, các tính chất sinh dục phụ cũng như toàn cơ thể của người phụ nữ vẫn tiếp tục phát triển đến mức tối đa. Thời kỳ hoạt động sinh dục kéo dài 30 - 35 năm.\n4.4. Thời kỳ mãn kinh\nMãn kinh là tình trạng không còn hành kinh của người phụ nữ. Nếu một thiếu nữ chưa hành kinh là do vùng dưới đổi hoạt động chưa chín muồi, thì một người phụ nữ không hành kinh ở tuổi mãn kinh là do buồng trứng đã suy kiệt, không còn nhạy cảm trước sự kích thích của các hormon hướng sinh dục, nên không còn chế tiết đủ hormon sinh dục. Kể từ khi mãn kinh, người phụ nữ không còn khả năng có thai nữa.\nCâu hỏi:\n1. Nêu cấu trúc, chức năng của hệ thống trục dưới đồi- tuyên yên- buồng trứng?\n2. Nêu tác dụng của các hormon sinh dục nữ?\n3. Nêu sinh lý của chu kỳ kinh nguyệt?\n4. Nếu các thời kỳ hoạt động sinh dục nữ?", "priority": "Trung bình"}, {"id": "SK-03", "chapter": "Chương 1. Sản thường", "folder": "01_San_thuong", "title": "Sự thụ tinh, làm tổ và phát triển của trứng", "author": "Ths. Bùi Thị Thanh Tuyền", "word_count": 3396, "line_count": 126, "key_numbers": ["1 tuần", "2 giờ", "2,5 mm", "3 ngày", "36 giờ", "4 ngày", "74 ngày"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["SỰ THỤ TINH, LÀM TỔ", "VÀ PHÁT TRIỂN CỦA TRỨNG", "Ths. Bùi Thị Thanh Tuyền"], "bullets": []}, {"heading": "1. ĐẠI CƯƠNG", "paragraphs": [], "bullets": ["- Sự thụ tinh là sự kết hợp giữa một tế bào đực (tinh trùng) và một tế bào cái (noãn) để hình thành một tế bào mới là trứng được thụ tinh.", "- Sự thụ thai là sự thụ tinh kèm theo sau đó là sự làm tổ của trứng.", "- Sau khi làm tổ trứng phát triển thành thai và các phần phụ của thai (bánh rau, màng rau, dây rau và nước ối)."]}, {"heading": "2.1. Sự phát triển của giao tử", "paragraphs": ["Giao tử là tế bào sinh dục, được biệt hoá cao, giữ một nhiệm vụ duy nhất là sinh sản và không giống với bất kỳ một tế bào nào khác. Tế bào sinh dục có kích thước khá lớn (25 - 30 (m), bào tương nhạt, giàu lipid, có nhân và một thể Idiosome (gồm 2 trung thể và bộ máy Golgy). Giao tử đực là tinh trùng mang bộ nhiễm sắc thể (NST) đơn bội. Giao tử cái là noãn cũng mang bộ NST đơn bội."], "bullets": []}, {"heading": "2.1.1. Sự sinh tinh", "paragraphs": ["Tinh trùng được sản sinh trong ống sinh tinh. Ra khỏi ống sinh tinh, tinh trùng có hình dạng cố định nhưng chưa di động, chưa thụ tinh được, chúng chỉ có khả năng trên sau khi đi qua ống mào tinh. Tinh trùng được dự trử tại mào tinh, ống tinh và phần lớn ở túi tinh. Sự sinh tinh trải qua nhiều giai đoạn để một tinh nguyên bào biến thành tinh trùng có khả năng thụ tinh. Qua trung gian của 5 lần phân chia, một tế bào cho ra 32 tinh trùng, quá trình kéo dài 74 ngày. Sự sinh tinh trùng là liên tục bắt đầu từ tuổi dậy thì (khoảng 200 triệu mỗi ngày).", "Cấu trúc tinh trùng:", "Tinh trùng là một tế bào đã được biệt hoá cao độ gồm có đầu thân và đuôi. Đầu là một khối nhân (chất nhiễm sắc) có hình tròn. Đầu được bảo vệ 3/4 phía trước bởi một cấu trúc đặc biệt gọi là thể cực đầu. Thể cực đầu chứa nhiều loại men có ảnh hưởng lên các loại protein của vỏ noãn như hyaluronidase, fertilysine. Đuôi nối tiếp với đầu qua trung gian đoạn cổ. Đuôi gồm có đoạn trung gian, đoạn chính và đoạn cuối. Trục của đuôi có cấu tạo đặc biệt gồm nhiều cặp ống ngoại vi và một cặp ống trung tâm, đó là bộ máy tạo ra sự cử động của đuôi. Tinh trùng được đẩy tới bởi các đợt sóng do đuôi tạo ra.", "Các đặc điểm của tinh trùng:", "ư Chiều dài 65 àm.", "Hình 1. Sự sinh tinh trùng"], "bullets": ["- Số lượng 60 - 120 triệu/ml tinh dịch.", "- Tỷ lệ hoạt động lúc mới phóng tinh > 80%.", "- Tốc độ di chuyển 1,5 - 2,5 mm/phút.", "- Thời gian sống trung bình trong đường sinh dục nữ tuỳ thuộc độ pH: ở âm đạo pH toan sống được < 2 giờ; ở ống cổ tử cung pH > 7,5 sống được 2 - 3 ngày; trong vòi tử cung tinh trùng sống thêm được 2 - 3 ngày."]}, {"heading": "2.1.2. Sự sinh noãn", "paragraphs": ["Noãn hình thành từ các nang trứng. Phần lớn các noãn trong thời kỳ bào thai và sau khi sinh đã bị thoái hoá còn lại từ 400 - 450  đạt tới mức độ chín sau tuổi dậy thì. Bề mặt noãn có nhiều vi mao xuyên qua màng trong suốt, bào tương tích luỹ nhiều Mucopolysacharide, Phosphatase kiềm và ARN. Phần lớn ARN tập trung thành từng vùng đặc biệt. Mỗi tháng 2 buồng trứng thay phiên nhau rụng một noãn từ tuổi dậy thì đến tuổi mãn kinh. Sự rụng trứng thường xảy ra khoảng giữa ngày thứ 12 và 14 của chu kỳ kinh và chia chu kỳ thành 2 giai đoạn: giai đoạn nang trứng (trước rụng trứng) và giai đoạn hoàng thể (sau rụng trứng). Nếu quá trình thụ tinh không xảy ra, sự thoái triển của hoàng thể dẫn đến kinh nguyệt. Giữa thời điểm cuối kỳ kinh trước và khởi đầu giai đoạn nang trứng, khoảng vài chục nang trứng đi vào giai đoạn tăng trưởng bằng cách tăng thể tích dịch nang và hốc nang lớn dần. Vào ngày thứ 6 chỉ có một nang duy nhất đạt tới tình trạng chín cần thiết: đó là nang trội, số nang còn lại bị thoái triển. Khoảng 36 giờ trước khi rụng trứng có một sự gia tăng tối đa hormone LH (Luteinizing Hormone) thúc đẩy trứng chín nhanh. Noãn rụng kèm theo màng trong suốt, tế bào gò noãn, tế bào vòng tia, tế bào hạt, tất cả đi vào loa vòi tử cung.", "Hình 2. Sự sinh noãn từ noãn nguyên bào cho đến lúc thụ tinh"], "bullets": []}, {"heading": "2.1.3. Những bất thường trong sự sinh giao tử", "paragraphs": [], "bullets": ["- Sự sinh tinh là một quá trình liên tục, mỗi ngày có hàng trăm triệu tinh trùng được tạo ra, 50% mang NST X và 50% mang NST Y.", "- Sự sinh noãn là một quá trình không liên tục, từng chu kỳ sinh ra những tế bào không bằng nhau (mặc dù trong cùng một lần phân bào), chỉ có một noãn hữu ích còn 2 cực cầu vô dụng.", "- Các quá trình phức tạp trên có thể là nguyên nhân gây bất thường về hình thái hoặc bất thường về NST:", "+ Bất thường về hình thái: rất khó quan sát những bất thường về hình thái ở noãn, nhưng đối với tinh trùng thì có thể thấy rõ hơn (ví dụ: tinh trùng hai đầu, …).", "+ Bất thường về NST: bất thường trong sự phân chia NST thường và NST giới tính."]}, {"heading": "2.2. Sự thụ tinh", "paragraphs": ["Sự hợp nhất cấu trúc tinh trùng và noãn xảy ra ở 1/3 ngoài của ống dẫn trứng. Thực chất đây là sự hoà lẫn giữa 2 bộ NST của noãn và tinh trùng.", "Có khoảng 200 triệu tinh trùng trong mỗi lần phóng tinh vào âm đạo. Cổ tử cung trước đó được bịt kín bởi một nút chất nhầy đặc quánh, dưới ảnh hưởng của estradiol được sinh ra từ nang trứng trong quá trình phát triển sẽ trở nên loãng hơn vào giai đoạn trước rụng trứng cho phép những tinh trùng di động nhanh nhất và mạnh nhất đi qua, số còn lại nằm lại  vùng cổ tử cung và túi cùng âm đạo. Nói chung, có khoảng vài triệu tinh trùng đến được gần noãn trong thời gian thích hợp vì tinh trùng có thể sống tới 1 tuần sau khi phóng còn noãn chỉ sống được hai ngày sau khi rụng. Khi tinh trùng vượt qua màng trong suốt của noãn, một sự hoà hợp vỏ bọc noãn và vỏ bọc thân tinh trùng xảy ra, nhân tinh trùng hoàn toàn được đưa vào trong bào tương noãn, đuôi rời khỏi đầu bị giữ lại bên ngoài màng trong suốt, một phản ứng vỏ noãn sẽ ngăn chặn không cho một tinh trùng nào khác được lọt vào chất noãn. Xuất hiện trong noãn một tiền nhân đực và một tiền nhân cái. Hai tiền nhân này tiếp tục phát triển riêng rẽ, sau đó xích lại gần nhau và hoà lẫn thành một sau khi cởi bỏ hoàn toàn màng bọc nhân. Ta có một hợp tử và sự phân cắt thành phôi bào bắt đầu.", "Kết quả của sự thụ tinh:", "Hình 3. Sự thụ tinh, hình thành tiền nhân đực, cái và phân bào lần đầu tiên."], "bullets": ["- Tái lập bộ NST của loài (2n).", "- Xác định giới tính của phôi: nếu tinh trùng mang NST Y thì phôi nang mang tính đực, nếu tinh trùng mang NST X thì phôi nang mang tính cái.", "- Chuẩn bị để hợp tử phân cắt."]}, {"heading": "3.1. Sự di chuyển của trứng", "paragraphs": ["Sau khi thụ tinh thường xảy ra ở 1/3 ngoài vòi tử cung, trứng tiếp tục di chuyển trong vòi tử cung để đến làm tổ ở buồng tử cung. Trứng di chuyển trong phần còn lại của vòi tử cung mất 3 - 4 ngày, sau đó còn sống tự do trong buồng tử cung thêm 2 - 3 ngày nữa mới bắt đầu quá trình làm tổ. Có 3 cơ chế tham gia vào sự di chuyển của trứng:", "Trên đường di chuyển trứng phân bào rất nhanh, từ một tế bào ban đầu phân chia thành 2 rồi 4 tế bào mầm bằng nhau, sau đó phân chia thành 8 tế bào: 4 tế bào mầm to và 4 tế bào mầm nhỏ. Các tế bào mầm nhỏ phát triển nhanh hơn các tế bào mầm to và bao quanh các tế bào mầm to, tạo nên phôi dâu, có hình dạng bên ngoài giống hình quả dâu. Các tế bào mầm nhỏ tạo thành lá nuôi có tác dụng nuôi dưỡng bào thai; các tế bào mầm to nằm ở giữa sẽ trở thành các lá thai, sẽ phát triển thành thai nhi. Ở giai đoạn phôi dâu nhóm tế bào trung tâm lớn hơn sẽ cho ra cúc phôi, nhóm tế bào ngoại vi nhỏ hơn ở giai đoạn 32 tế bào sẽ tiết dịch, tạo thành xoang đẩy cúc phôi về một góc."], "bullets": ["- Nhu động của vòi tử cung.", "- Hoạt động của nhung mao niêm mạc vòi tử cung.", "- Luồng dịch chảy từ phía loa vòi tử cung vào buồng tử cung."]}, {"heading": "3.2. Sự làm tổ", "paragraphs": ["Ở giai đoạn phôi dâu khi đã lọt vào khoang tử cung (vào khoảng ngày thứ 5 - 6 sau thụ tinh) hình thành một hốc nhỏ trong lòng phôi dâu nơi cúc phôi sẽ phát triển, những tế bào nhỏ giãn ra xung quanh hốc, tạo thành phôi nang. Phôi nang sẽ làm tổ vào nội mạc tử cung (khoảng ngày thứ 6 sau thụ tinh). Lúc này màng trong suốt đã biến mất.", "Sự phát triển bình thường đòi hỏi sự hiện diện của 2 bộ NST của bố và mẹ mà vai trò không giống nhau. Bộ NST của bố sẽ cần thiết cho sự phát triển các phần phụ và bộ NST mẹ cần cho sự phát triển của cúc phôi.", "Phôi nang hình thành vào ngày thứ 5, phần lớn tế bào ngoại vi tạo thành lá nuôi. Cúc phôi chứa 2 loại tế bào, một loại có số lượng ít sẽ là nguồn gốc bản phôi, phần khác sẽ cho ra những phần phụ ngoài phôi cần thiết để duy trì phôi. Phôi nang bắt đầu làm tổ vào ngày thứ 6 hoặc thứ 7 và làm tổ ở mặt đáy của cúc phôi nhờ hoạt động phân giải của lá nuôi hợp bào bằng cách bào mòn và xâm nhập dần dần vào nội mạc tử cung. Vào giai đoạn này, cúc phôi bắt đầu tách rời khỏi lá nuôi.", "Vị trí làm tổ thường ở mặt sau đáy tử cung, nhưng cũng có thể \"lạc chỗ\". Quá trình diễn biến như sau:", "Trước sự làm tổ, nội mạc tử cung dưới ảnh hưởng của progesterone và các yếu tố kích thích nội mạc mạch máu (Vascular Endothelial Growth Factor - VEGF) phát triển để đủ điều kiện để đón nhận hợp tử. Trong giai đoạn phát triển nội mạc giàu mạch máu, lớp đệm xung huyết, phù nề, tuyến phát triển dài và cong queo, tích luỹ nhiều Glycogen và chất nhầy trong lòng tuyến và trong tế bào.", "Hình 4. Sự phát triển của phôi trong quá trình di chuyển"], "bullets": ["- Ngày thứ 6 - 8: hiện tượng dính và bám rễ của phôi: phôi nang dính vào niêm mạc tử cung, các chân giả xuất phát từ các tế bào nuôi bám vào biểu mô, một số liên bào bị tiêu huỷ và phôi nang chui qua lớp biểu mô", "- Ngày thứ 9 - 10: phôi qua lớp biểu mô trụ, chưa nằm sâu trong lớp đệm và bề mặt chưa được biểu mô phủ kín.", "- Ngày thứ 11 - 12: phôi nằm hoàn toàn trong lớp đệm nhưng lỗ chui qua vẫn chưa được phủ kín.", "- Ngày thứ 13 - 14: phôi nằm hoàn toàn trong lớp đệm, được biểu mô phủ kín. Trung sản mạc được biệt hoá thành hai loại tế bào và hình thành những gai rau đầu tiên."]}, {"heading": "3.3. Những bất thường trong sự làm tổ", "paragraphs": ["Thông thường phôi làm tổ ở mặt trước và mặt sau thân tử cung. Các vị trí bất thường có thể gặp: vòi tử cung, buồng trứng, cổ tử cung, trong ổ bụng, đó là thai \"lạc chỗ\" hay còn gọi là thai ngoài tử cung."], "bullets": []}, {"heading": "4. SỰ PHÁT TRIỂN CỦA TRỨNG ĐÃ THỤ TINH", "paragraphs": ["Về phương diện tổ chức quá trình phát triển của trứng được chia làm hai phần:", "Về phương diện thời gian quá trình phát triển của trứng được chia làm hai thời kỳ:"], "bullets": ["- Phần trứng sau này trở thành thai.", "- Phần trứng sau này trở thành các phần phụ của thai.", "- Thời kỳ sắp xếp tổ chức: bắt đầu từ lúc thụ tinh đến hết tháng thứ hai.", "- Thời kỳ hoàn thiện tổ chức: từ tháng thứ ba trở đi.."]}, {"heading": "4.1.1. Sự hình thành bào thai", "paragraphs": ["Trong quá trình di chuyển từ nơi thụ tinh đến nơi làm tổ, trứng đã thụ tinh tiếp tục phát triển qua giai đoạn phôi dâu và đến khi làm tổ ở giai đoạn phôi nang. Các tế bào mầm to tiếp tục phân chia và phát triển thành bào thai với hai lớp tế bào: lá thai ngoài và lá thai trong. Vào ngày thứ 6 - 7 sau thụ tinh bắt đầu biệt hoá thành lá thai trong, ngày thứ 8 biệt hoá thành lá thai ngoài, vào tuần thứ 3 giữa hai lá sẽ phát triển thêm lá thai giữa. Các lá thai này tạo ra phôi thai và từ tuần lễ thứ 8 phôi thai được gọi là thai nhi.", "Ở phôi thai mới thành lập người ta phân biệt 3 vùng: vùng trước là đầu, vùng giữa nhô ra để trở thành bụng, lưng có rãnh thần kinh, vùng sau là phần đuôi và có mạng lưới thần kinh. Vùng trước và sau dần dần phình ra để tạo hình chi trên và chi dưới. Cuối thời kỳ phôi thai phần đầu phôi to một cách không cân đối, đã có phác hình của mắt, mũi, miệng, tai ngoài; tứ chi trở nên rõ nét (có chồi ngón), các bộ phận chính như tuần hoàn tiêu hoá cũng được thành lập ở thời kỳ này. Bào thai cong hình lưng tôm, phía bụng phát sinh ra nang rốn để cung cấp các chất dinh dưỡng. Từ các cung động mạch của thai các mạch máu phát ra đi vào nang rốn, đem chất dinh dưỡng nuôi thai. Đây là hệ tuần hoàn thứ nhất hay còn được gọi là hệ tuần hoàn nang rốn. Về sau ở phía đuôi và bụng bào thai mọc ra một túi khác gọi là nang niệu, trong nang này có phần cuối của động mạch chủ.", "Nguồn gốc", "Hình thành các bộ phận", "Lá thai ngoài", "Lá thai giữa", "Lá thai trong", "Hình 5. Nguồn gốc và sự hình thành các bộ phận"], "bullets": ["- Hệ thần kinh", "- Da", "- Hệ xương", "- Hệ cơ", "- Mô liên kết", "- Hệ tuần hoàn", "- Hệ tiết niệu", "- Hệ tiêu hoá", "- Hệ hô hấp"]}, {"heading": "4.1.2. Sự phát triển của phần phụ", "paragraphs": [], "bullets": ["- Nội sản mạc: về phía lưng của bào thai một số tế bào của lá thai ngoài tan đi, tạo thành một buồng gọi là buồng ối, trong chứa nước ối, thành của màng ối là một màng mỏng gọi là nội sản mạc.", "- Trung sản mạc: các tế bào mầm nhỏ phát triển thành trung sản mạc, bao gồm hai lớp: lớp ngoài là hội bào, lớp trong là các tế bào Langhans, trung sản mạc tạo thành các chân giả bao quanh trứng, được gọi là thời kỳ trung sản mạc rậm (thời kỳ rau toàn diện).", "- Ngoại sản mạc: trong khi trứng làm tổ niêm mạc tử cung phát triển thành ngoại sản mạc. Người ta phân biệt 3 phần:", "+ Ngoại sản mạc tử cung: chỉ liên quan đến tử cung.", "+ Ngoại sản mạc trứng: chỉ liên quan đến trứng.", "+ Ngoại sản mạc tử cung - rau: là phần ngoại sản mạc nằm giữa lớp cơ tử cung và trứng."]}, {"heading": "4.2.1. Sự phát triển của thai", "paragraphs": ["Thời kỳ này phôi thai được gọi là thai nhi, bắt đầu có đủ các bộ phận và tiếp tục phát triển tới khi hoàn chỉnh tổ chức. Bộ phận sinh dục được nhận biết rõ rệt vào tháng thứ 4, thai cũng bắt đầu vận động vào cuối tuần thứ 16. Cuối tháng thứ 6 da thai còn nhăn, được bao bọc bởi chất gây, sang tháng thứ 7 da bớt nhăn do nhiều mỡ dưới da; xuất hiện móng tay và móng chân. Các điểm cốt hoá ở đầu dưới xương đùi xuất hiện vào tuần thứ 36 và ở đầu trên xương chày vào tuần thứ 38.", "Trong thời kỳ này thai sống bằng hệ tuần hoàn thứ hai hay hệ tuần hoàn nang niệu. Nang niệu lôi kéo dần các mạch máu của nang rốn sang, nang rốn teo dần đi. Cuối cùng tuần hoàn nang niệu thay thế hoàn toàn tuần hoàn nang rốn, rối dần dần nang niệu cũng teo đi, chỉ còn lại các mạch máu, đó là động mạch rốn và tĩnh mạch rốn.", "Hình 6. Kích thước thai theo tuổi thai"], "bullets": []}, {"heading": "4.2.2. Sự phát triển của các phần phụ", "paragraphs": ["Hình 7. Ngoại sản mạc"], "bullets": ["- Nội sản mạc: ngày càng phát triển, buồng ối ngày càng rộng ra và bao quanh thai nhi, thai nhi như con cá nằm trong nước.", "- Trung sản mạc: các chân giả sẽ tan đi, trung sản mạc trở thành nhẵn, chỉ còn lại phần bám vào tử cung sẽ tiếp tục phát triển thành gai rau với hai loại tế bào là hội bào và tế bào Langhans; trong lòng gai rau có tổ chức liên kết và các mao mạch của mạch máu rốn. Lớp hội bào đục thủng niêm mạc tử cung tạo thành các hồ huyết, chứa hai loại gai rau:", "+ Gai rau dinh dưỡng lơ lửng trong hồ huyết, có nhiệm vụ trao đổi chất giữa thai và mẹ.", "+ Gai rau bám sẽ bám vào nóc hoặc vách hồ huyết, giữ cho rau bám vào niêm mạc tử cung.", "- Ngoại sản mạc: ngoại sản mạc trứng và ngoại sản mạc tử cung teo mỏng dần, đến gần đủ tháng hai màng này hợp làm một và chỉ còn ở một số vùng. Ngoại sản mạc tử cung - rau tiếp tục phát triển và bị đục thành các hồ huyết, có máu mẹ từ các nhánh của động mạch tử cung chảy tới; sau khi trao đổi dinh dưỡng máu theo các nhánh của tĩnh mạch tử cung trở về tuần hoàn mẹ."]}], "raw_text": "SỰ THỤ TINH, LÀM TỔ\nVÀ PHÁT TRIỂN CỦA TRỨNG\nThs. Bùi Thị Thanh Tuyền\nMục tiêu học tập\n1. Mô tả được quá trình sinh giao tử và sự thụ tinh.\n2. Mô tả được sự di chuyển và làm tổ của trứng đã thụ tinh.\n3. Mô tả được sự phát triển của trứng đã thụ tinh.\n\n1. ĐẠI CƯƠNG\n- Sự thụ tinh là sự kết hợp giữa một tế bào đực (tinh trùng) và một tế bào cái (noãn) để hình thành một tế bào mới là trứng được thụ tinh.\n- Sự thụ thai là sự thụ tinh kèm theo sau đó là sự làm tổ của trứng.\n- Sau khi làm tổ trứng phát triển thành thai và các phần phụ của thai (bánh rau, màng rau, dây rau và nước ối).\n2. SỰ THỤ TINH\n2.1. Sự phát triển của giao tử\nGiao tử là tế bào sinh dục, được biệt hoá cao, giữ một nhiệm vụ duy nhất là sinh sản và không giống với bất kỳ một tế bào nào khác. Tế bào sinh dục có kích thước khá lớn (25 - 30 (m), bào tương nhạt, giàu lipid, có nhân và một thể Idiosome (gồm 2 trung thể và bộ máy Golgy). Giao tử đực là tinh trùng mang bộ nhiễm sắc thể (NST) đơn bội. Giao tử cái là noãn cũng mang bộ NST đơn bội.\n2.1.1. Sự sinh tinh\nTinh trùng được sản sinh trong ống sinh tinh. Ra khỏi ống sinh tinh, tinh trùng có hình dạng cố định nhưng chưa di động, chưa thụ tinh được, chúng chỉ có khả năng trên sau khi đi qua ống mào tinh. Tinh trùng được dự trử tại mào tinh, ống tinh và phần lớn ở túi tinh. Sự sinh tinh trải qua nhiều giai đoạn để một tinh nguyên bào biến thành tinh trùng có khả năng thụ tinh. Qua trung gian của 5 lần phân chia, một tế bào cho ra 32 tinh trùng, quá trình kéo dài 74 ngày. Sự sinh tinh trùng là liên tục bắt đầu từ tuổi dậy thì (khoảng 200 triệu mỗi ngày).\nCấu trúc tinh trùng:\nTinh trùng là một tế bào đã được biệt hoá cao độ gồm có đầu thân và đuôi. Đầu là một khối nhân (chất nhiễm sắc) có hình tròn. Đầu được bảo vệ 3/4 phía trước bởi một cấu trúc đặc biệt gọi là thể cực đầu. Thể cực đầu chứa nhiều loại men có ảnh hưởng lên các loại protein của vỏ noãn như hyaluronidase, fertilysine. Đuôi nối tiếp với đầu qua trung gian đoạn cổ. Đuôi gồm có đoạn trung gian, đoạn chính và đoạn cuối. Trục của đuôi có cấu tạo đặc biệt gồm nhiều cặp ống ngoại vi và một cặp ống trung tâm, đó là bộ máy tạo ra sự cử động của đuôi. Tinh trùng được đẩy tới bởi các đợt sóng do đuôi tạo ra.\nCác đặc điểm của tinh trùng:\nư Chiều dài 65 àm.\n- Số lượng 60 - 120 triệu/ml tinh dịch.\n- Tỷ lệ hoạt động lúc mới phóng tinh > 80%.\n- Tốc độ di chuyển 1,5 - 2,5 mm/phút.\n- Thời gian sống trung bình trong đường sinh dục nữ tuỳ thuộc độ pH: ở âm đạo pH toan sống được < 2 giờ; ở ống cổ tử cung pH > 7,5 sống được 2 - 3 ngày; trong vòi tử cung tinh trùng sống thêm được 2 - 3 ngày.\n\nHình 1. Sự sinh tinh trùng\n2.1.2. Sự sinh noãn\nNoãn hình thành từ các nang trứng. Phần lớn các noãn trong thời kỳ bào thai và sau khi sinh đã bị thoái hoá còn lại từ 400 - 450  đạt tới mức độ chín sau tuổi dậy thì. Bề mặt noãn có nhiều vi mao xuyên qua màng trong suốt, bào tương tích luỹ nhiều Mucopolysacharide, Phosphatase kiềm và ARN. Phần lớn ARN tập trung thành từng vùng đặc biệt. Mỗi tháng 2 buồng trứng thay phiên nhau rụng một noãn từ tuổi dậy thì đến tuổi mãn kinh. Sự rụng trứng thường xảy ra khoảng giữa ngày thứ 12 và 14 của chu kỳ kinh và chia chu kỳ thành 2 giai đoạn: giai đoạn nang trứng (trước rụng trứng) và giai đoạn hoàng thể (sau rụng trứng). Nếu quá trình thụ tinh không xảy ra, sự thoái triển của hoàng thể dẫn đến kinh nguyệt. Giữa thời điểm cuối kỳ kinh trước và khởi đầu giai đoạn nang trứng, khoảng vài chục nang trứng đi vào giai đoạn tăng trưởng bằng cách tăng thể tích dịch nang và hốc nang lớn dần. Vào ngày thứ 6 chỉ có một nang duy nhất đạt tới tình trạng chín cần thiết: đó là nang trội, số nang còn lại bị thoái triển. Khoảng 36 giờ trước khi rụng trứng có một sự gia tăng tối đa hormone LH (Luteinizing Hormone) thúc đẩy trứng chín nhanh. Noãn rụng kèm theo màng trong suốt, tế bào gò noãn, tế bào vòng tia, tế bào hạt, tất cả đi vào loa vòi tử cung.\n\nHình 2. Sự sinh noãn từ noãn nguyên bào cho đến lúc thụ tinh\n2.1.3. Những bất thường trong sự sinh giao tử\n- Sự sinh tinh là một quá trình liên tục, mỗi ngày có hàng trăm triệu tinh trùng được tạo ra, 50% mang NST X và 50% mang NST Y.\n- Sự sinh noãn là một quá trình không liên tục, từng chu kỳ sinh ra những tế bào không bằng nhau (mặc dù trong cùng một lần phân bào), chỉ có một noãn hữu ích còn 2 cực cầu vô dụng.\n- Các quá trình phức tạp trên có thể là nguyên nhân gây bất thường về hình thái hoặc bất thường về NST:\n+ Bất thường về hình thái: rất khó quan sát những bất thường về hình thái ở noãn, nhưng đối với tinh trùng thì có thể thấy rõ hơn (ví dụ: tinh trùng hai đầu, …).\n+ Bất thường về NST: bất thường trong sự phân chia NST thường và NST giới tính.\n2.2. Sự thụ tinh\nSự hợp nhất cấu trúc tinh trùng và noãn xảy ra ở 1/3 ngoài của ống dẫn trứng. Thực chất đây là sự hoà lẫn giữa 2 bộ NST của noãn và tinh trùng.\nCó khoảng 200 triệu tinh trùng trong mỗi lần phóng tinh vào âm đạo. Cổ tử cung trước đó được bịt kín bởi một nút chất nhầy đặc quánh, dưới ảnh hưởng của estradiol được sinh ra từ nang trứng trong quá trình phát triển sẽ trở nên loãng hơn vào giai đoạn trước rụng trứng cho phép những tinh trùng di động nhanh nhất và mạnh nhất đi qua, số còn lại nằm lại  vùng cổ tử cung và túi cùng âm đạo. Nói chung, có khoảng vài triệu tinh trùng đến được gần noãn trong thời gian thích hợp vì tinh trùng có thể sống tới 1 tuần sau khi phóng còn noãn chỉ sống được hai ngày sau khi rụng. Khi tinh trùng vượt qua màng trong suốt của noãn, một sự hoà hợp vỏ bọc noãn và vỏ bọc thân tinh trùng xảy ra, nhân tinh trùng hoàn toàn được đưa vào trong bào tương noãn, đuôi rời khỏi đầu bị giữ lại bên ngoài màng trong suốt, một phản ứng vỏ noãn sẽ ngăn chặn không cho một tinh trùng nào khác được lọt vào chất noãn. Xuất hiện trong noãn một tiền nhân đực và một tiền nhân cái. Hai tiền nhân này tiếp tục phát triển riêng rẽ, sau đó xích lại gần nhau và hoà lẫn thành một sau khi cởi bỏ hoàn toàn màng bọc nhân. Ta có một hợp tử và sự phân cắt thành phôi bào bắt đầu.\nKết quả của sự thụ tinh:\n- Tái lập bộ NST của loài (2n).\n- Xác định giới tính của phôi: nếu tinh trùng mang NST Y thì phôi nang mang tính đực, nếu tinh trùng mang NST X thì phôi nang mang tính cái.\n- Chuẩn bị để hợp tử phân cắt.\n\nHình 3. Sự thụ tinh, hình thành tiền nhân đực, cái và phân bào lần đầu tiên.\n3. SỰ DI CHUYỂN VÀ LÀM TỔ CỦA TRỨNG ĐÃ THỤ TINH\n3.1. Sự di chuyển của trứng\nSau khi thụ tinh thường xảy ra ở 1/3 ngoài vòi tử cung, trứng tiếp tục di chuyển trong vòi tử cung để đến làm tổ ở buồng tử cung. Trứng di chuyển trong phần còn lại của vòi tử cung mất 3 - 4 ngày, sau đó còn sống tự do trong buồng tử cung thêm 2 - 3 ngày nữa mới bắt đầu quá trình làm tổ. Có 3 cơ chế tham gia vào sự di chuyển của trứng:\n- Nhu động của vòi tử cung.\n- Hoạt động của nhung mao niêm mạc vòi tử cung.\n- Luồng dịch chảy từ phía loa vòi tử cung vào buồng tử cung.\nTrên đường di chuyển trứng phân bào rất nhanh, từ một tế bào ban đầu phân chia thành 2 rồi 4 tế bào mầm bằng nhau, sau đó phân chia thành 8 tế bào: 4 tế bào mầm to và 4 tế bào mầm nhỏ. Các tế bào mầm nhỏ phát triển nhanh hơn các tế bào mầm to và bao quanh các tế bào mầm to, tạo nên phôi dâu, có hình dạng bên ngoài giống hình quả dâu. Các tế bào mầm nhỏ tạo thành lá nuôi có tác dụng nuôi dưỡng bào thai; các tế bào mầm to nằm ở giữa sẽ trở thành các lá thai, sẽ phát triển thành thai nhi. Ở giai đoạn phôi dâu nhóm tế bào trung tâm lớn hơn sẽ cho ra cúc phôi, nhóm tế bào ngoại vi nhỏ hơn ở giai đoạn 32 tế bào sẽ tiết dịch, tạo thành xoang đẩy cúc phôi về một góc.\n3.2. Sự làm tổ\nỞ giai đoạn phôi dâu khi đã lọt vào khoang tử cung (vào khoảng ngày thứ 5 - 6 sau thụ tinh) hình thành một hốc nhỏ trong lòng phôi dâu nơi cúc phôi sẽ phát triển, những tế bào nhỏ giãn ra xung quanh hốc, tạo thành phôi nang. Phôi nang sẽ làm tổ vào nội mạc tử cung (khoảng ngày thứ 6 sau thụ tinh). Lúc này màng trong suốt đã biến mất.\nSự phát triển bình thường đòi hỏi sự hiện diện của 2 bộ NST của bố và mẹ mà vai trò không giống nhau. Bộ NST của bố sẽ cần thiết cho sự phát triển các phần phụ và bộ NST mẹ cần cho sự phát triển của cúc phôi.\nPhôi nang hình thành vào ngày thứ 5, phần lớn tế bào ngoại vi tạo thành lá nuôi. Cúc phôi chứa 2 loại tế bào, một loại có số lượng ít sẽ là nguồn gốc bản phôi, phần khác sẽ cho ra những phần phụ ngoài phôi cần thiết để duy trì phôi. Phôi nang bắt đầu làm tổ vào ngày thứ 6 hoặc thứ 7 và làm tổ ở mặt đáy của cúc phôi nhờ hoạt động phân giải của lá nuôi hợp bào bằng cách bào mòn và xâm nhập dần dần vào nội mạc tử cung. Vào giai đoạn này, cúc phôi bắt đầu tách rời khỏi lá nuôi.\nVị trí làm tổ thường ở mặt sau đáy tử cung, nhưng cũng có thể \"lạc chỗ\". Quá trình diễn biến như sau:\n- Ngày thứ 6 - 8: hiện tượng dính và bám rễ của phôi: phôi nang dính vào niêm mạc tử cung, các chân giả xuất phát từ các tế bào nuôi bám vào biểu mô, một số liên bào bị tiêu huỷ và phôi nang chui qua lớp biểu mô\n- Ngày thứ 9 - 10: phôi qua lớp biểu mô trụ, chưa nằm sâu trong lớp đệm và bề mặt chưa được biểu mô phủ kín.\n- Ngày thứ 11 - 12: phôi nằm hoàn toàn trong lớp đệm nhưng lỗ chui qua vẫn chưa được phủ kín.\n- Ngày thứ 13 - 14: phôi nằm hoàn toàn trong lớp đệm, được biểu mô phủ kín. Trung sản mạc được biệt hoá thành hai loại tế bào và hình thành những gai rau đầu tiên.\nTrước sự làm tổ, nội mạc tử cung dưới ảnh hưởng của progesterone và các yếu tố kích thích nội mạc mạch máu (Vascular Endothelial Growth Factor - VEGF) phát triển để đủ điều kiện để đón nhận hợp tử. Trong giai đoạn phát triển nội mạc giàu mạch máu, lớp đệm xung huyết, phù nề, tuyến phát triển dài và cong queo, tích luỹ nhiều Glycogen và chất nhầy trong lòng tuyến và trong tế bào.\n\n\nHình 4. Sự phát triển của phôi trong quá trình di chuyển\n3.3. Những bất thường trong sự làm tổ\nThông thường phôi làm tổ ở mặt trước và mặt sau thân tử cung. Các vị trí bất thường có thể gặp: vòi tử cung, buồng trứng, cổ tử cung, trong ổ bụng, đó là thai \"lạc chỗ\" hay còn gọi là thai ngoài tử cung.\n4. SỰ PHÁT TRIỂN CỦA TRỨNG ĐÃ THỤ TINH\nVề phương diện tổ chức quá trình phát triển của trứng được chia làm hai phần:\n- Phần trứng sau này trở thành thai.\n- Phần trứng sau này trở thành các phần phụ của thai.\nVề phương diện thời gian quá trình phát triển của trứng được chia làm hai thời kỳ:\n- Thời kỳ sắp xếp tổ chức: bắt đầu từ lúc thụ tinh đến hết tháng thứ hai.\n- Thời kỳ hoàn thiện tổ chức: từ tháng thứ ba trở đi..\n4.1. Thời kỳ sắp xếp tổ chức\n4.1.1. Sự hình thành bào thai\nTrong quá trình di chuyển từ nơi thụ tinh đến nơi làm tổ, trứng đã thụ tinh tiếp tục phát triển qua giai đoạn phôi dâu và đến khi làm tổ ở giai đoạn phôi nang. Các tế bào mầm to tiếp tục phân chia và phát triển thành bào thai với hai lớp tế bào: lá thai ngoài và lá thai trong. Vào ngày thứ 6 - 7 sau thụ tinh bắt đầu biệt hoá thành lá thai trong, ngày thứ 8 biệt hoá thành lá thai ngoài, vào tuần thứ 3 giữa hai lá sẽ phát triển thêm lá thai giữa. Các lá thai này tạo ra phôi thai và từ tuần lễ thứ 8 phôi thai được gọi là thai nhi.\nỞ phôi thai mới thành lập người ta phân biệt 3 vùng: vùng trước là đầu, vùng giữa nhô ra để trở thành bụng, lưng có rãnh thần kinh, vùng sau là phần đuôi và có mạng lưới thần kinh. Vùng trước và sau dần dần phình ra để tạo hình chi trên và chi dưới. Cuối thời kỳ phôi thai phần đầu phôi to một cách không cân đối, đã có phác hình của mắt, mũi, miệng, tai ngoài; tứ chi trở nên rõ nét (có chồi ngón), các bộ phận chính như tuần hoàn tiêu hoá cũng được thành lập ở thời kỳ này. Bào thai cong hình lưng tôm, phía bụng phát sinh ra nang rốn để cung cấp các chất dinh dưỡng. Từ các cung động mạch của thai các mạch máu phát ra đi vào nang rốn, đem chất dinh dưỡng nuôi thai. Đây là hệ tuần hoàn thứ nhất hay còn được gọi là hệ tuần hoàn nang rốn. Về sau ở phía đuôi và bụng bào thai mọc ra một túi khác gọi là nang niệu, trong nang này có phần cuối của động mạch chủ.\nNguồn gốc\nHình thành các bộ phận\n\nLá thai ngoài\n- Hệ thần kinh\n- Da\n\nLá thai giữa\n- Hệ xương\n- Hệ cơ\n- Mô liên kết\n- Hệ tuần hoàn\n- Hệ tiết niệu\n\nLá thai trong\n- Hệ tiêu hoá\n- Hệ hô hấp\n\n\nHình 5. Nguồn gốc và sự hình thành các bộ phận\n\n4.1.2. Sự phát triển của phần phụ\n- Nội sản mạc: về phía lưng của bào thai một số tế bào của lá thai ngoài tan đi, tạo thành một buồng gọi là buồng ối, trong chứa nước ối, thành của màng ối là một màng mỏng gọi là nội sản mạc.\n- Trung sản mạc: các tế bào mầm nhỏ phát triển thành trung sản mạc, bao gồm hai lớp: lớp ngoài là hội bào, lớp trong là các tế bào Langhans, trung sản mạc tạo thành các chân giả bao quanh trứng, được gọi là thời kỳ trung sản mạc rậm (thời kỳ rau toàn diện).\n- Ngoại sản mạc: trong khi trứng làm tổ niêm mạc tử cung phát triển thành ngoại sản mạc. Người ta phân biệt 3 phần:\n+ Ngoại sản mạc tử cung: chỉ liên quan đến tử cung.\n+ Ngoại sản mạc trứng: chỉ liên quan đến trứng.\n+ Ngoại sản mạc tử cung - rau: là phần ngoại sản mạc nằm giữa lớp cơ tử cung và trứng.\n4.2. Thời kỳ hoàn chỉnh tổ chức\n4.2.1. Sự phát triển của thai\nThời kỳ này phôi thai được gọi là thai nhi, bắt đầu có đủ các bộ phận và tiếp tục phát triển tới khi hoàn chỉnh tổ chức. Bộ phận sinh dục được nhận biết rõ rệt vào tháng thứ 4, thai cũng bắt đầu vận động vào cuối tuần thứ 16. Cuối tháng thứ 6 da thai còn nhăn, được bao bọc bởi chất gây, sang tháng thứ 7 da bớt nhăn do nhiều mỡ dưới da; xuất hiện móng tay và móng chân. Các điểm cốt hoá ở đầu dưới xương đùi xuất hiện vào tuần thứ 36 và ở đầu trên xương chày vào tuần thứ 38.\nTrong thời kỳ này thai sống bằng hệ tuần hoàn thứ hai hay hệ tuần hoàn nang niệu. Nang niệu lôi kéo dần các mạch máu của nang rốn sang, nang rốn teo dần đi. Cuối cùng tuần hoàn nang niệu thay thế hoàn toàn tuần hoàn nang rốn, rối dần dần nang niệu cũng teo đi, chỉ còn lại các mạch máu, đó là động mạch rốn và tĩnh mạch rốn.\n\nHình 6. Kích thước thai theo tuổi thai\n4.2.2. Sự phát triển của các phần phụ\n- Nội sản mạc: ngày càng phát triển, buồng ối ngày càng rộng ra và bao quanh thai nhi, thai nhi như con cá nằm trong nước.\n- Trung sản mạc: các chân giả sẽ tan đi, trung sản mạc trở thành nhẵn, chỉ còn lại phần bám vào tử cung sẽ tiếp tục phát triển thành gai rau với hai loại tế bào là hội bào và tế bào Langhans; trong lòng gai rau có tổ chức liên kết và các mao mạch của mạch máu rốn. Lớp hội bào đục thủng niêm mạc tử cung tạo thành các hồ huyết, chứa hai loại gai rau:\n+ Gai rau dinh dưỡng lơ lửng trong hồ huyết, có nhiệm vụ trao đổi chất giữa thai và mẹ.\n+ Gai rau bám sẽ bám vào nóc hoặc vách hồ huyết, giữ cho rau bám vào niêm mạc tử cung.\n- Ngoại sản mạc: ngoại sản mạc trứng và ngoại sản mạc tử cung teo mỏng dần, đến gần đủ tháng hai màng này hợp làm một và chỉ còn ở một số vùng. Ngoại sản mạc tử cung - rau tiếp tục phát triển và bị đục thành các hồ huyết, có máu mẹ từ các nhánh của động mạch tử cung chảy tới; sau khi trao đổi dinh dưỡng máu theo các nhánh của tĩnh mạch tử cung trở về tuần hoàn mẹ.\n\nHình 7. Ngoại sản mạc\nCâu hỏi:\n1. Trình bày Sự thụ tinh (định nghĩa, cơ chế, hiện tượng thụ tinh)?\n2.  Trình bày sự di chuyển và làm tổ của trứng?\n3.  Trình bày sự phát triển của trứng và phần phụ của trứng ở giai đoạn sắp xếp tổ chức?\n4. Trình bày sự phát triển của trứng và phần phụ của trứng ở giai đoạn hoàn chỉnh tổ chức?", "priority": "Trung bình"}, {"id": "SK-04", "chapter": "Chương 1. Sản thường", "folder": "01_San_thuong", "title": "Tính chất thai nhi và phần phụ đủ tháng", "author": "Ths. Trần Thị Len", "word_count": 3605, "line_count": 162, "key_numbers": ["0,002mm", "0,052mm", "1 cm", "1 tuần", "1000 ml", "11 cm", "11 tuần", "12 cm", "12 tuần", "13 cm", "15 cm", "1cm", "20mm", "24 giờ", "3 cm", "3 giờ", "3 tháng", "3000g", "33cm", "38cm", "5 cm", "50cm", "50kg", "6 cm", "60cm", "8cm", "9 cm", "9,5cm"], "key_drugs": ["Glucose", "glucose"], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["TÍNH CHẤT THAI NHI VÀ PHẦN PHỤ ĐỦ THÁNG", "Ths. Trần Thị Len"], "bullets": []}, {"heading": "1. THAI NHI ĐỦ THÁNG", "paragraphs": ["Thai nhi đủ tháng có cấu tạo giải phẫu gần giống người lớn. Thai nhi đủ tháng có trọng lượng trung bình nặng khoảng 3000g, dài 50cm. Tuy vậy khi còn sống trong tử cung hoạt động của bộ máy hô hấp và tuần hoàn của thai nhi khác với trẻ sơ sinh."], "bullets": []}, {"heading": "1.1.1. Đầu: Có hai phần: sọ và mặt. Sọ có 2 vùng là đỉnh sọ và đáy sọ.", "paragraphs": ["Hình 1. Thóp trước và thóp sau", "Bình thường các thóp mềm. Trong trường hợp não úng thủy thì các thóp căng phồng, đường khớp giãn rộng hơn 1 cm.", "Cần nắm vững đặc điểm của thóp trước, thóp sau, vị trí của các khớp nối để xác định ngôi, thế và kiểu thế, và để phát hiện các bất thường của ngôi và thai.", "Hình 2. Các đường kính của đầu."], "bullets": ["- Đáy sọ: là một phần của các xương trán, xương thái dương, xương chẩm và các xương bướm, xương sàng. Đáy sọ không thể thu hẹp khi đi qua tiểu khung.", "- Đỉnh sọ: gồm hai xương trán, hai xương đỉnh, và một xương chẩm. Giữa các xương là khớp màng mỏng giúp cho xương sọ có thể dịch chuyển và chồng lên nhau. Điều này giúp đỉnh sọ có thể thu hẹp được nhiều khi đầu thai nhi đi qua tiểu khung trong quá trình đẻ, có thể thấy các xương chồng lên nhau ở khớp nối trong và sau khi đẻ.", "- Các đường khớp:", "+ Đường khớp dọc giữa: đi từ thóp trước tới thóp sau giữa 2 xương thái dương và kết thúc tại xương chẩm.", "+ Các đường khớp ngang: Trước là đường khớp nằm giữa các xương trán và xương thái dương. Sau là khớp Lambda nằm giữa các xương thái dương và xương chẩm.", "- Thóp là nơi giao nhau của các đường khớp dọc và đường khớp ngang. Có hai thóp chính:", "+ Thóp trước gọi là thóp lớn (Bregma) được tạo bởi đường khớp dọc giữa với đường khớp trán - đỉnh. Thóp trước có hình tứ giác và kích thước từ 2 x 3 cm tới 4 x 6 cm.", "+ Thóp sau gọi là thóp nhỏ (Lambda) được tạo bởi 3 đường khớp: 2 đường đỉnh - chẩm và phần cuối của đường khớp dọc giữa. Thóp sau có hình tam giác và nhỏ hơn.", "- Các đường kính của đầu: đầu có 3 đường kính trước - sau quan trọng như sau:", "+ Hạ chẩm - thóp trước: 9,5cm đi từ hạ chẩm đến thóp trước. Đây là đường kính lọt của ngôi chỏm đầu cúi tốt (đường kính nhỏ nhất).", "+ Chẩm - trán: 11, 5 cm, đi từ phần trên xương chẩm đến xương trán, đây là đường kính trong trường hợp ngôi chỏm đầu không cúi, không ngửa.", "+ Chẩm - cằm: 13 cm nằm giữa phần trên xương chẩm và xương cằm, gặp trong ngôi thóp trước.", "- Đường kính trên dưới: có 1 đường kính.", "+ Đường kính hạ cằm - thóp trước 9,5cm, đi từ hạ cằm đến thóp trước, gặp trong ngôi mặt.", "- Các đường kính ngang: có 2 đường kính.", "+ Lưỡng đỉnh 9, 5 cm.", "+ Lưỡng thái dương 8cm.", "- Vòng đầu: có 2 vòng.", "+ Vòng đầu to đi qua đường kính thượng chẩm - cằm, có chu vi 38cm.", "+ Vòng đầu nhỏ đi qua đường kính hạ chẩm - thóp trước, có chu vi 33cm."]}, {"heading": "1.1.2. Cổ và thân", "paragraphs": [], "bullets": ["- Cổ giúp cho đầu quay 1800, thực hiện các động tác khác dễ dàng. Nó chịu được một lực kéo dưới 50kg.", "- Thân thai nhi có một số đường kính:", "+ Đường kính lưỡng mỏm vai: 12 cm, có thể thu hẹp còn 9 cm.", "+ Đường kính lưỡng ụ đùi: 9 cm.", "+ Đường kính cùng chày: 11 cm, có thể thu lại 9 cm."]}, {"heading": "1.2. Sinh lý", "paragraphs": ["Khi còn trong tử cung thai sống nhờ mẹ qua hệ tuần hoàn tử cung - rau."], "bullets": []}, {"heading": "1.2.1. Hệ tuần hoàn", "paragraphs": ["Hình 3. Tuần hoàn thai nhi", "Sự lưu thông của máu thai nhi diễn ra như sau:"], "bullets": ["- Tim của thai nhi có 4 buồng: 2 tâm thất và 2 nhĩ. 2 tâm nhĩ thông nhau qua lỗ Botal.", "- Động mạch chủ và động mạch phổi thông nhau qua ống động mạch.", "- Từ động mạch hạ vị của thai có 2 động mạch rốn đưa máu trở lại bánh rau.", "- Máu sau khi trao đổi chất và ôxy từ bánh rau đến thai bằng tĩnh mạch rốn, đến tĩnh mạch chủ dưới nó sẽ pha với máu từ phần dưới cơ thể của thai nhi để đổ vào tĩnh mạch chủ. Máu đến tâm nhĩ phải một phần xuống thất phải để vào động mạch phổi, một phần qua lỗ Botal vào nhĩ trái. Theo cách này, máu giàu ô xy từ bánh rau có thể tới thẳng não của thai nhi. Phổi chưa làm việc nên hầu hết máu từ động mạch phổi sang động mạch chủ nhờ ống động mạch. Động mạch chủ đồng thời nhận máu từ thất trái đi nuôi cơ thể, một phần qua hai động mạch rốn trở về rau thai. Như vậy máu thai nhi là máu pha trộn. Sau khi trẻ ra đời thì các mạch máu rốn co lại. Hiện tượng thở tạo áp lực âm trong lồng ngực, như vậy sẽ hút thêm máu từ động mạch phổi vào phổi. Với các mao mạch phổi phát triển sẽ làm giảm áp lực mạch ở phổi, do đó máu ngừng đi qua ống động mạch, ống này bít lại trong 12-24 giờ sau đẻ và trở thành một dây chằng. Đôi khi ống này vẫn ở trạng thái mở trong một khoảng thời gian, đặc biệt ở những trẻ đẻ non, do đó sẽ nghe thấy tiếng thổi tim trong trường hợp này. Lỗ Botal là một lỗ van để cho máu đi từ tim phải sang tim trái. Sau khi sinh, áp lực tâm nhĩ trái tăng lên làm cho van bị bít lại. Áp lực này bít van và sau đó trong thời gian 1 tới 3 tháng sẽ hình thành một màng có tác dụng bít van vĩnh viễn. Lúc này trẻ sơ sinh  bắt đầu sống với hệ tuần hoàn vĩnh viễn như người lớn."]}, {"heading": "1.2.2. Hệ hô hấp", "paragraphs": ["Khi còn trong tử cung oxy được cung cấp cho thai qua bánh rau. Khí CO2 từ thai nhi đến gai rau thải vào hố huyết trở về máu mẹ. Máu từ tĩnh mạch rốn đến thai chứa nhiều khí O2. Sự trao đổi khí O2, CO2 giữa máu mẹ và máu con là một quá trình khuếch tán đơn giản, do sự chênh lệch nồng độ khuếch tán của các chất đó."], "bullets": ["- Độ bão hòa O2 trong máu đến từ bánh rau tới thai nhi là 80-85%. Khi máu từ tim lên não, độ bão hòa là 60%. Hemoglobin ở thai nhi hoàn toàn có đủ khả năng mang ôxy. Thai nhi cũng có nhiều ôxy nhờ có hematocrit cao.", "- Nếu có tình trạng thiếu khí O2 sẽ xảy ra tình trạng toan hô hấp do thừa CO2 và toan chuyển hóa do thừa acid lactic. Tình trạng trung tâm hóa tuần hoàn thai nhi xảy ra để tập trung máu cho các cơ quan quan trọng như não, tim. Do thiếu oxy nhu động ruột tăng nên sẽ tống phân su vào nước ối. Đây có thể là một dấu hiệu của suy thai."]}, {"heading": "1.2.3. Tiêu hóa", "paragraphs": ["Thai nhận chất dinh dưỡng từ mẹ qua bánh rau. Thai nhi bắt đầu nuốt nước ối vào tuần 8-11. Nước ối chứa các tế bào thượng bì, lông, dịch từ phổi thai nhi. Thai nhi tiêu hóa những thành phần này và tạo ra phân su. Phân su là một chất dịch sánh đặc, màu xanh đen với thành phần là chất nhầy, tế bào bong niêm mạc đường tiêu hóa, men ruột, mật và ít nước ối. Ruột thai nhi không có vi khuẩn cho tới khi sinh."], "bullets": []}, {"heading": "1.2.4. Bài tiết", "paragraphs": [], "bullets": ["- Da bài tiết các chất nhờn và bã vào tháng thứ  5. Quá trình này tạo chất gây nhằm bảo vệ da.", "- Thận bắt đầu tiết nước tiểu khi thai mới được 11 tuần tuổi: người ta thấy trong nước ối có một phần nước tiểu thai nhi, trẻ mới sinh ra đã có nước tiểu trong bàng quang. Một vài trường hợp bệnh lý về thận của thai nhi khiến lượng nước tiểu giảm có thể làm giảm lượng nước ối. Đó là một trong những nguyên nhân gây thiểu ối (oligohydramnios)."]}, {"heading": "1.2.5. Hệ thống nội tiết", "paragraphs": ["Tinh hoàn bắt đầu sản xuất testosterone từ tuần thứ 7 của quá trình thai nghén. Tuyến thượng thận và tụy - từ tuần thứ 12, tuyến giáp và tuyến yên - từ tuần 20. Buồng trứng không tiết estrogene hoặc progesterone cho tới thời điểm dậy thì.", "Phần lớn hệ thống nội tiết của thai nhi hoạt động từ rất sớm và hình thành đơn vị nội tiết  rau - thai."], "bullets": []}, {"heading": "2. CÁC PHẦN PHỤ ĐỦ THÁNG", "paragraphs": ["Các phần phụ đủ tháng của thai bao gồm các màng thai, bánh rau, dây rốn và nước ối."], "bullets": []}, {"heading": "2.1.1. Màng rụng (ngoại sản mạc)", "paragraphs": ["Màng rụng là màng chức năng của nội mạc tử cung ở phụ nữ có thai, còn được gọi là ngoại sản mạc. Màng rụng có 3 lớp:"], "bullets": ["- Màng rụng nền (Decidua basalis): nằm dưới phôi bào,còn được gọi là ngoại sản mạc tử cung rau.", "- Màng rụng trứng (Decidua capsularis): bao phủ phôi bào, còn được gọi là ngoại sản mạc trứng", "- Màng rụng thành tử cung (Decidua parietalis) bao phủ phần còn lại của buồng tử cung, còn được gọi là ngoại sản mạc tử cung.", "- Khi thai đủ tháng, màng rụng trứng và màng rụng tử cung teo mỏng, dính sát vào nhau."]}, {"heading": "2.1.2. Màng đệm (trung sản mạc)", "paragraphs": ["Màng đệm còn gọi là trung sản mạc, phát triển không đều. Phần bám vào màng rụng nền phát triển mạnh tạo thành các gai rau, phần còn lại của màng đệm sẽ trở thành một màng mỏng ít thấm nước."], "bullets": []}, {"heading": "2.1.3. Màng ối (nội sản mạc)", "paragraphs": ["Màng ối, còn gọi là nội sản mạc, là một màng mỏng lót mặt trong buồng ối; che phủ mặt trong bánh rau, dây rốn. Màng ối dai và dễ thấm nước. Màng này có nhiệm vụ sản xuất, tiêu thụ nước ối, ngăn cản vi khuẩn để bảo vệ cho thai.", "Màng ối nằm trong sát với thai nhi và màng đệm nằm ngoài. Trong trường hợp sinh đôi 2 noãn luôn có 2 màng ối và 2 màng đệm. Trong trường hợp sinh đôi 1 noãn sẽ có thể có 2 màng ối và 2 màng đệm nếu sự phân chia xuất hiện sớm. Nếu việc này xảy ra muộn có thể có 1 màng đệm và 2 màng ối, đây là trường hợp phổ biến nhất. Hiếm hơn, khi sự phân chia xảy ra muộn chỉ tạo ra một màng đệm và một màng ối, trường hợp này sẽ nguy hiểm hơn cho cặp song sinh.", "Bề dày của màng rau thai lúc 12 tuần là 0,052mm, khi đủ tháng là 0,002mm."], "bullets": []}, {"heading": "2.2.1. Cấu tạo", "paragraphs": ["Bánh rau hình tròn, đường kính khoảng 15 cm, nặng 1/6 trọng lượng thai nhi (khoảng 400 - 500 gram), dày 2,5 - 3 cm, mỏng hơn ở ngoại vi. Mỗi bánh rau gồm 15 - 20 múi, giữa các múi là các rãnh nhỏ. Bánh rau thường bám vào đáy tử cung. Bánh rau hình thành do sự phát triển của màng rụng nền và màng đệm.", "Màng rụng ở vùng bánh rau có 3 lớp: lớp đáy, lớp xốp và lớp đặc. Lớp xốp là đường bong của rau sau khi sinh. Trong lớp đặc có sản bào và hồ huyết. Đại đa phần màng này rụng rau sinh và có chảy máu kèm theo.", "Hình 4. Bánh rau"], "bullets": []}, {"heading": "2.2.2. Chức năng: Bánh rau có 2 chức năng chính:", "paragraphs": ["Chức năng thứ 1: đảm bảo cho thai sống và phát triển. Sự trao đổi chất thực hiện qua lớp hội bào của gai rau.", "Máu trong hồ huyết phải luôn luôn được đổi mới. Trong các trường hợp mẹ bị cao huyết áp trong thai kỳ hoặc cơn go cường tính máu ở hồ huyết chậm đổi mới sẽ gây suy thai.", "Ngoài ra, gai rau còn có thể tổng hợp một số phospholipid, nhất là các steroid rau thai.", "Chức năng thứ 2: giữ vai trò nội tiết để cơ thể mẹ phù hợp với thai nghén."], "bullets": ["-\tHô hấp: Sự trao đổi O2 và CO2 giữa máu mẹ và thai là một quá trình khuếch tán đơn giản do các đặc điểm sau:", "+ Áp lực máu mẹ ở hồ huyết của bánh rau thấp hơn máu thai và tốc độ chảy chậm.", "+ Nồng độ CO2 thấp hơn và nồng độ O2 trong máu mẹ cao hơn máu thai.", "+ Hemoglobine của thai có khả năng gắn O2 cao.", "+ Diện tích trao đổi mẹ - thai tăng do cấu trúc dạng nhú của gai rau.", "- Dinh dưỡng: Nguyên liệu tạo hình và năng lượng cần cho thai đều đưa từ mẹ vào qua gai rau.", "+ Các protein phải chuyển thành axit amin và đi qua gai rau, sau đó thai mới sử dụng để tổng hợp lại thành protein đặc hiệu của thai.", "+ Các Lipid rất ít đi qua rau thai nên thai thường thiếu các vitamin tan trong dầu như A, D, E, K. Do vậy trẻ sơ sinh hay bị chảy máu do giảm prothrombin và thiếu Vitamin K. Vitamin K sẽ được tổng hợp đầy đủ ở 1 tuần tuổi bởi các vi khuẩn trong ruột của trẻ sơ sinh.", "+ Glucose qua rau thai nhờ hiện tượng khuếch tán, gai rau còn tham gia chuyển glucose thành glycogen và dự trữ ở gai rau.", "+ Vitamin: Vitamin B, C qua rau thai dễ dàng.", "- Bảo vệ:", "+ Một số kháng nguyên kháng thể có nguồn gốc protein có thể đi qua  rau thai. Nhờ đó thai có khả năng miễn dịch thụ động, nhưng cũng có khi nguy hiểm cho thai nếu có sự bất đồng Rh hoặc bất đồng nhóm ABO.", "+ Mầm bệnh: Các vi khuẩn không qua được rau thai. Tuy nhiên vào các tháng cuối có một số loại vi khuẩn đi qua, ví dụ trực khuẩn lao khó qua, xoắn trùng giang mai qua rau thai sau tháng thứ 5. Virus qua được rau thai nên thường gây dị dạng cho thai, ví dụ virus cúm, sốt bại liệt, Rubella (bệnh sởi Đức), thủy đậu và virus cự bào (Cytomegalovirus).", "+ Thuốc và hoá chất không có quy luật. Nói chung các chất có trọng lượng phân tử dưới 600 đều qua rau dễ dàng. Ngược lại các chất có trọng lượng phân tử trên 1000 sẽ khó qua rau. Các thuốc qua rau trong 3 tháng đầu thai kỳ có thể gây dị dạng cho thai (chẳng hạn các thuốc chống động kinh, Tetracycline, rượu,... Cho nên khi phụ nữ có thai cần tham khảo kỹ hướng dẫn sử dụng thuốc). Các thuốc qua rau được trong những tháng cuối có thể gây ảnh hưởng độc hại trên bào thai.", "- Kích thích tố loại peptid:", "+ hCG (kích dục tố rau thai - human chorionic gonadotropin): Sự chế tiết hCG  bắt đầu khi có hiện tượng làm tổ, tăng nhanh đạt mức tối đa lúc tuổi thai khoảng hai tháng rưỡi. Nó có tác dụng duy trì hoàng thể và kích thích tiết ra các steroid sinh dục. Người ta sử dụng đặc điểm này để xét nghiệm chẩn đoán thai nghén.", "+ HPL (human placental lactogen): được tiết bởi tế bào nuôi, có tác dụng sinh sữa, biến dưỡng glucid, lipid và protid. Lượng kích thích tố tăng dần theo tuổi thai, tối đa vào tuần 36, sau đó hơi giảm.", "- Các steroide rau thai: Chủ yếu là estrogen và progesteron do bánh rau sản xuất từ tháng thứ 3, tăng cho đến gần ngày đẻ. Ở người mẹ chúng duy trì sự phát triển của tử cung, kiểm soát hoạt động của tử cung trong thai kỳ, kích thích sự phát triển của tuyến vú, duy trì thai nghén và sự phát triển của thai nhi. Người ta đo hàm lượng các chất này để đánh giá chức năng bánh rau.", "- Các steroid khác như 17 ketosteroid, glucocorticoid cũng tăng lên trong thai kỳ."]}, {"heading": "3. DÂY RỐN", "paragraphs": ["Hình 5. Cấu trúc dây rốn và các mạch máu rốn."], "bullets": ["- Dây rốn là 1 dây tròn, dài 40-60cm, đường kính 15 - 20mm, mềm trơn, màu trắng.", "- Một đầu dây rốn bám vào bánh rau, thường bám ở trung tâm bánh rau, đôi khi bám mép bánh rau, một số ít trường hợp bám màng rau. Đầu kia bám vào da bụng thai nhi. Lớp thượng bì của da bụng bao quanh chân dây rốn 1cm, chỗ tiếp giáp giữa thượng bì và dây rốn là chỗ rốn sẽ rụng.", "- Từ ngoài vào trong dây rốn là: nội sản mạc, thạch Wharton, tĩnh mạch rốn và 2 động mạch rốn xoắn quanh tĩnh mạch.", "- Dây rốn không có mạch máu nuôi dưỡng riêng. Sự dinh dưỡng thực hiện nhờ quá trình thẩm thấu.", "- Giữa 2 động mạch có nhánh nối để cân bằng áp lực và lưu lượng cho 2 nửa bánh rau.", "- Các bất thường dây rốn có thể gặp: dây rốn quá dài, dây rốn quá ngắn, rốn quấn cổ, dây rốn thắt nút, xoắn... gây nên một sự chèn ép tuần hoàn đưa đến suy thai. Nếu thai nhi chỉ có 1 động mạch rốn thường kèm theo các dị tật khác của thai nhi.", "- Người ta có thể lấy máu ở dây rốn để xét nghiệm khi có chỉ định."]}, {"heading": "4.1. Tính chất", "paragraphs": ["Nước ối của thai nhi đủ tháng lờ lờ trắng, pH 7,1-7,3. Nước ối cũng chứa các tế bào thượng bì, lông, các chất bã, nước tiểu và dịch từ phổi thai nhi..", "Thành phần 97% là nước, còn lại là các loại khoáng chất và các chất hữu cơ. Các điện giải chính là Na+, K+, Cl-, ngoài ra còn có P3+, Ca2+, Mg2+. Các chất hữu cơ gồm protein, các hợp chất chứa Nitơ không phải protein, glucide, lipide, các hormon và các sắc tố.", "Khối lượng 500 -1000 ml. Thể tích nước ối tăng cho tới tuần thứ 38, sau đó giảm dần."], "bullets": []}, {"heading": "4.2. Tái tạo", "paragraphs": ["Nước ối luôn đổi mới 3 giờ / 1 lần.", "Nguồn gốc"], "bullets": ["+ Do thai bài tiết: từ da thai nhi, từ khí - phế quản, đặc biệt nguồn nước ối quan trọng nhất từ thai nhi là đường tiết niệu. Vì vậy trong trường hợp thiểu ối phải khảo sát xem có bất thường, dị dạng hệ tiết niệu thai nhi không.", "+ Từ máu mẹ.", "+ Từ nội sản mạc.", "- Hấp thu", "+ Chủ yếu do thai nhi uống nước ối. Trong trường hợp có bất thường đường tiêu hóa, có thể biểu hiện đa ối trên lâm sàng.", "+ Nước ối còn được tái hấp thu qua da, dây rốn và màng ối."]}, {"heading": "4.3. Tác dụng", "paragraphs": ["Nước ối có tác dụng"], "bullets": ["- Chống sang chấn cho thai.", "- Giúp bình chỉnh ngôi thai.", "- Cân bằng nội môi cho thai (thai uống và bài tiết qua đường tiểu).", "- Chống lại sự chèn ép của cơ thể thai nhi vào rau và cuống rốn, đặc biệt trong giai đoạn chuyển dạ."]}, {"heading": "4.4. Bệnh lý nước ối", "paragraphs": [], "bullets": ["- Đa ối, quá nhiều nước ối có thể gây đẻ non", "- Thiểu ối, quá ít nước ối. Thường do việc suy giảm chức năng bánh rau, các vấn đề về phổi và thận ở thai nhi. Có nguy cơ giảm ôxy huyết trong quá trình chuyển dạ do dây rốn bị chèn ép.", "- Nhiễm khuẩn ối.", "- Vào tuần lễ thứ 15 - 18 của thai kỳ, người ta có thể chọc hút nước ối để làm một các xét nghiệm thăm dò trong sản khoa khi cần thiết."]}], "raw_text": "TÍNH CHẤT THAI NHI VÀ PHẦN PHỤ ĐỦ THÁNG\nThs. Trần Thị Len\n\nMục tiêu học tập\n1. Mô tả được cấu tạo giải phẫu và chức năng sinh lý của thai nhi đủ tháng.\n2. Trình bày được cấu tạo các phần phụ của thai nhi đủ tháng\n3. Giải thích được chức năng các phần phụ thai nhi đủ tháng.\n\n1. THAI NHI ĐỦ THÁNG\nThai nhi đủ tháng có cấu tạo giải phẫu gần giống người lớn. Thai nhi đủ tháng có trọng lượng trung bình nặng khoảng 3000g, dài 50cm. Tuy vậy khi còn sống trong tử cung hoạt động của bộ máy hô hấp và tuần hoàn của thai nhi khác với trẻ sơ sinh.\n1.1. Giải phẫu\n1.1.1. Đầu: Có hai phần: sọ và mặt. Sọ có 2 vùng là đỉnh sọ và đáy sọ.\n- Đáy sọ: là một phần của các xương trán, xương thái dương, xương chẩm và các xương bướm, xương sàng. Đáy sọ không thể thu hẹp khi đi qua tiểu khung.\n- Đỉnh sọ: gồm hai xương trán, hai xương đỉnh, và một xương chẩm. Giữa các xương là khớp màng mỏng giúp cho xương sọ có thể dịch chuyển và chồng lên nhau. Điều này giúp đỉnh sọ có thể thu hẹp được nhiều khi đầu thai nhi đi qua tiểu khung trong quá trình đẻ, có thể thấy các xương chồng lên nhau ở khớp nối trong và sau khi đẻ.\n- Các đường khớp:\n+ Đường khớp dọc giữa: đi từ thóp trước tới thóp sau giữa 2 xương thái dương và kết thúc tại xương chẩm.\n+ Các đường khớp ngang: Trước là đường khớp nằm giữa các xương trán và xương thái dương. Sau là khớp Lambda nằm giữa các xương thái dương và xương chẩm.\n- Thóp là nơi giao nhau của các đường khớp dọc và đường khớp ngang. Có hai thóp chính:\n+ Thóp trước gọi là thóp lớn (Bregma) được tạo bởi đường khớp dọc giữa với đường khớp trán - đỉnh. Thóp trước có hình tứ giác và kích thước từ 2 x 3 cm tới 4 x 6 cm.\n+ Thóp sau gọi là thóp nhỏ (Lambda) được tạo bởi 3 đường khớp: 2 đường đỉnh - chẩm và phần cuối của đường khớp dọc giữa. Thóp sau có hình tam giác và nhỏ hơn.\n\n\n\n\nHình 1. Thóp trước và thóp sau\n\nBình thường các thóp mềm. Trong trường hợp não úng thủy thì các thóp căng phồng, đường khớp giãn rộng hơn 1 cm.\nCần nắm vững đặc điểm của thóp trước, thóp sau, vị trí của các khớp nối để xác định ngôi, thế và kiểu thế, và để phát hiện các bất thường của ngôi và thai.\n- Các đường kính của đầu: đầu có 3 đường kính trước - sau quan trọng như sau:\n+ Hạ chẩm - thóp trước: 9,5cm đi từ hạ chẩm đến thóp trước. Đây là đường kính lọt của ngôi chỏm đầu cúi tốt (đường kính nhỏ nhất).\n+ Chẩm - trán: 11, 5 cm, đi từ phần trên xương chẩm đến xương trán, đây là đường kính trong trường hợp ngôi chỏm đầu không cúi, không ngửa.\n+ Chẩm - cằm: 13 cm nằm giữa phần trên xương chẩm và xương cằm, gặp trong ngôi thóp trước.\n- Đường kính trên dưới: có 1 đường kính.\n+ Đường kính hạ cằm - thóp trước 9,5cm, đi từ hạ cằm đến thóp trước, gặp trong ngôi mặt.\n- Các đường kính ngang: có 2 đường kính.\n+ Lưỡng đỉnh 9, 5 cm.\n+ Lưỡng thái dương 8cm.\n- Vòng đầu: có 2 vòng.\n+ Vòng đầu to đi qua đường kính thượng chẩm - cằm, có chu vi 38cm.\n+ Vòng đầu nhỏ đi qua đường kính hạ chẩm - thóp trước, có chu vi 33cm.\n\n\n\n\nHình 2. Các đường kính của đầu.\n1.1.2. Cổ và thân\n- Cổ giúp cho đầu quay 1800, thực hiện các động tác khác dễ dàng. Nó chịu được một lực kéo dưới 50kg.\n- Thân thai nhi có một số đường kính:\n+ Đường kính lưỡng mỏm vai: 12 cm, có thể thu hẹp còn 9 cm.\n+ Đường kính lưỡng ụ đùi: 9 cm.\n+ Đường kính cùng chày: 11 cm, có thể thu lại 9 cm.\n1.2. Sinh lý\nKhi còn trong tử cung thai sống nhờ mẹ qua hệ tuần hoàn tử cung - rau.\n1.2.1. Hệ tuần hoàn\n- Tim của thai nhi có 4 buồng: 2 tâm thất và 2 nhĩ. 2 tâm nhĩ thông nhau qua lỗ Botal.\n- Động mạch chủ và động mạch phổi thông nhau qua ống động mạch.\n- Từ động mạch hạ vị của thai có 2 động mạch rốn đưa máu trở lại bánh rau.\n\nHình 3. Tuần hoàn thai nhi\nSự lưu thông của máu thai nhi diễn ra như sau:\n- Máu sau khi trao đổi chất và ôxy từ bánh rau đến thai bằng tĩnh mạch rốn, đến tĩnh mạch chủ dưới nó sẽ pha với máu từ phần dưới cơ thể của thai nhi để đổ vào tĩnh mạch chủ. Máu đến tâm nhĩ phải một phần xuống thất phải để vào động mạch phổi, một phần qua lỗ Botal vào nhĩ trái. Theo cách này, máu giàu ô xy từ bánh rau có thể tới thẳng não của thai nhi. Phổi chưa làm việc nên hầu hết máu từ động mạch phổi sang động mạch chủ nhờ ống động mạch. Động mạch chủ đồng thời nhận máu từ thất trái đi nuôi cơ thể, một phần qua hai động mạch rốn trở về rau thai. Như vậy máu thai nhi là máu pha trộn. Sau khi trẻ ra đời thì các mạch máu rốn co lại. Hiện tượng thở tạo áp lực âm trong lồng ngực, như vậy sẽ hút thêm máu từ động mạch phổi vào phổi. Với các mao mạch phổi phát triển sẽ làm giảm áp lực mạch ở phổi, do đó máu ngừng đi qua ống động mạch, ống này bít lại trong 12-24 giờ sau đẻ và trở thành một dây chằng. Đôi khi ống này vẫn ở trạng thái mở trong một khoảng thời gian, đặc biệt ở những trẻ đẻ non, do đó sẽ nghe thấy tiếng thổi tim trong trường hợp này. Lỗ Botal là một lỗ van để cho máu đi từ tim phải sang tim trái. Sau khi sinh, áp lực tâm nhĩ trái tăng lên làm cho van bị bít lại. Áp lực này bít van và sau đó trong thời gian 1 tới 3 tháng sẽ hình thành một màng có tác dụng bít van vĩnh viễn. Lúc này trẻ sơ sinh  bắt đầu sống với hệ tuần hoàn vĩnh viễn như người lớn.\n1.2.2. Hệ hô hấp\nKhi còn trong tử cung oxy được cung cấp cho thai qua bánh rau. Khí CO2 từ thai nhi đến gai rau thải vào hố huyết trở về máu mẹ. Máu từ tĩnh mạch rốn đến thai chứa nhiều khí O2. Sự trao đổi khí O2, CO2 giữa máu mẹ và máu con là một quá trình khuếch tán đơn giản, do sự chênh lệch nồng độ khuếch tán của các chất đó.\n- Độ bão hòa O2 trong máu đến từ bánh rau tới thai nhi là 80-85%. Khi máu từ tim lên não, độ bão hòa là 60%. Hemoglobin ở thai nhi hoàn toàn có đủ khả năng mang ôxy. Thai nhi cũng có nhiều ôxy nhờ có hematocrit cao.\n- Nếu có tình trạng thiếu khí O2 sẽ xảy ra tình trạng toan hô hấp do thừa CO2 và toan chuyển hóa do thừa acid lactic. Tình trạng trung tâm hóa tuần hoàn thai nhi xảy ra để tập trung máu cho các cơ quan quan trọng như não, tim. Do thiếu oxy nhu động ruột tăng nên sẽ tống phân su vào nước ối. Đây có thể là một dấu hiệu của suy thai.\n1.2.3. Tiêu hóa\nThai nhận chất dinh dưỡng từ mẹ qua bánh rau. Thai nhi bắt đầu nuốt nước ối vào tuần 8-11. Nước ối chứa các tế bào thượng bì, lông, dịch từ phổi thai nhi. Thai nhi tiêu hóa những thành phần này và tạo ra phân su. Phân su là một chất dịch sánh đặc, màu xanh đen với thành phần là chất nhầy, tế bào bong niêm mạc đường tiêu hóa, men ruột, mật và ít nước ối. Ruột thai nhi không có vi khuẩn cho tới khi sinh.\n1.2.4. Bài tiết\n- Da bài tiết các chất nhờn và bã vào tháng thứ  5. Quá trình này tạo chất gây nhằm bảo vệ da.\n- Thận bắt đầu tiết nước tiểu khi thai mới được 11 tuần tuổi: người ta thấy trong nước ối có một phần nước tiểu thai nhi, trẻ mới sinh ra đã có nước tiểu trong bàng quang. Một vài trường hợp bệnh lý về thận của thai nhi khiến lượng nước tiểu giảm có thể làm giảm lượng nước ối. Đó là một trong những nguyên nhân gây thiểu ối (oligohydramnios).\n1.2.5. Hệ thống nội tiết\nTinh hoàn bắt đầu sản xuất testosterone từ tuần thứ 7 của quá trình thai nghén. Tuyến thượng thận và tụy - từ tuần thứ 12, tuyến giáp và tuyến yên - từ tuần 20. Buồng trứng không tiết estrogene hoặc progesterone cho tới thời điểm dậy thì.\nPhần lớn hệ thống nội tiết của thai nhi hoạt động từ rất sớm và hình thành đơn vị nội tiết  rau - thai.\n\n\n2. CÁC PHẦN PHỤ ĐỦ THÁNG\nCác phần phụ đủ tháng của thai bao gồm các màng thai, bánh rau, dây rốn và nước ối.\n2.1. Màng thai\n2.1.1. Màng rụng (ngoại sản mạc)\nMàng rụng là màng chức năng của nội mạc tử cung ở phụ nữ có thai, còn được gọi là ngoại sản mạc. Màng rụng có 3 lớp:\n- Màng rụng nền (Decidua basalis): nằm dưới phôi bào,còn được gọi là ngoại sản mạc tử cung rau.\n- Màng rụng trứng (Decidua capsularis): bao phủ phôi bào, còn được gọi là ngoại sản mạc trứng\n- Màng rụng thành tử cung (Decidua parietalis) bao phủ phần còn lại của buồng tử cung, còn được gọi là ngoại sản mạc tử cung.\n- Khi thai đủ tháng, màng rụng trứng và màng rụng tử cung teo mỏng, dính sát vào nhau.\n2.1.2. Màng đệm (trung sản mạc)\nMàng đệm còn gọi là trung sản mạc, phát triển không đều. Phần bám vào màng rụng nền phát triển mạnh tạo thành các gai rau, phần còn lại của màng đệm sẽ trở thành một màng mỏng ít thấm nước.\n2.1.3. Màng ối (nội sản mạc)\nMàng ối, còn gọi là nội sản mạc, là một màng mỏng lót mặt trong buồng ối; che phủ mặt trong bánh rau, dây rốn. Màng ối dai và dễ thấm nước. Màng này có nhiệm vụ sản xuất, tiêu thụ nước ối, ngăn cản vi khuẩn để bảo vệ cho thai.\nMàng ối nằm trong sát với thai nhi và màng đệm nằm ngoài. Trong trường hợp sinh đôi 2 noãn luôn có 2 màng ối và 2 màng đệm. Trong trường hợp sinh đôi 1 noãn sẽ có thể có 2 màng ối và 2 màng đệm nếu sự phân chia xuất hiện sớm. Nếu việc này xảy ra muộn có thể có 1 màng đệm và 2 màng ối, đây là trường hợp phổ biến nhất. Hiếm hơn, khi sự phân chia xảy ra muộn chỉ tạo ra một màng đệm và một màng ối, trường hợp này sẽ nguy hiểm hơn cho cặp song sinh.\nBề dày của màng rau thai lúc 12 tuần là 0,052mm, khi đủ tháng là 0,002mm.\n2.2. Bánh rau\n2.2.1. Cấu tạo\nBánh rau hình tròn, đường kính khoảng 15 cm, nặng 1/6 trọng lượng thai nhi (khoảng 400 - 500 gram), dày 2,5 - 3 cm, mỏng hơn ở ngoại vi. Mỗi bánh rau gồm 15 - 20 múi, giữa các múi là các rãnh nhỏ. Bánh rau thường bám vào đáy tử cung. Bánh rau hình thành do sự phát triển của màng rụng nền và màng đệm.\nMàng rụng ở vùng bánh rau có 3 lớp: lớp đáy, lớp xốp và lớp đặc. Lớp xốp là đường bong của rau sau khi sinh. Trong lớp đặc có sản bào và hồ huyết. Đại đa phần màng này rụng rau sinh và có chảy máu kèm theo.\n\n\nHình 4. Bánh rau\n2.2.2. Chức năng: Bánh rau có 2 chức năng chính:\nChức năng thứ 1: đảm bảo cho thai sống và phát triển. Sự trao đổi chất thực hiện qua lớp hội bào của gai rau.\n-\tHô hấp: Sự trao đổi O2 và CO2 giữa máu mẹ và thai là một quá trình khuếch tán đơn giản do các đặc điểm sau:\n+ Áp lực máu mẹ ở hồ huyết của bánh rau thấp hơn máu thai và tốc độ chảy chậm.\n+ Nồng độ CO2 thấp hơn và nồng độ O2 trong máu mẹ cao hơn máu thai.\n+ Hemoglobine của thai có khả năng gắn O2 cao.\n+ Diện tích trao đổi mẹ - thai tăng do cấu trúc dạng nhú của gai rau.\nMáu trong hồ huyết phải luôn luôn được đổi mới. Trong các trường hợp mẹ bị cao huyết áp trong thai kỳ hoặc cơn go cường tính máu ở hồ huyết chậm đổi mới sẽ gây suy thai.\n- Dinh dưỡng: Nguyên liệu tạo hình và năng lượng cần cho thai đều đưa từ mẹ vào qua gai rau.\n+ Các protein phải chuyển thành axit amin và đi qua gai rau, sau đó thai mới sử dụng để tổng hợp lại thành protein đặc hiệu của thai.\n+ Các Lipid rất ít đi qua rau thai nên thai thường thiếu các vitamin tan trong dầu như A, D, E, K. Do vậy trẻ sơ sinh hay bị chảy máu do giảm prothrombin và thiếu Vitamin K. Vitamin K sẽ được tổng hợp đầy đủ ở 1 tuần tuổi bởi các vi khuẩn trong ruột của trẻ sơ sinh.\n+ Glucose qua rau thai nhờ hiện tượng khuếch tán, gai rau còn tham gia chuyển glucose thành glycogen và dự trữ ở gai rau.\n+ Vitamin: Vitamin B, C qua rau thai dễ dàng.\nNgoài ra, gai rau còn có thể tổng hợp một số phospholipid, nhất là các steroid rau thai.\n- Bảo vệ:\n+ Một số kháng nguyên kháng thể có nguồn gốc protein có thể đi qua  rau thai. Nhờ đó thai có khả năng miễn dịch thụ động, nhưng cũng có khi nguy hiểm cho thai nếu có sự bất đồng Rh hoặc bất đồng nhóm ABO.\n+ Mầm bệnh: Các vi khuẩn không qua được rau thai. Tuy nhiên vào các tháng cuối có một số loại vi khuẩn đi qua, ví dụ trực khuẩn lao khó qua, xoắn trùng giang mai qua rau thai sau tháng thứ 5. Virus qua được rau thai nên thường gây dị dạng cho thai, ví dụ virus cúm, sốt bại liệt, Rubella (bệnh sởi Đức), thủy đậu và virus cự bào (Cytomegalovirus).\n+ Thuốc và hoá chất không có quy luật. Nói chung các chất có trọng lượng phân tử dưới 600 đều qua rau dễ dàng. Ngược lại các chất có trọng lượng phân tử trên 1000 sẽ khó qua rau. Các thuốc qua rau trong 3 tháng đầu thai kỳ có thể gây dị dạng cho thai (chẳng hạn các thuốc chống động kinh, Tetracycline, rượu,... Cho nên khi phụ nữ có thai cần tham khảo kỹ hướng dẫn sử dụng thuốc). Các thuốc qua rau được trong những tháng cuối có thể gây ảnh hưởng độc hại trên bào thai.\nChức năng thứ 2: giữ vai trò nội tiết để cơ thể mẹ phù hợp với thai nghén.\n- Kích thích tố loại peptid:\n+ hCG (kích dục tố rau thai - human chorionic gonadotropin): Sự chế tiết hCG  bắt đầu khi có hiện tượng làm tổ, tăng nhanh đạt mức tối đa lúc tuổi thai khoảng hai tháng rưỡi. Nó có tác dụng duy trì hoàng thể và kích thích tiết ra các steroid sinh dục. Người ta sử dụng đặc điểm này để xét nghiệm chẩn đoán thai nghén.\n+ HPL (human placental lactogen): được tiết bởi tế bào nuôi, có tác dụng sinh sữa, biến dưỡng glucid, lipid và protid. Lượng kích thích tố tăng dần theo tuổi thai, tối đa vào tuần 36, sau đó hơi giảm.\n- Các steroide rau thai: Chủ yếu là estrogen và progesteron do bánh rau sản xuất từ tháng thứ 3, tăng cho đến gần ngày đẻ. Ở người mẹ chúng duy trì sự phát triển của tử cung, kiểm soát hoạt động của tử cung trong thai kỳ, kích thích sự phát triển của tuyến vú, duy trì thai nghén và sự phát triển của thai nhi. Người ta đo hàm lượng các chất này để đánh giá chức năng bánh rau.\n- Các steroid khác như 17 ketosteroid, glucocorticoid cũng tăng lên trong thai kỳ.\n3. DÂY RỐN\n- Dây rốn là 1 dây tròn, dài 40-60cm, đường kính 15 - 20mm, mềm trơn, màu trắng.\n- Một đầu dây rốn bám vào bánh rau, thường bám ở trung tâm bánh rau, đôi khi bám mép bánh rau, một số ít trường hợp bám màng rau. Đầu kia bám vào da bụng thai nhi. Lớp thượng bì của da bụng bao quanh chân dây rốn 1cm, chỗ tiếp giáp giữa thượng bì và dây rốn là chỗ rốn sẽ rụng.\n- Từ ngoài vào trong dây rốn là: nội sản mạc, thạch Wharton, tĩnh mạch rốn và 2 động mạch rốn xoắn quanh tĩnh mạch.\n- Dây rốn không có mạch máu nuôi dưỡng riêng. Sự dinh dưỡng thực hiện nhờ quá trình thẩm thấu.\n- Giữa 2 động mạch có nhánh nối để cân bằng áp lực và lưu lượng cho 2 nửa bánh rau.\n\nHình 5. Cấu trúc dây rốn và các mạch máu rốn.\n- Các bất thường dây rốn có thể gặp: dây rốn quá dài, dây rốn quá ngắn, rốn quấn cổ, dây rốn thắt nút, xoắn... gây nên một sự chèn ép tuần hoàn đưa đến suy thai. Nếu thai nhi chỉ có 1 động mạch rốn thường kèm theo các dị tật khác của thai nhi.\n- Người ta có thể lấy máu ở dây rốn để xét nghiệm khi có chỉ định.\n4. NƯỚC ỐI\n4.1. Tính chất\nNước ối của thai nhi đủ tháng lờ lờ trắng, pH 7,1-7,3. Nước ối cũng chứa các tế bào thượng bì, lông, các chất bã, nước tiểu và dịch từ phổi thai nhi..\nThành phần 97% là nước, còn lại là các loại khoáng chất và các chất hữu cơ. Các điện giải chính là Na+, K+, Cl-, ngoài ra còn có P3+, Ca2+, Mg2+. Các chất hữu cơ gồm protein, các hợp chất chứa Nitơ không phải protein, glucide, lipide, các hormon và các sắc tố.\nKhối lượng 500 -1000 ml. Thể tích nước ối tăng cho tới tuần thứ 38, sau đó giảm dần.\n4.2. Tái tạo\nNước ối luôn đổi mới 3 giờ / 1 lần.\nNguồn gốc\n+ Do thai bài tiết: từ da thai nhi, từ khí - phế quản, đặc biệt nguồn nước ối quan trọng nhất từ thai nhi là đường tiết niệu. Vì vậy trong trường hợp thiểu ối phải khảo sát xem có bất thường, dị dạng hệ tiết niệu thai nhi không.\n+ Từ máu mẹ.\n+ Từ nội sản mạc.\n- Hấp thu\n+ Chủ yếu do thai nhi uống nước ối. Trong trường hợp có bất thường đường tiêu hóa, có thể biểu hiện đa ối trên lâm sàng.\n+ Nước ối còn được tái hấp thu qua da, dây rốn và màng ối.\n4.3. Tác dụng\nNước ối có tác dụng\n- Chống sang chấn cho thai.\n- Giúp bình chỉnh ngôi thai.\n- Cân bằng nội môi cho thai (thai uống và bài tiết qua đường tiểu).\n- Chống lại sự chèn ép của cơ thể thai nhi vào rau và cuống rốn, đặc biệt trong giai đoạn chuyển dạ.\n4.4. Bệnh lý nước ối\n- Đa ối, quá nhiều nước ối có thể gây đẻ non\n- Thiểu ối, quá ít nước ối. Thường do việc suy giảm chức năng bánh rau, các vấn đề về phổi và thận ở thai nhi. Có nguy cơ giảm ôxy huyết trong quá trình chuyển dạ do dây rốn bị chèn ép.\n- Nhiễm khuẩn ối.\n- Vào tuần lễ thứ 15 - 18 của thai kỳ, người ta có thể chọc hút nước ối để làm một các xét nghiệm thăm dò trong sản khoa khi cần thiết.\nCâu hỏi:\n1. Trình bày cấu tạo giải phẫu của đầu và các đường kính của đầu, thân thai nhi đủ tháng?\n2. Trình bày đặc điểm sinh lý hệ tuần hoàn và hô hấp của thai nhi đủ tháng?\n3. Trình bày cấu tạo giải phẫu và chức năng bánh rau?\n4.  Trình bày cấu tạo giải phẫu và chức năng của dây rốn? đặc điểm giải phẫu và sinh lý của màng nội sản mạc và trung sản mạc?\n5.  Mô tả tính chất và tác dụng sinh lý của nước ối?", "priority": "Trung bình"}, {"id": "SK-05", "chapter": "Chương 1. Sản thường", "folder": "01_San_thuong", "title": "Thay đổi giải phẫu, sinh lý người phụ nữ có thai", "author": "Ths. Trần Thị Len", "word_count": 3438, "line_count": 194, "key_numbers": ["0,5 cm", "0,5kg", "0000 IU", "1,5kg", "10 tuần", "1000g", "10cm", "12kg", "1500 IU", "1cm", "2,5cm", "2000 IU", "250ml", "3 tháng", "32cm", "4cm", "4ml", "5 tháng", "500 IU", "500000 IU", "5000ml", "5kg", "6 tuần", "60g", "7 tuần", "70g", "8cm"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["THAY ĐỔI GIẢI PHẪU, SINH LÝ NGƯỜI PHỤ NỮ CÓ THAI", "Ths.Trần Thị Len"], "bullets": []}, {"heading": "Mục tiêu học tập", "paragraphs": ["Trình bày được sự thay đổi về nội tiết của người phụ nữ trong quá trình mang thai.", "Mô tả được sự thay đổi giải phẫu - sinh lý ở các cơ quan sinh dục.", "Mô tả được sự thay đổi giải phẫu - sinh lý ở các cơ quan khác.", "Tư vấn cho cộng đồng: Những thay đổi bình thường của thai phụ và những yếu tố ảnh hưởng đến sự thay đổi bình thường đó.Ý nghĩa của việc khám thai định kỳ.", "Néi dung"], "bullets": []}, {"heading": "1.  ĐẠI CƯƠNG", "paragraphs": ["Khi có thai, người phụ nữ có những thay đổi rất lớn nhằm phục vụ cho quá trình thai nghén, thay đổi nhiều nhất là ở bộ phận sinh dục và nội tiết thai nghén. Tất cả những thay đổi đó đều do những nguyên nhân thần kinh và nội tiết gây ra."], "bullets": []}, {"heading": "2. THAY ĐỔI NỘI TIẾT", "paragraphs": ["2. 1. HCG (Human Chorionic Gonadotropin)", "2. 1. 1. Phương pháp sinh vật: Dựa vào hiện tượng thay đổi bộ phận sinh dục của các động vật thí nghiệm sau tiêm nước tiểu hoặc huyết thanh của phụ nữ có thai. Hiện nay không còn áp dụng trên lâm sàng", "2. 1. 2. Phương pháp miễn dịch.", "Cơ sở của phản ứng dựa trên hCG có tính kháng nguyên.", "2. 1. 3. Phương pháp phóng xạ miễn dịch RIA :", "Định lượng β hCG : Chính xác nhất nhưng đắt tiền.", "* Thai < 6 tuần          :        500 IU/l", "* Thai 6 - 7 tuần        :       1500 IU/l", "* Thai 7 - 10 tuần      :       10000 - < 500000 IU/l", "→ Khi thai sắp sảy hoặc GEU : 500 - <1500 IU/l", "→ Chửa trứng :                 > 50 0000 IU/l", "→ Khi nồng độ β hCG > 1500 IU/l thì siêu âm đầu dò âm đạo chắc chắn có túi thai trong buồng tử cung. Vậy khi nồng độ  β hCG > 1500 IU/l mà siêu âm đầu dò âm đạo chưa có túi thai trong buồng tử cung cần nghi ngờ chửa ngoài tử cung. Tương tự, khi nồng độ β hCG > 2000 IU/l thì siêu âm đầu dò bụng chắc chắn có túi thai trong buồng tử cung.", "2. 2. Các hormone Steroid :", "Khi có thai hormone Steroid được tăng rất nhiều chủ yếu là Progesteron và Estrogen. Nó được nhiều cơ quan sản xuất ra như :", "Lúc này rau thai trực tiếp sản xuất ra Estrogen và Progesteron cho đến cuối thời kỳ thai nghén.", "2. 3. Các tuyến nội tiết khác :"], "bullets": ["- HCG do tế bào langhans của rau thai sản xuất ra, được sản xuất rất sớm sau hai tuần lễ khi noãn được thụ tinh.", "- HCG cực đại vào tuần thứ 8 (lên tới 7000- 10000 đơn vị ếch) giám dần đến cuối tháng thứ 3(còn 1000 đơn vị ếch) và tiếp tục giảm cho đến khi chuyển dạ.", "- HCG có tác dụng kích thích hoàng thể của buồng trứng tiếp tục phát triển tiết ra Progesteron và một số nội tiết khác biến hoàng kinh nguyệt thành hoàng thể thai nghén, duy trì sự tồn tại của thai trong tử cung trong nửa đầu của thai kỳ.", "- Muốn phát hiện hCG có thể dùng nhiều phương pháp, có hai phương pháp chính là: Phương pháp sinh vật và phương pháp miễn dịch.", "- Dùng   β hCG có tác dụng để theo dõi thai nghén rất tốt, đặc biệt trong những trường hợp theo dõi GEU, theo dõi sau nạo thai trứng.", "- Kết quả :", "+ Vỏ thượng thận : Các Steroid chuyển hóa đường tăng cao.", "+ Buồng trứng : Khi có thai hoàng thể tiếp tục tồn tại và chế tiết cho đến hết tháng thứ 3 để sản xuất ra Progesteron và Estrogen.", "- Dưới tác dụng của hCG do rau thai tiết ra sự hoạt động của hoàng thể thai nghén được duy trì.", "+ Bánh rau : Từ tháng thứ 4 trở đi, bánh rau thay thế hoàng thể thai nghén khi hoàng thể thai nghén teo đi.", "+ Thai nhi cũng đưa vào máu mẹ một lượng lớn estriol.", "+ Tuyến yên :", "- Khi có thai tuyến yên to lên ≈ 35% so với khi không có thai, xuất hiện một số tế bào lạ mà ngoài thời kỳ thai nghén không có, có lẽ nó sản xuất ra prolactin có tác dụng khích thích sự bài tiết sữa.", "- Trong 5 tháng đầu của thời kỳ thai nghén do Estrogen và Progesteron ức chế prolactin nên không có hiện tượng tiết sữa.", "- Từ > 5 tháng của thời kỳ thai nghén do prolactin bị thoát ức chế nên có hiện tượng tiết sữa.", "- Sau đẻ nồng độ Progesteron, Estrogen giảm đột ngột, Prolactin tăng cao trong máu nên có hiện tượng bài tiết sữa.", "+ Tuyến giáp trạng : Phì đại, chuyển hóa cơ bản tăng.", "+ Tuyến cận giáp trạng : Thường ở tình trạng thiểu năng nên sự hấp thụ canxi kém, vì vậy một số trường hợp thai phụ có thể bị Tetani, sâu răng.", "+ Vỏ thượng thận : Phì đại. Các Steroid chuyển hóa đường và muối khoáng tăng lên trong khi có thai nên có hiện tượng tăng giữ nước trong cơ thể."]}, {"heading": "3. THAY ĐỔI GIẢI PHẪU VÀ SINH LÝ Ở BỘ PHẬN SINH DỤC :", "paragraphs": ["3. 1. Thay đổi ở tử cung :", "3. 1. 1. Thay đổi ở thân tử cung :", "3. 1. 1. 1. Trọng lượng :", "Sự gia tăng này không đều, chủ yếu tăng nhiều vào nửa đầu của thời kỳ thai nghén.", "3. 1. 1. 2. Hình thể :", "3. 1. 1. 3. Vị trí :", "Dựa vào tính chất này người ta có thể tính được tuổi thai theo công thức :", "Cao tử cung", "Tuổi thai   =         ─----------------       + 1", "4", "3. 1. 1. 4. Cấu tạo :", "* Khi chưa có thai dày 1cm, khi thai tháng thứ 4, 5 dày tới 2,5cm và đến cuối thời kỳ thai nghén giảm dần xuống còn 0,5 cm.", "* Khi có thai cơ tử cung tăng phát triển, gồm 3 lớp :", "Trong lớp cơ đan có các mạng lưới mạch máu sau khi sổ rau lớp cơ này co chặt lại để tạo thành khối cầu an toàn của tử cung giúp cầm máu sinh lý.", "Khi có thai lớp niêm mạc tử cung biến đổi thành ngoại sản mạc.", "3. 1. 1. 5. Dung tích tử cung :", "Cuối thời kỳ thai nghén có thể lên tới 32cm.", "3. 1. 1. 6. Thay đổi về sinh lý :", "* Tính chất này giúp cho ngôi thai bình chỉnh, khi chuyển dạ giúp xóa mở cổ tử cung, thành lập đầu ối và cho ngôi thai lọt, xuống, quay, sổ.", "* Co bóp tử cung giúp cho rau thai bong, sổ. Giúp tống sản dịch vầ sự thu hồi tử cung về giải phẫu bình thường thời kỳ hậu sản.", "3. 1. 2. Thay đổi ở eo tử cung", "3. 1. 3. Thay đổi ở cổ tử cung", "Lỗ ngoài cổ tử cung nhỏ trước khi sinh đẻ và hình mõm mè khi đẻ.", "3. 1. 4. Thay đổi ở âm hộ, âm đạo", "→ Âm đạo dài ra dễ giãn rộng.", "3. 1. 5. Thay đổi ở buồng trứng", "3. 1. 6. Thay đổi ở vòi trứng", "Trong khi có thai vòi trứng không làm nhiệm vụ gì nhưng to và dài ra. Niêm mạc vòi trứng cũng biến thành màng rụng."], "bullets": ["+ Khi cưa có thai trọng lượng của tử cung từ 50 - 60g", "+ Cuối thời kỳ thai nghén, tử cung trọng lượng trung bình 1000g.", "+ 3 tháng đầu tử cung hình cầu do đường kính trước sau phát triển nhanh hơn đường kính ngang. Phần dưới phình to lên có thể sờ thấy qua túi cùng bên âm đạo, đó là dấu hiệu Noble.", "+ 3 tháng giữa tử cung hình trứng, cực nhỏ ở dưới, cực to ở trên.", "+ 3 tháng cuối tử cung có hình dạng phụ thuộc vào tư thế của thai nhi trong buồng tử cung.", "- Hình trứng : Thai nhi nằm dọc.", "- Hình bè ngang : Thai nhi nằm ngang.", "- Hình trái tim : Tử cung hai sừng.", "+ Khi chưa có thai tử cung nằm trong tiểu khung.", "+ Khi có thai, từ tháng thứ hai trở đi mỗi tháng tử cung lớn lên, phát triển vào ổ bụng và trên khớp mu trung bình 4cm.", "+ Tư thế tử cung thường bị lệch sang phải, hơi bị vặn nghiêng.", "+ Thân tử cung có 3 lớp : Phúc mạc, cơ, niêm mạc.", "- Phúc mạc ở thân tử cung dính chặt vào lớp cơ. Khi có thai phúc mạc phì đại và giãn ra theo lớp cơ tử cung.", "- Phúc mạc ở eo tử cung lỏng lẻo, dẽ bóc tách. Ranh giới giữa thân và eo tử cung là đường phúc mạc bám chặt.", "- Lớp cơ tử cung chủ yếu là cơ trơn.", "+ Cơ đan : ở giữa.", "+ Cơ dọc : ở ngoài.", "+ Cơ vòng : ở trong.", "- Lớp niêm mạc tử cung :", "+ Bình thường buồng tử cung có thể tích ≈ 2 - 4ml.", "+ Khi có thai thể tích : 4000 - 5000ml và tăng lên nhiều hơn nữa trong đa ối, đa thai.", "+ Buồng tử cung khi chưa có thai đo được từ 6 - 8cm.", "+ Mật độ :  - Khi chưa có thai : Hơi chắc, có tính đàn hồi.", "- Khi có thai : Mềm, nắn dễ lún do ảnh hưởng của nội tiết thai nghén có tác dụng giữ nước.", "+ Khả năng co bóp và co rút : Là tính chất đặc thù của tử cung có thai, giúp chẩn đoán thai nghén.", "+ Khả năng co bóp : Cơn co tử cung.", "+ Khả năng co rút : giúp tử cung thành lập khối cầu an toàn sau đẻ gây tắc mạch sinh lý, tránh hiện tượng băng huyết sau đẻ.", "+ Bình thường eo tử cung dài 0,5 - 1cm, nằm giữa thân tử cung và cổ tử cung.", "- Biểu mô mang tính chất trung gian giữa thân và cổ tử cung. Cấu tạo gồm 2 lớp cơ : Cơ vòng và cơ dọc, không có lớp cơ đan.", "+ Khi có thai eo tử cung giãn rộng dần, dài và mỏng ra tạo thành đoạn dưới tử cung. Đến khi chuyển dạ dài khoảng 10cm.", "- Ở người con so, đoạn dưới được thành lập từ đầu tháng thứ 9, còn ở người con dạ đoạn dưới chỉ được thành lập khi chuyển dạ đẻ.", "- Đoạn dưới được hình thành dần dần trong suốt thời kỳ thai nghén nhưng hoàn toàn hình thành khi có sự chuyển dạ nhờ sự co bóp của tử cung.", "- Phúc mạc ở eo tử cung rất dễ bóc tách khỏi lớp cơ tư cung.", "- Khi có thai do ảnh hưởng của nội tiết thai nghén nên eo tử cung cũng mềm khi đó có thể không nắn thấy và khối thân tử cung như rời tách rời khỏi cổ tử cung thành hai phần riêng biệt. Đó là dấu hiệu Hegar.", "+ Bình thường cổ tử cung dài 2,5cm, cấu tạo chủ yếu là tổ chức xơ, tổ chức liên kết.", "+ Khi có thai cổ tử cung mềm dần, từ ngoài vào trong to lên, màu tím hơn lúc trước có thai. Các ống tuyến cổ tử cung chế tiết ít hoặc ngừng chế tiết. Chất nhầy cổ tử cung đục và đặc quánh lại tạo thành nút nhầy cổ tử cung, khi chuyển dạ đẻ cổ tử cung xóa mở tống nút nhầy cổ tử cung ra → đó là một trong những triệu chứng giúp chẩn đoán chuyển dạ đẻ.", "+ Khi có thai các lớp biểu mô của âm đạo không phát triển, không trưởng thành để tạo thành những lớp tế bào bề mặt, các tế bào nhân đông.", "+ Niêm mạc âm đạo dày lên và có màu tím.", "+ Âm hộ mềm và có màu tím do các mạch máu cương tụ dưới lớp biểu mô.", "+ Thành âm đạo dày lên, tổ chức liên kết lỏng lẻo, cơ trơn phì đại.", "+ Khi có thai khí hư âm đạo tăng, trắng, đục, chỉ số tế bào nhân đông rất thấp. Độ PH âm đạo axít hơn nên mầm bệnh ít hoặc không sinh sôi nẩy nở được. Phụ nữ có thai dễ bị nhiễm nấm.", "+ Ba tháng đầu hoàng thể kinh nguyệt tiếp tục phát triển thành hoàng thể thai nghén, các nang noãn không chín nên không có hiện tượng phóng noãn → không có kinh nguyệt.", "+ Từ tháng thứ 4 trở đi hoàng thể thai nghén teo đi. Buồng trứng cũng to lên phù xung huyết trong khi có thai."]}, {"heading": "4. THAY ĐỔI GIẢI PHẪU SINH LÝ Ở CÁC BỘ PHẬN KHÁC", "paragraphs": ["4. 1. Thay đổi ở da, cân, cơ:", "4. 2. Thay đổi ở vú.", "4. 3. Thay đổi hệ thống tuần hoàn:", "4. 3. 1. Thay đổi về tim", "4. 3. 2. Thay đổi về máu", "4. 3. 3. Thay đổi mạch máu", "Do thai to đè vào tĩnh mạch chủ dưới và các tĩnh mạch tiểu khung nên có thể ứ huyết chi dưới → huyết áp tĩnh mạch chi dưới tăng.", "Các mạch máu mềm, dài và to ra, dễ giãn → huyết áp động mạch không tăng.", "4. 4. Thay đổi về hô hấp", "4. 5. Thay đổi về hệ tiết niệu", "Tốc độ lọc cầu thận tăng, đài bể thận và niệu quản thường giãn to và giảm nhu động.", "4. 6. Thay đổi về tiêu hóa", "4. 7. Thay đổi hệ thống xương, khớp", "4. 8. Thay đổi về thần kinh", "Khi có thai, người phụ nữ có những thay đổi về cảm xúc, tâm lý:", "4. 9. Thay đổi toàn thân"], "bullets": ["+ Ở mặt xuất hiện các vết rám tập trung ở gò má, tạo cho người phụ nữ có bộ mặt đặc biệt gọi là gương mặt thai nghén.", "+ Ở thành bụng vết rám tập trung ở đường trắng giữa bụng gọi là đường nâu thành bụng và bị giãn nở nên bị rạn da.", "+ Ở người con so vết rạn màu hồng hoặc nâu, con rạ vết rạn có màu hồng hoặc trắng, các cơ thành bụng cũng bị giãn ra.", "+ Vú to và căng lên do tuyến sữa và ống dẫn sữa phát triển.", "+ Quầng vú sẫm màu và rộng ra.", "+ Núm vú to lên màu sẫm lại và dài ra dễ cương cứng.", "+ Các tĩnh mạch to và nổi rõ, nhìn thấy ở dưới da gọi là lưới tĩnh mạch Haller.", "+ Hạt Montgomery nổi rõ.", "+ Có thể ra sữa khi nắn vào những tháng cuối.", "+ Khi có thai cung lượng tim tăng lên 50%, cao nhất vào tháng thứ 7 sau đó giảm dần tới khi đẻ.", "+ Tim nằm ngang và quay ra trước do cơ hoành bị đẩy lên cao.", "+ Nhịp tim tăng từ 10 - 15 nhịp/ phút.", "+ Tiếng tim tăng cường độ T1 vào tuần lễ 12 - 32, sau đó giảm dần. Có thể có tiếng thổi tâm thu cơ năng do độ nhớt của máu giảm.", "+ Khi có thai khối lượng máu tăng 50%. Tăng theo tuổi thai và cao nhất vào tháng thứ 7.", "+ Huyết tương tăng nhiều hơn huyết cầu nên hồng cầu, tỷ lệ huyết sắc tố và hematocrit đều giảm. Máu loãng làm cho thiếu máu nhược sắc và giảm áp lực thẩm thấu.", "+ Máu: Hematocrit giảm, số lượng hồng cầu dưới 4 triệu/mm3; bạch cầu: 8000 - 16000/ mm3. công thức bạch cầu bình thường; số lượng tiểu cầu bình thường; Protit 60 - 70g/l; thời gian máu chảy, máu đông bình thường; tỷ lệ Prothrombin bình thường.", "+ Tăng tần số thở, thở nhanh nông. Có thở khó, thở nhanh ở những trường hợp đa ối, chửa đa thai.", "+ Mức tiêu thụ oxy ở phụ nữ có thai tăng lên 15% và giảm áp lực riêng phần khí CO2.", "+ Khi có thai máu qua thận tăng từ 200 lên 250ml/ phút.", "+ Niệu quản bị dài ra và cong queo, giảm trương lực.", "+ Bàng quang trong những tháng đầu có thể bị kích thích gây đái rắt. Có thể bí đái do tử cung chèn ép.", "+ Bình thường không có Protein niệu.", "+ Ba tháng đầu có biểu hiện nghén: Buồn nôn, nôn, tăng tiết nước bọt, thay đổi vị giác và khứu giác. Hết 3 tháng thai phụ trở lại ăn uống bình thường.", "+ Dạ dày đôi khi có đau và cảm giác rát bỏng.", "+ Ruột thừa bị đẩy lên cao hoặc sang bên nên khi bị viêm ruột thừa rất khó chẩn đoán.", "+ Ruột non và đại tràng giảm nhu động do bị chèn ép nên hay gây ra táo bón.", "+ Có thể bị trĩ do táo bón và tăng áp lực tĩnh mạch chi dưới.", "+ Chức năng gan, mật ít khi thay đổi khi có thai.", "+ Các xương bị ngấm nước và mềm so với trước. Do hấp thụ canxi kém, mặt khác số canxi lại được huy động cho thai nhi nên thai phụ dễ bị loãng xương, sâu răng, dễ gãy xương.", "+ Các khớp mềm và giãn ra, các dây chằng bị ngấm nước lên cũng mềm ra.", "- Dễ cáu gắt, tính tình dễ thay đổi, trí nhớ bị giảm sút", "- Tuy nhiên những thay đổi về thần kinh đều có liên quan mật thiết với những thay đổi về nội tiết.", "+ Trọng lượng cơ thể: Trong quá trình thai nghén, trọng lượng cơ thể người phụ nữ tăng trung bình 9 - 12kg. Sự tăng trọng lượng cơ thể không đều:", "- 3 tháng đầu tăng ít: tăng không quá 1,5kg", "- 3 tháng giữa tăng trung bình mỗi tuần 0,5kg", "- 3 tháng cuối tăng 4 - 5kg", "+ Phù: Thường phù nhẹ 2 chi dưới do chèn ép, với đặc điểm:", "- Phù hai chi dưới, phù trắng, mềm, ấn lõm, khi nghỉ ngơi giảm phù.", "- Không có các triệu chứng khác kèm theo như huyết áp bình thường, không có Protein niệu", "+ Thay đổi về chuyển hóa:", "- Tăng chuyển hóa.", "- Nhiệt độ tăng cao trong ba tháng đầu do tác dụng của hoàng thẻ thai nghén. Từ tháng thứ 4 trở đi thân nhiệt trở lại bình thường.", "- Dự trữ kiềm giảm do tăng chuyển hóa.", "- Mạch tăng nhẹ.", "- PH máu hơi cao = 7,6.", "- Nước tiểu có tỷ trọng thấp, các ion và ure trong nước tiểu không thay đổi.", "- Giảm hấp thụ canxi, sắt máu giảm."]}, {"heading": "5. CÔNG TÁC TƯ VẤN", "paragraphs": [], "bullets": ["- Khi có thai người phụ nữ có những thay đổi rất lớn, toàn thân tham gia vào thai nghén. Nếu người phụ nữ bị một bệnh dù là gì đi chăng nữa cũng ảnh hưởng đến thay đổi bình thường, dẫn đến những thay đổi bất thường. Vì vậy trước khi mang thai nên trị bệnh nếu có. Khi có thai nếu bị bệnh phải điều trị đúng ở cơ sở y tế.", "- Tuyên truyền cho cộng đồng những dấu hiệu thay đổi bình thường khi có thai và những dấu hiệu bất thường khi có thai như nôn nhiều, ra máu bất thường 3 tháng đầu; ra máu tự nhiên 3 tháng cuối, phù, tăng cân nhanh, bụng to quá nhanh, bụng không to lên hoặc nhỏ đi...thì phải đến cơ sở y tế khám ngay."]}, {"heading": "Câu hỏi:", "paragraphs": ["1: Trình bày sự thay đổi về nội tiết và các tuyến nội tiết ở phụ nữ khi có thai?", "2: Trình bày sự thay đổi về giải phẫu ở bộ phận sinh dục người phụ nữ khi có thai?", "3: Trình bày sự thay đổi về tuần hoàn, hô hấp, hệ thống tiêu hoá của người mẹ khi có thai?", "4: Trình bày sự thay đổi về tuần hoàn, tiết niệu, xương khớp của người mẹ khi có thai?"], "bullets": []}], "raw_text": "THAY ĐỔI GIẢI PHẪU, SINH LÝ NGƯỜI PHỤ NỮ CÓ THAI\n\nThs.Trần Thị Len\nMục tiêu học tập\n\nTrình bày được sự thay đổi về nội tiết của người phụ nữ trong quá trình mang thai.\nMô tả được sự thay đổi giải phẫu - sinh lý ở các cơ quan sinh dục.\nMô tả được sự thay đổi giải phẫu - sinh lý ở các cơ quan khác.\nTư vấn cho cộng đồng: Những thay đổi bình thường của thai phụ và những yếu tố ảnh hưởng đến sự thay đổi bình thường đó.Ý nghĩa của việc khám thai định kỳ.\nNéi dung\n1.  ĐẠI CƯƠNG\nKhi có thai, người phụ nữ có những thay đổi rất lớn nhằm phục vụ cho quá trình thai nghén, thay đổi nhiều nhất là ở bộ phận sinh dục và nội tiết thai nghén. Tất cả những thay đổi đó đều do những nguyên nhân thần kinh và nội tiết gây ra.\n\n2. THAY ĐỔI NỘI TIẾT\n2. 1. HCG (Human Chorionic Gonadotropin)\n- HCG do tế bào langhans của rau thai sản xuất ra, được sản xuất rất sớm sau hai tuần lễ khi noãn được thụ tinh.\n- HCG cực đại vào tuần thứ 8 (lên tới 7000- 10000 đơn vị ếch) giám dần đến cuối tháng thứ 3(còn 1000 đơn vị ếch) và tiếp tục giảm cho đến khi chuyển dạ.\n- HCG có tác dụng kích thích hoàng thể của buồng trứng tiếp tục phát triển tiết ra Progesteron và một số nội tiết khác biến hoàng kinh nguyệt thành hoàng thể thai nghén, duy trì sự tồn tại của thai trong tử cung trong nửa đầu của thai kỳ.\n- Muốn phát hiện hCG có thể dùng nhiều phương pháp, có hai phương pháp chính là: Phương pháp sinh vật và phương pháp miễn dịch.\n2. 1. 1. Phương pháp sinh vật: Dựa vào hiện tượng thay đổi bộ phận sinh dục của các động vật thí nghiệm sau tiêm nước tiểu hoặc huyết thanh của phụ nữ có thai. Hiện nay không còn áp dụng trên lâm sàng\n2. 1. 2. Phương pháp miễn dịch.\nCơ sở của phản ứng dựa trên hCG có tính kháng nguyên.\n2. 1. 3. Phương pháp phóng xạ miễn dịch RIA :\nĐịnh lượng β hCG : Chính xác nhất nhưng đắt tiền.\n- Dùng   β hCG có tác dụng để theo dõi thai nghén rất tốt, đặc biệt trong những trường hợp theo dõi GEU, theo dõi sau nạo thai trứng.\n- Kết quả :\n* Thai < 6 tuần          :        500 IU/l\n* Thai 6 - 7 tuần        :       1500 IU/l\n* Thai 7 - 10 tuần      :       10000 - < 500000 IU/l\n→ Khi thai sắp sảy hoặc GEU : 500 - <1500 IU/l\n→ Chửa trứng :                 > 50 0000 IU/l\n→ Khi nồng độ β hCG > 1500 IU/l thì siêu âm đầu dò âm đạo chắc chắn có túi thai trong buồng tử cung. Vậy khi nồng độ  β hCG > 1500 IU/l mà siêu âm đầu dò âm đạo chưa có túi thai trong buồng tử cung cần nghi ngờ chửa ngoài tử cung. Tương tự, khi nồng độ β hCG > 2000 IU/l thì siêu âm đầu dò bụng chắc chắn có túi thai trong buồng tử cung.\n2. 2. Các hormone Steroid :\nKhi có thai hormone Steroid được tăng rất nhiều chủ yếu là Progesteron và Estrogen. Nó được nhiều cơ quan sản xuất ra như :\n+ Vỏ thượng thận : Các Steroid chuyển hóa đường tăng cao.\n+ Buồng trứng : Khi có thai hoàng thể tiếp tục tồn tại và chế tiết cho đến hết tháng thứ 3 để sản xuất ra Progesteron và Estrogen.\n- Dưới tác dụng của hCG do rau thai tiết ra sự hoạt động của hoàng thể thai nghén được duy trì.\n+ Bánh rau : Từ tháng thứ 4 trở đi, bánh rau thay thế hoàng thể thai nghén khi hoàng thể thai nghén teo đi.\nLúc này rau thai trực tiếp sản xuất ra Estrogen và Progesteron cho đến cuối thời kỳ thai nghén.\n+ Thai nhi cũng đưa vào máu mẹ một lượng lớn estriol.\n2. 3. Các tuyến nội tiết khác :\n+ Tuyến yên :\n- Khi có thai tuyến yên to lên ≈ 35% so với khi không có thai, xuất hiện một số tế bào lạ mà ngoài thời kỳ thai nghén không có, có lẽ nó sản xuất ra prolactin có tác dụng khích thích sự bài tiết sữa.\n- Trong 5 tháng đầu của thời kỳ thai nghén do Estrogen và Progesteron ức chế prolactin nên không có hiện tượng tiết sữa.\n- Từ > 5 tháng của thời kỳ thai nghén do prolactin bị thoát ức chế nên có hiện tượng tiết sữa.\n- Sau đẻ nồng độ Progesteron, Estrogen giảm đột ngột, Prolactin tăng cao trong máu nên có hiện tượng bài tiết sữa.\n+ Tuyến giáp trạng : Phì đại, chuyển hóa cơ bản tăng.\n+ Tuyến cận giáp trạng : Thường ở tình trạng thiểu năng nên sự hấp thụ canxi kém, vì vậy một số trường hợp thai phụ có thể bị Tetani, sâu răng.\n+ Vỏ thượng thận : Phì đại. Các Steroid chuyển hóa đường và muối khoáng tăng lên trong khi có thai nên có hiện tượng tăng giữ nước trong cơ thể.\n\n3. THAY ĐỔI GIẢI PHẪU VÀ SINH LÝ Ở BỘ PHẬN SINH DỤC :\n3. 1. Thay đổi ở tử cung :\n3. 1. 1. Thay đổi ở thân tử cung :\n3. 1. 1. 1. Trọng lượng :\n+ Khi cưa có thai trọng lượng của tử cung từ 50 - 60g\n+ Cuối thời kỳ thai nghén, tử cung trọng lượng trung bình 1000g.\nSự gia tăng này không đều, chủ yếu tăng nhiều vào nửa đầu của thời kỳ thai nghén.\n3. 1. 1. 2. Hình thể :\n+ 3 tháng đầu tử cung hình cầu do đường kính trước sau phát triển nhanh hơn đường kính ngang. Phần dưới phình to lên có thể sờ thấy qua túi cùng bên âm đạo, đó là dấu hiệu Noble.\n+ 3 tháng giữa tử cung hình trứng, cực nhỏ ở dưới, cực to ở trên.\n+ 3 tháng cuối tử cung có hình dạng phụ thuộc vào tư thế của thai nhi trong buồng tử cung.\n- Hình trứng : Thai nhi nằm dọc.\n- Hình bè ngang : Thai nhi nằm ngang.\n- Hình trái tim : Tử cung hai sừng.\n3. 1. 1. 3. Vị trí :\n+ Khi chưa có thai tử cung nằm trong tiểu khung.\n+ Khi có thai, từ tháng thứ hai trở đi mỗi tháng tử cung lớn lên, phát triển vào ổ bụng và trên khớp mu trung bình 4cm.\nDựa vào tính chất này người ta có thể tính được tuổi thai theo công thức :\nCao tử cung\nTuổi thai   =         ─----------------       + 1\n4\n+ Tư thế tử cung thường bị lệch sang phải, hơi bị vặn nghiêng.\n3. 1. 1. 4. Cấu tạo :\n+ Thân tử cung có 3 lớp : Phúc mạc, cơ, niêm mạc.\n- Phúc mạc ở thân tử cung dính chặt vào lớp cơ. Khi có thai phúc mạc phì đại và giãn ra theo lớp cơ tử cung.\n- Phúc mạc ở eo tử cung lỏng lẻo, dẽ bóc tách. Ranh giới giữa thân và eo tử cung là đường phúc mạc bám chặt.\n- Lớp cơ tử cung chủ yếu là cơ trơn.\n* Khi chưa có thai dày 1cm, khi thai tháng thứ 4, 5 dày tới 2,5cm và đến cuối thời kỳ thai nghén giảm dần xuống còn 0,5 cm.\n* Khi có thai cơ tử cung tăng phát triển, gồm 3 lớp :\n+ Cơ đan : ở giữa.\n+ Cơ dọc : ở ngoài.\n+ Cơ vòng : ở trong.\nTrong lớp cơ đan có các mạng lưới mạch máu sau khi sổ rau lớp cơ này co chặt lại để tạo thành khối cầu an toàn của tử cung giúp cầm máu sinh lý.\n- Lớp niêm mạc tử cung :\nKhi có thai lớp niêm mạc tử cung biến đổi thành ngoại sản mạc.\n3. 1. 1. 5. Dung tích tử cung :\n+ Bình thường buồng tử cung có thể tích ≈ 2 - 4ml.\n+ Khi có thai thể tích : 4000 - 5000ml và tăng lên nhiều hơn nữa trong đa ối, đa thai.\n+ Buồng tử cung khi chưa có thai đo được từ 6 - 8cm.\nCuối thời kỳ thai nghén có thể lên tới 32cm.\n3. 1. 1. 6. Thay đổi về sinh lý :\n+ Mật độ :  - Khi chưa có thai : Hơi chắc, có tính đàn hồi.\n- Khi có thai : Mềm, nắn dễ lún do ảnh hưởng của nội tiết thai nghén có tác dụng giữ nước.\n+ Khả năng co bóp và co rút : Là tính chất đặc thù của tử cung có thai, giúp chẩn đoán thai nghén.\n+ Khả năng co bóp : Cơn co tử cung.\n* Tính chất này giúp cho ngôi thai bình chỉnh, khi chuyển dạ giúp xóa mở cổ tử cung, thành lập đầu ối và cho ngôi thai lọt, xuống, quay, sổ.\n* Co bóp tử cung giúp cho rau thai bong, sổ. Giúp tống sản dịch vầ sự thu hồi tử cung về giải phẫu bình thường thời kỳ hậu sản.\n+ Khả năng co rút : giúp tử cung thành lập khối cầu an toàn sau đẻ gây tắc mạch sinh lý, tránh hiện tượng băng huyết sau đẻ.\n3. 1. 2. Thay đổi ở eo tử cung\n+ Bình thường eo tử cung dài 0,5 - 1cm, nằm giữa thân tử cung và cổ tử cung.\n- Biểu mô mang tính chất trung gian giữa thân và cổ tử cung. Cấu tạo gồm 2 lớp cơ : Cơ vòng và cơ dọc, không có lớp cơ đan.\n+ Khi có thai eo tử cung giãn rộng dần, dài và mỏng ra tạo thành đoạn dưới tử cung. Đến khi chuyển dạ dài khoảng 10cm.\n- Ở người con so, đoạn dưới được thành lập từ đầu tháng thứ 9, còn ở người con dạ đoạn dưới chỉ được thành lập khi chuyển dạ đẻ.\n- Đoạn dưới được hình thành dần dần trong suốt thời kỳ thai nghén nhưng hoàn toàn hình thành khi có sự chuyển dạ nhờ sự co bóp của tử cung.\n- Phúc mạc ở eo tử cung rất dễ bóc tách khỏi lớp cơ tư cung.\n- Khi có thai do ảnh hưởng của nội tiết thai nghén nên eo tử cung cũng mềm khi đó có thể không nắn thấy và khối thân tử cung như rời tách rời khỏi cổ tử cung thành hai phần riêng biệt. Đó là dấu hiệu Hegar.\n3. 1. 3. Thay đổi ở cổ tử cung\n+ Bình thường cổ tử cung dài 2,5cm, cấu tạo chủ yếu là tổ chức xơ, tổ chức liên kết.\nLỗ ngoài cổ tử cung nhỏ trước khi sinh đẻ và hình mõm mè khi đẻ.\n+ Khi có thai cổ tử cung mềm dần, từ ngoài vào trong to lên, màu tím hơn lúc trước có thai. Các ống tuyến cổ tử cung chế tiết ít hoặc ngừng chế tiết. Chất nhầy cổ tử cung đục và đặc quánh lại tạo thành nút nhầy cổ tử cung, khi chuyển dạ đẻ cổ tử cung xóa mở tống nút nhầy cổ tử cung ra → đó là một trong những triệu chứng giúp chẩn đoán chuyển dạ đẻ.\n3. 1. 4. Thay đổi ở âm hộ, âm đạo\n+ Khi có thai các lớp biểu mô của âm đạo không phát triển, không trưởng thành để tạo thành những lớp tế bào bề mặt, các tế bào nhân đông.\n+ Niêm mạc âm đạo dày lên và có màu tím.\n+ Âm hộ mềm và có màu tím do các mạch máu cương tụ dưới lớp biểu mô.\n+ Thành âm đạo dày lên, tổ chức liên kết lỏng lẻo, cơ trơn phì đại.\n→ Âm đạo dài ra dễ giãn rộng.\n+ Khi có thai khí hư âm đạo tăng, trắng, đục, chỉ số tế bào nhân đông rất thấp. Độ PH âm đạo axít hơn nên mầm bệnh ít hoặc không sinh sôi nẩy nở được. Phụ nữ có thai dễ bị nhiễm nấm.\n3. 1. 5. Thay đổi ở buồng trứng\n+ Ba tháng đầu hoàng thể kinh nguyệt tiếp tục phát triển thành hoàng thể thai nghén, các nang noãn không chín nên không có hiện tượng phóng noãn → không có kinh nguyệt.\n+ Từ tháng thứ 4 trở đi hoàng thể thai nghén teo đi. Buồng trứng cũng to lên phù xung huyết trong khi có thai.\n3. 1. 6. Thay đổi ở vòi trứng\nTrong khi có thai vòi trứng không làm nhiệm vụ gì nhưng to và dài ra. Niêm mạc vòi trứng cũng biến thành màng rụng.\n4. THAY ĐỔI GIẢI PHẪU SINH LÝ Ở CÁC BỘ PHẬN KHÁC\n4. 1. Thay đổi ở da, cân, cơ:\n+ Ở mặt xuất hiện các vết rám tập trung ở gò má, tạo cho người phụ nữ có bộ mặt đặc biệt gọi là gương mặt thai nghén.\n+ Ở thành bụng vết rám tập trung ở đường trắng giữa bụng gọi là đường nâu thành bụng và bị giãn nở nên bị rạn da.\n+ Ở người con so vết rạn màu hồng hoặc nâu, con rạ vết rạn có màu hồng hoặc trắng, các cơ thành bụng cũng bị giãn ra.\n4. 2. Thay đổi ở vú.\n+ Vú to và căng lên do tuyến sữa và ống dẫn sữa phát triển.\n+ Quầng vú sẫm màu và rộng ra.\n+ Núm vú to lên màu sẫm lại và dài ra dễ cương cứng.\n+ Các tĩnh mạch to và nổi rõ, nhìn thấy ở dưới da gọi là lưới tĩnh mạch Haller.\n+ Hạt Montgomery nổi rõ.\n+ Có thể ra sữa khi nắn vào những tháng cuối.\n4. 3. Thay đổi hệ thống tuần hoàn:\n4. 3. 1. Thay đổi về tim\n+ Khi có thai cung lượng tim tăng lên 50%, cao nhất vào tháng thứ 7 sau đó giảm dần tới khi đẻ.\n+ Tim nằm ngang và quay ra trước do cơ hoành bị đẩy lên cao.\n+ Nhịp tim tăng từ 10 - 15 nhịp/ phút.\n+ Tiếng tim tăng cường độ T1 vào tuần lễ 12 - 32, sau đó giảm dần. Có thể có tiếng thổi tâm thu cơ năng do độ nhớt của máu giảm.\n4. 3. 2. Thay đổi về máu\n+ Khi có thai khối lượng máu tăng 50%. Tăng theo tuổi thai và cao nhất vào tháng thứ 7.\n+ Huyết tương tăng nhiều hơn huyết cầu nên hồng cầu, tỷ lệ huyết sắc tố và hematocrit đều giảm. Máu loãng làm cho thiếu máu nhược sắc và giảm áp lực thẩm thấu.\n+ Máu: Hematocrit giảm, số lượng hồng cầu dưới 4 triệu/mm3; bạch cầu: 8000 - 16000/ mm3. công thức bạch cầu bình thường; số lượng tiểu cầu bình thường; Protit 60 - 70g/l; thời gian máu chảy, máu đông bình thường; tỷ lệ Prothrombin bình thường.\n4. 3. 3. Thay đổi mạch máu\nDo thai to đè vào tĩnh mạch chủ dưới và các tĩnh mạch tiểu khung nên có thể ứ huyết chi dưới → huyết áp tĩnh mạch chi dưới tăng.\nCác mạch máu mềm, dài và to ra, dễ giãn → huyết áp động mạch không tăng.\n4. 4. Thay đổi về hô hấp\n+ Tăng tần số thở, thở nhanh nông. Có thở khó, thở nhanh ở những trường hợp đa ối, chửa đa thai.\n+ Mức tiêu thụ oxy ở phụ nữ có thai tăng lên 15% và giảm áp lực riêng phần khí CO2.\n4. 5. Thay đổi về hệ tiết niệu\n+ Khi có thai máu qua thận tăng từ 200 lên 250ml/ phút.\nTốc độ lọc cầu thận tăng, đài bể thận và niệu quản thường giãn to và giảm nhu động.\n+ Niệu quản bị dài ra và cong queo, giảm trương lực.\n+ Bàng quang trong những tháng đầu có thể bị kích thích gây đái rắt. Có thể bí đái do tử cung chèn ép.\n+ Bình thường không có Protein niệu.\n4. 6. Thay đổi về tiêu hóa\n+ Ba tháng đầu có biểu hiện nghén: Buồn nôn, nôn, tăng tiết nước bọt, thay đổi vị giác và khứu giác. Hết 3 tháng thai phụ trở lại ăn uống bình thường.\n+ Dạ dày đôi khi có đau và cảm giác rát bỏng.\n+ Ruột thừa bị đẩy lên cao hoặc sang bên nên khi bị viêm ruột thừa rất khó chẩn đoán.\n+ Ruột non và đại tràng giảm nhu động do bị chèn ép nên hay gây ra táo bón.\n+ Có thể bị trĩ do táo bón và tăng áp lực tĩnh mạch chi dưới.\n+ Chức năng gan, mật ít khi thay đổi khi có thai.\n4. 7. Thay đổi hệ thống xương, khớp\n+ Các xương bị ngấm nước và mềm so với trước. Do hấp thụ canxi kém, mặt khác số canxi lại được huy động cho thai nhi nên thai phụ dễ bị loãng xương, sâu răng, dễ gãy xương.\n+ Các khớp mềm và giãn ra, các dây chằng bị ngấm nước lên cũng mềm ra.\n4. 8. Thay đổi về thần kinh\nKhi có thai, người phụ nữ có những thay đổi về cảm xúc, tâm lý:\n- Dễ cáu gắt, tính tình dễ thay đổi, trí nhớ bị giảm sút\n- Tuy nhiên những thay đổi về thần kinh đều có liên quan mật thiết với những thay đổi về nội tiết.\n4. 9. Thay đổi toàn thân\n+ Trọng lượng cơ thể: Trong quá trình thai nghén, trọng lượng cơ thể người phụ nữ tăng trung bình 9 - 12kg. Sự tăng trọng lượng cơ thể không đều:\n- 3 tháng đầu tăng ít: tăng không quá 1,5kg\n- 3 tháng giữa tăng trung bình mỗi tuần 0,5kg\n- 3 tháng cuối tăng 4 - 5kg\n+ Phù: Thường phù nhẹ 2 chi dưới do chèn ép, với đặc điểm:\n- Phù hai chi dưới, phù trắng, mềm, ấn lõm, khi nghỉ ngơi giảm phù.\n- Không có các triệu chứng khác kèm theo như huyết áp bình thường, không có Protein niệu\n+ Thay đổi về chuyển hóa:\n- Tăng chuyển hóa.\n- Nhiệt độ tăng cao trong ba tháng đầu do tác dụng của hoàng thẻ thai nghén. Từ tháng thứ 4 trở đi thân nhiệt trở lại bình thường.\n- Dự trữ kiềm giảm do tăng chuyển hóa.\n- Mạch tăng nhẹ.\n- PH máu hơi cao = 7,6.\n- Nước tiểu có tỷ trọng thấp, các ion và ure trong nước tiểu không thay đổi.\n- Giảm hấp thụ canxi, sắt máu giảm.\n5. CÔNG TÁC TƯ VẤN\n- Khi có thai người phụ nữ có những thay đổi rất lớn, toàn thân tham gia vào thai nghén. Nếu người phụ nữ bị một bệnh dù là gì đi chăng nữa cũng ảnh hưởng đến thay đổi bình thường, dẫn đến những thay đổi bất thường. Vì vậy trước khi mang thai nên trị bệnh nếu có. Khi có thai nếu bị bệnh phải điều trị đúng ở cơ sở y tế.\n- Tuyên truyền cho cộng đồng những dấu hiệu thay đổi bình thường khi có thai và những dấu hiệu bất thường khi có thai như nôn nhiều, ra máu bất thường 3 tháng đầu; ra máu tự nhiên 3 tháng cuối, phù, tăng cân nhanh, bụng to quá nhanh, bụng không to lên hoặc nhỏ đi...thì phải đến cơ sở y tế khám ngay.\nCâu hỏi:\n1: Trình bày sự thay đổi về nội tiết và các tuyến nội tiết ở phụ nữ khi có thai?\n2: Trình bày sự thay đổi về giải phẫu ở bộ phận sinh dục người phụ nữ khi có thai?\n3: Trình bày sự thay đổi về tuần hoàn, hô hấp, hệ thống tiêu hoá của người mẹ khi có thai?\n4: Trình bày sự thay đổi về tuần hoàn, tiết niệu, xương khớp của người mẹ khi có thai?", "priority": "Trung bình"}, {"id": "SK-06", "chapter": "Chương 1. Sản thường", "folder": "01_San_thuong", "title": "Chẩn đoán thai nghén", "author": "Ths. Nguyễn Văn Hiền", "word_count": 1132, "line_count": 78, "key_numbers": ["3 tháng", "4,5 tháng", "6 tuần"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["chẩn đoán thai nghén", "Ths. Nguyễn Văn Hiền"], "bullets": []}, {"heading": "I.  mục tiêu :", "paragraphs": ["Sau khi học xong bài này học viên có khả năng :", "Trình bày được triệu chứng lâm sàng, cận lâm sàng của thai nghén 4,5 tháng đầu của thai kỳ.", "Trình bày được những bệnh lý phụ khoa và thai bệnh lý khác dễ nhầm với thai thường 4,5 tháng đầu của thai kỳ.", "Trình bày triệu chứng cơ năng, thực thể thai nghén 4,5 tháng sau của thai kỳ.", "Trình bày nội dung tuyên truyền cho cộng đồng những dấu hiệu có thai, nhằm đăng ký quản lý thai nghén, đề phòng và phát hiện thai nghén nguy cơ cao."], "bullets": []}, {"heading": "II.  néi dung", "paragraphs": ["Đại cương", "Khi có thai người phụ nữ có những thay đổi về giải phẫu và sinh lý rất lớn. Dựa vào đó mà chẩn đoán có thai hay không có thai, thai thường hay thai bệnh lý.", "Lâm sàng chia làm 2 thời kỳ:", "Giai đoạn 4,5 tháng đầu.", "Giai đoạn 4,5 tháng sau.", "Chẩn đoán thai nghén trong thời kỳ 4,5 tháng đầu:", "Chẩn đoán xác định:"], "bullets": []}, {"heading": "2.1.1 Triệu chứng cơ năng:", "paragraphs": ["Tiết nước bọt, buồn nôn, lơm giọng hoặc nôn vào buổi sáng.", "Thay đổi vị giác: Ngán ăn hoặc thích ăn những thức ăn lạ mà từ trước tới nay thích hoặc không thích.", "Thay đổi khứu giác: VD: Sợ mùi thơm, sợ mùi thuốc lá...mà bình thường không sợ.", "Thay đổi về tinh thần: Tính tình thay đổi, đễ cáu gắt, buồn ngủ, mệt mỏi hoặc ngược lại."], "bullets": ["+ Triệu chứng tắt kinh trên một người phụ nữ khỏe mạnh, có kinh nguyệt đều và có quan hệ tình dục. Đây là dấu hiệu đáng tin cậy hay gần như chắc chắn để chẩn đoán.", "+ Triệu chứng thai nghén: Tùy theo từng thai phụ, đó là sự thay đổi của người phụ nữ do tình trạng có thai gây nên."]}, {"heading": "2.1.2 Triệu chứng thực thể:", "paragraphs": ["* Da mặt và da bong: Xuất hiện các vết nâu sạm, ở mặt thường xuất hiện ở 2 gò má, ở đường trắng giữa bong và các vết rạn đối với con so. Còn con rạ có thể thấy các vết rạn màu trắng.", "* Vú phát triển nhanh theo tuổi thai, quầng vú them màu, hạt Montgomery nổi rõ hơn, có thể thấy xuất hiện sũa non.", "* Âm hộ và niêm mạc âm đạo bị tím lại.", "* Tử cung:", "Dấu hiệu Noble (+): Chứng tỏ tử cung to.", "Dấu hiệu Hegar (+): Chứng tỏ tử cung mềm (không nên làm với người giữ thai vì dễ sẩy)."], "bullets": ["+ Cổ tử cung mềm, tím.", "+ Thân tử cung to và có cơn co tử cung: Là dấu hiệu quyết định."]}, {"heading": "2.1.3 Triệu chứng cận lâm sàng:", "paragraphs": ["Phản ứng miễn dịch: Làm các test HCG có kết quả nhanh: HCG vitest", "Quickstick", "Định lượng β HCG.", "Với siêu âm ta có thể thấy:", "Tói èi khi 5 tuÇn tuæi (chËm kinh 1 tuÇn).", "Cấu trúc phôi từ tuần lễ thứ 6 ư 7.", "Tim thai tõ tuÇn lÔ thø 7- 8", "Hoạt động của thai từ tuần lễ thứ 9.", "Trước tuần lễ thứ 12 thì siêu âm có giá trị chẩn đoán tuổi thai chính xác nhất theo công thức:", "Tuæi thai dưới 6 : Dựa vào kích thước túi thai", "Tuæi thai trên 6 tuần : Dựa vào chiều dài phôi", "Sau tuần lễ thứ 12, đường kính lưỡng đỉnh của thai nhi là chỉ số chính xác nhất để tính tuổi thai.", "Chẩn đoán phân biệt", "Chẩn đoán thai nghén nói chung không khó nhưng trong những ngày đầu thai nghén cũng cần chẩn đoán phân biệt với những trường hợp sau:", "Thai chÕt l­u", "Chửa ngoài tử cung", "Chửa trứng.", "Chẩn đoán thai nghén 4,5 tháng sau:", "Chẩn đoán thai nghén thời kỳ này thường dễ nhưng tiên lượng cuộc đẻ mới là khó.", "Triệu chứng lâm sàng:"], "bullets": ["+ Tìm HCG trong nước tiểu hoạc trong máu bằng các xét nghiệm:", "+ Siêu âm: Là xét nghiệm hết sức đơn giản, nhanh và cho kết quả chính xác. Siêu âm những tháng đầu có tác dụng chẩn đoán thai sớm, chẩn đoán thai thường hay thai bệnh lý, chẩn đoán tuổi thai chính xác nhất.", "+ Tắt kinh: Phân biệt với những trường hợp mất kinh nhưng không phải có thai, gặp ở một số bệnh: Tâm thàn, rối loạn nội tiết, bệnh nội khoa nặng.", "+ Nghén: Phân biệt với nghén giả: Gặp ở những người mong hoặc sợ có con quá làm cho người phụ nữ có tình trạng nghén thực sự.", "+ Tử cung to cần chẩn đoán phân biệt với: U xơ tử cung, u nang buồng trứng.", "+ Ngoài ra cần chẩn đoán phân biệt với những trường hợp thai nghén bệnh lý thường gặp trong những tháng đầu của thời kỳ thai nghén như:", "+ Tắt kinh kéo dài, tử cung ngày càng to lên rõ rệt so với tuổi thai.", "+ Sờ nắn được các cực của thai nhi.", "+ Nghe được tiếng tim thai.", "+ Các cử động của thai nhi còn gọi là thai máy hay thai đạp."]}, {"heading": "3.2. Triệu chứng cận lâm sàng:", "paragraphs": ["Thường làm siêu âm để:", "Chẩn đoán tuổi thai.", "Đánh giá sự phát triển của thai.", "Phát hiện sớm các dị tật bẩm sinh.", "Điều cơ bản nhất là chẩn đoán được ngôi, thế, kiểu thế để phần nào tiên lượng sớm được cuộc đẻ.", "Mặt khác còn phải khám tìm các dấu hiệu thay đổi bất thường để chẩn đoán thai nghén nguy cơ cao nhằm điều trị sớm tránh tai biến và biến chứng nguy hiểm cho mẹ và con như: Rau tiền đạo, tiền sản giật…", "Công tác tư vấn", "Tuyên truyền cho cộng đồng những dấu hiệu bình thường khi có thai như: Chậm kinh, nghén, vú to và đau, bụng ngày càng to và thấy thai đạp.", "Những dấu hiệu bất thường khi có thai như: Đau bụng, ra máu âm đạo, nghén quá mức, thai không đạp  để đến cơ sở y tế khám ngay nhằm phát hiện thai nghén bất thường, những yếu tố nguy cơ cao ảnh hưởng đến tình trạng mẹ và con để phòng và điều trị sớm nhằm giảm tỷ lệ tử vong mẹ và con.", "Khi có thai phải được đăng ký quản lý thai nghén, phải đi khám thai định kỳ và mỗi khi có những dấu hiệu bất thường."], "bullets": []}], "raw_text": "chẩn đoán thai nghén\nThs. Nguyễn Văn Hiền\nI.  mục tiêu :\nSau khi học xong bài này học viên có khả năng :\nTrình bày được triệu chứng lâm sàng, cận lâm sàng của thai nghén 4,5 tháng đầu của thai kỳ.\nTrình bày được những bệnh lý phụ khoa và thai bệnh lý khác dễ nhầm với thai thường 4,5 tháng đầu của thai kỳ.\nTrình bày triệu chứng cơ năng, thực thể thai nghén 4,5 tháng sau của thai kỳ.\nTrình bày nội dung tuyên truyền cho cộng đồng những dấu hiệu có thai, nhằm đăng ký quản lý thai nghén, đề phòng và phát hiện thai nghén nguy cơ cao.\n\nII.  néi dung\nĐại cương\nKhi có thai người phụ nữ có những thay đổi về giải phẫu và sinh lý rất lớn. Dựa vào đó mà chẩn đoán có thai hay không có thai, thai thường hay thai bệnh lý.\nLâm sàng chia làm 2 thời kỳ:\nGiai đoạn 4,5 tháng đầu.\nGiai đoạn 4,5 tháng sau.\nChẩn đoán thai nghén trong thời kỳ 4,5 tháng đầu:\nChẩn đoán xác định:\n2.1.1 Triệu chứng cơ năng:\n+ Triệu chứng tắt kinh trên một người phụ nữ khỏe mạnh, có kinh nguyệt đều và có quan hệ tình dục. Đây là dấu hiệu đáng tin cậy hay gần như chắc chắn để chẩn đoán.\n+ Triệu chứng thai nghén: Tùy theo từng thai phụ, đó là sự thay đổi của người phụ nữ do tình trạng có thai gây nên.\nTiết nước bọt, buồn nôn, lơm giọng hoặc nôn vào buổi sáng.\nThay đổi vị giác: Ngán ăn hoặc thích ăn những thức ăn lạ mà từ trước tới nay thích hoặc không thích.\nThay đổi khứu giác: VD: Sợ mùi thơm, sợ mùi thuốc lá...mà bình thường không sợ.\nThay đổi về tinh thần: Tính tình thay đổi, đễ cáu gắt, buồn ngủ, mệt mỏi hoặc ngược lại.\n2.1.2 Triệu chứng thực thể:\n* Da mặt và da bong: Xuất hiện các vết nâu sạm, ở mặt thường xuất hiện ở 2 gò má, ở đường trắng giữa bong và các vết rạn đối với con so. Còn con rạ có thể thấy các vết rạn màu trắng.\n* Vú phát triển nhanh theo tuổi thai, quầng vú them màu, hạt Montgomery nổi rõ hơn, có thể thấy xuất hiện sũa non.\n* Âm hộ và niêm mạc âm đạo bị tím lại.\n* Tử cung:\n+ Cổ tử cung mềm, tím.\n+ Thân tử cung to và có cơn co tử cung: Là dấu hiệu quyết định.\nDấu hiệu Noble (+): Chứng tỏ tử cung to.\nDấu hiệu Hegar (+): Chứng tỏ tử cung mềm (không nên làm với người giữ thai vì dễ sẩy).\n2.1.3 Triệu chứng cận lâm sàng:\n+ Tìm HCG trong nước tiểu hoạc trong máu bằng các xét nghiệm:\nPhản ứng miễn dịch: Làm các test HCG có kết quả nhanh: HCG vitest\nQuickstick\nĐịnh lượng β HCG.\n+ Siêu âm: Là xét nghiệm hết sức đơn giản, nhanh và cho kết quả chính xác. Siêu âm những tháng đầu có tác dụng chẩn đoán thai sớm, chẩn đoán thai thường hay thai bệnh lý, chẩn đoán tuổi thai chính xác nhất.\nVới siêu âm ta có thể thấy:\nTói èi khi 5 tuÇn tuæi (chËm kinh 1 tuÇn).\nCấu trúc phôi từ tuần lễ thứ 6 ư 7.\nTim thai tõ tuÇn lÔ thø 7- 8\nHoạt động của thai từ tuần lễ thứ 9.\nTrước tuần lễ thứ 12 thì siêu âm có giá trị chẩn đoán tuổi thai chính xác nhất theo công thức:\nTuæi thai dưới 6 : Dựa vào kích thước túi thai\nTuæi thai trên 6 tuần : Dựa vào chiều dài phôi\nSau tuần lễ thứ 12, đường kính lưỡng đỉnh của thai nhi là chỉ số chính xác nhất để tính tuổi thai.\nChẩn đoán phân biệt\nChẩn đoán thai nghén nói chung không khó nhưng trong những ngày đầu thai nghén cũng cần chẩn đoán phân biệt với những trường hợp sau:\n+ Tắt kinh: Phân biệt với những trường hợp mất kinh nhưng không phải có thai, gặp ở một số bệnh: Tâm thàn, rối loạn nội tiết, bệnh nội khoa nặng.\n+ Nghén: Phân biệt với nghén giả: Gặp ở những người mong hoặc sợ có con quá làm cho người phụ nữ có tình trạng nghén thực sự.\n+ Tử cung to cần chẩn đoán phân biệt với: U xơ tử cung, u nang buồng trứng.\n+ Ngoài ra cần chẩn đoán phân biệt với những trường hợp thai nghén bệnh lý thường gặp trong những tháng đầu của thời kỳ thai nghén như:\nThai chÕt l­u\nChửa ngoài tử cung\nChửa trứng.\nChẩn đoán thai nghén 4,5 tháng sau:\nChẩn đoán thai nghén thời kỳ này thường dễ nhưng tiên lượng cuộc đẻ mới là khó.\nTriệu chứng lâm sàng:\n+ Tắt kinh kéo dài, tử cung ngày càng to lên rõ rệt so với tuổi thai.\n+ Sờ nắn được các cực của thai nhi.\n+ Nghe được tiếng tim thai.\n+ Các cử động của thai nhi còn gọi là thai máy hay thai đạp.\n3.2. Triệu chứng cận lâm sàng:\nThường làm siêu âm để:\nChẩn đoán tuổi thai.\nĐánh giá sự phát triển của thai.\nPhát hiện sớm các dị tật bẩm sinh.\nĐiều cơ bản nhất là chẩn đoán được ngôi, thế, kiểu thế để phần nào tiên lượng sớm được cuộc đẻ.\nMặt khác còn phải khám tìm các dấu hiệu thay đổi bất thường để chẩn đoán thai nghén nguy cơ cao nhằm điều trị sớm tránh tai biến và biến chứng nguy hiểm cho mẹ và con như: Rau tiền đạo, tiền sản giật…\nCông tác tư vấn\nTuyên truyền cho cộng đồng những dấu hiệu bình thường khi có thai như: Chậm kinh, nghén, vú to và đau, bụng ngày càng to và thấy thai đạp.\nNhững dấu hiệu bất thường khi có thai như: Đau bụng, ra máu âm đạo, nghén quá mức, thai không đạp  để đến cơ sở y tế khám ngay nhằm phát hiện thai nghén bất thường, những yếu tố nguy cơ cao ảnh hưởng đến tình trạng mẹ và con để phòng và điều trị sớm nhằm giảm tỷ lệ tử vong mẹ và con.\nKhi có thai phải được đăng ký quản lý thai nghén, phải đi khám thai định kỳ và mỗi khi có những dấu hiệu bất thường.\nCâu hỏi:\n1. Trình bày triệu chứng lâm sàng, cận lâm sàng để chẩn đoán xác định  thai nghén 3 tháng đầu?\n2. Trình bày triệu chứng lâm sàng, cận lâm sàng để chẩn đoán xác định  thai nghén 3 tháng giữa?", "priority": "Trung bình"}, {"id": "SK-07", "chapter": "Chương 1. Sản thường", "folder": "01_San_thuong", "title": "Sinh lý chuyển dạ", "author": "Ths. Bùi Thị Thanh Tuyền", "word_count": 3307, "line_count": 162, "key_numbers": ["1 giờ", "1 mmHg", "10 cm", "10 giờ", "10 mmHg", "10 phút", "10cm", "10mmHg", "120 mmHg", "13 mmHg", "18 giờ", "2 giờ", "20 ml", "3 cm", "3 phút", "30 phút", "30 tuần", "37 tuần", "40 mmHg", "45mmHg", "5 phút", "50 mmHg", "6 giờ"], "key_drugs": ["Glucose", "Oxytocin", "Prostaglandin", "glucose", "oxytocin", "prostaglandin"], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["SINH LÝ CHUYỂN DẠ", "Ths. Bùi Thị Thanh Tuyền"], "bullets": []}, {"heading": "1. ĐỊNH NGHĨA", "paragraphs": ["Chuyển dạ là quá trình sinh lý làm xóa mở cổ tử cung và đẩy thai, phần phụ của thai ra khỏi đường sinh dục của người mẹ. Chuyển dạ đủ tháng là chuyển dạ xảy ra từ đầu tuần 37 đến cuối tuần 41, lúc này thai nhi đã có thể sống độc lập ngoài tử cung."], "bullets": []}, {"heading": "2.1. Prostaglandin", "paragraphs": [], "bullets": ["-  Prostaglandin đóng vai trò cơ bản trong khởi phát chuyển dạ.", "- Prostaglandin được hình thành từ axít arachidonic dưới tác động của 15-hydroxyprostaglandin dehydrogenase. Prostaglandin có trong nước ối, màng rụng và cơ tử cung. Sự sản xuất prostaglandin F2 và PGE2 tăng từ từ trong thời kỳ thai nghén và đạt tỷ lệ cao sau khi bắt đầu chuyển dạ. Prostaglandin góp phần vào sự chín muồi cổ tử cung.", "- Các yếu tố: phá ối, nhiễm trùng ối, lóc ối có thể gây tăng tổng hợp đột ngột prostaglandin vào cuối thai kỳ."]}, {"heading": "2.2. Những yếu tố ảnh hưởng", "paragraphs": ["Nồng độ của progesteron giảm ở cuối thời kỳ thai nghén làm thay đổi tỷ lệ estrogen/ progesteron góp phần khởi phát chuyển dạ."], "bullets": ["- Estrogen: làm tăng sự nhạy cảm của cơ trơn và tốc độ truyền của hoạt động điện tế bào, do đó hỗ trợ cho cơn co co tử cung. Ngoài ra, estrogen còn làm thuận lợi cho sự tổng hợp các prostaglandin.", "- Progesteron: có tác dụng ức chế cơn co co tử cung, tuy nhiên vai trò của progesteron trong chuyển dạ vẫn chưa rõ ràng.", "- Yếu tố về mẹ: cơ chế màng rụng tổng hợp prostaglandin và tuyến yên giải phóng oxytocin còn là vấn đề đang tranh luận. Người ta quan sát thấy những đỉnh kế tiếp của nồng độ oxytocin với tần suất tăng trong chuyển dạ, đạt tối đa trong pha sổ thai. Tuy nhiên oxytocin dường như không có vai trò trong khởi phát chuyển dạ nhưng nồng độ lại tăng lên trong quá trình chuyển dạ.", "- Yếu tố về thai: người ta biết rằng nếu thai bị quái thai vô sọ, hoặc giảm sản tuyến thượng thận, thai nghén thường kéo dài, ngược lại nếu tăng sản tuyến thượng thận của thai nhi, thường gây đẻ non."]}, {"heading": "3.1. Cơn co tử cung", "paragraphs": ["Đó là động lực chính cho phép  sự xoá mở cổ tử cung và sự xuống của thai trong tiểu khung.", "Sinh lý co cơ của sợi cơ trơn: cơn co của sợi cơ trơn tử cung là kết quả của sự trượt các sợi actin và myosine. Sự tạo thành nối actine - myosine cần thiết của năng lượng cung cấp bởi ATP.", "Cơn co tử cung ghi được trên monitor sản khoa, có hình chuông, thời gian nghỉ dao động giữa 1 - 3 phút.", "Hình 1. Các thông số của cơn co tử cung", "Tần số cơn co là số cơn co tính trong 10 phút.", "Cường độ là số đo lúc áp lực buồng tử cung cao nhất.", "Hoạt độ là tích số giữa tần số và cường độ, được tính bằng đơn vị Montévideo (UM) trong 10 phút.", "Những thay đổi áp lực được trình bày bằng mmHg hoặc bằng Kilo Pascal (1 mmHg = 0,133H Pa).", "Trong 30 tuần đầu tử cung co nhẹ và hoạt động của tử cung < 20 UM.", "Từ 30 đến 37 tuần những cơn co co tử cung nhiều hơn có khi đạt đến 50 UM. Tần suất của nó không vượt quá 1 cơn co /1h.", "Trong khi đẻ, bắt đầu của chuyển dạ đặc trưng bởi những cơn co tử cung 120 UM tăng từ từ và đạt đến 250 UM khi sổ thai.", "Trương lực cơ bản trong khi chuyển dạ thay đổi từ 12 - 13 mmHg, cường độ toàn thể là 35 - 50 mmHg. Tần suất của cơn co tử cung có thể đạt 4 cơn co trong 10 phút. Tư thế nằm nghiêng không làm thay đổi trương lực cơ bản nhưng cường độ cơn co tăng từ 10 mmHg, trong khi tần suất cơn co giảm.", "Hiệu quả co tử cung", "Điều hoà cơn co tử cung được kiểm soát bởi:"], "bullets": ["- Thúc đẩy thai về phía đoạn dưới tử cung.", "- Làm giãn đoạn dưới và hình thành đầu ối.", "- Xoá mở cổ tử cung.", "- Estrogen cho phép tạo các protein co cơ nên sợi cơ tử cung dễ bị kích thích và làm dễ cho sự dẫn truyền các kích thích.", "- Progesteron: tăng những nối calci-ATP, gây hạ thấp calci tự do trong tế bào kéo theo sự giãn của các sợi cơ. Ức chế sự truyền các hoạt động điện của sợi cơ.", "- Prostaglandin: giải phóng calci dự trữ trong màng tế bào.", "- Oxytocin khởi phát những cơn co tử cung, làm mạnh hoạt động go, tăng lưu thông calci.", "- Yếu tố thần kinh: được thực hiện bởi sự giải phóng từng đợt những yếu tố thần kinh dẫn truyền nhất là catecholamines khuếch tán về phía các sợi cơ."]}, {"heading": "3.2. Sự hình thành đoạn dưới", "paragraphs": ["Trong khi mang thai, eo tử cung phát triển và kéo dài trở thành đoạn dưới. Đoạn dưới chỉ có 2 lớp cơ ngang và dọc, không có lớp cơ đan chéo.", "Ở con so, đoạn dưới được hình thành vào cuối thai kỳ, ở người con rạ, đoạn dưới thành lập vào lúc bắt đầu chuyển dạ."], "bullets": []}, {"heading": "3.3. Sự chín muồi của cổ tử cung (CTC)", "paragraphs": ["Trong nửa đầu của thời kỳ thai nghén, CTC màu tím, đóng giữ nguyên dạng kích thước của nó, phần dưới của ống cổ lộn ra kèm lộn niêm mạc ống cổ và tạo thành lộ tuyến.", "Trong nửa sau của thời kỳ thai nghén CTC trở nên mềm hơn, vị trí và hướng chỉ thay đổi vào cuối thời kỳ thai nghén, các tuyến tiết nhiều chất nhầy tạo thành nút nhầy CTC", "Sự chín muồi xuất hiện vài ngày trước khi chuyển dạ. CTC trở nên mềm, ngắn và hướng ra trước. Sự chín muồi là do những thay đổi ở mô liên kết đệm CTC, độc lập với cơn co tử cung, cốt lưới tạo keo của cổ tử cung trở nên thưa và rải rác vào cuối thai kỳ."], "bullets": []}, {"heading": "3.4. Sự xoá và mở cổ tử cung", "paragraphs": ["Đoạn dưới nhận những lực xuất phát từ tử cung được chuyển bởi thai sau khi vỡ màng ối. Đoạn dưới trở nên mỏng hơn vì không có cơ đan. Sự chín muồi CTC tiếp tục vào đầu chuyển dạ, rồi cổ tử cung mở dưới tác dụng của cơn co tử cung và áp lực của ngôi thai.", "Sự xoá của cổ tử cung bắt đầu bởi lỗ trong cổ tử cung mở dần, dẫn đến cổ tử cung ngắn lại. Tiếp theo là sự mở cổ tử cung từ 1đến 10cm (mở hết). Quá trình mở cổ tử cung thể hiện sự tiến triển của chuyển dạ, nó diễn ra trong hai giai đoạn: pha tiềm tàng (CTC mở từ 0 - 3 cm) và pha tích cực (CTC mở từ 3 - 10 cm).", "Ở người sinh con so, CTC bắt đầu xoá trước khi mở, ở người sinh con rạ sự xoá và mở CTC có thể diễn ra đồng thời. Thời gian mở cổ tử cung ở mỗi sản phụ có thể khác nhau, thường thì ở người sinh con rạ ngắn hơn so với người sinh con so.", "Hình 2. Sự xoá mở cổ tử cung"], "bullets": []}, {"heading": "4. CÁC GIAI ĐOẠN CỦA CHUYỂN DẠ", "paragraphs": ["Có ba giai đoạn khác nhau của chuyển dạ", "Thời gian của chuyển dạ bình thường", "Giai đoạn", "Con so", "Con rạ", "Giai đoạn I", "Giai đoạn II", "Giai đoạn III", "6 giờ - 18 giờ", "30 phút - 1 giờ", "0 - 30 phút", "2 giờ - 10 giờ", "5 phút - 30 phút", "0 - 30 phút"], "bullets": ["- Giai đoạn I là giai đoạn từ khi bắt đầu xoá mở cổ tử cung cho đến khi cổ tử cung mở hết. Đây là giai đoạn dài nhất của cuộc chuyển dạ.", "- Giai đoạn II là giai đoạn sổ thai, bắt đầu từ khi cổ tử cung mở hết đến khi sổ thai xong.", "- Giai đoạn III là giai đoạn sổ rau"]}, {"heading": "5.1. Những yếu tố ảnh hưởng đến thai", "paragraphs": ["Trong chuyển dạ thai chịu những yếu tố ảnh hưởng khác nhau như cơn co tử cung, động lực cơ học tác động lên thai và dây  rốn và thay đổi chuyển hoá của mẹ."], "bullets": []}, {"heading": "5.1.1. Cơn co tử cung", "paragraphs": ["Lưu lượng trong động mạch tử cung giảm 30% khi  cơn co tử cung đạt cực điểm, khi đó áp lực trong buồng ối vượt áp lực của hồ huyết (30 mHg) tuần hoàn gián đoạn trong khoảng 15 - 60 giây bởi sự chèn ép tĩnh mạch trở về. Tuy nhiên máu ở hồ huyết có dự trữ oxy để tạm thời cho thai và PO2 trong hồ huyết giữ ổn định ở 40 mmHg.", "Khi sổ thai, tần số và cường độ của cơn co tử cung tăng phối hợp cơn co thành bụng - lúc này áp lực buồng ối đạt đến 100 - 120 mmHg, tuần hoàn động mạch tử cung, hồ huyết bị gián đoạn dẫn đến sự hạ thấp PO2 và tăng PCO2.", "Đối với thai bình thường, cơn co tử cung bình thường trong chuyển dạ không ảnh hưởng đến thai bình thường.", "Cơn co tử cung quá dày hoặc quá dài có thể đe doạ một thai bình thường.", "Nếu rau suy hoặc kém tưới máu, dẫn đến trao đổi oxy giảm, thai có thể suy mặc dù cơn co bình thường.", "Thai yếu, thai kém phát triển, do dự trữ glucoza giảm nên thai chịu đựng kém với cơn co tử cung.", "Do vậy, sự bình thường của chuyển dạ phụ thuộc vào cơn co tử cung, thai, rau."], "bullets": []}, {"heading": "5.1.2. Lực cơ học", "paragraphs": ["Nếu còn màng ối, áp lực thành tử cung không ảnh hưởng trực tiếp đến thai và dây rốn.", "Sau khi ối vỡ, áp lực chèn ép vào đầu thai nhi có thể tăng 2 - 3 lần, dây rốn có thể bị ép giữa tử cung và thai nhi."], "bullets": []}, {"heading": "5.1.3. Ảnh hưởng của mẹ đến thai nhi", "paragraphs": [".5.2. Sự đáp ứng của thai đối với các kích thích", "Hậu quả chung của tất cả những kích thích trên là giảm oxy ở thai, dẫn đến những biểu hiện thay đổi về chuyển hoá và tim mạch."], "bullets": ["- Những cơ co tử cung dày và mạnh có thể dẫn đến tình trạng nhiễm toan (acid lactic) do chuyển hóa glucose theo đường kỵ khí ở thai nhi.", "- Tăng thông khí phổi do mẹ thở nhanh và gắng sức trong khi đẻ gây ra tình trạng nhiễm kiềm hô hấp, PCO2 hạ gây ra tình trạng giảm lưu lượng máu tử cung rau.", "- Trong khi sổ thai những cố gắng rặn với thanh môn mẹ đóng lại, tăng PCO2 và đưa đến tình trạng nhiễm toan ở mẹ, từ đó ảnh hưởng đến thai.", "- Chỉ định thở oxy cho mẹ không phải luôn luôn có lợi, vì nhiễm kiềm và tăng oxy kéo theo sự hạ thấp dung lượng tử cung rau, ngược lại nó cần thiết trong trường hợp giảm oxy của người mẹ.", "- Rối loạn huyết động:", "+ Ở tư thế nằm ngửa: tử cung mang thai với xu hướng lệch phải nên gây chèn ép tĩnh mạch chủ dưới và dẫn đến hạ huyết áp động mạch, giảm dung lượng máu đến rau thai, có thể làm giảm sức chịu đựng của thai trong cuộc chuyển dạ. Tư thế sản phụ nằm nghiêng trái sẽ tránh được hiện tượng này.", "+ Những cơn co tử cung mạnh, hoặc cố gắng rặn sẽ chèn ép động mạch chủ dưới, động mạch đùi làm giảm lưu lượng trong động mạch tử  cung gây suy thai.", "+ Hạ huyết áp mẹ do liệt hạch: do gây tê ngoài màng cứng có thể kéo theo tình trạng suy thai do giảm huyết áp dẫn đến giảm thể tích máu gây giảm lưu lượng máu tới rau.", "+ Đau và lo lắng trong chuyển dạ làm tăng tiết cortisol và catecholamine có tác dụng co mạch tử cung và tăng tình trạng nhiễm acide lactic. Do vậy luôn phải cho giảm đau và tránh buồn phiền.", "- Một số thuốc có thể làm ức chế trung tâm hô hấp và ức chế cơ tim của thai (như barbiturat, dolargan…)"]}, {"heading": "5.2.1. Những thay đổi về chuyển hoá do giảm oxy gây nhiễm toan chuyển hoá", "paragraphs": ["Glycogen của gan sẽ hoạt hoá và chuyển hoá thành năng lượng. Sự chuyển hoá này luôn trong tình trạng kỵ khí, chuyển thành lactate và CO2. Với mức độ thiếu oxy vừa phải, thai có trọng lượng trung bình có thể thích ứng với tình trạng thiếu oxy này bằng cách sử dụng glycogen của thai. Ngược lại, đối với thai kém phát triển, không có dự trữ sẽ chịu đựng kém vì thiếu oxy."], "bullets": []}, {"heading": "5.2.2. Sự thay đổi về tim mạch", "paragraphs": ["Khi thai có tình trạng giảm oxy người ta nhận thấy trong giai đoạn sớm, có sự tăng huyết áp, tăng nhịp tim thai do tác động của hệ adrenergic. Trong giai đoạn muộn, nhịp tim giảm do nhiễm toan.", "Phân bố lại những lượng máu riêng cho từng vùng, sự phân bố này nhằm bảo vệ những cơ quan quan trọng của thai, như tăng lượng máu cho não, tim, thượng thận và giảm lưu lượng máu tới hệ tiêu hoá, lách, xương, da, cơ, phổi. Do tình trạng ưu thán (tăng CO2) phối hợp giảm oxy kéo theo sự giãn mạch não đưa đến ứ trệ tuần hoàn gây phù não làm tăng thiếu máu não, giải phóng thromboplastine tổ chức gây hội chứng xuất huyết não ở trẻ sơ sinh."], "bullets": []}, {"heading": "5.2.3. Trong chuyển dạ", "paragraphs": ["Trong thời kỳ xoá mở cổ tử cung nhịp tim thai cơ bản nằm trong khoảng 120 - 160 lần/phút, nhịp tim thai có thể nhanh trong vài chục giây nhưng không bao giờ chậm không có lý do. Sự ổn định của nhịp tim thai trong chuyển dạ là bằng chứng không có nguy cơ đối với thai.", "Trong lúc sổ thai: nhịp tim thai giảm chậm trong 1/3 trường hợp.", "Lúc sinh:"], "bullets": ["- pH = 7,25", "- P02 = 10mmHg", "- PC02 = 45mmHg", "- Tăng catecholamin, cortisol, ACTH và TSH, angiotensin, renin, vasopressin trong máu. Sự thay đổi nội tiết này dường như có lợi đối với sự thích ứng của thai sau sinh."]}, {"heading": "6. SỰ THÍCH ỨNG CỦA TRẺ SƠ SINH SAU ĐẺ", "paragraphs": ["Khi thai ở trong tử cung các cơ quan thai nhi còn trong tình trạng nghỉ ngơi hoặc chưa hoạt động hoàn toàn như phổi, hệ tiêu hoá, thận… (những trao đổi khí và chuyển hoá diễn ra ở rau thai).", "Ngay sau sinh, trẻ sơ sinh phải thích hợp với cuộc sống mới, các thích ứng ở phổi, tim mạch xảy ra ngay tức thì để đảm bảo cuộc sống. Những thích ứng khác ở tiêu hoá, thân nhiệt, năng lượng, thận được thiết lập chậm hơn."], "bullets": ["- Sự duy trì thân nhiệt của thai được bảo đảm bởi sự truyền nhiệt của mẹ, sự chuyển hóa của thai, rau và nước ối.", "- Tuần hoàn vận hành theo cách riêng do sức cản ngoại vi thấp vì:", "+ Tuần hoàn rau thai.", "+ Mỗi tâm thất chỉ chịu một phần của cung lượng tim.", "+ Có 3 nối tắt riêng (ống Arantius, lỗ Botal, ống động mạch)."]}, {"heading": "6.1. Hệ thống hô hấp", "paragraphs": ["Khi sổ thai ngực của thai nhi bị chèn ép, điều đó loại bỏ một phần dịch ở đường hô hấp trên (khoảng 20 ml), sau đó lồng ngực lấy lại thể tích của nó đưa vào phổi một lượng không khí lớn khởi phát phản xạ hô hấp. Với điểm khởi phát là hầu, không khí tràn vào phổi đẩy tiếp dịch phổi ra, không khí trộn lẫn với các dịch tiết tạo thành bọt khí phủ phế nang làm thuận lợi duy trì một thể tích khí trong phế nang. Áp lực mạnh của sự thở ra đẩy dịch tiết trong nhu mô phổi về phía khoảng kẽ và hệ thống bạch huyết.", "Sự bài tiết adrenalin của thai trong lúc đẻ góp phần làm giảm sự bài tiết dịch ở phổi và làm thuận lợi cho sự hấp thu dịch.", "Khi tạo ra trong phổi một áp lực vượt quá 40 - 100 cmH2O có thể gây vỡ phế nang, hoặc tràn khí màng phổi."], "bullets": []}, {"heading": "6.2. Hệ thống tuần hoàn", "paragraphs": ["Hô hấp đầu tiên kéo theo sự giãn mạch.", "Áp lực trong động mạch phổi trở nên thấp hơn áp lực động mạch chủ, động mạch đảo ngược và trở thành trái phải, máu qua từ động mạch chủ đến động mạch phổi."], "bullets": ["- Hạ thấp PC02 và tăng P02 đưa tới tăng lưu lượng máu phổi.", "- Cắt đứt tuần hoàn rau tăng sức cản đại tuần hoàn."]}, {"heading": "6.3. Hệ tiêu hoá", "paragraphs": ["Phản xạ mút kích thích sự xuống sữa non, cung cấp năng lượng, các yếu tố miễn dịch."], "bullets": []}, {"heading": "6.4. Thận", "paragraphs": ["Huyết áp động mạch tăng, lưu lượng máu động mạch thận tăng, tăng lọc cầu thận."], "bullets": []}, {"heading": "6.5. Quân bình năng lượng", "paragraphs": ["Glucose cung cấp bởi rau bị cắt đứt nên chuyển sang sử dụng glucogen của gan, hủy lipid bằng oxy hoá mỡ xám của trẻ sơ sinh."], "bullets": []}, {"heading": "6.6. Sự thích hợp điều hoà thân nhiệt", "paragraphs": ["Sự co mạch ở da, tăng chuyển hoá nhằm bảo đảm sưởi ấm. Sự sinh nhiệt bởi oxy hoá mỡ xám (tập trung chủ yếu ở vùng tầng sinh môn và hai mạn sườn của trẻ sơ sinh trong vài ngày đầu để cung cấp năng lượng đầu tiên cho trẻ). Trẻ  sơ sinh bị nhiễm lạnh rất nhanh, nếu để trần hoặc làm ướt thân nhiệt bị giảm 20 trong 30 phút. Những trẻ bị ngạt hạ thân nhiệt xảy ra nhanh hơn."], "bullets": []}, {"heading": "6.7. Thay đổi thần kinh", "paragraphs": ["Sau sinh, hệ thần kinh thực vật chiếm ưu thế nên trẻ sơ sinh ăn ngủ, cử động không ý thức, tuỳ thuộc bữa bú và hô hấp."], "bullets": []}, {"heading": "Câu hỏi:", "paragraphs": ["1: Trình bày định nghĩa của chuyển dạ và các nguyên nhân gây chuyển dạ"], "bullets": []}, {"heading": "6. Trình bày chẩn đoán chuyển dạ và theo dõi chuyển dạ đẻ?", "paragraphs": ["CHẨN ĐOÁN NGÔI - THẾ - KIỂU THẾ"], "bullets": []}, {"heading": "Mục tiêu học tập", "paragraphs": ["Trình bày định nghĩa ngôi, thế, kiểu thế  và nêu các mốc của ngôi thai."], "bullets": []}], "raw_text": "SINH LÝ CHUYỂN DẠ\nThs. Bùi Thị Thanh Tuyền\nMục tiêu học tập\n1. Trính bày được cơ chế khởi phát chuyển dạ\n2. Trình bày được sinh lý của cơn co tử cung và thay đổi của cổ tử cung trong chuyển dạ.\n3. Giải thích được các ảnh hưởng của chuyển dạ đối với thai\n4. Trình bày được các đáp ứng của thai với chuyển dạ.\n\n1. ĐỊNH NGHĨA\nChuyển dạ là quá trình sinh lý làm xóa mở cổ tử cung và đẩy thai, phần phụ của thai ra khỏi đường sinh dục của người mẹ. Chuyển dạ đủ tháng là chuyển dạ xảy ra từ đầu tuần 37 đến cuối tuần 41, lúc này thai nhi đã có thể sống độc lập ngoài tử cung.\n2. CƠ CHẾ PHÁT KHỞI CHUYỂN DẠ\n2.1. Prostaglandin\n-  Prostaglandin đóng vai trò cơ bản trong khởi phát chuyển dạ.\n- Prostaglandin được hình thành từ axít arachidonic dưới tác động của 15-hydroxyprostaglandin dehydrogenase. Prostaglandin có trong nước ối, màng rụng và cơ tử cung. Sự sản xuất prostaglandin F2 và PGE2 tăng từ từ trong thời kỳ thai nghén và đạt tỷ lệ cao sau khi bắt đầu chuyển dạ. Prostaglandin góp phần vào sự chín muồi cổ tử cung.\n- Các yếu tố: phá ối, nhiễm trùng ối, lóc ối có thể gây tăng tổng hợp đột ngột prostaglandin vào cuối thai kỳ.\n2.2. Những yếu tố ảnh hưởng\n- Estrogen: làm tăng sự nhạy cảm của cơ trơn và tốc độ truyền của hoạt động điện tế bào, do đó hỗ trợ cho cơn co co tử cung. Ngoài ra, estrogen còn làm thuận lợi cho sự tổng hợp các prostaglandin.\n- Progesteron: có tác dụng ức chế cơn co co tử cung, tuy nhiên vai trò của progesteron trong chuyển dạ vẫn chưa rõ ràng.\nNồng độ của progesteron giảm ở cuối thời kỳ thai nghén làm thay đổi tỷ lệ estrogen/ progesteron góp phần khởi phát chuyển dạ.\n- Yếu tố về mẹ: cơ chế màng rụng tổng hợp prostaglandin và tuyến yên giải phóng oxytocin còn là vấn đề đang tranh luận. Người ta quan sát thấy những đỉnh kế tiếp của nồng độ oxytocin với tần suất tăng trong chuyển dạ, đạt tối đa trong pha sổ thai. Tuy nhiên oxytocin dường như không có vai trò trong khởi phát chuyển dạ nhưng nồng độ lại tăng lên trong quá trình chuyển dạ.\n- Yếu tố về thai: người ta biết rằng nếu thai bị quái thai vô sọ, hoặc giảm sản tuyến thượng thận, thai nghén thường kéo dài, ngược lại nếu tăng sản tuyến thượng thận của thai nhi, thường gây đẻ non.\n3. SINH LÝ CỦA CƠN CO TỬ CUNG VÀ NHỮNG THAY ĐỔI CỦA CỔ TỬ CUNG TRONG  CHUYỂN  DẠ\n3.1. Cơn co tử cung\nĐó là động lực chính cho phép  sự xoá mở cổ tử cung và sự xuống của thai trong tiểu khung.\nSinh lý co cơ của sợi cơ trơn: cơn co của sợi cơ trơn tử cung là kết quả của sự trượt các sợi actin và myosine. Sự tạo thành nối actine - myosine cần thiết của năng lượng cung cấp bởi ATP.\nCơn co tử cung ghi được trên monitor sản khoa, có hình chuông, thời gian nghỉ dao động giữa 1 - 3 phút.\n\nHình 1. Các thông số của cơn co tử cung\nTần số cơn co là số cơn co tính trong 10 phút.\nCường độ là số đo lúc áp lực buồng tử cung cao nhất.\nHoạt độ là tích số giữa tần số và cường độ, được tính bằng đơn vị Montévideo (UM) trong 10 phút.\nNhững thay đổi áp lực được trình bày bằng mmHg hoặc bằng Kilo Pascal (1 mmHg = 0,133H Pa).\nTrong 30 tuần đầu tử cung co nhẹ và hoạt động của tử cung < 20 UM.\nTừ 30 đến 37 tuần những cơn co co tử cung nhiều hơn có khi đạt đến 50 UM. Tần suất của nó không vượt quá 1 cơn co /1h.\nTrong khi đẻ, bắt đầu của chuyển dạ đặc trưng bởi những cơn co tử cung 120 UM tăng từ từ và đạt đến 250 UM khi sổ thai.\nTrương lực cơ bản trong khi chuyển dạ thay đổi từ 12 - 13 mmHg, cường độ toàn thể là 35 - 50 mmHg. Tần suất của cơn co tử cung có thể đạt 4 cơn co trong 10 phút. Tư thế nằm nghiêng không làm thay đổi trương lực cơ bản nhưng cường độ cơn co tăng từ 10 mmHg, trong khi tần suất cơn co giảm.\nHiệu quả co tử cung\n- Thúc đẩy thai về phía đoạn dưới tử cung.\n- Làm giãn đoạn dưới và hình thành đầu ối.\n- Xoá mở cổ tử cung.\nĐiều hoà cơn co tử cung được kiểm soát bởi:\n- Estrogen cho phép tạo các protein co cơ nên sợi cơ tử cung dễ bị kích thích và làm dễ cho sự dẫn truyền các kích thích.\n- Progesteron: tăng những nối calci-ATP, gây hạ thấp calci tự do trong tế bào kéo theo sự giãn của các sợi cơ. Ức chế sự truyền các hoạt động điện của sợi cơ.\n- Prostaglandin: giải phóng calci dự trữ trong màng tế bào.\n- Oxytocin khởi phát những cơn co tử cung, làm mạnh hoạt động go, tăng lưu thông calci.\n- Yếu tố thần kinh: được thực hiện bởi sự giải phóng từng đợt những yếu tố thần kinh dẫn truyền nhất là catecholamines khuếch tán về phía các sợi cơ.\n3.2. Sự hình thành đoạn dưới\nTrong khi mang thai, eo tử cung phát triển và kéo dài trở thành đoạn dưới. Đoạn dưới chỉ có 2 lớp cơ ngang và dọc, không có lớp cơ đan chéo.\nỞ con so, đoạn dưới được hình thành vào cuối thai kỳ, ở người con rạ, đoạn dưới thành lập vào lúc bắt đầu chuyển dạ.\n3.3. Sự chín muồi của cổ tử cung (CTC)\nTrong nửa đầu của thời kỳ thai nghén, CTC màu tím, đóng giữ nguyên dạng kích thước của nó, phần dưới của ống cổ lộn ra kèm lộn niêm mạc ống cổ và tạo thành lộ tuyến.\nTrong nửa sau của thời kỳ thai nghén CTC trở nên mềm hơn, vị trí và hướng chỉ thay đổi vào cuối thời kỳ thai nghén, các tuyến tiết nhiều chất nhầy tạo thành nút nhầy CTC\nSự chín muồi xuất hiện vài ngày trước khi chuyển dạ. CTC trở nên mềm, ngắn và hướng ra trước. Sự chín muồi là do những thay đổi ở mô liên kết đệm CTC, độc lập với cơn co tử cung, cốt lưới tạo keo của cổ tử cung trở nên thưa và rải rác vào cuối thai kỳ.\n3.4. Sự xoá và mở cổ tử cung\nĐoạn dưới nhận những lực xuất phát từ tử cung được chuyển bởi thai sau khi vỡ màng ối. Đoạn dưới trở nên mỏng hơn vì không có cơ đan. Sự chín muồi CTC tiếp tục vào đầu chuyển dạ, rồi cổ tử cung mở dưới tác dụng của cơn co tử cung và áp lực của ngôi thai.\nSự xoá của cổ tử cung bắt đầu bởi lỗ trong cổ tử cung mở dần, dẫn đến cổ tử cung ngắn lại. Tiếp theo là sự mở cổ tử cung từ 1đến 10cm (mở hết). Quá trình mở cổ tử cung thể hiện sự tiến triển của chuyển dạ, nó diễn ra trong hai giai đoạn: pha tiềm tàng (CTC mở từ 0 - 3 cm) và pha tích cực (CTC mở từ 3 - 10 cm).\nỞ người sinh con so, CTC bắt đầu xoá trước khi mở, ở người sinh con rạ sự xoá và mở CTC có thể diễn ra đồng thời. Thời gian mở cổ tử cung ở mỗi sản phụ có thể khác nhau, thường thì ở người sinh con rạ ngắn hơn so với người sinh con so.\n\nHình 2. Sự xoá mở cổ tử cung\n4. CÁC GIAI ĐOẠN CỦA CHUYỂN DẠ\nCó ba giai đoạn khác nhau của chuyển dạ\n- Giai đoạn I là giai đoạn từ khi bắt đầu xoá mở cổ tử cung cho đến khi cổ tử cung mở hết. Đây là giai đoạn dài nhất của cuộc chuyển dạ.\n- Giai đoạn II là giai đoạn sổ thai, bắt đầu từ khi cổ tử cung mở hết đến khi sổ thai xong.\n- Giai đoạn III là giai đoạn sổ rau\n\nThời gian của chuyển dạ bình thường\n\nGiai đoạn\nCon so\nCon rạ\n\nGiai đoạn I\nGiai đoạn II\nGiai đoạn III\n6 giờ - 18 giờ\n30 phút - 1 giờ\n0 - 30 phút\n2 giờ - 10 giờ\n5 phút - 30 phút\n0 - 30 phút\n\n\n5.  SỰ THÍCH ỨNG CỦA THAI ĐỐI VỚI CHUYỂN DẠ\n5.1. Những yếu tố ảnh hưởng đến thai\nTrong chuyển dạ thai chịu những yếu tố ảnh hưởng khác nhau như cơn co tử cung, động lực cơ học tác động lên thai và dây  rốn và thay đổi chuyển hoá của mẹ.\n5.1.1. Cơn co tử cung\nLưu lượng trong động mạch tử cung giảm 30% khi  cơn co tử cung đạt cực điểm, khi đó áp lực trong buồng ối vượt áp lực của hồ huyết (30 mHg) tuần hoàn gián đoạn trong khoảng 15 - 60 giây bởi sự chèn ép tĩnh mạch trở về. Tuy nhiên máu ở hồ huyết có dự trữ oxy để tạm thời cho thai và PO2 trong hồ huyết giữ ổn định ở 40 mmHg.\nKhi sổ thai, tần số và cường độ của cơn co tử cung tăng phối hợp cơn co thành bụng - lúc này áp lực buồng ối đạt đến 100 - 120 mmHg, tuần hoàn động mạch tử cung, hồ huyết bị gián đoạn dẫn đến sự hạ thấp PO2 và tăng PCO2.\nĐối với thai bình thường, cơn co tử cung bình thường trong chuyển dạ không ảnh hưởng đến thai bình thường.\nCơn co tử cung quá dày hoặc quá dài có thể đe doạ một thai bình thường.\nNếu rau suy hoặc kém tưới máu, dẫn đến trao đổi oxy giảm, thai có thể suy mặc dù cơn co bình thường.\nThai yếu, thai kém phát triển, do dự trữ glucoza giảm nên thai chịu đựng kém với cơn co tử cung.\nDo vậy, sự bình thường của chuyển dạ phụ thuộc vào cơn co tử cung, thai, rau.\n5.1.2. Lực cơ học\nNếu còn màng ối, áp lực thành tử cung không ảnh hưởng trực tiếp đến thai và dây rốn.\nSau khi ối vỡ, áp lực chèn ép vào đầu thai nhi có thể tăng 2 - 3 lần, dây rốn có thể bị ép giữa tử cung và thai nhi.\n5.1.3. Ảnh hưởng của mẹ đến thai nhi\n- Những cơ co tử cung dày và mạnh có thể dẫn đến tình trạng nhiễm toan (acid lactic) do chuyển hóa glucose theo đường kỵ khí ở thai nhi.\n- Tăng thông khí phổi do mẹ thở nhanh và gắng sức trong khi đẻ gây ra tình trạng nhiễm kiềm hô hấp, PCO2 hạ gây ra tình trạng giảm lưu lượng máu tử cung rau.\n- Trong khi sổ thai những cố gắng rặn với thanh môn mẹ đóng lại, tăng PCO2 và đưa đến tình trạng nhiễm toan ở mẹ, từ đó ảnh hưởng đến thai.\n- Chỉ định thở oxy cho mẹ không phải luôn luôn có lợi, vì nhiễm kiềm và tăng oxy kéo theo sự hạ thấp dung lượng tử cung rau, ngược lại nó cần thiết trong trường hợp giảm oxy của người mẹ.\n- Rối loạn huyết động:\n+ Ở tư thế nằm ngửa: tử cung mang thai với xu hướng lệch phải nên gây chèn ép tĩnh mạch chủ dưới và dẫn đến hạ huyết áp động mạch, giảm dung lượng máu đến rau thai, có thể làm giảm sức chịu đựng của thai trong cuộc chuyển dạ. Tư thế sản phụ nằm nghiêng trái sẽ tránh được hiện tượng này.\n+ Những cơn co tử cung mạnh, hoặc cố gắng rặn sẽ chèn ép động mạch chủ dưới, động mạch đùi làm giảm lưu lượng trong động mạch tử  cung gây suy thai.\n+ Hạ huyết áp mẹ do liệt hạch: do gây tê ngoài màng cứng có thể kéo theo tình trạng suy thai do giảm huyết áp dẫn đến giảm thể tích máu gây giảm lưu lượng máu tới rau.\n+ Đau và lo lắng trong chuyển dạ làm tăng tiết cortisol và catecholamine có tác dụng co mạch tử cung và tăng tình trạng nhiễm acide lactic. Do vậy luôn phải cho giảm đau và tránh buồn phiền.\n- Một số thuốc có thể làm ức chế trung tâm hô hấp và ức chế cơ tim của thai (như barbiturat, dolargan…)\n.5.2. Sự đáp ứng của thai đối với các kích thích\nHậu quả chung của tất cả những kích thích trên là giảm oxy ở thai, dẫn đến những biểu hiện thay đổi về chuyển hoá và tim mạch.\n5.2.1. Những thay đổi về chuyển hoá do giảm oxy gây nhiễm toan chuyển hoá\nGlycogen của gan sẽ hoạt hoá và chuyển hoá thành năng lượng. Sự chuyển hoá này luôn trong tình trạng kỵ khí, chuyển thành lactate và CO2. Với mức độ thiếu oxy vừa phải, thai có trọng lượng trung bình có thể thích ứng với tình trạng thiếu oxy này bằng cách sử dụng glycogen của thai. Ngược lại, đối với thai kém phát triển, không có dự trữ sẽ chịu đựng kém vì thiếu oxy.\n5.2.2. Sự thay đổi về tim mạch\nKhi thai có tình trạng giảm oxy người ta nhận thấy trong giai đoạn sớm, có sự tăng huyết áp, tăng nhịp tim thai do tác động của hệ adrenergic. Trong giai đoạn muộn, nhịp tim giảm do nhiễm toan.\nPhân bố lại những lượng máu riêng cho từng vùng, sự phân bố này nhằm bảo vệ những cơ quan quan trọng của thai, như tăng lượng máu cho não, tim, thượng thận và giảm lưu lượng máu tới hệ tiêu hoá, lách, xương, da, cơ, phổi. Do tình trạng ưu thán (tăng CO2) phối hợp giảm oxy kéo theo sự giãn mạch não đưa đến ứ trệ tuần hoàn gây phù não làm tăng thiếu máu não, giải phóng thromboplastine tổ chức gây hội chứng xuất huyết não ở trẻ sơ sinh.\n5.2.3. Trong chuyển dạ\nTrong thời kỳ xoá mở cổ tử cung nhịp tim thai cơ bản nằm trong khoảng 120 - 160 lần/phút, nhịp tim thai có thể nhanh trong vài chục giây nhưng không bao giờ chậm không có lý do. Sự ổn định của nhịp tim thai trong chuyển dạ là bằng chứng không có nguy cơ đối với thai.\nTrong lúc sổ thai: nhịp tim thai giảm chậm trong 1/3 trường hợp.\nLúc sinh:\n- pH = 7,25\n- P02 = 10mmHg\n- PC02 = 45mmHg\n- Tăng catecholamin, cortisol, ACTH và TSH, angiotensin, renin, vasopressin trong máu. Sự thay đổi nội tiết này dường như có lợi đối với sự thích ứng của thai sau sinh.\n6. SỰ THÍCH ỨNG CỦA TRẺ SƠ SINH SAU ĐẺ\nKhi thai ở trong tử cung các cơ quan thai nhi còn trong tình trạng nghỉ ngơi hoặc chưa hoạt động hoàn toàn như phổi, hệ tiêu hoá, thận… (những trao đổi khí và chuyển hoá diễn ra ở rau thai).\n- Sự duy trì thân nhiệt của thai được bảo đảm bởi sự truyền nhiệt của mẹ, sự chuyển hóa của thai, rau và nước ối.\n- Tuần hoàn vận hành theo cách riêng do sức cản ngoại vi thấp vì:\n+ Tuần hoàn rau thai.\n+ Mỗi tâm thất chỉ chịu một phần của cung lượng tim.\n+ Có 3 nối tắt riêng (ống Arantius, lỗ Botal, ống động mạch).\nNgay sau sinh, trẻ sơ sinh phải thích hợp với cuộc sống mới, các thích ứng ở phổi, tim mạch xảy ra ngay tức thì để đảm bảo cuộc sống. Những thích ứng khác ở tiêu hoá, thân nhiệt, năng lượng, thận được thiết lập chậm hơn.\n6.1. Hệ thống hô hấp\nKhi sổ thai ngực của thai nhi bị chèn ép, điều đó loại bỏ một phần dịch ở đường hô hấp trên (khoảng 20 ml), sau đó lồng ngực lấy lại thể tích của nó đưa vào phổi một lượng không khí lớn khởi phát phản xạ hô hấp. Với điểm khởi phát là hầu, không khí tràn vào phổi đẩy tiếp dịch phổi ra, không khí trộn lẫn với các dịch tiết tạo thành bọt khí phủ phế nang làm thuận lợi duy trì một thể tích khí trong phế nang. Áp lực mạnh của sự thở ra đẩy dịch tiết trong nhu mô phổi về phía khoảng kẽ và hệ thống bạch huyết.\nSự bài tiết adrenalin của thai trong lúc đẻ góp phần làm giảm sự bài tiết dịch ở phổi và làm thuận lợi cho sự hấp thu dịch.\nKhi tạo ra trong phổi một áp lực vượt quá 40 - 100 cmH2O có thể gây vỡ phế nang, hoặc tràn khí màng phổi.\n6.2. Hệ thống tuần hoàn\nHô hấp đầu tiên kéo theo sự giãn mạch.\n- Hạ thấp PC02 và tăng P02 đưa tới tăng lưu lượng máu phổi.\n- Cắt đứt tuần hoàn rau tăng sức cản đại tuần hoàn.\nÁp lực trong động mạch phổi trở nên thấp hơn áp lực động mạch chủ, động mạch đảo ngược và trở thành trái phải, máu qua từ động mạch chủ đến động mạch phổi.\n6.3. Hệ tiêu hoá\nPhản xạ mút kích thích sự xuống sữa non, cung cấp năng lượng, các yếu tố miễn dịch.\n6.4. Thận\nHuyết áp động mạch tăng, lưu lượng máu động mạch thận tăng, tăng lọc cầu thận.\n6.5. Quân bình năng lượng\nGlucose cung cấp bởi rau bị cắt đứt nên chuyển sang sử dụng glucogen của gan, hủy lipid bằng oxy hoá mỡ xám của trẻ sơ sinh.\n\n\n6.6. Sự thích hợp điều hoà thân nhiệt\nSự co mạch ở da, tăng chuyển hoá nhằm bảo đảm sưởi ấm. Sự sinh nhiệt bởi oxy hoá mỡ xám (tập trung chủ yếu ở vùng tầng sinh môn và hai mạn sườn của trẻ sơ sinh trong vài ngày đầu để cung cấp năng lượng đầu tiên cho trẻ). Trẻ  sơ sinh bị nhiễm lạnh rất nhanh, nếu để trần hoặc làm ướt thân nhiệt bị giảm 20 trong 30 phút. Những trẻ bị ngạt hạ thân nhiệt xảy ra nhanh hơn.\n6.7. Thay đổi thần kinh\nSau sinh, hệ thần kinh thực vật chiếm ưu thế nên trẻ sơ sinh ăn ngủ, cử động không ý thức, tuỳ thuộc bữa bú và hô hấp.\nCâu hỏi:\n1: Trình bày định nghĩa của chuyển dạ và các nguyên nhân gây chuyển dạ\n2. Trình bày các giai đoạn của chuyển dạ đẻ?\n3. Mô tả đặc điểm cơn co tử cung trong chuyển dạ đẻ?\n4.  Mô tả sự thay đổi về phía mẹ dưới tác dụng của cơn co tử cung khi chuyển dạ?\n5. Mô tả sự thay đổi về phía thai và phần phụ của thai trong chuyển dạ đẻ?\n6. Trình bày chẩn đoán chuyển dạ và theo dõi chuyển dạ đẻ?\nCHẨN ĐOÁN NGÔI - THẾ - KIỂU THẾ\n\nMục tiêu học tập\nTrình bày định nghĩa ngôi, thế, kiểu thế  và nêu các mốc của ngôi thai.", "priority": "Cao (Trọng tâm BSNT)"}, {"id": "SK-08", "chapter": "Chương 1. Sản thường", "folder": "01_San_thuong", "title": "Chẩn đoán ngôi, thế, kiểu thế", "author": "Ths. Đặng Thị Việt Hằng", "word_count": 1639, "line_count": 161, "key_numbers": [], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["Trình bày các phương pháp để chẩn đoán ngôi, thế, kiểu thế."], "bullets": []}, {"heading": "3. Kể tên các ngôi có thể sinh đường âm đạo và các ngôi không thể sinh đường âm đạo", "paragraphs": ["Vào thời điểm bắt đầu chuyển dạ, vị trí của thai nhi trong tử cung là yếu tố quan trọng trong tiên lượng cuộc đẻ. Bốn thành tố: chiều, ngôi, độ cúi, thế và kiểu thế được sử dụng để mô tả tư thế của thai nhi so với người mẹ. Gần đến ngày sinh hoặc trong khi chuyển dạ, thông thường thai nhi nằm dọc tử cung (chiều của thai), đầu xuống dưới (ngôi thai), chỏm cúi gập vào cổ (mức độ cúi của thai), chẩm nằm về phía trước trong tiểu khung (kiểu thế).Có khoảng 5% các trường hợp vị trí thai không theo hình thái thông thường và được gọi là ngôi thai bất thường. Ngôi thai bất thường đi kèm theo việc tăng nguy cơ cho cả mẹ và thai nhi.", "Việc khám ngoài giúp cho chúng ta nghĩ đến ngôi, thế và kiểu thế gì, nhưng muốn chẩn đoán xác định cần phải dựa vào mốc của ngôi trình diện trước mặt phẳng eo trên thông qua việc khám trong khi cổ tử cung đã mở."], "bullets": []}, {"heading": "1.1.1 Ngôi:", "paragraphs": ["Là phần thai nhi trình diện trước eo trên trong khi có thai hoặc khi chuyển dạ.", "Có hai loại ngôi cơ bản sau:", "Độ cúi bình thường của ngôi chỏm trong cuộc chuyển dạ là đầu cúi hoàn toàn, cằm của thai nhi gập sát vào phần trên của ngực để cho phần chẩm được trình diện trước. Nếu đầu không cúi hết sẽ đưa đến tình trạng ngôi trán và cổ ngửa ra sẽ đưa đến tình trạng ngôi mặt.", "Hình 1: Các loại ngôi đầu", "(Nguồn:https://www.pinterest.ph/pin/)", "Hình 2: Các loại ngôi mông", "(Nguồn: https://www.liberaldictionary.com/breech-baby)", "Ngoài ra còn có thể gặp ngôi phức hợp."], "bullets": ["- Ngôi dọc:  khi trục dọc của thai nhi cùng trục với trục tử cung của người mẹ. Có hai loại ngôi dọc:", "+ Ngôi đầu: đầu thai nhi trình diện trước eo trên. Ngôi đầu được chia ra thành các loại: ngôi chỏm (chẩm), ngôi trán và ngôi mặttuỳ thuộc vào mức độ cúi (flexion) của đầu thai nhi.", "+ Ngôi mông (ngôi ngược): mông thai nhi trình diện trước eo trên. Ngôi mông được chia thành: ngôi mông hoàn toàn hay còn gọi là ngôi mông đủ (khớp háng và gối gấp, mông trình diện), ngôi mông không hoàn toàn, còn gọi là ngôi mông thiếu (kiểu mông, kiểu đầu gối và kiểu chân).", "- Ngôi ngang: khi trục dọc của thai nhi vuông góc hoặc bắt chéo với trục tử cung của người mẹ."]}, {"heading": "1.1.2. Mốc của ngôi:", "paragraphs": ["Mỗi loại ngôi thai có một điểm mốc, dựa vào điểm mốc đó để phân biệt các loại ngôi thai."], "bullets": ["+ Ngôi chỏm: mốc là xương chẩm", "+ Ngôi mặt: mốc là mỏm cằm", "+ Ngôi trán: mốc là gốc mũi", "+ Ngôi ngang: mốc là mỏm vai", "+ Ngôi mông: mốc là đỉnh của xương cùng."]}, {"heading": "1.2. Thế", "paragraphs": ["Thế là tương quan giữa điểm mốc của ngôi thai với bên phải hoặc bên trái của người mẹ hay nói rõ hơn là bên phải hoặc bên trái của khung chậu người mẹ. Vậy mỗi ngôi có hai thế: thế phải và thế trái."], "bullets": []}, {"heading": "1.3. Kiểu thế", "paragraphs": ["Kiểu thế là mối tương quan giữa điểm mốc của ngôi thai với vị trí trước-sau của khung chậu người mẹ."], "bullets": []}, {"heading": "1.3.1. Kiểu thế lọt", "paragraphs": ["Khi phần thai nhi qua mặt phẳng eo trên lọt vào trong tiểu khung, mốc của thai có thể nằm ở phía Trước/Sau/Ngang, bên Trái/Phải và tạo ra 6 kiểu thế lọt cho một ngôi thai.", "ROA: Chẩm - chậu phải trước", "ROT: Chẩm - chậu phải ngang", "ROP: Chẩm - chậu phải sau", "LOA: Chẩm - chậu trái trước", "LOP: Chẩm - chậu trái sau", "LOT: Chẩm - chậu trái ngang", "Hình 3. 6 kiểu thế lọt của ngôi chỏm", "(Nguồn:https://doulatraining.ca/topic/)"], "bullets": []}, {"heading": "1.3.2. Kiểu thế sổ", "paragraphs": ["Khi ngôi đã xuống eo giữa và eo dưới thì tuỳ theo cơ chế đẻ và điểm mốc của ngôi so với khung chậu của người mẹ ta có2 kiểu thế sổ sau đây:"], "bullets": ["- Ngôi chỏm có hai kiểu thế sổ:đó là chẩm trước (chẩm ở phía xương mu) và chẩm sau (chẩm ở phía xương cùng).", "- Ngôi mặt có một kiểu thế sổ đó là cằm trước và một kiểu thế không sổ được đó là cằm sau.", "- Ngôi mông có hai kiểu thế sổ đó là cùng ngang trái và cùng ngang phải.", "- Ngôi trán và ngôi ngang không có kiểu thế sổ vì không lọt được."]}, {"heading": "2. CHẨN ĐOÁN NGÔI, THẾ, KIỂU THẾ", "paragraphs": ["Có nhiều phương pháp thăm khám để chẩn đoán ngôi, thế và kiểu thế: Sờ nắn, kết hợp nghe tim thai, khám âm đạo, siêu âm."], "bullets": []}, {"heading": "2.1. Sờ nắn bụng", "paragraphs": ["Để biết vị trí các phần của thai nhi, việc sờ nắn có vai trò quan trọng trong việc chẩn đoán ngôi thế. Thai phụ nằm ngửa, hai chân chống để đùi tạo với mặt giường một góc 450, làm các cơ bụng chùng dễ nắn hơn. Áp dụng bốn thủ thuật của Léopold, người khám đứng bên phải sản phụ, nắn lần lượt từ thủ thuật 1, 2, 3; đến thủ thuật 4 thì xoay nhìn về phía chân của sản phụ.", "Thủ thuật 1              Thủ thuật 2 Thủ thuật 3            Thủ thuật 4", "Hình 4. Khám 4 thủ thuật Léopold"], "bullets": ["- Thủ thuật thứ nhất: nắn cực trên (đáy tử cung) để biết ở đáy tử cung là đầu hay là mông của thai nhi. Nếu sờ được một khối có chỗ rắn chỗ mềm, không tròn, ít di động đó là mông. Nếu sờ được một khối rắn chắc, tròn đều, dễ di động có dạng đá cục đó là đầu của thai nhi.", "- Thủ thuật thứ hai: nắn nhẹ nhàng nhưng sâu hai bên bụng, để xác định bên nào là lưng, bên nào là chi của thai nhi. Nếu sờ được một diện phẳng, rắn, đều đó là lưng; đối diện với lưng nắn thấy lổn nhổn những khối to nhỏ khác nhau di động dễ, có khi nắn mạnh thấy phần thai nhi mất đi rồi hiện lại đó là tay chân của thai nhi.", "-Thủ thuật thứ ba: Nắn cực dưới để biết có đầu hay mông, dựa vào các tính chất như nắn cực trên của tử cung. Nếu không sờ thấy gì ta nói hạ vị rỗng và xác định đó là trường hợp ngôi ngang.", "- Thủ thuật thứ bốn: Người khám xoay mặt về phía chân của sản phụ:", "+ Dùng một bàn tay ấn sâu xuống bờ trên xương vệ, khi ngôi còn cao thì bàn tay người khám ấn xuống dễ.", "+ Dùng hai bàn tay ấn dọc hai bên cực dưới của tử cung. Khi đầu chưa lọt hai bàn tay có hướng hội tụ vào nhau, khi đầu đã lọt hai bàn tay hướng ra ngoài không thể chạm vào nhau được."]}, {"heading": "2.2. Nghe tim thai", "paragraphs": ["Tim thai được nghe rõ ở lưng của thai nhi, tự nó không giúp ta chẩn đoán được ngôi, thế, kiểu thế, nhưng giúp hỗ trợ cho những kết quả tìm thấy khi nắn bụng.", "Ví dụ: Trong ngôi chỏm thì tim thai nghe rõ ở dưới rốn của bà mẹ và  tim thai nghe rõ ở bên nào thì thế ở bên ấy, trong khi đó nếu là ngôi mông sẽ nghe rõ tim thai ở ngang hoặc phía trên rốn."], "bullets": []}, {"heading": "2.3. Khám âm đạo", "paragraphs": ["Trong lúc chuyển dạ, cổ tử cung đã mở một phần hoặc toàn bộ, khám âm đạo sẽ cung cấp cho ta các yếu tố hữu ích giúp ta chẩn đoán chính xác ngôi - thế - kiểu thế.", "Trong ngôi chỏm phải xác định rãnh liên đỉnh và các thóp, nhất là thóp sau ở đâu so với các điểm mốc của khung chậu của người mẹ. Trong ngôi mặt cần xác định cho được vị trí của cằm, trong ngôi mông cần xác định cho được vị trí đỉnh xương cùng và hai ụ ngồi của thai nhi hoặc chân của thai nhi nếu là ngôi mông kiểu ngồi xổm."], "bullets": []}, {"heading": "2.4. Siêu âm", "paragraphs": ["Một biện pháp an toàn, chính xác, được sử dụng trong những trường hợp khó như sản phụ quá mập, thành bụng quá dày quá rắn chắc hoặc rau bám trước. Một đôi khi cũng phải sử dụng đến X quang để xác định vị trí, tư thế hoặc hình thể của thai nhi; song từ  khi có siêu âm vai trò của X quang ngày càng ít."], "bullets": []}, {"heading": "Câu hỏi:", "paragraphs": ["Trình bày định nghĩa ngôi, thế, kiểu thế  và nêu các mốc của ngôi thai?", "Trình bày các phương pháp để chẩn đoán ngôi, thế, kiểu thế?"], "bullets": []}, {"heading": "3. Kể tên các ngôi có thể sinh đường âm đạo và các ngôi không thể sinh đường âm đạo?", "paragraphs": ["BẢNG TÓM TẮT NGÔI THẾ KIỂU THẾ", "NGÔI", "MỐC", "THẾ", "KIỂU THẾ-LỌT", "KIỂU THẾ SỔ", "Chỏm", "Xương Chẩm", "Trái", "Chẩm trái trước", "Chẩm trái ngang", "Chẩm trái sau", "Chẩm trước", "Chẩm sau", "Phải", "Chẩm phải trước", "Chẩm phải ngang", "Chẩm phải sau", "Mông", "Đỉnh xương cùng", "Trái", "Cùng trái trước", "Cùng trái sau", "Cùng ngang trái", "Cùng ngang phải", "Phải", "Cùng phải trước", "Cùng phải sau", "Mặt", "Cằm", "Trái", "Cằm trái trước", "Cằm trái ngang", "Cằm trái sau", "Cằm trước", "Phải", "Cằm phải trước", "Cằm phải ngang", "Cằm phải sau", "Trán", "Gốc mũi", "Trái", "Phải", "Không có", "Không có kiểu thế sổ", "Ngang", "Mỏm vai", "Trái", "Phải", "Không có", "Không có kiểu thế sổ"], "bullets": []}], "raw_text": "Trình bày các phương pháp để chẩn đoán ngôi, thế, kiểu thế.\n3. Kể tên các ngôi có thể sinh đường âm đạo và các ngôi không thể sinh đường âm đạo\n\nVào thời điểm bắt đầu chuyển dạ, vị trí của thai nhi trong tử cung là yếu tố quan trọng trong tiên lượng cuộc đẻ. Bốn thành tố: chiều, ngôi, độ cúi, thế và kiểu thế được sử dụng để mô tả tư thế của thai nhi so với người mẹ. Gần đến ngày sinh hoặc trong khi chuyển dạ, thông thường thai nhi nằm dọc tử cung (chiều của thai), đầu xuống dưới (ngôi thai), chỏm cúi gập vào cổ (mức độ cúi của thai), chẩm nằm về phía trước trong tiểu khung (kiểu thế).Có khoảng 5% các trường hợp vị trí thai không theo hình thái thông thường và được gọi là ngôi thai bất thường. Ngôi thai bất thường đi kèm theo việc tăng nguy cơ cho cả mẹ và thai nhi.\nViệc khám ngoài giúp cho chúng ta nghĩ đến ngôi, thế và kiểu thế gì, nhưng muốn chẩn đoán xác định cần phải dựa vào mốc của ngôi trình diện trước mặt phẳng eo trên thông qua việc khám trong khi cổ tử cung đã mở.\n\n1. ĐỊNH NGHĨA\n1.1. Ngôi\n1.1.1 Ngôi:\nLà phần thai nhi trình diện trước eo trên trong khi có thai hoặc khi chuyển dạ.\nCó hai loại ngôi cơ bản sau:\n- Ngôi dọc:  khi trục dọc của thai nhi cùng trục với trục tử cung của người mẹ. Có hai loại ngôi dọc:\n+ Ngôi đầu: đầu thai nhi trình diện trước eo trên. Ngôi đầu được chia ra thành các loại: ngôi chỏm (chẩm), ngôi trán và ngôi mặttuỳ thuộc vào mức độ cúi (flexion) của đầu thai nhi.\nĐộ cúi bình thường của ngôi chỏm trong cuộc chuyển dạ là đầu cúi hoàn toàn, cằm của thai nhi gập sát vào phần trên của ngực để cho phần chẩm được trình diện trước. Nếu đầu không cúi hết sẽ đưa đến tình trạng ngôi trán và cổ ngửa ra sẽ đưa đến tình trạng ngôi mặt.\n\nHình 1: Các loại ngôi đầu\n(Nguồn:https://www.pinterest.ph/pin/)\n+ Ngôi mông (ngôi ngược): mông thai nhi trình diện trước eo trên. Ngôi mông được chia thành: ngôi mông hoàn toàn hay còn gọi là ngôi mông đủ (khớp háng và gối gấp, mông trình diện), ngôi mông không hoàn toàn, còn gọi là ngôi mông thiếu (kiểu mông, kiểu đầu gối và kiểu chân).\n\nHình 2: Các loại ngôi mông\n(Nguồn: https://www.liberaldictionary.com/breech-baby)\n- Ngôi ngang: khi trục dọc của thai nhi vuông góc hoặc bắt chéo với trục tử cung của người mẹ.\nNgoài ra còn có thể gặp ngôi phức hợp.\n1.1.2. Mốc của ngôi:\nMỗi loại ngôi thai có một điểm mốc, dựa vào điểm mốc đó để phân biệt các loại ngôi thai.\n+ Ngôi chỏm: mốc là xương chẩm\n+ Ngôi mặt: mốc là mỏm cằm\n+ Ngôi trán: mốc là gốc mũi\n+ Ngôi ngang: mốc là mỏm vai\n+ Ngôi mông: mốc là đỉnh của xương cùng.\n1.2. Thế\nThế là tương quan giữa điểm mốc của ngôi thai với bên phải hoặc bên trái của người mẹ hay nói rõ hơn là bên phải hoặc bên trái của khung chậu người mẹ. Vậy mỗi ngôi có hai thế: thế phải và thế trái.\n\n1.3. Kiểu thế\nKiểu thế là mối tương quan giữa điểm mốc của ngôi thai với vị trí trước-sau của khung chậu người mẹ.\n1.3.1. Kiểu thế lọt\nKhi phần thai nhi qua mặt phẳng eo trên lọt vào trong tiểu khung, mốc của thai có thể nằm ở phía Trước/Sau/Ngang, bên Trái/Phải và tạo ra 6 kiểu thế lọt cho một ngôi thai.\nROA: Chẩm - chậu phải trước\nROT: Chẩm - chậu phải ngang\nROP: Chẩm - chậu phải sau\nLOA: Chẩm - chậu trái trước\nLOP: Chẩm - chậu trái sau\nLOT: Chẩm - chậu trái ngang\nHình 3. 6 kiểu thế lọt của ngôi chỏm\n(Nguồn:https://doulatraining.ca/topic/)\n1.3.2. Kiểu thế sổ\nKhi ngôi đã xuống eo giữa và eo dưới thì tuỳ theo cơ chế đẻ và điểm mốc của ngôi so với khung chậu của người mẹ ta có2 kiểu thế sổ sau đây:\n- Ngôi chỏm có hai kiểu thế sổ:đó là chẩm trước (chẩm ở phía xương mu) và chẩm sau (chẩm ở phía xương cùng).\n- Ngôi mặt có một kiểu thế sổ đó là cằm trước và một kiểu thế không sổ được đó là cằm sau.\n- Ngôi mông có hai kiểu thế sổ đó là cùng ngang trái và cùng ngang phải.\n- Ngôi trán và ngôi ngang không có kiểu thế sổ vì không lọt được.\n2. CHẨN ĐOÁN NGÔI, THẾ, KIỂU THẾ\nCó nhiều phương pháp thăm khám để chẩn đoán ngôi, thế và kiểu thế: Sờ nắn, kết hợp nghe tim thai, khám âm đạo, siêu âm.\n2.1. Sờ nắn bụng\nĐể biết vị trí các phần của thai nhi, việc sờ nắn có vai trò quan trọng trong việc chẩn đoán ngôi thế. Thai phụ nằm ngửa, hai chân chống để đùi tạo với mặt giường một góc 450, làm các cơ bụng chùng dễ nắn hơn. Áp dụng bốn thủ thuật của Léopold, người khám đứng bên phải sản phụ, nắn lần lượt từ thủ thuật 1, 2, 3; đến thủ thuật 4 thì xoay nhìn về phía chân của sản phụ.\n- Thủ thuật thứ nhất: nắn cực trên (đáy tử cung) để biết ở đáy tử cung là đầu hay là mông của thai nhi. Nếu sờ được một khối có chỗ rắn chỗ mềm, không tròn, ít di động đó là mông. Nếu sờ được một khối rắn chắc, tròn đều, dễ di động có dạng đá cục đó là đầu của thai nhi.\n- Thủ thuật thứ hai: nắn nhẹ nhàng nhưng sâu hai bên bụng, để xác định bên nào là lưng, bên nào là chi của thai nhi. Nếu sờ được một diện phẳng, rắn, đều đó là lưng; đối diện với lưng nắn thấy lổn nhổn những khối to nhỏ khác nhau di động dễ, có khi nắn mạnh thấy phần thai nhi mất đi rồi hiện lại đó là tay chân của thai nhi.\n-Thủ thuật thứ ba: Nắn cực dưới để biết có đầu hay mông, dựa vào các tính chất như nắn cực trên của tử cung. Nếu không sờ thấy gì ta nói hạ vị rỗng và xác định đó là trường hợp ngôi ngang.\n- Thủ thuật thứ bốn: Người khám xoay mặt về phía chân của sản phụ:\n+ Dùng một bàn tay ấn sâu xuống bờ trên xương vệ, khi ngôi còn cao thì bàn tay người khám ấn xuống dễ.\n+ Dùng hai bàn tay ấn dọc hai bên cực dưới của tử cung. Khi đầu chưa lọt hai bàn tay có hướng hội tụ vào nhau, khi đầu đã lọt hai bàn tay hướng ra ngoài không thể chạm vào nhau được.\n\nThủ thuật 1              Thủ thuật 2 Thủ thuật 3            Thủ thuật 4\nHình 4. Khám 4 thủ thuật Léopold\n2.2. Nghe tim thai\nTim thai được nghe rõ ở lưng của thai nhi, tự nó không giúp ta chẩn đoán được ngôi, thế, kiểu thế, nhưng giúp hỗ trợ cho những kết quả tìm thấy khi nắn bụng.\nVí dụ: Trong ngôi chỏm thì tim thai nghe rõ ở dưới rốn của bà mẹ và  tim thai nghe rõ ở bên nào thì thế ở bên ấy, trong khi đó nếu là ngôi mông sẽ nghe rõ tim thai ở ngang hoặc phía trên rốn.\n\n2.3. Khám âm đạo\nTrong lúc chuyển dạ, cổ tử cung đã mở một phần hoặc toàn bộ, khám âm đạo sẽ cung cấp cho ta các yếu tố hữu ích giúp ta chẩn đoán chính xác ngôi - thế - kiểu thế.\nTrong ngôi chỏm phải xác định rãnh liên đỉnh và các thóp, nhất là thóp sau ở đâu so với các điểm mốc của khung chậu của người mẹ. Trong ngôi mặt cần xác định cho được vị trí của cằm, trong ngôi mông cần xác định cho được vị trí đỉnh xương cùng và hai ụ ngồi của thai nhi hoặc chân của thai nhi nếu là ngôi mông kiểu ngồi xổm.\n2.4. Siêu âm\nMột biện pháp an toàn, chính xác, được sử dụng trong những trường hợp khó như sản phụ quá mập, thành bụng quá dày quá rắn chắc hoặc rau bám trước. Một đôi khi cũng phải sử dụng đến X quang để xác định vị trí, tư thế hoặc hình thể của thai nhi; song từ  khi có siêu âm vai trò của X quang ngày càng ít.\n\nCâu hỏi:\nTrình bày định nghĩa ngôi, thế, kiểu thế  và nêu các mốc của ngôi thai?\nTrình bày các phương pháp để chẩn đoán ngôi, thế, kiểu thế?\n3. Kể tên các ngôi có thể sinh đường âm đạo và các ngôi không thể sinh đường âm đạo?\n\n\n\nBẢNG TÓM TẮT NGÔI THẾ KIỂU THẾ\nNGÔI\nMỐC\nTHẾ\nKIỂU THẾ-LỌT\nKIỂU THẾ SỔ\n\n\n\nChỏm\n\n\n\nXương Chẩm\nTrái\nChẩm trái trước\nChẩm trái ngang\nChẩm trái sau\n\n\nChẩm trước\nChẩm sau\n\n\n\n\nPhải\nChẩm phải trước\nChẩm phải ngang\nChẩm phải sau\n\n\nMông\nĐỉnh xương cùng\nTrái\nCùng trái trước\nCùng trái sau\n\nCùng ngang trái\nCùng ngang phải\n\n\n\nPhải\nCùng phải trước\nCùng phải sau\n\n\nMặt\nCằm\nTrái\nCằm trái trước\nCằm trái ngang\nCằm trái sau\n\n\nCằm trước\n\n\n\n\nPhải\nCằm phải trước\nCằm phải ngang\nCằm phải sau\n\n\nTrán\nGốc mũi\nTrái\nPhải\nKhông có\nKhông có kiểu thế sổ\n\nNgang\nMỏm vai\nTrái\nPhải\nKhông có\nKhông có kiểu thế sổ", "priority": "Trung bình"}, {"id": "SK-09", "chapter": "Chương 1. Sản thường", "folder": "01_San_thuong", "title": "Ngôi chỏm và cơ chế đẻ ngôi chỏm", "author": "Ths. Đặng Thị Việt Hằng", "word_count": 1990, "line_count": 122, "key_numbers": ["11 cm", "12 cm", "3 cm", "3 tháng", "500ml", "60cm", "7cm", "9 cm", "9,5 cm"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["NGÔI CHỎM VÀ CƠ CHẾ ĐẺ NGÔI CHỎM", "Ths. Đặng Thị Việt Hằng"], "bullets": []}, {"heading": "1. ĐẠI CƯƠNG", "paragraphs": ["Ngôi chỏm là ngôi dọc, đầu ở dưới, trục của thai nhi trùng với trục của tử cung. Đầu thai nhi cúi tốt với xương chẩm trình diện trước eo trên.", "Ngôi chỏm chiếm 95% trường hợp các ngôi thai. Điểm mốc của ngôi chỏm là xương chẩm. Đường kính lọt của ngôi chỏm là đường kính hạ chẩm- thóp trước (bình thường 9,5 cm). Ngôi chỏm có thể lọt qua eo trên khung chậu người mẹ theo 2 đường kính chéo phải và trái (chủ yếu là đường kính chéo trái, chiếm 95%). Một số trường hợp thai nhỏ hoặc thai chết có thể lọt qua đường kính ngang.", "Ngôi chỏm có 2 thế (phải và trái), tương ứng với 6 kiểu thế lọt (chẩm trái trước, chẩm trái ngang, chẩm trái sau, chẩm phải trước, chẩm phải ngang, chẩm phải sau) và 2 kiểu thế sổ (chẩm trước và chẩm sau)."], "bullets": []}, {"heading": "2. SỰ BÌNH CHỈNH CỦA NGÔI CHỎM", "paragraphs": ["Bình thường thai nhi nằm khớp với buồng tử cung, nghĩa là trục của thai nhi và trục của tử cung là một. Nhưng không phải ngay từ đầu thai nhi đã nằm ở tư thế đó, trong 3 tháng đầu thai còn nhỏ, nằm trong buồng ối rộng, nhiều nước, nên thai không có một vị trí rõ ràng. Đến 3 tháng giữa, thai nằm dọc, đầu thai nhi to nằm ở đáy tử cung, mông nhỏ hơn ở phía dưới tử cung. Trong 3 tháng cuối, mông phát triển nhiều, cộng thêm 2 chi dưới trở thành cực to nên mông lại quay lên trên về phía đáy tử cung, đầu nhỏ hơn nên lại quay xuống dưới, khớp với eo tử cung.", "Sở dĩ thai nhi nằm theo tư thế đó là vì giữa thai nhi và tử cung có một sự bình chỉnh theo qui luật Pajot: “Khi một vật thể đặc nằm trong một vật đặc khác, nếu vật ngoài có thể co giãn được và vật trong cũng có những vận động riêng, nếu các diện tiếp xúc giữa hai vật đều trơn và nhẵn, thì vật đặc ở trong sẽ luôn luôn bình chỉnh hình thể và thể tích của nó, để ăn khớp với hình thể và dung tích của vật ở ngoài”. Chúng ta biết, tử cung hình trứng, cực to ở đáy tử cung, cực nhỏ là ở eo tử cung, và luôn luôn có những cơn co bóp và những thời gian nghỉ. Thai nhi cũng hình trứng và có những cử động riêng. Các diện tiếp xúc giữa thai nhi và tử cung đều trơn nhờ có nước ối và chất gây của thai nhi, vì vậy thai nhi sẽ bình chỉnh hình thể và thể tích của nó để ăn khớp với buồng tử cung, nghĩa là thai nhi sẽ khớp cực to của mình là mông với đáy tử cung, cực nhỏ là đầu với phần dưới của tử cung.", "Như vậy, tư thế thai nhi trong buồng tử cung phụ thuộc vào 3 yếu tố: Hình thể tử cung, hình thể thai nhi, sự vận động của thai nhi và tử cung. Nếu một trong 3 yếu tố thay đổi, thai nhi có thể nằm theo một tư thế bất thường."], "bullets": []}, {"heading": "2.1. Điều kiện về mẹ", "paragraphs": [], "bullets": ["- Khung chậu bình thường về giải phẫu", "- Thành bụng, các thành phần đáy chậu tốt", "- Tử cung bình thường"]}, {"heading": "2.2. Điều kiện về thai nhi", "paragraphs": ["Thai sống và phát triển bình thường trong suốt thai kỳ"], "bullets": []}, {"heading": "2.3. Điều kiện về phần phụ của thai", "paragraphs": [], "bullets": ["- Nước ối trung bình khoảng 500ml", "- Cuống rau bình thường, dài 40-60cm", "- Rau bám ở mặt trước, mặt sau thân tử cung"]}, {"heading": "3. CHẨN ĐOÁN NGÔI CHỎM", "paragraphs": ["Dựa vào phương pháp hỏi, nhìn, nắn, nghe và khám âm đạo khi có chuyển dạ."], "bullets": []}, {"heading": "3.1. Chẩn đoán ngôi", "paragraphs": [], "bullets": ["- Hỏi: tiền sử các lần đẻ trước thường là ngôi chỏm.", "- Nhìn: tử cung có hình trứng.", "- Khám thủ thuật 1 và 3 của Léopold: cực dưới là một khối tròn, rắn, đều, di động (khi ngôi cao lỏng), đó là đầu. Cực trên nắn được một khối mềm, không đều, lớn hơn khối cực dưới, đó là mông của thai nhi."]}, {"heading": "3.2. Chẩn đoán thế", "paragraphs": [], "bullets": ["- Khám thủ thuật 2 của Léopold xác định được một diện phẳng tương ứng lưng của thai nhi. Lưng bên nào thì thế của thai nhi bên đó.", "- Đôi khi nắn được bướu chẩm (to hơn bướu trán) thường thấp cùng bên với lưng thai nhi."]}, {"heading": "3.3. Chẩn đoán kiểu thế", "paragraphs": ["Dựa vào 2 triệu chứng sau đây:"], "bullets": ["- Nếu nắn được 3/4 diện lưng tức là kiểu thế trước, ngược lại nắn diện lưng không rõ và nắn chi rõ hơn là kiểu thế sau.", "- Lúc chuyển dạ cổ tử cung đã mở, khám âm đạo sờ được xương chẩm (thóp sau) ở phía trước của khung chậu tức là kiểu thế trước và ngược lại nghĩa là kiểu thế sau."]}, {"heading": "4.1. Chẩn đoán độ cúi ngôi chỏm", "paragraphs": ["Hình 1. Xác định khớp dọc giữa và các thóp qua thăm khám âm đạo"], "bullets": ["- Ngôi chỏm cúi tốt: khám âm đạo lúc cổ tử cung đã xoá, mở sẽ sờ được thóp sau ở chính giữa mặt phẳng eo trên khung chậu hay ngay giữa cổ tử cung.", "- Ngôi chỏm cúi không tốt: lúc thóp sau ở một bên cổ tử cung. Có thể sờ được thóp trước lẫn thóp sau trong trường hợp ngôi chỏm cúi không tốt."]}, {"heading": "4.2. Chẩn đoán độ lọt của ngôi chỏm", "paragraphs": ["Chẩn đoán độ lọt của ngôi bằng cách", "Delle lấy vị trí 0 tương ứng với mức ngang 2 gai hông làm mốc, điểm thấp nhất của đầu thai nhi ngang mức này là đầu bắt đầu lọt. Từ vị trí này lên 1, 2, 3 cm tương ứng vị trí (-1),(-2),(-3) là đầu chưa lọt, còn từ vị trí 0 xuống 1, 2, 3 cm tương ứng vị trí (+1),(+2),(+3) là đầu đã lọt. Vị trí (-3) khi đầu cao lỏng, (+3) khi đầu lọt thấp.", "Hình 2: Phân loại độ lọt của Delle"], "bullets": ["- Khám ngoài:", "+ Nắn đầu: đặt năm ngón đặt trên khớp vệ, tuỳ số ngón tay chạm được đến đầu thai tính ra mức độ lọt của ngôi: cao (5 ngón), chúc (4 ngón), chặt (3 ngón), lọt cao (2 ngón), lọt vừa (1 ngón) và lọt thấp (không có ngón tay nào chạm vào đầu thai nữa).", "+ Nắn vai: có thể đánh giá đầu đã lọt qua eo trên hay chưa. Nếu đo khoảng cách từ mỏm vai của thai nhi đến bờ trên khớp mu của sản phụ: >7cm tức là đầu chưa lọt và ngược lại < 7cm có nghĩa là đầu đã lọt qua mặt phẳng eo trên.", "- Khám trong: dựa vào phân độ lọt của Delle."]}, {"heading": "5. CƠ CHẾ ĐẺ NGÔI CHỎM", "paragraphs": ["Quá trình chuyển dạ đẻ là một chuỗi các động tác thụ động của thai nhi, đặc biệt là của phần ngôi thai trình diện, trong quá trình thai đi xuống để sổ qua đường sinh dục", "Trong một cuộc đẻ, thai nhi dù là ngôi gì cũng diễn tiến qua 4 thì chính:", "Hình 3. Đường kính lớn của ngôi trùng vào mặt phẳng eo trên", "Hình 4. Ngôi di chuyển từ mặt phẳng eo trên đến mặt phẳng eo dưới."], "bullets": ["- Lọt : đường kính lớn của ngôi trùng vào mặt phẳng eo trên (hay phần thấp nhất của đầu ngang vị trí -0- hai gai ngồi)", "- Xuống: ngôi di chuyển trong ống đẻ từ mặt phẳng eo trên đến mặt phẳng eo dưới.", "- Quay: điểm mốc của ngôi hoặc chẩm (thóp sau) quay về phía xương mu hay xương cùng", "- Sổ: phần thai sổ ra ngoài âm hộ"]}, {"heading": "5.1.1. Thì lọt", "paragraphs": ["1 bướu xuống sau", "Kiểu lọt không đối xứng kiểu sau thường hay gặp hơn kiểu lọt không đối xứng kiểu trước.", "Hình 5. Đầu thai nhi cúi trong chuyển dạ"], "bullets": ["- Trước khi chuyển dạ: đầu cao, cúi không tốt (đường kính chẩm trán = 11 cm, trình diện trước eo trên).", "- Để chuẩn bị lọt, cơn co tử cung làm đầu cúi hơn để đường kính hạ chẩm - thóp trước = 9,5 cm song song với đường kính chéo trái của mặt phẳng eo trên (Khám âm đạo sờ được rãnh dọc của đầu trùng với đường kính này).", "- Lọt thực sự: quá trình diễn tiến từ từ khi đường kính của ngôi (đường kính lớn nhất) đi qua mặt phẳng eo trên. Đặc biệt có một số dấu hiệu lâm sàng khi đầu đã lọt như sau:", "+ Qua khám bụng, chỉ có thể sờ thấy 2/5 đầu thai nhi (xem bài biểu đồ chuyển dạ).", "+ Khám âm đạo cho thấy phần thấp nhất của chỏm nằm ngang mặt phẳng gai hông của thai phụ (vị trí - 0 -).", "- Kiểu lọt:", "+ Lọt đối xứng: 2 bướu đỉnh cùng xuống song song.", "+ Lọt không đối xứng: 1 bướu xuống trước"]}, {"heading": "5.1.2. Thì xuống", "paragraphs": ["Là giai đoạn di chuyển của ngôi từ mặt phẳng eo trên đến mặt phẳng eo dưới ra phía âm đạo, khi đầu thai nhi xuống thấp làm tầng sinh môn căng phồng."], "bullets": []}, {"heading": "5.1.3. Thì quay", "paragraphs": ["Khi đầu thai nhi chạm vào lớp cân cơ của đáy chậu thì đầu thai nhi bắt đầu quay để đường kính hạ chẩm - thóp trước (9,5 cm) trở thành song song với đường kính trước sau của eo dưới."], "bullets": ["- Ngôi chỏm kiểu thế trước thì đầu sẽ quay 45o ra trước.", "- Ngôi chỏm kiểu thế sau thì đầu sẽ quay 45o ra phía sau, hoặc có thể quay 135o ra trước."]}, {"heading": "5.1.4. Thì sổ", "paragraphs": ["Các yếu tố trên làm cho đầu chuẩn bị sổ.", "Hình 6. Sổ đầu"], "bullets": ["-  Sau khi xuống và quay, đầu sẽ cúi thêm do:", "+ Sức đẩy của cơn co tử cung", "+ Sức đẩy của cơn co thành bụng lúc rặn đẻ.", "+ Sức cản của đáy chậu.", "- Sổ thực sự: Khi hạ chẩm thai nhi đã cố định ở bờ dưới khớp mu, dưới tác động của sức rặn và cơn co tử cung đầu thai nhi ngửa dần, âm hộ nở to để lần lượt trán, mặt, cằm chui ra và hướng lên trên.", "- Sau khi sổ xong đầu thai nhi sẽ quay 45o để trở về kiểu thế cũ."]}, {"heading": "5.2. Đẻ vai", "paragraphs": ["Cơ chế không khác mấy so với đẻ đầu. Sau khi sổ đầu, đầu quay về vị trí cũ, đường kính lưỡng mõm vai thu hẹp từ 12 cm còn 9,5 cm và lọt theo đường kính chéo (nếu ngôi lọt theo đường kính chéo trái thì vai lọt theo đường kính chéo phải và ngược lại). Sau khi lọt, vai sổ theo đường kính trước sau của eo dưới, vai trước sổ đến bờ dưới cơ Delta thì dừng lại để vai sau sổ.", "Hình 7. Đẻ vai"], "bullets": []}, {"heading": "2.3. Đẻ mông", "paragraphs": ["Giống như cơ chế đẻ vai, đường kính lớn của mông là đường kính lưỡng ụ đùi bằng 9 cm (đường kính cùng chày 11 cm) sẽ thu nhỏ còn 9 cm. Do đó đẻ mông không phải là trường hợp khó."], "bullets": []}, {"heading": "Câu hỏi:", "paragraphs": ["Trình bày khái niệm và chẩn đoán ngôi chỏm?", "Trình bày chẩn đoán độ lọt ngôi chỏm và các dấu hiệu khi đầu đã lọt?", "Trình bày cơ chế đẻ ngôi chỏm?"], "bullets": []}], "raw_text": "NGÔI CHỎM VÀ CƠ CHẾ ĐẺ NGÔI CHỎM\nThs. Đặng Thị Việt Hằng\n\nMục tiêu\n1. Định nghĩa ngôi chỏm\n2. Mô tả các dấu hiệu chẩn đoán ngôi chỏm\n3. Mô tả cơ chế đẻ ngôi chỏm\n\n1. ĐẠI CƯƠNG\nNgôi chỏm là ngôi dọc, đầu ở dưới, trục của thai nhi trùng với trục của tử cung. Đầu thai nhi cúi tốt với xương chẩm trình diện trước eo trên.\nNgôi chỏm chiếm 95% trường hợp các ngôi thai. Điểm mốc của ngôi chỏm là xương chẩm. Đường kính lọt của ngôi chỏm là đường kính hạ chẩm- thóp trước (bình thường 9,5 cm). Ngôi chỏm có thể lọt qua eo trên khung chậu người mẹ theo 2 đường kính chéo phải và trái (chủ yếu là đường kính chéo trái, chiếm 95%). Một số trường hợp thai nhỏ hoặc thai chết có thể lọt qua đường kính ngang.\nNgôi chỏm có 2 thế (phải và trái), tương ứng với 6 kiểu thế lọt (chẩm trái trước, chẩm trái ngang, chẩm trái sau, chẩm phải trước, chẩm phải ngang, chẩm phải sau) và 2 kiểu thế sổ (chẩm trước và chẩm sau).\n2. SỰ BÌNH CHỈNH CỦA NGÔI CHỎM\nBình thường thai nhi nằm khớp với buồng tử cung, nghĩa là trục của thai nhi và trục của tử cung là một. Nhưng không phải ngay từ đầu thai nhi đã nằm ở tư thế đó, trong 3 tháng đầu thai còn nhỏ, nằm trong buồng ối rộng, nhiều nước, nên thai không có một vị trí rõ ràng. Đến 3 tháng giữa, thai nằm dọc, đầu thai nhi to nằm ở đáy tử cung, mông nhỏ hơn ở phía dưới tử cung. Trong 3 tháng cuối, mông phát triển nhiều, cộng thêm 2 chi dưới trở thành cực to nên mông lại quay lên trên về phía đáy tử cung, đầu nhỏ hơn nên lại quay xuống dưới, khớp với eo tử cung.\nSở dĩ thai nhi nằm theo tư thế đó là vì giữa thai nhi và tử cung có một sự bình chỉnh theo qui luật Pajot: “Khi một vật thể đặc nằm trong một vật đặc khác, nếu vật ngoài có thể co giãn được và vật trong cũng có những vận động riêng, nếu các diện tiếp xúc giữa hai vật đều trơn và nhẵn, thì vật đặc ở trong sẽ luôn luôn bình chỉnh hình thể và thể tích của nó, để ăn khớp với hình thể và dung tích của vật ở ngoài”. Chúng ta biết, tử cung hình trứng, cực to ở đáy tử cung, cực nhỏ là ở eo tử cung, và luôn luôn có những cơn co bóp và những thời gian nghỉ. Thai nhi cũng hình trứng và có những cử động riêng. Các diện tiếp xúc giữa thai nhi và tử cung đều trơn nhờ có nước ối và chất gây của thai nhi, vì vậy thai nhi sẽ bình chỉnh hình thể và thể tích của nó để ăn khớp với buồng tử cung, nghĩa là thai nhi sẽ khớp cực to của mình là mông với đáy tử cung, cực nhỏ là đầu với phần dưới của tử cung.\nNhư vậy, tư thế thai nhi trong buồng tử cung phụ thuộc vào 3 yếu tố: Hình thể tử cung, hình thể thai nhi, sự vận động của thai nhi và tử cung. Nếu một trong 3 yếu tố thay đổi, thai nhi có thể nằm theo một tư thế bất thường.\n2.1. Điều kiện về mẹ\n- Khung chậu bình thường về giải phẫu\n- Thành bụng, các thành phần đáy chậu tốt\n- Tử cung bình thường\n2.2. Điều kiện về thai nhi\nThai sống và phát triển bình thường trong suốt thai kỳ\n2.3. Điều kiện về phần phụ của thai\n- Nước ối trung bình khoảng 500ml\n- Cuống rau bình thường, dài 40-60cm\n- Rau bám ở mặt trước, mặt sau thân tử cung\n3. CHẨN ĐOÁN NGÔI CHỎM\nDựa vào phương pháp hỏi, nhìn, nắn, nghe và khám âm đạo khi có chuyển dạ.\n3.1. Chẩn đoán ngôi\n- Hỏi: tiền sử các lần đẻ trước thường là ngôi chỏm.\n- Nhìn: tử cung có hình trứng.\n- Khám thủ thuật 1 và 3 của Léopold: cực dưới là một khối tròn, rắn, đều, di động (khi ngôi cao lỏng), đó là đầu. Cực trên nắn được một khối mềm, không đều, lớn hơn khối cực dưới, đó là mông của thai nhi.\n3.2. Chẩn đoán thế\n- Khám thủ thuật 2 của Léopold xác định được một diện phẳng tương ứng lưng của thai nhi. Lưng bên nào thì thế của thai nhi bên đó.\n- Đôi khi nắn được bướu chẩm (to hơn bướu trán) thường thấp cùng bên với lưng thai nhi.\n3.3. Chẩn đoán kiểu thế\nDựa vào 2 triệu chứng sau đây:\n- Nếu nắn được 3/4 diện lưng tức là kiểu thế trước, ngược lại nắn diện lưng không rõ và nắn chi rõ hơn là kiểu thế sau.\n- Lúc chuyển dạ cổ tử cung đã mở, khám âm đạo sờ được xương chẩm (thóp sau) ở phía trước của khung chậu tức là kiểu thế trước và ngược lại nghĩa là kiểu thế sau.\n4. CHẨN ĐOÁN ĐỘ CÚI VÀ ĐỘ LỌT CỦA NGÔI CHỎM\n4.1. Chẩn đoán độ cúi ngôi chỏm\n- Ngôi chỏm cúi tốt: khám âm đạo lúc cổ tử cung đã xoá, mở sẽ sờ được thóp sau ở chính giữa mặt phẳng eo trên khung chậu hay ngay giữa cổ tử cung.\n- Ngôi chỏm cúi không tốt: lúc thóp sau ở một bên cổ tử cung. Có thể sờ được thóp trước lẫn thóp sau trong trường hợp ngôi chỏm cúi không tốt.\n\nHình 1. Xác định khớp dọc giữa và các thóp qua thăm khám âm đạo\n\n4.2. Chẩn đoán độ lọt của ngôi chỏm\nChẩn đoán độ lọt của ngôi bằng cách\n- Khám ngoài:\n+ Nắn đầu: đặt năm ngón đặt trên khớp vệ, tuỳ số ngón tay chạm được đến đầu thai tính ra mức độ lọt của ngôi: cao (5 ngón), chúc (4 ngón), chặt (3 ngón), lọt cao (2 ngón), lọt vừa (1 ngón) và lọt thấp (không có ngón tay nào chạm vào đầu thai nữa).\n+ Nắn vai: có thể đánh giá đầu đã lọt qua eo trên hay chưa. Nếu đo khoảng cách từ mỏm vai của thai nhi đến bờ trên khớp mu của sản phụ: >7cm tức là đầu chưa lọt và ngược lại < 7cm có nghĩa là đầu đã lọt qua mặt phẳng eo trên.\n- Khám trong: dựa vào phân độ lọt của Delle.\nDelle lấy vị trí 0 tương ứng với mức ngang 2 gai hông làm mốc, điểm thấp nhất của đầu thai nhi ngang mức này là đầu bắt đầu lọt. Từ vị trí này lên 1, 2, 3 cm tương ứng vị trí (-1),(-2),(-3) là đầu chưa lọt, còn từ vị trí 0 xuống 1, 2, 3 cm tương ứng vị trí (+1),(+2),(+3) là đầu đã lọt. Vị trí (-3) khi đầu cao lỏng, (+3) khi đầu lọt thấp.\n\n\n\n\n\n\n\n\n\n\nHình 2: Phân loại độ lọt của Delle\n5. CƠ CHẾ ĐẺ NGÔI CHỎM\nQuá trình chuyển dạ đẻ là một chuỗi các động tác thụ động của thai nhi, đặc biệt là của phần ngôi thai trình diện, trong quá trình thai đi xuống để sổ qua đường sinh dục\nTrong một cuộc đẻ, thai nhi dù là ngôi gì cũng diễn tiến qua 4 thì chính:\n- Lọt : đường kính lớn của ngôi trùng vào mặt phẳng eo trên (hay phần thấp nhất của đầu ngang vị trí -0- hai gai ngồi)\n\nHình 3. Đường kính lớn của ngôi trùng vào mặt phẳng eo trên\n- Xuống: ngôi di chuyển trong ống đẻ từ mặt phẳng eo trên đến mặt phẳng eo dưới.\n\nHình 4. Ngôi di chuyển từ mặt phẳng eo trên đến mặt phẳng eo dưới.\n- Quay: điểm mốc của ngôi hoặc chẩm (thóp sau) quay về phía xương mu hay xương cùng\n- Sổ: phần thai sổ ra ngoài âm hộ\n5.1. Đẻ đầu\n5.1.1. Thì lọt\n- Trước khi chuyển dạ: đầu cao, cúi không tốt (đường kính chẩm trán = 11 cm, trình diện trước eo trên).\n- Để chuẩn bị lọt, cơn co tử cung làm đầu cúi hơn để đường kính hạ chẩm - thóp trước = 9,5 cm song song với đường kính chéo trái của mặt phẳng eo trên (Khám âm đạo sờ được rãnh dọc của đầu trùng với đường kính này).\n- Lọt thực sự: quá trình diễn tiến từ từ khi đường kính của ngôi (đường kính lớn nhất) đi qua mặt phẳng eo trên. Đặc biệt có một số dấu hiệu lâm sàng khi đầu đã lọt như sau:\n+ Qua khám bụng, chỉ có thể sờ thấy 2/5 đầu thai nhi (xem bài biểu đồ chuyển dạ).\n+ Khám âm đạo cho thấy phần thấp nhất của chỏm nằm ngang mặt phẳng gai hông của thai phụ (vị trí - 0 -).\n- Kiểu lọt:\n+ Lọt đối xứng: 2 bướu đỉnh cùng xuống song song.\n+ Lọt không đối xứng: 1 bướu xuống trước\n1 bướu xuống sau\nKiểu lọt không đối xứng kiểu sau thường hay gặp hơn kiểu lọt không đối xứng kiểu trước.\n\n\n\n\n\n\n\n\nHình 5. Đầu thai nhi cúi trong chuyển dạ\n5.1.2. Thì xuống\nLà giai đoạn di chuyển của ngôi từ mặt phẳng eo trên đến mặt phẳng eo dưới ra phía âm đạo, khi đầu thai nhi xuống thấp làm tầng sinh môn căng phồng.\n5.1.3. Thì quay\nKhi đầu thai nhi chạm vào lớp cân cơ của đáy chậu thì đầu thai nhi bắt đầu quay để đường kính hạ chẩm - thóp trước (9,5 cm) trở thành song song với đường kính trước sau của eo dưới.\n- Ngôi chỏm kiểu thế trước thì đầu sẽ quay 45o ra trước.\n- Ngôi chỏm kiểu thế sau thì đầu sẽ quay 45o ra phía sau, hoặc có thể quay 135o ra trước.\n5.1.4. Thì sổ\n-  Sau khi xuống và quay, đầu sẽ cúi thêm do:\n+ Sức đẩy của cơn co tử cung\n+ Sức đẩy của cơn co thành bụng lúc rặn đẻ.\n+ Sức cản của đáy chậu.\nCác yếu tố trên làm cho đầu chuẩn bị sổ.\n- Sổ thực sự: Khi hạ chẩm thai nhi đã cố định ở bờ dưới khớp mu, dưới tác động của sức rặn và cơn co tử cung đầu thai nhi ngửa dần, âm hộ nở to để lần lượt trán, mặt, cằm chui ra và hướng lên trên.\n- Sau khi sổ xong đầu thai nhi sẽ quay 45o để trở về kiểu thế cũ.\n\nHình 6. Sổ đầu\n5.2. Đẻ vai\nCơ chế không khác mấy so với đẻ đầu. Sau khi sổ đầu, đầu quay về vị trí cũ, đường kính lưỡng mõm vai thu hẹp từ 12 cm còn 9,5 cm và lọt theo đường kính chéo (nếu ngôi lọt theo đường kính chéo trái thì vai lọt theo đường kính chéo phải và ngược lại). Sau khi lọt, vai sổ theo đường kính trước sau của eo dưới, vai trước sổ đến bờ dưới cơ Delta thì dừng lại để vai sau sổ.\n\nHình 7. Đẻ vai\n2.3. Đẻ mông\nGiống như cơ chế đẻ vai, đường kính lớn của mông là đường kính lưỡng ụ đùi bằng 9 cm (đường kính cùng chày 11 cm) sẽ thu nhỏ còn 9 cm. Do đó đẻ mông không phải là trường hợp khó.\nCâu hỏi:\nTrình bày khái niệm và chẩn đoán ngôi chỏm?\nTrình bày chẩn đoán độ lọt ngôi chỏm và các dấu hiệu khi đầu đã lọt?\nTrình bày cơ chế đẻ ngôi chỏm?", "priority": "Trung bình"}, {"id": "SK-10", "chapter": "Chương 1. Sản thường", "folder": "01_San_thuong", "title": "Các thuốc điều chỉnh cơn co tử cung", "author": "Ths. Nguyễn Trung Kiên", "word_count": 4171, "line_count": 231, "key_numbers": ["0,25mg", "0,5 g", "1 cm", "1 giờ", "1 ml", "1 phút", "10 phút", "100mg", "100ml", "10mg", "10ml", "12 giờ", "15 phút", "150mg", "180mmHg", "1g", "2 giờ", "2 phút", "20 phút", "20mg", "20ml", "24 giờ", "250 phút", "250mcg", "25mg", "2g", "2mg", "3 phút", "30 phút", "330mg", "36 tuần", "4 giờ", "40 phút", "40mg", "40mmHg", "48 giờ", "4giờ", "4mg", "5 ngày", "50 mmHg", "500ml", "5mg", "5ml", "6 giờ", "6g", "70ml", "7mg", "80mg"], "key_drugs": ["Glucose", "Magnesium Sulfate", "Magnesium sulfate", "Nifedipine", "Oxytocin", "Prostaglandin", "glucose", "nifedipine", "oxytocin"], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["CÁC THUỐC ĐIỀU CHỈNH CƠN CO TỬ CUNG", "Ths. Nguyễn Trung Kiên"], "bullets": []}, {"heading": "1. RỐI LOẠN TĂNG CO BÓP TỬ CUNG", "paragraphs": ["Cơn co rối loạn có nghĩa là cơn co quá thưa và yếu hoặc quá mạnh và mau. Nếu cơn co thưa, nhịp độ tiến triển của cơn co không đều, cuộc chuyển dạ sẽ bị kéo dài. Ngược lại, nếu cơn co tăng quá mức bình thường, trương lực tử cung cũng tăng, sẽ dẫn đến tình trạng tử cung cơ cứng, cổ tử cung khó mở, đoạn dưới tử cung kéo dài và dọa vỡ tử cung.", "Vì vậy cần theo dõi cơn co tử cung và đánh giá cơn co cho đúng, phát hiện được các rối loạn của cơn co để xử lý kịp thời, đề phòng vỡ tử cung, tránh được chuyển dạ kéo dài, gây nhiễm khuẩn ối, suy thai.", "Có hai loại rối loạn cơn co: co bóp tăng và co bóp giảm."], "bullets": []}, {"heading": "1.1. Co bóp tử cung tăng", "paragraphs": ["Tăng co bóp tử cung quá mức bình thường có thể gồm các yếu tố sau đây:"], "bullets": []}, {"heading": "1.1. Tăng cơn co tử cung:", "paragraphs": [], "bullets": ["- Thời gian cơn co dài hơn, biên độ cơn co mạnh hơn, khoảng cách giữa hai cơn co ngắn hơn bình thường, nghĩa là cơn co quá dài, quá mạnh và quá mau."]}, {"heading": "1.2. Tăng trương lực tử cung:", "paragraphs": [], "bullets": ["- Bình thường trong quá trình chuyển dạ, khi không có cơn co tử cung, lớp cơ tử cung không giãn hoàn toàn như khi chưa chuyển dạ, mà có một trương lực cơ bản, thay đổi tùy từng người. Nếu trương lực cơ bản tăng cao, tử cung sẽ cứng liên tục, các cơn co tuy vẫn còn nhưng hiệu lực của các cơn co sẽ kém và hậu quả là tử cung sẽ co thắt lại, mở chậm, chuyển dạ kéo dài."]}, {"heading": "1.3. Những nguyên nhân:", "paragraphs": [], "bullets": ["- Gây ra tăng co tử cung có thể là do không tương xướng giữa thai và khung chậu, khối u tiền đạo, do cơ tử cung không tốt, ở tử cung bé kém phát triển, tử cung có tật bẩm sinh, tử cung của người con so lớn tuổi, do tinh thần của thai phụ không ổn định, dễ bị kích thích, nóng nảy, sợ sệt, cuối cùng có thể do sử dụng thuốc tăng co như oxytocin quá liều."]}, {"heading": "1.4. Cách xử trí", "paragraphs": [], "bullets": ["- Trước tiên khám lại đẻ phát hiện khung chậu hẹp, không tương ứng giữa khung chậu và thai nhi, thai to, ngôi thai cúi không tốt. Nếu là nguyên nhân cơ học thì cách xử trí là mổ lấy thai.", "- Sau khi đã loại bỏ nguyên nhân cơ học và chắc chắn là do rối loạn co bóp tử cung thì có thể điều chỉnh bằng thuốc.", "- Đối với các trường hợp tử cung có trương lực cao, cơn co quá mạnh và quá mau hơn bình thường, có thể lúc đầu dùng thuốc giảm co nhẹ như papaverin, atropin, sau đó dùng Dolosal để vừa làm giảm trương lực vừa giúp cho cổ tử cung mở nhanh, cuộc chuyển dạ sẽ tiến triển bình thường.", "- Trong trường hợp tử cung co cứng, điều chỉnh bằng papaverin không kết quả, nên nghĩ đến nguyên nhân rau bong non, cần phẫu thuật sớm để cứu con và mẹ."]}, {"heading": "1.2. Co bóp tử cung giảm", "paragraphs": [], "bullets": ["- Co bóp tử cung giảm thể hiện ở cơn co tử cung ngắn, khoảng cách giữa hai cơn co kéo dài hơn bình thường, cường độ cơn co nhẹ, nghĩa là cơn co thưa yếu. Có khi sau một thời gian chuyển dạ không còn có cơn co nữa, chuyển dạ coi như ngừng lại."]}, {"heading": "2.1. Nguyên nhân", "paragraphs": [], "bullets": ["- Có thể là nguyên phát từ lúc mới chuyển dạ, thường gặp ở những thai phụ thể trạng suy yếu như thiếu máu, suy tim, lao phổi… Có thể gặp ở người quá nhỏ bé hoặc có tử cung kém phát triển.", "- Nguyên nhân có thể là thứ phát do tử cung bị căng quá trong trường hợp thai đôi, đa ối, u xơ tử cung, hoặc ở những thai phụ mà chuyển dạ kéo dài, vỡ ối sớm, nhiễm khuẩn ối."]}, {"heading": "2.2. Cách xử trí", "paragraphs": ["Nếu ối đã vỡ, cần kích thích bằng các loại thuốc điều chỉnh tăng co như oxytocin 5 đơn vị và hòa vào 500ml huyết thanh ngọt đẳng trương 5%, truyền chậm vào tĩnh mạch. Lúc mới bắt đầu chỉ truyền 10 hay 15 giọt mỗi phút, sau đó tăng dần để cho hợp với sinh lý cơn co tử cung. Nếu cơn co còn thưa, tăng dần lên 20 giọt, 30 giọt mỗi phút. Nếu cơn co quá mau và mạnh phải giảm số giọt xuống cho vừa, để cơn co nhịp nhàng đền đặn. Như vậy, muốn truyền 500ml phải mất 250 phút tức là 4 giờ 10 phút. Nói chung nếu làm đúng kỹ thuật đúng liều lượng, cổ tử cung sẽ mở nhanh và chuyển dạ có kết thúc sau 3 hoặc 4 giờ.", "Tóm lại, nhờ các thuốc gây tăng và giảm co tử cung, chúng ta đã có thể điều chính được một số lớn trường hợp đẻ khó do rối loạn cơn co, giúp cho cuộc đẻ tiến triển bình thường, tránh cho thai phụ khỏi phải mổ lấy thai.", "Tuy nhiên, sử dụng các thuốc tăng và giảm cơn co phải đúng chỉ định, đúng kỹ thuật, khi dùng phải theo dõi thai phụ sát, vì các thuốc này có thể gây vỡ tử cung hoặc ngược lại đờ tử cung."], "bullets": ["- Cơn co thưa và yếu sẽ làm cho chuyển dạ kéo dài, nhiễm khuẩn ối, cổ tử cung phù nền, khó mở, suy thai, và sau đẻ thai phụ dễ bị chảy máu do đờ tử cung, cho nên cần xử lý kịp thời.", "- Nếu ối đã vỡ từ lâu thì phải tích cực hơn. Thường ối phải vỡ đúng lúc cổ tử cung mở hết, nghĩa là lúc cơn co tử cung dài 45 giây đến 1 phút, khoảng cách giữa hai cơn có từ 1 đến 2 phút. Điều đáng chú ý là từ khi vỡ ối cho đến khi cổ tử cung mở hết phải không quá 6 giờ. Quá thời gian đó phải cho kháng sinh chống nhiễm khuẩn, đồng thời dùng thuốc tăng co: oxytocin nhỏ giọt chậm vào tĩnh mạch để cuộc đẻ tiến triển nhanh.", "- Trong trường hợp đa ối, cơn co thưa nhẹ, chỉ cần chọc đầu ối cho dung tích tử cung nhỏ lại, cơn co tử cung sẽ tăng dần.", "- Trong trường hợp ngôi thai lọt và xuống bình thường, nhưng khi sổ thai, cơn co trở nên thưa và yếu, có thể dùng forceps hay giác hút để kéo thai ra. Muốn tránh can thiệp bằng thủ thuật vì sợ nó có thể làm tổn thương đến thai nhi, người ta khuyên có thể dùng 2 đơn vị oxytocin tiêm dưới da để kích thích cho cơn co trở lại mạnh và mau, giúp thai nhi sổ nhanh, không cần phải dùng thủ thuật để can thiệp."]}, {"heading": "2.1. Oxytocin", "paragraphs": ["Oxytocin là hormon thùy sau tuyến yên. Tuyến yên là một tuyến nhỏ, đường kính khoảng 1 cm, nằm trong hố yên của xương bướm, nặng 0,5 g. Tuyến yên liên quan mật thiết với vùng dưới đồi qua đường mạch máu và đường thần kinh, đó là hệ thống cửa dưới đồi - yên và bó sợi thần kinh dưới đồi - yên.", "Tuyến yên là một tuyến hỗn hợp, gồm có 3 thùy: thùy trước, thùy giữa và thùy sau. Thùy sau tuyến yên còn gọi là thùy thần kinh, các tế bào ở đây giống tế bào thần kinh đệm, không có khả năng chế tiết hormon mà có chức năng hỗ trợ cho các sợi trục và cúc tận cùng tiết ADH và Oxytocin.", "Hai hormon được bài tiết từ thuỳ sau tuyến yên có nguồn gốc từ vùng dưới đồi, do nhân trên thị và nhân cạnh não thất bài tiết. Sau khi được tổng hợp chúng được vận chuyển theo sợi trục đến chứa ở các túi nằm trong tận cùng thần kinh khu trú ở thuỳ sau tuyến yên."], "bullets": []}, {"heading": "2.1.1. Bản chất hoá học của Oxytocin", "paragraphs": ["Là peptid có 9 acid amin với trọng lượng phân tử 1025."], "bullets": []}, {"heading": "2.1.2. Tác dụng:", "paragraphs": [], "bullets": ["- Gây co thắt tế bào biểu mô cơ (myoepithelial cells) là những tế bào nằm thành hàng rào bao quanh nang tuyến sữa. Những tế bào này co lại sẽ ép vào các nang tuyến và đẩy sữa ra ống tuyến, khi đứa trẻ bú sẽ nhận được sữa. Tác dụng này được gọi là tác dụng bài xuất sữa, khác với tác dụng gây bài tiết sữa của prolactin.", "- Gây co cơ tử cung mạnh khi có thai, đặc biệt  mạnh vào cuối thai kỳ, lúc chuyển dạ."]}, {"heading": "2.1.3. Điều hoà bài tiết", "paragraphs": [], "bullets": ["- Oxytocin được bài tiết khi có kích thích trực tiếp vào tuyến vú (động tác mút vú của đứa trẻ) hoặc kích thích tâm lý. Những kích thích tâm lý hoặc giao cảm có liên quan đến cảm xúc đều có ảnh hưởng đến vùng dưới đồi kích thích hoặc ức chế bài tiết oxytocin và ảnh hưởng đến sự bài xuất sữa ở các bà mẹ cho con bú."]}, {"heading": "2.2. Các Alcaloid", "paragraphs": ["Điển hình là thuốc Methylergometrine (nấm cựa gà)", "Nhóm Dược lý: Thuốc có tác dụng thúc đẻ, cầm máu sau đẻ và chống đẻ non", "Tên Biệt dược : Pospargin, Uterin, Spametrin", "Dạng bào chế : Dung dịch tiêm", "Thành phần : Methylergometrine maleate"], "bullets": []}, {"heading": "2.2.1. Dược động học", "paragraphs": [], "bullets": ["- Hấp thu: Methylergometrin maleat là dẫn xuất của Ergometrin (là alcaloid của nấm cựa gà). Hấp thu nhanh và gần như hoàn toàn.", "- Chuyển hoá: thuốc chuyển hoá chủ yếu qua gan."]}, {"heading": "2.2.2. Tác dụng", "paragraphs": ["Thuốc có tác dụng trên tử cung mạnh, tác dụng chính là gây co tử cung mạnh, với liều cao tác dụng kéo dài hơn."], "bullets": []}, {"heading": "2.2.3. Chỉ định", "paragraphs": [], "bullets": ["- Mất trương lực cơ sau đẻ & chảy máu, thường dùng sau khi lấy rau ra.", "- Dưới sự giám sát của khoa sản có thể dùng thuốc vào giai đoạn chuyển dạ thứ hai, sau khi vai trước ra."]}, {"heading": "2.2.4. Chống chỉ định", "paragraphs": ["Không được dùng thuốc trong các trường hợp sau:"], "bullets": ["+ Đau thắt ngực không ổn định, mới bị nhồi máu cơ tim, tiền sử tai biến mạch máu não.", "+ Tăng huyết áp nặng.", "+ Tiền sử cơn thiếu máu cục bộ não thoáng qua.", "+ Bệnh mạch vành, sản giật, tiền sản giật, bệnh mạch máu ngoại vi tắc nghẽn, hiện tượng Raynaud nặng.", "+ Dị ứng, quá mẫn hoặc không dung nạp thuốc.", "+ Doạ sẩy thai tự nhiên."]}, {"heading": "2.2.5. Liều lượng", "paragraphs": ["Tiêm bắp (IM): 1 ml sau khi vai trước ra hay sau khi lấy rau.", "Có thể tiêm lặp lại liều khi cần, cách quãng 2 - 4 giờ."], "bullets": []}, {"heading": "2.4. Carbetocin (duratocin)", "paragraphs": ["Duratocin là một đồng vận oxytocin tác dụng kéo dài."], "bullets": []}, {"heading": "2.4.1. Tác dụng", "paragraphs": [], "bullets": ["- Gắn kết cao với thụ thể oxytocin.", "- Thời gian khởi phát tác dụng: 2 phút", "- Thời gian bán hủy: 40 phút (oxytocin: 3 phút)", "- Thời gian tử cung co bóp nhịp nhàng: 1- 2 giờ", "- Gây co tử cung mạnh hơn oxytocin."]}, {"heading": "2.4.2. Chỉ định", "paragraphs": ["Ngăn ngừa mất trương lực TC và băng huyết sau khi sinh mổ bằng phương pháp gây tê tủy sống hay gây tê ngoài màng cứng."], "bullets": []}, {"heading": "2.4.3. Chống chỉ định", "paragraphs": ["Không dùng DURATOCIN trước khi sinh", "Có tiền sử quá mẫn với oxytocin hoặc carbetocin", "Bệnh mạch máu, đặc biệt bệnh mạch vành, trừ khi theo dõi chặt chẽ", "Không dùng cho trẻ em"], "bullets": []}, {"heading": "3. CÁC NHÓM THUỐC GIẢM CO", "paragraphs": ["Thuốc giảm tác dụng trên cơ trơn và thuốc giảm tác dụng ưu tiên trên cơ tử cung, chỉ định trong các trường hợp:"], "bullets": ["- Suy thai do cơn co tử cung quá mạnh hoặc quá mau.", "- Cổ tử cung chậm mở, cứng, phù nề.", "- Dọa vỡ tử cung.", "- Dọa đẻ non.", "- Rau tiền đạo.", "- Sa dây rau."]}, {"heading": "3.1. Nhóm thuốc giảm co bóp tử cung", "paragraphs": ["Có rất nhiều loại thuốc có thể làm giảm co bóp của cơ tử cung nhưng tuyến cơ sở có thể dùng được một trong 4 loại sau:"], "bullets": []}, {"heading": "3.1.1. Papaverin chlohydrat", "paragraphs": [], "bullets": ["- Papaverin là thuốc có tác dụng làm giảm co thắt các cơ trơn. Đối với cơ tử cung nó có tác động trực tiếp gây giãn cơ, do đó làm giảm cường độ và thời gian co bóp.", "- Papaverin được bào chế ưới 3 dạng: thuốc tiêm 40mg/ống để tiêm bắp hoặc tiêm tĩnh mạch; thuốc bột và thuốc viên cũng có hàm lượng 40mg/gói hoặc viên để uống.", "- Liều dùng:", "+ Ngày uống 2 - 3 lần, mỗi lần 1 - 2 viên.", "+ Tiêm bắp hoặc tiêm tĩnh mạch chậm 1 ống x 2 lần/ngày. Liều tối đa 2,5 ống/ngày.", "- Tác dụng phụ: buồn nôn, toát mồ hôi, hoa mắt, loạn nhịp tim, nhức đầu, ngủ gà, bốc hoả, nổi sẩn ngoài da, tiêu chảy hay táo bón, hạ huyết áp và choáng khi tiêm tĩnh mạch nhanh."]}, {"heading": "3.1.2. Alverin citrat (Spasmaverin)", "paragraphs": [], "bullets": ["- Tác dụng: chống co thắt cơ trơn loại Papaverin. Dùng trong trường hợp dọa sẩy thai, dọa đẻ non và rau tiền đạo ra máu.", "- Spasmaverin được bào chế ưới dạng viên nén hoặc viên nang 40mg.", "+ Ngày uống 2 - 3 lần, mỗi lần 1 - 2 viên.", "+ Viên đạn 1 - 2 viên/ngày.", "- Chống chỉ định: huyết áp thấp và các trường hợp giảm huyết áp."]}, {"heading": "3.1.3. Phloroglucinol (Spasfon)", "paragraphs": [], "bullets": ["- Tác dụng: thuốc làm dãn cơ, chống co thắt hướng cơ. Spasfon có tác dụng ly giải co thắt trên sợi cơ trơn và làm dịu cơn đau.", "- Không tác dụng trên tim mạch nên sử dụng tốt hơn các loại giảm co khác như Atropin, Papaverin, Salbutamol.", "- Trên tử cung, Spasfon làm mềm đoạn ưới và cổ tử cung nhưng không ức chế những cơn co ở thân tử cung, o đó không cản trở sự tiến triển của ngôi thai và nhất là không gây băng huyết sau đẻ, điều trị cổ tử cung chậm mở.", "- Spasfon có 4 dạng bào chế: ống tiêm 80mg, viên đạn và viên nén 80mg, bột đông khô đường uống (ngậm tan).", "- Liều dùng:", "+ Điều trị tấn công: 1 - 3 ống/ngày tiêm bắp hoặc tĩnh mạch.", "+ Điều trị duy trì: uống 2 viên x 3 lần/ngày hoặc 1 viên đặt x 3 lần/ngày.", "+ Viên ngậm tan 2 viên/ngày uống lúc có cơn đau, có thể lặp lại nếu co thắt nhiều. Có thể hoà viên bột đông khô trong nước để uống hoặc ngậm dưới lưỡi sẽ có tác dụng nhanh.", "- Tác dụng phụ: hiếm gặp.", "+ Thường gặp là phản ứng dị ứng da nhưng đôi khi bị nặng: phát ban, nổi mề đay, phù Quink.", "+ Tiêm bắp và tĩnh mạch có thể gây hạ huyết áp.", "- Chống chỉ định:", "+ Quá mẫn cảm với một trong thành phần của thuốc này", "+ Không nên dùng phối hợp với các thuốc giảm đau mạnh như Morphine và các dẫn xuất của thuốc này."]}, {"heading": "3.1.4. Atropin sunfat", "paragraphs": [], "bullets": ["- Là thuốc có tác dụng làm giảm cường độ và tần số co bóp của cơ tử cung đồng thời có thể làm cổ tử cung mềm ra và dễ dãn nở hơn.", "- Ở nước ta thuốc được bào chế dưới dạng tiêm mỗi ống có 0,25mg hay 1/4mg.", "- Liều dùng trung bình 1 - 2 ống.", "- Thuốc có những tác dụng phụ:", "+ Giảm tiết nước bọt (khô miệng, khó nuốt).", "+ Tim đập nhanh.", "+ Giảm tiết mồ hôi làm khô da, có khi làm đỏ da.", "+ Đồng tử (con ngươi) bị giãn.", "- Chống chỉ định: suy thận nặng, glôcôm."]}, {"heading": "3.2. Nhóm thuốc đồng vận β - mimetic", "paragraphs": ["Các loại bêta - mimetic là các thuốc hướng beta giao cảm: gồm có cá thuốc như salbutamol, ritodrine, terbutaline."], "bullets": []}, {"heading": "3.2.1. Salbutamol", "paragraphs": [], "bullets": ["- Salbutamol là thuốc ãn cơ được sử dụng trong điều trị về các bệnh đường dẫn khí như hen phế quản, viêm phế quản co thắt.", "- Salbutamol có tác dụng làm giãn cơ tử cung, làm giảm biên độ và tần số cơn co tử cung. Thuốc làm tăng quá trình oxy hoá trong bánh rau, làm tăng vận chuyển tuần hoàn thai mẹ và tăng sự phát triển của thai.", "- Thuốc được duy trì trong huyết tương trong suốt 12 giờ sau chỉ một liều uống.", "- Các dạng thuốc được sử dụng:", "+ Dạng viên: viên nén 2mg và 4mg.", "+ Dạng tiêm truyền tĩnh mạch: ống 5ml chứa 5mg.", "- Cách dùng:", "+ Salbutamol 2mg uống 2 viên/lần.", "+ Dạng ống 5mg/5ml pha trong 500ml dung dịch Glucose 5% hoặc NaCl 0,9% truyền tĩnh mạch.", "- Tác dụng phụ của Salbutamol:", "+ Bứt rứt và run, nhức đầu, lo lắng, buồn nôn, suy nhược, mất ngủ, chóng mặt, đánh trống ngực, đau ngực, thở nông, mất ngủ, buồn nôn, suy nhược, hoa mắt, vã mồ hôi.", "+ Các rối loạn về tim mạch: nhịp tim tăng thường đi kèm với hồi hộp, hốt hoảng, cung lượng tim tăng, hạ huyết áp tâm trương (huyết áp tối thiểu).", "+ Nổi mề đay hiếm gặp.", "+ Đối với thai: nhịp tim thai tăng. Nếu dùng kéo dài có thể giảm kali, hạ đường huyết.", "- Chống chỉ định:", "+ Không được dùng Salbutamol trong các trường hợp chảy máu âm đạo (rau bong non, rau tiền đạo).", "+ Thai phụ mắc bệnh tim, loạn nhịp tim, tăng huyết áp.", "+ Đái tháo đường, cường tuyến giáp, hạ kali huyết.", "+ Viêm màng ối mạn tính."]}, {"heading": "3.2.2. Ritodrine", "paragraphs": ["Ritodrine là thuốc có tác dụng trực tiếp làm giảm cơ trơn của tử cung và của phổi. Pha 150mg trong 500ml dung dịch mặn đẳng trương."], "bullets": ["+ Liều tấn công: bắt đầu truyền với tốc độ 20ml/giờ và cứ 15 phút tăng lên 10ml/giờ và tăng tối đa là 70ml/giờ.", "+ Liều duy trì: khi cắt được cơn tiếp tục duy trì thêm 12 giờ. Trước khi rút đường truyền 30 phút cho uống Ritodrine cứ 2 giờ 10mg trong 24 giờ và sau đó duy trì ở liều 20mg/4- 6 giờ cho đến khi thai  được 36 tuần. Ngưng thuốc khi nhịp tim mẹ trên 150 lần /phút và tim thai trên 200 lần/ phút. HA max > 180mmHg và HA min <  40mmHg.", "+ Tác dụng phụ trên mẹ bao gồm: tăng nhịp tim, tăng đường huyết, tăng Insuline huyết, hạ Kali huyết, rùng mình, đánh trống ngực, bồn chồn, buồn nôn, nôn, ảo giác.", "+ Tác động lên thai nhi: nhịp tim nhanh, hạ canxi huyết, hạ đường huyết, hạ huyết áp, tăng bilirubine huyết, xuất huyết não thất.", "+ Chống chỉ định trong bệnh tim, cường giáp, tăng huyết áp không kiểm soát được, đái tháo đường nặng, các bện gan và bệnh thận mạn tính. Các bệnh nhân trên 35 tuổi cũng có chống chỉ định."]}, {"heading": "3.2.3. Terbutaline", "paragraphs": ["Terbutaline là thuốc có chỉ định, chống chỉ định giống Ritodrine."], "bullets": ["+ Liều tấn cụng: liều khởi đầu 250mcg, truyền TM với tốc độ 10ư80 àg/phỳt cho đến khi chuyển dạ ngừng lại. Sau đú tiờm dưới da 0,25ư0,5mg/2ư 4giờ trong 12 giờ tiếp theo.", "+ Liều duy trì: liều uống 5mg cứ 4- 6 giờ một lần cho đến khi thai đươc 36 tuần. Tác dụng phụ trên bà mẹ: loạn nhịp, phù phổi, thiếu máu cơ tim, hạ huyết áp, nhịp tim nhanh. Tác động lên thai nhi: nhịp tim nhanh, tăng đường huyết, tăng Insuline huyết, phì đại cơ tim, thiếu máu cơ tim."]}, {"heading": "3.3. Thuốc đối vận Oxytocin: Atosiban (tractocile)", "paragraphs": ["Atosiban là một đồng phân nhưng đối vận với Oxytocin,  có khả năng ức chế cạnh tranh trên thụ thể của oxytocin ở cơ tử cung và màng rụng. Do tác dụng đặc hiệu trên tử cung nên an toàn hơn thuốc giảm co khác."], "bullets": ["+ Tác dụng phụ hiếm gặp trên mẹ là buồn nôn, nhức đầu, chong mặt, nhịp nhanh, cao huyết áp, tăng đường huyết và phản ứng dị ứng.", "+ Tác dụng trên thai không đáng kể", "+ Liều lượng và đường dùng khuyến cáo bao gồm 3 bước (bảng 2). Thời gian điều trị không nên vượt quá 48 giờ và tổng liều điều trị không quá 330mg."]}, {"heading": "3.4. Thuốc chẹn kênh Calci - Nifedipine", "paragraphs": ["Nifedipine tác dụng trên cơ trơn làm giãn các loại cơ trơn: khí- phế quản, tiêu hóa, tử cung, nhưng đặc biệt là thành mạch (mao động mạch nhạy cảm hơn mao tĩnh mạch).", "Tác dụng nặng hơn, liên quan đến tác dụng điều trị do ức chế quá mạnh kênh Ca: tim đập chậm, nghẽn nhĩ thất, suy tim xung huyết, ngừng tim. Hiếm gặp.", "Đặc tính", "salbutamol", "nifedipine", "Atosiban(tractocile)", "Nhóm thuốc", "Đồng vận beta", "Chẹn kênh canxi", "Đối kháng oxytocine", "Được duyệt chính thức cho chỉ định sinh non", "Có", "Không", "Có", "Chống chỉ định", "Loạn nhịp", "Bệnh tuyến giáp, tiểu đường không được kiểm soát tốt", "Bệnh tim, bệnh lý thận, huyết áp thấp ở người mẹ, không dùng chung với MgSO4,", "Không", "Tác dụng phụ lên người mẹ", "Loạn nhịp tim, loạn nhịp thở, phù phổi, thiếu máu cơ tim, tụt huyết áp, nhịp tim nhanh, thở gấp, tăng glucose máu, hạ kali máu, run, lo lắng, buồn nôn, nôn mửa", "Bừng mặt, nhức đầu, tụt huyết áp thoáng qua, nhịp tim nhanh thoáng qua, đánh trống ngực", "Buồn nôn, nhức đầu, phản ứng dị ứng", "Tác dụng phụ lên thai nhi & trẻ sơ sinh", "Nhịp tim nhanh, tăng insuline máu, tăng glucose thai, hạ glucose, calci máu ở trẻ sơ sinh, phì đại cơ tim và vách ngăn, thiếu máu cơ tim, tắc ruột", "Thai chết bất ngờ, tình trạng nguy hiểm cho thai", "Đến nay chưa được ghi nhận"], "bullets": ["+  Liều tấn công: 20mg ngậm dưới lưỡi mỗi 20 phút, tối đa 3 liều.", "+ Sau  khi đã cắt cơn co thì duy trì liều 10-20mg đường uống trong mỗi 4-6 giờ.", "+ Chống chỉ định đối với bệnh tim, huyết áp thấp (< 90/50 mmHg).", "+ Không sử dụng cùng với Magnesium sulphate.", "+ Cẩn thận khi sử dụng cho người có bệnh lý ở thận.", "+ Tác dụng phụ trên bà mẹ: tác dụng nhẹ, không cần ngừng điều trị: cơn nóng bừng, nhức đầu, chóng mặt (do phản xạ giãn mạch, tăng nhịp tim nên dùng cùng với thuốc chẹn ( giao cảm), buồn nôn, táo.", "+ Tác động lên thai nhi: hiện chưa có ghi nhận đặc biệt gì."]}, {"heading": "3.5. Magnesium Sulfate", "paragraphs": ["Magnesium sulfate là thuốc thay thế cho các thuốc beta hướng giao cảm khi có chống chỉ định dùng các thuốc này hoặc khi có ngộ độc thuốc."], "bullets": ["- Liều tấn công: 4-6g trong 100ml Dextrose 5% truyền tĩnh mạch từ 15-20 phút.", "+ Liều duy trì: 2g/giờ truyền TM, trong vòng 12 giờ, sau đó là 1g/1 giờ trong 24 -48 giờ. Theo dõi nồng độ Mg++ huyết thanh duy trì từ 5-7mg/dL.", "- Tác dụng phụ:", "+ Trên bà mẹ: nóng bừng, ngủ lịm, đau đầu, mệt mỏi, khô miệng, ức chế hô hấp, giảm phản xạ gân xương. Thử phản xạ gân xương để phát hiện quá liều thuốc.", "+ Ngừng tim và hô hấp có thể xuất hiện nếu dùng quá liều. Có thể dùng chất đối kháng là Calci (Calcium gluconate hoặc calci clorua liều 1g tiêm TM chậm).", "+ Tác động lên thai nhi: ngủ lịm, giảm trương lực cơ, suy hô hấp."]}, {"heading": "3.6. Thuốc ức chế men tổng hợp Prostaglandin (indomethacin)", "paragraphs": [], "bullets": ["- Indomethacin liều 25mg/6 giờ trong 5 ngày hoặc nhét hậu môn 100mg sau đó uống 25mg/6 giờ cho đến 24 giờ sau khi không còn cơn gò nữa.", "- Thuốc này có những tác động ngược trên thai nhi: co thắt ống động mạch, tăng áp lực phổi, thiểu ối, xuất huyết não thất, viêm ruột hoại tử và tăng bilirubine huyết."]}], "raw_text": "CÁC THUỐC ĐIỀU CHỈNH CƠN CO TỬ CUNG\nThs. Nguyễn Trung Kiên\n1. RỐI LOẠN TĂNG CO BÓP TỬ CUNG\nCơn co rối loạn có nghĩa là cơn co quá thưa và yếu hoặc quá mạnh và mau. Nếu cơn co thưa, nhịp độ tiến triển của cơn co không đều, cuộc chuyển dạ sẽ bị kéo dài. Ngược lại, nếu cơn co tăng quá mức bình thường, trương lực tử cung cũng tăng, sẽ dẫn đến tình trạng tử cung cơ cứng, cổ tử cung khó mở, đoạn dưới tử cung kéo dài và dọa vỡ tử cung.\nVì vậy cần theo dõi cơn co tử cung và đánh giá cơn co cho đúng, phát hiện được các rối loạn của cơn co để xử lý kịp thời, đề phòng vỡ tử cung, tránh được chuyển dạ kéo dài, gây nhiễm khuẩn ối, suy thai.\nCó hai loại rối loạn cơn co: co bóp tăng và co bóp giảm.\n1.1. Co bóp tử cung tăng\nTăng co bóp tử cung quá mức bình thường có thể gồm các yếu tố sau đây:\n1.1. Tăng cơn co tử cung:\n- Thời gian cơn co dài hơn, biên độ cơn co mạnh hơn, khoảng cách giữa hai cơn co ngắn hơn bình thường, nghĩa là cơn co quá dài, quá mạnh và quá mau.\n1.2. Tăng trương lực tử cung:\n- Bình thường trong quá trình chuyển dạ, khi không có cơn co tử cung, lớp cơ tử cung không giãn hoàn toàn như khi chưa chuyển dạ, mà có một trương lực cơ bản, thay đổi tùy từng người. Nếu trương lực cơ bản tăng cao, tử cung sẽ cứng liên tục, các cơn co tuy vẫn còn nhưng hiệu lực của các cơn co sẽ kém và hậu quả là tử cung sẽ co thắt lại, mở chậm, chuyển dạ kéo dài.\n1.3. Những nguyên nhân:\n- Gây ra tăng co tử cung có thể là do không tương xướng giữa thai và khung chậu, khối u tiền đạo, do cơ tử cung không tốt, ở tử cung bé kém phát triển, tử cung có tật bẩm sinh, tử cung của người con so lớn tuổi, do tinh thần của thai phụ không ổn định, dễ bị kích thích, nóng nảy, sợ sệt, cuối cùng có thể do sử dụng thuốc tăng co như oxytocin quá liều.\n1.4. Cách xử trí\n- Trước tiên khám lại đẻ phát hiện khung chậu hẹp, không tương ứng giữa khung chậu và thai nhi, thai to, ngôi thai cúi không tốt. Nếu là nguyên nhân cơ học thì cách xử trí là mổ lấy thai.\n- Sau khi đã loại bỏ nguyên nhân cơ học và chắc chắn là do rối loạn co bóp tử cung thì có thể điều chỉnh bằng thuốc.\n- Đối với các trường hợp tử cung có trương lực cao, cơn co quá mạnh và quá mau hơn bình thường, có thể lúc đầu dùng thuốc giảm co nhẹ như papaverin, atropin, sau đó dùng Dolosal để vừa làm giảm trương lực vừa giúp cho cổ tử cung mở nhanh, cuộc chuyển dạ sẽ tiến triển bình thường.\n- Trong trường hợp tử cung co cứng, điều chỉnh bằng papaverin không kết quả, nên nghĩ đến nguyên nhân rau bong non, cần phẫu thuật sớm để cứu con và mẹ.\n1.2. Co bóp tử cung giảm\n- Co bóp tử cung giảm thể hiện ở cơn co tử cung ngắn, khoảng cách giữa hai cơn co kéo dài hơn bình thường, cường độ cơn co nhẹ, nghĩa là cơn co thưa yếu. Có khi sau một thời gian chuyển dạ không còn có cơn co nữa, chuyển dạ coi như ngừng lại.\n2.1. Nguyên nhân\n- Có thể là nguyên phát từ lúc mới chuyển dạ, thường gặp ở những thai phụ thể trạng suy yếu như thiếu máu, suy tim, lao phổi… Có thể gặp ở người quá nhỏ bé hoặc có tử cung kém phát triển.\n- Nguyên nhân có thể là thứ phát do tử cung bị căng quá trong trường hợp thai đôi, đa ối, u xơ tử cung, hoặc ở những thai phụ mà chuyển dạ kéo dài, vỡ ối sớm, nhiễm khuẩn ối.\n2.2. Cách xử trí\n- Cơn co thưa và yếu sẽ làm cho chuyển dạ kéo dài, nhiễm khuẩn ối, cổ tử cung phù nền, khó mở, suy thai, và sau đẻ thai phụ dễ bị chảy máu do đờ tử cung, cho nên cần xử lý kịp thời.\nNếu ối đã vỡ, cần kích thích bằng các loại thuốc điều chỉnh tăng co như oxytocin 5 đơn vị và hòa vào 500ml huyết thanh ngọt đẳng trương 5%, truyền chậm vào tĩnh mạch. Lúc mới bắt đầu chỉ truyền 10 hay 15 giọt mỗi phút, sau đó tăng dần để cho hợp với sinh lý cơn co tử cung. Nếu cơn co còn thưa, tăng dần lên 20 giọt, 30 giọt mỗi phút. Nếu cơn co quá mau và mạnh phải giảm số giọt xuống cho vừa, để cơn co nhịp nhàng đền đặn. Như vậy, muốn truyền 500ml phải mất 250 phút tức là 4 giờ 10 phút. Nói chung nếu làm đúng kỹ thuật đúng liều lượng, cổ tử cung sẽ mở nhanh và chuyển dạ có kết thúc sau 3 hoặc 4 giờ.\n- Nếu ối đã vỡ từ lâu thì phải tích cực hơn. Thường ối phải vỡ đúng lúc cổ tử cung mở hết, nghĩa là lúc cơn co tử cung dài 45 giây đến 1 phút, khoảng cách giữa hai cơn có từ 1 đến 2 phút. Điều đáng chú ý là từ khi vỡ ối cho đến khi cổ tử cung mở hết phải không quá 6 giờ. Quá thời gian đó phải cho kháng sinh chống nhiễm khuẩn, đồng thời dùng thuốc tăng co: oxytocin nhỏ giọt chậm vào tĩnh mạch để cuộc đẻ tiến triển nhanh.\n- Trong trường hợp đa ối, cơn co thưa nhẹ, chỉ cần chọc đầu ối cho dung tích tử cung nhỏ lại, cơn co tử cung sẽ tăng dần.\n- Trong trường hợp ngôi thai lọt và xuống bình thường, nhưng khi sổ thai, cơn co trở nên thưa và yếu, có thể dùng forceps hay giác hút để kéo thai ra. Muốn tránh can thiệp bằng thủ thuật vì sợ nó có thể làm tổn thương đến thai nhi, người ta khuyên có thể dùng 2 đơn vị oxytocin tiêm dưới da để kích thích cho cơn co trở lại mạnh và mau, giúp thai nhi sổ nhanh, không cần phải dùng thủ thuật để can thiệp.\nTóm lại, nhờ các thuốc gây tăng và giảm co tử cung, chúng ta đã có thể điều chính được một số lớn trường hợp đẻ khó do rối loạn cơn co, giúp cho cuộc đẻ tiến triển bình thường, tránh cho thai phụ khỏi phải mổ lấy thai.\nTuy nhiên, sử dụng các thuốc tăng và giảm cơn co phải đúng chỉ định, đúng kỹ thuật, khi dùng phải theo dõi thai phụ sát, vì các thuốc này có thể gây vỡ tử cung hoặc ngược lại đờ tử cung.\n2. CÁC THUỐC TĂNG CO TỬ CUNG\n2.1. Oxytocin\nOxytocin là hormon thùy sau tuyến yên. Tuyến yên là một tuyến nhỏ, đường kính khoảng 1 cm, nằm trong hố yên của xương bướm, nặng 0,5 g. Tuyến yên liên quan mật thiết với vùng dưới đồi qua đường mạch máu và đường thần kinh, đó là hệ thống cửa dưới đồi - yên và bó sợi thần kinh dưới đồi - yên.\nTuyến yên là một tuyến hỗn hợp, gồm có 3 thùy: thùy trước, thùy giữa và thùy sau. Thùy sau tuyến yên còn gọi là thùy thần kinh, các tế bào ở đây giống tế bào thần kinh đệm, không có khả năng chế tiết hormon mà có chức năng hỗ trợ cho các sợi trục và cúc tận cùng tiết ADH và Oxytocin.\nHai hormon được bài tiết từ thuỳ sau tuyến yên có nguồn gốc từ vùng dưới đồi, do nhân trên thị và nhân cạnh não thất bài tiết. Sau khi được tổng hợp chúng được vận chuyển theo sợi trục đến chứa ở các túi nằm trong tận cùng thần kinh khu trú ở thuỳ sau tuyến yên.\n2.1.1. Bản chất hoá học của Oxytocin\nLà peptid có 9 acid amin với trọng lượng phân tử 1025.\n2.1.2. Tác dụng:\n- Gây co thắt tế bào biểu mô cơ (myoepithelial cells) là những tế bào nằm thành hàng rào bao quanh nang tuyến sữa. Những tế bào này co lại sẽ ép vào các nang tuyến và đẩy sữa ra ống tuyến, khi đứa trẻ bú sẽ nhận được sữa. Tác dụng này được gọi là tác dụng bài xuất sữa, khác với tác dụng gây bài tiết sữa của prolactin.\n- Gây co cơ tử cung mạnh khi có thai, đặc biệt  mạnh vào cuối thai kỳ, lúc chuyển dạ.\n2.1.3. Điều hoà bài tiết\n- Oxytocin được bài tiết khi có kích thích trực tiếp vào tuyến vú (động tác mút vú của đứa trẻ) hoặc kích thích tâm lý. Những kích thích tâm lý hoặc giao cảm có liên quan đến cảm xúc đều có ảnh hưởng đến vùng dưới đồi kích thích hoặc ức chế bài tiết oxytocin và ảnh hưởng đến sự bài xuất sữa ở các bà mẹ cho con bú.\n2.2. Các Alcaloid\nĐiển hình là thuốc Methylergometrine (nấm cựa gà)\nNhóm Dược lý: Thuốc có tác dụng thúc đẻ, cầm máu sau đẻ và chống đẻ non\nTên Biệt dược : Pospargin, Uterin, Spametrin\nDạng bào chế : Dung dịch tiêm\nThành phần : Methylergometrine maleate\n2.2.1. Dược động học\n- Hấp thu: Methylergometrin maleat là dẫn xuất của Ergometrin (là alcaloid của nấm cựa gà). Hấp thu nhanh và gần như hoàn toàn.\n- Chuyển hoá: thuốc chuyển hoá chủ yếu qua gan.\n2.2.2. Tác dụng\nThuốc có tác dụng trên tử cung mạnh, tác dụng chính là gây co tử cung mạnh, với liều cao tác dụng kéo dài hơn.\n2.2.3. Chỉ định\n- Mất trương lực cơ sau đẻ & chảy máu, thường dùng sau khi lấy rau ra.\n- Dưới sự giám sát của khoa sản có thể dùng thuốc vào giai đoạn chuyển dạ thứ hai, sau khi vai trước ra.\n2.2.4. Chống chỉ định\nKhông được dùng thuốc trong các trường hợp sau:\n+ Đau thắt ngực không ổn định, mới bị nhồi máu cơ tim, tiền sử tai biến mạch máu não.\n+ Tăng huyết áp nặng.\n+ Tiền sử cơn thiếu máu cục bộ não thoáng qua.\n+ Bệnh mạch vành, sản giật, tiền sản giật, bệnh mạch máu ngoại vi tắc nghẽn, hiện tượng Raynaud nặng.\n+ Dị ứng, quá mẫn hoặc không dung nạp thuốc.\n+ Doạ sẩy thai tự nhiên.\n2.2.5. Liều lượng\nTiêm bắp (IM): 1 ml sau khi vai trước ra hay sau khi lấy rau.\nCó thể tiêm lặp lại liều khi cần, cách quãng 2 - 4 giờ.\n2.3. Prostaglandin\n2.4. Carbetocin (duratocin)\nDuratocin là một đồng vận oxytocin tác dụng kéo dài.\n\n2.4.1. Tác dụng\n- Gắn kết cao với thụ thể oxytocin.\n- Thời gian khởi phát tác dụng: 2 phút\n- Thời gian bán hủy: 40 phút (oxytocin: 3 phút)\n- Thời gian tử cung co bóp nhịp nhàng: 1- 2 giờ\n- Gây co tử cung mạnh hơn oxytocin.\n2.4.2. Chỉ định\nNgăn ngừa mất trương lực TC và băng huyết sau khi sinh mổ bằng phương pháp gây tê tủy sống hay gây tê ngoài màng cứng.\n2.4.3. Chống chỉ định\nKhông dùng DURATOCIN trước khi sinh\nCó tiền sử quá mẫn với oxytocin hoặc carbetocin\nBệnh mạch máu, đặc biệt bệnh mạch vành, trừ khi theo dõi chặt chẽ\nKhông dùng cho trẻ em\n3. CÁC NHÓM THUỐC GIẢM CO\nThuốc giảm tác dụng trên cơ trơn và thuốc giảm tác dụng ưu tiên trên cơ tử cung, chỉ định trong các trường hợp:\n- Suy thai do cơn co tử cung quá mạnh hoặc quá mau.\n- Cổ tử cung chậm mở, cứng, phù nề.\n- Dọa vỡ tử cung.\n- Dọa đẻ non.\n- Rau tiền đạo.\n- Sa dây rau.\n3.1. Nhóm thuốc giảm co bóp tử cung\nCó rất nhiều loại thuốc có thể làm giảm co bóp của cơ tử cung nhưng tuyến cơ sở có thể dùng được một trong 4 loại sau:\n3.1.1. Papaverin chlohydrat\n- Papaverin là thuốc có tác dụng làm giảm co thắt các cơ trơn. Đối với cơ tử cung nó có tác động trực tiếp gây giãn cơ, do đó làm giảm cường độ và thời gian co bóp.\n- Papaverin được bào chế ưới 3 dạng: thuốc tiêm 40mg/ống để tiêm bắp hoặc tiêm tĩnh mạch; thuốc bột và thuốc viên cũng có hàm lượng 40mg/gói hoặc viên để uống.\n- Liều dùng:\n+ Ngày uống 2 - 3 lần, mỗi lần 1 - 2 viên.\n+ Tiêm bắp hoặc tiêm tĩnh mạch chậm 1 ống x 2 lần/ngày. Liều tối đa 2,5 ống/ngày.\n- Tác dụng phụ: buồn nôn, toát mồ hôi, hoa mắt, loạn nhịp tim, nhức đầu, ngủ gà, bốc hoả, nổi sẩn ngoài da, tiêu chảy hay táo bón, hạ huyết áp và choáng khi tiêm tĩnh mạch nhanh.\n3.1.2. Alverin citrat (Spasmaverin)\n- Tác dụng: chống co thắt cơ trơn loại Papaverin. Dùng trong trường hợp dọa sẩy thai, dọa đẻ non và rau tiền đạo ra máu.\n- Spasmaverin được bào chế ưới dạng viên nén hoặc viên nang 40mg.\n+ Ngày uống 2 - 3 lần, mỗi lần 1 - 2 viên.\n+ Viên đạn 1 - 2 viên/ngày.\n- Chống chỉ định: huyết áp thấp và các trường hợp giảm huyết áp.\n3.1.3. Phloroglucinol (Spasfon)\n- Tác dụng: thuốc làm dãn cơ, chống co thắt hướng cơ. Spasfon có tác dụng ly giải co thắt trên sợi cơ trơn và làm dịu cơn đau.\n- Không tác dụng trên tim mạch nên sử dụng tốt hơn các loại giảm co khác như Atropin, Papaverin, Salbutamol.\n- Trên tử cung, Spasfon làm mềm đoạn ưới và cổ tử cung nhưng không ức chế những cơn co ở thân tử cung, o đó không cản trở sự tiến triển của ngôi thai và nhất là không gây băng huyết sau đẻ, điều trị cổ tử cung chậm mở.\n- Spasfon có 4 dạng bào chế: ống tiêm 80mg, viên đạn và viên nén 80mg, bột đông khô đường uống (ngậm tan).\n- Liều dùng:\n+ Điều trị tấn công: 1 - 3 ống/ngày tiêm bắp hoặc tĩnh mạch.\n+ Điều trị duy trì: uống 2 viên x 3 lần/ngày hoặc 1 viên đặt x 3 lần/ngày.\n+ Viên ngậm tan 2 viên/ngày uống lúc có cơn đau, có thể lặp lại nếu co thắt nhiều. Có thể hoà viên bột đông khô trong nước để uống hoặc ngậm dưới lưỡi sẽ có tác dụng nhanh.\n- Tác dụng phụ: hiếm gặp.\n+ Thường gặp là phản ứng dị ứng da nhưng đôi khi bị nặng: phát ban, nổi mề đay, phù Quink.\n+ Tiêm bắp và tĩnh mạch có thể gây hạ huyết áp.\n- Chống chỉ định:\n+ Quá mẫn cảm với một trong thành phần của thuốc này\n+ Không nên dùng phối hợp với các thuốc giảm đau mạnh như Morphine và các dẫn xuất của thuốc này.\n3.1.4. Atropin sunfat\n- Là thuốc có tác dụng làm giảm cường độ và tần số co bóp của cơ tử cung đồng thời có thể làm cổ tử cung mềm ra và dễ dãn nở hơn.\n- Ở nước ta thuốc được bào chế dưới dạng tiêm mỗi ống có 0,25mg hay 1/4mg.\n- Liều dùng trung bình 1 - 2 ống.\n- Thuốc có những tác dụng phụ:\n+ Giảm tiết nước bọt (khô miệng, khó nuốt).\n+ Tim đập nhanh.\n+ Giảm tiết mồ hôi làm khô da, có khi làm đỏ da.\n+ Đồng tử (con ngươi) bị giãn.\n- Chống chỉ định: suy thận nặng, glôcôm.\n3.2. Nhóm thuốc đồng vận β - mimetic\nCác loại bêta - mimetic là các thuốc hướng beta giao cảm: gồm có cá thuốc như salbutamol, ritodrine, terbutaline.\n3.2.1. Salbutamol\n- Salbutamol là thuốc ãn cơ được sử dụng trong điều trị về các bệnh đường dẫn khí như hen phế quản, viêm phế quản co thắt.\n- Salbutamol có tác dụng làm giãn cơ tử cung, làm giảm biên độ và tần số cơn co tử cung. Thuốc làm tăng quá trình oxy hoá trong bánh rau, làm tăng vận chuyển tuần hoàn thai mẹ và tăng sự phát triển của thai.\n- Thuốc được duy trì trong huyết tương trong suốt 12 giờ sau chỉ một liều uống.\n- Các dạng thuốc được sử dụng:\n+ Dạng viên: viên nén 2mg và 4mg.\n+ Dạng tiêm truyền tĩnh mạch: ống 5ml chứa 5mg.\n- Cách dùng:\n+ Salbutamol 2mg uống 2 viên/lần.\n+ Dạng ống 5mg/5ml pha trong 500ml dung dịch Glucose 5% hoặc NaCl 0,9% truyền tĩnh mạch.\n- Tác dụng phụ của Salbutamol:\n+ Bứt rứt và run, nhức đầu, lo lắng, buồn nôn, suy nhược, mất ngủ, chóng mặt, đánh trống ngực, đau ngực, thở nông, mất ngủ, buồn nôn, suy nhược, hoa mắt, vã mồ hôi.\n+ Các rối loạn về tim mạch: nhịp tim tăng thường đi kèm với hồi hộp, hốt hoảng, cung lượng tim tăng, hạ huyết áp tâm trương (huyết áp tối thiểu).\n+ Nổi mề đay hiếm gặp.\n+ Đối với thai: nhịp tim thai tăng. Nếu dùng kéo dài có thể giảm kali, hạ đường huyết.\n- Chống chỉ định:\n+ Không được dùng Salbutamol trong các trường hợp chảy máu âm đạo (rau bong non, rau tiền đạo).\n+ Thai phụ mắc bệnh tim, loạn nhịp tim, tăng huyết áp.\n+ Đái tháo đường, cường tuyến giáp, hạ kali huyết.\n+ Viêm màng ối mạn tính.\n3.2.2. Ritodrine\nRitodrine là thuốc có tác dụng trực tiếp làm giảm cơ trơn của tử cung và của phổi. Pha 150mg trong 500ml dung dịch mặn đẳng trương.\n+ Liều tấn công: bắt đầu truyền với tốc độ 20ml/giờ và cứ 15 phút tăng lên 10ml/giờ và tăng tối đa là 70ml/giờ.\n+ Liều duy trì: khi cắt được cơn tiếp tục duy trì thêm 12 giờ. Trước khi rút đường truyền 30 phút cho uống Ritodrine cứ 2 giờ 10mg trong 24 giờ và sau đó duy trì ở liều 20mg/4- 6 giờ cho đến khi thai  được 36 tuần. Ngưng thuốc khi nhịp tim mẹ trên 150 lần /phút và tim thai trên 200 lần/ phút. HA max > 180mmHg và HA min <  40mmHg.\n+ Tác dụng phụ trên mẹ bao gồm: tăng nhịp tim, tăng đường huyết, tăng Insuline huyết, hạ Kali huyết, rùng mình, đánh trống ngực, bồn chồn, buồn nôn, nôn, ảo giác.\n+ Tác động lên thai nhi: nhịp tim nhanh, hạ canxi huyết, hạ đường huyết, hạ huyết áp, tăng bilirubine huyết, xuất huyết não thất.\n+ Chống chỉ định trong bệnh tim, cường giáp, tăng huyết áp không kiểm soát được, đái tháo đường nặng, các bện gan và bệnh thận mạn tính. Các bệnh nhân trên 35 tuổi cũng có chống chỉ định.\n3.2.3. Terbutaline\nTerbutaline là thuốc có chỉ định, chống chỉ định giống Ritodrine.\n+ Liều tấn cụng: liều khởi đầu 250mcg, truyền TM với tốc độ 10ư80 àg/phỳt cho đến khi chuyển dạ ngừng lại. Sau đú tiờm dưới da 0,25ư0,5mg/2ư 4giờ trong 12 giờ tiếp theo.\n+ Liều duy trì: liều uống 5mg cứ 4- 6 giờ một lần cho đến khi thai đươc 36 tuần. Tác dụng phụ trên bà mẹ: loạn nhịp, phù phổi, thiếu máu cơ tim, hạ huyết áp, nhịp tim nhanh. Tác động lên thai nhi: nhịp tim nhanh, tăng đường huyết, tăng Insuline huyết, phì đại cơ tim, thiếu máu cơ tim.\n3.3. Thuốc đối vận Oxytocin: Atosiban (tractocile)\nAtosiban là một đồng phân nhưng đối vận với Oxytocin,  có khả năng ức chế cạnh tranh trên thụ thể của oxytocin ở cơ tử cung và màng rụng. Do tác dụng đặc hiệu trên tử cung nên an toàn hơn thuốc giảm co khác.\n+ Tác dụng phụ hiếm gặp trên mẹ là buồn nôn, nhức đầu, chong mặt, nhịp nhanh, cao huyết áp, tăng đường huyết và phản ứng dị ứng.\n+ Tác dụng trên thai không đáng kể\n+ Liều lượng và đường dùng khuyến cáo bao gồm 3 bước (bảng 2). Thời gian điều trị không nên vượt quá 48 giờ và tổng liều điều trị không quá 330mg.\n\n3.4. Thuốc chẹn kênh Calci - Nifedipine\nNifedipine tác dụng trên cơ trơn làm giãn các loại cơ trơn: khí- phế quản, tiêu hóa, tử cung, nhưng đặc biệt là thành mạch (mao động mạch nhạy cảm hơn mao tĩnh mạch).\n+  Liều tấn công: 20mg ngậm dưới lưỡi mỗi 20 phút, tối đa 3 liều.\n+ Sau  khi đã cắt cơn co thì duy trì liều 10-20mg đường uống trong mỗi 4-6 giờ.\n+ Chống chỉ định đối với bệnh tim, huyết áp thấp (< 90/50 mmHg).\n+ Không sử dụng cùng với Magnesium sulphate.\n+ Cẩn thận khi sử dụng cho người có bệnh lý ở thận.\n+ Tác dụng phụ trên bà mẹ: tác dụng nhẹ, không cần ngừng điều trị: cơn nóng bừng, nhức đầu, chóng mặt (do phản xạ giãn mạch, tăng nhịp tim nên dùng cùng với thuốc chẹn ( giao cảm), buồn nôn, táo.\nTác dụng nặng hơn, liên quan đến tác dụng điều trị do ức chế quá mạnh kênh Ca: tim đập chậm, nghẽn nhĩ thất, suy tim xung huyết, ngừng tim. Hiếm gặp.\n+ Tác động lên thai nhi: hiện chưa có ghi nhận đặc biệt gì.\nĐặc tính\nsalbutamol\nnifedipine\nAtosiban(tractocile)\n\nNhóm thuốc\nĐồng vận beta\nChẹn kênh canxi\nĐối kháng oxytocine\n\nĐược duyệt chính thức cho chỉ định sinh non\nCó\nKhông\nCó\n\nChống chỉ định\nLoạn nhịp\nBệnh tuyến giáp, tiểu đường không được kiểm soát tốt\nBệnh tim, bệnh lý thận, huyết áp thấp ở người mẹ, không dùng chung với MgSO4,\nKhông\n\nTác dụng phụ lên người mẹ\nLoạn nhịp tim, loạn nhịp thở, phù phổi, thiếu máu cơ tim, tụt huyết áp, nhịp tim nhanh, thở gấp, tăng glucose máu, hạ kali máu, run, lo lắng, buồn nôn, nôn mửa\nBừng mặt, nhức đầu, tụt huyết áp thoáng qua, nhịp tim nhanh thoáng qua, đánh trống ngực\nBuồn nôn, nhức đầu, phản ứng dị ứng\n\nTác dụng phụ lên thai nhi & trẻ sơ sinh\nNhịp tim nhanh, tăng insuline máu, tăng glucose thai, hạ glucose, calci máu ở trẻ sơ sinh, phì đại cơ tim và vách ngăn, thiếu máu cơ tim, tắc ruột\nThai chết bất ngờ, tình trạng nguy hiểm cho thai\nĐến nay chưa được ghi nhận\n\n\n3.5. Magnesium Sulfate\nMagnesium sulfate là thuốc thay thế cho các thuốc beta hướng giao cảm khi có chống chỉ định dùng các thuốc này hoặc khi có ngộ độc thuốc.\n- Liều tấn công: 4-6g trong 100ml Dextrose 5% truyền tĩnh mạch từ 15-20 phút.\n+ Liều duy trì: 2g/giờ truyền TM, trong vòng 12 giờ, sau đó là 1g/1 giờ trong 24 -48 giờ. Theo dõi nồng độ Mg++ huyết thanh duy trì từ 5-7mg/dL.\n- Tác dụng phụ:\n+ Trên bà mẹ: nóng bừng, ngủ lịm, đau đầu, mệt mỏi, khô miệng, ức chế hô hấp, giảm phản xạ gân xương. Thử phản xạ gân xương để phát hiện quá liều thuốc.\n+ Ngừng tim và hô hấp có thể xuất hiện nếu dùng quá liều. Có thể dùng chất đối kháng là Calci (Calcium gluconate hoặc calci clorua liều 1g tiêm TM chậm).\n+ Tác động lên thai nhi: ngủ lịm, giảm trương lực cơ, suy hô hấp.\n3.6. Thuốc ức chế men tổng hợp Prostaglandin (indomethacin)\n- Indomethacin liều 25mg/6 giờ trong 5 ngày hoặc nhét hậu môn 100mg sau đó uống 25mg/6 giờ cho đến 24 giờ sau khi không còn cơn gò nữa.\n- Thuốc này có những tác động ngược trên thai nhi: co thắt ống động mạch, tăng áp lực phổi, thiểu ối, xuất huyết não thất, viêm ruột hoại tử và tăng bilirubine huyết.\nCâu hỏi:\n1. Trình bày rối loạn tăng co bóp tử cung: Nguyên nhân, triệu chứng, hậu quả, hướng xử trí?\n2. Trình bày rối loạn giảm co bóp tử cung: Nguyên nhân, triệu chứng, hậu quả và hướng xử trí?\n3. Trình bày các thuốc tăng co bóp tử cung sử dụng trong sản khoa ?\n4. Trình bày các thuốc giảm co sử dụng trong thai kỳ và trong chuyển dạ đẻ?", "priority": "Trung bình"}, {"id": "SK-11", "chapter": "Chương 1. Sản thường", "folder": "01_San_thuong", "title": "Những yếu tố tiên lượng một cuộc đẻ", "author": "Ts. Bùi Minh Tiến", "word_count": 2895, "line_count": 142, "key_numbers": ["1 cm", "1 phút", "10 cm", "18 giờ", "2500 g", "3 cm", "3500 g", "41 tuần", "60 phút", "7 giờ", "8 giờ"], "key_drugs": ["oxytocin"], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["NHỮNG YẾU TỐ TIÊN LƯỢNG MỘT CUỘC ĐẺ"], "bullets": []}, {"heading": "1.1. Tiên lượng cuộc đẻ là gì?", "paragraphs": ["Tiên lượng cuộc đẻ là sự đánh giá của người thầy thuốc sau khi đã thăm khám một sản phụ để dự đoán cuộc đẻ sắp tới sẽ diễn ra bình thường hay khó khăn, có phải can thiệp không và can thiệp bằng cách nào là tối ưu để đảm bảo an toàn cho mẹ và con, phòng ngừa những tai biến có thể xảy ra trước, trong và sau khi đẻ.", "Tiên lượng cuộc đẻ không phải là dễ, đòi hỏi người thầy thuốc phải có kiến thức, có kinh nghiệm và quan trọng hơn cả là có thái độ nghiêm túc trong thăm khám và theo dõi sản phụ mới có thể tiên lượng được tốt và không để xảy ra tai biến."], "bullets": []}, {"heading": "1.2. Quan niệm về một cuộc đẻ bình thường", "paragraphs": ["Quan niệm về một cuộc đẻ bình thường bao gồm nhiều yếu tố:", "Sản phụ đẻ tự nhiên theo đường dưới sau một cuộc cuộc chuyển dạ xảy ra bình thường.", "Trong chuyển dạ cũng như khi đẻ không phải can thiệp bất cứ thuốc men gì hoặc thủ thuật, phẫu thuật nào.", "Không có biến cố nào xảy ra cho mẹ và con khi chuyển dạ, khi đẻ và sau đẻ (trong suốt thời kỳ hậu sản)", "Một số chỉ tiêu cụ thể đã được nêu ra để đánh giá một cuộc đẻ bình thường:", "Mẹ khỏe mạnh: không có bệnh (cấp, mạn tính), không có dị tật và di chứng bệnh (toàn thân, sinh dục) không có tiền sử đẻ khó, băng huyết...", "Không có biến cố trong khi có thai lần này.", "Tuổi thai: 37 - 41 tuần.", "Thai một - ngôi chỏm.", "Chuyển dạ tự nhiên.", "Cơn co tử cung bình thường theo sự tiến triển của cuộc chuyển dạ.", "Nhịp tim thai ổn định trong suốt thời kỳ chuyển dạ.", "Tình trạng ối bình thường (không đa ối, không thiểu ối, nước ối không có phân xu, không có ối vỡ non và ối vỡ sớm).", "Thời gian chuyển dạ bình thường trung bình 16 - 18 giờ.", "Thời gian rặn đẻ bình thường (dưới 60 phút).", "Thai sổ tự nhiên không cần can thiệp (trừ cắt tầng sinh môn).", "Không phải dùng bất cứ thuốc gì, kể cả việc cho thở oxy.", "Thai đẻ ra cân nặng trên 2500 g, Apgar sau 1 phút đầu phải từ 8 điểm trở lên.", "Không có tai biến gì xảy ra cho mẹ và con trong suốt thời kỳ hậu sản."], "bullets": []}, {"heading": "1.3. Thế nào là yếu tố tiên lượng", "paragraphs": ["Yếu tố tiên lượng là các dữ kiện được phát hiện khi hỏi sản phụ, khi thăm khám và trong quá trình theo dõi giúp cho người thầy thuốc đánh giá, dự đoán về diễn biến của cuộc chuyển dạ và quá trình đẻ. Các dữ kiện đó nếu trong phạm vi bình thường thì đó là các yếu tố tiên lượng tốt.", "Ngược lại, nếu trong các dữ kiện thu thập được, có những dấu hiệu, những chỉ số không bình thường thì cuộc đẻ có thể gặp khó khăn, tai biến có thể xảy ra. Trong trường hợp đó tiên lượng cuộc đẻ là dè dặt, là xấu và các yếu tố tiên lượng lúc đó là các yếu tố gây nguy cơ cho sức khỏe và tính mạng của cả mẹ và thai nhi. Ví dụ mẹ lùn, thấp (thường có khung chậu hẹp) thai to, u tiền đạo, đẻ nhiều lần, ngôi bất thường, sẹo mổ ở tử cung, nạo thai nhiều lần, rối loạn cơn co tử cung, chuyển dạ lâu..."], "bullets": []}, {"heading": "2.1. Yếu tố tiên lượng có sẵn từ trước", "paragraphs": ["Là những dấu hiệu đã có sẵn ở người thai phụ. Đó là những yếu tố tiên lượng không thể thay đổi được, hầu như đó là những yếu tố nguy cơ cao trong thai nghén."], "bullets": []}, {"heading": "2.1.1. Yếu tố tiên lượng xấu từ người mẹ", "paragraphs": ["a. Tình trạng bệnh lý của mẹ có từ trước lúc có thai: các bệnh tim, bệnh phổi, bệnh gan, bệnh thận, bệnh cao huyết áp, thiếu máu, sốt rét, suy dinh dưỡng, bệnh ngoại khoa (sẹo mổ viêm phúc mạc, thủng tạng rỗng, vỡ tạng đặc...) và cả các bệnh phụ khoa: u xơ tử cung, u nang bồng trứng, sa sinh dục, rò tiết niệu - sinh dục.", "b. Các bệnh cấp tính hoặc mạn tính mắc phải trong lúc đang có thai lần này và các bệnh do thai nghén mà có: nhiễm độc thai nghén, sốt, viêm ruột thừa và thai nghén, xoắn ruột...", "c. Các dị tật hoặc di chứng bệnh từ khi còn bé: các dị dạng sinh dục (tử cung nhi tính, vách ngăn âm đạo, tử cung đôi, tử cung co vách ngăn...). khung xương chậu hẹp, khung xương chậu lệch do còi xương, lao, chấn thương (gẫy xương, trật khớp), di chứng bại liệt...", "d. Tuổi mẹ quá trẻ (dưới 18 tuổi), lớn tuổi (trên 35 tuổi).", "e. Mẹ đẻ nhiều lần (4 lần trở lên), mẹ có tiền sử năng nề về thai nghén và sinh đẻ: điều trị vô sinh, sẩy thai liên tiếp, đẻ non, thai chết lưu, con chết ngạt, đã phải đẻ can thiệp (giác hút, forcept, mổ đẻ...) đã có lần bị băng huyết khi đẻ.", "Có yếu tố di truyền từ người mẹ hay người bố. Hoàn cảnh gia đình nghèo khó, thất học, lạc hậu về nhận thức..."], "bullets": []}, {"heading": "2.1.2. Yếu tố tiên lượng xấu từ phía thai", "paragraphs": ["a. Đa thai: sinh đôi, sinh ba.", "b. Ngôi thai bất thường: ngôi mặt cằm sau, ngôi trán, ngôi vai, ngôi mông.", "c. Thai to: Thai to bình thường (> 3500 g), thai to bệnh lý, thai dị dạng.", "d. Thai non tháng, thai suy dinh dưỡng, suy thai mạn tính, thai già tháng.", "e. Các bệnh lý bẩm sinh khác của thai khi còn trong bụng mẹ."], "bullets": []}, {"heading": "2.1.3. Yếu tố tiên lượng xấu từ phần phụ của thai", "paragraphs": ["a. Bánh rau: rau bám thấp, rau tiền đạo, rau bong non, suy rau, bánh rau phụ...", "b. Về dây rốn: Sa dây rau trong bọc ối, sa bên ngôi, hoặc sa hẳn ra ngoài. Dây rau thắt nút, dây rau cuốn cổ, quấn thân..."], "bullets": []}, {"heading": "2.2. Yếu tố tiên lượng phát sinh trong chuyển dạ", "paragraphs": ["Đó là những dấu hiệu, những triệu chứng chưa có hoặc chưa phát hiện được lúc ban đầu của thời kỳ chuyển dạ mà chỉ mới xuất hiện trong quá trình diễn biến của chuyển dạ."], "bullets": []}, {"heading": "2.2.1. Toàn thân của mẹ", "paragraphs": [], "bullets": ["- Các cơn đau do co bóp tử cung khiến bà mẹ lo lắng, sợ hãi, kêu la gây ảnh hưởng xấu đến quá trình chuyển dạ.", "- Cuộc chuyển dạ kéo dài làm sản phụ mệt mỏi, đói lả, kiệt sức vì không ăn được.", "- Những thay đổi về mạch, huyết áp, nhiệt độ do nguyên nhân tâm lý sợ hãi hay do bội nhiễm."]}, {"heading": "2.2.2. Diễn biến của cơn co tử cung", "paragraphs": ["a. Cơn co tử cung là động lực của cuộc chuyển dạ. Bình thường cơn co tử cung xuất phát từ một điểm hay gặp là từ sừng phải tử cung, lan xuống dưới cổ tử cung theo quy luật 3 giáng:", "Về mặt lâm sàng: các cơn co ban đầu: yếu, ngắn, thưa. Càng về sau càng mạnh, dài, mau.", "b. Các rối loạn cơn co tử cung có thể gặp trong chuyển dạ:", "Tình trạng rối loạn cơn co trong chuyển dạ thường có nguyên nhân thực thể, thường là do tình trạng thai bị cản trở (ngừng trệ chuyển dạ), không tiến triển thuận lợi (lọt, xuống, quay, sổ, thai to, ngôi cúi không tốt, khung chậu hẹp)...mà khi thăm khám trước đó chưa phát hiện được. Đó là những đẻ khó ”cơ học” cần khám xét kỹ để tìm nguyên nhân. Nếu không thấy nguyên nhân nào thực thể thì tạm thời coi như rối loạn ”cơ năng” gây đẻ khó do động lực và có thể dùng thuốc giảm co bóp để điều trị. Nếu không có kết quả vẫn phải mổ lấy thai."], "bullets": ["- Từ trên xuống dưới.", "- Cường độ giảm dần.", "- Thời gian co giảm dần.", "- Rối loạn tăng co bóp:", "+ Tăng cường độ (cơn co mạnh)", "+ Tăng tấn số (cơn co mau)", "+ Tăng cả hai (cơn co mạnh và mau)", "- Tăng trương lực cơ bản:", "+ Do co thắt (trong rau bong non)", "+ Do dãn căng (trong đa ối, sinh đôi)", "+ Do co bóp tăng kéo dài (do lạm dụng oxytoxin)", "- Rối loạn giảm co bóp:", "+ Giảm cường độ (cơn co yếu)", "+ Giảm tần số (cơn co thưa)", "+ Giảm cơn co toàn bộ (cơn co yếu và thưa)."]}, {"heading": "2.2.3. Xóa mở cổ tử cung", "paragraphs": ["a. Bình thường trong quá trình chuyển dạ cổ tử cung sẽ xóa mở dần từ 1 cm đến 10 cm. Các yếu tố thuận lợi về tiên lượng có thể là:", "b. Các yếu tố không tốt có thể gặp:"], "bullets": ["- Về vị trí: Cổ tử cung phải ở chính giữa tiểu khung.", "- Về mật độ: cổ tử cung phải mềm, xóa hết thì mỏng và ôm lấy đầu ối hoặc ngôi thai (nếu ối đã vỡ, không cứng rắn, không phù nề).", "- Về tốc độ mở:", "+ Ở người con so:từ 1 cm đến 3 cm trung bình 8 giờ", "+ Từ 3 cm đến 10 cm thời gian trung bình 7 giờ", "- Khi thăm khám cổ tử cung dày, cứng, phù nề, lỗ trong co thắt. Đặc biệt ở những thai phụ có tiền sử điều trị đốt nhiệt, đốt điện, đốt hóa chất, khoét chóp, cắt đoạn cổ tử cung.... thì tiên lượng xóa mở rất xấu.", "- Khi theo dõi tiến triển cổ tử cung mở chậm hoặc không mở thêm sau mỗi lần thăm khám."]}, {"heading": "2.2.4. Đầu ối", "paragraphs": ["a. Tiên lượng tốt khi đầu ối dẹt, màng ối không quá dày, ối vỡ đúng lúc (khi cổ tử cung mở hết) không có tình trạng đa ối hay thiểu ối, nước ối bình thường không có lẫn phân xu.", "b. Tiên lượng không tốt khi đầu ối phồng hay hình quả lê, màng ối dày, ối vỡ non, ối vỡ sớm sẽ kéo theo nhiều nguy cơ khác: sa dây rau, sa chi, nhiễm khuẩn...Nước ối có phân xu biểu hiện sự suy thai. Nước ối có máu trong rau bong non, chảy máu ở các mạch máu bánh rau."], "bullets": []}, {"heading": "2.2.5. Tim thai", "paragraphs": ["Trong chuyển dạ tùy theo tình trạng thai nhi mà cho phép chúng ta tiếp tục theo dõi cuộc chuyển dạ hoặc ngừng cuộc chuyển dạ. Suy thai là hậu quả của nhiều nguyên nhân:", "Hình 1: Các nguyên nhân gây suy thai", "Tình trạng thai nhi trong tử cung sẽ quyết định cách xử trí. Thai sống tốt là dấu hiệu tốt. Thai đã suy phải xử trí ngay. Thai chết thì không đặt vấn đề cấp cứu nữa. Vì vậy tim thai phải được theo dõi sát sao liên tục là rất quan trọng."], "bullets": []}, {"heading": "2.2.6. Độ lọt của ngôi thai", "paragraphs": ["a. Khi ngôi thai tiến triển thuận lợi cùng với sự tiến triển của quá trình chuyển dạ, tiên lượng sẽ tốt khi ngôi thai cứ di chuyển dần từ cao xuống thấp. Cổ điển cho rằng ở người con so khi bước vào chuyển dạ ngôi thai đã phải lọt từ trước rồi (hiện tượng sụt bụng vào những tuần lễ cuối của thai nghén). Còn ở người con rạ chỉ trong khi chuyển dạ ngôi thai mới lọt. Thực ra trên thực tế ít khi gặp ngôi thai đã lọt khi mới bắt đầu chuyển dạ ở người con so. Trên biểu đồ chuyển dạ mức độ tiến triển của ngôi ta sẽ thấy hướng của đường biểu diễn sự tiến triển của ngôi đi ngược với hướng của đường biểu diễn độ mở cổ tử cung (Hình 2)", "Hình 2: Đường biểu diễn độ mở cổ tử cung và tiến triển của ngôi", "b. Tiên lượng không tốt trong tiến triển của ngôi thai:", "Hình 3: Đầu chờm vệ (dấu hiệu Vastin)", "Hình 4: Lọt giả do bướu huyết thanh", "Hình 5: Lọt giả do xương so không chồng khớp nặng"], "bullets": ["- Đầu luôn chờm vệ (Dấu hiệu Vastin ở hình 3)", "- Ngôi thai không tiến triển hoặc tiến triển ở mức độ nào đó thì dừng lại ngừng tiến triển (đầu không lọt) mặc dù cơn co tử cung tốt, thậm chí còn tăng co bóp. Thăm trong thường thấy các xương sọ của thai chồng khớp nhiều hay ít. Khi đánh giá mức độ tiến triển của ngôi thai cần hết sức lưu ý đến những trường hợp lọt giả (hình 4 và 5), nếu nhầm lẫn sẽ gây hậu quả nghiêm trọng khi quyết định xử trí.", "- Độ lọt bị ngừng trệ nếu:", "+ Cơn co tử cung chưa đủ mạnh, không đều", "+ Ối vỡ sớm làm ngôi bình chỉnh không tốt.", "+ Cổ tử cung không mở", "+ Ngôi thế không thuận lợi do đầu cúi không tốt.", "+ Các yếu tố kín đáo như dây rau ngắn, dây rau cuốn cổ, rau bám thấp."]}, {"heading": "2.2.7 Các tai biến khi chuyển dạ", "paragraphs": ["a. Rau tiền đạo", "Việc tiên lượng trước hết là phải đánh giá được khối lượng máu chảy từ trước khi vào bệnh viện. Nếu chảy máu đã nhiều có hiện tượng suy thai và đe dọa tính mạng của người mẹ thì phải xử trí ngay. Tiên lượng còn phụ thuộc vào yếu tố phân loại rau tiền đạo:", "b. Rau bong non", "Nếu chẩn đoán là rau bong non thì mổ lấy thai ngay để cứu con và phòng biến chứng nặng hơn cho mẹ", "Khi đã co dấu hiệu choáng, trương lực cơ tử cung bắt đầu tăng, tử cung có xu hướng cứng liên tục thì vấn đề xử trí để cứu mẹ là chính. Hồi sức, chống choáng, chống chảy máu do rối loạn đông máu, mổ cắt tử cung, nếu bảo tồn được tử cung thì rất cần thiết và có điều kiện.", "c. Dọa vỡ tử cung", "Chỉ định mổ hoặc forceps khi đủ điều kiện.", "d. Vỡ tử cung", "Mổ, hồi sức, chống nhiễm khuẩn và rối loạn đông máu. Bảo tồn tử cung khi thật cần thiết và có điều kiện.", "e. Sa dây rau", "Sa dây rau là tối cấp cứu đối với thai nhi. Nếu thai còn sống, dây rau còn đập thì phải mổ lấy thai cấp cứu. Nếu thai đã chết thì không đặt vấn đề cấp cứu nữa.", "g. Sa chi: Thử đẩy chi lên, nếu có thêm một yếu tố đẻ khó khác cần mổ lấy thai."], "bullets": ["- Rau tiền đạo trung tâm hoàn toàn phải mổ dù con sống hay chết.", "- Rau tiền đạo bán trung tâm hầu hết là phải mổ trừ trường hợp thai quá nhỏ và chảy máu ít.", "- Rau bám mép, bám bên phải bấm ối cầm máu. Tiên lượng đẻ đường dưới nếu sau bấm ối cầm máu được nhưng vẫn phải kiểm tra những yếu tố đẻ khó khác.", "- Loại trừ nguyên nhân do dùng oxytocin quá liều, phải cho thuốc giảm co"]}, {"heading": "3. KẾT LUẬN", "paragraphs": ["Tiên lượng cuộc đẻ cho chính xác là điều khó nhưng lại là điều bắt buộc người thầy thuôc sản khoa nào cũng phải thực hiện để tránh các tai biến có thể xảy ra đối với cả hai sinh mạng của mẹ và con.", "Công việc tuyên truyền giáo dục sức khỏe trong nhân dân, nhất là với phụ nữ, việc xây dựng màng lưới y tế cộng đồng làm tốt công tác chăm sóc sức khỏe sinh sản, thực hiện tốt công tác đăng ký quản lý thai, khám thai định kỳ để phát hiện những nguy cơ, lựa chon nơi đẻ an toàn nhất cho sản phụ là những công việc thiết thực góp phần hạ thấp tỷ lệ tai biến khi thai nghén và sinh đẻ. Đó cũng là giúp cho các thầy thuốc ở cơ sở điều trị làm tốt công việc tiên lượng cho một cuộc đẻ."], "bullets": []}], "raw_text": "NHỮNG YẾU TỐ TIÊN LƯỢNG MỘT CUỘC ĐẺ\nMục tiêu học tập\n1. Nêu được khái niệm các yếu tố tiên lượng cuộc đẻ\n2. Nêu được các yếu tố tiên lượng cuộc đẻ có sẵn từ trước\n3. Nêu được các yếu tố tiên lượng cuộc đẻ phát sinh trong chuyển dạu đư Nêu được các yếu tố tiên lượng cuộc đẻ phát sinh trong chuyển dạ\n1. KHÁI NIỆM CHUNG\n1.1. Tiên lượng cuộc đẻ là gì?\nTiên lượng cuộc đẻ là sự đánh giá của người thầy thuốc sau khi đã thăm khám một sản phụ để dự đoán cuộc đẻ sắp tới sẽ diễn ra bình thường hay khó khăn, có phải can thiệp không và can thiệp bằng cách nào là tối ưu để đảm bảo an toàn cho mẹ và con, phòng ngừa những tai biến có thể xảy ra trước, trong và sau khi đẻ.\nTiên lượng cuộc đẻ không phải là dễ, đòi hỏi người thầy thuốc phải có kiến thức, có kinh nghiệm và quan trọng hơn cả là có thái độ nghiêm túc trong thăm khám và theo dõi sản phụ mới có thể tiên lượng được tốt và không để xảy ra tai biến.\n1.2. Quan niệm về một cuộc đẻ bình thường\nQuan niệm về một cuộc đẻ bình thường bao gồm nhiều yếu tố:\nSản phụ đẻ tự nhiên theo đường dưới sau một cuộc cuộc chuyển dạ xảy ra bình thường.\nTrong chuyển dạ cũng như khi đẻ không phải can thiệp bất cứ thuốc men gì hoặc thủ thuật, phẫu thuật nào.\nKhông có biến cố nào xảy ra cho mẹ và con khi chuyển dạ, khi đẻ và sau đẻ (trong suốt thời kỳ hậu sản)\nMột số chỉ tiêu cụ thể đã được nêu ra để đánh giá một cuộc đẻ bình thường:\nMẹ khỏe mạnh: không có bệnh (cấp, mạn tính), không có dị tật và di chứng bệnh (toàn thân, sinh dục) không có tiền sử đẻ khó, băng huyết...\nKhông có biến cố trong khi có thai lần này.\nTuổi thai: 37 - 41 tuần.\nThai một - ngôi chỏm.\nChuyển dạ tự nhiên.\nCơn co tử cung bình thường theo sự tiến triển của cuộc chuyển dạ.\nNhịp tim thai ổn định trong suốt thời kỳ chuyển dạ.\nTình trạng ối bình thường (không đa ối, không thiểu ối, nước ối không có phân xu, không có ối vỡ non và ối vỡ sớm).\nThời gian chuyển dạ bình thường trung bình 16 - 18 giờ.\nThời gian rặn đẻ bình thường (dưới 60 phút).\nThai sổ tự nhiên không cần can thiệp (trừ cắt tầng sinh môn).\nKhông phải dùng bất cứ thuốc gì, kể cả việc cho thở oxy.\nThai đẻ ra cân nặng trên 2500 g, Apgar sau 1 phút đầu phải từ 8 điểm trở lên.\nKhông có tai biến gì xảy ra cho mẹ và con trong suốt thời kỳ hậu sản.\n1.3. Thế nào là yếu tố tiên lượng\nYếu tố tiên lượng là các dữ kiện được phát hiện khi hỏi sản phụ, khi thăm khám và trong quá trình theo dõi giúp cho người thầy thuốc đánh giá, dự đoán về diễn biến của cuộc chuyển dạ và quá trình đẻ. Các dữ kiện đó nếu trong phạm vi bình thường thì đó là các yếu tố tiên lượng tốt.\nNgược lại, nếu trong các dữ kiện thu thập được, có những dấu hiệu, những chỉ số không bình thường thì cuộc đẻ có thể gặp khó khăn, tai biến có thể xảy ra. Trong trường hợp đó tiên lượng cuộc đẻ là dè dặt, là xấu và các yếu tố tiên lượng lúc đó là các yếu tố gây nguy cơ cho sức khỏe và tính mạng của cả mẹ và thai nhi. Ví dụ mẹ lùn, thấp (thường có khung chậu hẹp) thai to, u tiền đạo, đẻ nhiều lần, ngôi bất thường, sẹo mổ ở tử cung, nạo thai nhiều lần, rối loạn cơn co tử cung, chuyển dạ lâu...\n2. CÁC YẾU TỐ TIÊN LƯỢNG MỘT CUỘC ĐẺ\n2.1. Yếu tố tiên lượng có sẵn từ trước\nLà những dấu hiệu đã có sẵn ở người thai phụ. Đó là những yếu tố tiên lượng không thể thay đổi được, hầu như đó là những yếu tố nguy cơ cao trong thai nghén.\n2.1.1. Yếu tố tiên lượng xấu từ người mẹ\na. Tình trạng bệnh lý của mẹ có từ trước lúc có thai: các bệnh tim, bệnh phổi, bệnh gan, bệnh thận, bệnh cao huyết áp, thiếu máu, sốt rét, suy dinh dưỡng, bệnh ngoại khoa (sẹo mổ viêm phúc mạc, thủng tạng rỗng, vỡ tạng đặc...) và cả các bệnh phụ khoa: u xơ tử cung, u nang bồng trứng, sa sinh dục, rò tiết niệu - sinh dục.\nb. Các bệnh cấp tính hoặc mạn tính mắc phải trong lúc đang có thai lần này và các bệnh do thai nghén mà có: nhiễm độc thai nghén, sốt, viêm ruột thừa và thai nghén, xoắn ruột...\nc. Các dị tật hoặc di chứng bệnh từ khi còn bé: các dị dạng sinh dục (tử cung nhi tính, vách ngăn âm đạo, tử cung đôi, tử cung co vách ngăn...). khung xương chậu hẹp, khung xương chậu lệch do còi xương, lao, chấn thương (gẫy xương, trật khớp), di chứng bại liệt...\nd. Tuổi mẹ quá trẻ (dưới 18 tuổi), lớn tuổi (trên 35 tuổi).\ne. Mẹ đẻ nhiều lần (4 lần trở lên), mẹ có tiền sử năng nề về thai nghén và sinh đẻ: điều trị vô sinh, sẩy thai liên tiếp, đẻ non, thai chết lưu, con chết ngạt, đã phải đẻ can thiệp (giác hút, forcept, mổ đẻ...) đã có lần bị băng huyết khi đẻ.\nCó yếu tố di truyền từ người mẹ hay người bố. Hoàn cảnh gia đình nghèo khó, thất học, lạc hậu về nhận thức...\n2.1.2. Yếu tố tiên lượng xấu từ phía thai\na. Đa thai: sinh đôi, sinh ba.\nb. Ngôi thai bất thường: ngôi mặt cằm sau, ngôi trán, ngôi vai, ngôi mông.\nc. Thai to: Thai to bình thường (> 3500 g), thai to bệnh lý, thai dị dạng.\nd. Thai non tháng, thai suy dinh dưỡng, suy thai mạn tính, thai già tháng.\ne. Các bệnh lý bẩm sinh khác của thai khi còn trong bụng mẹ.\n2.1.3. Yếu tố tiên lượng xấu từ phần phụ của thai\na. Bánh rau: rau bám thấp, rau tiền đạo, rau bong non, suy rau, bánh rau phụ...\nb. Về dây rốn: Sa dây rau trong bọc ối, sa bên ngôi, hoặc sa hẳn ra ngoài. Dây rau thắt nút, dây rau cuốn cổ, quấn thân...\n2.2. Yếu tố tiên lượng phát sinh trong chuyển dạ\nĐó là những dấu hiệu, những triệu chứng chưa có hoặc chưa phát hiện được lúc ban đầu của thời kỳ chuyển dạ mà chỉ mới xuất hiện trong quá trình diễn biến của chuyển dạ.\n2.2.1. Toàn thân của mẹ\n- Các cơn đau do co bóp tử cung khiến bà mẹ lo lắng, sợ hãi, kêu la gây ảnh hưởng xấu đến quá trình chuyển dạ.\n- Cuộc chuyển dạ kéo dài làm sản phụ mệt mỏi, đói lả, kiệt sức vì không ăn được.\n- Những thay đổi về mạch, huyết áp, nhiệt độ do nguyên nhân tâm lý sợ hãi hay do bội nhiễm.\n2.2.2. Diễn biến của cơn co tử cung\na. Cơn co tử cung là động lực của cuộc chuyển dạ. Bình thường cơn co tử cung xuất phát từ một điểm hay gặp là từ sừng phải tử cung, lan xuống dưới cổ tử cung theo quy luật 3 giáng:\n- Từ trên xuống dưới.\n- Cường độ giảm dần.\n- Thời gian co giảm dần.\nVề mặt lâm sàng: các cơn co ban đầu: yếu, ngắn, thưa. Càng về sau càng mạnh, dài, mau.\nb. Các rối loạn cơn co tử cung có thể gặp trong chuyển dạ:\n- Rối loạn tăng co bóp:\n+ Tăng cường độ (cơn co mạnh)\n+ Tăng tấn số (cơn co mau)\n+ Tăng cả hai (cơn co mạnh và mau)\n- Tăng trương lực cơ bản:\n+ Do co thắt (trong rau bong non)\n+ Do dãn căng (trong đa ối, sinh đôi)\n+ Do co bóp tăng kéo dài (do lạm dụng oxytoxin)\n- Rối loạn giảm co bóp:\n+ Giảm cường độ (cơn co yếu)\n+ Giảm tần số (cơn co thưa)\n+ Giảm cơn co toàn bộ (cơn co yếu và thưa).\nTình trạng rối loạn cơn co trong chuyển dạ thường có nguyên nhân thực thể, thường là do tình trạng thai bị cản trở (ngừng trệ chuyển dạ), không tiến triển thuận lợi (lọt, xuống, quay, sổ, thai to, ngôi cúi không tốt, khung chậu hẹp)...mà khi thăm khám trước đó chưa phát hiện được. Đó là những đẻ khó ”cơ học” cần khám xét kỹ để tìm nguyên nhân. Nếu không thấy nguyên nhân nào thực thể thì tạm thời coi như rối loạn ”cơ năng” gây đẻ khó do động lực và có thể dùng thuốc giảm co bóp để điều trị. Nếu không có kết quả vẫn phải mổ lấy thai.\n2.2.3. Xóa mở cổ tử cung\na. Bình thường trong quá trình chuyển dạ cổ tử cung sẽ xóa mở dần từ 1 cm đến 10 cm. Các yếu tố thuận lợi về tiên lượng có thể là:\n- Về vị trí: Cổ tử cung phải ở chính giữa tiểu khung.\n- Về mật độ: cổ tử cung phải mềm, xóa hết thì mỏng và ôm lấy đầu ối hoặc ngôi thai (nếu ối đã vỡ, không cứng rắn, không phù nề).\n- Về tốc độ mở:\n+ Ở người con so:từ 1 cm đến 3 cm trung bình 8 giờ\n+ Từ 3 cm đến 10 cm thời gian trung bình 7 giờ\nb. Các yếu tố không tốt có thể gặp:\n- Khi thăm khám cổ tử cung dày, cứng, phù nề, lỗ trong co thắt. Đặc biệt ở những thai phụ có tiền sử điều trị đốt nhiệt, đốt điện, đốt hóa chất, khoét chóp, cắt đoạn cổ tử cung.... thì tiên lượng xóa mở rất xấu.\n- Khi theo dõi tiến triển cổ tử cung mở chậm hoặc không mở thêm sau mỗi lần thăm khám.\n2.2.4. Đầu ối\na. Tiên lượng tốt khi đầu ối dẹt, màng ối không quá dày, ối vỡ đúng lúc (khi cổ tử cung mở hết) không có tình trạng đa ối hay thiểu ối, nước ối bình thường không có lẫn phân xu.\nb. Tiên lượng không tốt khi đầu ối phồng hay hình quả lê, màng ối dày, ối vỡ non, ối vỡ sớm sẽ kéo theo nhiều nguy cơ khác: sa dây rau, sa chi, nhiễm khuẩn...Nước ối có phân xu biểu hiện sự suy thai. Nước ối có máu trong rau bong non, chảy máu ở các mạch máu bánh rau.\n2.2.5. Tim thai\nTrong chuyển dạ tùy theo tình trạng thai nhi mà cho phép chúng ta tiếp tục theo dõi cuộc chuyển dạ hoặc ngừng cuộc chuyển dạ. Suy thai là hậu quả của nhiều nguyên nhân:\n\nHình 1: Các nguyên nhân gây suy thai\nTình trạng thai nhi trong tử cung sẽ quyết định cách xử trí. Thai sống tốt là dấu hiệu tốt. Thai đã suy phải xử trí ngay. Thai chết thì không đặt vấn đề cấp cứu nữa. Vì vậy tim thai phải được theo dõi sát sao liên tục là rất quan trọng.\n2.2.6. Độ lọt của ngôi thai\na. Khi ngôi thai tiến triển thuận lợi cùng với sự tiến triển của quá trình chuyển dạ, tiên lượng sẽ tốt khi ngôi thai cứ di chuyển dần từ cao xuống thấp. Cổ điển cho rằng ở người con so khi bước vào chuyển dạ ngôi thai đã phải lọt từ trước rồi (hiện tượng sụt bụng vào những tuần lễ cuối của thai nghén). Còn ở người con rạ chỉ trong khi chuyển dạ ngôi thai mới lọt. Thực ra trên thực tế ít khi gặp ngôi thai đã lọt khi mới bắt đầu chuyển dạ ở người con so. Trên biểu đồ chuyển dạ mức độ tiến triển của ngôi ta sẽ thấy hướng của đường biểu diễn sự tiến triển của ngôi đi ngược với hướng của đường biểu diễn độ mở cổ tử cung (Hình 2)\n\nHình 2: Đường biểu diễn độ mở cổ tử cung và tiến triển của ngôi\nb. Tiên lượng không tốt trong tiến triển của ngôi thai:\n- Đầu luôn chờm vệ (Dấu hiệu Vastin ở hình 3)\n\n\nHình 3: Đầu chờm vệ (dấu hiệu Vastin)\n- Ngôi thai không tiến triển hoặc tiến triển ở mức độ nào đó thì dừng lại ngừng tiến triển (đầu không lọt) mặc dù cơn co tử cung tốt, thậm chí còn tăng co bóp. Thăm trong thường thấy các xương sọ của thai chồng khớp nhiều hay ít. Khi đánh giá mức độ tiến triển của ngôi thai cần hết sức lưu ý đến những trường hợp lọt giả (hình 4 và 5), nếu nhầm lẫn sẽ gây hậu quả nghiêm trọng khi quyết định xử trí.\n\nHình 4: Lọt giả do bướu huyết thanh\n\n\nHình 5: Lọt giả do xương so không chồng khớp nặng\n\n- Độ lọt bị ngừng trệ nếu:\n+ Cơn co tử cung chưa đủ mạnh, không đều\n+ Ối vỡ sớm làm ngôi bình chỉnh không tốt.\n+ Cổ tử cung không mở\n+ Ngôi thế không thuận lợi do đầu cúi không tốt.\n+ Các yếu tố kín đáo như dây rau ngắn, dây rau cuốn cổ, rau bám thấp.\n2.2.7 Các tai biến khi chuyển dạ\na. Rau tiền đạo\nViệc tiên lượng trước hết là phải đánh giá được khối lượng máu chảy từ trước khi vào bệnh viện. Nếu chảy máu đã nhiều có hiện tượng suy thai và đe dọa tính mạng của người mẹ thì phải xử trí ngay. Tiên lượng còn phụ thuộc vào yếu tố phân loại rau tiền đạo:\n- Rau tiền đạo trung tâm hoàn toàn phải mổ dù con sống hay chết.\n- Rau tiền đạo bán trung tâm hầu hết là phải mổ trừ trường hợp thai quá nhỏ và chảy máu ít.\n- Rau bám mép, bám bên phải bấm ối cầm máu. Tiên lượng đẻ đường dưới nếu sau bấm ối cầm máu được nhưng vẫn phải kiểm tra những yếu tố đẻ khó khác.\nb. Rau bong non\nNếu chẩn đoán là rau bong non thì mổ lấy thai ngay để cứu con và phòng biến chứng nặng hơn cho mẹ\nKhi đã co dấu hiệu choáng, trương lực cơ tử cung bắt đầu tăng, tử cung có xu hướng cứng liên tục thì vấn đề xử trí để cứu mẹ là chính. Hồi sức, chống choáng, chống chảy máu do rối loạn đông máu, mổ cắt tử cung, nếu bảo tồn được tử cung thì rất cần thiết và có điều kiện.\nc. Dọa vỡ tử cung\n- Loại trừ nguyên nhân do dùng oxytocin quá liều, phải cho thuốc giảm co\nChỉ định mổ hoặc forceps khi đủ điều kiện.\nd. Vỡ tử cung\nMổ, hồi sức, chống nhiễm khuẩn và rối loạn đông máu. Bảo tồn tử cung khi thật cần thiết và có điều kiện.\ne. Sa dây rau\nSa dây rau là tối cấp cứu đối với thai nhi. Nếu thai còn sống, dây rau còn đập thì phải mổ lấy thai cấp cứu. Nếu thai đã chết thì không đặt vấn đề cấp cứu nữa.\ng. Sa chi: Thử đẩy chi lên, nếu có thêm một yếu tố đẻ khó khác cần mổ lấy thai.\n3. KẾT LUẬN\nTiên lượng cuộc đẻ cho chính xác là điều khó nhưng lại là điều bắt buộc người thầy thuôc sản khoa nào cũng phải thực hiện để tránh các tai biến có thể xảy ra đối với cả hai sinh mạng của mẹ và con.\nCông việc tuyên truyền giáo dục sức khỏe trong nhân dân, nhất là với phụ nữ, việc xây dựng màng lưới y tế cộng đồng làm tốt công tác chăm sóc sức khỏe sinh sản, thực hiện tốt công tác đăng ký quản lý thai, khám thai định kỳ để phát hiện những nguy cơ, lựa chon nơi đẻ an toàn nhất cho sản phụ là những công việc thiết thực góp phần hạ thấp tỷ lệ tai biến khi thai nghén và sinh đẻ. Đó cũng là giúp cho các thầy thuốc ở cơ sở điều trị làm tốt công việc tiên lượng cho một cuộc đẻ.\nCâu hỏi:\n1. Anh (Chị) trỡnh bày các yếu tố tiên lượng cuộc đẻ cú sẵn từ trước về phía mẹ?\n2. Anh (Chị) trỡnh bày các yếu tố tiên lượng cuộc đẻ cú sẵn từ trước về phía thai và phần phụ của thai?\n4. Anh (Chị) trỡnh bày các yếu tố tiên lượng cuộc đẻ phỏt sinh trong chuyển dạ ?\n5. Anh (Chị) trỡnh bày các tai biến cuộc đẻ phỏt sinh trong chuyển dạ về phía con?", "priority": "Trung bình"}, {"id": "SK-12", "chapter": "Chương 1. Sản thường", "folder": "01_San_thuong", "title": "Sổ rau thường", "author": "TS. Bùi Minh Tiến", "word_count": 1035, "line_count": 59, "key_numbers": ["15 phút", "2 phút", "30 phút", "60cm"], "key_drugs": ["oxytocin"], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["SỔ RAU THƯỜNG", "TS. Bùi Minh Tiến"], "bullets": []}, {"heading": "1. ĐẠI CƯƠNG", "paragraphs": ["Sổ rau là giai đoạn III của cuộc chuyển dạ. Bình thường, giai đoạn này kéo dài trung bình 30 phút. Sự bong rau xảy ra ở lớp nông (lớp đặc) của màng rụng.", "Sự bong rau xảy ra qua 3 thì:", "Hình 1. Giai đoạn sổ rau"], "bullets": ["- Thì bong: sau khi sổ thai, tử cung co lại nhưng vì bánh rau có  tính chất đàn hồi kém nên co rúm lại, dày lên, lớp rau chờm ra ngoài vùng rau bám. Các gai rau bị kéo căng, mạch máu lớp xốp đứt gây chảy máu. Trọng lượng cục máu sau rau làm cho rau bong tiếp. Có 2 kiểu bong rau: Baudelocque và Duncan.", "- Thì sổ rau: dưới tác dụng của cơn co tử cung, rau bong kéo theo màng ối xuống đoạn dưới, rồi xuống âm đạo và ra ngoài.", "- Thì cầm máu: nhờ sự co bóp của tất cả các sợi cơ tử cung và cơ chế đông máu bình  thường. Sau sổ rau tử cung co lại thành một khối an toàn."]}, {"heading": "2.1 Các dấu hiệu bong rau", "paragraphs": [], "bullets": ["- Dây rốn xuống thấp.", "- Máu chảy ra qua âm đạo báo hiệu rau bong khỏi thành tử cung.", "- Sự thay đổi đáy tử cung từ dạng đĩa sang khối cầu."]}, {"heading": "2.2.1 Bong rau kiểu Baudelocque", "paragraphs": ["Rau được bong từ trung tâm ra bìa của bánh rau. Toàn bộ máu cục tụ lại sau rau nên khi rau ra ngoài ta thấy nội sản mạc ra trước. Kiểu bong này ít gây sót rau và sót màng, loại bong rau này chiếm tỉ lệ 75%.", "Hinh 2.  Bong rau kiểu Baudelocque"], "bullets": []}, {"heading": "2.2.2 Bong rau kiểu Duncan:\tRau được bong từ rìa của bánh rau và các màng xung quanh vào giữa, làm cho một phần huyết tụ sau rau, một phần chảy ra ngoài âm đạo nhiều. Khi rau ra ngoài ta thấy màng rụng ra trước. Kiểu bong này chiếm tỉ lệ 25% và thường gây chảy máu, sót rau và màng.", "paragraphs": ["Hinh 3. Bong rau kiểu Duncan"], "bullets": []}, {"heading": "2.3. Các cách sổ rau", "paragraphs": [], "bullets": ["- Sổ rau tự động: Cả 3 thì bong-xuống-sổ không có sự can thiệp của người đỡ đẻ.", "- Sổ rau tự nhiên: Thì bong và xuống  xảy ra tự nhiên, thì sổ có can thiệp", "- Sổ rau nhân tạo: Cả 3 thì không tự xảy ra được mà phải can thiệp."]}, {"heading": "3.1. Theo dõi", "paragraphs": ["Đây là thời kỳ quan trọng nhất nên phải theo dõi sát để can thiệp kịp thời nếu không sẽ có thể nguy hiểm đến tính mạng của sản phụ."], "bullets": ["- Toàn trạng mẹ : mạch, huyết áp, ra máu âm đạo.", "- Dấu hiệu tại chỗ: vị trí cuống rau, chảy máu âm đạo.", "- Di chuyển của đáy tử cung, mật độ của tử cung."]}, {"heading": "3.2. Cách làm nghiệm pháp bong rau", "paragraphs": ["Cách 1: Đặt cạnh bàn tay trên xương mu, đẩy tử cung lên trên, nếu dây rốn di chuyển lên theo là rau chưa bong, nếu không di chuyển là rau đã bong.", "Cách 2: Theo dõi vị trí di chuyển của dây rốn qua kẹp rốn. Nếu kẹp rốn xuống thấp hơn vị trí ban đầu thì rau đã bong."], "bullets": []}, {"heading": "3.3. Xử trí tích cực giai đoạn III", "paragraphs": ["Mục đích: Ngăn ngừa chảy máu sau đẻ.", "Các bước:", "Tiêm bắp oxytocin 10 đơn vị ngay sau khi sổ thai.", "Kéo dây rốn có kiểm soát: dùng kẹp Kocher để kẹp dây rốn đoạn gần với tầng sinh môn và giữ kẹp bằng 1 tay, trong khi đó tay kia đặt trên bụng sản phụ vị trí ngay trên khớp mu và ấn ngược tử cung lên trên. Đợi khi có một cơn co tử cung mạnh, yêu cầu sản phụ rặn và nhân viên y tế nhẹ nhàng kéo dây rốn để làm sổ rau thai, vẫn tiếp tục ép một tay lên tử cung hướng lên trên. Nếu rau không xuống chờ thêm 1 - 2 phút, với cơn co tử cung tiếp theo - kiểm tra kéo nhẹ dây rốn để bánh rau sổ.", "Khi rau sổ, dùng hai tay đỡ bánh rau, nhẹ nhàng quay bánh rau đến khi màng rau xoắn lại. Kéo xuống từ từ để cho rau sổ hoàn toàn.", "Xoa tử cung: cứ 15 phút kiểm tra cơn co tử cung một lần và nếu cần thiết thực hiện lại động tác xoa đáy tử cung."], "bullets": []}, {"heading": "3.4. Kiểm tra rau", "paragraphs": ["Hình 4.  Kiểm tra rau"], "bullets": ["- Kiểm tra màng: xem có đủ không. Xem màu sắc, tính chất của màng rau trắng tươi hay vàng xanh, đo màng từ mép lỗ vỡ ối đến rìa bánh rau để kiểm ra vị trí rau bám.", "- Kiểm tra bánh rau: kiểm tra múi đủ hay không bằng cách lau sạch và dùng các ngón tay kiểm tra quanh mép bánh rau. Những vị trí sần sùi hoặc mạch máu bị rách gợi ý tình trạng tổ chức bánh rau bị rách hoặc sót bánh rau phụ. Lưu ý rằng bánh rau thường có màu đỏ thẫm và mịn bóng nhưng đôi khi có thể bị vôi hoá hoặc ngấm màu phân su. Kiểm tra trọng lượng của bánh rau (bình thường bánh rau nặng khoảng 1/6 trọng lượng thai nhi).", "- Kiểm tra dây rốn: đo chiều dài dây rốn (bình thường dây rốn dài từ 45-60cm), xem màu sắc, độ to nhỏ của dây rốn, đếm mạch máu để đảm bảo rằng có đủ hai động mạch và một tĩnh mạch."]}], "raw_text": "SỔ RAU THƯỜNG\nTS. Bùi Minh Tiến\nMục tiêu học tập\n1. Trình bày được các hiện tượng lâm sàng thời kỳ sổ rau.\n2. Mô tả các bước trong xử trí tích cực giai đoạn III\n\n1. ĐẠI CƯƠNG\nSổ rau là giai đoạn III của cuộc chuyển dạ. Bình thường, giai đoạn này kéo dài trung bình 30 phút. Sự bong rau xảy ra ở lớp nông (lớp đặc) của màng rụng.\nSự bong rau xảy ra qua 3 thì:\n- Thì bong: sau khi sổ thai, tử cung co lại nhưng vì bánh rau có  tính chất đàn hồi kém nên co rúm lại, dày lên, lớp rau chờm ra ngoài vùng rau bám. Các gai rau bị kéo căng, mạch máu lớp xốp đứt gây chảy máu. Trọng lượng cục máu sau rau làm cho rau bong tiếp. Có 2 kiểu bong rau: Baudelocque và Duncan.\n- Thì sổ rau: dưới tác dụng của cơn co tử cung, rau bong kéo theo màng ối xuống đoạn dưới, rồi xuống âm đạo và ra ngoài.\n- Thì cầm máu: nhờ sự co bóp của tất cả các sợi cơ tử cung và cơ chế đông máu bình  thường. Sau sổ rau tử cung co lại thành một khối an toàn.\n\nHình 1. Giai đoạn sổ rau\n2. CÁC HIỆN TƯỢNG LÂM SÀNG THỜI KỲ SỔ RAU\n2.1 Các dấu hiệu bong rau\n- Dây rốn xuống thấp.\n- Máu chảy ra qua âm đạo báo hiệu rau bong khỏi thành tử cung.\n- Sự thay đổi đáy tử cung từ dạng đĩa sang khối cầu.\n2.2 Các kiểu bong rau\n2.2.1 Bong rau kiểu Baudelocque\nRau được bong từ trung tâm ra bìa của bánh rau. Toàn bộ máu cục tụ lại sau rau nên khi rau ra ngoài ta thấy nội sản mạc ra trước. Kiểu bong này ít gây sót rau và sót màng, loại bong rau này chiếm tỉ lệ 75%.\n\nHinh 2.  Bong rau kiểu Baudelocque\n2.2.2 Bong rau kiểu Duncan:\tRau được bong từ rìa của bánh rau và các màng xung quanh vào giữa, làm cho một phần huyết tụ sau rau, một phần chảy ra ngoài âm đạo nhiều. Khi rau ra ngoài ta thấy màng rụng ra trước. Kiểu bong này chiếm tỉ lệ 25% và thường gây chảy máu, sót rau và màng.\nHinh 3. Bong rau kiểu Duncan\n\n2.3. Các cách sổ rau\n- Sổ rau tự động: Cả 3 thì bong-xuống-sổ không có sự can thiệp của người đỡ đẻ.\n- Sổ rau tự nhiên: Thì bong và xuống  xảy ra tự nhiên, thì sổ có can thiệp\n- Sổ rau nhân tạo: Cả 3 thì không tự xảy ra được mà phải can thiệp.\n\n3. XỬ TRÍ TRONG THỜI KỲ SỔ RAU\n3.1. Theo dõi\nĐây là thời kỳ quan trọng nhất nên phải theo dõi sát để can thiệp kịp thời nếu không sẽ có thể nguy hiểm đến tính mạng của sản phụ.\n- Toàn trạng mẹ : mạch, huyết áp, ra máu âm đạo.\n- Dấu hiệu tại chỗ: vị trí cuống rau, chảy máu âm đạo.\n- Di chuyển của đáy tử cung, mật độ của tử cung.\n3.2. Cách làm nghiệm pháp bong rau\nCách 1: Đặt cạnh bàn tay trên xương mu, đẩy tử cung lên trên, nếu dây rốn di chuyển lên theo là rau chưa bong, nếu không di chuyển là rau đã bong.\nCách 2: Theo dõi vị trí di chuyển của dây rốn qua kẹp rốn. Nếu kẹp rốn xuống thấp hơn vị trí ban đầu thì rau đã bong.\n3.3. Xử trí tích cực giai đoạn III\nMục đích: Ngăn ngừa chảy máu sau đẻ.\nCác bước:\nTiêm bắp oxytocin 10 đơn vị ngay sau khi sổ thai.\nKéo dây rốn có kiểm soát: dùng kẹp Kocher để kẹp dây rốn đoạn gần với tầng sinh môn và giữ kẹp bằng 1 tay, trong khi đó tay kia đặt trên bụng sản phụ vị trí ngay trên khớp mu và ấn ngược tử cung lên trên. Đợi khi có một cơn co tử cung mạnh, yêu cầu sản phụ rặn và nhân viên y tế nhẹ nhàng kéo dây rốn để làm sổ rau thai, vẫn tiếp tục ép một tay lên tử cung hướng lên trên. Nếu rau không xuống chờ thêm 1 - 2 phút, với cơn co tử cung tiếp theo - kiểm tra kéo nhẹ dây rốn để bánh rau sổ.\nKhi rau sổ, dùng hai tay đỡ bánh rau, nhẹ nhàng quay bánh rau đến khi màng rau xoắn lại. Kéo xuống từ từ để cho rau sổ hoàn toàn.\nXoa tử cung: cứ 15 phút kiểm tra cơn co tử cung một lần và nếu cần thiết thực hiện lại động tác xoa đáy tử cung.\n3.4. Kiểm tra rau\n- Kiểm tra màng: xem có đủ không. Xem màu sắc, tính chất của màng rau trắng tươi hay vàng xanh, đo màng từ mép lỗ vỡ ối đến rìa bánh rau để kiểm ra vị trí rau bám.\n- Kiểm tra bánh rau: kiểm tra múi đủ hay không bằng cách lau sạch và dùng các ngón tay kiểm tra quanh mép bánh rau. Những vị trí sần sùi hoặc mạch máu bị rách gợi ý tình trạng tổ chức bánh rau bị rách hoặc sót bánh rau phụ. Lưu ý rằng bánh rau thường có màu đỏ thẫm và mịn bóng nhưng đôi khi có thể bị vôi hoá hoặc ngấm màu phân su. Kiểm tra trọng lượng của bánh rau (bình thường bánh rau nặng khoảng 1/6 trọng lượng thai nhi).\n- Kiểm tra dây rốn: đo chiều dài dây rốn (bình thường dây rốn dài từ 45-60cm), xem màu sắc, độ to nhỏ của dây rốn, đếm mạch máu để đảm bảo rằng có đủ hai động mạch và một tĩnh mạch.\n\n\nHình 4.  Kiểm tra rau\nCâu hỏi:\n1. Trình bầy cơ chế bong rau và màng rau trong giai đoạn 3 của cuộc đẻ ư mô tả các kiểu bong rau và sổ rau?\n\n2. Trình bày cách đỡ rau và kiểm tra sau khi sổ rau?", "priority": "Trung bình"}, {"id": "SK-13", "chapter": "Chương 1. Sản thường", "folder": "01_San_thuong", "title": "Hậu sản thường", "author": "TS. Bùi Minh Tiến", "word_count": 1801, "line_count": 96, "key_numbers": ["1 cm", "1 giờ", "1.3 Giờ", "12 giờ", "13 cm", "14 ngày", "15 phút", "1cm", "2 tháng", "2 tuần", "24 giờ", "3 cm", "3 ngày", "3 tháng", "30 phút", "42 ngày", "48 giờ", "5 ngày", "5kg", "6 giờ", "6 tuần", "60 g"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["HẬU SẢN THƯỜNG", "TS. Bùi Minh Tiến"], "bullets": []}, {"heading": "1. ĐỊNH NGHĨA", "paragraphs": ["Hậu sản là thời gian để trở lại bình thường của các cơ quan sinh dục về mặt giải phẫu và sinh lý (ngoại trừ vú vẫn tiếp tục phát triển để tiết sữa). Thời gian này là 6 tuần (42 ngày) tính từ sau khi đẻ.."], "bullets": []}, {"heading": "2.1.1 Thân tử cung", "paragraphs": ["Trọng lượng tử cung ngay sau đẻ nặng khoảng 1.000 gram sau đó giảm dần đến cuối thời kỳ hậu sản sẽ trở về trọng lượng bình thường như khi chưa có thai (50- 60 g).", "Trên lâm sàng người ta nhận thấy có 3 hiện tượng:"], "bullets": ["+ Tử cung co rút: sau khi đẻ, tử cung co rút lại trong vài giờ tạo thành một khối chắc, gọi là cầu an toàn, lúc này đáy tử cung ở ngay dưới rốn.", "+ Tử cung co bóp: biểu hiện bởi đau bụng, ra máu và  sản dịch chảy ra ngoài. Các cơn đau này biểu hiện ở người con rạ nhiều hơn ở người con so.", "+ Tử cung co hồi: Sau khi đẻ đáy tử cung ở trên khớp vệ khoảng 13 cm, mỗi ngày co hồi được khoảng 1cm, riêng ngày đầu có thể co hồi được nhanh hơn có thể được khoảng 2 đến 3 cm. Sau 2 tuần lễ sẽ không sờ thấy được tử cung ở trên khớp vệ nữa."]}, {"heading": "2.1.2. Phần dưới tử cung", "paragraphs": [], "bullets": ["- Đoạn dưới ngắn lại và thành eo tử cung vào ngày thứ 5 sau đẻ.", "- Cổ tử cung ngắn và nhỏ lại: lỗ trong đóng vào ngày thứ 5 đến thứ 8, lỗ ngoài đóng vào ngày thứ 12 hoặc hé mở, có khi thấy lộ tuyến."]}, {"heading": "2.1.3. Nội mạc tử cung", "paragraphs": ["Sẽ trải qua hai giai đoạn để trở lại chức phận của niêm mạc tử cung bình thường."], "bullets": ["- Giai đoạn thoái triển: xảy ra trong 14 ngày đầu sau đẻ. Lớp bề mặt bị hoại tử và thoát ra ngoài cùng với sản dịch, lớp đáy gồm đáy tuyến vẫn còn nguyên vẹn và là nguồn gốc của niêm mạc tử cung mới.", "- Giai đoạn phát triển: dưới ảnh hưởng của estrogen và progesteron sau 3-6 tuần,  niêm mạc tử cung được phục hồi hoàn toàn và sẽ thực hiện chu kỳ kinh nguyệt đầu tiên nếu không cho con bú."]}, {"heading": "2.2. Thay đổi ở âm đạo, âm hộ và phần phụ", "paragraphs": [], "bullets": ["- Âm hộ, âm đạo bị giãn căng trong khi đẻ cũng co dần và trở về kích thước bình thường vào ngày thứ 15.", "- Màng trinh sau khi đẻ bị rách chỉ còn lại di tích của rìa màng trinh.", "- Phần phụ trở lại bình thường trong hố chậu.", "- Tầng sinh môn: các cơ nông và sâu lấy lại trương lực tùy thuộc vào nhiều yếu tố, bao gồm các vấn đề liên quan đến diễn biến của cuộc chuyển dạ, can thiệp (có cắt tầng sinh môn hay không) và yếu tố cá nhân (yếu tố dinh dưỡng, di truyền)  và thể dục sau đẻ."]}, {"heading": "2.3. Thay đổi ở vú", "paragraphs": ["Vài ngày sau đẻ:"], "bullets": ["- Vú phát triển nhanh, căng to.", "- Núm vú to và dài ra, tĩnh mạch vú nổi rõ.", "- Tuyến sữa phát triển to lên có khi lan tới tận nách.", "- Có hiện tượng tiết sữa, thường xảy ra sau đẻ 2 - 3 ngày. Cơ chế của hiện tượng xuống sữa là do nồng độ estrogen tụt xuống đột ngột sau đẻ, Prolactin được giải phóng và tác dụng lên tuyến sữa gây ra sự tiết sữa. Sự tiết sữa được duy trì bởi động tác bú."]}, {"heading": "2.4.  Thay đổi ở hệ tiết niệu", "paragraphs": ["Sau khi đẻ, thành bàng quang và niêm mạc niệu đạo bị xung huyết gây ra tình trạng bí tiểu, bàng quang trở nên xung huyết nhạy cảm hơn đối với sự thay đổi khối lượng nước tiểu."], "bullets": []}, {"heading": "3.1. Sự co hồi tử cung", "paragraphs": [], "bullets": ["- Tử cung thu nhỏ lại ngay sau đẻ, đáy tử cung trên vệ 13 cm và trung bình  mỗi ngày thu lại 1 cm. Đến ngày thứ 12-13 thì không còn nắn thấy đáy tử cung trên khớp vệ. Ở người sinh con so tử cung go hồi nhanh hơn ở người sinh con rạ, người đẻ thường tử cung go hồi nhanh hơn ở người mổ đẻ, cho con bú tử cung go hồi nhanh hơn không cho con bú, tử cung bị nhiễm khuẩn go hồi chậm hơn tử cung không bị nhiễm khuẩn, bí tiểu và táo bón tử cung cũng go hồi chậm hơn.", "- Cơn đau tử cung: do tử cung co bóp tống máu cục và sản dịch ra ngoài. Người con rạ đau nhiều hơn con so, thường cơn đau giảm dần."]}, {"heading": "3.2. Sản dịch", "paragraphs": [], "bullets": ["- Là chất dịch chảy ra ngoài âm hộ trong thời kỳ đầu của thời kỳ hậu sản.", "- Cấu tạo: là những mảnh vụn của màng rụng, máu cục và máu loãng các tế bào và dịch tiết ra từ âm đạo.", "- Tính chất: vô trùng, mùi tanh nồng, pH kiềm, 2 - 3 ngày đầu sản dịch màu đỏ tươi về sau đỏ sẫm, từ ngày 4 - 8 sản dịch loãng hơn lẫn nhầy lờ lờ máu cá, từ ngày 8 - 12 sản dịch chỉ là chất nhầy, trong.", "- Số lượng: Ngày thứ 1 và 2 ra nhiều, sau 2 tuần lễ sẽ hết hẳn. Ở những phụ nữ không cho con bú, ba tuần sau sinh có thể thấy kinh non do niêm mạc tử cung  đã phục hồi."]}, {"heading": "3.3. Sự xuống sữa", "paragraphs": ["Ở người con so, sự xuống sữa vào ngày thứ 3, người con rạ ngày thứ 2 với các  các triệu chứng:", "Sốt nhẹ, ớn lạnh, nhức đầu, khó chịu, mạch hơi nhanh.. Hai vú cương to và đau. Tuy nhiên, những triệu chứng này không mang tính điển hình. Sau 24 giờ - 48 giờ các triệu chứng mất khi có hiện tượng tiết sữa."], "bullets": []}, {"heading": "3.4. Các hiện tượng khác", "paragraphs": ["Cơn rét run sinh lý  hay xảy ra ngay sau khi đẻ do mất nhiệt. Đặc điểm của cơn rét run là mạch, nhiệt độ và huyết áp vẫn bình thường.", "Nếu không cho con bú, 5-6 tuần lễ sau đẻ có thể có kinh lại lần đầu tiên và đó cũng là dấu hiệu chấm dứt thời kỳ hậu sản. Kỳ kinh đầu sau đẻ thường nhiều và kéo dài hơn các kỳ kinh bình thường."], "bullets": ["- Mạch thường chậm lại khoảng 10 nhịp/phút và trở lại bình  thường sau 5 ngày", "- Nhịp thở sâu và chậm hơn do cơ hoành không bị đẩy lên cao nữa.", "- Trọng lượng cơ thể giảm từ 3 - 5kg ngay sau khi sinh. Cân nặng có thể giảm xuống dần dần trong 2 tuần tiếp theo do giảm tình trạng phù."]}, {"heading": "4.1. Ngày thứ nhất", "paragraphs": ["Phải theo dõi sát sản phụ."], "bullets": []}, {"heading": "4.1.1. Trong hai giờ đầu sau đẻ", "paragraphs": [], "bullets": ["- Sản phụ phải được nằm theo dõi tại phòng đẻ.", "- Mạch, nhiệt độ, huyết áp, toàn trạng, xoa đáy tử cung qua thành bụng để theo dõi khối an toàn tử  cung, đánh giá  trình trạng chảy máu âm đạo, 15 phút/lần trong  giờ đầu và 30 phút/ lần trong giờ thứ hai sau đẻ."]}, {"heading": "4.1.2. Giờ thứ ba đến giờ thứ sáu", "paragraphs": ["Theo dõi tích cực hai giờ đầu, nếu bình thường tiếp tục theo dõi từ giờ thứ ba đến giờ thứ 6 như sau:"], "bullets": ["-  Đưa bà mẹ về phòng,  cho mẹ nằm cùng phòng với con.", "-  Đóng băng vệ sinh,  theo dõi các yếu tố ở trên 1 giờ/lần.", "- Giúp người mẹ ăn uống, ngủ đủ.", "- Giúp và khuyến khích mẹ cho trẻ bú sớm.", "- Vận động nhẹ sau 6 giờ.", "- Hướng dẫn người mẹ cách chăm sóc con, theo dõi chảy máu rốn.", "- Yêu cầu bà mẹ và người nhà gọi ngay nhân viên y tế khi sản phụ chảy máu nhiều, đau bụng tăng, nhức đầu, chóng mặt hoặc có bất cứ một vấn đề gì khác."]}, {"heading": "4.1.3 Giờ thứ bảy đến hết ngày đầu", "paragraphs": ["Theo dõi thể trạng, sự co hồi tử cung, băng vệ sinh (kiểm tra lượng máu mất), Tình trạng vết may tầng sinh môn hoặc các vết rách xuất hiện trong trường hợp không cắt tầng sinh môn."], "bullets": []}, {"heading": "4.2. Những ngày sau", "paragraphs": ["Cõu hỏi: Trình bầy các hiện tượng lâm sàng của thời kỳ hậu sản?"], "bullets": ["- Chăm sóc tinh thần, nhất là những cuộc đẻ không theo ý muốn.", "- Bảo đảm điều kiện vệ sinh tốt cho sản phụ (buồng sạch, thoáng, cách ly buồng nhiễm khuẩn).", "- Theo dõi mạch, nhiệt, huyết áp, ngày 2 lần.", "- Theo dõi sự co hồi tử cung và sản dịch.", "- Làm thuốc ngoài ngày 2 lần bằng nước muối sinh lý, hoặc bằng các dung dịch sát khuẩn.", "- Hướng dẫn bà mẹ rửa sạch đầu vú bằng gạc mềm tẩm nước ấm trước khi cho bú và rửa sạch lại sau khi cho bú.", "- Theo dõi tình trạng tiểu tiện (gọi là bí tiểu nếu sau đẻ 12 giờ chưa đi tiểu được) và đại tiện (gọi là táo bón nếu sau đẻ 3 ngày chưa đại tiện được). Không nên cho thuốc nhuận tràng và thụt tháo bằng nước.", "- Ăn uống đủ chất bổ, thức ăn nhiều chất xơ, bổ sung thêm chất sắt, tránh các chất kích thích. Không nên kiêng khem quá mức. Sau đẻ ngày thứ 2 có thể tắm nước ấm, không nên ngâm mình trong bồn nước.", "- Tránh lao động nặng trong 2 tháng đầu.", "- Không nên giao hợp  trong thời gian hậu sản vì dễ gây nhiễm khuẩn.", "- Có thể dùng các biện pháp sau để tránh thai sau sinh:", "+ Bao cao su.", "+ Dụng cụ tử cung có thể đặt sau 3 tháng.", "+ Thuốc tránh thai  Progestatif liều thấp (Exluton)", "+ Thuốc diệt tinh trùng tại chỗ.", "+ Triệt sản (nếu đủ con).", "- Hẹn khám lại tại trạm y tế xã vào tuần thứ 6 sau đẻ."]}], "raw_text": "HẬU SẢN THƯỜNG\nTS. Bùi Minh Tiến\nMục tiêu học tập\n1. Phân biệt được những thay đổi giải phẫu, sinh lý trong thời kỳ hậu sản.\n2. Mô tả được cấu tạo và tính chất của sản dịch,\n3. Xác định  được những hiện tượng lâm sàng trong thời kỳ hậu sản.\n4. Thực hành được chăm sóc hậu sản ở cộng đồng.\n\n1. ĐỊNH NGHĨA\nHậu sản là thời gian để trở lại bình thường của các cơ quan sinh dục về mặt giải phẫu và sinh lý (ngoại trừ vú vẫn tiếp tục phát triển để tiết sữa). Thời gian này là 6 tuần (42 ngày) tính từ sau khi đẻ..\n\n2. SINH LÝ HỌC VÀ GIẢI PHẪU HỌC THỜI KỲ HẬU SẢN\n2.1. Thay đổi ở tử cung\n2.1.1 Thân tử cung\nTrọng lượng tử cung ngay sau đẻ nặng khoảng 1.000 gram sau đó giảm dần đến cuối thời kỳ hậu sản sẽ trở về trọng lượng bình thường như khi chưa có thai (50- 60 g).\nTrên lâm sàng người ta nhận thấy có 3 hiện tượng:\n+ Tử cung co rút: sau khi đẻ, tử cung co rút lại trong vài giờ tạo thành một khối chắc, gọi là cầu an toàn, lúc này đáy tử cung ở ngay dưới rốn.\n+ Tử cung co bóp: biểu hiện bởi đau bụng, ra máu và  sản dịch chảy ra ngoài. Các cơn đau này biểu hiện ở người con rạ nhiều hơn ở người con so.\n+ Tử cung co hồi: Sau khi đẻ đáy tử cung ở trên khớp vệ khoảng 13 cm, mỗi ngày co hồi được khoảng 1cm, riêng ngày đầu có thể co hồi được nhanh hơn có thể được khoảng 2 đến 3 cm. Sau 2 tuần lễ sẽ không sờ thấy được tử cung ở trên khớp vệ nữa.\n2.1.2. Phần dưới tử cung\n- Đoạn dưới ngắn lại và thành eo tử cung vào ngày thứ 5 sau đẻ.\n- Cổ tử cung ngắn và nhỏ lại: lỗ trong đóng vào ngày thứ 5 đến thứ 8, lỗ ngoài đóng vào ngày thứ 12 hoặc hé mở, có khi thấy lộ tuyến.\n2.1.3. Nội mạc tử cung\nSẽ trải qua hai giai đoạn để trở lại chức phận của niêm mạc tử cung bình thường.\n- Giai đoạn thoái triển: xảy ra trong 14 ngày đầu sau đẻ. Lớp bề mặt bị hoại tử và thoát ra ngoài cùng với sản dịch, lớp đáy gồm đáy tuyến vẫn còn nguyên vẹn và là nguồn gốc của niêm mạc tử cung mới.\n- Giai đoạn phát triển: dưới ảnh hưởng của estrogen và progesteron sau 3-6 tuần,  niêm mạc tử cung được phục hồi hoàn toàn và sẽ thực hiện chu kỳ kinh nguyệt đầu tiên nếu không cho con bú.\n2.2. Thay đổi ở âm đạo, âm hộ và phần phụ\n- Âm hộ, âm đạo bị giãn căng trong khi đẻ cũng co dần và trở về kích thước bình thường vào ngày thứ 15.\n- Màng trinh sau khi đẻ bị rách chỉ còn lại di tích của rìa màng trinh.\n- Phần phụ trở lại bình thường trong hố chậu.\n- Tầng sinh môn: các cơ nông và sâu lấy lại trương lực tùy thuộc vào nhiều yếu tố, bao gồm các vấn đề liên quan đến diễn biến của cuộc chuyển dạ, can thiệp (có cắt tầng sinh môn hay không) và yếu tố cá nhân (yếu tố dinh dưỡng, di truyền)  và thể dục sau đẻ.\n\n2.3. Thay đổi ở vú\nVài ngày sau đẻ:\n- Vú phát triển nhanh, căng to.\n- Núm vú to và dài ra, tĩnh mạch vú nổi rõ.\n- Tuyến sữa phát triển to lên có khi lan tới tận nách.\n- Có hiện tượng tiết sữa, thường xảy ra sau đẻ 2 - 3 ngày. Cơ chế của hiện tượng xuống sữa là do nồng độ estrogen tụt xuống đột ngột sau đẻ, Prolactin được giải phóng và tác dụng lên tuyến sữa gây ra sự tiết sữa. Sự tiết sữa được duy trì bởi động tác bú.\n2.4.  Thay đổi ở hệ tiết niệu\nSau khi đẻ, thành bàng quang và niêm mạc niệu đạo bị xung huyết gây ra tình trạng bí tiểu, bàng quang trở nên xung huyết nhạy cảm hơn đối với sự thay đổi khối lượng nước tiểu.\n3. NHỮNG HIỆN TƯỢNG LÂM SÀNG\n3.1. Sự co hồi tử cung\n- Tử cung thu nhỏ lại ngay sau đẻ, đáy tử cung trên vệ 13 cm và trung bình  mỗi ngày thu lại 1 cm. Đến ngày thứ 12-13 thì không còn nắn thấy đáy tử cung trên khớp vệ. Ở người sinh con so tử cung go hồi nhanh hơn ở người sinh con rạ, người đẻ thường tử cung go hồi nhanh hơn ở người mổ đẻ, cho con bú tử cung go hồi nhanh hơn không cho con bú, tử cung bị nhiễm khuẩn go hồi chậm hơn tử cung không bị nhiễm khuẩn, bí tiểu và táo bón tử cung cũng go hồi chậm hơn.\n- Cơn đau tử cung: do tử cung co bóp tống máu cục và sản dịch ra ngoài. Người con rạ đau nhiều hơn con so, thường cơn đau giảm dần.\n3.2. Sản dịch\n- Là chất dịch chảy ra ngoài âm hộ trong thời kỳ đầu của thời kỳ hậu sản.\n- Cấu tạo: là những mảnh vụn của màng rụng, máu cục và máu loãng các tế bào và dịch tiết ra từ âm đạo.\n- Tính chất: vô trùng, mùi tanh nồng, pH kiềm, 2 - 3 ngày đầu sản dịch màu đỏ tươi về sau đỏ sẫm, từ ngày 4 - 8 sản dịch loãng hơn lẫn nhầy lờ lờ máu cá, từ ngày 8 - 12 sản dịch chỉ là chất nhầy, trong.\n- Số lượng: Ngày thứ 1 và 2 ra nhiều, sau 2 tuần lễ sẽ hết hẳn. Ở những phụ nữ không cho con bú, ba tuần sau sinh có thể thấy kinh non do niêm mạc tử cung  đã phục hồi.\n3.3. Sự xuống sữa\nỞ người con so, sự xuống sữa vào ngày thứ 3, người con rạ ngày thứ 2 với các  các triệu chứng:\nSốt nhẹ, ớn lạnh, nhức đầu, khó chịu, mạch hơi nhanh.. Hai vú cương to và đau. Tuy nhiên, những triệu chứng này không mang tính điển hình. Sau 24 giờ - 48 giờ các triệu chứng mất khi có hiện tượng tiết sữa.\n3.4. Các hiện tượng khác\nCơn rét run sinh lý  hay xảy ra ngay sau khi đẻ do mất nhiệt. Đặc điểm của cơn rét run là mạch, nhiệt độ và huyết áp vẫn bình thường.\n- Mạch thường chậm lại khoảng 10 nhịp/phút và trở lại bình  thường sau 5 ngày\n- Nhịp thở sâu và chậm hơn do cơ hoành không bị đẩy lên cao nữa.\n- Trọng lượng cơ thể giảm từ 3 - 5kg ngay sau khi sinh. Cân nặng có thể giảm xuống dần dần trong 2 tuần tiếp theo do giảm tình trạng phù.\nNếu không cho con bú, 5-6 tuần lễ sau đẻ có thể có kinh lại lần đầu tiên và đó cũng là dấu hiệu chấm dứt thời kỳ hậu sản. Kỳ kinh đầu sau đẻ thường nhiều và kéo dài hơn các kỳ kinh bình thường.\n4. CHĂM SÓC HẬU SẢN\n4.1. Ngày thứ nhất\nPhải theo dõi sát sản phụ.\n4.1.1. Trong hai giờ đầu sau đẻ\n- Sản phụ phải được nằm theo dõi tại phòng đẻ.\n- Mạch, nhiệt độ, huyết áp, toàn trạng, xoa đáy tử cung qua thành bụng để theo dõi khối an toàn tử  cung, đánh giá  trình trạng chảy máu âm đạo, 15 phút/lần trong  giờ đầu và 30 phút/ lần trong giờ thứ hai sau đẻ.\n4.1.2. Giờ thứ ba đến giờ thứ sáu\nTheo dõi tích cực hai giờ đầu, nếu bình thường tiếp tục theo dõi từ giờ thứ ba đến giờ thứ 6 như sau:\n-  Đưa bà mẹ về phòng,  cho mẹ nằm cùng phòng với con.\n-  Đóng băng vệ sinh,  theo dõi các yếu tố ở trên 1 giờ/lần.\n- Giúp người mẹ ăn uống, ngủ đủ.\n- Giúp và khuyến khích mẹ cho trẻ bú sớm.\n- Vận động nhẹ sau 6 giờ.\n- Hướng dẫn người mẹ cách chăm sóc con, theo dõi chảy máu rốn.\n- Yêu cầu bà mẹ và người nhà gọi ngay nhân viên y tế khi sản phụ chảy máu nhiều, đau bụng tăng, nhức đầu, chóng mặt hoặc có bất cứ một vấn đề gì khác.\n4.1.3 Giờ thứ bảy đến hết ngày đầu\nTheo dõi thể trạng, sự co hồi tử cung, băng vệ sinh (kiểm tra lượng máu mất), Tình trạng vết may tầng sinh môn hoặc các vết rách xuất hiện trong trường hợp không cắt tầng sinh môn.\n4.2. Những ngày sau\n- Chăm sóc tinh thần, nhất là những cuộc đẻ không theo ý muốn.\n- Bảo đảm điều kiện vệ sinh tốt cho sản phụ (buồng sạch, thoáng, cách ly buồng nhiễm khuẩn).\n- Theo dõi mạch, nhiệt, huyết áp, ngày 2 lần.\n- Theo dõi sự co hồi tử cung và sản dịch.\n- Làm thuốc ngoài ngày 2 lần bằng nước muối sinh lý, hoặc bằng các dung dịch sát khuẩn.\n- Hướng dẫn bà mẹ rửa sạch đầu vú bằng gạc mềm tẩm nước ấm trước khi cho bú và rửa sạch lại sau khi cho bú.\n- Theo dõi tình trạng tiểu tiện (gọi là bí tiểu nếu sau đẻ 12 giờ chưa đi tiểu được) và đại tiện (gọi là táo bón nếu sau đẻ 3 ngày chưa đại tiện được). Không nên cho thuốc nhuận tràng và thụt tháo bằng nước.\n- Ăn uống đủ chất bổ, thức ăn nhiều chất xơ, bổ sung thêm chất sắt, tránh các chất kích thích. Không nên kiêng khem quá mức. Sau đẻ ngày thứ 2 có thể tắm nước ấm, không nên ngâm mình trong bồn nước.\n- Tránh lao động nặng trong 2 tháng đầu.\n- Không nên giao hợp  trong thời gian hậu sản vì dễ gây nhiễm khuẩn.\n- Có thể dùng các biện pháp sau để tránh thai sau sinh:\n+ Bao cao su.\n+ Dụng cụ tử cung có thể đặt sau 3 tháng.\n+ Thuốc tránh thai  Progestatif liều thấp (Exluton)\n+ Thuốc diệt tinh trùng tại chỗ.\n+ Triệt sản (nếu đủ con).\n- Hẹn khám lại tại trạm y tế xã vào tuần thứ 6 sau đẻ.\n\n\nCõu hỏi: Trình bầy các hiện tượng lâm sàng của thời kỳ hậu sản?", "priority": "Trung bình"}, {"id": "SK-14", "chapter": "Chương 1. Sản thường", "folder": "01_San_thuong", "title": "Một số phương pháp thăm dò trong sản khoa", "author": "THs. BSCKII. Lê Hải Dương, Ths. Phạm Thị Quỳnh Như", "word_count": 3208, "line_count": 199, "key_numbers": ["10 ngày", "100.000 UI", "12 tuần", "13 tuần", "16 tuần", "18 tuần", "2 ngày", "20 phút", "20 tuần", "2000UI", "22 tuần", "24 tuần", "25 IU", "25cm", "29 tuần", "3 tháng", "4 ngày", "4 tuần", "41 tuần", "48 giờ", "5 tuần", "5,5 tuần", "5cm", "6 tuần", "6,5 tuần", "7 tuần", "8,9 ngày", "800UI"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["MỘT SỐ PHƯƠNG PHÁP THĂM DÒ TRONG SẢN KHOA"], "bullets": []}, {"heading": "Mục tiêu học tập", "paragraphs": ["Trình bày được chỉ định, chống chỉ định và kết quả của soi ối", "Trình bày được chỉ định, thời điểm và các tai biến của chọc ối", "Liệt kê được các xét nghiệm sinh hóa trong thăm dò sản khoa", "Trình bày được các chỉ định siêu âm trong thai kỳ", "Nêu được mục đích và phân tích một số biểu đồ tim thai và cơn co trên monitoring sản khoa"], "bullets": []}, {"heading": "1. SOI ỐI", "paragraphs": ["Soi ối cho phép nhìn thấy nước ối qua màng ối nhờ vào hệ thống ánh sáng lạnh. Xét nghiệm này chỉ nên thực hiện từ tuần 37 trở đi. Soi ối là một phương pháp có thể thực hiện đơn giản, để quan sát màu sắc nước ối. Tuy nhiên giải thích kết quả phải tinh tế. Nếu xuất hiện ối xanh là dấu hiệu báo động."], "bullets": []}, {"heading": "1.1. Chỉ định", "paragraphs": ["Trong mọi trường hợp thai nghén có nghi ngờ thai suy khi ối chưa vỡ."], "bullets": []}, {"heading": "1.2. Chống chỉ định", "paragraphs": ["Nhiễm trùng âm đạo", "Rau tiền đạo", "Thai chết trong tử cung (vì nguy cơ làm ối vỡ và nhiễm trùng nặng sau vỡ ối).", "Ngôi mông."], "bullets": []}, {"heading": "1.3. Kết quả", "paragraphs": [], "bullets": ["-\tNước ối bình thường: Màu trong, có vài nụ chất gây chuyển động.", "-\tNước ối có màu vàng: dấu hiệu này có thể cho thấy có phân su cũ trong nước ối, có tình trạng thai suy trước đó. Biểu hiện này không có ý nghĩa rõ ràng là thai đang suy hay không.", "-\tNước ối  màu xanh đặc, chứng tỏ có sự thải phân su mới.", "- Đôi khi sự quan sát nước ối bị hạn chế do chất nhầy cổ tử cung nhiều và đặc, hoặc trong trường hợp thiểu ối."]}, {"heading": "2.1. Chỉ định", "paragraphs": ["Hình 1. Chọc buồng ối"], "bullets": ["- Mẹ thuộc nhóm nguy cơ cao: tuổi mẹ ≥ 35 tuổi, mẹ có bộ nhiễm sắc thể bất thường, tiền căn gia đình có bất thường về nhiễm sắc thể hoặc bệnh lý về nhiễm sắc thể ( thiếu máu hồng cầu hình liềm…)", "- Xét nghiệm tầm soát thai kỳ nguy cơ cao bất thường về nhiễm sắc thể (Xét nghiệm double test, triple test, NIPT)", "- Tiền căn sinh con có bất thường nhiễm sắc thể (Down, chậm phát triển tâm thần…)", "- Thai kỳ trước có bất thường về nhiễm sắc thể giới tính: Turner 45X, 47XXY.", "- Vợ hoặc chồng có bất thường nhiễm sắc thể (dù kiểu hình bình thường)", "- Siêu âm bất thường: độ mờ da gáy dày, có các dị dạng thai: bệnh não nhỏ, không có sọ, bệnh thoát vị não, não úng thuỷ, nứt đốt sống…", "-  Đánh giá mức độ trưởng thành phổi của thai nhi trong những trường hợp cần chấm dứt thai kỳ sớm như: tiền sản giật, tiểu đường thai kỳ, bệnh lý nội khoa của mẹ…", "- Một số chỉ định ít gặp: chọc ối trong chẩn đoán nhiễm trùng trong tử cung, chọc ối để điều trị trong đa ối."]}, {"heading": "2.2. Thời điểm chọc ối", "paragraphs": [], "bullets": ["- Chọc ối trong quý 1 thai kỳ, giữa tuần 11 và 14. Tuy nhiên nguy cơ sẩy thai cao gấp 3 lần so với chọc ối ở quý 2. Vì vậy nếu cần thiết phải chẩn đoán tiền sản ở giai đoạn này nên lựa chọn sinh thiết gai rau.", "- Chọc ối trong quý 2 thai kỳ. Đây là thời điểm thường thực hiện, khoảng giữa tuần 15 và 18, có thể lên tới 20 tuần.", "- Chọc ối trong quý 3 thai kỳ. Chỉ thực hiện khi cần đánh giá mức độ trưởng thành phổi thai nhi hoặc điều trị trong đa ối."]}, {"heading": "2.3. Tai Biến", "paragraphs": [], "bullets": ["- Ra huyết âm đạo.", "- Xuất huyết ở rau hoặc dây rốn.", "- Sẩy thai hoặc thai lưu.", "- Rỉ ối, vỡ ối, nhiễm trùng ối.", "- Tổn thương thai."]}, {"heading": "2.4.  Phân tích kết quả", "paragraphs": [], "bullets": ["- Định lượng Bilirubin để chẩn đoán bất đồng nhóm máu mẹ - con.", "- Xác định phân su trong nước ối để chẩn đoán suy thai.", "- Định lượng estriol để chẩn đoán sự phát triển của thai.", "- Định lượng hPL để chẩn đoán sự phát triển và trưởng thành của thai và rau thai.", "- Định lượng một số men trong nước ối:", "+ Định lượng phosphatase kiềm, lacticodehydrogenase: tăng trong trường hợp thai thiếu oxy.", "+ Định lượng transaminase: có giá trị tiên lượng xấu khi tăng.", "- Định lượng Creatinin và axit uric để xác định độ trưởng thành của thận thai nhi.", "- Định lượng các chất phospholipid để xác định độ trưởng thành của phổi thai.", "- Phân tích tế bào học để chẩn đoán các bệnh liên quan đến di truyền.", "- Định lượng AFP để chẩn đoán các dị dạng về hệ thần kinh."]}, {"heading": "3.1. Định tính hCG trong nước tiểu", "paragraphs": ["Hiện nay, việc định tính hCG trong nước tiểu để phát hiện có thai thường được thực hiện bằng cách sử dụng que thử thai nhanh. Xét nghiệm này cho kết quả dương tính khi nồng độ hCG từ mức 25 IU/l.", "Hình 2. Que thử thai nhanh"], "bullets": ["- Nếu kết quả dương tính: Khả năng có thai.", "- Nếu kết quả âm tính: cần làm lại sau vài ngày vì có thể bỏ qua những thai nghén ở giai đoạn sớm."]}, {"heading": "3.2. Định lượng (-hCG trong huyết thanh", "paragraphs": ["hCG là loại hormone thai kỳ được tiết ra bởi nhau thai. hCG đi vào máu ngay sau khi phôi bắt đầu hình thành, sau khoảng một tuần thụ tinh và rụng trứng, phôi thai xuất hiện và làm tổ vào niêm mạc tử cung. hCG gồm hai tiểu đơn vị khác nhau, gọi là alpha và beta. Vì tiểu đơn vị alpha giống với chuỗi alpha của FSH và LH, chỉ có tiểu đơn vị beta mới đặc hiệu cho hCG, do đó định lượng nồng độ beta hCG trở thành cơ sở cho định lượng hCG. Hiện nay, người ta sử dụng các phương pháp miễn dịch để định lượng (-hCG trong huyết thanh. Các phương pháp này cho phép phát hiện nồng độ rất thấp của (-hCG và theo dõi diễn biến của (-hCG khi định lượng liên tục. Từ ngày thứ 10 - 20 sau thụ thai, (-hCG tăng gấp đôi sau mỗi 1,4 đến 2 ngày. Đỉnh cao của (-hCG đạt được ở ngày thứ 60 đến 70 của thai kỳ.", "Định lượng (-hCG trong huyết thanh giúp:", "Kết quả", "(-hCG (mIU/ml)", "Âm tính", "< 5", "Nghi ngờ", "5 – 25", "Dương tính", "> 25", "3 – 4 tuần", "9 – 130", "4 – 5 tuần", "75 – 2.600", "5 – 6 tuần", "850 – 20.800", "6 – 7 tuần"], "bullets": ["- Chẩn đoán sớm thai nghén: định lượng (-hCG cho phép chẩn đoán sớm thai nghén kể cả khi chưa có dấu hiệu chậm kinh (khoảng 8,9 ngày sau khi trứng rụng).", "- Chẩn đoán và theo dõi các bất thường thai nghén:", "+ Chẩn đoán thai ngoài tử cung: bình thường (-hCG tăng gấp đôi sau mỗi 48 giờ, nếu thấp hơn thì nghi ngờ thai ngoài tử cung. Có 50% trường hợp thai ngoài tử cung có nồng độ (-hCG thấp dưới 800UI/l. Khi nồng độ (-hCG bằng hoặc cao hơn 2000UI/l, nếu siêu âm không thấy hình ảnh thai trong tử cung thì phải nghi ngờ thai ngoài tử cung. Khi nồng độ (-hCG dưới 2000UI/l và không có bằng chứng thai ngoài tử cung trên siêu âm, cần phải định lượng (-hCG nhiều lần.", "+ Chẩn đoán và theo dõi bệnh tế bào nuôi cần phải phối hợp định lượng (-hCG với siêu âm. (-hCG thường cao hơn 100.000 UI/l.", "+ Thai lưu hoặc đã sẩy nếu nồng độ (-hCG thấp không tương xứng với tuổi thai hoặc không tăng qua các lần xét nghiệm. Cần kết hợp với siêu âm để chẩn đoán.", "+ Sàng lọc huyết thanh mẹ trong 3 tháng giữa thai kỳ: Nồng độ AFP giảm đồng thời cùng với nồng độ hCG và estriol thì thai nhi có nguy cơ cao bị hội chứng Down (Trisomy 21 hay tam thể 21), hội chứng Edwards (Trisomy 18 hay tam thể 18) hoặc một số bất thường nhiễm sắc thể khác."]}, {"heading": "4.000 – 100.200", "paragraphs": ["7 – 12 tuần"], "bullets": []}, {"heading": "11.500 – 289.000", "paragraphs": ["12 – 16 tuần"], "bullets": []}, {"heading": "18.300 – 137.000", "paragraphs": ["16 – 29 tuần"], "bullets": []}, {"heading": "1.400 – 53.000", "paragraphs": ["29 – 41 tuần", "940 – 60.000", "4 - 6 tuần sau sinh", "< 5", "Bảng 1. Giá trị (-hCG thay đổi theo tuổi thai"], "bullets": []}, {"heading": "3.3. AFP (alpha-fetoprotein)", "paragraphs": ["Thông thường, trong cơ thể luôn tồn tại một lượng AFP nhỏ nhất định. Tuy nhiên, khi một người mắc các bệnh lý về gan hay đang mang thai thì nồng độ này trong máu có thể tăng đáng kể. AFP được tổng hợp chủ yếu bởi gan của thai nhi, thải trừ qua nước tiểu vào buồng ối và một ít lưu thông qua bánh rau vào tuần hoàn của mẹ. Tuy nhiên, khi có bất thường ống thần kinh (bao gồm: thai vô sọ, hở khe đốt sống) hoặc tật khe hở thành bụng hoặc thoát vị rốn thì AFP sẽ đi từ thai thoát vào máu mẹ với một lượng lớn bình thường.", "Để xét nghiệm chính xác AFP thì cần xác định chính xác tuổi thai vì AFP tăng theo tuổi thai. AFP có độ nhạy lớn nhất trong tuổi thai 16-18 tuần nhưng thường sử dụng nó để tính nguy cơ trong giới hạn tuổi thai 15-22 tuần. Nếu nồng độ AFP cao trên hơn 2,5 lần mức bình thường song hành với tăng acetylcholinesterase cho thấy thai có nguy cơ bị mắc dị tật bẩm sinh như khuyết tật ống thần kinh. Nếu nồng độ AFP giảm có thể nghi ngờ thai nhi bị hội chứng Down hoặc hội chứng Edwards."], "bullets": []}, {"heading": "3.4. Protein huyết thanh liên quan đến thai nghén", "paragraphs": ["PAPP-A (Pregnancy Associated Plasma Protein A) là một loại glycoprotein do nhau thai sản xuất và bài tiết vào máu mẹ. Trong thai kỳ bình thường, nồng độ PAPP-A tăng dần trong suốt thai kỳ. Trong quý I của thai kỳ nếu thai nhi có nguy cơ bất thường nhiễm sắc thể 21 (hội chứng Down), nhiễm sắc thể 18 (hội chứng Edwards) và nhiễm sắc thể 13 (hội chứng Patau) sẽ thấy nồng độ PAPP-A trong máu mẹ giảm."], "bullets": []}, {"heading": "4.1. Siêu âm chẩn đoán trong 3 tháng đầu thai kỳ", "paragraphs": ["Chỉ định", "Hình 3. Siêu âm thai tuần thứ 5 thai kỳ", "Hình 4. Hình ảnh đa thai trong quý 1 thai kỳ", "Hình 5. Hình ảnh siêu âm thai trong và thai ngoài tử cung", "Hình 6. Hình ảnh siêu âm thai chết lưu", "Hình 7. Hình ảnh thai 13 tuần thoát vị rốn"], "bullets": ["- Xác định có thai hay không, vị trí của túi thai.", "- Xác định số lượng thai.", "- Xác định tim thai: Nếu siêu âm qua đường bụng có thể thấy được tim thai lúc thai khoảng 6,5 tuần, nếu qua đường âm đạo có thể thấy được thấy tim thai lúc thai 5,5 tuần.", "- Xác định tuổi thai: Xác định tuổi thai dựa theo kích thước túi thai (GS: gestational sac), túi ối (amniotic sac: AS), chiều dài đầu - mông (CRL: Crown-rump length), đường kính lưỡng đỉnh, chiều dài xương đùi. Khi tuổi thai tăng dần thì mức độ chính xác trong việc xác định tuổi thai bằng phương pháp siêu âm càng giảm đi. Khi tuổi thai từ 6-16 tuần, sai số chẩn đoán tuổi thai của siêu âm là ± 4 ngày. Khi tuổi thai từ 17-24 tuần, sai số này là ± 7 đến 10 ngày.", "- Khảo sát những bất thường của thai: thai ngoài tử cung, thai trứng, thai lưu, sẩy thai, bóc tách màng đệm, thai và dụng cụ tránh thai trong buồng tử cung...", "- Khảo sát các bất thường ở tử cung và phần phụ kèm thai nghén như: u xơ tử cung, khối u buồng trứng, các dị dạng  tử cung..."]}, {"heading": "4.2. Siêu âm chẩn đoán trong 3 tháng giữa và 3 tháng cuối thai kỳ", "paragraphs": ["Chỉ định:", "Hình 8. Hình ảnh siêu âm song thai hai bánh rau hai buồng ối", "Hình 9. Hình ảnh siêu âm não úng thủy và sứt môi hở hàm ếch", "Hình 10. Hình ảnh siêu âm rau bám trung tâm hoàn toàn", "Hình 11. Hình ảnh siêu âm đa ối"], "bullets": ["- Khảo sát hoạt động của tim thai: vị trí, tần số, nhịp tim thai.", "- Xác định lại số lượng thai. Nếu xác định đa thai, cần ghi nhận các thông tin về rau thai vì điều đó rất cần cho xử trí lâm sàng.", "+ Đặc điểm, số lượng, độ dày bánh rau.", "+ Dấu hiệu lamda sign (song thai một bánh rau, hai buồng ối) hay T sign ( song thai 2 bánh rau, hai buồng ối).", "+ Giới tính thai nhi: nếu hai thai nhi khác giới tính sẽ luôn có hai màng ối và hai màng đệm. Song thai đồng giới tính còn phụ thuộc vào một số yếu tố khác để tạo nên màng đệm.", "+ So sánh kích thước 2 thai: sự khác biệt kích thước của 2 thai lớn trên 20% có mối tương quan với tỷ lệ mắc bệnh và tử vong chu sinh cao.", "- Khảo sát ngôi thai", "- Sự phát triển của thai: Bằng việc đo kích thước của đường kính lưỡng đỉnh (BPD: Biparietal diameter), hoặc chu vi vòng đầu (HC: head circumference) và chiều dài xương đùi (FL: Femur length). Đánh giá trọng lượng thai và sự phát triển của thai thường dùng chu vi vòng bụng (AC: abdominal circumference).", "- Khảo sát các bất thường về cấu trúc giải phẫu và chức năng của thai.", "- Ước định thể tích nước ối: theo phương pháp Phelan, bình thường chỉ số ối (AFI) trong giới hạn 5-25cm, nếu ít hơn 5cm thì nghi ngờ thiểu ối, nếu trên 25cm thì có thể là đa ối.", "- Khảo sát vị trí và độ trưởng thành của bánh rau.", "- Dây rốn: bình thường dây rốn gồm 2 động mạch và 1 tĩnh mạch.", "- Khảo sát tìm các khối bất thường ở tử cung và 2 phần phụ: tử cung dị dạng, u xơ tử cung, khối u buồng trứng..."]}, {"heading": "4.4. Vai trò siêu âm trong hướng dẫn một số thăm dò chẩn đoán tiền sản", "paragraphs": [], "bullets": ["- Chọc dò ối: để đánh giá bất thường nhiễm sắc thể, định lượng AFP và achetyl cholinesterase trong dịch ối để đánh giá tình trạng dị tật ống thần kinh.", "- Chọc dò dây rốn áp dụng trong việc xử trí tình trạng thai nhi thiếu máu nặng. Tuy nhiên, thủ thuật này có mối tương quan với tỷ lệ tử vong cao ở thai nhi (1%) do đó hiếm khi được sử dụng với mục đích chẩn đoán di truyền.", "- Chọc hút gai rau để khảo sát di truyền học."]}, {"heading": "5. MONITORING", "paragraphs": ["Sử dụng monitoring sản khoa để ghi liên tục nhịp tim thai và cơn co tử cung trong khi có thai và khi chuyển dạ."], "bullets": []}, {"heading": "5.1. Mục đích", "paragraphs": ["Hình 12. Ghi biểu đồ tim thai với đầu dò ngoài buồng tử cung"], "bullets": ["- Phát hiện một số bất thường về tim thai.", "- Phát hiện một số bất thường về cơn co trong chuyển dạ."]}, {"heading": "5.2. Phân tích một biểu đồ tim thai và cơn co trên monitoring sản khoa", "paragraphs": ["Hai loại dao động này có giá trị tiên lượng thai suy (nhưng cần phân biệt với trường hợp thai ngủ).", "Hình 13. Hình ảnh CTG  bình thường", "Hình 14. Tim thai hình sin", "Hình 15. Các loại nhịp giảm trong đo Monitoring sản khoa", "Hình 16. Nhịp giảm kéo dài"], "bullets": ["- Nhịp tim thai cơ bản (NTTCB) : bình thường nằm trong khoảng 120-160 lần/phút, trung bình là 140 lần/phút.", "- Nhịp tim thai gọi là nhanh khi 160 – 180 lần/phút, gọi là nhanh trầm trọng khi vượt quá 180 lần/phút. Thông thường, nhịp tim nhanh độc lập với tình trạng ngạt. Tình trạng này thường liên quan đến các yếu tố ngoại lai như : nhiệt độ cơ thể mẹ, nhiễm trùng ôi, nhiễm trùng bào thai, tác dụng các thuốc như atropine hay beta –mimetic.", "- Nhịp tim thai cơ bản gọi là chậm khi 100 -120 nhip/phút, nhịp chậm vừa nhưng còn giữ được dao động nội tại thường là thay đổi mang tính chất sinh lý, phản ánh sự gia tăng trương lực đối giao cảm. Nhịp tim thai gọi là chậm trầm trọng khi dưới 100 lần/phút. Có thể liên quan đến tình trạng bloc nhĩ – thất, thường đi kèm bệnh lý tim bẩm sinh, hoặc giai đoạn muộn của suy thai.", "- Dao động nội tại (DĐNT)", "+ Dao động loại 0: khi độ dao động dưới 5 nhịp/phút.", "+ Dao động loại 1: khi độ dao động trên 5 và dưới 10nhịp/phút.", "+ Dao động loại 2: khi độ dao động trên 10 và dưới 25 nhịp/phút. Là dao động nội tại bình thường.", "+ Dao động loại 3: khi độ dao động trên 25nhịp/phút. Là loại dao động có liên quan đến trường hợp bào thai bị kích thích, sự vận động của nó).", "- Nhịp tim thai tăng đặc trưng bằng sự gia tăng nhất thời của nhịp tim thai, có biên độ ít nhất 15 nhịp/phút và kéo dài ít nhất trong 15 giây. Nhịp tim thai tăng điển hình nhất là sau cử động thai. Một biểu đồ ghi tim thai được gọi là có đáp ứng nếu trong 20 phút theo dõi có ít nhất 2 đến 5 cử động thai và sau mỗi cử động thai là một đáp ứng tăng tim thai.", "- Nhịp tim thai giảm đặc trưng bởi sự giảm nhất thời của tim thai, với biên độ ít nhất 15 nhịp/phút và kéo dài ít nhất trong 15 giây. Các nhịp giảm ít hơn 15 giây không mang ý nghĩa bệnh lý. Các nhịp giảm xuất hiện đồng thời với con cơ tử cung gọi là nhịp giảm sớm, lệch muộn hơn so với cơn co tử cung là nhịp giảm muộn. Các nhịp giảm cũng có thể xuất hiện một cách tự phát không hoặc có kèm theo cơn co tử cung gọi là nhịp giảm bất định.", "- Cơn co tử cung: đánh giá cường độ, tần số cơn co."]}, {"heading": "Câu hỏi:", "paragraphs": ["Trình bày chỉ định, chống chỉ định và kết quả của soi ối?", "Trình bày các chỉ định, thời điểm và các tai biến của chọc ối?", "Liệt kê các xét nghiệm sinh hóa trong thăm dò sản khoa?", "Trình bày các chỉ định siêu âm trong thăm dò sản khoa?", "Trình bày và phân tích một số biểu đồ tim thai và cơn co trên monitoring sản khoa?", "CHƯƠNG 2. SẢN BỆNH"], "bullets": []}], "raw_text": "MỘT SỐ PHƯƠNG PHÁP THĂM DÒ TRONG SẢN KHOA\nMục tiêu học tập\nTrình bày được chỉ định, chống chỉ định và kết quả của soi ối\nTrình bày được chỉ định, thời điểm và các tai biến của chọc ối\nLiệt kê được các xét nghiệm sinh hóa trong thăm dò sản khoa\nTrình bày được các chỉ định siêu âm trong thai kỳ\nNêu được mục đích và phân tích một số biểu đồ tim thai và cơn co trên monitoring sản khoa\n1. SOI ỐI\nSoi ối cho phép nhìn thấy nước ối qua màng ối nhờ vào hệ thống ánh sáng lạnh. Xét nghiệm này chỉ nên thực hiện từ tuần 37 trở đi. Soi ối là một phương pháp có thể thực hiện đơn giản, để quan sát màu sắc nước ối. Tuy nhiên giải thích kết quả phải tinh tế. Nếu xuất hiện ối xanh là dấu hiệu báo động.\n1.1. Chỉ định\nTrong mọi trường hợp thai nghén có nghi ngờ thai suy khi ối chưa vỡ.\n1.2. Chống chỉ định\nNhiễm trùng âm đạo\nRau tiền đạo\nThai chết trong tử cung (vì nguy cơ làm ối vỡ và nhiễm trùng nặng sau vỡ ối).\nNgôi mông.\n1.3. Kết quả\n-\tNước ối bình thường: Màu trong, có vài nụ chất gây chuyển động.\n-\tNước ối có màu vàng: dấu hiệu này có thể cho thấy có phân su cũ trong nước ối, có tình trạng thai suy trước đó. Biểu hiện này không có ý nghĩa rõ ràng là thai đang suy hay không.\n-\tNước ối  màu xanh đặc, chứng tỏ có sự thải phân su mới.\n- Đôi khi sự quan sát nước ối bị hạn chế do chất nhầy cổ tử cung nhiều và đặc, hoặc trong trường hợp thiểu ối.\n2. CHỌC BUỒNG ỐI\n2.1. Chỉ định\n- Mẹ thuộc nhóm nguy cơ cao: tuổi mẹ ≥ 35 tuổi, mẹ có bộ nhiễm sắc thể bất thường, tiền căn gia đình có bất thường về nhiễm sắc thể hoặc bệnh lý về nhiễm sắc thể ( thiếu máu hồng cầu hình liềm…)\n- Xét nghiệm tầm soát thai kỳ nguy cơ cao bất thường về nhiễm sắc thể (Xét nghiệm double test, triple test, NIPT)\n- Tiền căn sinh con có bất thường nhiễm sắc thể (Down, chậm phát triển tâm thần…)\n- Thai kỳ trước có bất thường về nhiễm sắc thể giới tính: Turner 45X, 47XXY.\n- Vợ hoặc chồng có bất thường nhiễm sắc thể (dù kiểu hình bình thường)\n- Siêu âm bất thường: độ mờ da gáy dày, có các dị dạng thai: bệnh não nhỏ, không có sọ, bệnh thoát vị não, não úng thuỷ, nứt đốt sống…\n-  Đánh giá mức độ trưởng thành phổi của thai nhi trong những trường hợp cần chấm dứt thai kỳ sớm như: tiền sản giật, tiểu đường thai kỳ, bệnh lý nội khoa của mẹ…\n- Một số chỉ định ít gặp: chọc ối trong chẩn đoán nhiễm trùng trong tử cung, chọc ối để điều trị trong đa ối.\n\nHình 1. Chọc buồng ối\n2.2. Thời điểm chọc ối\n- Chọc ối trong quý 1 thai kỳ, giữa tuần 11 và 14. Tuy nhiên nguy cơ sẩy thai cao gấp 3 lần so với chọc ối ở quý 2. Vì vậy nếu cần thiết phải chẩn đoán tiền sản ở giai đoạn này nên lựa chọn sinh thiết gai rau.\n- Chọc ối trong quý 2 thai kỳ. Đây là thời điểm thường thực hiện, khoảng giữa tuần 15 và 18, có thể lên tới 20 tuần.\n- Chọc ối trong quý 3 thai kỳ. Chỉ thực hiện khi cần đánh giá mức độ trưởng thành phổi thai nhi hoặc điều trị trong đa ối.\n2.3. Tai Biến\n- Ra huyết âm đạo.\n- Xuất huyết ở rau hoặc dây rốn.\n- Sẩy thai hoặc thai lưu.\n- Rỉ ối, vỡ ối, nhiễm trùng ối.\n- Tổn thương thai.\n2.4.  Phân tích kết quả\n- Định lượng Bilirubin để chẩn đoán bất đồng nhóm máu mẹ - con.\n- Xác định phân su trong nước ối để chẩn đoán suy thai.\n- Định lượng estriol để chẩn đoán sự phát triển của thai.\n- Định lượng hPL để chẩn đoán sự phát triển và trưởng thành của thai và rau thai.\n- Định lượng một số men trong nước ối:\n+ Định lượng phosphatase kiềm, lacticodehydrogenase: tăng trong trường hợp thai thiếu oxy.\n+ Định lượng transaminase: có giá trị tiên lượng xấu khi tăng.\n- Định lượng Creatinin và axit uric để xác định độ trưởng thành của thận thai nhi.\n- Định lượng các chất phospholipid để xác định độ trưởng thành của phổi thai.\n- Phân tích tế bào học để chẩn đoán các bệnh liên quan đến di truyền.\n- Định lượng AFP để chẩn đoán các dị dạng về hệ thần kinh.\n3. XÉT NGHIỆM SINH HOÁ\n3.1. Định tính hCG trong nước tiểu\nHiện nay, việc định tính hCG trong nước tiểu để phát hiện có thai thường được thực hiện bằng cách sử dụng que thử thai nhanh. Xét nghiệm này cho kết quả dương tính khi nồng độ hCG từ mức 25 IU/l.\n- Nếu kết quả dương tính: Khả năng có thai.\n- Nếu kết quả âm tính: cần làm lại sau vài ngày vì có thể bỏ qua những thai nghén ở giai đoạn sớm.\n\nHình 2. Que thử thai nhanh\n3.2. Định lượng (-hCG trong huyết thanh\nhCG là loại hormone thai kỳ được tiết ra bởi nhau thai. hCG đi vào máu ngay sau khi phôi bắt đầu hình thành, sau khoảng một tuần thụ tinh và rụng trứng, phôi thai xuất hiện và làm tổ vào niêm mạc tử cung. hCG gồm hai tiểu đơn vị khác nhau, gọi là alpha và beta. Vì tiểu đơn vị alpha giống với chuỗi alpha của FSH và LH, chỉ có tiểu đơn vị beta mới đặc hiệu cho hCG, do đó định lượng nồng độ beta hCG trở thành cơ sở cho định lượng hCG. Hiện nay, người ta sử dụng các phương pháp miễn dịch để định lượng (-hCG trong huyết thanh. Các phương pháp này cho phép phát hiện nồng độ rất thấp của (-hCG và theo dõi diễn biến của (-hCG khi định lượng liên tục. Từ ngày thứ 10 - 20 sau thụ thai, (-hCG tăng gấp đôi sau mỗi 1,4 đến 2 ngày. Đỉnh cao của (-hCG đạt được ở ngày thứ 60 đến 70 của thai kỳ.\nĐịnh lượng (-hCG trong huyết thanh giúp:\n- Chẩn đoán sớm thai nghén: định lượng (-hCG cho phép chẩn đoán sớm thai nghén kể cả khi chưa có dấu hiệu chậm kinh (khoảng 8,9 ngày sau khi trứng rụng).\n- Chẩn đoán và theo dõi các bất thường thai nghén:\n+ Chẩn đoán thai ngoài tử cung: bình thường (-hCG tăng gấp đôi sau mỗi 48 giờ, nếu thấp hơn thì nghi ngờ thai ngoài tử cung. Có 50% trường hợp thai ngoài tử cung có nồng độ (-hCG thấp dưới 800UI/l. Khi nồng độ (-hCG bằng hoặc cao hơn 2000UI/l, nếu siêu âm không thấy hình ảnh thai trong tử cung thì phải nghi ngờ thai ngoài tử cung. Khi nồng độ (-hCG dưới 2000UI/l và không có bằng chứng thai ngoài tử cung trên siêu âm, cần phải định lượng (-hCG nhiều lần.\n+ Chẩn đoán và theo dõi bệnh tế bào nuôi cần phải phối hợp định lượng (-hCG với siêu âm. (-hCG thường cao hơn 100.000 UI/l.\n+ Thai lưu hoặc đã sẩy nếu nồng độ (-hCG thấp không tương xứng với tuổi thai hoặc không tăng qua các lần xét nghiệm. Cần kết hợp với siêu âm để chẩn đoán.\n+ Sàng lọc huyết thanh mẹ trong 3 tháng giữa thai kỳ: Nồng độ AFP giảm đồng thời cùng với nồng độ hCG và estriol thì thai nhi có nguy cơ cao bị hội chứng Down (Trisomy 21 hay tam thể 21), hội chứng Edwards (Trisomy 18 hay tam thể 18) hoặc một số bất thường nhiễm sắc thể khác.\nKết quả\n(-hCG (mIU/ml)\n\nÂm tính\n< 5\n\nNghi ngờ\n5 – 25\n\nDương tính\n> 25\n\n3 – 4 tuần\n9 – 130\n\n4 – 5 tuần\n75 – 2.600\n\n5 – 6 tuần\n850 – 20.800\n\n6 – 7 tuần\n4.000 – 100.200\n\n7 – 12 tuần\n11.500 – 289.000\n\n12 – 16 tuần\n18.300 – 137.000\n\n16 – 29 tuần\n1.400 – 53.000\n\n29 – 41 tuần\n940 – 60.000\n\n4 - 6 tuần sau sinh\n< 5\n\nBảng 1. Giá trị (-hCG thay đổi theo tuổi thai\n3.3. AFP (alpha-fetoprotein)\nThông thường, trong cơ thể luôn tồn tại một lượng AFP nhỏ nhất định. Tuy nhiên, khi một người mắc các bệnh lý về gan hay đang mang thai thì nồng độ này trong máu có thể tăng đáng kể. AFP được tổng hợp chủ yếu bởi gan của thai nhi, thải trừ qua nước tiểu vào buồng ối và một ít lưu thông qua bánh rau vào tuần hoàn của mẹ. Tuy nhiên, khi có bất thường ống thần kinh (bao gồm: thai vô sọ, hở khe đốt sống) hoặc tật khe hở thành bụng hoặc thoát vị rốn thì AFP sẽ đi từ thai thoát vào máu mẹ với một lượng lớn bình thường.\nĐể xét nghiệm chính xác AFP thì cần xác định chính xác tuổi thai vì AFP tăng theo tuổi thai. AFP có độ nhạy lớn nhất trong tuổi thai 16-18 tuần nhưng thường sử dụng nó để tính nguy cơ trong giới hạn tuổi thai 15-22 tuần. Nếu nồng độ AFP cao trên hơn 2,5 lần mức bình thường song hành với tăng acetylcholinesterase cho thấy thai có nguy cơ bị mắc dị tật bẩm sinh như khuyết tật ống thần kinh. Nếu nồng độ AFP giảm có thể nghi ngờ thai nhi bị hội chứng Down hoặc hội chứng Edwards.\n3.4. Protein huyết thanh liên quan đến thai nghén\nPAPP-A (Pregnancy Associated Plasma Protein A) là một loại glycoprotein do nhau thai sản xuất và bài tiết vào máu mẹ. Trong thai kỳ bình thường, nồng độ PAPP-A tăng dần trong suốt thai kỳ. Trong quý I của thai kỳ nếu thai nhi có nguy cơ bất thường nhiễm sắc thể 21 (hội chứng Down), nhiễm sắc thể 18 (hội chứng Edwards) và nhiễm sắc thể 13 (hội chứng Patau) sẽ thấy nồng độ PAPP-A trong máu mẹ giảm.\n4. SIÊU ÂM\n4.1. Siêu âm chẩn đoán trong 3 tháng đầu thai kỳ\nChỉ định\n- Xác định có thai hay không, vị trí của túi thai.\n- Xác định số lượng thai.\n- Xác định tim thai: Nếu siêu âm qua đường bụng có thể thấy được tim thai lúc thai khoảng 6,5 tuần, nếu qua đường âm đạo có thể thấy được thấy tim thai lúc thai 5,5 tuần.\n- Xác định tuổi thai: Xác định tuổi thai dựa theo kích thước túi thai (GS: gestational sac), túi ối (amniotic sac: AS), chiều dài đầu - mông (CRL: Crown-rump length), đường kính lưỡng đỉnh, chiều dài xương đùi. Khi tuổi thai tăng dần thì mức độ chính xác trong việc xác định tuổi thai bằng phương pháp siêu âm càng giảm đi. Khi tuổi thai từ 6-16 tuần, sai số chẩn đoán tuổi thai của siêu âm là ± 4 ngày. Khi tuổi thai từ 17-24 tuần, sai số này là ± 7 đến 10 ngày.\n- Khảo sát những bất thường của thai: thai ngoài tử cung, thai trứng, thai lưu, sẩy thai, bóc tách màng đệm, thai và dụng cụ tránh thai trong buồng tử cung...\n- Khảo sát các bất thường ở tử cung và phần phụ kèm thai nghén như: u xơ tử cung, khối u buồng trứng, các dị dạng  tử cung...\n\n\nHình 3. Siêu âm thai tuần thứ 5 thai kỳ\n\nHình 4. Hình ảnh đa thai trong quý 1 thai kỳ\n\nHình 5. Hình ảnh siêu âm thai trong và thai ngoài tử cung\n\nHình 6. Hình ảnh siêu âm thai chết lưu\n\nHình 7. Hình ảnh thai 13 tuần thoát vị rốn\n4.2. Siêu âm chẩn đoán trong 3 tháng giữa và 3 tháng cuối thai kỳ\nChỉ định:\n- Khảo sát hoạt động của tim thai: vị trí, tần số, nhịp tim thai.\n- Xác định lại số lượng thai. Nếu xác định đa thai, cần ghi nhận các thông tin về rau thai vì điều đó rất cần cho xử trí lâm sàng.\n\nHình 8. Hình ảnh siêu âm song thai hai bánh rau hai buồng ối\n+ Đặc điểm, số lượng, độ dày bánh rau.\n+ Dấu hiệu lamda sign (song thai một bánh rau, hai buồng ối) hay T sign ( song thai 2 bánh rau, hai buồng ối).\n+ Giới tính thai nhi: nếu hai thai nhi khác giới tính sẽ luôn có hai màng ối và hai màng đệm. Song thai đồng giới tính còn phụ thuộc vào một số yếu tố khác để tạo nên màng đệm.\n+ So sánh kích thước 2 thai: sự khác biệt kích thước của 2 thai lớn trên 20% có mối tương quan với tỷ lệ mắc bệnh và tử vong chu sinh cao.\n- Khảo sát ngôi thai\n- Sự phát triển của thai: Bằng việc đo kích thước của đường kính lưỡng đỉnh (BPD: Biparietal diameter), hoặc chu vi vòng đầu (HC: head circumference) và chiều dài xương đùi (FL: Femur length). Đánh giá trọng lượng thai và sự phát triển của thai thường dùng chu vi vòng bụng (AC: abdominal circumference).\n- Khảo sát các bất thường về cấu trúc giải phẫu và chức năng của thai.\n\nHình 9. Hình ảnh siêu âm não úng thủy và sứt môi hở hàm ếch\n- Ước định thể tích nước ối: theo phương pháp Phelan, bình thường chỉ số ối (AFI) trong giới hạn 5-25cm, nếu ít hơn 5cm thì nghi ngờ thiểu ối, nếu trên 25cm thì có thể là đa ối.\n- Khảo sát vị trí và độ trưởng thành của bánh rau.\n- Dây rốn: bình thường dây rốn gồm 2 động mạch và 1 tĩnh mạch.\n- Khảo sát tìm các khối bất thường ở tử cung và 2 phần phụ: tử cung dị dạng, u xơ tử cung, khối u buồng trứng...\n\nHình 10. Hình ảnh siêu âm rau bám trung tâm hoàn toàn\n\nHình 11. Hình ảnh siêu âm đa ối\n4.4. Vai trò siêu âm trong hướng dẫn một số thăm dò chẩn đoán tiền sản\n- Chọc dò ối: để đánh giá bất thường nhiễm sắc thể, định lượng AFP và achetyl cholinesterase trong dịch ối để đánh giá tình trạng dị tật ống thần kinh.\n- Chọc dò dây rốn áp dụng trong việc xử trí tình trạng thai nhi thiếu máu nặng. Tuy nhiên, thủ thuật này có mối tương quan với tỷ lệ tử vong cao ở thai nhi (1%) do đó hiếm khi được sử dụng với mục đích chẩn đoán di truyền.\n- Chọc hút gai rau để khảo sát di truyền học.\n5. MONITORING\nSử dụng monitoring sản khoa để ghi liên tục nhịp tim thai và cơn co tử cung trong khi có thai và khi chuyển dạ.\n5.1. Mục đích\n- Phát hiện một số bất thường về tim thai.\n- Phát hiện một số bất thường về cơn co trong chuyển dạ.\n\nHình 12. Ghi biểu đồ tim thai với đầu dò ngoài buồng tử cung\n5.2. Phân tích một biểu đồ tim thai và cơn co trên monitoring sản khoa\n- Nhịp tim thai cơ bản (NTTCB) : bình thường nằm trong khoảng 120-160 lần/phút, trung bình là 140 lần/phút.\n- Nhịp tim thai gọi là nhanh khi 160 – 180 lần/phút, gọi là nhanh trầm trọng khi vượt quá 180 lần/phút. Thông thường, nhịp tim nhanh độc lập với tình trạng ngạt. Tình trạng này thường liên quan đến các yếu tố ngoại lai như : nhiệt độ cơ thể mẹ, nhiễm trùng ôi, nhiễm trùng bào thai, tác dụng các thuốc như atropine hay beta –mimetic.\n- Nhịp tim thai cơ bản gọi là chậm khi 100 -120 nhip/phút, nhịp chậm vừa nhưng còn giữ được dao động nội tại thường là thay đổi mang tính chất sinh lý, phản ánh sự gia tăng trương lực đối giao cảm. Nhịp tim thai gọi là chậm trầm trọng khi dưới 100 lần/phút. Có thể liên quan đến tình trạng bloc nhĩ – thất, thường đi kèm bệnh lý tim bẩm sinh, hoặc giai đoạn muộn của suy thai.\n- Dao động nội tại (DĐNT)\n+ Dao động loại 0: khi độ dao động dưới 5 nhịp/phút.\n+ Dao động loại 1: khi độ dao động trên 5 và dưới 10nhịp/phút.\nHai loại dao động này có giá trị tiên lượng thai suy (nhưng cần phân biệt với trường hợp thai ngủ).\n+ Dao động loại 2: khi độ dao động trên 10 và dưới 25 nhịp/phút. Là dao động nội tại bình thường.\n+ Dao động loại 3: khi độ dao động trên 25nhịp/phút. Là loại dao động có liên quan đến trường hợp bào thai bị kích thích, sự vận động của nó).\n- Nhịp tim thai tăng đặc trưng bằng sự gia tăng nhất thời của nhịp tim thai, có biên độ ít nhất 15 nhịp/phút và kéo dài ít nhất trong 15 giây. Nhịp tim thai tăng điển hình nhất là sau cử động thai. Một biểu đồ ghi tim thai được gọi là có đáp ứng nếu trong 20 phút theo dõi có ít nhất 2 đến 5 cử động thai và sau mỗi cử động thai là một đáp ứng tăng tim thai.\n- Nhịp tim thai giảm đặc trưng bởi sự giảm nhất thời của tim thai, với biên độ ít nhất 15 nhịp/phút và kéo dài ít nhất trong 15 giây. Các nhịp giảm ít hơn 15 giây không mang ý nghĩa bệnh lý. Các nhịp giảm xuất hiện đồng thời với con cơ tử cung gọi là nhịp giảm sớm, lệch muộn hơn so với cơn co tử cung là nhịp giảm muộn. Các nhịp giảm cũng có thể xuất hiện một cách tự phát không hoặc có kèm theo cơn co tử cung gọi là nhịp giảm bất định.\n- Cơn co tử cung: đánh giá cường độ, tần số cơn co.\n\nHình 13. Hình ảnh CTG  bình thường\n\nHình 14. Tim thai hình sin\n\nHình 15. Các loại nhịp giảm trong đo Monitoring sản khoa\n\nHình 16. Nhịp giảm kéo dài\nCâu hỏi:\nTrình bày chỉ định, chống chỉ định và kết quả của soi ối?\nTrình bày các chỉ định, thời điểm và các tai biến của chọc ối?\nLiệt kê các xét nghiệm sinh hóa trong thăm dò sản khoa?\nTrình bày các chỉ định siêu âm trong thăm dò sản khoa?\nTrình bày và phân tích một số biểu đồ tim thai và cơn co trên monitoring sản khoa?\n\nCHƯƠNG 2. SẢN BỆNH", "priority": "Trung bình"}, {"id": "SK-15", "chapter": "Chương 2. Sản bệnh", "folder": "02_San_benh", "title": "Sẩy thai", "author": "Ths. Nguyễn Trung Kiên", "word_count": 3133, "line_count": 156, "key_numbers": ["1 tuần", "10 ngày", "10.000 UI", "100 mg", "12 tuần", "14 tuần", "16 tuần", "2 tuần", "20 tuần", "24 giờ", "3 tháng", "300 mg", "400 mg", "5 tháng", "5.000 UI", "8 tuần"], "key_drugs": ["misoprostol", "oxytocin"], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["SẨY THAI", "Ths. Nguyễn Trung Kiên"], "bullets": []}, {"heading": "Mục tiêu học tập", "paragraphs": ["Xếp loại được các nguyên nhân gây sẩy thai.", "Mô tả các triệu chứng để chẩn đoán dọa sẩy thai và sẩy thai.", "Phân loại được 6 hình thái lâm sàng của sẩy thai.", "Lựa chọn cách điều trị dọa sẩy thai và  sẩy thai."], "bullets": []}, {"heading": "1.1. Định nghĩa", "paragraphs": ["Gọi là sẩy thai khi thai bị tống xuất ra khỏi buồng tử cung, chấm dứt thai kỳ trước tuổi thai có thể sống được một cách độc lập bên ngoài tử cung (ngay cả khi có sự can thiệp của y tế). Theo Tổ chức Y tế Thế giới (WHO): sẩy thai khi thai bị tống xuất ra khỏi buồng tử cung trước tuần thứ 22 của thai kỳ hoặc trọng lượng nhỏ hơn 500 gam. Sẩy thai sớm là trường hợp sẩy thai trước 12 tuần và sẩy thai muộn là từ 12 - 20 tuần."], "bullets": []}, {"heading": "1.2. Phân loại", "paragraphs": ["Sẩy thai có thể gồm:"], "bullets": ["- Sẩy thai tự nhiên: là những loại sẩy thai đột nhiên xảy ra ở người có thai bình thường.", "- Sẩy thai liên tiếp: khi sẩy thai tự nhiên từ 3 lần liên tiếp trở lên. Theo Malpas, ở người phụ nữ có tiền sử sẩy thai 3 lần liên tiếp thì chỉ có cơ hội đẻ con sống là 50% và nguy cơ đẻ non cao hơn 20% so với người bình thường."]}, {"heading": "1.3. Tần suất", "paragraphs": [], "bullets": ["- Tỷ lệ sẩy thai thực sự rất khó đánh giá vì nhiều trường hợp sẩy thai xảy ra trước khi người phụ nữ nhận biết được mình có thai.", "- Trong số những trường hợp nhận biết được mình có thai, tỷ lệ sẩy thai chiếm khoảng 12% và một nửa trong số này xảy ra trước khi thai 8 tuần tuổi.", "- 80% trường hợp sẩy thai xảy ra trong 3 tháng đầu và 20 % xảy ra trong 3 tháng giữa."]}, {"heading": "1.4. Cách sẩy thai theo tuổi thai", "paragraphs": [], "bullets": ["- Sẩy thai hai tháng đầu (dưới 8 tuần lễ): hầu hết các trường hợp sẩy thai trước 8 tuần là sẩy thai hoàn toàn. Thời kỳ này, tổ chức chỉ là một bọc bằng quả trứng chim cút, trong có phôi, bên ngoài có các gai rau. Nếu sẩy, thường sẩy một thì, ra cả bọc lẫn với máu. Ngoại sản mạc rất mỏng, sẽ ra trong những ngày sau. Do đó, thời kỳ này ít bị sót rau, băng huyết.", "- Sẩy thai tháng thứ ba và thứ tư (8 - 16 tuần lễ): thai làm tổ chắc chắn hơn, được nuôi dưỡng tốt hơn nên tỷ lệ sẩy giảm xuống. Trong độ tuổi này thường gặp sẩy thai không hoàn toàn. Thời kỳ này, phôi đã lớn thành thai nhi, nếu sẩy thường sẩy từng phần, thì đầu: thai ra, thì hai: rau ra, thì ba: ngoại sản mạc ra. Vì vậy dễ bị sót rau và thường băng huyết nặng.", "- Sẩy thai tháng thứ năm và tháng thứ sáu: Sẩy thai diễn ra như cuộc đẻ: thì đầu thai ra, thì sau rau và màng rau ra."]}, {"heading": "2. NGUYÊN NHÂN GÂY SẨY THAI", "paragraphs": ["Chẩn đoán nguyên nhân gây sẩy thai là vấn đề quan trọng nhưng thường khó khăn. Đối với những trường hợp sẩy thai sớm 2 lần liên tiếp hoặc có một lần sẩy thai muộn, phải hỏi kỹ tiền sử, quá trình xuất hiện bệnh, khám toàn thân và bộ phận sinh dục, nếu cần kết hợp với xét nghiệm huyết học, sinh hóa, tế bào và tổ chức học bọc trứng, đôi khi phải chụp buồng tử cung ngoài thời kỳ có thai mới có thể tìm được nguyên nhân.", "Khoảng một nửa trường hợp sẩy thai có thể biết rõ nguyên nhân."], "bullets": []}, {"heading": "2.1. Các nguyên nhân chung", "paragraphs": [], "bullets": ["- Nguyên nhân toàn thân:", "+ Bệnh tim, bệnh thận.", "+ Mẹ bị đái tháo đường.", "+ Giang mai có thể gây sẩy thai vào tháng thứ 4 và tháng thứ 5 (vi khuẩn giang mai qua rau sau 5 tháng nên thường gây sinh non hơn là sẩy thai).", "+ Suy nhược cơ thể, thiếu sinh tố (nhất là vitamin E).", "- Viêm nhiễm niêm mạc tử cung (bệnh toxoplasmoses, listerioses).", "- Nguyên nhân miễn dịch: thai như một mảnh ghép trong tử cung người mẹ, phản ứng loại bỏ thai qua trung gian lympho bào T của người mẹ chống lại kháng nguyên thai sẽ ức chế sự phát triển của phôi do bất tương hợp hệ thống HLA (Humane Lymphocyte Antigens).", "- Yếu tố môi trường: hút thuốc, uống rượu, bức xạ, độc tố…", "- Rối loạn nhiễm sắc thể: nếu nuôi cấy tổ chức của những bọc thai sẩy để làm nhiễm sắc đồ thì thấy khoảng 50 - 85% những trường hợp sẩy là do rối loạn nhiễm sắc thể. Tuy nhiên, theo Mishell và cộng sự, 80 - 90% trường hợp thai bị sẩy ở những bà mẹ sẩy 3 hoặc trên 3 lần có nhiễm sắc thể bình thường. Những rối loạn thường gặp là ở các cặp nhiễm sắc thể thường số 6, 12, 13, 16, 17, 18, 21 hoặc ở nhiễm sắc thể giới tính (XO trong hội chứng Turner) hoặc đơn bội thể, tam bội thể, hình khảm. Tam bội nhiễm sắc thể thường là bất thường hay gặp nhất (50 - 65%), tiếp theo là đơn thể 45XO (7 - 15%), tam bội (15%), tứ bội (10%) và các bất thường cấu trúc (5%)."]}, {"heading": "2.2. Nguyên nhân sẩy thai tự nhiên", "paragraphs": [], "bullets": ["- Nhiễm khuẩn cấp: nhiễm khuẩn làm thai chết hoặc do thân nhiệt tăng cao gây nên cơn co tử cung và sẩy thai. Các nguyên nhân thường gặp là rubéon, cúm, nhiễm toxoplasma, sốt rét, viêm phổi, thương hàn….", "- Sang chấn: sang chấn mạnh, đột ngột, hoặc nhiều sang chấn nhỏ liên tiếp có thể gây sẩy thai. Những sang chấn này có thể là những cảm xúc tự nhiên do sợ hãi, xúc động quá độ hoặc những chấn thương thực thể như chấn thương vùng bụng hay do phẫu thuật.", "- Nhiễm độc: những nghề nghiệp độc hại nếu không được bảo vệ cẩn thận cũng có thể là nguyên nhân gây sẩy thai.", "- Trứng làm tổ bất thường:", "+ Làm tổ ở góc hoặc ở eo dễ bị sẩy.", "+ Sinh đôi, đa thai, đa ối.", "+ Chửa trứng toàn phần hoặc bán phần vì vậy những bệnh phẩm sẩy thai tự nhiên đều phải làm xét nghiệm giải phẫu bệnh."]}, {"heading": "2.3. Nguyên nhân sẩy thai liên tiếp", "paragraphs": ["Gọi là sẩy thai liên tiếp khi sản phụ bị sẩy thai tự nhiên liên tiếp từ 3 lần trở lên. Thường do nhiều nguyên nhân khác nhau:", "Hình 1. Đa huyết khối bánh rau, ở một phụ nữ bị hội chứng kháng phospholipid, thường đi kèm với thai chết."], "bullets": ["- Nguyên nhân ở tử cung: những bất thường tử cung do bẩm sinh hoặc mắc phải:", "+ Tử cung kém phát triển, khám thấy tử cung nhỏ, cổ tử cung nhỏ và dài.", "+ U xơ tử cung to hoặc nhiều nhân.", "+ Các dị dạng ở tử cung như tử cung đôi, tử cung hai sừng, vách ngăn tử cung.", "+ Hở eo tử cung: thường do tổn thương rách cổ tử cung sau đẻ, do nong nạo, khoét chóp cổ tử cung hoặc cắt cụt cổ tử cung. Bệnh thường gây sẩy thai đột ngột vào 3 tháng giữa của thai kỳ, trên lâm sàng xảy rất đột ngột, không có dấu hiệu báo trước, cổ tử cung mở nhưng sản phụ không thấy đau, chuyển dạ xảy ra rất nhanh sau vài cơn co mạnh và vỡ ối. Các lần sẩy sau có khuynh hướng xảy ra sớm hơn với trọng lượng thai nhỏ hơn. Ngoài thai kỳ, hở eo tử cung được chẩn đoán chắc chắn khi đút lọt nến Hegar số 8 qua cổ tử cung một cách dễ dàng.", "- Nguyên nhân nội tiết: tất cả các rối loạn nội tiết đều có thể gây sẩy thai, ví dụ:", "+ Giảm hormon hướng sinh dục rau thai (hCG) và nội tiết tố sinh dục (estrogen, progesteron).", "+ Cường androgen, cường hoặc thiểu năng giáp trạng cũng có thể gây sẩy thai.", "- Bất tương hợp yếu tố Rh giữa thai và mẹ.", "- Hội chứng kháng phospholipid (Antiphospholipid syndrome-APS): Kháng thể kháng phospholipids có thể là một immunoglobulin G (IgG), IgA, hoặc IgM isotype hiện diện trong cơ thể người mẹ gây sẩy thai do tắc mạch và nhồi máu ở bánh rau. Các kháng thể này có thể ức chế giải phóng các prostacyclin, một chất gây giãn mạch và ức chế ngưng tập tiểu cầu. Ngoài ra chúng còn ức chế hoạt hóa protein C, dẫn đến đông máu và hình thành Fibrin. Đây là bệnh tự miễn, tỷ lệ lưu hành ở thai phụ là 2,7-7%, ở bệnh nhân bị sẩy thai liên tiếp là 10-16% (Empson et al, 2005). In vitro: kháng thể ức chế tăng sản nguyên bào nuôi, huyết khối tắc mạch máu bánh rau."]}, {"heading": "3.1. Dọa sẩy thai", "paragraphs": ["Phôi thai còn sống, chưa bị bong ra khỏi niêm mạc tử cung.", "Hình 1. Dọa sẩy thai", "Hình 2. Hình ảnh siêu âm bóc tách màng ối"], "bullets": ["- Cơ năng:", "+ Ra máu âm đạo là triệu chứng chủ yếu. Ra máu đỏ hoặc máu đen, lượng ít, có thể kéo dài nhiều ngày, máu thường lẫn với dịch nhầy. Đó là một dấu hiệu báo động về một quá trình thai nghén diễn ra không bình thường.", "+ Sản phụ có cảm giác tức, nặng bụng dưới hoặc đau lưng.", "- Thực thể:", "+ Khám ngoài ít có giá trị vì tử cung và phần thai đang còn nhỏ nên khó phát hiện triệu chứng.", "+ Đặt mỏ vịt luôn luôn cần thiết để phát hiện chảy máu từ buồng tử cung và loại trừ nguyên nhân chảy máu từ các tổn thương ở cổ tử cung, âm đạo.", "+ Khám âm đạo: cổ tử cung dài, đóng kín, thân tử cung mềm, to tương ứng với tuổi thai.", "- Siêu âm: rất cần thiết để đánh giá nguyên nhân chảy máu", "+ Có hiện tượng bóc tách một phần nhỏ của bánh rau hay màng rau, bờ túi thai đều và rõ, có âm vang của phôi, có tim thai hoặc không."]}, {"heading": "3.2. Sẩy thai khó tránh", "paragraphs": [], "bullets": ["- Ra máu: máu ra nhiều, đỏ tươi, có thể không ra máu nhiều nhưng lại kéo dài dây dưa trên 10 ngày.", "- Đau bụng: đau vùng hạ vị, đau từng cơn ngày càng tăng.", "- Khám âm đạo: cổ tử cung có hiện tượng xóa, có thể hé mở lọt ngón tay, đoạn dưới phình to do bọc thai tụt  xuống phía cổ tử cung làm cho cổ tử cung có hình con quay."]}, {"heading": "3.3. Đang sẩy thai", "paragraphs": [], "bullets": ["- Ra máu âm đạo nhiều, tươi, có máu cục.", "- Đau quặn từng cơn vùng hạ vị do tử cung co thắt mạnh để tống thai ra.", "- Khám thấy đoạn dưới tử cung phình to do bọc thai đã bong khỏi thành tử cung. Cổ tử cung mở, đôi khi có thể thấy khối rau thai đang nằm lấp ló ở cổ tử cung."]}, {"heading": "3.4. Sẩy thai sót rau", "paragraphs": ["Thường bệnh nhân đã có triệu chứng doạ sẩy trước đó, rồi có một lúc đau bụng nhiều hơn, ra máu nhiều hơn. Bệnh nhân có thể ghi nhận có một mảnh mô được tống xuất ra khỏi âm đạo. Tuy nhiên, ra máu âm dạo vẫn tiếp diễn và vẫn còn đau bụng âm ỉ.", "Hình 3. Sẩy thai sót rau"], "bullets": ["- Khám thấy cổ tử cung còn hé mở hay đã đóng kín. Thân tử cung còn to hơn bình thường.", "- Bệnh nhân có thể có biểu hiện nhiễm trùng.", "- Siêu âm có thể cho thấy hình ảnh sót rau trong buồng tử cung."]}, {"heading": "3.5. Sẩy thai băng huyết", "paragraphs": [], "bullets": ["- Ra máu âm đạo nhiều, máu tươi. Bệnh nhân có thể biểu hiện tình trạng choáng mất máu.", "- Khám âm đạo thấy nhiều máu tươi lẫn máu cục. Thường có phần thai thập thò ở cổ tử cung hoặc trong âm đạo. Trường hợp bệnh nhân vào viện muộn, thai đã sẩy thì không còn các triệu chứng này mà chỉ nổi bật các triệu chứng chảy máu."]}, {"heading": "3.6. Sẩy thai nhiễm khuẩn", "paragraphs": [], "bullets": ["- Sản phụ ra máu âm đạo kéo dài kèm theo hội chứng nhiễm trùng: sốt, mạch nhanh, vẻ mặt nhiễm trùng, bạch cầu tăng, CRP tăng.", "- Khám âm đạo thấy cổ tử cung hé mở, máu âm đạo sẫm màu, hôi. Tử cung mềm, ấn đau."]}, {"heading": "4.1. Chẩn đoán xác định", "paragraphs": ["Cần khai thác đầy đủ các triệu chứng lâm sàng và cận lâm sàng để chẩn đoán được các thể lâm sàng của bệnh lý sẩy thai."], "bullets": []}, {"heading": "4.2.1. Thể giả sẩy của thai ngoài tử cung", "paragraphs": ["Trong thai ngoài tử cung cũng có ra máu âm đạo và phần ngoại sản mạc tử cung bong ra nguyên khối nên dễ nhầm với sẩy thai.", "Khám thấy các dấu hiệu của thai ngoài tử cung như chậm kinh, ra máu, tử cung mềm, ấn đau, túi cùng Douglas đầy  và đau. Tử cung không lớn tương xứng với tuổi thai, có thể sờ được khối u cạnh tử cung đau. Nếu nạo buồng tử cung, hình ảnh giải phẫu bệnh lý mô nạo sẽ là niêm mạc tử cung có phản ứng màng rụng, không thấy gai rau trong khối sẩy. Siêu âm: không thấy túi thai trong buồng tử cung, niêm mạc tử cung dày, không có hình ảnh các mảng tổ chức rau, xét nghiệm (hCG để củng cố chẩn đoán."], "bullets": []}, {"heading": "4.2.2. Chửa trứng", "paragraphs": ["Thường có rong huyết kéo dài, gây thiếu máu, nôn nhiều.", "Khám tử cung thường lớn hơn tuổi thai, có thể sờ thấy hai nang hoàng tuyến. Không sờ được các phần thai, không nghe được tim thai.", "Định lượng (hCG trong máu trên 100.000 mUI/ml.", "Siêu âm: có hình ảnh tuyết rơi."], "bullets": []}, {"heading": "4.2.3. Viêm phần phụ", "paragraphs": ["Nếu cấp tính thì có hội chứng nhiễm khuẩn cấp và thường đau cả hai bên hố chậu."], "bullets": []}, {"heading": "4.2.4. Viêm ruột thừa", "paragraphs": ["Có hội chứng nhiễm khuẩn và rối loạn tiêu hóa, điểm đau khu trú ở hố chậu phải."], "bullets": []}, {"heading": "5.1. Dọa sẩy thai", "paragraphs": [], "bullets": ["- Nghỉ ngơi tuyệt đối, ăn nhẹ chống táo bón.", "- Bổ sung sinh tố, nhất là vitamin E, có thể sử dụng acid folic 300 mg/ngày và vitamin B6.", "- Thuốc giảm co", "- Điều trị nội tiết:", "+ Progesteron tự nhiên nhằm giảm co bóp tử cung là chính, không nên dùng các progesteron tổng hợp vì có khả năng gây dị tật thai nhi, nhất là trong giai đoạn tạo phôi ở hai tháng đầu thai kỳ. Một số tác giả chỉ định progesteron đơn độc, một số khác phối hợp với estrogen do tăng hiệu quả dinh dưỡng đối với tử cung. utrogestan 100 mg, liều lượng tùy từng trường hợp, có thể cho tới 400 mg/ngày.", "+ Pregnyl: dùng 10.000 UI vào lúc chẩn đoán có thai, sau đó 5.000 UI 2 lần 1 tuần cho đến tuần thứ 12.", "+ Không nên điều trị nội tiết đối với thai quá 14 tuần.", "- Sử dụng kháng sinh khi nghi ngờ có nhiễm khuẩn.", "- Tránh giao hợp cho đến 2 tuần sau khi ngưng ra máu."]}, {"heading": "5.2. Sắp sẩy và đang sẩy hoặc sẩy thai sót rau", "paragraphs": ["Nguyên tắc là phải nạo buồng tử cung để lấy hết thai và rau, đề phòng băng huyết và nhiễm khuẩn. Trong khi xử trí phải dựa vào tình trạng toàn thân của bệnh nhân, tuổi thai, sự xóa, mở cổ tử cung để xử trí thích hợp."], "bullets": []}, {"heading": "5.2.1. Sẩy thai băng huyết", "paragraphs": [], "bullets": ["- Tuyến xã: chuyển tuyến trên, nếu có choáng truyền dịch mặn đẳng trương 9o/oo trong khi chuyển tuyến hoặc chờ tuyến trên xuống xử trí.", "- Tuyến huyện: hồi sức tích cực bằng truyền dịch và máu. Khi tình trạng toàn thân cho phép thì nong cổ tử cung, gắp bọc thai ra, hút hay nạo nạo buồng tử cung. Sau nạo tiêm bắp 10 đơn vị oxytocin. Có thể cho oxytocin nhiều lần nếu còn chảy máu. Cũng có thể dùng misoprostol đường trực tràng để giúp khống chế chảy máu."]}, {"heading": "5.2.2. Mới sẩy thai không băng huyết", "paragraphs": [], "bullets": ["- Tuyến xã: cho uống kháng sinh, tư vấn và chuyển tuyến huyện.", "- Tuyến huyện: siêu âm buồng tử cung, nếu đã sạch không cần hút hay nạo lại. Nếu còn sót rau nạo lấy hết tổ chức rau."]}, {"heading": "5.2.3. Sẩy thai nhiễm khuẩn", "paragraphs": [], "bullets": ["- Cho kháng sinh, tư vấn, chuyển tuyến.", "- Cho kháng sinh liều cao phối hợp và oxytocin.", "- Nạo buồng tử cung sau ít nhất 12 - 24 giờ. Khi nạo phải cẩn thận vì dễ bị thủng tử cung và nhiễm khuẩn lan tỏa.", "- Trong trường hợp nhiễm khuẩn nặng (viêm tử cung toàn bộ, nhiễm khuẩn huyết) có thể chỉ định cắt tử cung. Cần tư vấn trước và sau phẫu thuật."]}, {"heading": "5.3. Sẩy thai liên tiếp", "paragraphs": ["Để xác định nguyên nhân phải sử dụng các phương pháp thăm dò và xét nghiệm như định lượng hormon, xét nghiệm giang mai, yếu tố Rh, nhiễm sắc đồ, chụp buồng tử cung..."], "bullets": ["- Mổ bóc nhân xơ tử cung, mổ cắt vách ngăn tử cung....", "- Khâu vòng cổ tử cung cho các  trường hợp hở eo tử cung.", "- Điều trị những nguyên nhân toàn thân: giang mai, đái tháo đường, viêm thận.", "- Điều trị nguyên nhân do rối loạn nội tiết như thiểu năng giáp trạng; với thiếu hụt estrogen, progesteron thì nên điều trị ngay và sớm từ khi mới có thai và liên tục trong 12 tuần đầu của thai kỳ.", "- Với hội chứng kháng phospholipid cần điều trị bằng các thuốc chống huyết khối: lovenox…"]}], "raw_text": "SẨY THAI\nThs. Nguyễn Trung Kiên\nMục tiêu học tập\nXếp loại được các nguyên nhân gây sẩy thai.\nMô tả các triệu chứng để chẩn đoán dọa sẩy thai và sẩy thai.\nPhân loại được 6 hình thái lâm sàng của sẩy thai.\nLựa chọn cách điều trị dọa sẩy thai và  sẩy thai.\n\n1. ĐẠI CƯƠNG\n1.1. Định nghĩa\nGọi là sẩy thai khi thai bị tống xuất ra khỏi buồng tử cung, chấm dứt thai kỳ trước tuổi thai có thể sống được một cách độc lập bên ngoài tử cung (ngay cả khi có sự can thiệp của y tế). Theo Tổ chức Y tế Thế giới (WHO): sẩy thai khi thai bị tống xuất ra khỏi buồng tử cung trước tuần thứ 22 của thai kỳ hoặc trọng lượng nhỏ hơn 500 gam. Sẩy thai sớm là trường hợp sẩy thai trước 12 tuần và sẩy thai muộn là từ 12 - 20 tuần.\n1.2. Phân loại\nSẩy thai có thể gồm:\n- Sẩy thai tự nhiên: là những loại sẩy thai đột nhiên xảy ra ở người có thai bình thường.\n- Sẩy thai liên tiếp: khi sẩy thai tự nhiên từ 3 lần liên tiếp trở lên. Theo Malpas, ở người phụ nữ có tiền sử sẩy thai 3 lần liên tiếp thì chỉ có cơ hội đẻ con sống là 50% và nguy cơ đẻ non cao hơn 20% so với người bình thường.\n1.3. Tần suất\n- Tỷ lệ sẩy thai thực sự rất khó đánh giá vì nhiều trường hợp sẩy thai xảy ra trước khi người phụ nữ nhận biết được mình có thai.\n- Trong số những trường hợp nhận biết được mình có thai, tỷ lệ sẩy thai chiếm khoảng 12% và một nửa trong số này xảy ra trước khi thai 8 tuần tuổi.\n- 80% trường hợp sẩy thai xảy ra trong 3 tháng đầu và 20 % xảy ra trong 3 tháng giữa.\n1.4. Cách sẩy thai theo tuổi thai\n- Sẩy thai hai tháng đầu (dưới 8 tuần lễ): hầu hết các trường hợp sẩy thai trước 8 tuần là sẩy thai hoàn toàn. Thời kỳ này, tổ chức chỉ là một bọc bằng quả trứng chim cút, trong có phôi, bên ngoài có các gai rau. Nếu sẩy, thường sẩy một thì, ra cả bọc lẫn với máu. Ngoại sản mạc rất mỏng, sẽ ra trong những ngày sau. Do đó, thời kỳ này ít bị sót rau, băng huyết.\n- Sẩy thai tháng thứ ba và thứ tư (8 - 16 tuần lễ): thai làm tổ chắc chắn hơn, được nuôi dưỡng tốt hơn nên tỷ lệ sẩy giảm xuống. Trong độ tuổi này thường gặp sẩy thai không hoàn toàn. Thời kỳ này, phôi đã lớn thành thai nhi, nếu sẩy thường sẩy từng phần, thì đầu: thai ra, thì hai: rau ra, thì ba: ngoại sản mạc ra. Vì vậy dễ bị sót rau và thường băng huyết nặng.\n- Sẩy thai tháng thứ năm và tháng thứ sáu: Sẩy thai diễn ra như cuộc đẻ: thì đầu thai ra, thì sau rau và màng rau ra.\n\n2. NGUYÊN NHÂN GÂY SẨY THAI\nChẩn đoán nguyên nhân gây sẩy thai là vấn đề quan trọng nhưng thường khó khăn. Đối với những trường hợp sẩy thai sớm 2 lần liên tiếp hoặc có một lần sẩy thai muộn, phải hỏi kỹ tiền sử, quá trình xuất hiện bệnh, khám toàn thân và bộ phận sinh dục, nếu cần kết hợp với xét nghiệm huyết học, sinh hóa, tế bào và tổ chức học bọc trứng, đôi khi phải chụp buồng tử cung ngoài thời kỳ có thai mới có thể tìm được nguyên nhân.\nKhoảng một nửa trường hợp sẩy thai có thể biết rõ nguyên nhân.\n2.1. Các nguyên nhân chung\n- Nguyên nhân toàn thân:\n+ Bệnh tim, bệnh thận.\n+ Mẹ bị đái tháo đường.\n+ Giang mai có thể gây sẩy thai vào tháng thứ 4 và tháng thứ 5 (vi khuẩn giang mai qua rau sau 5 tháng nên thường gây sinh non hơn là sẩy thai).\n+ Suy nhược cơ thể, thiếu sinh tố (nhất là vitamin E).\n- Viêm nhiễm niêm mạc tử cung (bệnh toxoplasmoses, listerioses).\n- Nguyên nhân miễn dịch: thai như một mảnh ghép trong tử cung người mẹ, phản ứng loại bỏ thai qua trung gian lympho bào T của người mẹ chống lại kháng nguyên thai sẽ ức chế sự phát triển của phôi do bất tương hợp hệ thống HLA (Humane Lymphocyte Antigens).\n- Yếu tố môi trường: hút thuốc, uống rượu, bức xạ, độc tố…\n- Rối loạn nhiễm sắc thể: nếu nuôi cấy tổ chức của những bọc thai sẩy để làm nhiễm sắc đồ thì thấy khoảng 50 - 85% những trường hợp sẩy là do rối loạn nhiễm sắc thể. Tuy nhiên, theo Mishell và cộng sự, 80 - 90% trường hợp thai bị sẩy ở những bà mẹ sẩy 3 hoặc trên 3 lần có nhiễm sắc thể bình thường. Những rối loạn thường gặp là ở các cặp nhiễm sắc thể thường số 6, 12, 13, 16, 17, 18, 21 hoặc ở nhiễm sắc thể giới tính (XO trong hội chứng Turner) hoặc đơn bội thể, tam bội thể, hình khảm. Tam bội nhiễm sắc thể thường là bất thường hay gặp nhất (50 - 65%), tiếp theo là đơn thể 45XO (7 - 15%), tam bội (15%), tứ bội (10%) và các bất thường cấu trúc (5%).\n2.2. Nguyên nhân sẩy thai tự nhiên\n- Nhiễm khuẩn cấp: nhiễm khuẩn làm thai chết hoặc do thân nhiệt tăng cao gây nên cơn co tử cung và sẩy thai. Các nguyên nhân thường gặp là rubéon, cúm, nhiễm toxoplasma, sốt rét, viêm phổi, thương hàn….\n- Sang chấn: sang chấn mạnh, đột ngột, hoặc nhiều sang chấn nhỏ liên tiếp có thể gây sẩy thai. Những sang chấn này có thể là những cảm xúc tự nhiên do sợ hãi, xúc động quá độ hoặc những chấn thương thực thể như chấn thương vùng bụng hay do phẫu thuật.\n- Nhiễm độc: những nghề nghiệp độc hại nếu không được bảo vệ cẩn thận cũng có thể là nguyên nhân gây sẩy thai.\n- Trứng làm tổ bất thường:\n+ Làm tổ ở góc hoặc ở eo dễ bị sẩy.\n+ Sinh đôi, đa thai, đa ối.\n+ Chửa trứng toàn phần hoặc bán phần vì vậy những bệnh phẩm sẩy thai tự nhiên đều phải làm xét nghiệm giải phẫu bệnh.\n2.3. Nguyên nhân sẩy thai liên tiếp\nGọi là sẩy thai liên tiếp khi sản phụ bị sẩy thai tự nhiên liên tiếp từ 3 lần trở lên. Thường do nhiều nguyên nhân khác nhau:\n- Nguyên nhân ở tử cung: những bất thường tử cung do bẩm sinh hoặc mắc phải:\n+ Tử cung kém phát triển, khám thấy tử cung nhỏ, cổ tử cung nhỏ và dài.\n+ U xơ tử cung to hoặc nhiều nhân.\n+ Các dị dạng ở tử cung như tử cung đôi, tử cung hai sừng, vách ngăn tử cung.\n+ Hở eo tử cung: thường do tổn thương rách cổ tử cung sau đẻ, do nong nạo, khoét chóp cổ tử cung hoặc cắt cụt cổ tử cung. Bệnh thường gây sẩy thai đột ngột vào 3 tháng giữa của thai kỳ, trên lâm sàng xảy rất đột ngột, không có dấu hiệu báo trước, cổ tử cung mở nhưng sản phụ không thấy đau, chuyển dạ xảy ra rất nhanh sau vài cơn co mạnh và vỡ ối. Các lần sẩy sau có khuynh hướng xảy ra sớm hơn với trọng lượng thai nhỏ hơn. Ngoài thai kỳ, hở eo tử cung được chẩn đoán chắc chắn khi đút lọt nến Hegar số 8 qua cổ tử cung một cách dễ dàng.\n- Nguyên nhân nội tiết: tất cả các rối loạn nội tiết đều có thể gây sẩy thai, ví dụ:\n+ Giảm hormon hướng sinh dục rau thai (hCG) và nội tiết tố sinh dục (estrogen, progesteron).\n+ Cường androgen, cường hoặc thiểu năng giáp trạng cũng có thể gây sẩy thai.\n- Bất tương hợp yếu tố Rh giữa thai và mẹ.\n- Hội chứng kháng phospholipid (Antiphospholipid syndrome-APS): Kháng thể kháng phospholipids có thể là một immunoglobulin G (IgG), IgA, hoặc IgM isotype hiện diện trong cơ thể người mẹ gây sẩy thai do tắc mạch và nhồi máu ở bánh rau. Các kháng thể này có thể ức chế giải phóng các prostacyclin, một chất gây giãn mạch và ức chế ngưng tập tiểu cầu. Ngoài ra chúng còn ức chế hoạt hóa protein C, dẫn đến đông máu và hình thành Fibrin. Đây là bệnh tự miễn, tỷ lệ lưu hành ở thai phụ là 2,7-7%, ở bệnh nhân bị sẩy thai liên tiếp là 10-16% (Empson et al, 2005). In vitro: kháng thể ức chế tăng sản nguyên bào nuôi, huyết khối tắc mạch máu bánh rau.\n\n\n\n\n\n\nHình 1. Đa huyết khối bánh rau, ở một phụ nữ bị hội chứng kháng phospholipid, thường đi kèm với thai chết.\n3.  LÂM SÀNG\n3.1. Dọa sẩy thai\nPhôi thai còn sống, chưa bị bong ra khỏi niêm mạc tử cung.\n\nHình 1. Dọa sẩy thai\n- Cơ năng:\n+ Ra máu âm đạo là triệu chứng chủ yếu. Ra máu đỏ hoặc máu đen, lượng ít, có thể kéo dài nhiều ngày, máu thường lẫn với dịch nhầy. Đó là một dấu hiệu báo động về một quá trình thai nghén diễn ra không bình thường.\n+ Sản phụ có cảm giác tức, nặng bụng dưới hoặc đau lưng.\n- Thực thể:\n+ Khám ngoài ít có giá trị vì tử cung và phần thai đang còn nhỏ nên khó phát hiện triệu chứng.\n+ Đặt mỏ vịt luôn luôn cần thiết để phát hiện chảy máu từ buồng tử cung và loại trừ nguyên nhân chảy máu từ các tổn thương ở cổ tử cung, âm đạo.\n+ Khám âm đạo: cổ tử cung dài, đóng kín, thân tử cung mềm, to tương ứng với tuổi thai.\n- Siêu âm: rất cần thiết để đánh giá nguyên nhân chảy máu\n+ Có hiện tượng bóc tách một phần nhỏ của bánh rau hay màng rau, bờ túi thai đều và rõ, có âm vang của phôi, có tim thai hoặc không.\n\nHình 2. Hình ảnh siêu âm bóc tách màng ối\n3.2. Sẩy thai khó tránh\n- Ra máu: máu ra nhiều, đỏ tươi, có thể không ra máu nhiều nhưng lại kéo dài dây dưa trên 10 ngày.\n- Đau bụng: đau vùng hạ vị, đau từng cơn ngày càng tăng.\n- Khám âm đạo: cổ tử cung có hiện tượng xóa, có thể hé mở lọt ngón tay, đoạn dưới phình to do bọc thai tụt  xuống phía cổ tử cung làm cho cổ tử cung có hình con quay.\n3.3. Đang sẩy thai\n- Ra máu âm đạo nhiều, tươi, có máu cục.\n- Đau quặn từng cơn vùng hạ vị do tử cung co thắt mạnh để tống thai ra.\n- Khám thấy đoạn dưới tử cung phình to do bọc thai đã bong khỏi thành tử cung. Cổ tử cung mở, đôi khi có thể thấy khối rau thai đang nằm lấp ló ở cổ tử cung.\n3.4. Sẩy thai sót rau\nThường bệnh nhân đã có triệu chứng doạ sẩy trước đó, rồi có một lúc đau bụng nhiều hơn, ra máu nhiều hơn. Bệnh nhân có thể ghi nhận có một mảnh mô được tống xuất ra khỏi âm đạo. Tuy nhiên, ra máu âm dạo vẫn tiếp diễn và vẫn còn đau bụng âm ỉ.\n- Khám thấy cổ tử cung còn hé mở hay đã đóng kín. Thân tử cung còn to hơn bình thường.\n- Bệnh nhân có thể có biểu hiện nhiễm trùng.\n- Siêu âm có thể cho thấy hình ảnh sót rau trong buồng tử cung.\n\nHình 3. Sẩy thai sót rau\n3.5. Sẩy thai băng huyết\n- Ra máu âm đạo nhiều, máu tươi. Bệnh nhân có thể biểu hiện tình trạng choáng mất máu.\n- Khám âm đạo thấy nhiều máu tươi lẫn máu cục. Thường có phần thai thập thò ở cổ tử cung hoặc trong âm đạo. Trường hợp bệnh nhân vào viện muộn, thai đã sẩy thì không còn các triệu chứng này mà chỉ nổi bật các triệu chứng chảy máu.\n3.6. Sẩy thai nhiễm khuẩn\n- Sản phụ ra máu âm đạo kéo dài kèm theo hội chứng nhiễm trùng: sốt, mạch nhanh, vẻ mặt nhiễm trùng, bạch cầu tăng, CRP tăng.\n- Khám âm đạo thấy cổ tử cung hé mở, máu âm đạo sẫm màu, hôi. Tử cung mềm, ấn đau.\n\n4. CHẨN ĐOÁN\n4.1. Chẩn đoán xác định\nCần khai thác đầy đủ các triệu chứng lâm sàng và cận lâm sàng để chẩn đoán được các thể lâm sàng của bệnh lý sẩy thai.\n4.2. Chẩn đoán phân biệt\n4.2.1. Thể giả sẩy của thai ngoài tử cung\nTrong thai ngoài tử cung cũng có ra máu âm đạo và phần ngoại sản mạc tử cung bong ra nguyên khối nên dễ nhầm với sẩy thai.\nKhám thấy các dấu hiệu của thai ngoài tử cung như chậm kinh, ra máu, tử cung mềm, ấn đau, túi cùng Douglas đầy  và đau. Tử cung không lớn tương xứng với tuổi thai, có thể sờ được khối u cạnh tử cung đau. Nếu nạo buồng tử cung, hình ảnh giải phẫu bệnh lý mô nạo sẽ là niêm mạc tử cung có phản ứng màng rụng, không thấy gai rau trong khối sẩy. Siêu âm: không thấy túi thai trong buồng tử cung, niêm mạc tử cung dày, không có hình ảnh các mảng tổ chức rau, xét nghiệm (hCG để củng cố chẩn đoán.\n4.2.2. Chửa trứng\nThường có rong huyết kéo dài, gây thiếu máu, nôn nhiều.\nKhám tử cung thường lớn hơn tuổi thai, có thể sờ thấy hai nang hoàng tuyến. Không sờ được các phần thai, không nghe được tim thai.\nĐịnh lượng (hCG trong máu trên 100.000 mUI/ml.\nSiêu âm: có hình ảnh tuyết rơi.\n4.2.3. Viêm phần phụ\nNếu cấp tính thì có hội chứng nhiễm khuẩn cấp và thường đau cả hai bên hố chậu.\n4.2.4. Viêm ruột thừa\nCó hội chứng nhiễm khuẩn và rối loạn tiêu hóa, điểm đau khu trú ở hố chậu phải.\n5. ĐIỀU TRỊ\n5.1. Dọa sẩy thai\n- Nghỉ ngơi tuyệt đối, ăn nhẹ chống táo bón.\n- Bổ sung sinh tố, nhất là vitamin E, có thể sử dụng acid folic 300 mg/ngày và vitamin B6.\n- Thuốc giảm co\n- Điều trị nội tiết:\n+ Progesteron tự nhiên nhằm giảm co bóp tử cung là chính, không nên dùng các progesteron tổng hợp vì có khả năng gây dị tật thai nhi, nhất là trong giai đoạn tạo phôi ở hai tháng đầu thai kỳ. Một số tác giả chỉ định progesteron đơn độc, một số khác phối hợp với estrogen do tăng hiệu quả dinh dưỡng đối với tử cung. utrogestan 100 mg, liều lượng tùy từng trường hợp, có thể cho tới 400 mg/ngày.\n+ Pregnyl: dùng 10.000 UI vào lúc chẩn đoán có thai, sau đó 5.000 UI 2 lần 1 tuần cho đến tuần thứ 12.\n+ Không nên điều trị nội tiết đối với thai quá 14 tuần.\n- Sử dụng kháng sinh khi nghi ngờ có nhiễm khuẩn.\n- Tránh giao hợp cho đến 2 tuần sau khi ngưng ra máu.\n5.2. Sắp sẩy và đang sẩy hoặc sẩy thai sót rau\nNguyên tắc là phải nạo buồng tử cung để lấy hết thai và rau, đề phòng băng huyết và nhiễm khuẩn. Trong khi xử trí phải dựa vào tình trạng toàn thân của bệnh nhân, tuổi thai, sự xóa, mở cổ tử cung để xử trí thích hợp.\n5.2.1. Sẩy thai băng huyết\n- Tuyến xã: chuyển tuyến trên, nếu có choáng truyền dịch mặn đẳng trương 9o/oo trong khi chuyển tuyến hoặc chờ tuyến trên xuống xử trí.\n- Tuyến huyện: hồi sức tích cực bằng truyền dịch và máu. Khi tình trạng toàn thân cho phép thì nong cổ tử cung, gắp bọc thai ra, hút hay nạo nạo buồng tử cung. Sau nạo tiêm bắp 10 đơn vị oxytocin. Có thể cho oxytocin nhiều lần nếu còn chảy máu. Cũng có thể dùng misoprostol đường trực tràng để giúp khống chế chảy máu.\n5.2.2. Mới sẩy thai không băng huyết\n- Tuyến xã: cho uống kháng sinh, tư vấn và chuyển tuyến huyện.\n- Tuyến huyện: siêu âm buồng tử cung, nếu đã sạch không cần hút hay nạo lại. Nếu còn sót rau nạo lấy hết tổ chức rau.\n5.2.3. Sẩy thai nhiễm khuẩn\n- Cho kháng sinh, tư vấn, chuyển tuyến.\n- Cho kháng sinh liều cao phối hợp và oxytocin.\n- Nạo buồng tử cung sau ít nhất 12 - 24 giờ. Khi nạo phải cẩn thận vì dễ bị thủng tử cung và nhiễm khuẩn lan tỏa.\n- Trong trường hợp nhiễm khuẩn nặng (viêm tử cung toàn bộ, nhiễm khuẩn huyết) có thể chỉ định cắt tử cung. Cần tư vấn trước và sau phẫu thuật.\n5.3. Sẩy thai liên tiếp\nĐể xác định nguyên nhân phải sử dụng các phương pháp thăm dò và xét nghiệm như định lượng hormon, xét nghiệm giang mai, yếu tố Rh, nhiễm sắc đồ, chụp buồng tử cung...\n- Mổ bóc nhân xơ tử cung, mổ cắt vách ngăn tử cung....\n- Khâu vòng cổ tử cung cho các  trường hợp hở eo tử cung.\n- Điều trị những nguyên nhân toàn thân: giang mai, đái tháo đường, viêm thận.\n- Điều trị nguyên nhân do rối loạn nội tiết như thiểu năng giáp trạng; với thiếu hụt estrogen, progesteron thì nên điều trị ngay và sớm từ khi mới có thai và liên tục trong 12 tuần đầu của thai kỳ.\n- Với hội chứng kháng phospholipid cần điều trị bằng các thuốc chống huyết khối: lovenox…\nCâu hỏi:\n1. Trình bày  các nguyên nhân của sảy thai?\n2. Trình bày triệu chứng lâm sàng và hướng xử trí  doạ sảy thai?\n3. Trình bày triệu chứng lâm sàng và hướng xử trí đang sảy thai?\n4. Trình bày triệu chứng lâm sàng và hướng xử trí sảy thai băng huyết?\n5. Trình bày triệu chứng lâm sàng và hướng xử trí sảy thai sót rau?\n6. Trình bày triệu chứng lâm sàng và hướng xử trí  sảy thai nhiễm trùng?", "priority": "Cao (Trọng tâm BSNT)"}, {"id": "SK-16", "chapter": "Chương 2. Sản bệnh", "folder": "02_San_benh", "title": "Thai chết lưu trong tử cung", "author": "Ths. Nguyễn Trung Kiên", "word_count": 3240, "line_count": 138, "key_numbers": ["1 giờ", "1 tuần", "10 ngày", "2 mg", "2 tuần", "20 tuần", "250 mg", "28 tuần", "3 ngày", "3 tháng", "3 tuần", "4 tháng", "4 tuần", "5 tháng", "6 tuần", "7 ngày", "8 cm"], "key_drugs": ["Prostaglandin", "misoprostol", "oxytocin", "prostaglandin"], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["THAI CHẾT TRONG TỬ CUNG", "Ths. Nguyễn Trung Kiên"], "bullets": []}, {"heading": "1. ĐẠI CƯƠNG", "paragraphs": ["Thai chết lưu trong tử cung là thai chết và lưu lại buồng tử cung của người mẹ có thể xảy ra ở bất kỳ tuổi thai nào khi chưa có chuyển dạ.", "Trong nhiều trường hợp nguyên nhân gây thai chết khó xác định được.", "Sau khi thai chết, người mẹ có thể đứng trước hai nguy cơ lớn:", "Ngoài ra, thai chết còn gây ảnh hưởng nhiều đến tâm lý, tình cảm của người mẹ"], "bullets": ["- Các sản phẩm thoái hoá của thai đi vào tuần hoàn mẹ gây nên tình trạng rối loạn đông máu gây chảy máu, đe dọa tính mạng người mẹ.", "- Nguy cơ nhiễm trùng cao, tiến triển nhanh và nặng nề, đặc biệt là sau khi ối vỡ."]}, {"heading": "2.1. Nguyên nhân về phía mẹ", "paragraphs": [], "bullets": ["- Cao huyết áp trong thai kỳ, sản giật đều có thể gây chết thai nếu không được điều trị hay điều trị không đúng. Khi tiền sản giật càng nặng, tỷ lệ thai chết càng cao", "- Các bệnh mạn tính: viêm thận, xơ gan, bệnh tim...", "- Mẹ bị các bệnh nội tiết: basedow, thiểu năng giáp, đái tháo đường, thiểu năng hay cường tuyến thượng thận.", "- Các bệnh nhiễm khuẩn (bệnh lậu, giang mai...), nhiễm ký sinh trùng(đặc biệt là sốt rét ác tính làm cho thai chết gần 100%), nhiễm virus (Viêm gan, quai bị, cúm, sởi,...). Trong các trường hợp nặng thai chết có thể là do tác động trực tiếp của nguyên nhân gây bệnh lên thai,  bánh rau hoặc do tình trạng sốt của mẹ(vì hệ thống điều hoà nhiệt của thai chưa hoạt động, khả năng điều hoà nhiệt rất kém)."]}, {"heading": "2.2. Nguyên nhân do thai", "paragraphs": [], "bullets": ["- Đa thai kèm hội chứng truyền máu, thai cho máu dễ bị chết", "- Di tật bẩm sinh", "- Dị tật di truyền", "- Nhiễm khuẩn"]}, {"heading": "2.3. Nguyên nhân do rau", "paragraphs": ["Có một tỷ lệ không nhỏ (20-50%) thai chết không rõ nguyên nhân"], "bullets": ["- Bất thường của dây rốn: dây rốn thắt nút, dây rốn ngắn, dây rốn quấn cổ, dây rốn bị chèn ép hoặc bị xoắn quá mức.", "- Bệnh lý bánh rau: phù rau thai, bánh rau xơ hoá, bánh rau bị bong.", "- Đa ối: teo thực quản, thai vô sọ, mẹ đái tháo đường dẫn đến tăng đường máu thai.", "- Thiểu ối: thai dị dạng thận, tim, hệ thần kinh trung ương", "- Vỡ ối non nhưng không phát hiện sớm."]}, {"heading": "3. GIẢI PHẪU BỆNH LÝ", "paragraphs": ["Tuỳ theo tuổi thai và thời gian thai chết trong tử cung mà có các hình thái khác nhau:"], "bullets": []}, {"heading": "3.1. Thai bị tiêu", "paragraphs": ["Thai bị chết trong những tuần đầu, ở giai đoạn rau toàn diện thì thai có thể bị tiêu hoàn toàn, chỉ còn túi thai rỗng (trứng trống)."], "bullets": []}, {"heading": "3.2. Thai bị teo đét", "paragraphs": ["Khi tuổi thai 3 - 4 tháng, nếu thai chết sẽ bị teo đét lại: da vàng sám như màu đất, nhăn nheo bọc lấy xương, nước ối ít, sánh đặc, vẩn đục và cuối cùng sẽ khô đi để lại một lớp như sáp trắng bao quanh thai."], "bullets": []}, {"heading": "3.2.1. Thai bị ủng mục", "paragraphs": ["Khi tuổi thai hơn 5 tháng, nếu thai chết sẽ bị ủng mục. Lớp ngoại bì bị bong, bong dần từ chân lên đầu thai nhi. Lớp nội bì thấm hemoglobin nên có màu đỏ tím. Các nội tạng bị rữa, xương sọ ọp ẹp, chồng lên nhau, ngực xẹp, bánh rau vàng úa, teo đét xơ cứng lại. Màng rau vàng úa, nước ối cạn dần có màu hồng đỏ, dây rốn teo nhỏ. Chúng ta có thể dựa vào hiện tượng lột da để xác định thời gian thai chết:", "Ngày thứ ba:    lột da bàn chân.", "Ngày thứ tư:     lột da chi dưới.", "Ngày thứ tám:   lột da toàn thân."], "bullets": []}, {"heading": "3.2.2. Thai bị thối rữa", "paragraphs": ["Nếu ối vỡ, nhiễm trùng lan toả rất nhanh, gây nhiễm độc cho mẹ. Vi khuẩn có thể gặp là các vi khuẩn kỵ khí, hoại thư sinh hơi."], "bullets": []}, {"heading": "4.1. Thai dưới 20 tuần bị chết", "paragraphs": ["Việc chẩn đoán thai chết ở giai đoạn này tương đối khó khăn vì thường thai chết âm thầm, không có triệu chứng."], "bullets": ["- Bệnh nhân có đã các dấu hiệu có thai: chậm kinh, nghén, bụng to dần, hCG dương  tính, siêu âm thấy các phần thai và hoạt động của tim thai.", "- Ra máu âm đạo tự nhiên, ít một, máu đỏ sẫm hay nâu đen, không kèm theo đau bụng. Đây là một dấu hiệu phổ biến của thai chết dưới 20 tuần.", "- Tử cung không lớn lên, ngược lại tử cung sẽ nhỏ lại và nhỏ hơn tuổi thai", "- Xét nghiệm hCG trong nước tiểu âm tính (sau khi thai chết khoảng 2 tuần) hoặc βHCG giảm thấp < 25 mUI/ml.", "- Siêu âm (rất có giá trị trong chẩn đoán sớm): trên siêu âm thấy hình ảnh của thai nhưng không có hoạt động của thai và tim thai. Có khi chỉ thấy túi ối mà không có phần thai (trứng trống). Hình ảnh túi thai rỗng, méo mó không đều càng chắc chắn thai đã chết. Nếu có  nghi ngờ nên kiểm tra lại sau một tuần."]}, {"heading": "4.2. Thai trên 20 tuần", "paragraphs": ["Triệu chứng lâm sàng khá rõ, dễ xác định được thời gian thai chết hơn.", "Chẩn đoán thai chết luôn cần được khẳng định qua siêu âm. Đó là dấu hiệu tim thai không hoạt động."], "bullets": ["- Bệnh nhân đã có các dấu hiệu có thai với các dấu hiệu thai sống: bụng lớn, vú phát triển, có dấu hiệu thai máy. Nắn thấy rõ các phần của thai, nghe được tim thai, siêu âm có tim thai và cử động thai.", "- Trong một vài trường hợp, thai chết xảy ra ở bệnh nhân có nguy cơ cao đang được theo dõi. Người ta có thể phát hiện các dấu hiệu suy thai trước khi thai chết trong khi đang theo dõi một thai nghén nguy cơ cao. Ít khi thai chết trong quá trình chuyển dạ.", "- Xuất hiện dấu hiệu thai chết: không thấy cử động của thai (đây thường là dấu hiệu để bệnh nhân đi khám), bụng nhỏ dần, vú tiết sữa non, có thể ra máu âm đạo nhưng hiếm gặp ở giai đoạn này.", "- Nếu bệnh nhân có một số bệnh lý kèm theo như tiền sản giật, bệnh tim thì bệnh sẽ có xu hướng giảm nhẹ sau khi thai chết.", "- Thăm khám: khám thực thể và tiền sử không có nhiều giá trị chẩn đoán thai chết. Trong đa số trường hợp, dấu hiệu duy nhất là không có cử động của thai.", "+ Chiều cao tử cung nhỏ hơn tuổi thai. đo chiều cao tử cung nhỏ lại so với lần đo trước đặc biệt có ý nghĩa trong chẩn đoán thai chết trong tử cung.", "+ Nắn bụng không rõ phần thai.", "+ Không nghe được tim thai. Tim thai không nghe được khi khám có thể gợi ý thai chết. Tuy nhiên, điều đó chưa thể khẳng định chẩn đoán, chẩn đoán thai chết được khẳng định qua siêu âm.", "- Cận lâm sàng:", "+ Siêu âm: cho kết quả sớm và chính xác, không thấy cử động của thai, không có hoạt động của tim thai, đầu thai méo mó, có thể thấy một viền âm vang nghèo quanh hộp sọ do da đầu bị bong ra (dấu hiệu Hallo).", "+ X quang: sau khi thai chết khoảng 10 ngày có hình ảnh chồng xương sọ (dấu hiệu Spalding 1), cột sống bị gấp khúc, đốt sống chồng nhau (dấu hiệu Spalding 2) hoặc vòng sáng quanh đầu (dấu hiệu Devel). Đôi khi thấy bóng hơi trong buồng tim hoặc trong cách mạch máu lớn (dấu hiệu Robertson). Ngày nay không còn được sử dụng do nguy hiểm cho mẹ và thai nếu thai còn sống", "+ Định lượng Fibrinogen: đánh giá ảnh hưởng của thai chết lưu đến quá trình đông máu. Đây là xét nghiệm cần thiết và quan trọng trước khi can thiệp cho thai ra."]}, {"heading": "4.3. Chẩn đoán phân biệt", "paragraphs": ["Chẩn đoán phân biệt cần đặt ra đối với một thai nhỏ có tuổi thai dưới 20 tuần", "Thai ngoài tử cung: có rối loạn kinh nguyệt, đau bụng hạ vị; khám thấy có khối cạnh tử cung, ấn đau chói; siêu âm không thấy túi thai trong buồng tử cung, niêm mạc tử cung dày.", "Tử cung có u xơ: khám thấy tử cung to hơn bình thường và ra máu âm đạo.", "Thai trứng: đặc biệt dễ nhầm với thai trứng thoái hoá, đôi khi không thể phân biệt dược trên lâm sàng và cả siêu âm, chỉ khi làm giải phẫu bệnh lý mới chẩn đoán xác định được.", "Dọa sẩy thai: đặc biệt dễ nhầm khi thai dưới 6 tuần mà siêu âm chưa thấy tim thai, cần siêu âm lại sau 1 tuần để xác đinh chẩn đoán.", "Thai còn sống: đây là một vấn đề có thể xảy ra nếu chẩn đoán vội vàng. Tất cả các triệu chứng cơ năng, thực thể hoặc siêu âm cũng có thể không chính xác. Do đó, cách tốt nhất để tránh lầm lẫn là không nên vội vàng khi chẩn đoán và xử trí. Phải thăm khám kỹ, phối hợp các xét nghiệm, thăm dò nhiều lần mới được xác định chẩn đoán."], "bullets": []}, {"heading": "5.1. Chuyển dạ đẻ của thai chết trong tử cung", "paragraphs": ["Hầu hết (90%) là chuyển dạ tự nhiên, thai sẽ bị tống ra ngoài tử cung sau khi chết 2 - 3 tuần. Chuyển dạ tự nhiên thường xảy ra ở các trường hợp con rạ, thai gần đủ tháng, có chỉ số Bishop ( 6.", "Trường hợp tiến triển không thuận lợi (con so, tuổi thai nhỏ, chỉ số Bishop (5) cần phải phát khởi chuyển dạ sau khi đã chuẩn bị đầy đủ."], "bullets": ["- Đau bụng tăng dần như chuyển dạ.", "- Có hiện tượng xoá, mở cổ tử cung.", "- Ôi phồng hình “quả lê” do màng ối chết mất tính đàn hồi.", "- Ối có thể vỡ, nước ối hồng hoặc đen bẩn, dễ gây nhiễm trùng.", "- Rau thường sổ ngay sau khi thai sổ và hay có biến chứng chảy máu", "- Nhiễm trùng hậu sản dễ xảy ra trong thời kỳ hậu sản"]}, {"heading": "5.2.1. Rối loạn đông máu", "paragraphs": ["Rối loạn đông máu là một biến chứng nặng của thai chết trong tử cung. Thời gian thai chết và lưu trong buồng tử cung càng lâu, nếu chết lưu trên 4 tuần thì nguy cơ rối loạn đông máu càng cao. Fibrinogen giảm hoặc mất, kèm theo giảm tiểu cầu gây chảy máu không đông. Cơ chế có thể do:", "Dù rối loạn đông máu do CIVD hay do tiêu sợi huyết thì biểu hiện lâm sàng cũng là chảy máu không đông từ tử cung. Chảy máu có thể xuất hiện ngay sau đẻ hoặc sau khi can thiệp."], "bullets": ["- Đông máu rải rác trong lòng mạch (CIVD): các sản phẩm của rau thai thoái hoá, hoại tử sẽ kích hoạt quá trình sinh thromboplastin ở máu mẹ, dẫn tới tăng quá trình đông máu nên tăng tiêu thụ Fibrinogen", "- Tiêu huỷ fibrinogen: sản phẩm thoái hoá của rau thai có thể kích hoạt sự sản sinh quá nhiều plasminogen (chất phân huỷ fibrin) gây nên tiêu sợi huyết."]}, {"heading": "5.2.2. Biến chứng nhiễm trùng", "paragraphs": ["Nếu thai chết nhưng chưa có vỡ ối thường là vô trùng, chỉ nhiễm trùng khi ối đã vỡ. Biến chứng nhiễm trùng xảy ra rất nhanh, có thể đưa đến tình trạng nhiễm trùng máu, sốc nhiễm trùng đặc biệt là do vi khuẩn Gram âm....Các vi khuẩn có thể gặp là Colibacille, Proteus, Pseudomonas, thậm chí cả  Chlostridium Perferingent."], "bullets": []}, {"heading": "5.2.3. Ảnh hưởng đến tâm lý", "paragraphs": ["Tâm lý người mẹ bị ảnh hưởng nghiêm trọng khi thai chết, nhất là ở những thai phụ hiếm con, vô sinh. Ngoài ra họ còn có tâm lý lo sợ khi phải mang thai đã chết, do đó cần giải thích cặn kẽ, động viên để thai phụ tránh được những ảnh hưởng xấu cho lần mang thai này và những lần mang thai sau."], "bullets": []}, {"heading": "6.1. Tuyến xã", "paragraphs": ["Tư vấn và chuyển tuyến trên xử trí vì thai chết  trong tử cung có thể có các biến chứng nặng nề như: chảy máu, nhiễm khuẩn, có thể gây nguy hiểm đến tính mạng người mẹ."], "bullets": []}, {"heading": "6.2.1 Nguyên tắc chung", "paragraphs": ["Không vội vàng xử trí", "Những trường hợp dù xét nghiệm chức năng đông máu bình thường cũng cần chuẩn bị sẵn máu tươi hoặc các chế phẩm như fibrinogene, để điều trị khi có biến chứng rối loạn đông máu thứ phát xảy ra.", "(Một số tác giả sử dụng heparin để điều trị với liều từ 50000 - 100000 đv, tuy nhiên vấn đề này cần được nghiên cứu thêm để có thể áp dụng mà không gây tai biến)."], "bullets": ["- Chỉ  quyết định điều trị sau khi đã có chẩn đoán chính xác và chuẩn bị đầy đủ.", "- Làm các xét nghiệm: công thức máu, phân loại nhóm máu, chức năng đông máu toàn bộ, đặc biệt là lượng fibrinogen máu, và một số xét nghiệm cần thiết khác.", "- Nếu  xét nghiệm có hiện tượng rối loạn chức năng đông máu thì phải điều trị rối loạn đó rồi mới đặt vấn đề giải quyết thai lưu. Các thuốc sử dụng để điều chỉnh rối loạn đong máu:", "+ Fibrinogen truyền tĩnh mạch.", "+ Máu tươi toàn phần.", "+ Thuốc chống tiêu sinh sợi huyết: E.A.C, transamin 250 mg x 2 - 4 ống/ngày.", "- Những nguy cơ đáng lưu ý đối với thai chết lưu là rất dễ bị nhiễm khuẩn sau khi vỡ ối hoặc sau khi thai, rau ra có thể chảy máu nặng do rối loạn chức năng đông máu, hoặc đờ tử cung. Vì vậy cần phòng chống nhiễm khuẩn tốt, dùng kháng sinh toàn thân, liều cao và phối hợp kháng sinh trong 5 - 7 ngày."]}, {"heading": "6.2.2. Chuẩn bị cổ tử cung, hút/nạo thai", "paragraphs": ["ư Chuẩn bị cổ tử cung: bằng thuốc dựng misoproston 200àg ngậm dưới lưỡi trước khi làm thủ thuật 1 giờ hoặc nong cổ tử cung"], "bullets": ["- Hút/nạo buồng tử cung được áp dụng cho những trường hợp thai chết mà thể tích tử cung nhỏ hơn tử cung có thai 3 tháng hoặc chiều cao tử cung < 8 cm.", "- Phải giảm đau cho bệnh nhân trước khi nạo.", "- Sau thủ thuật dùng thuốc tăng co tử cung và kháng sinh. Không để sót tổ chức rau, thai.", "- Chú ý theo dõi đề phòng chảy máu, biến chứng rối loạn đông chảy máu sau nạo vì thủ thuật khó hơn nạo thai sống vì ra thai lưu xơ hóa bám chặt vào cơ tử cung. Cần giảm đau thật tốt, có thể gây mê để làm thủ thuật."]}, {"heading": "6.2.3 Khởi phát chuyển dạ", "paragraphs": ["Khi  đã chẩn đoán khẳng định thai chết, cần phát khởi chuyển dạ để cho thai ra. Phản ứng của bệnh nhân có thể khác nhau đối với hình thức xử trí này. Một số bệnh nhân có thể đồng ý khởi phát chuyển dạ ngay, một số khác cần đợi một thời gian nhất định (có thể vài giờ hoặc vài ngày) để họ ổn định về tinh thần. Cả hai trường hợp này đều có thể chấp nhận.", "Khi thai chết trong tử cung từ 3 - 4 tuần, lượng fibrinogen trong máu có thể giảm, dẫn tới rối loạn đông máu - chảy máu.", "Khởi phát chuyển dạ bắt đầu với việc chuẩn bị bệnh nhân:"], "bullets": []}, {"heading": "1. Dùng phương pháp Stein cải tiến: estrogen liều cao (Progynova 2 mg x 4 viên/ngày) x 3 ngày và sau đó truyền oxytocin tĩnh mạch. Bệnh nhân có tiền sử mổ đẻ cần được chú ý để tránh nguy cơ vỡ tử cung.", "paragraphs": ["Thai chết lưu sớm có thể được xử trí bằng việc đặt dung cụ và nong rồi đưa thai ra. Ở phụ nữ có thai chết lưu trước 28 tuần tuổi, khởi phát chuyển dạ bằng prostaglandin E2 đặt âm đạo (misoprostol đặt âm đạo) hoặc dùng đường uống và/hoặc oxytocin (thường áp dụng ở những phụ nữ không có sẹo mổ ở tử cung). Đối với những phụ nữ có thai chết lưu sau 28 tuần tuổi nên dùng những liều thấp hơn.", "Prostaglandin E2 và misoprostol không nên dùng ở những phụ nữ có tiền sử phẫu thuật tử cung vì có nguy cơ vỡ tử cung."], "bullets": []}, {"heading": "6.2.4. Đánh giá nguyên nhân", "paragraphs": ["Ngoài những nguyên nhân rõ ràng như: dây rốn thắt nút, quấn cổ…cần tìm hiểu những yếu tố nguy cơ bệnh lý từ phía mẹ như: tiểu đường, nhiễm khuẩn, cao huyết áp…và phía thai và phần phụ của thai: làm giải phẫu bệnh lý, thử máu, nuôi cấy, phân tích nhiễm sắc thể…", "Có tới 50% trường hợp thai chết lưu không rõ nguyên nhân. Tuy nhiên việc đánh giá nguyên nhân thai chết có thể tác động tới việc ước lượng tần số xuất hiện và giúp cải thiện tốt hơn hoạt động tư vấn, quản lý thai nghén, hệ thống chẩn đoán trong thời kỳ mang thai của phụ nữ và quản lý thai"], "bullets": []}, {"heading": "7. DỰ  PHÒNG", "paragraphs": ["Việc dự phòng thai chết trong tử cung là một vấn đề khó khăn bởi nhiều trường hợp không tìm được nguyên nhân, tuy nhiên giảm dược tỷ lệ thai chết nếu làm tốt những việc sau:"], "bullets": ["- Đăng ký quản lý thai nghén, tư vấn tốt cho các bà mẹ khi  mang thai ngay từ những tuần lễ đầu tiên, chú trọng chế độ dinh dưỡng và làm việc, tránh các lao động nặng, lao động trong môi trường độc hại. Không để sót các trường hợp thai quá ngày sinh", "- Phát hiện, chẩn đoán, điều trị sớm các bệnh lý của mẹ trước và trong khi mang thai.", "- Thận trọng khi dùng thuốc cho phụ nữ có thai.", "- Khi nghi ngờ thai chết lưu: nếu ở tuyến xã phải tư vấn và chuyển ngay lên tuyến trên, nếu ở tuyến trên phải cho nhập viện và điều trị kịp thời."]}, {"heading": "Câu hỏi:", "paragraphs": ["1:Trình bày  các nguyên nhân của thai chết lưu?", "2: Trình bày triệu chứng lâm sàng, cận lâm sàng và hướng xử trí thai dưới 20 tuần chết lưu?", "3: Trình bày triệu chứng lâm sàng,cận lâm sàng và hướng xử trí  thai trên 20 tuần chết lưu?"], "bullets": []}], "raw_text": "THAI CHẾT TRONG TỬ CUNG\nThs. Nguyễn Trung Kiên\n\nMục tiêu học tập\n1. Xác định nguyên nhân thai chết trong tử cung.\n2. Mô tả triệu chứng lâm sàng và cận lâm sàng của thai chết trong tử cung.\n3. Kể tên các nguy cơ của  thai chết trong tử cung.\n4. Lựa chọn được cách xử trí thai chết trong tử cung.\n\n1. ĐẠI CƯƠNG\nThai chết lưu trong tử cung là thai chết và lưu lại buồng tử cung của người mẹ có thể xảy ra ở bất kỳ tuổi thai nào khi chưa có chuyển dạ.\nTrong nhiều trường hợp nguyên nhân gây thai chết khó xác định được.\nSau khi thai chết, người mẹ có thể đứng trước hai nguy cơ lớn:\n- Các sản phẩm thoái hoá của thai đi vào tuần hoàn mẹ gây nên tình trạng rối loạn đông máu gây chảy máu, đe dọa tính mạng người mẹ.\n- Nguy cơ nhiễm trùng cao, tiến triển nhanh và nặng nề, đặc biệt là sau khi ối vỡ.\nNgoài ra, thai chết còn gây ảnh hưởng nhiều đến tâm lý, tình cảm của người mẹ\n2. NGUYÊN NHÂN\n2.1. Nguyên nhân về phía mẹ\n- Cao huyết áp trong thai kỳ, sản giật đều có thể gây chết thai nếu không được điều trị hay điều trị không đúng. Khi tiền sản giật càng nặng, tỷ lệ thai chết càng cao\n- Các bệnh mạn tính: viêm thận, xơ gan, bệnh tim...\n- Mẹ bị các bệnh nội tiết: basedow, thiểu năng giáp, đái tháo đường, thiểu năng hay cường tuyến thượng thận.\n- Các bệnh nhiễm khuẩn (bệnh lậu, giang mai...), nhiễm ký sinh trùng(đặc biệt là sốt rét ác tính làm cho thai chết gần 100%), nhiễm virus (Viêm gan, quai bị, cúm, sởi,...). Trong các trường hợp nặng thai chết có thể là do tác động trực tiếp của nguyên nhân gây bệnh lên thai,  bánh rau hoặc do tình trạng sốt của mẹ(vì hệ thống điều hoà nhiệt của thai chưa hoạt động, khả năng điều hoà nhiệt rất kém).\n2.2. Nguyên nhân do thai\n- Đa thai kèm hội chứng truyền máu, thai cho máu dễ bị chết\n- Di tật bẩm sinh\n- Dị tật di truyền\n- Nhiễm khuẩn\n2.3. Nguyên nhân do rau\n- Bất thường của dây rốn: dây rốn thắt nút, dây rốn ngắn, dây rốn quấn cổ, dây rốn bị chèn ép hoặc bị xoắn quá mức.\n- Bệnh lý bánh rau: phù rau thai, bánh rau xơ hoá, bánh rau bị bong.\n- Đa ối: teo thực quản, thai vô sọ, mẹ đái tháo đường dẫn đến tăng đường máu thai.\n- Thiểu ối: thai dị dạng thận, tim, hệ thần kinh trung ương\n- Vỡ ối non nhưng không phát hiện sớm.\nCó một tỷ lệ không nhỏ (20-50%) thai chết không rõ nguyên nhân\n3. GIẢI PHẪU BỆNH LÝ\nTuỳ theo tuổi thai và thời gian thai chết trong tử cung mà có các hình thái khác nhau:\n3.1. Thai bị tiêu\nThai bị chết trong những tuần đầu, ở giai đoạn rau toàn diện thì thai có thể bị tiêu hoàn toàn, chỉ còn túi thai rỗng (trứng trống).\n3.2. Thai bị teo đét\nKhi tuổi thai 3 - 4 tháng, nếu thai chết sẽ bị teo đét lại: da vàng sám như màu đất, nhăn nheo bọc lấy xương, nước ối ít, sánh đặc, vẩn đục và cuối cùng sẽ khô đi để lại một lớp như sáp trắng bao quanh thai.\n3.2.1. Thai bị ủng mục\nKhi tuổi thai hơn 5 tháng, nếu thai chết sẽ bị ủng mục. Lớp ngoại bì bị bong, bong dần từ chân lên đầu thai nhi. Lớp nội bì thấm hemoglobin nên có màu đỏ tím. Các nội tạng bị rữa, xương sọ ọp ẹp, chồng lên nhau, ngực xẹp, bánh rau vàng úa, teo đét xơ cứng lại. Màng rau vàng úa, nước ối cạn dần có màu hồng đỏ, dây rốn teo nhỏ. Chúng ta có thể dựa vào hiện tượng lột da để xác định thời gian thai chết:\nNgày thứ ba:    lột da bàn chân.\nNgày thứ tư:     lột da chi dưới.\nNgày thứ tám:   lột da toàn thân.\n3.2.2. Thai bị thối rữa\nNếu ối vỡ, nhiễm trùng lan toả rất nhanh, gây nhiễm độc cho mẹ. Vi khuẩn có thể gặp là các vi khuẩn kỵ khí, hoại thư sinh hơi.\n4. TRIỆU CHỨNG LÂM SÀNG VÀ CHẨN ĐOÁN\n4.1. Thai dưới 20 tuần bị chết\nViệc chẩn đoán thai chết ở giai đoạn này tương đối khó khăn vì thường thai chết âm thầm, không có triệu chứng.\n- Bệnh nhân có đã các dấu hiệu có thai: chậm kinh, nghén, bụng to dần, hCG dương  tính, siêu âm thấy các phần thai và hoạt động của tim thai.\n- Ra máu âm đạo tự nhiên, ít một, máu đỏ sẫm hay nâu đen, không kèm theo đau bụng. Đây là một dấu hiệu phổ biến của thai chết dưới 20 tuần.\n- Tử cung không lớn lên, ngược lại tử cung sẽ nhỏ lại và nhỏ hơn tuổi thai\n- Xét nghiệm hCG trong nước tiểu âm tính (sau khi thai chết khoảng 2 tuần) hoặc βHCG giảm thấp < 25 mUI/ml.\n- Siêu âm (rất có giá trị trong chẩn đoán sớm): trên siêu âm thấy hình ảnh của thai nhưng không có hoạt động của thai và tim thai. Có khi chỉ thấy túi ối mà không có phần thai (trứng trống). Hình ảnh túi thai rỗng, méo mó không đều càng chắc chắn thai đã chết. Nếu có  nghi ngờ nên kiểm tra lại sau một tuần.\n4.2. Thai trên 20 tuần\nTriệu chứng lâm sàng khá rõ, dễ xác định được thời gian thai chết hơn.\n- Bệnh nhân đã có các dấu hiệu có thai với các dấu hiệu thai sống: bụng lớn, vú phát triển, có dấu hiệu thai máy. Nắn thấy rõ các phần của thai, nghe được tim thai, siêu âm có tim thai và cử động thai.\n- Trong một vài trường hợp, thai chết xảy ra ở bệnh nhân có nguy cơ cao đang được theo dõi. Người ta có thể phát hiện các dấu hiệu suy thai trước khi thai chết trong khi đang theo dõi một thai nghén nguy cơ cao. Ít khi thai chết trong quá trình chuyển dạ.\n- Xuất hiện dấu hiệu thai chết: không thấy cử động của thai (đây thường là dấu hiệu để bệnh nhân đi khám), bụng nhỏ dần, vú tiết sữa non, có thể ra máu âm đạo nhưng hiếm gặp ở giai đoạn này.\n- Nếu bệnh nhân có một số bệnh lý kèm theo như tiền sản giật, bệnh tim thì bệnh sẽ có xu hướng giảm nhẹ sau khi thai chết.\n- Thăm khám: khám thực thể và tiền sử không có nhiều giá trị chẩn đoán thai chết. Trong đa số trường hợp, dấu hiệu duy nhất là không có cử động của thai.\n+ Chiều cao tử cung nhỏ hơn tuổi thai. đo chiều cao tử cung nhỏ lại so với lần đo trước đặc biệt có ý nghĩa trong chẩn đoán thai chết trong tử cung.\n+ Nắn bụng không rõ phần thai.\n+ Không nghe được tim thai. Tim thai không nghe được khi khám có thể gợi ý thai chết. Tuy nhiên, điều đó chưa thể khẳng định chẩn đoán, chẩn đoán thai chết được khẳng định qua siêu âm.\n- Cận lâm sàng:\n+ Siêu âm: cho kết quả sớm và chính xác, không thấy cử động của thai, không có hoạt động của tim thai, đầu thai méo mó, có thể thấy một viền âm vang nghèo quanh hộp sọ do da đầu bị bong ra (dấu hiệu Hallo).\n+ X quang: sau khi thai chết khoảng 10 ngày có hình ảnh chồng xương sọ (dấu hiệu Spalding 1), cột sống bị gấp khúc, đốt sống chồng nhau (dấu hiệu Spalding 2) hoặc vòng sáng quanh đầu (dấu hiệu Devel). Đôi khi thấy bóng hơi trong buồng tim hoặc trong cách mạch máu lớn (dấu hiệu Robertson). Ngày nay không còn được sử dụng do nguy hiểm cho mẹ và thai nếu thai còn sống\nChẩn đoán thai chết luôn cần được khẳng định qua siêu âm. Đó là dấu hiệu tim thai không hoạt động.\n+ Định lượng Fibrinogen: đánh giá ảnh hưởng của thai chết lưu đến quá trình đông máu. Đây là xét nghiệm cần thiết và quan trọng trước khi can thiệp cho thai ra.\n4.3. Chẩn đoán phân biệt\nChẩn đoán phân biệt cần đặt ra đối với một thai nhỏ có tuổi thai dưới 20 tuần\nThai ngoài tử cung: có rối loạn kinh nguyệt, đau bụng hạ vị; khám thấy có khối cạnh tử cung, ấn đau chói; siêu âm không thấy túi thai trong buồng tử cung, niêm mạc tử cung dày.\nTử cung có u xơ: khám thấy tử cung to hơn bình thường và ra máu âm đạo.\nThai trứng: đặc biệt dễ nhầm với thai trứng thoái hoá, đôi khi không thể phân biệt dược trên lâm sàng và cả siêu âm, chỉ khi làm giải phẫu bệnh lý mới chẩn đoán xác định được.\nDọa sẩy thai: đặc biệt dễ nhầm khi thai dưới 6 tuần mà siêu âm chưa thấy tim thai, cần siêu âm lại sau 1 tuần để xác đinh chẩn đoán.\nThai còn sống: đây là một vấn đề có thể xảy ra nếu chẩn đoán vội vàng. Tất cả các triệu chứng cơ năng, thực thể hoặc siêu âm cũng có thể không chính xác. Do đó, cách tốt nhất để tránh lầm lẫn là không nên vội vàng khi chẩn đoán và xử trí. Phải thăm khám kỹ, phối hợp các xét nghiệm, thăm dò nhiều lần mới được xác định chẩn đoán.\n5. TIẾN TRIỂN CỦA THAI CHẾT LƯU TRONG TỬ CUNG\n5.1. Chuyển dạ đẻ của thai chết trong tử cung\nHầu hết (90%) là chuyển dạ tự nhiên, thai sẽ bị tống ra ngoài tử cung sau khi chết 2 - 3 tuần. Chuyển dạ tự nhiên thường xảy ra ở các trường hợp con rạ, thai gần đủ tháng, có chỉ số Bishop ( 6.\n- Đau bụng tăng dần như chuyển dạ.\n- Có hiện tượng xoá, mở cổ tử cung.\n- Ôi phồng hình “quả lê” do màng ối chết mất tính đàn hồi.\n- Ối có thể vỡ, nước ối hồng hoặc đen bẩn, dễ gây nhiễm trùng.\n- Rau thường sổ ngay sau khi thai sổ và hay có biến chứng chảy máu\n- Nhiễm trùng hậu sản dễ xảy ra trong thời kỳ hậu sản\nTrường hợp tiến triển không thuận lợi (con so, tuổi thai nhỏ, chỉ số Bishop (5) cần phải phát khởi chuyển dạ sau khi đã chuẩn bị đầy đủ.\n5.2. Biến chứng\n5.2.1. Rối loạn đông máu\nRối loạn đông máu là một biến chứng nặng của thai chết trong tử cung. Thời gian thai chết và lưu trong buồng tử cung càng lâu, nếu chết lưu trên 4 tuần thì nguy cơ rối loạn đông máu càng cao. Fibrinogen giảm hoặc mất, kèm theo giảm tiểu cầu gây chảy máu không đông. Cơ chế có thể do:\n- Đông máu rải rác trong lòng mạch (CIVD): các sản phẩm của rau thai thoái hoá, hoại tử sẽ kích hoạt quá trình sinh thromboplastin ở máu mẹ, dẫn tới tăng quá trình đông máu nên tăng tiêu thụ Fibrinogen\n- Tiêu huỷ fibrinogen: sản phẩm thoái hoá của rau thai có thể kích hoạt sự sản sinh quá nhiều plasminogen (chất phân huỷ fibrin) gây nên tiêu sợi huyết.\nDù rối loạn đông máu do CIVD hay do tiêu sợi huyết thì biểu hiện lâm sàng cũng là chảy máu không đông từ tử cung. Chảy máu có thể xuất hiện ngay sau đẻ hoặc sau khi can thiệp.\n5.2.2. Biến chứng nhiễm trùng\nNếu thai chết nhưng chưa có vỡ ối thường là vô trùng, chỉ nhiễm trùng khi ối đã vỡ. Biến chứng nhiễm trùng xảy ra rất nhanh, có thể đưa đến tình trạng nhiễm trùng máu, sốc nhiễm trùng đặc biệt là do vi khuẩn Gram âm....Các vi khuẩn có thể gặp là Colibacille, Proteus, Pseudomonas, thậm chí cả  Chlostridium Perferingent.\n5.2.3. Ảnh hưởng đến tâm lý\nTâm lý người mẹ bị ảnh hưởng nghiêm trọng khi thai chết, nhất là ở những thai phụ hiếm con, vô sinh. Ngoài ra họ còn có tâm lý lo sợ khi phải mang thai đã chết, do đó cần giải thích cặn kẽ, động viên để thai phụ tránh được những ảnh hưởng xấu cho lần mang thai này và những lần mang thai sau.\n6.  THÁI ĐỘ XỬ TRÍ\n6.1. Tuyến xã\nTư vấn và chuyển tuyến trên xử trí vì thai chết  trong tử cung có thể có các biến chứng nặng nề như: chảy máu, nhiễm khuẩn, có thể gây nguy hiểm đến tính mạng người mẹ.\n6.2 Tuyến huyện và các tuyến cao hơn\n6.2.1 Nguyên tắc chung\nKhông vội vàng xử trí\n- Chỉ  quyết định điều trị sau khi đã có chẩn đoán chính xác và chuẩn bị đầy đủ.\n- Làm các xét nghiệm: công thức máu, phân loại nhóm máu, chức năng đông máu toàn bộ, đặc biệt là lượng fibrinogen máu, và một số xét nghiệm cần thiết khác.\n- Nếu  xét nghiệm có hiện tượng rối loạn chức năng đông máu thì phải điều trị rối loạn đó rồi mới đặt vấn đề giải quyết thai lưu. Các thuốc sử dụng để điều chỉnh rối loạn đong máu:\n+ Fibrinogen truyền tĩnh mạch.\n+ Máu tươi toàn phần.\n+ Thuốc chống tiêu sinh sợi huyết: E.A.C, transamin 250 mg x 2 - 4 ống/ngày.\nNhững trường hợp dù xét nghiệm chức năng đông máu bình thường cũng cần chuẩn bị sẵn máu tươi hoặc các chế phẩm như fibrinogene, để điều trị khi có biến chứng rối loạn đông máu thứ phát xảy ra.\n(Một số tác giả sử dụng heparin để điều trị với liều từ 50000 - 100000 đv, tuy nhiên vấn đề này cần được nghiên cứu thêm để có thể áp dụng mà không gây tai biến).\n- Những nguy cơ đáng lưu ý đối với thai chết lưu là rất dễ bị nhiễm khuẩn sau khi vỡ ối hoặc sau khi thai, rau ra có thể chảy máu nặng do rối loạn chức năng đông máu, hoặc đờ tử cung. Vì vậy cần phòng chống nhiễm khuẩn tốt, dùng kháng sinh toàn thân, liều cao và phối hợp kháng sinh trong 5 - 7 ngày.\n6.2.2. Chuẩn bị cổ tử cung, hút/nạo thai\n- Hút/nạo buồng tử cung được áp dụng cho những trường hợp thai chết mà thể tích tử cung nhỏ hơn tử cung có thai 3 tháng hoặc chiều cao tử cung < 8 cm.\n- Phải giảm đau cho bệnh nhân trước khi nạo.\nư Chuẩn bị cổ tử cung: bằng thuốc dựng misoproston 200àg ngậm dưới lưỡi trước khi làm thủ thuật 1 giờ hoặc nong cổ tử cung\n- Sau thủ thuật dùng thuốc tăng co tử cung và kháng sinh. Không để sót tổ chức rau, thai.\n- Chú ý theo dõi đề phòng chảy máu, biến chứng rối loạn đông chảy máu sau nạo vì thủ thuật khó hơn nạo thai sống vì ra thai lưu xơ hóa bám chặt vào cơ tử cung. Cần giảm đau thật tốt, có thể gây mê để làm thủ thuật.\n6.2.3 Khởi phát chuyển dạ\nKhi  đã chẩn đoán khẳng định thai chết, cần phát khởi chuyển dạ để cho thai ra. Phản ứng của bệnh nhân có thể khác nhau đối với hình thức xử trí này. Một số bệnh nhân có thể đồng ý khởi phát chuyển dạ ngay, một số khác cần đợi một thời gian nhất định (có thể vài giờ hoặc vài ngày) để họ ổn định về tinh thần. Cả hai trường hợp này đều có thể chấp nhận.\nKhi thai chết trong tử cung từ 3 - 4 tuần, lượng fibrinogen trong máu có thể giảm, dẫn tới rối loạn đông máu - chảy máu.\nKhởi phát chuyển dạ bắt đầu với việc chuẩn bị bệnh nhân:\n1. Dùng phương pháp Stein cải tiến: estrogen liều cao (Progynova 2 mg x 4 viên/ngày) x 3 ngày và sau đó truyền oxytocin tĩnh mạch. Bệnh nhân có tiền sử mổ đẻ cần được chú ý để tránh nguy cơ vỡ tử cung.\nThai chết lưu sớm có thể được xử trí bằng việc đặt dung cụ và nong rồi đưa thai ra. Ở phụ nữ có thai chết lưu trước 28 tuần tuổi, khởi phát chuyển dạ bằng prostaglandin E2 đặt âm đạo (misoprostol đặt âm đạo) hoặc dùng đường uống và/hoặc oxytocin (thường áp dụng ở những phụ nữ không có sẹo mổ ở tử cung). Đối với những phụ nữ có thai chết lưu sau 28 tuần tuổi nên dùng những liều thấp hơn.\nProstaglandin E2 và misoprostol không nên dùng ở những phụ nữ có tiền sử phẫu thuật tử cung vì có nguy cơ vỡ tử cung.\n6.2.4. Đánh giá nguyên nhân\nNgoài những nguyên nhân rõ ràng như: dây rốn thắt nút, quấn cổ…cần tìm hiểu những yếu tố nguy cơ bệnh lý từ phía mẹ như: tiểu đường, nhiễm khuẩn, cao huyết áp…và phía thai và phần phụ của thai: làm giải phẫu bệnh lý, thử máu, nuôi cấy, phân tích nhiễm sắc thể…\nCó tới 50% trường hợp thai chết lưu không rõ nguyên nhân. Tuy nhiên việc đánh giá nguyên nhân thai chết có thể tác động tới việc ước lượng tần số xuất hiện và giúp cải thiện tốt hơn hoạt động tư vấn, quản lý thai nghén, hệ thống chẩn đoán trong thời kỳ mang thai của phụ nữ và quản lý thai\n7. DỰ  PHÒNG\nViệc dự phòng thai chết trong tử cung là một vấn đề khó khăn bởi nhiều trường hợp không tìm được nguyên nhân, tuy nhiên giảm dược tỷ lệ thai chết nếu làm tốt những việc sau:\n- Đăng ký quản lý thai nghén, tư vấn tốt cho các bà mẹ khi  mang thai ngay từ những tuần lễ đầu tiên, chú trọng chế độ dinh dưỡng và làm việc, tránh các lao động nặng, lao động trong môi trường độc hại. Không để sót các trường hợp thai quá ngày sinh\n- Phát hiện, chẩn đoán, điều trị sớm các bệnh lý của mẹ trước và trong khi mang thai.\n- Thận trọng khi dùng thuốc cho phụ nữ có thai.\n- Khi nghi ngờ thai chết lưu: nếu ở tuyến xã phải tư vấn và chuyển ngay lên tuyến trên, nếu ở tuyến trên phải cho nhập viện và điều trị kịp thời.\nCâu hỏi:\n1:Trình bày  các nguyên nhân của thai chết lưu?\n2: Trình bày triệu chứng lâm sàng, cận lâm sàng và hướng xử trí thai dưới 20 tuần chết lưu?\n3: Trình bày triệu chứng lâm sàng,cận lâm sàng và hướng xử trí  thai trên 20 tuần chết lưu?", "priority": "Cao (Trọng tâm BSNT)"}, {"id": "SK-17", "chapter": "Chương 2. Sản bệnh", "folder": "02_San_benh", "title": "Thai ngoài tử cung", "author": "Ths. Nguyễn Trung Kiên", "word_count": 3090, "line_count": 186, "key_numbers": ["100 ml", "28 tuần", "3 tháng", "38 tuần", "4 cm", "50 mg"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["THAI NGOÀI TỬ CUNG", "Ths. Nguyễn Trung Kiên"], "bullets": []}, {"heading": "1.1. Định nghĩa", "paragraphs": ["Thai ngoài tử cung (Grossese Extra Uterine - GEU) là trường hợp trứng được thụ tinh, làm tổ và phát triển ở ngoài buồng tử cung."], "bullets": []}, {"heading": "1.2. Dịch tễ học", "paragraphs": ["Tần suất: thai ngoài tử cung chiếm 1 - 2% thai nghén. Đây là nguyên nhân gây tử vong cao nhất trong sản khoa trong 3 tháng đầu thai kỳ (4 - 10%). Tuy nhiên tỷ lệ tử vong mẹ giảm trong những năm trở lại đây do chẩn đoán sớm và điều trị sớm.", "Tỷ lệ thai ngoài tử cung tăng có liên quan với, các bệnh lây truyền qua đường tình dục, đặc biệt chlamydia trachomatis, viêm nhiễm tiểu khung, tiền sử nạo phá thai, sử dụng một số biện pháp tránh thai như đặt dụng cụ tử cung hay mẹ lớn tuổi..."], "bullets": []}, {"heading": "2. NGUYÊN NHÂN", "paragraphs": ["Gồm tất cả những nguyên nhân ngăn cản hoặc làm chậm cuộc hành trình của trứng qua vòi tử cung để vào buồng tử cung. Thường gặp là do biến dạng và thay đổi nhu động vòi tử cung:"], "bullets": ["- Viêm vòi tử cung (hay gặp nhất).", "- Các khối u trong lòng hoặc bên ngoài đè ép.", "- Dị dạng vòi tử cung, hoặc vòi tử cung bị co thắt bất thường.", "- Xơ dính do phẫu thuật đã thực hiện trước đó trên vòi tử cung, các phẫu thuật vùng bụng, hoặc hậu quả của lạc nội mạc tử cung.", "- Thuốc ngừa thai đơn thuần progestin.", "- Các kỹ thuật hỗ trợ sinh sản như kích thích rụng trứng bằng Gonadotropin, thụ tinh trong ống nghiệm...", "- Tiền sử vô sinh."]}, {"heading": "3. PHÂN LOẠI", "paragraphs": ["Thai ngoài tử cung có thể là ở vòi tử cung, buồng trứng hoặc trong ổ bụng, trong ống cổ tử cung. Thai ở buồng trứng và trong ổ bụng rất hiếm gặp.", "Nếu chửa ở vòi tử cung, phôi có thể làm tổ ở 4 vị trí khác nhau:", "Đoạn bóng: \t78%", "Đoạn eo: \t12%", "Đoạn loa: \t5%", "Đoạn kẽ:\t2%", "Hình 1. Các vị trí làm tổ của phôi"], "bullets": ["- Vòi tử cung: 95 - 96%", "- Buồng trứng: \t      3%", "- Sẹo mổ đẻ cũ:    < 1%", "- Ống cổ tử cung: < 1%", "- Ổ bụng: \t< 1%"]}, {"heading": "4.1. Vòi tử cung và tử cung", "paragraphs": [], "bullets": ["- Vòi tử cung không đảm bảo cho thai làm tổ, vì niêm mạc của vòi tử cung ít biến đổi so với niêm mạc tử cung và lớp cơ vòi tử cung rất mỏng do đó thai chỉ phát triển được một thời gian ngắn rồi những biến chứng sẽ xảy ra.", "- Tử cung do ảnh hưởng của các hormon thai nghén nên tử cung cũng phản ứng to hơn bình thường, mềm ra, niêm mạc tử cung chuyển thành ngoại sản mạc."]}, {"heading": "4.2. Sự tiến triển của thai làm tổ ở vòi tử cung", "paragraphs": ["Hình 2. Thai ngoài tử cung ở đoạn bóng vòi tử cung"], "bullets": ["- Vỡ vòi tử cung: do gai rau ăn sâu vào lớp cơ làm thủng vòi tử cung, hoặc do vòi tử cung căng to làm vỡ vòi, đồng thời các nhánh mạch máu cũng bị vỡ gây chảy máu vào ổ bụng. Mức độ chảy máu có thể khác nhau:", "+ Chảy ồ ạt, gây tràn ngập máu trong ổ bụng", "+ Chảy từ từ ít một, đọng ở vùng thấp và được khu trú lại, tạo ra khối máu tụ.", "-  Sẩy thai: vì thai làm tổ lạc chỗ nên dễ bị bong ra gây sẩy và chảy máu.", "+ Nếu máu chảy được khu trú trong vòi tử cung thì được gọi là ứ máu vòi tử cung, bọc thai còn nhỏ sẽ chết và tiêu đi.", "+ Nếu bọc thai bong dần, máu chảy ít một, đọng lại trong túi cùng Douglas hoặc ở cạnh tử cung và được ruột, mạc treo, mạc nối đến khu trú để tạo thành khối máu tụ.", "+ Nếu bọc thai sẩy, máu chảy ồ ạt  gây tràn ngập máu ổ bụng."]}, {"heading": "5.1. Thai ngoài tử cung chưa vỡ", "paragraphs": [], "bullets": ["- Triệu chứng cơ năng", "+ Tắt kinh: hay có khi chỉ chậm kinh vài ngày hoặc có rối loạn kinh nguyệt, có thể có dấu hiệu nghén, vú căng.", "+ Đau bụng: vùng hạ vị, một bên, âm ỉ.", "+ Ra huyết: huyết ra ít một, rỉ rả, màu nâu đen, có khi lẫn màng, không đông.", "- Triệu chứng thực thể", "+ Cổ tử cung hơi tím, mềm, đóng kín, có máu đen từ trong lòng tử cung ra.", "+ Tử cung lớn hơn bình thường, mềm, nhưng không tương xứng với tuổi thai.", "+ Có khối u cạnh tử cung mềm, bờ không rõ, di động, chạm đau hoặc hiếm hơn có thể sờ thấy khối u có dạng hơi dài theo chiều dài của vòi tử cung.", "- Cận lâm sàng", "+ hCG: định tính hCG chỉ gợi ý có hoạt động của tế bào nuôi giúp xác định có thai, tuy nhiên khi hCG âm tính ta cũng chưa loại trừ được thai ngoài tử cung. Định lượng nồng độ βhCG thấy nồng độ hCG thấp hơn so với thai nghén bình thường.", "+ Siêu âm: không có túi thai trong buồng tử cung, có khối âm vang hỗn hợp hoặc có hình ảnh túi thai ngoài tử cung. Có thể có hình ảnh tụ dịch ở cùng đồ sau, hoặc trong ổ bụng (tuỳ lượng dịch và máu chảy ra). Nếu siêu âm đường bụng nghi ngờ phải siêu âm đường âm đạo để kiểm tra.", "+ Soi ổ bụng: đây là phương pháp giúp xác định chẩn đoán và xử trí."]}, {"heading": "5.2. Thai ngoài tử cung vỡ tràn ngập máu ổ bụng", "paragraphs": ["A\t\t\t\t\tB", "Hình 3. A. Thai ngoài tử cung tràn ngập máu ổ bụng,   B.  Tiếng kêu Douglas", "Chọc dò túi cùng Douglas: chỉ thực hiện khi không có siêu âm hoặc nghi ngờ chẩn đoán. Hút ra máu đen loãng, không đông dễ dàng."], "bullets": ["- Choáng: do tình trạng chảy máu ồ ạt trong ổ bụng. Bệnh nhân có biểu hiện vật vã, chân tay lạnh, mạch nhanh, huyết áp hạ.", "- Triệu chứng cơ năng", "+ Có chậm kinh, tắt kinh hoặc rối loạn kinh nguyệt.", "+ Ra huyết đen, ít một.", "+ Thường có những cơn đau vùng hạ vị đột ngột, dữ dội làm bệnh nhân choáng váng hoặc ngất đi.", "- Triệu chứng thực thể", "+ Khám bụng: bụng căng, hơi chướng, có cảm ứng phúc mạc và phản ứng thành bụng khắp bụng, đặc biệt là vùng hạ vị, gõ đục ở vùng thấp.", "+ Khám âm đạo: túi cùng sau đầy, ấn vào bệnh nhân đau chói (tiếng kêu Douglas).", "+ Di động tử cung rất đau, có cảm giác tử cung bồng bềnh trong nước. Khó xác định tử cung và hai phần phụ vì bệnh nhân đau và phản ứng nên khó khám."]}, {"heading": "5.3. Khối huyết tụ thành nang", "paragraphs": [], "bullets": ["- Toàn thân", "+ Da hơi xanh hoặc hơi vàng do thiếu máu và tan máu.", "+ Toàn thân không suy sụp, nhưng mệt mỏi, gầy sút.", "- Triệu chứng cơ năng", "+ Có chậm kinh hoặc rối loạn kinh nguyệt.", "+ Ra huyết đen âm đạo ít một, dai dẳng.", "+ Có đau vùng hạ vị, có khi đau trội lên rồi giảm đi.", "+ Đau tức ở bụng dưới, kèm những dấu hiệu chèn ép như táo bón, đái khó.", "- Triệu chứng thực thể", "+ Tử cung hơi to, có khối u cạnh, trước hay sau tử cung. Đặc điểm của khối u là mật độ chắc, bờ không rõ, không di động, ấn rất rất tức, đôi khi khối u dính với tử cung thành một khối khó xác định vị trí và thể tích tử cung.", "- Cận lâm sàng", "+ hCG có thể âm tính, chứng tỏ thai đã chết.", "+ Chọc dò qua túi cùng Douglas vào khối u bằng kim to có thể thấy máu đen, lẫn máu cục.", "+ Siêu âm: có khối cạnh TC, âm vang không đồng nhất, ranh giới không rõ ràng."]}, {"heading": "5.4. Thai trong ổ bụng", "paragraphs": [], "bullets": ["- Tiền sử đã có triệu chứng như doạ sẩy trong những tháng đầu thai kỳ.", "- Triệu chứng cơ năng", "+ Đau bụng, đau tăng khi có cử động thai.", "+ Có thể có hiện tượng bán tắc ruột: nôn, buồn nôn, bí trung đại tiện.", "+ Ra  huyết, lượng ít (ở 70% trường hợp).", "- Thực thể", "+ Cảm giác thai ở nông ngay dưới da bụng, không có cơn co tử cung.", "+ Khám âm đạo: kích thước tử cung bình thường, tách biệt với khối thai. Ngôi thai bất thường trong 50 - 60% các trường hợp.", "- Cận lâm sàng", "+ Siêu âm: thai nằm ngoài tử cung, xen kẽ giữa các quai ruột non, thường bị suy dinh dưỡng, có các kích thước nhỏ hơn tuổi thai, bờ khối thai không đều, mặt rau không phẳng, nước ối thường ít, hình ảnh mạc nối, ruột, tử cung, rau tạo thành một vỏ dày khó phân biệt với cơ tử cung.", "+ X quang bụng không chuẩn bị: không có bóng mờ của tử cung bao quanh thai, bóng hơi của ruột nằm chồng lên các phần thai, trên phim chụp nghiêng thấy các phần thai nằm vắt qua cột sống lưng của mẹ."]}, {"heading": "5.5. Chẩn đoán phân biệt", "paragraphs": ["Tử cung to, mềm, tương đương với tuổi thai, cạnh tử cung không thấy khối gì đặc biệt.", "Cổ tử cung hé mở, có thể thấy ra máu đỏ tươi ở lỗ ngoài cổ tử cung, nếu đang sẩy thì ra máu nhiều.", "Siêu âm có túi thai trong buồng tử cung, có hiện tượng bong màng nuôi.", "Nếu cần hút buồng tử cung sẽ thấy rau thai trong buồng tử cung. Xét nghiệm giải phẫu bệnh có ngoại sản mạc và gai rau.", "Bệnh nhân có dấu hiệu nghén sau đó hết nghén. Vú tiết sữa non. Tử cung nhỏ hơn so với tuổi thai, có túi thai trong buồng tử cung. β HCG giảm thấp", "Bệnh nhân thường có dấu hiệu nghén nặng, Tử cung to hơn tuổi thai, rất mềm. Siêu âm trong buồng tử cung có hình ảnh ruột bánh mì, có thể thấy túi thai trong buồng tử cung (thể chửa trứng bán phần), β HCG tăng rất cao > 10.000 mUI/ml", "Bệnh nhân không có triệu chứng tắt kinh, nghén.Bệnh nhân có hội chứng nhiễm trùng, đau bụng vùng hố chậu,", "Khám thấy tử cung không to, khối nề cạnh tử cung không rõ ranh giới. Thường viêm cả hai bên.", "Siêu âm có thể thấy khối không rõ ranh giới, Douglas không có dịch. Công thức máu: bạch cầu đa nhân trung tính tăng. β HCG < 5 mUI/ml.", "Cho kháng sinh, các triệu chứng giảm xuống rõ.", "Bệnh nhân có hội chứng nhiễm trùng rõ, có rối loạn tiêu hóa rõ: kém ăn, nôn hoặc buồn nôn, bí trung, đại tiện, thường đau khu trú vùng hố chậu phải", "Không có triệu chứng tắt kinh, nghén.", "Khám có phản ứng thành bụng vùng hố chậu phải, Mac Burney (+).", "β HCG < 5 mUI/ml, Công thức máu: số lượng bạch cầu tăng, bạch cầu đa nhân trung tính tăng.", "Không có triệu chứng tắt kinh, nghén.", "Bệnh nhân có đau bụng dữ dội vùng hố chậu, hội chứng nhiễm trùng, nhiễm độc. Khám thấy vùng cạnh tử cung cố khối căng, di động biệt lập với tử cung, ấn đau chói.", "Siêu âm: cạnh tử cung có khối ranh giới rõ, trong lòng khối có vách, có thể có dịch Douglas. β HCG < 5 mUI/ml", "Bệnh nhân có đau bụng vùng thắt lưng dữ dội.", "Có triệu chứng về tiết niệu: đái buốt, đái khó, đôi khi đái máu.", "Siêu âm và chụp hệ tiết niệu có chuẩn bị (chụp UIV) để chẩn đoán phân biệt."], "bullets": ["- Sẩy thai:", "- Thai lưu:", "- Chửa trứng:", "- Viêm phần phụ.", "- Vỡ nang De Graaf (khó phân biệt và hiếm).", "- Viêm ruột thừa.", "- Khối u buồng trứng xoắn.", "- Cơn đau của sỏi niệu quản.", "- Khối u lạc nội mạc tử cung (chẩn đoán phân biệt với thể huyết tụ thành nang).", "- Khối u đường tiêu hoá (chẩn đoán phân biệt với thể chửa trong ổ bụng)."]}, {"heading": "6. XỬ TRÍ", "paragraphs": ["Thai ngoài tử cung là một cấp cứu cần được phát hiện sớm và chuyển tuyến để được điều trị sớm ở cơ sở có khả năng phẫu thuật."], "bullets": []}, {"heading": "6.1.1. Điều trị nội khoa", "paragraphs": ["Điều kiện:", "Thuốc sử dụng: Methotrexate (MTX - Acide amino-4 méthyl-10 folique) là một loại hoá chất chống tăng sinh tế bào của nhóm antifolic thường được sử dụng nhất. Những loại thuốc khác đã được nghiên cứu sử dụng nhưng ít hiệu quả hơn rất nhiều.", "Liều dùng: MTX 50 mg/m2 da cơ thể tiêm bắp và có thể lặp lại liều."], "bullets": ["- Khối thai ngoài tử cung chưa vỡ", "- Lượng dịch trong ổ bụng dưới 100 ml", "- Đường kính khối thai dưới 4 cm.", "- Chưa thấy tim thai trên siêu âm.", "- Nồng độ βhCG không vượt quá 5000 mIU/ml", "- Bệnh nhân không có chống chỉ định với Methotrexate"]}, {"heading": "6.1.2. Phẫu thuật", "paragraphs": [], "bullets": ["- Điều trị tận gốc: cắt bỏ vòi tử cung đến sát góc tử cung và giữ lại buồng trứng, lau sạch ổ bụng, nếu sản phụ đã đẻ nhiều lần và/ hoặc sản phụ có tiền sử thai ngoài tử cung nhiều lần (và không mong muốn sinh thêm con) thì triệt sản luôn vòi tử cung bên đối diện, đóng bụng, không cần dẫn lưu.", "- Điều trị bảo tồn: chỉ đặt ra với những bệnh nhân còn trẻ, chưa có con, tình trạng vòi tử cung bên kia bất thường và tổn thương vòi tử cung cho phép. Xẻ vòi tử cung, hút hoặc lấy bọc thai ra và cầm máu.", "- Phẫu thuật nội soi: ngày nay người ta thường chỉ định và ứng dụng kỹ thuật mổ nội soi trong những trường hợp thai ngoài tử cung thể đơn giản và chưa có biến chứng."]}, {"heading": "6.2. Thai ngoài tử cung tràn ngập máu ổ bụng", "paragraphs": [], "bullets": ["- Phải hồi sức chống choáng và mời chi viện kỹ thuật huy động kíp cấp cứu mổ tại chỗ.", "- Mổ ngay không trì hoãn, mổ càng sớm càng tốt, vừa mổ vừa hồi sức tích cực bằng truyền máu, truyền dịch, nếu có thể nên truyền máu hoàn hồi."]}, {"heading": "6.3. Thai ngoài tử cung thể huyết tụ thành nang", "paragraphs": [], "bullets": ["- Nếu phát hiện được hoặc nghi ngờ cần phải tư vấn và gửi đi bệnh viện sớm vì có thể có hai biến chứng xảy ra: vỡ gây chảy máu lại trong ổ bụng với bệnh cảnh giống như chửa ngoài tử cung vỡ và nhiễm khuẩn.", "- Tuyến có cơ sở phẫu thuật: chẩn đoán xác định và mổ để tránh vỡ thứ phát và nhiễm khuẩn trong ổ máu tụ. Bệnh nhân phải được chuẩn bị tốt trước khi mổ."]}, {"heading": "6.4. Thai trong ổ bụng (thai phát triển trong ổ bụng)", "paragraphs": ["Hình 4.  Thai ngoài tử cung trong ổ bụng"], "bullets": ["- Nếu thai chết, phải mổ lấy thai sớm, tránh biến chứng rối loạn đông máu cho mẹ.", "- Nếu thai còn sống :", "+ Dưới 28 tuần: mổ ngay để lấy thai ra ngay.", "+ Sau 28 tuần: có thể chờ đợi và mổ khi thai khoảng 36-38 tuần, sản phụ phải được nhập viện và theo dõi nghiêm ngặt. Trong lúc mổ nếu rau bám chặt vào các cơ quan trong ổ bụng thì để bánh rau lại không bóc, không nên gắng bóc hết rau ra vì có thể gây chảy máu rất nhiều. Phần rau còn lại  có thể sẽ tự huỷ hoặc có thể thúc đẩy quá trình tự huỷ của rau thai bằng Méthotrexate."]}, {"heading": "7. TIÊN LƯỢNG", "paragraphs": [], "bullets": ["- Nếu chẩn đoán sớm và xử trí lúc thai ngoài tử cung chưa vỡ, tiên lượng thường tốt.", "- Nếu chẩn đoán muộn, xử trí không kịp thời, tỷ lệ tử vong 1-1,5%.", "- Khoảng 30% các trường hợp có thể có thai lại bình thường sau đó.", "- Tỷ lệ tái phát thai ngoài tử cung ở các lần có thai sau khoảng 10%."]}, {"heading": "8. PHÒNG BỆNH", "paragraphs": ["Để giảm tỷ lệ thai ngoài tử cung, tư vấn cho chị em giữ vệ sinh phụ nữ tốt (vệ sinh hàng ngày, vệ sinh kinh nguyệt, vệ sinh khi giao hợp, khi sẩy, đẻ).", "Hạn chế các trường hợp phải phá thai, phòng ngừa viêm nhiễm sinh dục, nhất là các bệnh lây truyền qua đường tình dục là yếu tố nguy cơ hàng đầu của thai ngoài tử cung.", "Vận động chị em đi khám phụ khoa định kỳ hoặc có triệu chứng bất thường phải đi khám phụ khoa ngay để phát hiện sớm các bệnh viêm nhiễm đường sinh dục và phải điều trị  tích cực.", "Vận động chị em khi có thai nên đi khám sớm ngay những ngày đầu chậm kinh để có thể kịp thời phát hiện các tai biến sớm của thai nghén, trong đó có thai ngoài tử cung để có thể xử trí kịp thời làm giảm nguy cơ tử vong mẹ và biến chứng."], "bullets": []}], "raw_text": "THAI NGOÀI TỬ CUNG\nThs. Nguyễn Trung Kiên\n\nMục tiêu học tập\n1. Kể ra được các nguyên nhân của thai ngoài tử cung\n2. Trình bày được triệu chứng, chẩn đoán, các hình thái lâm sàng của thai ngoài tử cung\n3. Trình bày được cách xử trí cho từng hình thái lâm sàng của thai ngoài tử cung\n1.  ĐẠI CƯƠNG\n1.1. Định nghĩa\nThai ngoài tử cung (Grossese Extra Uterine - GEU) là trường hợp trứng được thụ tinh, làm tổ và phát triển ở ngoài buồng tử cung.\n1.2. Dịch tễ học\nTần suất: thai ngoài tử cung chiếm 1 - 2% thai nghén. Đây là nguyên nhân gây tử vong cao nhất trong sản khoa trong 3 tháng đầu thai kỳ (4 - 10%). Tuy nhiên tỷ lệ tử vong mẹ giảm trong những năm trở lại đây do chẩn đoán sớm và điều trị sớm.\nTỷ lệ thai ngoài tử cung tăng có liên quan với, các bệnh lây truyền qua đường tình dục, đặc biệt chlamydia trachomatis, viêm nhiễm tiểu khung, tiền sử nạo phá thai, sử dụng một số biện pháp tránh thai như đặt dụng cụ tử cung hay mẹ lớn tuổi...\n2. NGUYÊN NHÂN\nGồm tất cả những nguyên nhân ngăn cản hoặc làm chậm cuộc hành trình của trứng qua vòi tử cung để vào buồng tử cung. Thường gặp là do biến dạng và thay đổi nhu động vòi tử cung:\n- Viêm vòi tử cung (hay gặp nhất).\n- Các khối u trong lòng hoặc bên ngoài đè ép.\n- Dị dạng vòi tử cung, hoặc vòi tử cung bị co thắt bất thường.\n- Xơ dính do phẫu thuật đã thực hiện trước đó trên vòi tử cung, các phẫu thuật vùng bụng, hoặc hậu quả của lạc nội mạc tử cung.\n- Thuốc ngừa thai đơn thuần progestin.\n- Các kỹ thuật hỗ trợ sinh sản như kích thích rụng trứng bằng Gonadotropin, thụ tinh trong ống nghiệm...\n- Tiền sử vô sinh.\n3. PHÂN LOẠI\nThai ngoài tử cung có thể là ở vòi tử cung, buồng trứng hoặc trong ổ bụng, trong ống cổ tử cung. Thai ở buồng trứng và trong ổ bụng rất hiếm gặp.\n- Vòi tử cung: 95 - 96%\n- Buồng trứng: \t      3%\n- Sẹo mổ đẻ cũ:    < 1%\n- Ống cổ tử cung: < 1%\n- Ổ bụng: \t< 1%\nNếu chửa ở vòi tử cung, phôi có thể làm tổ ở 4 vị trí khác nhau:\nĐoạn bóng: \t78%\nĐoạn eo: \t12%\n\nĐoạn loa: \t5%\nĐoạn kẽ:\t2%\n\n\nHình 1. Các vị trí làm tổ của phôi\n4. GIẢI PHẪU BỆNH - SINH LÝ BỆNH\n4.1. Vòi tử cung và tử cung\n- Vòi tử cung không đảm bảo cho thai làm tổ, vì niêm mạc của vòi tử cung ít biến đổi so với niêm mạc tử cung và lớp cơ vòi tử cung rất mỏng do đó thai chỉ phát triển được một thời gian ngắn rồi những biến chứng sẽ xảy ra.\n- Tử cung do ảnh hưởng của các hormon thai nghén nên tử cung cũng phản ứng to hơn bình thường, mềm ra, niêm mạc tử cung chuyển thành ngoại sản mạc.\n4.2. Sự tiến triển của thai làm tổ ở vòi tử cung\n- Vỡ vòi tử cung: do gai rau ăn sâu vào lớp cơ làm thủng vòi tử cung, hoặc do vòi tử cung căng to làm vỡ vòi, đồng thời các nhánh mạch máu cũng bị vỡ gây chảy máu vào ổ bụng. Mức độ chảy máu có thể khác nhau:\n+ Chảy ồ ạt, gây tràn ngập máu trong ổ bụng\n+ Chảy từ từ ít một, đọng ở vùng thấp và được khu trú lại, tạo ra khối máu tụ.\n-  Sẩy thai: vì thai làm tổ lạc chỗ nên dễ bị bong ra gây sẩy và chảy máu.\n+ Nếu máu chảy được khu trú trong vòi tử cung thì được gọi là ứ máu vòi tử cung, bọc thai còn nhỏ sẽ chết và tiêu đi.\n+ Nếu bọc thai bong dần, máu chảy ít một, đọng lại trong túi cùng Douglas hoặc ở cạnh tử cung và được ruột, mạc treo, mạc nối đến khu trú để tạo thành khối máu tụ.\n+ Nếu bọc thai sẩy, máu chảy ồ ạt  gây tràn ngập máu ổ bụng.\n\n\n\nHình 2. Thai ngoài tử cung ở đoạn bóng vòi tử cung\n5. LÂM SÀNG\n5.1. Thai ngoài tử cung chưa vỡ\n- Triệu chứng cơ năng\n+ Tắt kinh: hay có khi chỉ chậm kinh vài ngày hoặc có rối loạn kinh nguyệt, có thể có dấu hiệu nghén, vú căng.\n+ Đau bụng: vùng hạ vị, một bên, âm ỉ.\n+ Ra huyết: huyết ra ít một, rỉ rả, màu nâu đen, có khi lẫn màng, không đông.\n- Triệu chứng thực thể\n+ Cổ tử cung hơi tím, mềm, đóng kín, có máu đen từ trong lòng tử cung ra.\n+ Tử cung lớn hơn bình thường, mềm, nhưng không tương xứng với tuổi thai.\n+ Có khối u cạnh tử cung mềm, bờ không rõ, di động, chạm đau hoặc hiếm hơn có thể sờ thấy khối u có dạng hơi dài theo chiều dài của vòi tử cung.\n- Cận lâm sàng\n+ hCG: định tính hCG chỉ gợi ý có hoạt động của tế bào nuôi giúp xác định có thai, tuy nhiên khi hCG âm tính ta cũng chưa loại trừ được thai ngoài tử cung. Định lượng nồng độ βhCG thấy nồng độ hCG thấp hơn so với thai nghén bình thường.\n+ Siêu âm: không có túi thai trong buồng tử cung, có khối âm vang hỗn hợp hoặc có hình ảnh túi thai ngoài tử cung. Có thể có hình ảnh tụ dịch ở cùng đồ sau, hoặc trong ổ bụng (tuỳ lượng dịch và máu chảy ra). Nếu siêu âm đường bụng nghi ngờ phải siêu âm đường âm đạo để kiểm tra.\n+ Soi ổ bụng: đây là phương pháp giúp xác định chẩn đoán và xử trí.\n5.2. Thai ngoài tử cung vỡ tràn ngập máu ổ bụng\n- Choáng: do tình trạng chảy máu ồ ạt trong ổ bụng. Bệnh nhân có biểu hiện vật vã, chân tay lạnh, mạch nhanh, huyết áp hạ.\n- Triệu chứng cơ năng\n+ Có chậm kinh, tắt kinh hoặc rối loạn kinh nguyệt.\n+ Ra huyết đen, ít một.\n+ Thường có những cơn đau vùng hạ vị đột ngột, dữ dội làm bệnh nhân choáng váng hoặc ngất đi.\n- Triệu chứng thực thể\n+ Khám bụng: bụng căng, hơi chướng, có cảm ứng phúc mạc và phản ứng thành bụng khắp bụng, đặc biệt là vùng hạ vị, gõ đục ở vùng thấp.\n+ Khám âm đạo: túi cùng sau đầy, ấn vào bệnh nhân đau chói (tiếng kêu Douglas).\n+ Di động tử cung rất đau, có cảm giác tử cung bồng bềnh trong nước. Khó xác định tử cung và hai phần phụ vì bệnh nhân đau và phản ứng nên khó khám.\n\nA\t\t\t\t\tB\nHình 3. A. Thai ngoài tử cung tràn ngập máu ổ bụng,   B.  Tiếng kêu Douglas\nChọc dò túi cùng Douglas: chỉ thực hiện khi không có siêu âm hoặc nghi ngờ chẩn đoán. Hút ra máu đen loãng, không đông dễ dàng.\n5.3. Khối huyết tụ thành nang\n- Toàn thân\n+ Da hơi xanh hoặc hơi vàng do thiếu máu và tan máu.\n+ Toàn thân không suy sụp, nhưng mệt mỏi, gầy sút.\n- Triệu chứng cơ năng\n+ Có chậm kinh hoặc rối loạn kinh nguyệt.\n+ Ra huyết đen âm đạo ít một, dai dẳng.\n+ Có đau vùng hạ vị, có khi đau trội lên rồi giảm đi.\n+ Đau tức ở bụng dưới, kèm những dấu hiệu chèn ép như táo bón, đái khó.\n- Triệu chứng thực thể\n+ Tử cung hơi to, có khối u cạnh, trước hay sau tử cung. Đặc điểm của khối u là mật độ chắc, bờ không rõ, không di động, ấn rất rất tức, đôi khi khối u dính với tử cung thành một khối khó xác định vị trí và thể tích tử cung.\n- Cận lâm sàng\n+ hCG có thể âm tính, chứng tỏ thai đã chết.\n+ Chọc dò qua túi cùng Douglas vào khối u bằng kim to có thể thấy máu đen, lẫn máu cục.\n+ Siêu âm: có khối cạnh TC, âm vang không đồng nhất, ranh giới không rõ ràng.\n5.4. Thai trong ổ bụng\n- Tiền sử đã có triệu chứng như doạ sẩy trong những tháng đầu thai kỳ.\n- Triệu chứng cơ năng\n+ Đau bụng, đau tăng khi có cử động thai.\n+ Có thể có hiện tượng bán tắc ruột: nôn, buồn nôn, bí trung đại tiện.\n+ Ra  huyết, lượng ít (ở 70% trường hợp).\n- Thực thể\n+ Cảm giác thai ở nông ngay dưới da bụng, không có cơn co tử cung.\n+ Khám âm đạo: kích thước tử cung bình thường, tách biệt với khối thai. Ngôi thai bất thường trong 50 - 60% các trường hợp.\n- Cận lâm sàng\n+ Siêu âm: thai nằm ngoài tử cung, xen kẽ giữa các quai ruột non, thường bị suy dinh dưỡng, có các kích thước nhỏ hơn tuổi thai, bờ khối thai không đều, mặt rau không phẳng, nước ối thường ít, hình ảnh mạc nối, ruột, tử cung, rau tạo thành một vỏ dày khó phân biệt với cơ tử cung.\n+ X quang bụng không chuẩn bị: không có bóng mờ của tử cung bao quanh thai, bóng hơi của ruột nằm chồng lên các phần thai, trên phim chụp nghiêng thấy các phần thai nằm vắt qua cột sống lưng của mẹ.\n5.5. Chẩn đoán phân biệt\n- Sẩy thai:\nTử cung to, mềm, tương đương với tuổi thai, cạnh tử cung không thấy khối gì đặc biệt.\nCổ tử cung hé mở, có thể thấy ra máu đỏ tươi ở lỗ ngoài cổ tử cung, nếu đang sẩy thì ra máu nhiều.\nSiêu âm có túi thai trong buồng tử cung, có hiện tượng bong màng nuôi.\nNếu cần hút buồng tử cung sẽ thấy rau thai trong buồng tử cung. Xét nghiệm giải phẫu bệnh có ngoại sản mạc và gai rau.\n- Thai lưu:\nBệnh nhân có dấu hiệu nghén sau đó hết nghén. Vú tiết sữa non. Tử cung nhỏ hơn so với tuổi thai, có túi thai trong buồng tử cung. β HCG giảm thấp\n- Chửa trứng:\nBệnh nhân thường có dấu hiệu nghén nặng, Tử cung to hơn tuổi thai, rất mềm. Siêu âm trong buồng tử cung có hình ảnh ruột bánh mì, có thể thấy túi thai trong buồng tử cung (thể chửa trứng bán phần), β HCG tăng rất cao > 10.000 mUI/ml\n- Viêm phần phụ.\nBệnh nhân không có triệu chứng tắt kinh, nghén.Bệnh nhân có hội chứng nhiễm trùng, đau bụng vùng hố chậu,\nKhám thấy tử cung không to, khối nề cạnh tử cung không rõ ranh giới. Thường viêm cả hai bên.\nSiêu âm có thể thấy khối không rõ ranh giới, Douglas không có dịch. Công thức máu: bạch cầu đa nhân trung tính tăng. β HCG < 5 mUI/ml.\nCho kháng sinh, các triệu chứng giảm xuống rõ.\n- Vỡ nang De Graaf (khó phân biệt và hiếm).\n- Viêm ruột thừa.\nBệnh nhân có hội chứng nhiễm trùng rõ, có rối loạn tiêu hóa rõ: kém ăn, nôn hoặc buồn nôn, bí trung, đại tiện, thường đau khu trú vùng hố chậu phải\nKhông có triệu chứng tắt kinh, nghén.\nKhám có phản ứng thành bụng vùng hố chậu phải, Mac Burney (+).\nβ HCG < 5 mUI/ml, Công thức máu: số lượng bạch cầu tăng, bạch cầu đa nhân trung tính tăng.\n- Khối u buồng trứng xoắn.\nKhông có triệu chứng tắt kinh, nghén.\nBệnh nhân có đau bụng dữ dội vùng hố chậu, hội chứng nhiễm trùng, nhiễm độc. Khám thấy vùng cạnh tử cung cố khối căng, di động biệt lập với tử cung, ấn đau chói.\nSiêu âm: cạnh tử cung có khối ranh giới rõ, trong lòng khối có vách, có thể có dịch Douglas. β HCG < 5 mUI/ml\n- Cơn đau của sỏi niệu quản.\nBệnh nhân có đau bụng vùng thắt lưng dữ dội.\nCó triệu chứng về tiết niệu: đái buốt, đái khó, đôi khi đái máu.\nSiêu âm và chụp hệ tiết niệu có chuẩn bị (chụp UIV) để chẩn đoán phân biệt.\n- Khối u lạc nội mạc tử cung (chẩn đoán phân biệt với thể huyết tụ thành nang).\n- Khối u đường tiêu hoá (chẩn đoán phân biệt với thể chửa trong ổ bụng).\n6. XỬ TRÍ\nThai ngoài tử cung là một cấp cứu cần được phát hiện sớm và chuyển tuyến để được điều trị sớm ở cơ sở có khả năng phẫu thuật.\n6.1. Thai ngoài tử cung chưa có biến chứng chảy máu trong ổ bụng\n6.1.1. Điều trị nội khoa\nĐiều kiện:\n- Khối thai ngoài tử cung chưa vỡ\n- Lượng dịch trong ổ bụng dưới 100 ml\n- Đường kính khối thai dưới 4 cm.\n- Chưa thấy tim thai trên siêu âm.\n- Nồng độ βhCG không vượt quá 5000 mIU/ml\n- Bệnh nhân không có chống chỉ định với Methotrexate\nThuốc sử dụng: Methotrexate (MTX - Acide amino-4 méthyl-10 folique) là một loại hoá chất chống tăng sinh tế bào của nhóm antifolic thường được sử dụng nhất. Những loại thuốc khác đã được nghiên cứu sử dụng nhưng ít hiệu quả hơn rất nhiều.\nLiều dùng: MTX 50 mg/m2 da cơ thể tiêm bắp và có thể lặp lại liều.\n6.1.2. Phẫu thuật\n- Điều trị tận gốc: cắt bỏ vòi tử cung đến sát góc tử cung và giữ lại buồng trứng, lau sạch ổ bụng, nếu sản phụ đã đẻ nhiều lần và/ hoặc sản phụ có tiền sử thai ngoài tử cung nhiều lần (và không mong muốn sinh thêm con) thì triệt sản luôn vòi tử cung bên đối diện, đóng bụng, không cần dẫn lưu.\n- Điều trị bảo tồn: chỉ đặt ra với những bệnh nhân còn trẻ, chưa có con, tình trạng vòi tử cung bên kia bất thường và tổn thương vòi tử cung cho phép. Xẻ vòi tử cung, hút hoặc lấy bọc thai ra và cầm máu.\n- Phẫu thuật nội soi: ngày nay người ta thường chỉ định và ứng dụng kỹ thuật mổ nội soi trong những trường hợp thai ngoài tử cung thể đơn giản và chưa có biến chứng.\n6.2. Thai ngoài tử cung tràn ngập máu ổ bụng\n- Phải hồi sức chống choáng và mời chi viện kỹ thuật huy động kíp cấp cứu mổ tại chỗ.\n- Mổ ngay không trì hoãn, mổ càng sớm càng tốt, vừa mổ vừa hồi sức tích cực bằng truyền máu, truyền dịch, nếu có thể nên truyền máu hoàn hồi.\n6.3. Thai ngoài tử cung thể huyết tụ thành nang\n- Nếu phát hiện được hoặc nghi ngờ cần phải tư vấn và gửi đi bệnh viện sớm vì có thể có hai biến chứng xảy ra: vỡ gây chảy máu lại trong ổ bụng với bệnh cảnh giống như chửa ngoài tử cung vỡ và nhiễm khuẩn.\n- Tuyến có cơ sở phẫu thuật: chẩn đoán xác định và mổ để tránh vỡ thứ phát và nhiễm khuẩn trong ổ máu tụ. Bệnh nhân phải được chuẩn bị tốt trước khi mổ.\n6.4. Thai trong ổ bụng (thai phát triển trong ổ bụng)\n\nHình 4.  Thai ngoài tử cung trong ổ bụng\n- Nếu thai chết, phải mổ lấy thai sớm, tránh biến chứng rối loạn đông máu cho mẹ.\n- Nếu thai còn sống :\n+ Dưới 28 tuần: mổ ngay để lấy thai ra ngay.\n+ Sau 28 tuần: có thể chờ đợi và mổ khi thai khoảng 36-38 tuần, sản phụ phải được nhập viện và theo dõi nghiêm ngặt. Trong lúc mổ nếu rau bám chặt vào các cơ quan trong ổ bụng thì để bánh rau lại không bóc, không nên gắng bóc hết rau ra vì có thể gây chảy máu rất nhiều. Phần rau còn lại  có thể sẽ tự huỷ hoặc có thể thúc đẩy quá trình tự huỷ của rau thai bằng Méthotrexate.\n7. TIÊN LƯỢNG\n- Nếu chẩn đoán sớm và xử trí lúc thai ngoài tử cung chưa vỡ, tiên lượng thường tốt.\n- Nếu chẩn đoán muộn, xử trí không kịp thời, tỷ lệ tử vong 1-1,5%.\n- Khoảng 30% các trường hợp có thể có thai lại bình thường sau đó.\n- Tỷ lệ tái phát thai ngoài tử cung ở các lần có thai sau khoảng 10%.\n\n8. PHÒNG BỆNH\nĐể giảm tỷ lệ thai ngoài tử cung, tư vấn cho chị em giữ vệ sinh phụ nữ tốt (vệ sinh hàng ngày, vệ sinh kinh nguyệt, vệ sinh khi giao hợp, khi sẩy, đẻ).\nHạn chế các trường hợp phải phá thai, phòng ngừa viêm nhiễm sinh dục, nhất là các bệnh lây truyền qua đường tình dục là yếu tố nguy cơ hàng đầu của thai ngoài tử cung.\nVận động chị em đi khám phụ khoa định kỳ hoặc có triệu chứng bất thường phải đi khám phụ khoa ngay để phát hiện sớm các bệnh viêm nhiễm đường sinh dục và phải điều trị  tích cực.\nVận động chị em khi có thai nên đi khám sớm ngay những ngày đầu chậm kinh để có thể kịp thời phát hiện các tai biến sớm của thai nghén, trong đó có thai ngoài tử cung để có thể xử trí kịp thời làm giảm nguy cơ tử vong mẹ và biến chứng.\nCâu hỏi:\n1. Trình bày triệu chứng lâm sàng, cận lâm sàng của chửa ngoài tử cung chưa vỡ và hướng xử trí?\n2. Trình bày triệu chứng lâm sàng, cận lâm sàng của chửa ngoài tử cung vỡ và hướng xử trí?\n3. Trình bày triệu chứng lâm sàng, cận lâm sàng và hướng xử trícủa chửa ngoài tử cung thể huyết tụ?\n4. Trình bày triệu chứng lâm sàng, cận lâm sàng và hướng xử trí của chửa trong ổ bụng?", "priority": "Cao (Trọng tâm BSNT)"}, {"id": "SK-18", "chapter": "Chương 2. Sản bệnh", "folder": "02_San_benh", "title": "Chửa trứng", "author": "Ths. BSCK II. Lê Hải Dương, Ths. Phạm Thị Quỳnh Như", "word_count": 2095, "line_count": 141, "key_numbers": ["12 tuần", "14 tuần", "18 tháng", "20 tuần", "3 ngày", "3 tháng", "3mm", "6 ngày", "8 ngày", "8 tuần"], "key_drugs": ["Glucose", "Oxytocin", "oxytocin"], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["CHỬA TRỨNG", "Ths.iMục tiêu học tập"], "bullets": []}, {"heading": "1. ĐẠI CƯƠNG", "paragraphs": ["Chửa trứng là bệnh của tế bào nuôi, do sự tăng sinh của các hợp bào và lớp trong lá nuôi của gai rau, tạo thành những túi chứa chất dịch, dính vào nhau như chùm nho.", "Chửa trứng là một bệnh bắt nguồn từ thai nghén. Trong phần lớn các trường hợp, chửa trứng là một dạng lành tính của nguyên bào nuôi do thai nghén. Tuy nhiên, chửa trứng có thể dẫn đến các biến chứng như nhiễm độc, nhiễm trùng, xuất huyết và ung thư nguyên bào nuôi (Choriocarcinoma)."], "bullets": []}, {"heading": "2. TỶ LỆ", "paragraphs": ["Tỷ lệ chửa trứng thay đổi tùy từng vùng, châu Á hay gặp hơn châu Âu. Ở Nhật Bản (1960-1990): 4,9-1,9/1000, Hàn Quốc (1960-1990): 4,4-2,3/1000, Châu Âu, Bắc Mỹ 0,6 – 1,1/1000 thai kỳ và Việt Nam là 2 % thai kỳ."], "bullets": []}, {"heading": "3.1. Điều kiện sống", "paragraphs": ["Ăn thiếu carotene, Vitamin A: nguy cơ chửa trứng toàn phần"], "bullets": []}, {"heading": "3.2. Tuổi", "paragraphs": ["So với phụ nữ 21 đến 35 tuổi, người mẹ > 35 tuổi và < 21 tuổi có nguy cơ thai trứng gấp 1,9 lần. Nếu mẹ trên 40 tuổi thì nguy cơ gấp 7,5 lần."], "bullets": []}, {"heading": "3.3. Bất thường nhiễm sắc thể", "paragraphs": ["Hình 1. Cơ chế tạo thành chửa trứng"], "bullets": ["- Chửa trứng toàn phần: chửa trứng toàn phần thường có nhiễm sắc đồ là 46XX và có nguồn gốc từ bố, đó là sự thụ tinh của một noãn không có nhân hoặc nhân không hoạt động với một tinh trùng đơn bội, sau đó nhân đôi để tạo thành 46 nhiễm sắc thể. Có khoảng 4-6% chửa trứng toàn phần có 46 nhiễm sắc thể với giới tính XY.", "- Chửa trứng bán phần: Có cả thai nhi và rau thai. 90% đến 93% chửa trứng bán phần có tam bội thể. Do hai tinh trùng thụ tinh với một tế bào noãn bình thường nên bộ nhiễm sắc thể sẽ là 69 XXY, XXX hay XYY. Vì vậy thai nhi hiện diện trong chửa trứng bán phần mang đặc điểm nhiều dị dạng của tam bội như não úng thủy, dính ngón, chậm phát triển…Khả năng ác tính của chửa trứng bán phần thấp hơn chửa trứng toàn phần."]}, {"heading": "4.1. Đại thể", "paragraphs": ["Có 2 loại thai trứng:", "Chửa trứng toàn phần: toàn bộ gai rau đều thoái hóa, ứ nước thành các túi trứng.", "Chửa trứng bán phần: bên cạnh các túi trứng còn có mô rau thai bình thường, hoặc có cả phôi, thai nhi (thường chết trong giai đoạn 3 tháng đầu).", "Đường kính túi trứng từ 1-3mm. Các túi trứng dính vào nhau như những bọc trứng ếch hoặc chùm nho", "Hình 2. Bệnh phẩm đại thể chửa trứng toàn phần và bán phần."], "bullets": []}, {"heading": "4.2. Vi thể", "paragraphs": ["Các túi trứng thể tích lớn hơn gai rau rất nhiều, lớp nguyên bào nuôi bọc ngoài bị căng mỏng, trục liên kết động-tĩnh mạch bị thoái hoá không còn mạch máu. Tổ chức liên kết thưa thớt và chỉ chứa một chất dịch trong như nước."], "bullets": []}, {"heading": "5.1.1. Triệu chứng cơ năng", "paragraphs": [], "bullets": ["- Bệnh nhân có hiện tượng mất kinh.", "- Rong huyết chiếm trên 90% trường hợp chửa trứng. Máu ra ở âm đạo tự nhiên, máu sẫm đen hoặc đỏ loãng, ra kéo dài.", "- Nghén nặng: gặp trong 25-30% các trường hợp, biểu hiện nôn nhiều, đôi khi phù.", "- Bụng to nhanh.", "- Không thấy thai máy."]}, {"heading": "5.1.2. Triệu chứng thực thể", "paragraphs": ["Toàn thân: mệt mỏi. Ngày nay nhờ phát hiện sớm chửa trứng trong 3 tháng đầu thai kỳ nên triệu chứng thiếu máu chỉ khoảng 5%.", "Cường giáp chiếm khoảng 7%. Bệnh nhân có nhịp tim nhanh, da ẩm, tay run, xét nghiệm T3,T4 tăng. Nếu cường giáp nên cho thuốc chẹn β-adrenergic trước khi hút nạo. Cơn bão giáp có thể xảy ra với tăng thân nhiệt, mê sảng, co giật, nhịp tim nhanh, tăng cung lượng tim.", "Tiền sản giật chiếm tỷ lệ khoảng 27%. Tiền sản giật xuất hiện ở bệnh nhân có tử cung to hơn tuổi thai và hCG tăng cao, nên nghĩ đến chửa trứng khi tiền sản giật xuất hiện sớm.", "Tử cung mềm, bề cao tử cung lớn hơn tuổi thai do chứa máu và mô trứng là dấu hiệu điển hình chiếm 50% (trừ trường hợp chửa trứng thoái triển).", "Không sờ được phần thai và không nghe được tim thai.", "Nang hoàng tuyến xuất hiện trong 25-50%, do hCG tăng cao gây kích thích buồng trứng. Nang thường gặp cả 2 bên và trở về bình thường sau 8 tuần.", "Khám âm đạo có thể thấy nhân di căn âm đạo, màu tím sẫm, dễ vỡ gây chảy máu"], "bullets": []}, {"heading": "5.2. Chửa trứng bán phần", "paragraphs": ["Chửa trứng bán phần thường không có triệu chứng điển hình như chửa trứng toàn phần, chẩn đoán thường dựa vào mô bệnh học sau khi hút nạo", "Rong huyết 72%", "Tử cung to hơn tuổi thai 3,7%", "Tiền sản giật 2,5%", "Nghén, nang hoàng tuyến, cường giáp không có", "(-hCG >100.000 mIU/ml chỉ chiếm 6,6%"], "bullets": []}, {"heading": "6. ĐẶC ĐIỂM CẬN LÂM SÀNG", "paragraphs": ["Siêu âm: cho thấy hình ảnh tuyết rơi hoặc lổ chổ như tổ ong. Có thể thấy nang hoàng tuyến hai bên, không thấy phôi thai trong chửa trứng toàn phần.", "Hình 3. Hình ảnh siêu âm của chửa trứng toàn phần", "Hình 4. Hình ảnh nang hoàng tuyến 2 bên", "Hình 5. Hình ảnh siêu âm của chửa trứng bán phần"], "bullets": ["- Định lượng (-hCG: là xét nghiệm cơ bản để chẩn đoán và theo dõi chửa trứng. Lượng (-hCG tăng cao, trên 100.000 mUI/ ml gặp trong 46% chửa trứng hoàn toàn và 10% chửa trứng bán phần.", "- Các xét nghiệm khác: định lượng HPL (Human placental lactogen), thường cao trong thai thường, nhưng rất thấp trong chửa trứng.", "- Định lượng Estrogen: Trong nước tiểu Estrogen dưới dạng các Estrone, estradiol hay estriol đều thấp hơn trong thai thường, do sự rối loạn chế tiết của rau và do không có sự biến đổi estradiol và estriol xảy ra ở tuyến thượng thận của thai nhi. Sự khác biệt này thấy rõ khi tuổi thai từ 14 tuần trở lên."]}, {"heading": "7. CHẨN ĐOÁN PHÂN BIỆT", "paragraphs": ["Doạ sẩy thai: tử cung không to hơn tuổi thai, lượng (-hCG không cao.", "Thai ngoài tử cung: ra máu âm đạo, tử cung nhỏ, có khối cạnh tử cung đau.", "Thai chết lưu: tử cung nhỏ hơn tuổi thai, (-hCG  âm tính, vú có tiết sữa non. Có thể nhầm với chửa trứng thoái triển. Siêu âm giúp ta chẩn đoán xác định và chẩn đoán phân biệt chính xác.", "Nghén nặng trong thai thường, đa thai."], "bullets": []}, {"heading": "8.1. Tiến triển tự nhiên", "paragraphs": ["Nếu không được chẩn đoán và điều trị kịp thời thường sẩy trứng băng huyết nặng, nguy hiểm đến tính mạng bệnh nhân."], "bullets": []}, {"heading": "8.2. Tiến triển sau nạo thai trứng", "paragraphs": ["Tiến triển tốt: trong 80- 90% các trường hợp. Bệnh nhân hết ra máu, tử cung co hồi nhanh sau 5 - 6 ngày, nang hoàng tuyến nhỏ dần và biến mất, nồng độ (-hCG giảm nhanh trong vài ngày, có thể giảm xuống còn 350 - 500mUI/ml trong vài tuần.", "Tiến triển xấu: sau khi hút nạo, có đến 15% tiến triển thành chửa trứng xâm lấn và choriocarcinoma khoảng 4%.", "Tiêu chuẩn đánh giá chửa trứng có nguy cơ cao tiến triển thành u nguyên bào nuôi:"], "bullets": ["+ Kích thước tử cung trước nạo to hơn tuổi thai 20 tuần", "+ Có 2 nang hoàng tuyến to 2 bên", "+ Tuổi của mẹ trên 40", "+ Nồng độ òưhCG tăng rất cao", "+ Có biến chứng của thai trứng như nhiễm độc thai nghén, cường giáp.", "+ Chửa trứng lặp lại."]}, {"heading": "8.3. Biến chứng", "paragraphs": ["Băng huyết sau sẩy, sau nạo", "Thủng tử cung sau nạo hút trứng", "Nhiễm khuẩn sau sẩy, sau nạo trứng."], "bullets": []}, {"heading": "9.1. Tuyến xã", "paragraphs": ["Chuyển lên tuyến trên nếu chửa trứng chưa sẩy.", "Nếu chửa đang sẩy: thiết lập đường chuyền, hồi sức chống choáng, sử dụng Oxytocin và các thuốc co hồi tử cung, nhanh chóng chuyển lên tuyến trên."], "bullets": []}, {"heading": "9.2. Tuyến huyện và các tuyến chuyên khoa", "paragraphs": ["Sau khi chẩn đoán chửa trứng, nên điều trị những bệnh nội khoa kết hợp như tiền sản giật, cường giáp, thiếu máu, rối loạn nước điện giải trước khi nạp hút trứng"], "bullets": []}, {"heading": "9.2.1. Nạo hút trứng", "paragraphs": ["Nạo hút trứng ngay sau khi được chẩn đoán để đề phòng sẩy tự nhiên gây băng huyết.", "Kỹ thuật: Hút trứng + truyền oxytocin + kháng sinh.", "Thường dùng máy hút dưới áp lực âm để hút nhanh, đỡ chảy máu. Tốt nhất hút dưới hướng dẫn của siêu âm.", "Trong khi hút phải truyền tĩnh mạch dung dịch Glucose 5% pha với 5 đơn vị Oxytocin để giúp tử cung go hồi tốt, tránh thủng tử cung khi nạo và cầm máu.", "Nạo lại lần 2 sau 2 - 3 ngày nếu kiểm tra thấy còn sót mô trứng.", "Sau nạo phải dùng kháng sinh chống nhiễm trùng.", "Gửi tổ chức sau nạo làm giải phẫu bệnh."], "bullets": []}, {"heading": "9.2.2. Phẫu thuật cắt tử cung nguyên khối", "paragraphs": ["Nếu bệnh nhân không muốn có con nữa hoặc trên 40 tuổi, đủ con và trường hợp chửa trứng xâm lấn làm thủng tử cung, có thể cắt tử cung nguyên khối. Cắt tử cung không phòng được di căn vì vậy bệnh nhân cần được theo dõi hCG."], "bullets": []}, {"heading": "9.2.3. Điều trị hóa chất dự phòng", "paragraphs": ["Điều trị dự phòng cho những bệnh nhân có nguy cơ cao và không theo dõi sau nạo hút được."], "bullets": []}, {"heading": "9.2.4. Theo dõi sau nạo trứng", "paragraphs": ["Cần gửi giải phẫu bệnh mô nạo hoặc tử cung để có chẩn đoán mô học lành tính hay ác tính.", "ư Cận lõm sàng: định lượng ò hCG 8 ngày/1 lần cho đến khi õm tớnh. Nếu xột nghiệm 3 lần liờn tiếp õm tớnh thỡ mới được khẳng định là õm tớnh. Sau đú định lượng 2 thỏng một lần cho đến hết thời gian theo dừi.", "Tiến triển bệnh lý: Những tiến triển không tương ứng với các tiêu chuẩn lành bệnh được coi là tiến triển không thuận lợi.", "Hình 4. Diễn biến bình thường của nồng độ Beta-hCG sau nạo trứng", "Tiêu chuẩn đánh giá chửa trứng có nguy cơ cao:", "Thời gian theo dõi: 2 năm, ít nhất 12 - 18 tháng."], "bullets": ["- Lâm sàng:", "+ Toàn trạng, triệu chứng nghén, triệu chứng ra máu âm đạo, sự nhỏ lại của nang hoàng tuyến và  sự co hồi tử cung.", "+ Xét nghiệm chức năng gan, thận", "+ X quang phổi: tìm nhân di căn.", "+ Siêu âm: tìm nhân di căn, theo dõi nang hoàng tuyến.", "+ Tử cung vẫn to, nang hoàng tuyến không mất đi hoặc xuất hiện nhân di căn âm đạo", "+ òưhCG khụng biến mất sau 3 thỏng.", "+ òưhCG tăng trở lại sau 3 lần định lượng cỏch nhau 8 ngày.", "+ Bỡnh thường òưhCG biến mất 12 tuần sau nạo trứng.", "+ Kích thước tử cung trước nạo to hơn tuổi thai 20 tuần", "+ Có 2 nang hoàng tuyến to 2 bên", "+ Tuổi của mẹ trên 40", "+ Nồng độ òưhCG tăng rất cao", "+ Có biến chứng của thai trứng như nhiễm độc thai nghén, cường giáp.", "+ Chửa trứng lặp lại.", "- Thời gian theo dõi"]}, {"heading": "9.2.5. Các biện pháp tránh thai sử dụng trong thời gian theo dõi", "paragraphs": ["Bao cao su", "Thuốc tránh thai đường uống dạng phối hợp nếu không có chống chỉ định.", "Triệt sản", "Không nên đặt dụng cụ tử cung vì có nguy cơ thủng tử cung"], "bullets": []}, {"heading": "Câu hỏi:", "paragraphs": ["Trình bày các yếu tố nguy cơ của chửa trứng?", "Trình bày triệu chứng lâm sàng, cận lâm sàng để chẩn đoán chửa trứng?", "Liệt kê được các tiến triển và biến chứng của chửa trứng", "Trình bày hướng điều trị và theo dõi sau nạo trứng ?"], "bullets": []}], "raw_text": "CHỬA TRỨNG\nThs.iMục tiêu học tập\n1. Nêu được các yếu tố nguy cơ của chửa trứng.\n2. Trình bày các đặc điểm lâm sàng và cận lâm sàng để chẩn đoán chửa trứng\n3. Liệt kê được các tiến triển và biến chứng của chửa trứng\n4. Trình bày được hướng xử trí chửa trứng và theo dõi sau nạo trứng.\n1. ĐẠI CƯƠNG\nChửa trứng là bệnh của tế bào nuôi, do sự tăng sinh của các hợp bào và lớp trong lá nuôi của gai rau, tạo thành những túi chứa chất dịch, dính vào nhau như chùm nho.\nChửa trứng là một bệnh bắt nguồn từ thai nghén. Trong phần lớn các trường hợp, chửa trứng là một dạng lành tính của nguyên bào nuôi do thai nghén. Tuy nhiên, chửa trứng có thể dẫn đến các biến chứng như nhiễm độc, nhiễm trùng, xuất huyết và ung thư nguyên bào nuôi (Choriocarcinoma).\n2. TỶ LỆ\nTỷ lệ chửa trứng thay đổi tùy từng vùng, châu Á hay gặp hơn châu Âu. Ở Nhật Bản (1960-1990): 4,9-1,9/1000, Hàn Quốc (1960-1990): 4,4-2,3/1000, Châu Âu, Bắc Mỹ 0,6 – 1,1/1000 thai kỳ và Việt Nam là 2 % thai kỳ.\n3. CÁC YẾU TỐ NGUY CƠ\n3.1. Điều kiện sống\nĂn thiếu carotene, Vitamin A: nguy cơ chửa trứng toàn phần\n3.2. Tuổi\nSo với phụ nữ 21 đến 35 tuổi, người mẹ > 35 tuổi và < 21 tuổi có nguy cơ thai trứng gấp 1,9 lần. Nếu mẹ trên 40 tuổi thì nguy cơ gấp 7,5 lần.\n3.3. Bất thường nhiễm sắc thể\n- Chửa trứng toàn phần: chửa trứng toàn phần thường có nhiễm sắc đồ là 46XX và có nguồn gốc từ bố, đó là sự thụ tinh của một noãn không có nhân hoặc nhân không hoạt động với một tinh trùng đơn bội, sau đó nhân đôi để tạo thành 46 nhiễm sắc thể. Có khoảng 4-6% chửa trứng toàn phần có 46 nhiễm sắc thể với giới tính XY.\n- Chửa trứng bán phần: Có cả thai nhi và rau thai. 90% đến 93% chửa trứng bán phần có tam bội thể. Do hai tinh trùng thụ tinh với một tế bào noãn bình thường nên bộ nhiễm sắc thể sẽ là 69 XXY, XXX hay XYY. Vì vậy thai nhi hiện diện trong chửa trứng bán phần mang đặc điểm nhiều dị dạng của tam bội như não úng thủy, dính ngón, chậm phát triển…Khả năng ác tính của chửa trứng bán phần thấp hơn chửa trứng toàn phần.\n\nHình 1. Cơ chế tạo thành chửa trứng\n4. GIẢI PHẪU BỆNH\n4.1. Đại thể\nCó 2 loại thai trứng:\nChửa trứng toàn phần: toàn bộ gai rau đều thoái hóa, ứ nước thành các túi trứng.\nChửa trứng bán phần: bên cạnh các túi trứng còn có mô rau thai bình thường, hoặc có cả phôi, thai nhi (thường chết trong giai đoạn 3 tháng đầu).\nĐường kính túi trứng từ 1-3mm. Các túi trứng dính vào nhau như những bọc trứng ếch hoặc chùm nho\n\nHình 2. Bệnh phẩm đại thể chửa trứng toàn phần và bán phần.\n4.2. Vi thể\nCác túi trứng thể tích lớn hơn gai rau rất nhiều, lớp nguyên bào nuôi bọc ngoài bị căng mỏng, trục liên kết động-tĩnh mạch bị thoái hoá không còn mạch máu. Tổ chức liên kết thưa thớt và chỉ chứa một chất dịch trong như nước.\n5. ĐẶC ĐIỂM LÂM SÀNG\n5.1. Chửa trứng toàn phần\n5.1.1. Triệu chứng cơ năng\n- Bệnh nhân có hiện tượng mất kinh.\n- Rong huyết chiếm trên 90% trường hợp chửa trứng. Máu ra ở âm đạo tự nhiên, máu sẫm đen hoặc đỏ loãng, ra kéo dài.\n- Nghén nặng: gặp trong 25-30% các trường hợp, biểu hiện nôn nhiều, đôi khi phù.\n- Bụng to nhanh.\n- Không thấy thai máy.\n5.1.2. Triệu chứng thực thể\nToàn thân: mệt mỏi. Ngày nay nhờ phát hiện sớm chửa trứng trong 3 tháng đầu thai kỳ nên triệu chứng thiếu máu chỉ khoảng 5%.\nCường giáp chiếm khoảng 7%. Bệnh nhân có nhịp tim nhanh, da ẩm, tay run, xét nghiệm T3,T4 tăng. Nếu cường giáp nên cho thuốc chẹn β-adrenergic trước khi hút nạo. Cơn bão giáp có thể xảy ra với tăng thân nhiệt, mê sảng, co giật, nhịp tim nhanh, tăng cung lượng tim.\nTiền sản giật chiếm tỷ lệ khoảng 27%. Tiền sản giật xuất hiện ở bệnh nhân có tử cung to hơn tuổi thai và hCG tăng cao, nên nghĩ đến chửa trứng khi tiền sản giật xuất hiện sớm.\nTử cung mềm, bề cao tử cung lớn hơn tuổi thai do chứa máu và mô trứng là dấu hiệu điển hình chiếm 50% (trừ trường hợp chửa trứng thoái triển).\nKhông sờ được phần thai và không nghe được tim thai.\nNang hoàng tuyến xuất hiện trong 25-50%, do hCG tăng cao gây kích thích buồng trứng. Nang thường gặp cả 2 bên và trở về bình thường sau 8 tuần.\nKhám âm đạo có thể thấy nhân di căn âm đạo, màu tím sẫm, dễ vỡ gây chảy máu\n5.2. Chửa trứng bán phần\nChửa trứng bán phần thường không có triệu chứng điển hình như chửa trứng toàn phần, chẩn đoán thường dựa vào mô bệnh học sau khi hút nạo\nRong huyết 72%\nTử cung to hơn tuổi thai 3,7%\nTiền sản giật 2,5%\nNghén, nang hoàng tuyến, cường giáp không có\n(-hCG >100.000 mIU/ml chỉ chiếm 6,6%\n6. ĐẶC ĐIỂM CẬN LÂM SÀNG\nSiêu âm: cho thấy hình ảnh tuyết rơi hoặc lổ chổ như tổ ong. Có thể thấy nang hoàng tuyến hai bên, không thấy phôi thai trong chửa trứng toàn phần.\n\nHình 3. Hình ảnh siêu âm của chửa trứng toàn phần\n\nHình 4. Hình ảnh nang hoàng tuyến 2 bên\n\n\nHình 5. Hình ảnh siêu âm của chửa trứng bán phần\n- Định lượng (-hCG: là xét nghiệm cơ bản để chẩn đoán và theo dõi chửa trứng. Lượng (-hCG tăng cao, trên 100.000 mUI/ ml gặp trong 46% chửa trứng hoàn toàn và 10% chửa trứng bán phần.\n- Các xét nghiệm khác: định lượng HPL (Human placental lactogen), thường cao trong thai thường, nhưng rất thấp trong chửa trứng.\n- Định lượng Estrogen: Trong nước tiểu Estrogen dưới dạng các Estrone, estradiol hay estriol đều thấp hơn trong thai thường, do sự rối loạn chế tiết của rau và do không có sự biến đổi estradiol và estriol xảy ra ở tuyến thượng thận của thai nhi. Sự khác biệt này thấy rõ khi tuổi thai từ 14 tuần trở lên.\n7. CHẨN ĐOÁN PHÂN BIỆT\nDoạ sẩy thai: tử cung không to hơn tuổi thai, lượng (-hCG không cao.\nThai ngoài tử cung: ra máu âm đạo, tử cung nhỏ, có khối cạnh tử cung đau.\nThai chết lưu: tử cung nhỏ hơn tuổi thai, (-hCG  âm tính, vú có tiết sữa non. Có thể nhầm với chửa trứng thoái triển. Siêu âm giúp ta chẩn đoán xác định và chẩn đoán phân biệt chính xác.\nNghén nặng trong thai thường, đa thai.\n8. TIẾN TRIỂN VÀ BIẾN CHỨNG\n8.1. Tiến triển tự nhiên\nNếu không được chẩn đoán và điều trị kịp thời thường sẩy trứng băng huyết nặng, nguy hiểm đến tính mạng bệnh nhân.\n8.2. Tiến triển sau nạo thai trứng\nTiến triển tốt: trong 80- 90% các trường hợp. Bệnh nhân hết ra máu, tử cung co hồi nhanh sau 5 - 6 ngày, nang hoàng tuyến nhỏ dần và biến mất, nồng độ (-hCG giảm nhanh trong vài ngày, có thể giảm xuống còn 350 - 500mUI/ml trong vài tuần.\nTiến triển xấu: sau khi hút nạo, có đến 15% tiến triển thành chửa trứng xâm lấn và choriocarcinoma khoảng 4%.\nTiêu chuẩn đánh giá chửa trứng có nguy cơ cao tiến triển thành u nguyên bào nuôi:\n+ Kích thước tử cung trước nạo to hơn tuổi thai 20 tuần\n+ Có 2 nang hoàng tuyến to 2 bên\n+ Tuổi của mẹ trên 40\n+ Nồng độ òưhCG tăng rất cao\n+ Có biến chứng của thai trứng như nhiễm độc thai nghén, cường giáp.\n+ Chửa trứng lặp lại.\n8.3. Biến chứng\nBăng huyết sau sẩy, sau nạo\nThủng tử cung sau nạo hút trứng\nNhiễm khuẩn sau sẩy, sau nạo trứng.\n9. ĐIỀU TRỊ\n9.1. Tuyến xã\nChuyển lên tuyến trên nếu chửa trứng chưa sẩy.\nNếu chửa đang sẩy: thiết lập đường chuyền, hồi sức chống choáng, sử dụng Oxytocin và các thuốc co hồi tử cung, nhanh chóng chuyển lên tuyến trên.\n9.2. Tuyến huyện và các tuyến chuyên khoa\nSau khi chẩn đoán chửa trứng, nên điều trị những bệnh nội khoa kết hợp như tiền sản giật, cường giáp, thiếu máu, rối loạn nước điện giải trước khi nạp hút trứng\n9.2.1. Nạo hút trứng\nNạo hút trứng ngay sau khi được chẩn đoán để đề phòng sẩy tự nhiên gây băng huyết.\nKỹ thuật: Hút trứng + truyền oxytocin + kháng sinh.\nThường dùng máy hút dưới áp lực âm để hút nhanh, đỡ chảy máu. Tốt nhất hút dưới hướng dẫn của siêu âm.\nTrong khi hút phải truyền tĩnh mạch dung dịch Glucose 5% pha với 5 đơn vị Oxytocin để giúp tử cung go hồi tốt, tránh thủng tử cung khi nạo và cầm máu.\nNạo lại lần 2 sau 2 - 3 ngày nếu kiểm tra thấy còn sót mô trứng.\nSau nạo phải dùng kháng sinh chống nhiễm trùng.\nGửi tổ chức sau nạo làm giải phẫu bệnh.\n9.2.2. Phẫu thuật cắt tử cung nguyên khối\nNếu bệnh nhân không muốn có con nữa hoặc trên 40 tuổi, đủ con và trường hợp chửa trứng xâm lấn làm thủng tử cung, có thể cắt tử cung nguyên khối. Cắt tử cung không phòng được di căn vì vậy bệnh nhân cần được theo dõi hCG.\n9.2.3. Điều trị hóa chất dự phòng\nĐiều trị dự phòng cho những bệnh nhân có nguy cơ cao và không theo dõi sau nạo hút được.\n9.2.4. Theo dõi sau nạo trứng\nCần gửi giải phẫu bệnh mô nạo hoặc tử cung để có chẩn đoán mô học lành tính hay ác tính.\n- Lâm sàng:\n+ Toàn trạng, triệu chứng nghén, triệu chứng ra máu âm đạo, sự nhỏ lại của nang hoàng tuyến và  sự co hồi tử cung.\nư Cận lõm sàng: định lượng ò hCG 8 ngày/1 lần cho đến khi õm tớnh. Nếu xột nghiệm 3 lần liờn tiếp õm tớnh thỡ mới được khẳng định là õm tớnh. Sau đú định lượng 2 thỏng một lần cho đến hết thời gian theo dừi.\n+ Xét nghiệm chức năng gan, thận\n+ X quang phổi: tìm nhân di căn.\n+ Siêu âm: tìm nhân di căn, theo dõi nang hoàng tuyến.\nTiến triển bệnh lý: Những tiến triển không tương ứng với các tiêu chuẩn lành bệnh được coi là tiến triển không thuận lợi.\n+ Tử cung vẫn to, nang hoàng tuyến không mất đi hoặc xuất hiện nhân di căn âm đạo\n+ òưhCG khụng biến mất sau 3 thỏng.\n+ òưhCG tăng trở lại sau 3 lần định lượng cỏch nhau 8 ngày.\n+ Bỡnh thường òưhCG biến mất 12 tuần sau nạo trứng.\n\nHình 4. Diễn biến bình thường của nồng độ Beta-hCG sau nạo trứng\n\nTiêu chuẩn đánh giá chửa trứng có nguy cơ cao:\n+ Kích thước tử cung trước nạo to hơn tuổi thai 20 tuần\n+ Có 2 nang hoàng tuyến to 2 bên\n+ Tuổi của mẹ trên 40\n+ Nồng độ òưhCG tăng rất cao\n+ Có biến chứng của thai trứng như nhiễm độc thai nghén, cường giáp.\n+ Chửa trứng lặp lại.\n- Thời gian theo dõi\nThời gian theo dõi: 2 năm, ít nhất 12 - 18 tháng.\n9.2.5. Các biện pháp tránh thai sử dụng trong thời gian theo dõi\nBao cao su\nThuốc tránh thai đường uống dạng phối hợp nếu không có chống chỉ định.\nTriệt sản\nKhông nên đặt dụng cụ tử cung vì có nguy cơ thủng tử cung\nCâu hỏi:\nTrình bày các yếu tố nguy cơ của chửa trứng?\nTrình bày triệu chứng lâm sàng, cận lâm sàng để chẩn đoán chửa trứng?\nLiệt kê được các tiến triển và biến chứng của chửa trứng\nTrình bày hướng điều trị và theo dõi sau nạo trứng ?", "priority": "Cao (Trọng tâm BSNT)"}, {"id": "SK-19", "chapter": "Chương 2. Sản bệnh", "folder": "02_San_benh", "title": "Đẻ khó", "author": "PGS. TS. Ninh Văn Minh", "word_count": 3050, "line_count": 127, "key_numbers": ["10 cm", "10 phút", "12 giờ", "12 mmHg", "13,5 cm", "20 mmHg", "25 mm", "28 mmHg", "3 tháng", "41 mmHg", "47 mmHg", "500 ml", "6 giờ", "8 mmHg", "8,5 cm", "9 cm"], "key_drugs": ["Oxytocin", "Prostaglandin", "oxytocin", "prostaglandin"], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["ĐẺ KHÓ"], "bullets": []}, {"heading": "1. MỞ ĐẦU", "paragraphs": ["Đẻ khó là cuộc đẻ cần có sự can thiệp của người thầy thuốc. Đẻ khó có thể gây hậu quả bệnh tật, tử vong cho sản phụ và thai nhi. Để hạn chế đến mức thấp nhất tai biến của các cuộc đẻ khó, người thầy thuốc sản khoa phải nắm chắc các nguyên nhân gây đẻ khó, phân loại các nguy cơ trong quá trình quản lý thai nghén 3 tháng cuối, lúc chuyển dạ, chẩn đoán được các nguyên nhân gây đẻ khó để xây dựng phương án xử trí tốt nhất cho từng sản phụ."], "bullets": []}, {"heading": "2.1. Sinh lý cơn co tử cung", "paragraphs": ["Trong thai kỳ, đặc tính của cơ tử cung thường tăng khả năng co bóp. Người ta nhận thấy có sự gia tăng một số chất như oxytocin, prostaglandin, angiotensin, serotonin, acethylcholin, adrenalin, noradrenalin..., đến quý 3 của thai kỳ nên có một vài cơn co sinh lý bình thường không gây giãn cổ tử cung xuất hiện. Chúng được gọi là cơn co Braxton - Hicks. Trong quá trình chuyển dạ thực sự thì các cơn co tử cung thường xuất hiện một cách nhịp nhàng và tăng dần về cường độ, tần số và biên độ và làm giãn cổ tử cung. Cơn co tử cung thường được phát hiện bằng cảm giác đau của người mẹ. Lúc cường độ cơn co tử cung ≥ 25 mm Hg, bất kể cơn co Braxton - Hicks ít khi hoặc không gây ra cảm giác đau cho sản phụ. Ngoài cảm giác đau của sản phụ, muốn phát hiện cơn co tử cung thì cần bắt cơn co bằng cách người thầy thuốc đặt tay lên bụng sản phụ (lúc cơn co tử cung đạt trị số ≥ 20 mmHg). Hiện nay sau các công trình nghiên cứu của Caldeyro - Barcia, Alvarez ở Montévideo (Uruguay), người ta đánh giá cơn co tử cung bằng đơn vị Montévideo (U.M).", "Đây cũng chính là đơn vị tính hoạt độ tử cung. Hoạt độ tử cung bằng tích số của cường độ cơn co tử cung (mmHg) và tần số các cơn co tử cung (trong 10 phút). Qua khảo sát các tác giả đều nhận thấy rằng:", "Cơn co tử cung là động lực chính của cuộc đẻ và thường chịu ảnh hưởng bởi nhiều yếu tố:", "Cơn co tử cung xuất phát từ 2 sừng tử cung, thường bắt đầu ở sừng phải, đi từ đáy tử cung xuống dưới, càng xuống dưới càng giảm về cường độ và biên độ. Khi có sự bất thường dẫn truyền cơn cothì dẫn đến rối loạn co bóp tử cung.", "Vào thời điểm bắt đầu cuộc chuyển dạ trương lực cơ bản của cơ tử cung khoảng 8 mmHg, tăng lên khoảng 12 mmHg khi cổ tử cung mở hết. Trong trường hợp trương lực cơ tử cung tăng bất thường có thể làm chậm quá trình xoá mở cổ tử cung, gây nên đẻ khó. Tăng trương lực cơ tử cung thường xảy ra sau cơn co tử cung cường tính, tuy nhiên cũng có thể xuất hiện đơn lẻ.", "Một cuộc chuyển dạ tiến triển bình thường khi cơn co tử cung bình thường nghĩa là phải nhịp nhàng có lúc nghỉ, không mạnh quá và không yếu quá, trương lực của tử cung không cao, nhịp độ và cường độ của các cơn co ngày càng tăng, khoảng cách giữa hai cơn co ngày càng ngắn lại.", "Có 2 loại đẻ khó do rối loạn cơn co tử cung:"], "bullets": ["- Đối với cơn co Braxton - Hicks thì hoạt độ tử cung < 50 U.M.", "- Lúc có chuyển dạ thực sự thì cường độ cơn co tử cung trung bình là 28 mmHg, tần số là 3 cơn co trong 10 phút, hoạt độ tử cung khoảng 85 U.M.", "- Khi cổ tử cung mở hết, hoạt độ tử cung thường là 187 U.M. Cường độ mỗi cơn co tử cung khoảng 41 mmHg và tần số khoảng 4,2 cơn co trong 10 phút. Khi rặn sổ, cường độ cơn co khoảng 47 mmHg, tần số 5 cơn co tử cung trong 10 phút, hoạt độ trong thời điểm này là khoảng 235 U.M.", "- Tình trạng sức khoẻ chung của sản phụ, thai nhi và phần phụ của thai nhi.", "- Các thuốc tăng co, giảm co sử dụng trong chuyển dạ.", "- Tư thế nằm ngửa, tần số cơn co tử cung thường tăng hơn tư thế nằm nghiêng, tuy nhiên cơn co tử cung thường mạnh hơn ở tư thế nghiêng.", "- Đẻ khó do tăng trương lực cơ bản của tử cung (chú ý: loại này cũng đồng nghĩa với đẻ khó do cơn co tử cung tăng).", "- Đẻ khó do cơn co tử cung giảm."]}, {"heading": "2.2. Đẻ khó do cơn co tử cung tăng", "paragraphs": ["Khi có sự tăng co bóp cơ tử cung quá mức bình thường tức là thời gian co dài hơn bình thường, cường độ cơn co mạnh hơn, khoảng cách giữa hai cơn co ngắn làm sản phụ kêu la, đau nhiều. Trong khi đó, trương lực cơ bản vẫn bình thường giữa các cơn co."], "bullets": []}, {"heading": "2.2.1. Nguyên nhân", "paragraphs": ["Thường gặp là nhóm nguyên nhân cơ học như:"], "bullets": ["- Bất tương xứng giữa thai nhi và khung chậu.", "- Khối u tiền đạo.", "- Cổ tử cung khó mở (do viêm cổ tử cung, đốt cổ tử cung, phẫu thuật Manchester, khoét chóp cổ tử cung, sẹo cổ tử cung do rách cũ, phù nề cổ tử cung do thăm khám âm đạo nhiều lần trong chuyển dạ...)", "- Tử cung kém phát triển, tử cung xơ hoá (thường ở sản phụ lớn hơn 35 tuổi), dị dạng tử cung (tử cung đôi...)", "- Rau bong non", "- Đa ối, đa thai làm cho thể tích tử cung tăng lên bất thường.", "- Đoạn dưới tử cung kém phát triển.", "- Sử dụng thuốc tăng co tử cung không đúng chỉ định. (Oxytocin, Prostaglandin)", "- Các nguyên nhân về thần kinh, thay đổi tâm sinh lý người mẹ như tinh thần sản phụ không ổn định, lo lắng nhiều v.v.", "- Các nguyên nhân khác về thai và phần phụ thai như: thai to toàn bộ hoặc từng phần (não úng thuỷ), ngôi thai, kiểu thế thai thất thường, ối vỡ sớm, vỡ non làm giảm thể tích buồng tử cung."]}, {"heading": "2.2.2. Hậu quả", "paragraphs": [], "bullets": ["- Chuyển dạ đình trệ do cổ tử cung khó xoá mở.", "- Suy thai, nhất là sau khi ối vỡ vì áp lực cơn co tử cung sẽ tác động trực tiếp đến bánh rau và dây rốn, hơn nữa do cơn co tử cung tăng nên tuần hoàn mẹ - rau - thai bị suy giảm.", "- Vỡ tử cung nếu không xử trí kịp thời đặc biệt trên các sản phụ có vết mổ cũ, dị dạng tử cung, tử cung nhi dạng, con rạ (đẻ nhiều lần)."]}, {"heading": "2.2.3. Xử trí", "paragraphs": [], "bullets": ["- Ngưng dùng thuốc tăng co (nếu đang dùng), điều chỉnh cơn go bằng các thuốc giảm co như Papavérin, Spasmavérin, Spasmalgin, Seduxen, Dolargan (Dolosal).", "- Mổ lấy thai nếu khung chậu hẹp hoặc bất tương xứng đầu chậu.", "- Liệu pháp tâm lý: động viên, giải thích để sản phụ yên tâm, nhất là các sản phụ hay lo lắng, suy nhược thần kinh. Nếu cần thiết thì sử dụng seduxen, dolargan."]}, {"heading": "2.3. Đẻ khó do cơn co tử cung giảm", "paragraphs": ["Cơn co tử cung giảm khi giảm cường độ, biên độ, tần số."], "bullets": []}, {"heading": "2.3.1. Nguyên nhân", "paragraphs": [], "bullets": ["- Nguyên phát: Sản phụ suy nhược, thiếu máu, thiếu nước, suy tim, lao phổi, tử cung kém phát triển, u xơ tử cung.", "- Thứ phát: Đa ối, đa thai, chuyển dạ kéo dài, ối vỡ sớm, nhiễm khuẩn ối, lạm dụng các thuốc giảm co vào giai đoạn đầu của chuyển dạ."]}, {"heading": "2.3.2. Hậu quả", "paragraphs": [], "bullets": ["- Chuyển dạ đình trệ.", "- Cổ tử cung phù nề, chậm tiến triển.", "- Nhiễm khuẩn ối.", "- Suy thai."]}, {"heading": "2.3.3. Xử trí", "paragraphs": [], "bullets": ["- Kháng sinh: nếu ối vỡ trên 6 giờ để đề phòng nhiễm khuẩn ối.", "- Tăng co: nếu ối đã vỡ trên 12 giờ bằng cách chuyền oxytocin 5 đơn vị hoà trong 500 ml dung dịch Glucoza 5%, tăng giảm số giọt tuỳ theo tình trạng cơn co. Nếu chỉ số Bishop > 6 điểm: hiệu quả tốt.", "- Bấm ối: nếu đa ối, đa thai để tạo cơn co tử cung.", "- Trong giai đoạn thai sổ, nếu cơn co tử cung thưa, yếu cần phối hợp thuốc tăng co hoặc hỗ trợ forceps, giác hút nếu có chỉ định và đủ điều kiện."]}, {"heading": "3. ĐẺ KHÓ DO NGUYÊN NHÂN CƠ HỌC", "paragraphs": ["Đẻ khó do nguyên nhân cơ học nghĩa là tất cả những nguyên nhân gây cản trở quá trình lọt, xuống và sổ của thai."], "bullets": []}, {"heading": "3.1.1. Khung chậu bất thường", "paragraphs": ["Gọi là khung chậu bất thường khi một hoặc nhiều đường kính của khung chậu ngắn hơn bình thường. Trên lâm sàng người ta thường gặp:", "* Khung chậu hẹp toàn bộ: Khi các đường kính giảm đều ở eo trên và eo dưới (đường kính nhô hậu vệ < 8,5 cm).", "* Xử trí: mổ lấy thai khi thai đủ tháng và có dấu hiệu chuyển dạ.", "Hinh 1. Khung chậu méo"], "bullets": ["- Khung chậu hẹp", "+ Khung chậu có tất cả các đường kính đều giảm, bao gồm hai loại sau:", "+ Khung chậu giới hạn: Khi đường kính nhô hậu vệ từ 8,5 - 10 cm; nhưng trọng lượng thai bình thường có thể làm nghiệm pháp lọt ngôi chỏm, nếu diễn tiến thuận lợi thì đẻ đường âm đạo, ngược lại thì mổ lấy thai. Trường hợp ngôi chỏm mà thai to hoặc các ngôi bất lợi thì nên chỉ định mổ lấy thai khi có dấu hiệu chuyển dạ.", "- Khung chậu biến dạng", "+ Hẹp eo trên, hẹp eo dưới, hoặc khung chậu méo, bao gồm:", "+ Khung chậu hẹp eo trên: Khung chậu dẹt khi các đường kính ngang và đường kính chéo không thay đổi chỉ có đường kính trước sau ngắn hơn bình thường. Khung chậu dẹt có cột sống cong trước làm eo trên hẹp, eo dưới rộng, vì vậy nếu thai lọt được thì sổ sẽ dễ dàng.", "+ Chẩn đoán dựa vào đường kính nhô hậu vệ và thái độ xử trí tuỳ thuộc vào đường kính này.", "+ Khung chậu hẹp eo dưới: là loại khung chậu có cột sống cong sau, nguyên nhân do gù, lao cột sống, thương tổn cột sống ở thấp. Dạng khung chậu này hình phễu, thai sẽ lọt dễ dàng qua eo trên, nhưng khó hoặc không sổ được qua eo dưới dễ bị mắc kẹt trong tiểu khung. Chẩn đoán dựa vào đường kính lưỡng ụ ngồi, nếu đường kính này < 9 cm thì thai không sổ được.", "+ Thái độ xử trí: Cần tiên lượng sớm để có chỉ định mổ lấy thai, nếu thai nhỏ sổ được thì có thể phải cắt rộng tầng sinh môn.", "+ Khung chậu méo: còn gọi là khung chậu không đối xứng, do cột sống bị vẹo vì bệnh còi xương, sai khớp háng bẩm sinh một bên hay bị bại liệt. Việc chẩn đoán dựa vào hình trám Michaelis, dáng đi để định mức độ lệch. Hai đường kính chéo của eo trên dài ngắn khác biệt rõ rệt, nếu ngôi lọt hướng vào đường kính chéo lớn thì tiên lượng tốt.", "+ Thái độ xử trí: Dựa vào đường kính nhô hậu vệ. Nếu đường kính này bình thường, trọng lượng thai trung bình, chỏm hướng theo đường kính chéo lớn của eo trên thì ta có thể bấm ối làm nghiệm pháp lọt ngôi chỏm. Nếu tiến triển thuận lợi thì đẻ đường dưới, ngược lại thì mổ lấy thai. Các trường hợp khác đều có chỉ định mổ lấy thai khi có dấu chuyển dạ."]}, {"heading": "3.1.2. Khối u tiền đạo", "paragraphs": ["Đây là các khối u nằm trong tiểu khung cản trở ngôi không lọt và không sổ được, thường gặp là khối u buồng trứng nằm ở túi cùng sau của âm đạo, u xơ ở eo hay ở cổ tử cung. Ngoài ra có các khối u tiền đạo khác ít gặp hơn như u âm đạo, u vòi trứng, u dây chằng rộng, u thận, u trực tràng, u bàng quang, tử cung đôi....", "Xử trí: Mổ lấy thai và giải quyết khối u nếu u tiền đạo làm ngôi không lọt.."], "bullets": []}, {"heading": "3.1.3. Âm đạo chít hẹp, vách ngăn âm đạo", "paragraphs": ["Xử trí: Nếu đủ điều kiện đẻ đường dưới, cắt vách ngăn khi cổ tử cung mở hết, ngôi lọt thấp."], "bullets": ["- Âm đạo chít hẹp do bị  rách phức tạp trong những lần đẻ trước hoặc sau những cuộc mổ có liên quan đến âm đạo như mổ sa sinh dục, mổ rò bàng quang âm đạo, rò trực tràng âm đạo. Xử trí: Mổ lấy thai khi có dấu hiệu chuyển dạ.", "- Do dị tật bẩm sinh âm đạo có vách ngăn dọc, vách ngăn ngang."]}, {"heading": "3.2.1. Thai to toàn bộ", "paragraphs": ["Thai to khi trọng lượng của thai > 4.000 gram (ở Châu Âu) hay > 3.500 gram ở Việt Nam, ở trường hợp này nếu khung chậu bình thường có thể làm nghiệm pháp lọt ngôi chỏm, nếu thất bại thì mổ lấy thai. Các ngôi khác có chỉ định mổ lấy thai khi chuyển dạ."], "bullets": []}, {"heading": "3.2.2. Thai to từng phần", "paragraphs": ["Xử trí:", "Xử trí: Nếu đầu đã sổ, có thể hạ tay theo thủ thuật Jacquemier.", "Xử trí: chọc bụng hút dịch bụng báng, moi hết phủ tạng rồi sau đó kéo thai ra qua đường âm đạo."], "bullets": ["- Đầu to: thường gặp não úng thuỷ. Chẩn đoán dựa vào khám âm đạo (các đường khớp của đầu thai nhi dãn rộng), siêu âm hoặc X quang.", "+ Nếu não úng thuỷ to có thể chọc sọ để tháo bớt nước não tuỷ và sau đó huỷ thai qua đường âm đạo.", "+ Trường hợp não úng thuỷ nhỏ, thai nhi có thể sống thì chỉ định mổ lấy thai nếu không đẻ được đường dưới.", "- Vai to: gặp trong trường hợp thai to, thai vô sọ, mẹ bị đái tháo đường.", "- Bụng to: thường gặp ở dị dạng bụng cóc do cổ chướng, thận đa nang, gan to, lách to. Tiên lượng khó sổ thai hoặc khi đã sổ đầu rồi thì bị mắc ở bụng.", "- Thai dính nhau trong sinh đôi: Gặp trong sinh đôi cùng một noãn, có thể dính lưng, dính bụng… Chỉ định mổ lấy thai."]}, {"heading": "3.2.3. Đẻ khó do ngôi, thế, kiểu thể", "paragraphs": [], "bullets": ["- Ngôi chỏm: Gặp trong ngôi chỏm kiểu thế sau. Một số trường hợp nếu ngôi sổ kiểu chẩm cùng sẽ gây sổ khó khăn. Xử trí: Cắt rộng tầng sinh môn hoặc hỗ trợ thủ thuật.", "- Ngôi mặt: Ngôi mặt chỉ sổ được theo kiểu cằm vệ, ngôi mặt cằm sau thì mổ lấy thai.", "- Ngôi trán: Đường kính trình diện trước eo trên thường là đường kính thượng chẩm - cằm (13,5 cm). Vì vậy thai đủ tháng sẽ không lọt được nên chỉ định mổ lấy thai.", "- Ngôi vai: đối với trường hợp đơn thai, không đẻ được đường dưới, chỉ định mổ lấy thai. Đối với thai thứ hai trong trường hợp song thai, nội xoay và đại kéo thai.", "- Ngôi mông: là ngôi đẻ khó, đặc biệt là thì sổ đầu. Các biến chứng thường gặp trong đẻ ngôi mông là mắc đầu hậu, sa dây rốn, suy thai, nên đa số các trường hợp cóchỉ định mổ lấy thai."]}, {"heading": "3.2.4. Đa thai", "paragraphs": [], "bullets": ["- Song thai cùng là ngôi đầu sẽ cản trở nhau, làm ngôi thai xuống chậm.ở giai đoạn chuẩn bị lọt, đầu sẽ không cúi tốt, phải mổ lấy thai.", "- Ngôi thứ nhất ngược, ngôi thứ 2 là ngôi đầu: Đầu của thai thứ nhất có thể vướng vào thai thứ 2 và không xuống được.", "- Hai thai dính nhau: mổ lấy thai."]}, {"heading": "3.3.1. Rau tiền đạo", "paragraphs": ["Rau tiền đạo bán trung tâm hay trung tâm hoàn toàn phải mổ cấp cứu vì chảy máu và không đẻ được đường âm đạo. Đối với những trường hợp khác có thể bấm ối để giảm bớt sự chảy máu, nếu sau khi bấm ối, máu không cầm được thì phải mổ lấy thai."], "bullets": []}, {"heading": "3.3.2. Dây rốn", "paragraphs": [], "bullets": ["- Sa dây rốn: Chỉ định mổ lấy thai, khi thai còn sống.", "- Dây rốn ngắn: Thường gặp do dây rốn quấn cổ nhiều vòng gây ngôi bất thường, ngôi không lọt được."]}, {"heading": "3.3.3. Đa ối và thiểu ối", "paragraphs": [], "bullets": ["- Trong đa ối phần lớn thai bình chỉnh không tốt và tử cung quá căng làm cho cơn co tử cung bị rối loạn, một số trường hợp ối vỡ đột ngột làm ngôi thai trở thành ngôi vai, sa dây rốn, gây ra đẻ khó. Các nguyên nhân này làm tăng chỉ định mổ lấy thai.", "- Trường hợp thiểu ối: ảnh hưởng tới quá trình trao đổi oxy của thai nhi,  thai bình chỉnh không tốt, gây đẻ khó, chỉ định mổ lấy thai."]}], "raw_text": "ĐẺ KHÓ\n\nMỤC TIÊU HỌC TẬP\n1. Trình bày được sinh lý cơn co tử cung.\n2. Trình bày được các nguyên nhân, hậu quả và cách xử trí các trường hợp đẻ khó do cơn co tử cung.\n3. Trình bày được các nguyên nhân, hậu quả và cách xử trí các trường hợp đẻ khó do các nguyên nhân cơ giới.\n\n1. MỞ ĐẦU\nĐẻ khó là cuộc đẻ cần có sự can thiệp của người thầy thuốc. Đẻ khó có thể gây hậu quả bệnh tật, tử vong cho sản phụ và thai nhi. Để hạn chế đến mức thấp nhất tai biến của các cuộc đẻ khó, người thầy thuốc sản khoa phải nắm chắc các nguyên nhân gây đẻ khó, phân loại các nguy cơ trong quá trình quản lý thai nghén 3 tháng cuối, lúc chuyển dạ, chẩn đoán được các nguyên nhân gây đẻ khó để xây dựng phương án xử trí tốt nhất cho từng sản phụ.\n\n2. ĐẺ KHÓ DO CƠN CO TỬ CUNG\n2.1. Sinh lý cơn co tử cung\nTrong thai kỳ, đặc tính của cơ tử cung thường tăng khả năng co bóp. Người ta nhận thấy có sự gia tăng một số chất như oxytocin, prostaglandin, angiotensin, serotonin, acethylcholin, adrenalin, noradrenalin..., đến quý 3 của thai kỳ nên có một vài cơn co sinh lý bình thường không gây giãn cổ tử cung xuất hiện. Chúng được gọi là cơn co Braxton - Hicks. Trong quá trình chuyển dạ thực sự thì các cơn co tử cung thường xuất hiện một cách nhịp nhàng và tăng dần về cường độ, tần số và biên độ và làm giãn cổ tử cung. Cơn co tử cung thường được phát hiện bằng cảm giác đau của người mẹ. Lúc cường độ cơn co tử cung ≥ 25 mm Hg, bất kể cơn co Braxton - Hicks ít khi hoặc không gây ra cảm giác đau cho sản phụ. Ngoài cảm giác đau của sản phụ, muốn phát hiện cơn co tử cung thì cần bắt cơn co bằng cách người thầy thuốc đặt tay lên bụng sản phụ (lúc cơn co tử cung đạt trị số ≥ 20 mmHg). Hiện nay sau các công trình nghiên cứu của Caldeyro - Barcia, Alvarez ở Montévideo (Uruguay), người ta đánh giá cơn co tử cung bằng đơn vị Montévideo (U.M).\nĐây cũng chính là đơn vị tính hoạt độ tử cung. Hoạt độ tử cung bằng tích số của cường độ cơn co tử cung (mmHg) và tần số các cơn co tử cung (trong 10 phút). Qua khảo sát các tác giả đều nhận thấy rằng:\n- Đối với cơn co Braxton - Hicks thì hoạt độ tử cung < 50 U.M.\n- Lúc có chuyển dạ thực sự thì cường độ cơn co tử cung trung bình là 28 mmHg, tần số là 3 cơn co trong 10 phút, hoạt độ tử cung khoảng 85 U.M.\n- Khi cổ tử cung mở hết, hoạt độ tử cung thường là 187 U.M. Cường độ mỗi cơn co tử cung khoảng 41 mmHg và tần số khoảng 4,2 cơn co trong 10 phút. Khi rặn sổ, cường độ cơn co khoảng 47 mmHg, tần số 5 cơn co tử cung trong 10 phút, hoạt độ trong thời điểm này là khoảng 235 U.M.\nCơn co tử cung là động lực chính của cuộc đẻ và thường chịu ảnh hưởng bởi nhiều yếu tố:\n- Tình trạng sức khoẻ chung của sản phụ, thai nhi và phần phụ của thai nhi.\n- Các thuốc tăng co, giảm co sử dụng trong chuyển dạ.\n- Tư thế nằm ngửa, tần số cơn co tử cung thường tăng hơn tư thế nằm nghiêng, tuy nhiên cơn co tử cung thường mạnh hơn ở tư thế nghiêng.\nCơn co tử cung xuất phát từ 2 sừng tử cung, thường bắt đầu ở sừng phải, đi từ đáy tử cung xuống dưới, càng xuống dưới càng giảm về cường độ và biên độ. Khi có sự bất thường dẫn truyền cơn cothì dẫn đến rối loạn co bóp tử cung.\nVào thời điểm bắt đầu cuộc chuyển dạ trương lực cơ bản của cơ tử cung khoảng 8 mmHg, tăng lên khoảng 12 mmHg khi cổ tử cung mở hết. Trong trường hợp trương lực cơ tử cung tăng bất thường có thể làm chậm quá trình xoá mở cổ tử cung, gây nên đẻ khó. Tăng trương lực cơ tử cung thường xảy ra sau cơn co tử cung cường tính, tuy nhiên cũng có thể xuất hiện đơn lẻ.\nMột cuộc chuyển dạ tiến triển bình thường khi cơn co tử cung bình thường nghĩa là phải nhịp nhàng có lúc nghỉ, không mạnh quá và không yếu quá, trương lực của tử cung không cao, nhịp độ và cường độ của các cơn co ngày càng tăng, khoảng cách giữa hai cơn co ngày càng ngắn lại.\nCó 2 loại đẻ khó do rối loạn cơn co tử cung:\n- Đẻ khó do tăng trương lực cơ bản của tử cung (chú ý: loại này cũng đồng nghĩa với đẻ khó do cơn co tử cung tăng).\n- Đẻ khó do cơn co tử cung giảm.\n2.2. Đẻ khó do cơn co tử cung tăng\nKhi có sự tăng co bóp cơ tử cung quá mức bình thường tức là thời gian co dài hơn bình thường, cường độ cơn co mạnh hơn, khoảng cách giữa hai cơn co ngắn làm sản phụ kêu la, đau nhiều. Trong khi đó, trương lực cơ bản vẫn bình thường giữa các cơn co.\n2.2.1. Nguyên nhân\nThường gặp là nhóm nguyên nhân cơ học như:\n- Bất tương xứng giữa thai nhi và khung chậu.\n- Khối u tiền đạo.\n- Cổ tử cung khó mở (do viêm cổ tử cung, đốt cổ tử cung, phẫu thuật Manchester, khoét chóp cổ tử cung, sẹo cổ tử cung do rách cũ, phù nề cổ tử cung do thăm khám âm đạo nhiều lần trong chuyển dạ...)\n- Tử cung kém phát triển, tử cung xơ hoá (thường ở sản phụ lớn hơn 35 tuổi), dị dạng tử cung (tử cung đôi...)\n- Rau bong non\n- Đa ối, đa thai làm cho thể tích tử cung tăng lên bất thường.\n- Đoạn dưới tử cung kém phát triển.\n- Sử dụng thuốc tăng co tử cung không đúng chỉ định. (Oxytocin, Prostaglandin)\n- Các nguyên nhân về thần kinh, thay đổi tâm sinh lý người mẹ như tinh thần sản phụ không ổn định, lo lắng nhiều v.v.\n- Các nguyên nhân khác về thai và phần phụ thai như: thai to toàn bộ hoặc từng phần (não úng thuỷ), ngôi thai, kiểu thế thai thất thường, ối vỡ sớm, vỡ non làm giảm thể tích buồng tử cung.\n2.2.2. Hậu quả\n- Chuyển dạ đình trệ do cổ tử cung khó xoá mở.\n- Suy thai, nhất là sau khi ối vỡ vì áp lực cơn co tử cung sẽ tác động trực tiếp đến bánh rau và dây rốn, hơn nữa do cơn co tử cung tăng nên tuần hoàn mẹ - rau - thai bị suy giảm.\n- Vỡ tử cung nếu không xử trí kịp thời đặc biệt trên các sản phụ có vết mổ cũ, dị dạng tử cung, tử cung nhi dạng, con rạ (đẻ nhiều lần).\n2.2.3. Xử trí\n- Ngưng dùng thuốc tăng co (nếu đang dùng), điều chỉnh cơn go bằng các thuốc giảm co như Papavérin, Spasmavérin, Spasmalgin, Seduxen, Dolargan (Dolosal).\n- Mổ lấy thai nếu khung chậu hẹp hoặc bất tương xứng đầu chậu.\n- Liệu pháp tâm lý: động viên, giải thích để sản phụ yên tâm, nhất là các sản phụ hay lo lắng, suy nhược thần kinh. Nếu cần thiết thì sử dụng seduxen, dolargan.\n2.3. Đẻ khó do cơn co tử cung giảm\nCơn co tử cung giảm khi giảm cường độ, biên độ, tần số.\n2.3.1. Nguyên nhân\n- Nguyên phát: Sản phụ suy nhược, thiếu máu, thiếu nước, suy tim, lao phổi, tử cung kém phát triển, u xơ tử cung.\n- Thứ phát: Đa ối, đa thai, chuyển dạ kéo dài, ối vỡ sớm, nhiễm khuẩn ối, lạm dụng các thuốc giảm co vào giai đoạn đầu của chuyển dạ.\n2.3.2. Hậu quả\n- Chuyển dạ đình trệ.\n- Cổ tử cung phù nề, chậm tiến triển.\n- Nhiễm khuẩn ối.\n- Suy thai.\n2.3.3. Xử trí\n- Kháng sinh: nếu ối vỡ trên 6 giờ để đề phòng nhiễm khuẩn ối.\n- Tăng co: nếu ối đã vỡ trên 12 giờ bằng cách chuyền oxytocin 5 đơn vị hoà trong 500 ml dung dịch Glucoza 5%, tăng giảm số giọt tuỳ theo tình trạng cơn co. Nếu chỉ số Bishop > 6 điểm: hiệu quả tốt.\n- Bấm ối: nếu đa ối, đa thai để tạo cơn co tử cung.\n- Trong giai đoạn thai sổ, nếu cơn co tử cung thưa, yếu cần phối hợp thuốc tăng co hoặc hỗ trợ forceps, giác hút nếu có chỉ định và đủ điều kiện.\n\n3. ĐẺ KHÓ DO NGUYÊN NHÂN CƠ HỌC\nĐẻ khó do nguyên nhân cơ học nghĩa là tất cả những nguyên nhân gây cản trở quá trình lọt, xuống và sổ của thai.\n3.1. Nguyên nhân thuộc về người mẹ\n3.1.1. Khung chậu bất thường\nGọi là khung chậu bất thường khi một hoặc nhiều đường kính của khung chậu ngắn hơn bình thường. Trên lâm sàng người ta thường gặp:\n- Khung chậu hẹp\n+ Khung chậu có tất cả các đường kính đều giảm, bao gồm hai loại sau:\n* Khung chậu hẹp toàn bộ: Khi các đường kính giảm đều ở eo trên và eo dưới (đường kính nhô hậu vệ < 8,5 cm).\n* Xử trí: mổ lấy thai khi thai đủ tháng và có dấu hiệu chuyển dạ.\n+ Khung chậu giới hạn: Khi đường kính nhô hậu vệ từ 8,5 - 10 cm; nhưng trọng lượng thai bình thường có thể làm nghiệm pháp lọt ngôi chỏm, nếu diễn tiến thuận lợi thì đẻ đường âm đạo, ngược lại thì mổ lấy thai. Trường hợp ngôi chỏm mà thai to hoặc các ngôi bất lợi thì nên chỉ định mổ lấy thai khi có dấu hiệu chuyển dạ.\n- Khung chậu biến dạng\n+ Hẹp eo trên, hẹp eo dưới, hoặc khung chậu méo, bao gồm:\n+ Khung chậu hẹp eo trên: Khung chậu dẹt khi các đường kính ngang và đường kính chéo không thay đổi chỉ có đường kính trước sau ngắn hơn bình thường. Khung chậu dẹt có cột sống cong trước làm eo trên hẹp, eo dưới rộng, vì vậy nếu thai lọt được thì sổ sẽ dễ dàng.\n+ Chẩn đoán dựa vào đường kính nhô hậu vệ và thái độ xử trí tuỳ thuộc vào đường kính này.\n+ Khung chậu hẹp eo dưới: là loại khung chậu có cột sống cong sau, nguyên nhân do gù, lao cột sống, thương tổn cột sống ở thấp. Dạng khung chậu này hình phễu, thai sẽ lọt dễ dàng qua eo trên, nhưng khó hoặc không sổ được qua eo dưới dễ bị mắc kẹt trong tiểu khung. Chẩn đoán dựa vào đường kính lưỡng ụ ngồi, nếu đường kính này < 9 cm thì thai không sổ được.\n+ Thái độ xử trí: Cần tiên lượng sớm để có chỉ định mổ lấy thai, nếu thai nhỏ sổ được thì có thể phải cắt rộng tầng sinh môn.\n+ Khung chậu méo: còn gọi là khung chậu không đối xứng, do cột sống bị vẹo vì bệnh còi xương, sai khớp háng bẩm sinh một bên hay bị bại liệt. Việc chẩn đoán dựa vào hình trám Michaelis, dáng đi để định mức độ lệch. Hai đường kính chéo của eo trên dài ngắn khác biệt rõ rệt, nếu ngôi lọt hướng vào đường kính chéo lớn thì tiên lượng tốt.\n\nHinh 1. Khung chậu méo\n+ Thái độ xử trí: Dựa vào đường kính nhô hậu vệ. Nếu đường kính này bình thường, trọng lượng thai trung bình, chỏm hướng theo đường kính chéo lớn của eo trên thì ta có thể bấm ối làm nghiệm pháp lọt ngôi chỏm. Nếu tiến triển thuận lợi thì đẻ đường dưới, ngược lại thì mổ lấy thai. Các trường hợp khác đều có chỉ định mổ lấy thai khi có dấu chuyển dạ.\n3.1.2. Khối u tiền đạo\nĐây là các khối u nằm trong tiểu khung cản trở ngôi không lọt và không sổ được, thường gặp là khối u buồng trứng nằm ở túi cùng sau của âm đạo, u xơ ở eo hay ở cổ tử cung. Ngoài ra có các khối u tiền đạo khác ít gặp hơn như u âm đạo, u vòi trứng, u dây chằng rộng, u thận, u trực tràng, u bàng quang, tử cung đôi....\nXử trí: Mổ lấy thai và giải quyết khối u nếu u tiền đạo làm ngôi không lọt..\n3.1.3. Âm đạo chít hẹp, vách ngăn âm đạo\n- Âm đạo chít hẹp do bị  rách phức tạp trong những lần đẻ trước hoặc sau những cuộc mổ có liên quan đến âm đạo như mổ sa sinh dục, mổ rò bàng quang âm đạo, rò trực tràng âm đạo. Xử trí: Mổ lấy thai khi có dấu hiệu chuyển dạ.\n- Do dị tật bẩm sinh âm đạo có vách ngăn dọc, vách ngăn ngang.\nXử trí: Nếu đủ điều kiện đẻ đường dưới, cắt vách ngăn khi cổ tử cung mở hết, ngôi lọt thấp.\n3.2. Đẻ khó do thai\n3.2.1. Thai to toàn bộ\nThai to khi trọng lượng của thai > 4.000 gram (ở Châu Âu) hay > 3.500 gram ở Việt Nam, ở trường hợp này nếu khung chậu bình thường có thể làm nghiệm pháp lọt ngôi chỏm, nếu thất bại thì mổ lấy thai. Các ngôi khác có chỉ định mổ lấy thai khi chuyển dạ.\n3.2.2. Thai to từng phần\n- Đầu to: thường gặp não úng thuỷ. Chẩn đoán dựa vào khám âm đạo (các đường khớp của đầu thai nhi dãn rộng), siêu âm hoặc X quang.\nXử trí:\n+ Nếu não úng thuỷ to có thể chọc sọ để tháo bớt nước não tuỷ và sau đó huỷ thai qua đường âm đạo.\n+ Trường hợp não úng thuỷ nhỏ, thai nhi có thể sống thì chỉ định mổ lấy thai nếu không đẻ được đường dưới.\n- Vai to: gặp trong trường hợp thai to, thai vô sọ, mẹ bị đái tháo đường.\nXử trí: Nếu đầu đã sổ, có thể hạ tay theo thủ thuật Jacquemier.\n- Bụng to: thường gặp ở dị dạng bụng cóc do cổ chướng, thận đa nang, gan to, lách to. Tiên lượng khó sổ thai hoặc khi đã sổ đầu rồi thì bị mắc ở bụng.\nXử trí: chọc bụng hút dịch bụng báng, moi hết phủ tạng rồi sau đó kéo thai ra qua đường âm đạo.\n- Thai dính nhau trong sinh đôi: Gặp trong sinh đôi cùng một noãn, có thể dính lưng, dính bụng… Chỉ định mổ lấy thai.\n3.2.3. Đẻ khó do ngôi, thế, kiểu thể\n- Ngôi chỏm: Gặp trong ngôi chỏm kiểu thế sau. Một số trường hợp nếu ngôi sổ kiểu chẩm cùng sẽ gây sổ khó khăn. Xử trí: Cắt rộng tầng sinh môn hoặc hỗ trợ thủ thuật.\n- Ngôi mặt: Ngôi mặt chỉ sổ được theo kiểu cằm vệ, ngôi mặt cằm sau thì mổ lấy thai.\n- Ngôi trán: Đường kính trình diện trước eo trên thường là đường kính thượng chẩm - cằm (13,5 cm). Vì vậy thai đủ tháng sẽ không lọt được nên chỉ định mổ lấy thai.\n- Ngôi vai: đối với trường hợp đơn thai, không đẻ được đường dưới, chỉ định mổ lấy thai. Đối với thai thứ hai trong trường hợp song thai, nội xoay và đại kéo thai.\n- Ngôi mông: là ngôi đẻ khó, đặc biệt là thì sổ đầu. Các biến chứng thường gặp trong đẻ ngôi mông là mắc đầu hậu, sa dây rốn, suy thai, nên đa số các trường hợp cóchỉ định mổ lấy thai.\n3.2.4. Đa thai\n- Song thai cùng là ngôi đầu sẽ cản trở nhau, làm ngôi thai xuống chậm.ở giai đoạn chuẩn bị lọt, đầu sẽ không cúi tốt, phải mổ lấy thai.\n- Ngôi thứ nhất ngược, ngôi thứ 2 là ngôi đầu: Đầu của thai thứ nhất có thể vướng vào thai thứ 2 và không xuống được.\n- Hai thai dính nhau: mổ lấy thai.\n3.3. Đẻ khó do phần phụ của thai\n3.3.1. Rau tiền đạo\nRau tiền đạo bán trung tâm hay trung tâm hoàn toàn phải mổ cấp cứu vì chảy máu và không đẻ được đường âm đạo. Đối với những trường hợp khác có thể bấm ối để giảm bớt sự chảy máu, nếu sau khi bấm ối, máu không cầm được thì phải mổ lấy thai.\n3.3.2. Dây rốn\n- Sa dây rốn: Chỉ định mổ lấy thai, khi thai còn sống.\n- Dây rốn ngắn: Thường gặp do dây rốn quấn cổ nhiều vòng gây ngôi bất thường, ngôi không lọt được.\n3.3.3. Đa ối và thiểu ối\n- Trong đa ối phần lớn thai bình chỉnh không tốt và tử cung quá căng làm cho cơn co tử cung bị rối loạn, một số trường hợp ối vỡ đột ngột làm ngôi thai trở thành ngôi vai, sa dây rốn, gây ra đẻ khó. Các nguyên nhân này làm tăng chỉ định mổ lấy thai.\n- Trường hợp thiểu ối: ảnh hưởng tới quá trình trao đổi oxy của thai nhi,  thai bình chỉnh không tốt, gây đẻ khó, chỉ định mổ lấy thai.\nCâu hỏi:\n1. Trình bày các nguyên nhân, hậu quả và cách xử trí các trường hợp đẻ khó do cơn co tử cung?\n2. Trình bày các nguyên nhân, hậu quả và cách xử trí các trường hợp đẻ khó do các nguyên nhân cơ giới?", "priority": "Cao (Trọng tâm BSNT)"}, {"id": "SK-20", "chapter": "Chương 2. Sản bệnh", "folder": "02_San_benh", "title": "Ngôi mặt, ngôi trán, ngôi thóp trước, ngôi vai", "author": "Ths. Đinh Văn Hoành", "word_count": 3233, "line_count": 155, "key_numbers": ["12 cm", "13,5 cm", "13,5cm", "15 cm", "2500g", "9 cm", "9,5 cm"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["NGÔI MẶT, NGÔI TRÁN", "NGÔI THÓP TRƯỚC, NGÔI VAI", "Ths. Đinh Văn Hoành"], "bullets": []}, {"heading": "3. Lựa chọn hướng xử trí thích hợp cho từng loại ngôi.", "paragraphs": ["Khác với ngôi chỏm là ngôi mà đầu cúi tốt, ngôi mặt, ngôi trán và ngôi thóp trước là những ngôi đầu ngửa hoặc cúi không tốt. Nguyên nhân thường gặp của các ngôi này thường do sự bất tương xứng đầu - chậu. Việc chẩn đoán sớm các ngôi bất thường có ý nghĩa quan trọng cho mẹ và cho thai. Trong quá trình chuyển dạ ngôi mặt, ngôi thóp trước có thể tiến triển và có thể đẻ được qua đường âm đạo, ngôi trán và ngôi vai phải mổ lấy thai ngay"], "bullets": []}, {"heading": "1.1. Định nghĩa", "paragraphs": ["Ngôi mặt là ngôi đầu ngửa tối đa, mặt trình diện trước eo trên, vùng chỏm dựa vào lưng thai nhi. Mốc của ngôi mặt là cằm, ngôi mặt kiểu cằm trước đẻ tương đối dễ hơn ngôi mặt cằm sau. Tỷ lệ ngôi mặt 1 - 3/1000 cuộc đẻ. Tiên lượng một cuộc đẻ ngôi mặt ít thuận lợi hơn so với ngôi chỏm."], "bullets": []}, {"heading": "1.2. Nguyên nhân", "paragraphs": ["Các yếu tố thuận lợi cho ngôi mặt có thể là do mẹ, do thai, do phần phụ của thai."], "bullets": ["- Về phía mẹ : Do dị dạng tử cung, tử cung 2 sừng, tử cung lệch hay đổ trước, có u xơ tử cung ở eo hoặc tử cung nhão ở người con rạ đẻ nhiều lần", "- Về phía thai: Thai to, đầu to, u ở cổ, thai vô sọ, cột sống bị gù.", "- Phần phụ: Rau tiền đạo, đa ối, dây rau quấn cổ."]}, {"heading": "1.3. Cơ chế đẻ", "paragraphs": ["Người ta phân biệt ngôi mặt nguyên phát là ngôi có từ trước khi chuyển dạ và ngôi mặt thứ phát xảy ra khi đã chuyển dạ. Đa số ngôi mặt là thứ phát cho nên có tác giả cho rằng ngôi mặt là ngôi xảy ra trong chuyển dạ.", "Trong đẻ ngôi mặt, ngôi thai bình chỉnh không tốt, ối dễ vỡ, cổ tử cung xoá mở chậm, chuyển dạ kéo dài. Mốc của ngôi mặt là cằm, đường kính lọt là hạ cằm - thóp trước 9,5 cm."], "bullets": []}, {"heading": "1.3.1.Thì lọt", "paragraphs": ["Mặt trình diện toàn bộ ở eo trên, lọt luôn là đối xứng, trung tâm của ngôi tương ứng với trung tâm của eo trên. Kiểu cằm chậu trái trước gặp nhiều hơn cằm chậu phải trước: Lọt sẽ xảy ra không khó khăn vì đường kính lọt hạ cằm thóp trước 9,5 cm, đường kính lưỡng gò má 8,5 - 9 cm lọt dễ dàng qua eo trên."], "bullets": []}, {"heading": "1.3.2. Thì xuống và quay", "paragraphs": ["Đây là thì quyết định có khả năng đẻ được đường dưới hay không, điều này tuỳ thuộc vào sự tiến triển thuận lợi hay ngừng tiến triển. Sự tiến triển ngôi thai phụ thuộc hoàn toàn vào hướng quay của đầu.", "Đối với kiểu thế sau đầu quay 1350 ra trước, với kiểu thế trước đầu quay 450 để lựa theo đường kính trước sau của eo dưới, cằm hướng tới khớp mu. Hiện tượng xuống tiếp diễn và mỏm cằm thoát khỏi bờ dưới khớp mu rồi đầu cúi từ từ để sổ ra.", "Kiểu cằm sau lọt khó vì đầu khó ngửa hẳn, cằm bị đưa vào hõm của xương cùng, cổ không uốn dài được. Muốn cho ngôi xuống, tiểu khung phải tiếp nhận đường kính ức - thóp trước của thai nhi là 15 cm. Do đó một khung chậu bình thường không thể thích ứng với một thai nhi bình thường, và cuộc đẻ trong kiểu thế cằm sau thông thường giải quyết bằng mổ lấy thai."], "bullets": ["-  Đầu quay về phía trước:", "-  Đầu quay về phía sau:"]}, {"heading": "1.3.3. Thì sổ", "paragraphs": [], "bullets": ["-  Chỉ xảy ra đối với kiểu thế trước. Cắm xuống tới khớp mu, cổ ưỡn dài để cằm tới bờ dưới khớp mu và cố định ở đó. Đầu bắt đầu cúi để dần dần sổ miệng, mũi, thóp trước rồi đến trán và cuối cùng là thượng  chẩm. Như vậy đường kính thượng chẩm cằm 13,5 cm sổ cuối cùng, nên khi thai sổ dễ bị rách tầng sinh môn, cần cắt rộng tầng sinh môn tránh tổn thương phức tạp.", "-  Ở kiểu thế sau, ngôi không xuống được và không lọt được, cuộc đẻ sẽ bị ngừng lại vì ngôi mắc kẹt trong tiểu khung."]}, {"heading": "1.4.1Trong khi có thai:", "paragraphs": ["Thăm khám ngoài cho dấu hiệu gợi ý đầu ngửa."], "bullets": ["-  Nếu kiểu cằm sau: Nắn thấy bướu chẩm to, tròn, rắn, giữa bướu chẩm và lưng có rãnh gáy gọi là dấu hiệu nhát rìu.", "-  Nếu kiểu cằm trước nắn dễ thấy chân tay, cằm hình móng ngựa rõ, khó thấy lưng, bướu chẩm và rãnh gáy."]}, {"heading": "1.4.1 Khi chuyển dạ", "paragraphs": ["Khám ngoài như chưa chuyển dạ nhưng khó hơn vì tử cung đã có cơn co, khó nắn thấy dấu hiệu nhát rìu.", "Thăm âm đạo: Phải thăm khám nhẹ nhàng, tránh chấn thương mặt, nhãn cầu. Trong ngôi mặt luôn sờ thấy mũi, thậm chí con sờ thấy bướu huyết thanh nằm đối diện với cằm. Cằm cứng hình móng ngựa, không bao giờ sờ thấy thóp trước.", "Cằm  chậu  trái  trước: \t20%", "Cằm  chậu  phải  sau: \t30%", "Cằm  chậu  phải  trước: \t27%", "Cằm  chậu  phải  sau: \t10%."], "bullets": ["- Khi ối chưa vỡ: Đầu ối phồng, ngôi cao, khó xác định chẩn đoán. Phải thăm khám cẩn thận, tránh làm ối vỡ dễ sa dây rốn.", "- Khi ối đã vỡ, cổ tử cung xoá mở rộng sờ thấy vòm mặt, sống mũi, hai hố mắt, lỗ mũi, hàm trên, miệng, hàm dưới. Nếu ối vỡ đã lâu, mặt phù nề, có thể nhầm với ngôi mông nhưng có thể phân biệt được vì hậu môn và hai ụ ngồi luôn luôn thẳng hàng trong khi miệng và hai xương gò má thì ở 3 điểm tạo thành các góc của một tam giác. Cũng cần phân biệt với ngôi trán, nhưng ngôi trán không sờ thấy cằm.", "- Trường hợp thai vô sọ thường sổ bằng ngôi mặt, nhưng trong ngôi mặt ở thai vô sọ không sờ thấy bướu chẩm, X quang không thấy hộp sọ.", "- Kiểu thế của ngôi được xác định bởi vị trí cằm :", "- Trường hợp nghi ngờ nên cho siêu âm hoặc chụp X quang để xác định chẩn đoán và loại trừ thai dị dạng."]}, {"heading": "1.5.1 Tuyến xã", "paragraphs": ["Tư vấn cho sản phụ và gia đình rồi chuyển lên tuyến trên."], "bullets": []}, {"heading": "1.5.2. Tuyến huyện và các tuyến trên", "paragraphs": ["Dựa vào nguyên tắc:"], "bullets": ["- Nếu khung chậu bình thường, cằm sau chưa cố định, vẫn có thể hy vọng cho sinh tự nhiên được vì 2 / 3 các trường hợp cằm sau sẽ tự xoay thành cằm trước.", "- Hướng quay của đầu: Chỉ đẻ đường âm đạo khi cằm quay về phía trước, dưới khớp mu, phải theo dõi sát vì sự  quay của cằm sau ra trước rất lâu. Chuyển dạ kéo dài, lọt giả, ngôi thai không tiến triển, thường gặp trong kiểu cằm quay về phía sau còn gọi là cằm  cùng, cằm cùng không thể đẻ được phải mổ lấy thai. Thai có nguy cơ bởi có thể sa dây rốn, chèn ép dây rốn giữa chẩm và lưng, giảm tuần hoàn rốn.", "- Sổ thai: Cằm, miệng, mũi, trán, thóp trước, xuất hiện ở âm hộ, rồi đến hạ chẩm. Trong thì này phải kiểm soát kỹ các phần thai nhi sổ vì dễ gây rách tầng sinh môn."]}, {"heading": "2.1. Đại cương", "paragraphs": ["Ngôi trán là ngôi mà phần trán trình diện trước eo trên, tỷ lệ 1 / 1000 trường hợp. Là ngôi trung gian giữa ngôi chỏm và ngôi mặt. Vì đường kính của ngôi là thượng chẩm - cằm 13,5 cm không thể lọt qua đường kính chéo của eo trên 12 cm nên ngôi trán không  đẻ được đường âm đạo. Chẩn đoán càng sớm càng cho phép đặt ra chỉ định mổ lấy thai để tránh tất cả các biến chứng cho mẹ và thai."], "bullets": []}, {"heading": "2.2. Cơ chế đẻ", "paragraphs": ["Mặc dù ngôi trán là ngôi đẻ khó thường phải mổ lấy thai khi thai nhi đủ tháng, tuy nhiên cũng có những trường hợp có thể đẻ được nếu thai quá nhỏ. Do đó, có hai tình huống cần phân biệt rõ:"], "bullets": []}, {"heading": "2.2.1. Chuyển dạ thai đủ tháng, trọng lượng thai bình thường", "paragraphs": ["Đầu cao, đường kính lọt của ngôi là thượng chẩm cằm 13,5cm không lọt được, do đó phải mổ lấy thai"], "bullets": []}, {"heading": "2.2.2. Đối với một thai non tháng hoặc trọng lượng thai nhỏ", "paragraphs": ["Đây là một tình huống đặc biệt, có thể đẻ đường âm đạo. Thường chỉ gặp khi trọng lượng thai quá nhỏ, trong song thai hoặc thai non tháng. Không bao giờ quên rằng đây là một cuộc đẻ khó, phải theo dõi cẩn thận.", "Đầu lọt theo đường kính ngang hoặc chéo. Đầu thai nhi giảm thể tích bằng các hiện tượng chồng các xương của sọ, thường xuất hiện bướu huyết thanh sớm, trán dài theo khung chậu nhỏ, trong khi chẩm dài về phía lưng.", "Ngôi xuống chậm và khó, trán thường quay ra trước. Mặt thai nhi nằm dưới xương vệ, cằm trên của thai nhi đối diện với bờ dưới xương vệ. Chẩm nằm dọc mặt trước xương cùng. Trục của đầu thai nhi nằm trên trục trước - sau của eo trên.", "Khi chẩm thai nhi sổ, tầng sinh môn dãn rộng nên chỉ định  cắt tầng sinh môn để tránh rách và sang chấn cho trẻ."], "bullets": ["- Thì lọt:", "- Thì xuống và quay", "- Thì sổ:", "+ Thì sổ được thực hiện như ngôi mặt cằm trước:", "+ Đầu cúi để cho phần đầu của thai nhi đi từ mũi đến hạ chẩm xuất hiện ở âm hộ", "+ Đầu ngửa: Hạ chẩm cố định vào âm hộ, đầu ngửa để cho miệng và cằm sổ"]}, {"heading": "2.3.1. Khám lâm sàng", "paragraphs": ["Ngôi trán là ngôi chỉ xảy ra trong thời kỳ chuyển dạ nên chỉ chẩn đoán được trong thời kỳ chuyển dạ.", "Thăm âm đạo có thể thấy:"], "bullets": ["- Nhìn: Tử cung hình trứng tương ứng với một ngôi dọc, đầu ở dưới.", "- Nắn: Nắn ngoài thấy đầu cao, cúi không tốt, ở một bên là bướu chẩm tròn đều, có rãnh gáy. Đôi khi sờ thấy cằm phía đối diện biểu hiện sự ngửa của đầu.", "- Thăm âm đạo: Người ta chỉ có thể chẩn đoán được ngôi trán khi ngôi đã cố định. Tất cả các ngôi còn di động về sau có thể cúi tốt hơn để trở thành ngôi chỏm.", "- Điểm mốc của ngôi là gốc mũi không bao giờ bị biến dạng bởi bướu huyết thanh, mỗi bên có gờ trên hố mắt và nhãn cầu. Các dấu hiệu âm tính rất quan trọng để chẩn đoán gián biệt với các ngôi khác. Trong ngôi trán có thể sờ thấy gốc mũi và thóp trước, nhưng không bao giờ sờ thấy thóp sau cũng như không sờ thấy miệng và cằm.", "- Thóp trước với 4 cạnh và 4 góc của nó (Hình trám)", "- Để xác định kiểu thế của ngôi dựa vào vị trí gốc mũi nằm ở phía nào so với khung chậu của người mẹ:", "+ Mũi chậu trái trước và mũi chậu phải sau đối với đường kính chéo trái.", "+ Mũi chậu phải trước và mũi chậu trái sau đối với đường kính chéo phải.", "+ Mũi chậu trái ngang và mũi chậu phải ngang đối với đường kính ngang."]}, {"heading": "2.3.2. Cận lâm sàng", "paragraphs": ["Chụp X quang và siêu âm có hai ưu điểm:"], "bullets": ["-  Chẩn đoán có thể đặt ra sớm khi thấy đầu ngửa và sự tăng ưỡn cột sống cổ.", "-  Loại trừ các bất thường của thai (Quái thai vô sọ, não úng thuỷ)"]}, {"heading": "2.4. Thái độ xử trí", "paragraphs": ["Khi đã xác định là ngôi trán các bước xử trí như sau:"], "bullets": []}, {"heading": "2.4.1.Tuyến xã", "paragraphs": ["Theo dõi sát các cuộc chuyển dạ đẻ ngôi thuận để phát hiện sớm, đặc biệt lá các trường hợp ngôi cao, không lọt, chuyển dạ kéo dài. Nếu chẩn đoán là ngôi trán cần chuyển lên tuyến trên ngay."], "bullets": []}, {"heading": "2.4.2. Tuyến huyện và các tuyến trên", "paragraphs": ["Các bước xử trí như sau:"], "bullets": ["-   Khi ối chưa vỡ, ngôi cao lỏng nên chờ đợi xem sự tiến triển của ngôi:", "+ Nếu tiến triển không thuận lợi, ngôi không lọt được, chuyển dạ kéo dài, chỉ định mổ lấy thai ngay.", "+  Nếu tiến triển thuận lợi, ngôi có tự biến thành ngôi chỏm hoặc ngôi mặt trong lúc chuyển dạ. Có thể đẻ đường âm đạo", "- Khi màng ối đã vỡ, ngôi trán đã cố định, mổ lấy thai ngay."]}, {"heading": "3.1. Đại cương", "paragraphs": ["Ngôi thóp trước là một ngôi đầu ngửa nhẹ, trung gian giữa ngôi trán và chỏm. Trong ngôi thóp trước, không thể sờ được thóp sau khi khám. Trong khi ngôi chỏm kiểu chẩm cùng, thóp sau luôn sờ được.", "Hình 1. Ngôi thóp trước"], "bullets": []}, {"heading": "3.2. Cơ chế đẻ", "paragraphs": ["Lọt có thể xảy ra nhờ đầu cúi tốt, chuyển ngôi thóp trước thành ngôi chỏm. Nếu không lọt, sự xuống và quay của ngôi rất khó khăn. Đường kính lọt của ngôi là đường kính  chẩm - trán:12 cm. Sự biến dạng của đầu và bướu huyết thanh thường xuất hiện sớm và trầm trọng. Khi đó việc xác định ngôi gặp nhiều khó khăn. Đầu thai nhi cũng sổ bằng phép quay dạng chữ S., điểm trục được tạo bởi xương vệ và gốc mũi. Đầu cúi cho phép sổ trán, thóp trước, chẩm và hạ chẩm đến cố định vào đáy chậu, rồi đầu ngửa cho mũi miệng, cằm sổ."], "bullets": []}, {"heading": "3.3. Lâm sàng", "paragraphs": [], "bullets": ["-  Khám ngoài: ít có giá trị.", "- Thăm khám âm đạo: Sờ được thóp trước, điểm mốc của ngôi trình diện ở trung tâm, gốc mũi có thể sờ thấy nhưng ở ngoại vi và không ở trung tâm như trong ngôi trán. Vị trí của thóp trước xác định kiểu thế của ngôi, phải hoặc trái, trước hoặc sau. Kiểu thế trước thường gặp nhất >80%."]}, {"heading": "3.4. Thái độ xử trí", "paragraphs": ["Nếu tiến triển không thuận lợi: Ngôi không lọt hoặc lọt giả phải mổ lấy thai.", "Phần lớn các trường hợp tiến triển thuận lợi. Thời gian chuyển dạ và sổ thai thường kéo dài, tỷ lệ can thiệp trong thời kỳ sổ thai cao."], "bullets": []}, {"heading": "4.1. Đại cương", "paragraphs": ["Ngôi vai (hay còn gọi là ngôi ngang) là một ngôi không thuận, ngôi thai không nằm dọc theo trục tử cung mà nằm ngang hoặc chếch. Mốc của ngôi là mỏm vai. Tỷ lệ ngôi vai khoảng 0,3 - 0,5%.", "Nguyên nhân: Ngôi vai thường hay gặp ở những sản phụ đẻ con rạ hơn là con so và hay gặp ở chuyển dạ thiếu tháng hơn là đủ tháng.", "Bất luận một nguyên nhân nào cản trở đầu thai lọt vào khung chậu đều dễ gây ra ngôi vai. Tương tự như các ngôi không thuận khác,  song thai, đa ối, rau tiền đạo, khung chậu hẹp, hình dạng thai bất thường, tử cung dị dạng là những nguyên nhân thường gặp, tuy nhiên nguyên nhân hay gặp nhất là do cơ tử cung, cơ thành bụng nhão  ở người con rạ đẻ nhiều lần.", "Kiểu ngôi là ngang hoặc chếch, ngôi chếch chỉ là ngôi tạm thời, nó sẽ biến thành ngôi dọc hay ngôi ngang vào lúc chuyển dạ nên còn gọi là ngôi không cố định.", "Hình 2. Ngôi vai."], "bullets": []}, {"heading": "4.2. Triệu chứng và chẩn đoán", "paragraphs": ["Cần phát hiện ngôi vai sớm ngay từ cuối thai kỳ hay ngay từ đầu thời kỳ chuyển dạ.", "Hình 3. Bốn thủ thuật trong khám ngôi vai.", "Thăm âm đạo phát hiện thấy một hố chậu rỗng, và một phần thai trình diện không bình thường. Vai có thể tưởng nhầm với mông, song các xương sườn tạo nên một cảm giác đặc biệt.", "Nếu chuyển dạ đã lâu, một vai sẽ lọt chặt vào tiểu khung và thường đi kèm với sa  một cánh tay vào âm đạo, thò ra ngoài âm hộ gọi là ngôi vai sa tay.", "Dựa theo vị trí của vai người ta có thể phân biệt:"], "bullets": ["- Nhìn: Bụng bè ngang, đáy tử cung như nằm gần rốn.", "- Sờ nắn:", "+ Không thấy cực thai ở phần thấp của tử cung mà lại sờ được 2 cực ở 2 hố hông.", "+ Nắn trên xương vệ không thấy gì trừ khi chuyển dạ lâu, vai đã lọt vào trong tiểu khung. Phải xác định thêm xem lưng ở đâu. Nếu lưng trước sờ thấy diện phẳng, nếu lưng sau sờ thấy chân tay lổn nhổn. Thường lưng luôn ở trước.", "- Thăm âm đạo:", "+ Vai chậu phải", "+ Vai chậu trái", "- Cận lâm sàng: Chụp Xquang và siêu âm  có thể xác định khi có nghi ngờ trong chẩn đoán cũng như chọn lựa hướng xử trí thích hợp."]}, {"heading": "4.3.1. Tuyến xã", "paragraphs": ["Khám và phát hiện sớm các trường hợp ngôi vai.", "Tư vấn cho sản phụ và chuyển lên tuyến trên. Trường hợp ối đã vỡ cần sử dụng các thuốc giảm go và kháng sinh dự phòng trước khi chuyển"], "bullets": []}, {"heading": "4.3.2. Tuyến huyện và các tuyến trên", "paragraphs": ["Ở người con so, đứng trước một trường hợp ngôi vai phải nghĩ đến nguyên nhân có thể là khung chậu hẹp. Tất cả con so khung chậu hẹp hay bình thường mà lúc chuyển dạ còn giữ ngôi vai đều phải mổ lấy thai. Không tiến hành thủ thuật xoay thai, kéo thai.", "Nếu thai nhi đã chết, cổ tử cung mở hết, có thể dùng dụng cụ cắt thai  trong ngôi vai buông trôi, tuy nhiên thủ thuật này cũng rất nguy hiểm cho mẹ vì vậy nếu không có kinh nghiệm vẫn nên mổ lấy thai."], "bullets": ["-  Nếu ngôi vai, ối đã vỡ chỉ định mổ lấy thai ngay.", "- Chỉ định nội xoay thai:  Ở người con rạ, có thể tiến hành nội xoay thai trong trường hợp  thai nhi nhỏ < 2500g, thai thứ hai trong song thai  giúp đầu quay và xuống được tiểu khung, chuyển dạ có thể tiến triển bình thường. Tuy nhiên chỉ tiến hành ở nơi có phòng mổ và khi có đủ điều kiện: khung chậu rộng rãi, thai con rạ, ối còn nguyên, cơn co thưa, và cổ tử cung mở hết."]}, {"heading": "Câu hỏi:", "paragraphs": ["1: Nêu triệu chứng, chẩn đoán xác định, chẩn đoán phân biệt ngôi vai?", "2: Nêu triệu chứng, chẩn đoán  xác định, chẩn đoán phân biệt ngôi trán? hướng xử trí?", "3: Nêu triệu chứng lâm sàng chẩn đoán xác định ngôi mặt?"], "bullets": []}], "raw_text": "NGÔI MẶT, NGÔI TRÁN\nNGÔI THÓP TRƯỚC, NGÔI VAI\nThs. Đinh Văn Hoành\nMục tiêu học tập\n1. Kể được các nguyên nhân gây nên ngôi bất thường.\n2. Mô tả được các triệu chứng và chẩn đoán ngôi bất thường\n3. Lựa chọn hướng xử trí thích hợp cho từng loại ngôi.\nKhác với ngôi chỏm là ngôi mà đầu cúi tốt, ngôi mặt, ngôi trán và ngôi thóp trước là những ngôi đầu ngửa hoặc cúi không tốt. Nguyên nhân thường gặp của các ngôi này thường do sự bất tương xứng đầu - chậu. Việc chẩn đoán sớm các ngôi bất thường có ý nghĩa quan trọng cho mẹ và cho thai. Trong quá trình chuyển dạ ngôi mặt, ngôi thóp trước có thể tiến triển và có thể đẻ được qua đường âm đạo, ngôi trán và ngôi vai phải mổ lấy thai ngay\n\n1. NGÔI MẶT\n1.1. Định nghĩa\nNgôi mặt là ngôi đầu ngửa tối đa, mặt trình diện trước eo trên, vùng chỏm dựa vào lưng thai nhi. Mốc của ngôi mặt là cằm, ngôi mặt kiểu cằm trước đẻ tương đối dễ hơn ngôi mặt cằm sau. Tỷ lệ ngôi mặt 1 - 3/1000 cuộc đẻ. Tiên lượng một cuộc đẻ ngôi mặt ít thuận lợi hơn so với ngôi chỏm.\n1.2. Nguyên nhân\nCác yếu tố thuận lợi cho ngôi mặt có thể là do mẹ, do thai, do phần phụ của thai.\n- Về phía mẹ : Do dị dạng tử cung, tử cung 2 sừng, tử cung lệch hay đổ trước, có u xơ tử cung ở eo hoặc tử cung nhão ở người con rạ đẻ nhiều lần\n- Về phía thai: Thai to, đầu to, u ở cổ, thai vô sọ, cột sống bị gù.\n- Phần phụ: Rau tiền đạo, đa ối, dây rau quấn cổ.\n1.3. Cơ chế đẻ\nNgười ta phân biệt ngôi mặt nguyên phát là ngôi có từ trước khi chuyển dạ và ngôi mặt thứ phát xảy ra khi đã chuyển dạ. Đa số ngôi mặt là thứ phát cho nên có tác giả cho rằng ngôi mặt là ngôi xảy ra trong chuyển dạ.\nTrong đẻ ngôi mặt, ngôi thai bình chỉnh không tốt, ối dễ vỡ, cổ tử cung xoá mở chậm, chuyển dạ kéo dài. Mốc của ngôi mặt là cằm, đường kính lọt là hạ cằm - thóp trước 9,5 cm.\n1.3.1.Thì lọt\nMặt trình diện toàn bộ ở eo trên, lọt luôn là đối xứng, trung tâm của ngôi tương ứng với trung tâm của eo trên. Kiểu cằm chậu trái trước gặp nhiều hơn cằm chậu phải trước: Lọt sẽ xảy ra không khó khăn vì đường kính lọt hạ cằm thóp trước 9,5 cm, đường kính lưỡng gò má 8,5 - 9 cm lọt dễ dàng qua eo trên.\n1.3.2. Thì xuống và quay\nĐây là thì quyết định có khả năng đẻ được đường dưới hay không, điều này tuỳ thuộc vào sự tiến triển thuận lợi hay ngừng tiến triển. Sự tiến triển ngôi thai phụ thuộc hoàn toàn vào hướng quay của đầu.\n-  Đầu quay về phía trước:\nĐối với kiểu thế sau đầu quay 1350 ra trước, với kiểu thế trước đầu quay 450 để lựa theo đường kính trước sau của eo dưới, cằm hướng tới khớp mu. Hiện tượng xuống tiếp diễn và mỏm cằm thoát khỏi bờ dưới khớp mu rồi đầu cúi từ từ để sổ ra.\n-  Đầu quay về phía sau:\nKiểu cằm sau lọt khó vì đầu khó ngửa hẳn, cằm bị đưa vào hõm của xương cùng, cổ không uốn dài được. Muốn cho ngôi xuống, tiểu khung phải tiếp nhận đường kính ức - thóp trước của thai nhi là 15 cm. Do đó một khung chậu bình thường không thể thích ứng với một thai nhi bình thường, và cuộc đẻ trong kiểu thế cằm sau thông thường giải quyết bằng mổ lấy thai.\n1.3.3. Thì sổ\n-  Chỉ xảy ra đối với kiểu thế trước. Cắm xuống tới khớp mu, cổ ưỡn dài để cằm tới bờ dưới khớp mu và cố định ở đó. Đầu bắt đầu cúi để dần dần sổ miệng, mũi, thóp trước rồi đến trán và cuối cùng là thượng  chẩm. Như vậy đường kính thượng chẩm cằm 13,5 cm sổ cuối cùng, nên khi thai sổ dễ bị rách tầng sinh môn, cần cắt rộng tầng sinh môn tránh tổn thương phức tạp.\n-  Ở kiểu thế sau, ngôi không xuống được và không lọt được, cuộc đẻ sẽ bị ngừng lại vì ngôi mắc kẹt trong tiểu khung.\n1.4. Triệu chứng và chẩn đoán\n1.4.1Trong khi có thai:\nThăm khám ngoài cho dấu hiệu gợi ý đầu ngửa.\n-  Nếu kiểu cằm sau: Nắn thấy bướu chẩm to, tròn, rắn, giữa bướu chẩm và lưng có rãnh gáy gọi là dấu hiệu nhát rìu.\n-  Nếu kiểu cằm trước nắn dễ thấy chân tay, cằm hình móng ngựa rõ, khó thấy lưng, bướu chẩm và rãnh gáy.\n1.4.1 Khi chuyển dạ\nKhám ngoài như chưa chuyển dạ nhưng khó hơn vì tử cung đã có cơn co, khó nắn thấy dấu hiệu nhát rìu.\nThăm âm đạo: Phải thăm khám nhẹ nhàng, tránh chấn thương mặt, nhãn cầu. Trong ngôi mặt luôn sờ thấy mũi, thậm chí con sờ thấy bướu huyết thanh nằm đối diện với cằm. Cằm cứng hình móng ngựa, không bao giờ sờ thấy thóp trước.\n- Khi ối chưa vỡ: Đầu ối phồng, ngôi cao, khó xác định chẩn đoán. Phải thăm khám cẩn thận, tránh làm ối vỡ dễ sa dây rốn.\n- Khi ối đã vỡ, cổ tử cung xoá mở rộng sờ thấy vòm mặt, sống mũi, hai hố mắt, lỗ mũi, hàm trên, miệng, hàm dưới. Nếu ối vỡ đã lâu, mặt phù nề, có thể nhầm với ngôi mông nhưng có thể phân biệt được vì hậu môn và hai ụ ngồi luôn luôn thẳng hàng trong khi miệng và hai xương gò má thì ở 3 điểm tạo thành các góc của một tam giác. Cũng cần phân biệt với ngôi trán, nhưng ngôi trán không sờ thấy cằm.\n- Trường hợp thai vô sọ thường sổ bằng ngôi mặt, nhưng trong ngôi mặt ở thai vô sọ không sờ thấy bướu chẩm, X quang không thấy hộp sọ.\n- Kiểu thế của ngôi được xác định bởi vị trí cằm :\nCằm  chậu  trái  trước: \t20%\nCằm  chậu  phải  sau: \t30%\nCằm  chậu  phải  trước: \t27%\nCằm  chậu  phải  sau: \t10%.\n- Trường hợp nghi ngờ nên cho siêu âm hoặc chụp X quang để xác định chẩn đoán và loại trừ thai dị dạng.\n1.5. Thái độ xử trí\n1.5.1 Tuyến xã\nTư vấn cho sản phụ và gia đình rồi chuyển lên tuyến trên.\n1.5.2. Tuyến huyện và các tuyến trên\nDựa vào nguyên tắc:\n- Nếu khung chậu bình thường, cằm sau chưa cố định, vẫn có thể hy vọng cho sinh tự nhiên được vì 2 / 3 các trường hợp cằm sau sẽ tự xoay thành cằm trước.\n- Hướng quay của đầu: Chỉ đẻ đường âm đạo khi cằm quay về phía trước, dưới khớp mu, phải theo dõi sát vì sự  quay của cằm sau ra trước rất lâu. Chuyển dạ kéo dài, lọt giả, ngôi thai không tiến triển, thường gặp trong kiểu cằm quay về phía sau còn gọi là cằm  cùng, cằm cùng không thể đẻ được phải mổ lấy thai. Thai có nguy cơ bởi có thể sa dây rốn, chèn ép dây rốn giữa chẩm và lưng, giảm tuần hoàn rốn.\n- Sổ thai: Cằm, miệng, mũi, trán, thóp trước, xuất hiện ở âm hộ, rồi đến hạ chẩm. Trong thì này phải kiểm soát kỹ các phần thai nhi sổ vì dễ gây rách tầng sinh môn.\n2. NGÔI TRÁN\n2.1. Đại cương\nNgôi trán là ngôi mà phần trán trình diện trước eo trên, tỷ lệ 1 / 1000 trường hợp. Là ngôi trung gian giữa ngôi chỏm và ngôi mặt. Vì đường kính của ngôi là thượng chẩm - cằm 13,5 cm không thể lọt qua đường kính chéo của eo trên 12 cm nên ngôi trán không  đẻ được đường âm đạo. Chẩn đoán càng sớm càng cho phép đặt ra chỉ định mổ lấy thai để tránh tất cả các biến chứng cho mẹ và thai.\n2.2. Cơ chế đẻ\nMặc dù ngôi trán là ngôi đẻ khó thường phải mổ lấy thai khi thai nhi đủ tháng, tuy nhiên cũng có những trường hợp có thể đẻ được nếu thai quá nhỏ. Do đó, có hai tình huống cần phân biệt rõ:\n2.2.1. Chuyển dạ thai đủ tháng, trọng lượng thai bình thường\nĐầu cao, đường kính lọt của ngôi là thượng chẩm cằm 13,5cm không lọt được, do đó phải mổ lấy thai\n2.2.2. Đối với một thai non tháng hoặc trọng lượng thai nhỏ\nĐây là một tình huống đặc biệt, có thể đẻ đường âm đạo. Thường chỉ gặp khi trọng lượng thai quá nhỏ, trong song thai hoặc thai non tháng. Không bao giờ quên rằng đây là một cuộc đẻ khó, phải theo dõi cẩn thận.\n- Thì lọt:\nĐầu lọt theo đường kính ngang hoặc chéo. Đầu thai nhi giảm thể tích bằng các hiện tượng chồng các xương của sọ, thường xuất hiện bướu huyết thanh sớm, trán dài theo khung chậu nhỏ, trong khi chẩm dài về phía lưng.\n- Thì xuống và quay\nNgôi xuống chậm và khó, trán thường quay ra trước. Mặt thai nhi nằm dưới xương vệ, cằm trên của thai nhi đối diện với bờ dưới xương vệ. Chẩm nằm dọc mặt trước xương cùng. Trục của đầu thai nhi nằm trên trục trước - sau của eo trên.\n\n- Thì sổ:\n+ Thì sổ được thực hiện như ngôi mặt cằm trước:\n+ Đầu cúi để cho phần đầu của thai nhi đi từ mũi đến hạ chẩm xuất hiện ở âm hộ\n+ Đầu ngửa: Hạ chẩm cố định vào âm hộ, đầu ngửa để cho miệng và cằm sổ\nKhi chẩm thai nhi sổ, tầng sinh môn dãn rộng nên chỉ định  cắt tầng sinh môn để tránh rách và sang chấn cho trẻ.\n2.3. Triệu chứng và chẩn đoán\n2.3.1. Khám lâm sàng\nNgôi trán là ngôi chỉ xảy ra trong thời kỳ chuyển dạ nên chỉ chẩn đoán được trong thời kỳ chuyển dạ.\n- Nhìn: Tử cung hình trứng tương ứng với một ngôi dọc, đầu ở dưới.\n- Nắn: Nắn ngoài thấy đầu cao, cúi không tốt, ở một bên là bướu chẩm tròn đều, có rãnh gáy. Đôi khi sờ thấy cằm phía đối diện biểu hiện sự ngửa của đầu.\n- Thăm âm đạo: Người ta chỉ có thể chẩn đoán được ngôi trán khi ngôi đã cố định. Tất cả các ngôi còn di động về sau có thể cúi tốt hơn để trở thành ngôi chỏm.\nThăm âm đạo có thể thấy:\n- Điểm mốc của ngôi là gốc mũi không bao giờ bị biến dạng bởi bướu huyết thanh, mỗi bên có gờ trên hố mắt và nhãn cầu. Các dấu hiệu âm tính rất quan trọng để chẩn đoán gián biệt với các ngôi khác. Trong ngôi trán có thể sờ thấy gốc mũi và thóp trước, nhưng không bao giờ sờ thấy thóp sau cũng như không sờ thấy miệng và cằm.\n- Thóp trước với 4 cạnh và 4 góc của nó (Hình trám)\n- Để xác định kiểu thế của ngôi dựa vào vị trí gốc mũi nằm ở phía nào so với khung chậu của người mẹ:\n+ Mũi chậu trái trước và mũi chậu phải sau đối với đường kính chéo trái.\n+ Mũi chậu phải trước và mũi chậu trái sau đối với đường kính chéo phải.\n+ Mũi chậu trái ngang và mũi chậu phải ngang đối với đường kính ngang.\n\n\n2.3.2. Cận lâm sàng\nChụp X quang và siêu âm có hai ưu điểm:\n-  Chẩn đoán có thể đặt ra sớm khi thấy đầu ngửa và sự tăng ưỡn cột sống cổ.\n-  Loại trừ các bất thường của thai (Quái thai vô sọ, não úng thuỷ)\n2.4. Thái độ xử trí\nKhi đã xác định là ngôi trán các bước xử trí như sau:\n2.4.1.Tuyến xã\nTheo dõi sát các cuộc chuyển dạ đẻ ngôi thuận để phát hiện sớm, đặc biệt lá các trường hợp ngôi cao, không lọt, chuyển dạ kéo dài. Nếu chẩn đoán là ngôi trán cần chuyển lên tuyến trên ngay.\n2.4.2. Tuyến huyện và các tuyến trên\nCác bước xử trí như sau:\n-   Khi ối chưa vỡ, ngôi cao lỏng nên chờ đợi xem sự tiến triển của ngôi:\n+ Nếu tiến triển không thuận lợi, ngôi không lọt được, chuyển dạ kéo dài, chỉ định mổ lấy thai ngay.\n+  Nếu tiến triển thuận lợi, ngôi có tự biến thành ngôi chỏm hoặc ngôi mặt trong lúc chuyển dạ. Có thể đẻ đường âm đạo\n- Khi màng ối đã vỡ, ngôi trán đã cố định, mổ lấy thai ngay.\n3. NGÔI THÓP TRƯỚC\n3.1. Đại cương\nNgôi thóp trước là một ngôi đầu ngửa nhẹ, trung gian giữa ngôi trán và chỏm. Trong ngôi thóp trước, không thể sờ được thóp sau khi khám. Trong khi ngôi chỏm kiểu chẩm cùng, thóp sau luôn sờ được.\n\nHình 1. Ngôi thóp trước\n3.2. Cơ chế đẻ\nLọt có thể xảy ra nhờ đầu cúi tốt, chuyển ngôi thóp trước thành ngôi chỏm. Nếu không lọt, sự xuống và quay của ngôi rất khó khăn. Đường kính lọt của ngôi là đường kính  chẩm - trán:12 cm. Sự biến dạng của đầu và bướu huyết thanh thường xuất hiện sớm và trầm trọng. Khi đó việc xác định ngôi gặp nhiều khó khăn. Đầu thai nhi cũng sổ bằng phép quay dạng chữ S., điểm trục được tạo bởi xương vệ và gốc mũi. Đầu cúi cho phép sổ trán, thóp trước, chẩm và hạ chẩm đến cố định vào đáy chậu, rồi đầu ngửa cho mũi miệng, cằm sổ.\n3.3. Lâm sàng\n-  Khám ngoài: ít có giá trị.\n- Thăm khám âm đạo: Sờ được thóp trước, điểm mốc của ngôi trình diện ở trung tâm, gốc mũi có thể sờ thấy nhưng ở ngoại vi và không ở trung tâm như trong ngôi trán. Vị trí của thóp trước xác định kiểu thế của ngôi, phải hoặc trái, trước hoặc sau. Kiểu thế trước thường gặp nhất >80%.\n3.4. Thái độ xử trí\nNếu tiến triển không thuận lợi: Ngôi không lọt hoặc lọt giả phải mổ lấy thai.\nPhần lớn các trường hợp tiến triển thuận lợi. Thời gian chuyển dạ và sổ thai thường kéo dài, tỷ lệ can thiệp trong thời kỳ sổ thai cao.\n\n4. NGÔI VAI\n4.1. Đại cương\nNgôi vai (hay còn gọi là ngôi ngang) là một ngôi không thuận, ngôi thai không nằm dọc theo trục tử cung mà nằm ngang hoặc chếch. Mốc của ngôi là mỏm vai. Tỷ lệ ngôi vai khoảng 0,3 - 0,5%.\nNguyên nhân: Ngôi vai thường hay gặp ở những sản phụ đẻ con rạ hơn là con so và hay gặp ở chuyển dạ thiếu tháng hơn là đủ tháng.\nBất luận một nguyên nhân nào cản trở đầu thai lọt vào khung chậu đều dễ gây ra ngôi vai. Tương tự như các ngôi không thuận khác,  song thai, đa ối, rau tiền đạo, khung chậu hẹp, hình dạng thai bất thường, tử cung dị dạng là những nguyên nhân thường gặp, tuy nhiên nguyên nhân hay gặp nhất là do cơ tử cung, cơ thành bụng nhão  ở người con rạ đẻ nhiều lần.\nKiểu ngôi là ngang hoặc chếch, ngôi chếch chỉ là ngôi tạm thời, nó sẽ biến thành ngôi dọc hay ngôi ngang vào lúc chuyển dạ nên còn gọi là ngôi không cố định.\n\nHình 2. Ngôi vai.\n\n4.2. Triệu chứng và chẩn đoán\nCần phát hiện ngôi vai sớm ngay từ cuối thai kỳ hay ngay từ đầu thời kỳ chuyển dạ.\n- Nhìn: Bụng bè ngang, đáy tử cung như nằm gần rốn.\n- Sờ nắn:\n+ Không thấy cực thai ở phần thấp của tử cung mà lại sờ được 2 cực ở 2 hố hông.\n+ Nắn trên xương vệ không thấy gì trừ khi chuyển dạ lâu, vai đã lọt vào trong tiểu khung. Phải xác định thêm xem lưng ở đâu. Nếu lưng trước sờ thấy diện phẳng, nếu lưng sau sờ thấy chân tay lổn nhổn. Thường lưng luôn ở trước.\n\nHình 3. Bốn thủ thuật trong khám ngôi vai.\n- Thăm âm đạo:\nThăm âm đạo phát hiện thấy một hố chậu rỗng, và một phần thai trình diện không bình thường. Vai có thể tưởng nhầm với mông, song các xương sườn tạo nên một cảm giác đặc biệt.\nNếu chuyển dạ đã lâu, một vai sẽ lọt chặt vào tiểu khung và thường đi kèm với sa  một cánh tay vào âm đạo, thò ra ngoài âm hộ gọi là ngôi vai sa tay.\nDựa theo vị trí của vai người ta có thể phân biệt:\n+ Vai chậu phải\n+ Vai chậu trái\n- Cận lâm sàng: Chụp Xquang và siêu âm  có thể xác định khi có nghi ngờ trong chẩn đoán cũng như chọn lựa hướng xử trí thích hợp.\n4.3. Thái độ xử trí\n4.3.1. Tuyến xã\nKhám và phát hiện sớm các trường hợp ngôi vai.\nTư vấn cho sản phụ và chuyển lên tuyến trên. Trường hợp ối đã vỡ cần sử dụng các thuốc giảm go và kháng sinh dự phòng trước khi chuyển\n4.3.2. Tuyến huyện và các tuyến trên\nỞ người con so, đứng trước một trường hợp ngôi vai phải nghĩ đến nguyên nhân có thể là khung chậu hẹp. Tất cả con so khung chậu hẹp hay bình thường mà lúc chuyển dạ còn giữ ngôi vai đều phải mổ lấy thai. Không tiến hành thủ thuật xoay thai, kéo thai.\n-  Nếu ngôi vai, ối đã vỡ chỉ định mổ lấy thai ngay.\n- Chỉ định nội xoay thai:  Ở người con rạ, có thể tiến hành nội xoay thai trong trường hợp  thai nhi nhỏ < 2500g, thai thứ hai trong song thai  giúp đầu quay và xuống được tiểu khung, chuyển dạ có thể tiến triển bình thường. Tuy nhiên chỉ tiến hành ở nơi có phòng mổ và khi có đủ điều kiện: khung chậu rộng rãi, thai con rạ, ối còn nguyên, cơn co thưa, và cổ tử cung mở hết.\nNếu thai nhi đã chết, cổ tử cung mở hết, có thể dùng dụng cụ cắt thai  trong ngôi vai buông trôi, tuy nhiên thủ thuật này cũng rất nguy hiểm cho mẹ vì vậy nếu không có kinh nghiệm vẫn nên mổ lấy thai.\nCâu hỏi:\n1: Nêu triệu chứng, chẩn đoán xác định, chẩn đoán phân biệt ngôi vai?\n2: Nêu triệu chứng, chẩn đoán  xác định, chẩn đoán phân biệt ngôi trán? hướng xử trí?\n3: Nêu triệu chứng lâm sàng chẩn đoán xác định ngôi mặt?", "priority": "Trung bình"}, {"id": "SK-21", "chapter": "Chương 2. Sản bệnh", "folder": "02_San_benh", "title": "Đẻ non", "author": "Ths. BSCK II. Hoàng Tiến Nam", "word_count": 4371, "line_count": 345, "key_numbers": ["0,5mg", "1 giờ", "10 ngày", "10 phút", "100mg", "100ml", "10mg", "10ml", "12 giờ", "12mg", "15 phút", "150mg", "18 tuần", "180mmHg", "18mg", "1cm", "1g", "2 cm", "2 giờ", "2 mg", "2 ngày", "2,5cm", "20 phút", "20mg", "20ml", "24 giờ", "250mcg", "25mg", "285 ngày", "294 ngày", "2cm", "2g", "3 giờ", "3 ngày", "30 phút", "32 tuần", "330mg", "34 tuần", "35 tuần", "36 tuần", "37 tuần", "3cm", "4 mg", "40mmHg", "41 tuần", "42 tuần", "45 giờ", "48 giờ", "4cm", "4giờ", "5 ngày", "500ml", "50mmHg", "5mg", "6 giờ", "6 tuần", "6,75mg", "6g", "6mg", "7 ngày", "70ml", "7mg", "8 tuần", "9 tháng"], "key_drugs": ["Dexamethasone", "Magnesium Sulfate", "Nifedipine", "Oxytocin", "oxytocin"], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["ĐẺ NON", "Ths. BSCK II. Hoàng Tiến Nam"], "bullets": []}, {"heading": "2. Trình bày được các triệu chứng chẩn đoán doạ đẻ non, đẻ non.", "paragraphs": ["3.Trình bày được các yếu tố tiên lượng và dự phòng doạ đẻ non."], "bullets": []}, {"heading": "1.1. Định nghĩa", "paragraphs": ["Theo tổ chức Y tế thế giới, đẻ non là một cuộc chuyển dạ xảy từ tuần 22 đến trước tuần thứ 37 của thai kỳ tính từ ngày đầu tiên của kỳ kinh cuối cùng."], "bullets": []}, {"heading": "1.2. Tỷ lệ", "paragraphs": [], "bullets": ["- Đẻ non có tỷ lệ từ  5% đến 15 % trong tổng số các cuộc đẻ.", "- Chủng tộc: da trắng 8,5%, da đen: 18,3%. (Theo Tổ chức Y Tế Thế Giới, 1997)", "- Tỷ lệ đẻ non ở Pháp vào 1972 là 8, 2% và 1981 còn 5, 6%.", "- Tại Bệnh viện Trung ương Huế, tỷ lệ đẻ non là 7,8 % (1995)"]}, {"heading": "1.3. Tầm quan trọng đối với cộng đồng", "paragraphs": ["Đẻ non nguy hiểm cho trẻ sơ sinh, tỷ lệ tử vong chu sản càng cao khi tuổi thai càng non. Đặc biệt, trẻ đẻ non có nguy cơ cao về di chứng thần kinh. Trước 32 tuần tỷ lệ di chứng là 1/3. Từ 32- 35 tuần tỷ lệ di chứng thần kinh là 1/5. Từ 35 đến 37 tuần tỷ lệ di chứng là 1/10.", "Chăm sóc một trường hợp đẻ non rất tốn kém. Ngoài ra khi lớn lên trẻ còn có những di chứng về tâm thần kinh, là gánh nặng cho gia đình cũng như xã hội.", "Mẹ bị đẻ non thì cũng dễ biến chứng sót rau, nhiễm khuẩn hậu sản.", "Do đó đẻ non là một trong những vấn đề quan trọng đặt ra cho các thầy thuốc và xã hội."], "bullets": []}, {"heading": "2. NGUYÊN NHÂN", "paragraphs": ["Có khoảng 50% đẻ non không xác định rõ lý do.", "Sau đây là một số nguyên nhân và yếu tố thuận lợi:"], "bullets": []}, {"heading": "2.1. Yếu tố xã hội", "paragraphs": [], "bullets": ["- Đời sống kinh tế xã hội thấp, không được chăm sóc trước sinh đầy đủ.", "- Cân nặng của mẹ thấp và/hoặc tăng cân kém.", "- Lao động vất vả trong lúc mang thai.", "- Tuổi mẹ dưới 20 hoặc con so lớn tuổi trên 35 tuổi.", "- Mẹ nghiện thuốc lá, rượu hay các chất cocain."]}, {"heading": "2.2.1. Nguyên nhân do bệnh lý toàn thân", "paragraphs": ["Các bệnh lý nhiễm trùng: nhiễm trùng đường tiết niệu, nhiễm trùng nặng do vi khuẩn, virus.", "Nghề nghiệp: các nghề tiếp xúc với hoá chất độc, lao động nặng, căng thẳng.", "Bệnh toàn thân của mẹ: bệnh tim, bệnh gan, bệnh thân, thiếu máu.", "Rối loạn cao huyết do thai: Tiền sản giật - sản giật (9%)", "Miễn dịch: Hội chứng kháng thể kháng Phospholipid."], "bullets": ["- Các chấn thương trong thai nghén: Chấn thương trực tiếp vào vùng bụng hoặc gián tiếp do phẫu thuật vùng bụng."]}, {"heading": "2.2.2. Nguyên nhân tại chỗ", "paragraphs": ["Hình 1. A. Cổ tử cung bình thường, B. Hở eo tử cung, C. Khâu vòng cổ tử cung"], "bullets": ["- Tử cung dị dạng bẩm sinh: chiếm 5% trong đẻ non. Nếu có nguyên nhân này thì nguy cơ đẻ non là 40%. Các dị dạng thường gặp: tử cung hai sừng, một sừng, tử cung kém phát triển, vách ngăn tử cung.", "- Bất thường mắc phải ở tử cung: Dính buồng tử cung, u xơ tử cung, tử cung có sẹo.", "- Hở eo tử cung: 100% đẻ non nếu không được điều trị.", "- Các can thiệp phẫu thuật tại cổ tử cung như khoét chóp."]}, {"heading": "2.2.4. Tiền sử sinh non", "paragraphs": [], "bullets": ["- Nguy cơ tái phát 25 - 50 %. Nguy cơ này tăng cao nếu có nhiều lần sinh non trước đó."]}, {"heading": "2.3. Do thai và phần phụ của thai", "paragraphs": ["Tóm lại muốn tìm hiểu nguyên nhân về đẻ non, ta phải xem xét lại toàn bộ bệnh lý sản phụ khoa, có những nguyên nhân về phía mẹ, về phía thai, và phần phụ của thai, có những nguyên nhân phối hợp."], "bullets": ["- Ối vỡ non, ối vỡ sớm: 10% đủ tháng và 30% đẻ non, có nguy cơ nhiễm trùng cho thai.", "- Nhiễm trùng ối.", "- Đa thai: 10- 20% đẻ non.", "- Đa ối: do tử cung quá căng gây chuyển dạ sớm.", "- Rau tiền đạo: 10% trong các trường hợp đẻ non vì gây chảy máu trước đẻ hoặc ối vỡ.", "- Rau bong non."]}, {"heading": "3.1.1. Triệu chứng cơ năng", "paragraphs": [], "bullets": ["- Đau bụng: Sản phụ cảm giác đau bụng từng cơn hoặc trì nặng bụng dưới.", "- Ra dịch âm đạo: có thể là dịch nhầy âm đạo, ra máu hoặc nước ối."]}, {"heading": "3.1.2. Triệu chứng thực thể", "paragraphs": [], "bullets": ["- Cơn go tử cung: thưa nhẹ, có 1 - 2 cơn go tử cung trong 10 phút và thời gian quan sát trên 30 phút.", "- Cổ tử cung có thể còn dài, đóng kín nhưng cũng có thể xoá và mở đến < 4cm.", "- Ối vỡ non: dẫn đến chuyển dạ trong một thời gian ngắn. Nó là bước ngoặt trong đẻ non bởi vì nó làm cho buồng ối bị hở, tăng thêm nguy cơ nhiễm khuẩn."]}, {"heading": "3.1.3. Cận lâm sàng", "paragraphs": ["Hình 2. Ðo cổ tử cung qua siêu âm với mẫu biểu đồ để đo độ dài,", "chiều dài hình nón và độ rộng cổ tử cung trong chẩn đoán dọa sinh non", "Hình 3. Đánh giá thai và theo dõi cơn go bằng Monitoring,", "2 cơn co trong 10 phút ở thai 32 tuần"], "bullets": ["- Siêu âm: khảo sát độ dài cổ tử cung, nếu dưới 2,5cm thì nguy cơ đẻ non cao.", "- Đánh giá thai và theo dõi cơn go bằng Monitoring, có 1-2 cơn co đều đặn trong 10 phút.", "- Chỉ số doạ đẻ non dưới 6", "- Ngoài ra cần làm các xét nghiệm để tìm nguyên nhân:", "+ Tế bào vi trùng nước tiểu.", "+ Xét nghiệm vi khuẩn ở cổ tử cung.", "+ Nếu sốt phải kéo máu tìm ký sinh trùng sốt rét, CRP, cấy máu tuỳ trường hợp. Cân nhắc việc chọc dò ối để loại bỏ khả năng nhiễm trùng màng ối."]}, {"heading": "3.2.1. Triệu chứng cơ năng", "paragraphs": [], "bullets": ["- Đau bụng: Sản phụ đau bụng từng cơn, các cơn đau tăng dần.", "- Ra dịch âm đạo: có thể là dịch nhầy âm đạo, ra máu hoặc nước ối."]}, {"heading": "3.2.2. Triệu chứng thực thể", "paragraphs": [], "bullets": ["- Cơn go tử cung: có 2 - 3 cơn go tử cung trong 10 phút, tăng dần.", "- Cổ tử cung xoá trên 80%, hoặc mở trên 2 cm, đầu ối bắt đầu thành lập hoặc ối vỡ sớm.", "- Theo dõi cơn go bằng Monitoring, nếu có 2 - 3 cơn go đều đặn trong 10 phút.", "- Chỉ số doạ đẻ non lớn hơn 6"]}, {"heading": "4. CÁC YẾU TỐ TIÊN LƯỢNG:", "paragraphs": ["Dựa vào 4 yếu tố: cơn go, thay đổi ở cổ tử cung, ối vỡ, ra máu âm đạo và người ta đã xây dựng nên một chỉ số doạ đẻ non", "Bảng 1.  Chỉ số doạ đẻ non", "Điểm", "Yếu tố", "1", "2", "3", "4", "Go tử cung", "Không đều", "Đều", "Ối vỡ", "Có thể", "Rõ ràng", "Ra máu", "Vừa", "> 100ml", "Mở cổ tử cung", "1cm", "2cm", "3cm", "( 4cm", "Bảng 2 : Khả năng đình chỉ chuyển dạ thành công", "(theo chỉ số doạ đẻ non)", "Chỉ số", "1", "2", "3", "4", "5", "6", "(7", "Chuyển dạ ngừng lại          (%)", "100", "90", "84", "38", "11", "7", "0"], "bullets": []}, {"heading": "5.1.1. Tuyến xã", "paragraphs": [], "bullets": ["- Không nên điều trị doạ đẻ non, chuyển tuyến trên càng sớm càng tốt."]}, {"heading": "5.1.2. Tuyến huyện và tuyến bệnh viện chuyên khoa:", "paragraphs": ["Sử dụng các thuốc ức chế chuyển dạ.\t- Các nghiên cứu so sánh hiệu quả của các thuốc cho thấy không có thuốc nào có ưu thế vượt trội. Tất cả những thuốc này chỉ có thể kéo dài thời gian mang thai trong một khoảng thời gian hạn chế từ 2 -7 ngày, đây là khoảng thời gian để sử dụng steroid và vận chuyển bà mẹ đến cơ sở y tế có phòng hồi sức sơ sinh. Do đó, việc chọn loại thuốc nào phụ thuộc vào sự có sẵn của thuốc và những tác dụng phụ đối với bà mẹ và thai nhi.", "* Liều tấn công: 4-6g trong 100ml Dextrose 5% truyền tĩnh mạch từ 15-20 phút.", "* Liều duy trì: 2g/giờ truyền TM, trong vòng 12 giờ, sau đó là 1g/1 giờ trong 24 -48 giờ. Theo dõi nồng độ Mg++ huyết thanh duy trì từ 5-7mg/dL.", "* Tác dụng phụ trên bà mẹ: nóng bừng, ngủ lịm, đau đầu, mệt mỏi, khô miệng, ức chế hô hấp, giảm phản xạ gân xương. Thử phản xạ gân xương để phát hiện quá liều thuốc. Ngừng tim và hô hấp có thể xuất hiện nếu dùng quá liều. Có thể dùng chất đối kháng là Calci (Calcium gluconate hoặc calci clorua liều 1g tiêm TM chậm).", "* Tác động lên thai nhi: ngủ lịm, giảm trương lực cơ, suy hô hấp.", "* Liều tấn công: 20mg ngậm dưới lưỡi mỗi 20 phút, tối đa 3 liều.", "* Sau đó khi đã cắt cơn go thì duy trì liều 10-20mg đường uống trong mỗi 4-6 giờ.", "* Chống chỉ định đối với trường hợp có bệnh tim, huyết áp thấp (dưới 90/50mmHg). Không sử dụng cùng với Magnesium sulphate. Cẩn thận khi sử dụng cho người có bệnh lý ở thận.", "* Tác dụng phụ trên bà mẹ: nóng bừng, đau đầu, buồn nôn, hạ huyết áp thoáng qua. Tác động lên thai nhi: hiện chưa có ghi nhận đặc biệt gì."], "bullets": ["- Các loại bêta - mimetic", "+ Là các thuốc hướng beta giao cảm.", "- Ritodrine là thuốc có tác dụng trực tiếp làm giảm cơ trơn của tử cung và của phổi. Pha 150mg trong 500ml dung dịch mặn đẳng trương.", "+ Liều tấn công: Bắt đầu truyền với tốc độ 20ml/giờ và cứ 15 phút tăng lên 10ml/giờ và tăng tối đa là 70ml/giờ.", "+ Liều duy trì: Khi cắt được cơn tiếp tục duy trì thêm 12 giờ. Trước khi rút đường truyền 30 phút cho uống Ritodrine cứ 2 giờ 10mg trong 24 giờ và sau đó duy trì ở liều 20mg/4- 6 giờ cho đến khi thai  được 36 tuần. Ngưng thuốc khi nhịp tim mẹ trên 150 lần /phút và tim thai trên 200 lần/ phút. Huyết huyết áp tâm thu trên 180mmHg và huyết áp tâm trương dưới 40mmHg.", "+ Tác dụng phụ trên bà mẹ bao gồm: tăng nhịp tim, tăng đường huyết, tăng Insuline huyết, hạ Kali huyết, rùng mình, đánh trống ngực, bồn chồn, buồn nôn, nôn, ảo giác.", "+ Tác động lên thai nhi: nhịp tim nhanh, hạ canxi huyết, hạ đường huyết, hạ huyết áp, tăng bilirubine huyết, xuất huyết não thất.", "+ Chống chỉ định trong bệnh tim, cường giáp, tăng huyết áp không kiểm soát được, đái tháo đường nặng, các bện gan và bệnh thận mạn tính. Các bệnh nhân trên 35 tuổi cũng có chống chỉ định.", "- Terbutaline:  Chỉ định, chống chỉ định giống Ritodrine.", "+ Liều tấn cụng: Liều khởi đầu 250mcg, truyền TM với tốc độ 10ư80 àg/phỳt cho đến khi chuyển dạ ngừng lại. Sau đú tiờm dưới da 0,25ư 0,5mg/2ư 4giờ trong 12 giờ tiếp theo.", "+ Liều duy trì: liều uống 5mg cứ 4- 6 giờ một lần cho đến khi thai đươc 36 tuần. Tác dụng phụ trên bà mẹ: loạn nhịp, phù phổi, thiếu máu cơ tim, hạ huyết áp, nhịp tim nhanh. Tác động lên thai nhi: nhịp tim nhanh, tăng đường huyết, tăng Insuline huyết, phì đại cơ tim, thiếu máu cơ tim.", "- Atosiban (Tractocile): cho liều tấn công 6,75mg, tiêm tĩnh mạch chậm trong một phút, sau đó cho liều duy trì 18mg/giờ trong 3 giờ rồi duy trì 6mg/giờ trong 45 giờ. Tổng liều tối đa là 330mg.", "-  Các chất đối kháng Calci", "+ Magnesium Sulfate: Là thuốc thay thế cho các thuốc beta hướng giao cảm khi có chống chỉ định dùng các thuốc này hoặc khi có ngộ độc thuốc.", "+  Nifedipine:", "- Thuốc ức chế tổng hợp Prostaglandine: Indomethacin liều 25mg/6 giờ trong 5 ngày hoặc nhét hậu môn 100mg sau đó uống 25mg/6 giờ cho đến 24 giờ sau khi không còn cơn go nữa. Thuốc này có những tác động ngược trên thai nhi: co thắt ống động mạch, tăng áp lực phổi, thiểu ối, xuất huyết não thất, viêm ruột hoại tử và tăng bilirubine huyết", "- Sử dụng Corticosteroid", "+ Giúp cho phổi thai nhi trưởng thành tránh được bệnh màng trong, chỉ dùng cho trường hợp thai từ 28 đến hết 34 tuần.", "+ Cho corticoide ở mẹ làm giảm từ 40-60%  nguy cơ bệnh màng trong ở sơ sinh.", "+ Betamethason (Celestene) tiêm bắp 2 ống/ một ngày  hoặc một ống /ngày trong 2 ngày, hoặc Dexamethasone (Dexaron): 12mg/ngày (3 ống) tiêm bắp x 2 ngày liên tiếp. Hiệu quả tối đa của Corticosteroid đạt được trong vòng 24-48 giờ, do đó cố gắng trì hoãn cuộc chuyển dạ ít nhất 24 giờ sau khi sử dụng thuốc này. Chú ý loại trừ mẹ mắc bệnh đái đường thai nghén trước khi dùng corticosteroid."]}, {"heading": "5.2.1. Tuyến xã", "paragraphs": [], "bullets": ["- Tư vấn, chuyển tuyến trên càng sớm càng tốt", "- Trường hợp đã đẻ ở xã:", "+ Chăm sóc trẻ sơ sinh theo phác đồ chăm sóc trẻ sơ sinh non tháng, nhẹ cân.", "+Chăm sóc mẹ: theo dõi chảy máu, kiểm soát tử cung nếu rau thiếu                                                    tư vấn, chuyển tuyến trên nếu cần."]}, {"heading": "5.2.2. Tuyến huyện và tuyến bệnh viện chuyên khoa", "paragraphs": ["Thái độ xử trí cho một chuyển dạ đẻ non có khác nhau, tuỳ thuộc ối còn hay đã vỡ, tuổi thai là một yếu tố  rất quan trọng."], "bullets": ["- Cần đảm bảo cho trẻ ít bị chấn thương nhất trong đẻ vì trẻ non tháng rất yếu ớt. Người ta dễ dàng chỉ định mổ lấy thai vì lợi ích của đứa trẻ nếu là ngôi mông, suy thai.", "- Đẻ đường dưới được chấp nhận khi là ngôi chỏm và có đủ điều kiện.", "- Sau đẻ phải kiểm soát tử cung để tránh sót rau, tìm dị dạng tử cung, xét nghiệm vi khuẩn (rau, nước tiểu và trẻ sơ sinh).", "- Cần có sự theo dõi dặc biệt trong chuyển dạ và có phòng chăm sóc tích cực cho các trẻ non tháng sau đẻ.", "- Hồi sức thai và chống ngạt: Cho mẹ thở oxy ngắt quãng, mỗi lần 10 phút, 3-4 đợt/giờ, lưu lượng 6-8l /phút.", "- Tránh sang chấn cho thai: Bảo vệ đầu ối đến khi mở gần hết hoặc mở hết. Hạn chế sử dụng oxytocin. Giúp thai sổ dễ dàng bằng cách cắt rộng tầng sinh môn khi sổ thai.", "- Tránh mất nhiệt cho trẻ mới đẻ, đảm bảo ủ ấm cho trẻ."]}, {"heading": "6. DỰ PHÒNG", "paragraphs": ["Sau khi đã xác định các yếu tố nguy cơ, vai trò dự phòng là cố gắng loại bỏ các yếu tố nguy cơ:", "Không nên đi du lịch xa, động viên nghỉ ngơi tối đa.", "Tôn trọng thời gian nghỉ trước đẻ 6 tuần (8 tuần nếu trên 3 con)", "Điều trị các nhiễm khuẩn nếu có.", "Ổn định các bệnh lý của mẹ như nhiễm độc thai nghén, đái đường, đặc biệt các thai nghén có nguy cơ cao.", "Hình 4. Kỹ thuật khâu vòng cổ tử cung theo phương pháp Mc Donald"], "bullets": ["- Khâu vòng cổ tử cung từ tuần thứ 12- 14 nếu có hở eo."]}, {"heading": "2. Trình bày các triệu chứng chẩn đoán doạ đẻ non, đẻ non?", "paragraphs": ["3.Trình bày các yếu tố tiên lượng và dự phòng doạ đẻ non?"], "bullets": []}, {"heading": "4. Trình bày cách xử trí doạ đẻ non, đẻ non?", "paragraphs": ["THAI GIÀ THÁNG"], "bullets": []}, {"heading": "1.1. Định nghĩa", "paragraphs": ["Thời gian thai nghén bình thường trung bình là 9 tháng 10 ngày hay 285 ngày (10 ngày tính từ ngày đầu của kinh cuối cùng).", "Thai nghén được gọi là già tháng khi tuổi thai theo lý thuyết vượt quá 42 tuần hoặc 294 ngày."], "bullets": []}, {"heading": "1.2. Tỷ lệ", "paragraphs": ["Khoảng 3- 12% thai nghén vượt quá tuần 42, nhưng thực tế thì tỷ lệ thai già tháng không vượt quá 4% (do không nhớ ngày kinh cuối cùng chính xác, hoặc thời gian phóng noãn chậm) .", "Tỷ lệ biến chứng ở mẹ và thai gia tăng theo tuổi thai, tỷ lệ tử vong chu sinh tăng từ  giữa tuần thứ 41 và 42, gấp đôi vào tuần 43 và cao gấp 4 - 6 lần vào tuần 44 so với thai đủ tháng.", "Biến chứng cho mẹ ngay cả mổ lấy thai cũng tăng gấp đôi với chảy máu, nhiễm trùng, bục vết thương.", "Vấn đề chẩn đoán và xử trí thai già tháng rất quan trọng vì tử vong sơ sinh cao, gấp 3 lần so với trẻ sinh trong khoảng 38 - 41 tuần."], "bullets": []}, {"heading": "2. NGUYÊN NHÂN", "paragraphs": ["Nguyên nhân của thai già tháng vẫn chưa biết rõ. Tuy nhiên có một số yếu tố nguy cơ như: thai vô sọ, thiếu sulfatase rau thai, sử dụng progesteron kéo dài, tiền sử sinh quá ngày.", "Nguyên nhân thường gặp nhất là tính tuổi thai không chính xác."], "bullets": []}, {"heading": "3. SINH LÝ BỆNH HỌC", "paragraphs": ["Bánh rau và nước ối đóng một vai trò quan trọng trong quá trình vận chuyển và chuyển hóa sinh học của thai nhi. Trong thai già tháng, lượng nước ối giảm dần, bánh rau thoái hóa dần dẫn đến giảm dòng máu ở bánh rau và  các chất dinh dưỡng  đến thai. Do đó thai bị suy  trường diễn trong tử cung và có thể chết trong tử cung hoặc chết trong khi chuyển dạ (do có cơn go tử cung). Vì vậy, thai già tháng là thai nghén bị đe dọa, thiếu ôxy là nguyên nhân chính của suy thai, khi thai đẻ ra sống thì nó có biểu hiện tổn thương đặc biệt theo kiểu gầy, bị mất nước, da nhăn nheo nhuộm đầy phân su."], "bullets": []}, {"heading": "4.1. Lâm sàng", "paragraphs": [], "bullets": ["- Hỏi bệnh sử để định tuổi thai:", "+ Kinh cuối cùng:  lấy mốc là ngày đầu của kinh cuối cùng để tính tuổi thai.", "+ Thời gian thụ tinh: nếu có điều trị vô sinh, vì đây là mốc rất có giá trị để chẩn đoán tuổi thai.", "+ Lần thăm khám sản khoa đầu tiên: nếu có làm phản ứng sinh học, hoặc siêu âm  để chẩn đoán thai sớm (trong quý đầu) thì rất có giá trị.", "+ Thời gian xuất hiện thai máy: con so thường vào tuần thứ 18 tuần, con rạ tuần 16.", "+ Giảm cử động thai xảy ra đột ngột ở những thai phụ có thai đạp nhiều, cần phải được xem xét nghiêm túc.", "-  Đo bề cao tử cung giảm qua 2 lần thăm kế tiếp kèm với giảm lượng nước ối (có tính chất gợi ý)."]}, {"heading": "4.2. Xét nghiệm bổ sung", "paragraphs": ["Hiện nay không có một tiêu chuẩn nào cho phép khẳng định chắc chắn thai già tháng, tuy nhiên tốt nhất có thể dựa vào:", "Sau khi đã loại trừ các sai lầm lớn về tuổi thai, chỉ còn một khả năng là theo dõi chặt chẽ lúc cuối thời kỳ  thai nghén để phát hiện suy thai.", "Dù sao đi nữa, mọi thai nghén vượt quá 41 tuần và 3 ngày là phải có ý kiến của bác sĩ sản khoa theo dõi và đỡ đẻ."], "bullets": ["- Siêu âm sớm (đặc biệt trong quý đầu) giúp chẩn đoán chính xác tuổi thai.", "- Siêu âm muộn ít chính xác hơn nhưng nếu thấy lượng nước ối ít và bánh rau vôi hóa cũng gợi ý chẩn đoán.", "- Doppler: Phương pháp này cho phép khảo sát tình trạng huyết động học của thai và tuần hoàn rau thai để tiên lượng suy thai.", "- Monitor thai để tìm suy thai mãn (thử nghiệm không đả kích 2 lần/ tuần hoặc thử nghiệm đã kích).", "- Soi ối: tìm dấu hiệu suy thai mãn, có thể thấy ối màu vàng hoặc màu  xanh  .", "- Chọc hút nước ối: chỉ cho khẳng định thai đã trưởng thành mà không cho phép chẩn đoán thai già tháng.", "- Chụp X quang để tìm  điểm hóa cốt:  điểm  Béclard (đầu dưới xương đùi). Điểm TOD  (đầu trên xương chày ). Tỷ lệ âm tính giả khá cao hiện nay ít được sử dụng", "- Ngày kinh cuối cùng", "- Siêu âm", "- Lượng nước ối: Nước ối ít"]}, {"heading": "5.1. Nguy cơ cho mẹ", "paragraphs": [], "bullets": ["- Gia tăng khả năng mổ lấy thai và đẻ có can thiệp thủ thuật.", "- Chảy máu sau sinh.", "- Nằm viện dài ngày và có nhiều biến chứng."]}, {"heading": "5.2. Nguy  cơ cho thai", "paragraphs": [], "bullets": ["- Thiểu ối (thiểu năng rau thai)", "+ Chèn ép dây rốn", "+ Suy thai", "+ Tử vong thai đột ngột.", "- Rối loạn trưởng thành thai (chiếm tỷ lệ 10- 20% thai quá ngày).", "- Hội chứng hít phân su: 25-30 % thai 42 tuần có phân su trong dịch ối.", "- Thai lớn: gây đẻ khó, tổn thương xương và gãy xương và để lại chứng thần kinh tại chỗ và lâu dài."]}, {"heading": "6.1. Tuyến xã", "paragraphs": ["Chuyển thai phụ lên tuyến trên sau khi đã tư vấn."], "bullets": []}, {"heading": "6.2.1. Nhập viện", "paragraphs": ["Nếu tuổi thai trên 41 tuần và phải được theo dõi sát, sản phụ sẽ được xác định độ trưởng thành và tình trạng sức khoẻ thai nhi.", "Hướng dẫn bệnh nhân theo dõi cử động thai, hướng dẫn cho thai phụ đếm cử động thai bắt đầu vào một giờ nhất định trong ngày. Bình thường thai cử động trên 10 lần trong thời gian 12 giờ. Nếu số lần cử động thai giảm dần hay giảm đột ngột là dấu hiệu của suy thai.", "Ví dụ sau 2 giờ mà không thấy thai máy cần cảnh giác. Sau 12 giờ không thấy thai máy có thể thai đã chết.", "Theo dõi chỉ số nước ối bằng siêu âm: Siêu âm thai kiểm tra dịch ối ít nhất 2 lần/tuần. Thiểu ối được định nghĩa khi chỉ số nước ối < 5 hoặc túi ối lớn nhất < 2 x 2cm). Thiểu ối có liên quan đến nguy cơ cao của suy thai và tử vong sơ sinh.", "Theo dõi suy thai bằng máy monitor: hai thử nghiệm hay được dùng là thử nghiệm không đả kích (non-stress test) và thử nghiệm đả kích (contraction stress test) như test vê núm vú hoặc test truyền oxytocin. Thử nghiệm này được làm 2 lần/tuần. Chỉ định mổ lấy thai nếu có xuất hiện Dip II."], "bullets": []}, {"heading": "6.2.2. Chấm dứt thai kỳ", "paragraphs": ["Bảng chỉ số Bishop", "Điểm", "Đánh gía", "0 điểm", "1 điểm", "2 điểm", "3 điểm", "Độ mở CTC (cm)", "0", "1 - 2", "3 - 4", "5 - 6", "Độ xoá CTC (%)", "0-30", "40 - 50", "60 - 70", ">=80", "Độ lọt của thai", "Mật độ CTC", "Cứng", "Vừa", "Mềm", "Hướng CTC", "Sau", "Trung gian", "trước"], "bullets": ["- Trong trường hợp con hiếm hoặc bất tương xứng đầu chậu nên mổ lấy thai.", "-  Nếu có tình trạng suy thai: mổ lấy thai.", "- Trong những trường hợp khác như thai đã trưởng thành, thai không suy, tiến hành làm test đả kích, nếu dương tính phải mổ lấy thai. Nếu âm tính, phải khởi phát chuyển dạ và đánh giá chỉ số Bishop để tiên lượng khả năng gây chuyển dạ.", "-3", "-2", "-1 - 0", "+1 - +2", "- Nếu CTC có thể mở, chỉ số Bishop trên 5, gây chuyển dạ bằng truyền Oxytocin. Trong khi giục sinh phải theo dõi sát tim thai bằng monitoring vì thai có thể suy rất nhanh.", "- Nếu CTC không mở, chỉ số Bishop dưới 5, nên kết hợp với các phương pháp thăm dò khác như theo dõi cử động thai, siêu âm đánh giá chỉ số nước ối, monitoring để quyết định gây chuyển dạ hoặc theo dõi tiếp.", "- Trong trường hợp gây chuyển dạ, làm mềm CTC bằng PGE2 (Dinoprostol) 1-2 mg, tối đa không quá 4 mg đặt âm đạo.", "- Nếu trong quá trình chuyền thất bại hoặc xuất hiện suy thai thì cũng phải mổ lấy thai."]}, {"heading": "6.3. Chăm sóc em bé", "paragraphs": ["Cần phải xem lại trẻ sơ sinh có bị bong da hay không, rau, ối như thế nào. Khi đã xác định là thai già tháng, cần phải thực hiện các biện pháp săn sóc đặc biệt, hút kỹ phân su đường hô hấp, điều chỉnh toan biến dưỡng, tiêm Vitamin K1, kháng sinh dự  phòng...và theo dõi sự phát triển của trẻ.", "Lưu ý: chẩn đoán thai già tháng dựa vào những dấu hiệu nghi ngờ. Do đó đòi hỏi người thầy thuốc phải theo dõi sát bệnh nhân và quyết định xử trí đúng lúc, tránh những can thiệp trên một thai chưa đủ tháng, nhưng cũng không để xảy ra tình trạng suy thai và tử vong thai trong bụng mẹ do rau già  cỗi và thoái hóa."], "bullets": []}], "raw_text": "ĐẺ NON\nThs. BSCK II. Hoàng Tiến Nam\nMục tiêu học tập\n1. Kể ra các nguyên nhân gây đẻ non.\n2. Trình bày được các triệu chứng chẩn đoán doạ đẻ non, đẻ non.\n3.Trình bày được các yếu tố tiên lượng và dự phòng doạ đẻ non.\n4. Trình bày được cách xử trí doạ đẻ non, đẻ non.\n\n1. ĐẠI CƯƠNG\n1.1. Định nghĩa\nTheo tổ chức Y tế thế giới, đẻ non là một cuộc chuyển dạ xảy từ tuần 22 đến trước tuần thứ 37 của thai kỳ tính từ ngày đầu tiên của kỳ kinh cuối cùng.\n1.2. Tỷ lệ\n- Đẻ non có tỷ lệ từ  5% đến 15 % trong tổng số các cuộc đẻ.\n- Chủng tộc: da trắng 8,5%, da đen: 18,3%. (Theo Tổ chức Y Tế Thế Giới, 1997)\n- Tỷ lệ đẻ non ở Pháp vào 1972 là 8, 2% và 1981 còn 5, 6%.\n- Tại Bệnh viện Trung ương Huế, tỷ lệ đẻ non là 7,8 % (1995)\n1.3. Tầm quan trọng đối với cộng đồng\nĐẻ non nguy hiểm cho trẻ sơ sinh, tỷ lệ tử vong chu sản càng cao khi tuổi thai càng non. Đặc biệt, trẻ đẻ non có nguy cơ cao về di chứng thần kinh. Trước 32 tuần tỷ lệ di chứng là 1/3. Từ 32- 35 tuần tỷ lệ di chứng thần kinh là 1/5. Từ 35 đến 37 tuần tỷ lệ di chứng là 1/10.\nChăm sóc một trường hợp đẻ non rất tốn kém. Ngoài ra khi lớn lên trẻ còn có những di chứng về tâm thần kinh, là gánh nặng cho gia đình cũng như xã hội.\nMẹ bị đẻ non thì cũng dễ biến chứng sót rau, nhiễm khuẩn hậu sản.\nDo đó đẻ non là một trong những vấn đề quan trọng đặt ra cho các thầy thuốc và xã hội.\n\n2. NGUYÊN NHÂN\nCó khoảng 50% đẻ non không xác định rõ lý do.\nSau đây là một số nguyên nhân và yếu tố thuận lợi:\n2.1. Yếu tố xã hội\n- Đời sống kinh tế xã hội thấp, không được chăm sóc trước sinh đầy đủ.\n- Cân nặng của mẹ thấp và/hoặc tăng cân kém.\n- Lao động vất vả trong lúc mang thai.\n- Tuổi mẹ dưới 20 hoặc con so lớn tuổi trên 35 tuổi.\n- Mẹ nghiện thuốc lá, rượu hay các chất cocain.\n2.2. Do mẹ\n2.2.1. Nguyên nhân do bệnh lý toàn thân\nCác bệnh lý nhiễm trùng: nhiễm trùng đường tiết niệu, nhiễm trùng nặng do vi khuẩn, virus.\n- Các chấn thương trong thai nghén: Chấn thương trực tiếp vào vùng bụng hoặc gián tiếp do phẫu thuật vùng bụng.\nNghề nghiệp: các nghề tiếp xúc với hoá chất độc, lao động nặng, căng thẳng.\nBệnh toàn thân của mẹ: bệnh tim, bệnh gan, bệnh thân, thiếu máu.\nRối loạn cao huyết do thai: Tiền sản giật - sản giật (9%)\nMiễn dịch: Hội chứng kháng thể kháng Phospholipid.\n2.2.2. Nguyên nhân tại chỗ\n- Tử cung dị dạng bẩm sinh: chiếm 5% trong đẻ non. Nếu có nguyên nhân này thì nguy cơ đẻ non là 40%. Các dị dạng thường gặp: tử cung hai sừng, một sừng, tử cung kém phát triển, vách ngăn tử cung.\n- Bất thường mắc phải ở tử cung: Dính buồng tử cung, u xơ tử cung, tử cung có sẹo.\n- Hở eo tử cung: 100% đẻ non nếu không được điều trị.\n- Các can thiệp phẫu thuật tại cổ tử cung như khoét chóp.\n\nHình 1. A. Cổ tử cung bình thường, B. Hở eo tử cung, C. Khâu vòng cổ tử cung\n\n2.2.3. Viêm nhiễm âm đạo - cổ tử cung\n2.2.4. Tiền sử sinh non\n- Nguy cơ tái phát 25 - 50 %. Nguy cơ này tăng cao nếu có nhiều lần sinh non trước đó.\n2.3. Do thai và phần phụ của thai\n- Ối vỡ non, ối vỡ sớm: 10% đủ tháng và 30% đẻ non, có nguy cơ nhiễm trùng cho thai.\n- Nhiễm trùng ối.\n- Đa thai: 10- 20% đẻ non.\n- Đa ối: do tử cung quá căng gây chuyển dạ sớm.\n- Rau tiền đạo: 10% trong các trường hợp đẻ non vì gây chảy máu trước đẻ hoặc ối vỡ.\n- Rau bong non.\nTóm lại muốn tìm hiểu nguyên nhân về đẻ non, ta phải xem xét lại toàn bộ bệnh lý sản phụ khoa, có những nguyên nhân về phía mẹ, về phía thai, và phần phụ của thai, có những nguyên nhân phối hợp.\n\n3. TRIỆU CHỨNG VÀ CHẨN ĐOÁN DOẠ ĐẺ NON VÀ ĐẺ NON\n3.1. Doạ đẻ non\n3.1.1. Triệu chứng cơ năng\n- Đau bụng: Sản phụ cảm giác đau bụng từng cơn hoặc trì nặng bụng dưới.\n- Ra dịch âm đạo: có thể là dịch nhầy âm đạo, ra máu hoặc nước ối.\n3.1.2. Triệu chứng thực thể\n- Cơn go tử cung: thưa nhẹ, có 1 - 2 cơn go tử cung trong 10 phút và thời gian quan sát trên 30 phút.\n- Cổ tử cung có thể còn dài, đóng kín nhưng cũng có thể xoá và mở đến < 4cm.\n- Ối vỡ non: dẫn đến chuyển dạ trong một thời gian ngắn. Nó là bước ngoặt trong đẻ non bởi vì nó làm cho buồng ối bị hở, tăng thêm nguy cơ nhiễm khuẩn.\n3.1.3. Cận lâm sàng\n- Siêu âm: khảo sát độ dài cổ tử cung, nếu dưới 2,5cm thì nguy cơ đẻ non cao.\n\nHình 2. Ðo cổ tử cung qua siêu âm với mẫu biểu đồ để đo độ dài,\nchiều dài hình nón và độ rộng cổ tử cung trong chẩn đoán dọa sinh non\n\n- Đánh giá thai và theo dõi cơn go bằng Monitoring, có 1-2 cơn co đều đặn trong 10 phút.\n- Chỉ số doạ đẻ non dưới 6\n- Ngoài ra cần làm các xét nghiệm để tìm nguyên nhân:\n+ Tế bào vi trùng nước tiểu.\n+ Xét nghiệm vi khuẩn ở cổ tử cung.\n+ Nếu sốt phải kéo máu tìm ký sinh trùng sốt rét, CRP, cấy máu tuỳ trường hợp. Cân nhắc việc chọc dò ối để loại bỏ khả năng nhiễm trùng màng ối.\n\n\nHình 3. Đánh giá thai và theo dõi cơn go bằng Monitoring,\n2 cơn co trong 10 phút ở thai 32 tuần\n\n3.2. Đẻ non\n3.2.1. Triệu chứng cơ năng\n- Đau bụng: Sản phụ đau bụng từng cơn, các cơn đau tăng dần.\n- Ra dịch âm đạo: có thể là dịch nhầy âm đạo, ra máu hoặc nước ối.\n3.2.2. Triệu chứng thực thể\n- Cơn go tử cung: có 2 - 3 cơn go tử cung trong 10 phút, tăng dần.\n- Cổ tử cung xoá trên 80%, hoặc mở trên 2 cm, đầu ối bắt đầu thành lập hoặc ối vỡ sớm.\n- Theo dõi cơn go bằng Monitoring, nếu có 2 - 3 cơn go đều đặn trong 10 phút.\n- Chỉ số doạ đẻ non lớn hơn 6\n4. CÁC YẾU TỐ TIÊN LƯỢNG:\nDựa vào 4 yếu tố: cơn go, thay đổi ở cổ tử cung, ối vỡ, ra máu âm đạo và người ta đã xây dựng nên một chỉ số doạ đẻ non\nBảng 1.  Chỉ số doạ đẻ non\nĐiểm\n\nYếu tố\n1\n2\n3\n4\n\nGo tử cung\nKhông đều\nĐều\n\n\n\nỐi vỡ\n\nCó thể\n\nRõ ràng\n\nRa máu\nVừa\n> 100ml\n\n\n\nMở cổ tử cung\n1cm\n2cm\n3cm\n( 4cm\n\n\nBảng 2 : Khả năng đình chỉ chuyển dạ thành công\n(theo chỉ số doạ đẻ non)\nChỉ số\n1\n2\n3\n4\n5\n6\n(7\n\nChuyển dạ ngừng lại          (%)\n100\n90\n84\n38\n11\n7\n0\n\n\n5. ĐIỀU TRỊ\n5.1. Doạ đẻ non\n5.1.1. Tuyến xã\n- Không nên điều trị doạ đẻ non, chuyển tuyến trên càng sớm càng tốt.\n5.1.2. Tuyến huyện và tuyến bệnh viện chuyên khoa:\nSử dụng các thuốc ức chế chuyển dạ.\t- Các nghiên cứu so sánh hiệu quả của các thuốc cho thấy không có thuốc nào có ưu thế vượt trội. Tất cả những thuốc này chỉ có thể kéo dài thời gian mang thai trong một khoảng thời gian hạn chế từ 2 -7 ngày, đây là khoảng thời gian để sử dụng steroid và vận chuyển bà mẹ đến cơ sở y tế có phòng hồi sức sơ sinh. Do đó, việc chọn loại thuốc nào phụ thuộc vào sự có sẵn của thuốc và những tác dụng phụ đối với bà mẹ và thai nhi.\n- Các loại bêta - mimetic\n+ Là các thuốc hướng beta giao cảm.\n- Ritodrine là thuốc có tác dụng trực tiếp làm giảm cơ trơn của tử cung và của phổi. Pha 150mg trong 500ml dung dịch mặn đẳng trương.\n+ Liều tấn công: Bắt đầu truyền với tốc độ 20ml/giờ và cứ 15 phút tăng lên 10ml/giờ và tăng tối đa là 70ml/giờ.\n+ Liều duy trì: Khi cắt được cơn tiếp tục duy trì thêm 12 giờ. Trước khi rút đường truyền 30 phút cho uống Ritodrine cứ 2 giờ 10mg trong 24 giờ và sau đó duy trì ở liều 20mg/4- 6 giờ cho đến khi thai  được 36 tuần. Ngưng thuốc khi nhịp tim mẹ trên 150 lần /phút và tim thai trên 200 lần/ phút. Huyết huyết áp tâm thu trên 180mmHg và huyết áp tâm trương dưới 40mmHg.\n+ Tác dụng phụ trên bà mẹ bao gồm: tăng nhịp tim, tăng đường huyết, tăng Insuline huyết, hạ Kali huyết, rùng mình, đánh trống ngực, bồn chồn, buồn nôn, nôn, ảo giác.\n+ Tác động lên thai nhi: nhịp tim nhanh, hạ canxi huyết, hạ đường huyết, hạ huyết áp, tăng bilirubine huyết, xuất huyết não thất.\n+ Chống chỉ định trong bệnh tim, cường giáp, tăng huyết áp không kiểm soát được, đái tháo đường nặng, các bện gan và bệnh thận mạn tính. Các bệnh nhân trên 35 tuổi cũng có chống chỉ định.\n- Terbutaline:  Chỉ định, chống chỉ định giống Ritodrine.\n+ Liều tấn cụng: Liều khởi đầu 250mcg, truyền TM với tốc độ 10ư80 àg/phỳt cho đến khi chuyển dạ ngừng lại. Sau đú tiờm dưới da 0,25ư 0,5mg/2ư 4giờ trong 12 giờ tiếp theo.\n+ Liều duy trì: liều uống 5mg cứ 4- 6 giờ một lần cho đến khi thai đươc 36 tuần. Tác dụng phụ trên bà mẹ: loạn nhịp, phù phổi, thiếu máu cơ tim, hạ huyết áp, nhịp tim nhanh. Tác động lên thai nhi: nhịp tim nhanh, tăng đường huyết, tăng Insuline huyết, phì đại cơ tim, thiếu máu cơ tim.\n- Atosiban (Tractocile): cho liều tấn công 6,75mg, tiêm tĩnh mạch chậm trong một phút, sau đó cho liều duy trì 18mg/giờ trong 3 giờ rồi duy trì 6mg/giờ trong 45 giờ. Tổng liều tối đa là 330mg.\n-  Các chất đối kháng Calci\n+ Magnesium Sulfate: Là thuốc thay thế cho các thuốc beta hướng giao cảm khi có chống chỉ định dùng các thuốc này hoặc khi có ngộ độc thuốc.\n* Liều tấn công: 4-6g trong 100ml Dextrose 5% truyền tĩnh mạch từ 15-20 phút.\n* Liều duy trì: 2g/giờ truyền TM, trong vòng 12 giờ, sau đó là 1g/1 giờ trong 24 -48 giờ. Theo dõi nồng độ Mg++ huyết thanh duy trì từ 5-7mg/dL.\n* Tác dụng phụ trên bà mẹ: nóng bừng, ngủ lịm, đau đầu, mệt mỏi, khô miệng, ức chế hô hấp, giảm phản xạ gân xương. Thử phản xạ gân xương để phát hiện quá liều thuốc. Ngừng tim và hô hấp có thể xuất hiện nếu dùng quá liều. Có thể dùng chất đối kháng là Calci (Calcium gluconate hoặc calci clorua liều 1g tiêm TM chậm).\n* Tác động lên thai nhi: ngủ lịm, giảm trương lực cơ, suy hô hấp.\n+  Nifedipine:\n* Liều tấn công: 20mg ngậm dưới lưỡi mỗi 20 phút, tối đa 3 liều.\n* Sau đó khi đã cắt cơn go thì duy trì liều 10-20mg đường uống trong mỗi 4-6 giờ.\n* Chống chỉ định đối với trường hợp có bệnh tim, huyết áp thấp (dưới 90/50mmHg). Không sử dụng cùng với Magnesium sulphate. Cẩn thận khi sử dụng cho người có bệnh lý ở thận.\n* Tác dụng phụ trên bà mẹ: nóng bừng, đau đầu, buồn nôn, hạ huyết áp thoáng qua. Tác động lên thai nhi: hiện chưa có ghi nhận đặc biệt gì.\n- Thuốc ức chế tổng hợp Prostaglandine: Indomethacin liều 25mg/6 giờ trong 5 ngày hoặc nhét hậu môn 100mg sau đó uống 25mg/6 giờ cho đến 24 giờ sau khi không còn cơn go nữa. Thuốc này có những tác động ngược trên thai nhi: co thắt ống động mạch, tăng áp lực phổi, thiểu ối, xuất huyết não thất, viêm ruột hoại tử và tăng bilirubine huyết\n- Sử dụng Corticosteroid\n+ Giúp cho phổi thai nhi trưởng thành tránh được bệnh màng trong, chỉ dùng cho trường hợp thai từ 28 đến hết 34 tuần.\n+ Cho corticoide ở mẹ làm giảm từ 40-60%  nguy cơ bệnh màng trong ở sơ sinh.\n+ Betamethason (Celestene) tiêm bắp 2 ống/ một ngày  hoặc một ống /ngày trong 2 ngày, hoặc Dexamethasone (Dexaron): 12mg/ngày (3 ống) tiêm bắp x 2 ngày liên tiếp. Hiệu quả tối đa của Corticosteroid đạt được trong vòng 24-48 giờ, do đó cố gắng trì hoãn cuộc chuyển dạ ít nhất 24 giờ sau khi sử dụng thuốc này. Chú ý loại trừ mẹ mắc bệnh đái đường thai nghén trước khi dùng corticosteroid.\n5.2. Đẻ non\n5.2.1. Tuyến xã\n- Tư vấn, chuyển tuyến trên càng sớm càng tốt\n- Trường hợp đã đẻ ở xã:\n+ Chăm sóc trẻ sơ sinh theo phác đồ chăm sóc trẻ sơ sinh non tháng, nhẹ cân.\n+Chăm sóc mẹ: theo dõi chảy máu, kiểm soát tử cung nếu rau thiếu                                                    tư vấn, chuyển tuyến trên nếu cần.\n5.2.2. Tuyến huyện và tuyến bệnh viện chuyên khoa\nThái độ xử trí cho một chuyển dạ đẻ non có khác nhau, tuỳ thuộc ối còn hay đã vỡ, tuổi thai là một yếu tố  rất quan trọng.\n- Cần đảm bảo cho trẻ ít bị chấn thương nhất trong đẻ vì trẻ non tháng rất yếu ớt. Người ta dễ dàng chỉ định mổ lấy thai vì lợi ích của đứa trẻ nếu là ngôi mông, suy thai.\n- Đẻ đường dưới được chấp nhận khi là ngôi chỏm và có đủ điều kiện.\n- Sau đẻ phải kiểm soát tử cung để tránh sót rau, tìm dị dạng tử cung, xét nghiệm vi khuẩn (rau, nước tiểu và trẻ sơ sinh).\n- Cần có sự theo dõi dặc biệt trong chuyển dạ và có phòng chăm sóc tích cực cho các trẻ non tháng sau đẻ.\n- Hồi sức thai và chống ngạt: Cho mẹ thở oxy ngắt quãng, mỗi lần 10 phút, 3-4 đợt/giờ, lưu lượng 6-8l /phút.\n- Tránh sang chấn cho thai: Bảo vệ đầu ối đến khi mở gần hết hoặc mở hết. Hạn chế sử dụng oxytocin. Giúp thai sổ dễ dàng bằng cách cắt rộng tầng sinh môn khi sổ thai.\n- Tránh mất nhiệt cho trẻ mới đẻ, đảm bảo ủ ấm cho trẻ.\n6. DỰ PHÒNG\nSau khi đã xác định các yếu tố nguy cơ, vai trò dự phòng là cố gắng loại bỏ các yếu tố nguy cơ:\nKhông nên đi du lịch xa, động viên nghỉ ngơi tối đa.\nTôn trọng thời gian nghỉ trước đẻ 6 tuần (8 tuần nếu trên 3 con)\nĐiều trị các nhiễm khuẩn nếu có.\nỔn định các bệnh lý của mẹ như nhiễm độc thai nghén, đái đường, đặc biệt các thai nghén có nguy cơ cao.\n- Khâu vòng cổ tử cung từ tuần thứ 12- 14 nếu có hở eo.\n\nHình 4. Kỹ thuật khâu vòng cổ tử cung theo phương pháp Mc Donald\n\n\n\nCâu hỏi:\n1. Hãy kể ra các nguyên nhân gây đẻ non\n2. Trình bày các triệu chứng chẩn đoán doạ đẻ non, đẻ non?\n3.Trình bày các yếu tố tiên lượng và dự phòng doạ đẻ non?\n4. Trình bày cách xử trí doạ đẻ non, đẻ non?\n\n\n\n\nTHAI GIÀ THÁNG\n\nMục tiêu học tập\n1. Phân tích quá trình sinh lý bệnh học của  thai già tháng.\n2. Mô tả các triệu chứng lâm sàng, cận lâm sàng của thai già tháng.\n3. Lựa chọn cách xử trí thai quá ngày sinh.\n\n1. ĐẠI CƯƠNG\n1.1. Định nghĩa\nThời gian thai nghén bình thường trung bình là 9 tháng 10 ngày hay 285 ngày (10 ngày tính từ ngày đầu của kinh cuối cùng).\nThai nghén được gọi là già tháng khi tuổi thai theo lý thuyết vượt quá 42 tuần hoặc 294 ngày.\n1.2. Tỷ lệ\nKhoảng 3- 12% thai nghén vượt quá tuần 42, nhưng thực tế thì tỷ lệ thai già tháng không vượt quá 4% (do không nhớ ngày kinh cuối cùng chính xác, hoặc thời gian phóng noãn chậm) .\nTỷ lệ biến chứng ở mẹ và thai gia tăng theo tuổi thai, tỷ lệ tử vong chu sinh tăng từ  giữa tuần thứ 41 và 42, gấp đôi vào tuần 43 và cao gấp 4 - 6 lần vào tuần 44 so với thai đủ tháng.\nBiến chứng cho mẹ ngay cả mổ lấy thai cũng tăng gấp đôi với chảy máu, nhiễm trùng, bục vết thương.\nVấn đề chẩn đoán và xử trí thai già tháng rất quan trọng vì tử vong sơ sinh cao, gấp 3 lần so với trẻ sinh trong khoảng 38 - 41 tuần.\n\n2. NGUYÊN NHÂN\nNguyên nhân của thai già tháng vẫn chưa biết rõ. Tuy nhiên có một số yếu tố nguy cơ như: thai vô sọ, thiếu sulfatase rau thai, sử dụng progesteron kéo dài, tiền sử sinh quá ngày.\nNguyên nhân thường gặp nhất là tính tuổi thai không chính xác.\n\n3. SINH LÝ BỆNH HỌC\nBánh rau và nước ối đóng một vai trò quan trọng trong quá trình vận chuyển và chuyển hóa sinh học của thai nhi. Trong thai già tháng, lượng nước ối giảm dần, bánh rau thoái hóa dần dẫn đến giảm dòng máu ở bánh rau và  các chất dinh dưỡng  đến thai. Do đó thai bị suy  trường diễn trong tử cung và có thể chết trong tử cung hoặc chết trong khi chuyển dạ (do có cơn go tử cung). Vì vậy, thai già tháng là thai nghén bị đe dọa, thiếu ôxy là nguyên nhân chính của suy thai, khi thai đẻ ra sống thì nó có biểu hiện tổn thương đặc biệt theo kiểu gầy, bị mất nước, da nhăn nheo nhuộm đầy phân su.\n\n4. CHẨN ĐOÁN\n4.1. Lâm sàng\n- Hỏi bệnh sử để định tuổi thai:\n+ Kinh cuối cùng:  lấy mốc là ngày đầu của kinh cuối cùng để tính tuổi thai.\n+ Thời gian thụ tinh: nếu có điều trị vô sinh, vì đây là mốc rất có giá trị để chẩn đoán tuổi thai.\n+ Lần thăm khám sản khoa đầu tiên: nếu có làm phản ứng sinh học, hoặc siêu âm  để chẩn đoán thai sớm (trong quý đầu) thì rất có giá trị.\n+ Thời gian xuất hiện thai máy: con so thường vào tuần thứ 18 tuần, con rạ tuần 16.\n+ Giảm cử động thai xảy ra đột ngột ở những thai phụ có thai đạp nhiều, cần phải được xem xét nghiêm túc.\n-  Đo bề cao tử cung giảm qua 2 lần thăm kế tiếp kèm với giảm lượng nước ối (có tính chất gợi ý).\n4.2. Xét nghiệm bổ sung\n- Siêu âm sớm (đặc biệt trong quý đầu) giúp chẩn đoán chính xác tuổi thai.\n- Siêu âm muộn ít chính xác hơn nhưng nếu thấy lượng nước ối ít và bánh rau vôi hóa cũng gợi ý chẩn đoán.\n- Doppler: Phương pháp này cho phép khảo sát tình trạng huyết động học của thai và tuần hoàn rau thai để tiên lượng suy thai.\n- Monitor thai để tìm suy thai mãn (thử nghiệm không đả kích 2 lần/ tuần hoặc thử nghiệm đã kích).\n- Soi ối: tìm dấu hiệu suy thai mãn, có thể thấy ối màu vàng hoặc màu  xanh  .\n- Chọc hút nước ối: chỉ cho khẳng định thai đã trưởng thành mà không cho phép chẩn đoán thai già tháng.\n- Chụp X quang để tìm  điểm hóa cốt:  điểm  Béclard (đầu dưới xương đùi). Điểm TOD  (đầu trên xương chày ). Tỷ lệ âm tính giả khá cao hiện nay ít được sử dụng\nHiện nay không có một tiêu chuẩn nào cho phép khẳng định chắc chắn thai già tháng, tuy nhiên tốt nhất có thể dựa vào:\n- Ngày kinh cuối cùng\n- Siêu âm\n- Lượng nước ối: Nước ối ít\nSau khi đã loại trừ các sai lầm lớn về tuổi thai, chỉ còn một khả năng là theo dõi chặt chẽ lúc cuối thời kỳ  thai nghén để phát hiện suy thai.\nDù sao đi nữa, mọi thai nghén vượt quá 41 tuần và 3 ngày là phải có ý kiến của bác sĩ sản khoa theo dõi và đỡ đẻ.\n\n5. BIẾN CHỨNG CỦA THAI QUÁ NGÀY\n5.1. Nguy cơ cho mẹ\n- Gia tăng khả năng mổ lấy thai và đẻ có can thiệp thủ thuật.\n- Chảy máu sau sinh.\n- Nằm viện dài ngày và có nhiều biến chứng.\n5.2. Nguy  cơ cho thai\n- Thiểu ối (thiểu năng rau thai)\n+ Chèn ép dây rốn\n+ Suy thai\n+ Tử vong thai đột ngột.\n- Rối loạn trưởng thành thai (chiếm tỷ lệ 10- 20% thai quá ngày).\n- Hội chứng hít phân su: 25-30 % thai 42 tuần có phân su trong dịch ối.\n- Thai lớn: gây đẻ khó, tổn thương xương và gãy xương và để lại chứng thần kinh tại chỗ và lâu dài.\n\n6. THEO DÕI VÀ XỬ TRÍ THAI GIÀ THÁNG\n6.1. Tuyến xã\nChuyển thai phụ lên tuyến trên sau khi đã tư vấn.\n6.2. Tuyến huyện trở lên\n6.2.1. Nhập viện\nNếu tuổi thai trên 41 tuần và phải được theo dõi sát, sản phụ sẽ được xác định độ trưởng thành và tình trạng sức khoẻ thai nhi.\nHướng dẫn bệnh nhân theo dõi cử động thai, hướng dẫn cho thai phụ đếm cử động thai bắt đầu vào một giờ nhất định trong ngày. Bình thường thai cử động trên 10 lần trong thời gian 12 giờ. Nếu số lần cử động thai giảm dần hay giảm đột ngột là dấu hiệu của suy thai.\nVí dụ sau 2 giờ mà không thấy thai máy cần cảnh giác. Sau 12 giờ không thấy thai máy có thể thai đã chết.\nTheo dõi chỉ số nước ối bằng siêu âm: Siêu âm thai kiểm tra dịch ối ít nhất 2 lần/tuần. Thiểu ối được định nghĩa khi chỉ số nước ối < 5 hoặc túi ối lớn nhất < 2 x 2cm). Thiểu ối có liên quan đến nguy cơ cao của suy thai và tử vong sơ sinh.\nTheo dõi suy thai bằng máy monitor: hai thử nghiệm hay được dùng là thử nghiệm không đả kích (non-stress test) và thử nghiệm đả kích (contraction stress test) như test vê núm vú hoặc test truyền oxytocin. Thử nghiệm này được làm 2 lần/tuần. Chỉ định mổ lấy thai nếu có xuất hiện Dip II.\n6.2.2. Chấm dứt thai kỳ\n- Trong trường hợp con hiếm hoặc bất tương xứng đầu chậu nên mổ lấy thai.\n-  Nếu có tình trạng suy thai: mổ lấy thai.\n- Trong những trường hợp khác như thai đã trưởng thành, thai không suy, tiến hành làm test đả kích, nếu dương tính phải mổ lấy thai. Nếu âm tính, phải khởi phát chuyển dạ và đánh giá chỉ số Bishop để tiên lượng khả năng gây chuyển dạ.\n\nBảng chỉ số Bishop\nĐiểm\n\nĐánh gía\n0 điểm\n1 điểm\n2 điểm\n3 điểm\n\nĐộ mở CTC (cm)\n0\n1 - 2\n3 - 4\n5 - 6\n\nĐộ xoá CTC (%)\n0-30\n40 - 50\n60 - 70\n>=80\n\nĐộ lọt của thai\n-3\n-2\n-1 - 0\n+1 - +2\n\nMật độ CTC\nCứng\nVừa\nMềm\n\n\nHướng CTC\nSau\nTrung gian\ntrước\n\n\n\n- Nếu CTC có thể mở, chỉ số Bishop trên 5, gây chuyển dạ bằng truyền Oxytocin. Trong khi giục sinh phải theo dõi sát tim thai bằng monitoring vì thai có thể suy rất nhanh.\n- Nếu CTC không mở, chỉ số Bishop dưới 5, nên kết hợp với các phương pháp thăm dò khác như theo dõi cử động thai, siêu âm đánh giá chỉ số nước ối, monitoring để quyết định gây chuyển dạ hoặc theo dõi tiếp.\n- Trong trường hợp gây chuyển dạ, làm mềm CTC bằng PGE2 (Dinoprostol) 1-2 mg, tối đa không quá 4 mg đặt âm đạo.\n- Nếu trong quá trình chuyền thất bại hoặc xuất hiện suy thai thì cũng phải mổ lấy thai.\n6.3. Chăm sóc em bé\nCần phải xem lại trẻ sơ sinh có bị bong da hay không, rau, ối như thế nào. Khi đã xác định là thai già tháng, cần phải thực hiện các biện pháp săn sóc đặc biệt, hút kỹ phân su đường hô hấp, điều chỉnh toan biến dưỡng, tiêm Vitamin K1, kháng sinh dự  phòng...và theo dõi sự phát triển của trẻ.\nLưu ý: chẩn đoán thai già tháng dựa vào những dấu hiệu nghi ngờ. Do đó đòi hỏi người thầy thuốc phải theo dõi sát bệnh nhân và quyết định xử trí đúng lúc, tránh những can thiệp trên một thai chưa đủ tháng, nhưng cũng không để xảy ra tình trạng suy thai và tử vong thai trong bụng mẹ do rau già  cỗi và thoái hóa.", "priority": "Cao (Trọng tâm BSNT)"}, {"id": "SK-22", "chapter": "Chương 2. Sản bệnh", "folder": "02_San_benh", "title": "Đa ối", "author": "Ths. BSCK II. Hoàng Tiến Nam", "word_count": 2163, "line_count": 99, "key_numbers": ["1500ml", "2000ml", "25 cm", "3 mg", "3 tháng", "32 tuần", "375 ml", "39 tuần", "72 giờ", "800ml"], "key_drugs": ["oxytocin"], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["ĐA ỐI", "Ths. BSCK II. Hoàng Tiến Nam"], "bullets": []}, {"heading": "1. CHỨC NĂNG SINH LÝ CỦA NƯỚC ỐI", "paragraphs": ["Túi ối được tạo ra khoảng ngày thứ 12 sau khi trứng thụ tinh. Trong quí đầu của thời kỳ thai nghén, nước ối có tính đẳng trương và tương tự như huyết tương của người mẹ. Trong quý hai và nửa sau của thời kỳ thai nghén dịch ối trở nên nhược trương.", "Thể tích nước ối tăng dần cho đến đầu của 3 tháng cuối thai kỳ và từ đó hằng định cho đến khi thai đủ tháng. Trong giai đoạn tuần thứ 37 đến tuần thứ 41, thể tích nước ối giảm đi 10%. Từ tuần thứ 42 trở đi, thể tích nước ối giảm đi rất nhanh, khoảng 33% trong một tuần.", "Nước ối có vai trò:", "Bảo vệ thai khỏi các sang chấn trực tiếp lên tử cung.", "Điều hoà thân nhiệt cho thai nhi.", "Cho phép thai cử động tự do trong tử cung.", "Trao đổi nước, điện giải giữa thai nhi và mẹ.", "Giúp cho sự bình chỉnh của thai nhi.", "Trong chuyển dạ, đầu ối giúp cho sự xoá mở cổ tử cung.", "Dịch ối thay đổi tuỳ thuộc chủ yếu vào sự bài tiết của màng ối, sự thẩm thấu của thành mạch và nước tiểu của thai nhi. Trong vòng một giờ có khoảng 350 - 375 ml nước ối được thay thế."], "bullets": []}, {"heading": "2. NGUYÊN NHÂN", "paragraphs": ["Nói chung đa ối là do sự sản xuất quá mức nước ối hoặc do rối loạn tái hấp thu của nước ối. Có những nguyên nhân về phía mẹ, thai nhi và rau thai."], "bullets": []}, {"heading": "2.1. Nguyên nhân về phía mẹ", "paragraphs": ["Tiểu đường trước hoặc trong khi mang thai là nguyên nhân thường gặp.", "Kháng thể kháng Rh và các bệnh tán huyết thứ phát do kháng thể bất thường có thể gây tình trạng thiếu máu thai nhi trầm trọng hoặc phù thai nhi có liên quan đến tình trạng đa ối.", "Loạn dưỡng tăng trương lực cơ (ít gặp)."], "bullets": []}, {"heading": "2.2. Nguyên nhân rau thai", "paragraphs": ["U mạch máu màng đệm có thể gây suy tim thai nhi và dẫn đến tình trạng đa ối.", "Các bệnh lý viêm nội mạc tử cung hoặc gây thương tổn bánh rau (giang mai)"], "bullets": []}, {"heading": "2.3. Nguyên nhân do thai", "paragraphs": ["Bất thường hệ thống thần kinh trung ương thai nhi (vô sọ, khuyết tật ống nơron thần kinh).", "Khuyết tật cấu trúc hệ thống tiêu hoá (tắc ống thực quản hoặc ống tiêu hoá).", "Bất thường nhiễm sắc thể thai nhi.", "Phù thai không do yếu tố miễn dịch: có tiên lượng rất xấu và thường liên quan đến đa ối. Trường hợp điển hình có tình trạng phù rau thai.", "Hội chứng truyền máu song thai: là một rối loạn có tiên lượng xấu, xuất hiện với tỷ lệ 15% trong thai nghén song thai một màng đệm, hai túi ối, là biến chứng do đa ối ở thai nhận máu."], "bullets": []}, {"heading": "3. TRIỆU CHỨNG VÀ CHẨN ĐOÁN", "paragraphs": ["Hình 1.  Đa ối.", "Bình thường lượng nước ối khoảng 300 - 800ml, từ 800 -1500ml gọi là dư ối. Đa ối khi lượng nước ối vượt quá trên 2000ml (con số này ít có ý nghĩa vì trên thực tế lâm sàng không thể ước lượng chính xác được lượng nước ối. Chẩn đoán được thực hiện bằng siêu âm và cho kết quả ước lượng gián tiếp về thể tích nước ối).", "Tỷ lệ đa ối khoảng 0,2 - 1,6 %.", "Người ta thường dùng chỉ số nước ối (A.F.I: amniotic fluid index) qua siêu âm để xác định đa ối. Gọi là đa ối khi chỉ số nước ối (A.F.I) vượt trên 25 cm (đo theo kỹ thuật của Phelan) phương pháp này nên được ưu tiên sử dụng trong trường hợp song thai."], "bullets": []}, {"heading": "3.1. Các hình thái lâm sàng", "paragraphs": ["Trên lâm sàng ta có thể gặp 2 hình thái, đó là đa ối cấp và đa ối mãn, đa ối cấp ít gặp hơn."], "bullets": []}, {"heading": "3.1.1. Đa ối cấp", "paragraphs": ["Đa ối cấp thường xảy ra vào tuần thứ 16-20 của thai kỳ, thường gây chuyển dạ trước tuần thứ 28 hoặc do các triệu chứng quá trầm trọng nên phải đình chỉ thai nghén.", "Những triệu chứng chủ yếu gây ra do nước ối phát triển nhanh làm tử cung to nhanh chèn ép vào cơ hoành gây khó thở. Hình ảnh lâm sàng phụ thuộc vào mức độ của đa ối và mức độ nhanh chóng của giai đoạn khởi bệnh:", "Dị dạng cấu trúc thai nhi cần được loại trừ bằng siêu âm trong tình huống này vì đa ối cấp tính có thể kèm theo dị dạng thai nhi như tắc nghẽn thực quản hoặc đoạn cao của ống tiêu hoá, quái thai vô sọ, tật nứt cột sống (spina bifida)...."], "bullets": ["- Bụng lớn nhanh và căng cứng", "- Tử cung căng cứng và ấn đau", "- Không sờ được các phần thai nhi, khám kỹ có thể có dấu hiệu cục đá nổi.", "- Tim thai khó nghe hoặc nghe xa xăm.", "- Thăm âm đạo thấy đoạn dưới căng phồng, cổ tử cung hé mở, đầu ối căng", "- Phù và giãn tĩnh mạch đặc biệt là chi dưới do tĩnh mạch chủ dưới bị chèn ép.", "- Tình trạng khó thở ở bà mẹ và tiếp theo có thể xảy ra suy hô hấp."]}, {"heading": "3.1.2. Đa ối mãn", "paragraphs": ["Đa ối mãn chiếm 95% các trường hợp đa ối và thường xảy ra vào những tháng cuối của thai kỳ. Bệnh tiến triển chậm nên bệnh nhân dễ thích nghi với các triệu chứng hơn. Bệnh nhân không đau nhiều và không khó thở nhiều như trong đa ối cấp.", "Sản phụ đến khám trong ba tháng cuối vì cảm thấy nặng bụng, bụng căng, khó thở, tim đập nhanh. Các triệu chứng thường phát triển từ từ. Nước ối tăng dần đến một lượng lớn làm tử cung căng to gây khó thở, mệt mỏi.", "Khám thực thể:"], "bullets": ["- Tử cung lớn hơn so với tuổi thai.", "- Có dấu hiệu sóng vỗ.", "- Sờ nắn khó thấy các cực của thai nhi và có dấu hiệu cục đá nổi.", "- Thăm âm đạo thấy đoạn dưới căng phồng."]}, {"heading": "3.2. Cận lâm sàng", "paragraphs": [], "bullets": ["- Siêu âm: Siêu âm không những có vai trò giúp chẩn đoán xác định mà còn giúp phát hiện sớm những bất thường của thai nhi và phần phụ.", "- Xét nghiệm nước ối: định lượng(( Feto - protein, Acetylcholinestease, làm nhiễm sắt thể phát hiện các khuyết tật ống thần kinh.", "- Các xét nghiệm tổng quát khác để tìm các bệnh có thể có của mẹ như giang mai, đái đường, nhiễm Toxoplasma, nhóm máu và sàng lọc kháng thể..."]}, {"heading": "3.3. Chẩn đoán phân biệt", "paragraphs": [], "bullets": ["- Chửa trứng: gặp trong thời kỳ đầu của thai kỳ, bụng thường lớn nhanh hơn so với tuổi thai, có ra máu âm đạo tự nhiên, ít một. Định lượng thấy (hCG huyết thanh rất cao, siêu âm thấy hình ảnh tuyết rơi hay chùm nho, ruột bánh mỳ.", "- Song thai: bụng to nhanh đều trong thai kỳ, có nghén nhiều, thai máy nhiều chỗ, khám thấy nhiều cực, nhiều chi… Chẩn đoán loại trừ chính xác qua siêu âm.", "- Bụng báng: không có dấu hiệu thai nghén, có dấu sóng vỗ, gõ đục vùng thấp, bụng bè ngang, có tuần hoàn bàng hệ. Chẩn đoán phân biệt nhờ siêu âm.", "- Khối u buồng trứng: bệnh nhân thường không có biểu hiện của có thai và các triệu chứng nghén, bụng thường lớn dần, đôi khi có cảm giác tức nặng hay đau nhiều trong trường hợp có biến chứng.Khám lâm sàng và siêu âm giúp chẩn đoán phân biệt.", "- Bí tiểu cấp: bệnh nhân có cảm giác căng tức và xuất hiện bụng lớn nhanh mà trước đó không có. Khi nghi ngờ nên thông tiểu"]}, {"heading": "4. ĐIỀU TRỊ", "paragraphs": ["Việc nghỉ ngơi, dùng thuốc lợi tiểu, hạn chế uống nước, và muối là những biện pháp ít có hiệu quả và không nên khuyến khích sử dụng các biện pháp này."], "bullets": []}, {"heading": "4.1. Đa ối cấp", "paragraphs": [], "bullets": ["- Chọc ối: làm giảm các triệu chứng về hô hấp cho mẹ. Đây chỉ là liệu pháp có tính chất tạm thời.", "- Đình chỉ thai nghén bằng cách gây chuyển dạ: Nếu thai nhi có dị dạng cấu trúc hoặc bất thường nhiễm sắc thể, nhân viên y tế cần phải tư vấn cho cặp vợ chồng về tiên lượng và một số giải pháp để lựa chọn, bao gồm cả việc chấm dứt thai nghén."]}, {"heading": "4.2. Đa ối mãn", "paragraphs": ["Trong trường hợp bệnh nhẹ thì không cần can thiệp mà chỉ chờ đợi cho thai nhi đủ tháng nếu không có các chỉ định sản khoa khác.", "Nếu bệnh nhân xuất hiện khó thở, đau bụng hoặc đi lại khó khăn thì cho bệnh nhân nhập viện.", "Liều dùng 1,5 - 3 mg/kg/ngày.", "Trong chuyển dạ thường cơn co tử cung yếu do tử cung bị căng quá mức do đó có thể bấm ối sớm để làm giảm áp lực của buồng ối giúp chuyển dạ tiến triển nhanh hơn.", "Khi tia ối chú ý cố định ngôi thai để đề phòng sa dây rốn.", "Nếu cần, có thể hỗ trợ cơn co tử cung bằng truyền oxytocin.", "Do tử cung quá căng, nguy cơ chảy máu sau sinh do đờ tử cung vì vậy phải cho thuốc co bóp tử cung ngay sau sinh."], "bullets": ["- Điều trị nội khoa: Gần đây người ta dùng Indomethacine để điều trị đa ối. Thuốc này có tác dụng làm giảm lượng dịch ối tiết ra hoặc làm tăng sự tái hấp thu nước ối, làm giảm lượng nước tiểu thai nhi thải ra và làm tăng sự trao đổi dịch qua màng thai. Tuy nhiên, Indomethacine gây tình trạng đóng sớm ống động mạch nếu sử dụng kéo dài trên 48 -72 giờ hoặc sử dụng sau khi thai được 32 tuần. Có một số biến chứng khác của thai nhi và trẻ sơ sinh đã được biết có liên quan đến việc sử dụng Indomethacine. Bao gồm: tăng tỷ lệ viêm ruột hoại tử ở trẻ sơ sinh, tăng huyết áp mạch phổi, thiểu năng thận ở trẻ sơ sinh. Chính vì những lý do nêu trên, Indomethacin ít được sử dụng trong điều trị đa ối và phải hết sức cẩn thận khi dùng.", "- Gây chuyển dạ: khi thai 38-39 tuần hoặc thai phụ khó thở, đi lại khó khăn.", "- Bấm ối khi sinh: Bấm ối chủ động làm giảm căng tử cung và giúp chuyển dạ được tiến triển thuận lợi, đồng thời hạn chế rau bong non và sa dây rốn. Do có một lượng dịch lớn nên khi lượng dịch này bị rút đi đột ngột làm giảm nhanh áp lực và diện tiếp xúc giữa rau thai và buồng tử cung, điều này có thể làm rau bong non và sa dây rốn. Do đó, cần phải thực hiện thủ thuật bấm ối một cách thận trọng, sử dụng kim để dịch ối chảy ra từ từ. Cần phải chuẩn bị sẵn sàng cho cuộc mổ lấy thai đề phòng có tai biến xảy ra khi bấm ối."]}, {"heading": "5. TIÊN LƯỢNG", "paragraphs": ["Nói chung tỷ lệ tử vong chu sinh tăng cao theo độ trầm trong của đa ối.", "Tiên lượng con xấu dù trên siêu âm không phát hiện các dị dạng thai.", "Tỷ lệ tử vong trẻ cao do thai thường đẻ non kèm với thai bất thường (39%), sa dây rốn, rau bong non do buồng tử cung bị căng quá mức...", "Biến chứng mẹ hay gặp là chảy máu do đờ tử cung, rau bong non, ngôi thai bất thường làm tăng chỉ định các thủ thuật can thiệp. Các biểu hiện về rối loạn hô hấp của mẹ có thể xuất hiện, từ mức khó thở cho đến tình trạng suy hô hấp nặng. Tình trạng này có thể thấy rõ trong các trường hợp đa ối cấp."], "bullets": []}, {"heading": "Câu hỏi:", "paragraphs": ["1: Anh (Chị) trỡnh bày triệu chứng lâm sàng, cận lâm sàng để chẩn đoán xác định, chẩn đoán phân biệt đa ối cấp?", "2: Anh (Chị) trỡnh bày triệu chứng lâm sàng, cận lâm sàng để chẩn đoán xác định, chẩn đoán phân biệt đa ối món?"], "bullets": []}], "raw_text": "ĐA ỐI\nThs. BSCK II. Hoàng Tiến Nam\nMục tiêu học tập\n1. Liệt kê các nguyên nhân gây đa ối.\n2. Trình bày được các triệu chứng của đa ối cấp và đa ối mãn.\n3. Nói được chẩn đoán phân biệt được đa ối và một số  bệnh lý khác.\n4. Trình bày được hướng xử  trí của đa ối.\n1. CHỨC NĂNG SINH LÝ CỦA NƯỚC ỐI\nTúi ối được tạo ra khoảng ngày thứ 12 sau khi trứng thụ tinh. Trong quí đầu của thời kỳ thai nghén, nước ối có tính đẳng trương và tương tự như huyết tương của người mẹ. Trong quý hai và nửa sau của thời kỳ thai nghén dịch ối trở nên nhược trương.\nThể tích nước ối tăng dần cho đến đầu của 3 tháng cuối thai kỳ và từ đó hằng định cho đến khi thai đủ tháng. Trong giai đoạn tuần thứ 37 đến tuần thứ 41, thể tích nước ối giảm đi 10%. Từ tuần thứ 42 trở đi, thể tích nước ối giảm đi rất nhanh, khoảng 33% trong một tuần.\nNước ối có vai trò:\nBảo vệ thai khỏi các sang chấn trực tiếp lên tử cung.\nĐiều hoà thân nhiệt cho thai nhi.\nCho phép thai cử động tự do trong tử cung.\nTrao đổi nước, điện giải giữa thai nhi và mẹ.\nGiúp cho sự bình chỉnh của thai nhi.\nTrong chuyển dạ, đầu ối giúp cho sự xoá mở cổ tử cung.\nDịch ối thay đổi tuỳ thuộc chủ yếu vào sự bài tiết của màng ối, sự thẩm thấu của thành mạch và nước tiểu của thai nhi. Trong vòng một giờ có khoảng 350 - 375 ml nước ối được thay thế.\n\n2. NGUYÊN NHÂN\nNói chung đa ối là do sự sản xuất quá mức nước ối hoặc do rối loạn tái hấp thu của nước ối. Có những nguyên nhân về phía mẹ, thai nhi và rau thai.\n2.1. Nguyên nhân về phía mẹ\nTiểu đường trước hoặc trong khi mang thai là nguyên nhân thường gặp.\nKháng thể kháng Rh và các bệnh tán huyết thứ phát do kháng thể bất thường có thể gây tình trạng thiếu máu thai nhi trầm trọng hoặc phù thai nhi có liên quan đến tình trạng đa ối.\nLoạn dưỡng tăng trương lực cơ (ít gặp).\n2.2. Nguyên nhân rau thai\nU mạch máu màng đệm có thể gây suy tim thai nhi và dẫn đến tình trạng đa ối.\nCác bệnh lý viêm nội mạc tử cung hoặc gây thương tổn bánh rau (giang mai)\n2.3. Nguyên nhân do thai\nBất thường hệ thống thần kinh trung ương thai nhi (vô sọ, khuyết tật ống nơron thần kinh).\nKhuyết tật cấu trúc hệ thống tiêu hoá (tắc ống thực quản hoặc ống tiêu hoá).\nBất thường nhiễm sắc thể thai nhi.\nPhù thai không do yếu tố miễn dịch: có tiên lượng rất xấu và thường liên quan đến đa ối. Trường hợp điển hình có tình trạng phù rau thai.\nHội chứng truyền máu song thai: là một rối loạn có tiên lượng xấu, xuất hiện với tỷ lệ 15% trong thai nghén song thai một màng đệm, hai túi ối, là biến chứng do đa ối ở thai nhận máu.\n3. TRIỆU CHỨNG VÀ CHẨN ĐOÁN\n\nHình 1.  Đa ối.\nBình thường lượng nước ối khoảng 300 - 800ml, từ 800 -1500ml gọi là dư ối. Đa ối khi lượng nước ối vượt quá trên 2000ml (con số này ít có ý nghĩa vì trên thực tế lâm sàng không thể ước lượng chính xác được lượng nước ối. Chẩn đoán được thực hiện bằng siêu âm và cho kết quả ước lượng gián tiếp về thể tích nước ối).\nTỷ lệ đa ối khoảng 0,2 - 1,6 %.\nNgười ta thường dùng chỉ số nước ối (A.F.I: amniotic fluid index) qua siêu âm để xác định đa ối. Gọi là đa ối khi chỉ số nước ối (A.F.I) vượt trên 25 cm (đo theo kỹ thuật của Phelan) phương pháp này nên được ưu tiên sử dụng trong trường hợp song thai.\n3.1. Các hình thái lâm sàng\nTrên lâm sàng ta có thể gặp 2 hình thái, đó là đa ối cấp và đa ối mãn, đa ối cấp ít gặp hơn.\n3.1.1. Đa ối cấp\nĐa ối cấp thường xảy ra vào tuần thứ 16-20 của thai kỳ, thường gây chuyển dạ trước tuần thứ 28 hoặc do các triệu chứng quá trầm trọng nên phải đình chỉ thai nghén.\nNhững triệu chứng chủ yếu gây ra do nước ối phát triển nhanh làm tử cung to nhanh chèn ép vào cơ hoành gây khó thở. Hình ảnh lâm sàng phụ thuộc vào mức độ của đa ối và mức độ nhanh chóng của giai đoạn khởi bệnh:\n- Bụng lớn nhanh và căng cứng\n- Tử cung căng cứng và ấn đau\n- Không sờ được các phần thai nhi, khám kỹ có thể có dấu hiệu cục đá nổi.\n- Tim thai khó nghe hoặc nghe xa xăm.\n- Thăm âm đạo thấy đoạn dưới căng phồng, cổ tử cung hé mở, đầu ối căng\n- Phù và giãn tĩnh mạch đặc biệt là chi dưới do tĩnh mạch chủ dưới bị chèn ép.\n- Tình trạng khó thở ở bà mẹ và tiếp theo có thể xảy ra suy hô hấp.\nDị dạng cấu trúc thai nhi cần được loại trừ bằng siêu âm trong tình huống này vì đa ối cấp tính có thể kèm theo dị dạng thai nhi như tắc nghẽn thực quản hoặc đoạn cao của ống tiêu hoá, quái thai vô sọ, tật nứt cột sống (spina bifida)....\n3.1.2. Đa ối mãn\nĐa ối mãn chiếm 95% các trường hợp đa ối và thường xảy ra vào những tháng cuối của thai kỳ. Bệnh tiến triển chậm nên bệnh nhân dễ thích nghi với các triệu chứng hơn. Bệnh nhân không đau nhiều và không khó thở nhiều như trong đa ối cấp.\nSản phụ đến khám trong ba tháng cuối vì cảm thấy nặng bụng, bụng căng, khó thở, tim đập nhanh. Các triệu chứng thường phát triển từ từ. Nước ối tăng dần đến một lượng lớn làm tử cung căng to gây khó thở, mệt mỏi.\nKhám thực thể:\n- Tử cung lớn hơn so với tuổi thai.\n- Có dấu hiệu sóng vỗ.\n- Sờ nắn khó thấy các cực của thai nhi và có dấu hiệu cục đá nổi.\n- Thăm âm đạo thấy đoạn dưới căng phồng.\n3.2. Cận lâm sàng\n- Siêu âm: Siêu âm không những có vai trò giúp chẩn đoán xác định mà còn giúp phát hiện sớm những bất thường của thai nhi và phần phụ.\n- Xét nghiệm nước ối: định lượng(( Feto - protein, Acetylcholinestease, làm nhiễm sắt thể phát hiện các khuyết tật ống thần kinh.\n- Các xét nghiệm tổng quát khác để tìm các bệnh có thể có của mẹ như giang mai, đái đường, nhiễm Toxoplasma, nhóm máu và sàng lọc kháng thể...\n3.3. Chẩn đoán phân biệt\n- Chửa trứng: gặp trong thời kỳ đầu của thai kỳ, bụng thường lớn nhanh hơn so với tuổi thai, có ra máu âm đạo tự nhiên, ít một. Định lượng thấy (hCG huyết thanh rất cao, siêu âm thấy hình ảnh tuyết rơi hay chùm nho, ruột bánh mỳ.\n- Song thai: bụng to nhanh đều trong thai kỳ, có nghén nhiều, thai máy nhiều chỗ, khám thấy nhiều cực, nhiều chi… Chẩn đoán loại trừ chính xác qua siêu âm.\n- Bụng báng: không có dấu hiệu thai nghén, có dấu sóng vỗ, gõ đục vùng thấp, bụng bè ngang, có tuần hoàn bàng hệ. Chẩn đoán phân biệt nhờ siêu âm.\n- Khối u buồng trứng: bệnh nhân thường không có biểu hiện của có thai và các triệu chứng nghén, bụng thường lớn dần, đôi khi có cảm giác tức nặng hay đau nhiều trong trường hợp có biến chứng.Khám lâm sàng và siêu âm giúp chẩn đoán phân biệt.\n- Bí tiểu cấp: bệnh nhân có cảm giác căng tức và xuất hiện bụng lớn nhanh mà trước đó không có. Khi nghi ngờ nên thông tiểu\n\n4. ĐIỀU TRỊ\nViệc nghỉ ngơi, dùng thuốc lợi tiểu, hạn chế uống nước, và muối là những biện pháp ít có hiệu quả và không nên khuyến khích sử dụng các biện pháp này.\n4.1. Đa ối cấp\n- Chọc ối: làm giảm các triệu chứng về hô hấp cho mẹ. Đây chỉ là liệu pháp có tính chất tạm thời.\n- Đình chỉ thai nghén bằng cách gây chuyển dạ: Nếu thai nhi có dị dạng cấu trúc hoặc bất thường nhiễm sắc thể, nhân viên y tế cần phải tư vấn cho cặp vợ chồng về tiên lượng và một số giải pháp để lựa chọn, bao gồm cả việc chấm dứt thai nghén.\n\n4.2. Đa ối mãn\nTrong trường hợp bệnh nhẹ thì không cần can thiệp mà chỉ chờ đợi cho thai nhi đủ tháng nếu không có các chỉ định sản khoa khác.\nNếu bệnh nhân xuất hiện khó thở, đau bụng hoặc đi lại khó khăn thì cho bệnh nhân nhập viện.\n- Điều trị nội khoa: Gần đây người ta dùng Indomethacine để điều trị đa ối. Thuốc này có tác dụng làm giảm lượng dịch ối tiết ra hoặc làm tăng sự tái hấp thu nước ối, làm giảm lượng nước tiểu thai nhi thải ra và làm tăng sự trao đổi dịch qua màng thai. Tuy nhiên, Indomethacine gây tình trạng đóng sớm ống động mạch nếu sử dụng kéo dài trên 48 -72 giờ hoặc sử dụng sau khi thai được 32 tuần. Có một số biến chứng khác của thai nhi và trẻ sơ sinh đã được biết có liên quan đến việc sử dụng Indomethacine. Bao gồm: tăng tỷ lệ viêm ruột hoại tử ở trẻ sơ sinh, tăng huyết áp mạch phổi, thiểu năng thận ở trẻ sơ sinh. Chính vì những lý do nêu trên, Indomethacin ít được sử dụng trong điều trị đa ối và phải hết sức cẩn thận khi dùng.\nLiều dùng 1,5 - 3 mg/kg/ngày.\n- Gây chuyển dạ: khi thai 38-39 tuần hoặc thai phụ khó thở, đi lại khó khăn.\n- Bấm ối khi sinh: Bấm ối chủ động làm giảm căng tử cung và giúp chuyển dạ được tiến triển thuận lợi, đồng thời hạn chế rau bong non và sa dây rốn. Do có một lượng dịch lớn nên khi lượng dịch này bị rút đi đột ngột làm giảm nhanh áp lực và diện tiếp xúc giữa rau thai và buồng tử cung, điều này có thể làm rau bong non và sa dây rốn. Do đó, cần phải thực hiện thủ thuật bấm ối một cách thận trọng, sử dụng kim để dịch ối chảy ra từ từ. Cần phải chuẩn bị sẵn sàng cho cuộc mổ lấy thai đề phòng có tai biến xảy ra khi bấm ối.\nTrong chuyển dạ thường cơn co tử cung yếu do tử cung bị căng quá mức do đó có thể bấm ối sớm để làm giảm áp lực của buồng ối giúp chuyển dạ tiến triển nhanh hơn.\nKhi tia ối chú ý cố định ngôi thai để đề phòng sa dây rốn.\nNếu cần, có thể hỗ trợ cơn co tử cung bằng truyền oxytocin.\nDo tử cung quá căng, nguy cơ chảy máu sau sinh do đờ tử cung vì vậy phải cho thuốc co bóp tử cung ngay sau sinh.\n\n5. TIÊN LƯỢNG\nNói chung tỷ lệ tử vong chu sinh tăng cao theo độ trầm trong của đa ối.\nTiên lượng con xấu dù trên siêu âm không phát hiện các dị dạng thai.\nTỷ lệ tử vong trẻ cao do thai thường đẻ non kèm với thai bất thường (39%), sa dây rốn, rau bong non do buồng tử cung bị căng quá mức...\nBiến chứng mẹ hay gặp là chảy máu do đờ tử cung, rau bong non, ngôi thai bất thường làm tăng chỉ định các thủ thuật can thiệp. Các biểu hiện về rối loạn hô hấp của mẹ có thể xuất hiện, từ mức khó thở cho đến tình trạng suy hô hấp nặng. Tình trạng này có thể thấy rõ trong các trường hợp đa ối cấp.\nCâu hỏi:\n1: Anh (Chị) trỡnh bày triệu chứng lâm sàng, cận lâm sàng để chẩn đoán xác định, chẩn đoán phân biệt đa ối cấp?\n2: Anh (Chị) trỡnh bày triệu chứng lâm sàng, cận lâm sàng để chẩn đoán xác định, chẩn đoán phân biệt đa ối món?\n3. Anh (Chị) trỡnh bày nguyờn tắc và cỏc phương phỏp điều trị đa ối cấp và đa ối món?", "priority": "Cao (Trọng tâm BSNT)"}, {"id": "SK-23", "chapter": "Chương 2. Sản bệnh", "folder": "02_San_benh", "title": "Thiểu ối", "author": "Ths. BSCK II. Hoàng Tiến Nam", "word_count": 1385, "line_count": 63, "key_numbers": ["10 mm", "2  cm", "35 tuần"], "key_drugs": ["Prostaglandin"], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["THIỂU ỐI"], "bullets": []}, {"heading": "1. ĐẠI CƯƠNG", "paragraphs": ["Thiểu ối là khi lượng nước ối giảm so với lượng nước ối bình thường tính theo tuổi thai và ở dưới đường bách phân (percentile) thứ 5.", "Tỷ lệ thiểu ối khoảng 0,4 - 3,9%.", "Nguyên nhân dẫn tới thiểu ối bao gồm ối vỡ sớm, ối vỡ non, bất thường cấu trúc thai nhi, thai quá ngày sinh, thai kém phát triển trong tử cung... Tuy nhiên, có nhiều trường hợp thiểu ối  không xác định được nguyên nhân.", "Thiểu ối xảy ra trong giai đoạn sớm của thai kỳ thường có tiên lượng xấu, trong khi thiểu ối ở thai quá ngày sinh thường có tiên lượng tốt hơn.", "Thiểu ối có nguy cơ gây chèn ép dây rốn và đưa đến suy thai, nguy cơ này càng tăng lên trong chuyển dạ."], "bullets": []}, {"heading": "2.1. Nguyên nhân do mẹ", "paragraphs": [], "bullets": ["- Bệnh lý của người mẹ có ảnh hưởng đến tính thấm của màng ối và chức năng của rau thai gây thai kém phát triển và chức năng tái tạo nước ối như: bệnh cao huyết áp, tiền sản giật, bệnh về lý về gan, thận..."]}, {"heading": "2.2. Nguyên nhân do thai", "paragraphs": ["Ở mọi giai đoạn của thai kỳ, nguyên nhân thường gặp nhất của thiểu ối là vỡ ối sớm.  Thường có một số bất thường bẩm sinh của thai kỳ kèm theo thiểu ối. Các bất thường của thai kết hợp với thiểu ối hay gặp là:", "Thiểu ối trong thai chậm phát triển trong tử cung xảy ra sau một tình trạng thiếu oxy của bào thai, giảm tưới máu phổi và giảm tiết dịch.", "Nhiễm trùng thai cũng có thể là một nguyên nhân của thiểu ối. Một số thuốc kháng Prostaglandin hay hoá trị liệu ung thư có thể gây thiểu ối.", "Khoảng 30 % trường hợp không tìm thấy nguyên nhân"], "bullets": ["- Hệ thần kinh: Mặc dù các bất thường chính của hệ thần kinh có thể có liên quan tới lượng nước ối bình thường và sự tăng lượng nước ối, nhưng chỉ trong một số trường hợp là có liên quan tới thiểu ối.", "+ Thai vô sọ", "+ Não úng thuỷ", "+ Thoát vị não màng não", "- Hệ tiêu hoá: hiếm gặp, thường thì tắc nghẽn đường tiêu hoá là nguyên nhân gây đa ối.", "+ Thoát vị rốn.", "+ Dò thực quản - khí quản", "+ Teo hành tá tràng", "- Hệ hô hấp:", "+ Giảm sản phổi", "- Hệ tiết niệu:", "+ Tắc nghẽn đường tiết niệu hoặc không có thận. Các bệnh lý thường gặp là bất sản thận, nghịch sản thận, thận đa nang."]}, {"heading": "3. TRIỆU CHỨNG VÀ CHẨN ĐOÁN", "paragraphs": [], "bullets": ["- Chiều cao tử cung thường nhỏ hơn so với tuổi thai rõ, số đo thường thấp và có chiều hướng đi xuống so với đường chuẩn.", "- Thai thường cử động yếu. Khi thực hiện 4 thủ thuật của Leopol có cảm giác thấy rõ các phần thai nằm sát dưới bàn tay mà không cảm thấy có nước ối, khó làm động tác di động đầu thai nhi.", "- Siêu âm có chỉ số nước ối thấp, thường dưới đường percentile thứ 5 so với tuổi thai hoặc khi tuổi thai sau 35 tuần có chỉ số nước ối (AFI) ≤5, hoặc là buồng ối lớn nhất có độ sâu ≤ 2  cm."]}, {"heading": "4. ĐIỀU TRỊ", "paragraphs": ["Cần phải chẩn đoán phân biệt thiểu ối với ối vỡ non. Cho đến nay chưa có phương pháp điều trị và phòng ngừa thiểu ối nào thật sự hữu hiệu. Do đó cần khuyên các sản phụ đi khám thai định kỳ, làm các xét nghiệm để phát hiện sớm các bệnh lý của người mẹ và các bất thường của thai nhi để có hướng điều trị kịp thời và theo dõi cẩn thận.", "Siêu âm là một xét nghiệm có tính chất thường quy nhằm đánh giá lượng nước ối và phát hiện các dị dạng thai nhi, đồng thời khảo sát doppler tuần hoàn tử cung - rau và tuần hoàn thai nhi để đánh giá tình trạng thai. Các trường hợp khi có thiểu ối phải khảo sát kỹ hình thái và chức năng hệ tiết niệu thai nhi.", "Trên siêu âm nếu khoang ối lớn nhất ( 10 mm và chỉ số nước ối AFI( 5 là chắc chắn có thiểu ối. Nếu AFI trong khoảng 5 - 24 biểu hiện nước ối trong giới hạn bình thường.", "Thiểu ối hầu như không gây biến chứng gì cho mẹ, vấn đề điều trị thay đổi tuỳ thuộc vào tình trạng thai."], "bullets": []}, {"heading": "4.1. Khi thai chưa đủ tháng", "paragraphs": ["Nếu thiểu ối mà không có dị dạng bẩm sinh lớn ở các cơ quan tiết niệu, tiêu hoá, thần kinh… có thể là do suy hay tắc một phần tuần hoàn tử cung - rau thai. Cho đến nay vẫn chưa có phương pháp điều trị nào được cho là đặc hiệu. Trong những trường hợp này thì nên khuyên bệnh nhân nằm nghiêng trái, kiểm soát các bệnh lý đi kèm, đảm bảo chế độ dinh dưỡng đầy đủ nhằm cải thiện tuần hoàn tử cung - rau thai nhằm cố gắng giữ thai phát triển đến trên 35 tuần.", "Trong các trường hợp thiểu ối và có các dị dạng cấu trúc thai nhi, cần phải làm thêm các xét nghiệm để xác định các bất thường đó có khả năng điều trị hay không, cũng như có bất thường về nhiễm sắc thể hay không để có quyết định điều trị giữ thai hay đình chỉ thai nghén.\tTrường hợp thai chậm phát triển trong tử cung mà không tìm được nguyên nhân thì thái độ xử trí tuỳ thuộc vào sự diễn tiến của tình trạng suy thai trong tử cung. Thai chậm phát triển trong tử cung ở quý ba và có thiểu ối là dấu hiệu nặng của tình trạng chậm tăng trưởng thai. Cần cân nhắc khả năng chấm dứt thai kỳ được khi có tình trạng suy thai và/hoặc phổi thai nhi đã trưởng thành."], "bullets": []}, {"heading": "4.2. Khi thai đủ tháng", "paragraphs": ["Khi đã xác định thai đủ tháng và biểu hiện thiểu ối thì cần được theo dõi bằng monitoring. Nếu khi không làm test đả kích hoặc trong khi làm test đả kích có xuất hiện tim thai chậm hay Dip biến đổi thì cần chỉ định mổ lấy thai để chấm dứt thai kỳ. Nếu làm test đả kích mà nhịp tim thai vẫn trong giới hạn bình thường thì cần đánh giá thêm chỉ số Bishop để có chỉ định khởi phát chuyển dạ."], "bullets": []}, {"heading": "4.3. Trong chuyển dạ", "paragraphs": ["Thiểu ối làm tăng nguy cơ suy thai và đẻ khó vì chèn ép dây rốn và thai khó bình chỉnh tốt trong chuyển dạ, vì vậy cần phải theo dõi sát các yếu tố chuyển dạ để có tiên lượng và xử trí kịp thời."], "bullets": []}, {"heading": "5. BIẾN CHỨNG", "paragraphs": ["Tiên lượng thai thường xấu với tỷ lệ chết cao với những trường hợp thiểu ối ở giai đoạn sớm của thai kỳ. Mặt khác, thai trải qua thiểu ối kéo dài dù là do nguyên nhân nào đều có thể mang những hậu quả do thiểu ối như thiểu sản phổi, dị dạng mặt và xương (loạn sản xương hông, cụt chi, vẹo chân và các khiếm khuyết khác ở chi).", "Thiểu ối thường gây thiểu sản phổi vì 3 nguyên nhân sau:"], "bullets": ["- Do bị chèn ép vào lồng ngực làm giảm các cử động của phổi", "- Giảm các cử động thở của thai nhi", "- Do phổi kém phát triển."]}], "raw_text": "THIỂU ỐI\nMục tiêu học tập\n1. Định nghĩa được thiểu ối\n2. Kể được các nguyên nhân của thiểu ối trong các giai đoạn của thai kỳ\n3. Phân biệt thiểu ối sớm của thai kỳ và thiểu ối trong giai đoạn cuối thai kỳ\n4. Xác định được các vấn đề cơ bản trong điều trị thiểu ối\n\n1. ĐẠI CƯƠNG\nThiểu ối là khi lượng nước ối giảm so với lượng nước ối bình thường tính theo tuổi thai và ở dưới đường bách phân (percentile) thứ 5.\nTỷ lệ thiểu ối khoảng 0,4 - 3,9%.\nNguyên nhân dẫn tới thiểu ối bao gồm ối vỡ sớm, ối vỡ non, bất thường cấu trúc thai nhi, thai quá ngày sinh, thai kém phát triển trong tử cung... Tuy nhiên, có nhiều trường hợp thiểu ối  không xác định được nguyên nhân.\nThiểu ối xảy ra trong giai đoạn sớm của thai kỳ thường có tiên lượng xấu, trong khi thiểu ối ở thai quá ngày sinh thường có tiên lượng tốt hơn.\nThiểu ối có nguy cơ gây chèn ép dây rốn và đưa đến suy thai, nguy cơ này càng tăng lên trong chuyển dạ.\n\n2. NGUYÊN NHÂN THIỂU ỐI\n2.1. Nguyên nhân do mẹ\n- Bệnh lý của người mẹ có ảnh hưởng đến tính thấm của màng ối và chức năng của rau thai gây thai kém phát triển và chức năng tái tạo nước ối như: bệnh cao huyết áp, tiền sản giật, bệnh về lý về gan, thận...\n2.2. Nguyên nhân do thai\nỞ mọi giai đoạn của thai kỳ, nguyên nhân thường gặp nhất của thiểu ối là vỡ ối sớm.  Thường có một số bất thường bẩm sinh của thai kỳ kèm theo thiểu ối. Các bất thường của thai kết hợp với thiểu ối hay gặp là:\n- Hệ thần kinh: Mặc dù các bất thường chính của hệ thần kinh có thể có liên quan tới lượng nước ối bình thường và sự tăng lượng nước ối, nhưng chỉ trong một số trường hợp là có liên quan tới thiểu ối.\n+ Thai vô sọ\n+ Não úng thuỷ\n+ Thoát vị não màng não\n- Hệ tiêu hoá: hiếm gặp, thường thì tắc nghẽn đường tiêu hoá là nguyên nhân gây đa ối.\n+ Thoát vị rốn.\n+ Dò thực quản - khí quản\n+ Teo hành tá tràng\n- Hệ hô hấp:\n+ Giảm sản phổi\n- Hệ tiết niệu:\n+ Tắc nghẽn đường tiết niệu hoặc không có thận. Các bệnh lý thường gặp là bất sản thận, nghịch sản thận, thận đa nang.\nThiểu ối trong thai chậm phát triển trong tử cung xảy ra sau một tình trạng thiếu oxy của bào thai, giảm tưới máu phổi và giảm tiết dịch.\nNhiễm trùng thai cũng có thể là một nguyên nhân của thiểu ối. Một số thuốc kháng Prostaglandin hay hoá trị liệu ung thư có thể gây thiểu ối.\nKhoảng 30 % trường hợp không tìm thấy nguyên nhân\n3. TRIỆU CHỨNG VÀ CHẨN ĐOÁN\n- Chiều cao tử cung thường nhỏ hơn so với tuổi thai rõ, số đo thường thấp và có chiều hướng đi xuống so với đường chuẩn.\n- Thai thường cử động yếu. Khi thực hiện 4 thủ thuật của Leopol có cảm giác thấy rõ các phần thai nằm sát dưới bàn tay mà không cảm thấy có nước ối, khó làm động tác di động đầu thai nhi.\n- Siêu âm có chỉ số nước ối thấp, thường dưới đường percentile thứ 5 so với tuổi thai hoặc khi tuổi thai sau 35 tuần có chỉ số nước ối (AFI) ≤5, hoặc là buồng ối lớn nhất có độ sâu ≤ 2  cm.\n\n4. ĐIỀU TRỊ\nCần phải chẩn đoán phân biệt thiểu ối với ối vỡ non. Cho đến nay chưa có phương pháp điều trị và phòng ngừa thiểu ối nào thật sự hữu hiệu. Do đó cần khuyên các sản phụ đi khám thai định kỳ, làm các xét nghiệm để phát hiện sớm các bệnh lý của người mẹ và các bất thường của thai nhi để có hướng điều trị kịp thời và theo dõi cẩn thận.\nSiêu âm là một xét nghiệm có tính chất thường quy nhằm đánh giá lượng nước ối và phát hiện các dị dạng thai nhi, đồng thời khảo sát doppler tuần hoàn tử cung - rau và tuần hoàn thai nhi để đánh giá tình trạng thai. Các trường hợp khi có thiểu ối phải khảo sát kỹ hình thái và chức năng hệ tiết niệu thai nhi.\nTrên siêu âm nếu khoang ối lớn nhất ( 10 mm và chỉ số nước ối AFI( 5 là chắc chắn có thiểu ối. Nếu AFI trong khoảng 5 - 24 biểu hiện nước ối trong giới hạn bình thường.\nThiểu ối hầu như không gây biến chứng gì cho mẹ, vấn đề điều trị thay đổi tuỳ thuộc vào tình trạng thai.\n4.1. Khi thai chưa đủ tháng\nNếu thiểu ối mà không có dị dạng bẩm sinh lớn ở các cơ quan tiết niệu, tiêu hoá, thần kinh… có thể là do suy hay tắc một phần tuần hoàn tử cung - rau thai. Cho đến nay vẫn chưa có phương pháp điều trị nào được cho là đặc hiệu. Trong những trường hợp này thì nên khuyên bệnh nhân nằm nghiêng trái, kiểm soát các bệnh lý đi kèm, đảm bảo chế độ dinh dưỡng đầy đủ nhằm cải thiện tuần hoàn tử cung - rau thai nhằm cố gắng giữ thai phát triển đến trên 35 tuần.\nTrong các trường hợp thiểu ối và có các dị dạng cấu trúc thai nhi, cần phải làm thêm các xét nghiệm để xác định các bất thường đó có khả năng điều trị hay không, cũng như có bất thường về nhiễm sắc thể hay không để có quyết định điều trị giữ thai hay đình chỉ thai nghén.\tTrường hợp thai chậm phát triển trong tử cung mà không tìm được nguyên nhân thì thái độ xử trí tuỳ thuộc vào sự diễn tiến của tình trạng suy thai trong tử cung. Thai chậm phát triển trong tử cung ở quý ba và có thiểu ối là dấu hiệu nặng của tình trạng chậm tăng trưởng thai. Cần cân nhắc khả năng chấm dứt thai kỳ được khi có tình trạng suy thai và/hoặc phổi thai nhi đã trưởng thành.\n4.2. Khi thai đủ tháng\nKhi đã xác định thai đủ tháng và biểu hiện thiểu ối thì cần được theo dõi bằng monitoring. Nếu khi không làm test đả kích hoặc trong khi làm test đả kích có xuất hiện tim thai chậm hay Dip biến đổi thì cần chỉ định mổ lấy thai để chấm dứt thai kỳ. Nếu làm test đả kích mà nhịp tim thai vẫn trong giới hạn bình thường thì cần đánh giá thêm chỉ số Bishop để có chỉ định khởi phát chuyển dạ.\n4.3. Trong chuyển dạ\nThiểu ối làm tăng nguy cơ suy thai và đẻ khó vì chèn ép dây rốn và thai khó bình chỉnh tốt trong chuyển dạ, vì vậy cần phải theo dõi sát các yếu tố chuyển dạ để có tiên lượng và xử trí kịp thời.\n\n\n5. BIẾN CHỨNG\nTiên lượng thai thường xấu với tỷ lệ chết cao với những trường hợp thiểu ối ở giai đoạn sớm của thai kỳ. Mặt khác, thai trải qua thiểu ối kéo dài dù là do nguyên nhân nào đều có thể mang những hậu quả do thiểu ối như thiểu sản phổi, dị dạng mặt và xương (loạn sản xương hông, cụt chi, vẹo chân và các khiếm khuyết khác ở chi).\nThiểu ối thường gây thiểu sản phổi vì 3 nguyên nhân sau:\n- Do bị chèn ép vào lồng ngực làm giảm các cử động của phổi\n- Giảm các cử động thở của thai nhi\n- Do phổi kém phát triển.\n\nCâu hỏi:\n1. Anh (Chị) trỡnh bày triệu chứng lâm sàng, cận lâm sàng để chẩn đoán xác định, chẩn đoán phân biệt thiểu ối?\n2.  Anh (Chị) trỡnh bày hướng xử trí và biến chứng của thiểu ối?", "priority": "Cao (Trọng tâm BSNT)"}, {"id": "SK-24", "chapter": "Chương 2. Sản bệnh", "folder": "02_San_benh", "title": "Thai nghén nguy cơ cao", "author": "PGS. TS. Ninh Văn Minh", "word_count": 3634, "line_count": 266, "key_numbers": ["0,16ml", "0,5ml", "10 tuần", "12 tuần", "16 tuần", "2 tuần", "22 tuần", "32 tuần", "34 tuần", "4 tuần", "40kg", "48 giờ", "6 tháng", "70kg"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["THAI NGHÉN NGUY CƠ CAO"], "bullets": []}, {"heading": "1. ĐẠI CƯƠNG", "paragraphs": ["Thai nghén nguy cơ cao là thai nghén có các yếu tố có thể ảnh hưởng đến sức khoẻ của mẹ và con.", "Thai nghén nguy cơ cao gặp khá phổ biến, ở bất cứ tuổi thai nào, là nguyên nhân gây tăng tỷ lệ mắc bệnh, tử vong cho mẹ, thai và  sơ sinh. Thai nghén nguy cơ cao còn có thể gây nên các loại bệnh tật, các dị dạng cho thai khi còn nằm trong tử cung hoặc làm cho trẻ bị trì trệ, kém phát triển khi đã ra đời.", "Tỷ lệ thai nghén nguy cơ cao thay đổi từ  5 - 40%."], "bullets": []}, {"heading": "2. PHÂN NHÓM CÁC THAI NGHÉN NGUY CƠ CAO", "paragraphs": ["Về mặt lâm sàng, người ta chia ra 4 nhóm nguy cơ:"], "bullets": []}, {"heading": "2.1.1. Tuổi mẹ: Mang thai ở tuổi vị thành niên (dưới 18 tuổi) có nguy cơ tiền sản giật, thai chậm phát triển trong tử cung, doạ đẻ non và đẻ non, và mẹ thiểu năng dinh dưỡng, lây lan các bệnh viêm nhiễm theo đường tình dục.", "paragraphs": ["Mẹ trên 35 tuổi có nguy cơ cao huyết áp do thai, tiền sản giật, nhau tiền đạo, bệnh béo phì, các bệnh nội khoa khác. Những bất thường về nhiễm sắc thể có thể gặp ở trẻ sinh ra từ các bà mẹ lớn tuổi"], "bullets": []}, {"heading": "2.1.3. Cân nặng mẹ", "paragraphs": [], "bullets": ["-  Mẹ nhẹ cân: khi cân nặng dưới 40kg khi có thai có thể do thiếu dinh dưỡng, bệnh chán ăn. Nguy cơ của thiếu cân trong thai kỳ là sinh ra một em bé nhẹ cân hơn tuổi thai, chậm phát triển trong tử cung, suy thai, thai ngạt, sơ sinh hạ đường máu, giảm thân nhiệt, tỷ lệ tử vong và bệnh lý cao.", "- Mẹ béo phì: Là những bà mẹ có cân nặng trên 70kg. Các biến chứng thường gặp ở mẹ béo phì là rối loạn cao huyết áp có từ trước và trong khi có thai, tần suất gặp từ 4 - 7%, biến chứng đái đường cũng hay gặp. Ngoài ra còn gặp các biến chứng khác như viêm đường tiết niệu, viêm tĩnh mạch. Mẹ béo phì thường sinh một em bé lớn, ngôi thế không rõ ràng, tỷ lệ mổ lấy thai cao và dễ nhiễm trùng sau mổ."]}, {"heading": "2.1.4. Các bệnh di truyền: Các bệnh do cha mẹ truyền cho con, xảy ra trong quá trình thụ thai (phối hợp giữa tinh trùng và noãn) hoặc do sự tiếp xúc với môi trường ô nhiễm. Ví dụ như chứng tam bội thể 21 (trisomie) gây ra hội chứng Usker ở trẻ nhỏ với thoái hoá sắc tố ở võng mạc, điếc, xơ cứng teo cơ.", "paragraphs": ["Rối loạn nhiễm sắc thể (đơn bội thể, tam bội thể) thường gây sẩy thai ở 12 tuần đầu. Bệnh Down gặp ở sản phụ nhiều tuổi, thai bé nhỏ, non yếu, gặp ở phụ nữ quá trẻ hoặc cơ  thể nhỏ bé."], "bullets": []}, {"heading": "2.1.6. Yếu tố dinh dưỡng: Năng lượng dự trữ trong thời gian sắp có thai, thức ăn hàng ngày và thức ăn bổ sung trong thời gian mang thai có thể ảnh hưởng tới tốc độ tăng trưởng và phát triển của thai. Thiếu năng lượng trường diễn dẫn tới sinh ra trẻ thiếu cân. Thiếu acid folic là nguyên nhân đầu tiên ảnh hưởng đến khuyết tật ống thần kinh. Mẹ thiếu vitamin B1 có liên quan tới một số trường hợp tử vong cấp của sơ sinh và các tình trạng tim của thai nhi bị sung huyết. Thiếu vitamin D có thể dẫn tới tình trạng hạ canxi huyết và cơn tetani của sơ sinh.", "paragraphs": ["Ngoài ra các yếu tố về môi trường, mẹ nghiện thuốc lá, nghiện rượu cũng là các yếu tố nguy cơ."], "bullets": []}, {"heading": "2.2.1. Các bệnh nhiễm khuẩn của mẹ", "paragraphs": [], "bullets": ["- Bệnh nhiễm khuẩn: thường nặng lên gây nhiều nguy cơ cho thai :", "+ Thời kỳ sắp xếp tổ chức: một số bệnh do virus như cúm, sốt xuất huyết, Rubéon, do vi khuẩn Listéria, do ký sinh trùng Toxoplasma gây những dị dạng cho thai như não úng thuỷ, bụng cóc, sứt môi hở hàm  ếch.", "+ Thời kỳ hoàn chỉnh tổ chức: do lớp hội bào mỏng dần làm cho vi khuẩn, virus, ký sinh trùng dễ thấm qua màng ngăn của rau thai (độc tố, kháng thể) gây bệnh cho thai như như viêm gan, giang mai, viêm não, viêm phổi.", "- Hậu quả của nhiễm khuẩn:", "+ Quý I bệnh của phôi, sẩy thai tự nhiên.", "+ Quý II chết thai, sẩy thai muộn, lây nhiễm qua bánh rau.", "+ Quý III lây qua bánh rau, đẻ non, chết thai.", "+  Lây nhiễm chu sinh (viêm gan), trong quý II và III lây nhiễm qua bánh rau có thể gây ra nhiễm khuẩn bẩm sinh với nguy cơ thai bị bệnh."]}, {"heading": "2.2.2. Các bệnh về gan: Thường gặp viêm gan do virus gây suy gan cấp, xơ gan làm giảm chức năng gan, gây chảy máu, hôn mê, tử vong trong cuộc đẻ. Đối với thai thường bị dị dạng ở 10 tuần lễ đầu hoặc bị sẩy thai. Từ tuần lễ thứ 12 trở đi làm thai bị viêm gan, gây dễ sẩy, đẻ non hoặc chết lưu. Nếu thai nhi sinh ra từ mẹ mang kháng nguyên HBs gần 2% trong số trẻ này trở thành người mang virus mạn tính sẽ có nguy cơ bị tổn thương gan nặng.", "paragraphs": ["Tình trạng huyết thanh của thai phụ", "ở quý 3", "Nguy cơ lây cho TSS  khi đẻ hoặc sau đẻ", "Xử trí", "Kháng nguyên HBs (+) / KN HBe (+)", "Khángnguyên HBs (+) / KNHBe (-)", "Kháng nguyên HBs(-) / Kháng thể HBc(+)", "Kháng nguyên HBs (-) / kháng thể HBs(+)", "90 đến 100%", "20%", "Không biết - ít", "0%", "Tiêm  huyết thanh", "Tiêm huyết thanh", "Không xử trí", "Không xử trí", "Bảng1: Nguy cơ lây cho trẻ sơ sinh phụ thuộc vào tình trạng huyết thanh của mẹ ở quý 3.", "Dự phòng cho trẻ sơ sinh mang virus bằng cách tiêm Immoglobuline đặc hiệu 0,5ml/kg tiêm bắp sau sinh 48 giờ.", "Sau đó tiêm hàng tháng 0,16ml/kg trong 6 tháng và nhắc lại sau một năm."], "bullets": []}, {"heading": "2.2.3. Các bệnh về thận: Viêm thận, viêm mủ bể thận, cao huyết áp, các bệnh này sẽ nặng lên lúc mang thai gây nhiều biến chứng như: rau bong non, sản giật do co thắt tiểu động mạch, lượng máu rau thai ít làm rau bị xơ hoá, bánh rau nhỏ, thai kém phát triển, chết lưu. Tăng tỷ lệ tử vong chu sinh. Cần điều trị tích cực và có hệ thống hoặc phải đình chỉ thai nghén để cứu mẹ.", "paragraphs": ["Nguy cơ cho me: Cao huyết áp, gia tăng mức độ thương tổn thận."], "bullets": []}, {"heading": "2.2.8. Các bệnh phụ khoa", "paragraphs": [], "bullets": ["- Thiểu năng nội tiết (Estrogen, Progesteron) gây sẩy thai.", "- Viêm nhiễm đường sinh dục, gây ra viêm màng thai, nhiễm khuẩn ối, nhiễm khuẩn thai.", "- Các dị dạng tử cung, u xơ, hở eo... gây sẩy thai hay đẻ non."]}, {"heading": "2.3. Nhóm 3: Các yếu tố liên quan đến  tới tiền sử sản phụ khoa", "paragraphs": [], "bullets": ["- Đẻ khó, can thiệp thủ thuật gây sang chấn cho thai nhi", "- Sản phụ có tiền sử sẩy thai liên tiếp, chết lưu, đẻ non nhiều lần dễ gây ra nguy hiểm cho thai, đẻ con chết nhiều lần. Khi người phụ nữ có tiền sử sẩy thai liên tiếp từ 3 lần trở lên thì chỉ có cơ hội đẻ con sống là 30% và nguy cơ đẻ non cao hơn 20% so với người bình thường.", "- Điều trị vô sinh", "- Mổ lấy thai, sẹo cũ ở tử cung (bóc u, tạo hình... )"]}, {"heading": "2.4.2. Nguyên nhân do phần phụ của thai", "paragraphs": ["Nguyên nhân do bánh nhau", "Rau tiền đạo: gặp ở những thai phụ suy dinh dưỡng, nạo thai hay đẻ nhiều lần. Thai thường bị đẻ non, những trường hợp nặng phải mổ để cứu thai phụ.", "Rau bong non: Làm hai bị thiếu oxy nghiêm trọng,thai phụ bị mất máu nhiều, đe doạ đến tính mạngcủa thai nhi và thai phụ.", "Rau xơ hoá (calci hoá) hay gặp trong nhiễm độc thai nghén hoặc thiểu năng nội tiết, bánh nhau kém phát triển, sự trao đổi chất dinh dưỡng, oxy giữa mẹ và thai giảm, làm cho thai kém phát triển, chết lưu hoặc đẻ non.", "Nguyên nhân do màng ối", "Nguyên nhân do dây rau:", "Nguyên nhân do nước ối"], "bullets": ["- Rỉ ối, ối vỡ non gây nhiễm khuẩn ối, nhiễm khuẩn cho thai nhi. Thai phụ đôi khi phải mổ cắt tử cung ở những thể nhiễm trùng nặng.", "- Dây rau ngắn, dây rau cuốn cổ dây rau thắt nút, khối u ở dây rau dây rau bị chèn ép, hoặc sa dây rau dều làm cho thai nhi bình chỉnh không tốt, hoặc ngăn cản tuần hoàn nhau thai làm cho thai chết.", "- Đa ối:", "+ Đa ối cấp ít gặp, thường xuất hiên vào tháng thứ 4 hoặc thứ 5, gây khó thở cho thai phu, phải tia ối để cứu mẹ.Trong đa ối cấp thai thường dị dạng", "+ Đa ối mạn: thường gặp nhiều hơn, xuất hiện muộn vào những tháng cuối, tiến triển từ từ, thai thường bị dị dạng, đẻ non, ngôi thế bất thường.", "- Thiểu ối"]}, {"heading": "2.4.3. Các nguyên nhân do thai", "paragraphs": ["Hình 1. Quái thai vô sọ                        Hình 2. CT scan não úng thủy", "Hình 3. Hở hàm ếch", "Tóm lại, hậu quả của thai nghén có nguy cơ cao, thường gây:"], "bullets": ["-  Thai già tháng: Bánh rau bị thoái hoá làm giảm cung cấp chất dinh dưỡng và oxy cho thai, thai suy dần, nhỏ lại các cơ quan chức năng của thai nhi suy giảm, làm thai bị chết trong tử cung, hoặc nếu đẻ ra thì cũng chết trong tuần đầu với tỷ lệ cao.", "-  Thai dị dạng", "+ Dị dạng lớn: Não úng thuỷ, vô sọ, bụng cóc, thai thường bị chết.", "+ Dị dạng nhỏ: Hở hàm ếch, thừa ngón chân, ngón tay.", "-  Thai bị bệnh và nhiễm khuẩn:  Thai bị các bệnh di truyền, bệnh bẩm sinh, bị nhiễm khuẩn trong buồng tử cung đều bị chết đột ngột, chết lưu, sẩy thai hoặc đẻ non.", "-  Đa thai: sinh đôi, sinh ba thai thường nhỏ, non yếu dễ đẻ non. Khi đẻ có thể thai mắc vào nhau hoặc mắc kẹt, hoặc ngôi thế bất thưòng. Mẹ sau đẻ dễ bị băng huyết.", "- Bất đồng nhóm máu giữa mẹ và thai: thường gặp là yếu tố Rh, ngày nay người ta đã phát hiện bất đồng nhóm máu A - O - B giữa mẹ và con, hậu quả  sơ sinh  vàng da, tán huyết, dẫn đến vàng da nhân.", "- Sẩy thai.", "- Đẻ non.", "- Thai kém phát triển.", "- Suy thai cấp tính và mãn tính.", "- Thai chết trong tử cung.", "- Tăng tỷ lệ tử vong chu sinh.", "- Đối với mẹ gây tăng tỷ lệ can thiệp trong và sau đẻ, tăng tỷ lệ mổ đẻ. Thậm chí gây tử vong mẹ."]}, {"heading": "2.4.4. Một số phương pháp thăm dò sản khoa phát hiện các yếu tố nguy cơ của thai", "paragraphs": ["Siêu âm trong theo dõi thai nghén nguy cơ cao", "Doppler động mạch tử cung (từ tuần 20 - 24 ) ở thai nghén nguy cơ cao, thai chậm phát triển trong tử cung, tiền sản giật.", "Doppler động mạch rốn  28 - 34 tuần. Thai nghén nguy cơ, nguy cơ mạch máu ở mẹ Nhiễm độc thai nghén, suy thai, song thai, thai bất thường.", "Doppler  động mạch não từ  tuần thứ  26 thai chậm phát triển.", "Monitoring sản khoa theo dõi tim thai", "Rất có giá trị trong việc theo dõi và đánh giá sức khoẻ của thai nhi trong thai kỳ và trong chuyển dạ, góp phần làm giảm tỷ lệ mắc bệnh (morbidity) và tử vong (mortality) chu sinh."], "bullets": ["- 10 - 12 tuần: Xác định thai, số lượng thai, tình trạng thai, bệnh lý phối hợp, phát hiện những bất thường về nhiễm sắc thể, bất thường về thai.", "- 20 - 22 tuần: Phát hiện các dị dạng thai nhi, vị trí nhau, thể tích nước ối, mạch máu cuống rốn.", "- 30 - 32 tuần: ngôi thai, sự phát triển của thai, dị dạng thai nếu có, vị trí hình dạng của bánh rau, lượng nước ối."]}, {"heading": "3. CHĂM SÓC VÀ QUẢN LÝ THAI NGHÉN NGUY CƠ CAO", "paragraphs": ["Để có thể giảm tỷ lệ tai biến trong những trường hợp thai nghén có nguy cơ cao cần phát hiện sớm, theo dõi và xử trí kịp thời bao gồm:"], "bullets": ["- Cung cấp những lời khuyên, giáo dục, tư vấn cho phụ nữ có thai và gia đình họ.", "- Cung cấp các dịch vụ lâm sàng, cận lâm sàng để đảm bảo rằng người phụ nữ luôn ở nguy cơ thấp.", "- Dự phòng, xử trí những vấn đề và những yếu tố bất lợi cho mẹ và thai.", "- Giảm tỷ lệ bệnh suất và tử suất cho mẹ, giảm tỷ lệ bệnh suất và tử suất chu sinh."]}, {"heading": "3.1. Số lần khám thai", "paragraphs": ["Ở Việt nam số lần khám thai khuyên tối thiểu là 3 lần ở thai nghén bình thường. Đối với thai nghén nguy cơ cao yêu cầu người phụ nữ khám thai 4 tuần một lần cho tới tuần 28. Sau đó 2 tuần một lần cho tới tuần 36, và hàng tuần cho tới tuần 40. Như vậy, có ít nhất từ 13 lần khám thai cho tuổi thai từ tuần thứ 8 - tuần 40.", "Mỗi lần khám thai nếu nhận diện được yếu tố nguy cơ cần có thái độ xử trí thích hợp cho từng trường hợp."], "bullets": []}, {"heading": "3.2. Nội dung chăm sóc và quản lý thai nghén nguy cơ cao", "paragraphs": ["Sơ đồ chăm sóc tiền sản", "Tuần thai nghén", "Hoạt động", "Tuần 8-14", "Xác định thai nghén. Hỏi về: tiền sử nội ngoại khoa, tiền sử gia đình và tiền sử sản khoa", "Khám toàn thân. Khám tiểu khung nếu có chỉ dịnh.", "Xét nghiệm: phân tích nước tiểu (protein/glucoza/ máu)", "Công thức máu. Nhóm máu ABO/ Rh", "Huyết thanh học các bệnh (sởi, giang mai).", "Tư vấn dinh dưỡng, thể dục, chăm sóc vú, răng, vấn đề cho con bú, vấn dề kế hoạch hoá gia đình sau đẻ.", "Tuần 16", "Xét nghiệm máu để phát hiện những trường hợp có nguy cơ hở ống thần kinh và bệnh down", "Tuần 18", "Siêu âm hình thái học kiểm tra lại kết quả huyết thanh học khi 16 tuần. Xác định ngày sinh dự đoán", "Tuần 22-24", "Khám thai thường quy :hỏi bệnh sử, các triệu chứng đặc biệt (xuất huyết âm đạo, giảm hoặc mất cử động thai).", "Phân tích nước tiểu, đo chiều cao tử cung, vòng bụng. Kiểm tra huyết áp.", "Tuần 28", "Khám thường quy tim thai, nước ối, chiều cao tử cung đánh giá sự phát triển của thai. Làm công thức máu.", "Tuần 32", "Khám thai thường quy. Kiểm tra huyết áp. Thảo luận về vấn đề sinh đẻ đối với phụ  nữ có thai và gia đình họ.", "Tuần 36", "Khám thai thường quy. Kiểm tra huyết áp công thức máu, ngôi thai bất thường hay không", "Tuần 38", "Khám thai thường quy. Kiểm tra huyết áp. Sự phát triển của thai. Ngôi thai bất thường", "Tuần 40", "Khám thường quy kiểm tra huyết áp, ngôi thai. Thảo luận về cuộc đẻ.", "Tuần 41", "Khám lại và thảo luận gây chuyển dạ nhân tạo."], "bullets": []}, {"heading": "3.3. Một số thăm dò để phát hiện thai nghén nguy cơ cao", "paragraphs": ["Thăm dò", "Các yếu tố nguy cơ có thể phát hiện"], "bullets": []}, {"heading": "1. Siêu âm thai", "paragraphs": ["Vị trí, số túi thai, thai bất thường"], "bullets": []}, {"heading": "2. Xét nghiệm alpha-foetoprotein", "paragraphs": ["Tật hở ống thần kinh, Down"], "bullets": []}, {"heading": "3. Chiều cao tử cung ở thai nguy cơ cao", "paragraphs": ["Bệnh lý về sự phát triển của thai"], "bullets": []}, {"heading": "4. Siêu âm lặp lại về kích thước thai", "paragraphs": ["Bệnh lý về sự phát triển của thai"], "bullets": []}, {"heading": "5. Các tests về sức khoẻ thai nhi", "paragraphs": ["Thai chết"], "bullets": []}, {"heading": "6. Doppler mạch máu ở thai", "paragraphs": ["Thai suy"], "bullets": []}, {"heading": "7. Rhesus antibody", "paragraphs": ["Thiếu máu tiêu huyết do Rh."], "bullets": []}, {"heading": "8. Siêu âm định kỳ", "paragraphs": ["Ngôi thai, vị trí nhau, ối"], "bullets": []}, {"heading": "9.  Huyết áp và phân tích nước tiểu", "paragraphs": ["Tiền sản giật"], "bullets": []}, {"heading": "10. Thăm dò độ dung nạp glucoza", "paragraphs": ["Đái đường do thai nghén"], "bullets": []}, {"heading": "11. Xét nghiêm nước tiểu", "paragraphs": ["Nhiễm trùng tiết niệu không triệu chứng"], "bullets": []}, {"heading": "12. Huyết thanh học với giang mai, lậu", "paragraphs": ["Nhiễm trùng mẹ và thai."], "bullets": []}, {"heading": "3.4. Một số biện pháp điều trị dự phòng trong thai nghén nguy cơ cao:", "paragraphs": ["Chiến lược cung cấp", "Lợi ích", "1.Cung cấp vitamin và folate", "Dự phòng tật hở cột sống", "Giảm nguy cơ mắc bệnh khi có thai"], "bullets": []}, {"heading": "2. Siêu âm thường quy", "paragraphs": ["Giảm tỷ lệ thai già tháng"], "bullets": []}, {"heading": "3. Điều trị cao huyết áp", "paragraphs": ["Giảm cao huyết áp nặng khi có thai ở phụ nữ cao huyết áp"], "bullets": []}, {"heading": "4. Đảm bảo kiểm soát đươc bệnh đái đường", "paragraphs": ["Giảm nhiễm trùng tiết niệu, giảm đẻ non,                                                                      giảm mổ lấy thai, thai to, suy hô hấp.                                                               Tử vong chu sinh giảm"], "bullets": []}, {"heading": "5. Khâu eo tử cung", "paragraphs": ["Giảm tỷ lệ đẻ non"], "bullets": []}, {"heading": "6. Siêu âm phát hiện thai bất thường", "paragraphs": ["Giảm sự cố sinh ra trẻ sơ sinh bất thường, giảm tỷ lệ mắc bệnh của mẹ"], "bullets": []}, {"heading": "7. Xét nghiệm hoá sinh", "paragraphs": ["Giảm tỷ lệ bệnh suất và tử suất chu sinh"], "bullets": []}, {"heading": "8. Trắc nghiệm sinh học thai nhi bình thường", "paragraphs": ["Giảm tỷ lệ bệnh suất và tử suất chu sinh"], "bullets": []}, {"heading": "9. Doppler mạch máu thai nhi", "paragraphs": ["Giảm tỷ lệ bệnh suất và tử suất chu sinh"], "bullets": []}, {"heading": "10. Nhập viện đối với cao huyết áp không có protein niệu", "paragraphs": ["Giảm phát triển protein niệu nặng..."], "bullets": []}], "raw_text": "THAI NGHÉN NGUY CƠ CAO\n\nMục tiêu học tập\n1. Mô tả 4 nhóm các yếu tố nguy cơ\n2. Đề nghị được các xét nghiệm nhằm theo dõi, phát hiện thai nghén nguy cơ\n3. Nêu được tầm quan trọng và lợi ích của chăm sóc và  theo dõi thai nghén nguy cơ.\n\n1. ĐẠI CƯƠNG\nThai nghén nguy cơ cao là thai nghén có các yếu tố có thể ảnh hưởng đến sức khoẻ của mẹ và con.\nThai nghén nguy cơ cao gặp khá phổ biến, ở bất cứ tuổi thai nào, là nguyên nhân gây tăng tỷ lệ mắc bệnh, tử vong cho mẹ, thai và  sơ sinh. Thai nghén nguy cơ cao còn có thể gây nên các loại bệnh tật, các dị dạng cho thai khi còn nằm trong tử cung hoặc làm cho trẻ bị trì trệ, kém phát triển khi đã ra đời.\nTỷ lệ thai nghén nguy cơ cao thay đổi từ  5 - 40%.\n\n2. PHÂN NHÓM CÁC THAI NGHÉN NGUY CƠ CAO\nVề mặt lâm sàng, người ta chia ra 4 nhóm nguy cơ:\n2.1. Nhóm 1: các yếu tố nguy cơ có liên quan về nhân trắc học, bao gồm: tuổi mẹ, chiều cao, cân nặng, điều kiện kinh tế xã hội và các yếu tố di truyền.\n2.1.1. Tuổi mẹ: Mang thai ở tuổi vị thành niên (dưới 18 tuổi) có nguy cơ tiền sản giật, thai chậm phát triển trong tử cung, doạ đẻ non và đẻ non, và mẹ thiểu năng dinh dưỡng, lây lan các bệnh viêm nhiễm theo đường tình dục.\nMẹ trên 35 tuổi có nguy cơ cao huyết áp do thai, tiền sản giật, nhau tiền đạo, bệnh béo phì, các bệnh nội khoa khác. Những bất thường về nhiễm sắc thể có thể gặp ở trẻ sinh ra từ các bà mẹ lớn tuổi\n2.1.2. Chiều cao của mẹ: mẹ có chiều cao dưới 1m45 thường có nguy cơ xương chậu hẹp gây nên ngôi bất thường, đẻ khó.\n2.1.3. Cân nặng mẹ\n-  Mẹ nhẹ cân: khi cân nặng dưới 40kg khi có thai có thể do thiếu dinh dưỡng, bệnh chán ăn. Nguy cơ của thiếu cân trong thai kỳ là sinh ra một em bé nhẹ cân hơn tuổi thai, chậm phát triển trong tử cung, suy thai, thai ngạt, sơ sinh hạ đường máu, giảm thân nhiệt, tỷ lệ tử vong và bệnh lý cao.\n- Mẹ béo phì: Là những bà mẹ có cân nặng trên 70kg. Các biến chứng thường gặp ở mẹ béo phì là rối loạn cao huyết áp có từ trước và trong khi có thai, tần suất gặp từ 4 - 7%, biến chứng đái đường cũng hay gặp. Ngoài ra còn gặp các biến chứng khác như viêm đường tiết niệu, viêm tĩnh mạch. Mẹ béo phì thường sinh một em bé lớn, ngôi thế không rõ ràng, tỷ lệ mổ lấy thai cao và dễ nhiễm trùng sau mổ.\n2.1.4. Các bệnh di truyền: Các bệnh do cha mẹ truyền cho con, xảy ra trong quá trình thụ thai (phối hợp giữa tinh trùng và noãn) hoặc do sự tiếp xúc với môi trường ô nhiễm. Ví dụ như chứng tam bội thể 21 (trisomie) gây ra hội chứng Usker ở trẻ nhỏ với thoái hoá sắc tố ở võng mạc, điếc, xơ cứng teo cơ.\nRối loạn nhiễm sắc thể (đơn bội thể, tam bội thể) thường gây sẩy thai ở 12 tuần đầu. Bệnh Down gặp ở sản phụ nhiều tuổi, thai bé nhỏ, non yếu, gặp ở phụ nữ quá trẻ hoặc cơ  thể nhỏ bé.\n2.1.5. Điều kiện về kinh tế xã hội: Mức sống vật chất thấp, lao động quá nặng nhọc, sống ở nơi chật hẹp, thiếu vệ sinh, tinh thần căng thẳng thường làm thai kém phát triển, gây tỷ lệ đẻ non cao.\n2.1.6. Yếu tố dinh dưỡng: Năng lượng dự trữ trong thời gian sắp có thai, thức ăn hàng ngày và thức ăn bổ sung trong thời gian mang thai có thể ảnh hưởng tới tốc độ tăng trưởng và phát triển của thai. Thiếu năng lượng trường diễn dẫn tới sinh ra trẻ thiếu cân. Thiếu acid folic là nguyên nhân đầu tiên ảnh hưởng đến khuyết tật ống thần kinh. Mẹ thiếu vitamin B1 có liên quan tới một số trường hợp tử vong cấp của sơ sinh và các tình trạng tim của thai nhi bị sung huyết. Thiếu vitamin D có thể dẫn tới tình trạng hạ canxi huyết và cơn tetani của sơ sinh.\nNgoài ra các yếu tố về môi trường, mẹ nghiện thuốc lá, nghiện rượu cũng là các yếu tố nguy cơ.\n2.2. Nhóm 2: các yếu tố liên quan đến các bệnh lý chung\n2.2.1. Các bệnh nhiễm khuẩn của mẹ\n- Bệnh nhiễm khuẩn: thường nặng lên gây nhiều nguy cơ cho thai :\n+ Thời kỳ sắp xếp tổ chức: một số bệnh do virus như cúm, sốt xuất huyết, Rubéon, do vi khuẩn Listéria, do ký sinh trùng Toxoplasma gây những dị dạng cho thai như não úng thuỷ, bụng cóc, sứt môi hở hàm  ếch.\n+ Thời kỳ hoàn chỉnh tổ chức: do lớp hội bào mỏng dần làm cho vi khuẩn, virus, ký sinh trùng dễ thấm qua màng ngăn của rau thai (độc tố, kháng thể) gây bệnh cho thai như như viêm gan, giang mai, viêm não, viêm phổi.\n- Hậu quả của nhiễm khuẩn:\n+ Quý I bệnh của phôi, sẩy thai tự nhiên.\n+ Quý II chết thai, sẩy thai muộn, lây nhiễm qua bánh rau.\n+ Quý III lây qua bánh rau, đẻ non, chết thai.\n+  Lây nhiễm chu sinh (viêm gan), trong quý II và III lây nhiễm qua bánh rau có thể gây ra nhiễm khuẩn bẩm sinh với nguy cơ thai bị bệnh.\n2.2.2. Các bệnh về gan: Thường gặp viêm gan do virus gây suy gan cấp, xơ gan làm giảm chức năng gan, gây chảy máu, hôn mê, tử vong trong cuộc đẻ. Đối với thai thường bị dị dạng ở 10 tuần lễ đầu hoặc bị sẩy thai. Từ tuần lễ thứ 12 trở đi làm thai bị viêm gan, gây dễ sẩy, đẻ non hoặc chết lưu. Nếu thai nhi sinh ra từ mẹ mang kháng nguyên HBs gần 2% trong số trẻ này trở thành người mang virus mạn tính sẽ có nguy cơ bị tổn thương gan nặng.\n\nTình trạng huyết thanh của thai phụ\nở quý 3\nNguy cơ lây cho TSS  khi đẻ hoặc sau đẻ\nXử trí\n\nKháng nguyên HBs (+) / KN HBe (+)\nKhángnguyên HBs (+) / KNHBe (-)\nKháng nguyên HBs(-) / Kháng thể HBc(+)\nKháng nguyên HBs (-) / kháng thể HBs(+)\n90 đến 100%\n20%\nKhông biết - ít\n0%\nTiêm  huyết thanh\nTiêm huyết thanh\nKhông xử trí\nKhông xử trí\n\nBảng1: Nguy cơ lây cho trẻ sơ sinh phụ thuộc vào tình trạng huyết thanh của mẹ ở quý 3.\nDự phòng cho trẻ sơ sinh mang virus bằng cách tiêm Immoglobuline đặc hiệu 0,5ml/kg tiêm bắp sau sinh 48 giờ.\nSau đó tiêm hàng tháng 0,16ml/kg trong 6 tháng và nhắc lại sau một năm.\n2.2.3. Các bệnh về thận: Viêm thận, viêm mủ bể thận, cao huyết áp, các bệnh này sẽ nặng lên lúc mang thai gây nhiều biến chứng như: rau bong non, sản giật do co thắt tiểu động mạch, lượng máu rau thai ít làm rau bị xơ hoá, bánh rau nhỏ, thai kém phát triển, chết lưu. Tăng tỷ lệ tử vong chu sinh. Cần điều trị tích cực và có hệ thống hoặc phải đình chỉ thai nghén để cứu mẹ.\nNguy cơ cho me: Cao huyết áp, gia tăng mức độ thương tổn thận.\n2.2.4. Các bệnh tim mạch: Chủ yếu là bệnh tim mắc phải thường nặng lên, cơ thể của thai luôn trong tình trạng thiếu oxy làm thai kém phát triển. Thiếu oxy cơ tử cung gây đẻ non, sẩy thai, tử vong và bệnh lý thai tăng gấp 2 ở bệnh nhân có loạn nhịp hoàn toàn và gấp 5 lần ở tim mất bù. Khi đẻ nếu có can thiệp bằng forceps thì dễ gây sang chấn cho thai hoặc đôi lúc phải đình chỉ thai nghén vì bệnh lý của mẹ quá nặng. Nguy cơ trẻ bị tim bẩm sinh từ 10 - 24% nếu mẹ hoặc bố cũng bị tim bẩm sinh. Nguy cơ cho mẹ: suy tim, phù phổi cấp, tử vong mẹ tăng.\n2.2.5. Các bệnh về máu: Thai nghén được coi là thiếu máu khi Hb <10gr. Thường gặp thiếu máu hồng cầu nhỏ, nhược sắc do thiếu sắt hoặc thiếu máu hồng cầu to ưu sắc do thiếu acid folic, do cung cấp không đủ khi ăn uống hay do kém hấp thu ở hệ thống tiêu hoá. Ở Việt Nam thường gặp do dinh dưỡng kém hay do giun móc làm cho thai kém phát triển, đẻ non, sẩy thai, hoặc chết lưu. Mẹ có thể bị suy tim khi mang thai, biến chứng lúc sinh và sổ nhau, tăng nguy cơ tắc mạch, nhiễm trùng.\n2.2.6. Các bệnh nội tiết: Đái đường, Basedow, Addison gây nguy cơ cao cho thai. Bệnh Basedow có thể gây đẻ non, thai suy dưỡng, nhiễm độc thai nghén. Đối với mẹ làm tăng tỷ lệ tử vong.\n2.2.7. Các bệnh khác như: Ung thư, thường tiến triển nhanh. Các bệnh nghề nghiệp như nhiễm độc chì, thuỷ ngân, các chất hoá học, phóng xạ, nghiện rượu, thuốc lá thường gây ra dị dạng, sẩy thai, thai lưu hoặc đẻ non.\n2.2.8. Các bệnh phụ khoa\n- Thiểu năng nội tiết (Estrogen, Progesteron) gây sẩy thai.\n- Viêm nhiễm đường sinh dục, gây ra viêm màng thai, nhiễm khuẩn ối, nhiễm khuẩn thai.\n- Các dị dạng tử cung, u xơ, hở eo... gây sẩy thai hay đẻ non.\n\n2.3. Nhóm 3: Các yếu tố liên quan đến  tới tiền sử sản phụ khoa\n- Đẻ khó, can thiệp thủ thuật gây sang chấn cho thai nhi\n- Sản phụ có tiền sử sẩy thai liên tiếp, chết lưu, đẻ non nhiều lần dễ gây ra nguy hiểm cho thai, đẻ con chết nhiều lần. Khi người phụ nữ có tiền sử sẩy thai liên tiếp từ 3 lần trở lên thì chỉ có cơ hội đẻ con sống là 30% và nguy cơ đẻ non cao hơn 20% so với người bình thường.\n- Điều trị vô sinh\n- Mổ lấy thai, sẹo cũ ở tử cung (bóc u, tạo hình... )\n2.4. Nhóm 4: các yếu tố gây nguy cơ liên quan đến bệnh lý xảy ra trong thời kỳ có thai\n2.4.1. Tiền sản giật - sản giật: làm thai kém phát triển, đẻ non do mẹ bị sản giật, rau bong non, nhiều khi gây tử vong cho cả mẹ và thai\n2.4.2. Nguyên nhân do phần phụ của thai\nNguyên nhân do bánh nhau\nRau tiền đạo: gặp ở những thai phụ suy dinh dưỡng, nạo thai hay đẻ nhiều lần. Thai thường bị đẻ non, những trường hợp nặng phải mổ để cứu thai phụ.\nRau bong non: Làm hai bị thiếu oxy nghiêm trọng,thai phụ bị mất máu nhiều, đe doạ đến tính mạngcủa thai nhi và thai phụ.\nRau xơ hoá (calci hoá) hay gặp trong nhiễm độc thai nghén hoặc thiểu năng nội tiết, bánh nhau kém phát triển, sự trao đổi chất dinh dưỡng, oxy giữa mẹ và thai giảm, làm cho thai kém phát triển, chết lưu hoặc đẻ non.\nNguyên nhân do màng ối\n- Rỉ ối, ối vỡ non gây nhiễm khuẩn ối, nhiễm khuẩn cho thai nhi. Thai phụ đôi khi phải mổ cắt tử cung ở những thể nhiễm trùng nặng.\nNguyên nhân do dây rau:\n- Dây rau ngắn, dây rau cuốn cổ dây rau thắt nút, khối u ở dây rau dây rau bị chèn ép, hoặc sa dây rau dều làm cho thai nhi bình chỉnh không tốt, hoặc ngăn cản tuần hoàn nhau thai làm cho thai chết.\nNguyên nhân do nước ối\n- Đa ối:\n+ Đa ối cấp ít gặp, thường xuất hiên vào tháng thứ 4 hoặc thứ 5, gây khó thở cho thai phu, phải tia ối để cứu mẹ.Trong đa ối cấp thai thường dị dạng\n+ Đa ối mạn: thường gặp nhiều hơn, xuất hiện muộn vào những tháng cuối, tiến triển từ từ, thai thường bị dị dạng, đẻ non, ngôi thế bất thường.\n- Thiểu ối\n2.4.3. Các nguyên nhân do thai\n-  Thai già tháng: Bánh rau bị thoái hoá làm giảm cung cấp chất dinh dưỡng và oxy cho thai, thai suy dần, nhỏ lại các cơ quan chức năng của thai nhi suy giảm, làm thai bị chết trong tử cung, hoặc nếu đẻ ra thì cũng chết trong tuần đầu với tỷ lệ cao.\n-  Thai dị dạng\n+ Dị dạng lớn: Não úng thuỷ, vô sọ, bụng cóc, thai thường bị chết.\n+ Dị dạng nhỏ: Hở hàm ếch, thừa ngón chân, ngón tay.\n\n\nHình 1. Quái thai vô sọ                        Hình 2. CT scan não úng thủy\n\n\nHình 3. Hở hàm ếch\n\n-  Thai bị bệnh và nhiễm khuẩn:  Thai bị các bệnh di truyền, bệnh bẩm sinh, bị nhiễm khuẩn trong buồng tử cung đều bị chết đột ngột, chết lưu, sẩy thai hoặc đẻ non.\n-  Đa thai: sinh đôi, sinh ba thai thường nhỏ, non yếu dễ đẻ non. Khi đẻ có thể thai mắc vào nhau hoặc mắc kẹt, hoặc ngôi thế bất thưòng. Mẹ sau đẻ dễ bị băng huyết.\n- Bất đồng nhóm máu giữa mẹ và thai: thường gặp là yếu tố Rh, ngày nay người ta đã phát hiện bất đồng nhóm máu A - O - B giữa mẹ và con, hậu quả  sơ sinh  vàng da, tán huyết, dẫn đến vàng da nhân.\nTóm lại, hậu quả của thai nghén có nguy cơ cao, thường gây:\n- Sẩy thai.\n- Đẻ non.\n- Thai kém phát triển.\n- Suy thai cấp tính và mãn tính.\n- Thai chết trong tử cung.\n- Tăng tỷ lệ tử vong chu sinh.\n- Đối với mẹ gây tăng tỷ lệ can thiệp trong và sau đẻ, tăng tỷ lệ mổ đẻ. Thậm chí gây tử vong mẹ.\n2.4.4. Một số phương pháp thăm dò sản khoa phát hiện các yếu tố nguy cơ của thai\nSiêu âm trong theo dõi thai nghén nguy cơ cao\n- 10 - 12 tuần: Xác định thai, số lượng thai, tình trạng thai, bệnh lý phối hợp, phát hiện những bất thường về nhiễm sắc thể, bất thường về thai.\n- 20 - 22 tuần: Phát hiện các dị dạng thai nhi, vị trí nhau, thể tích nước ối, mạch máu cuống rốn.\n- 30 - 32 tuần: ngôi thai, sự phát triển của thai, dị dạng thai nếu có, vị trí hình dạng của bánh rau, lượng nước ối.\nDoppler động mạch tử cung (từ tuần 20 - 24 ) ở thai nghén nguy cơ cao, thai chậm phát triển trong tử cung, tiền sản giật.\nDoppler động mạch rốn  28 - 34 tuần. Thai nghén nguy cơ, nguy cơ mạch máu ở mẹ Nhiễm độc thai nghén, suy thai, song thai, thai bất thường.\nDoppler  động mạch não từ  tuần thứ  26 thai chậm phát triển.\nMonitoring sản khoa theo dõi tim thai\nRất có giá trị trong việc theo dõi và đánh giá sức khoẻ của thai nhi trong thai kỳ và trong chuyển dạ, góp phần làm giảm tỷ lệ mắc bệnh (morbidity) và tử vong (mortality) chu sinh.\n\n3. CHĂM SÓC VÀ QUẢN LÝ THAI NGHÉN NGUY CƠ CAO\nĐể có thể giảm tỷ lệ tai biến trong những trường hợp thai nghén có nguy cơ cao cần phát hiện sớm, theo dõi và xử trí kịp thời bao gồm:\n- Cung cấp những lời khuyên, giáo dục, tư vấn cho phụ nữ có thai và gia đình họ.\n- Cung cấp các dịch vụ lâm sàng, cận lâm sàng để đảm bảo rằng người phụ nữ luôn ở nguy cơ thấp.\n- Dự phòng, xử trí những vấn đề và những yếu tố bất lợi cho mẹ và thai.\n- Giảm tỷ lệ bệnh suất và tử suất cho mẹ, giảm tỷ lệ bệnh suất và tử suất chu sinh.\n3.1. Số lần khám thai\nỞ Việt nam số lần khám thai khuyên tối thiểu là 3 lần ở thai nghén bình thường. Đối với thai nghén nguy cơ cao yêu cầu người phụ nữ khám thai 4 tuần một lần cho tới tuần 28. Sau đó 2 tuần một lần cho tới tuần 36, và hàng tuần cho tới tuần 40. Như vậy, có ít nhất từ 13 lần khám thai cho tuổi thai từ tuần thứ 8 - tuần 40.\nMỗi lần khám thai nếu nhận diện được yếu tố nguy cơ cần có thái độ xử trí thích hợp cho từng trường hợp.\n3.2. Nội dung chăm sóc và quản lý thai nghén nguy cơ cao\nSơ đồ chăm sóc tiền sản\nTuần thai nghén\nHoạt động\n\n\nTuần 8-14\nXác định thai nghén. Hỏi về: tiền sử nội ngoại khoa, tiền sử gia đình và tiền sử sản khoa\nKhám toàn thân. Khám tiểu khung nếu có chỉ dịnh.\nXét nghiệm: phân tích nước tiểu (protein/glucoza/ máu)\nCông thức máu. Nhóm máu ABO/ Rh\nHuyết thanh học các bệnh (sởi, giang mai).\nTư vấn dinh dưỡng, thể dục, chăm sóc vú, răng, vấn đề cho con bú, vấn dề kế hoạch hoá gia đình sau đẻ.\n\nTuần 16\nXét nghiệm máu để phát hiện những trường hợp có nguy cơ hở ống thần kinh và bệnh down\n\nTuần 18\nSiêu âm hình thái học kiểm tra lại kết quả huyết thanh học khi 16 tuần. Xác định ngày sinh dự đoán\n\nTuần 22-24\nKhám thai thường quy :hỏi bệnh sử, các triệu chứng đặc biệt (xuất huyết âm đạo, giảm hoặc mất cử động thai).\nPhân tích nước tiểu, đo chiều cao tử cung, vòng bụng. Kiểm tra huyết áp.\n\nTuần 28\nKhám thường quy tim thai, nước ối, chiều cao tử cung đánh giá sự phát triển của thai. Làm công thức máu.\n\nTuần 32\nKhám thai thường quy. Kiểm tra huyết áp. Thảo luận về vấn đề sinh đẻ đối với phụ  nữ có thai và gia đình họ.\n\nTuần 36\nKhám thai thường quy. Kiểm tra huyết áp công thức máu, ngôi thai bất thường hay không\n\nTuần 38\nKhám thai thường quy. Kiểm tra huyết áp. Sự phát triển của thai. Ngôi thai bất thường\n\nTuần 40\nKhám thường quy kiểm tra huyết áp, ngôi thai. Thảo luận về cuộc đẻ.\n\nTuần 41\nKhám lại và thảo luận gây chuyển dạ nhân tạo.\n\n\n3.3. Một số thăm dò để phát hiện thai nghén nguy cơ cao\nThăm dò\nCác yếu tố nguy cơ có thể phát hiện\n\n1. Siêu âm thai\nVị trí, số túi thai, thai bất thường\n\n2. Xét nghiệm alpha-foetoprotein\nTật hở ống thần kinh, Down\n\n3. Chiều cao tử cung ở thai nguy cơ cao\nBệnh lý về sự phát triển của thai\n\n4. Siêu âm lặp lại về kích thước thai\nBệnh lý về sự phát triển của thai\n\n5. Các tests về sức khoẻ thai nhi\nThai chết\n\n6. Doppler mạch máu ở thai\nThai suy\n\n7. Rhesus antibody\nThiếu máu tiêu huyết do Rh.\n\n8. Siêu âm định kỳ\nNgôi thai, vị trí nhau, ối\n\n9.  Huyết áp và phân tích nước tiểu\nTiền sản giật\n\n10. Thăm dò độ dung nạp glucoza\nĐái đường do thai nghén\n\n11. Xét nghiêm nước tiểu\nNhiễm trùng tiết niệu không triệu chứng\n\n12. Huyết thanh học với giang mai, lậu\nNhiễm trùng mẹ và thai.\n\n\n\n\n\n3.4. Một số biện pháp điều trị dự phòng trong thai nghén nguy cơ cao:\nChiến lược cung cấp\nLợi ích\n\n1.Cung cấp vitamin và folate\nDự phòng tật hở cột sống\nGiảm nguy cơ mắc bệnh khi có thai\n\n2. Siêu âm thường quy\nGiảm tỷ lệ thai già tháng\n\n3. Điều trị cao huyết áp\nGiảm cao huyết áp nặng khi có thai ở phụ nữ cao huyết áp\n\n4. Đảm bảo kiểm soát đươc bệnh đái đường\nGiảm nhiễm trùng tiết niệu, giảm đẻ non,                                                                      giảm mổ lấy thai, thai to, suy hô hấp.                                                               Tử vong chu sinh giảm\n\n5. Khâu eo tử cung\nGiảm tỷ lệ đẻ non\n\n6. Siêu âm phát hiện thai bất thường\nGiảm sự cố sinh ra trẻ sơ sinh bất thường, giảm tỷ lệ mắc bệnh của mẹ\n\n7. Xét nghiệm hoá sinh\nGiảm tỷ lệ bệnh suất và tử suất chu sinh\n\n8. Trắc nghiệm sinh học thai nhi bình thường\nGiảm tỷ lệ bệnh suất và tử suất chu sinh\n\n9. Doppler mạch máu thai nhi\nGiảm tỷ lệ bệnh suất và tử suất chu sinh\n\n10. Nhập viện đối với cao huyết áp không có protein niệu\nGiảm phát triển protein niệu nặng...\n\n\n\n\nCâu hỏi:\n1.  Trỡnh bày các yếu tố nguy cơ có liên quan về nhân trắc học?\n2.  Trỡnh bày các yếu tố nguy cơ có liên quan đến bệnh lý chung?\n\n3.  Trỡnh bày các yếu tố nguy cơ có liên quan đến tiền sử sản phụ khoa?\n4.  Trỡnh bày các yếu tố nguy cơ có liên quan đến bệnh lý xảy ra trong thời kỳ có thai ?\n5. Trình bày các hậu quả của thai nghén nguy cơ cao?", "priority": "Trung bình"}, {"id": "SK-25", "chapter": "Chương 2. Sản bệnh", "folder": "02_San_benh", "title": "Chỉ định mổ lấy thai", "author": "Ths. Nguyễn Trung Kiên", "word_count": 1743, "line_count": 91, "key_numbers": ["24 tháng", "25 ngày", "42 tuần", "50 cm", "8,5 cm", "8,5cm", "95 mm", "9cm"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["Chỉ định mổ lấy thai", "Ths. Nguyễn Trung Kiên"], "bullets": []}, {"heading": "1. Đại cương", "paragraphs": ["Định nghĩa: mổ lấy thai là một phẫu thuật mở tử cung lấy thai, rau thai và màng rau theo đường rạch trên bụng.", "Lịch sử phẫu thuật mổ lấy thai:", "1610: Cuộc mổ trên người sống đầu tiên, mẹ chết sau mổ 25 ngày.", "1805: Osiauder mô tả phẫu thuật mổ ngang đoạn dưới.", "1882: Sanger đề nghị một phẫu thuật ngày nay được gọi là mổ lấy thai theo phương pháp cổ điển hay mổ dọc thân tử cung lấy thai, nay ít áp dụng.", "Nửa sau thế kỷ XIX tỷ lệ tử vong mẹ do mổ lấy thai cao 50 ư 85% do chảy máu, nhiễm khuẩn.", "Nửa đầu thế kỷ XX mổ lấy thai còn hạn chế do nhiễm trùng và gây mê hồi sức kém.", "Ngày nay mổ lấy thai ngày càng rộng rãi do phương tiện vô khuẩn, kháng sinh, truyền máu, gây mê hồi sức tốt.", "ở Việt Nam trước năm 1954 chỉ mổ thân tử cung lấy thai. Khoảng từ năm 1955 ư 1956 mới bắt đầu mổ lấy thai qua đoạn dưới tử cung. Tại các bệnh viện trong cả nước tỷ lệ mổ lấy thai cũng tăng dần theo hàng năm", "Chỉ địng mổ lấy thai có những đặc điểm khác với các chỉ định về phụ khoa, ngoại khoa nói chung. Ngoài các chỉ định có tính chất tuyệt đối, đa số các chỉ định mổ lấy thai có tính tương đối mà theo sản khoa cổ điển có thể giải quyết cho đẻ đường dưới bằng thủ thuật: fooc xep, giác hút, nội xoay thai, đại kéo thai, huỷ thai....Có nhiều trường hợp mổ lấy thai mang tính chất dự phòng"], "bullets": []}, {"heading": "2. Những đặc điểm của chỉ định mổ lấy thai", "paragraphs": ["Chỉ định mổ lấy thai ít khi là một chỉ định đơn độc mà hay phối hợp nhiều chỉ định với nhau phụ thuộc vào nhiều yếu tố như bệnh lý, tâm lý, gia đình, xã hội.", "Chỉ định mổ lấy thai thay đổi tuỳ trường phái,  tuỳ từng thầy thuốc, từng nước và từng giai đoạn.", "Chỉ định mổ lấy thai có chiều hướng mở rộng nên tỷ lệ ngày càng tăng.", "Có nhiều chỉ định phối hợp làm tỷ lệ mổ lấy thai tăng", "Kỹ thật vô trùng, tiệt trùng gây tê, gây mê và cải tiến kỹ thuật đã làm cho tỷ lệ tử vong do mổ lấy thai giảm.", "Phân loại chỉ định mổ lấy thai: ngày nay người ta thường phân làm 2 nhóm chỉ định mổ lấy thai sau: mổ lấy thai dự phòng (mổ chủ động khi chưa có chuyển dạ) và mổ lấy thai trong thời kỳ chuyển dạ"], "bullets": []}, {"heading": "3. Những chỉ định mổ lấy thai dự phòng", "paragraphs": ["Chỉ định được đặt ra ngay trong thời gian đang được theo dõi thai nghén và nguyên nhân đưa đến chỉ định mổ có thể là:"], "bullets": []}, {"heading": "3.1. Khung chËu bÊt th­êng", "paragraphs": ["Khung chậu hẹp toàn diện: khung chậu có tất cả các đường kính giảm đều cả eo trên và eo dưới đặc biệt đường kính nhô hậu vệ < 8,5 cm", "Khung chậu méo (khung chậu lệch hay khung chậu không đối xứng). Dựa vào đo hình trám Michaelis không cân đối và đường kính nhô hậu vệ < 8,5cm", "Khung chậu hình phễu : khung chậu biến dạng làm  eo dưới hẹp, eo trên rộng. Thai lọt qua eo trên dễ dàng nhưng khó sổ hoặc không sổ được qua eo dưới. Chẩn đoán dựa vào đo đường kính lưỡng ụ ngồi, nếu đường kính này < 9cm."], "bullets": []}, {"heading": "3.2. Đường xuống của thai bị cản trở", "paragraphs": ["Do mẹ có các khối u tiền đạo làm cho ngôi không lọt và không xuống được (u buồng trứng, u xơ tử cung, u âm đạo, u vòi trứng...)", "Rau tiền đạo: bán trung tâm hoặc trung tâm."], "bullets": []}, {"heading": "3.3. Tử cung có sẹo xấu", "paragraphs": ["Sẹo mổ cũ ở thân tử cung.", "Sẹo do vết khâu vỡ tử cung.", "Sẹo mổ cũ đã 2 lần hoặc < 24 tháng.", "Sẹo mổ cũ lần trước vì một lý do nhất thời nhưng lần này ngôi bất thường: ngôi mông, ngôi vai hoặc có những biến cố khác", "Sẹo mổ cũ dính, mỏng, đau khi thăm khám hoặc sẹo nhiễm trùng."], "bullets": []}, {"heading": "3.4. Nguyên nhân về phía mẹ", "paragraphs": ["Trong các bệnh tim ở giai đoạn không bù trừ", "Bệnh cao huyết áp, tai biến mạch máu não, nhiễm độc thai nghén có thể nguy hiểm cho mẹ và con.", "Âm đạo bị chít hẹp bẩm sinh hoặc bị rách trong các lần đẻ trước không được khâu phục hồi tốt hoặc sau những trường hợp mổ có liên quan đến âm đạo như mổ sa sinh dục, mổ dò bàng quang âm đạo, mổ dò trực tràng âm đạo,...", "Bảo tồn kết quả phẫu thuật chỉnh hình phụ khoa: tạo hình âm đạo, treo tử cung trong sa sinh dục...", "Các dị dạng sinh dục: tử cung đôi, tử cung hai sừng hoặc đáy tử cung có vách ngăn, sau phẫu thuật Strassmann, các dị tật ở âm đạo: vách ngăn âm đạo..."], "bullets": []}, {"heading": "3.5. Nguyên nhân về phía thai", "paragraphs": ["Suy thai mạn tính: suy dinh dưỡng nặng, bất đồng nhóm máu....", "Thai dính nhau, hoặc thai thứ nhất là ngôi vai trong đa thai.", "Đối với mổ lấy thai chủ động, dù do nguyên nhân gì cũng phải xác định chắc chắn không có dị dạng thai. Về thời điểm mổ, ở nước ta chưa có quy định cụ thể, nhưng ở Pháp mổ dự phòng thường được thực hiện trong tuần thứ 39 của thai nghén để đảm bảo chắc chắn thai đã trưởng thành có khả năng sống tốt khi ra ngoài"], "bullets": []}, {"heading": "4. Chỉ định mổ lấy thai trong chuyển dạ", "paragraphs": ["Các chỉ định mổ lấy thai trong chuyển dạ có thể do một tình huống cấp cứu, do một tiến triển bất thường của chuyển dạ hoặc do một nguyên nhân bệnh lý nào đó chưa được phát hiện trong thời kỳ trước chuyển dạ."], "bullets": []}, {"heading": "4.1. Chảy máu", "paragraphs": ["* Rau tiền đạo:", "Rau tiền đạo trung tâm và bán trung tâm phải mổ lấy thai", "Rau tiền đạo bám mép: mổ lấy thai nếu ra máu nhiều. Nếu máu ra ít, ngôi thế và cổ tử cung thuận lợi thì bấm ối, xé ối cầm máu.", "Rau tiền đạo bám bên và bám thấp: mổ lấy thai nếu ra máu nhiều. Nếu máu ra ít thì đẻ đường dưới.", "Rau tiền đạo kết hợp rau cài răng lược: mổ lấy thai kèm theo cắt tử cung.", "* Rau bong non: nếu chẩn đoán là rau bong non thì mổ lấy thai ngay để cứu con và phòng biến chứng nặng hơn cho mẹ."], "bullets": ["- Nguyên tắc:", "+ Cầm máu cứu mẹ là chính", "+ Nghi ngờ rau tiền đạo phải chuyển lên tuyến Huyện có khả năng phẫu thuật", "+ Nghi ngờ rau tiền đạo kèm theo rau cài răng lược phải chuyển lên tuyến tỉnh và trung ương.", "- Điều trị cụ thể:", "+ Chưa chuyển dạ: nếu thai đủ tháng thì mổ lấy thai chủ động cho các loại rau tiền đạo trung tâm. Nếu rau tiền đạo chảy máu nhiều thì mổ lấy thai ở bất kỳ tuổi thai nào.", "+ Khi chuyển dạ:"]}, {"heading": "4.2. Doạ vỡ tử cung", "paragraphs": ["Nếu không đủ điều kiện lấy thai đường dưới bằng forceps thì phải chỉ định mổ lấy thai."], "bullets": []}, {"heading": "4.3. Sa d©y rau", "paragraphs": ["Đây là một cấp cứu sản khoa số một khi thai còn sống, nên cần chỉ định mổ khẩn cấp kết hợp với hồi sức tim thai tích cực. Nếu thai đã chết không có chỉ định mổ."], "bullets": []}, {"heading": "4.4. Chỉ định mổ về phía thai", "paragraphs": ["Thai to: thai to toàn bộ không tương xứng với khung chậu, không có khả năng lọt qua eo trên cần chỉ định mổ lấy thai. Loại trừ những thai to một phần: não úng thuỷ, bụng cóc để có chỉ định huỷ thai", "Ngôi ngang hay ngôi vai buông trôi: con sống, đã chuyển dạ thì mổ. Con chết không đủ điều kiện nội xoay cũng mổ.", "Ngôi trán.", "Ngôi chỏm sa chi không đẩy lên được, tiền sử đẻ khó.", "Ngôi ngược con so, đường kính lưỡng đỉnh 95 mm, tầng sinh hẹp rắn sẹo cũ, con so lớn tuổi, con dạ khung chậu giới hạn, hiếm con, tiền sử sản khoa nặng nề.", "Ngôi mặt cằm cùng", ", con so, mẹ nhiều tuổi, con to, ối vỡ sớm, chuyển dạ kéo dài.", "Thai suy, xuất hiện DIP II liên tục trong các cơn co, nhịp tim thai giao động dưới 10 nhịp, đo pH máu giảm dưới 7,20 (thai nhiễm toan).", "Thai già tháng từ 42 tuần trở lên, nước ối ít, đổi màu, xuất hiện DIP II.", "Thai dị dạng, đầu to vòng đầu trên 50 cm do bất sản sụn xương.", "Đa thai: Hai thai chèn nhau, thai thứ nhất là ngôi vai, ba thai trở lên, có thêm một nguyên nhân đẻ khó"], "bullets": []}, {"heading": "4.5. Chỉ định do mẹ", "paragraphs": ["Chỉ định mổ lấy thai vì tử cung có sẹo mổ cũ", "Con so lín tuæi.", "Tình trạng bệnh lý của mẹ: tăng huyết áp, bệnh tim đã có suy tim hoặc nguy cơ phù phổi cấp, thiếu máu nặng, đái tháo đường không được theo dõi, ung thư cổ tử cung tại chỗ hoặc xâm lấn."], "bullets": []}, {"heading": "4.6. Các chỉ định do bất thường xảy ra khi theo dõi chuyển dạ", "paragraphs": ["Trong quá trình theo dõi chuyển dạ có những tình huống xảy ra không cho phép tiếp tục theo dõi cho đẻ đường dưới khi đó chỉ định mổ lấy thai cần được đặt ra.", "Đẻ khó do cổ tử cung không tiến triển: cổ tử cung có sẹo cũ xấu, khoét chóp hay cắt đoạn cổ tử cung", "Các đẻ khó do nguyên nhân cơ học, nghiệm pháp lọt ngôi chỏm thất bại.", "Các đẻ khó do nguyên nhân động lực: là các đẻ khó do rối loạn cơn co tử cung.", "Suy thai cấp trong chuyển dạ."], "bullets": []}], "raw_text": "Chỉ định mổ lấy thai\nThs. Nguyễn Trung Kiên\n1. Đại cương\nĐịnh nghĩa: mổ lấy thai là một phẫu thuật mở tử cung lấy thai, rau thai và màng rau theo đường rạch trên bụng.\nLịch sử phẫu thuật mổ lấy thai:\n1610: Cuộc mổ trên người sống đầu tiên, mẹ chết sau mổ 25 ngày.\n1805: Osiauder mô tả phẫu thuật mổ ngang đoạn dưới.\n1882: Sanger đề nghị một phẫu thuật ngày nay được gọi là mổ lấy thai theo phương pháp cổ điển hay mổ dọc thân tử cung lấy thai, nay ít áp dụng.\nNửa sau thế kỷ XIX tỷ lệ tử vong mẹ do mổ lấy thai cao 50 ư 85% do chảy máu, nhiễm khuẩn.\nNửa đầu thế kỷ XX mổ lấy thai còn hạn chế do nhiễm trùng và gây mê hồi sức kém.\nNgày nay mổ lấy thai ngày càng rộng rãi do phương tiện vô khuẩn, kháng sinh, truyền máu, gây mê hồi sức tốt.\nở Việt Nam trước năm 1954 chỉ mổ thân tử cung lấy thai. Khoảng từ năm 1955 ư 1956 mới bắt đầu mổ lấy thai qua đoạn dưới tử cung. Tại các bệnh viện trong cả nước tỷ lệ mổ lấy thai cũng tăng dần theo hàng năm\nChỉ địng mổ lấy thai có những đặc điểm khác với các chỉ định về phụ khoa, ngoại khoa nói chung. Ngoài các chỉ định có tính chất tuyệt đối, đa số các chỉ định mổ lấy thai có tính tương đối mà theo sản khoa cổ điển có thể giải quyết cho đẻ đường dưới bằng thủ thuật: fooc xep, giác hút, nội xoay thai, đại kéo thai, huỷ thai....Có nhiều trường hợp mổ lấy thai mang tính chất dự phòng\n2. Những đặc điểm của chỉ định mổ lấy thai\nChỉ định mổ lấy thai ít khi là một chỉ định đơn độc mà hay phối hợp nhiều chỉ định với nhau phụ thuộc vào nhiều yếu tố như bệnh lý, tâm lý, gia đình, xã hội.\nChỉ định mổ lấy thai thay đổi tuỳ trường phái,  tuỳ từng thầy thuốc, từng nước và từng giai đoạn.\nChỉ định mổ lấy thai có chiều hướng mở rộng nên tỷ lệ ngày càng tăng.\nCó nhiều chỉ định phối hợp làm tỷ lệ mổ lấy thai tăng\nKỹ thật vô trùng, tiệt trùng gây tê, gây mê và cải tiến kỹ thuật đã làm cho tỷ lệ tử vong do mổ lấy thai giảm.\nPhân loại chỉ định mổ lấy thai: ngày nay người ta thường phân làm 2 nhóm chỉ định mổ lấy thai sau: mổ lấy thai dự phòng (mổ chủ động khi chưa có chuyển dạ) và mổ lấy thai trong thời kỳ chuyển dạ\n3. Những chỉ định mổ lấy thai dự phòng\nChỉ định được đặt ra ngay trong thời gian đang được theo dõi thai nghén và nguyên nhân đưa đến chỉ định mổ có thể là:\n3.1. Khung chËu bÊt th­êng\nKhung chậu hẹp toàn diện: khung chậu có tất cả các đường kính giảm đều cả eo trên và eo dưới đặc biệt đường kính nhô hậu vệ < 8,5 cm\nKhung chậu méo (khung chậu lệch hay khung chậu không đối xứng). Dựa vào đo hình trám Michaelis không cân đối và đường kính nhô hậu vệ < 8,5cm\nKhung chậu hình phễu : khung chậu biến dạng làm  eo dưới hẹp, eo trên rộng. Thai lọt qua eo trên dễ dàng nhưng khó sổ hoặc không sổ được qua eo dưới. Chẩn đoán dựa vào đo đường kính lưỡng ụ ngồi, nếu đường kính này < 9cm.\n3.2. Đường xuống của thai bị cản trở\nDo mẹ có các khối u tiền đạo làm cho ngôi không lọt và không xuống được (u buồng trứng, u xơ tử cung, u âm đạo, u vòi trứng...)\nRau tiền đạo: bán trung tâm hoặc trung tâm.\n3.3. Tử cung có sẹo xấu\nSẹo mổ cũ ở thân tử cung.\nSẹo do vết khâu vỡ tử cung.\nSẹo mổ cũ đã 2 lần hoặc < 24 tháng.\nSẹo mổ cũ lần trước vì một lý do nhất thời nhưng lần này ngôi bất thường: ngôi mông, ngôi vai hoặc có những biến cố khác\nSẹo mổ cũ dính, mỏng, đau khi thăm khám hoặc sẹo nhiễm trùng.\n3.4. Nguyên nhân về phía mẹ\nTrong các bệnh tim ở giai đoạn không bù trừ\nBệnh cao huyết áp, tai biến mạch máu não, nhiễm độc thai nghén có thể nguy hiểm cho mẹ và con.\nÂm đạo bị chít hẹp bẩm sinh hoặc bị rách trong các lần đẻ trước không được khâu phục hồi tốt hoặc sau những trường hợp mổ có liên quan đến âm đạo như mổ sa sinh dục, mổ dò bàng quang âm đạo, mổ dò trực tràng âm đạo,...\nBảo tồn kết quả phẫu thuật chỉnh hình phụ khoa: tạo hình âm đạo, treo tử cung trong sa sinh dục...\nCác dị dạng sinh dục: tử cung đôi, tử cung hai sừng hoặc đáy tử cung có vách ngăn, sau phẫu thuật Strassmann, các dị tật ở âm đạo: vách ngăn âm đạo...\n3.5. Nguyên nhân về phía thai\nSuy thai mạn tính: suy dinh dưỡng nặng, bất đồng nhóm máu....\nThai dính nhau, hoặc thai thứ nhất là ngôi vai trong đa thai.\nĐối với mổ lấy thai chủ động, dù do nguyên nhân gì cũng phải xác định chắc chắn không có dị dạng thai. Về thời điểm mổ, ở nước ta chưa có quy định cụ thể, nhưng ở Pháp mổ dự phòng thường được thực hiện trong tuần thứ 39 của thai nghén để đảm bảo chắc chắn thai đã trưởng thành có khả năng sống tốt khi ra ngoài\n4. Chỉ định mổ lấy thai trong chuyển dạ\nCác chỉ định mổ lấy thai trong chuyển dạ có thể do một tình huống cấp cứu, do một tiến triển bất thường của chuyển dạ hoặc do một nguyên nhân bệnh lý nào đó chưa được phát hiện trong thời kỳ trước chuyển dạ.\n4.1. Chảy máu\n* Rau tiền đạo:\n- Nguyên tắc:\n+ Cầm máu cứu mẹ là chính\n+ Nghi ngờ rau tiền đạo phải chuyển lên tuyến Huyện có khả năng phẫu thuật\n+ Nghi ngờ rau tiền đạo kèm theo rau cài răng lược phải chuyển lên tuyến tỉnh và trung ương.\n- Điều trị cụ thể:\n+ Chưa chuyển dạ: nếu thai đủ tháng thì mổ lấy thai chủ động cho các loại rau tiền đạo trung tâm. Nếu rau tiền đạo chảy máu nhiều thì mổ lấy thai ở bất kỳ tuổi thai nào.\n+ Khi chuyển dạ:\nRau tiền đạo trung tâm và bán trung tâm phải mổ lấy thai\nRau tiền đạo bám mép: mổ lấy thai nếu ra máu nhiều. Nếu máu ra ít, ngôi thế và cổ tử cung thuận lợi thì bấm ối, xé ối cầm máu.\nRau tiền đạo bám bên và bám thấp: mổ lấy thai nếu ra máu nhiều. Nếu máu ra ít thì đẻ đường dưới.\nRau tiền đạo kết hợp rau cài răng lược: mổ lấy thai kèm theo cắt tử cung.\n* Rau bong non: nếu chẩn đoán là rau bong non thì mổ lấy thai ngay để cứu con và phòng biến chứng nặng hơn cho mẹ.\n4.2. Doạ vỡ tử cung\nNếu không đủ điều kiện lấy thai đường dưới bằng forceps thì phải chỉ định mổ lấy thai.\n4.3. Sa d©y rau\nĐây là một cấp cứu sản khoa số một khi thai còn sống, nên cần chỉ định mổ khẩn cấp kết hợp với hồi sức tim thai tích cực. Nếu thai đã chết không có chỉ định mổ.\n4.4. Chỉ định mổ về phía thai\nThai to: thai to toàn bộ không tương xứng với khung chậu, không có khả năng lọt qua eo trên cần chỉ định mổ lấy thai. Loại trừ những thai to một phần: não úng thuỷ, bụng cóc để có chỉ định huỷ thai\nNgôi ngang hay ngôi vai buông trôi: con sống, đã chuyển dạ thì mổ. Con chết không đủ điều kiện nội xoay cũng mổ.\nNgôi trán.\nNgôi chỏm sa chi không đẩy lên được, tiền sử đẻ khó.\nNgôi ngược con so, đường kính lưỡng đỉnh 95 mm, tầng sinh hẹp rắn sẹo cũ, con so lớn tuổi, con dạ khung chậu giới hạn, hiếm con, tiền sử sản khoa nặng nề.\nNgôi mặt cằm cùng\n, con so, mẹ nhiều tuổi, con to, ối vỡ sớm, chuyển dạ kéo dài.\nThai suy, xuất hiện DIP II liên tục trong các cơn co, nhịp tim thai giao động dưới 10 nhịp, đo pH máu giảm dưới 7,20 (thai nhiễm toan).\nThai già tháng từ 42 tuần trở lên, nước ối ít, đổi màu, xuất hiện DIP II.\nThai dị dạng, đầu to vòng đầu trên 50 cm do bất sản sụn xương.\nĐa thai: Hai thai chèn nhau, thai thứ nhất là ngôi vai, ba thai trở lên, có thêm một nguyên nhân đẻ khó\n4.5. Chỉ định do mẹ\nChỉ định mổ lấy thai vì tử cung có sẹo mổ cũ\nCon so lín tuæi.\nTình trạng bệnh lý của mẹ: tăng huyết áp, bệnh tim đã có suy tim hoặc nguy cơ phù phổi cấp, thiếu máu nặng, đái tháo đường không được theo dõi, ung thư cổ tử cung tại chỗ hoặc xâm lấn.\n4.6. Các chỉ định do bất thường xảy ra khi theo dõi chuyển dạ\nTrong quá trình theo dõi chuyển dạ có những tình huống xảy ra không cho phép tiếp tục theo dõi cho đẻ đường dưới khi đó chỉ định mổ lấy thai cần được đặt ra.\nĐẻ khó do cổ tử cung không tiến triển: cổ tử cung có sẹo cũ xấu, khoét chóp hay cắt đoạn cổ tử cung\nCác đẻ khó do nguyên nhân cơ học, nghiệm pháp lọt ngôi chỏm thất bại.\nCác đẻ khó do nguyên nhân động lực: là các đẻ khó do rối loạn cơn co tử cung.\nSuy thai cấp trong chuyển dạ.\nCâu hỏi:\n1. Anh (Chị) nêu chỉ định mổ lấy thai về phía mẹ?\n2. Anh (Chị) nêu chỉ định mổ lấy thai về phía con?\n3. Anh (Chị) nêu chỉ định mổ lấy thai về phía phần phụ của thai?", "priority": "Cao (Trọng tâm BSNT)"}, {"id": "SK-26", "chapter": "Chương 2. Sản bệnh", "folder": "02_San_benh", "title": "Forceps sản khoa", "author": "BsCK II. Nguyễn Thị Tuyết", "word_count": 1920, "line_count": 112, "key_numbers": ["12 giờ", "8 ngày"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["FORCEPS SẢN KHOA", "BsCK II. Nguyễn Thị Tuyết"], "bullets": []}, {"heading": "Mục tiêu học tập", "paragraphs": ["Nói được chỉ định của Forceps", "Nêu được điều kiện để đặt Forceps", "Trình bày được tác dụng và kỹ thuật đặt forceps", "Nắm được các tai biến của Forceps."], "bullets": []}, {"heading": "I. Đại cương", "paragraphs": ["Forceps là một dụng cụ sản khoa để giữ chắc lấy đầu thai nhi để kéo cho ngôi thai sổ ra ngoài theo cơ chế gần giống như tự nhiên, đúng như cơ chế của cuộc chuyển dạ đẻ: quay trước hay quay sau, cúi hay ngửa, xuống hay sổ, giúp cho cuộc chuyển dạ nhanh chóng kết thúc bảo vệ quyền lợi của mẹ và thai nhi.", "Forceps ra đời vào giữa thế kỷ XVII đến nay đã cứu sống nhiều em bé nhưng cũng đã xảy ra những tai biến cho mẹ và con. Ngày nay, cùng với sự phát triển của gây mê hồi sức và sự phát sinh ra kháng sinh, phẫu thuật mổ lấy thai mở rộng và có giác hút thì phạm vi sử dụng forceps ngày càng thu hẹp với những chỉ định nhất định."], "bullets": []}, {"heading": "II. Mô tả dụng cụ", "paragraphs": ["Forceps gồm 2 cành tách biệt là cành trái và cành phải tùy thuộc nó được đặt vào bên trái hay bên phải khung chậu người mẹ. Hai cành được khớp với nhau bởi một khóa chéo (Simpson). Mỗi cành gồm 3 phần cán, thân và thìa. Phần thìa có 1 cửa sổ. Mỗi forceps có 2 độ cong chính: độ cong đầu và độ cong chậu tương ứng với độ cong của đầu thai nhi và độ cong của khung chậu. Nhờ có 2 độ cong này ta có thể hướng được forceps khi sử dụng."], "bullets": []}, {"heading": "1. Tác dụng cặp: Cặp tốt và lý tưởng nhất là khi forceps vừa cặp chặt ngôi thai vừa bảo vệ được ngôi thai mà không nguy hiểm cho thai và người mẹ. Tùy theo các ngôi mà ta có cách cặp khác nhau:", "paragraphs": ["a. Ngôi chỏm: có hai cách cặp", "b. Cặp trong ngôi mặt: cặp đối xứng theo đường kính căm chẩm, đầ thìa ở chẩm, gốc thìa ở cằm.", "c. Cặp ngôi mông ở thì đầu hậu: cũng theo kiểu cằm chẩm (rất ít sử dụng)"], "bullets": ["- Cặp đối xứng là cách cặp lý tưởng nhất là hai thìa ôm hai bướu đỉnh, hướng theo đường kính chẩm cằm, một bờ thìa ở trước vành tai, 1 bờ thìa ở đuôi mắt. Cửa sổ thìa tương ứng với xương đỉnh và xương gò má, gốc của thìa ở chẩm, còn đầu của thìa ở cằm.", "- Cặp không đối xứng: Một thìa ở xương trán, một thìa ở trên xương chũm ta gọi là kiểu chán chũm. Nhưng kiểu nay nguy hiểm cho thai vì dễ tổn thương mắt, thường cặp cho kiểu CCTN hoặc CCFN"]}, {"heading": "2. Kéo:", "paragraphs": ["Kéo tốt nhất là phải kéo theo cơ chế đẻ nghĩa là phải đúng theo cơ chế xuống và sổ của thai. Như vậy sẽ ít nguy hiểm cho mẹ và thai. Hiện nay người ta chỉ dùng forceps trong ngôi chỏm đã lọt thấp hoặc tối thiểu đầu đã lọt trung bình. Kỹ thuật kéo phải đều tay, từ từ, đúng theo trục xuống và sổ. Phải kéo bằng sức của cẳng tay tuyệt đối không được kéo bằng sức của cả thân người."], "bullets": []}, {"heading": "3. Tác dụng khác của forceps:", "paragraphs": [], "bullets": ["- Quay: trong 3 tác động thì tác động quay người ta đòi hỏi forceps nhiều nhất. Đối với ngôi chỏm có hai kiểu sổ chẩm vệ và chẩm cùng, nhưng sổ chẩm vệ tốt hơn nên người ta thường quay về chẩm vệ. Với ngôi mặt chỉ có một kiểu sổ là cằm vệ nên chỉ được quay về cằm vệ như vậy sẽ phải quay 450 hoặc 1350.", "- Cúi hay ngửa: trong ngôi chỏm và ngôi mặt thường gặp kểu thế sau nên cúi hoặc ngửa không tốt, do đó dù có lọt cũng thì xuống quay sổ cũng khó. Muốn thực hiện được thì khi đặt forceps thìa phải bám chặt vào đầu thai nhi để khi ta hạ cán thì xuống thì đầu cúi hoặc ngửa theo.", "- Nghiêng: chỉ đến khi sổ, hai bướu đỉnh đã đến gần âm hộ thì động tác làm nghiêng sẽ giúp cho từng bướu đỉnh một lần lượt sổ ra."]}, {"heading": "IV. Điều kiện", "paragraphs": ["Thai sống", "Đầu đã lọt trung bình hoặc thấp trong tiểu khung.", "Phải là ngôi đẻ được đường dưới: ngôi thai phải là ngôi chỏm, ngôi mặt cằm trước hoặc đầu hậu trong ngôi mông.", "Không có bất tương xứng giữa thai và khung chậu", "CTC mở hết.", "Ối vỡ hoặc bấm ối trước khi làm thủ thuật.", "Bàng quang và trực tràng phải rỗng"], "bullets": []}, {"heading": "V. Chỉ định", "paragraphs": ["Chỉ định về phía mẹ", "Mẹ không còn sức rặn hoặc rặn không hiệu quả.", "Dọa vỡ tử cung, ngôi đã lọt chú ý nếu nghi ngờ vỡ tử cung phải mổ lấy thai không được làm forceps.", "Mẹ có sẹo mổ lấy thai cũ.", "Sản giật và tiền sản giât.", "Các bệnh nội khoa: Basedow, đái tháo đường", "Các trường hợp không được rặn: mẹ mắc bệnh nội khoa (Bệnh tim mạch, bệnh phổi...).", "Chỉ định về phía con", "Thai suy", "Ngôi thai cúi không tốt hoặc ngửa không tốt.", "Ngôi ngừng quay ở kiểu thế ngang hoặc kiểu thế sau."], "bullets": []}, {"heading": "VI. Kỹ thuật đặt forceps", "paragraphs": ["Xác định ngôi, thế, kiểu thế, độ lọt và điều kiện làm forceps."], "bullets": []}, {"heading": "1. Chuẩn bị", "paragraphs": ["a. Chuẩn bị sản phụ trước khi làm thủ thuật", "b. Người làm thủ thuât", "Mặc áo, đội mũ, đeo găng vô khuẩn", "Xác định ngôi, thế, kiểu thế, độ lọt và các điều kiện của forceps", "Chọn dụng cụ phù hợp độ lọt, kiểu thế và thói quen người làm."], "bullets": ["- Sản phụ nằm tư thế phụ khoa, mông chạm mép bàn.", "- Vệ sinh.", "- Cạo lông mu.", "- Sát khuẩn âm hộ, âm đạo, trải săng vô khuẩn như trong phẫu thuật.", "- Thông đái.", "- Giảm đau cho sản phụ", "- Báo cáo bác sỹ gây mê nếu thấy cần thiết phải gây mê.", "- Báo cáo bác sỹ sơ sinh nếu như có suy thai, thai non tháng.", "- Rửa tay, sát khuẩn như trong phẫu thuật."]}, {"heading": "2. Kỹ thuật đặt forceps", "paragraphs": ["Khi đặt forceps cần phải bình tĩnh, không hấp tấp vội vàng, thai nhi chịu đựng tình trạng thiếu oxy tốt hơn là tình trạng chấn thương.", "Thì 1:", "Kiểm tra lại lần cuối cùng ngôi thế, tìm các thóp, các rãnh khớp", "Xác định lại lần nữa các điều kiện đặt, nếu đủ điều kiện mới được đặt.", "Thì 2: Đặt hai cành forceps.", "Cành đặt trước là cành dưới. Thường đó là cành trái, cho cả bàn tay hay 4 ngón tay vào âm đạo để tìm các mốc và tai thai nhi và hướng cho thìa forcep vào, lý tưởng nhất là đặt theo hướng chẩm cằm, qua bướu đỉnh xuống má và cằm, chú ý không đặt vào cổ tử cung và âm đạo, sau khi đặt giao cho người phụ giữ để cành forcep không thay đổi vị trí.", "Đặt tiếp cành thứ hai, dùng 2 hoặc 4 ngón tay hướng cành thứ hai vào vị trí đối xứng để khớp với cành thứ nhất. Nếu cành thứ hai không khớp được với cành thứ nhất cần phải rút cành ra đặt lại không nên cố khớp cành vì như vậy có thể làm sang chấn cho thai nhi. Tuyệt đối không thay đổi vị trí cành thứ nhất.", "Đối với các ngôi lọt theo đường kính chéo trái ta đặt cành trái trước, đối với các ngôi lọt theo đường kính chéo phải ta đặt cành phải trước.", "Thì 3: Kiểm tra", "Kiểm tra lại cách đặt đã đạt các yêu cầu: đặt đúng kiểu đã dự định qua các điểm mốc, không đặt vào các phần mềm, các cành không kênh.", "Thì 4: Khớp cành", "Khớp hai cành với nhau.", "Kéo từ từ theo cơ chế đẻ (theo trục của ống đẻ) bằng sức của cẳng tay, tốt nhất trong cơn co phối hợp với sức rặn của người mẹ, trừ trường hợp có chống chỉ định rặn.", "Cắt tầng sinh môn giữa hai cành forceps, mũi kéo nằm ngang hướng về phía ụ ngồi.", "Thì 5: Tháo cành forceps.", "Khi đường kính lớn nhất của đầu thai nhi (lưỡng đỉnh) qua âm hộ thì ngừng kéo để tháo cành. Cành đặt sau lấy ra trước, cành đặt trước lấy ra sau. Vuốt cành theo chiều cong của đầu vừa để không gây sang chấn vừa để lách từng bướu đỉnh một sa đó cho thai nhi sổ đầu.", "Đỡ thai nhi như đỡ đẻ thường.", "Đỡ rau như thường lệ bằng phương pháp xử trí tích cực giai đoạn 3 của chuyển dạ.", "Kiểm tra kỹ tổn thương cổ tử cung âm đạo và tầng sinh môn.", "Khâu tầng sinh môn và các vết rách."], "bullets": []}, {"heading": "1. Tổn thương cho mẹ", "paragraphs": ["Hậu quả dẫn đến tử vong mẹ nếu không giải quyết tốt."], "bullets": ["- Chấn thương:", "+ Rách tầng sinh môn, rách âm hộ, rách âm đạo, túi cùng nhất là các kiểu thế khó như chẩm cùng", "+ Rách cổ tử cung", "+ Vỡ tử cung", "+ Rò bàng quang âm đạo, trực tràng âm đạo", "+ Giãn khớp mu", "- Chảy máu", "- Sốc."]}, {"heading": "2. Tổn thương cho thai", "paragraphs": ["Điều trị dẫn lưu.", "Tụ máu trong não", "Liệt mặt ngoại biên : liệt dây thần kinh VII", "Tổn thương tủy"], "bullets": ["- Tụ máu vùng đầu: tụ máu dưới màng xương. Khối máu tụ sẽ tự tiêu đi trong vài tuần.", "- Tổn thương mắt: chảy máu kết mạc, trầy xước mi mắt, lồi mắt...", "- Vỡ xương sọ:", "+ Vỡ xương sọ cành tươi có lún xương bắt buộc phải làm scanner tìm máu tụ dưới màng cứng hoặc giập não tại chỗ. Mặc dù các vết lún xương nhỏ có thể khỏi tự nhiên nhưng ngày nay có thể khỏi trong tuần lễ đầu.", "- Chảy máu trong sọ:", "+ Tụ máu vùng hố sau: xuất hiện sau giai đoạn tiềm tàng 12 giờ, có thể sau 5 đến 8 ngày : Dựa vào các dấu hiệu khóc yếu, trương lực cơ giảm hoặc tăng trương lực cơ, rung giật nhãn cầu, co giật, liệt thần kinh sọ, thopx phồng, tăng chu vi đầu, nhịp thở không đều, ngừng thở, nhịp tim chậm trụy mạch.", "+ Tụ máu ngoài màng cứng: do tổn thương động mạch màng não giữa hoặc xoang tĩnh mạch lớn do vỡ xương thái dương. Triệu chứng tăng trương lực cơ, thóp phồng, siêu âm qua thóp hoặc scanner giúp cho chẩn đoán. Điều trị bằng phẫu thuật.", "+ Tụ máu dưới màng cứng: tụ máu dưới màng cứng vùng thái dương không có triệu chứng hoặc biểu hiện bằng co giật kèm theo dấu hiệu thần kinh khu trú. Tụ máu vùng nền não, chèn ép thân não biểu hiện co giật, đồng tử không đều, hôn mê… Chẩn đoán bằng siêu âm, chụp scanner."]}, {"heading": "Câu hỏi:", "paragraphs": ["Anh (Chị) nêu chỉ định của Forceps", "Anh (Chị) trỡnh bày điờ̀u kiợ̀n đờ̉ đặt Forceps", "Anh (Chị) trỡnh bày tỏc dụng và kỹ thuật đặt forceps", "Anh (Chị) trỡnh bày các tai biờ́n của Forceps."], "bullets": []}], "raw_text": "FORCEPS SẢN KHOA\nBsCK II. Nguyễn Thị Tuyết\nMục tiêu học tập\nNói được chỉ định của Forceps\nNêu được điều kiện để đặt Forceps\nTrình bày được tác dụng và kỹ thuật đặt forceps\nNắm được các tai biến của Forceps.\nI. Đại cương\nForceps là một dụng cụ sản khoa để giữ chắc lấy đầu thai nhi để kéo cho ngôi thai sổ ra ngoài theo cơ chế gần giống như tự nhiên, đúng như cơ chế của cuộc chuyển dạ đẻ: quay trước hay quay sau, cúi hay ngửa, xuống hay sổ, giúp cho cuộc chuyển dạ nhanh chóng kết thúc bảo vệ quyền lợi của mẹ và thai nhi.\nForceps ra đời vào giữa thế kỷ XVII đến nay đã cứu sống nhiều em bé nhưng cũng đã xảy ra những tai biến cho mẹ và con. Ngày nay, cùng với sự phát triển của gây mê hồi sức và sự phát sinh ra kháng sinh, phẫu thuật mổ lấy thai mở rộng và có giác hút thì phạm vi sử dụng forceps ngày càng thu hẹp với những chỉ định nhất định.\nII. Mô tả dụng cụ\nForceps gồm 2 cành tách biệt là cành trái và cành phải tùy thuộc nó được đặt vào bên trái hay bên phải khung chậu người mẹ. Hai cành được khớp với nhau bởi một khóa chéo (Simpson). Mỗi cành gồm 3 phần cán, thân và thìa. Phần thìa có 1 cửa sổ. Mỗi forceps có 2 độ cong chính: độ cong đầu và độ cong chậu tương ứng với độ cong của đầu thai nhi và độ cong của khung chậu. Nhờ có 2 độ cong này ta có thể hướng được forceps khi sử dụng.\nIII. Tác dụng của forceps\n1. Tác dụng cặp: Cặp tốt và lý tưởng nhất là khi forceps vừa cặp chặt ngôi thai vừa bảo vệ được ngôi thai mà không nguy hiểm cho thai và người mẹ. Tùy theo các ngôi mà ta có cách cặp khác nhau:\na. Ngôi chỏm: có hai cách cặp\n- Cặp đối xứng là cách cặp lý tưởng nhất là hai thìa ôm hai bướu đỉnh, hướng theo đường kính chẩm cằm, một bờ thìa ở trước vành tai, 1 bờ thìa ở đuôi mắt. Cửa sổ thìa tương ứng với xương đỉnh và xương gò má, gốc của thìa ở chẩm, còn đầu của thìa ở cằm.\n- Cặp không đối xứng: Một thìa ở xương trán, một thìa ở trên xương chũm ta gọi là kiểu chán chũm. Nhưng kiểu nay nguy hiểm cho thai vì dễ tổn thương mắt, thường cặp cho kiểu CCTN hoặc CCFN\nb. Cặp trong ngôi mặt: cặp đối xứng theo đường kính căm chẩm, đầ thìa ở chẩm, gốc thìa ở cằm.\nc. Cặp ngôi mông ở thì đầu hậu: cũng theo kiểu cằm chẩm (rất ít sử dụng)\n2. Kéo:\nKéo tốt nhất là phải kéo theo cơ chế đẻ nghĩa là phải đúng theo cơ chế xuống và sổ của thai. Như vậy sẽ ít nguy hiểm cho mẹ và thai. Hiện nay người ta chỉ dùng forceps trong ngôi chỏm đã lọt thấp hoặc tối thiểu đầu đã lọt trung bình. Kỹ thuật kéo phải đều tay, từ từ, đúng theo trục xuống và sổ. Phải kéo bằng sức của cẳng tay tuyệt đối không được kéo bằng sức của cả thân người.\n3. Tác dụng khác của forceps:\n- Quay: trong 3 tác động thì tác động quay người ta đòi hỏi forceps nhiều nhất. Đối với ngôi chỏm có hai kiểu sổ chẩm vệ và chẩm cùng, nhưng sổ chẩm vệ tốt hơn nên người ta thường quay về chẩm vệ. Với ngôi mặt chỉ có một kiểu sổ là cằm vệ nên chỉ được quay về cằm vệ như vậy sẽ phải quay 450 hoặc 1350.\n- Cúi hay ngửa: trong ngôi chỏm và ngôi mặt thường gặp kểu thế sau nên cúi hoặc ngửa không tốt, do đó dù có lọt cũng thì xuống quay sổ cũng khó. Muốn thực hiện được thì khi đặt forceps thìa phải bám chặt vào đầu thai nhi để khi ta hạ cán thì xuống thì đầu cúi hoặc ngửa theo.\n- Nghiêng: chỉ đến khi sổ, hai bướu đỉnh đã đến gần âm hộ thì động tác làm nghiêng sẽ giúp cho từng bướu đỉnh một lần lượt sổ ra.\nIV. Điều kiện\nThai sống\nĐầu đã lọt trung bình hoặc thấp trong tiểu khung.\nPhải là ngôi đẻ được đường dưới: ngôi thai phải là ngôi chỏm, ngôi mặt cằm trước hoặc đầu hậu trong ngôi mông.\nKhông có bất tương xứng giữa thai và khung chậu\nCTC mở hết.\nỐi vỡ hoặc bấm ối trước khi làm thủ thuật.\nBàng quang và trực tràng phải rỗng\nV. Chỉ định\nChỉ định về phía mẹ\nMẹ không còn sức rặn hoặc rặn không hiệu quả.\nDọa vỡ tử cung, ngôi đã lọt chú ý nếu nghi ngờ vỡ tử cung phải mổ lấy thai không được làm forceps.\nMẹ có sẹo mổ lấy thai cũ.\nSản giật và tiền sản giât.\nCác bệnh nội khoa: Basedow, đái tháo đường\nCác trường hợp không được rặn: mẹ mắc bệnh nội khoa (Bệnh tim mạch, bệnh phổi...).\nChỉ định về phía con\nThai suy\nNgôi thai cúi không tốt hoặc ngửa không tốt.\nNgôi ngừng quay ở kiểu thế ngang hoặc kiểu thế sau.\nVI. Kỹ thuật đặt forceps\nXác định ngôi, thế, kiểu thế, độ lọt và điều kiện làm forceps.\n1. Chuẩn bị\na. Chuẩn bị sản phụ trước khi làm thủ thuật\n- Sản phụ nằm tư thế phụ khoa, mông chạm mép bàn.\n- Vệ sinh.\n- Cạo lông mu.\n- Sát khuẩn âm hộ, âm đạo, trải săng vô khuẩn như trong phẫu thuật.\n- Thông đái.\n- Giảm đau cho sản phụ\nb. Người làm thủ thuât\n- Báo cáo bác sỹ gây mê nếu thấy cần thiết phải gây mê.\n- Báo cáo bác sỹ sơ sinh nếu như có suy thai, thai non tháng.\n- Rửa tay, sát khuẩn như trong phẫu thuật.\nMặc áo, đội mũ, đeo găng vô khuẩn\nXác định ngôi, thế, kiểu thế, độ lọt và các điều kiện của forceps\nChọn dụng cụ phù hợp độ lọt, kiểu thế và thói quen người làm.\n2. Kỹ thuật đặt forceps\nKhi đặt forceps cần phải bình tĩnh, không hấp tấp vội vàng, thai nhi chịu đựng tình trạng thiếu oxy tốt hơn là tình trạng chấn thương.\nThì 1:\nKiểm tra lại lần cuối cùng ngôi thế, tìm các thóp, các rãnh khớp\nXác định lại lần nữa các điều kiện đặt, nếu đủ điều kiện mới được đặt.\nThì 2: Đặt hai cành forceps.\nCành đặt trước là cành dưới. Thường đó là cành trái, cho cả bàn tay hay 4 ngón tay vào âm đạo để tìm các mốc và tai thai nhi và hướng cho thìa forcep vào, lý tưởng nhất là đặt theo hướng chẩm cằm, qua bướu đỉnh xuống má và cằm, chú ý không đặt vào cổ tử cung và âm đạo, sau khi đặt giao cho người phụ giữ để cành forcep không thay đổi vị trí.\nĐặt tiếp cành thứ hai, dùng 2 hoặc 4 ngón tay hướng cành thứ hai vào vị trí đối xứng để khớp với cành thứ nhất. Nếu cành thứ hai không khớp được với cành thứ nhất cần phải rút cành ra đặt lại không nên cố khớp cành vì như vậy có thể làm sang chấn cho thai nhi. Tuyệt đối không thay đổi vị trí cành thứ nhất.\nĐối với các ngôi lọt theo đường kính chéo trái ta đặt cành trái trước, đối với các ngôi lọt theo đường kính chéo phải ta đặt cành phải trước.\nThì 3: Kiểm tra\nKiểm tra lại cách đặt đã đạt các yêu cầu: đặt đúng kiểu đã dự định qua các điểm mốc, không đặt vào các phần mềm, các cành không kênh.\nThì 4: Khớp cành\nKhớp hai cành với nhau.\nKéo từ từ theo cơ chế đẻ (theo trục của ống đẻ) bằng sức của cẳng tay, tốt nhất trong cơn co phối hợp với sức rặn của người mẹ, trừ trường hợp có chống chỉ định rặn.\nCắt tầng sinh môn giữa hai cành forceps, mũi kéo nằm ngang hướng về phía ụ ngồi.\nThì 5: Tháo cành forceps.\nKhi đường kính lớn nhất của đầu thai nhi (lưỡng đỉnh) qua âm hộ thì ngừng kéo để tháo cành. Cành đặt sau lấy ra trước, cành đặt trước lấy ra sau. Vuốt cành theo chiều cong của đầu vừa để không gây sang chấn vừa để lách từng bướu đỉnh một sa đó cho thai nhi sổ đầu.\nĐỡ thai nhi như đỡ đẻ thường.\nĐỡ rau như thường lệ bằng phương pháp xử trí tích cực giai đoạn 3 của chuyển dạ.\nKiểm tra kỹ tổn thương cổ tử cung âm đạo và tầng sinh môn.\nKhâu tầng sinh môn và các vết rách.\nVII. Tai biến\n1. Tổn thương cho mẹ\n- Chấn thương:\n+ Rách tầng sinh môn, rách âm hộ, rách âm đạo, túi cùng nhất là các kiểu thế khó như chẩm cùng\n+ Rách cổ tử cung\n+ Vỡ tử cung\n+ Rò bàng quang âm đạo, trực tràng âm đạo\n+ Giãn khớp mu\n- Chảy máu\n- Sốc.\nHậu quả dẫn đến tử vong mẹ nếu không giải quyết tốt.\n2. Tổn thương cho thai\n- Tụ máu vùng đầu: tụ máu dưới màng xương. Khối máu tụ sẽ tự tiêu đi trong vài tuần.\n- Tổn thương mắt: chảy máu kết mạc, trầy xước mi mắt, lồi mắt...\n- Vỡ xương sọ:\n+ Vỡ xương sọ cành tươi có lún xương bắt buộc phải làm scanner tìm máu tụ dưới màng cứng hoặc giập não tại chỗ. Mặc dù các vết lún xương nhỏ có thể khỏi tự nhiên nhưng ngày nay có thể khỏi trong tuần lễ đầu.\n- Chảy máu trong sọ:\n+ Tụ máu vùng hố sau: xuất hiện sau giai đoạn tiềm tàng 12 giờ, có thể sau 5 đến 8 ngày : Dựa vào các dấu hiệu khóc yếu, trương lực cơ giảm hoặc tăng trương lực cơ, rung giật nhãn cầu, co giật, liệt thần kinh sọ, thopx phồng, tăng chu vi đầu, nhịp thở không đều, ngừng thở, nhịp tim chậm trụy mạch.\n+ Tụ máu ngoài màng cứng: do tổn thương động mạch màng não giữa hoặc xoang tĩnh mạch lớn do vỡ xương thái dương. Triệu chứng tăng trương lực cơ, thóp phồng, siêu âm qua thóp hoặc scanner giúp cho chẩn đoán. Điều trị bằng phẫu thuật.\n+ Tụ máu dưới màng cứng: tụ máu dưới màng cứng vùng thái dương không có triệu chứng hoặc biểu hiện bằng co giật kèm theo dấu hiệu thần kinh khu trú. Tụ máu vùng nền não, chèn ép thân não biểu hiện co giật, đồng tử không đều, hôn mê… Chẩn đoán bằng siêu âm, chụp scanner.\nĐiều trị dẫn lưu.\nTụ máu trong não\nLiệt mặt ngoại biên : liệt dây thần kinh VII\nTổn thương tủy\nCâu hỏi:\nAnh (Chị) nêu chỉ định của Forceps\nAnh (Chị) trỡnh bày điờ̀u kiợ̀n đờ̉ đặt Forceps\nAnh (Chị) trỡnh bày tỏc dụng và kỹ thuật đặt forceps\nAnh (Chị) trỡnh bày các tai biờ́n của Forceps.", "priority": "Cao (Trọng tâm BSNT)"}, {"id": "SK-27", "chapter": "Chương 2. Sản bệnh", "folder": "02_San_benh", "title": "Giác hút sản khoa", "author": "Bs CK II. Nguyễn Thị Tuyết", "word_count": 1412, "line_count": 105, "key_numbers": ["0,2 kg", "0,8 kg", "10 phút", "1000ml", "15mm", "2 phút", "5 ngày", "5 phút", "60 mm", "60cm"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["GIÁC HÚT SẢN KHOA", "Bs CK II. Nguyễn Thị Tuyết"], "bullets": []}, {"heading": "Mục tiêu học tập", "paragraphs": ["Nêu được chỉ định và chống chỉ định của giác hút", "Nêu được điều kiện để đặt giác hút", "Nói được kỹ thuật đặt giác hút", "Trình bày được các tai biến của giác hút."], "bullets": []}, {"heading": "I. Đại cương", "paragraphs": ["Giác hút sản khoa là một thủ thuật dùng bầu giác tạo ra bởi áp lực âm bám chắc vào đầu thai nhi, để hỗ trợ cho sản phụ rặn, cho thai sổ ra theo cơ chế đẻ."], "bullets": []}, {"heading": "II. Mô tả dụng cụ", "paragraphs": ["Giác hút bơm điện hay bơm tay đều là một hệ thống hút kín gồm 2 phần:"], "bullets": []}, {"heading": "1. Bộ phận tạo áp lực chân không:", "paragraphs": ["Bơm ngược chiều để hút khí ra. Bơm tay thì giống bơm xe đạp, bơm điện thì dùng động cơ để hút khí ra.", "Bình thủy tinh có thể tích từ 650 đến 1000ml", "Nút lọ bằng cao su có thể điều chỉnh không khí vào hay ra theo ý muốn", "Áp kế âm nối với bình thủy tinh qua nút cao su.", "Vít áp lực để giữ áp lực âm"], "bullets": []}, {"heading": "2. Bộ phận kéo", "paragraphs": [], "bullets": ["- Dây cao su nối liền bình không khí với dây xích", "- Các loại nắp kim loại để chụp ngôi thai: số 4, 5 với các đường kính tương ứng 40,50 và 60 mm. Bề sâu của nắp là 15mm", "- Dây xích dài 50-60cm, một đầu có gắn mảnh kim loại tròn áp chặt vào đáy nắp, một đầu gắn với tay cầm. Dây xích được luồn trong một dây cao su.", "- Tay cầm hình chữ thập rỗng ở trong, trong đó có luồn một cái đinh để xuyên qua một mắt của dây xích để giúp giữ chắc khi kéo. Tay cầm được nối liền với bình thủy tinh bởi dây cao su."]}, {"heading": "III. Tác dụng của giác hút", "paragraphs": ["Hiện nay tác dụng duy nhất của giác hút sản khoa là kéo. Nhờ có áp xuất âm nắp kim loại sẽ bám chặt đầu thai nhi tạo ra một bướu huyết thanh trên nền xương sọ cứng do vây có thể kéo được thai nhi ra ngoài trong những trường hợp sản phụ rặn không sổ. Ta có thể tính được lực bám dính theo công thức sau đây:", "F=P.π. R2", "Với F là trị số của lực bám dính tính bằng kgF", "P là trị số áp suật chân không trong hệ thống tính bằng kg/cm2.", "π= 3,1416", "R là bán kính của nắp giác hút tính bằng chứng minh", "Lực bám dính này có trị số bằng trị số của lực kéo tối đa cho phép trên lý thuyết cùng phương nhưng ngược chiều. Khi lực kéo vượt qua trị số này sẽ làm bật nắp giác hút.", "Cần chú ý là khi kéo phải kéo theo phương thẳng góc với nắp giác hút. Nếu phương này bị nghiêng đi một góc alpha thì khả năng bật nắp giác hút tỷ lệ thuận với độ lớn của góc này."], "bullets": []}, {"heading": "III. Điều kiện", "paragraphs": ["Phải hết sức tôn trọng và nắm vững điều kiện của giác hút. Đó là vấn đề then chốt cho sự thành công và ít dẫn đến sang chấn cho thai nhi: khung chậu và thai nhi phải tương xứng, nghĩa là thai có thể lọt và sổ được.", "CTC mở hết.", "Mẹ còn sức rặn", "Thai còn sống", "Ngôi chỏm", "Đầu đã lọt trung bình hoặc lọt thấp trong tiểu khung.", "Ối vỡ hoặc bấm ối trước khi làm thủ thuật.", "Cơn co tử cung phải tốt."], "bullets": []}, {"heading": "1. Chỉ định về phía mẹ", "paragraphs": ["Mẹ răn lâu không chuyển (Con so > 45’, con rạ > 30’)", "Mẹ rặn yếu do chuyển dạ kéo dài", "Tầng sinh môn rắn làm cho thai nhi không sổ được.", "Mẹ mắc các bệnh nội khoa ở mức độ nhẹ: hô hấp, tim mạch, tiền sản giật."], "bullets": []}, {"heading": "2. Chỉ định về phía thai", "paragraphs": ["Thai suy, tim thai nhanh trên 160 lần/phút.", "Các kiểu thế sau, ngang không quay tốt. Vì giác hút ưu điểm hơn forceps là không làm tăng đường kính sổ."], "bullets": []}, {"heading": "3. Chống chỉ định", "paragraphs": ["Những trường hợp không được rặn (THA, suy tim, tiền sản giật, sản giật)", "Dọa vỡ tử cung", "Sẹo mổ cũ ở TC", "Khung chậu bất thường, khung chậu hẹp eo giữa, eo dưới.", "Cổ tử cung chưa mở hết.", "Thai non tháng, thai suy dinh dưỡng, thai kém phát triển trong buồng tử cung.", "Suy thai cấp", "Các ngôi bất thường.", "Ngôi thai chưa lọt", "Thai dị dạng, đặc biệt là nào úng thủy", "Bướu huyết thanh lớn"], "bullets": ["- Về phía mẹ:", "-Về phía thai"]}, {"heading": "1. Chuẩn bị", "paragraphs": ["Người làm thủ thuật rửa tay, mặc áo, đội mũ, đeo găng vô khuẩn.", "Chuẩn bị tư tưởng cho thai phụ phối hợp rặn khi kéo thai nhi.", "Hồi sức thai nhi nếu cần", "Sát khuẩn vùng âm hộ, tầng sinh môn.", "Thông đái.", "Dụng cụ: Kiểm tra lại các bộ phận của giác hút và dụng cụ cần thiết để đón thai.", "Thầy thuốc và người phụ:", "Thăm khám lại thai phụ, kiểm tra lại ngôi, thế,kiểu thế và độ lọt của ngôi và các điều kiện.", "Rửa tay, sát khuẩn như trong phẫu thuật.", "Mặc áo, đội mũ, đeo găng vô khuẩn"], "bullets": []}, {"heading": "2. Kỹ thuật", "paragraphs": ["Thì 1: Đặt nắp", "Chọn nắp giác kéo cho thích hợp nên đặt nắp với kích cỡ to nhất có thể được. Thường dùng chụp số 5 - 6.", "Ngón cái và ngón trỏ tay trái banh rộng môi lớn âm hộ, tay phải cầm nghiêng nắp lách vào âm đạo, đặt trên nền xương của ngôi thai. Đặt chụp vào vùng chẩm không trùm lên các thóp và đường khớp.", "Thì 2: Bơm và kéo", "Tạo áp lực âm bằng cách bơm từ từ tới áp lực -0,2 kg/cm2, kiểm tra lại chụp giác kéo tại nơi bám xem có chụp vào cổ tử cung hay không.", "Nếu hút phải phần mềm hoặc chụp bị kênh thì tháo hơi và đặt lại.", "Tăng dần áp lực hút đến -0,7 hoặc - 0,8 kg/cm2 trong thời gian 3-5 phút thì bắt đầu kéo khi có cơn co tử cung và phối hợp với sức rặn của sản phụ. Dây kéo luôn luôn thẳng góc với diện chụp, kéo bằng sức của cẳng tay. Kéo theo truch của ống đẻ.Cắt tầng sinh môn nếu cần.", "Thì 3:", "Khi hạ chẩm tì vào khớp vệ thì kéo lên cho đầu sổ. Khi hai bướu đỉnh của thai lách đến âm hộ thì sau đó mở vít áp lực để không khí vào trong bình thủy tinh làm tháo hơi từ từ, sau đó tháo bỏ từ từ nắp chụp ra ngoài, cho sản phụ rặn tiếp một hơi, đầu thai nhi sẽ sổ ra âm hộ, đỡ đẻ như bình thường.", "Chú ý.", "Thời gian bơm hút hơi cũng như lúc xả hơi phải kéo dài 1 - 2 phút.", "Theo dõi tiến triển của ngôi sau mỗi cơn co. Tầng sinh môn phải giãn sau lần kéo thứ 2.", "Không được kéo lâu quá 10 phút hoặc quá 4 cơn co.", "Nếu trong lúc đang kéo, giác kéo bị trượt, chỉ đặt lại chụp một lần nữa và không quá 1 lần."], "bullets": []}, {"heading": "1. Tổn thương cho mẹ: ít hơn forceps", "paragraphs": [], "bullets": ["+ Rách âm đạo và rách tầng sinh môn", "+ Vỡ tử cung, rách cổ tử cung hiếm gặp", "+ Bí đái: do tổn thương vùng cổ BQ."]}, {"heading": "2. Tổn thương cho thai: không nặng nề như forceps", "paragraphs": ["Tỷ lệ tai biến của con tăng lên rõ rệt trong các trường hợp bật nắp giác hút, áp lực âm quá lớn, hay thời gian thực hiện thủ thuật kéo dài."], "bullets": ["- Trầy da đầu và khối tụ máu vùng đầu: tụ máu dưới màng xương. Khối máu tụ sẽ tự tiêu đi trong 3-5 ngày.", "- Xuất huyết dưới màng xương hiếm gặp hơn.", "- Xuất huyết não, màng não có thể gặp và tần số gặp khác nhau tùy theo nghiên cứu của từng tác giả."]}, {"heading": "Câu hỏi:", "paragraphs": ["Anh (Chị) nêu chỉ định và chống chỉ định của giác hút?", "Anh (Chị) nêu điều kiện để đặt giác hút?", "Anh (Chị) trình bày kỹ thuật đặt giác hút?", "Anh (Chị) trình bày các tai biến của giác hút?"], "bullets": []}], "raw_text": "GIÁC HÚT SẢN KHOA\nBs CK II. Nguyễn Thị Tuyết\nMục tiêu học tập\nNêu được chỉ định và chống chỉ định của giác hút\nNêu được điều kiện để đặt giác hút\nNói được kỹ thuật đặt giác hút\nTrình bày được các tai biến của giác hút.\nI. Đại cương\nGiác hút sản khoa là một thủ thuật dùng bầu giác tạo ra bởi áp lực âm bám chắc vào đầu thai nhi, để hỗ trợ cho sản phụ rặn, cho thai sổ ra theo cơ chế đẻ.\nII. Mô tả dụng cụ\nGiác hút bơm điện hay bơm tay đều là một hệ thống hút kín gồm 2 phần:\n1. Bộ phận tạo áp lực chân không:\nBơm ngược chiều để hút khí ra. Bơm tay thì giống bơm xe đạp, bơm điện thì dùng động cơ để hút khí ra.\nBình thủy tinh có thể tích từ 650 đến 1000ml\nNút lọ bằng cao su có thể điều chỉnh không khí vào hay ra theo ý muốn\nÁp kế âm nối với bình thủy tinh qua nút cao su.\nVít áp lực để giữ áp lực âm\n2. Bộ phận kéo\n- Dây cao su nối liền bình không khí với dây xích\n- Các loại nắp kim loại để chụp ngôi thai: số 4, 5 với các đường kính tương ứng 40,50 và 60 mm. Bề sâu của nắp là 15mm\n- Dây xích dài 50-60cm, một đầu có gắn mảnh kim loại tròn áp chặt vào đáy nắp, một đầu gắn với tay cầm. Dây xích được luồn trong một dây cao su.\n- Tay cầm hình chữ thập rỗng ở trong, trong đó có luồn một cái đinh để xuyên qua một mắt của dây xích để giúp giữ chắc khi kéo. Tay cầm được nối liền với bình thủy tinh bởi dây cao su.\nIII. Tác dụng của giác hút\nHiện nay tác dụng duy nhất của giác hút sản khoa là kéo. Nhờ có áp xuất âm nắp kim loại sẽ bám chặt đầu thai nhi tạo ra một bướu huyết thanh trên nền xương sọ cứng do vây có thể kéo được thai nhi ra ngoài trong những trường hợp sản phụ rặn không sổ. Ta có thể tính được lực bám dính theo công thức sau đây:\nF=P.π. R2\nVới F là trị số của lực bám dính tính bằng kgF\nP là trị số áp suật chân không trong hệ thống tính bằng kg/cm2.\nπ= 3,1416\nR là bán kính của nắp giác hút tính bằng chứng minh\nLực bám dính này có trị số bằng trị số của lực kéo tối đa cho phép trên lý thuyết cùng phương nhưng ngược chiều. Khi lực kéo vượt qua trị số này sẽ làm bật nắp giác hút.\nCần chú ý là khi kéo phải kéo theo phương thẳng góc với nắp giác hút. Nếu phương này bị nghiêng đi một góc alpha thì khả năng bật nắp giác hút tỷ lệ thuận với độ lớn của góc này.\nIII. Điều kiện\nPhải hết sức tôn trọng và nắm vững điều kiện của giác hút. Đó là vấn đề then chốt cho sự thành công và ít dẫn đến sang chấn cho thai nhi: khung chậu và thai nhi phải tương xứng, nghĩa là thai có thể lọt và sổ được.\nCTC mở hết.\nMẹ còn sức rặn\nThai còn sống\nNgôi chỏm\nĐầu đã lọt trung bình hoặc lọt thấp trong tiểu khung.\nỐi vỡ hoặc bấm ối trước khi làm thủ thuật.\nCơn co tử cung phải tốt.\nIV. Chỉ định\n1. Chỉ định về phía mẹ\nMẹ răn lâu không chuyển (Con so > 45’, con rạ > 30’)\nMẹ rặn yếu do chuyển dạ kéo dài\nTầng sinh môn rắn làm cho thai nhi không sổ được.\nMẹ mắc các bệnh nội khoa ở mức độ nhẹ: hô hấp, tim mạch, tiền sản giật.\n2. Chỉ định về phía thai\nThai suy, tim thai nhanh trên 160 lần/phút.\nCác kiểu thế sau, ngang không quay tốt. Vì giác hút ưu điểm hơn forceps là không làm tăng đường kính sổ.\n3. Chống chỉ định\n- Về phía mẹ:\nNhững trường hợp không được rặn (THA, suy tim, tiền sản giật, sản giật)\nDọa vỡ tử cung\nSẹo mổ cũ ở TC\nKhung chậu bất thường, khung chậu hẹp eo giữa, eo dưới.\nCổ tử cung chưa mở hết.\n-Về phía thai\nThai non tháng, thai suy dinh dưỡng, thai kém phát triển trong buồng tử cung.\nSuy thai cấp\nCác ngôi bất thường.\nNgôi thai chưa lọt\nThai dị dạng, đặc biệt là nào úng thủy\nBướu huyết thanh lớn\nV. Kỹ thuật đặt giác hút\n1. Chuẩn bị\nNgười làm thủ thuật rửa tay, mặc áo, đội mũ, đeo găng vô khuẩn.\nChuẩn bị tư tưởng cho thai phụ phối hợp rặn khi kéo thai nhi.\nHồi sức thai nhi nếu cần\nSát khuẩn vùng âm hộ, tầng sinh môn.\nThông đái.\nDụng cụ: Kiểm tra lại các bộ phận của giác hút và dụng cụ cần thiết để đón thai.\nThầy thuốc và người phụ:\nThăm khám lại thai phụ, kiểm tra lại ngôi, thế,kiểu thế và độ lọt của ngôi và các điều kiện.\nRửa tay, sát khuẩn như trong phẫu thuật.\nMặc áo, đội mũ, đeo găng vô khuẩn\n2. Kỹ thuật\nThì 1: Đặt nắp\nChọn nắp giác kéo cho thích hợp nên đặt nắp với kích cỡ to nhất có thể được. Thường dùng chụp số 5 - 6.\nNgón cái và ngón trỏ tay trái banh rộng môi lớn âm hộ, tay phải cầm nghiêng nắp lách vào âm đạo, đặt trên nền xương của ngôi thai. Đặt chụp vào vùng chẩm không trùm lên các thóp và đường khớp.\nThì 2: Bơm và kéo\nTạo áp lực âm bằng cách bơm từ từ tới áp lực -0,2 kg/cm2, kiểm tra lại chụp giác kéo tại nơi bám xem có chụp vào cổ tử cung hay không.\nNếu hút phải phần mềm hoặc chụp bị kênh thì tháo hơi và đặt lại.\nTăng dần áp lực hút đến -0,7 hoặc - 0,8 kg/cm2 trong thời gian 3-5 phút thì bắt đầu kéo khi có cơn co tử cung và phối hợp với sức rặn của sản phụ. Dây kéo luôn luôn thẳng góc với diện chụp, kéo bằng sức của cẳng tay. Kéo theo truch của ống đẻ.Cắt tầng sinh môn nếu cần.\nThì 3:\nKhi hạ chẩm tì vào khớp vệ thì kéo lên cho đầu sổ. Khi hai bướu đỉnh của thai lách đến âm hộ thì sau đó mở vít áp lực để không khí vào trong bình thủy tinh làm tháo hơi từ từ, sau đó tháo bỏ từ từ nắp chụp ra ngoài, cho sản phụ rặn tiếp một hơi, đầu thai nhi sẽ sổ ra âm hộ, đỡ đẻ như bình thường.\nChú ý.\nThời gian bơm hút hơi cũng như lúc xả hơi phải kéo dài 1 - 2 phút.\nTheo dõi tiến triển của ngôi sau mỗi cơn co. Tầng sinh môn phải giãn sau lần kéo thứ 2.\nKhông được kéo lâu quá 10 phút hoặc quá 4 cơn co.\nNếu trong lúc đang kéo, giác kéo bị trượt, chỉ đặt lại chụp một lần nữa và không quá 1 lần.\nVI. Tai biến\n1. Tổn thương cho mẹ: ít hơn forceps\n+ Rách âm đạo và rách tầng sinh môn\n+ Vỡ tử cung, rách cổ tử cung hiếm gặp\n+ Bí đái: do tổn thương vùng cổ BQ.\n2. Tổn thương cho thai: không nặng nề như forceps\n- Trầy da đầu và khối tụ máu vùng đầu: tụ máu dưới màng xương. Khối máu tụ sẽ tự tiêu đi trong 3-5 ngày.\n- Xuất huyết dưới màng xương hiếm gặp hơn.\n- Xuất huyết não, màng não có thể gặp và tần số gặp khác nhau tùy theo nghiên cứu của từng tác giả.\nTỷ lệ tai biến của con tăng lên rõ rệt trong các trường hợp bật nắp giác hút, áp lực âm quá lớn, hay thời gian thực hiện thủ thuật kéo dài.\nCâu hỏi:\nAnh (Chị) nêu chỉ định và chống chỉ định của giác hút?\nAnh (Chị) nêu điều kiện để đặt giác hút?\nAnh (Chị) trình bày kỹ thuật đặt giác hút?\nAnh (Chị) trình bày các tai biến của giác hút?", "priority": "Cao (Trọng tâm BSNT)"}, {"id": "SK-28", "chapter": "Chương 2. Sản bệnh", "folder": "02_San_benh", "title": "Vỡ tử cung", "author": "Ths. Đinh Văn Hoành", "word_count": 2337, "line_count": 134, "key_numbers": ["3 tháng", "4000g"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["VỠ TỬ CUNG", "Ths. Đinh Văn Hoành"], "bullets": []}, {"heading": "1. ĐẠI CƯƠNG", "paragraphs": ["Vỡ tử cung là một tai biến sản khoa. Nếu không phát hiện và xử trí kịp thời sẽ gây tử vong cho mẹ và thai nhi. Vỡ tử cung trong chuyển dạ thường gặp hơn vỡ tử cung trong thai kỳ.", "Hình 1. Vỡ tử cung"], "bullets": []}, {"heading": "2.1. Nguyên nhân:", "paragraphs": ["Có thể xảy ra trên các thai phụ có sẹo mổ cũ ở tử cung do:"], "bullets": ["- Mổ lấy thai ở thân tử cung.", "- Khâu lại tử cung bị vỡ.", "- Mổ lấy thai từ hai lần trở lên (sẹo mổ ngang đoạn dưới tử cung trước đó, số lần mổ càng nhiều càng làm tăng nguy cơ vỡ tử cung).", "- Mổ cắt góc tử cung trong phẫu thuật điều trị chửa ngoài tử cung đoạn kẽ.", "- Mổ lấy thai bị nhiễm khuẩn tại vết mổ hoặc tử cung.", "- Phẫu thuật bóc nhân xơ tử cung (nếu u xơ tử cung ăn vào nội mạc tử cung).", "- Khâu lỗ thủng tử cung sau nạo phá thai.", "- Tai nạn, sang chấn trực tiếp.", "- Phẫu thuật Strassman tạo hình tử cung."]}, {"heading": "2.2. Triệu chứng", "paragraphs": ["Vỡ tử cung trong thai kỳ có thể xảy ra ở 3 tháng giữa và 3 tháng cuối thai kỳ nhưng không có dấu hiệu dọa vỡ tử cung.", "Trong một số trường hợp bệnh nhân có dấu hiệu choáng, đôi khi choáng nặng: da mặt tái nhợt, nhịp thở nhanh, thở nông, vẻ mặt hốt hoảng, lo lắng, chân tay lạnh toát, vã mồ hôi, mạch nhanh, huyết áp hạ, đôi khi có thể ngừng tim.", "Cần chú ý: Có trường hợp sẹo mổ cũ bị nứt, nên không có dấu hiệu điển hình của chảy máu trong như đã mô tả ở trên."], "bullets": ["- Triệu chứng cơ năng:", "+ Đau xảy ra đột ngột ở vùng giữa tử cung  (thường ở vị trí vết mổ cũ).", "+ Ra máu ở âm đạo.", "- Triệu chứng toàn thân:", "- Triệu chứng thực thể", "+ Ðau bụng: đau có thể lan toả toàn bụng, có khi cảm ứng phúc mạc, phản ứng thành bụng rất rõ.", "+ Tử cung không còn hình dạng ban đầu, có thể sờ thấy các phần thai ngay dưới thành bụng, trường hợp vỡ tử cung không hoàn toàn có thể còn sờ thấy tử cung nhưng có điểm đau chói tại vùng sẹo của tử cung.", "+ Nghe tim thai: Tim thai không còn nghe được.", "+ Gõ bụng: bụng đục toàn bộ.", "+ Khám âm đạo: ngôi thai không sờ thấy, có máu chảy ra theo tay.", "-  Cận lâm sàng", "+ Siêu âm: nếu vỡ tử cung hoàn toàn sẽ thấy trong ổ bụng có: thai nhi, tim thai không đập, có dịch tự do trong ổ bụng.", "+ Xét nghiệm: trong xét nghiệm máu có giảm số lượng hồng cầu, hemoglobin (Hb) và hematocrit (Hct).  Hồng cầu, Hb, Hct giảm nhiều trong trường hợp mất máu nặng."]}, {"heading": "3. VỠ TỬ CUNG TRONG CHUYỂN DẠ", "paragraphs": ["Vỡ tử cung trong chuyển dạ được chia làm 2 nhóm:"], "bullets": ["- Vỡ tử cung tự nhiên xảy ra không do sự can thiệp thủ thuật.", "- Vỡ tử cung do can thiệp bởi các thủ thuật sản khoa như nội xoay thai, lấy đầu hậu trong đỡ đẻ ngôi mông, đẻ thủ thuật forceps, giác hút và đẩy bụng trong giai đoạn rặn sổ..."]}, {"heading": "3.1.1. Nguyên nhân về phía mẹ", "paragraphs": [], "bullets": ["- Ðẻ khó do khung chậu: khung chậu hẹp tuyệt đối, khung chậu hẹp eo giữa và eo dưới (hình phễu), khung chậu méo...", "- Sẹo mổ cũ ở tử cung.", "- Sản phụ đã đẻ nhiều lần, có tiền sử sinh đa thai nên cơ tử cung nhão, mỏng, dễ vỡ.", "- Sản phụ đã nhiều lần phải nạo phá thai", "- Đẻ khó do các khối u tiền đạo như: u xơ ở eo tử cung, u nang buồng trứng và một số u khác trong tiểu khung."]}, {"heading": "3.1.2. Nguyên nhân về phía thai", "paragraphs": [], "bullets": ["- Thai to toàn bộ: trọng lượng thai trên 4000g, gây bất tương xứng giữa thai và khung chậu người mẹ", "- Thai to từng phần như não úng thủy.", "- Do ngôi và kiểu thế bất thường: ngôi chỏm đầu cúi không tốt, ngôi mặt cằm cùng, ngôi trán, ngôi thóp trước, ngôi vai...", "- Ða thai: do các thai vướng nhau hoặc dị dạng"]}, {"heading": "3.1.3. Nguyên nhân do can thiệp", "paragraphs": [], "bullets": ["- Các thủ thuật thực hiện không đúng chỉ định, chưa đủ điều kiện hoặc không đúng kỹ thuật.", "- Sử dụng thuốc tăng co không chính xác (chỉ định, liều lượng) và theo dõi không cẩn thận."]}, {"heading": "3.2.1. Vỡ tử cung hoàn toàn", "paragraphs": ["Hình thái này chiếm 80% các trường hợp vỡ tử cung. Toàn bộ bề dày thành tử cung đều bị xé rách (niêm mạc, cơ đến phúc mạc). Vị trí rách thường ở bên trái và mặt trước đoạn dưới tử cung, vết rách có thể kéo dài từ cổ tử cung đến thân tử cung. Trong vỡ tử cung hoàn toàn thai, rau nước ối bị đẩy vào ổ bụng của mẹ nên mẹ dễ bị viêm phúc mạc."], "bullets": []}, {"heading": "3.2.2. Vỡ tử cung không hoàn toàn", "paragraphs": ["Hình thái này còn gọi là vỡ tử cung dưới phúc mạc. Chỉ có lớp niêm mạc và lớp cơ bị xé rách, phúc mạc đoạn dưới bị bong ra nhưng vẫn chưa bị rách. Máu không chảy vào ổ bụng người mẹ mà chảy vào dây chằng rộng tạo thành khối máu tụ trong dây chằng rộng, tiểu khung. Trường hợp vỡ tử cung không hoàn toàn thai và rau vẫn ở trong tử cung nên thai có thể còn sống.", "(b)", "Hình 2.  (a) Vỡ tử cung trong dây chằng rộng. (b) Vỡ tử cung hoàn toàn"], "bullets": []}, {"heading": "3.2.3. Vỡ tử cung ở người có sẹo mổ cũ", "paragraphs": ["Thường do sẹo mổ cũ ở tử cung bị vỡ hoặc bị nứt một phần, trường hợp này bờ vết rách không nham nhở và có khi ít chảy máu."], "bullets": []}, {"heading": "3.2.4. Vỡ phức tạp", "paragraphs": ["Tổn thương của vỡ tử cung phức tạp bao gồm vỡ tử cung hoàn toàn với tổn thương rộng, có thể kéo dài xuống âm đạo, xé rách túi cùng, bàng quang hoặc đứt động mạch tử cung. Do tổn thương phức tạp, bệnh nhân thường bị choáng nặng nên việc xử trí rất khó khăn và hậu phẫu nặng nề."], "bullets": []}, {"heading": "3.3. Triệu chứng", "paragraphs": ["Vỡ tử cung thường có dấu hiệu báo trước mà ta thường gọi dấu hiệu dọa vỡ tử cung. Đó là dấu hiệu rất quí cho người thầy thuốc, nếu phát hiện và xử trí kịp thời sẽ hạn chế được vỡ tử cung. Vỡ tử cung ở người có sẹo mổ cũ thường xảy ra đột ngột không có dấu hiệu dọa vỡ."], "bullets": []}, {"heading": "3.3.1. Doạ vỡ tử cung", "paragraphs": [], "bullets": ["- Triệu chứng cơ năng", "+ Thai phụ đau nhiều, dữ dội do cơn co mau và mạnh.", "- Triệu chứng thực thể", "+ Nhìn: thấy rõ tử cung bị chia làm hai khối, thắt ở giữa như hình quả bầu nậm. Khối dưới là đoạn dưới bị kéo dài (có khi lên tới rốn), giãn mỏng, khối thân tử cung  bị đẩy lên cao. Chỗ thắt ở giữa gọi là vòng Bandl, lúc tử cung gần vỡ vòng Bandl càng lên cao và càng rõ.", "+ Cơn co tử cung mau và mạnh.", "+ Sờ nắn: hai dây chằng tròn bị căng như hai sợi dây đàn, đoạn dưới giãn mỏng. Vòng Bandl và dây chằng tròn bị kéo căng tạo thành dấu hiệu Bandl - Frommel.", "+ Nhịp tim thai có biểu hiện bất thường: nhanh, chậm, hoặc không đều.", "+ Khám âm đạo: có thể tìm thấy các nguyên nhân gây cản trở chuyển dạ như khung chậu hẹp, ngôi thai bất thường (ngôi vai, ngôi trán, ngôi mặt cằm cùng), thai to hoặc bất tương xứng đầu - chậu..."]}, {"heading": "3.3.2. Vỡ tử cung", "paragraphs": [], "bullets": ["- Triệu chứng cơ năng:", "+ Ở sản phụ đã có dấu hiệu dọa vỡ đột nhiên đau chói, đau nhiều ở chỗ vỡ, sau đó dịu đi.", "+ Chảy máu: âm đạo có máu đỏ tươi chảy ra, số lượng nhiều hoặc ít tùy theo vị trí vỡ và có kèm tổn thương mạch máu không.", "- Triệu chứng thực thể:", "+ Nếu mất máu nhiều có tình trạng choáng: màu da nhợt nhạt, niêm mạc mắt trắng bệch, thở nhanh - nông, vã mồ hôi, chân tay lạnh, mạch nhanh, huyết áp hạ.", "+ Nhìn: không còn thấy hình dạng tử cung.", "+ Sờ nắn: nếu thai còn trong buồng tử cung thì tử cung vẫn còn hình thể cũ nhưng sờ vào chỗ vỡ thai phụ sẽ đau chói, bụng có phản ứng. Nếu thai bị đẩy vào ổ bụng ta sờ thấy các phần của thai lổn nhổn dưới da bụng.", "+ Nghe: nhịp tim thai không có hoặc có biểu hiện suy thai trong trường hợp nứt sẹo mổ cũ ở đoạn dưới.", "+ Khám âm đạo: có máu đỏ tươi chảy ra theo tay, ngôi thai cao, đẩy lên dễ dàng.", "+ Thông tiểu: nước tiểu có màu hồng hoặc đỏ tùy theo có vỡ bàng quang hay không."]}, {"heading": "3.4.1. Chẩn đoán xác định", "paragraphs": [], "bullets": ["- Doạ vỡ tử cung: thai phụ đau bụng dữ dội, cơn co dồn dập, có vòng Bandl hoặc dấu hiệu Bandl - Frommel.", "- Vỡ tử cung: đã có dấu hiệu dọa vỡ tử cung (trừ trường hợp có sẹo mổ ở tử cung), thai phụ thấy đau chói, ra máu âm đạo đỏ tươi, có tình trạng choáng tuỳ thuộc vào mức độ mất máu, không còn tim thai, sờ thấy phần thai dưới da bụng.", "- Vỡ tử cung sau đẻ, sau thủ thuật: sau đẻ thấy ra máu âm đạo nhiều, bóc rau nhân tạo và kiểm soát tử cung hoặc kiểm tra cổ tử cung mới phát hiện ra vỡ tử cung."]}, {"heading": "3.4.2. Chẩn đoán phân biệt", "paragraphs": [], "bullets": ["- Rau tiền đạo: không có dấu hiệu dọa vỡ, chảy máu ra ngoài là chủ yếu, nhịp tim thai có thể mất khi máu chảy nhiều, không đau bụng, khám âm đạo sờ thấy  bánh rau.", "- Rau bong non: có thể có các dấu hiệu của tiền sản giật (protein niệu, phù, huyết áp cao), máu chảy ra âm đạo là máu loãng không đông, tử cung co cứng như gỗ, không nghe thấy nhịp tim thai, giảm fibrinogen máu, choáng có thể xảy ra."]}, {"heading": "4. TIÊN LƯỢNG", "paragraphs": ["Vỡ tử cung nguy hiểm đến tính mạng cho cả mẹ và con."], "bullets": ["- Thai suy hoặc chết vì cơn co dồn dập, rau bong.", "- Tỷ lệ tử vong mẹ phụ thuộc vào:", "+ Độ phức tạp của tổn thương", "+ Thái độ xử trí và điều kiện gây mê - hồi sức.", "+ Phương tiện di chuyển bệnh nhân."]}, {"heading": "5. ĐIỀU TRỊ", "paragraphs": ["Tất cả các loại vỡ tử cung đều phải mổ cấp cứu, vừa hồi sức vừa mổ.", "Trong và sau mổ dùng kháng sinh liều cao, có thể phối hợp hai loại kháng sinh."], "bullets": ["- Hồi sức chống choáng bằng cách bồi phụ lượng máu đã mất, truyền dịch điện giải.", "- Phẫu thuật: tuỳ thuộc vào tình trạng toàn thân của bệnh nhân, thời gian vỡ, tình trạng nhiễm khuẩn, vỡ đơn giản hay phức tạp, tuổi và số con sống của bệnh nhân mà quyết định cắt hay bảo tồn tử cung.", "+ Khâu phục hồi tử cung: chỉ khâu lại tử cung khi bệnh nhân còn trẻ, còn nguyện vọng sinh đẻ, vết rách không phức tạp.", "+ Cắt tử cung: khi bệnh nhân nhiều tuổi, đã đẻ nhiều lần có đủ con, nhiễm khuẩn, vỡ phức tạp."]}, {"heading": "6. DỰ PHÒNG", "paragraphs": ["Dự phòng có vai trò rất quan trọng để hạ thấp tỷ lệ vỡ tử cung, tỷ lệ tử vong do vỡ tử cung."], "bullets": ["- Trong thai kỳ: cần khám thai thường xuyên, phát hiện sớm các nguy cơ đẻ khó như khung chậu hẹp, khung chậu méo, có sẹo mổ cũ ở tử cung, thai to, ngôi bất thường...", "+ Tuyến xã, tuyến huyện không có khả năng phẫu thuật không được quản lý các loại đẻ khó mà phải chuyển lên tuyến trên để quản lý.", "+ Các thai phụ có sẹo ở tử cung phải được vào viện trước khi chuyển dạ để theo dõi cẩn thận và chỉ định can thiệp đúng lúc.", "- Trong chuyển dạ :", "+ Khám phát hiện sớm các nguyên nhân đẻ khó.", "+ Sử dụng biểu đồ chuyển dạ để theo dõi, phát hiện sớm dấu hiệu chuyển dạ đình trệ, dọa vỡ tử cung để xử trí kịp thời.", "+ Sử dụng các thuốc tăng co cần phải đúng chỉ định, đúng liều lượng và theo dõi cẩn thận.", "+ Khi làm thủ thuật đường dưới như nội xoay thai, cắt thai, forceps, giác hút... phải đúng chỉ định và đủ điều kiện. Sau thủ thuật phải kiểm tra sự toàn vẹn của ống đẻ.", "+ Cấm đẩy bụng trong giai đoạn rặn sổ thai."]}, {"heading": "Câu hỏi:", "paragraphs": ["Câu 1: Trình bày các nguyên nhân gây vỡ tử cung?", "Câu 2: Trình bày cách phòng và hướng xử trí ban đầu vỡ tử cung?", "Câu 3: Trình bày triệu chứng lâm sàng để chẩn đoán xác định, chẩn đoán phân biệt doạ vỡ, vỡ tử cung trong chuyển dạ?"], "bullets": []}], "raw_text": "VỠ TỬ CUNG\nThs. Đinh Văn Hoành\nMục tiêu học tập\n1.  Liệt kê các nguyên nhân vỡ tử cung trong thai kỳ và trong chuyển dạ\n2. Mô tả triệu chứng của dọa vỡ tử cung\n3. Mô tả triệu chứng điển hình của vỡ tử cung hoàn toàn\n4. Xác định hướng xử trí và dự phòng vỡ tử cung\n\n1. ĐẠI CƯƠNG\nVỡ tử cung là một tai biến sản khoa. Nếu không phát hiện và xử trí kịp thời sẽ gây tử vong cho mẹ và thai nhi. Vỡ tử cung trong chuyển dạ thường gặp hơn vỡ tử cung trong thai kỳ.\n\nHình 1. Vỡ tử cung\n2. VỠ TỬ CUNG TRONG THAI KỲ\n2.1. Nguyên nhân:\nCó thể xảy ra trên các thai phụ có sẹo mổ cũ ở tử cung do:\n- Mổ lấy thai ở thân tử cung.\n- Khâu lại tử cung bị vỡ.\n- Mổ lấy thai từ hai lần trở lên (sẹo mổ ngang đoạn dưới tử cung trước đó, số lần mổ càng nhiều càng làm tăng nguy cơ vỡ tử cung).\n- Mổ cắt góc tử cung trong phẫu thuật điều trị chửa ngoài tử cung đoạn kẽ.\n- Mổ lấy thai bị nhiễm khuẩn tại vết mổ hoặc tử cung.\n- Phẫu thuật bóc nhân xơ tử cung (nếu u xơ tử cung ăn vào nội mạc tử cung).\n- Khâu lỗ thủng tử cung sau nạo phá thai.\n- Tai nạn, sang chấn trực tiếp.\n- Phẫu thuật Strassman tạo hình tử cung.\n2.2. Triệu chứng\nVỡ tử cung trong thai kỳ có thể xảy ra ở 3 tháng giữa và 3 tháng cuối thai kỳ nhưng không có dấu hiệu dọa vỡ tử cung.\n- Triệu chứng cơ năng:\n+ Đau xảy ra đột ngột ở vùng giữa tử cung  (thường ở vị trí vết mổ cũ).\n+ Ra máu ở âm đạo.\n- Triệu chứng toàn thân:\nTrong một số trường hợp bệnh nhân có dấu hiệu choáng, đôi khi choáng nặng: da mặt tái nhợt, nhịp thở nhanh, thở nông, vẻ mặt hốt hoảng, lo lắng, chân tay lạnh toát, vã mồ hôi, mạch nhanh, huyết áp hạ, đôi khi có thể ngừng tim.\n- Triệu chứng thực thể\n+ Ðau bụng: đau có thể lan toả toàn bụng, có khi cảm ứng phúc mạc, phản ứng thành bụng rất rõ.\n+ Tử cung không còn hình dạng ban đầu, có thể sờ thấy các phần thai ngay dưới thành bụng, trường hợp vỡ tử cung không hoàn toàn có thể còn sờ thấy tử cung nhưng có điểm đau chói tại vùng sẹo của tử cung.\n+ Nghe tim thai: Tim thai không còn nghe được.\n+ Gõ bụng: bụng đục toàn bộ.\n+ Khám âm đạo: ngôi thai không sờ thấy, có máu chảy ra theo tay.\nCần chú ý: Có trường hợp sẹo mổ cũ bị nứt, nên không có dấu hiệu điển hình của chảy máu trong như đã mô tả ở trên.\n-  Cận lâm sàng\n+ Siêu âm: nếu vỡ tử cung hoàn toàn sẽ thấy trong ổ bụng có: thai nhi, tim thai không đập, có dịch tự do trong ổ bụng.\n+ Xét nghiệm: trong xét nghiệm máu có giảm số lượng hồng cầu, hemoglobin (Hb) và hematocrit (Hct).  Hồng cầu, Hb, Hct giảm nhiều trong trường hợp mất máu nặng.\n3. VỠ TỬ CUNG TRONG CHUYỂN DẠ\nVỡ tử cung trong chuyển dạ được chia làm 2 nhóm:\n- Vỡ tử cung tự nhiên xảy ra không do sự can thiệp thủ thuật.\n- Vỡ tử cung do can thiệp bởi các thủ thuật sản khoa như nội xoay thai, lấy đầu hậu trong đỡ đẻ ngôi mông, đẻ thủ thuật forceps, giác hút và đẩy bụng trong giai đoạn rặn sổ...\n3.1. Nguyên nhân\n3.1.1. Nguyên nhân về phía mẹ\n- Ðẻ khó do khung chậu: khung chậu hẹp tuyệt đối, khung chậu hẹp eo giữa và eo dưới (hình phễu), khung chậu méo...\n- Sẹo mổ cũ ở tử cung.\n- Sản phụ đã đẻ nhiều lần, có tiền sử sinh đa thai nên cơ tử cung nhão, mỏng, dễ vỡ.\n- Sản phụ đã nhiều lần phải nạo phá thai\n- Đẻ khó do các khối u tiền đạo như: u xơ ở eo tử cung, u nang buồng trứng và một số u khác trong tiểu khung.\n3.1.2. Nguyên nhân về phía thai\n- Thai to toàn bộ: trọng lượng thai trên 4000g, gây bất tương xứng giữa thai và khung chậu người mẹ\n- Thai to từng phần như não úng thủy.\n- Do ngôi và kiểu thế bất thường: ngôi chỏm đầu cúi không tốt, ngôi mặt cằm cùng, ngôi trán, ngôi thóp trước, ngôi vai...\n- Ða thai: do các thai vướng nhau hoặc dị dạng\n3.1.3. Nguyên nhân do can thiệp\n- Các thủ thuật thực hiện không đúng chỉ định, chưa đủ điều kiện hoặc không đúng kỹ thuật.\n- Sử dụng thuốc tăng co không chính xác (chỉ định, liều lượng) và theo dõi không cẩn thận.\n3.2. Giải phẫu bệnh lý\n3.2.1. Vỡ tử cung hoàn toàn\nHình thái này chiếm 80% các trường hợp vỡ tử cung. Toàn bộ bề dày thành tử cung đều bị xé rách (niêm mạc, cơ đến phúc mạc). Vị trí rách thường ở bên trái và mặt trước đoạn dưới tử cung, vết rách có thể kéo dài từ cổ tử cung đến thân tử cung. Trong vỡ tử cung hoàn toàn thai, rau nước ối bị đẩy vào ổ bụng của mẹ nên mẹ dễ bị viêm phúc mạc.\n3.2.2. Vỡ tử cung không hoàn toàn\nHình thái này còn gọi là vỡ tử cung dưới phúc mạc. Chỉ có lớp niêm mạc và lớp cơ bị xé rách, phúc mạc đoạn dưới bị bong ra nhưng vẫn chưa bị rách. Máu không chảy vào ổ bụng người mẹ mà chảy vào dây chằng rộng tạo thành khối máu tụ trong dây chằng rộng, tiểu khung. Trường hợp vỡ tử cung không hoàn toàn thai và rau vẫn ở trong tử cung nên thai có thể còn sống.\n\n(b)\n\nHình 2.  (a) Vỡ tử cung trong dây chằng rộng. (b) Vỡ tử cung hoàn toàn\n\n3.2.3. Vỡ tử cung ở người có sẹo mổ cũ\nThường do sẹo mổ cũ ở tử cung bị vỡ hoặc bị nứt một phần, trường hợp này bờ vết rách không nham nhở và có khi ít chảy máu.\n\n3.2.4. Vỡ phức tạp\nTổn thương của vỡ tử cung phức tạp bao gồm vỡ tử cung hoàn toàn với tổn thương rộng, có thể kéo dài xuống âm đạo, xé rách túi cùng, bàng quang hoặc đứt động mạch tử cung. Do tổn thương phức tạp, bệnh nhân thường bị choáng nặng nên việc xử trí rất khó khăn và hậu phẫu nặng nề.\n3.3. Triệu chứng\nVỡ tử cung thường có dấu hiệu báo trước mà ta thường gọi dấu hiệu dọa vỡ tử cung. Đó là dấu hiệu rất quí cho người thầy thuốc, nếu phát hiện và xử trí kịp thời sẽ hạn chế được vỡ tử cung. Vỡ tử cung ở người có sẹo mổ cũ thường xảy ra đột ngột không có dấu hiệu dọa vỡ.\n3.3.1. Doạ vỡ tử cung\n- Triệu chứng cơ năng\n+ Thai phụ đau nhiều, dữ dội do cơn co mau và mạnh.\n- Triệu chứng thực thể\n+ Nhìn: thấy rõ tử cung bị chia làm hai khối, thắt ở giữa như hình quả bầu nậm. Khối dưới là đoạn dưới bị kéo dài (có khi lên tới rốn), giãn mỏng, khối thân tử cung  bị đẩy lên cao. Chỗ thắt ở giữa gọi là vòng Bandl, lúc tử cung gần vỡ vòng Bandl càng lên cao và càng rõ.\n+ Cơn co tử cung mau và mạnh.\n+ Sờ nắn: hai dây chằng tròn bị căng như hai sợi dây đàn, đoạn dưới giãn mỏng. Vòng Bandl và dây chằng tròn bị kéo căng tạo thành dấu hiệu Bandl - Frommel.\n+ Nhịp tim thai có biểu hiện bất thường: nhanh, chậm, hoặc không đều.\n+ Khám âm đạo: có thể tìm thấy các nguyên nhân gây cản trở chuyển dạ như khung chậu hẹp, ngôi thai bất thường (ngôi vai, ngôi trán, ngôi mặt cằm cùng), thai to hoặc bất tương xứng đầu - chậu...\n3.3.2. Vỡ tử cung\n- Triệu chứng cơ năng:\n+ Ở sản phụ đã có dấu hiệu dọa vỡ đột nhiên đau chói, đau nhiều ở chỗ vỡ, sau đó dịu đi.\n+ Chảy máu: âm đạo có máu đỏ tươi chảy ra, số lượng nhiều hoặc ít tùy theo vị trí vỡ và có kèm tổn thương mạch máu không.\n- Triệu chứng thực thể:\n+ Nếu mất máu nhiều có tình trạng choáng: màu da nhợt nhạt, niêm mạc mắt trắng bệch, thở nhanh - nông, vã mồ hôi, chân tay lạnh, mạch nhanh, huyết áp hạ.\n+ Nhìn: không còn thấy hình dạng tử cung.\n+ Sờ nắn: nếu thai còn trong buồng tử cung thì tử cung vẫn còn hình thể cũ nhưng sờ vào chỗ vỡ thai phụ sẽ đau chói, bụng có phản ứng. Nếu thai bị đẩy vào ổ bụng ta sờ thấy các phần của thai lổn nhổn dưới da bụng.\n+ Nghe: nhịp tim thai không có hoặc có biểu hiện suy thai trong trường hợp nứt sẹo mổ cũ ở đoạn dưới.\n+ Khám âm đạo: có máu đỏ tươi chảy ra theo tay, ngôi thai cao, đẩy lên dễ dàng.\n+ Thông tiểu: nước tiểu có màu hồng hoặc đỏ tùy theo có vỡ bàng quang hay không.\n3.4. Chẩn đoán\n3.4.1. Chẩn đoán xác định\n- Doạ vỡ tử cung: thai phụ đau bụng dữ dội, cơn co dồn dập, có vòng Bandl hoặc dấu hiệu Bandl - Frommel.\n- Vỡ tử cung: đã có dấu hiệu dọa vỡ tử cung (trừ trường hợp có sẹo mổ ở tử cung), thai phụ thấy đau chói, ra máu âm đạo đỏ tươi, có tình trạng choáng tuỳ thuộc vào mức độ mất máu, không còn tim thai, sờ thấy phần thai dưới da bụng.\n- Vỡ tử cung sau đẻ, sau thủ thuật: sau đẻ thấy ra máu âm đạo nhiều, bóc rau nhân tạo và kiểm soát tử cung hoặc kiểm tra cổ tử cung mới phát hiện ra vỡ tử cung.\n3.4.2. Chẩn đoán phân biệt\n- Rau tiền đạo: không có dấu hiệu dọa vỡ, chảy máu ra ngoài là chủ yếu, nhịp tim thai có thể mất khi máu chảy nhiều, không đau bụng, khám âm đạo sờ thấy  bánh rau.\n- Rau bong non: có thể có các dấu hiệu của tiền sản giật (protein niệu, phù, huyết áp cao), máu chảy ra âm đạo là máu loãng không đông, tử cung co cứng như gỗ, không nghe thấy nhịp tim thai, giảm fibrinogen máu, choáng có thể xảy ra.\n4. TIÊN LƯỢNG\nVỡ tử cung nguy hiểm đến tính mạng cho cả mẹ và con.\n- Thai suy hoặc chết vì cơn co dồn dập, rau bong.\n- Tỷ lệ tử vong mẹ phụ thuộc vào:\n+ Độ phức tạp của tổn thương\n+ Thái độ xử trí và điều kiện gây mê - hồi sức.\n+ Phương tiện di chuyển bệnh nhân.\n5. ĐIỀU TRỊ\nTất cả các loại vỡ tử cung đều phải mổ cấp cứu, vừa hồi sức vừa mổ.\n- Hồi sức chống choáng bằng cách bồi phụ lượng máu đã mất, truyền dịch điện giải.\n- Phẫu thuật: tuỳ thuộc vào tình trạng toàn thân của bệnh nhân, thời gian vỡ, tình trạng nhiễm khuẩn, vỡ đơn giản hay phức tạp, tuổi và số con sống của bệnh nhân mà quyết định cắt hay bảo tồn tử cung.\n+ Khâu phục hồi tử cung: chỉ khâu lại tử cung khi bệnh nhân còn trẻ, còn nguyện vọng sinh đẻ, vết rách không phức tạp.\n+ Cắt tử cung: khi bệnh nhân nhiều tuổi, đã đẻ nhiều lần có đủ con, nhiễm khuẩn, vỡ phức tạp.\nTrong và sau mổ dùng kháng sinh liều cao, có thể phối hợp hai loại kháng sinh.\n6. DỰ PHÒNG\nDự phòng có vai trò rất quan trọng để hạ thấp tỷ lệ vỡ tử cung, tỷ lệ tử vong do vỡ tử cung.\n- Trong thai kỳ: cần khám thai thường xuyên, phát hiện sớm các nguy cơ đẻ khó như khung chậu hẹp, khung chậu méo, có sẹo mổ cũ ở tử cung, thai to, ngôi bất thường...\n+ Tuyến xã, tuyến huyện không có khả năng phẫu thuật không được quản lý các loại đẻ khó mà phải chuyển lên tuyến trên để quản lý.\n+ Các thai phụ có sẹo ở tử cung phải được vào viện trước khi chuyển dạ để theo dõi cẩn thận và chỉ định can thiệp đúng lúc.\n- Trong chuyển dạ :\n+ Khám phát hiện sớm các nguyên nhân đẻ khó.\n+ Sử dụng biểu đồ chuyển dạ để theo dõi, phát hiện sớm dấu hiệu chuyển dạ đình trệ, dọa vỡ tử cung để xử trí kịp thời.\n+ Sử dụng các thuốc tăng co cần phải đúng chỉ định, đúng liều lượng và theo dõi cẩn thận.\n+ Khi làm thủ thuật đường dưới như nội xoay thai, cắt thai, forceps, giác hút... phải đúng chỉ định và đủ điều kiện. Sau thủ thuật phải kiểm tra sự toàn vẹn của ống đẻ.\n+ Cấm đẩy bụng trong giai đoạn rặn sổ thai.\nCâu hỏi:\nCâu 1: Trình bày các nguyên nhân gây vỡ tử cung?\nCâu 2: Trình bày cách phòng và hướng xử trí ban đầu vỡ tử cung?\nCâu 3: Trình bày triệu chứng lâm sàng để chẩn đoán xác định, chẩn đoán phân biệt doạ vỡ, vỡ tử cung trong chuyển dạ?", "priority": "Cao (Trọng tâm BSNT)"}, {"id": "SK-29", "chapter": "Chương 2. Sản bệnh", "folder": "02_San_benh", "title": "Rau tiền đạo", "author": "Ths. Nguyễn Trung Kiên", "word_count": 1739, "line_count": 109, "key_numbers": ["100 mm", "20 mm", "3 tháng"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["RAU TIỀN ĐẠO", "Ths. Nguyễn Trung Kiên"], "bullets": []}, {"heading": "Mục tiêu học tập", "paragraphs": ["Định nghĩa rau tiền đạo và mô tả được các hình thái lâm sàng.", "Trình bày  được các yếu tố thuận lợi và triệu chứng lâm sàng."], "bullets": []}, {"heading": "1. ĐẠI CƯƠNG", "paragraphs": ["Rau tiền đạo là bánh rau bám ở đoạn dưới tử cung, có thể che lấp một phần hoặc toàn bộ lỗ trong cổ tử cung.", "Rau tiền đạo xảy ra khoảng 1/200 trường hợp thai nghén, là một trong những nguyên nhân chính gây chảy máu trong ba tháng cuối của thai kỳ, trong chuyển dạ và sau đẻ. Vì vậy, rau tiền đạo còn là một cấp cứu trong sản khoa.", "Cơ chế chảy máu trong rau tiền đạo:", "A                                        B", "Hình 1. A. Rau bám vị trí bình thường  B. Rau tiền đạo"], "bullets": ["- Đoạn dưới thành lập trong 3 tháng cuối thai kỳ.", "- Sự co kéo của đoạn dưới ở diện rau bám gây bóc tách.", "- Gai rau bám sâu vào cơ tử cung ở đoạn dưới."]}, {"heading": "2.1. Phân loại theo giải phẫu", "paragraphs": [], "bullets": ["- Rau bám thấp: bánh rau bám lan xuống đoạn dưới của tử cung nhưng chưa tới lỗ trong cổ tử cung.", "- Rau bám bên: bánh rau bám lan xuống đoạn dưới của tử cung và gần tới lỗ trong cổ tử cung.", "- Rau bám mép: bờ của bánh rau bám sát mép lỗ trong cổ tử cung.", "- Rau tiền đạo trung tâm không hoàn toàn: bánh rau che lấp một phần lỗ trong tử cung.", "- Rau tiền đạo trung tâm hoàn toàn: bánh rau che lấp toàn bộ lỗ trong cổ tử cung."]}, {"heading": "2.2. Phân loại theo lâm sàng", "paragraphs": ["Hình 2. Phân loại theo giải phẫu rau tiền đạo"], "bullets": ["- Rau tiền đạo trung tâm: bao gồm loại bán trung tâm và trung tâm hoàn toàn. Thái độ xử trí chủ yếu là mổ lấy thai.", "- Rau tiền đạo không trung tâm: bao gồm loại rau bám thấp, bám bên và bám mép. Các trường hợp này có thể theo dõi đẻ đường âm đạo."]}, {"heading": "2.3. Phân loại theo siêu âm", "paragraphs": ["Khi chưa chuyển dạ trên siêu âm ta đo từ bờ mép bánh rau tới lỗ trong cổ tử cung nếu khoảng cách:", "Hình 4. Phân loại rau tiền đạotheo siêu âm"], "bullets": ["+ 20 - 100 mm, khi chuyển dạ có khả năng đẻ đường dưới được.", "+ < 20 mm, khi chuyển dạ sẽ trở thành rau tiền đạo bám mép.", "+ Nếu mép bánh rau lan tới lỗ trong hoặc lan qua lỗ trong cổ tử cung thì khi chuyển dạ trở thành rau tiền đạo bán trung tâm hoặc trung tâm hoàn toàn."]}, {"heading": "3. CÁC YẾU TỐ THUẬN LỢI", "paragraphs": ["Người ta chưa hiểu đầy đủ nguyên nhân sinh ra rau tiền đạo. Tuy nhiên, tần suất rau tiền đạo tăng lên ở những thai phụ có tiền sử sau:"], "bullets": ["- Đẻ nhiều lần.", "- Mổ lấy thai.", "- Mổ bóc nhân xơ tử cung, cắt góc tử cung trong điều trị thai làm tổ ở sừng tử cung, tạo hình tử cung...", "- Nạo thai, hút điều hoà kinh nguyệt nhiều lần.", "- Đẻ có kiểm soát tử cung hay bóc rau nhân tạo.", "- Viêm nhiễm tử cung.", "- Đa thai.", "- Tiền sử đã mang thai bị rau tiền đạo."]}, {"heading": "4.1. Triệu chứng lâm sàng", "paragraphs": ["* Kiểm tra bằng mỏ vịt hay van âm đạo nhằm chẩn đoán phân biệt với các nguyên nhân gây chảy máu từ các tổn thương ở cổ tử cung và âm đạo.", "* Nên hạn chế và thận trọng khi khám âm đạo bằng tay vì có thể làm rau bong thêm, gây chảy máu ồ ạt, nguy hiểm cho cả mẹ lẫn con."], "bullets": ["- Triệu chứng cơ năng: chảy máu âm đạo là triệu chứng chính, thường xuất hiện vào ba tháng cuối của thai kỳ, đôi khi sớm hơn.", "+ Chảy máu thường xuất hiện đột ngột, không có nguyên nhân, không có triệu chứng báo trước.", "+ Lượng máu ít trong những lần đầu, có thể tự cầm, sau đó lại tái phát nhiều lần và lần sau có khuynh hướng nhiều hơn những lần trước và khoảng cách giữa các lần ngắn lại.", "+ Máu ra đỏ tươi lẫn máu cục.", "- Triệu chứng thực thể:", "+ Toàn trạng bệnh nhân biểu hiện tương ứng lượng máu mất ra ngoài. Mạch, huyết áp, nhịp thở có thể bình thường hay thay đổi tuỳ sự theo mất máu nhiều hay ít.", "+ Nắn tử cung thường thấy ngôi đầu cao lỏng  hoặc ngôi bất thường.", "+ Nghe tim thai: tình trạng tim thai thay đổi tuỳ thuộc vào lượng máu mất ra ngoài.", "+ Khám âm đạo:", "- Cận lâm sàng:", "+ Siêu âm: xác định được vị trí bám chính xác của bánh rau sớm. Phương pháp này an toàn và có giá trị chẩn đoán cao (độ chính xác 95% với đầu dò đường bụng và 100% với đầu dò đường âm đạo), trước khi có biểu hiện lâm sàng là chảy máu. Siêu âm còn giúp theo dõi tiến triển của rau tiền đạo trong thai kỳ.", "+ Chụp cộng hưởng từ giúp chẩn đoán chính xác rau tiền đạo nhưng đây là một phương pháp tốn kém và phức tạp nên ít được sử dụng rộng rãi như siêu âm."]}, {"heading": "4.3.1. Rau bong non", "paragraphs": ["Thường có hội chứng tiền sản giật - sản giật. Máu âm đạo đen loãng, không đông, sản phụ đau bụng nhiều, tử cung co cứng, thai suy nhanh chóng."], "bullets": []}, {"heading": "4.3.2. Vỡ tử cung", "paragraphs": ["Thường có dấu hiệu doạ vỡ, thai suy hoặc chết, sản phụ choáng nặng, có dấu hiệu xuất huyết nội."], "bullets": []}, {"heading": "4.3.3. Các nguyên nhân khác", "paragraphs": ["Một số nguyên nhân chảy máu từ cổ tử cung (viêm lộ tuyến, polype, ung thư...), chảy máu âm đạo. Trong khi chuyển dạ chẩn đoán phân biệt với đứt mạch máu của dây rau, máu chảy ra đỏ tươi, suy thai rất nhanh."], "bullets": []}, {"heading": "5.1. Tuyến xã", "paragraphs": [], "bullets": ["- Khi nghi ngờ và chẩn đoán được rau tiền đạo thì phải chuyển tuyến trên khám chẩn đoán và theo dõi điều trị.", "- Trường hợp đã có chuyển dạ hay chảy máu âm đạo nhiều, cần hồi sức chống choáng tích cực và sử dụng thuốc giảm go và chuyển lên tuyến trên cùng cán bộ y tế đi kèm."]}, {"heading": "5.2. Tuyến huyện và các tuyến chuyên khoa", "paragraphs": ["Nguyên tắc trong điều trị rau tiền đạo là phải dựa vào tuổi thai, phân loại lâm sàng, mức độ chảy máu."], "bullets": []}, {"heading": "5.2.1. Xử trí rau tiền đạo khi chưa chuyển dạ", "paragraphs": ["* Điều trị duy trì: khi thai chưa trưởng thành và mức độ chảy máu không nhiều.", "* Chấm dứt thai kỳ"], "bullets": ["- Chăm sóc, theo dõi", "+ Khuyên bệnh nhân vào viện để điều trị và dự phòng cho lần chảy máu sau.", "+ Nghỉ ngơi tại giường, hạn chế đi lại tối đa.", "+ Chế độ ăn uống: đầy đủ dinh dưỡng, chống táo bón.", "+ Theo dõi sự phát triển của thai và bánh rau. Xác định lại chẩn đoán rau tiền đạo thuộc loại nào, tuổi thai và trọng lượng thai để có biện pháp xử lý cho phù hợp.", "+ Làm các xét nghiệm máu như công thức máu, hemoglobin, hematocrit, phân  loại máu. Chuẩn bị máu tươi để truyền khi cần thiết.", "- Điều trị", "+ Thuốc giảm co tử cung như spasmaverin, salbutamol, magné sulfate.", "+ Kháng sinh.", "+ Viên sắt và các vitamin.", "+ Nếu rau tiền đạo trung tâm thì nên chủ động mổ lấy thai khi thai đủ tháng để tránh chảy máu khi chuyển dạ.", "+ Nếu chảy máu nặng, hoặc điều trị chảy máu không có kết quả nên chủ động mổ lấy thai để cầm máu cứu mẹ là chính không kể tuổi thai."]}, {"heading": "5.2.2.  Xử trí rau tiền đạo khi chuyển dạ", "paragraphs": [], "bullets": ["- Rau tiền đạo không trung tâm", "+ Đa số các trường hợp này có thể sinh đường dưới. Khi chuyển dạ nên bấm ối để hạn chế chảy máu. Nếu sau bấm ối máu vẫn tiếp tục chảy nên mổ lấy thai.", "+ Khi có quyết định cho sinh đường âm đạo cần phải theo dõi sát toàn trạng và các dấu hiệu sinh tồn của sản phụ, số lượng máu mất và tình trạng thai. Nếu toàn trạng mẹ xấu đi do mất máu nhiều, hoặc phát sinh thêm các yếu tố nguy cư khác thì phải mổ lấy thai cấp cứu.", "+ Sau khi thai sổ, bánh rau thường bong sớm vì một phần đã bị bong trước sinh. Chỗ rau bám có thể chảy máu, cần dùng các thuốc co hồi tử cung. Nếu không kết quả phải cắt tử cung bán phần thấp.", "- Rau tiền đạo trung tâm", "+ Chỉ định mổ lấy thai tuyệt đối. Trường hợp chảy máu nhiều không kiểm soát được thì có thể buộc động mạch tử cung hoặc động mạch hạ vị để cầm máu. Nếu không có kết quả thì phải cắt tử cung bán phần thấp để cầm máu."]}, {"heading": "5.2.3. Thời kỳ hậu sản", "paragraphs": [], "bullets": ["- Theo dõi sát để đề phòng chảy máu thứ phát sau sinh và nhiễm khuẩn.", "- Trong thời kỳ hậu sản nếu mẹ thiếu máu nhiều phải truyền máu để bù lại số lượng máu đã mất và uống thêm viên sắt.", "- Trẻ sơ sinh cần được chăm sóc đặc biệt vì phần lớn là trẻ non tháng"]}, {"heading": "6. PHÒNG BỆNH", "paragraphs": ["Đăng ký quản lý thai nghén chặt chẽ nhằm phát hiện sớm các trường hợp rau tiền đạo. Nếu cần thiết, cho thai phụ nhập viện để theo dõi và điều trị, hạn chế chảy máu tới mức thấp nhất."], "bullets": []}, {"heading": "Câu hỏi:", "paragraphs": ["1: Trình bày các yếu tố thuận lợi và phân loại rau tiền đạo?", "2: Trình bày triệu chứng lâm sàng, cận lâm sàng chẩn đoán rau tiền đạo?", "3: Hướng xử trí ban đầu tại tuyến cơ sở một sản phụ được chẩn đoán là rau tiền đạo?"], "bullets": []}], "raw_text": "RAU TIỀN ĐẠO\nThs. Nguyễn Trung Kiên\nMục tiêu học tập\nĐịnh nghĩa rau tiền đạo và mô tả được các hình thái lâm sàng.\nTrình bày  được các yếu tố thuận lợi và triệu chứng lâm sàng.\n3. Nêu được các nguyên nhân chảy máu cần chẩn đoán phân biệt với rau tiền đạo.\n4. Trình bày được hướng xử trí rau tiền đạo.\n1. ĐẠI CƯƠNG\nRau tiền đạo là bánh rau bám ở đoạn dưới tử cung, có thể che lấp một phần hoặc toàn bộ lỗ trong cổ tử cung.\nRau tiền đạo xảy ra khoảng 1/200 trường hợp thai nghén, là một trong những nguyên nhân chính gây chảy máu trong ba tháng cuối của thai kỳ, trong chuyển dạ và sau đẻ. Vì vậy, rau tiền đạo còn là một cấp cứu trong sản khoa.\nCơ chế chảy máu trong rau tiền đạo:\n- Đoạn dưới thành lập trong 3 tháng cuối thai kỳ.\n- Sự co kéo của đoạn dưới ở diện rau bám gây bóc tách.\n- Gai rau bám sâu vào cơ tử cung ở đoạn dưới.\n\nA                                        B\nHình 1. A. Rau bám vị trí bình thường  B. Rau tiền đạo\n2. PHÂN LOẠI\n2.1. Phân loại theo giải phẫu\n- Rau bám thấp: bánh rau bám lan xuống đoạn dưới của tử cung nhưng chưa tới lỗ trong cổ tử cung.\n- Rau bám bên: bánh rau bám lan xuống đoạn dưới của tử cung và gần tới lỗ trong cổ tử cung.\n- Rau bám mép: bờ của bánh rau bám sát mép lỗ trong cổ tử cung.\n- Rau tiền đạo trung tâm không hoàn toàn: bánh rau che lấp một phần lỗ trong tử cung.\n- Rau tiền đạo trung tâm hoàn toàn: bánh rau che lấp toàn bộ lỗ trong cổ tử cung.\n2.2. Phân loại theo lâm sàng\n- Rau tiền đạo trung tâm: bao gồm loại bán trung tâm và trung tâm hoàn toàn. Thái độ xử trí chủ yếu là mổ lấy thai.\n- Rau tiền đạo không trung tâm: bao gồm loại rau bám thấp, bám bên và bám mép. Các trường hợp này có thể theo dõi đẻ đường âm đạo.\n\nHình 2. Phân loại theo giải phẫu rau tiền đạo\n2.3. Phân loại theo siêu âm\nKhi chưa chuyển dạ trên siêu âm ta đo từ bờ mép bánh rau tới lỗ trong cổ tử cung nếu khoảng cách:\n+ 20 - 100 mm, khi chuyển dạ có khả năng đẻ đường dưới được.\n+ < 20 mm, khi chuyển dạ sẽ trở thành rau tiền đạo bám mép.\n+ Nếu mép bánh rau lan tới lỗ trong hoặc lan qua lỗ trong cổ tử cung thì khi chuyển dạ trở thành rau tiền đạo bán trung tâm hoặc trung tâm hoàn toàn.\n\nHình 4. Phân loại rau tiền đạotheo siêu âm\n\n3. CÁC YẾU TỐ THUẬN LỢI\nNgười ta chưa hiểu đầy đủ nguyên nhân sinh ra rau tiền đạo. Tuy nhiên, tần suất rau tiền đạo tăng lên ở những thai phụ có tiền sử sau:\n- Đẻ nhiều lần.\n- Mổ lấy thai.\n- Mổ bóc nhân xơ tử cung, cắt góc tử cung trong điều trị thai làm tổ ở sừng tử cung, tạo hình tử cung...\n- Nạo thai, hút điều hoà kinh nguyệt nhiều lần.\n- Đẻ có kiểm soát tử cung hay bóc rau nhân tạo.\n- Viêm nhiễm tử cung.\n- Đa thai.\n- Tiền sử đã mang thai bị rau tiền đạo.\n4. TRIỆU CHỨNG VÀ CHẨN ĐOÁN\n4.1. Triệu chứng lâm sàng\n- Triệu chứng cơ năng: chảy máu âm đạo là triệu chứng chính, thường xuất hiện vào ba tháng cuối của thai kỳ, đôi khi sớm hơn.\n+ Chảy máu thường xuất hiện đột ngột, không có nguyên nhân, không có triệu chứng báo trước.\n+ Lượng máu ít trong những lần đầu, có thể tự cầm, sau đó lại tái phát nhiều lần và lần sau có khuynh hướng nhiều hơn những lần trước và khoảng cách giữa các lần ngắn lại.\n+ Máu ra đỏ tươi lẫn máu cục.\n- Triệu chứng thực thể:\n+ Toàn trạng bệnh nhân biểu hiện tương ứng lượng máu mất ra ngoài. Mạch, huyết áp, nhịp thở có thể bình thường hay thay đổi tuỳ sự theo mất máu nhiều hay ít.\n+ Nắn tử cung thường thấy ngôi đầu cao lỏng  hoặc ngôi bất thường.\n+ Nghe tim thai: tình trạng tim thai thay đổi tuỳ thuộc vào lượng máu mất ra ngoài.\n+ Khám âm đạo:\n* Kiểm tra bằng mỏ vịt hay van âm đạo nhằm chẩn đoán phân biệt với các nguyên nhân gây chảy máu từ các tổn thương ở cổ tử cung và âm đạo.\n* Nên hạn chế và thận trọng khi khám âm đạo bằng tay vì có thể làm rau bong thêm, gây chảy máu ồ ạt, nguy hiểm cho cả mẹ lẫn con.\n- Cận lâm sàng:\n+ Siêu âm: xác định được vị trí bám chính xác của bánh rau sớm. Phương pháp này an toàn và có giá trị chẩn đoán cao (độ chính xác 95% với đầu dò đường bụng và 100% với đầu dò đường âm đạo), trước khi có biểu hiện lâm sàng là chảy máu. Siêu âm còn giúp theo dõi tiến triển của rau tiền đạo trong thai kỳ.\n+ Chụp cộng hưởng từ giúp chẩn đoán chính xác rau tiền đạo nhưng đây là một phương pháp tốn kém và phức tạp nên ít được sử dụng rộng rãi như siêu âm.\n4.3. Chẩn đoán phân biệt\n4.3.1. Rau bong non\nThường có hội chứng tiền sản giật - sản giật. Máu âm đạo đen loãng, không đông, sản phụ đau bụng nhiều, tử cung co cứng, thai suy nhanh chóng.\n4.3.2. Vỡ tử cung\nThường có dấu hiệu doạ vỡ, thai suy hoặc chết, sản phụ choáng nặng, có dấu hiệu xuất huyết nội.\n4.3.3. Các nguyên nhân khác\nMột số nguyên nhân chảy máu từ cổ tử cung (viêm lộ tuyến, polype, ung thư...), chảy máu âm đạo. Trong khi chuyển dạ chẩn đoán phân biệt với đứt mạch máu của dây rau, máu chảy ra đỏ tươi, suy thai rất nhanh.\n5. XỬ TRÍ\n5.1. Tuyến xã\n- Khi nghi ngờ và chẩn đoán được rau tiền đạo thì phải chuyển tuyến trên khám chẩn đoán và theo dõi điều trị.\n- Trường hợp đã có chuyển dạ hay chảy máu âm đạo nhiều, cần hồi sức chống choáng tích cực và sử dụng thuốc giảm go và chuyển lên tuyến trên cùng cán bộ y tế đi kèm.\n5.2. Tuyến huyện và các tuyến chuyên khoa\nNguyên tắc trong điều trị rau tiền đạo là phải dựa vào tuổi thai, phân loại lâm sàng, mức độ chảy máu.\n5.2.1. Xử trí rau tiền đạo khi chưa chuyển dạ\n- Chăm sóc, theo dõi\n+ Khuyên bệnh nhân vào viện để điều trị và dự phòng cho lần chảy máu sau.\n+ Nghỉ ngơi tại giường, hạn chế đi lại tối đa.\n+ Chế độ ăn uống: đầy đủ dinh dưỡng, chống táo bón.\n+ Theo dõi sự phát triển của thai và bánh rau. Xác định lại chẩn đoán rau tiền đạo thuộc loại nào, tuổi thai và trọng lượng thai để có biện pháp xử lý cho phù hợp.\n+ Làm các xét nghiệm máu như công thức máu, hemoglobin, hematocrit, phân  loại máu. Chuẩn bị máu tươi để truyền khi cần thiết.\n- Điều trị\n* Điều trị duy trì: khi thai chưa trưởng thành và mức độ chảy máu không nhiều.\n+ Thuốc giảm co tử cung như spasmaverin, salbutamol, magné sulfate.\n+ Kháng sinh.\n+ Viên sắt và các vitamin.\n* Chấm dứt thai kỳ\n+ Nếu rau tiền đạo trung tâm thì nên chủ động mổ lấy thai khi thai đủ tháng để tránh chảy máu khi chuyển dạ.\n+ Nếu chảy máu nặng, hoặc điều trị chảy máu không có kết quả nên chủ động mổ lấy thai để cầm máu cứu mẹ là chính không kể tuổi thai.\n5.2.2.  Xử trí rau tiền đạo khi chuyển dạ\n- Rau tiền đạo không trung tâm\n+ Đa số các trường hợp này có thể sinh đường dưới. Khi chuyển dạ nên bấm ối để hạn chế chảy máu. Nếu sau bấm ối máu vẫn tiếp tục chảy nên mổ lấy thai.\n+ Khi có quyết định cho sinh đường âm đạo cần phải theo dõi sát toàn trạng và các dấu hiệu sinh tồn của sản phụ, số lượng máu mất và tình trạng thai. Nếu toàn trạng mẹ xấu đi do mất máu nhiều, hoặc phát sinh thêm các yếu tố nguy cư khác thì phải mổ lấy thai cấp cứu.\n+ Sau khi thai sổ, bánh rau thường bong sớm vì một phần đã bị bong trước sinh. Chỗ rau bám có thể chảy máu, cần dùng các thuốc co hồi tử cung. Nếu không kết quả phải cắt tử cung bán phần thấp.\n- Rau tiền đạo trung tâm\n+ Chỉ định mổ lấy thai tuyệt đối. Trường hợp chảy máu nhiều không kiểm soát được thì có thể buộc động mạch tử cung hoặc động mạch hạ vị để cầm máu. Nếu không có kết quả thì phải cắt tử cung bán phần thấp để cầm máu.\n5.2.3. Thời kỳ hậu sản\n- Theo dõi sát để đề phòng chảy máu thứ phát sau sinh và nhiễm khuẩn.\n- Trong thời kỳ hậu sản nếu mẹ thiếu máu nhiều phải truyền máu để bù lại số lượng máu đã mất và uống thêm viên sắt.\n- Trẻ sơ sinh cần được chăm sóc đặc biệt vì phần lớn là trẻ non tháng\n6. PHÒNG BỆNH\nĐăng ký quản lý thai nghén chặt chẽ nhằm phát hiện sớm các trường hợp rau tiền đạo. Nếu cần thiết, cho thai phụ nhập viện để theo dõi và điều trị, hạn chế chảy máu tới mức thấp nhất.\n\nCâu hỏi:\n1: Trình bày các yếu tố thuận lợi và phân loại rau tiền đạo?\n2: Trình bày triệu chứng lâm sàng, cận lâm sàng chẩn đoán rau tiền đạo?\n3: Hướng xử trí ban đầu tại tuyến cơ sở một sản phụ được chẩn đoán là rau tiền đạo?", "priority": "Cao (Trọng tâm BSNT)"}, {"id": "SK-30", "chapter": "Chương 2. Sản bệnh", "folder": "02_San_benh", "title": "Rau bong non", "author": "Ths. Nguyễn Trung Kiên", "word_count": 2522, "line_count": 216, "key_numbers": ["1000 mg", "1500g", "250 mg", "3 tháng", "4 g", "40 mg", "8 g"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["RAU BONG NON", "Ths. Đinh Văn Hoành"], "bullets": []}, {"heading": "1. ĐẠI CƯƠNG", "paragraphs": ["Rau bong non là một cấp cứu sản khoa, là bệnh lý nặng toàn thân, biến chuyển nhanh chóng làm tử vong mẹ và con. Nguyên nhân là rau bám đúng chỗ song bị bong trước khi sổ thai do có sự hình thành khối huyết tụ sau rau. Khối huyết tụ lớn dần làm bong dần bánh rau, màng rau khỏi thành tử cung, cắt đứt sự trao đổi oxy giữa mẹ và con.", "Tỷ lệ gặp 0,6 - 1%. Rau bong non là nguyên nhân gây tử vong của 10 - 15% các trường hợp thai chết trong vòng 3 tháng cuối."], "bullets": []}, {"heading": "2. NGUYÊN NHÂN VÀ CÁC YẾU TỐ NGUY CƠ", "paragraphs": ["Nguyên nhân trực tiếp là sự phá vỡ của các mạch máu của niêm mạc tử cung nơi rau bám.", "Các yếu tố nguy cơ bao gồm:"], "bullets": ["- Tiền sản giật.", "- Sự căng giãn đột ngột quá mức của tử cung.", "- Những thương tổn của mạch máu tại bánh rau, tại vùng rau bám, xuất hiện trong các bệnh lý: rau tiền đạo, cao huyết áp, đái tháo đường.", "- Sự thay đổi thể tích đột ngột của tử cung như trường hợp chọc hút nước ối trong đa ối, hoặc song thai sau khi thai thứ nhất ra.", "- Dây rốn ngắn.", "- Sang chấn.", "- Thiếu acide folic, thường gặp ở những sản phụ có mức sống thấp.", "- Hút thuốc, sử dụng cocain.", "- Có tiền sử rau bong non.", "- Mẹ lớn tuổi."]}, {"heading": "3.1. Đại thể", "paragraphs": ["Cần chú ý tổn thương giải phẫu bệnh lý có khi không phù hợp với các thể lâm sàng. Trên lâm sàng có thể là bệnh cảnh nhẹ nhưng tổn thương giải phẫu bệnh lý lại nặng và ngược lại.", "Hình 1. Rau bong non"], "bullets": ["- Khối máu tụ sau rau: có thể nhỏ hoặc to từ 500 - 1500g, khối huyết tụ này làm bong dần bánh rau, nếu khối huyết tụ nhỏ rau bong ít, thai có thể sống. Nếu khối huyết tụ lớn làm rau bong hoàn toàn thì thai chết.", "- Bánh rau: mặt phía nội mạc bình thường, mặt về phía tử cung do khối máu tụ chèn ép bị lõm xuống.", "- Tử cung: các mạch máu ở vùng rau bám bị xung huyết và vỡ ra, tạo thành những mảng nhồi huyết ở tử cung, nhẹ thì chỉ có mảng nhồi huyết ở vùng rau bám, nặng thì nhồi huyết lan toả khắp tử cung, có khi tổn thương lan đến dây chằng rộng, các phần phụ và nhiều cơ quan khác, các ổ nhồi huyết sẽ làm tách các sợi cơ tử cung, dịch và máu sẽ thấm vào ổ bụng, cơ tử cung sẽ mất khả năng đàn hồi và khả năng co bóp, nên sau khi đẻ dễ bị đờ tử cung.", "- Các phần phụ và phủ tạng khác: trong các trường hợp nặng và rất nặng các tổn thương sẽ lan toả đến vòi trứng, buồng trứng, thận, gan, tuỵ tạng... các tổn thương nhồi huyết cũng giống như ở tử cung."]}, {"heading": "3.2. Vi thể", "paragraphs": ["Tổn thương vi thể thường là tổn thương các mạch máu, các mao mạch bị căng, vỡ, phù nề và xung huyết."], "bullets": []}, {"heading": "4. SINH LÝ BỆNH", "paragraphs": ["Sự hình thành khối máu tụ sau rau sẽ đưa đến các hậu quả:"], "bullets": []}, {"heading": "4.1. Về phía thai", "paragraphs": ["Nhanh chóng tạo nên tình trạng thiếu dưỡng khí do:"], "bullets": ["- Nơi rau bong làm cắt đứt một phần sự trao đổi dưỡng khí giữa mẹ và con.", "- Tử cung co cứng và tình trạng hạ huyết áp ở mẹ làm giảm lưu lượng máu từ tử cung qua rau."]}, {"heading": "4.2. Về phía mẹ", "paragraphs": ["Có thể xảy ra:"], "bullets": ["- Choáng do mất máu.", "- Tình trạng rối loạn đông máu: giảm hoặc mất hoàn toàn fibrinogen, hội chứng đông máu rải rác trong lòng mạch và hiện tượng tiêu fibrinogen thứ phát."]}, {"heading": "5.1.1. Toàn thân", "paragraphs": [], "bullets": ["- Choáng: bệnh nhân xanh, niêm mạc nhợt nhạt, hốt hoảng, thở nhanh, chân tay lạnh, mạch có thể chậm, huyết áp có thể bình thường hay giảm nhẹ."]}, {"heading": "5.1. 2.Cơ năng", "paragraphs": [], "bullets": ["- Đau bụng: thường đau nhiều, bắt đầu đau ở tử cung sau lan ra khắp bụng, bụng càng căng cứng, càng đau nhiều.", "- Chảy máu: âm đạo thường là máu loãng, không có máu cục."]}, {"heading": "5.1. 3.  Thực thể", "paragraphs": [". \t- Biến động tim thai tuỳ thuộc vào thể lâm sàng."], "bullets": ["- Dấu hiệu tiền sản giật: 60 - 70% các trường hợp rau bong non có tiền sản giật (phù, proteine niệu, cao huyết áp).", "- Tử cung co cứng liên tục, bề cao tử cung tăng dần theo thể tích khối máu tụ. Đo cơn co tử cung thường thấy trương lực cơ bản tăng.", "- Máu ra ở âm đạo thường là máu loãng, sẫm màu và không đông.", "- Khám âm đạo: đoạn dưới căng phồng, cổ tử cung giãn mỏng và cứng, có khi thấy đầu ối phồng căng, bấm ối nước ối màu hồng."]}, {"heading": "5.1. 3. Cận lâm sàng", "paragraphs": [], "bullets": ["- Công thức máu: hồng cầu, tiểu cầu, hematocrit giảm.", "- Monitoring: trương lực cơ bản tử cung tăng lên 3 - 4 lần so với bình thường.", "- Siêu âm: thấy khối máu tụ sau rau.", "- Fibrinogen: giảm hoặc không có."]}, {"heading": "5.2. Chẩn đoán xác định: dựa theo các thể lâm sàng.", "paragraphs": ["Còn gọi là phong huyết tử cung - rau hay hội chứng Couvelaire. Có đầy đủ các triệu chứng điển hình:", "Thể", "Choáng", "Chảy máu", "Tiền sản giật", "Trương lực cơ tử cung", "Fibrinogen", "Tim thai", "Thể ẩn", "Không thay đổi", "Bình thường", "Thể nhẹ", "(", "Cường tính", "Giảm nhẹ hoặc bình thường", "Thể trung bình", "Co cứng", "Giảm", "(", "Thể nặng", "Cứng như gỗ", "Giảm nhiều, thậm chí không còn", "Bảng 1. Các thể lâm sàng của rau bong non"], "bullets": ["- Thể ẩn: không thể phát hiện được trên lâm sàng trước khi đẻ, chỉ có thể phát hiện khi kiểm tra thấy cục máu sau rau. Đôi khi tình cờ phát hiện khi kiểm tra siêu âm trước đẻ.", "- Thể nhẹ:", "+ Toàn trạng bình thường, sản phụ không có biểu hiện choáng.", "+ Chảy máu âm đạo ít hoặc không có.", "+ Trương lực cơ tử cung có thể tăng nhẹ.", "+ Tim thai bình thường.", "+ Chưa có biểu hiện rối loạn đông chảy máu.", "+ Siêu âm: có thể có hình ảnh khối máu tụ sau rau.", "- Thể trung bình:", "+ Mạch nhanh, nhỏ, có thể hạ huyết áp.", "+ Chảy máu âm đạo có thể có hoặc không, máu loãng, sẫm màu, không đông.", "+ Trương lực cơ tử cung tăng, cơn co tử cung cường tính.", "+ Nhịp tim thai biểu hiện suy thai.", "+ Sinh sợi huyết giảm.", "- Thể nặng:", "+ Toàn thân biểu biện mất máu nặng.", "+ Thường có tiền sản giật.", "+ Chảy máu âm đạo không tương xứng với tình trạng mất máu toàn thân.", "+ Tử cung co cứng như gỗ và và đau liên tục.", "+ Không có tim thai.", "+ Có rối loạn đông máu, có thể chảy máu ở các phủ tạng như phổi, dạ dày, thận, buồng trứng, ruột, chảy máu những chỗ tiêm chích...", "+ Xét nghiệm sinh sợi huyết giảm hoặc không có, tiểu cầu giảm, hồng cầu và hematocrit giảm.", "-", "-", "-", "+", "-", "+", "+", "+", "++", "+", "+++", "+++", "+++", "-"]}, {"heading": "5.3. 1. Đa ối cấp", "paragraphs": ["Thường xảy ra vào ba tháng giữa, tử cung to nhanh, không có chảy máu, thai thường dị dạng. Nguy cơ rau bong non rất cao khi màng ối vỡ (do sự giảm nhanh thể tích buồng tử cung)."], "bullets": []}, {"heading": "5.3.2. Rau tiền đạo", "paragraphs": ["Tử cung không co cứng, tim thai có thể còn, không có rối loạn đông máu, sờ được bánh rau, không đau bụng, máu âm đạo tươi lẫn máu cục."], "bullets": []}, {"heading": "5.3.3. Vỡ tử cung", "paragraphs": ["Có dấu hiệu dọa vỡ hoặc vỡ tử cung, máu âm đạo tươi đi kèm triệu chứng chảy máu trong."], "bullets": []}, {"heading": "6.1.2. Thể nhẹ", "paragraphs": [], "bullets": ["- Tuyến cơ sở:", "+ Sơ cứu: giảm đau, giảm co: papaverin 40 mg (1 - 4 ống tiêm bắp).", "+ Chuyển tuyến chuyên khoa có nhân viên Y tế đi kèm.", "- Tuyến chuyên khoa:", "+ Giảm đau, an thần, giảm co (papaverin hoặc dolosal…)", "+ Sản khoa: bấm ối sớm, thúc đẩy cuộc đẻ kết thúc nhanh; nếu khó khăn thì chỉ định mổ lấy thai ngay.", "+ Ngoại khoa: trong mổ cần đánh giá sát tổn thương tại tử cung để có quyết định đúng đắn là bảo tồn tử cung hay phải cắt bán phần tử cung vì trong thể nhẹ triệu chứng lâm sàng đôi khi không rõ rệt, nhưng tổn thương tử cung lại nặng (không tương xứng với thể lâm sàng)."]}, {"heading": "6.1.3. Thể trung bình", "paragraphs": ["* Bù khối lượng tuần hoàn (truyền máu và dịch thay thế máu) bù điện giải, Cortison (sử dụng hydrocortison đường truyền tĩnh mạch...).", "* Kháng histamin tổng hợp và các thuốc phong bế thần kinh giao cảm.", "* Trợ tim.", "* E.A.C (4 - 8 g tiêm tĩnh mạch); transamin (250 mg - 1000 mg truyền tĩnh mạch).", "* Fibrinogen (2 - 4 g tiêm tĩnh mạch).", "Các trường hợp: CTC mở ít, nguy cơ diễn biến nặng lên phải chỉ định mổ ngay để cứu mẹ và con."], "bullets": ["- Tuyến cơ sở:", "+ Cấp cứu: giảm đau, giảm co, và lập đường truyền tĩnh mạch (dịch truyền tuỳ điều kiện cơ sở đang có sẵn).", "+ Chuyển ngay lên tuyến chuyên khoa có nhân viên Y tế đi kèm.", "- Tuyến chuyên khoa:", "+ Chống choáng:", "+ Chống rối loạn đông máu.", "+ Sản khoa:chỉ lấy thai ra khi CTC đã mở rộng, sau bấm ối ngôi thai tiến triển nhanh, thường đẻ dễ dàng...", "+ Ngoại khoa: sau khi mổ lấy thai cần đánh giá tổn thương thực thể tại tử cung để quyết định bảo tồn tử cung hay phải cắt bán phần để cầm máu."]}, {"heading": "5.1.4. Thể nặng", "paragraphs": ["Chú ý: Xử trí thể nặng phải nhanh chóng, phải tiến hành song song hồi sức chống sốc tích cực với mổ cắt tử cung.", "Hình 2.Rau bong non thể nặng"], "bullets": ["- Tuyến cơ sở: thực hiện song song 2 việc:", "+ Cấp cứu ngay khi bệnh nhân vào: thở oxy liên tục và thiết lập ngay đường truyền tĩnh mạch (bằng loại dịch truyền tại cơ sở đang có sẵn) và sử dụng các thuốc hồi sức, thuốc giảm đau, giảm co qua đường truyền tĩnh mạch.", "+ Mời ngay kíp mổ tuyến chuyên khoa về hồi sức và mổ cấp cứu tại chỗ, tránh vận chuyển bệnh nhân gây nặng hơn tình trạng sốc.", "- Tuyến chuyên khoa:", "+ Thở oxy liên tục", "+ Chống choáng tích cực bằng truyền máu tươi, dung dịch thay thế máu, bù điện giải, corticoid, kháng histamin tổng hợp, trợ tim, giảm đau... (liều trị như ở thể trung bình).", "+ Chống rối loạn đông máu: E.A.C, transamin, fibrinogen liên tục (tất cả tiêm theo đường tĩnh mạch như điều trị ở thể trung bình).", "+ Chống vô niệu bằng Lasix tiêm bắp hay tĩnh mạch liều cao.", "+ Chống nhiễm khuẩn bằng kháng sinh toàn thân phối hợp.", "+ Chỉ đinh mổ lấy thai nhanh (mặc dù con đã chết) và cắt ngay TC bán phần vì thường là tử cung đã tổn thương nặng (phải cắt tử cung tới hết vùng có nhồi huyết bầm tím)."]}, {"heading": "6.2. Xử trí sau đẻ", "paragraphs": ["Không thực hiện ở tuyến cơ sở mà chỉ thực hiện ở tuyến chuyên khoa."], "bullets": ["- Tiếp tục điều trị chống sốc cho mẹ và hồi sức sơ sinh (nếu con sống).", "- Theo dõi chảy máu sau đẻ, sau mổ đặc biệt khi còn để lại tử cung. Nếu thấy còn ra máu loãng thẫm màu liên tục chứng tỏ điều trị nội khoa chống đông máu không kết quả hoặc tử cung đã đờ không hồi phục thì phải chỉ định mổ lại cắt TC ngay để cầm máu.", "- Tiếp tục theo dõi chức năng gan thận để điều trị kịp thời khi có biến chứng.", "- Theo dõi tình trạng nhiễm khuẩn sau đẻ sau mổ để kịp thời điều chỉnh liều kháng sinh và phối hợp kháng sinh hợp lý."]}, {"heading": "7.1. Với tuyến cơ sở", "paragraphs": [], "bullets": ["- Truyền thông giáo dục SĐKH và Bảo vệ sức khoẻ sinh sản.", "- Tuyên truyền và tổ chức khám và quản lý thai nghén đúng, đầy đủ tại tuyến cơ sở.", "- Chuyển lên khám, theo dõi và đẻ tại tuyến trên những trờng hợp thai nghén có nguy cơ hoặc có những yếu tố thuận lợi dễ xảy ra rau bong non..."]}, {"heading": "7.2. Tuyến chuyên khoa: phòng các biến chứng nặng của rau bong non.", "paragraphs": [], "bullets": ["- Chẩn đoán sớm và phân loại đúng các thể lâm sàng rau bong non để cho xử trí nhanh chóng phù hợp và tích cực ngay từ đầu.", "- Cần có một bộ phận chuyên sâu về hồi sức tích cực với đầy đủ các phơng tiện: máy móc, thuốc men, dịch truyền, nguồn máu tươi dự trữ và nhân lực khi cấp cứu..."]}, {"heading": "8.1. Choáng", "paragraphs": ["Thường nặng, nhất là sau khi thai ra vì:"], "bullets": ["- Tử cung đang căng to được giải phóng đột ngột.", "- Chảy máu nhiều."]}, {"heading": "8.2. Chảy máu", "paragraphs": ["Do rối loạn đông chảy máu, giảm trầm trọng sinh sợi huyết."], "bullets": []}, {"heading": "8.3. Vô niệu", "paragraphs": [], "bullets": ["- Do thể tích máu giảm, huyết áp tụt làm giảm tưới máu cầu thận.", "- Thiếu oxy thận: do giảm tưới máu và co mạch, gây hoại tử vỏ thận."]}, {"heading": "8.4. Biến chứng khác", "paragraphs": ["Ngoài ra rau bong non có thể để lại các di chứng sau:"], "bullets": ["- Suy gan cấp.", "- Suy thận mạn.", "- Suy tuyến thượng thận.", "- Cao huyết áp."]}, {"heading": "5. Tử vong", "paragraphs": [], "bullets": ["- Tử vong sớm: gặp trong thể nặng không được xử trí kịp thời. Tử vong con 100%.", "- Tử vong muộn đối với mẹ: thường do biến chứng của một loạt các rối loạn suy chức năng các tạng (gan, thận), biến chứng tắc mạch..."]}], "raw_text": "RAU BONG NON\nThs. Đinh Văn Hoành\nMục tiêu học tập\n1.  Mô tả các dấu hiệu lâm sàng, cân lâm sàng để chẩn đoán xác định rau bong non.\n2. Trình bày xử trí cho từng thể lâm sàng rau bong non.\n3. Trình bày được tiến triển và biến chứng.\n1. ĐẠI CƯƠNG\nRau bong non là một cấp cứu sản khoa, là bệnh lý nặng toàn thân, biến chuyển nhanh chóng làm tử vong mẹ và con. Nguyên nhân là rau bám đúng chỗ song bị bong trước khi sổ thai do có sự hình thành khối huyết tụ sau rau. Khối huyết tụ lớn dần làm bong dần bánh rau, màng rau khỏi thành tử cung, cắt đứt sự trao đổi oxy giữa mẹ và con.\nTỷ lệ gặp 0,6 - 1%. Rau bong non là nguyên nhân gây tử vong của 10 - 15% các trường hợp thai chết trong vòng 3 tháng cuối.\n\n2. NGUYÊN NHÂN VÀ CÁC YẾU TỐ NGUY CƠ\nNguyên nhân trực tiếp là sự phá vỡ của các mạch máu của niêm mạc tử cung nơi rau bám.\nCác yếu tố nguy cơ bao gồm:\n- Tiền sản giật.\n- Sự căng giãn đột ngột quá mức của tử cung.\n- Những thương tổn của mạch máu tại bánh rau, tại vùng rau bám, xuất hiện trong các bệnh lý: rau tiền đạo, cao huyết áp, đái tháo đường.\n- Sự thay đổi thể tích đột ngột của tử cung như trường hợp chọc hút nước ối trong đa ối, hoặc song thai sau khi thai thứ nhất ra.\n- Dây rốn ngắn.\n- Sang chấn.\n- Thiếu acide folic, thường gặp ở những sản phụ có mức sống thấp.\n- Hút thuốc, sử dụng cocain.\n- Có tiền sử rau bong non.\n- Mẹ lớn tuổi.\n3. GIẢI PHẪU BỆNH\n3.1. Đại thể\nCần chú ý tổn thương giải phẫu bệnh lý có khi không phù hợp với các thể lâm sàng. Trên lâm sàng có thể là bệnh cảnh nhẹ nhưng tổn thương giải phẫu bệnh lý lại nặng và ngược lại.\n- Khối máu tụ sau rau: có thể nhỏ hoặc to từ 500 - 1500g, khối huyết tụ này làm bong dần bánh rau, nếu khối huyết tụ nhỏ rau bong ít, thai có thể sống. Nếu khối huyết tụ lớn làm rau bong hoàn toàn thì thai chết.\n- Bánh rau: mặt phía nội mạc bình thường, mặt về phía tử cung do khối máu tụ chèn ép bị lõm xuống.\n- Tử cung: các mạch máu ở vùng rau bám bị xung huyết và vỡ ra, tạo thành những mảng nhồi huyết ở tử cung, nhẹ thì chỉ có mảng nhồi huyết ở vùng rau bám, nặng thì nhồi huyết lan toả khắp tử cung, có khi tổn thương lan đến dây chằng rộng, các phần phụ và nhiều cơ quan khác, các ổ nhồi huyết sẽ làm tách các sợi cơ tử cung, dịch và máu sẽ thấm vào ổ bụng, cơ tử cung sẽ mất khả năng đàn hồi và khả năng co bóp, nên sau khi đẻ dễ bị đờ tử cung.\n- Các phần phụ và phủ tạng khác: trong các trường hợp nặng và rất nặng các tổn thương sẽ lan toả đến vòi trứng, buồng trứng, thận, gan, tuỵ tạng... các tổn thương nhồi huyết cũng giống như ở tử cung.\n\nHình 1. Rau bong non\n3.2. Vi thể\nTổn thương vi thể thường là tổn thương các mạch máu, các mao mạch bị căng, vỡ, phù nề và xung huyết.\n4. SINH LÝ BỆNH\nSự hình thành khối máu tụ sau rau sẽ đưa đến các hậu quả:\n4.1. Về phía thai\nNhanh chóng tạo nên tình trạng thiếu dưỡng khí do:\n- Nơi rau bong làm cắt đứt một phần sự trao đổi dưỡng khí giữa mẹ và con.\n- Tử cung co cứng và tình trạng hạ huyết áp ở mẹ làm giảm lưu lượng máu từ tử cung qua rau.\n4.2. Về phía mẹ\nCó thể xảy ra:\n- Choáng do mất máu.\n- Tình trạng rối loạn đông máu: giảm hoặc mất hoàn toàn fibrinogen, hội chứng đông máu rải rác trong lòng mạch và hiện tượng tiêu fibrinogen thứ phát.\n\n5. TRIỆU CHỨNG VÀ CHẨN ĐOÁN\n5.1. Triệu chứng\n5.1.1. Toàn thân\n- Choáng: bệnh nhân xanh, niêm mạc nhợt nhạt, hốt hoảng, thở nhanh, chân tay lạnh, mạch có thể chậm, huyết áp có thể bình thường hay giảm nhẹ.\n5.1. 2.Cơ năng\n- Đau bụng: thường đau nhiều, bắt đầu đau ở tử cung sau lan ra khắp bụng, bụng càng căng cứng, càng đau nhiều.\n- Chảy máu: âm đạo thường là máu loãng, không có máu cục.\n5.1. 3.  Thực thể\n- Dấu hiệu tiền sản giật: 60 - 70% các trường hợp rau bong non có tiền sản giật (phù, proteine niệu, cao huyết áp).\n- Tử cung co cứng liên tục, bề cao tử cung tăng dần theo thể tích khối máu tụ. Đo cơn co tử cung thường thấy trương lực cơ bản tăng.\n. \t- Biến động tim thai tuỳ thuộc vào thể lâm sàng.\n- Máu ra ở âm đạo thường là máu loãng, sẫm màu và không đông.\n- Khám âm đạo: đoạn dưới căng phồng, cổ tử cung giãn mỏng và cứng, có khi thấy đầu ối phồng căng, bấm ối nước ối màu hồng.\n5.1. 3. Cận lâm sàng\n- Công thức máu: hồng cầu, tiểu cầu, hematocrit giảm.\n- Monitoring: trương lực cơ bản tử cung tăng lên 3 - 4 lần so với bình thường.\n- Siêu âm: thấy khối máu tụ sau rau.\n- Fibrinogen: giảm hoặc không có.\n5.2. Chẩn đoán xác định: dựa theo các thể lâm sàng.\n- Thể ẩn: không thể phát hiện được trên lâm sàng trước khi đẻ, chỉ có thể phát hiện khi kiểm tra thấy cục máu sau rau. Đôi khi tình cờ phát hiện khi kiểm tra siêu âm trước đẻ.\n- Thể nhẹ:\n+ Toàn trạng bình thường, sản phụ không có biểu hiện choáng.\n+ Chảy máu âm đạo ít hoặc không có.\n+ Trương lực cơ tử cung có thể tăng nhẹ.\n+ Tim thai bình thường.\n+ Chưa có biểu hiện rối loạn đông chảy máu.\n+ Siêu âm: có thể có hình ảnh khối máu tụ sau rau.\n- Thể trung bình:\n+ Mạch nhanh, nhỏ, có thể hạ huyết áp.\n+ Chảy máu âm đạo có thể có hoặc không, máu loãng, sẫm màu, không đông.\n+ Trương lực cơ tử cung tăng, cơn co tử cung cường tính.\n+ Nhịp tim thai biểu hiện suy thai.\n+ Sinh sợi huyết giảm.\n- Thể nặng:\nCòn gọi là phong huyết tử cung - rau hay hội chứng Couvelaire. Có đầy đủ các triệu chứng điển hình:\n+ Toàn thân biểu biện mất máu nặng.\n+ Thường có tiền sản giật.\n+ Chảy máu âm đạo không tương xứng với tình trạng mất máu toàn thân.\n+ Tử cung co cứng như gỗ và và đau liên tục.\n+ Không có tim thai.\n+ Có rối loạn đông máu, có thể chảy máu ở các phủ tạng như phổi, dạ dày, thận, buồng trứng, ruột, chảy máu những chỗ tiêm chích...\n+ Xét nghiệm sinh sợi huyết giảm hoặc không có, tiểu cầu giảm, hồng cầu và hematocrit giảm.\nThể\nChoáng\nChảy máu\nTiền sản giật\nTrương lực cơ tử cung\nFibrinogen\nTim thai\n\nThể ẩn\n-\n-\n-\nKhông thay đổi\nBình thường\n+\n\nThể nhẹ\n-\n+\n(\nCường tính\nGiảm nhẹ hoặc bình thường\n+\n\n\nThể trung bình\n+\n++\n+\nCo cứng\nGiảm\n(\n\nThể nặng\n+++\n+++\n+++\nCứng như gỗ\nGiảm nhiều, thậm chí không còn\n-\n\nBảng 1. Các thể lâm sàng của rau bong non\n\n5.3. Chẩn đoán phân biệt\n5.3. 1. Đa ối cấp\nThường xảy ra vào ba tháng giữa, tử cung to nhanh, không có chảy máu, thai thường dị dạng. Nguy cơ rau bong non rất cao khi màng ối vỡ (do sự giảm nhanh thể tích buồng tử cung).\n5.3.2. Rau tiền đạo\nTử cung không co cứng, tim thai có thể còn, không có rối loạn đông máu, sờ được bánh rau, không đau bụng, máu âm đạo tươi lẫn máu cục.\n5.3.3. Vỡ tử cung\nCó dấu hiệu dọa vỡ hoặc vỡ tử cung, máu âm đạo tươi đi kèm triệu chứng chảy máu trong.\n\n6. THÁI ĐỘ XỬ TRÍ\n6.1. Xử trí trước đẻ\n6.1.1. Thể ẩn: thường không phát hiện trước nên không xử trí gì.\n6.1.2. Thể nhẹ\n- Tuyến cơ sở:\n+ Sơ cứu: giảm đau, giảm co: papaverin 40 mg (1 - 4 ống tiêm bắp).\n+ Chuyển tuyến chuyên khoa có nhân viên Y tế đi kèm.\n- Tuyến chuyên khoa:\n+ Giảm đau, an thần, giảm co (papaverin hoặc dolosal…)\n+ Sản khoa: bấm ối sớm, thúc đẩy cuộc đẻ kết thúc nhanh; nếu khó khăn thì chỉ định mổ lấy thai ngay.\n+ Ngoại khoa: trong mổ cần đánh giá sát tổn thương tại tử cung để có quyết định đúng đắn là bảo tồn tử cung hay phải cắt bán phần tử cung vì trong thể nhẹ triệu chứng lâm sàng đôi khi không rõ rệt, nhưng tổn thương tử cung lại nặng (không tương xứng với thể lâm sàng).\n6.1.3. Thể trung bình\n- Tuyến cơ sở:\n+ Cấp cứu: giảm đau, giảm co, và lập đường truyền tĩnh mạch (dịch truyền tuỳ điều kiện cơ sở đang có sẵn).\n+ Chuyển ngay lên tuyến chuyên khoa có nhân viên Y tế đi kèm.\n- Tuyến chuyên khoa:\n+ Chống choáng:\n* Bù khối lượng tuần hoàn (truyền máu và dịch thay thế máu) bù điện giải, Cortison (sử dụng hydrocortison đường truyền tĩnh mạch...).\n* Kháng histamin tổng hợp và các thuốc phong bế thần kinh giao cảm.\n* Trợ tim.\n+ Chống rối loạn đông máu.\n* E.A.C (4 - 8 g tiêm tĩnh mạch); transamin (250 mg - 1000 mg truyền tĩnh mạch).\n* Fibrinogen (2 - 4 g tiêm tĩnh mạch).\n+ Sản khoa:chỉ lấy thai ra khi CTC đã mở rộng, sau bấm ối ngôi thai tiến triển nhanh, thường đẻ dễ dàng...\nCác trường hợp: CTC mở ít, nguy cơ diễn biến nặng lên phải chỉ định mổ ngay để cứu mẹ và con.\n+ Ngoại khoa: sau khi mổ lấy thai cần đánh giá tổn thương thực thể tại tử cung để quyết định bảo tồn tử cung hay phải cắt bán phần để cầm máu.\n5.1.4. Thể nặng\n- Tuyến cơ sở: thực hiện song song 2 việc:\n+ Cấp cứu ngay khi bệnh nhân vào: thở oxy liên tục và thiết lập ngay đường truyền tĩnh mạch (bằng loại dịch truyền tại cơ sở đang có sẵn) và sử dụng các thuốc hồi sức, thuốc giảm đau, giảm co qua đường truyền tĩnh mạch.\n+ Mời ngay kíp mổ tuyến chuyên khoa về hồi sức và mổ cấp cứu tại chỗ, tránh vận chuyển bệnh nhân gây nặng hơn tình trạng sốc.\n- Tuyến chuyên khoa:\n+ Thở oxy liên tục\n+ Chống choáng tích cực bằng truyền máu tươi, dung dịch thay thế máu, bù điện giải, corticoid, kháng histamin tổng hợp, trợ tim, giảm đau... (liều trị như ở thể trung bình).\n+ Chống rối loạn đông máu: E.A.C, transamin, fibrinogen liên tục (tất cả tiêm theo đường tĩnh mạch như điều trị ở thể trung bình).\n+ Chống vô niệu bằng Lasix tiêm bắp hay tĩnh mạch liều cao.\n+ Chống nhiễm khuẩn bằng kháng sinh toàn thân phối hợp.\n+ Chỉ đinh mổ lấy thai nhanh (mặc dù con đã chết) và cắt ngay TC bán phần vì thường là tử cung đã tổn thương nặng (phải cắt tử cung tới hết vùng có nhồi huyết bầm tím).\nChú ý: Xử trí thể nặng phải nhanh chóng, phải tiến hành song song hồi sức chống sốc tích cực với mổ cắt tử cung.\n\nHình 2.Rau bong non thể nặng\n6.2. Xử trí sau đẻ\nKhông thực hiện ở tuyến cơ sở mà chỉ thực hiện ở tuyến chuyên khoa.\n- Tiếp tục điều trị chống sốc cho mẹ và hồi sức sơ sinh (nếu con sống).\n- Theo dõi chảy máu sau đẻ, sau mổ đặc biệt khi còn để lại tử cung. Nếu thấy còn ra máu loãng thẫm màu liên tục chứng tỏ điều trị nội khoa chống đông máu không kết quả hoặc tử cung đã đờ không hồi phục thì phải chỉ định mổ lại cắt TC ngay để cầm máu.\n- Tiếp tục theo dõi chức năng gan thận để điều trị kịp thời khi có biến chứng.\n- Theo dõi tình trạng nhiễm khuẩn sau đẻ sau mổ để kịp thời điều chỉnh liều kháng sinh và phối hợp kháng sinh hợp lý.\n\n7. DỰ PHÒNG\n7.1. Với tuyến cơ sở\n- Truyền thông giáo dục SĐKH và Bảo vệ sức khoẻ sinh sản.\n- Tuyên truyền và tổ chức khám và quản lý thai nghén đúng, đầy đủ tại tuyến cơ sở.\n- Chuyển lên khám, theo dõi và đẻ tại tuyến trên những trờng hợp thai nghén có nguy cơ hoặc có những yếu tố thuận lợi dễ xảy ra rau bong non...\n7.2. Tuyến chuyên khoa: phòng các biến chứng nặng của rau bong non.\n- Chẩn đoán sớm và phân loại đúng các thể lâm sàng rau bong non để cho xử trí nhanh chóng phù hợp và tích cực ngay từ đầu.\n- Cần có một bộ phận chuyên sâu về hồi sức tích cực với đầy đủ các phơng tiện: máy móc, thuốc men, dịch truyền, nguồn máu tươi dự trữ và nhân lực khi cấp cứu...\n8. BIẾN CHỨNG\n8.1. Choáng\nThường nặng, nhất là sau khi thai ra vì:\n- Tử cung đang căng to được giải phóng đột ngột.\n- Chảy máu nhiều.\n8.2. Chảy máu\nDo rối loạn đông chảy máu, giảm trầm trọng sinh sợi huyết.\n8.3. Vô niệu\n- Do thể tích máu giảm, huyết áp tụt làm giảm tưới máu cầu thận.\n- Thiếu oxy thận: do giảm tưới máu và co mạch, gây hoại tử vỏ thận.\n8.4. Biến chứng khác\nNgoài ra rau bong non có thể để lại các di chứng sau:\n- Suy gan cấp.\n- Suy thận mạn.\n- Suy tuyến thượng thận.\n- Cao huyết áp.\n5. Tử vong\n- Tử vong sớm: gặp trong thể nặng không được xử trí kịp thời. Tử vong con 100%.\n- Tử vong muộn đối với mẹ: thường do biến chứng của một loạt các rối loạn suy chức năng các tạng (gan, thận), biến chứng tắc mạch...\nCâu hỏi:\n1. Trình bày dấu hiệu lâm sàng chẩn đoán rau bong non?\n2.  Nêu chẩn đoán phân biệt rau bong non?\n3.  Nêu hướng xử trí rau bong non ở y tế tuyến cơ sở?", "priority": "Cao (Trọng tâm BSNT)"}, {"id": "SK-31", "chapter": "Chương 2. Sản bệnh", "folder": "02_San_benh", "title": "Đa thai", "author": "Ths. Bs CK II. Hoàng Tiến Nam", "word_count": 2683, "line_count": 117, "key_numbers": ["1 phút", "10 tuần", "100 cm", "10cm", "17 tuần", "3 tháng", "32 tuần", "40 cm", "6 tuần", "7 tháng"], "key_drugs": ["oxytocin"], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["ĐA THAI", "Ths. Bs CK II. Hoàng Tiến Nam"], "bullets": []}, {"heading": "1. ĐỊNH NGHĨA", "paragraphs": ["Sinh đôi (Song thai) là sự phát triển đồng thời hai thai trong lòng tử cung người mẹ. Sinh đôi chiếm tỷ lệ khoảng 1- 1,5% tổng số các trường hợp đẻ (1/80 trường hợp). Tuy nhiên hiện nay tỷ lệ này có xu hướng tăng lên cùng với sự phát triển của các phương tiện hỗ trợ sinh sản mới. Cũng như các trường hợp đa thai khác, sinh đôi là một thai nghén có nguy cơ bệnh lý và tử vong chu sản cao. Đặc điểm \"nguy cơ cao\" xảy ra ngay cả trong thời kỳ mang thai cũng như trong chuyển dạ đẻ."], "bullets": []}, {"heading": "2. PHÂN LOẠI", "paragraphs": ["Dựa vào nguồn gốc phát sinh có hai loại sinh đôi:"], "bullets": []}, {"heading": "2.1. Sinh đôi hai noãn (sinh đôi dị hợp tử)", "paragraphs": [], "bullets": ["- Sinh đôi hai noãn thường gặp hơn sinh đôi một noãn, tỷ lệ khoảng 65% - 70% tổng số sinh đôi. Nguyên nhân có thể do yếu tố dân tộc, di truyền, gia đình, con rạ đẻ nhiều lần, ngày nay do sử dụng các thuốc ngừa thai, thuốc kích thích rụng trứng trong hỗ trợ sinh sản nên tỷ lệ sinh sinh đôi tăng lên.", "- Nguồn gốc: Sinh đôi hai noãn còn gọi là sinh đôi dị hợp tử. Là kết quả của sự thụ tinh giữa hai tiểu noãn với hai tinh trùng riêng biệt để trở thành hai trứng. Do nguồn gốc phát sinh khác nhau, trẻ có thể khác giới hay cùng giới. Hai thai dù cùng giới nhưng không hoàn toàn giống nhau như trong sinh đôi một noãn", "- Bánh rau: Hai bánh rau riêng biệt hay đôi khi nằm gần với nhau nhưng hệ tuần hoàn riêng biệt và không lưu thông, hai nội sản mạc, hai trung sản mạc, ngoại sản mạc có thể chung cho cả hai  buồng ối hoặc riêng biệt."]}, {"heading": "2.2. Sinh đôi một noãn (sinh đôi đồng hợp tử)", "paragraphs": ["Bánh rau trong sinh đôi một noãn thường có các mạch máu nối thông với nhau. Có hai dạng nối thông là loại nối tiếp nông trên bề mặt nội sản mạc và loại mạch nối tiếp sâu ở trong bề dày của các múi rau, động mạch hệ này nối với tĩnh mạch hệ kia hoặc ngược lại. Do tính chất này mà hai thai sẽ liên quan chặt chẽ với nhau theo hình thức cho máu và nhận máu. Thông thường sự truyền máu cho nhận diễn ra cân bằng và hai thai phát triển bình thường như nhau. Đôi khi diễn ra  sự mất  cân  bằng  tuần  hoàn, một thai cho nhiều còn ngược lại thai kia nhận nhiều  sẽ dẫn đến tình trạng một thai teo đét, thậm chí chết lưu trong khi thai kia có thể phù to.", "Hình 1. Tóm tắt các dạng khác nhau của sinh đôi"], "bullets": ["- Sinh đôi một noãn hiếm gặp hơn, khoảng 1/250 trường hợp sinh, không có tính chất gia đình và di truyền, là kết quả của sự thụ tinh giữa một tiểu noãn và một tinh trùng duy nhất, nhưng trong quá trình phân bào của trứng do sự đột biến mà phát triển thành hai thai. Do có cùng nguồn gốc cho nên hai thai mang cùng tính chất di truyền, bao giờ cũng cùng giới, có thể giống nhau về hình thái cơ thể...", "- Bánh rau: tùy theo sự đột biến trong quá trình phân bào của trứng sớm hay muộn mà có 3 dạng khác nhau:", "+ Nếu sự phân bào xảy ra ở thời kỳ sau khi thành lập lá nuôi và trước thành lập buồng ối (ngày 4) thì sẽ có một bánh rau, một trung sản mạc, hai nội sản mạc. Một số  hiếm có thể xảy ra là hai bánh rau riêng biệt, hai trung sản mạc, hai nội sản mạc (1/10).", "+ Nếu sự phân bào xảy ra vào thời kỳ sau thành lập buồng ối (ngày thứ 7) sẽ có một bánh rau, một trung sản mạc, hai nội sản mạc (25- 30%), hai thai ở trong hai buồng ối nhưng nhận sư nuôi dưỡng từ một bánh rau chung.", "+ Nếu sự phân bào xảy ra từ ngày thứ 7- 13, sẽ có hai thai chung nhau một bánh rau, cùng chung một buồng ối.", "+ Nếu sự phân chia xảy ra muộn sẽ có nhiều nguy cơ hai thai dính nhau, chung tạng, quái thai. Trường hợp này rất hiếm gặp (3%)."]}, {"heading": "3. ĐẶC ĐIỂM SINH ĐÔI", "paragraphs": [], "bullets": ["- Tỷ lệ thai bệnh lý và tử vong chu sản cao 7% - 10%.", "-  Nguy cơ tử vong chu sản chủ yếu là đẻ non.", "- Tỷ lệ dị tật bẩm sinh ở sinh đôi đồng hợp tử cao hơn sinh đôi dị hợp tử.", "-  Trong chuyển dạ, sinh đôi đồng hợp tử có nguy cơ cao hơn sinh đôi dị hợp tử.", "- Có khả năng xảy ra sự bất cân bằng tuần hoàn trong truyền máu cho nhận."]}, {"heading": "4. TRIỆU CHỨNG HỌC VÀ CHẨN ĐOÁN", "paragraphs": ["Cần phải phát hiện, chẩn đoán sớm bởi vì tiên lượng của nó một phần liên quan đến sự chẩn đoán này."], "bullets": []}, {"heading": "4.1. Hỏi", "paragraphs": [], "bullets": ["- Tiền sử gia đình bên vợ hay chồng có người sinh đôi hoặc đa thai không. Nếu sản phụ sinh con rạ thì các lần trước đã có lần nào sinh đôi chưa.", "- Tiền sử sản phụ có sử dụng thuốc ngừa thai, hoặc thuốc kích thích rụng trứng trong điều trị vô sinh không, loại thuốc nào."]}, {"heading": "4.2. Cơ năng", "paragraphs": [], "bullets": ["- Dấu hiệu nghén : Thai phụ có dấu hiệu nghén nhiều  hơn bình thường so với lần thai trước hoặc so với người cùng có thai. Phù sớm và nhiều do tử cung to chèn ép tuần hoàn chi dưới. Sản phụ mệt mỏi, đi lại khó khăn.", "- Tử cung to nhanh làm thai phụ có thể cảm thấy khó thở do cơ hoành bị đẩy lên.", "- Thai máy ở nhiều nơi trên tử cung, khắp ổ bụng."]}, {"heading": "4.3. Thực thể", "paragraphs": ["Ngoài việc chẩn đoán xác định sinh đôi thì việc xác định tư thế của hai thai trong buồng tử cung cũng rất quan trọng. Tỷ lệ các ngôi thường gặp là:", "Hình 2. Các ngôi kết hợp trong song thai"], "bullets": ["- Nhìn thấy bụng to, thành bụng căng, có nhiều vết rạn. Hai chân phù to, trắng mọng, đôi khi phù lên tới bụng.", "- Đo chiều cao tử cung lớn hơn tuổi thai. Khi thai đủ tháng chiều cao tử cung có thể tới 35 - 40 cm trên vệ, vòng bụng có thể tới 100 cm hoặc hơn.", "- Nắn khó thấy đủ cả bốn cực. Thường nắn thấy ba cực, hai cực đầu một cực mông hoặc hai cực  mông một cực đầu. Nếu chỉ nắn thấy hai cực thì hai cực đó phải là hai cực đầu hoặc hai mông. Đôi khi không nắn rõ được cực nào mà chỉ thấy được nhiều chi.", "- Nghe: Nghe được hai ổ tim thai riêng biệt, tần số hai ổ tim thai chênh lệch hơn nhau 10 nhịp/1 phút. Khoảng cách giữa hai ổ tim thai trên 10cm.", "- Khám trong giúp khẳng định kết quả khám ngoài. Khám trong xác định được một cực của thai ngoài một cực đã xác định khi khám ngoài.", "+ Hai ngôi chỏm: 50%\tMột ngôi chỏm, một ngôi mông: 35%", "+ Hai ngôi mông: 10%\tMột ngôi chỏm, một ngôi vai: 3%", "+ Một ngôi mông, một ngôi vai: 2%"]}, {"heading": "4.4. Các phương pháp thăm dò khác", "paragraphs": [], "bullets": ["- Chụp X quang bụng: Có hình ảnh 2 đầu, 2 cột sống của thai nhi. Tuy nhiên thai dễ bị nhiễm tia X, nên cần hạn chế chụp phim. Chỉ chụp khi thai nhi đã trên  7 tháng.", "- Siêu âm: Có thể phát hiện sinh đôi sớm. Chẩn đoán sinh đôi ở giai đoạn đầu dễ dàng vì ở giai đoạn này màng đệm thấy rõ, tạo thành vòng dày khác với màng ối mỏng và thưa âm vang hơn. Thai 6 tuần tuổi: Thấy  hai túi ối. Thai 10 tuần : Thấy hai túi thai, hai ổ tim thai. Thai > 17 tuần: Đo đường kính lưỡng đỉnh của mỗi thai nhi, trên siêu âm có thể theo dõi sự phát triển khác nhau của từng thai. Dấu hiệu dư ối thường gặp trong sinh đôi."]}, {"heading": "4.5.1. Thai to", "paragraphs": ["Chỉ nắn thấy hai cực đầu và mông,  nghe một ổ tim thai.."], "bullets": []}, {"heading": "4.5.2. Một thai - đa ối", "paragraphs": ["Trong sinh đôi, tỷ lệ dư ối khoảng 10%, thành tử cung căng, mềm, khó nắn  được các cực của thai, nghe tiếng tim thai nhỏ, xa xăm."], "bullets": []}, {"heading": "4.5.3. Một thai và một khối  u  buồng trứng hoặc u xơ tử cung", "paragraphs": ["Khi nắn dễ nhầm khối u là 1 cực của thai. U xơ tử cung thường có tiền sử rối loạn kinh nguyệt, hơn nữa trong cơn co các phần thai khó xác định được còn u xơ tử cung vẫn nắn thấy rõ."], "bullets": []}, {"heading": "4.6.1. Trong thai kỳ", "paragraphs": ["ư Sẩy thai, đẻ non:  Là một biến chứng thường gặp, nguy cơ đẻ non cao gấp 6 lần thai thường (khoảng 15ư30% cỏc trường hợp sinh đụi bị đẻ non trong đú ùkhoảng 8% trước 32 tuần). Tỷ lệ tử vong chu sản và thai bệnh lý cao cũng do thai non yếu."], "bullets": ["- Tiền sản giật: Xảy ra thường xuyên và sớm hơn các trường hợp một thai.", "- Đa ối: Thường xảy ra vào thời kỳ cuối của 3 tháng giữa thai kỳ. Hay gặp ở trường hợp sinh đôi một bánh rau, bất cân bằng tuần hoàn giữa hai thai.", "- Hội chứng truyền máu cho nhận: Chẩn đoán hội chứng truyền máu cho nhận thường bắt đầu từ tuần thứ 22 -24. Thai nhận có tình trạng đa ối, thai cho thì thiểu ối.", "- Thai chậm phát triển trong tử cung: Là nguy cơ đứng thứ hai sau đẻ non, tỷ lệ gặp gấp 10 lần một thai. Hơn 50% trường hợp thai chết trong tử cung là hậu quả của thai chậm phát triển trong tử cung hoặc do sự bất cân bằng tuần hoàn hai thai.", "- Rau bám thấp: Là do sự tăng bề mặt của bánh rau, nó làm tăng nguy cơ đẻ non, chảy máu do bong rau, ngôi thai bất thường.", "- Thai dị dạng: Nguy cơ thai dị dạng 2% trong sinh đôi, đặc biệt là sinh đôi đồng hợp tử  (10%)", "- Thiếu máu: 3,2% trường hợp"]}, {"heading": "4.6.2. Trong chuyển dạ", "paragraphs": [], "bullets": ["- Đẻ khó do cơn go tử cung", "- Sa dây rốn", "- Đẻ khó thai thứ hai", "- Hai thai mắc nhau", "- Sang chấn sản khoa", "- Đờ tử cung sau đẻ"]}, {"heading": "5.1. Trong thời kỳ mang thai", "paragraphs": ["Việc theo dõi thai phụ và phát hiện các nguy cơ trong sinh đôi có thể được tiến hành ở tuyến xã, tuy nhiên không nên đỡ đẻ sinh đôi ở tuyến xã mà phải chuyển lên các tuyến trên."], "bullets": ["- Theo dõi, đánh giá sự phát triển của thai định kỳ, phát hiện sớm các nguy cơ cho thai và người mẹ. Bảo đảm vệ sinh thai nghén, chế độ dinh dưỡng,", "- Dự phòng hiện tượng đẻ non: Phải có một chế độ nghỉ ngơi thích hợp cho thai phụ, tránh lao động và di chuyển nhiều trong thời kỳ mang thai.", "- Cần phát hiện sớm và điều trị kịp thời khi có hiện tượng chuyển dạ đẻ non: Theo dõi và điều trị tại bệnh viện, nằm nghỉ tuyệt đối, dùng các thuốc giảm co, utrogestan, acid folic, sắt, vitamin D."]}, {"heading": "5.2.1. Nguyên tắc chung trong đẻ sinh đôi", "paragraphs": [], "bullets": ["- Kíp đỡ đẻ và săn sóc phải có ít nhất hai người trở lên. Tốt nhất nên có một nhà sản khoa, một bác sĩ nhi sơ sinh và một gây mê hồi sức.", "- Trong quá trình chuyển dạ luôn theo dõi tình trạng sức khỏe của người mẹ và hai thai, nhất là thai nhi thứ hai. Phát hiện kịp thời nguy cơ suy thai và có biện pháp xử trí thích hợp. Do tử cung quá căng nên cơn co tử cung thường yếu và thưa, cổ tử cung mở chậm. Nếu đủ điều kiện có thể bấm ối cho tử cung bớt căng, điều chỉnh  cơn co tử cung để chuyển dạ tiến triển tốt hơn."]}, {"heading": "5.2.2. Diễn tiến cuộc đẻ", "paragraphs": ["Thông thường cuộc đẻ diễn ra qua 4 giai đoạn:", "Tùy theo thai thứ hai ngôi gì mà có hướng xử trí thích hợp. Nếu ngôi vai thì bấm ối, nội xoay thai tìm chân kéo thai ra ngay. Nếu là ngôi dọc, ngôi có thể là thuận hay ngược, tôn trọng thời gian nghỉ ngơi sinh lý  chờ có cơn go xuất hiện thì bấm ối cố định ngôi thai và sinh thường. Nếu cơn co tử cung yếu thì truyền oxytocin.", "Thường hai bánh rau cùng sổ một lúc hoặc liên tiếp sổ sau khi đẻ thai thứ hai. Nhưng cũng có trường hợp hai bánh rau đều bong khi thai thứ hai chưa sổ làm thai thứ hai chết. Trong thời kỳ sổ rau dễ có biến chứng chảy máu do đờ tử cung, do đó phải dùng thuốc co bóp tử cung ngay và duy trì nhỏ giọt tĩnh mạch. Sau đẻ cần kiểm tra bánh rau để chẩn đoán sinh đôi một noãn hay hai noãn"], "bullets": ["- Giai đoạn 1: Đẻ thai nhi thứ nhất: Thai thứ nhất thường là ngôi thuận, đôi khi là ngôi mông. Thường ngôi lọt chậm, cơn co yếu. Nếu là ngôi chỏm thì đỡ đẻ như bình thường, chú khi khi ối vỡ dễ gây sa dây rốn. Sau khi thai sổ kẹp chặt dây rốn trước khi cắt để ngăn ngừa mất máu của thai thứ hai nếu có tuần hoàn nối thông.", "- Giai đoạn 2: Sau khi thai thứ nhất sổ, buồng tử cung trở thành quá rộng đối với thai thứ hai làm cho thai không bình chỉnh tốt, dễ sinh ra ngôi bất thường như ngôi vai, ngôi mông. Vì vậy cần kiểm tra ngay ngôi, thế và tình trạng tim thai của thai thứ hai. Chú ý rằng thai thứ hai luôn bị đe dọa trước nguy cơ thiếu oxy.", "- Giai đoạn 3: Đẻ thai thứ hai", "- Giai đoạn 4: Sổ rau"]}, {"heading": "5.3. Thời kỳ hậu sản", "paragraphs": ["Cần theo dõi sát sản phụ những giờ đầu sau đẻ vì dễ xảy ra chảy máu do đờ tử cung thứ phát. Bảo đảm tốt chế độ dinh dưỡng để tạo cho sản phụ khả năng nhanh chóng phục hồi sức khỏe và có đủ sữa nuôi hai con."], "bullets": []}, {"heading": "VI.  CHỈ ĐỊNH MỔ LẤY THAI TRONG SINH ĐÔI", "paragraphs": [], "bullets": ["- Hai cực đầu của hai thai cùng xuống một lúc, chèn ép rau.", "- Thai thứ nhất là ngôi mông, thai thứ hai  thuận (hai thai có thể mắc nhau).", "- Thai thứ nhất ngôi vai.", "- Thai thứ nhất  bị suy thai, sa dây rau không đẩy lên  được.", "- Sinh đôi hai thai dính nhau.", "- Rau tiền đạo, tử cung có sẹo mổ cũ, con so lớn tuổi."]}], "raw_text": "ĐA THAI\nThs. Bs CK II. Hoàng Tiến Nam\n\nMục tiêu học tập\n1. Phân biệt được sinh đôi đồng hợp tử và sinh đôi dị hợp tử.\n2. Phân tích được các nguy cơ cao cho thai nhi và thai phụ đẻ sinh đôi.\n3. Khám và phát hiện được một trường hợp sinh đôi.\n4. Theo dõi và xử trí được một trường hợp sinh đôi.\n\n1. ĐỊNH NGHĨA\nSinh đôi (Song thai) là sự phát triển đồng thời hai thai trong lòng tử cung người mẹ. Sinh đôi chiếm tỷ lệ khoảng 1- 1,5% tổng số các trường hợp đẻ (1/80 trường hợp). Tuy nhiên hiện nay tỷ lệ này có xu hướng tăng lên cùng với sự phát triển của các phương tiện hỗ trợ sinh sản mới. Cũng như các trường hợp đa thai khác, sinh đôi là một thai nghén có nguy cơ bệnh lý và tử vong chu sản cao. Đặc điểm \"nguy cơ cao\" xảy ra ngay cả trong thời kỳ mang thai cũng như trong chuyển dạ đẻ.\n\n2. PHÂN LOẠI\nDựa vào nguồn gốc phát sinh có hai loại sinh đôi:\n2.1. Sinh đôi hai noãn (sinh đôi dị hợp tử)\n- Sinh đôi hai noãn thường gặp hơn sinh đôi một noãn, tỷ lệ khoảng 65% - 70% tổng số sinh đôi. Nguyên nhân có thể do yếu tố dân tộc, di truyền, gia đình, con rạ đẻ nhiều lần, ngày nay do sử dụng các thuốc ngừa thai, thuốc kích thích rụng trứng trong hỗ trợ sinh sản nên tỷ lệ sinh sinh đôi tăng lên.\n- Nguồn gốc: Sinh đôi hai noãn còn gọi là sinh đôi dị hợp tử. Là kết quả của sự thụ tinh giữa hai tiểu noãn với hai tinh trùng riêng biệt để trở thành hai trứng. Do nguồn gốc phát sinh khác nhau, trẻ có thể khác giới hay cùng giới. Hai thai dù cùng giới nhưng không hoàn toàn giống nhau như trong sinh đôi một noãn\n- Bánh rau: Hai bánh rau riêng biệt hay đôi khi nằm gần với nhau nhưng hệ tuần hoàn riêng biệt và không lưu thông, hai nội sản mạc, hai trung sản mạc, ngoại sản mạc có thể chung cho cả hai  buồng ối hoặc riêng biệt.\n2.2. Sinh đôi một noãn (sinh đôi đồng hợp tử)\n- Sinh đôi một noãn hiếm gặp hơn, khoảng 1/250 trường hợp sinh, không có tính chất gia đình và di truyền, là kết quả của sự thụ tinh giữa một tiểu noãn và một tinh trùng duy nhất, nhưng trong quá trình phân bào của trứng do sự đột biến mà phát triển thành hai thai. Do có cùng nguồn gốc cho nên hai thai mang cùng tính chất di truyền, bao giờ cũng cùng giới, có thể giống nhau về hình thái cơ thể...\n- Bánh rau: tùy theo sự đột biến trong quá trình phân bào của trứng sớm hay muộn mà có 3 dạng khác nhau:\n+ Nếu sự phân bào xảy ra ở thời kỳ sau khi thành lập lá nuôi và trước thành lập buồng ối (ngày 4) thì sẽ có một bánh rau, một trung sản mạc, hai nội sản mạc. Một số  hiếm có thể xảy ra là hai bánh rau riêng biệt, hai trung sản mạc, hai nội sản mạc (1/10).\n+ Nếu sự phân bào xảy ra vào thời kỳ sau thành lập buồng ối (ngày thứ 7) sẽ có một bánh rau, một trung sản mạc, hai nội sản mạc (25- 30%), hai thai ở trong hai buồng ối nhưng nhận sư nuôi dưỡng từ một bánh rau chung.\n+ Nếu sự phân bào xảy ra từ ngày thứ 7- 13, sẽ có hai thai chung nhau một bánh rau, cùng chung một buồng ối.\n+ Nếu sự phân chia xảy ra muộn sẽ có nhiều nguy cơ hai thai dính nhau, chung tạng, quái thai. Trường hợp này rất hiếm gặp (3%).\nBánh rau trong sinh đôi một noãn thường có các mạch máu nối thông với nhau. Có hai dạng nối thông là loại nối tiếp nông trên bề mặt nội sản mạc và loại mạch nối tiếp sâu ở trong bề dày của các múi rau, động mạch hệ này nối với tĩnh mạch hệ kia hoặc ngược lại. Do tính chất này mà hai thai sẽ liên quan chặt chẽ với nhau theo hình thức cho máu và nhận máu. Thông thường sự truyền máu cho nhận diễn ra cân bằng và hai thai phát triển bình thường như nhau. Đôi khi diễn ra  sự mất  cân  bằng  tuần  hoàn, một thai cho nhiều còn ngược lại thai kia nhận nhiều  sẽ dẫn đến tình trạng một thai teo đét, thậm chí chết lưu trong khi thai kia có thể phù to.\n\n\n\nHình 1. Tóm tắt các dạng khác nhau của sinh đôi\n\n3. ĐẶC ĐIỂM SINH ĐÔI\n- Tỷ lệ thai bệnh lý và tử vong chu sản cao 7% - 10%.\n-  Nguy cơ tử vong chu sản chủ yếu là đẻ non.\n- Tỷ lệ dị tật bẩm sinh ở sinh đôi đồng hợp tử cao hơn sinh đôi dị hợp tử.\n-  Trong chuyển dạ, sinh đôi đồng hợp tử có nguy cơ cao hơn sinh đôi dị hợp tử.\n- Có khả năng xảy ra sự bất cân bằng tuần hoàn trong truyền máu cho nhận.\n\n4. TRIỆU CHỨNG HỌC VÀ CHẨN ĐOÁN\nCần phải phát hiện, chẩn đoán sớm bởi vì tiên lượng của nó một phần liên quan đến sự chẩn đoán này.\n4.1. Hỏi\n- Tiền sử gia đình bên vợ hay chồng có người sinh đôi hoặc đa thai không. Nếu sản phụ sinh con rạ thì các lần trước đã có lần nào sinh đôi chưa.\n- Tiền sử sản phụ có sử dụng thuốc ngừa thai, hoặc thuốc kích thích rụng trứng trong điều trị vô sinh không, loại thuốc nào.\n4.2. Cơ năng\n- Dấu hiệu nghén : Thai phụ có dấu hiệu nghén nhiều  hơn bình thường so với lần thai trước hoặc so với người cùng có thai. Phù sớm và nhiều do tử cung to chèn ép tuần hoàn chi dưới. Sản phụ mệt mỏi, đi lại khó khăn.\n- Tử cung to nhanh làm thai phụ có thể cảm thấy khó thở do cơ hoành bị đẩy lên.\n- Thai máy ở nhiều nơi trên tử cung, khắp ổ bụng.\n4.3. Thực thể\n- Nhìn thấy bụng to, thành bụng căng, có nhiều vết rạn. Hai chân phù to, trắng mọng, đôi khi phù lên tới bụng.\n- Đo chiều cao tử cung lớn hơn tuổi thai. Khi thai đủ tháng chiều cao tử cung có thể tới 35 - 40 cm trên vệ, vòng bụng có thể tới 100 cm hoặc hơn.\n- Nắn khó thấy đủ cả bốn cực. Thường nắn thấy ba cực, hai cực đầu một cực mông hoặc hai cực  mông một cực đầu. Nếu chỉ nắn thấy hai cực thì hai cực đó phải là hai cực đầu hoặc hai mông. Đôi khi không nắn rõ được cực nào mà chỉ thấy được nhiều chi.\n- Nghe: Nghe được hai ổ tim thai riêng biệt, tần số hai ổ tim thai chênh lệch hơn nhau 10 nhịp/1 phút. Khoảng cách giữa hai ổ tim thai trên 10cm.\n- Khám trong giúp khẳng định kết quả khám ngoài. Khám trong xác định được một cực của thai ngoài một cực đã xác định khi khám ngoài.\nNgoài việc chẩn đoán xác định sinh đôi thì việc xác định tư thế của hai thai trong buồng tử cung cũng rất quan trọng. Tỷ lệ các ngôi thường gặp là:\n+ Hai ngôi chỏm: 50%\tMột ngôi chỏm, một ngôi mông: 35%\n+ Hai ngôi mông: 10%\tMột ngôi chỏm, một ngôi vai: 3%\n+ Một ngôi mông, một ngôi vai: 2%\n\nHình 2. Các ngôi kết hợp trong song thai\n4.4. Các phương pháp thăm dò khác\n- Chụp X quang bụng: Có hình ảnh 2 đầu, 2 cột sống của thai nhi. Tuy nhiên thai dễ bị nhiễm tia X, nên cần hạn chế chụp phim. Chỉ chụp khi thai nhi đã trên  7 tháng.\n- Siêu âm: Có thể phát hiện sinh đôi sớm. Chẩn đoán sinh đôi ở giai đoạn đầu dễ dàng vì ở giai đoạn này màng đệm thấy rõ, tạo thành vòng dày khác với màng ối mỏng và thưa âm vang hơn. Thai 6 tuần tuổi: Thấy  hai túi ối. Thai 10 tuần : Thấy hai túi thai, hai ổ tim thai. Thai > 17 tuần: Đo đường kính lưỡng đỉnh của mỗi thai nhi, trên siêu âm có thể theo dõi sự phát triển khác nhau của từng thai. Dấu hiệu dư ối thường gặp trong sinh đôi.\n4.5. Chẩn đoán phân biệt\n4.5.1. Thai to\nChỉ nắn thấy hai cực đầu và mông,  nghe một ổ tim thai..\n4.5.2. Một thai - đa ối\nTrong sinh đôi, tỷ lệ dư ối khoảng 10%, thành tử cung căng, mềm, khó nắn  được các cực của thai, nghe tiếng tim thai nhỏ, xa xăm.\n4.5.3. Một thai và một khối  u  buồng trứng hoặc u xơ tử cung\nKhi nắn dễ nhầm khối u là 1 cực của thai. U xơ tử cung thường có tiền sử rối loạn kinh nguyệt, hơn nữa trong cơn co các phần thai khó xác định được còn u xơ tử cung vẫn nắn thấy rõ.\n4.6. Tiến triển và các nguy cơ của sinh đôi\n4.6.1. Trong thai kỳ\nư Sẩy thai, đẻ non:  Là một biến chứng thường gặp, nguy cơ đẻ non cao gấp 6 lần thai thường (khoảng 15ư30% cỏc trường hợp sinh đụi bị đẻ non trong đú ùkhoảng 8% trước 32 tuần). Tỷ lệ tử vong chu sản và thai bệnh lý cao cũng do thai non yếu.\n- Tiền sản giật: Xảy ra thường xuyên và sớm hơn các trường hợp một thai.\n- Đa ối: Thường xảy ra vào thời kỳ cuối của 3 tháng giữa thai kỳ. Hay gặp ở trường hợp sinh đôi một bánh rau, bất cân bằng tuần hoàn giữa hai thai.\n- Hội chứng truyền máu cho nhận: Chẩn đoán hội chứng truyền máu cho nhận thường bắt đầu từ tuần thứ 22 -24. Thai nhận có tình trạng đa ối, thai cho thì thiểu ối.\n- Thai chậm phát triển trong tử cung: Là nguy cơ đứng thứ hai sau đẻ non, tỷ lệ gặp gấp 10 lần một thai. Hơn 50% trường hợp thai chết trong tử cung là hậu quả của thai chậm phát triển trong tử cung hoặc do sự bất cân bằng tuần hoàn hai thai.\n- Rau bám thấp: Là do sự tăng bề mặt của bánh rau, nó làm tăng nguy cơ đẻ non, chảy máu do bong rau, ngôi thai bất thường.\n- Thai dị dạng: Nguy cơ thai dị dạng 2% trong sinh đôi, đặc biệt là sinh đôi đồng hợp tử  (10%)\n- Thiếu máu: 3,2% trường hợp\n4.6.2. Trong chuyển dạ\n- Đẻ khó do cơn go tử cung\n- Sa dây rốn\n- Đẻ khó thai thứ hai\n- Hai thai mắc nhau\n- Sang chấn sản khoa\n- Đờ tử cung sau đẻ\n5. THÁI ĐỘ XỬ TRÍ\n5.1. Trong thời kỳ mang thai\n- Theo dõi, đánh giá sự phát triển của thai định kỳ, phát hiện sớm các nguy cơ cho thai và người mẹ. Bảo đảm vệ sinh thai nghén, chế độ dinh dưỡng,\n- Dự phòng hiện tượng đẻ non: Phải có một chế độ nghỉ ngơi thích hợp cho thai phụ, tránh lao động và di chuyển nhiều trong thời kỳ mang thai.\n- Cần phát hiện sớm và điều trị kịp thời khi có hiện tượng chuyển dạ đẻ non: Theo dõi và điều trị tại bệnh viện, nằm nghỉ tuyệt đối, dùng các thuốc giảm co, utrogestan, acid folic, sắt, vitamin D.\nViệc theo dõi thai phụ và phát hiện các nguy cơ trong sinh đôi có thể được tiến hành ở tuyến xã, tuy nhiên không nên đỡ đẻ sinh đôi ở tuyến xã mà phải chuyển lên các tuyến trên.\n5.2. Khi chuyển dạ\n5.2.1. Nguyên tắc chung trong đẻ sinh đôi\n- Kíp đỡ đẻ và săn sóc phải có ít nhất hai người trở lên. Tốt nhất nên có một nhà sản khoa, một bác sĩ nhi sơ sinh và một gây mê hồi sức.\n- Trong quá trình chuyển dạ luôn theo dõi tình trạng sức khỏe của người mẹ và hai thai, nhất là thai nhi thứ hai. Phát hiện kịp thời nguy cơ suy thai và có biện pháp xử trí thích hợp. Do tử cung quá căng nên cơn co tử cung thường yếu và thưa, cổ tử cung mở chậm. Nếu đủ điều kiện có thể bấm ối cho tử cung bớt căng, điều chỉnh  cơn co tử cung để chuyển dạ tiến triển tốt hơn.\n5.2.2. Diễn tiến cuộc đẻ\nThông thường cuộc đẻ diễn ra qua 4 giai đoạn:\n- Giai đoạn 1: Đẻ thai nhi thứ nhất: Thai thứ nhất thường là ngôi thuận, đôi khi là ngôi mông. Thường ngôi lọt chậm, cơn co yếu. Nếu là ngôi chỏm thì đỡ đẻ như bình thường, chú khi khi ối vỡ dễ gây sa dây rốn. Sau khi thai sổ kẹp chặt dây rốn trước khi cắt để ngăn ngừa mất máu của thai thứ hai nếu có tuần hoàn nối thông.\n- Giai đoạn 2: Sau khi thai thứ nhất sổ, buồng tử cung trở thành quá rộng đối với thai thứ hai làm cho thai không bình chỉnh tốt, dễ sinh ra ngôi bất thường như ngôi vai, ngôi mông. Vì vậy cần kiểm tra ngay ngôi, thế và tình trạng tim thai của thai thứ hai. Chú ý rằng thai thứ hai luôn bị đe dọa trước nguy cơ thiếu oxy.\n- Giai đoạn 3: Đẻ thai thứ hai\nTùy theo thai thứ hai ngôi gì mà có hướng xử trí thích hợp. Nếu ngôi vai thì bấm ối, nội xoay thai tìm chân kéo thai ra ngay. Nếu là ngôi dọc, ngôi có thể là thuận hay ngược, tôn trọng thời gian nghỉ ngơi sinh lý  chờ có cơn go xuất hiện thì bấm ối cố định ngôi thai và sinh thường. Nếu cơn co tử cung yếu thì truyền oxytocin.\n- Giai đoạn 4: Sổ rau\nThường hai bánh rau cùng sổ một lúc hoặc liên tiếp sổ sau khi đẻ thai thứ hai. Nhưng cũng có trường hợp hai bánh rau đều bong khi thai thứ hai chưa sổ làm thai thứ hai chết. Trong thời kỳ sổ rau dễ có biến chứng chảy máu do đờ tử cung, do đó phải dùng thuốc co bóp tử cung ngay và duy trì nhỏ giọt tĩnh mạch. Sau đẻ cần kiểm tra bánh rau để chẩn đoán sinh đôi một noãn hay hai noãn\n5.3. Thời kỳ hậu sản\nCần theo dõi sát sản phụ những giờ đầu sau đẻ vì dễ xảy ra chảy máu do đờ tử cung thứ phát. Bảo đảm tốt chế độ dinh dưỡng để tạo cho sản phụ khả năng nhanh chóng phục hồi sức khỏe và có đủ sữa nuôi hai con.\n\nVI.  CHỈ ĐỊNH MỔ LẤY THAI TRONG SINH ĐÔI\n- Hai cực đầu của hai thai cùng xuống một lúc, chèn ép rau.\n- Thai thứ nhất là ngôi mông, thai thứ hai  thuận (hai thai có thể mắc nhau).\n- Thai thứ nhất ngôi vai.\n- Thai thứ nhất  bị suy thai, sa dây rau không đẩy lên  được.\n- Sinh đôi hai thai dính nhau.\n- Rau tiền đạo, tử cung có sẹo mổ cũ, con so lớn tuổi.\nCâu hỏi:\n1. Trình bày triệu chứng và chẩn đoán song thai?\n2. Trình bày thái độ xử trí thai đôi?", "priority": "Cao (Trọng tâm BSNT)"}, {"id": "SK-32", "chapter": "Chương 2. Sản bệnh", "folder": "02_San_benh", "title": "Ngôi mông", "author": "Ths. Bs CK II. Hoàng Tiến Nam", "word_count": 1911, "line_count": 124, "key_numbers": ["25 phút", "9,5 cm"], "key_drugs": ["glucose", "oxytocin"], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["NGÔI MÔNG", "Ths. Bs CK II. Hoàng Tiến Nam"], "bullets": []}, {"heading": "Mục tiêu học tập", "paragraphs": ["Chẩn đoán được ngôi mông trong chuyển dạ.", "Mô tả được cách xử trí đỡ đẻ ngôi mông", "Kể ra được những chỉ định mổ lấy thai trong ngôi mông."], "bullets": []}, {"heading": "1. ĐỊNH NGHĨA", "paragraphs": ["Ngôi mông hay ngôi ngược là một ngôi dọc; đầu ở trên, mông hay chân ở dưới."], "bullets": []}, {"heading": "2. PHÂN LOẠI", "paragraphs": ["Có 2 loại ngôi mông", "Ngôi mông hoàn toàn (mông và 2 chi dưới gập lại).", "Hình 1. Ngôi mông hoàn toàn", "Ngôi mông không hoàn toàn gồm:", "A.                                                 B.", "Hình 2. A. Ngôi mông kiểu chân   B. Ngôi mông kiểu mông"], "bullets": ["- Ngôi mông không hoàn toàn kiểu mông (mông và 2 chân vắt ngược lên đầu).", "- Ngôi mông không hoàn toàn kiểu chân (2 chân duỗi thẳng)", "- Ngôi mông không hoàn toàn  kiểu đầu gối (thai quỳ gối trong tử cung)."]}, {"heading": "3. NGUYÊN NHÂN", "paragraphs": ["Hai yếu tố hình thành ngôi mông:", "Các nguyên nhân:"], "bullets": ["- Sinh non (thai chưa kịp bình chỉnh thành ngôi thuận)", "- Các yếu tố cản trở bình chỉnh của thai.", "- Phía mẹ: Tử cung kém phát triển, tử cung đôi, tử cung hai sừng, tử cung có vách ngăn, u xơ tử cung, khối u tiền đạo, con rạ sinh nhiều lần.", "- Phía thai nhi: Đa thai, thai dị dạng (đặc biệt gặp trong não úng thủy)", "- Phía phần phụ của thai: thiểu ối, đa ối, rau tiền đạo..."]}, {"heading": "4. THẾ VÀ KIỂU THẾ", "paragraphs": [], "bullets": ["- Điểm mốc: đỉnh xương cùng.", "- Lưng bên nào thì thế bên đó.", "- Đường kính lọt: đường kính lưỡng ụ đùi = 9,5 cm.", "- 4 kiểu thế lọt:", "+ Cùng chậu trái trước", "+ Cùng chậu trái sau", "+ Cùng chậu phải trước", "+ Cùng chậu phải sau", "- 2 kiểu sổ:", "+ Cùng chậu trái ngang", "+ Cùng chậu phải ngang"]}, {"heading": "5. CHẨN ĐOÁN", "paragraphs": ["bàn chân (cần phân biệt với bàn tay : chân ngón ngắn, gót, 2 mắt cá, gót chân là một góc vuông tạo giữa bàn chân và cẳng chân)."], "bullets": ["- Hỏi: sản phụ cảm giác tức một bên hạ sườn.", "- Nhìn: tử cung hình trứng, trục dọc.", "- Nghe tim thai: ngang rốn hay cao hơn rốn.", "- Khám 4 thủ thuật (các thủ thuật Léopold).", "+ Cực trên (đáy tử cung) là đầu.", "+ Cực dưới (vùng đoạn dưới) là mông.", "- Khám âm đạo:", "+ Nhất là lúc đã chuyển dạ sẽ thấy xương cùng, mông và 2 chân thai nhi  (mông đủ) nếu ối chưa vỡ.", "+ Hoặc có thể sờ được xương cùng, mông, hậu môn và cơ quan sinh dục,", "- Siêu âm: sử dụng thường quy trong ngôi mông để xác định trọng lượng thai, các bất thường của thai", "- X quang: giúp chẩn đoán phân biệt với các ngôi khác, chẩn đoán đầu ngửa."]}, {"heading": "6.1. Nguyên tắc", "paragraphs": ["Phải khám xét cẩn thận, tiên lượng kỹ càng để có thái độ xử trí chính xác. Việc xử trí một ngôi mông không được phép để trở thành một cấp cứu, phải có chỉ định cụ thể trước khi chuyển dạ bắt đầu.", "Có hai hướng xử trí là sinh đường âm đạo hay mổ lấy thai."], "bullets": []}, {"heading": "6.2.1. Đẻ đường âm đạo", "paragraphs": [], "bullets": ["- Chuẩn bị đỡ đẻ: tốt nhất ngôi mông nên đẻ ở trung tâm có khả năng phẫu thuật.", "- Cho sản phụ:", "+ Hướng dẫn cách cách rặn đẻ.", "+ Sản phụ nằm theo tư thế sản khoa.", "+ Thông tiểu, thụt tháo", "- Về nhân viên Y tế:", "+ Phải có đủ người (2 đến 3 người).", "+ Các phương tiện hồi sức sơ sinh, oxytocin, dịch truyền."]}, {"heading": "6.2.2. Kỹ thuật đỡ đẻ ngôi mông", "paragraphs": ["Phương pháp Vermelin:", "Chỉ định: trường hợp con rạ, thai nhỏ, tầng sinh môn giãn tốt, để cuộc đẻ xảy ra một cách tự nhiên, không có bất kỳ một sự trợ giúp nào, không có một sự can thiệp thủ thuật nào trên thai nhi.", "Phương pháp Xôvianốp:", "Mục đích của phương pháp đó là làm cho ngôi lọt và xuống trong tiểu khung một cánh từ từ, không nhanh quá, lợi dụng ngôi làm cho cổ tử cung, âm đạo, tầng sinh môn giãn tốt. Muốn thế, người hộ sinh phải giữ cho ngôi không sổ ra ngoài trong một thời gian nhất định.", "Đến thì sổ đầu sử dụng thuốc để giúp cơn co mạnh lên, hướng dẫn thai phụ rặn mạnh, kết hợp với ấn đầu thai nhi ở phía trên khớp mu.", "Cho thai phụ nằm theo kiểu nửa nằm nửa ngồi. Hồi sức thai có hệ thống mặc dù thai không suy bằng glucose và oxy,vì theo Xôvianôp trong ngôi mông thai dễ suy.", "Trường hợp vai sau đã đi qua bờ của tiểu khung trong khi vai trước hãy còn cao (nằm trên vai sau) phải dùng thủ thuật Lovset (nắm hai đùi thai nhi với các ngón tay ở phía trước, ngón cái ở phía sau đùi, quay thân của thai nhi sao cho vai sau được đưa ra phía trước, thường quay theo chiều kim đồng hồ, trong quá trình đó cánh tay sẽ bị đẩy xuống phía dưới đến bờ dưới cung xương vệ và sổ ra ngoài. Tránh ôm vào bụng thai nhi gây phản xạ thở của trẻ.", "Trường hợp các cánh tay kẹt sau gáy, có thể xử trí tình huống này bằng thủ thuật tương tự, trong đó đứa trẻ được quay đủ 1800 như vậy trong quá trình quay cánh tay trước được đẩy ra phía trước qua mặt đứa trẻ và cuối cùng xuống phía dưới để có thể sổ ra bên dưới cung vệ. Cùng một quá trình ấy được thực hiện cho cánh tay kia.", "Hai tay người đỡ đẻ ôm vào khung chậu của thai nhi kéo nhẹ thai theo hướng xuống dưới và ra sau cùng lúc người phụ đẩy trên đáy tử cung để đầu cúi tốt cho đến khi hạ chẩm số đến bờ dưới khớp vệ, nâng thai ngược lên về phía bụng mẹ để đầu thai ngửa dần, cằm, mặt và các phần còn lại của đầu sẽ lần lượt sổ ra khỏi âm hộ.", "Sổ đầu hậu:", "Hình 3. Thủ thuật Bracht", "Hình 4. Thủ thuật Mauriceau", "Ngày nay người ta đã chỉ định mổ lấy thai thay cho chỉ định đại kéo thai.", "Chỉ định đại kéo thai:"], "bullets": ["- Đặt sẵn một đường truyền tính mạch khi cổ tử cung mở gần hết.", "- Nếu có thể nên gây tê thần kinh thẹn.", "- Nên để cuộc chuyển dạ xảy ra một cách tự nhiên : chờ đợi - chờ đợi-chờ đợi.", "- Lưu ý tình trạng cổ tử cung phải mở hết, không kéo chân thai nhi.", "- Để sinh tự nhiên:", "- Đối với ngôi mông không hoàn toàn kiểu mông,mục đích của phương pháp là lợi dụng khối ngực và chân của thai nhi khá to để làm cho cổ tử cung, âm đạo, tầng sinh môn giãn tốt.", "-  Đối với ngôi mông hoàn toàn: khi ngôi đã thập thò ở âm hộ người hộ sinh dùng một miếng gạc lớn ấn vào âm hộ mỗi khi có cơn co, thời gian ấn vào âm hộ để giữ mông không sổ sớm có thể từ 15- 25 phút, nhưng phải theo dõi tim thai, nếu thai suy phải dừng giữ mông để mông sổ. Nếu thai không suy, trong cơn rặn, mông thai nhi muốn đẩy bật tay người hộ sinh ra ngoài, lúc đó buông tay ra để mông sổ.", "-  Đối với ngôi mông không hoàn toàn kiểu mông: khi mông sổ ra ngoài hai tay người hộ sinh ôm vào đùi thai nhi, ngón cái về phía sau đùi,các ngón khác về phía xương cùng, hướng thai nhi lên trên, chuyển dần tay về phía thân thai nhi,giữ cho chân thai nhi luôn luôn áp vào bụng và ngực giúp giãn nở các phần mềm tốt.", "-  Sinh ngôi mông có can thiệp từng phần:", "+ Để sinh tự nhiên đến rốn, chỉ hỗ trợ trong thì sinh vai, tay và đầu hậu.", "+ Khi mông đã sổ, nếu thấy dây rốn căng phải kéo nhẹ dây rốn ra để đỡ căng (không đụng đến bụng và thân thai nhi).", "+ Hỗ trợ sinh vai: lúc vai đã lọt và sắp sổ, nhấc nhẹ thân thai nhi về phía xương vệ người mẹ để vai sau và tay sổ ra ngoài rồi hạ thân thai nhi xuống để vai trước sổ. Sau khi đã sổ 2 vai và tay, xoay nhẹ thân thai nhi ở vị trí nằm sấp (không để thai nằm ngửa). Nếu tay thai nhi giơ cao hay vòng sau gáy phải dùng các thủ thuật hạ tay.", "- Hỗ trợ sinh đầu hậu :", "+ Thủ thuật Bracht (áp dụng trong những trường hợp con nhỏ, con rạ, tầng sinh môn mềm giãn tốt): mông đã sổ đến rốn cả khối thân thai nhi, 2 chân duỗi thẳng (người đỡ đẻ cầm 2 chân) giữ cho lưng thai nhi luôn luôn sát vào xương vệ của mẹ cộng với sức đẩy cơn co tử cung và sức ấn trên xương vệ, phần còn lại của thai nhi sẽ sổ ra tự nhiên.", "+ Thủ thuật Mauriceau (áp dụng cho con so, tầng sinh môn chắc) sau khi vai đã sổ ra ngoài để thai nhi nằm vắt trên mặt trong của cẳng tay người đỡ. Ngón trỏ và ngón giữa của bàn tay này đè vào hàm dưới trên lưỡi tới đáy lưỡi của thai (cẩn thận tránh làm rách hãm lưỡi của thai). Mục đích giúp đầu hậu cúi tốt, dùng ngón trỏ và ngón giữa của bàn tay còn lại đè lên vai gáy thai nhi tạo một lực kéo theo phương hướng ra sau và xuống dưới; Phải kéo đều tay, liên tục với cơn co tử cung thật tốt đến khi hạ chẩm sổ ra đến bờ dưới khớp vệ, lúc đó cho đầu ngửa dần bằng cách nâng thai lên dần về phía bụng mẹ để sổ mặt và các phần còn lại của đầu.", "+ Ngoài ra còn có thể lấy đầu hậu bằng Forceps Piper", "+ Đại thủ thuật kéo thai ngôi mông: là thủ thuật can thiệp trên toàn bộ cuộc sinh ngôi mông, phải  gây mê và chuẩn bị như một cuộc mổ.", "- Điều trị tiếp sau nội xoay thai.", "- Ngôi mông có dấu hiệu suy thai và đủ điều kiện để sinh đường âm đạo tức thì.", "- Áp dụng cho ngôi mông thiếu kiểu chân và ngôi mông đủ."]}, {"heading": "6.2.2. Chỉ định mổ lấy thai ngôi mông", "paragraphs": [], "bullets": ["- Con so, ngôi mông ước lượng trọng lượng thai trên 3000 gram", "- Con rạ, ngôi mông ước lượng trọng lượng thai khá to so với lần sinh trước.", "- Tiền sử sinh khó ở những lần sinh trước.", "- Con so, ngôi mông, mẹ lớn tuổi.", "- Ngôi mông con quý", "- Ngôi mông sa dây rốn", "- Ngôi mông suy thai trong chuyển dạ", "- Ngôi mông chuyển dạ kéo dài, chuyển dạ khó khăn...."]}], "raw_text": "NGÔI MÔNG\n\nThs. Bs CK II. Hoàng Tiến Nam\n\nMục tiêu học tập\nChẩn đoán được ngôi mông trong chuyển dạ.\nMô tả được cách xử trí đỡ đẻ ngôi mông\nKể ra được những chỉ định mổ lấy thai trong ngôi mông.\n1. ĐỊNH NGHĨA\nNgôi mông hay ngôi ngược là một ngôi dọc; đầu ở trên, mông hay chân ở dưới.\n2. PHÂN LOẠI\nCó 2 loại ngôi mông\nNgôi mông hoàn toàn (mông và 2 chi dưới gập lại).\n\nHình 1. Ngôi mông hoàn toàn\nNgôi mông không hoàn toàn gồm:\n- Ngôi mông không hoàn toàn kiểu mông (mông và 2 chân vắt ngược lên đầu).\n- Ngôi mông không hoàn toàn kiểu chân (2 chân duỗi thẳng)\n- Ngôi mông không hoàn toàn  kiểu đầu gối (thai quỳ gối trong tử cung).\n\nA.                                                 B.\nHình 2. A. Ngôi mông kiểu chân   B. Ngôi mông kiểu mông\n\n3. NGUYÊN NHÂN\nHai yếu tố hình thành ngôi mông:\n- Sinh non (thai chưa kịp bình chỉnh thành ngôi thuận)\n- Các yếu tố cản trở bình chỉnh của thai.\n\nCác nguyên nhân:\n- Phía mẹ: Tử cung kém phát triển, tử cung đôi, tử cung hai sừng, tử cung có vách ngăn, u xơ tử cung, khối u tiền đạo, con rạ sinh nhiều lần.\n- Phía thai nhi: Đa thai, thai dị dạng (đặc biệt gặp trong não úng thủy)\n- Phía phần phụ của thai: thiểu ối, đa ối, rau tiền đạo...\n4. THẾ VÀ KIỂU THẾ\n- Điểm mốc: đỉnh xương cùng.\n- Lưng bên nào thì thế bên đó.\n- Đường kính lọt: đường kính lưỡng ụ đùi = 9,5 cm.\n- 4 kiểu thế lọt:\n+ Cùng chậu trái trước\n+ Cùng chậu trái sau\n+ Cùng chậu phải trước\n+ Cùng chậu phải sau\n- 2 kiểu sổ:\n+ Cùng chậu trái ngang\n+ Cùng chậu phải ngang\n\n5. CHẨN ĐOÁN\n- Hỏi: sản phụ cảm giác tức một bên hạ sườn.\n- Nhìn: tử cung hình trứng, trục dọc.\n- Nghe tim thai: ngang rốn hay cao hơn rốn.\n- Khám 4 thủ thuật (các thủ thuật Léopold).\n+ Cực trên (đáy tử cung) là đầu.\n+ Cực dưới (vùng đoạn dưới) là mông.\n- Khám âm đạo:\n+ Nhất là lúc đã chuyển dạ sẽ thấy xương cùng, mông và 2 chân thai nhi  (mông đủ) nếu ối chưa vỡ.\n+ Hoặc có thể sờ được xương cùng, mông, hậu môn và cơ quan sinh dục,\nbàn chân (cần phân biệt với bàn tay : chân ngón ngắn, gót, 2 mắt cá, gót chân là một góc vuông tạo giữa bàn chân và cẳng chân).\n- Siêu âm: sử dụng thường quy trong ngôi mông để xác định trọng lượng thai, các bất thường của thai\n- X quang: giúp chẩn đoán phân biệt với các ngôi khác, chẩn đoán đầu ngửa.\n6. THÁI ĐỘ XỬ TRÍ TRONG NGÔI MÔNG\n6.1. Nguyên tắc\nPhải khám xét cẩn thận, tiên lượng kỹ càng để có thái độ xử trí chính xác. Việc xử trí một ngôi mông không được phép để trở thành một cấp cứu, phải có chỉ định cụ thể trước khi chuyển dạ bắt đầu.\nCó hai hướng xử trí là sinh đường âm đạo hay mổ lấy thai.\n6.2. Xử trí\n6.2.1. Đẻ đường âm đạo\n- Chuẩn bị đỡ đẻ: tốt nhất ngôi mông nên đẻ ở trung tâm có khả năng phẫu thuật.\n- Cho sản phụ:\n+ Hướng dẫn cách cách rặn đẻ.\n+ Sản phụ nằm theo tư thế sản khoa.\n+ Thông tiểu, thụt tháo\n- Về nhân viên Y tế:\n+ Phải có đủ người (2 đến 3 người).\n+ Các phương tiện hồi sức sơ sinh, oxytocin, dịch truyền.\n6.2.2. Kỹ thuật đỡ đẻ ngôi mông\n- Đặt sẵn một đường truyền tính mạch khi cổ tử cung mở gần hết.\n- Nếu có thể nên gây tê thần kinh thẹn.\n- Nên để cuộc chuyển dạ xảy ra một cách tự nhiên : chờ đợi - chờ đợi-chờ đợi.\n- Lưu ý tình trạng cổ tử cung phải mở hết, không kéo chân thai nhi.\n- Để sinh tự nhiên:\nPhương pháp Vermelin:\nChỉ định: trường hợp con rạ, thai nhỏ, tầng sinh môn giãn tốt, để cuộc đẻ xảy ra một cách tự nhiên, không có bất kỳ một sự trợ giúp nào, không có một sự can thiệp thủ thuật nào trên thai nhi.\nPhương pháp Xôvianốp:\nMục đích của phương pháp đó là làm cho ngôi lọt và xuống trong tiểu khung một cánh từ từ, không nhanh quá, lợi dụng ngôi làm cho cổ tử cung, âm đạo, tầng sinh môn giãn tốt. Muốn thế, người hộ sinh phải giữ cho ngôi không sổ ra ngoài trong một thời gian nhất định.\n- Đối với ngôi mông không hoàn toàn kiểu mông,mục đích của phương pháp là lợi dụng khối ngực và chân của thai nhi khá to để làm cho cổ tử cung, âm đạo, tầng sinh môn giãn tốt.\nĐến thì sổ đầu sử dụng thuốc để giúp cơn co mạnh lên, hướng dẫn thai phụ rặn mạnh, kết hợp với ấn đầu thai nhi ở phía trên khớp mu.\nCho thai phụ nằm theo kiểu nửa nằm nửa ngồi. Hồi sức thai có hệ thống mặc dù thai không suy bằng glucose và oxy,vì theo Xôvianôp trong ngôi mông thai dễ suy.\n-  Đối với ngôi mông hoàn toàn: khi ngôi đã thập thò ở âm hộ người hộ sinh dùng một miếng gạc lớn ấn vào âm hộ mỗi khi có cơn co, thời gian ấn vào âm hộ để giữ mông không sổ sớm có thể từ 15- 25 phút, nhưng phải theo dõi tim thai, nếu thai suy phải dừng giữ mông để mông sổ. Nếu thai không suy, trong cơn rặn, mông thai nhi muốn đẩy bật tay người hộ sinh ra ngoài, lúc đó buông tay ra để mông sổ.\n-  Đối với ngôi mông không hoàn toàn kiểu mông: khi mông sổ ra ngoài hai tay người hộ sinh ôm vào đùi thai nhi, ngón cái về phía sau đùi,các ngón khác về phía xương cùng, hướng thai nhi lên trên, chuyển dần tay về phía thân thai nhi,giữ cho chân thai nhi luôn luôn áp vào bụng và ngực giúp giãn nở các phần mềm tốt.\n-  Sinh ngôi mông có can thiệp từng phần:\n+ Để sinh tự nhiên đến rốn, chỉ hỗ trợ trong thì sinh vai, tay và đầu hậu.\n+ Khi mông đã sổ, nếu thấy dây rốn căng phải kéo nhẹ dây rốn ra để đỡ căng (không đụng đến bụng và thân thai nhi).\n+ Hỗ trợ sinh vai: lúc vai đã lọt và sắp sổ, nhấc nhẹ thân thai nhi về phía xương vệ người mẹ để vai sau và tay sổ ra ngoài rồi hạ thân thai nhi xuống để vai trước sổ. Sau khi đã sổ 2 vai và tay, xoay nhẹ thân thai nhi ở vị trí nằm sấp (không để thai nằm ngửa). Nếu tay thai nhi giơ cao hay vòng sau gáy phải dùng các thủ thuật hạ tay.\nTrường hợp vai sau đã đi qua bờ của tiểu khung trong khi vai trước hãy còn cao (nằm trên vai sau) phải dùng thủ thuật Lovset (nắm hai đùi thai nhi với các ngón tay ở phía trước, ngón cái ở phía sau đùi, quay thân của thai nhi sao cho vai sau được đưa ra phía trước, thường quay theo chiều kim đồng hồ, trong quá trình đó cánh tay sẽ bị đẩy xuống phía dưới đến bờ dưới cung xương vệ và sổ ra ngoài. Tránh ôm vào bụng thai nhi gây phản xạ thở của trẻ.\nTrường hợp các cánh tay kẹt sau gáy, có thể xử trí tình huống này bằng thủ thuật tương tự, trong đó đứa trẻ được quay đủ 1800 như vậy trong quá trình quay cánh tay trước được đẩy ra phía trước qua mặt đứa trẻ và cuối cùng xuống phía dưới để có thể sổ ra bên dưới cung vệ. Cùng một quá trình ấy được thực hiện cho cánh tay kia.\n- Hỗ trợ sinh đầu hậu :\nHai tay người đỡ đẻ ôm vào khung chậu của thai nhi kéo nhẹ thai theo hướng xuống dưới và ra sau cùng lúc người phụ đẩy trên đáy tử cung để đầu cúi tốt cho đến khi hạ chẩm số đến bờ dưới khớp vệ, nâng thai ngược lên về phía bụng mẹ để đầu thai ngửa dần, cằm, mặt và các phần còn lại của đầu sẽ lần lượt sổ ra khỏi âm hộ.\nSổ đầu hậu:\n+ Thủ thuật Bracht (áp dụng trong những trường hợp con nhỏ, con rạ, tầng sinh môn mềm giãn tốt): mông đã sổ đến rốn cả khối thân thai nhi, 2 chân duỗi thẳng (người đỡ đẻ cầm 2 chân) giữ cho lưng thai nhi luôn luôn sát vào xương vệ của mẹ cộng với sức đẩy cơn co tử cung và sức ấn trên xương vệ, phần còn lại của thai nhi sẽ sổ ra tự nhiên.\n\nHình 3. Thủ thuật Bracht\n+ Thủ thuật Mauriceau (áp dụng cho con so, tầng sinh môn chắc) sau khi vai đã sổ ra ngoài để thai nhi nằm vắt trên mặt trong của cẳng tay người đỡ. Ngón trỏ và ngón giữa của bàn tay này đè vào hàm dưới trên lưỡi tới đáy lưỡi của thai (cẩn thận tránh làm rách hãm lưỡi của thai). Mục đích giúp đầu hậu cúi tốt, dùng ngón trỏ và ngón giữa của bàn tay còn lại đè lên vai gáy thai nhi tạo một lực kéo theo phương hướng ra sau và xuống dưới; Phải kéo đều tay, liên tục với cơn co tử cung thật tốt đến khi hạ chẩm sổ ra đến bờ dưới khớp vệ, lúc đó cho đầu ngửa dần bằng cách nâng thai lên dần về phía bụng mẹ để sổ mặt và các phần còn lại của đầu.\n+ Ngoài ra còn có thể lấy đầu hậu bằng Forceps Piper\n+ Đại thủ thuật kéo thai ngôi mông: là thủ thuật can thiệp trên toàn bộ cuộc sinh ngôi mông, phải  gây mê và chuẩn bị như một cuộc mổ.\n\nHình 4. Thủ thuật Mauriceau\n\nNgày nay người ta đã chỉ định mổ lấy thai thay cho chỉ định đại kéo thai.\nChỉ định đại kéo thai:\n- Điều trị tiếp sau nội xoay thai.\n- Ngôi mông có dấu hiệu suy thai và đủ điều kiện để sinh đường âm đạo tức thì.\n- Áp dụng cho ngôi mông thiếu kiểu chân và ngôi mông đủ.\n6.2.2. Chỉ định mổ lấy thai ngôi mông\n- Con so, ngôi mông ước lượng trọng lượng thai trên 3000 gram\n- Con rạ, ngôi mông ước lượng trọng lượng thai khá to so với lần sinh trước.\n- Tiền sử sinh khó ở những lần sinh trước.\n- Con so, ngôi mông, mẹ lớn tuổi.\n- Ngôi mông con quý\n- Ngôi mông sa dây rốn\n- Ngôi mông suy thai trong chuyển dạ\n- Ngôi mông chuyển dạ kéo dài, chuyển dạ khó khăn....\n\n\nCâu hỏi:\n1. Trình bày định nghĩa, chẩn đoán ngôi mông.\n2. Trình bày cách đỡ đẻ ngôi mông", "priority": "Cao (Trọng tâm BSNT)"}, {"id": "SK-33", "chapter": "Chương 2. Sản bệnh", "folder": "02_San_benh", "title": "Chảy máu sau sinh", "author": "Ths. Bùi Thị Thanh Tuyền", "word_count": 3112, "line_count": 171, "key_numbers": ["0,2 mg", "0,5 cm", "1 cm", "1000 ml", "15 phút", "2 giờ", "2 phút", "21 ngày", "24 giờ", "3 giờ", "300ml", "5 ngày", "500 ml", "500ml", "9 giờ"], "key_drugs": ["Misoprostol", "ergometrine", "oxytocin"], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["CHẢY MÁU SAU SINH", "Ths. Bùi Thị Thanh Tuyền"], "bullets": []}, {"heading": "1. ĐẠI CƯƠNG", "paragraphs": ["Chảy máu sau sinh là một biến chứng trầm trọng, một trong 5 tai biến chính của sản khoa. Ngày nay, nhờ các tiến bộ của hồi sức cấp cứu đã làm giảm sự trầm trọng của biến chứng này. Chảy máu sau đẻ vẫn là nguyên nhân gây tử vong chính trong sản khoa, đặc biệt khi có biểu hiện rối loạn đông máu. Biến chứng này thường xảy ra bất ngờ do vậy cần phải có biện pháp dự phòng và điều trị tích cực.", "Chảy máu sau đẻ là khi lượng máu mất trên 500ml hoặc choáng do mất máu xảy ra sau đẻ và thường xảy ra trong 24 giờ đầu. Tuy nhiên, một số trường hợp chỉ mất lượng máu ít hơn nhưng đã ảnh hưởng đến tổng trạng chung của sản phụ, tuỳ theo thể trạng và bệnh lý trước đó.", "Tần suất: trong y văn đối với đẻ đường dưới tần suất chảy máu trên 300ml là 18 - 26%, chảy máu nặng trên 1000 ml từ 3 - 4,5% sau đẻ hoặc 6% sau mổ lấy thai.", "Chảy máu xảy ra ngay sau đẻ có thể do 3 nguyên nhân:"], "bullets": ["- Bệnh lý trong thời kỳ sổ rau: do sót rau, đờ tử cung.", "- Tổn thương đường sinh dục: vỡ tử cung, rách cổ tử cung, rách âm đạo, rách tầng sinh môn.", "- Bệnh lý rối loạn đông máu (rất hiếm gặp)."]}, {"heading": "2.1. Sót rau", "paragraphs": ["Rau sót nhiều hoặc ít trong tử cung đều gây chảy máu."], "bullets": []}, {"heading": "2.1.1. Rối loạn về co bóp tử cung", "paragraphs": ["Đờ tử cung là nguyên nhân gây chảy máu sau đẻ thường gặp nhất. Ngược với đờ tử cung là tăng trương lực tử cung dưới dạng co thắt tử cung, tạo vòng thắt ở lỗ trong cổ tử cung hoặc ở sừng tử cung làm rau bị cầm tù trên vòng thắt."], "bullets": []}, {"heading": "2.1. 2. Bám bất thường của bánh rau", "paragraphs": ["Rau cài răng lược (rau bám chặt, rau bám vào cơ tử cung, rau xuyên cơ tử cung) loại này hiếm gặp, tỷ lệ 1/10.000 cuộc đẻ, chỉ xảy ra trong trường hợp bất thường của niêm mạc tử cung: sẹo cũ, dính, u xơ, giảm sản nội mạc, viêm nội mạc, dị dạng tử cung."], "bullets": []}, {"heading": "2.1.3. Bất thường về vị trí bánh rau", "paragraphs": ["Rau bám đoạn dưới, trên vách tử cung dị dạng, trên vùng tử cung mỏng. Hoạt động tử cung ở vùng này ít hiệu quả để bong rau. Nguy cơ rau cài răng lược ở trên các chỗ bám này cũng cao hơn.", "Điều trị: chỉ định kiểm soát buồng tử cung trong trường hợp chảy máu do sót rau. Đối với trường hợp sau sổ thai một giờ rau không bong, nghiệm pháp bong rau âm tính, hoặc chảy máu nhiều phải bóc rau nhân tạo, nếu không kết quả thì mổ cắt tử cung bán phần."], "bullets": []}, {"heading": "2.1.4. Dự phòng", "paragraphs": ["Lý tưởng nhất là phải dự phòng các trường hợp chảy máu sau đẻ:"], "bullets": ["+ Tôn trọng các nguyên tắc trong thời kỳ sổ rau.", "+ Nếu xử trí tích cực giai đoạn 3 cần phải thực hiện đúng kỹ thuật", "+ Kiểm tra kỹ bánh rau, trong trường hợp sót rau phải kiểm tra lòng tử cung."]}, {"heading": "2.2.1. Nguyên nhân: đờ tử cung có thể xaỷ ra ở những trường hợp sau", "paragraphs": ["Trên lâm sàng có hai mức độ đờ tử cung:"], "bullets": ["- Sản phụ suy nhược, thiếu máu, tăng huyết áp, tiền sản giật...", "- Nhược cơ tử cung do chuyển dạ kéo dài.", "- Tử cung giãn quá mức do song thai, đa ối, thai to.", "- Tử cung mất trương lực sau khi đẻ quá nhanh.", "- Sót rau, màng rau trong buồng tử cung", "- Bất thường tử cung: u xơ, tử cung dị dạng.", "- Đờ tử cung do sử dụng thuốc: sau gây mê bằng các thuốc mê họ Halothane(fluothane) sử dụng Betamimetic, dùng oxytocin không liên tục sau khi sổ thai.", "- Đờ tử cung còn phục hồi: là tình trạng cơ tử cung bị giảm trương lực nên tử cung co hồi kém, đặc biệt ở vùng rau bám; nhưng cơ tử cung còn đáp ứng với các kích thích cơ học và thuốc.", "- Đờ tử cung không hồi phục: cơ tử cung không còn đáp ứng với các kích thích trên."]}, {"heading": "2.2.2. Triệu chứng và chẩn đoán", "paragraphs": [], "bullets": ["- Chảy máu: chảy máu ngay sau sổ rau là triệu chứng phổ biến nhất. Máu có thể chảy liên tục hoặc khi ấn vào đáy tử cung máu sẽ chảy ồ ạt ra ngoài.", "- Tử cung nhão, mềm do co hồi kém hoặc không co hồi, không có khối an toàn mặc dầu rau đã sổ."]}, {"heading": "2.2.3. Xử trí", "paragraphs": ["Phải xử trí khẩn trương, tiến hành song song cầm máu và hồi sức.", "Tuy nhiên nếu sau khi xoa bóp tử cung, tiêm oxytocin hoặc ergometrin nhưng máu tiếp tục chảy và mỗi khi ngừng xoa tử cung lại nhão, phải nghĩ đến đờ tử cung không hồi phục, lập tức chỉ định can thiệp phẫu thuật (thắt hai động mạch tử cung, thực hiện mũi khâu B_Lynch, thắt động mạch hạ vị trước khi cắt tử cung bán phần)."], "bullets": ["- Dùng mọi biện pháp cơ học để cầm máu: xoa tử cung qua thành bụng, chẹn động mạch chủ bụng, ép tử cung bằng hai tay.", "- Thông tiểu để làm rỗng bàng quang.", "- Làm sạch lòng tử cung: lấy hết rau sót, lấy hết máu cục.", "- Tiêm 5 - 10 đơn vị oxytocin tiêm bắp hoặc tiêm vào cơ tử cung, nếu tử cung vẫn không co thì tiêm bắp ergometrine 0,2 mg (cũng có thể truyền tĩnh mạch để có tác dụng nhanh hơn).", "- Truyền nhỏ giọt tĩnh mạch oxytocin  5 - 10 đơn vị trong 500 ml dung dịch glucoza 5%.", "- Truyền dịch chống choáng.", "- Trong 2 giờ đầu mỗi 15 phút xoa đáy tử cung một lần, kéo dài trong 2 phút cho đến khi có cảm giác tử cung co cứng thành khối dưới tay.", "- Tuyến xã: nếu không cầm máu được thì mời tuyến trên hỗ trợ hoặc chuyển tuyến trên có hộ tống.", "- Tuyến huyện: xử trí như trên, nếu không cầm máu được thì mổ cắt tử cung bán phần."]}, {"heading": "2.2.4. Dự phòng", "paragraphs": ["Trong trường hợp chuyển dạ kéo dài hoặc tử cung bị giãn quá mức do thai to, đa ối, các trường hợp con rạ đẻ nhiều lần nên:", "ư Misoprostol 200 àg x 2 viờn đặt trực tràng sau sổ rau.", "Hình 1. Ðờ tử cung và xử trí ép tử cung bằng 2 tay"], "bullets": ["- Theo dõi cuộc đẻ bằng biểu đồ chuyển dạ.", "- Tiêm bắp 10 đơn vị oxytocin khi vai trước sổ hoặc ngay sau sổ thai nhưng phải chắc chắn rằng không còn thai thứ 2.", "- Xử trí tích cực giai đoạn III bao gồm: tiêm oxytocin, kéo nhẹ dây rốn có kiểm soát và xoa tử cung."]}, {"heading": "2.3. Lộn lòng tử cung", "paragraphs": ["Là biến chứng hiếm gặp, do các nguyên nhân: kéo dây rốn, đẩy đáy tử cung khi sổ rau. Triệu chứng thường gặp là đau dữ dội, chảy máu nhiều, choáng, mót rặn. Mót rặn chỉ gặp trong hai trường hợp sau đẻ, đó là khối máu tụ âm đạo, tiểu khung hoặc lộn lòng tử cung.", "Khám bụng: tuỳ theo mức độ có thể thấy lõm ở đáy tử cung, hoặc không sờ thấy tử cung trên vệ. Khám âm đạo thấy khối tử cung trong âm đạo, mềm, đau, có thể co bóp, có vòng thắt tử cung trên khối đó.", "Xử trí: nếu chẩn đoán sớm có thể đẩy tử cung trở lại, sau đó tiêm oxytocin và phải giữ tay trong lòng tử cung để kiểm soát sự co bóp của tử cung, nếu thất bại phải mổ thắt động mạch tử cung, thực hiện mũi khâu B-Lynch cải tiến (khâu 2 đai cạnh tử cung) nếu không cầm máu được thì cắt tử cung.", "Hình 2. Ðẩy tử cung trở lại trong lộn lòng tử cung"], "bullets": []}, {"heading": "2.4. Rau cài răng lược", "paragraphs": ["Ở người có tiền sử đẻ nhiều lần, nạo thai nhiều lần, viêm niêm mạc tử cung; chất lượng niêm mạc tử cung không còn tốt nên các gai rau bám trực tiếp vào cơ tử cung (không có lớp xốp của ngoại sản mạc), có khi gai rau xuyên sâu vào chiều dày lớp cơ tử cung. Có thể chỉ một phần bánh rau bám vào lớp cơ hay toàn bộ bánh rau bám vào lớp cơ, người ta phân  rau cài răng lược thành các loại sau:", "Rau cài răng lược toàn phần: toàn bộ bánh rau bám vào lớp cơ tử cung do đó không bong ra được và không chảy máu.", "Rau cài răng lược bán phần: chỉ một phần bánh rau bám sâu vào cơ tử cung do đó bánh rau có thể bong một phần, gây chảy máu. Lượng máu chảy tùy thuộc vào vào tình trạng co của lớp cơ tử cung và mức độ bong rau.", "Có 3 mức độ cài của gai rau:"], "bullets": ["+ Rau bám chặt.", "+ Rau bám xuyên cơ tử cung.", "+ Rau xuyên thủng cơ tử cung, có thể bám vào các tạng lân cận."]}, {"heading": "2.4.1. Triệu chứng lâm sàng", "paragraphs": ["Trường hợp này bánh rau đã bong nhưng không sổ tự nhiên được vì bị mắc kẹt trong tử cung do vòng thắt của lớp cơ đan. Đặc biệt bánh rau dễ bị mắc kẹt trong trường hợp tử cung hai sừng, khi ấy chỉ cần cho tay vào buồng tử cung sẽ lấy được rau ra vì bánh rau đã bong hoàn toàn."], "bullets": ["- Nếu rau cài răng lược toàn phần thì sau sổ thai một giờ rau vẫn không bong, tuy không chảy máu.", "- Nếu rau cài răng lược bán phần thì sau khi thai sổ, rau vẫn không bong hết nên không sổ được, chảy máu nhiều hay ít tùy theo diện rau đã bong rộng hay hẹp.", "- Chỉ có thể chẩn đoán chắc chắn dựa vào thử bóc rau không kết quả hay chỉ bóc được một phần và máu chảy nhiều.", "-  Cần chú ý phân biệt với rau mắc kẹt (rau bị cầm tù):"]}, {"heading": "2.4.2. Xử trí", "paragraphs": ["Nếu máu chảy trong thời kỳ sổ rau hoặc trên một giờ rau không bong thì bóc rau nhân tạo, kiểm soát tử cung.", "Hình 3. Bóc rau bằng tay", "Nếu bóc rau không được do rau bám xuyên vào cơ tử cung, phải mổ cắt tử cung bán phần, hồi sức, truyền dịch, truyền máu trong và sau mổ.", "Trường hợp rau tiền đạo cài răng lược phải cắt tử cung bán phần thấp hoặc cắt tử cung hoàn toàn để cầm máu.", "Tuyến xã: nếu chảy máu khi rau chưa bong thì bóc rau nhân tạo, kiểm soát tử cung và dùng oxytocin. Nếu rau không bong và không chảy máu thì chuyển tuyến trên.", "Tuyến huyện: bóc rau nhân tạo, kiểm soát tử cung, nếu bóc không được thì cắt tử cung bán phần."], "bullets": []}, {"heading": "3.1. Vỡ tử cung", "paragraphs": ["Xem bài \"Vỡ tử cung\""], "bullets": []}, {"heading": "3.2.1 Nguyên nhân", "paragraphs": [], "bullets": ["- Về phía mẹ: tầng sinh môn rắn ở người sinh con so lớn tuổi, nhiễm khuẩn, phù nề và có sẹo cũ ở tầng sinh môn.", "- Về phía thai: thai to, thai sổ kiểu chẩm cùng, sổ đầu hậu trong ngôi mông", "-  Do thủ thuật: đẻ hỗ trợ bằng forceps, giác hút.."]}, {"heading": "3.2.2.Chẩn đoán:", "paragraphs": ["Sau khi sổ thai thấy máu vẫn chảy ra, có thể nhìn thấy ngay máu chảy từ vết rách hay vết cắt tầng sinh môn, cần kiểm tra kỹ chỗ rách để xác định mức độ rách tầng sinh môn:", "_ Độ III: rách cơ tầng sinh môn tới tận nút thớ trung tâm."], "bullets": ["- Độ I: rách da và niêm mạc âm đạo.", "- Độ II: rách da, niêm mạc âm đạo và một phần cơ tầng sinh môn (thường là cơ hành hang).", "- Độ IV: rách qua nút thớ trung tâm tới tận phên trực tràng âm đạo, làm âm đạo thông với trực tràng."]}, {"heading": "3.2.2 Xử trí", "paragraphs": ["Hình 4. Rách âm đạo - tầng sinh môn và kỹ thuật khâu"], "bullets": ["- Gây tê tại chỗ hoặc sử dụng các thuốc giảm đau.", "- Khâu phục hồi sau khi sổ rau và biết chắc là tử cung không còn sót rau.", "- Khâu từ trong ra ngoài, từ lớp sâu đến nông, khâu mũi rời, các mũi cách rau 0,5 cm. Mũi khâu đầu tiên của lớp niêm mạc phải trên đỉnh vết rách 0,5 - 1 cm.", "- Khâu 3 lớp: lớp niêm mạc và lớp cơ ở trong bằng catgut, lớp da ở ngoài bằng chỉ không tiêu; Không để khoảng trống giữa 2 lớp, không để lệch hoặc chồng mép. Riêng đối với rách tầng sinh môn độ IV, vì phẫu thuật phức tạp, vết rách khó liền do sản dịch và nước tiểu gây nhiễm khuẩn tại chỗ, chỉ nên khâu phục hồi sau khi hết thời kỳ hậu sản."]}, {"heading": "3.2.3. Chăm sóc", "paragraphs": [], "bullets": ["- Giữ vết khâu luôn sạch: phải rửa âm hộ ngày 2 - 3 lần nhất là sau đại tiện, tiểu tiện.", "- Giữ vết khâu khô: sau khi rửa phải thấm khô.", "- Chế độ ăn: ăn nhẹ, tránh táo bón.", "- Nếu vết khâu phù nề cần cắt chỉ sớm.", "- Cắt chỉ sau 5 ngày."]}, {"heading": "3.2.4. Dự phòng :", "paragraphs": [], "bullets": ["- Hướng dẫn cho sản phụ cách rặn đẻ.", "- Giữ tầng sinh môn đúng phương pháp khi sổ thai.", "- Đỡ đẻ đúng kỹ thuật.", "- Cắt tầng sinh môn khi có chỉ định."]}, {"heading": "3.3.1. Nguyên nhân", "paragraphs": ["Tất cả các trường hợp chảy máu ngay sau đẻ, phải kiểm tra cổ tử cung. Tần suất có thể gặp 11% ở con so, 4% ở con rạ. Rách thường ở hai vị trí 3 - 9 giờ, có thể kéo lên đến vòm âm đạo, đôi khi rách cổ tử cung lên đến đoạn dưới. Rách cổ tử cung có thể gặp khi sổ thai mà cổ tử cung chưa mở hết, sinh thủ thuật, đẻ nhanh, cổ tử cung xơ chai."], "bullets": []}, {"heading": "3.3.2. Chẩn đoán", "paragraphs": ["Sau khi sổ thai hoặc rau máu ra nhiều màu đỏ tươi, kiểm tra cổ tử cung thấy có chỗ rách nham nhở hoặc không liên tục, đang chảy máu (lưu ý vị trí 3 giờ và 9 giờ).", "Rách nông: đỉnh vết rách ở dưới chỗ bám âm đạo - cổ tử cung.", "Rách sâu: Đỉnh vết rách ở trên chỗ bám âm đạo -cổ tử cung, phải kiểm tra kỹ xem có vỡ tử cung, rách bàng quang hoặc tổn thương trực tràng."], "bullets": []}, {"heading": "3.3.2. Xử trí", "paragraphs": ["Đánh giá cẩn thận tổn thương, phải thấy rõ đỉnh vết rách, khâu phục hồi vết rách bằng các mũi rời. Trường hợp rách trên âm đạo, nếu ngoài phúc mạc có thể khâu đường dưới, nếu trong phúc mạc đôi khi phải phẫu thuật.", "Hình 5. Khâu vết rách cổ tử cung"], "bullets": []}, {"heading": "4.1. Nguyên nhân", "paragraphs": ["Chảy máu do bệnh lý rối loạn đông máu thường nặng, có thể gặp trong các bệnh lý sản khoa như rau bong non, thai chết trong tử cung, nhiễm trùng tử cung, tắc mạch nước ối, hoặc một số bệnh lý nội khoa khác như viêm gan siêu vi cấp, xuất huyết giảm tiểu cầu,…"], "bullets": []}, {"heading": "4.2. Các yếu tố chẩn đoán sinh học", "paragraphs": [], "bullets": ["- Tăng thời gian Quick", "- Tăng thời gian hoạt hoá cephaline", "- Giảm số lượng tiểu cầu", "- Giảm fibrinogen.", "- Giảm tỷ lệ của các yếu tố II, V, giảm Antithrombin III, tăng các sản phẩm thoái hoá fibrin (PDF)."]}, {"heading": "4.3. Điều trị", "paragraphs": [], "bullets": ["- Điều trị: bổ sung các yếu tố thiếu: truyền máu tươi, plasma tươi, cung cấp các yếu tố đông máu. Fibrinogen cô đặc được chỉ định trong trường hợp giảm fibrinogen nặng.", "- Heparin ít sử dụng trong chảy máu sản khoa.", "- Sau khi điều chỉnh các yếu tố đông máu và ngừng chảy máu, nên dự phòng tắc mạch do huyết khối  bằng calciparin trong 21 ngày.", "- Phẫu thuật cắt tử cung bán phần kèm buộc động mạch hạ vị trong một số trường hợp có chỉ định."]}, {"heading": "5. ĐỀ PHÒNG CHẢY MÁU SAU SINH", "paragraphs": [], "bullets": ["- Sử dụng biểu đồ chuyển dạ để phát hiện chuyển dạ bất thường và phải xử trí thích hợp", "- Sử dụng thuốc tăng và giảm co đúng chỉ đinh, liều lượng", "- Đỡ đẻ đúng kỹ thuật", "- Kiểm tra rau và màng rau tránh để sót rau, sót màng", "- Sau sinh phải kiểm tra ống đẻ để phát hiện các tổn thương", "- Tư vấn và vận động thực hiện sinh đẻ có kế hoạch"]}, {"heading": "Câu hỏi:", "paragraphs": ["Câu 1: Trình bày nguyên nhân, triệu chứng lâm sàng của đờ tử cung sau đẻ", "Câu 2: Trình bày các triệu chứng lâm sàng của rau cài răng lược?", "Câu 3: Trình bày nguyên nhân, triệu chứng lâm sàng của sót rau sau đẻ?", "Câu 4:  Trình bày nguyên nhân của rách tầng sinh môn?", "Câu 5: Trình bày nguyên nhân, triệu chứng lâm sàng và hướng xử trí của rách âm đạo?", "Câu 6: Trình bày nguyên nhân, triệu chứng lâm sàng và hướng xử trí rách cổ tử cung sau đẻ?", "Câu 7:Trình bày  nguyên nhân, triệu chứng lâm sàng và hướng xử trí của rối loạn đông máu sau đẻ băng huyết?", "Câu 8:Trình bày hướng xử trí  ban đầu của đở tử cung sau đẻ ở tuyến cơ sở?", "Câu 9: Trình bày hướng xử trí  ban đầu của rau cài răng lược ở tuyến cơ sở?", "Câu 10: Trình bày hướng xử trí  ban đầu của sót rau ở tuyến cơ sở?", "Câu 11:Trình bày  triệu chứng lâm sàng và hướng xử trí của rách tầng sinh môn?"], "bullets": []}], "raw_text": "CHẢY MÁU SAU SINH\nThs. Bùi Thị Thanh Tuyền\n\nMục tiêu học tập\n1.  Phân loại các nguyên nhân chảy máu sau đẻ\n2. Lựa chọn các xử trí ban đầu chảy máu sau đẻ\n3. Lựa chọn các biện pháp phòng chống cho từng trường hợp\n\n1. ĐẠI CƯƠNG\nChảy máu sau sinh là một biến chứng trầm trọng, một trong 5 tai biến chính của sản khoa. Ngày nay, nhờ các tiến bộ của hồi sức cấp cứu đã làm giảm sự trầm trọng của biến chứng này. Chảy máu sau đẻ vẫn là nguyên nhân gây tử vong chính trong sản khoa, đặc biệt khi có biểu hiện rối loạn đông máu. Biến chứng này thường xảy ra bất ngờ do vậy cần phải có biện pháp dự phòng và điều trị tích cực.\nChảy máu sau đẻ là khi lượng máu mất trên 500ml hoặc choáng do mất máu xảy ra sau đẻ và thường xảy ra trong 24 giờ đầu. Tuy nhiên, một số trường hợp chỉ mất lượng máu ít hơn nhưng đã ảnh hưởng đến tổng trạng chung của sản phụ, tuỳ theo thể trạng và bệnh lý trước đó.\nTần suất: trong y văn đối với đẻ đường dưới tần suất chảy máu trên 300ml là 18 - 26%, chảy máu nặng trên 1000 ml từ 3 - 4,5% sau đẻ hoặc 6% sau mổ lấy thai.\nChảy máu xảy ra ngay sau đẻ có thể do 3 nguyên nhân:\n- Bệnh lý trong thời kỳ sổ rau: do sót rau, đờ tử cung.\n- Tổn thương đường sinh dục: vỡ tử cung, rách cổ tử cung, rách âm đạo, rách tầng sinh môn.\n- Bệnh lý rối loạn đông máu (rất hiếm gặp).\n2. BỆNH LÝ THỜI KỲ SỔ RAU\n2.1. Sót rau\nRau sót nhiều hoặc ít trong tử cung đều gây chảy máu.\n2.1.1. Rối loạn về co bóp tử cung\nĐờ tử cung là nguyên nhân gây chảy máu sau đẻ thường gặp nhất. Ngược với đờ tử cung là tăng trương lực tử cung dưới dạng co thắt tử cung, tạo vòng thắt ở lỗ trong cổ tử cung hoặc ở sừng tử cung làm rau bị cầm tù trên vòng thắt.\n2.1. 2. Bám bất thường của bánh rau\nRau cài răng lược (rau bám chặt, rau bám vào cơ tử cung, rau xuyên cơ tử cung) loại này hiếm gặp, tỷ lệ 1/10.000 cuộc đẻ, chỉ xảy ra trong trường hợp bất thường của niêm mạc tử cung: sẹo cũ, dính, u xơ, giảm sản nội mạc, viêm nội mạc, dị dạng tử cung.\n2.1.3. Bất thường về vị trí bánh rau\nRau bám đoạn dưới, trên vách tử cung dị dạng, trên vùng tử cung mỏng. Hoạt động tử cung ở vùng này ít hiệu quả để bong rau. Nguy cơ rau cài răng lược ở trên các chỗ bám này cũng cao hơn.\nĐiều trị: chỉ định kiểm soát buồng tử cung trong trường hợp chảy máu do sót rau. Đối với trường hợp sau sổ thai một giờ rau không bong, nghiệm pháp bong rau âm tính, hoặc chảy máu nhiều phải bóc rau nhân tạo, nếu không kết quả thì mổ cắt tử cung bán phần.\n2.1.4. Dự phòng\nLý tưởng nhất là phải dự phòng các trường hợp chảy máu sau đẻ:\n+ Tôn trọng các nguyên tắc trong thời kỳ sổ rau.\n+ Nếu xử trí tích cực giai đoạn 3 cần phải thực hiện đúng kỹ thuật\n+ Kiểm tra kỹ bánh rau, trong trường hợp sót rau phải kiểm tra lòng tử cung.\n2.2. Đờ tử cung\n2.2.1. Nguyên nhân: đờ tử cung có thể xaỷ ra ở những trường hợp sau\n- Sản phụ suy nhược, thiếu máu, tăng huyết áp, tiền sản giật...\n- Nhược cơ tử cung do chuyển dạ kéo dài.\n- Tử cung giãn quá mức do song thai, đa ối, thai to.\n- Tử cung mất trương lực sau khi đẻ quá nhanh.\n- Sót rau, màng rau trong buồng tử cung\n- Bất thường tử cung: u xơ, tử cung dị dạng.\n- Đờ tử cung do sử dụng thuốc: sau gây mê bằng các thuốc mê họ Halothane(fluothane) sử dụng Betamimetic, dùng oxytocin không liên tục sau khi sổ thai.\nTrên lâm sàng có hai mức độ đờ tử cung:\n- Đờ tử cung còn phục hồi: là tình trạng cơ tử cung bị giảm trương lực nên tử cung co hồi kém, đặc biệt ở vùng rau bám; nhưng cơ tử cung còn đáp ứng với các kích thích cơ học và thuốc.\n- Đờ tử cung không hồi phục: cơ tử cung không còn đáp ứng với các kích thích trên.\n2.2.2. Triệu chứng và chẩn đoán\n- Chảy máu: chảy máu ngay sau sổ rau là triệu chứng phổ biến nhất. Máu có thể chảy liên tục hoặc khi ấn vào đáy tử cung máu sẽ chảy ồ ạt ra ngoài.\n- Tử cung nhão, mềm do co hồi kém hoặc không co hồi, không có khối an toàn mặc dầu rau đã sổ.\n2.2.3. Xử trí\nPhải xử trí khẩn trương, tiến hành song song cầm máu và hồi sức.\n- Dùng mọi biện pháp cơ học để cầm máu: xoa tử cung qua thành bụng, chẹn động mạch chủ bụng, ép tử cung bằng hai tay.\n- Thông tiểu để làm rỗng bàng quang.\n- Làm sạch lòng tử cung: lấy hết rau sót, lấy hết máu cục.\n- Tiêm 5 - 10 đơn vị oxytocin tiêm bắp hoặc tiêm vào cơ tử cung, nếu tử cung vẫn không co thì tiêm bắp ergometrine 0,2 mg (cũng có thể truyền tĩnh mạch để có tác dụng nhanh hơn).\n- Truyền nhỏ giọt tĩnh mạch oxytocin  5 - 10 đơn vị trong 500 ml dung dịch glucoza 5%.\n- Truyền dịch chống choáng.\n- Trong 2 giờ đầu mỗi 15 phút xoa đáy tử cung một lần, kéo dài trong 2 phút cho đến khi có cảm giác tử cung co cứng thành khối dưới tay.\nTuy nhiên nếu sau khi xoa bóp tử cung, tiêm oxytocin hoặc ergometrin nhưng máu tiếp tục chảy và mỗi khi ngừng xoa tử cung lại nhão, phải nghĩ đến đờ tử cung không hồi phục, lập tức chỉ định can thiệp phẫu thuật (thắt hai động mạch tử cung, thực hiện mũi khâu B_Lynch, thắt động mạch hạ vị trước khi cắt tử cung bán phần).\n- Tuyến xã: nếu không cầm máu được thì mời tuyến trên hỗ trợ hoặc chuyển tuyến trên có hộ tống.\n- Tuyến huyện: xử trí như trên, nếu không cầm máu được thì mổ cắt tử cung bán phần.\n2.2.4. Dự phòng\nTrong trường hợp chuyển dạ kéo dài hoặc tử cung bị giãn quá mức do thai to, đa ối, các trường hợp con rạ đẻ nhiều lần nên:\n- Theo dõi cuộc đẻ bằng biểu đồ chuyển dạ.\n- Tiêm bắp 10 đơn vị oxytocin khi vai trước sổ hoặc ngay sau sổ thai nhưng phải chắc chắn rằng không còn thai thứ 2.\n- Xử trí tích cực giai đoạn III bao gồm: tiêm oxytocin, kéo nhẹ dây rốn có kiểm soát và xoa tử cung.\nư Misoprostol 200 àg x 2 viờn đặt trực tràng sau sổ rau.\n\nHình 1. Ðờ tử cung và xử trí ép tử cung bằng 2 tay\n2.3. Lộn lòng tử cung\nLà biến chứng hiếm gặp, do các nguyên nhân: kéo dây rốn, đẩy đáy tử cung khi sổ rau. Triệu chứng thường gặp là đau dữ dội, chảy máu nhiều, choáng, mót rặn. Mót rặn chỉ gặp trong hai trường hợp sau đẻ, đó là khối máu tụ âm đạo, tiểu khung hoặc lộn lòng tử cung.\nKhám bụng: tuỳ theo mức độ có thể thấy lõm ở đáy tử cung, hoặc không sờ thấy tử cung trên vệ. Khám âm đạo thấy khối tử cung trong âm đạo, mềm, đau, có thể co bóp, có vòng thắt tử cung trên khối đó.\nXử trí: nếu chẩn đoán sớm có thể đẩy tử cung trở lại, sau đó tiêm oxytocin và phải giữ tay trong lòng tử cung để kiểm soát sự co bóp của tử cung, nếu thất bại phải mổ thắt động mạch tử cung, thực hiện mũi khâu B-Lynch cải tiến (khâu 2 đai cạnh tử cung) nếu không cầm máu được thì cắt tử cung.\n\nHình 2. Ðẩy tử cung trở lại trong lộn lòng tử cung\n2.4. Rau cài răng lược\nỞ người có tiền sử đẻ nhiều lần, nạo thai nhiều lần, viêm niêm mạc tử cung; chất lượng niêm mạc tử cung không còn tốt nên các gai rau bám trực tiếp vào cơ tử cung (không có lớp xốp của ngoại sản mạc), có khi gai rau xuyên sâu vào chiều dày lớp cơ tử cung. Có thể chỉ một phần bánh rau bám vào lớp cơ hay toàn bộ bánh rau bám vào lớp cơ, người ta phân  rau cài răng lược thành các loại sau:\nRau cài răng lược toàn phần: toàn bộ bánh rau bám vào lớp cơ tử cung do đó không bong ra được và không chảy máu.\nRau cài răng lược bán phần: chỉ một phần bánh rau bám sâu vào cơ tử cung do đó bánh rau có thể bong một phần, gây chảy máu. Lượng máu chảy tùy thuộc vào vào tình trạng co của lớp cơ tử cung và mức độ bong rau.\nCó 3 mức độ cài của gai rau:\n+ Rau bám chặt.\n+ Rau bám xuyên cơ tử cung.\n+ Rau xuyên thủng cơ tử cung, có thể bám vào các tạng lân cận.\n2.4.1. Triệu chứng lâm sàng\n- Nếu rau cài răng lược toàn phần thì sau sổ thai một giờ rau vẫn không bong, tuy không chảy máu.\n- Nếu rau cài răng lược bán phần thì sau khi thai sổ, rau vẫn không bong hết nên không sổ được, chảy máu nhiều hay ít tùy theo diện rau đã bong rộng hay hẹp.\n- Chỉ có thể chẩn đoán chắc chắn dựa vào thử bóc rau không kết quả hay chỉ bóc được một phần và máu chảy nhiều.\n-  Cần chú ý phân biệt với rau mắc kẹt (rau bị cầm tù):\nTrường hợp này bánh rau đã bong nhưng không sổ tự nhiên được vì bị mắc kẹt trong tử cung do vòng thắt của lớp cơ đan. Đặc biệt bánh rau dễ bị mắc kẹt trong trường hợp tử cung hai sừng, khi ấy chỉ cần cho tay vào buồng tử cung sẽ lấy được rau ra vì bánh rau đã bong hoàn toàn.\n2.4.2. Xử trí\nNếu máu chảy trong thời kỳ sổ rau hoặc trên một giờ rau không bong thì bóc rau nhân tạo, kiểm soát tử cung.\n\nHình 3. Bóc rau bằng tay\nNếu bóc rau không được do rau bám xuyên vào cơ tử cung, phải mổ cắt tử cung bán phần, hồi sức, truyền dịch, truyền máu trong và sau mổ.\nTrường hợp rau tiền đạo cài răng lược phải cắt tử cung bán phần thấp hoặc cắt tử cung hoàn toàn để cầm máu.\nTuyến xã: nếu chảy máu khi rau chưa bong thì bóc rau nhân tạo, kiểm soát tử cung và dùng oxytocin. Nếu rau không bong và không chảy máu thì chuyển tuyến trên.\nTuyến huyện: bóc rau nhân tạo, kiểm soát tử cung, nếu bóc không được thì cắt tử cung bán phần.\n\n3. CHẤN THƯƠNG ĐƯỜNG SINH DỤC\n3.1. Vỡ tử cung\nXem bài \"Vỡ tử cung\"\n3.2. Rách âm hộ, âm đạo, tầng sinh môn\n3.2.1 Nguyên nhân\n- Về phía mẹ: tầng sinh môn rắn ở người sinh con so lớn tuổi, nhiễm khuẩn, phù nề và có sẹo cũ ở tầng sinh môn.\n- Về phía thai: thai to, thai sổ kiểu chẩm cùng, sổ đầu hậu trong ngôi mông\n-  Do thủ thuật: đẻ hỗ trợ bằng forceps, giác hút..\n3.2.2.Chẩn đoán:\nSau khi sổ thai thấy máu vẫn chảy ra, có thể nhìn thấy ngay máu chảy từ vết rách hay vết cắt tầng sinh môn, cần kiểm tra kỹ chỗ rách để xác định mức độ rách tầng sinh môn:\n- Độ I: rách da và niêm mạc âm đạo.\n- Độ II: rách da, niêm mạc âm đạo và một phần cơ tầng sinh môn (thường là cơ hành hang).\n_ Độ III: rách cơ tầng sinh môn tới tận nút thớ trung tâm.\n- Độ IV: rách qua nút thớ trung tâm tới tận phên trực tràng âm đạo, làm âm đạo thông với trực tràng.\n3.2.2 Xử trí\n- Gây tê tại chỗ hoặc sử dụng các thuốc giảm đau.\n- Khâu phục hồi sau khi sổ rau và biết chắc là tử cung không còn sót rau.\n- Khâu từ trong ra ngoài, từ lớp sâu đến nông, khâu mũi rời, các mũi cách rau 0,5 cm. Mũi khâu đầu tiên của lớp niêm mạc phải trên đỉnh vết rách 0,5 - 1 cm.\n- Khâu 3 lớp: lớp niêm mạc và lớp cơ ở trong bằng catgut, lớp da ở ngoài bằng chỉ không tiêu; Không để khoảng trống giữa 2 lớp, không để lệch hoặc chồng mép. Riêng đối với rách tầng sinh môn độ IV, vì phẫu thuật phức tạp, vết rách khó liền do sản dịch và nước tiểu gây nhiễm khuẩn tại chỗ, chỉ nên khâu phục hồi sau khi hết thời kỳ hậu sản.\n\nHình 4. Rách âm đạo - tầng sinh môn và kỹ thuật khâu\n3.2.3. Chăm sóc\n- Giữ vết khâu luôn sạch: phải rửa âm hộ ngày 2 - 3 lần nhất là sau đại tiện, tiểu tiện.\n- Giữ vết khâu khô: sau khi rửa phải thấm khô.\n- Chế độ ăn: ăn nhẹ, tránh táo bón.\n- Nếu vết khâu phù nề cần cắt chỉ sớm.\n- Cắt chỉ sau 5 ngày.\n3.2.4. Dự phòng :\n- Hướng dẫn cho sản phụ cách rặn đẻ.\n- Giữ tầng sinh môn đúng phương pháp khi sổ thai.\n- Đỡ đẻ đúng kỹ thuật.\n- Cắt tầng sinh môn khi có chỉ định.\n3.3. Rách cổ tử cung\n3.3.1. Nguyên nhân\nTất cả các trường hợp chảy máu ngay sau đẻ, phải kiểm tra cổ tử cung. Tần suất có thể gặp 11% ở con so, 4% ở con rạ. Rách thường ở hai vị trí 3 - 9 giờ, có thể kéo lên đến vòm âm đạo, đôi khi rách cổ tử cung lên đến đoạn dưới. Rách cổ tử cung có thể gặp khi sổ thai mà cổ tử cung chưa mở hết, sinh thủ thuật, đẻ nhanh, cổ tử cung xơ chai.\n3.3.2. Chẩn đoán\nSau khi sổ thai hoặc rau máu ra nhiều màu đỏ tươi, kiểm tra cổ tử cung thấy có chỗ rách nham nhở hoặc không liên tục, đang chảy máu (lưu ý vị trí 3 giờ và 9 giờ).\nRách nông: đỉnh vết rách ở dưới chỗ bám âm đạo - cổ tử cung.\nRách sâu: Đỉnh vết rách ở trên chỗ bám âm đạo -cổ tử cung, phải kiểm tra kỹ xem có vỡ tử cung, rách bàng quang hoặc tổn thương trực tràng.\n3.3.2. Xử trí\nĐánh giá cẩn thận tổn thương, phải thấy rõ đỉnh vết rách, khâu phục hồi vết rách bằng các mũi rời. Trường hợp rách trên âm đạo, nếu ngoài phúc mạc có thể khâu đường dưới, nếu trong phúc mạc đôi khi phải phẫu thuật.\n\nHình 5. Khâu vết rách cổ tử cung\n4. BỆNH LÝ RỐI LOẠN ĐÔNG CHẢY  MÁU\n4.1. Nguyên nhân\nChảy máu do bệnh lý rối loạn đông máu thường nặng, có thể gặp trong các bệnh lý sản khoa như rau bong non, thai chết trong tử cung, nhiễm trùng tử cung, tắc mạch nước ối, hoặc một số bệnh lý nội khoa khác như viêm gan siêu vi cấp, xuất huyết giảm tiểu cầu,…\n4.2. Các yếu tố chẩn đoán sinh học\n- Tăng thời gian Quick\n- Tăng thời gian hoạt hoá cephaline\n- Giảm số lượng tiểu cầu\n- Giảm fibrinogen.\n- Giảm tỷ lệ của các yếu tố II, V, giảm Antithrombin III, tăng các sản phẩm thoái hoá fibrin (PDF).\n4.3. Điều trị\n- Điều trị: bổ sung các yếu tố thiếu: truyền máu tươi, plasma tươi, cung cấp các yếu tố đông máu. Fibrinogen cô đặc được chỉ định trong trường hợp giảm fibrinogen nặng.\n- Heparin ít sử dụng trong chảy máu sản khoa.\n- Sau khi điều chỉnh các yếu tố đông máu và ngừng chảy máu, nên dự phòng tắc mạch do huyết khối  bằng calciparin trong 21 ngày.\n- Phẫu thuật cắt tử cung bán phần kèm buộc động mạch hạ vị trong một số trường hợp có chỉ định.\n5. ĐỀ PHÒNG CHẢY MÁU SAU SINH\n- Sử dụng biểu đồ chuyển dạ để phát hiện chuyển dạ bất thường và phải xử trí thích hợp\n- Sử dụng thuốc tăng và giảm co đúng chỉ đinh, liều lượng\n- Đỡ đẻ đúng kỹ thuật\n- Kiểm tra rau và màng rau tránh để sót rau, sót màng\n- Sau sinh phải kiểm tra ống đẻ để phát hiện các tổn thương\n- Tư vấn và vận động thực hiện sinh đẻ có kế hoạch\nCâu hỏi:\nCâu 1: Trình bày nguyên nhân, triệu chứng lâm sàng của đờ tử cung sau đẻ\nCâu 2: Trình bày các triệu chứng lâm sàng của rau cài răng lược?\nCâu 3: Trình bày nguyên nhân, triệu chứng lâm sàng của sót rau sau đẻ?\nCâu 4:  Trình bày nguyên nhân của rách tầng sinh môn?\nCâu 5: Trình bày nguyên nhân, triệu chứng lâm sàng và hướng xử trí của rách âm đạo?\nCâu 6: Trình bày nguyên nhân, triệu chứng lâm sàng và hướng xử trí rách cổ tử cung sau đẻ?\nCâu 7:Trình bày  nguyên nhân, triệu chứng lâm sàng và hướng xử trí của rối loạn đông máu sau đẻ băng huyết?\nCâu 8:Trình bày hướng xử trí  ban đầu của đở tử cung sau đẻ ở tuyến cơ sở?\nCâu 9: Trình bày hướng xử trí  ban đầu của rau cài răng lược ở tuyến cơ sở?\nCâu 10: Trình bày hướng xử trí  ban đầu của sót rau ở tuyến cơ sở?\nCâu 11:Trình bày  triệu chứng lâm sàng và hướng xử trí của rách tầng sinh môn?", "priority": "Cao (Trọng tâm BSNT)"}, {"id": "SK-34", "chapter": "Chương 2. Sản bệnh", "folder": "02_San_benh", "title": "Suy thai", "author": "Ths. Đinh Văn Hoành", "word_count": 3077, "line_count": 175, "key_numbers": ["10 phút", "12 giờ", "2 phút", "200ml", "23cm", "250 ml", "28 tuần", "3 tuần", "30 phút", "30 tuần", "32 tuần", "34 tuần", "36 tuần", "38 tuần", "50mmHg", "5cm", "7cm"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["SUY THAI", "Ths. Đinh Văn Hoành"], "bullets": []}, {"heading": "Mục tiêu học tập", "paragraphs": ["Mô tả được các triệu chứng của suy thai cấp và suy thai mãn", "Trình bày được các nguyên tắc xử trí suy thai cấp và mãn"], "bullets": []}, {"heading": "1. ĐỊNH NGHĨA VÀ PHÂN LOẠI", "paragraphs": ["Suy thai là một quá trình bệnh lý do tình trạng thai thiếu oxy trong máu hoặc thiếu oxy tổ chức khi thai đang sống trong tử cung. Hiện nay, người ta còn gọi suy thai là tình trạng bất ổn của thai nhi bao gồm: giảm thành phần oxy trong máu, giảm oxy trong tổ chức, tình trạng tăng ion hydro trong máu (thai nhi nhiễm toan), biểu hiện với những thay đổi về nhịp tim thai được ghi nhận bằng máy theo dõi nhịp tim thai (ví dụ: nhịp giảm biến đổi lặp lại, nhịp giảm muộn, nhịp nhanh, nhịp chậm hoặc tình trạng bất thường).", "Suy thai cấp thường xảy ra đột ngột trong quá trình chuyển dạ, đe doạ tính mạng đứa bé, ảnh hưởng đến sự phát triển tinh thần, thể chất của đứa bé trong tương lai nếu không được phát hiện và xử trí kịp thời. Đánh giá được tình trạng sức khoẻ của thai nhi trong chuyển dạ có ý nghĩa quan trọng nhằm đảm bảo một cuộc đẻ an toàn cho cả mẹ và con. Suy thai cấp chiếm tỷ lệ dưới 20% các cuộc đẻ.", "Suy thai mãn xảy ra từ từ trong quá trình mang thai, các triệu chứng thường không rầm rộ, tuy nhiên có thể nhanh chóng chuyển thành suy thai cấp khi chuyển dạ."], "bullets": []}, {"heading": "2. SINH LÝ BỆNH", "paragraphs": ["Nếu tình trạng thai suy không được xử trí kịp thời, tình trạng thiếu ôxy kéo dài đứa trẻ sinh ra có thể bị các bệnh lý sau:"], "bullets": ["- Sự thích nghi: Khi thiếu ôxy sẽ xảy ra hiện tượng co mạch ngoại vi nhưng não và cơ trơn có hiện tượng giãn mạch để tăng sự tưới máu, đảm bảo cho chức năng sống của các cơ quan quan trọng. Trong giai đoạn đầu tiếng tim vẫn bình thường do thai nhi trưởng thành có dự trữ ôxy đảm bảo cho 2 phút nếu trao đổi khí bị cản trở", "- Thay đổi tần số tim thai: Bình thường lưu lượng máu qua thai là 180-200ml/kg/phút. Khi có tình trạng giảm oxy sẽ xảy ra hiện tượng co thắt mạch máu làm tăng áp lực tưới máu ở não, tim, thượng thận. Đồng thời hệ thống nhận cảm áp lực, nhận cảm hoá học hoạt động làm tăng nhịp tim thai. Tuy nhiên, nếu tình trạng thiếu oxy kéo dài thì bản thân cơ tim cũng sẽ thiếu oxy, nhịp tim sẽ chậm dần và ngưng đập.", "- Sự thải phân su vào nước ối: Do hiện tượng giảm oxy và tăng CO2 trong máu thai nhi nên xảy ra tình trạng tăng nhu động ruột, giãn cơ vòng hậu môn nên phân su được tống vào buồng ối làm cho nước ối lẫn phân su hoặc có màu xanh.", "- Sự thay đổi về sinh hoá:", "+ Toan hô hấp: Khởi đầu là toan hô hấp do sự gia tăng của CO2 trong máu, có thể hồi phục nếu sự trao đổi máu mẹ và con bình thường.", "+ Toan chuyển hoá: Tình trạng thiếu oxy kéo dài buộc các cơ quan phải chuyển hoá yếm khí tạo ra các sản phẩm chuyển hoá trung gian là Axít Lactic, Axít Pyruvic... các sản phẩm này tích tụ lại làm nặng thêm tình trạng toan máu. Nếu tình trạng toan kéo dài các cơ quan  không thể hồi phục. Giai đoạn cuối cùng là cơ tim bị ức chế, tim đập chậm lại,  pH máu thai giảm < 7,25 thai chết.", "- Hậu quả đối với trẻ sơ sinh:", "+ Tổn thương não, phù não, hôn mê, co giật, xuất huyết não", "+ Tim to do thiếu oxy kéo dài", "+ Suy thận chức năng", "+ Suy gan với vàng da do tăng bilirubin gián tiếp", "+ Rối loạn chức năng đông máu", "+ Có thể gặp viêm ruột hoại tử", "+ Tử vong sơ sinh có thể xảy ra"]}, {"heading": "3.1. Các nguyên nhân về phía mẹ", "paragraphs": ["Các yếu tố làm giảm lưu lượng tuần hoàn tử cung - rau:"], "bullets": ["- Gia tăng sức cản ngoại vi làm luồng máu từ mẹ đến hồ huyết  bị giảm.", "- Cơn co tử cung: Trong mỗi cơn co tử cung, tuần hoàn tử cung - rau bị gián đoạn trong 15-60 giây, lượng máu cung cấp sẽ bị giảm đi khoảng 50%. Thật vậy, khi xuất hiện cơn co tử cung có áp lực > 50mmHg các động mạch bị chèn ép nên lượng máu đến hồ huyết giảm. Thai nhi sống đựoc nhờ có dự trữ ô-xy, năng lượng trong hồ huyết (tổng lượng máu dự trữ trong hồ huyết khoảng 250 ml). Thời gian ngừng lưu thông máu giữa mẹ và con thường ngắn, nên thai bình thường có thể chịu đựng được. Nếu tần số, cường độ cơn co tăng, thời gian cơn co kéo dài sẽ làm tăng thời gian ngừng lưu thông máu giữa mẹ và con, dẫn đến thai không thể hồi phục giữa các cơn co...", "- Tư thế nằm ngửa của sản phụ làm tử cung đè ép vào động mạch chủ gây giảm dòng chảy của máu mẹ đến tử cung. Tử cung có thể đè lên tĩnh mạch chủ làm giảm lưu lượng máu trở về tim, gây hạ huyết áp và giảm tưới máu. Tình trạng này được giải quyết khi thay đổi tư thế của bà mẹ sang tư thế nằm nghiêng.", "- Chảy máu ở mẹ: Tình trạng chảy máu ở mẹ làm tụt huyết áp đưa đến suy thai. Trong rau bong non khối máu tụ sau rau còn làm cắt đứt sự trao đổi máu giữa mẹ và con.", "- Mẹ bị thiếu máu mãn, nhiễm trùng.", "- Vì bất cứ nguyên nhân gì, nếu có tình trạng giảm tuần hoàn ngoại vi ở bà mẹ  đều có thể gây ra tình trạng giảm lưu lượng máu đến tử cung, rau thai từ đó gây tổn hại đến thai nhi."]}, {"heading": "3.2. Nguyên nhân do thai", "paragraphs": ["Thai non tháng", "Thai chậm phát triển", "Thai già tháng", "Thai dị dạng", "Thai thiếu máu hoặc nhiễm trùng"], "bullets": []}, {"heading": "3.3. Nguyên nhân do phần phụ của thai", "paragraphs": ["Rau tiền đạo, rau bong non", "Bánh rau vôi hoá trong thai già tháng", "Sa dây rốn, dây rốn thắt nút", "Vỡ mạch máu rốn (trong trường hợp dây rốn bám màng…)", "Ối vỡ non, ối vỡ sớm"], "bullets": []}, {"heading": "3.4. Nguyên nhân sản khoa", "paragraphs": ["Các trường hợp đẻ khó do nguyên nhân cơ học", "Bất tương xứng đầu -chậu", "Ngôi thai bất thường", "Chuyển dạ kéo dài", "Rối loạn cơn co (tăng tần số và trương lực)"], "bullets": []}, {"heading": "3.5. Nguyên nhân do thuốc", "paragraphs": ["Thai nhi bị ức chế do dùng các thuốc gây mê, giảm đau", "Dùng thuốc tăng co không kiểm soát làm tăng cơn co."], "bullets": []}, {"heading": "41.1. Lâm sàng", "paragraphs": ["Cử động thai: Bình thường thai máy trong quá trình mang thai, thai ít máy tức là trương lực cơ giảm có thể có suy thai. Mức hoạt động của thai trung bình 90 lần trong 12 giờ ở tuổi thai 32 tuần và khoảng 50 lần trong 12 giờ khi thai đủ tháng. Khi thai có sự giảm cử động gợi ý thai thiếu oxy. Ví dụ: khi thai 38 tuần nếu bà mẹ cảm nhận cử động thai nhi dưới 4 lần/giờ là có lý do để lo lắng và cần phải có những kiểm tra."], "bullets": ["- Chiều cao tử cung nhỏ hơn so với tuổi thai: Bề cao tử cung nhỏ hơn số tuần 5cm kể từ tuần thứ 16 đến 32. Ví dụ: Bề cao 23cm trong khi tuổi thai 28 tuần.", "- Giảm cử động thai.", "- Nhịp tim thai thay đổi: tần số dưới 120 lần/phút hoặc trên 160 lần/phút.", "- Sờ nắn được các phần thai qua da bụng chứng tỏ có thiểu ối."]}, {"heading": "4.1.2. Cận lâm sàng", "paragraphs": ["Biên độ dao động giảm", "Giảm các nhịp tăng về biên độ và thời gian", "Có thể xuất hiện nhịp giảm", "Tăng hoặc giảm tần số tim thai cơ bản", "Test dương tính: khi có nhịp giảm muộn trong ít nhất là 50% số cơn co.", "Test âm tính: không có nhịp giảm.", "Chấm dứt kích thích ngay khi có các dấu hiệu sau:", "Xuất hiện nhịp chậm muộn tương ứng với mỗi cơn co", "Nếu cơn co kéo dài quá 90 giây", "Nếu khoảng cách giữa 2 cơn co ngắn hơn 20 giây", "Nếu cơn co cường tính."], "bullets": ["- Siêu âm", "+ Đo kích thước của thai để suy ra trọng lượng thai, sau đó so sánh với trị số mẫu. Đo đường kính lưỡng đỉnh, chu vi vòng bụng, chiều dài xương đùi dưới đường Percentile thứ 10.", "+ Đánh giá tình trạng rau thai và nước ối. Nếu độ trưởng thành (độ can-xi hoá) của rau cao hơn so với tuổi thai có thể là một trong những biểu hiện của thai  kém phát triển trong buồng tử cung. Thể tích nước ối giảm được biểu hiện qua chỉ số nước ối (AFI) < 7cm", "+ Siêu âm Doppler đo trở kháng động mạch rốn RI ≥ 0,8.", "+ Siêu âm xác định tuổi thai và theo dõi độ phát triển của thai, so sánh các trị số hàng tuần để đánh giá.", "- Theo dõi bằng Monitoring sản khoa", "+ Thử nghiệm không đả kích: Ghi nhịp tim thai khi chưa có cơn go tử cung. Trong suy thai mãn có thể có các dấu hiệu sau:", "+ Test đả kích: Thử nghiệm ôxytôxin hay test vê núm vú để khảo sát sức chịu đựng của thai nhi trong tử cung khi có cơn co tử cung."]}, {"heading": "4.2.1. Lâm sàng", "paragraphs": ["* Thay đổi về tim thai", "Thiếu oxy còn bù.", "Mẹ bị thiếu máu.", "Mẹ sốt, nhiễm trùng.", "Do dùng thuốc (tăng co, kích thích β,Atropin…)", "Thai non tháng.", "Nhiễm trùng ối.", "Mẹ lo lắng, kích thích.", "Bệnh lý tim bẩm sinh của thai.", "Thiếu oxy mất bù.", "Chèn ép cuống rốn (do phản xạ cuống rốn).", "Hạ thân nhiệt.", "Mẹ dùng thuốc.(ức chế β, Magnésium sulfate…)", "Bệnh lý tim bẩm sinh của thai.", "Dị dạng thai.", "Khi xuất hiện nhịp tim thai chậm là dấu hiệu cảnh báo cần có thái độ xử trí tích cực", "* Thay đổi nước ối", "Ngoại trừ ngôi mông khi đã lọt, mọi trường hợp có phân su trong nước ối đều cho biết thai đã hoặc đang suy. Phân su trong nước ối là tình trạng thường gặp, khoảng 20-23% các cuộc chuyển dạ đủ tháng có hiện tượng này, nó có thể liên quan đến tình trạng suy thai ở một số trường hợp. Trong trường hợp không có máy theo dõi tim thai liên tục (monitoring), để an toàn có thể coi tình trạng có phân su trong nước ối như là dấu hiệu của suy thai."], "bullets": ["- Thay đổi tần số: Bình thường tim thai có tần số 120- 160l/phút. Gọi là nhịp tim thai chậm khi tần số dưới 120 l/phút và nhịp tim thai nhanh khi tần số trên 160 l/phút. Người ta thấy rằng với nhịp nhanh từ 160-180 l/phút thì chưa thấy sự tương quan với suy thai, biểu hiện bằng chỉ số APGAR và pH máu sau sinh.", "- Thay đổi tần số tim thai trong và ngoài cơn co: nếu trong cơn co tần số tim thai giảm 1/3 thì phải nghi ngờ có suy thai.", "- Các nguyên nhân làm thay đổi tần số tim thai :", "+ Nguyên nhân của nhịp tim thai nhanh", "+ Nguyên nhân của nhịp tim thai chậm", "- Thay đổi về nhịp tim thai: khi có suy thai tim thai sẽ không đều.", "- Thay đổi về cường độ tim thai: tiếng tim nghe nhỏ, mờ xa xăm.", "+ Nước ối có màu xanh: thể hiện thai có suy trước đây và tạm thời  có tiên lượng gần như ối trong, có khoảng 5% trong số này thai hít nước ối gây ra hội chứng suy hô hấp sơ sinh.", "+ Nước ối có dải phân su đó là tình trạng bài tiết phân su khi còn trong tử cung biểu hiện của thai suy trong chuyển dạ."]}, {"heading": "4.2.2. Cận lâm sàng", "paragraphs": ["Mục đích của việc theo dõi nhịp tim thai trước chuyển dạ hoặc trong chuyển dạ là để phát hiện sớm những thay đổi nồng độ oxy ở thai nhi để đề phòng những tổn thương tổ chức hoặc tử vong cho thai nhi, đặc biệt khi có chuyển dạ. Nhịp tim thai phải được xem xét trong một bối cảnh lâm sàng cụ thể như tuổi thai, tình trạng mẹ, những đánh giá khác về thai nhi, việc sử dụng thuốc.v.v. cần phải theo dõi nhịp tim thai có hệ thống.", "Nhịp tim thai cơ bản 120-160 l/phút", "Có ít nhất hai nhịp tăng trong 10 phút", "Dao động nội tại 5-25 l/phút", "Không có nhip giảm", "Nhịp tim thai cơ bản dưới 120 hoặc trên 160 lần/phút", "Dao động nội tại dưới 5 nhịp/phút, kéo dài trên 30 phút", "Xuất hiện nhịp giảm chậm, giảm kéo dài và nhịp giảm biến đổi", "Hiện nay xét nghiệm này hầu như không còn được sử dụng."], "bullets": ["- Monitoring sản khoa", "+Nhịp tim thai bình thường trên Monitoring sản khoa:", "+Khi thai suy, nhịp tim thai trên Monitoring có thể biểu hiện:", "-  Soi ối: Có thể kiểm tra màu sắc của nước ối ngay giai đoạn đầu của chuyển dạ bằng phương pháp soi ối. Bình thường nước ối trong hoặc có lẫn ít chất gây. Nước ối xanh hoặc lẫn phân su là có biểu hiện của suy thai. Ngày nay soi ối ít được sử dụng.", "-  Đo pH máu da đầu", "+ Bình thường pH lúc bắt đầu chuyển dạ 7,29 ± 0,05 duy trì trong suốt cuộc chuyển dạ nếu không có suy thai.", "+ Khi cổ tử cung mở hết pH giảm nhẹ 7,28 ± 0,05", "+ Khi rặn sổ giảm còn 7,23 ± 0,06", "+ Có mối liên hệ giữa nhịp giảm muộn và pH với chỉ số APGAR xấu, khi pH <7,25 là nghi ngờ nếu pH < 7,20 là bệnh lý."]}, {"heading": "5.1 Nguyên tắc xử trí là lấy thai ra khỏi môi trường tử cung đã bất lợi cho thai nhưng phải  đúng lúc, tránh can thiệp quá sớm gây nên biến chứng do thai non tháng.", "paragraphs": ["Nói chung trừ khi thai quá non hoặc thai suy quá nặng nên nghĩ đến chấm dứt thai kỳ khi các số đo sinh học không tăng thêm qua 3 tuần theo dõi.", "Nên mổ lấy thai để tránh nguy cơ gây sang chấn cho con. Theo dõi sinh bằng đường âm đạo khi điều kiện thật thuận lợi và  test đả kích âm tính."], "bullets": ["- Điều trị nội khoa:", "+ Điều trị ổn định bệnh lý của mẹ", "+ Để sản phụ nghỉ ngơi và  tăng cường dinh dưỡng", "+ Dùng Corticoide để kích thích trưởng thành phổi thai nhi khi thai dưới 34 tuần", "- Điều trị sản khoa:", "+ Nếu thai suy nặng, tuổi thai 28-30 tuần: tiên lượng rất xấu, nên chuyển đến những cơ sở đầy đủ điều kiện chăm sóc sơ sinh.", "+ Thai 30-34 tuần: việc chấm dứt thai kỳ cần cân nhắc", "+ Thai  trên 36 tuần: nên chủ động chấm dứt thai kỳ"]}, {"heading": "5.2. Suy thai cấp", "paragraphs": ["Tuỳ nguyên nhân cụ thể gây suy thai cấp mà có hướng xử trí thích hợp."], "bullets": []}, {"heading": "5.2.1. Nội khoa", "paragraphs": ["Cung cấp oxy cho mẹ: cho thở oxy 5-6l /phút, ngắt quãng, nồng độ riêng phần SaO2 của thai có thể tăng được 4-7%.", "Nằm nghiêng trái để hạn chế việc tử cung chèn ép vào các mạch máu lớn ở bụng", "Truyền dịch: nên theo dõi huyết động của mẹ, nếu thấp thì bù dịch để giúp cải thiện nội môi cho thai. Có thể dùng Ringers lactat, Natribicarbonat 4,2%, nếu nhịp tim thai trở lại bình thường có thể theo dõi tiếp. Không nên sử dụng dung dịch Glucôza truyền cho mẹ để hôì sức  thai vì sẽ làm tăng nguy cơ hạ đường máu ở trẻ sơ sinh ngay sau đẻ.", "Cho kháng sinh khi có biểu hiện nhiễm trùng, hạ sốt khi sốt trên 38,50C."], "bullets": []}, {"heading": "5.2.2. Sản khoa", "paragraphs": ["Tìm kiếm các nguyên nhân gây suy thai để có hướng xử trí thích hợp"], "bullets": ["+ Nếu cơn co mạnh, dày thì cho thuốc giảm co (No-spa, Buscopan...). Nếu đang sử dụng ôxytoxin thì ngừng sử dụng hoặc làm giảm tốc độ truyền ôxytoxin. Việc sử dụng ôxytoxin trong chuyển dạ là nguyên nhân số một gây suy thai cấp trong phần lớn các trường hợp.", "+ Sa dây rốn: nếu cuống rốn còn đập thì cho mẹ nằm mông cao, lấy gạc tẩm dung dịch Natri Clorua 0,9% ấm để bọc cuống rốn, chuyển mổ lấy thai cấp cứu.", "+ Nếu không tìm được nguyên nhân, điều trị suy thai không kết quả thì tuỳ điều kiện mà mổ lấy thai hoặc đặt forceps nếu đủ điều kiện (đầu lọt, thai sống, không có bất tương xứng đầu chậu).", "+ Nếu nước ối đặc phân su, nên mổ lấy thai."]}, {"heading": "5.2.3. Dự phòng", "paragraphs": ["Theo dõi chuyển dạ bằng biểu đồ chuyển dạ để phát hiện sớm suy thai và can thiệp lấy thai ra kịp thời", "Đánh giá đúng tình trạng bệnh lý của mẹ và thai", "Theo dõi liên tục tim thai 15-30 phút/lần phù hợp với chuyển dạ", "Điều chỉnh cơn co cho phù hợp với giai đoạn chuyển dạ", "Nếu có điều kiện nên theo dõi tim thai liên tục với Monitoring sản khoa, phát hiện sớm các nhịp tim thai bất thường."], "bullets": []}], "raw_text": "SUY THAI\nThs. Đinh Văn Hoành\nMục tiêu học tập\nMô tả được các triệu chứng của suy thai cấp và suy thai mãn\nTrình bày được các nguyên tắc xử trí suy thai cấp và mãn\n\n1. ĐỊNH NGHĨA VÀ PHÂN LOẠI\nSuy thai là một quá trình bệnh lý do tình trạng thai thiếu oxy trong máu hoặc thiếu oxy tổ chức khi thai đang sống trong tử cung. Hiện nay, người ta còn gọi suy thai là tình trạng bất ổn của thai nhi bao gồm: giảm thành phần oxy trong máu, giảm oxy trong tổ chức, tình trạng tăng ion hydro trong máu (thai nhi nhiễm toan), biểu hiện với những thay đổi về nhịp tim thai được ghi nhận bằng máy theo dõi nhịp tim thai (ví dụ: nhịp giảm biến đổi lặp lại, nhịp giảm muộn, nhịp nhanh, nhịp chậm hoặc tình trạng bất thường).\nSuy thai cấp thường xảy ra đột ngột trong quá trình chuyển dạ, đe doạ tính mạng đứa bé, ảnh hưởng đến sự phát triển tinh thần, thể chất của đứa bé trong tương lai nếu không được phát hiện và xử trí kịp thời. Đánh giá được tình trạng sức khoẻ của thai nhi trong chuyển dạ có ý nghĩa quan trọng nhằm đảm bảo một cuộc đẻ an toàn cho cả mẹ và con. Suy thai cấp chiếm tỷ lệ dưới 20% các cuộc đẻ.\nSuy thai mãn xảy ra từ từ trong quá trình mang thai, các triệu chứng thường không rầm rộ, tuy nhiên có thể nhanh chóng chuyển thành suy thai cấp khi chuyển dạ.\n\n2. SINH LÝ BỆNH\n- Sự thích nghi: Khi thiếu ôxy sẽ xảy ra hiện tượng co mạch ngoại vi nhưng não và cơ trơn có hiện tượng giãn mạch để tăng sự tưới máu, đảm bảo cho chức năng sống của các cơ quan quan trọng. Trong giai đoạn đầu tiếng tim vẫn bình thường do thai nhi trưởng thành có dự trữ ôxy đảm bảo cho 2 phút nếu trao đổi khí bị cản trở\n- Thay đổi tần số tim thai: Bình thường lưu lượng máu qua thai là 180-200ml/kg/phút. Khi có tình trạng giảm oxy sẽ xảy ra hiện tượng co thắt mạch máu làm tăng áp lực tưới máu ở não, tim, thượng thận. Đồng thời hệ thống nhận cảm áp lực, nhận cảm hoá học hoạt động làm tăng nhịp tim thai. Tuy nhiên, nếu tình trạng thiếu oxy kéo dài thì bản thân cơ tim cũng sẽ thiếu oxy, nhịp tim sẽ chậm dần và ngưng đập.\n- Sự thải phân su vào nước ối: Do hiện tượng giảm oxy và tăng CO2 trong máu thai nhi nên xảy ra tình trạng tăng nhu động ruột, giãn cơ vòng hậu môn nên phân su được tống vào buồng ối làm cho nước ối lẫn phân su hoặc có màu xanh.\n- Sự thay đổi về sinh hoá:\n+ Toan hô hấp: Khởi đầu là toan hô hấp do sự gia tăng của CO2 trong máu, có thể hồi phục nếu sự trao đổi máu mẹ và con bình thường.\n+ Toan chuyển hoá: Tình trạng thiếu oxy kéo dài buộc các cơ quan phải chuyển hoá yếm khí tạo ra các sản phẩm chuyển hoá trung gian là Axít Lactic, Axít Pyruvic... các sản phẩm này tích tụ lại làm nặng thêm tình trạng toan máu. Nếu tình trạng toan kéo dài các cơ quan  không thể hồi phục. Giai đoạn cuối cùng là cơ tim bị ức chế, tim đập chậm lại,  pH máu thai giảm < 7,25 thai chết.\n\n- Hậu quả đối với trẻ sơ sinh:\nNếu tình trạng thai suy không được xử trí kịp thời, tình trạng thiếu ôxy kéo dài đứa trẻ sinh ra có thể bị các bệnh lý sau:\n+ Tổn thương não, phù não, hôn mê, co giật, xuất huyết não\n+ Tim to do thiếu oxy kéo dài\n+ Suy thận chức năng\n+ Suy gan với vàng da do tăng bilirubin gián tiếp\n+ Rối loạn chức năng đông máu\n+ Có thể gặp viêm ruột hoại tử\n+ Tử vong sơ sinh có thể xảy ra\n\n3. NGUYÊN NHÂN\n3.1. Các nguyên nhân về phía mẹ\nCác yếu tố làm giảm lưu lượng tuần hoàn tử cung - rau:\n- Gia tăng sức cản ngoại vi làm luồng máu từ mẹ đến hồ huyết  bị giảm.\n- Cơn co tử cung: Trong mỗi cơn co tử cung, tuần hoàn tử cung - rau bị gián đoạn trong 15-60 giây, lượng máu cung cấp sẽ bị giảm đi khoảng 50%. Thật vậy, khi xuất hiện cơn co tử cung có áp lực > 50mmHg các động mạch bị chèn ép nên lượng máu đến hồ huyết giảm. Thai nhi sống đựoc nhờ có dự trữ ô-xy, năng lượng trong hồ huyết (tổng lượng máu dự trữ trong hồ huyết khoảng 250 ml). Thời gian ngừng lưu thông máu giữa mẹ và con thường ngắn, nên thai bình thường có thể chịu đựng được. Nếu tần số, cường độ cơn co tăng, thời gian cơn co kéo dài sẽ làm tăng thời gian ngừng lưu thông máu giữa mẹ và con, dẫn đến thai không thể hồi phục giữa các cơn co...\n- Tư thế nằm ngửa của sản phụ làm tử cung đè ép vào động mạch chủ gây giảm dòng chảy của máu mẹ đến tử cung. Tử cung có thể đè lên tĩnh mạch chủ làm giảm lưu lượng máu trở về tim, gây hạ huyết áp và giảm tưới máu. Tình trạng này được giải quyết khi thay đổi tư thế của bà mẹ sang tư thế nằm nghiêng.\n- Chảy máu ở mẹ: Tình trạng chảy máu ở mẹ làm tụt huyết áp đưa đến suy thai. Trong rau bong non khối máu tụ sau rau còn làm cắt đứt sự trao đổi máu giữa mẹ và con.\n- Mẹ bị thiếu máu mãn, nhiễm trùng.\n- Vì bất cứ nguyên nhân gì, nếu có tình trạng giảm tuần hoàn ngoại vi ở bà mẹ  đều có thể gây ra tình trạng giảm lưu lượng máu đến tử cung, rau thai từ đó gây tổn hại đến thai nhi.\n3.2. Nguyên nhân do thai\nThai non tháng\nThai chậm phát triển\nThai già tháng\nThai dị dạng\nThai thiếu máu hoặc nhiễm trùng\n3.3. Nguyên nhân do phần phụ của thai\nRau tiền đạo, rau bong non\nBánh rau vôi hoá trong thai già tháng\nSa dây rốn, dây rốn thắt nút\nVỡ mạch máu rốn (trong trường hợp dây rốn bám màng…)\nỐi vỡ non, ối vỡ sớm\n3.4. Nguyên nhân sản khoa\nCác trường hợp đẻ khó do nguyên nhân cơ học\nBất tương xứng đầu -chậu\nNgôi thai bất thường\nChuyển dạ kéo dài\nRối loạn cơn co (tăng tần số và trương lực)\n3.5. Nguyên nhân do thuốc\nThai nhi bị ức chế do dùng các thuốc gây mê, giảm đau\nDùng thuốc tăng co không kiểm soát làm tăng cơn co.\n\n4. TRIỆU CHỨNG VÀ CHẨN ĐOÁN\n4.1. Suy thai mãn\n41.1. Lâm sàng\n- Chiều cao tử cung nhỏ hơn so với tuổi thai: Bề cao tử cung nhỏ hơn số tuần 5cm kể từ tuần thứ 16 đến 32. Ví dụ: Bề cao 23cm trong khi tuổi thai 28 tuần.\n- Giảm cử động thai.\nCử động thai: Bình thường thai máy trong quá trình mang thai, thai ít máy tức là trương lực cơ giảm có thể có suy thai. Mức hoạt động của thai trung bình 90 lần trong 12 giờ ở tuổi thai 32 tuần và khoảng 50 lần trong 12 giờ khi thai đủ tháng. Khi thai có sự giảm cử động gợi ý thai thiếu oxy. Ví dụ: khi thai 38 tuần nếu bà mẹ cảm nhận cử động thai nhi dưới 4 lần/giờ là có lý do để lo lắng và cần phải có những kiểm tra.\n- Nhịp tim thai thay đổi: tần số dưới 120 lần/phút hoặc trên 160 lần/phút.\n- Sờ nắn được các phần thai qua da bụng chứng tỏ có thiểu ối.\n4.1.2. Cận lâm sàng\n- Siêu âm\n+ Đo kích thước của thai để suy ra trọng lượng thai, sau đó so sánh với trị số mẫu. Đo đường kính lưỡng đỉnh, chu vi vòng bụng, chiều dài xương đùi dưới đường Percentile thứ 10.\n+ Đánh giá tình trạng rau thai và nước ối. Nếu độ trưởng thành (độ can-xi hoá) của rau cao hơn so với tuổi thai có thể là một trong những biểu hiện của thai  kém phát triển trong buồng tử cung. Thể tích nước ối giảm được biểu hiện qua chỉ số nước ối (AFI) < 7cm\n+ Siêu âm Doppler đo trở kháng động mạch rốn RI ≥ 0,8.\n+ Siêu âm xác định tuổi thai và theo dõi độ phát triển của thai, so sánh các trị số hàng tuần để đánh giá.\n- Theo dõi bằng Monitoring sản khoa\n+ Thử nghiệm không đả kích: Ghi nhịp tim thai khi chưa có cơn go tử cung. Trong suy thai mãn có thể có các dấu hiệu sau:\nBiên độ dao động giảm\nGiảm các nhịp tăng về biên độ và thời gian\nCó thể xuất hiện nhịp giảm\nTăng hoặc giảm tần số tim thai cơ bản\n+ Test đả kích: Thử nghiệm ôxytôxin hay test vê núm vú để khảo sát sức chịu đựng của thai nhi trong tử cung khi có cơn co tử cung.\nTest dương tính: khi có nhịp giảm muộn trong ít nhất là 50% số cơn co.\nTest âm tính: không có nhịp giảm.\nChấm dứt kích thích ngay khi có các dấu hiệu sau:\nXuất hiện nhịp chậm muộn tương ứng với mỗi cơn co\nNếu cơn co kéo dài quá 90 giây\nNếu khoảng cách giữa 2 cơn co ngắn hơn 20 giây\nNếu cơn co cường tính.\n\n4.2. Suy thai cấp\n4.2.1. Lâm sàng\n* Thay đổi về tim thai\n- Thay đổi tần số: Bình thường tim thai có tần số 120- 160l/phút. Gọi là nhịp tim thai chậm khi tần số dưới 120 l/phút và nhịp tim thai nhanh khi tần số trên 160 l/phút. Người ta thấy rằng với nhịp nhanh từ 160-180 l/phút thì chưa thấy sự tương quan với suy thai, biểu hiện bằng chỉ số APGAR và pH máu sau sinh.\n- Thay đổi tần số tim thai trong và ngoài cơn co: nếu trong cơn co tần số tim thai giảm 1/3 thì phải nghi ngờ có suy thai.\n- Các nguyên nhân làm thay đổi tần số tim thai :\n+ Nguyên nhân của nhịp tim thai nhanh\nThiếu oxy còn bù.\nMẹ bị thiếu máu.\nMẹ sốt, nhiễm trùng.\nDo dùng thuốc (tăng co, kích thích β,Atropin…)\nThai non tháng.\nNhiễm trùng ối.\nMẹ lo lắng, kích thích.\nBệnh lý tim bẩm sinh của thai.\n+ Nguyên nhân của nhịp tim thai chậm\nThiếu oxy mất bù.\nChèn ép cuống rốn (do phản xạ cuống rốn).\nHạ thân nhiệt.\nMẹ dùng thuốc.(ức chế β, Magnésium sulfate…)\nBệnh lý tim bẩm sinh của thai.\nDị dạng thai.\nKhi xuất hiện nhịp tim thai chậm là dấu hiệu cảnh báo cần có thái độ xử trí tích cực\n- Thay đổi về nhịp tim thai: khi có suy thai tim thai sẽ không đều.\n- Thay đổi về cường độ tim thai: tiếng tim nghe nhỏ, mờ xa xăm.\n* Thay đổi nước ối\nNgoại trừ ngôi mông khi đã lọt, mọi trường hợp có phân su trong nước ối đều cho biết thai đã hoặc đang suy. Phân su trong nước ối là tình trạng thường gặp, khoảng 20-23% các cuộc chuyển dạ đủ tháng có hiện tượng này, nó có thể liên quan đến tình trạng suy thai ở một số trường hợp. Trong trường hợp không có máy theo dõi tim thai liên tục (monitoring), để an toàn có thể coi tình trạng có phân su trong nước ối như là dấu hiệu của suy thai.\n+ Nước ối có màu xanh: thể hiện thai có suy trước đây và tạm thời  có tiên lượng gần như ối trong, có khoảng 5% trong số này thai hít nước ối gây ra hội chứng suy hô hấp sơ sinh.\n+ Nước ối có dải phân su đó là tình trạng bài tiết phân su khi còn trong tử cung biểu hiện của thai suy trong chuyển dạ.\n4.2.2. Cận lâm sàng\n- Monitoring sản khoa\nMục đích của việc theo dõi nhịp tim thai trước chuyển dạ hoặc trong chuyển dạ là để phát hiện sớm những thay đổi nồng độ oxy ở thai nhi để đề phòng những tổn thương tổ chức hoặc tử vong cho thai nhi, đặc biệt khi có chuyển dạ. Nhịp tim thai phải được xem xét trong một bối cảnh lâm sàng cụ thể như tuổi thai, tình trạng mẹ, những đánh giá khác về thai nhi, việc sử dụng thuốc.v.v. cần phải theo dõi nhịp tim thai có hệ thống.\n+Nhịp tim thai bình thường trên Monitoring sản khoa:\nNhịp tim thai cơ bản 120-160 l/phút\nCó ít nhất hai nhịp tăng trong 10 phút\nDao động nội tại 5-25 l/phút\nKhông có nhip giảm\n+Khi thai suy, nhịp tim thai trên Monitoring có thể biểu hiện:\nNhịp tim thai cơ bản dưới 120 hoặc trên 160 lần/phút\nDao động nội tại dưới 5 nhịp/phút, kéo dài trên 30 phút\nXuất hiện nhịp giảm chậm, giảm kéo dài và nhịp giảm biến đổi\n-  Soi ối: Có thể kiểm tra màu sắc của nước ối ngay giai đoạn đầu của chuyển dạ bằng phương pháp soi ối. Bình thường nước ối trong hoặc có lẫn ít chất gây. Nước ối xanh hoặc lẫn phân su là có biểu hiện của suy thai. Ngày nay soi ối ít được sử dụng.\n-  Đo pH máu da đầu\n+ Bình thường pH lúc bắt đầu chuyển dạ 7,29 ± 0,05 duy trì trong suốt cuộc chuyển dạ nếu không có suy thai.\n+ Khi cổ tử cung mở hết pH giảm nhẹ 7,28 ± 0,05\n+ Khi rặn sổ giảm còn 7,23 ± 0,06\n+ Có mối liên hệ giữa nhịp giảm muộn và pH với chỉ số APGAR xấu, khi pH <7,25 là nghi ngờ nếu pH < 7,20 là bệnh lý.\nHiện nay xét nghiệm này hầu như không còn được sử dụng.\n\n5. HƯỚNG XỬ TRÍ\n5.1 Nguyên tắc xử trí là lấy thai ra khỏi môi trường tử cung đã bất lợi cho thai nhưng phải  đúng lúc, tránh can thiệp quá sớm gây nên biến chứng do thai non tháng.\n- Điều trị nội khoa:\n+ Điều trị ổn định bệnh lý của mẹ\n+ Để sản phụ nghỉ ngơi và  tăng cường dinh dưỡng\n+ Dùng Corticoide để kích thích trưởng thành phổi thai nhi khi thai dưới 34 tuần\n- Điều trị sản khoa:\n+ Nếu thai suy nặng, tuổi thai 28-30 tuần: tiên lượng rất xấu, nên chuyển đến những cơ sở đầy đủ điều kiện chăm sóc sơ sinh.\n+ Thai 30-34 tuần: việc chấm dứt thai kỳ cần cân nhắc\n+ Thai  trên 36 tuần: nên chủ động chấm dứt thai kỳ\nNói chung trừ khi thai quá non hoặc thai suy quá nặng nên nghĩ đến chấm dứt thai kỳ khi các số đo sinh học không tăng thêm qua 3 tuần theo dõi.\nNên mổ lấy thai để tránh nguy cơ gây sang chấn cho con. Theo dõi sinh bằng đường âm đạo khi điều kiện thật thuận lợi và  test đả kích âm tính.\n5.2. Suy thai cấp\nTuỳ nguyên nhân cụ thể gây suy thai cấp mà có hướng xử trí thích hợp.\n5.2.1. Nội khoa\nCung cấp oxy cho mẹ: cho thở oxy 5-6l /phút, ngắt quãng, nồng độ riêng phần SaO2 của thai có thể tăng được 4-7%.\nNằm nghiêng trái để hạn chế việc tử cung chèn ép vào các mạch máu lớn ở bụng\nTruyền dịch: nên theo dõi huyết động của mẹ, nếu thấp thì bù dịch để giúp cải thiện nội môi cho thai. Có thể dùng Ringers lactat, Natribicarbonat 4,2%, nếu nhịp tim thai trở lại bình thường có thể theo dõi tiếp. Không nên sử dụng dung dịch Glucôza truyền cho mẹ để hôì sức  thai vì sẽ làm tăng nguy cơ hạ đường máu ở trẻ sơ sinh ngay sau đẻ.\nCho kháng sinh khi có biểu hiện nhiễm trùng, hạ sốt khi sốt trên 38,50C.\n5.2.2. Sản khoa\nTìm kiếm các nguyên nhân gây suy thai để có hướng xử trí thích hợp\n+ Nếu cơn co mạnh, dày thì cho thuốc giảm co (No-spa, Buscopan...). Nếu đang sử dụng ôxytoxin thì ngừng sử dụng hoặc làm giảm tốc độ truyền ôxytoxin. Việc sử dụng ôxytoxin trong chuyển dạ là nguyên nhân số một gây suy thai cấp trong phần lớn các trường hợp.\n+ Sa dây rốn: nếu cuống rốn còn đập thì cho mẹ nằm mông cao, lấy gạc tẩm dung dịch Natri Clorua 0,9% ấm để bọc cuống rốn, chuyển mổ lấy thai cấp cứu.\n+ Nếu không tìm được nguyên nhân, điều trị suy thai không kết quả thì tuỳ điều kiện mà mổ lấy thai hoặc đặt forceps nếu đủ điều kiện (đầu lọt, thai sống, không có bất tương xứng đầu chậu).\n+ Nếu nước ối đặc phân su, nên mổ lấy thai.\n5.2.3. Dự phòng\nTheo dõi chuyển dạ bằng biểu đồ chuyển dạ để phát hiện sớm suy thai và can thiệp lấy thai ra kịp thời\nĐánh giá đúng tình trạng bệnh lý của mẹ và thai\nTheo dõi liên tục tim thai 15-30 phút/lần phù hợp với chuyển dạ\nĐiều chỉnh cơn co cho phù hợp với giai đoạn chuyển dạ\nNếu có điều kiện nên theo dõi tim thai liên tục với Monitoring sản khoa, phát hiện sớm các nhịp tim thai bất thường.\n\nCâu hỏi:\n1. Trình bày triệu chứng lâm sàng  chẩn đoán suy thai cấp, hướng xử trí  ở tuyến cơ sở?\n\n2. Trình bầy các nguyên nhân gây suy thai?\n3. Trình bày cách đánh gía tình trạng sơ sinh ngay sau đẻ?", "priority": "Cao (Trọng tâm BSNT)"}, {"id": "SK-35", "chapter": "Chương 2. Sản bệnh", "folder": "02_San_benh", "title": "Tiền sản giật - Sản giật", "author": "Ths. Đinh Văn Hoành", "word_count": 4103, "line_count": 270, "key_numbers": ["0,1 g", "0,3 g", "0,3g", "0,5g", "0,5kg", "1 giờ", "1 phút", "1,0 g", "10 mg", "10 phút", "100mg", "100ml", "100mmHg", "10g", "10mg", "10ml", "110 mmHg", "110mmHg", "12 giờ", "12,5mg", "140mmHg", "15 phút", "15mmHg", "160 mmHg", "1g", "1ml", "2 giờ", "2 phút", "20 phút", "20 tuần", "20mg", "20ml", "24 giờ", "24g", "24giờ", "250mg", "2g", "3 g", "30mg", "30ml", "30mmHg", "3g", "4 giờ", "40mg", "48 giờ", "4g", "5 giờ", "5 phút", "500mg", "500ml", "5g", "5mg", "6 tuần", "6giờ", "7 phút", "700ml", "80mg", "90mmHg"], "key_drugs": ["Labetalol", "Magnesium Sulfate", "Magnesium sulfate", "Methyldopa", "Nifedipine"], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["TIỀN SẢN GIẬT - SẢN GIẬT", "Ths. Đinh Văn Hoành"], "bullets": []}, {"heading": "Mục tiêu học tập", "paragraphs": ["Phân loại tăng huyết áp trong thai nghén.", "Mô tả các triệu chứng lâm sàng và cận lâm sàng của tiền sản giật- sản giật.", "Lựa chọn cách điều trị theo từng thể lâm sàng.", "Kể ra được các biện phá dự phòng tăng huyết áp trong thai nghén."], "bullets": []}, {"heading": "1. ĐẠI  CƯƠNG", "paragraphs": ["Tăng huyết áp là một triệu chứng có thể có sẵn trước khi mang thai, hoặc xuất hiện lúc mang thai, hay nặng lên do thai nghén. Như vậy, tăng huyết áp khi có thai có thể có nguyên nhân độc lập với tình trạng mang thai hoặc nguyên nhân do thai và là dấu hiệu báo động, biểu hiện của một thai kỳ nguy cơ cao, có thể gây tử vong cho mẹ và thai nhi.", "Trong sản khoa, tăng huyết áp đi kèm với protein niệu và phù tạo nên một bệnh cảnh đặc biệt mà trước đây người ta đây người ta thường gọi là nhiễm độc thai nghén, nay được gọi là tiền sản giật - sản giật.", "Phân loại các rối loạn tăng huyết áp do thai :", "2.TIỀN SẢN GIẬT"], "bullets": ["- Tiền sản giật, Sản giật", "- Tăng huyết áp mạn tính do bất kể nguyên nhân gì", "- Tăng huyết áp mạn tính trước khi có thai nặng lên trong khi có thai", "- Tăng huyết áp thai nghén."]}, {"heading": "2.1. Định nghĩa", "paragraphs": ["Tiền sản giật là bệnh lý do thai nghén hoặc ảnh hưởng của một thai nghén rất gần gây nên với sự xuất hiện tăng huyết áp với protein niệu, có hoặc không kèm theo phù. Tiền sản giật - sản giật thường xảy ra sau tuần lễ thứ 20 của thai kỳ và chấm dứt sau 6 tuần sau đẻ. Tuy nhiên, với sự hiện diện của bệnh lá nuôi, tiền sản giật nặng có thể xuất hiện trước thời điểm đó.", "Trước đây người ta thường gọi tiền sản giật là nhiễm độc thai nghén hay hội chứng protein niệu, nhưng ngày nay người ta nhận thấy chính huyết áp tăng là triệu chứng thường gặp nhất và gây nên các biến chứng trầm trọng cho mẹ và thai.", "Hình 1. Tăng huyết áp, phù và protein niệu trong tiền sản giật"], "bullets": []}, {"heading": "2.2.Tỷ lệ", "paragraphs": ["Tiền sản giật xảy ra khoảng 5-10 % và sản giật chiếm khoảng 0,2- 0,5% trong tổng số thai nghén."], "bullets": []}, {"heading": "2.3.1. Bệnh nguyên", "paragraphs": ["Cho đến nay người ta vẫn chưa hiểu rõ nguyên nhân sinh bệnh của tiền sản giật. Một số yếu tố sau đây có thể góp phần trong sự xuất hiện tiền sản giật - sản giật.", "Điều này làm giảm tỷ lệ prostacyclin/thromboxan A2, gây co mạch và dẫn đến tăng huyết áp."], "bullets": ["- Hiện tượng miễn dịch", "- Di truyền.", "- Các yếu tố dinh dưỡng.", "- Phản ứng, stress.", "- Phản xạ do căng tử cung trong đa thai, thai to.", "- Thiếu máu cục bộ tử cung - rau.", "- Mất cân bằng giữa Prostacyclin và Thromboxan:", "+ Tăng sản xuất thromboxan A2 (chất gây co mạch và dễ hình thành cục máu đông.)", "+ Giảm sản xuất prostacyclin (chất gây giãn mạch)."]}, {"heading": "2.3.2. Các yếu tố nguy cơ", "paragraphs": [], "bullets": ["- Con so", "- Thai phụ lớn tuổi (trên 35 tuổi).", "- Đa thai, đa ối.", "- Chửa trứng, biểu hiện tiền sản giật  thường xảy ra sớm.", "- Thai nghén kèm đái tháo đường, bệnh thận mạn tính, tăng huyết áp mạn tính.", "- Tiền sử có tiền sản giật - sản giật."]}, {"heading": "2.4.1. Tăng huyết áp", "paragraphs": ["Tăng huyết áp là triệu chứng cơ bản để chẩn đoán xác định tiền sản giật. Tăng huyết áp được xác định khi tuổi thai từ 20 tuần trở lên với các giá trị sau :", "Huyết áp tối đa ≥ 140mmHg hoặc", "Huyết áp tối thiểu ≥ 90mmHg.", "Những trường hợp có huyết áp tối đa tăng hơn 30mmHg hoặc huyết áp tối thiểu tăng hơn 15mmHg so với trị số huyết áp khi chưa có thai cần được quan tâm đặc biệt, vì có thể xuất hiện tiền sản giật - sản giật.", "Lưu ý: Phải đo huyết áp 2 lần cách nhau ít nhất sau 4 giờ, sau khi nghỉ."], "bullets": []}, {"heading": "2.4.2.Phù:", "paragraphs": ["Đặc điểm của phù:", "Có thể phù nhiều, phù toàn thân, các chi to lên, ngón tay tròn trĩnh, mặt nặng, mí mắt húp lại, âm hộ sưng to. Bụng căng lên, nổi hằn dây thắt lưng hay sau khi nghe tim thai còn hằn dấu vết của ống nghe. Có khi phù cả phủ tạng, phù phúc mạc nên có nước trong ổ bụng, màng phổi, não. Võng mạc có thể bị phù nên bệnh nhân bị nhức đầu, mờ mắt. Trong một số trường hợp, phù có thể nhẹ, kín đáo, chỉ khi ấn lên mắt cá chân mới phát hiện được hoặc buổi sáng hơi nặng mặt."], "bullets": ["+ Phù toàn thân, không giảm khi nghỉ ngơi.", "+ Phù trắng, mềm, có dấu ấn lõm.", "+Tăng cân nhanh, quá 0,5kg/tuần."]}, {"heading": "2.4.3. Protein niệu: Protein niệu thường là dấu hiệu sau cùng của bộ ba triệu chứng. Mức độ protein niệu có thể thay đổi nhiều trong 24 giờ, do đó xét để nghiệm protein niệu chính xác nước tiểu  phải được lấy mẫu trong 24 giờ.", "paragraphs": ["Protein niệu dương tính khi lượng protein lớn hơn 0,3g/l/24 giờ hoặc trên 0,5g/l/ mẫu nước tiểu ngẫu nhiên.", "Mức độ protein niệu trong 24 giờ", "Vết\t# 0,1 g/l"], "bullets": ["+\t# 0,3 g/l", "++\t# 1,0 g/l", "+++\t# 3 g/l"]}, {"heading": "2.4.4. Các xét nghiệm : Bệnh nhân tiền sản giật cần được làm các xét nghiệm sau", "paragraphs": ["Công thức máu, hematocrit, hemoglobin, tiểu cầu", "Chức năng thận: Ure, creatinin, axit uric, protein niệu. Ngoài ra tuỳ thuộc vào mức độ tổn thương thận trong nước tiểu có thể có hồng cầu, bạch cầu, trụ niệu", "Chức năng gan: SGOT, SGPT."], "bullets": ["-  Điện giải đồ và dự trữ kiềm", "- Chức năng đông chảy máu toàn bộ.", "-  CRP, Protid máu.", "- Soi đáy mắt", "- Đánh giá tình trạng thai qua siêu âm và monitoring."]}, {"heading": "3.5. Chẩn đoán tiền sản giật", "paragraphs": ["Dựa vào ba triệu chứng chính là tăng huyết áp, phù và protein niệu."], "bullets": []}, {"heading": "3.5.1.  Tiền sản giật nhẹ", "paragraphs": [], "bullets": ["- Huyết áp tâm thu 140 - <160 mmHg", "- Huyết áp tâm trương 90 - <110 mmHg", "- Protein niệu từ (+) đến (++)"]}, {"heading": "3.5.2. Tiền sản giật nặng: khi có ít nhất một trong những dấu hiệu sau:", "paragraphs": ["Huyết áp tối đa ≥ 160 mmHg và/hoặc tối thiểu  ≥110mmHg,", "Protein niệu ≥ 5g/24h.(+++)", "Rối loạn thị giác và tri giác.", "Đau đầu nhưng không đáp ứng với các thuốc giảm đau thông thường.", "Đau vùng thượng vị hoặc phần tư trên của hạ sườn phải.", "Phù phổi hoặc xanh tím.", "Thiểu niệu: lượng nước tiểu < 500ml/24 giờ.", "Giảm tiểu cầu: số lượng tiểu cầu <100.000/mm3.", "Tăng men gan.", "Thai chậm phát triển"], "bullets": []}, {"heading": "3.6. Chẩn đoán phân biệt", "paragraphs": [], "bullets": ["- Tăng huyết áp mạn tính: tiền sử đã có tăng huyết áp, hoặc tăng huyết áp xuất hiện trước tuần thứ 20 của thai kỳ.", "- Các bệnh lý về thận: viêm thận cấp, viêm thận mãn, viêm mủ bể thận, hội chứng thận hư.", "- Phù do tim, phù do suy dinh dưỡng."]}, {"heading": "3.7.1.. Biến chứng cho mẹ", "paragraphs": ["Mắt: Phù võng mạc, mù mắt,", "Thận:  Suy thận cấp.", "Gan: Chảy máu dưới bao gan, vỡ gan.", "Tim, phổi: suy tim cấp, phù phổi cấp (gặp trong tiền sản giật nặng hoặc sản giật).", "Huyết học: Rối loạn đông - chảy máu, giảm tiểu cầu, đông máu rải rác trong lòng mạch."], "bullets": ["- Hệ thần kinh trung ương:  phù não, xuất huyết não- màng não."]}, {"heading": "3.7.2. Biến chứng cho thai", "paragraphs": ["Thai chậm phát triển trong tử cung (56%).", "Đẻ non (40%), do tiền sản giật nặng hoặc sản giật phải cho đẻ sớm.", "Tiền sản giật nặng, sản giật có thể tiến triển thành hội chứng HELLP (Hemolysis- Elevated Liver enzyme- Low plateletes: tan huyết, tăng các men gan và giảm tiểu cầu). Hội chứng này có thể đe doạ tính mạng cho mẹ và con."], "bullets": ["-  Tử vong chu sinh (10%): Tỷ lệ tử vong chu sinh tăng tăng nếu đẻ non hoặc biến chứng rau bong non."]}, {"heading": "3.8.1. Dự phòng: Vì nguyên nhân chưa rõ nên dự phòng bệnh lý này không có biện pháp đặc hiệu, cần làm tốt những việc sau:", "paragraphs": ["Đăng ký quản lý thai nghén là khâu cơ bản nhất trong dự phòng tiền sản giật - sản giật.  Đảm bảo chế độ ăn đầy đủ chất dinh dưỡng, bổ sung Canxi. Chế độ ăn ít muối (muối ăn) không ngăn ngừa được tiền sản giật", "Thai phụ cần được giữ ấm.", "Phát hiện sớm, điều trị kịp thời những sản phụ có nguy cơ cao để ngăn ngừa xảy ra sản giật.", "Chăm sóc liên tục trong thời kỳ hậu sản."], "bullets": []}, {"heading": "3.8.2. Điều trị", "paragraphs": ["Nguyên tắc điều trị: Bảo vệ mẹ là chính, có chiếu cố đến con.", "Phải nhập viện và theo dõi tại tuyến tỉnh và được điều trị tích cực. Theo dõi huyết áp 4 lần/ngày, cân nặng và protein niệu hàng ngày, xét nghiệm đếm tiểu cầu, Hct, đánh giá các chức năng gan, thận, rối loạn đông chảy máu, hội chứng HELLP, siêu âm và theo dõi tim thai liên tục. Chế độ điều trị cụ thể như sau:", "Nghỉ ngơi và nằm nghiêng trái", "Thuốc an thần: Diazepam tiêm hoặc uống.", "Sử dụng Magnesium Sulfate", "Liều tấn công", "Dung dịch Magnesium Sulfate 4 gam, pha loãng trong 20ml dung dịch Glucoza 5% tiêm tĩnh mạch chậm trên 5 phút.", "Ngay sau đó dùng 10g Magnesium sulfate 50% (10ml) tiêm bắp sâu, mỗi bên 5g hoà với 1ml Lidocain 2%.", "Liều duy trì", "Truyền tĩnh mạch Magnesium sulfate 15%, liều lượng 1g trong một giờ hoặc tiêm bắp 4g mỗi 5 giờ.", "Trong khi dùng cần bảo đảm", "Có phản xạ xương bánh chè.", "Tần số thở ít nhất là 16 lần/ phút.", "Lượng nước tiểu tối thiểu trên 30ml/ giờ  hoặc 100ml/4 giờ", "Có sẵn thuốc đối kháng là Gluconat calci hoặc Clorua calci.", "Khi có ngộ độc, bệnh nhân có thể bị ngừng thở phải thông khí hỗ trợ bằng mặt nạ hoặc đặt nội khí quản cho đến khi hô hấp trở lại, phải cho ngay Calcium Gluconate 1g (10ml dung dịch 10%) hoặc calci chlorua tiêm tĩnh mạch chậm để trung hoà tác dụng của Magnesium Sulfate.", "Nồng độ tác dụng và ngộ độc của Magnesium Sulfat :", "Tác dụng và ngộ độc", "Nồng độ (mg/dl)", "Chống co giật", "4,8-8,4", "Giảm phản xạ xương bánh chè", "10-12", "Ngừng hô hấp", "15-17", "Ngừng tim", "30- 35", "* Lưu ý:- Không được dùng quá 24g/24giờ", "Thuốc hạ huyết áp:  sử dụng thuốc hạ huyết áp khi có huyết áp tăng (160/110mmHg):", "Hydralazin hoặc Dihydralazin là thuốc được lựa chọn đầu tiên.", "Thuốc có tác dụng làm giãn các tiểu động mạch, tăng lưu lượng máu đến tim và thận ngoài ra thuốc còn làm tăng lượng máu đến bánh rau.", "Thời gian bán huỷ của thuốc: 1 giờ, thuốc được thải trừ qua gan.", "Liều dùng: Dihydralazin 5 - 10 mg tiêm tĩnh mạch chậm, có thể lập lại liều 5mg, sau 10-20 phút nếu cần. Tổng liều là 100mg/24giờ, có thể truyền tĩnh mạch chậm 10mg trong 100ml Dextrose 5%.", "Một số thuốc hạ huyết áp có thể dùng thay thế như:", "Labetalol: thuốc hạ huyết áp chẹn α và (, liều 10-20mg tiêm tĩnh mạch chậm.", "Nifedipin (thuốc ức chế kênh calci): Biệt dược là Adalat 10mg, ngậm dưới lưỡi hoặc giọt 3 giọt dưới lưỡi. Thuốc có tác dụng tốt trong trường hợp tăng huyết áp đột ngột.", "Alpha methyl dopa (Dopegyt 250mg; Methyldopa 250mg): Tác dụng: Methyldopa ở nơron giao cảm đã chuyển thành alfa-methylnor-adrenalin, chất này kích thích alfa2-adrenergic ở trung ương gây tác dụng làm hạ huyết áp.Thuốc còn làm tăng trương lực phế vị, tăng hoạt tính renin huyết tương.", "Liều lượng - cách dùng:", "Người lớn 250mg, 2-3 lần/ngày, duy trì: 500mg-2g, chia làm 2 liều, tối đa: 3g/ngày.", "Thuốc lợi tiểu: chỉ sử dụng khi có đe doạ phù phổi cấp và thiểu niệu.", "Nếu tiền sản giật nặng không đáp ứng với với điều trị hoặc xảy ra sản giật thì chấm dứt thai kỳ với mọi tuổi thai. Trước khi chủ động chấm dứt thai kỳ, cần ổn định tình trạng bệnh nhân trong vòng 24- 48 giờ giống như trong sản giật.", "Nên sinh thủ thuật nếu đủ điều kiện, hoặc mổ lấy thai khi có chỉ định sản khoa hoặc cần nhanh chóng chấm dứt thai kỳ."], "bullets": ["- Tiền sản giật nhẹ: chủ yếu điều trị ngoại trú", "+ Nghỉ ngơi và nằm nghiêng trái.", "+ Có thể cho uống thuốc an thần Seduxen (Diazepam) 5mg.", "+ Theo dõi hằng tuần, nếu nặng lên phải nhập viện và điều trị tích cực.", "+ Nếu thai đã đủ tháng nên chấm dứt thai kỳ ở tuyến chuyên khoa.", "- Tiền sản giật nặng", "+ Điều trị nội khoa", "- Theo dõi nồng độ ion Magnesium mỗi 4-6giờ /lần, để điều chỉnh liều dùng.", "+ Điều trị sản khoa và ngoại khoa:"]}, {"heading": "4.1. Định nghĩa", "paragraphs": ["Sản giật được xác định là khi xuất hiện những cơn co giật hoặc hôn mê, xảy ra trên một bệnh nhân có hội chứng tiền sản giật nặng. Đây là một biến chứng cấp tính của tiền sản giật nặng nếu không được theo dõi và điều trị đúng mức.", "Sản giật có thể xảy ra ở các thời điểm khác nhau: trước đẻ (50%), trong đẻ (25%) và sau đẻ (25%)."], "bullets": []}, {"heading": "4.2.1. Lâm sàng", "paragraphs": ["Cơn giật điển hình thường  trải qua 4 giai đoạn."], "bullets": ["- Giai đoạn xâm nhiễm: kéo dài từ 30 giây đến 1 phút, với những cơn kích thích ở vùng mặt, miệng, mí mắt nhấp nháy, nét mặt nhăn nhúm, sau đó cơn giật lan xuống hai tay.", "- Giai đoạn giật cứng: xảy ra khoảng 30 giây, biểu hiện bằng những cơn giật cứng lan toả khắp người. Toàn thân co cứng, các cơ thanh quản và hô hấp bị co thắt làm cho bệnh nhân ngạt thở vì thiếu oxy.", "- Giai đoạn giật gián cách: Sau cơn giật, các cơ toàn thân giãn ra trong chốc lát rồi tiếp tục những cơn co giật toàn thân, lưỡi thè ra thụt vào nên rất dễ cắn phải lưỡi, mặt tím do ngưng thở, miệng sùi bọt mép. Giai đoạn giật gián cách kéo dài khoảng 1 phút.", "- Giai đoạn hôn mê: Các cử động co giật nhẹ và thưa dần rồi chấm dứt. Bệnh nhân đi vào tình trạng hôn mê. Bệnh nhân có thể hôn mê nhẹ hoặc hôn mê sâu tùy thuộc mức độ nặng hay nhẹ của bệnh. Nếu nhẹ thì sau 5-7 phút bệnh nhân sẽ tỉnh lại, nếu nặng thì bệnh nhân hôn mê sâu. Hôn mê có thể kéo dài từ vài giờ đến vài ngày. Bệnh nhân mất tri giác, đồng tử dãn rộng, rối loạn cơ vòng nên đại tiểu tiện không tự chủ. Trường hợp nặng bệnh nhân có thể tử vong."]}, {"heading": "4.2.2. Chẩn đoán", "paragraphs": [], "bullets": ["- Chẩn đoán xác định: dựa và triệu chứng lâm sàng của cơn giật điển hình trên một bệnh nhân có hội chứng tiền sản giật nặng.", "-  Chẩn đoán phân biệt", "+ Động kinh: có tiền sử động kinh trước khi có thai.", "+ Cơn Tetanie: có thể có hay không có tiền sử. Các ngón tay duỗi thẳng và co dúm lại như bàn tay người đỡ đẻ.", "+ Cơn Hysteria: sự biểu hiện các cơn giật không giống nhau, tuy không tỉnh nhưng người xung quanh nói vẫn biết; Mất tri giác nhưng không mất phản xạ.", "+ Các tai biến mạch máu não: xuất huyết não, thuyên tắc mạch não do huyết khối. Tổn thương não (u não, áp- xe não).", "+ Các bệnh nhiễm trùng: viêm màng não, viêm não.", "+ Các bệnh chuyển hoá: hạ calci máu, hạ glucoza máu, hôn mê do urê máu cao, hôn mê gan, hôn mê do đái tháo đường..."]}, {"heading": "4.3.1. Về phía mẹ", "paragraphs": [], "bullets": ["- Cắn phải lưỡi khi lên cơn giật", "- Ngạt thở, suy hô hấp", "-  Suy tim cấp, phù phổi cấp", "- Xuất huyết não - màng não", "- Chảy máu dưới bao gan, vỡ gan", "- Suy gan cấp, suy thận cấp", "- Mù mắt, thong manh, ngớ ngẩn", "-  Có thể để lại di chứng tăng huyết áp mãn, suy gan, suy thận mãn.", "-  Tử vong"]}, {"heading": "4.3.2. Về phía con", "paragraphs": [], "bullets": ["- Thai kém phát triển trong tử cung.", "- Đẻ non.", "- Thai chết trong tử cung."]}, {"heading": "4.4.1. Chế độ chăm sóc", "paragraphs": [], "bullets": ["-  Giữ bệnh nhân tại nơi yên tĩnh, tránh mọi kích thích, không cho ăn.", "-  Ngáng miệng bằng thanh ngáng có quấn vải để đề phòng cắn phải lưỡi. Đây là một việc làm bắt buộc vì khi bệnh nhân lên cơn giật rất dễ cắn lưỡi.", "- Nằm giường có thanh chắn, cố định bệnh nhân.", "- Hút đờm dãi đề phòng tắc đường hô hấp.", "- Thở oxy qua mặt nạ hoặc ống thông mũi.", "- Theo dõi cơn giật, huyết áp, lượng nước tiểu, mạch, nhiệt độ. Tất cả được ghi vào bảng theo dõi để phục vụ điều trị."]}, {"heading": "4.4.2. Xử trí tại tuyến y tế cơ sở:", "paragraphs": [], "bullets": ["- Nguyên tắc: bệnh nhân phải được sơ cứu trước khi chuyển tuyến, phải có nhân viên y tế hộ tống khi chuyển lên tuyến trên.", "- Cần thực hiện đầy đủ chế độ chăm sóc: Hút đờm dãi, ngáng miệng, tiêm thuốc an thần, lập một đường truyền tĩnh mạch trước và trong khi chuyển tuyến."]}, {"heading": "4.4.3. Điều trị nội khoa", "paragraphs": ["* Thuốc chống co giật và đề phòng cơn giật:", "* Sử dụng Diazepam(Seduxen) trong tiền sản giật nặng và sản giật", "Diazepam 10mg tiêm tĩnh mạch chậm trên 2 phút.", "Nếu cơn giật tái diễn: lập lại liều tấn công.", "Không dùng quá 100mg Diazepam trong 24 giờ. Hô hấp hỗ trợ khi có suy hô hấp (mặt nạ oxy, bóp bóng ambu, đặt nội khí quản)", "* Thuốc hạ huyết áp:(xem  phần điều trị  tiền sản giật nặng).", "Nếu như huyết áp tâm trương trên 110mmHg sẽ có nguy cơ xuất huyết não, để đề phòng tai biến này phải điều chỉnh để huyết áp tâm trương ở giữa khoảng 90-100mmHg", "Hydralazin hoặc Dihydralazine là thuốc được lựa chọn.", "Liều dùng: Dihydralazine 5-10mg tiêm tĩnh mạch chậm, nếu cần có thể lập lại liều 5mg cứ 10-20 phút cho đến khi huyết áp giảm, hoặc liều Dihydralazine 12,5mg tiêm bắp cách 2 giờ. Tổng liều Dihydralazine là 100mg trong 24giờ.", "Nếu Dihydralazine không có sẵn, có thể dùng:", "Labetalol 10mg tiêm tĩnh mạch. Nếu đáp ứng chưa tốt (huyết áp tâm trương trên 110mmHg) sau 10 phút cho thêm 20mg tiêm tĩnh mạch và có thể tăng liều này lên tới 40- 80mg để đạt kết quả điều trị.", "Alpha methyl dopa (Dopegyt 250mg; Methyldopa 250mg): Tác dụng: Methydopa ở nơron giao cảm đã chuyển thành alfa-methylnor-adrenalin, chất này kích thích alfa2-adrenergic ở trung ương gây tác dụng làm hạ huyết áp.", "Thuốc còn làm tăng trương lực phế vị, tăng hoạt tính renin huyết tương.", "\tLiều lượng - cách dùng:", "Người lớn 250mg, 2-3 lần/ngày, duy trì: 500mg-2g, chia làm 2 liều, tối đa: 3g/ngày.", "Nifedipine  viên nang 10mg ngậm dưới lưỡi.", "Lưu ý: Nifedipine có khả năng tương tác với Magnesium sulfate dẫn đến hạ huyết áp mạnh.", "Thuốc lợi tiểu chỉ dùng khi có thiểu niệu, đe doạ phù phổi, phù não. Lượng dịch cần bù phụ thuộc vào sự bài tiết nước tiểu. Trong trường hợp bệnh nặng cần đo áp lực tĩnh mạch trung tâm (CVP). Lượng dịch truyền vào bằng lượng nước tiểu trong ngày cộng với 700ml dịch."], "bullets": ["-  Để chống co giật có hiệu quả yếu tố then chốt trong điều trị là sử dụng thuốc chống co giật đủ liều lượng. Co giật ở sản phụ đang  điều trị hầu hết do sử dụng không đủ liều lượng thuốc chống co giật. Magnesium sulfate là thuốc được chọn lựa để phòng và chống co giật.", "- Lưu ý thuốc này phải dùng tại bệnh viện, phải theo dõi sát, đề phòng ngộ độc.", "- Nếu không có Magnesium sulfate, có thể thay bằng Diazepam; nhưng có nhiều nguy cơ  ức chế hô hấp cho thai hơn vì Diazepam đi qua hàng rào rau thai một cách tự do.", "- Liều lượng, cách dùng Magnesium Sulfate giống  như điều trị tiền sản giật nặng.", "- Nếu cơn giật tái diễn sau 15 phút, dùng thêm 2g Magnesium sulfate 20%  tiêm chậm vào tĩnh mạch (thận trọng khi tiêm Magnesium sulfate vào tĩnh mạch vì thuốc có thể gây ngưng thở đột ngột do ức chế hô hấp).", "- Dung dịch Magnesium sulfate 50% 10ml (5g) + 1ml Lidocain 2% tiêm bắp mỗi 4 giờ, luân phiên mỗi mông.", "-  Liệu trình Magnesium sulfate tiếp tục được sử dụng đến 24 giờ sau sinh hoặc cơn giật cuối cùng.", "-Liều tấn công :", "-Liều duy trì:", "+ Diazepam 40mg, pha trong 500ml dung dịch chuyền tĩnh mạch (Glucoza 5% hoặc Ringers lactat) đủ để giữ cho bệnh nhân ngủ nhưng có thể đánh thức.", "+ Bệnh nhân có thể bị ức chế hô hấp  khi dùng quá 30mg/ 1 giờ.", "- Dùng thuốc đường trực tràng:", "+ Dùng thuốc đường trực tràng nếu đường tĩnh mạch không thực hiện được. Liều tấn công 20mg hút vào một bơm tiêm 10ml, tháo bỏ kim, bôi trơn đầu ống và đưa bơm tiêm vào trực tràng đến nửa ống. Bơm thuốc và giữ bơm tiêm tại chỗ, khép mông lại trong 10 phút để thuốc không trào ra. Có thể sử dụng Catheter để đưa thuốc vào hậu môn.", "+ Nếu sau 10 phút không cắt được cơn giật, có thể sử dụng thêm 10mg mỗi giờ hoặc nhiều hơn tuỳ theo trọng lượng và đáp ứng lâm sàng của bệnh nhân.", "- Lợi tiểu và vấn đề truyền dịch:", "-  Sử dụng kháng sinh để dự phòng bội nhiễm."]}, {"heading": "4.4.4. Điều trị sản khoa và ngoại khoa", "paragraphs": ["Nếu thai nhi còn sống sau cơn giật thì cuộc đẻ cần phải được tiến hành ngay khi bệnh nhân ổn định.", "Khởi phát chuyển dạ, nếu tiến triển thuận lợi thì bấm ối. Không nên để sản phụ phải dùng sức rặn, cần hỗ trợ thủ thuật khi đẻ (forceps). Có thể mổ lấy thai khi có chỉ định.", "*Lưu ý:"], "bullets": ["- Không được dùng Ergometrin sau đẻ cho bệnh nhân tiền sản giật- sản giật vì tăng nguy cơ co giật và tai biến mạch máu não.", "- Trong trường hợp tiền sản giật nặng cần chấm dứt thai kỳ trong vòng 24 giờ kể từ  khi bắt đầu có triệu chứng. Nếu sản giật cần khởi phát chuyển dạ trong vòng 12 giờ từ khi bắt đầu có cơn giật."]}, {"heading": "4.4.5.Theo dõi và  điều trị trong thời gian hậu sản", "paragraphs": [], "bullets": ["-  Tiếp tục theo dõi, điều trị chống co giật trong 24 giờ sau đẻ hoặc cơn giật cuối cùng.", "-  Tiếp tục điều trị tăng huyết áp nếu có.", "-  Tiếp tục theo dõi lượng nước tiểu.", "-  Tư vấn các biện pháp tránh thai."]}], "raw_text": "TIỀN SẢN GIẬT - SẢN GIẬT\nThs. Đinh Văn Hoành\nMục tiêu học tập\n\nPhân loại tăng huyết áp trong thai nghén.\nMô tả các triệu chứng lâm sàng và cận lâm sàng của tiền sản giật- sản giật.\nLựa chọn cách điều trị theo từng thể lâm sàng.\nKể ra được các biện phá dự phòng tăng huyết áp trong thai nghén.\n\n1. ĐẠI  CƯƠNG\nTăng huyết áp là một triệu chứng có thể có sẵn trước khi mang thai, hoặc xuất hiện lúc mang thai, hay nặng lên do thai nghén. Như vậy, tăng huyết áp khi có thai có thể có nguyên nhân độc lập với tình trạng mang thai hoặc nguyên nhân do thai và là dấu hiệu báo động, biểu hiện của một thai kỳ nguy cơ cao, có thể gây tử vong cho mẹ và thai nhi.\nTrong sản khoa, tăng huyết áp đi kèm với protein niệu và phù tạo nên một bệnh cảnh đặc biệt mà trước đây người ta đây người ta thường gọi là nhiễm độc thai nghén, nay được gọi là tiền sản giật - sản giật.\nPhân loại các rối loạn tăng huyết áp do thai :\n- Tiền sản giật, Sản giật\n- Tăng huyết áp mạn tính do bất kể nguyên nhân gì\n- Tăng huyết áp mạn tính trước khi có thai nặng lên trong khi có thai\n- Tăng huyết áp thai nghén.\n2.TIỀN SẢN GIẬT\n2.1. Định nghĩa\nTiền sản giật là bệnh lý do thai nghén hoặc ảnh hưởng của một thai nghén rất gần gây nên với sự xuất hiện tăng huyết áp với protein niệu, có hoặc không kèm theo phù. Tiền sản giật - sản giật thường xảy ra sau tuần lễ thứ 20 của thai kỳ và chấm dứt sau 6 tuần sau đẻ. Tuy nhiên, với sự hiện diện của bệnh lá nuôi, tiền sản giật nặng có thể xuất hiện trước thời điểm đó.\nTrước đây người ta thường gọi tiền sản giật là nhiễm độc thai nghén hay hội chứng protein niệu, nhưng ngày nay người ta nhận thấy chính huyết áp tăng là triệu chứng thường gặp nhất và gây nên các biến chứng trầm trọng cho mẹ và thai.\n\nHình 1. Tăng huyết áp, phù và protein niệu trong tiền sản giật\n2.2.Tỷ lệ\nTiền sản giật xảy ra khoảng 5-10 % và sản giật chiếm khoảng 0,2- 0,5% trong tổng số thai nghén.\n2.3. Bệnh nguyên và các yếu tố ảnh hưởng\n2.3.1. Bệnh nguyên\nCho đến nay người ta vẫn chưa hiểu rõ nguyên nhân sinh bệnh của tiền sản giật. Một số yếu tố sau đây có thể góp phần trong sự xuất hiện tiền sản giật - sản giật.\n- Hiện tượng miễn dịch\n- Di truyền.\n- Các yếu tố dinh dưỡng.\n- Phản ứng, stress.\n- Phản xạ do căng tử cung trong đa thai, thai to.\n- Thiếu máu cục bộ tử cung - rau.\n- Mất cân bằng giữa Prostacyclin và Thromboxan:\n+ Tăng sản xuất thromboxan A2 (chất gây co mạch và dễ hình thành cục máu đông.)\n+ Giảm sản xuất prostacyclin (chất gây giãn mạch).\nĐiều này làm giảm tỷ lệ prostacyclin/thromboxan A2, gây co mạch và dẫn đến tăng huyết áp.\n2.3.2. Các yếu tố nguy cơ\n- Con so\n- Thai phụ lớn tuổi (trên 35 tuổi).\n- Đa thai, đa ối.\n- Chửa trứng, biểu hiện tiền sản giật  thường xảy ra sớm.\n- Thai nghén kèm đái tháo đường, bệnh thận mạn tính, tăng huyết áp mạn tính.\n- Tiền sử có tiền sản giật - sản giật.\n2.4. Triệu chứng\n2.4.1. Tăng huyết áp\nTăng huyết áp là triệu chứng cơ bản để chẩn đoán xác định tiền sản giật. Tăng huyết áp được xác định khi tuổi thai từ 20 tuần trở lên với các giá trị sau :\nHuyết áp tối đa ≥ 140mmHg hoặc\nHuyết áp tối thiểu ≥ 90mmHg.\nNhững trường hợp có huyết áp tối đa tăng hơn 30mmHg hoặc huyết áp tối thiểu tăng hơn 15mmHg so với trị số huyết áp khi chưa có thai cần được quan tâm đặc biệt, vì có thể xuất hiện tiền sản giật - sản giật.\nLưu ý: Phải đo huyết áp 2 lần cách nhau ít nhất sau 4 giờ, sau khi nghỉ.\n2.4.2.Phù:\nĐặc điểm của phù:\n+ Phù toàn thân, không giảm khi nghỉ ngơi.\n+ Phù trắng, mềm, có dấu ấn lõm.\n+Tăng cân nhanh, quá 0,5kg/tuần.\nCó thể phù nhiều, phù toàn thân, các chi to lên, ngón tay tròn trĩnh, mặt nặng, mí mắt húp lại, âm hộ sưng to. Bụng căng lên, nổi hằn dây thắt lưng hay sau khi nghe tim thai còn hằn dấu vết của ống nghe. Có khi phù cả phủ tạng, phù phúc mạc nên có nước trong ổ bụng, màng phổi, não. Võng mạc có thể bị phù nên bệnh nhân bị nhức đầu, mờ mắt. Trong một số trường hợp, phù có thể nhẹ, kín đáo, chỉ khi ấn lên mắt cá chân mới phát hiện được hoặc buổi sáng hơi nặng mặt.\n2.4.3. Protein niệu: Protein niệu thường là dấu hiệu sau cùng của bộ ba triệu chứng. Mức độ protein niệu có thể thay đổi nhiều trong 24 giờ, do đó xét để nghiệm protein niệu chính xác nước tiểu  phải được lấy mẫu trong 24 giờ.\nProtein niệu dương tính khi lượng protein lớn hơn 0,3g/l/24 giờ hoặc trên 0,5g/l/ mẫu nước tiểu ngẫu nhiên.\nMức độ protein niệu trong 24 giờ\nVết\t# 0,1 g/l\n+\t# 0,3 g/l\n++\t# 1,0 g/l\n+++\t# 3 g/l\n2.4.4. Các xét nghiệm : Bệnh nhân tiền sản giật cần được làm các xét nghiệm sau\nCông thức máu, hematocrit, hemoglobin, tiểu cầu\nChức năng thận: Ure, creatinin, axit uric, protein niệu. Ngoài ra tuỳ thuộc vào mức độ tổn thương thận trong nước tiểu có thể có hồng cầu, bạch cầu, trụ niệu\nChức năng gan: SGOT, SGPT.\n-  Điện giải đồ và dự trữ kiềm\n- Chức năng đông chảy máu toàn bộ.\n-  CRP, Protid máu.\n- Soi đáy mắt\n- Đánh giá tình trạng thai qua siêu âm và monitoring.\n3.5. Chẩn đoán tiền sản giật\nDựa vào ba triệu chứng chính là tăng huyết áp, phù và protein niệu.\n3.5.1.  Tiền sản giật nhẹ\n- Huyết áp tâm thu 140 - <160 mmHg\n- Huyết áp tâm trương 90 - <110 mmHg\n- Protein niệu từ (+) đến (++)\n3.5.2. Tiền sản giật nặng: khi có ít nhất một trong những dấu hiệu sau:\nHuyết áp tối đa ≥ 160 mmHg và/hoặc tối thiểu  ≥110mmHg,\nProtein niệu ≥ 5g/24h.(+++)\nRối loạn thị giác và tri giác.\nĐau đầu nhưng không đáp ứng với các thuốc giảm đau thông thường.\nĐau vùng thượng vị hoặc phần tư trên của hạ sườn phải.\nPhù phổi hoặc xanh tím.\nThiểu niệu: lượng nước tiểu < 500ml/24 giờ.\nGiảm tiểu cầu: số lượng tiểu cầu <100.000/mm3.\nTăng men gan.\nThai chậm phát triển\n3.6. Chẩn đoán phân biệt\n- Tăng huyết áp mạn tính: tiền sử đã có tăng huyết áp, hoặc tăng huyết áp xuất hiện trước tuần thứ 20 của thai kỳ.\n- Các bệnh lý về thận: viêm thận cấp, viêm thận mãn, viêm mủ bể thận, hội chứng thận hư.\n- Phù do tim, phù do suy dinh dưỡng.\n3.7. Biến chứng của tiền sản giật\n3.7.1.. Biến chứng cho mẹ\n- Hệ thần kinh trung ương:  phù não, xuất huyết não- màng não.\nMắt: Phù võng mạc, mù mắt,\nThận:  Suy thận cấp.\nGan: Chảy máu dưới bao gan, vỡ gan.\nTim, phổi: suy tim cấp, phù phổi cấp (gặp trong tiền sản giật nặng hoặc sản giật).\nHuyết học: Rối loạn đông - chảy máu, giảm tiểu cầu, đông máu rải rác trong lòng mạch.\n\n3.7.2. Biến chứng cho thai\nThai chậm phát triển trong tử cung (56%).\nĐẻ non (40%), do tiền sản giật nặng hoặc sản giật phải cho đẻ sớm.\n-  Tử vong chu sinh (10%): Tỷ lệ tử vong chu sinh tăng tăng nếu đẻ non hoặc biến chứng rau bong non.\nTiền sản giật nặng, sản giật có thể tiến triển thành hội chứng HELLP (Hemolysis- Elevated Liver enzyme- Low plateletes: tan huyết, tăng các men gan và giảm tiểu cầu). Hội chứng này có thể đe doạ tính mạng cho mẹ và con.\n3.8. Xử trí\n3.8.1. Dự phòng: Vì nguyên nhân chưa rõ nên dự phòng bệnh lý này không có biện pháp đặc hiệu, cần làm tốt những việc sau:\nĐăng ký quản lý thai nghén là khâu cơ bản nhất trong dự phòng tiền sản giật - sản giật.  Đảm bảo chế độ ăn đầy đủ chất dinh dưỡng, bổ sung Canxi. Chế độ ăn ít muối (muối ăn) không ngăn ngừa được tiền sản giật\nThai phụ cần được giữ ấm.\nPhát hiện sớm, điều trị kịp thời những sản phụ có nguy cơ cao để ngăn ngừa xảy ra sản giật.\nChăm sóc liên tục trong thời kỳ hậu sản.\n3.8.2. Điều trị\nNguyên tắc điều trị: Bảo vệ mẹ là chính, có chiếu cố đến con.\n- Tiền sản giật nhẹ: chủ yếu điều trị ngoại trú\n+ Nghỉ ngơi và nằm nghiêng trái.\n+ Có thể cho uống thuốc an thần Seduxen (Diazepam) 5mg.\n+ Theo dõi hằng tuần, nếu nặng lên phải nhập viện và điều trị tích cực.\n+ Nếu thai đã đủ tháng nên chấm dứt thai kỳ ở tuyến chuyên khoa.\n- Tiền sản giật nặng\nPhải nhập viện và theo dõi tại tuyến tỉnh và được điều trị tích cực. Theo dõi huyết áp 4 lần/ngày, cân nặng và protein niệu hàng ngày, xét nghiệm đếm tiểu cầu, Hct, đánh giá các chức năng gan, thận, rối loạn đông chảy máu, hội chứng HELLP, siêu âm và theo dõi tim thai liên tục. Chế độ điều trị cụ thể như sau:\n+ Điều trị nội khoa\nNghỉ ngơi và nằm nghiêng trái\nThuốc an thần: Diazepam tiêm hoặc uống.\nSử dụng Magnesium Sulfate\nLiều tấn công\nDung dịch Magnesium Sulfate 4 gam, pha loãng trong 20ml dung dịch Glucoza 5% tiêm tĩnh mạch chậm trên 5 phút.\nNgay sau đó dùng 10g Magnesium sulfate 50% (10ml) tiêm bắp sâu, mỗi bên 5g hoà với 1ml Lidocain 2%.\nLiều duy trì\nTruyền tĩnh mạch Magnesium sulfate 15%, liều lượng 1g trong một giờ hoặc tiêm bắp 4g mỗi 5 giờ.\nTrong khi dùng cần bảo đảm\nCó phản xạ xương bánh chè.\nTần số thở ít nhất là 16 lần/ phút.\nLượng nước tiểu tối thiểu trên 30ml/ giờ  hoặc 100ml/4 giờ\nCó sẵn thuốc đối kháng là Gluconat calci hoặc Clorua calci.\nKhi có ngộ độc, bệnh nhân có thể bị ngừng thở phải thông khí hỗ trợ bằng mặt nạ hoặc đặt nội khí quản cho đến khi hô hấp trở lại, phải cho ngay Calcium Gluconate 1g (10ml dung dịch 10%) hoặc calci chlorua tiêm tĩnh mạch chậm để trung hoà tác dụng của Magnesium Sulfate.\nNồng độ tác dụng và ngộ độc của Magnesium Sulfat :\nTác dụng và ngộ độc\nNồng độ (mg/dl)\n\nChống co giật\n4,8-8,4\n\nGiảm phản xạ xương bánh chè\n10-12\n\nNgừng hô hấp\n15-17\n\nNgừng tim\n30- 35\n\n* Lưu ý:- Không được dùng quá 24g/24giờ\n- Theo dõi nồng độ ion Magnesium mỗi 4-6giờ /lần, để điều chỉnh liều dùng.\nThuốc hạ huyết áp:  sử dụng thuốc hạ huyết áp khi có huyết áp tăng (160/110mmHg):\nHydralazin hoặc Dihydralazin là thuốc được lựa chọn đầu tiên.\nThuốc có tác dụng làm giãn các tiểu động mạch, tăng lưu lượng máu đến tim và thận ngoài ra thuốc còn làm tăng lượng máu đến bánh rau.\nThời gian bán huỷ của thuốc: 1 giờ, thuốc được thải trừ qua gan.\nLiều dùng: Dihydralazin 5 - 10 mg tiêm tĩnh mạch chậm, có thể lập lại liều 5mg, sau 10-20 phút nếu cần. Tổng liều là 100mg/24giờ, có thể truyền tĩnh mạch chậm 10mg trong 100ml Dextrose 5%.\nMột số thuốc hạ huyết áp có thể dùng thay thế như:\nLabetalol: thuốc hạ huyết áp chẹn α và (, liều 10-20mg tiêm tĩnh mạch chậm.\nNifedipin (thuốc ức chế kênh calci): Biệt dược là Adalat 10mg, ngậm dưới lưỡi hoặc giọt 3 giọt dưới lưỡi. Thuốc có tác dụng tốt trong trường hợp tăng huyết áp đột ngột.\nAlpha methyl dopa (Dopegyt 250mg; Methyldopa 250mg): Tác dụng: Methyldopa ở nơron giao cảm đã chuyển thành alfa-methylnor-adrenalin, chất này kích thích alfa2-adrenergic ở trung ương gây tác dụng làm hạ huyết áp.Thuốc còn làm tăng trương lực phế vị, tăng hoạt tính renin huyết tương.\nLiều lượng - cách dùng:\nNgười lớn 250mg, 2-3 lần/ngày, duy trì: 500mg-2g, chia làm 2 liều, tối đa: 3g/ngày.\nThuốc lợi tiểu: chỉ sử dụng khi có đe doạ phù phổi cấp và thiểu niệu.\n+ Điều trị sản khoa và ngoại khoa:\nNếu tiền sản giật nặng không đáp ứng với với điều trị hoặc xảy ra sản giật thì chấm dứt thai kỳ với mọi tuổi thai. Trước khi chủ động chấm dứt thai kỳ, cần ổn định tình trạng bệnh nhân trong vòng 24- 48 giờ giống như trong sản giật.\nNên sinh thủ thuật nếu đủ điều kiện, hoặc mổ lấy thai khi có chỉ định sản khoa hoặc cần nhanh chóng chấm dứt thai kỳ.\n4. SẢN GIẬT\n4.1. Định nghĩa\nSản giật được xác định là khi xuất hiện những cơn co giật hoặc hôn mê, xảy ra trên một bệnh nhân có hội chứng tiền sản giật nặng. Đây là một biến chứng cấp tính của tiền sản giật nặng nếu không được theo dõi và điều trị đúng mức.\nSản giật có thể xảy ra ở các thời điểm khác nhau: trước đẻ (50%), trong đẻ (25%) và sau đẻ (25%).\n4.2. Triệu chứng và chẩn đoán\n4.2.1. Lâm sàng\nCơn giật điển hình thường  trải qua 4 giai đoạn.\n- Giai đoạn xâm nhiễm: kéo dài từ 30 giây đến 1 phút, với những cơn kích thích ở vùng mặt, miệng, mí mắt nhấp nháy, nét mặt nhăn nhúm, sau đó cơn giật lan xuống hai tay.\n- Giai đoạn giật cứng: xảy ra khoảng 30 giây, biểu hiện bằng những cơn giật cứng lan toả khắp người. Toàn thân co cứng, các cơ thanh quản và hô hấp bị co thắt làm cho bệnh nhân ngạt thở vì thiếu oxy.\n- Giai đoạn giật gián cách: Sau cơn giật, các cơ toàn thân giãn ra trong chốc lát rồi tiếp tục những cơn co giật toàn thân, lưỡi thè ra thụt vào nên rất dễ cắn phải lưỡi, mặt tím do ngưng thở, miệng sùi bọt mép. Giai đoạn giật gián cách kéo dài khoảng 1 phút.\n- Giai đoạn hôn mê: Các cử động co giật nhẹ và thưa dần rồi chấm dứt. Bệnh nhân đi vào tình trạng hôn mê. Bệnh nhân có thể hôn mê nhẹ hoặc hôn mê sâu tùy thuộc mức độ nặng hay nhẹ của bệnh. Nếu nhẹ thì sau 5-7 phút bệnh nhân sẽ tỉnh lại, nếu nặng thì bệnh nhân hôn mê sâu. Hôn mê có thể kéo dài từ vài giờ đến vài ngày. Bệnh nhân mất tri giác, đồng tử dãn rộng, rối loạn cơ vòng nên đại tiểu tiện không tự chủ. Trường hợp nặng bệnh nhân có thể tử vong.\n4.2.2. Chẩn đoán\n- Chẩn đoán xác định: dựa và triệu chứng lâm sàng của cơn giật điển hình trên một bệnh nhân có hội chứng tiền sản giật nặng.\n-  Chẩn đoán phân biệt\n+ Động kinh: có tiền sử động kinh trước khi có thai.\n+ Cơn Tetanie: có thể có hay không có tiền sử. Các ngón tay duỗi thẳng và co dúm lại như bàn tay người đỡ đẻ.\n+ Cơn Hysteria: sự biểu hiện các cơn giật không giống nhau, tuy không tỉnh nhưng người xung quanh nói vẫn biết; Mất tri giác nhưng không mất phản xạ.\n+ Các tai biến mạch máu não: xuất huyết não, thuyên tắc mạch não do huyết khối. Tổn thương não (u não, áp- xe não).\n+ Các bệnh nhiễm trùng: viêm màng não, viêm não.\n+ Các bệnh chuyển hoá: hạ calci máu, hạ glucoza máu, hôn mê do urê máu cao, hôn mê gan, hôn mê do đái tháo đường...\n4.3. Biến chứng\n4.3.1. Về phía mẹ\n- Cắn phải lưỡi khi lên cơn giật\n- Ngạt thở, suy hô hấp\n-  Suy tim cấp, phù phổi cấp\n- Xuất huyết não - màng não\n- Chảy máu dưới bao gan, vỡ gan\n- Suy gan cấp, suy thận cấp\n- Mù mắt, thong manh, ngớ ngẩn\n-  Có thể để lại di chứng tăng huyết áp mãn, suy gan, suy thận mãn.\n-  Tử vong\n4.3.2. Về phía con\n- Thai kém phát triển trong tử cung.\n- Đẻ non.\n- Thai chết trong tử cung.\n4.4. Điều trị sản giật\n4.4.1. Chế độ chăm sóc\n-  Giữ bệnh nhân tại nơi yên tĩnh, tránh mọi kích thích, không cho ăn.\n-  Ngáng miệng bằng thanh ngáng có quấn vải để đề phòng cắn phải lưỡi. Đây là một việc làm bắt buộc vì khi bệnh nhân lên cơn giật rất dễ cắn lưỡi.\n- Nằm giường có thanh chắn, cố định bệnh nhân.\n- Hút đờm dãi đề phòng tắc đường hô hấp.\n- Thở oxy qua mặt nạ hoặc ống thông mũi.\n- Theo dõi cơn giật, huyết áp, lượng nước tiểu, mạch, nhiệt độ. Tất cả được ghi vào bảng theo dõi để phục vụ điều trị.\n4.4.2. Xử trí tại tuyến y tế cơ sở:\n- Nguyên tắc: bệnh nhân phải được sơ cứu trước khi chuyển tuyến, phải có nhân viên y tế hộ tống khi chuyển lên tuyến trên.\n- Cần thực hiện đầy đủ chế độ chăm sóc: Hút đờm dãi, ngáng miệng, tiêm thuốc an thần, lập một đường truyền tĩnh mạch trước và trong khi chuyển tuyến.\n4.4.3. Điều trị nội khoa\n* Thuốc chống co giật và đề phòng cơn giật:\n-  Để chống co giật có hiệu quả yếu tố then chốt trong điều trị là sử dụng thuốc chống co giật đủ liều lượng. Co giật ở sản phụ đang  điều trị hầu hết do sử dụng không đủ liều lượng thuốc chống co giật. Magnesium sulfate là thuốc được chọn lựa để phòng và chống co giật.\n- Lưu ý thuốc này phải dùng tại bệnh viện, phải theo dõi sát, đề phòng ngộ độc.\n- Nếu không có Magnesium sulfate, có thể thay bằng Diazepam; nhưng có nhiều nguy cơ  ức chế hô hấp cho thai hơn vì Diazepam đi qua hàng rào rau thai một cách tự do.\n- Liều lượng, cách dùng Magnesium Sulfate giống  như điều trị tiền sản giật nặng.\n- Nếu cơn giật tái diễn sau 15 phút, dùng thêm 2g Magnesium sulfate 20%  tiêm chậm vào tĩnh mạch (thận trọng khi tiêm Magnesium sulfate vào tĩnh mạch vì thuốc có thể gây ngưng thở đột ngột do ức chế hô hấp).\n- Dung dịch Magnesium sulfate 50% 10ml (5g) + 1ml Lidocain 2% tiêm bắp mỗi 4 giờ, luân phiên mỗi mông.\n-  Liệu trình Magnesium sulfate tiếp tục được sử dụng đến 24 giờ sau sinh hoặc cơn giật cuối cùng.\n* Sử dụng Diazepam(Seduxen) trong tiền sản giật nặng và sản giật\n-Liều tấn công :\nDiazepam 10mg tiêm tĩnh mạch chậm trên 2 phút.\nNếu cơn giật tái diễn: lập lại liều tấn công.\n-Liều duy trì:\n+ Diazepam 40mg, pha trong 500ml dung dịch chuyền tĩnh mạch (Glucoza 5% hoặc Ringers lactat) đủ để giữ cho bệnh nhân ngủ nhưng có thể đánh thức.\n+ Bệnh nhân có thể bị ức chế hô hấp  khi dùng quá 30mg/ 1 giờ.\nKhông dùng quá 100mg Diazepam trong 24 giờ. Hô hấp hỗ trợ khi có suy hô hấp (mặt nạ oxy, bóp bóng ambu, đặt nội khí quản)\n- Dùng thuốc đường trực tràng:\n+ Dùng thuốc đường trực tràng nếu đường tĩnh mạch không thực hiện được. Liều tấn công 20mg hút vào một bơm tiêm 10ml, tháo bỏ kim, bôi trơn đầu ống và đưa bơm tiêm vào trực tràng đến nửa ống. Bơm thuốc và giữ bơm tiêm tại chỗ, khép mông lại trong 10 phút để thuốc không trào ra. Có thể sử dụng Catheter để đưa thuốc vào hậu môn.\n+ Nếu sau 10 phút không cắt được cơn giật, có thể sử dụng thêm 10mg mỗi giờ hoặc nhiều hơn tuỳ theo trọng lượng và đáp ứng lâm sàng của bệnh nhân.\n* Thuốc hạ huyết áp:(xem  phần điều trị  tiền sản giật nặng).\nNếu như huyết áp tâm trương trên 110mmHg sẽ có nguy cơ xuất huyết não, để đề phòng tai biến này phải điều chỉnh để huyết áp tâm trương ở giữa khoảng 90-100mmHg\nHydralazin hoặc Dihydralazine là thuốc được lựa chọn.\nLiều dùng: Dihydralazine 5-10mg tiêm tĩnh mạch chậm, nếu cần có thể lập lại liều 5mg cứ 10-20 phút cho đến khi huyết áp giảm, hoặc liều Dihydralazine 12,5mg tiêm bắp cách 2 giờ. Tổng liều Dihydralazine là 100mg trong 24giờ.\nNếu Dihydralazine không có sẵn, có thể dùng:\nLabetalol 10mg tiêm tĩnh mạch. Nếu đáp ứng chưa tốt (huyết áp tâm trương trên 110mmHg) sau 10 phút cho thêm 20mg tiêm tĩnh mạch và có thể tăng liều này lên tới 40- 80mg để đạt kết quả điều trị.\nAlpha methyl dopa (Dopegyt 250mg; Methyldopa 250mg): Tác dụng: Methydopa ở nơron giao cảm đã chuyển thành alfa-methylnor-adrenalin, chất này kích thích alfa2-adrenergic ở trung ương gây tác dụng làm hạ huyết áp.\nThuốc còn làm tăng trương lực phế vị, tăng hoạt tính renin huyết tương.\n\tLiều lượng - cách dùng:\nNgười lớn 250mg, 2-3 lần/ngày, duy trì: 500mg-2g, chia làm 2 liều, tối đa: 3g/ngày.\nNifedipine  viên nang 10mg ngậm dưới lưỡi.\nLưu ý: Nifedipine có khả năng tương tác với Magnesium sulfate dẫn đến hạ huyết áp mạnh.\n- Lợi tiểu và vấn đề truyền dịch:\nThuốc lợi tiểu chỉ dùng khi có thiểu niệu, đe doạ phù phổi, phù não. Lượng dịch cần bù phụ thuộc vào sự bài tiết nước tiểu. Trong trường hợp bệnh nặng cần đo áp lực tĩnh mạch trung tâm (CVP). Lượng dịch truyền vào bằng lượng nước tiểu trong ngày cộng với 700ml dịch.\n-  Sử dụng kháng sinh để dự phòng bội nhiễm.\n4.4.4. Điều trị sản khoa và ngoại khoa\nNếu thai nhi còn sống sau cơn giật thì cuộc đẻ cần phải được tiến hành ngay khi bệnh nhân ổn định.\nKhởi phát chuyển dạ, nếu tiến triển thuận lợi thì bấm ối. Không nên để sản phụ phải dùng sức rặn, cần hỗ trợ thủ thuật khi đẻ (forceps). Có thể mổ lấy thai khi có chỉ định.\n*Lưu ý:\n- Không được dùng Ergometrin sau đẻ cho bệnh nhân tiền sản giật- sản giật vì tăng nguy cơ co giật và tai biến mạch máu não.\n- Trong trường hợp tiền sản giật nặng cần chấm dứt thai kỳ trong vòng 24 giờ kể từ  khi bắt đầu có triệu chứng. Nếu sản giật cần khởi phát chuyển dạ trong vòng 12 giờ từ khi bắt đầu có cơn giật.\n4.4.5.Theo dõi và  điều trị trong thời gian hậu sản\n-  Tiếp tục theo dõi, điều trị chống co giật trong 24 giờ sau đẻ hoặc cơn giật cuối cùng.\n-  Tiếp tục điều trị tăng huyết áp nếu có.\n-  Tiếp tục theo dõi lượng nước tiểu.\n-  Tư vấn các biện pháp tránh thai.\nCâu hỏi:\n1. Hãy mô tả các triệu chứng lâm sàng chính (3 triệu chứng cổ điển) của của rối loạn tăng huyết áp trong thai nghén?\n2. Hãy phân loại các thể lâm sàng của rối loạn tăng huyết áp theo mức độ nặng nhẹ?\n3. Trình bày các yếu tố tiên lượng bệnh về phía mẹ và về phía con trong rối loạn tăng huyết áp ư thai nghén?\n4. Trình bày các nhóm thuốc hạ huyết áp: Thuốc đại diện, liều dùng, đường dùng được sử dụng trong điều trị bệnh tăng huyết áp trong thai nghén?\n5. Mô tả các giai đoạn của một cơn sản giật?", "priority": "Cao (Trọng tâm BSNT)"}, {"id": "SK-36", "chapter": "Chương 2. Sản bệnh", "folder": "02_San_benh", "title": "Thai quá ngày sinh", "author": "Ths. Nguyễn Văn Hiền", "word_count": 2296, "line_count": 81, "key_numbers": ["1 tuần", "10ml", "28 mm", "287 ngày", "294 ngày", "3 tháng", "38 tuần", "3cm", "40 mm", "41 tuần", "42 tuần", "48 giờ", "60 mm"], "key_drugs": ["Prostaglandin", "oxytocin", "prostaglandin"], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["THAI QUÁ NGÀY SINH"], "bullets": []}, {"heading": "Mục tiêu học tập", "paragraphs": ["Phân tích các đặc điểm liên quan của thai quá ngày sinh.", "Mô tả các triệu chứng lâm sàng, cận lâm sàng của thai quá ngày sinh.", "Lựa chọn cách xử trí thai quá ngày sinh.", "Đại cương", "Thai nghén được gọi là quá ngày sinh khi tuối thai tính theo lý thuyết vượt quá 42 tuần (294 ngày). Thai nghén vượt quá 42 tuần chiếm 3 - 12%.", "Phải cho nằm viện để theo dõi sát các thai nghén từ sau 41 tuần (287 ngày) trở lên để phát hiện sớm suy thai vì bánh rau thoái hóa nên thai dễ bị suy, ngạt, tử vong do thiếu dinh dưỡng.", "Tỷ lệ biến chứng cho mẹ và thai tăng theo tuối thai quá ngày sinh. Tỷ lệ tử vong chu sinh tăng từ tuối thai giữa tuần thứ 41 đến hết tuần 42, tăng gấp đôi vào tuần 43 và tăng gấp 4 - 6 lần vào tuần 44 so với thai đủ tháng. Tỷ lệ tử vong sơ sinh tăng gấp 3 lần so với thai đẻ đủ tháng 38 - 41 tuần.", "Tần suất xuất hiện thai quá ngày sinh là từ 6%-12% các thai kỳ và có sự gia tăng nguy cơ cao cho con. Tần suất thai quá ngày sinh bị ảnh hưởng bởi nhiều yếu tố. Một trong những yếu tố quan trọng làm giảm tỷ lệ thai quá ngày sinh là sự siêu âm sớm để xác định tuối thai. Siêu âm 3 tháng đầu giúp tính ngày dự kiến sinh và khi biết chính xác tuối thai thì người ta không để thai kỳ kéo dài và làm giảm tỷ lệ thai quá ngày sinh.", "Nguy cơ cho thai quá ngày sinh", "Nguy cơ cho mẹ", "Nguyên nhân", "Sinh lý bệnh", "Bánh rau và nước ối đóng một vai trò quan trọng trong quá trình vận chuyển và chuyển hóa sinh học của thai nhi. Trong thai quá ngày sinh, lượng nước ối giảm dần, bánh rau thoái hóa dần dẫn đến giảm dòng máu ở bánh rau và các chất dinh dưỡng đến thai. Do đó thai bị suy trong tử cung và có thể chết trong tử cung hoặc chết trong khi chuyển dạ (do có cơn co tử cung). Vì vậy, thai quá ngày sinh là thai nghén nguy cơ cao, thiếu oxy là nguyên nhân chính của suy thai, khi thai đẻ ra sống thì nó có biểu hiện tổn thương đặc biệt theo kiểu gầy, bị mất nước, da nhăn nheo nhuộm đầy phân su.", "Vai trò của Estrogen trong khởi phát chuyển dạ. Bánh rau là nguồn cung cấp Estrogen chủ yếu. Nồng độ Estrogen tăng trong máu mẹ theo tuối thai. Estrone và 176-Estradiol dẫn xuất từ C19 Androgen trong khi Estriol dẫn xuất từ DHEAS thai nhi. Estrogen không gây cơn co tử cung nhưng khởi phát một chuỗi những thay đối ở cơ tử cung bao gồm sự gia tăng số lượng thụ thể Prostaglandin, thụ thể oxytocin, điều chỉnh tăng những enzyme chịu trách nhiệm trong sự co cơ tử cung (calmodulin, myosin light chain kinase).", "Vai trò của Progesterone trong khởi phát chuyển dạ: Progesterone giúp tử cung ở trạng thải yên nghỉ trong nửa sau của thai kỳ bằng cách ức chế sự sản xuất prostaglandins. Cơ chế tác dụng của Progesterone liên quan đến thụ thể progesterone. Khi cho chất đối kháng thụ thể progesterone là RU-486 lúc thai đủ tháng thì làm tăng cơn co tử cung và khởi phát chuyển dạ. Cortisol và Progesterone có tác dụng đối kháng nhau nên với tình trạng tăng cortisol ở rau thai trước khi chuyển dạ sẽ ức chế hoạt động của progesterone và tạo cơn co tử cung.", "Như vậy, khi có sự suy giảm hoạt động của trục dưới đồi – tuyến yên – tuyến thượng thận thai nhi thì đều có thể làm thiếu yếu tố khởi phát chuyển dạ khi thai đã đủ tháng từ đó dẫn đến thai quá ngày sinh.", "Lâm sàng", "Chẩn đoán thai quá ngày sinh:", "Cận lâm sàng", "Doppler: Phương pháp này cho phép khảo sát tình trạng huyết động học của thai và tuần hoàn rau thai để tiên lượng suy thai.", "Xử trí", "Ở tuyến y tế cơ sở", "Ở cơ sở không có phương tiện chẩn đoán thai quá ngày sinh thì nên xác định thai đủ tháng để có thể đình chỉ thai nghén. Tuy vậy không nên vội vàng kết thúc thai kỳ khi thai còn non tháng hoặc có thái độ chần chừ dẫn đến khi thai sinh ra thì đã suy do thai quá ngày sinh gây nhiều biến chứng cho thai. Cần được theo dõi sát sao bằng các triệu chứng lâm sàng, cận lâm sàng đặc hiệu nếu có, nếu không có điều kiện theo dõi cần gửi tới tuyến có điều kiện chẩn đoán và xử trí.", "Tuyến chuyên khoa", "Nếu trong quá trình gây chuyển dạ thất bại hoặc xuất hiện suy thai thì cũng phải mổ lấy thai.", "Khởi phát chuyển dạ bằng các phương pháp sau đây:"], "bullets": ["+ Suy thai: 5 -> 10% trẻ sơ sinh từ thai quá ngày sinh bị suy thai, tỷ lệ tử vong ở các trẻ này cao. Tuối thai càng quá ngày sinh tỷ lệ tử vong càng cao.", "+ Số lượng nước ối giảm: trong giai đoạn tuần thứ 37 đến tuần 41, thể tích nước ối giảm đi 10%, từ tuần thứ 42 trở đi thể tích nước ối giảm đi rất nhanh khoãng 33,5% trong 1 tuần.", "+ Thoái hoá gai rau: sau tuần 41, các gai rau thoái hóa, bánh rau canxi hóa độ III, xuất hiện hiện tượng trung tâm hoá tuần hoàn bánh rau. Tuần hoàn ở rau giảm đi dẫn đến suy thai, trọng lượng của thai không tăng thêm, dấu hiệu trung tâm hoá tuần hoàn bánh rau tăng ở người sản phụ cao tuối hoặc tiền sản giật. Thiếu oxy là nguyên nhân chính của suy thai do vậy thai sổ ra ngoài mang đặc điểm gầy, da nhăn nheo do bị mất nước, da thấm đầy phân su. Trong buồng tử cung nhanh chóng chuyển thành thiếu oxy khi có cơn co tử cung của chuyển dạ.", "+ Thai chết lưu.", "+ Rối loạn phát tiển thai nhi (chiếm tỷ lệ 10- 20% thai quá ngày sinh).", "+ Hội chứng hít phân su: 25-30 % thai 42 tuần có phân su trong dịch ối.", "+ Nếu thai to: gây đẻ khó, tổn thương xương và gãy xương và để lại chứng thần kinh", "- Tăng khả năng mổ lấy thai và đẻ có can thiệp thủ thuật.", "- Nằm viện dài ngày.", "+ Sử dụng progesteron kéo dài.", "+ Nguyên nhân thường gặp nhất của thai quá ngày sinh là do sự tính toán không chính xác tuối thai vì:", "• Kinh không đều.", "• Rối loạn phóng noãn.", "• Không nhớ ngày kinh cuối cùng.", "+ Suy thượng thận thai nhi.", "+ Có một số thai quá ngày sinh là thai vô sọ. Người ta biết rằng khởi động chuyển dạ có một phần nguồn gốc do hoạt động của vùng dưới đồi của thai. Thai vô sọ không có tuyến yên làm rối loạn sản xuất và chuyển hoá estrogen dẫn tới chuyển dạ muộn.", "+ Suy thượng thận thai nhi.", "+ Thai vô sọ (không kèm đa ối)", "+ Thiếu Placental sulfatase ảnh hưởng đến sự chuyển hóa Estrogen ở rau thai, là một bệnh hiếm di truyền theo gen lặn liên kết với nhiễm sắc thể X.", "+ Giảm 16a hydroxy dehydroepiandrosterone beta sulfate (tiền chất của Estriol).", "+ Dựa vào ngày bắt đầu có kinh của kỳ kinh cuối cùng: tuối thai lớn hơn 41 tuần, triệu chứng này không có giá trị chính xác vì còn phụ thuộc vào vòng kinh dài hay ngắn (phóng noãn sớm hay muộn).", "+ Dựa vào thời gian xuất hiện các cử động của thai nhi.", "+ Giảm số đo chiều cao tử cung qua 2 lần thăm khám kế tiếp nhau (không giảm chiều cao tử cung không cho phép loại trừ).", "+ Giảm cử động của thai nhi xảy ra đột ngột khi đang có cảm giác thai đạp nhiều.", "+ Chụp XQ: tìm điểm cốt hoá đầu dưới xương đùi (dấu hiệu Beclard), đầu trên xương chày (dấu hiệu Tod). Nếu thấy chỉ cho phép ta nói rằng thai đủ 38 tuần, điểm cốt hoá đầu trên xương cánh tay xuất hiện ở tuần 41. XQ chưa nói được thai quá ngày sinh, chỉ cho phép chẩn đoán là đủ tháng. Ngày nay ít dùng phương pháp này vì ảnh hưởng của tia X quang lên thai nhi chưa thực sự được hiểu biết rõ ràng.", "+ Siêu âm sớm (đặc biệt trong 3 tháng đầu) giúp chẩn đoán chính xác tuối thai.", "+ Siêu âm muộn ít chính xác hơn nhưng nếu thấy lượng nước ối ít và bánh rau vôi hóa nhiều cũng gợi ý chẩn đoán. Nếu chỉ số ối (CSO) < 40 mm, nguy cơ cao cho thai và có chỉ định đình chỉ thai nghén. Nếu 40 mm < CSO < 60 mm thì theo dõi. Nếu CSO > 60 mm là bình thường. Ngoài ra siêu âm còn giúp phát hiện thai dị dạng vô sọ, phù thai…", "+ Soi ối: soi ối hàng ngày thấy đầu ối dẹt dần đi, ngôi thai áp sát màng ối, nước ối có màu xanh nhạt. Ngày nay phương pháp này ít được sử dụng.", "+ Ghi nhịp tim thai đơn thuần: cứ 24 đến 48 giờ làm một lần tìm dấu hiệu giảm phản ứng, nhịp tim thai phẳng, nhịp tim thai giảm muộn. Mọi bất thường của nhịp tim thai buộc phải làm test oxytocin: test (-) bảo đảm thai sống một tuần, test (+) phải chỉ định mổ lấy thai ngay.", "+ Monitor sản khoa thấy xuất hiện DIP II, có giá trị trong tiên lượng và điều trị.", "+ Định lượng estriol, creatinin trong nước tiểu trên 24h thấy giảm dần có giá trị gợi ý.", "+ Xử trí dựa vào CSO qua siêu âm.", "- Nếu CSO < 28 mm chỉ định mổ.", "- Nếu 28 mm < CSO < 40 mm: đình chỉ thai nghén bằng cách bấm ối gây chuyển dạ, nếu thất bại thì mổ lấy thai.", "- Nếu 40 mm < CSO < 60 mm: theo dõi thường xuyên bằng siêu âm để phát hiện sự giảm đi chỉ số nước ối và sử trí kịp thời.", "+ Căn cứ vào chỉ số Bishop để đưa ra hướng xử trí:", "- Chỉ số Bishop > 5 điểm gây chuyển dạ bằng truyền oxytocin tiên lượng kết quả tốt hơn.", "- Chỉ số Bishop < 5 điểm thì làm chín muồi cổ tử cung bằng prostaglandin. Theo dõi sát các yếu tố chuyển dạ vì dễ xảy ra các nguy cơ như suy thai, rối loạn cơn co...đây là một phương pháp được chấp nhận để giúp làm chín muồi của cổ tử cung và tạo cơn co tử cung gây chuyển dạ.", "+ Theo dõi suy thai bằng máy monitor: hai thử nghiệm hay được dùng là thử nghiệm không đả kích (non-stress test) và thử nghiệm đả kích (contraction stress test) như test vê núm vú hoặc test truyền oxytocin. Thử nghiệm này được làm 2 lần/tuần. Chỉ định mổ lấy thai nếu có xuất hiện Dip II.", "+ Trong trường hợp con hiếm hoặc bất tương xứng đầu chậu nên mổ lấy thai.", "+ Nếu có tình trạng suy thai: mổ lấy thai."]}, {"heading": "5. Bấm ối kết hợp với truyền oxytocin (chỉ được tiến hành tại cơ sở có phẫu thuật.)", "paragraphs": ["Chăm sóc sơ sinh", "Cần phải xem lại trẻ sơ sinh có bị bong da hay không, rau, ối như thế nào. Khi đã xác định là thai quá ngày sinh, cần phải thực hiện các biện pháp chăm sóc đặc biệt, hút kỹ phân su đường hô hấp, điều chỉnh toan chuyển hóa nếu có, tiêm Vitamin K1, kháng sinh dự phòng...và theo dõi sự phát triển của trẻ.", "Lưu ý: chẩn đoán thai quá ngày sinh hầu hết dựa vào những dấu hiệu nghi ngờ. Do đó đòi hỏi người thầy thuốc phải theo dõi sát bệnh nhân và quyết định xử trí đúng lúc, tránh những can thiệp trên một thai chưa đủ tháng, nhưng cũng không để xảy ra tình trạng suy thai và thai chết lưu."], "bullets": []}, {"heading": "Câu hỏi tự lượng giá:", "paragraphs": ["Nêu các đặc điểm liên quan của thai quá ngày sinh?", "Mô tả các triệu chứng lâm sàng, cận lâm sàng của thai quá ngày sinh?", "Nêu cách xử trí thai quá ngày sinh ở tuyến y tế cơ sở và tuyến chuyên khoa?."], "bullets": []}], "raw_text": "THAI QUÁ NGÀY SINH\nMục tiêu học tập\nPhân tích các đặc điểm liên quan của thai quá ngày sinh.\nMô tả các triệu chứng lâm sàng, cận lâm sàng của thai quá ngày sinh.\nLựa chọn cách xử trí thai quá ngày sinh.\nĐại cương\nThai nghén được gọi là quá ngày sinh khi tuối thai tính theo lý thuyết vượt quá 42 tuần (294 ngày). Thai nghén vượt quá 42 tuần chiếm 3 - 12%.\nPhải cho nằm viện để theo dõi sát các thai nghén từ sau 41 tuần (287 ngày) trở lên để phát hiện sớm suy thai vì bánh rau thoái hóa nên thai dễ bị suy, ngạt, tử vong do thiếu dinh dưỡng.\nTỷ lệ biến chứng cho mẹ và thai tăng theo tuối thai quá ngày sinh. Tỷ lệ tử vong chu sinh tăng từ tuối thai giữa tuần thứ 41 đến hết tuần 42, tăng gấp đôi vào tuần 43 và tăng gấp 4 - 6 lần vào tuần 44 so với thai đủ tháng. Tỷ lệ tử vong sơ sinh tăng gấp 3 lần so với thai đẻ đủ tháng 38 - 41 tuần.\nTần suất xuất hiện thai quá ngày sinh là từ 6%-12% các thai kỳ và có sự gia tăng nguy cơ cao cho con. Tần suất thai quá ngày sinh bị ảnh hưởng bởi nhiều yếu tố. Một trong những yếu tố quan trọng làm giảm tỷ lệ thai quá ngày sinh là sự siêu âm sớm để xác định tuối thai. Siêu âm 3 tháng đầu giúp tính ngày dự kiến sinh và khi biết chính xác tuối thai thì người ta không để thai kỳ kéo dài và làm giảm tỷ lệ thai quá ngày sinh.\nNguy cơ cho thai quá ngày sinh\n+ Suy thai: 5 -> 10% trẻ sơ sinh từ thai quá ngày sinh bị suy thai, tỷ lệ tử vong ở các trẻ này cao. Tuối thai càng quá ngày sinh tỷ lệ tử vong càng cao.\n+ Số lượng nước ối giảm: trong giai đoạn tuần thứ 37 đến tuần 41, thể tích nước ối giảm đi 10%, từ tuần thứ 42 trở đi thể tích nước ối giảm đi rất nhanh khoãng 33,5% trong 1 tuần.\n+ Thoái hoá gai rau: sau tuần 41, các gai rau thoái hóa, bánh rau canxi hóa độ III, xuất hiện hiện tượng trung tâm hoá tuần hoàn bánh rau. Tuần hoàn ở rau giảm đi dẫn đến suy thai, trọng lượng của thai không tăng thêm, dấu hiệu trung tâm hoá tuần hoàn bánh rau tăng ở người sản phụ cao tuối hoặc tiền sản giật. Thiếu oxy là nguyên nhân chính của suy thai do vậy thai sổ ra ngoài mang đặc điểm gầy, da nhăn nheo do bị mất nước, da thấm đầy phân su. Trong buồng tử cung nhanh chóng chuyển thành thiếu oxy khi có cơn co tử cung của chuyển dạ.\n+ Thai chết lưu.\n+ Rối loạn phát tiển thai nhi (chiếm tỷ lệ 10- 20% thai quá ngày sinh).\n+ Hội chứng hít phân su: 25-30 % thai 42 tuần có phân su trong dịch ối.\n+ Nếu thai to: gây đẻ khó, tổn thương xương và gãy xương và để lại chứng thần kinh\nNguy cơ cho mẹ\n- Tăng khả năng mổ lấy thai và đẻ có can thiệp thủ thuật.\n- Nằm viện dài ngày.\nNguyên nhân\n+ Sử dụng progesteron kéo dài.\n+ Nguyên nhân thường gặp nhất của thai quá ngày sinh là do sự tính toán không chính xác tuối thai vì:\n• Kinh không đều.\n• Rối loạn phóng noãn.\n• Không nhớ ngày kinh cuối cùng.\n+ Suy thượng thận thai nhi.\n+ Có một số thai quá ngày sinh là thai vô sọ. Người ta biết rằng khởi động chuyển dạ có một phần nguồn gốc do hoạt động của vùng dưới đồi của thai. Thai vô sọ không có tuyến yên làm rối loạn sản xuất và chuyển hoá estrogen dẫn tới chuyển dạ muộn.\n+ Suy thượng thận thai nhi.\n+ Thai vô sọ (không kèm đa ối)\n+ Thiếu Placental sulfatase ảnh hưởng đến sự chuyển hóa Estrogen ở rau thai, là một bệnh hiếm di truyền theo gen lặn liên kết với nhiễm sắc thể X.\n+ Giảm 16a hydroxy dehydroepiandrosterone beta sulfate (tiền chất của Estriol).\nSinh lý bệnh\nBánh rau và nước ối đóng một vai trò quan trọng trong quá trình vận chuyển và chuyển hóa sinh học của thai nhi. Trong thai quá ngày sinh, lượng nước ối giảm dần, bánh rau thoái hóa dần dẫn đến giảm dòng máu ở bánh rau và các chất dinh dưỡng đến thai. Do đó thai bị suy trong tử cung và có thể chết trong tử cung hoặc chết trong khi chuyển dạ (do có cơn co tử cung). Vì vậy, thai quá ngày sinh là thai nghén nguy cơ cao, thiếu oxy là nguyên nhân chính của suy thai, khi thai đẻ ra sống thì nó có biểu hiện tổn thương đặc biệt theo kiểu gầy, bị mất nước, da nhăn nheo nhuộm đầy phân su.\nVai trò của Estrogen trong khởi phát chuyển dạ. Bánh rau là nguồn cung cấp Estrogen chủ yếu. Nồng độ Estrogen tăng trong máu mẹ theo tuối thai. Estrone và 176-Estradiol dẫn xuất từ C19 Androgen trong khi Estriol dẫn xuất từ DHEAS thai nhi. Estrogen không gây cơn co tử cung nhưng khởi phát một chuỗi những thay đối ở cơ tử cung bao gồm sự gia tăng số lượng thụ thể Prostaglandin, thụ thể oxytocin, điều chỉnh tăng những enzyme chịu trách nhiệm trong sự co cơ tử cung (calmodulin, myosin light chain kinase).\nVai trò của Progesterone trong khởi phát chuyển dạ: Progesterone giúp tử cung ở trạng thải yên nghỉ trong nửa sau của thai kỳ bằng cách ức chế sự sản xuất prostaglandins. Cơ chế tác dụng của Progesterone liên quan đến thụ thể progesterone. Khi cho chất đối kháng thụ thể progesterone là RU-486 lúc thai đủ tháng thì làm tăng cơn co tử cung và khởi phát chuyển dạ. Cortisol và Progesterone có tác dụng đối kháng nhau nên với tình trạng tăng cortisol ở rau thai trước khi chuyển dạ sẽ ức chế hoạt động của progesterone và tạo cơn co tử cung.\nNhư vậy, khi có sự suy giảm hoạt động của trục dưới đồi – tuyến yên – tuyến thượng thận thai nhi thì đều có thể làm thiếu yếu tố khởi phát chuyển dạ khi thai đã đủ tháng từ đó dẫn đến thai quá ngày sinh.\nLâm sàng\nChẩn đoán thai quá ngày sinh:\n+ Dựa vào ngày bắt đầu có kinh của kỳ kinh cuối cùng: tuối thai lớn hơn 41 tuần, triệu chứng này không có giá trị chính xác vì còn phụ thuộc vào vòng kinh dài hay ngắn (phóng noãn sớm hay muộn).\n+ Dựa vào thời gian xuất hiện các cử động của thai nhi.\n+ Giảm số đo chiều cao tử cung qua 2 lần thăm khám kế tiếp nhau (không giảm chiều cao tử cung không cho phép loại trừ).\n+ Giảm cử động của thai nhi xảy ra đột ngột khi đang có cảm giác thai đạp nhiều.\nCận lâm sàng\n+ Chụp XQ: tìm điểm cốt hoá đầu dưới xương đùi (dấu hiệu Beclard), đầu trên xương chày (dấu hiệu Tod). Nếu thấy chỉ cho phép ta nói rằng thai đủ 38 tuần, điểm cốt hoá đầu trên xương cánh tay xuất hiện ở tuần 41. XQ chưa nói được thai quá ngày sinh, chỉ cho phép chẩn đoán là đủ tháng. Ngày nay ít dùng phương pháp này vì ảnh hưởng của tia X quang lên thai nhi chưa thực sự được hiểu biết rõ ràng.\n+ Siêu âm sớm (đặc biệt trong 3 tháng đầu) giúp chẩn đoán chính xác tuối thai.\n+ Siêu âm muộn ít chính xác hơn nhưng nếu thấy lượng nước ối ít và bánh rau vôi hóa nhiều cũng gợi ý chẩn đoán. Nếu chỉ số ối (CSO) < 40 mm, nguy cơ cao cho thai và có chỉ định đình chỉ thai nghén. Nếu 40 mm < CSO < 60 mm thì theo dõi. Nếu CSO > 60 mm là bình thường. Ngoài ra siêu âm còn giúp phát hiện thai dị dạng vô sọ, phù thai…\nDoppler: Phương pháp này cho phép khảo sát tình trạng huyết động học của thai và tuần hoàn rau thai để tiên lượng suy thai.\n+ Soi ối: soi ối hàng ngày thấy đầu ối dẹt dần đi, ngôi thai áp sát màng ối, nước ối có màu xanh nhạt. Ngày nay phương pháp này ít được sử dụng.\n+ Ghi nhịp tim thai đơn thuần: cứ 24 đến 48 giờ làm một lần tìm dấu hiệu giảm phản ứng, nhịp tim thai phẳng, nhịp tim thai giảm muộn. Mọi bất thường của nhịp tim thai buộc phải làm test oxytocin: test (-) bảo đảm thai sống một tuần, test (+) phải chỉ định mổ lấy thai ngay.\n+ Monitor sản khoa thấy xuất hiện DIP II, có giá trị trong tiên lượng và điều trị.\n+ Định lượng estriol, creatinin trong nước tiểu trên 24h thấy giảm dần có giá trị gợi ý.\nXử trí\nỞ tuyến y tế cơ sở\nỞ cơ sở không có phương tiện chẩn đoán thai quá ngày sinh thì nên xác định thai đủ tháng để có thể đình chỉ thai nghén. Tuy vậy không nên vội vàng kết thúc thai kỳ khi thai còn non tháng hoặc có thái độ chần chừ dẫn đến khi thai sinh ra thì đã suy do thai quá ngày sinh gây nhiều biến chứng cho thai. Cần được theo dõi sát sao bằng các triệu chứng lâm sàng, cận lâm sàng đặc hiệu nếu có, nếu không có điều kiện theo dõi cần gửi tới tuyến có điều kiện chẩn đoán và xử trí.\nTuyến chuyên khoa\n+ Xử trí dựa vào CSO qua siêu âm.\n- Nếu CSO < 28 mm chỉ định mổ.\n- Nếu 28 mm < CSO < 40 mm: đình chỉ thai nghén bằng cách bấm ối gây chuyển dạ, nếu thất bại thì mổ lấy thai.\n- Nếu 40 mm < CSO < 60 mm: theo dõi thường xuyên bằng siêu âm để phát hiện sự giảm đi chỉ số nước ối và sử trí kịp thời.\n+ Căn cứ vào chỉ số Bishop để đưa ra hướng xử trí:\n- Chỉ số Bishop > 5 điểm gây chuyển dạ bằng truyền oxytocin tiên lượng kết quả tốt hơn.\n- Chỉ số Bishop < 5 điểm thì làm chín muồi cổ tử cung bằng prostaglandin. Theo dõi sát các yếu tố chuyển dạ vì dễ xảy ra các nguy cơ như suy thai, rối loạn cơn co...đây là một phương pháp được chấp nhận để giúp làm chín muồi của cổ tử cung và tạo cơn co tử cung gây chuyển dạ.\nNếu trong quá trình gây chuyển dạ thất bại hoặc xuất hiện suy thai thì cũng phải mổ lấy thai.\n+ Theo dõi suy thai bằng máy monitor: hai thử nghiệm hay được dùng là thử nghiệm không đả kích (non-stress test) và thử nghiệm đả kích (contraction stress test) như test vê núm vú hoặc test truyền oxytocin. Thử nghiệm này được làm 2 lần/tuần. Chỉ định mổ lấy thai nếu có xuất hiện Dip II.\n+ Trong trường hợp con hiếm hoặc bất tương xứng đầu chậu nên mổ lấy thai.\n+ Nếu có tình trạng suy thai: mổ lấy thai.\nKhởi phát chuyển dạ bằng các phương pháp sau đây:\n1. Bóc tách màng ối.\n2. Bấm ối: cần đánh giá số lượng và màu sắc dịch ối. Phải theo dõi nhịp tim thai trước và ngay sau khi bấm ối. Có thể bấm ối đơn thuần hoặc kết hợp với truyền oxytocin.\n3. Sonde Foley. Đưa một sonde Foley qua lỗ trong cổ tử cung. Bơm 10ml huyết thanh mặn 0,9% làm phồng bóng cao su tạo áp lực giúp cho cổ tử cung xóa và mở. Khi cổ tử cung mở được 3cm, sonde sẽ tự tuột ra ngoài và cuộc chuyển dạ được khởi phát. Có thể kết hợp với truyền tĩnh mạch oxytocin nếu cần.\n4. Prostaglandin (chỉ được tiến hành tại cơ sở có phẫu thuật.) Prostaglandin giúp cổ tử cung chín muồi và mềm.\n5. Bấm ối kết hợp với truyền oxytocin (chỉ được tiến hành tại cơ sở có phẫu thuật.)\nChăm sóc sơ sinh\nCần phải xem lại trẻ sơ sinh có bị bong da hay không, rau, ối như thế nào. Khi đã xác định là thai quá ngày sinh, cần phải thực hiện các biện pháp chăm sóc đặc biệt, hút kỹ phân su đường hô hấp, điều chỉnh toan chuyển hóa nếu có, tiêm Vitamin K1, kháng sinh dự phòng...và theo dõi sự phát triển của trẻ.\nLưu ý: chẩn đoán thai quá ngày sinh hầu hết dựa vào những dấu hiệu nghi ngờ. Do đó đòi hỏi người thầy thuốc phải theo dõi sát bệnh nhân và quyết định xử trí đúng lúc, tránh những can thiệp trên một thai chưa đủ tháng, nhưng cũng không để xảy ra tình trạng suy thai và thai chết lưu.\nCâu hỏi tự lượng giá:\nNêu các đặc điểm liên quan của thai quá ngày sinh?\nMô tả các triệu chứng lâm sàng, cận lâm sàng của thai quá ngày sinh?\nNêu cách xử trí thai quá ngày sinh ở tuyến y tế cơ sở và tuyến chuyên khoa?.", "priority": "Trung bình"}, {"id": "SK-37", "chapter": "Chương 2. Sản bệnh", "folder": "02_San_benh", "title": "Nhiễm khuẩn hậu sản", "author": "Ths. Nguyễn Trung Kiên", "word_count": 2601, "line_count": 227, "key_numbers": ["10 ngày", "10mg", "15 ngày", "1kg", "2 giờ", "24 giờ", "25000 UI", "3 ngày", "3 tuần", "48 giờ", "6 giờ"], "key_drugs": ["oxytocin"], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["NHIỄM KHUẨN HẬU SẢN", "Ths. Nguyễn Trung Kiên"], "bullets": []}, {"heading": "1. ĐẠI CƯƠNG", "paragraphs": ["Nhiễm khuẩn hậu sản (NKHS) là một trong những tai biến sản khoa thường gặp, đặc biệt là ở các nước đang phát triển do nhiều nguyên nhân từ cơ sở và trang thiết bị yếu kém, thực hiện quy trình khống chế nhiễm khuẩn trong lĩnh vực sức khoẻ sinh sản chưa được bảo đảm… NKHS là một trong những nguyên nhân hàng đầu gây tử vong mẹ trong các tai biến Sản khoa, chiếm khoảng 34,7-43,4%."], "bullets": []}, {"heading": "1.1. Định nghĩa", "paragraphs": ["Nhiễm khuẩn hậu sản là các nhiễm khuẩn xuất phát từ bộ phận sinh dục trong thời kỳ hậu sản."], "bullets": []}, {"heading": "1.2. Đường vào", "paragraphs": ["Đường máu", "Nhiễm khuẩn ngược dòng từ âm đạo và/hoặc cổ tử cung", "Qua các tổn thương của sinh dục trong và sau khi đẻ: tầng sinh môn, âm hộ, âm đạo, cổ tử cung  bị tổn thương trong đẻ"], "bullets": ["- Sản dịch là môi trường tốt cho vi khuẩn"]}, {"heading": "1.3. Nguyên nhân/các yếu tố nguy cơ", "paragraphs": ["Cơ sở vật chất trang thiết bị không đảm bảo vô khuẩn.", "Các chỉ định và kỹ thuật can thiệp không đúng thời điểm (trường hợp đang nhiễm khuẩn) trong lĩnh vực sản khoa.", "Chăm sóc trước, trong và sau đẻ không đảm bảo qui trình.", "Các nhiễm khuẩn ở đường sinh dục không được xử trí tốt trước đẻ.", "Chuyển dạ kéo dài, ối vỡ non, ối vỡ sớm."], "bullets": []}, {"heading": "1.4. Mầm bệnh các loại vi khuẩn phân lập được", "paragraphs": ["Vi khuẩn", "Bệnh viện Trung ương Huế", "Viện BVBMTSS", "Tụ cầu", "50,4%", "76%", "E.Coli", "31,2%", "30,8%", "Phối hợp", "33,6%", "Aerobacter", "12,0%", "Dịch vết mổ", "Dịch âm đạo", "Tụ cầu", "78,2%", "44,1%", "E.Coli", "13,0%", "35,2%", "Aerobacter", "17,0%", "10,7%", "Phối hợp", "43,4%", "31,3%"], "bullets": []}, {"heading": "2.1. Nhiễm khuẩn tầng sinh môn, âm hộ, âm đạo", "paragraphs": ["Đây là hình thái nhẹ nhất", "Các triệu chứng/dấu hiệu:"], "bullets": ["+ Sốt nhẹ 38oC - 38o5 C", "+ Vùng tầng sinh môn có biểu hiện viêm tấy, đỏ, đau, trường hợp nặng có mủ (khối tụ máu âm hộ/âm đạo có thể là nơi đặc biệt dễ nhiễm khuẩn).", "- Tiến triển thường tốt nếu được phát hiện và điều trị kịp thời.", "- Điều trị:", "+ Cắt chỉ ngắt khoảng nếu vết khâu phù nề, cắt chỉ toàn bộ nếu vết thương có tấy đỏ và mủ.", "+ Kháng sinh đường uống hoặc đường toàn thân.", "+ Vệ sinh tại chỗ hàng ngày bằng dung dịch Betadine 10%."]}, {"heading": "2.2. Viêm nội mạc tử cung", "paragraphs": ["Đây là hình thái nhẹ, thường gặp, nếu không điều trị kịp thời có thể đưa đến các biến chứng. Các hình thái có thể gặp: viêm nội mạc tử cung đơn thuần, bế sản dịch và viêm niêm mạc tử cung chảy máu.", "Bế sản dịch là hình thái trung bình của viêm niêm mạc tử cung, khám thấy tử cung gập trước, sản dịch ra ít hoặc không, đau vùng hạ vị, ấn vào tử cung bệnh nhân đau.", "Hình thái viêm niêm mạc tử cung chảy máu: xuất hiện thường chậm hơn sau đẻ; sản dịch có màu đỏ, lẫn máu cục. Trường hợp này hay nhầm với chẩn đoán là sót ra, đưa đến xử trí nạo rau sót làm cho tiên lượng nặng hơn. Điều trị kháng sinh thích hợp với vi khuẩn, thường sau 48h tiến triển khả quan, góp phần co hồi tử cung bằng oxytocin hoặc methylergometrin."], "bullets": []}, {"heading": "2.2.1.Triệu chứng", "paragraphs": ["Sốt xuất hiện 2-3 ngày sau đẻ.", "Mạch nhanh 100 - 120 l /phút, mệt mỏi", "Tử cung co hồi chậm.", "Sản dịch hôi, có thể có mủ lẫn máu."], "bullets": []}, {"heading": "2.2.2. Điều trị", "paragraphs": [], "bullets": ["- Thuốc co hồi tử cung.", "- Kháng sinh đường tiêm.", "- Nong cổ tử cung trong trường hợp bế sản dịch.", "- Cấy sản dịch, sau đó điều chỉnh kháng sinh theo kháng sinh đồ.", "- Nạo buồng tử cung nếu có sót rau, tốt nhất sau khi đã dùng kháng sinh 24 giờ."]}, {"heading": "2.3. Viêm cơ tử cung", "paragraphs": ["Đây là hình thái hiếm gặp, thường xảy ra sau viêm nội mạc không được điều kịp thời và tích cực. Tiên lượng phụ thuộc vào chẩn đoán và điều trị.", "Những biến chứng có thể xảy ra là viêm phúc mạc hoặc nhiễm trùng máu."], "bullets": []}, {"heading": "2.3.1. Triệu chứng", "paragraphs": ["Sốt cao 39-40oC, biểu hiện nhiễm trùng nặng.", "Sản dịch hôi thối, ra máu lẫn mủ.", "Tử cung to mềm và nắn đau."], "bullets": []}, {"heading": "2.3.2. Điều trị", "paragraphs": ["Cấy sản dịch, điều trị theo kháng sinh đồ", "Dùng kháng sinh đường tiêm liều cao, phổ rộng và phối hợp 2-3 loại kháng sinh (Beta-Lactam, Aminosid, Metronidazol).", "Thuốc co hồi tử cung (oxytocin)"], "bullets": ["-  Nâng cao thể trạng, bù nước và điện giải, truyền máu nếu cần thiết.", "-  Nạo kiểm tra buồng tử cung trong trường hợp sót rau.", "-  Cắt tử cung trong các trường hợp nặng."]}, {"heading": "2.4.1. Triệu chứng", "paragraphs": ["Xuất hiện muộn 8 -10 ngày sau đẻ", "Sốt, mệt mỏi", "Tử cung co hồi chậm, sản dịch hôi", "Nắn thấy khối u cạnh tử cung đau, bờ không rõ"], "bullets": []}, {"heading": "2.4.2. Điều trị", "paragraphs": ["Kháng sinh phù hợp với kháng sinh đồ trong hai tuần hoặc cho đến khi khỏi", "Thuốc co hồi tử cung", "Giảm đau, kháng viêm", "Dẫn lưu túi mủ qua âm đạo", "Nếu nặng phải cắt tử cung bán phần và dẫn lưu"], "bullets": []}, {"heading": "2.5. Viêm phúc mạc tiểu khung", "paragraphs": ["Viêm phúc mạc tiểu khung là nhiễm khuẩn lan từ tử cung, dây chằng rộng, phần phụ, đáy chậu. Vi khuẩn cũng có thể xâm nhập từ vết thương tầng sinh môn trực tiếp vào tổ chức liên kết hoặc qua hệ thống bạch huyết."], "bullets": []}, {"heading": "2.5.1. Triệu chứng", "paragraphs": ["Thời gian xuất hiện 3 - 15 ngày sau đẻ, sau các hình thái khác của nhiễm khuẩn hậu sản.", "Sốt cao 39 - 40oC, rét run, mạch nhanh", "Biểu hiện nhiễm trùng và nhiễm độc nặng, sốt dao động", "Đau âm ỉ hạ vị", "Tiểu buốt, tiểu rát, hội chứng giả lỵ", "Tử cung to, đau, di động kém.", "Đau túi cùng sau khi khám"], "bullets": []}, {"heading": "2.5.2. Điều trị", "paragraphs": ["Nội khoa: Điều trị kháng sinh đường tiêm liều cao, phổ rộng và phối hợp 2-3 loại (Beta-Lactam, Aminosid, Metronidazol).", "Ngoại khoa: Dẫn lưu mủ từ túi cùng sau qua âm đạo (tốt nhất dưới hướng dẫn siêu âm)."], "bullets": []}, {"heading": "2.6.1. Triệu chứng: thường xuất hiện muộn", "paragraphs": ["Nếu viêm phúc mạc sau mổ các triệu chứng có sớm", "Sốt cao 39 - 40oC, rét run, mạch nhanh và nhỏ.", "Nhiễm độc nhiễm trùng nặng, hơi thở hôi, thở nhanh - nông", "Nôn, buồn nôn", "Ỉa chảy, phân thối khắm", "Bụng chướng, cảm ứng phúc mạc", "Tử cung to, ấn đau", "Cổ tử cung chưa đóng kín, các túi cùng căng đau", "Xét nghiệm :"], "bullets": ["+ Công thức máu có bạch cầu tăng cao, thiếu máu tán huyết.", "+ CRP cao, hematocrit cao.", "+ Rối loạn điện giải và toan chuyển hoá.", "+ Rối loạn chức năng gan thận.", "+ Cấy sản dịch xác định được vi khuẩn gây bệnh.", "+ Siêu âm: có dịch ổ bụng, các quai ruột chướng, có thể xác định được bất thường ở tử cung và nguyên nhân gây viêm phúc mạc."]}, {"heading": "2.6.2.  Tiên lượng", "paragraphs": ["Tiên lượng tốt nếu được chẩn đoán sớm và xử trí kịp thời."], "bullets": ["- Tiên lượng xấu nếu chẩn đoán muộn hoặc viêm phúc mạc kèm nhiễm trùng máu, thường để lại di chứng dính và tắc ruột, có thể tử vong."]}, {"heading": "2.6.3. Điều trị", "paragraphs": ["Nội khoa:", "Ngoại khoa: Phẫu thuật để dẫn lưu ổ mủ, hoặc cắt tử cung. Trong khi phẫu thuật cần cấy dịch ổ bụng, làm kháng sinh đồ."], "bullets": ["+ Nâng cao thể trạng, bồi phụ nước, điện giải.", "+ Kháng sinh liều cao, phối hợp, phổ diệt khuẩn rộng (Beta-Lactam, Aminosid, Metronidazol)"]}, {"heading": "2.7. Nhiễm khuẩn máu", "paragraphs": ["Là hình thái nặng nhất trong nhiễm khuẩn hậu sản.", "Tỉ lệ tử vong cao, có thể để lại nhiều di chứng."], "bullets": []}, {"heading": "2.7.1. Triệu chứng", "paragraphs": ["Thời gian xuất hiện sau can thiệp thủ thuật sớm nhất từ 24 - 48 giờ.", "Hội chứng nhiễm trùng nặng: Sốt cao, rét run, môi khô, lưỡi bẩn, mặt hốc hác do mất nước và nhiễm độc.", "Hội chứng thiếu máu: da xanh, hồng cầu và Hb giảm.", "Các dấu hiệu choáng: trạng thái tâm thần bất định, tụt huyết áp và rối loạn vận mạch và tình trạng nhiễm toan máu.", "Tử cung to, mềm, ấn rất đau, cổ tử cung hé mở, sản dịch nhiều bẩn đục như mủ lẫn máu và có mùi hôi.", "Có thể xuất hiện nhiễm khuẩn ở các cơ quan khác (phổi, gan hoặc thận).", "Cấy máu: phải thực hiện trước khi sử dụng kháng sinh để tìm tác nhân gây bệnh, phải cấy máu ít nhất 3 lần, cách nhau một giờ.", "Công thức máu: Bạch cầu tăng rất cao, tỷ lệ bạch cầu đa nhân trung tính tăng cao, hematocrit tăng, tốc độ lắng máu tăng cao.", "Chức năng gan thận suy giảm, rối loạn các yếu tố đông chảy máu."], "bullets": []}, {"heading": "2.7.2. Điều trị", "paragraphs": [], "bullets": ["- Nội khoa:", "+ Hồi sức chống choáng, truyền dịch, chống rối loạn nước, điện giải.", "+ Kháng sinh phổ rộng, liều cao, phối hợp, tốt nhất phải dựa theo kháng sinh đồ.", "- Ngoại - Sản khoa: nhằm loại bỏ ổ nhiễm khuẩn", "+ Cắt tử cung sau 6 giờ điều trị, chậm nhất là 24 giờ sau khi điều trị.", "+ Có thể giữ tử cung ở những bệnh nhân còn trẻ, mong muốn có con và đáp ứng tốt với điều trị nội khoa."]}, {"heading": "2.8. Choáng nhiễm khuẩn", "paragraphs": ["Choáng nhiễm khuẩn là biến chứng nặng của nhiễm khuẩn hậu sản, một tình trạng suy sụp tuần hoàn do nội độc tố của vi khuẩn.", "Tỷ lệ tử vong cao tới 60% - 75%."], "bullets": []}, {"heading": "2.8.1. Mầm bệnh", "paragraphs": ["Nhiều loại vi khuẩn có thể gây ra choáng nhiễm khuẩn như:"], "bullets": ["- Các loại vi khuẩn Gram dương: Tụ cầu vàng, liên cầu tan máu, clostridium", "- Các loại vi khuẩn Gram âm: Escherichia coli, Pseudomonas pyocyanea, Klebsiella pneumoniae, Proteus specils"]}, {"heading": "2.8.2. Triệu chứng", "paragraphs": ["Biểu hiện nổi bật là suy tuần hoàn và suy hô hấp: Tím tái toàn thân, nổi vân tím, khó thở,  thở nhanh nông, mạch nhanh, huyết áp tụt kẹp.", "Hội chứng nhiễm trùng nặng: sốt cao đột ngột, có thể đến 40 - 410C, môi khô, lưỡi bẩn.", "Thần kinh: lơ mơ, vật vã, ảo giác hoặc li bì.", "Thiểu niệu", "Công thức máu bạch cầu tăng cao, men gan tăng, urê máu tăng, rối loạn nước và điện giải. Cấy máu có thể tìm thấy vi khuẩn."], "bullets": []}, {"heading": "2.8.3. Điều trị", "paragraphs": ["Mục đích là chống nhiễm khuẩn, chống trụy tim mạch và các biến chứng."], "bullets": ["- Nội khoa:", "+ Hồi sức chống choáng, bồi phụ nước và điện giải. Truyền máu nếu có biểu hiện thiếu máu nặng hoặc rối loạn đông chảy máu.", "+ Trợ tim", "+ Corticoid", "+ Kháng sinh liều cao, phổ rộng, phối hợp, theo kháng sinh đồ.", "- Ngoại - Sản khoa:", "+ Sau khi điều trị choáng ổn định cần loại bỏ ổ nhiễm khuẩn: dẫn lưu ổ mủ, nạo buồng tử cung hoặc cắt tử cung."]}, {"heading": "2.9 Viêm tắc tĩnh mạch", "paragraphs": ["Viêm tắc tĩnh mạch sau đẻ hiếm gặp ở Viêt Nam. Viêm tắc tĩnh mạch tử cung, rồi lan đến tĩnh mạch quanh tử cung, tĩnh mạch chậu thường do những vi khuẩn loại liên cầu kỵ khí.", "Các vi khuẩn khu trú trong buồng tử cung sản sinh ra men streptokinase hủy hoại các thrombus (cục máu), rồi vi khuẩn lan theo thành mạch dọc đường đi của tĩnh mạch. Viêm tắc phát triển đến đâu thì thì những cục máu mới hình thành để hạn chế nhiễm khuẩn. Viêm tắc lan đến tĩnh mạch dây chằng rộng, buồng trứng, chậu, đùi, đôi khi lan đến tĩnh mạch chậu. Tĩnh mạch buồng trứng (thường bên trái) hay bị viêm tắc vì tĩnh mạch này dẫn lưu một nửa trên của tử cung."], "bullets": []}, {"heading": "2.9.1. Nguyên nhân", "paragraphs": ["Gặp ở con rạ, chuyển dạ kéo dài, chảy máu nhiều. Về cơ địa: lưu thông máu hệ thống tĩnh mạch bị cản trở, tăng sinh sợi huyết hoặc do yếu tố thần kinh giao cảm của hệ tĩnh mạch đùi, chân, bụng dưới."], "bullets": []}, {"heading": "2.9.2. Triệu chứng", "paragraphs": ["Triệu chứng xuất hiện muộn, sau đẻ 12-15 ngày, sốt nhẹ, rét run, mạch nhanh xuất hiện sớm, nhịp tăng dần. Viêm tắc tĩnh mạch ở chân: chân phù, màu trắng, ấn đau (phlegmatia alba dolens), căng nóng từ đùi trở xuống, gót chân không nhấc được khỏi mặt giường.", "Khi điều trị không kịp thời, nhiễm khuẩn lan đến phổi gây viêm tắc động mạch phổi ( khó thở, khạc ra máu, tức ngực), viêm tắc động mạch thận….bệnh nhân có thể tử vong đột ngột."], "bullets": []}, {"heading": "2.9.3 Điều trị", "paragraphs": ["Cần làm xét nghiệm về thời gian đông máu, tiểu cầu , thời gian Quick và tỷ lệ prothrombin.", "Bất động chân trong khi bị bệnh và kéo dài 3 tuần sau khi hết sốt.", "Điều trị kháng sinh, corticoid sau vài ngày điều trị kháng sinh.", "Thuốc chống đông máu: Heparin 25000 UI/1kg thể trọng/24 giờ, tiêm tĩnh mạch cách 2 giờ một lần hoặc truyền nhỏ giọt tĩnh mạch, lưu lượng cố định vì heparin thải trừ nhanh.", "Hoặc Dicoumarol (Coumadine) loại uống 2-10mg, đây là loại kháng vitamin K, tác dụng chậm, liều 2-10mg/ 24 giờ. Theo dõi kết quả điều trị bằng xét nghiệm thời gian Howell, Quick.", "Đang sử dụng heparin nếu thay thế bằng dicoumarol thì phải tiếp tục heparin cho đến khi có tác dụng của dicoumarol.", "Với heparin kiểm tra xét nghiệm giảm đông máu bằng 1,5-3 lần thời gian so với chứng. Với dicoumarol duy trì thời gian quick là 20-35%."], "bullets": []}, {"heading": "3. DỰ PHÒNG", "paragraphs": ["Muốn hạn chế các nhiễm khuẩn hậu sản cũng như các biến chứng của nó, cần làm tốt những việc sau:", "Đảm bảo điều kiện vô khuẩn khi đỡ đẻ, khi tiến hành thăm khám, các thủ thuật phẫu thuật sản phụ khoa.", "Xử trí tốt các tổn thương sinh dục khi đẻ, không để sót rau, chỉ định đúng kiểm soát tử cung, bóc rau nhân tạo.", "Phát hiện sớm, điều trị tích cực các trường hợp nhiễm khuẩn sinh dục trước, trong và sau đẻ."], "bullets": []}, {"heading": "Câu hỏi:", "paragraphs": ["1: Trình bày triệu chứng lâm sàng, cận lâm sàng của nhiễm khuẩn huyết và hướng điều trị?", "2: Trình bày nguyên nhân, triệu chứng nhiễm khuẩn tầng sinh môn sau đẻ và hướng điều trị ?", "3: Trình bày nguyên nhân, triệu chứng của viêm niêm mạc tử cung sau đẻ. Hướng điều trị ?", "4: Trình bày triệu chứng lâm sàng của viêm tử cung sau đẻ. Hướng điều trị?", "CHƯƠNG 3. PHỤ KHOA"], "bullets": []}], "raw_text": "NHIỄM KHUẨN HẬU SẢN\nThs. Nguyễn Trung Kiên\nMục tiêu học tập\n1. Kể ra được các yếu tố thuận lợi và các loại vi khuẩn gây nhiễm khuẩn hậu sản.\n2. Trình bày được triệu chứng của các thể lâm sàng trong nhiễm khuẩn hậu sản.\n3. Lựa chọn được hướng xử trí các thể lâm sàng của nhiễm khuẩn hậu sản ở tuyến y tế cơ sở.\n\n1. ĐẠI CƯƠNG\nNhiễm khuẩn hậu sản (NKHS) là một trong những tai biến sản khoa thường gặp, đặc biệt là ở các nước đang phát triển do nhiều nguyên nhân từ cơ sở và trang thiết bị yếu kém, thực hiện quy trình khống chế nhiễm khuẩn trong lĩnh vực sức khoẻ sinh sản chưa được bảo đảm… NKHS là một trong những nguyên nhân hàng đầu gây tử vong mẹ trong các tai biến Sản khoa, chiếm khoảng 34,7-43,4%.\n1.1. Định nghĩa\nNhiễm khuẩn hậu sản là các nhiễm khuẩn xuất phát từ bộ phận sinh dục trong thời kỳ hậu sản.\n1.2. Đường vào\nĐường máu\nNhiễm khuẩn ngược dòng từ âm đạo và/hoặc cổ tử cung\nQua các tổn thương của sinh dục trong và sau khi đẻ: tầng sinh môn, âm hộ, âm đạo, cổ tử cung  bị tổn thương trong đẻ\n- Sản dịch là môi trường tốt cho vi khuẩn\n1.3. Nguyên nhân/các yếu tố nguy cơ\nCơ sở vật chất trang thiết bị không đảm bảo vô khuẩn.\nCác chỉ định và kỹ thuật can thiệp không đúng thời điểm (trường hợp đang nhiễm khuẩn) trong lĩnh vực sản khoa.\nChăm sóc trước, trong và sau đẻ không đảm bảo qui trình.\nCác nhiễm khuẩn ở đường sinh dục không được xử trí tốt trước đẻ.\nChuyển dạ kéo dài, ối vỡ non, ối vỡ sớm.\n1.4. Mầm bệnh các loại vi khuẩn phân lập được\nVi khuẩn\nBệnh viện Trung ương Huế\nViện BVBMTSS\n\nTụ cầu\n50,4%\n76%\n\nE.Coli\n31,2%\n30,8%\n\nPhối hợp\n33,6%\n\n\nAerobacter\n12,0%\n\n\n\nDịch vết mổ\nDịch âm đạo\n\nTụ cầu\n78,2%\n44,1%\n\nE.Coli\n13,0%\n35,2%\n\nAerobacter\n17,0%\n10,7%\n\nPhối hợp\n43,4%\n31,3%\n\n\n2. CÁC HÌNH THÁI NHIỄM KHUẨN HẬU SẢN\n2.1. Nhiễm khuẩn tầng sinh môn, âm hộ, âm đạo\nĐây là hình thái nhẹ nhất\nCác triệu chứng/dấu hiệu:\n+ Sốt nhẹ 38oC - 38o5 C\n+ Vùng tầng sinh môn có biểu hiện viêm tấy, đỏ, đau, trường hợp nặng có mủ (khối tụ máu âm hộ/âm đạo có thể là nơi đặc biệt dễ nhiễm khuẩn).\n- Tiến triển thường tốt nếu được phát hiện và điều trị kịp thời.\n- Điều trị:\n+ Cắt chỉ ngắt khoảng nếu vết khâu phù nề, cắt chỉ toàn bộ nếu vết thương có tấy đỏ và mủ.\n+ Kháng sinh đường uống hoặc đường toàn thân.\n+ Vệ sinh tại chỗ hàng ngày bằng dung dịch Betadine 10%.\n2.2. Viêm nội mạc tử cung\nĐây là hình thái nhẹ, thường gặp, nếu không điều trị kịp thời có thể đưa đến các biến chứng. Các hình thái có thể gặp: viêm nội mạc tử cung đơn thuần, bế sản dịch và viêm niêm mạc tử cung chảy máu.\nBế sản dịch là hình thái trung bình của viêm niêm mạc tử cung, khám thấy tử cung gập trước, sản dịch ra ít hoặc không, đau vùng hạ vị, ấn vào tử cung bệnh nhân đau.\nHình thái viêm niêm mạc tử cung chảy máu: xuất hiện thường chậm hơn sau đẻ; sản dịch có màu đỏ, lẫn máu cục. Trường hợp này hay nhầm với chẩn đoán là sót ra, đưa đến xử trí nạo rau sót làm cho tiên lượng nặng hơn. Điều trị kháng sinh thích hợp với vi khuẩn, thường sau 48h tiến triển khả quan, góp phần co hồi tử cung bằng oxytocin hoặc methylergometrin.\n2.2.1.Triệu chứng\nSốt xuất hiện 2-3 ngày sau đẻ.\nMạch nhanh 100 - 120 l /phút, mệt mỏi\nTử cung co hồi chậm.\nSản dịch hôi, có thể có mủ lẫn máu.\n2.2.2. Điều trị\n- Thuốc co hồi tử cung.\n- Kháng sinh đường tiêm.\n- Nong cổ tử cung trong trường hợp bế sản dịch.\n- Cấy sản dịch, sau đó điều chỉnh kháng sinh theo kháng sinh đồ.\n- Nạo buồng tử cung nếu có sót rau, tốt nhất sau khi đã dùng kháng sinh 24 giờ.\n2.3. Viêm cơ tử cung\nĐây là hình thái hiếm gặp, thường xảy ra sau viêm nội mạc không được điều kịp thời và tích cực. Tiên lượng phụ thuộc vào chẩn đoán và điều trị.\nNhững biến chứng có thể xảy ra là viêm phúc mạc hoặc nhiễm trùng máu.\n2.3.1. Triệu chứng\nSốt cao 39-40oC, biểu hiện nhiễm trùng nặng.\nSản dịch hôi thối, ra máu lẫn mủ.\nTử cung to mềm và nắn đau.\n2.3.2. Điều trị\nCấy sản dịch, điều trị theo kháng sinh đồ\nDùng kháng sinh đường tiêm liều cao, phổ rộng và phối hợp 2-3 loại kháng sinh (Beta-Lactam, Aminosid, Metronidazol).\nThuốc co hồi tử cung (oxytocin)\n-  Nâng cao thể trạng, bù nước và điện giải, truyền máu nếu cần thiết.\n-  Nạo kiểm tra buồng tử cung trong trường hợp sót rau.\n-  Cắt tử cung trong các trường hợp nặng.\n2.4. Viêm dây chằng và phần phụ\n2.4.1. Triệu chứng\nXuất hiện muộn 8 -10 ngày sau đẻ\nSốt, mệt mỏi\nTử cung co hồi chậm, sản dịch hôi\nNắn thấy khối u cạnh tử cung đau, bờ không rõ\n2.4.2. Điều trị\nKháng sinh phù hợp với kháng sinh đồ trong hai tuần hoặc cho đến khi khỏi\nThuốc co hồi tử cung\nGiảm đau, kháng viêm\nDẫn lưu túi mủ qua âm đạo\nNếu nặng phải cắt tử cung bán phần và dẫn lưu\n2.4.3. Tiến triển: phụ thuộc vào thời gian phát hiện và điều trị; khỏi hoặc biến thành ổ mủ, viêm phúc mạc khu trú, viêm phúc mạc toàn thể.\n2.5. Viêm phúc mạc tiểu khung\nViêm phúc mạc tiểu khung là nhiễm khuẩn lan từ tử cung, dây chằng rộng, phần phụ, đáy chậu. Vi khuẩn cũng có thể xâm nhập từ vết thương tầng sinh môn trực tiếp vào tổ chức liên kết hoặc qua hệ thống bạch huyết.\n2.5.1. Triệu chứng\nThời gian xuất hiện 3 - 15 ngày sau đẻ, sau các hình thái khác của nhiễm khuẩn hậu sản.\nSốt cao 39 - 40oC, rét run, mạch nhanh\nBiểu hiện nhiễm trùng và nhiễm độc nặng, sốt dao động\nĐau âm ỉ hạ vị\nTiểu buốt, tiểu rát, hội chứng giả lỵ\nTử cung to, đau, di động kém.\nĐau túi cùng sau khi khám\n2.5.2. Điều trị\nNội khoa: Điều trị kháng sinh đường tiêm liều cao, phổ rộng và phối hợp 2-3 loại (Beta-Lactam, Aminosid, Metronidazol).\nNgoại khoa: Dẫn lưu mủ từ túi cùng sau qua âm đạo (tốt nhất dưới hướng dẫn siêu âm).\n2.5.3. Tiến triển: Có thể dẫn tới viêm phúc mạc toàn thể.\n2.6. Viêm phúc mạc toàn thể\n2.6.1. Triệu chứng: thường xuất hiện muộn\nNếu viêm phúc mạc sau mổ các triệu chứng có sớm\nSốt cao 39 - 40oC, rét run, mạch nhanh và nhỏ.\nNhiễm độc nhiễm trùng nặng, hơi thở hôi, thở nhanh - nông\nNôn, buồn nôn\nỈa chảy, phân thối khắm\nBụng chướng, cảm ứng phúc mạc\nTử cung to, ấn đau\nCổ tử cung chưa đóng kín, các túi cùng căng đau\nXét nghiệm :\n+ Công thức máu có bạch cầu tăng cao, thiếu máu tán huyết.\n+ CRP cao, hematocrit cao.\n+ Rối loạn điện giải và toan chuyển hoá.\n+ Rối loạn chức năng gan thận.\n+ Cấy sản dịch xác định được vi khuẩn gây bệnh.\n+ Siêu âm: có dịch ổ bụng, các quai ruột chướng, có thể xác định được bất thường ở tử cung và nguyên nhân gây viêm phúc mạc.\n2.6.2.  Tiên lượng\nTiên lượng tốt nếu được chẩn đoán sớm và xử trí kịp thời.\n- Tiên lượng xấu nếu chẩn đoán muộn hoặc viêm phúc mạc kèm nhiễm trùng máu, thường để lại di chứng dính và tắc ruột, có thể tử vong.\n2.6.3. Điều trị\nNội khoa:\n+ Nâng cao thể trạng, bồi phụ nước, điện giải.\n+ Kháng sinh liều cao, phối hợp, phổ diệt khuẩn rộng (Beta-Lactam, Aminosid, Metronidazol)\nNgoại khoa: Phẫu thuật để dẫn lưu ổ mủ, hoặc cắt tử cung. Trong khi phẫu thuật cần cấy dịch ổ bụng, làm kháng sinh đồ.\n2.7. Nhiễm khuẩn máu\nLà hình thái nặng nhất trong nhiễm khuẩn hậu sản.\nTỉ lệ tử vong cao, có thể để lại nhiều di chứng.\n2.7.1. Triệu chứng\nThời gian xuất hiện sau can thiệp thủ thuật sớm nhất từ 24 - 48 giờ.\nHội chứng nhiễm trùng nặng: Sốt cao, rét run, môi khô, lưỡi bẩn, mặt hốc hác do mất nước và nhiễm độc.\nHội chứng thiếu máu: da xanh, hồng cầu và Hb giảm.\nCác dấu hiệu choáng: trạng thái tâm thần bất định, tụt huyết áp và rối loạn vận mạch và tình trạng nhiễm toan máu.\nTử cung to, mềm, ấn rất đau, cổ tử cung hé mở, sản dịch nhiều bẩn đục như mủ lẫn máu và có mùi hôi.\nCó thể xuất hiện nhiễm khuẩn ở các cơ quan khác (phổi, gan hoặc thận).\nCấy máu: phải thực hiện trước khi sử dụng kháng sinh để tìm tác nhân gây bệnh, phải cấy máu ít nhất 3 lần, cách nhau một giờ.\nCông thức máu: Bạch cầu tăng rất cao, tỷ lệ bạch cầu đa nhân trung tính tăng cao, hematocrit tăng, tốc độ lắng máu tăng cao.\nChức năng gan thận suy giảm, rối loạn các yếu tố đông chảy máu.\n2.7.2. Điều trị\n- Nội khoa:\n+ Hồi sức chống choáng, truyền dịch, chống rối loạn nước, điện giải.\n+ Kháng sinh phổ rộng, liều cao, phối hợp, tốt nhất phải dựa theo kháng sinh đồ.\n- Ngoại - Sản khoa: nhằm loại bỏ ổ nhiễm khuẩn\n+ Cắt tử cung sau 6 giờ điều trị, chậm nhất là 24 giờ sau khi điều trị.\n+ Có thể giữ tử cung ở những bệnh nhân còn trẻ, mong muốn có con và đáp ứng tốt với điều trị nội khoa.\n2.8. Choáng nhiễm khuẩn\nChoáng nhiễm khuẩn là biến chứng nặng của nhiễm khuẩn hậu sản, một tình trạng suy sụp tuần hoàn do nội độc tố của vi khuẩn.\nTỷ lệ tử vong cao tới 60% - 75%.\n2.8.1. Mầm bệnh\nNhiều loại vi khuẩn có thể gây ra choáng nhiễm khuẩn như:\n- Các loại vi khuẩn Gram dương: Tụ cầu vàng, liên cầu tan máu, clostridium\n- Các loại vi khuẩn Gram âm: Escherichia coli, Pseudomonas pyocyanea, Klebsiella pneumoniae, Proteus specils\n2.8.2. Triệu chứng\nBiểu hiện nổi bật là suy tuần hoàn và suy hô hấp: Tím tái toàn thân, nổi vân tím, khó thở,  thở nhanh nông, mạch nhanh, huyết áp tụt kẹp.\nHội chứng nhiễm trùng nặng: sốt cao đột ngột, có thể đến 40 - 410C, môi khô, lưỡi bẩn.\nThần kinh: lơ mơ, vật vã, ảo giác hoặc li bì.\nThiểu niệu\nCông thức máu bạch cầu tăng cao, men gan tăng, urê máu tăng, rối loạn nước và điện giải. Cấy máu có thể tìm thấy vi khuẩn.\n2.8.3. Điều trị\nMục đích là chống nhiễm khuẩn, chống trụy tim mạch và các biến chứng.\n- Nội khoa:\n+ Hồi sức chống choáng, bồi phụ nước và điện giải. Truyền máu nếu có biểu hiện thiếu máu nặng hoặc rối loạn đông chảy máu.\n+ Trợ tim\n+ Corticoid\n+ Kháng sinh liều cao, phổ rộng, phối hợp, theo kháng sinh đồ.\n- Ngoại - Sản khoa:\n+ Sau khi điều trị choáng ổn định cần loại bỏ ổ nhiễm khuẩn: dẫn lưu ổ mủ, nạo buồng tử cung hoặc cắt tử cung.\n2.9 Viêm tắc tĩnh mạch\nViêm tắc tĩnh mạch sau đẻ hiếm gặp ở Viêt Nam. Viêm tắc tĩnh mạch tử cung, rồi lan đến tĩnh mạch quanh tử cung, tĩnh mạch chậu thường do những vi khuẩn loại liên cầu kỵ khí.\nCác vi khuẩn khu trú trong buồng tử cung sản sinh ra men streptokinase hủy hoại các thrombus (cục máu), rồi vi khuẩn lan theo thành mạch dọc đường đi của tĩnh mạch. Viêm tắc phát triển đến đâu thì thì những cục máu mới hình thành để hạn chế nhiễm khuẩn. Viêm tắc lan đến tĩnh mạch dây chằng rộng, buồng trứng, chậu, đùi, đôi khi lan đến tĩnh mạch chậu. Tĩnh mạch buồng trứng (thường bên trái) hay bị viêm tắc vì tĩnh mạch này dẫn lưu một nửa trên của tử cung.\n2.9.1. Nguyên nhân\nGặp ở con rạ, chuyển dạ kéo dài, chảy máu nhiều. Về cơ địa: lưu thông máu hệ thống tĩnh mạch bị cản trở, tăng sinh sợi huyết hoặc do yếu tố thần kinh giao cảm của hệ tĩnh mạch đùi, chân, bụng dưới.\n2.9.2. Triệu chứng\nTriệu chứng xuất hiện muộn, sau đẻ 12-15 ngày, sốt nhẹ, rét run, mạch nhanh xuất hiện sớm, nhịp tăng dần. Viêm tắc tĩnh mạch ở chân: chân phù, màu trắng, ấn đau (phlegmatia alba dolens), căng nóng từ đùi trở xuống, gót chân không nhấc được khỏi mặt giường.\nKhi điều trị không kịp thời, nhiễm khuẩn lan đến phổi gây viêm tắc động mạch phổi ( khó thở, khạc ra máu, tức ngực), viêm tắc động mạch thận….bệnh nhân có thể tử vong đột ngột.\n2.9.3 Điều trị\nCần làm xét nghiệm về thời gian đông máu, tiểu cầu , thời gian Quick và tỷ lệ prothrombin.\nBất động chân trong khi bị bệnh và kéo dài 3 tuần sau khi hết sốt.\nĐiều trị kháng sinh, corticoid sau vài ngày điều trị kháng sinh.\nThuốc chống đông máu: Heparin 25000 UI/1kg thể trọng/24 giờ, tiêm tĩnh mạch cách 2 giờ một lần hoặc truyền nhỏ giọt tĩnh mạch, lưu lượng cố định vì heparin thải trừ nhanh.\nHoặc Dicoumarol (Coumadine) loại uống 2-10mg, đây là loại kháng vitamin K, tác dụng chậm, liều 2-10mg/ 24 giờ. Theo dõi kết quả điều trị bằng xét nghiệm thời gian Howell, Quick.\nĐang sử dụng heparin nếu thay thế bằng dicoumarol thì phải tiếp tục heparin cho đến khi có tác dụng của dicoumarol.\nVới heparin kiểm tra xét nghiệm giảm đông máu bằng 1,5-3 lần thời gian so với chứng. Với dicoumarol duy trì thời gian quick là 20-35%.\n3. DỰ PHÒNG\nMuốn hạn chế các nhiễm khuẩn hậu sản cũng như các biến chứng của nó, cần làm tốt những việc sau:\nĐảm bảo điều kiện vô khuẩn khi đỡ đẻ, khi tiến hành thăm khám, các thủ thuật phẫu thuật sản phụ khoa.\nXử trí tốt các tổn thương sinh dục khi đẻ, không để sót rau, chỉ định đúng kiểm soát tử cung, bóc rau nhân tạo.\nPhát hiện sớm, điều trị tích cực các trường hợp nhiễm khuẩn sinh dục trước, trong và sau đẻ.\n\nCâu hỏi:\n1: Trình bày triệu chứng lâm sàng, cận lâm sàng của nhiễm khuẩn huyết và hướng điều trị?\n2: Trình bày nguyên nhân, triệu chứng nhiễm khuẩn tầng sinh môn sau đẻ và hướng điều trị ?\n3: Trình bày nguyên nhân, triệu chứng của viêm niêm mạc tử cung sau đẻ. Hướng điều trị ?\n4: Trình bày triệu chứng lâm sàng của viêm tử cung sau đẻ. Hướng điều trị?\n\nCHƯƠNG 3. PHỤ KHOA", "priority": "Cao (Trọng tâm BSNT)"}, {"id": "SK-38", "chapter": "Chương 3. Phụ khoa", "folder": "03_Phu_khoa", "title": "Thăm dò trong phụ khoa", "author": "Ths. Phạm Thị Quỳnh Như", "word_count": 2538, "line_count": 201, "key_numbers": ["24 giờ", "28 ngày", "3 ngày", "4 cm"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["THĂM DÒ TRONG PHỤ KHOA.Lê Hải Dương K II.Lê Hả", "Ths. BMục tiêu học tập", "Nêu được các phương pháp thăm dò âm đạo và chất nhầy cổ tử cung.", "Trình bày được cách thực hiện tế bào âm đạo cổ tử cung và đánh giá theo Bethesda 2001.", "Trình bày được ý nghĩa của soi cổ tử cung.", "Liệt kê được các phương pháp thăm dò buồng tử cung.", "Trình bày được các phương pháp thăm dò vú.", "Trình bày được các chỉ định nội soi ổ bụng."], "bullets": []}, {"heading": "1.1. Đo pH âm đạo", "paragraphs": [], "bullets": ["- Trong điều kiện bình thường, dịch âm đạo là một chất màu trắng, hơi sệt như bột. Các trực khuẩn Doderlein có mặt trong âm đạo sử dụng glycogen từ các tế bào âm đạo bị bong tróc tạo ra acid latic, vì vậy môi trường âm đạo có pH acid. Nồng độ estrogen càng cao thì âm đạo càng nhiều glycogen.", "- pH âm đạo xung quanh ngày phóng noãn là 4,2, trước và sau hành kinh pH từ 4,8 đến 5,2, trong những ngày hành kinh âm đạo có pH là 5,4. Ở phụ nữ có kinh nguyệt bình thường nếu pH trên 5,5 phải nghĩ tới viêm âm đạo (có thể do Trichomonas).", "- Thường sử dụng giấy quỳ để đo pH âm đạo."]}, {"heading": "1.2. Xét nghiệm độ sạch âm đạo:", "paragraphs": ["Hình 1. Trực khuẩn Doderlein", "KẾT QUẢ: chia độ sạch âm đạo thành 4 độ như sau", "Như vậy độ 3 và độ 4 cho biết mức độ viêm và thiểu năng Estrogen của âm đạo vừa hay nặng, phụ thuộc vào số lượng trực khuẩn Doderlein nhiều hay ít."], "bullets": ["- Bình thường trong dịch âm đạo bao gồm các tế bào biểu mô âm đạo đã bong, trực khuẩn Doderlein, một số tạp khuẩn và bạch cầu. Việc xét nghiệm âm đạo giúp tìm ra nguyên nhân gây viêm âm đạo để điều trị.", "- Kỹ thuật: Để xét nghiệm độ sạch âm đạo người bệnh không thụt rửa âm đạo, không khám phụ khoa trước khi lấy phiến đồ âm đạo. Cách làm: lấy dịch ở túi cùng sau âm đạo, phết lên phiến kính, cố định bằng hỗn hợp cồn 90o + ête (tỷ lệ cồn 50%, ête 50%)", "- Độ 1:", "+ Trực khuẩn Doderlein: nhiều", "+ Tế bào biểu mô âm đạo: nhiều", "+ Các vi khuẩn khác: không có, không có nấm và Trichomonas", "+ Bạch cầu: không có", "- Độ 2:", "+ Trực khuẩn Doderlein: nhiều", "+ Tế bào biểu mô âm đạo: nhiều", "+ Các vi khuẩn khác: có ít, không có nấm và Trichomonas", "+ Bạch cầu: có ít", "- Độ 3:", "+ Trực khuẩn Doderlein: giảm", "+ Tế bào biểu mô âm đạo: rất ít", "+ Các vi khuẩn khác: rất nhiều, có nấm hoặc Trichomonas", "+ Bạch cầu: rất nhiều hay (+++)", "- Độ 4:", "+ Trực khuẩn Doderlein: không còn", "+ Tế bào biểu mô âm đạo: rất ít", "+ Các vi khuẩn khác: rất nhiều, có nấm hoặc Trichomonas", "+ Bạch cầu: rất nhiều hay (+++)"]}, {"heading": "1.3. Thăm dò chất nhầy cổ tử cung", "paragraphs": ["Bình thường xung quanh ngày phóng noãn, lỗ cổ tử cung hé mở rồi mở cực đại vào ngày phóng noãn, chất nhầy trong, loãng và kéo dài thành sợi dài. Chất nhầy thường được đánh giá vào giai đoạn trước phóng noãn (từ ngày 12-14 của chu kỳ 28 ngày) giữa 2 phần đầu của 1 kẹp (pince) dài. Người ta quan sát số lượng, độ kéo sợi, độ trong và độ đục của chất nhầy."], "bullets": ["+ Nhiễm trùng khi chất nhầy đục, soi dưới kính hiển vi thấy nhiều bạch cầu.", "+ Dưới tác dụng của estrogen, chất nhầy nhiều và kéo sợi; Dưới tác dụng của progesteron thì chất nhầy đặc và vón lại."]}, {"heading": "1.4. Xét nghiệm tế bào âm đạo cổ tử cung", "paragraphs": ["Phương pháp tế bào học cổ điển", "Hình 2. Dụng cụ lấy tế bào âm đạo cổ tử cung cổ điển", "Hình 3. Cách phết bệnh phẩm từ thìa và bàn chải lên lam kính", "A. Bệnh phẩm từ ống cổ tử cung, B. Bệnh phẩm từ lổ ngoài cổ tử cung", "Phương pháp tế bào học nhúng dịch", "Hình 4. Phương pháp tế bào học nhúng dịch", "Đánh giá kết quả: tiêu bản được nhuộm theo phương pháp Papanicolaou và xếp loại theo danh pháp Bethesda 2001 bao gồm:", "Bình thường: không có các tế bào bị biến đổi hình dạng hoặc thay đổi tế bào phản ứng lành tính", "Các bất thường tế bào biểu mô vẩy:", "Các thay đổi tế bào biểu mô trụ:", "Các tổn thương tân sinh ác tính khác"], "bullets": ["- Là một thăm dò thường quy được tiến hành có hệ thống và định kỳ cho mọi phụ nữ nhằm chẩn đoán sớm ung thư cổ tử cung. Xét nghiệm giúp phát hiện các biến đổi ở mức độ tế bào theo hướng tiền ung thư hoặc ung thư.", "- Tối thiểu 24 giờ trước khi lấy bệnh phẩm, bệnh nhân không khám phụ khoa, không thụt rửa âm đạo, không giao hợp, không đặt thuốc âm đạo trước đó 3 ngày và lấy ngoài thời kỳ kinh nguyệt.", "- Có 2 phương pháp lấy bệnh phẩm làm xét nghiệm tế bào âm đạo cổ tử cung", "- Kỹ thuật lấy bệnh phẩm: sử dụng que bẹt gỗ 2 đầu và phải lấy được vùng chuyển tiếp vẩy - trụ. Dàn 2 đầu que trên lam kính đảm bảo dàn mỏng, đều, đủ bệnh phẩm.", "-  Kỹ thuật lấy bệnh phẩm: Dùng dụng cụ phết chuyên biệt được cung cấp bởi nhà sản xuất (thường là chổi) để phết lên cổ tử cung, sau đó khuấy dụng cụ phết vào trong hộp chứa dung dịch bảo quản để chuyển bệnh phẩm tế bào vào dung dịch bảo quản. Hệ thống máy sẽ xử lý bệnh phẩm loại bỏ hồng cầu, bạch cầu, các thành phần không có giá trị chẩn đoán rồi chuyển lên lam kính.", "+ Tế bào biểu mô vẩy không điển hình có ý nghĩa chưa xác định (ASC-US)", "+ Tế bào biểu mô vẩy không điển hình không loại trừ tổn thương nội biểu mô vảy mức độ cao ( ASC – H)", "+ Tổn thương nội biểu mô vẩy mức độ thấp (LSIL) bao gồm: tổn thương do nhiễm HPV, loạn sản nhẹ/CIN 1.", "+ Tổn thương nội biểu mô vẩy mức độ cao (HSIL) bao gồm: loạn sản trung bình và nặng, ung thư tại chỗ và những tổn thương nghi ngờ ung thư xâm lấn.", "+ Ung thư biểu mô vảy.", "+ Tế bào biểu mô tuyến không điển hình (AGUS)", "+ Ung thư tế bào biểu mô tuyến cổ tử cung tại chỗ (AIS)", "+ Ung thư biểu mô tuyến xâm nhập: biểu mô tuyến ống cổ tử cung, biểu mô tuyến nội mạc tử cung, biểu mô tuyến ngoài tử cung, không rõ nguồn gốc."]}, {"heading": "1.5. Soi cổ tử cung", "paragraphs": ["Hình 5. Máy soi cổ tử cung"], "bullets": ["- Không chuẩn bị hoặc có chuẩn bị với dung dịch axít axetic 3% và dung dịch Lugol 3% - 5%.", "- Soi cổ tử cung cho phép xác định:", "+ Các thương tổn lành tính như: polyp, condyloma, lạc nội mạc tử cung...", "+ Các thương tổn không điển hình như: vết trắng, vết lát đá, vết chấm đáy, vùng đỏ bất thường.....", "+ Ung thư xâm nhiễm.", "+ Soi cổ tử cung để định hướng vùng sẽ sinh thiết."]}, {"heading": "1.6. Sinh thiết", "paragraphs": ["Chỉ định sinh thiết khi có các thương tổn nghi ngờ ở âm hộ, âm đạo, cổ tử cung như vùng loét trợt, vùng không bắt màu với iod, mảng trắng... hoặc các tổn thương có biểu hiện ác tính. Xét nghiệm này nên được thực hiện dưới hướng dẫn của soi cổ tử cung. Mẫu thử nên được lấy ở ranh giới giữa mô lành và mô bệnh, phải sinh thiết ở nhiều vị trí khác nhau.", "Hình 6. Soi và sinh thiết cổ tử cung"], "bullets": []}, {"heading": "2.1. Soi buồng tử cung", "paragraphs": ["Có thể soi buồng tử cung để chẩn đoán hoặc phẫu thuật", "Hình 7. Polyp buồng tử cung qua soi buồng tử cung", "Chỉ định soi buồng tử cung chẩn đoán", "Tìm nguyên nhân chảy máu bất thường của tử cung.", "Chẩn đoán dị dạng tử cung, dính BTC ở những bệnh nhân vô sinh.", "Nghi ngờ u xơ dưới niêm mạc TC, polyp BTC.", "Chẩn đoán nguyên nhân sẩy thai liên tiếp.", "Những bệnh nhân làm thụ tinh ống nghiệm thất bại nhiều lần.", "Chỉ định soi buồng tử cung phẫu thuật", "U xơ tử cung dưới nội mạc gây rong kinh, rong huyết hoặc vô sinh, u nằm hoàn toàn trong BTC hoặc đường kính lớn nhất của u nằm trong BTC, đường kính u xơ dưới 4 cm.", "Polyp buồng tử cung.", "Quá sản nội mạc tử cung: cắt bỏ niêm mạc tử cung khi điều trị nội khoa thất bại và tử cung không quá to.", "Vách ngăn tử cung gây ra sẩy thai liên tiếp, đẻ non, thai chết lưu.", "Dính buồng tử cung: tách dính bằng đèn soi hoặc cắt dính bằng dụng cụ phẫu thuật.", "Rong kinh mà điều trị nội khoa không kết quả."], "bullets": []}, {"heading": "2.2. Sinh thiết buồng tử cung", "paragraphs": ["Mục đích:", "Đánh giá sự tiếp nhận và ảnh hưởng của estrogen và progesteron lên niêm mạc tử cung: sự trưởng thành của noãn, chức năng của hoàng thể.", "Thăm dò các tổn thương thực thể của niêm mạc tử cung quá sản nội mạc, polyp nội mạc, rong kinh, rong huyết trong tiền mãn kinh,…", "Tuỳ thuộc vào chỉ định. Có thể sinh thiết niêm mạc tử cung bằng cách nạo niêm mạc, hút bằng bơm hút Karmann hoặc sinh thiết qua nội soi buồng tử cung."], "bullets": []}, {"heading": "2.3. Chụp tử cung - vòi tử cung có bơm thuốc cản quang", "paragraphs": ["Chỉ định để chẩn đoán nguyên nhân vô sinh như khảo sát hình dạng tử cung, dị dạng tử cung, dính buồng tử cung, tắc nghẽn vòi tử cung (ứ nước, lao...) hoặc các trường hợp nghi ngờ có tổn thương buồng tử cung như tìm polyp buồng tử cung, u xơ tử cung dưới niêm mạc, ung thư nội mạc tử cung.", "Hình 8. Phim chụp tử cung vòi tử cung có bơm thuốc cản quang", "Thuốc cản quang tan trong dầu hoặc tan trong nước thường được sử dụng để chụp tử cung - vòi tử cung. Thời điểm tốt nhất để chụp là sau sạch kinh và trước thời điểm phóng noãn.", "Nhận định kết quả: chụp tử cung vòi tử cung có bơm thuốc cản quang cho phép đánh giá hình dạng buồng tử cung, 2 vòi tử cung cũng như vị trí các tổn thương nếu có."], "bullets": []}, {"heading": "3. THĂM DÒ TUYẾN VÚ", "paragraphs": ["Hình 9. Phương pháp chụp X quang tuyến vú", "Hình 10. Hình ảnh siêu âm vú", "Hình 11. Sinh thiết lõi"], "bullets": ["- X quang vú (Mamography): phát hiện sớm các tổn thương ở vú. X quang  vú có giá trị chẩn đoán trong 80% các trường hợp ung thư vú.", "- Siêu âm: Có thể xác định bản chất một số khối u (hình ảnh âm vang trống của u nang, hình ảnh giới hạn rõ với echo giàu của u xơ tuyến vú). Hiện nay, siêu âm phân loại đánh giá, tiên lượng các tổn thương vú thường theo phân loại của BIRADS.", "- Chọc hút tế bào bằng kim nhỏ: khi chọc hút tế bào phải đánh giá màu sắc của dịch, nếu dịch lẫn máu phải nghĩ tới ung thư dạng nang. Kết quả xét nghiệm của chọc hút tế bào cho phép chẩn đoán chính xác tới  90% các trường hợp.", "- Sinh thiết lõi: Giúp chẩn đoán mô học chính xác trước khi có chỉ định mổ hoặc khi các thăm dò khác có kết quả nghi ngờ."]}, {"heading": "4.1. Thăm dò nội tiết", "paragraphs": ["Định lượng các hormon căn bản được thực hiện vào đầu chu kỳ kinh (từ ngày thứ nhất đến ngày thứ 4), mẫu máu để xét nghiệm phải lấy vào buổi sáng.", "Bảng 1. Nồng độ FSH, LH, Prolactin, Estrogen, Progesteron trong máu bình thường", "Giai đoạn trong chu kỳ", "Kết quả", "FSH", "Nang noãn sớm", "Đỉnh phóng noãn", "Giai đoạn hoàng thể", "Giai đoạn mãn kinh", "02 - 10mIU/ml", "10 - 23mIU/ml", "1,5 - 9mIU/ml", "30- 140mIU/ml", "LH", "Nang noãn sớm", "Đỉnh phóng noãn", "Giai đoạn hoàng thể", "Giai đoạn mãn kinh", "1,5 - 20mIU/ml", "17 - 80mIU/ml", "02 - 15mIU/ml", "20 - 90mIU/ml", "Prolactin (PRL)", "02 - 30ng/ml", "Estradiol (E2)", "Nang noãn", "Phóng noãn", "Giai đoạn hoàng thể", "Giai đoạn mãn kinh", "10 - 175pg/ml", "125 - 500pg/ml", "60 - 300pg/ml", "< 50pg/ml", "Progesteron", "Ngày 1 - 14 chu kỳ", "Ngày 15 - cuối vòng kinh", "0,2 - 1,2ng/ml", "2,5 - 25ng/ml", "Siêu âm tử cung- phần phụ", "Là một phương pháp phổ biến, đơn giản, rẻ tiền, không thể thiếu trong thăm dò phụ khoa, rất hữu ích để chẩn đoán và hướng dẫn cho một số thăm dò phụ khoa khác.", "Hình 12. Hình ảnh tử cung qua siêu âm đầu dò âm đạo", "Siêu âm qua đường âm đạo cho phép đánh giá kích thước tử cung, nội mạc tử cung, cơ tử cung, buồng trứng và vòi tử cung"], "bullets": []}, {"heading": "4.3. Nội soi ổ bụng", "paragraphs": ["Nội soi ổ bụng là một phẫu thuật phụ khoa có thể sử dụng để chẩn đoán và điều trị.", "Hình 13. Nội soi ổ bụng", "Khi tiến hành nội soi ổ bụng, cần mô tả chi tiết các kết quả quan sát được:", "Tử cung - sừng tử cung", "Vòi tử cung - loa vòi.", "Buồng trứng và tất cả các mặt của nó", "Túi cùng tử cung - trực tràng (túi cùng sau - túi cùng Douglas), dây chằng tử cung - cùng, ổ phúc mạc.", "Trắc nghiệm xanh Methylen.", "Chỉ định:"], "bullets": ["-  Toàn bộ ổ bụng và vùng chậu", "- Nội soi ổ bụng chẩn đoán trong chẩn đoán chửa ngoài tử cung, các bệnh lý viêm nhiễm vùng chậu, khảo sát các trường hợp vô sinh", "- Nội soi chỉ định điều trị rất rộng, bao gồm: Tắc vòi tử cung ở đoạn sừng tử cung, hình ảnh ứ nước vòi tử cung qua phim chụp X quang, xử trí chửa ngoài tử cung, xử trí lạc nội mạc tử cung, buồng trứng đa nang bóc u xơ tử cung, triệt sản, cắt tử cung, treo tạng sa sinh dục,…"]}, {"heading": "Câu hỏi:", "paragraphs": ["Nêu các phương pháp thăm dò âm đạo và chất nhầy cổ tử cung ?", "Trình bày xét nghiệm tế bào âm đạo cổ tử cung và đánh giá theo Bethesda 2001?", "Trình bày mục đích soi cổ tử cung?", "Liệt kê các phương pháp thăm dò buồng tử cung?", "Trình bày các phương pháp thăm dò vú?", "Trình bày các chỉ định nội soi ổ bụng?"], "bullets": []}], "raw_text": "THĂM DÒ TRONG PHỤ KHOA.Lê Hải Dương K II.Lê Hả\nThs. BMục tiêu học tập\nNêu được các phương pháp thăm dò âm đạo và chất nhầy cổ tử cung.\nTrình bày được cách thực hiện tế bào âm đạo cổ tử cung và đánh giá theo Bethesda 2001.\nTrình bày được ý nghĩa của soi cổ tử cung.\nLiệt kê được các phương pháp thăm dò buồng tử cung.\nTrình bày được các phương pháp thăm dò vú.\nTrình bày được các chỉ định nội soi ổ bụng.\n1. THĂM DÒ Ở CƠ QUAN SINH DỤC THẤP\n1.1. Đo pH âm đạo\n- Trong điều kiện bình thường, dịch âm đạo là một chất màu trắng, hơi sệt như bột. Các trực khuẩn Doderlein có mặt trong âm đạo sử dụng glycogen từ các tế bào âm đạo bị bong tróc tạo ra acid latic, vì vậy môi trường âm đạo có pH acid. Nồng độ estrogen càng cao thì âm đạo càng nhiều glycogen.\n- pH âm đạo xung quanh ngày phóng noãn là 4,2, trước và sau hành kinh pH từ 4,8 đến 5,2, trong những ngày hành kinh âm đạo có pH là 5,4. Ở phụ nữ có kinh nguyệt bình thường nếu pH trên 5,5 phải nghĩ tới viêm âm đạo (có thể do Trichomonas).\n- Thường sử dụng giấy quỳ để đo pH âm đạo.\n1.2. Xét nghiệm độ sạch âm đạo:\n- Bình thường trong dịch âm đạo bao gồm các tế bào biểu mô âm đạo đã bong, trực khuẩn Doderlein, một số tạp khuẩn và bạch cầu. Việc xét nghiệm âm đạo giúp tìm ra nguyên nhân gây viêm âm đạo để điều trị.\n- Kỹ thuật: Để xét nghiệm độ sạch âm đạo người bệnh không thụt rửa âm đạo, không khám phụ khoa trước khi lấy phiến đồ âm đạo. Cách làm: lấy dịch ở túi cùng sau âm đạo, phết lên phiến kính, cố định bằng hỗn hợp cồn 90o + ête (tỷ lệ cồn 50%, ête 50%)\n\n\nHình 1. Trực khuẩn Doderlein\nKẾT QUẢ: chia độ sạch âm đạo thành 4 độ như sau\n- Độ 1:\n+ Trực khuẩn Doderlein: nhiều\n+ Tế bào biểu mô âm đạo: nhiều\n+ Các vi khuẩn khác: không có, không có nấm và Trichomonas\n+ Bạch cầu: không có\n- Độ 2:\n+ Trực khuẩn Doderlein: nhiều\n+ Tế bào biểu mô âm đạo: nhiều\n+ Các vi khuẩn khác: có ít, không có nấm và Trichomonas\n+ Bạch cầu: có ít\n- Độ 3:\n+ Trực khuẩn Doderlein: giảm\n+ Tế bào biểu mô âm đạo: rất ít\n+ Các vi khuẩn khác: rất nhiều, có nấm hoặc Trichomonas\n+ Bạch cầu: rất nhiều hay (+++)\n- Độ 4:\n+ Trực khuẩn Doderlein: không còn\n+ Tế bào biểu mô âm đạo: rất ít\n+ Các vi khuẩn khác: rất nhiều, có nấm hoặc Trichomonas\n+ Bạch cầu: rất nhiều hay (+++)\nNhư vậy độ 3 và độ 4 cho biết mức độ viêm và thiểu năng Estrogen của âm đạo vừa hay nặng, phụ thuộc vào số lượng trực khuẩn Doderlein nhiều hay ít.\n1.3. Thăm dò chất nhầy cổ tử cung\nBình thường xung quanh ngày phóng noãn, lỗ cổ tử cung hé mở rồi mở cực đại vào ngày phóng noãn, chất nhầy trong, loãng và kéo dài thành sợi dài. Chất nhầy thường được đánh giá vào giai đoạn trước phóng noãn (từ ngày 12-14 của chu kỳ 28 ngày) giữa 2 phần đầu của 1 kẹp (pince) dài. Người ta quan sát số lượng, độ kéo sợi, độ trong và độ đục của chất nhầy.\n+ Nhiễm trùng khi chất nhầy đục, soi dưới kính hiển vi thấy nhiều bạch cầu.\n+ Dưới tác dụng của estrogen, chất nhầy nhiều và kéo sợi; Dưới tác dụng của progesteron thì chất nhầy đặc và vón lại.\n1.4. Xét nghiệm tế bào âm đạo cổ tử cung\n- Là một thăm dò thường quy được tiến hành có hệ thống và định kỳ cho mọi phụ nữ nhằm chẩn đoán sớm ung thư cổ tử cung. Xét nghiệm giúp phát hiện các biến đổi ở mức độ tế bào theo hướng tiền ung thư hoặc ung thư.\n- Tối thiểu 24 giờ trước khi lấy bệnh phẩm, bệnh nhân không khám phụ khoa, không thụt rửa âm đạo, không giao hợp, không đặt thuốc âm đạo trước đó 3 ngày và lấy ngoài thời kỳ kinh nguyệt.\n- Có 2 phương pháp lấy bệnh phẩm làm xét nghiệm tế bào âm đạo cổ tử cung\nPhương pháp tế bào học cổ điển\n- Kỹ thuật lấy bệnh phẩm: sử dụng que bẹt gỗ 2 đầu và phải lấy được vùng chuyển tiếp vẩy - trụ. Dàn 2 đầu que trên lam kính đảm bảo dàn mỏng, đều, đủ bệnh phẩm.\n\nHình 2. Dụng cụ lấy tế bào âm đạo cổ tử cung cổ điển\n\nHình 3. Cách phết bệnh phẩm từ thìa và bàn chải lên lam kính\nA. Bệnh phẩm từ ống cổ tử cung, B. Bệnh phẩm từ lổ ngoài cổ tử cung\nPhương pháp tế bào học nhúng dịch\n\nHình 4. Phương pháp tế bào học nhúng dịch\n-  Kỹ thuật lấy bệnh phẩm: Dùng dụng cụ phết chuyên biệt được cung cấp bởi nhà sản xuất (thường là chổi) để phết lên cổ tử cung, sau đó khuấy dụng cụ phết vào trong hộp chứa dung dịch bảo quản để chuyển bệnh phẩm tế bào vào dung dịch bảo quản. Hệ thống máy sẽ xử lý bệnh phẩm loại bỏ hồng cầu, bạch cầu, các thành phần không có giá trị chẩn đoán rồi chuyển lên lam kính.\nĐánh giá kết quả: tiêu bản được nhuộm theo phương pháp Papanicolaou và xếp loại theo danh pháp Bethesda 2001 bao gồm:\nBình thường: không có các tế bào bị biến đổi hình dạng hoặc thay đổi tế bào phản ứng lành tính\nCác bất thường tế bào biểu mô vẩy:\n+ Tế bào biểu mô vẩy không điển hình có ý nghĩa chưa xác định (ASC-US)\n+ Tế bào biểu mô vẩy không điển hình không loại trừ tổn thương nội biểu mô vảy mức độ cao ( ASC – H)\n+ Tổn thương nội biểu mô vẩy mức độ thấp (LSIL) bao gồm: tổn thương do nhiễm HPV, loạn sản nhẹ/CIN 1.\n+ Tổn thương nội biểu mô vẩy mức độ cao (HSIL) bao gồm: loạn sản trung bình và nặng, ung thư tại chỗ và những tổn thương nghi ngờ ung thư xâm lấn.\n+ Ung thư biểu mô vảy.\nCác thay đổi tế bào biểu mô trụ:\n+ Tế bào biểu mô tuyến không điển hình (AGUS)\n+ Ung thư tế bào biểu mô tuyến cổ tử cung tại chỗ (AIS)\n+ Ung thư biểu mô tuyến xâm nhập: biểu mô tuyến ống cổ tử cung, biểu mô tuyến nội mạc tử cung, biểu mô tuyến ngoài tử cung, không rõ nguồn gốc.\nCác tổn thương tân sinh ác tính khác\n1.5. Soi cổ tử cung\n- Không chuẩn bị hoặc có chuẩn bị với dung dịch axít axetic 3% và dung dịch Lugol 3% - 5%.\n- Soi cổ tử cung cho phép xác định:\n+ Các thương tổn lành tính như: polyp, condyloma, lạc nội mạc tử cung...\n+ Các thương tổn không điển hình như: vết trắng, vết lát đá, vết chấm đáy, vùng đỏ bất thường.....\n+ Ung thư xâm nhiễm.\n+ Soi cổ tử cung để định hướng vùng sẽ sinh thiết.\n\nHình 5. Máy soi cổ tử cung\n1.6. Sinh thiết\nChỉ định sinh thiết khi có các thương tổn nghi ngờ ở âm hộ, âm đạo, cổ tử cung như vùng loét trợt, vùng không bắt màu với iod, mảng trắng... hoặc các tổn thương có biểu hiện ác tính. Xét nghiệm này nên được thực hiện dưới hướng dẫn của soi cổ tử cung. Mẫu thử nên được lấy ở ranh giới giữa mô lành và mô bệnh, phải sinh thiết ở nhiều vị trí khác nhau.\n\nHình 6. Soi và sinh thiết cổ tử cung\n2. THĂM DÒ BUỒNG TỬ CUNG\n2.1. Soi buồng tử cung\nCó thể soi buồng tử cung để chẩn đoán hoặc phẫu thuật\n\nHình 7. Polyp buồng tử cung qua soi buồng tử cung\nChỉ định soi buồng tử cung chẩn đoán\nTìm nguyên nhân chảy máu bất thường của tử cung.\nChẩn đoán dị dạng tử cung, dính BTC ở những bệnh nhân vô sinh.\nNghi ngờ u xơ dưới niêm mạc TC, polyp BTC.\nChẩn đoán nguyên nhân sẩy thai liên tiếp.\nNhững bệnh nhân làm thụ tinh ống nghiệm thất bại nhiều lần.\nChỉ định soi buồng tử cung phẫu thuật\nU xơ tử cung dưới nội mạc gây rong kinh, rong huyết hoặc vô sinh, u nằm hoàn toàn trong BTC hoặc đường kính lớn nhất của u nằm trong BTC, đường kính u xơ dưới 4 cm.\nPolyp buồng tử cung.\nQuá sản nội mạc tử cung: cắt bỏ niêm mạc tử cung khi điều trị nội khoa thất bại và tử cung không quá to.\nVách ngăn tử cung gây ra sẩy thai liên tiếp, đẻ non, thai chết lưu.\nDính buồng tử cung: tách dính bằng đèn soi hoặc cắt dính bằng dụng cụ phẫu thuật.\nRong kinh mà điều trị nội khoa không kết quả.\n2.2. Sinh thiết buồng tử cung\nMục đích:\nĐánh giá sự tiếp nhận và ảnh hưởng của estrogen và progesteron lên niêm mạc tử cung: sự trưởng thành của noãn, chức năng của hoàng thể.\nThăm dò các tổn thương thực thể của niêm mạc tử cung quá sản nội mạc, polyp nội mạc, rong kinh, rong huyết trong tiền mãn kinh,…\nTuỳ thuộc vào chỉ định. Có thể sinh thiết niêm mạc tử cung bằng cách nạo niêm mạc, hút bằng bơm hút Karmann hoặc sinh thiết qua nội soi buồng tử cung.\n2.3. Chụp tử cung - vòi tử cung có bơm thuốc cản quang\nChỉ định để chẩn đoán nguyên nhân vô sinh như khảo sát hình dạng tử cung, dị dạng tử cung, dính buồng tử cung, tắc nghẽn vòi tử cung (ứ nước, lao...) hoặc các trường hợp nghi ngờ có tổn thương buồng tử cung như tìm polyp buồng tử cung, u xơ tử cung dưới niêm mạc, ung thư nội mạc tử cung.\n\nHình 8. Phim chụp tử cung vòi tử cung có bơm thuốc cản quang\nThuốc cản quang tan trong dầu hoặc tan trong nước thường được sử dụng để chụp tử cung - vòi tử cung. Thời điểm tốt nhất để chụp là sau sạch kinh và trước thời điểm phóng noãn.\nNhận định kết quả: chụp tử cung vòi tử cung có bơm thuốc cản quang cho phép đánh giá hình dạng buồng tử cung, 2 vòi tử cung cũng như vị trí các tổn thương nếu có.\n3. THĂM DÒ TUYẾN VÚ\n- X quang vú (Mamography): phát hiện sớm các tổn thương ở vú. X quang  vú có giá trị chẩn đoán trong 80% các trường hợp ung thư vú.\n\n\nHình 9. Phương pháp chụp X quang tuyến vú\n- Siêu âm: Có thể xác định bản chất một số khối u (hình ảnh âm vang trống của u nang, hình ảnh giới hạn rõ với echo giàu của u xơ tuyến vú). Hiện nay, siêu âm phân loại đánh giá, tiên lượng các tổn thương vú thường theo phân loại của BIRADS.\n\nHình 10. Hình ảnh siêu âm vú\n- Chọc hút tế bào bằng kim nhỏ: khi chọc hút tế bào phải đánh giá màu sắc của dịch, nếu dịch lẫn máu phải nghĩ tới ung thư dạng nang. Kết quả xét nghiệm của chọc hút tế bào cho phép chẩn đoán chính xác tới  90% các trường hợp.\n- Sinh thiết lõi: Giúp chẩn đoán mô học chính xác trước khi có chỉ định mổ hoặc khi các thăm dò khác có kết quả nghi ngờ.\n\nHình 11. Sinh thiết lõi\n4. CÁC THĂM DÒ KHÁC\n4.1. Thăm dò nội tiết\nĐịnh lượng các hormon căn bản được thực hiện vào đầu chu kỳ kinh (từ ngày thứ nhất đến ngày thứ 4), mẫu máu để xét nghiệm phải lấy vào buổi sáng.\nBảng 1. Nồng độ FSH, LH, Prolactin, Estrogen, Progesteron trong máu bình thường\n\nGiai đoạn trong chu kỳ\nKết quả\n\nFSH\nNang noãn sớm\nĐỉnh phóng noãn\nGiai đoạn hoàng thể\nGiai đoạn mãn kinh\n02 - 10mIU/ml\n10 - 23mIU/ml\n1,5 - 9mIU/ml\n30- 140mIU/ml\n\nLH\nNang noãn sớm\nĐỉnh phóng noãn\nGiai đoạn hoàng thể\nGiai đoạn mãn kinh\n1,5 - 20mIU/ml\n17 - 80mIU/ml\n02 - 15mIU/ml\n20 - 90mIU/ml\n\nProlactin (PRL)\n\n02 - 30ng/ml\n\nEstradiol (E2)\nNang noãn\nPhóng noãn\nGiai đoạn hoàng thể\nGiai đoạn mãn kinh\n10 - 175pg/ml\n125 - 500pg/ml\n60 - 300pg/ml\n< 50pg/ml\n\nProgesteron\nNgày 1 - 14 chu kỳ\nNgày 15 - cuối vòng kinh\n0,2 - 1,2ng/ml\n2,5 - 25ng/ml\n\nSiêu âm tử cung- phần phụ\nLà một phương pháp phổ biến, đơn giản, rẻ tiền, không thể thiếu trong thăm dò phụ khoa, rất hữu ích để chẩn đoán và hướng dẫn cho một số thăm dò phụ khoa khác.\n\nHình 12. Hình ảnh tử cung qua siêu âm đầu dò âm đạo\nSiêu âm qua đường âm đạo cho phép đánh giá kích thước tử cung, nội mạc tử cung, cơ tử cung, buồng trứng và vòi tử cung\n4.3. Nội soi ổ bụng\nNội soi ổ bụng là một phẫu thuật phụ khoa có thể sử dụng để chẩn đoán và điều trị.\n\nHình 13. Nội soi ổ bụng\nKhi tiến hành nội soi ổ bụng, cần mô tả chi tiết các kết quả quan sát được:\n-  Toàn bộ ổ bụng và vùng chậu\nTử cung - sừng tử cung\nVòi tử cung - loa vòi.\nBuồng trứng và tất cả các mặt của nó\nTúi cùng tử cung - trực tràng (túi cùng sau - túi cùng Douglas), dây chằng tử cung - cùng, ổ phúc mạc.\nTrắc nghiệm xanh Methylen.\nChỉ định:\n- Nội soi ổ bụng chẩn đoán trong chẩn đoán chửa ngoài tử cung, các bệnh lý viêm nhiễm vùng chậu, khảo sát các trường hợp vô sinh\n- Nội soi chỉ định điều trị rất rộng, bao gồm: Tắc vòi tử cung ở đoạn sừng tử cung, hình ảnh ứ nước vòi tử cung qua phim chụp X quang, xử trí chửa ngoài tử cung, xử trí lạc nội mạc tử cung, buồng trứng đa nang bóc u xơ tử cung, triệt sản, cắt tử cung, treo tạng sa sinh dục,…\nCâu hỏi:\nNêu các phương pháp thăm dò âm đạo và chất nhầy cổ tử cung ?\nTrình bày xét nghiệm tế bào âm đạo cổ tử cung và đánh giá theo Bethesda 2001?\nTrình bày mục đích soi cổ tử cung?\nLiệt kê các phương pháp thăm dò buồng tử cung?\nTrình bày các phương pháp thăm dò vú?\nTrình bày các chỉ định nội soi ổ bụng?", "priority": "Trung bình"}, {"id": "SK-39", "chapter": "Chương 3. Phụ khoa", "folder": "03_Phu_khoa", "title": "Tổn thương lành tính cổ tử cung", "author": "Ths. Đinh Văn Hoành", "word_count": 1825, "line_count": 96, "key_numbers": ["5 ngày"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["TỔN THƯƠNG LÀNH TÍNH CỔ TỬ CUNG", "Ths. Đinh Văn Hoành"], "bullets": []}, {"heading": "1. ĐẠI CƯƠNG", "paragraphs": ["Các tổn thương cổ tử cung rất hay gặp, chủ yếu là các tổn thương lành tính, trước đây thường gọi chung là viêm loét cổ tử cung. Ngày nay qua việc dùng máy soi cổ tử cung, ta phân biệt được nhiều loại tổn thương. Tuy các tổn thương lành tính này không phải là ung thư song cần phải điều trị vì:", "Hình 1. Cổ tử cung bình thường"], "bullets": ["- Diễn biến có thể kéo dài, gây lo lắng, ảnh hưởng đến sinh hoạt của bệnh nhân.", "- Có thể gây viêm nhiễm đường sinh dục trên và vô sinh.", "- Có thể tiến triển thành ung thư nếu không được điều trị."]}, {"heading": "2.1. Hình dạng", "paragraphs": ["Cổ tử cung có thể thay đổi hình thể tuỳ thuộc người phụ nữ đã sinh đẻ hay chưa. Ở người chưa đẻ cổ tử cung thường tròn, ở người con rạ lỗ cổ tử cung có thể sẽ bè ra theo chiều ngang."], "bullets": []}, {"heading": "2.2. Tổ chức học và biến đổi", "paragraphs": ["Phía ngoài cổ tử cung được bao phủ bởi lớp biểu mô lát tầng (các tế bào gai). Phía trong lỗ cổ tử cung được che phủ bởi lớp biểu mô tuyến (biểu mô trụ đơn). Vùng chuyển tiếp ở lỗ ngoài cổ tử cung là ranh giới giữa biểu mô lát và biểu mô trụ."], "bullets": ["- Khi mang thai cổ tử cung hé mở thấy được một phần biểu mô tuyến của ống tử cung.", "- Sau mãn kinh lớp tế bào biểu mô ở bề ngoài nhạt màu hơn, ranh giới tổ chức học không thấy rõ rệt vì tụt vào sâu trong ống cổ tử cung."]}, {"heading": "2.3. Sinh lý cổ tử cung", "paragraphs": ["Biểu mô tuyến ở cổ tử cung gồm có hai loại tế bào:", "Hai loại tế bào này chịu ảnh hưởng của estrogen là chính, chúng tạo ra dịch nhầy có pH 7-7,5, tính chất của dịch nhầy vì thế cũng thay đổi theo chu kỳ kinh:"], "bullets": ["- Tế bào tiết nhầy: Bên trong tế bào chứa chất nhầy. Nhân của tế bào bị đẩy xuống cực dưới.", "- Tế bào có nhung mao: Chất nhầy chế tiết ra được đẩy vào âm đạo nhờ tác dụng của các nhung mao.", "+ Trong nửa đầu kỳ kinh (trước khi rụng trứng) chất nhầy ở cổ tử cung trong, nhầy và nhiều nhất vào trước ngày rụng trứng.", "+ Trong nửa sau kỳ kinh(sau rụng trứng) dịch cổ tử cung dần đặc lại do ảnh hưởng của progesteron."]}, {"heading": "2.4. Sự tái tạo", "paragraphs": ["Lộ tuyến cổ tử cung cũng có thể là tình trạng sinh lý ở cổ tử cung, lúc này biểu mô tuyến bò ra che phủ một phần cổ tử cung, tạo nên hình ảnh không nhẵn, đỏ và có ít dịch nhầy che phủ. Lộ tuyến thường gặp ở phụ nữ trong độ tuổi sinh đẻ hoặc đang dùng các thuốc tránh thai có estrogen. Lộ tuyến thường do sự thay đổi của pH âm đạo hoặc do cường estrogen. Do vậy, nếu điều chỉnh được các thay đổi này lộ tuyến cũng sẽ mất dần.", "Hình 2. Nang Naboth và lộ tuyến cổ tử cung"], "bullets": ["- Khi có sự tái tạo, lớp biểu mô lát ở vùng lộ tuyến bò vào trong, che phủ lớp biểu mô trụ hoặc lớp biểu mô trụ dị sản (chuyển sản). Dù với hoàn cảnh nào quá trình tái tạo cũng không thể hoàn thiện, có thể sẽ tồn tại các đám lộ tuyến hoặc các nang Naboth."]}, {"heading": "3.1.1. Viêm cổ tử cung", "paragraphs": ["Nguyên nhân gây viêm thường do các vi khuẩn có mặt trong âm đạo, lậu cầu khuẩn, Chlamydia… Cổ tử cung đỏ rực, khí hư đục, nhầy, đôi khi như mủ, hôi. Vùng viêm nhiễm có thể bị giả mạc che phủ, chạm vào dễ chảy máu.", "Hình 3. Viêm cổ tử cung do Chlamydia", "với lộ tuyến, khí hư và dễ chảy máu"], "bullets": []}, {"heading": "3.1.2. Viêm ống cổ tử cung", "paragraphs": ["Chủ yếu sẽ thấy có dịch nhầy đục ở ống hoặc khí hư bẩn và đục nếu ép mỏ vịt vào cổ tử cung."], "bullets": []}, {"heading": "3.1.3. Lộ tuyến cổ tử cung", "paragraphs": ["Vùng lộ tuyến cổ tử cung khi bị nhiễm khuẩn đỏ rực, dễ chảy máu. Khám âm đạo có thể gây đau cho bệnh nhân. Vùng lộ tuyến khi bôi Lugol không bắt màu iode"], "bullets": []}, {"heading": "3.1.4. Điều trị", "paragraphs": ["Quá trình điều trị lộ tuyến có thể để lại các di chứng lành tính, hoặc lộ tuyến có thể tái phát. Các di chứng lành tính đó là:", "Đối với các di chứng lành tính, nếu ít thì chỉ cần chống viêm để biểu mô lát tự phục hồi."], "bullets": ["- Điều trị các tổn thương không đặc hiệu: các tổn thương không đặc hiệu ở cổ tử cung thường chỉ cần điều trị tại chỗ tuỳ theo nguyên nhân (các thuốc kháng sinh, kháng nấm hoặc chống đơn bào). Khi có viêm lỗ trong cổ tử cung phải điều trị kháng sinh toàn thân.", "- Điều trị lộ tuyến: Nếu lộ tuyến cổ tử cung không kèm theo viêm thì lộ tuyến có thể tự khỏi. Trong các trường hợp lộ tuyến rộng kèm theo viêm, tái phát thì điều trị chống viêm bằng thuốc đặc hiệu, sau đó có thể đốt lộ tuyến (bằng nhiệt, hoá chất, đốt điện hay đốt lạnh) để diệt biểu mô trụ, giúp biểu mô lát phục hồi. Thời điểm để đốt lộ tuyến thường sau sạch kinh 3-5 ngày. Không được đốt lộ tuyến khi đang có thai, khi đang viêm âm đạo cấp tính hoặc có tổn thương nghi ngờ.", "+ Nang Naboth là do biểu mô lát mọc che phủ qua miệng tuyến chưa bị diệt, chất nhầy tiếp tục chế tiết ra ngày càng nhiều sẽ phồng lên thành nang, khi nang vỡ sẽ để lại lỗ nang.", "+ Cửa tuyến: giữa vùng biểu mô lát còn lại các miệng tuyến tiếp tục tiết nhầy.", "+ Đảo tuyến: tụ tập một số tuyến còn lại trong biểu mô lát mới hồi phục."]}, {"heading": "3.2.2. Săng giang mai", "paragraphs": ["Săng (chancre) giang mai có thể có ở cổ tử cung, tổn thương là ổ loét cứng, bờ rõ, dễ chảy máu, thường kèm với hạch.", "Xét nghiệm trực tiếp bệnh phẩm có xoắn khuẩn giang mai (T. palidum).", "Hình 4. Xoắn khuẩn Treponema pallidum"], "bullets": []}, {"heading": "3.3.1. Polyp cổ tử cung", "paragraphs": ["Hình 5. Polyp cổ tử cung"], "bullets": ["- Polyp lỗ trong cổ tử cung còn gọi là polyp niêm mạc, polyp thường có cuống nhỏ, tổ chức mềm. Dễ chảy máu sau giao hợp.", "- Polyp lỗ ngoài thường nằm ở ống cổ tử cung là một polyp xơ, màu hồng đậm, có thể làm biến dạng cổ tử cung.", "- Đối với các polyp cuống nhỏ có thể xoắn bằng kẹp."]}, {"heading": "3.3.2. Lạc nội mạc tử cung ở cổ tử cung", "paragraphs": ["Do tế bào nội mạc tử cung lạc chỗ. Lạc nội mạc tử cung ở cổ tử cung có thể thấy rõ sau sạch kinh dưới dạng nốt xanh hoặc đen rải rác trên cổ tử cung. Các nốt này to lên và rõ hơn khi có kinh.", "Hình 6. Lạc nội mạc tử cung ở cổ tử cung"], "bullets": []}, {"heading": "4.1. Lâm sàng: Cổ tử cung có thể nhìn thấy và sờ được khi thăm khám.", "paragraphs": [], "bullets": ["- Khám bằng mỏ vịt: Quan sát được các tổn thương như viêm, polyp cổ tử cung, viêm lỗ trong cổ tử cung. Ngoài ra ta còn có thể lấy bệnh phẩm để nhuộm Gram, cấy, làm phiến đồ âm đạo, phết mỏng cổ tử cung để tầm soát ung thư.", "- Khám âm đạo: Sờ được cổ tử cung, đánh giá độ lớn của cổ tử cung, mật độ cổ tử cung và phát hiện đau khi lay cổ tử cung."]}, {"heading": "4.2. Cận lâm sàng: để phát hiện, xác định các tổn thương lành tính ở cổ tử cung nên làm các xét nghiệm sau", "paragraphs": ["Hình 7. Khoét chóp cổ tử cung"], "bullets": ["- Phiến đồ âm đạo - cổ tử cung", "- Sinh thiết trực tiếp.", "- Soi cổ tử cung: Giúp đánh giá cấu trúc lành tính của bề mặt cổ tử cung, vùng chuyển tiếp, loạn dưỡng, polyp, lộ tuyến cổ tử cung. Sau khi bôi axit acetic có thể phát hiện các tổn thương không điển hình: loạn sản (nghịch sản), tổn thương tiền ung thư hoặc ung thư, giúp sinh thiết đúng chỗ tổn thương.", "- Khoét chóp: Cũng được coi là một sinh thiết lớn lấy được cổ ngoài và vùng chuyển tiếp, như vậy sẽ lấy được tổn thương ở những vùng mà soi cổ tử cung không thấy."]}, {"heading": "5. DỰ PHÒNG", "paragraphs": ["Các tổn thương lành tính ở cổ tử cung ảnh hưởng nhiều đến sức khoẻ sinh sản của người phụ nữ, nên phòng bệnh có một vai trò quan trọng:"], "bullets": ["- Giải thích cho người phụ nữ hiểu các tổn thương lành tính cổ tử cung dễ khám, dễ phát hiện điều trị đơn giản, có hiệu quả, tạo cho họ có ý thức khám phụ khoa định kỳ khoảng mỗi năm một lần để phát hiện sớm các tổn thương, có kế hoạch điều trị, theo dõi.", "- Tổn thương lành tính cổ tử cung thường do nhiễm trùng, sinh đẻ nhiều gây ra vì vậy cần giải thích tầm quan trọng của vệ sinh kinh nguyệt, vệ sinh cá nhân, vệ sinh giao hợp.", "- Xây dựng ý thức vô khuẩn và khử khuẩn cho nhân viên y tế khi làm các thủ thuật.", "- Khi có tổn thương ở cổ tử cung dù là lành tính cũng nên điều trị dứt điểm, không để xảy ra các tái tạo bất thường."]}], "raw_text": "TỔN THƯƠNG LÀNH TÍNH CỔ TỬ CUNG\nThs. Đinh Văn Hoành\nMục tiêu học tập\n1. Mô tả được cấu trúc giải phẫu và tổ chức học, sinh lý cổ tử cung.\n2. Mô tả được các dấu hiệu lâm sàng của các tổn thương lành tính ở cổ tử cung.\n3. Trình bày hướng điều trị các tổn thương lành tính cổ tử cung.\n\n1. ĐẠI CƯƠNG\nCác tổn thương cổ tử cung rất hay gặp, chủ yếu là các tổn thương lành tính, trước đây thường gọi chung là viêm loét cổ tử cung. Ngày nay qua việc dùng máy soi cổ tử cung, ta phân biệt được nhiều loại tổn thương. Tuy các tổn thương lành tính này không phải là ung thư song cần phải điều trị vì:\n- Diễn biến có thể kéo dài, gây lo lắng, ảnh hưởng đến sinh hoạt của bệnh nhân.\n- Có thể gây viêm nhiễm đường sinh dục trên và vô sinh.\n- Có thể tiến triển thành ung thư nếu không được điều trị.\n\nHình 1. Cổ tử cung bình thường\n2. CỔ TỬ CUNG BÌNH THƯỜNG\n2.1. Hình dạng\nCổ tử cung có thể thay đổi hình thể tuỳ thuộc người phụ nữ đã sinh đẻ hay chưa. Ở người chưa đẻ cổ tử cung thường tròn, ở người con rạ lỗ cổ tử cung có thể sẽ bè ra theo chiều ngang.\n2.2. Tổ chức học và biến đổi\nPhía ngoài cổ tử cung được bao phủ bởi lớp biểu mô lát tầng (các tế bào gai). Phía trong lỗ cổ tử cung được che phủ bởi lớp biểu mô tuyến (biểu mô trụ đơn). Vùng chuyển tiếp ở lỗ ngoài cổ tử cung là ranh giới giữa biểu mô lát và biểu mô trụ.\n- Khi mang thai cổ tử cung hé mở thấy được một phần biểu mô tuyến của ống tử cung.\n- Sau mãn kinh lớp tế bào biểu mô ở bề ngoài nhạt màu hơn, ranh giới tổ chức học không thấy rõ rệt vì tụt vào sâu trong ống cổ tử cung.\n2.3. Sinh lý cổ tử cung\nBiểu mô tuyến ở cổ tử cung gồm có hai loại tế bào:\n- Tế bào tiết nhầy: Bên trong tế bào chứa chất nhầy. Nhân của tế bào bị đẩy xuống cực dưới.\n- Tế bào có nhung mao: Chất nhầy chế tiết ra được đẩy vào âm đạo nhờ tác dụng của các nhung mao.\nHai loại tế bào này chịu ảnh hưởng của estrogen là chính, chúng tạo ra dịch nhầy có pH 7-7,5, tính chất của dịch nhầy vì thế cũng thay đổi theo chu kỳ kinh:\n+ Trong nửa đầu kỳ kinh (trước khi rụng trứng) chất nhầy ở cổ tử cung trong, nhầy và nhiều nhất vào trước ngày rụng trứng.\n+ Trong nửa sau kỳ kinh(sau rụng trứng) dịch cổ tử cung dần đặc lại do ảnh hưởng của progesteron.\n2.4. Sự tái tạo\nLộ tuyến cổ tử cung cũng có thể là tình trạng sinh lý ở cổ tử cung, lúc này biểu mô tuyến bò ra che phủ một phần cổ tử cung, tạo nên hình ảnh không nhẵn, đỏ và có ít dịch nhầy che phủ. Lộ tuyến thường gặp ở phụ nữ trong độ tuổi sinh đẻ hoặc đang dùng các thuốc tránh thai có estrogen. Lộ tuyến thường do sự thay đổi của pH âm đạo hoặc do cường estrogen. Do vậy, nếu điều chỉnh được các thay đổi này lộ tuyến cũng sẽ mất dần.\n- Khi có sự tái tạo, lớp biểu mô lát ở vùng lộ tuyến bò vào trong, che phủ lớp biểu mô trụ hoặc lớp biểu mô trụ dị sản (chuyển sản). Dù với hoàn cảnh nào quá trình tái tạo cũng không thể hoàn thiện, có thể sẽ tồn tại các đám lộ tuyến hoặc các nang Naboth.\n\nHình 2. Nang Naboth và lộ tuyến cổ tử cung\n3. CÁC TỔN THƯƠNG LÀNH TÍNH Ở CỔ TỬ CUNG\n3.1. Các tổn thương không đặc hiệu\n3.1.1. Viêm cổ tử cung\nNguyên nhân gây viêm thường do các vi khuẩn có mặt trong âm đạo, lậu cầu khuẩn, Chlamydia… Cổ tử cung đỏ rực, khí hư đục, nhầy, đôi khi như mủ, hôi. Vùng viêm nhiễm có thể bị giả mạc che phủ, chạm vào dễ chảy máu.\n\n\n\n\n\n\nHình 3. Viêm cổ tử cung do Chlamydia\nvới lộ tuyến, khí hư và dễ chảy máu\n3.1.2. Viêm ống cổ tử cung\nChủ yếu sẽ thấy có dịch nhầy đục ở ống hoặc khí hư bẩn và đục nếu ép mỏ vịt vào cổ tử cung.\n3.1.3. Lộ tuyến cổ tử cung\nVùng lộ tuyến cổ tử cung khi bị nhiễm khuẩn đỏ rực, dễ chảy máu. Khám âm đạo có thể gây đau cho bệnh nhân. Vùng lộ tuyến khi bôi Lugol không bắt màu iode\n3.1.4. Điều trị\n- Điều trị các tổn thương không đặc hiệu: các tổn thương không đặc hiệu ở cổ tử cung thường chỉ cần điều trị tại chỗ tuỳ theo nguyên nhân (các thuốc kháng sinh, kháng nấm hoặc chống đơn bào). Khi có viêm lỗ trong cổ tử cung phải điều trị kháng sinh toàn thân.\n- Điều trị lộ tuyến: Nếu lộ tuyến cổ tử cung không kèm theo viêm thì lộ tuyến có thể tự khỏi. Trong các trường hợp lộ tuyến rộng kèm theo viêm, tái phát thì điều trị chống viêm bằng thuốc đặc hiệu, sau đó có thể đốt lộ tuyến (bằng nhiệt, hoá chất, đốt điện hay đốt lạnh) để diệt biểu mô trụ, giúp biểu mô lát phục hồi. Thời điểm để đốt lộ tuyến thường sau sạch kinh 3-5 ngày. Không được đốt lộ tuyến khi đang có thai, khi đang viêm âm đạo cấp tính hoặc có tổn thương nghi ngờ.\nQuá trình điều trị lộ tuyến có thể để lại các di chứng lành tính, hoặc lộ tuyến có thể tái phát. Các di chứng lành tính đó là:\n+ Nang Naboth là do biểu mô lát mọc che phủ qua miệng tuyến chưa bị diệt, chất nhầy tiếp tục chế tiết ra ngày càng nhiều sẽ phồng lên thành nang, khi nang vỡ sẽ để lại lỗ nang.\n+ Cửa tuyến: giữa vùng biểu mô lát còn lại các miệng tuyến tiếp tục tiết nhầy.\n+ Đảo tuyến: tụ tập một số tuyến còn lại trong biểu mô lát mới hồi phục.\nĐối với các di chứng lành tính, nếu ít thì chỉ cần chống viêm để biểu mô lát tự phục hồi.\n3.2. Các tổn thương viêm đặc hiệu\n3.2.1. Lao cổ tử cung: ít khi có lao cổ tử cung đơn thuần, nó có thể xảy ra khi có lao phần phụ và lao nội mạc tử cung. Tổn thương có dạng loét, sùi dễ chảy máu nên dễ nhầm với ung thư cổ tử cung. Sinh thiết sẽ thấy các nang lao và tế bào viêm đặc hiệu.\n3.2.2. Săng giang mai\nSăng (chancre) giang mai có thể có ở cổ tử cung, tổn thương là ổ loét cứng, bờ rõ, dễ chảy máu, thường kèm với hạch.\nXét nghiệm trực tiếp bệnh phẩm có xoắn khuẩn giang mai (T. palidum).\n\nHình 4. Xoắn khuẩn Treponema pallidum\n3.2.3. Điều trị: theo nguyên nhân\n3.3. Các tổn thương khác\n3.3.1. Polyp cổ tử cung\n- Polyp lỗ trong cổ tử cung còn gọi là polyp niêm mạc, polyp thường có cuống nhỏ, tổ chức mềm. Dễ chảy máu sau giao hợp.\n- Polyp lỗ ngoài thường nằm ở ống cổ tử cung là một polyp xơ, màu hồng đậm, có thể làm biến dạng cổ tử cung.\n- Đối với các polyp cuống nhỏ có thể xoắn bằng kẹp.\n\nHình 5. Polyp cổ tử cung\n3.3.2. Lạc nội mạc tử cung ở cổ tử cung\nDo tế bào nội mạc tử cung lạc chỗ. Lạc nội mạc tử cung ở cổ tử cung có thể thấy rõ sau sạch kinh dưới dạng nốt xanh hoặc đen rải rác trên cổ tử cung. Các nốt này to lên và rõ hơn khi có kinh.\n\nHình 6. Lạc nội mạc tử cung ở cổ tử cung\n\n4. KHÁM PHÁT HIỆN TỔN THƯƠNG LÀNH TÍNH Ở CỔ TỬ CUNG\n4.1. Lâm sàng: Cổ tử cung có thể nhìn thấy và sờ được khi thăm khám.\n- Khám bằng mỏ vịt: Quan sát được các tổn thương như viêm, polyp cổ tử cung, viêm lỗ trong cổ tử cung. Ngoài ra ta còn có thể lấy bệnh phẩm để nhuộm Gram, cấy, làm phiến đồ âm đạo, phết mỏng cổ tử cung để tầm soát ung thư.\n- Khám âm đạo: Sờ được cổ tử cung, đánh giá độ lớn của cổ tử cung, mật độ cổ tử cung và phát hiện đau khi lay cổ tử cung.\n4.2. Cận lâm sàng: để phát hiện, xác định các tổn thương lành tính ở cổ tử cung nên làm các xét nghiệm sau\n- Phiến đồ âm đạo - cổ tử cung\n- Sinh thiết trực tiếp.\n- Soi cổ tử cung: Giúp đánh giá cấu trúc lành tính của bề mặt cổ tử cung, vùng chuyển tiếp, loạn dưỡng, polyp, lộ tuyến cổ tử cung. Sau khi bôi axit acetic có thể phát hiện các tổn thương không điển hình: loạn sản (nghịch sản), tổn thương tiền ung thư hoặc ung thư, giúp sinh thiết đúng chỗ tổn thương.\n- Khoét chóp: Cũng được coi là một sinh thiết lớn lấy được cổ ngoài và vùng chuyển tiếp, như vậy sẽ lấy được tổn thương ở những vùng mà soi cổ tử cung không thấy.\n\nHình 7. Khoét chóp cổ tử cung\n5. DỰ PHÒNG\nCác tổn thương lành tính ở cổ tử cung ảnh hưởng nhiều đến sức khoẻ sinh sản của người phụ nữ, nên phòng bệnh có một vai trò quan trọng:\n- Giải thích cho người phụ nữ hiểu các tổn thương lành tính cổ tử cung dễ khám, dễ phát hiện điều trị đơn giản, có hiệu quả, tạo cho họ có ý thức khám phụ khoa định kỳ khoảng mỗi năm một lần để phát hiện sớm các tổn thương, có kế hoạch điều trị, theo dõi.\n- Tổn thương lành tính cổ tử cung thường do nhiễm trùng, sinh đẻ nhiều gây ra vì vậy cần giải thích tầm quan trọng của vệ sinh kinh nguyệt, vệ sinh cá nhân, vệ sinh giao hợp.\n- Xây dựng ý thức vô khuẩn và khử khuẩn cho nhân viên y tế khi làm các thủ thuật.\n- Khi có tổn thương ở cổ tử cung dù là lành tính cũng nên điều trị dứt điểm, không để xảy ra các tái tạo bất thường.\nCâu hỏi:\n1. Thình bày các tổn thương lành tính cổ tử cung?", "priority": "Trung bình"}, {"id": "SK-40", "chapter": "Chương 3. Phụ khoa", "folder": "03_Phu_khoa", "title": "Ung thư cổ tử cung", "author": "TS. Bùi Minh Tiến, TS. Phan Văn Cương", "word_count": 2902, "line_count": 220, "key_numbers": ["1 mg", "1000 mg", "25 mg", "2cm", "3 tuần", "3mm", "4 ngày", "40 mg", "4cm", "50 mg", "5mm", "6 tháng", "6 tuần", "75 mg", "7mm"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["UNG THƯ CỔ TỬ CUNG"], "bullets": []}, {"heading": "1. ĐẠI CƯƠNG VÀ CÁC YẾU TỐ NGUY CƠ", "paragraphs": ["CIN(cervical intraepithelian neoplasia): gọi là tiền ung thư hay khối u mới phát sinh trong biểu mô mức độ loạn sản khác nhau. Chẩn đoán và điều trị sớm loạn sản biểu mô cổ tử cung sẽ giảm được xâm lấn rất rõ ràng."], "bullets": ["- Ung thư cổ tử cung (UTCTC) là khối u ác tính đứng hàng thứ hai sau ung thư vú và cũng đứng thứ hai gây tử vong do ung thư ở nữ giới, thường xảy ra ở ranh giới giữa biểu mô lát tầng và biểu mô trụ của cổ tử cung.", "- Theo số liệu của Hiệp hội phòng chống ung thư thế giới thì UTCTC chiếm 12% các ung thư đường sinh dục nữ. Tại Viện ung bướu Hà Nội, ung thư cổ tử cung chiếm khoảng 6%. Nếu tính trên tổng số dân thì UTCTC chiếm từ 6,6 - 8,6/100.000 dân. Trong khi đó, tỷ lệ này tại thành phố Hồ Chí Minh là 35,6/100.000", "- Kết quả điều trị UTCTC phụ thuộc vào thời điểm chẩn đoán. Nếu chẩn đoán muộn việc điều trị gặp nhiều khó khăn và kết quả điều trị thấp.", "- Các yếu tố nguy cơ:", "+ Các sang chấn liên tục ở cổ tử cung: có thai và đẻ quá sớm (< 20 tuổi), rách CTC", "+ Lộ tuyến CTC có nguy cơ loạn sản nếu như điều trị không triệt để", "+ Nhiễm Human Papilloma virus (HPV, GPB thấy nhân nằm xuống cực dưới), Herpes virus, HIV.", "+ Tuổi: từ 40 -70.", "+ Hút thuốc lá", "+ Sinh nhiều: từ 5 con trở lên.", "+ Quan hệ tình dục sớm.", "+ Có nhiều bạn tình: người vợ của những người chồng có nhiều bạn tình chất tiết quy đầu có men hyaruluaronidaza (bựa) gây ung thư cổ tử cung..", "+ Vệ sinh cá nhân kém.", "+ Dùng corticoid kéo dài, hoá trị liệu...", "+ Thuốc ngừa thai dạng uống, yếu tố gia đình.", "+ Tiền sử viêm nhiễm đường sinh dục, nhiều lần", "+ Di truyền: mẹ truyền cho con gái nhiều gen dễ chịu tác động"]}, {"heading": "2.2. Ung thư xâm lấn: Tế bào ung thư phá huỷ lớp màng đáy và xâm lấn vào tổ chức đệm, trường hợp này ta gọi là ung thư xâm lấn. Có khoảng 95% các trường hợp là ung thư biểu mô lát và khoảng 5% dạng biểu mô trụ.", "paragraphs": ["Biểu đồ 1. Tiến triển của các thương tổn tiền ác tính và ung thư ở cổ tử cung", "Hình 1. Hình ảnh đại thể ung thư cổ tử cung ở cổ ngoài (trái) và ống cổ tử cung (phải)"], "bullets": []}, {"heading": "2.3.1. Tại chỗ", "paragraphs": [], "bullets": ["- Từ vùng chuyển tiếp ở bề mặt cổ tử cung - âm đạo lan xuống âm đạo, lan lên eo của tử cung,", "- Xâm lấn sâu về phía trước, đến vách bàng quang-âm đạo và bàng quang.", "-  Xâm lấn ra phía sau phên trực tràng - âm đạo và trực tràng.", "- Xâm lấn  ra hai bên đáy dây chằng rộng, niệu quản và vách chậu."]}, {"heading": "2.3.2. Theo đường bạch mạch", "paragraphs": ["Ung thư lan theo đường này đến chuỗi hạch chậu ngoài, chậu trong, cũng có khi ung thư lan tràn bất thường, chẳng hạn bỏ qua chuỗi hạch chậu hông tới ngay nhóm hạch động mạch chủ bụng “di căn theo kiểu kỵ sĩ “.", "Rất hiếm khi thấy ung thư di căn theo đường máu."], "bullets": []}, {"heading": "3.1. Các thương tổn tiền lâm sàng", "paragraphs": ["Ở giai đoạn sớm, các triệu chứng cơ năng thường nghèo nàn: ra khí hư vàng bẩn khác thường. Khi khám âm đạo - cổ tử cung bằng mỏ vịt có thể thấy cổ tử cung trông giống như bình thường hoặc có vết loét trợt, một vùng trắng không điển hình hoặc tăng sinh mạch máu."], "bullets": []}, {"heading": "3.2. Các thương tổn rõ trên lâm sàng", "paragraphs": ["Bệnh nhân thường đến khám với triệu chứng ra máu âm đạo bất thường giữa kỳ kinh, ra máu sau giao hợp, hoặc khí hư hôi, lẫn máu, có thể phối hợp với tình trạng cơ thể suy kiệt.", "Khám mỏ vịt hiện diện một khối sùi, dễ chảy máu khi chạm vào. Khi bôi Lugol vùng tổn thương không bắt màu (nghiệm pháp Schiller âm tính). Một số trường hợp muộn hơn cổ tử cung sẽ biến dạng, loét sâu hoặc cổ tử cung bị mất hẳn hình dạng. Sinh thiết được thực hiện ở cả vùng lành và vùng bệnh lý. Ngoài ra, cần phải đánh giá mức độ lan tràn và xâm lấn của ung thư vào các túi cùng âm đạo, nền dây chằng rộng, bàng quang, trực tràng và các vùng kế cận.", "Hình 2. Thương tổn cổ tử cung trên lâm sàng"], "bullets": []}, {"heading": "3.3.1. Tế bào âm đạo: Giúp phát hiện các thay đổi ở mức độ tế bào theo hướng tiền ung thư hoặc ung thư. Tiêu bản được nhuộm theo phương pháp Papanicolaou và xếp loại theo danh pháp Bethesda 2001 bao gồm:", "paragraphs": ["Các thay đổi tế bào biểu mô lát:", "ASCUS(Atypical Squamous Cells of undetermined Signification): bất điển hình tế bào lát có ý nghĩa không xác định", "LSIL(Low-grade Squamous Intraepithelium Lesions): tổn thương trong biểu mô lát mức độ thấp", "HSIL(High-grade Squamous Intraepithelium Lesions): thương tổn trong biểu mô lát mức độ cao", "Ung thư.", "Các thay đổi tế bào biểu mô trụ:", "AGUS(Atypical Glandular Cells of undetermined Signification): bất điển hình tế bào tuyến có ý nghĩa không xác định", "ACIS(Adenocarcinoma In Situ): ung thư trong liên bào biểu mô tuyến", "Ung thư.", "Bảng phân loại tương đương của 3 hệ thống: Bethesda, CIN và Pap", "CIN", "Bethesda", "Pap", "Normal", "Normal", "I", "Atypia", "ASCUS/ AGUS", "II", "HPV", "L-SIL", "II", "Condylom, Koilocyte", "L-SIL", "II", "CIN I", "L-SIL", "III", "CIN II", "H-SIL", "III", "CIN III", "H-SIL", "III-IV", "CIS", "H-SIL", "IV", "Invasive Cancer", "Invasive Cancer", "V"], "bullets": []}, {"heading": "3.3.2. Soi cổ tử cung", "paragraphs": ["Ngoài các thương tổn trên, cần phải xác định vùng chuyển tiếp.", "A. Chứng nghiệm Hinselmann                     B. Chứng nghiệm Schiller", "Hình 3. Soi cổ tử cung"], "bullets": ["- Không chuẩn bị: tổn thương dạng sùi hoặc loét, bề mặt dễ chảy máu, nhiều mạch máu tăng sinh.", "- Chứng nghiệm Hinselmann (chứng nghiệm axít axêtic): Khi bôi acid acetic 3%, vùng tổn thương trở nên trắng đục, có thể có hình chấm đáy hoặc hình lát đá.", "- Chứng nghiệm Schiller: Bôi dung dịch Lugol 3%, vùng tổn thương không bắt màu  nâu."]}, {"heading": "3.3.4. Chẩn đoán hình ảnh", "paragraphs": ["Để giúp đánh giá đầy đủ mức độ lan tràn và xâm lấn của ung thư, có thể chỉ định một số thăm dò sau: siêu âm, chụp UIV, chụp cắt lớp vi tính (CT Scan), cộng hưởng từ hạt nhân (MRI)."], "bullets": []}, {"heading": "3.4. Các giai đoạn lâm sàng", "paragraphs": ["Phân loại theo FIGO -1994 (Fédération Internationale de Gynécologie et Obstétrique).", "Ung thư xâm lấn âm đạo nhưng chưa lan đến 1/3 dưới.", "Hình 4. Phân loại ung thư cổ tử cung theo FIGO -1994"], "bullets": ["- Giai đoạn Ia: Ung thư xâm lấn chỉ được xác định trên vi thể. Tất cả các tổn thương đại thể thậm chí với xâm lấn nông thuộc ung thư giai đoạn Ib, xâm lấn giới hạn đến mô đệm sâu tối đa 5mm và không rộng hơn 7mm.", "+ Giai đoạn Ia1: Xâm lấn mô đệm sâu không quá 3mm và không rộng quá 7mm.", "+ Giai đoạn Ia2: Xâm lấn mô đệm sâu hơn 3mm, nhưng không quá 5mm và lan rộng không quá 7mm.", "- Giai đoạn Ib: Tổn thương lâm sàng khu trú ở cổ tử cung hoặc tổn thương tiền lâm sàng lớn hơn giai đoạn Ia.", "+ Giai đoạn Ib1: Tổn thương lâm sàng có kích thước không quá 4cm.", "+ Giai đoạn Ib2: Tổn thương lâm sàng có kích thước lớn hơn 4cm.", "- Giai đoạn II: Ung thư lan lên khỏi cổ tử cung nhưng chưa lan rộng đến thành chậu.", "+ Giai đoạn IIa: Không có xâm nhiễm nền dây chằng rộng.", "+ Giai đoạn IIb: Có xâm nhiễm rõ ràng nền dây chằng rộng.", "- Giai đoạn III: Ung thư lan đến thành chậu. Khám trực tràng, không thấy có khoang trống không có ung thư giữa khối u và thành chậu. Khối u lan xuống 1/3 dưới âm đạo. Tất cả các trường hợp thận ứ nước hoặc thận câm đều thuộc giai đoạn III trừ khi do nguyên nhân khác gây ra.", "+ Giai đoạn IIIa: Không lan đến thành chậu nhưng xâm lấn đến 1/3 dưới âm đạo.", "+ Giai đoạn IIIb: Lan đến thành chậu hay thận ứ nước hoặc thận câm.", "- Giai đoạn IV: Ung thư lan khỏi vùng chậu hoặc có bằng chứng lâm sàng xâm lấn niêm mạc bàng quang hay trực tràng.", "+ Giai đoạn IVa: Lan đến cơ quan lân cận.", "+ Giai đoạn IVb: Lan đến cơ quan xa."]}, {"heading": "5.1.1. Xạ trị", "paragraphs": ["Các biến chứng thường gặp là: Nhiễm trùng, viêm bàng quang thoáng qua, loét trực tràng, dò bàng quang-âm đạo, dò bàng quang-trực tràng.", "Phương pháp này chỉ có khả năng tiêu diệt những ổ ung thư tại chỗ và một số chuỗi hạch lân cận."], "bullets": ["- Xạ trị ngoài: sử dụng Cobalt 60, tổng liều 50-60 grays. Biến chứng thường gặp là viêm bàng quang, viêm ruột, các phản ứng của da như tình trạng xơ cứng hạ bì. Quang tuyến liệu pháp được dùng như một biện pháp bổ sung trong trường hợp có di căn đến hạch, hoặc điều trị trước mổ trong trường hợp khối u quá lớn.", "- Xạ trị tại chỗ: sử dụng radium hoặc césium, bằng cách đặt các nguồn tia xạ vào âm đạo - cổ tử cung."]}, {"heading": "5.1.2. Điều trị ngoại khoa", "paragraphs": [], "bullets": ["- Các phương pháp cắt bỏ thương tổn tại chỗ:  Dị sản và carcinoma tại chỗ: khoét chóp cổ tử cung bằng phương pháp đốt điện hoặc đốt lạnh hoặc đốt bằng laser. Một lựa chọn khác vừa chẩn đoán vừa điều trị là cắt bằng dao điện vòng (LEEP). Tuy nhiên trong nhiều tình huống, LEEP không đủ, cần các thủ thuật cắt bỏ rộng rãi hơn. Các biện pháp nói trên có thể giúp bảo tồn nếu người phụ nữ còn muốn sinh đẻ. Những bệnh nhân đã sinh con đủ có thể lựa chọn cắt tử cung toàn bộ.", "- Phẫu thuật Wertheim-Meigs", "+ Cắt tử cung toàn phần rộng rãi đến 1/3 trên âm đạo.", "+ Lấy hạch và lấy hết mô mỡ dọc theo các chuỗi hạch thành chậu.", "+Lấy nhóm hạch cạnh động mạch chủ."]}, {"heading": "5.1.3 Điều trị hoá chất", "paragraphs": ["Cho đến nay vẫn chưa xác định được liệu pháp hoá chất tối ưu sau phẫu thuật, nhưng kết quả từ các nghiên cứu hiện có cho thấy Cisplatin đơn thuần liều thấp (40 mg/m2 hàng tuần) hoặc Cisplatin (50 - 75 mg/m2 ngày thứ nhất) phối hợp với 5-FU (1000 mg/m2 trong 4 ngày tiếp theo) có thể cải thiện thời gian sống còn của bệnh nhân."], "bullets": ["- Hoá liệu pháp trước phẫu thuật tỏ ra hữu ích trong các trường hợp khối u trên 2cm.", "- Liệu trình với Cisplatin 50 mg/m2, Vincristine 1 mg/m2 và Bleomycine 25 mg/m2 trong ngày 1-3/3 tuần có thể làm giảm bớt kích thước khối u, tạo điều kiện cho phẫu thuật dễ dàng và kéo dài thời gian tái phát."]}, {"heading": "5.2.1. Ung thư trong liên bào", "paragraphs": ["Ở người phụ nữ còn trẻ, còn có nguyện vọng sinh đẻ, có thể khoét chóp  hay cắt cụt cổ tử cung, và sau đó cần phải được theo dõi kỹ định kỳ 6 tháng với 3-4 lần làm tế bào học âm đạo. Ở người phụ nữ đủ con, lớn tuổi có thể cắt tử cung toàn phần rộng rãi."], "bullets": []}, {"heading": "5.2.2. Ung thư xâm lấn", "paragraphs": ["Thông thường xử trí theo phác đồ phối hợp giữa xạ trị và phẫu thuật."], "bullets": ["- Giai đoạn I - IIa: Chủ yếu là phẫu thuật theo phương pháp Wertheim-Meigs,  cắt tử cung hoàn toàn, cắt hai phần phụ, cắt 1/3 trên âm đạo,lấy hết các tổ chức liên kết dưới hai lá dây chằng rộng, nạo hạch trong hố chậu và dọc theo động mạch chủ bụng. Đối với giai đoạn Ib, nhiều tác giả nêu lợi ích của xạ trị trước phẫu thuật nhằm giảm mức độ ác tính của tế bào ung thư, diệt những ổ lan tràn quanh tổn thương nguyên phát, ngăn chặn di căn. Xạ trị trước mổ, nguồn xạ sử dụng là césium hay radium, ngừng xạ trị khoảng 6 tuần trước  phẫu thuật, xạ trị sau mổ dùng tia Cobalt chiếu vào vùng chậu nơi đã lấy hạch có tế bào ung thư.", "- Giai đoạn IIb và giai đoạn IVa:  xạ trị và đánh giá lại để cân nhắc chỉ định phẫu thuật.", "- Giai đoạn IVb: Phương pháp điều trị chủ yếu là giảm nhẹ, xạ trị và điều trị hỗ trợ, có thể áp dụng phẫu thuật tạm thời như dẫn lưu bàng quang, hậu môn nhân tạo."]}, {"heading": "6. TIÊN LƯỢNG", "paragraphs": ["Các yếu tố tiên lượng: phụ thuộc vào giai đoạn bệnh, di căn hạch, kích thước khối ung thư, thể trạng của bệnh nhân và mức độ triệt để của phẫu thuật.", "Tỷ lệ sống sau 5 năm:"], "bullets": ["+ Giai đoạn ung thư trong liên bào: 100%", "+ Giai đoạn I: 80%", "+ Giai đoạn II: 50%", "+ Giai đoạn III: 20-30%", "+ Giai đoạn IV: dưới 10%"]}, {"heading": "7. DỰ PHÒNG", "paragraphs": ["Ung thư cổ tử cung nguy hiểm vì gây tử vong cao vào giai đoạn xâm lấn, song tiến triển chậm, nếu được phát hiện sớm có thể điều trị khỏi. Do đó dự phòng ung thư cổ tử cung có vai trò rất lớn trong việc làm giảm tỷ lệ mắc bệnh và tử vong. Để phòng bệnh, cần hướng dẫn các biện pháp dự phòng cho phụ nữ:", "ư Năm 2006 Liên hiệp Châu Âu và Tổ chức kiểm soát thuốc và thực phẩm Hoa Kỳ tiếp cận một loại vaccine đầu tiên phòng chống ung thư cổ tử cung, tiền ung thư, nụ sùi sinh dục. Loại vaccine có thể bảo vệ khỏi lây nhiễm bởi 4 type HPV nguyên nhân gây ra của 70% của tất cả các ung thư cổ tử cung và khoảng 90% của tất cả các nụ sùi sinh dục. Loại này được sử dụng cho nữ ở độ tuổi từ 9ư26 tuổi."], "bullets": ["- Sinh ít", "- Thực hiện tốt vệ sinh phụ nữ.", "- Khám phụ khoa định kỳ, ít nhất là 1 lần/năm để thực hiện các xét nghiệm sàng lọc (làm phiến đồ âm đạo - cổ tử cung...) hoặc đến khám ở cơ sở chuyên khoa khi có dấu hiệu bất thường như: ra máu sau giao hợp, khí hư bất thường.", "- Điều trị sớm và triệt để các tổn thương lành tính cổ tử cung", "- Không quan hệ tình dục quá sớm, không có nhiều bạn tình."]}, {"heading": "Câu hỏi:", "paragraphs": ["Mô tả triệu chứng cơ năng và thực thể của bệnh ung thư cổ tử cung?", "Phân loại ung thư cổ tử cung theo FIGO?", "Trình bày các xét nghiệm sàng lọc tổn thương tiền ung thư và  ung thư?", "Trình bày các phương thức điều trị cho từng giai đoạn của ung thư cổ tử cung?"], "bullets": []}], "raw_text": "UNG THƯ CỔ TỬ CUNG\nMục tiêu học tập\n1. Liệt kê được các yếu tố nguy cơ của ung thư cổ tử cung..\n2. Trình bày được triệu chứng, chẩn đoán và phân giai đoạn ung thư cổ tử cung.\n3. Trình bày được các xét nghiệm sàng lọc tổn thương tiền ung thư và  ung thư.\n4. Trình bày được các phương thức điều trị cho từng giai đoạn của ung thư cổ tử cung.\n1. ĐẠI CƯƠNG VÀ CÁC YẾU TỐ NGUY CƠ\n- Ung thư cổ tử cung (UTCTC) là khối u ác tính đứng hàng thứ hai sau ung thư vú và cũng đứng thứ hai gây tử vong do ung thư ở nữ giới, thường xảy ra ở ranh giới giữa biểu mô lát tầng và biểu mô trụ của cổ tử cung.\nCIN(cervical intraepithelian neoplasia): gọi là tiền ung thư hay khối u mới phát sinh trong biểu mô mức độ loạn sản khác nhau. Chẩn đoán và điều trị sớm loạn sản biểu mô cổ tử cung sẽ giảm được xâm lấn rất rõ ràng.\n- Theo số liệu của Hiệp hội phòng chống ung thư thế giới thì UTCTC chiếm 12% các ung thư đường sinh dục nữ. Tại Viện ung bướu Hà Nội, ung thư cổ tử cung chiếm khoảng 6%. Nếu tính trên tổng số dân thì UTCTC chiếm từ 6,6 - 8,6/100.000 dân. Trong khi đó, tỷ lệ này tại thành phố Hồ Chí Minh là 35,6/100.000\n- Kết quả điều trị UTCTC phụ thuộc vào thời điểm chẩn đoán. Nếu chẩn đoán muộn việc điều trị gặp nhiều khó khăn và kết quả điều trị thấp.\n- Các yếu tố nguy cơ:\n+ Các sang chấn liên tục ở cổ tử cung: có thai và đẻ quá sớm (< 20 tuổi), rách CTC\n+ Lộ tuyến CTC có nguy cơ loạn sản nếu như điều trị không triệt để\n+ Nhiễm Human Papilloma virus (HPV, GPB thấy nhân nằm xuống cực dưới), Herpes virus, HIV.\n+ Tuổi: từ 40 -70.\n+ Hút thuốc lá\n+ Sinh nhiều: từ 5 con trở lên.\n+ Quan hệ tình dục sớm.\n+ Có nhiều bạn tình: người vợ của những người chồng có nhiều bạn tình chất tiết quy đầu có men hyaruluaronidaza (bựa) gây ung thư cổ tử cung..\n+ Vệ sinh cá nhân kém.\n+ Dùng corticoid kéo dài, hoá trị liệu...\n+ Thuốc ngừa thai dạng uống, yếu tố gia đình.\n+ Tiền sử viêm nhiễm đường sinh dục, nhiều lần\n+ Di truyền: mẹ truyền cho con gái nhiều gen dễ chịu tác động\n\n2. GIẢI PHẪU BỆNH\n2.1. Ung thư trong liên bào (carcinoma in situ): Tế bào ung thư chiếm toàn bộ bề dày lớp biểu mô nhưng chưa xâm lấn qua màng đáy.\n2.1.1. Bất thường về mặt tế bào: Nhiều tế bào bệnh lý có nhân lớn, không đồng đều, chất nhiễm sắc bắt màu đậm, có nhiều sự phân bào bất thường dạng nhân quái nhân chia.\n2.1.2. Bất thường về cấu trúc: Mất hiện tượng phân tầng bình thường của các lớp tế bào.\n2.2. Ung thư xâm lấn: Tế bào ung thư phá huỷ lớp màng đáy và xâm lấn vào tổ chức đệm, trường hợp này ta gọi là ung thư xâm lấn. Có khoảng 95% các trường hợp là ung thư biểu mô lát và khoảng 5% dạng biểu mô trụ.\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\nBiểu đồ 1. Tiến triển của các thương tổn tiền ác tính và ung thư ở cổ tử cung\n\n\n\n\nHình 1. Hình ảnh đại thể ung thư cổ tử cung ở cổ ngoài (trái) và ống cổ tử cung (phải)\n2.3. Lan tràn của ung thư cổ tử cung\n2.3.1. Tại chỗ\n- Từ vùng chuyển tiếp ở bề mặt cổ tử cung - âm đạo lan xuống âm đạo, lan lên eo của tử cung,\n- Xâm lấn sâu về phía trước, đến vách bàng quang-âm đạo và bàng quang.\n-  Xâm lấn ra phía sau phên trực tràng - âm đạo và trực tràng.\n- Xâm lấn  ra hai bên đáy dây chằng rộng, niệu quản và vách chậu.\n2.3.2. Theo đường bạch mạch\nUng thư lan theo đường này đến chuỗi hạch chậu ngoài, chậu trong, cũng có khi ung thư lan tràn bất thường, chẳng hạn bỏ qua chuỗi hạch chậu hông tới ngay nhóm hạch động mạch chủ bụng “di căn theo kiểu kỵ sĩ “.\nRất hiếm khi thấy ung thư di căn theo đường máu.\n\n3. TRIỆU CHỨNG LÂM SÀNG VÀ CẬN LÂM SÀNG\n3.1. Các thương tổn tiền lâm sàng\nỞ giai đoạn sớm, các triệu chứng cơ năng thường nghèo nàn: ra khí hư vàng bẩn khác thường. Khi khám âm đạo - cổ tử cung bằng mỏ vịt có thể thấy cổ tử cung trông giống như bình thường hoặc có vết loét trợt, một vùng trắng không điển hình hoặc tăng sinh mạch máu.\n3.2. Các thương tổn rõ trên lâm sàng\nBệnh nhân thường đến khám với triệu chứng ra máu âm đạo bất thường giữa kỳ kinh, ra máu sau giao hợp, hoặc khí hư hôi, lẫn máu, có thể phối hợp với tình trạng cơ thể suy kiệt.\nKhám mỏ vịt hiện diện một khối sùi, dễ chảy máu khi chạm vào. Khi bôi Lugol vùng tổn thương không bắt màu (nghiệm pháp Schiller âm tính). Một số trường hợp muộn hơn cổ tử cung sẽ biến dạng, loét sâu hoặc cổ tử cung bị mất hẳn hình dạng. Sinh thiết được thực hiện ở cả vùng lành và vùng bệnh lý. Ngoài ra, cần phải đánh giá mức độ lan tràn và xâm lấn của ung thư vào các túi cùng âm đạo, nền dây chằng rộng, bàng quang, trực tràng và các vùng kế cận.\n\n\nHình 2. Thương tổn cổ tử cung trên lâm sàng\n\n3.3. Cận lâm sàng\n3.3.1. Tế bào âm đạo: Giúp phát hiện các thay đổi ở mức độ tế bào theo hướng tiền ung thư hoặc ung thư. Tiêu bản được nhuộm theo phương pháp Papanicolaou và xếp loại theo danh pháp Bethesda 2001 bao gồm:\nCác thay đổi tế bào biểu mô lát:\nASCUS(Atypical Squamous Cells of undetermined Signification): bất điển hình tế bào lát có ý nghĩa không xác định\nLSIL(Low-grade Squamous Intraepithelium Lesions): tổn thương trong biểu mô lát mức độ thấp\nHSIL(High-grade Squamous Intraepithelium Lesions): thương tổn trong biểu mô lát mức độ cao\nUng thư.\nCác thay đổi tế bào biểu mô trụ:\nAGUS(Atypical Glandular Cells of undetermined Signification): bất điển hình tế bào tuyến có ý nghĩa không xác định\nACIS(Adenocarcinoma In Situ): ung thư trong liên bào biểu mô tuyến\nUng thư.\nBảng phân loại tương đương của 3 hệ thống: Bethesda, CIN và Pap\n\nCIN\nBethesda\nPap\n\nNormal\nNormal\nI\n\nAtypia\nASCUS/ AGUS\nII\n\nHPV\nL-SIL\nII\n\nCondylom, Koilocyte\nL-SIL\nII\n\nCIN I\nL-SIL\nIII\n\nCIN II\nH-SIL\nIII\n\nCIN III\nH-SIL\nIII-IV\n\nCIS\nH-SIL\nIV\n\nInvasive Cancer\nInvasive Cancer\nV\n\n\n3.3.2. Soi cổ tử cung\n- Không chuẩn bị: tổn thương dạng sùi hoặc loét, bề mặt dễ chảy máu, nhiều mạch máu tăng sinh.\n- Chứng nghiệm Hinselmann (chứng nghiệm axít axêtic): Khi bôi acid acetic 3%, vùng tổn thương trở nên trắng đục, có thể có hình chấm đáy hoặc hình lát đá.\n- Chứng nghiệm Schiller: Bôi dung dịch Lugol 3%, vùng tổn thương không bắt màu  nâu.\nNgoài các thương tổn trên, cần phải xác định vùng chuyển tiếp.\n\n\nA. Chứng nghiệm Hinselmann                     B. Chứng nghiệm Schiller\nHình 3. Soi cổ tử cung\n3.3.3. Sinh thiết: Được lấy từ vùng chuyển tiếp và vùng nghi ngờ, cho phép khảo sát mô học một cách chính xác và đầy đủ.\n3.3.4. Chẩn đoán hình ảnh\nĐể giúp đánh giá đầy đủ mức độ lan tràn và xâm lấn của ung thư, có thể chỉ định một số thăm dò sau: siêu âm, chụp UIV, chụp cắt lớp vi tính (CT Scan), cộng hưởng từ hạt nhân (MRI).\n3.4. Các giai đoạn lâm sàng\nPhân loại theo FIGO -1994 (Fédération Internationale de Gynécologie et Obstétrique).\n- Giai đoạn Ia: Ung thư xâm lấn chỉ được xác định trên vi thể. Tất cả các tổn thương đại thể thậm chí với xâm lấn nông thuộc ung thư giai đoạn Ib, xâm lấn giới hạn đến mô đệm sâu tối đa 5mm và không rộng hơn 7mm.\n+ Giai đoạn Ia1: Xâm lấn mô đệm sâu không quá 3mm và không rộng quá 7mm.\n+ Giai đoạn Ia2: Xâm lấn mô đệm sâu hơn 3mm, nhưng không quá 5mm và lan rộng không quá 7mm.\n- Giai đoạn Ib: Tổn thương lâm sàng khu trú ở cổ tử cung hoặc tổn thương tiền lâm sàng lớn hơn giai đoạn Ia.\n+ Giai đoạn Ib1: Tổn thương lâm sàng có kích thước không quá 4cm.\n+ Giai đoạn Ib2: Tổn thương lâm sàng có kích thước lớn hơn 4cm.\n- Giai đoạn II: Ung thư lan lên khỏi cổ tử cung nhưng chưa lan rộng đến thành chậu.\nUng thư xâm lấn âm đạo nhưng chưa lan đến 1/3 dưới.\n+ Giai đoạn IIa: Không có xâm nhiễm nền dây chằng rộng.\n+ Giai đoạn IIb: Có xâm nhiễm rõ ràng nền dây chằng rộng.\n- Giai đoạn III: Ung thư lan đến thành chậu. Khám trực tràng, không thấy có khoang trống không có ung thư giữa khối u và thành chậu. Khối u lan xuống 1/3 dưới âm đạo. Tất cả các trường hợp thận ứ nước hoặc thận câm đều thuộc giai đoạn III trừ khi do nguyên nhân khác gây ra.\n+ Giai đoạn IIIa: Không lan đến thành chậu nhưng xâm lấn đến 1/3 dưới âm đạo.\n+ Giai đoạn IIIb: Lan đến thành chậu hay thận ứ nước hoặc thận câm.\n- Giai đoạn IV: Ung thư lan khỏi vùng chậu hoặc có bằng chứng lâm sàng xâm lấn niêm mạc bàng quang hay trực tràng.\n+ Giai đoạn IVa: Lan đến cơ quan lân cận.\n+ Giai đoạn IVb: Lan đến cơ quan xa.\n\nHình 4. Phân loại ung thư cổ tử cung theo FIGO -1994\n\n4. CHẨN ĐOÁN PHÂN BIỆT\n4.1. Lộ tuyến, loét trợt cổ tử cung: là thương tổn thường gặp ở cổ tử cung.\n4.2. Polyp cổ tử cung: Dạng polyp tuyến bị hoại tử hoặc nhiễm khuẩn.\n4.3. Lạc nội mạc tử cung: Dễ nhầm nhất là vào giai đoạn chảy máu trùng với hành kinh trên nền của thương tổn lạc nội mạc tử cung.\n4.4. Giang mai cổ tử cung: có thể gặp săng giang mai nguyên phát ở cổ tử cung.\n4.5 Lao cổ tử cung: rất hiếm gặp, có tiền sử lao sinh dục.\n\n5. ĐIỀU TRỊ\n5.1. Các biện pháp điều trị\n5.1.1. Xạ trị\n- Xạ trị ngoài: sử dụng Cobalt 60, tổng liều 50-60 grays. Biến chứng thường gặp là viêm bàng quang, viêm ruột, các phản ứng của da như tình trạng xơ cứng hạ bì. Quang tuyến liệu pháp được dùng như một biện pháp bổ sung trong trường hợp có di căn đến hạch, hoặc điều trị trước mổ trong trường hợp khối u quá lớn.\n- Xạ trị tại chỗ: sử dụng radium hoặc césium, bằng cách đặt các nguồn tia xạ vào âm đạo - cổ tử cung.\nCác biến chứng thường gặp là: Nhiễm trùng, viêm bàng quang thoáng qua, loét trực tràng, dò bàng quang-âm đạo, dò bàng quang-trực tràng.\nPhương pháp này chỉ có khả năng tiêu diệt những ổ ung thư tại chỗ và một số chuỗi hạch lân cận.\n5.1.2. Điều trị ngoại khoa\n- Các phương pháp cắt bỏ thương tổn tại chỗ:  Dị sản và carcinoma tại chỗ: khoét chóp cổ tử cung bằng phương pháp đốt điện hoặc đốt lạnh hoặc đốt bằng laser. Một lựa chọn khác vừa chẩn đoán vừa điều trị là cắt bằng dao điện vòng (LEEP). Tuy nhiên trong nhiều tình huống, LEEP không đủ, cần các thủ thuật cắt bỏ rộng rãi hơn. Các biện pháp nói trên có thể giúp bảo tồn nếu người phụ nữ còn muốn sinh đẻ. Những bệnh nhân đã sinh con đủ có thể lựa chọn cắt tử cung toàn bộ.\n- Phẫu thuật Wertheim-Meigs\n+ Cắt tử cung toàn phần rộng rãi đến 1/3 trên âm đạo.\n+ Lấy hạch và lấy hết mô mỡ dọc theo các chuỗi hạch thành chậu.\n+Lấy nhóm hạch cạnh động mạch chủ.\n5.1.3 Điều trị hoá chất\n- Hoá liệu pháp trước phẫu thuật tỏ ra hữu ích trong các trường hợp khối u trên 2cm.\n- Liệu trình với Cisplatin 50 mg/m2, Vincristine 1 mg/m2 và Bleomycine 25 mg/m2 trong ngày 1-3/3 tuần có thể làm giảm bớt kích thước khối u, tạo điều kiện cho phẫu thuật dễ dàng và kéo dài thời gian tái phát.\nCho đến nay vẫn chưa xác định được liệu pháp hoá chất tối ưu sau phẫu thuật, nhưng kết quả từ các nghiên cứu hiện có cho thấy Cisplatin đơn thuần liều thấp (40 mg/m2 hàng tuần) hoặc Cisplatin (50 - 75 mg/m2 ngày thứ nhất) phối hợp với 5-FU (1000 mg/m2 trong 4 ngày tiếp theo) có thể cải thiện thời gian sống còn của bệnh nhân.\n5.2. Chỉ định điều trị\n5.2.1. Ung thư trong liên bào\nỞ người phụ nữ còn trẻ, còn có nguyện vọng sinh đẻ, có thể khoét chóp  hay cắt cụt cổ tử cung, và sau đó cần phải được theo dõi kỹ định kỳ 6 tháng với 3-4 lần làm tế bào học âm đạo. Ở người phụ nữ đủ con, lớn tuổi có thể cắt tử cung toàn phần rộng rãi.\n5.2.2. Ung thư xâm lấn\nThông thường xử trí theo phác đồ phối hợp giữa xạ trị và phẫu thuật.\n- Giai đoạn I - IIa: Chủ yếu là phẫu thuật theo phương pháp Wertheim-Meigs,  cắt tử cung hoàn toàn, cắt hai phần phụ, cắt 1/3 trên âm đạo,lấy hết các tổ chức liên kết dưới hai lá dây chằng rộng, nạo hạch trong hố chậu và dọc theo động mạch chủ bụng. Đối với giai đoạn Ib, nhiều tác giả nêu lợi ích của xạ trị trước phẫu thuật nhằm giảm mức độ ác tính của tế bào ung thư, diệt những ổ lan tràn quanh tổn thương nguyên phát, ngăn chặn di căn. Xạ trị trước mổ, nguồn xạ sử dụng là césium hay radium, ngừng xạ trị khoảng 6 tuần trước  phẫu thuật, xạ trị sau mổ dùng tia Cobalt chiếu vào vùng chậu nơi đã lấy hạch có tế bào ung thư.\n- Giai đoạn IIb và giai đoạn IVa:  xạ trị và đánh giá lại để cân nhắc chỉ định phẫu thuật.\n- Giai đoạn IVb: Phương pháp điều trị chủ yếu là giảm nhẹ, xạ trị và điều trị hỗ trợ, có thể áp dụng phẫu thuật tạm thời như dẫn lưu bàng quang, hậu môn nhân tạo.\n6. TIÊN LƯỢNG\nCác yếu tố tiên lượng: phụ thuộc vào giai đoạn bệnh, di căn hạch, kích thước khối ung thư, thể trạng của bệnh nhân và mức độ triệt để của phẫu thuật.\nTỷ lệ sống sau 5 năm:\n+ Giai đoạn ung thư trong liên bào: 100%\n+ Giai đoạn I: 80%\n+ Giai đoạn II: 50%\n+ Giai đoạn III: 20-30%\n+ Giai đoạn IV: dưới 10%\n\n7. DỰ PHÒNG\nUng thư cổ tử cung nguy hiểm vì gây tử vong cao vào giai đoạn xâm lấn, song tiến triển chậm, nếu được phát hiện sớm có thể điều trị khỏi. Do đó dự phòng ung thư cổ tử cung có vai trò rất lớn trong việc làm giảm tỷ lệ mắc bệnh và tử vong. Để phòng bệnh, cần hướng dẫn các biện pháp dự phòng cho phụ nữ:\n- Sinh ít\n- Thực hiện tốt vệ sinh phụ nữ.\n- Khám phụ khoa định kỳ, ít nhất là 1 lần/năm để thực hiện các xét nghiệm sàng lọc (làm phiến đồ âm đạo - cổ tử cung...) hoặc đến khám ở cơ sở chuyên khoa khi có dấu hiệu bất thường như: ra máu sau giao hợp, khí hư bất thường.\n- Điều trị sớm và triệt để các tổn thương lành tính cổ tử cung\n- Không quan hệ tình dục quá sớm, không có nhiều bạn tình.\nư Năm 2006 Liên hiệp Châu Âu và Tổ chức kiểm soát thuốc và thực phẩm Hoa Kỳ tiếp cận một loại vaccine đầu tiên phòng chống ung thư cổ tử cung, tiền ung thư, nụ sùi sinh dục. Loại vaccine có thể bảo vệ khỏi lây nhiễm bởi 4 type HPV nguyên nhân gây ra của 70% của tất cả các ung thư cổ tử cung và khoảng 90% của tất cả các nụ sùi sinh dục. Loại này được sử dụng cho nữ ở độ tuổi từ 9ư26 tuổi.\nCâu hỏi:\nMô tả triệu chứng cơ năng và thực thể của bệnh ung thư cổ tử cung?\nPhân loại ung thư cổ tử cung theo FIGO?\nTrình bày các xét nghiệm sàng lọc tổn thương tiền ung thư và  ung thư?\nTrình bày các phương thức điều trị cho từng giai đoạn của ung thư cổ tử cung?", "priority": "Cao (Trọng tâm BSNT)"}, {"id": "SK-41", "chapter": "Chương 3. Phụ khoa", "folder": "03_Phu_khoa", "title": "Ung thư niêm mạc tử cung", "author": "TS. Bùi Minh Tiến, TS. Phan Văn Cương", "word_count": 2069, "line_count": 134, "key_numbers": ["150mg", "25kg", "6 tuần"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["UNG THƯ NIÊM MẠC TỬ CUNG", "TS. Bùi Minh Tiến"], "bullets": []}, {"heading": "1. ĐẠI CƯƠNG", "paragraphs": ["Ung thư niêm mạc tử cung là các khối u phát triển từ niêm mạc tử cung, là một loại ung thư thường gặp ở người lớn tuổi. Có hơn 80% bệnh nhân ung thư niêm mạc tử cung gặp ở người mãn kinh, trong đó có khoảng 95% có nguồn gốc từ biểu mô tuyến của nội mạc tử cung. So sánh với ung thư cổ tử cung: cứ 4 case ung thư cổ tử cung có 1 case  ung thư niêm mạc tử cung"], "bullets": []}, {"heading": "2. CÁC YẾU TỐ NGUY CƠ", "paragraphs": ["Tuổi: từ  50-70", "Không sinh đẻ hoặc đẻ ít", "Béo phì (trên 25kg so với bình thường)", "Đái tháo đường.", "Cao huyết áp.", "Bệnh lý ở tử cung: quá sản nội mạc tử cung.", "Có kinh sớm, mãn kinh muộn: sau 55 tuổi.", "Dùng estrogen đơn thuần, kéo dài.", "Phụ nữ không bao giờ mang thai, không cho con bú.", "Rối loạn chức năng buồng trứng: tồn tại dai dẳng các nang bọc noãn làm cho niêm mạc tử cung luôn bị kích thích, tăng sinh gây tình trạng quá sản, loạn sản.", "Hội chứng buồng trứng đa nang: vòng kinh không phóng noãn biểu hiện kinh thưa, vô kinh, không phóng noãn, siêu âm buồng trứng có nhiều nang cùng lứa tuổi xếp theo hình tràng hạt.", "Cường vỏ thượng thận.", "Tiền sử ung thư buồng trứng, ung thư vú và ung thư đại tràng."], "bullets": []}, {"heading": "3.1. Đại thể", "paragraphs": ["Lòng tử cung có một khối mềm sùi dễ vỡ, có thể dạng như polyp mọc lấn vào buồng tử cung.", "Hình 1. Hình ảnh ung thư niêm mạc tử cung"], "bullets": []}, {"heading": "3.2. Vi thể", "paragraphs": ["Là một loại ung thư tuyến (adenocarcinom), từ đó tiên lượng bệnh tuỳ thuộc vào mức độ biệt hoá của tế bào:"], "bullets": ["- Grade 1: Hình ảnh của quá sản không điển hình, song có các tế bào ác tính, lớp cơ không bị xâm lấn. Tiên lượng tốt.", "- Grade 2: Các tuyến nhỏ hơn, ép sát vào nhau, lớp cơ mới bị xâm lấn, ở đó thấy rõ các tế bào ác tính. Biệt hoá trung bình.", "- Grade 3: Có thể thấy các cấu trúc tuyến nhỏ và các tế bào không biệt hoá. Loại ác tính nhất."]}, {"heading": "3.3. Sự lan tràn của ung thư niêm mạc tử cung", "paragraphs": ["Ung thư niêm mạc tử cung không lan tràn nhanh bằng ung thư cổ tử cung, vì cơ tử cung là một hàng rào có tác dụng khá tốt."], "bullets": []}, {"heading": "3.3.2. Lan tràn theo đường bạch huyết:", "paragraphs": ["Có khoảng từ 30- 40% ung thư lan tràn theo đường này, ở thân tử cung tổ chức ung thư phát triển xuống eo tử cung rồi xuống đáy dây chằng rộng, đến hệ thống hạch chậu trong, chậu ngoài và xa hơn nữa; sự lan tràn này dể xảy ra hơn khi khối u bị thoái triển và thành tử cung bị ung thư xâm lấn sâu."], "bullets": []}, {"heading": "3.3.3. Lan theo đường dẫn tự nhiên (vòi tử cung)", "paragraphs": ["Các tế bào ung thư có thể đi theo vòi tử cung, theo cùng đường tràn vào trong ổ phúc mạc của máu kinh, điều này giải thích cho các trường hợp di căn buồng trứng đơn thuần."], "bullets": []}, {"heading": "3.3.5. Lan tràn theo đường tĩnh mạch: ít thấy.", "paragraphs": ["Hình 2. Bệnh phẩm đại thể ung thư niêm mạc tử cung giai đoạn I (trái)", "và giai đoạn II (phải)"], "bullets": []}, {"heading": "4. TRIỆU CHỨNG VÀ CHẨN ĐOÁN", "paragraphs": ["Thường bệnh nhân đến khám vì:"], "bullets": []}, {"heading": "4.1. Ra máu bất thường (# 95% các trường hợp)", "paragraphs": ["Ra máu ở người đã mãn kinh là một dấu hiệu có giá trị, có khi ra máu trong thời kỳ tiền mãn kinh, làm cho ta lầm với những rối loạn của thời kỳ này. Ra máu thường kèm theo khí hư nhiều, hôi.", "Đau: tiến triển dần. Lúc đầu cảm giác tức nặng vùng bụng dưới, giai đoạn muộn khi lan ra các tạng trong hố chậu đau càng nhiều."], "bullets": []}, {"heading": "4.2. Hỏi bệnh", "paragraphs": ["Có thể phát hiện được các yếu tố nguy cơ hiện tại cũng như trong tiền sử."], "bullets": []}, {"heading": "4.3. Khám thực thể", "paragraphs": [], "bullets": ["- Khám mỏ vịt: Cũng có khi thấy âm đạo bình thường, hơi teo ở những người mãn kinh. Thường thì khí hư nhiều, nhầy loãng, hôi, có khi là mủ. Trong trường hợp này thường kèm theo đau và cảm giác nặng nề ở vùng hạ vị.", "- Khám âm đạo bằng tay, tử cung thường có kích thước bình thường, cũng có thể hơi to và mềm. Có khi phát hiện u xơ tử cung đi kèm. Di động tử cung đau thường có ứ mủ buồng tử cung, di động tử cung cũng phụ thuộc vào từng giai đoạn lan tràn.", "- Toàn thân: nếu có ứ mủ buồng tử cung có thể sốt.", "- Khám hạch: khám hệ thống hạch ngoại biên: bẹn, thượng đòn, nách có thể thấy hạch"]}, {"heading": "4.4.1. Tế bào bệnh học: Bệnh phẩm là dịch hút từ buồng tử cung. Đây là dấu hiệu quyết định chẩn đoán.", "paragraphs": [], "bullets": ["- Thuận lợi: Dễ thực hiện, ít có biến chứng.", "- Không thuận lợi: Những trường hợp ung thư giai đoạn sớm có thể khó phát hiện."]}, {"heading": "4.4.2. Chụp buồng tử cung:", "paragraphs": ["Chỉ bơm thuốc cản quang với áp lực nhẹ đủ thuốc ngấm trong buồng tử cung mà không cần lan ra hai vòi trứng, có thể thấy hình ảnh khuyết, bờ không đều, nham nhở, buồng tử cung lớn, có hình ảnh đọng dịch. Thủ thuật này hiện nay ít được chỉ định."], "bullets": []}, {"heading": "4.4.3. Soi buồng tử cung:", "paragraphs": ["Quan sát trực tiếp hình ảnh nội mạc tử cung cũng như thương tổn một cách chính xác như nụ sùi, vùng loét hoại tử chảy máu, hoặc hình ảnh quá sản nội mạc tử cung chạm vào dễ chảy máu, xác định được độ lan rộng và giúp định vị vùng sinh thiết."], "bullets": ["- Thuận lợi: Dễ làm, có thể tiến hành nhanh ở phòng khám bệnh.", "- Không thuận lợi: Phương tiện đắt."]}, {"heading": "4.4.4. Nạo sinh thiết toàn bộ tử cung:", "paragraphs": ["Tiến hành cẩn thận, đề phòng thủng. Tốt nhất nên làm từ ngoài vào trong và để riêng bệnh phẩm: ống cổ tử cung và buồng tử cung. Sử dụng thìa nạo hoặc ống hút Novak. Kết quả sinh thiết giúp phân loại mô học."], "bullets": []}, {"heading": "4.4.5. Siêu âm:", "paragraphs": ["Nhất là siêu âm theo đường âm đạo cho hình ảnh thực thể của tử cung, nội mạc dày hoặc đánh giá độ lan tràn và bề dày lớp cơ. đồng thời siêu âm cũng giúp khảo sát các bệnh lý phối hợp như u xơ tử cung, u nang buồng trứng..."], "bullets": []}, {"heading": "4.4.6. Chụp cắt lớp:", "paragraphs": ["Là một phương pháp khá hữu hiệu để xác định mức độ xâm lấn và lan tràn của ung thư, nhất là ở các giai đoạn muộn. Phương pháp này được chỉ định trong những trường hợp cần thiết phải chẩn đoán phân biệt.", "Cần phải đánh giá tình trạng ung thư tuyến khác có thể kèm theo như ung thư vú hoặc đại tràng."], "bullets": []}, {"heading": "5. CÁC GIAI ĐOẠN LÂM SÀNG", "paragraphs": ["Theo Hiệp hội ung thư Hoa Kỳ AJCC và FIGO (Fédération Internationale de Gynécologie et Obsstétrique) 2010, ung thư niêm mạc tử cung được phân loại như sau: U khu trú ở thân tử cung", "Giai đoạn I: U khu trú ở thân tử cung", "IA : : Tổn thương giới hạn ở niêm mạc tử cung (bề mặt) hoặc tổn thương ăn sâu vào lớp cơ tử cung <50%", "IB : tổn thương ăn sâu vào lớp cơ tử cung >50%", "Giai đoạn II: U xâm lấn tới mô đệm cổ tử cung nhưng chưa lan ra khỏi tử cung", "Hình 3. Phân độ ung thư niêm mạc tử cung theo FIGO 2010- giai đoạn I và II", "Giai đoạn III: U lan ra ngoài tử cung nhưng còn khu trú trong khung chậu", "IIIA: tổn thương xâm nhiễm vào thanh mạc hay phần phụ hay tế bào phúc mạc dương tính", "IIIB: tổn thương di căn âm đạo", "IIIC1: Di căn tới hạch chậu (hạch chậu dương tính)", "IIIC2: Di căn tới hạch cạnh động mạch chủ, có/hoặc không kèm theo hạch chậu dương tính.", "Hình 4. Phân độ ung thư niêm mạc tử cung theo FIGO 2010- giai đoạn III", "Giai đoạn IV: U xâm lấn tới niêm mạc bàng quang và/hoặc niêm mạc ruột và/hoặc di căn xa", "IVA: tổn thương ung thư xâm nhiễm vào bàng quang và/hoặc ruột", "IVB: ung thư di căn xa bao gồm di căn hạch trong ổ bụng hay hạch bẹn  hoặc phổi, gan, xương. (Ngoại trừ di căn tới hạch cạnh động mạch chủ, âm đạo, thanh mạc tiểu khung hoặc phần phụ)", "Hình 5. Phân độ ung thư niêm mạc tử cung theo FIGO 2010- giai đoạn IV", "Ghi chú: Xâm lấn tuyến nội mạc cổ tử cung chỉ xếp vào giai đoạn I, không xếp vào giai đoạn II như trước kia. Dịch rửa ổ bụng dương tính được ghi nhận riêng, không làm thay đổi giai đoạn."], "bullets": []}, {"heading": "6.1. Chỉ định điều trị: cần phải cân nhắc kỹ theo thể trạng và giai đoạn.", "paragraphs": [], "bullets": ["- Theo giai đoạn (Theo phân loại FIGO):", "+ Giai đoạn 1: cắt tử cung toàn phần và hai phần phụ, vét hạch chậu và hạch cạnh động mạch chủ, nếu hạch xâm nhiễm thì xạ trị ngoài. U biệt hoá cao thì bổ sung nội tiết.", "+ Giai đoạn 2: tia xạ tại chỗ và phẫu thuật cắt tử cung toàn phần rộng rãi và lấy hạch. Sau 4-6 tuần thì tia xạ ngoài nếu hạch xâm nhiễm.", "+ Giai đoạn 3: Nếu mổ được thì cắt bỏ và xạ trị, nếu không thì xạ trị bằng kim radium đặt tại chỗ và hormon liệu pháp kết hợp (thực hiện tại chuyên khoa ung thư).", "+ Giai đoạn 4: Điều trị triệu chứng bằng progestatif. Trong trường hợp tái phát ở mỏm cắt âm đạo thì đặt kim Radium."]}, {"heading": "6.2. Điều trị phẫu thuật", "paragraphs": ["Phẫu thuật là phương pháp cơ bản. Tuỳ theo trường hợp mà chỉ định cắt tử cung toàn phần, cắt hai phần phụ, hoặc cắt tử cung rộng rãi có nạo hạch, cắt hết mạc nối lớn, nên cắt tử cung qua đường bụng để quan sát rõ các tổn thương phối hợp."], "bullets": []}, {"heading": "6.3. Tia xạ", "paragraphs": [], "bullets": ["- Chỉ định đối với ung thư giai đoạn muộn hoặc điều trị hỗ trợ sau phẫu thuật", "- Radium, Cobalt tại chỗ (thuộc chuyên khoa ung thư)."]}, {"heading": "6.4. Hormon liệu pháp", "paragraphs": [], "bullets": ["- Progestatif liều cao (tuỳ theo các thụ thể) như dùng Depoprovera 150mg x 3 lần/tuần. Hiệu quả không rõ ràng, thường chỉ định trong trường hợp dịch rửa phúc mạc dương tính."]}, {"heading": "6.5. Hoá liệu pháp: ít hiệu quả, chỉ dùng khi tái phát ở phụ nữ trẻ.", "paragraphs": [], "bullets": ["- 5 Fluoro-uracile và canxi folinat (giúp giảm độc tính của 5-FU).", "- Adrimycine."]}, {"heading": "6.6. Kết quả điều trị", "paragraphs": ["70% tái phát xảy ra trong 2 năm đầu sau điều trị."], "bullets": ["+ Ở giai đoạn I có # 90% sống sau 5 năm.", "+ Ở giai đoạn II thì có # 75%.", "+ Giai đoạn III có # 30%.", "+ Giai đoạn IV có ít hơn 9% sống sau 5 năm."]}], "raw_text": "UNG THƯ NIÊM MẠC TỬ CUNG\nTS. Bùi Minh Tiến\n\nMục tiêu học tập\n1. Mô tả được các yếu tố nguy cơ của ung thư niêm mạc tử cung.\n2. Giải thích được sự lan tràn của ung thư niêm mạc tử cung.\n3. Mô tả được các triệu chứng chẩn đoán của bệnh.\n4. Lựa chọn được các phương thức điều trị.\n1. ĐẠI CƯƠNG\nUng thư niêm mạc tử cung là các khối u phát triển từ niêm mạc tử cung, là một loại ung thư thường gặp ở người lớn tuổi. Có hơn 80% bệnh nhân ung thư niêm mạc tử cung gặp ở người mãn kinh, trong đó có khoảng 95% có nguồn gốc từ biểu mô tuyến của nội mạc tử cung. So sánh với ung thư cổ tử cung: cứ 4 case ung thư cổ tử cung có 1 case  ung thư niêm mạc tử cung\n\n2. CÁC YẾU TỐ NGUY CƠ\nTuổi: từ  50-70\nKhông sinh đẻ hoặc đẻ ít\nBéo phì (trên 25kg so với bình thường)\nĐái tháo đường.\nCao huyết áp.\nBệnh lý ở tử cung: quá sản nội mạc tử cung.\nCó kinh sớm, mãn kinh muộn: sau 55 tuổi.\nDùng estrogen đơn thuần, kéo dài.\nPhụ nữ không bao giờ mang thai, không cho con bú.\nRối loạn chức năng buồng trứng: tồn tại dai dẳng các nang bọc noãn làm cho niêm mạc tử cung luôn bị kích thích, tăng sinh gây tình trạng quá sản, loạn sản.\nHội chứng buồng trứng đa nang: vòng kinh không phóng noãn biểu hiện kinh thưa, vô kinh, không phóng noãn, siêu âm buồng trứng có nhiều nang cùng lứa tuổi xếp theo hình tràng hạt.\nCường vỏ thượng thận.\nTiền sử ung thư buồng trứng, ung thư vú và ung thư đại tràng.\n\n3. GIẢI PHẪU BỆNH\n3.1. Đại thể\nLòng tử cung có một khối mềm sùi dễ vỡ, có thể dạng như polyp mọc lấn vào buồng tử cung.\n\n\nHình 1. Hình ảnh ung thư niêm mạc tử cung\n\n3.2. Vi thể\nLà một loại ung thư tuyến (adenocarcinom), từ đó tiên lượng bệnh tuỳ thuộc vào mức độ biệt hoá của tế bào:\n- Grade 1: Hình ảnh của quá sản không điển hình, song có các tế bào ác tính, lớp cơ không bị xâm lấn. Tiên lượng tốt.\n- Grade 2: Các tuyến nhỏ hơn, ép sát vào nhau, lớp cơ mới bị xâm lấn, ở đó thấy rõ các tế bào ác tính. Biệt hoá trung bình.\n- Grade 3: Có thể thấy các cấu trúc tuyến nhỏ và các tế bào không biệt hoá. Loại ác tính nhất.\n3.3. Sự lan tràn của ung thư niêm mạc tử cung\nUng thư niêm mạc tử cung không lan tràn nhanh bằng ung thư cổ tử cung, vì cơ tử cung là một hàng rào có tác dụng khá tốt.\n3.3.1. Lan tràn tại chỗ: Sự xâm lấn chậm vào lớp cơ tử cung là cách xâm lấn hay gặp nhất. Nó có thể làm cho tử cung to lên một cách đáng kể.\n3.3.2. Lan tràn theo đường bạch huyết:\nCó khoảng từ 30- 40% ung thư lan tràn theo đường này, ở thân tử cung tổ chức ung thư phát triển xuống eo tử cung rồi xuống đáy dây chằng rộng, đến hệ thống hạch chậu trong, chậu ngoài và xa hơn nữa; sự lan tràn này dể xảy ra hơn khi khối u bị thoái triển và thành tử cung bị ung thư xâm lấn sâu.\n3.3.3. Lan theo đường dẫn tự nhiên (vòi tử cung)\nCác tế bào ung thư có thể đi theo vòi tử cung, theo cùng đường tràn vào trong ổ phúc mạc của máu kinh, điều này giải thích cho các trường hợp di căn buồng trứng đơn thuần.\n3.3.4. Lan tràn đến các tạng khác trong ổ bụng: hiếm gặp, có thể thấy di căn đến gan, phổi.\n3.3.5. Lan tràn theo đường tĩnh mạch: ít thấy.\n\n\n\n\n\n\n\n\nHình 2. Bệnh phẩm đại thể ung thư niêm mạc tử cung giai đoạn I (trái)\nvà giai đoạn II (phải)\n4. TRIỆU CHỨNG VÀ CHẨN ĐOÁN\nThường bệnh nhân đến khám vì:\n4.1. Ra máu bất thường (# 95% các trường hợp)\nRa máu ở người đã mãn kinh là một dấu hiệu có giá trị, có khi ra máu trong thời kỳ tiền mãn kinh, làm cho ta lầm với những rối loạn của thời kỳ này. Ra máu thường kèm theo khí hư nhiều, hôi.\nĐau: tiến triển dần. Lúc đầu cảm giác tức nặng vùng bụng dưới, giai đoạn muộn khi lan ra các tạng trong hố chậu đau càng nhiều.\n4.2. Hỏi bệnh\nCó thể phát hiện được các yếu tố nguy cơ hiện tại cũng như trong tiền sử.\n4.3. Khám thực thể\n- Khám mỏ vịt: Cũng có khi thấy âm đạo bình thường, hơi teo ở những người mãn kinh. Thường thì khí hư nhiều, nhầy loãng, hôi, có khi là mủ. Trong trường hợp này thường kèm theo đau và cảm giác nặng nề ở vùng hạ vị.\n- Khám âm đạo bằng tay, tử cung thường có kích thước bình thường, cũng có thể hơi to và mềm. Có khi phát hiện u xơ tử cung đi kèm. Di động tử cung đau thường có ứ mủ buồng tử cung, di động tử cung cũng phụ thuộc vào từng giai đoạn lan tràn.\n- Toàn thân: nếu có ứ mủ buồng tử cung có thể sốt.\n- Khám hạch: khám hệ thống hạch ngoại biên: bẹn, thượng đòn, nách có thể thấy hạch\n4.4. Xét nghiệm:\n4.4.1. Tế bào bệnh học: Bệnh phẩm là dịch hút từ buồng tử cung. Đây là dấu hiệu quyết định chẩn đoán.\n- Thuận lợi: Dễ thực hiện, ít có biến chứng.\n- Không thuận lợi: Những trường hợp ung thư giai đoạn sớm có thể khó phát hiện.\n4.4.2. Chụp buồng tử cung:\nChỉ bơm thuốc cản quang với áp lực nhẹ đủ thuốc ngấm trong buồng tử cung mà không cần lan ra hai vòi trứng, có thể thấy hình ảnh khuyết, bờ không đều, nham nhở, buồng tử cung lớn, có hình ảnh đọng dịch. Thủ thuật này hiện nay ít được chỉ định.\n4.4.3. Soi buồng tử cung:\nQuan sát trực tiếp hình ảnh nội mạc tử cung cũng như thương tổn một cách chính xác như nụ sùi, vùng loét hoại tử chảy máu, hoặc hình ảnh quá sản nội mạc tử cung chạm vào dễ chảy máu, xác định được độ lan rộng và giúp định vị vùng sinh thiết.\n- Thuận lợi: Dễ làm, có thể tiến hành nhanh ở phòng khám bệnh.\n- Không thuận lợi: Phương tiện đắt.\n4.4.4. Nạo sinh thiết toàn bộ tử cung:\nTiến hành cẩn thận, đề phòng thủng. Tốt nhất nên làm từ ngoài vào trong và để riêng bệnh phẩm: ống cổ tử cung và buồng tử cung. Sử dụng thìa nạo hoặc ống hút Novak. Kết quả sinh thiết giúp phân loại mô học.\n4.4.5. Siêu âm:\nNhất là siêu âm theo đường âm đạo cho hình ảnh thực thể của tử cung, nội mạc dày hoặc đánh giá độ lan tràn và bề dày lớp cơ. đồng thời siêu âm cũng giúp khảo sát các bệnh lý phối hợp như u xơ tử cung, u nang buồng trứng...\n4.4.6. Chụp cắt lớp:\nLà một phương pháp khá hữu hiệu để xác định mức độ xâm lấn và lan tràn của ung thư, nhất là ở các giai đoạn muộn. Phương pháp này được chỉ định trong những trường hợp cần thiết phải chẩn đoán phân biệt.\nCần phải đánh giá tình trạng ung thư tuyến khác có thể kèm theo như ung thư vú hoặc đại tràng.\n5. CÁC GIAI ĐOẠN LÂM SÀNG\nTheo Hiệp hội ung thư Hoa Kỳ AJCC và FIGO (Fédération Internationale de Gynécologie et Obsstétrique) 2010, ung thư niêm mạc tử cung được phân loại như sau: U khu trú ở thân tử cung\nGiai đoạn I: U khu trú ở thân tử cung\nIA : : Tổn thương giới hạn ở niêm mạc tử cung (bề mặt) hoặc tổn thương ăn sâu vào lớp cơ tử cung <50%\nIB : tổn thương ăn sâu vào lớp cơ tử cung >50%\nGiai đoạn II: U xâm lấn tới mô đệm cổ tử cung nhưng chưa lan ra khỏi tử cung\n\nHình 3. Phân độ ung thư niêm mạc tử cung theo FIGO 2010- giai đoạn I và II\nGiai đoạn III: U lan ra ngoài tử cung nhưng còn khu trú trong khung chậu\nIIIA: tổn thương xâm nhiễm vào thanh mạc hay phần phụ hay tế bào phúc mạc dương tính\nIIIB: tổn thương di căn âm đạo\nIIIC1: Di căn tới hạch chậu (hạch chậu dương tính)\nIIIC2: Di căn tới hạch cạnh động mạch chủ, có/hoặc không kèm theo hạch chậu dương tính.\n\nHình 4. Phân độ ung thư niêm mạc tử cung theo FIGO 2010- giai đoạn III\nGiai đoạn IV: U xâm lấn tới niêm mạc bàng quang và/hoặc niêm mạc ruột và/hoặc di căn xa\nIVA: tổn thương ung thư xâm nhiễm vào bàng quang và/hoặc ruột\nIVB: ung thư di căn xa bao gồm di căn hạch trong ổ bụng hay hạch bẹn  hoặc phổi, gan, xương. (Ngoại trừ di căn tới hạch cạnh động mạch chủ, âm đạo, thanh mạc tiểu khung hoặc phần phụ)\n\nHình 5. Phân độ ung thư niêm mạc tử cung theo FIGO 2010- giai đoạn IV\nGhi chú: Xâm lấn tuyến nội mạc cổ tử cung chỉ xếp vào giai đoạn I, không xếp vào giai đoạn II như trước kia. Dịch rửa ổ bụng dương tính được ghi nhận riêng, không làm thay đổi giai đoạn.\n6. ĐIỀU TRỊ\n6.1. Chỉ định điều trị: cần phải cân nhắc kỹ theo thể trạng và giai đoạn.\n- Theo giai đoạn (Theo phân loại FIGO):\n+ Giai đoạn 1: cắt tử cung toàn phần và hai phần phụ, vét hạch chậu và hạch cạnh động mạch chủ, nếu hạch xâm nhiễm thì xạ trị ngoài. U biệt hoá cao thì bổ sung nội tiết.\n+ Giai đoạn 2: tia xạ tại chỗ và phẫu thuật cắt tử cung toàn phần rộng rãi và lấy hạch. Sau 4-6 tuần thì tia xạ ngoài nếu hạch xâm nhiễm.\n+ Giai đoạn 3: Nếu mổ được thì cắt bỏ và xạ trị, nếu không thì xạ trị bằng kim radium đặt tại chỗ và hormon liệu pháp kết hợp (thực hiện tại chuyên khoa ung thư).\n+ Giai đoạn 4: Điều trị triệu chứng bằng progestatif. Trong trường hợp tái phát ở mỏm cắt âm đạo thì đặt kim Radium.\n6.2. Điều trị phẫu thuật\nPhẫu thuật là phương pháp cơ bản. Tuỳ theo trường hợp mà chỉ định cắt tử cung toàn phần, cắt hai phần phụ, hoặc cắt tử cung rộng rãi có nạo hạch, cắt hết mạc nối lớn, nên cắt tử cung qua đường bụng để quan sát rõ các tổn thương phối hợp.\n6.3. Tia xạ\n- Chỉ định đối với ung thư giai đoạn muộn hoặc điều trị hỗ trợ sau phẫu thuật\n- Radium, Cobalt tại chỗ (thuộc chuyên khoa ung thư).\n6.4. Hormon liệu pháp\n- Progestatif liều cao (tuỳ theo các thụ thể) như dùng Depoprovera 150mg x 3 lần/tuần. Hiệu quả không rõ ràng, thường chỉ định trong trường hợp dịch rửa phúc mạc dương tính.\n6.5. Hoá liệu pháp: ít hiệu quả, chỉ dùng khi tái phát ở phụ nữ trẻ.\n- 5 Fluoro-uracile và canxi folinat (giúp giảm độc tính của 5-FU).\n- Adrimycine.\n6.6. Kết quả điều trị\n+ Ở giai đoạn I có # 90% sống sau 5 năm.\n+ Ở giai đoạn II thì có # 75%.\n+ Giai đoạn III có # 30%.\n+ Giai đoạn IV có ít hơn 9% sống sau 5 năm.\n70% tái phát xảy ra trong 2 năm đầu sau điều trị.\nCâu hỏi:\n1. Mô tả các yếu tố nguy cơ của ung thư niêm mạc tử cung?\n2. Mô tả  triệu chứng chẩn đoán ung thư niêm mạc tử cung?\n3. Trình bày chỉ định và  các phương pháp điều trị ung thư niêm mạc tử cung?", "priority": "Trung bình"}, {"id": "SK-42", "chapter": "Chương 3. Phụ khoa", "folder": "03_Phu_khoa", "title": "Ung thư nguyên bào nuôi", "author": "Ths. Đinh Văn Hoành", "word_count": 1538, "line_count": 107, "key_numbers": ["0,3mg", "0,5 mg", "100.000 IU", "2 tháng", "2 tuần", "20.000 IU", "25 IU", "3 tháng", "4 tháng", "5 ngày", "500 IU", "5IU", "6 tháng"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["UNG THƯ nguyên bào nuôi"], "bullets": []}, {"heading": "1. Định nghĩa", "paragraphs": ["Bệnh nguyên bào nuôi là sự tăng sinh bất thường của nguyên bào nuôi có liên quan đến thai nghén. U nguyên bào nuôi là bệnh ác tính của nguyên bào nuôi, có tính chất xâm lấn và khả năng chế tiết hCG (human chorionic gonadotropin). U nguyên bào nuôi bao gồm ung thư nguyên bào nuôi và chửa trứng xâm nhập."], "bullets": []}, {"heading": "2. Dịch tễ học", "paragraphs": ["Ung thư nguyên bào nuôi tần suất 1/40.000 phụ nữ có thai, gần 50% sau chửa trứng, 25% sau sẩy thai, 22% sau đẻ thường và sau đẻ thường 2ư3%. Bệnh nguyên bào nuôi có tỉ lệ 1/1.200 thai nghén ở Mỹ và 1/120 thai nghén ở vùng Đông Nam á.", "Tỉ lệ bệnh tăng lên ở những phụ nữ có mức sống thấp, ở những nước đang phát triển.", "Phụ nữ lớn tuổi có nguy cơ cao hơn."], "bullets": []}, {"heading": "3. Giải phẫu bệnh", "paragraphs": ["Có biểu hiện quá sản và nghịch sản của nguyên bào nuôi, không nhìn thấy gai rau, có hiện tượng chảy máu hoại tử, xâm lấn trực tiếp vào cơ tử cung, lan theo đường máu tới các cơ quan khác. Vì vậy di căn hay gặp nhất là ở phổi, gan, não, tiểu khung âm đạo, lách, ruột, thận.", "Đôi khi khó phân biệt giữa ung thư nguyên bào nuôi và chửa trứng xâm nhập về lâm sàng mà chỉ phân biệt mà chỉ phân biệt được trên phương diện giải phẫu bệnh học. Chửa trứng xâm nhập là khối u lành tính phát triển sau chửa trứng nó xâm lấn vào lớp cơ tử cung do sự lan rộng trực tiếp hoặc theo đường tĩnh mạch, tỉ lệ di căn xa của nó khoảng 15%, hay gặp nhất là phổi và âm đạo. Đặc điểm của khối u là còn có hình ảnh gai rau phù nề cùng với sự quá sản và hay gặp nhất là loạn sản của nguyên bào nuôi ở ngoài buồng tử cung."], "bullets": []}, {"heading": "4.4.\tKhám phụ khoa:", "paragraphs": [], "bullets": ["+ Tử cung: co hồi chậm, to hơn bình thường, mềm có thể sờ thấy nhân ung thư nguyên bào nuôi nổi gồ trên mặt tử cung.", "+ Sờ thấy nang hoàng tuyến ở một hoặc hai bên.", "+ Nhân di căn âm đạo thường hay gặp ở thành trước, tiền đình. Nhân màu tím, mềm, không đau, chạm vào dễ chảy máu."]}, {"heading": "4.5.\tXét nghiệm hCG (quyết định chẩn đoán).", "paragraphs": ["hCG nước tiểu: Phản ứng Galli manini, Quick stick 25 IU.", "1 đơn vị ếch tương đương 30 ư 35 đơn vị quốc tế.", "( hCG huyÕt thanh.", "Chẩn đoán dương tính khi:", "ư\tTrong hai tuần, nồng độ ( hCG ở tuần sau cao hơn tuần trước.", "ư\tTrong ba tuần liên tiếp nồng độ ( hCG không giảm.", "ư\tBốn tuần sau nạo ( hCG > 20.000 IU/L.", "ư\tHai tháng sau nạo ( hCG > 500 IU/L.", "ư\tSáu tháng sau nạo ( hCG > 5IU/L."], "bullets": []}, {"heading": "4.6\tXét nghiệm giải phẫu bệnh lý", "paragraphs": ["Bệnh phẩm ở tử cung hoặc nhân di căn âm đạo: chửa trứng xâm nhập hoặc ung thư nguyên bào nuôi"], "bullets": []}, {"heading": "4.7. Những khám nghiệm cận lâm sàng khác:", "paragraphs": [], "bullets": ["+ X quang phổi: nhân di căn có hình ảnh điển hình giống như bóng bay.", "+ Siêu âm: Có thể thấy hình ảnh nhân ung thư nguyên bào nuôi trong cơ tử cung, nhân di căn ở gan; thận.", "+ Chụp cắt lớp để phát hiện nhân di căn não."]}, {"heading": "5.\tPhân loại tiên lượng ung thư nguyên bào nuôi", "paragraphs": ["* Ung thư nguyên bào nuôi không có di căn.", "* Ung thư nguyên bào nuôi có di căn.", "Tiên lượng tốt (nguy cơ thấp)", "1. hCG n­íc tiÓu < 100.000 IU/24 h; hCG huyÕt thanh < 400.000 mIU/ml."], "bullets": []}, {"heading": "5. Không phải sau đẻ thường.", "paragraphs": ["Tiên lượng xấu (nguy cơ cao)", "1. hCG n­íc tiÓu > 100.000 IU/24 h; hCG huyÕt thanh > 400.000 mIU/ml."], "bullets": []}, {"heading": "6.\tPhòng bệnh và điều trị", "paragraphs": ["Vì nguyên nhân của bệnh chưa rõ nên nguyên tắc chung của phòng bệnh là theo dõi sát những bệnh nhân sau nạo trứng để chẩn đoán sớm và điều trị kịp thời.", "Có nhiều phương pháp điều trị, thường phối hợp các phương pháp nhằm mục đích:", "ư Loại trừ tổ chức ung thư tại chỗ.", "ư Diệt những tế bào ung thư đã di căn.", "Các phương pháp điều trị chính"], "bullets": []}, {"heading": "6.1.1. Cắt tử cung hoàn toàn: để loại bỏ ổ gốc ung thư nguyên bào nuôi, nhiều khi không có tổn thương ở tử cung người ta vẫn cắt tử cung. Cắt cả hai buồng trứng khi bệnh nhân trên 45 tuổi, dưới 45 tuổi cắt hay để lại hai buồng trứng là cân nhắc tuỳ từng trường hợp.", "paragraphs": ["Chỉ định cắt tử cung hoàn toàn đối với:", "ưNhững phụ nữ lớn tuổi, đủ con.", "ư Điều trị hoá chất không kết quả."], "bullets": []}, {"heading": "6.2. Điều trị hoá chất", "paragraphs": ["Chỉ định:", "ư Bệnh nhân trẻ tuổi.", "ư Còn có nguyện vọng sinh đẻ.", "ư Không có khả năng phẫu thuật.", "* Đơn trị liệu: Methotrexate hoặc Actinomycin D áp dụng trong trường hợp:", "Liều dùng:", "ư  Methotrexate (MTX) 0,3mg/kg/ngày x 5 ngày; nghỉ 7 ư10 ngày.", "ư  Actinomycin D  0,5 mg/kg/ngày x 5 ngày; nghỉ 7 ư10 ngày.", "* Đa trị liệu: dùng phối hợp nhiều loại hoá chất. áp dụng trong trường hợp:", "Theo dõi điều trị: trong đợt điều trị cần xét nghiệm:", "ư Công thức máu, công thức bạch hàng ngày.", "ư Chức năng gan, thận.", "ư Đường huyết.", "ư Định lượng hCG", "Triệu chứng nhiễm độc hoá chất MTX:", "ư Viêm da, lở loét niêm mạc miệng, lưỡi; rụng tóc; ỉa chảy...", "ư Xét nghiệm: số lượng bạch cầu < 3.000/mm3 ; bach cầu đa nhân trung tính dưới 1.500/ mm3, tiểu cầu dưới 100.000/ mm3, transaminase huyết thanh tăng cao.", "Khi có triệu chứng nhiễm độc thì phải ngừng điều trị hoá chất ngay.", "Triệu chứng kháng thuốc: sau mỗi đợt điều trị, nồng độ hCG không giảm hoặc tăng, xuất hiện thêm nhân di căn.", "Nếu có biểu hiện kháng thuốc phải thay đổi hoặc phối hợp hoá chất, dùng các biện pháp khác như phẫu thuật, tia xạ để loại bỏ ung thư tại chỗ hoặc di căn."], "bullets": ["+ Ung thư nguyên bào nuôi không có nhân di căn.", "+ Ung thư nguyên bào nuôi có nhân di căn nhưng nguy cơ thấp.", "+ Ung thư nguyên bào nuôi có di căn ở nhóm nguy cơ cao.", "+ Điều trị với một loại hoá chất thất bại."]}, {"heading": "6.3.\tĐiều trị quang tuyến:", "paragraphs": ["Thường dùng tia X hoặc cobalt rọi vào vùng hạ vị hoặc âm đạo để hạn chế sự phát triển của tế bào ung thư tại chỗ hoặc di căn.", "Chỉ định: ung thư nguyên bào nuôi lan tràn trong hố chậu không mổ được."], "bullets": []}, {"heading": "7.1.\tKhỏi bệnh", "paragraphs": ["ư Ba tuần liên tiếp xét nghiệm hCG âm tính.", "ư Xét nghiệm hCG 2 tuần một lần trong 3 tháng; rồi tiếp mỗi tháng một lần trong 3 tháng; tiếp theo 2 tháng một lần trong 6 tháng; rồi 6 tháng một lần.", "ư Khám phụ khoa.", "ư Chụp X quang phổi 3 tháng một lần trong một năm.", "ư Tránh thai trong vòng 2 năm."], "bullets": []}, {"heading": "7.2.\tTỷ lệ tái phát", "paragraphs": ["ư Ung thư nguyên bào nuôi không có di căn: 2%.", "ư Ung thư nguyên bào nuôi có di căn, tiên lượng tốt: 5%.", "ư Ung thư nguyên bào nuôi có di căn, tiên lượng tồi: 21%."], "bullets": []}, {"heading": "Câu hỏi:", "paragraphs": ["1: Trình bày triệu chứng lâm sàng, cận lâm sàng để chẩn đoán xác định, chẩn đoán phân biệt bệnh ung thư nguyên bào nuôi?", "2: Trình bày  chỉ định, cách điều trị hoá chất với bệnh ung thư nguyên bào nuôi?"], "bullets": []}], "raw_text": "UNG THƯ nguyên bào nuôi\nMục tiêu học tập:\n1.\tChẩn đoán được ung thư nguyên bào nuôi qua các triệu chứng lâm sàng và cận  lâm sàng.\n2.\tTrình bày được nguyên tắc xử trí chung cho u nguyên bào nuôi.\n1. Định nghĩa\nBệnh nguyên bào nuôi là sự tăng sinh bất thường của nguyên bào nuôi có liên quan đến thai nghén. U nguyên bào nuôi là bệnh ác tính của nguyên bào nuôi, có tính chất xâm lấn và khả năng chế tiết hCG (human chorionic gonadotropin). U nguyên bào nuôi bao gồm ung thư nguyên bào nuôi và chửa trứng xâm nhập.\n2. Dịch tễ học\nUng thư nguyên bào nuôi tần suất 1/40.000 phụ nữ có thai, gần 50% sau chửa trứng, 25% sau sẩy thai, 22% sau đẻ thường và sau đẻ thường 2ư3%. Bệnh nguyên bào nuôi có tỉ lệ 1/1.200 thai nghén ở Mỹ và 1/120 thai nghén ở vùng Đông Nam á.\nTỉ lệ bệnh tăng lên ở những phụ nữ có mức sống thấp, ở những nước đang phát triển.\nPhụ nữ lớn tuổi có nguy cơ cao hơn.\n3. Giải phẫu bệnh\nCó biểu hiện quá sản và nghịch sản của nguyên bào nuôi, không nhìn thấy gai rau, có hiện tượng chảy máu hoại tử, xâm lấn trực tiếp vào cơ tử cung, lan theo đường máu tới các cơ quan khác. Vì vậy di căn hay gặp nhất là ở phổi, gan, não, tiểu khung âm đạo, lách, ruột, thận.\nĐôi khi khó phân biệt giữa ung thư nguyên bào nuôi và chửa trứng xâm nhập về lâm sàng mà chỉ phân biệt mà chỉ phân biệt được trên phương diện giải phẫu bệnh học. Chửa trứng xâm nhập là khối u lành tính phát triển sau chửa trứng nó xâm lấn vào lớp cơ tử cung do sự lan rộng trực tiếp hoặc theo đường tĩnh mạch, tỉ lệ di căn xa của nó khoảng 15%, hay gặp nhất là phổi và âm đạo. Đặc điểm của khối u là còn có hình ảnh gai rau phù nề cùng với sự quá sản và hay gặp nhất là loạn sản của nguyên bào nuôi ở ngoài buồng tử cung.\n4. Chẩn đoán:\n4.1. Có tiền sử liên quan đến thai nghén: chửa trứng, chửa ngoài tử cung, sẩy thai, đẻ thường.\n4.2.\tRong huyết: do khối u nguyên bào nuôi gây thương tổn trực tiếp tại tử cung, thời gian xuất hiện có thể tương đối ngắn hoặc dài sau thai nghén.\n4.3.\tCó triệu chứng cơ năng do khối u di căn các phủ tạng khác: ho; đi ngoài; tiểu tiện ra máu, nhức đầu...\n4.4.\tKhám phụ khoa:\n+ Tử cung: co hồi chậm, to hơn bình thường, mềm có thể sờ thấy nhân ung thư nguyên bào nuôi nổi gồ trên mặt tử cung.\n+ Sờ thấy nang hoàng tuyến ở một hoặc hai bên.\n+ Nhân di căn âm đạo thường hay gặp ở thành trước, tiền đình. Nhân màu tím, mềm, không đau, chạm vào dễ chảy máu.\n4.5.\tXét nghiệm hCG (quyết định chẩn đoán).\nhCG nước tiểu: Phản ứng Galli manini, Quick stick 25 IU.\n1 đơn vị ếch tương đương 30 ư 35 đơn vị quốc tế.\n( hCG huyÕt thanh.\nChẩn đoán dương tính khi:\nư\tTrong hai tuần, nồng độ ( hCG ở tuần sau cao hơn tuần trước.\nư\tTrong ba tuần liên tiếp nồng độ ( hCG không giảm.\nư\tBốn tuần sau nạo ( hCG > 20.000 IU/L.\nư\tHai tháng sau nạo ( hCG > 500 IU/L.\nư\tSáu tháng sau nạo ( hCG > 5IU/L.\n4.6\tXét nghiệm giải phẫu bệnh lý\nBệnh phẩm ở tử cung hoặc nhân di căn âm đạo: chửa trứng xâm nhập hoặc ung thư nguyên bào nuôi\n4.7. Những khám nghiệm cận lâm sàng khác:\n+ X quang phổi: nhân di căn có hình ảnh điển hình giống như bóng bay.\n+ Siêu âm: Có thể thấy hình ảnh nhân ung thư nguyên bào nuôi trong cơ tử cung, nhân di căn ở gan; thận.\n+ Chụp cắt lớp để phát hiện nhân di căn não.\n5.\tPhân loại tiên lượng ung thư nguyên bào nuôi\n* Ung thư nguyên bào nuôi không có di căn.\n* Ung thư nguyên bào nuôi có di căn.\nTiên lượng tốt (nguy cơ thấp)\n1. hCG n­íc tiÓu < 100.000 IU/24 h; hCG huyÕt thanh < 400.000 mIU/ml.\n2. Triệu chứng xuất hiện dưới 4 tháng.\n3. Không có di căn não, gan.\n4. Không điều trị hoá chất trước đó.\n5. Không phải sau đẻ thường.\nTiên lượng xấu (nguy cơ cao)\n1. hCG n­íc tiÓu > 100.000 IU/24 h; hCG huyÕt thanh > 400.000 mIU/ml.\n2. Triệu chứng xuất hiện dưới 4 tháng.\n3. Có di căn não, gan.\n4. Có điều trị hoá chất trước đó.\n5. Sau đẻ thường.\n6.\tPhòng bệnh và điều trị\nVì nguyên nhân của bệnh chưa rõ nên nguyên tắc chung của phòng bệnh là theo dõi sát những bệnh nhân sau nạo trứng để chẩn đoán sớm và điều trị kịp thời.\nCó nhiều phương pháp điều trị, thường phối hợp các phương pháp nhằm mục đích:\nư Loại trừ tổ chức ung thư tại chỗ.\nư Diệt những tế bào ung thư đã di căn.\nCác phương pháp điều trị chính\n6.1.\tPhÉu thuËt\n6.1.1. Cắt tử cung hoàn toàn: để loại bỏ ổ gốc ung thư nguyên bào nuôi, nhiều khi không có tổn thương ở tử cung người ta vẫn cắt tử cung. Cắt cả hai buồng trứng khi bệnh nhân trên 45 tuổi, dưới 45 tuổi cắt hay để lại hai buồng trứng là cân nhắc tuỳ từng trường hợp.\nChỉ định cắt tử cung hoàn toàn đối với:\nưNhững phụ nữ lớn tuổi, đủ con.\nư Điều trị hoá chất không kết quả.\n6.1.2. Mổ lấy nhân di căn: nhân di căn âm đạo thường lấy dễ, trừ trường hợp di căn sát niệu đạo, trực tràng. Di căn phổi nếu chỉ có ít nhân ở một thuỳ hay ở một bên phổi có thể cắt phổi để loại bỏ nhân di căn.\n6.2. Điều trị hoá chất\nChỉ định:\nư Bệnh nhân trẻ tuổi.\nư Còn có nguyện vọng sinh đẻ.\nư Không có khả năng phẫu thuật.\n* Đơn trị liệu: Methotrexate hoặc Actinomycin D áp dụng trong trường hợp:\n+ Ung thư nguyên bào nuôi không có nhân di căn.\n+ Ung thư nguyên bào nuôi có nhân di căn nhưng nguy cơ thấp.\nLiều dùng:\nư  Methotrexate (MTX) 0,3mg/kg/ngày x 5 ngày; nghỉ 7 ư10 ngày.\nư  Actinomycin D  0,5 mg/kg/ngày x 5 ngày; nghỉ 7 ư10 ngày.\n* Đa trị liệu: dùng phối hợp nhiều loại hoá chất. áp dụng trong trường hợp:\n+ Ung thư nguyên bào nuôi có di căn ở nhóm nguy cơ cao.\n+ Điều trị với một loại hoá chất thất bại.\nTheo dõi điều trị: trong đợt điều trị cần xét nghiệm:\nư Công thức máu, công thức bạch hàng ngày.\nư Chức năng gan, thận.\nư Đường huyết.\nư Định lượng hCG\nTriệu chứng nhiễm độc hoá chất MTX:\nư Viêm da, lở loét niêm mạc miệng, lưỡi; rụng tóc; ỉa chảy...\nư Xét nghiệm: số lượng bạch cầu < 3.000/mm3 ; bach cầu đa nhân trung tính dưới 1.500/ mm3, tiểu cầu dưới 100.000/ mm3, transaminase huyết thanh tăng cao.\nKhi có triệu chứng nhiễm độc thì phải ngừng điều trị hoá chất ngay.\nTriệu chứng kháng thuốc: sau mỗi đợt điều trị, nồng độ hCG không giảm hoặc tăng, xuất hiện thêm nhân di căn.\nNếu có biểu hiện kháng thuốc phải thay đổi hoặc phối hợp hoá chất, dùng các biện pháp khác như phẫu thuật, tia xạ để loại bỏ ung thư tại chỗ hoặc di căn.\n6.3.\tĐiều trị quang tuyến:\nThường dùng tia X hoặc cobalt rọi vào vùng hạ vị hoặc âm đạo để hạn chế sự phát triển của tế bào ung thư tại chỗ hoặc di căn.\nChỉ định: ung thư nguyên bào nuôi lan tràn trong hố chậu không mổ được.\n\n7.\tTiêu chuẩn khỏi bệnh và theo dõi sau điều trị\n7.1.\tKhỏi bệnh\nư Ba tuần liên tiếp xét nghiệm hCG âm tính.\nư Xét nghiệm hCG 2 tuần một lần trong 3 tháng; rồi tiếp mỗi tháng một lần trong 3 tháng; tiếp theo 2 tháng một lần trong 6 tháng; rồi 6 tháng một lần.\nư Khám phụ khoa.\nư Chụp X quang phổi 3 tháng một lần trong một năm.\nư Tránh thai trong vòng 2 năm.\n7.2.\tTỷ lệ tái phát\nư Ung thư nguyên bào nuôi không có di căn: 2%.\nư Ung thư nguyên bào nuôi có di căn, tiên lượng tốt: 5%.\nư Ung thư nguyên bào nuôi có di căn, tiên lượng tồi: 21%.\nCâu hỏi:\n1: Trình bày triệu chứng lâm sàng, cận lâm sàng để chẩn đoán xác định, chẩn đoán phân biệt bệnh ung thư nguyên bào nuôi?\n2: Trình bày  chỉ định, cách điều trị hoá chất với bệnh ung thư nguyên bào nuôi?", "priority": "Trung bình"}, {"id": "SK-43", "chapter": "Chương 3. Phụ khoa", "folder": "03_Phu_khoa", "title": "Bệnh của tuyến vú", "author": "Ths. Nguyễn Văn Hiền, TS. Phan Văn Cương", "word_count": 2331, "line_count": 231, "key_numbers": ["0,1 cm", "0,5 cm", "1 cm", "2 cm", "24 giờ", "2cm", "3 cm", "3 ngày", "5cm", "6 tháng", "8 ngày"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["Bệnh của tuyến vú", "Ths. Nguyễn Văn Hiền"], "bullets": []}, {"heading": "Mục tiêu học tập:", "paragraphs": ["Mô tả được các tổn thương giải phẫu bệnh trong bệnh vú lành tính.", "Phân biệt được các dạng lâm sàng trong bệnh vú lành tính.", "Xác định được cách xử trí cho từng trường hợp cụ thể.", "Tóm tắt được phân loại ung thư vú theo TNM", "Liệt kê được các yếu tố tiên lượng của ung thư vú", "Trình bày được chẩn đoán và đưa ra thái độ xử trí ung thư vú"], "bullets": []}, {"heading": "1. Nhắc lại giải phẫu tuyến vú:", "paragraphs": ["ư Tổ chức học:"], "bullets": ["+ Vó bao gåm: nóm, quÇng, bÇu.", "+ Khi đứng vú ngang khoang gian sườn 4.", "+ Vú trải dài từ xương ức đến đường nách trước, phần vú bám vào nách gọi là đuôi nách.", "+ Vú nằm trên cân của cơ ngực lớn.", "+ Vú được nâng đỡ bởi các dây chằng Cooper vào thành ngực.", "+ Da, tæ chøc d­íi da", "+ Tổ chức liên kết", "+ ống dẫn sữa", "+ TiÓu thuú vó, mèi vó: 10 -> 20 tiÓu thuú."]}, {"heading": "2. Sinh lý tuyÕn vó:", "paragraphs": [], "bullets": ["+ Dưới tác dụng của Estrogen làm cho tuyến vú phát triển : Số lượng, ống dẫn sữa và chất lượng.", "+ Trưởng thành: Dưới tác dụng của Estrogen, Progesteron, Cortisol, Insulin, Prolactin và các yếu tố tăng trưởng làm cho vú trưởng thành và được biệt hoá đầy đủ.", "+ Mãn kinh: Lượng Estrgen giảm làm tuyến vú teo nhỏ nhưng mô mỡ vẫn bình thường."]}, {"heading": "II. Các bệnh lành tính ở tuyến vú", "paragraphs": ["A. Các bệnh hay gặp"], "bullets": []}, {"heading": "1.1. Nguyên nhân", "paragraphs": ["Do mất cân bằng nội tiết: Estrogen và Progesteron."], "bullets": []}, {"heading": "1.2. Giải phẫu bệnh :", "paragraphs": [], "bullets": ["+ Các ống tuyến tăng sinh giãn ra và hình thành nang chế tiết thanh dịch.", "+ Các phân thuỳ: Tăng sinh tuyến và tăng sinh tuyến xơ cứng.", "+ Lớp đệm : Tăng sinh biểu mô và tăng sinh xơ cứng"]}, {"heading": "1.3. Triệu chứng chẩn đoán xác định", "paragraphs": ["* Mảng cứng :", "ư Xuất hiện trên vú hay gặp 1/4 trên ngoài, có thể ở một bên hoặc hai bên vú.", "ư Ranh giới không rõ.", "ư Có thể mảng này mất đi sau khi có kinh.", "* U nang :", "ư Khối u tròn, ranh giới rõ, di động, mật độ căng, ấn hơi đau, vị trí thường ở 1/4 trên ngoài.", "* Vú tăng về thể tích :", "ư Chọc hút làm tế bào học.", "Vú tăng về mật độ.", "Cản quang mờ tương ứng với vùng bị phù nề.", "Cản quang tròn tương ứng với vùng bị u nang.", "Vết Canxi hoá: to, nhỏ rải rác tập trung không thành nhóm.", "ư Siêu âm vú biết nang, mảng cứng.", "* Đau :", "ư Hội chứng tiến kinh : trước kinh 2ư>3 ngày đau vú. Nhưng vú không tăng về thể tích, sờ vú mềm không có u, mảng.", "ư Đau dây thần kinh liên sườn : Đau một bên cố định, không liên quan đến chu kỳ kinh.", "* U nang tuyến vú có thể nhầm với u xơ tuyến vú. Chẩn đoán bằng tế bào học.", "* Mảng cứng ở vú có thể nhầm với ung thư vú.", "ư Điều trị :", "ư chống viêm : kháng sinh, thuốc chống phù nề.", "ư Nội tiết : Dùng Progesteron vào giai đoạn 2 của vòng kinh: từ 3 ư> 6 tháng.", "ư Có nghi ngờ về mặt tế bào học (tế bào loạn sản)", "ư Điều trị nội khoa thất bại với mảng cứng tồn tại khá lâu."], "bullets": ["+ Hay gặp ở tuổi: 29 ư> 49 tuổi.", "+ Tỷ lệ : 34 ư> 50 %", "+ Cơ năng : Đau vú theo chu kỳ, xuất hiện khoảng 8 ngày trước kinh và sau khi hết kinh thì hết đau.", "+ Thùc thÓ :", "+ Cận lâm sàng:", "- XQ vó:", "+ Chẩn đoán phân biệt :", "+ Néi khoa :", "+ Ngoại khoa :"]}, {"heading": "2. U xơ tuyến vú", "paragraphs": ["ư Khối u phát triển từ mô liên kết giữa các tiểu thuỳ vú.", "ư Tuổi gặp : từ 20 ư> 49.", "ư Tỷ lệ : 19 %"], "bullets": []}, {"heading": "2.1. Triệu chứng", "paragraphs": ["ư U tròn, chắc, ranh giới rõ, di động dễ, ấn không đau, kích thước thay đổi từ 2 ư> 3 cm.", "ư Số lượng : Thường thì có 1 u nhưng có trường có nhiều u xuất hiện ở 1 hoặc 2 bên vú.", "ư Khối u xuất hiện không liên quan đến chu kỳ kinh.", "ư Chọc hút làm tế bào học. Xác định u lành tính hoặc ác tính.", "ư Siêu âm", "ư Điều trị : Là u xơ tuyến vú lành tính : phẫu thuật cắt bỏ u.", "B. Các bệnh lành tính ở tuyến vú ít gặp"], "bullets": ["+ Cơ năng : Nghèo nàn, tự sờ thấy u hoặc vô tình khám định kỳ phát hiện.", "+ Thùc thÓ :", "+ Cận lâm sàng :", "- Chôp  XQ"]}, {"heading": "1. Giãn ống dẫn sữa", "paragraphs": ["ư Tỷ lệ : 4 %"], "bullets": ["- Tuæi tõ : 35 -> 55."]}, {"heading": "1.1. Triệu chứng", "paragraphs": [], "bullets": ["+ Tiết dịch ở núm vú 1 bên hoặc 2 bên : vàng, trong.", "+ Các abcès quanh quầng vú tái phát là biến chứng của giãn ống dẫn sữa sau này.", "+ Cận lâm sàng : Xét nghiệm tế bào dịch ống dẫn sữa."]}, {"heading": "2. U nhú trong ống dẫn sữa", "paragraphs": ["ư Triệu chứng", "Xét nghiệm tế bào học dịch núm vú để loại trừ ung thư."], "bullets": ["+ Cơ năng : Tiết dịch hoặc chảy máu ở 1 hoặc 2 bên núm vú.", "+ Thực thể : ép xung quanh quầng vú có thể thấy dịch hoặc từ núm vú chảy ra.", "+ Cận lâm sàng : Chụp XQ vú để loại trừ ung thư vú", "+ Điều trị : Phẫu thuật là phương pháp chủ yếu."]}, {"heading": "4. Túi sữa", "paragraphs": ["ư Nguyên nhân :", "Do tắc ống dẫn sữa ở người đang nuôi con bú ư> u bọc chứa sữa gọi là túi sữa hay gọi là tắc sữa gây nang hoá.", "ư Tổn thương : U tròn, ranh giới rõ, di động.", "ư Cận lâm sàng : Tế bào học để chẩn đoán.", "ư Xử trí : Phẫu thuật ngoài thời kỳ cho con bú."], "bullets": []}, {"heading": "III.  Ung th­ tuyÕn vó", "paragraphs": ["ư Là 1 khối u ác tính, hay gặp ở các nước công nghiệp phát triển. Trong cỏc yếu tố nguy cơ gõy UT vỳ, yếu tố nổi bật nhất là tiền sử gia đỡnh cú người mắc UT vỳ, đặc biệt trong gia đỡnh cú từ 2 người mắc UT vỳ trở lờn ở lứa tuổi trẻ, đột biến gen ức chế u BRCAư1 và BRCAư2 nằm trờn nhiễm sắc thể 17 và 13. UT vỳ ở nam giới chiếm dưới 1% trong tổng số bệnh nhõn mắc căn bệnh này.", "ư Đứng thứ 2 sau ung thư cổ tử cung.", "ư Tuổi :   Bắt đầu ở lứa tuổi 40", "Hay gặp : 50 ư> 60 tuổi.", "ư Các yếu tố nguy cơ :", "A. Giải phẫu bệnh : 2 loại"], "bullets": ["- ChiÕm 30 % trong ung th­ phô khoa.", "+ Chưa sinh đẻ", "+ Thai nghÐn muén sau tuæi 30.", "+ Tiền sử điều trị K cổ tử cung, K dạ dày, K đại tràng.", "+ Yếu tố gia đình."]}, {"heading": "1. Ung thư biểu mô tại chỗ", "paragraphs": ["ư Thường không có dấu hiệu lâm sàng.", "ư Các tế bào ác tính ở bên trong của tiểu thuỳ vú hoặc ở bên trong của ống dẫn sữa chưa xâm lấn."], "bullets": []}, {"heading": "2. Ung th­ x©m lÊn", "paragraphs": ["ư Các tế bào ác tính xâm lấn vào mô liên kết quanh ống dẫn sữa và quanh tiểu thuỳ vú.", "B. TiÕn triÓn", "ư Ung thư có thể lan tràn theo hệ bạch huyết, hạch nách, nhóm cơ ngực, hạch thượng đòn, hạch vú trong.", "ư Di căn : Phổi, xương, gan. 1 gram khối u giải phóng vào tuần hoàn 3 triệu tế bào trong 24 giờ. Vì vậy, điều trị ung thư vú kết hợp tại chỗ và toàn thân.", "C. Phân loại :  Theo hệ T.N.M", "Theo phân loại TNM lần thứ 7 của UICC (Union International Contre le Cancer) và AJCC (American Joint Committee on Cancer) năm 2010.", "T: U nguyên phát", "Tx: \tKhông đánh giá được u nguyên phát", "To:\tKhông có dấu hiệu u nguyên phát", "Tis:\tCarcinoma tại chỗ, carcinoma nội ống (DCIS), carcinoma thùy tại chỗ (LCIS), hoặc bệnh Paget của núm vú nhưng không có u", "T1:\tĐường kính u ( 2 cm", "T1mic: Xâm lấn vi thể đường kính lớn nhất ( 0,1 cm.", "T1a:  \tU có đường kính lớn nhất > 0,1 cm nhưng ( 0,5 cm.", "T1b:   \tU có đường kính lớn nhất > 0,5 cm nhưng ( 1 cm", "T1c:  \tU có đường kính lớn nhất > 1 cm nhưng ( 2 cm", "T2:\tU có đường kính lớn nhất > 2cm nhưng ( 5cm", "T3:\tU có đường kính lớn nhất > 5cm", "T4:\tU với mọi kích thước nhưng xâm lấn trực tiếp tới thành ngực hoặc da (thành ngực bao gồm xương sườn, cơ gian sườn, cơ răng cưa trước, không tính cơ ngực)", "T4a:\tU xâm lấn tới thành ngực", "T4b:     Phù da cam, loét da vú, hoặc có nhiều u nhỏ vệ tinh trên da vú cùng bên", "T4c:\tBao gồm cả T4a và T4b", "T4d:\tUng thư vú dạng viêm", "N: hạch vùng", "Nx:\tHạch vùng không xác định được (ví dụ hạch đã được lấy bỏ trước đó)", "No:\tKhông có di căn tới hạch vùng", "N1:\tDi căn hạch nách cùng bên, di động", "N2:\tDi căn hạch nách cùng bên nhưng hạch dính nhau hoặc hạch dính vào tổ chức khác, hoặc chỉ di căn hạch vú trong cùng bên rõ trên lâm sàng nhưng không có di căn hạch nách.", "N2a:  \tDi căn hạch nách cùng bên nhưng hạch dính nhau hoặc dính vào tổ chức khác.", "N2b:  \tDi căn hạch vú trong cùng bên rõ trên lâm sàng nhưng không có di căn hạch nách", "N3: \tDi căn hạch hạ đòn cùng bên hoặc di căn hạch vú trong cùng bên rõ trên lâm sàng có kèm di căn hạch nách hoặc đã có di căn hạch thượng đòn cùng bên.", "N3a:   \tDi căn hạch hạ đòn cùng bên", "N3b:  \tDi căn hạch vú trong cùng bên rõ trên lâm sàng có kèm di căn hạch nách", "N3c:   \tDi căn hạch thượng đòn cùng bên", "M: Di căn xa", "Mx: \tKhông xác định được di căn xa ở thời điểm chẩn đoán", "Mo:\tKhông có di căn xa", "M1:\tDi căn xa", "Giai đoạn", "Giai đoạn\t\tU\t     Hạch vùng\t     Di căn xa", "0 \t\tTis\t\tN0\t\t\tM0", "I\t\tT1\t\tN0\t\t\tM0", "IIA\t\tT0\t\tN1\t\t\tM0", "T1\t\tN1\t\t\tM0", "T2\t\tN0\t\t\tM0", "IIB\t\tT2\t\tN1\t\t\tM0", "T3\t\tN0\t\t\tM0", "IIIA\t\tT0\t\tN2\t\t\tM0", "T1\t\tN2\t\t\tM0", "T2\t\tN2\t\t\tM0", "T3\t\tN1,\t\t\tM0", "T3\t\tN2\t\t\tM0", "IIIB\t\tT4\t\tN0\t\t            M0", "T4\t\tN1\t\t            M0", "T4\t\tN2\t\t            M0", "IIIC\t\tBất kỳ T \tN3\t\t\tM0", "IV\t\tBất kỳ T\tBất kỳ N\t\t M1", "D. Chẩn đoán"], "bullets": ["- Khèi u dÝnh víi tæ chøc xung quanh.", "- Ung th­ víi Hormon:", "+ Ung thư vú : Có thụ thể Estrogen và Progesteron (+) : thì 80% đáp ứng với điều trị hormon.", "+ Ung thư vú : có thụ thể nội tiết (ư) : chỉ có 10% đáp ứng với điều trị hormon."]}, {"heading": "1. Cơ năng", "paragraphs": ["Triệu chứng nghèo nàn, tự sờ thấy u, chiếm 80%."], "bullets": []}, {"heading": "2. Thùc thÓ", "paragraphs": ["ư Nhìn : Vùng da vú :   Biến đổi về màu sắc", "Co kÐo da, nóm vó", "Có vết trợt hoặc loét"], "bullets": ["- Sê :", "+ Khối u : Rắn, chắc, di động hạn chế hoặc không di động, ranh giới rõ.", "+ Mảng cứng : Chắc, không di động.", "+ Một số trường hợp có tiết dịch hoặc chảy máu ở núm vú.", "+ Hạch nach có thể sờ thấy."]}, {"heading": "3. Cận lâm sàng", "paragraphs": ["ư Chọc hút tế bào mức độ chính xác tới 90%.", "ư Chụp XQ vú : ở 3 tư thế : thẳng, nghiêng, xiên :", ". Hình ảnh gai đá.", ". Khối u không đều", ". Các điểm Canxi hoá nhỏ không đều tập trung thành đám.", ". Da vùng khối u dầy.", "ư Siêu âm", "ư Phát hiện di căn : chụp phổi, siêu âm gan, chụp XQ xương.", "E. Điều trị", "Nguyên tắc : Kết hợp điều trị tại chỗ với điều trị các di căn xa."], "bullets": []}, {"heading": "1. Điều trị tại chỗ", "paragraphs": ["ư Phẫu thuật : Cắt bỏ u + cơ ngực lớn + Nạo hạch nách.", "ư Tia xạ :"], "bullets": ["+ Trên vùng ngực sau phẫu thuật u và nạo hạch nách.", "+ Trên da vùng ngực sau khi cắt bỏ vú.", "+ Tia xạ trên vùng hạch : Hạch nách, hạch vú trong và hạch thượng đòn."]}, {"heading": "2. Điều trị di căn xa", "paragraphs": ["ư Hoá trị liệu : Endoxan, MTX", "ư Điều trị hormon : Chế phẩm kháng Estrogen : Tamoxifen.", "F. Dự phòng", "ư Khám vú định kỳ 3 ư> 6 tháng 1 lần cùng với khám phụ khoa.", "ư Tuyên truyền cộng đồng tự khám vú phát hiện dấu hiệu bất thường. Được đến cơ sở y tế khám và điều trị kịp thời.", "ư Tích cực điều trị các u vú lành tính."], "bullets": []}, {"heading": "Câu hỏi:", "paragraphs": ["Mô tả các tổn thương giải phẫu bệnh trong bệnh vú lành tính?", "Phân biệt các dạng lâm sàng trong bệnh vú lành tính?", "Xác định cách xử trí cho từng bệnh vú lành tính?", "Trình bày phân loại ung thư vú theo TNM?", "Liệt kê các yếu tố tiên lượng của ung thư vú?", "Trình bày chẩn đoán và đưa ra thái độ xử trí ung thư vú?"], "bullets": []}], "raw_text": "Bệnh của tuyến vú\nThs. Nguyễn Văn Hiền\nMục tiêu học tập:\nMô tả được các tổn thương giải phẫu bệnh trong bệnh vú lành tính.\nPhân biệt được các dạng lâm sàng trong bệnh vú lành tính.\nXác định được cách xử trí cho từng trường hợp cụ thể.\nTóm tắt được phân loại ung thư vú theo TNM\nLiệt kê được các yếu tố tiên lượng của ung thư vú\nTrình bày được chẩn đoán và đưa ra thái độ xử trí ung thư vú\n\nI. Đại cương\n1. Nhắc lại giải phẫu tuyến vú:\n+ Vó bao gåm: nóm, quÇng, bÇu.\n+ Khi đứng vú ngang khoang gian sườn 4.\n+ Vú trải dài từ xương ức đến đường nách trước, phần vú bám vào nách gọi là đuôi nách.\n+ Vú nằm trên cân của cơ ngực lớn.\n+ Vú được nâng đỡ bởi các dây chằng Cooper vào thành ngực.\nư Tổ chức học:\n\n\n\n\n\n\n\n+ Da, tæ chøc d­íi da\n+ Tổ chức liên kết\n+ ống dẫn sữa\n+ TiÓu thuú vó, mèi vó: 10 -> 20 tiÓu thuú.\n2. Sinh lý tuyÕn vó:\n+ Dưới tác dụng của Estrogen làm cho tuyến vú phát triển : Số lượng, ống dẫn sữa và chất lượng.\n+ Trưởng thành: Dưới tác dụng của Estrogen, Progesteron, Cortisol, Insulin, Prolactin và các yếu tố tăng trưởng làm cho vú trưởng thành và được biệt hoá đầy đủ.\n+ Mãn kinh: Lượng Estrgen giảm làm tuyến vú teo nhỏ nhưng mô mỡ vẫn bình thường.\nII. Các bệnh lành tính ở tuyến vú\nA. Các bệnh hay gặp\n1. Xơ nang tuyến vú\n1.1. Nguyên nhân\nDo mất cân bằng nội tiết: Estrogen và Progesteron.\n1.2. Giải phẫu bệnh :\n+ Các ống tuyến tăng sinh giãn ra và hình thành nang chế tiết thanh dịch.\n+ Các phân thuỳ: Tăng sinh tuyến và tăng sinh tuyến xơ cứng.\n+ Lớp đệm : Tăng sinh biểu mô và tăng sinh xơ cứng\n1.3. Triệu chứng chẩn đoán xác định\n+ Hay gặp ở tuổi: 29 ư> 49 tuổi.\n+ Tỷ lệ : 34 ư> 50 %\n+ Cơ năng : Đau vú theo chu kỳ, xuất hiện khoảng 8 ngày trước kinh và sau khi hết kinh thì hết đau.\n+ Thùc thÓ :\n* Mảng cứng :\nư Xuất hiện trên vú hay gặp 1/4 trên ngoài, có thể ở một bên hoặc hai bên vú.\nư Ranh giới không rõ.\nư Có thể mảng này mất đi sau khi có kinh.\n* U nang :\nư Khối u tròn, ranh giới rõ, di động, mật độ căng, ấn hơi đau, vị trí thường ở 1/4 trên ngoài.\n* Vú tăng về thể tích :\n+ Cận lâm sàng:\nư Chọc hút làm tế bào học.\n- XQ vó:\nVú tăng về mật độ.\nCản quang mờ tương ứng với vùng bị phù nề.\nCản quang tròn tương ứng với vùng bị u nang.\nVết Canxi hoá: to, nhỏ rải rác tập trung không thành nhóm.\nư Siêu âm vú biết nang, mảng cứng.\n+ Chẩn đoán phân biệt :\n* Đau :\nư Hội chứng tiến kinh : trước kinh 2ư>3 ngày đau vú. Nhưng vú không tăng về thể tích, sờ vú mềm không có u, mảng.\nư Đau dây thần kinh liên sườn : Đau một bên cố định, không liên quan đến chu kỳ kinh.\n* U nang tuyến vú có thể nhầm với u xơ tuyến vú. Chẩn đoán bằng tế bào học.\n* Mảng cứng ở vú có thể nhầm với ung thư vú.\nư Điều trị :\n+ Néi khoa :\nư chống viêm : kháng sinh, thuốc chống phù nề.\nư Nội tiết : Dùng Progesteron vào giai đoạn 2 của vòng kinh: từ 3 ư> 6 tháng.\n+ Ngoại khoa :\nư Có nghi ngờ về mặt tế bào học (tế bào loạn sản)\nư Điều trị nội khoa thất bại với mảng cứng tồn tại khá lâu.\n2. U xơ tuyến vú\nư Khối u phát triển từ mô liên kết giữa các tiểu thuỳ vú.\nư Tuổi gặp : từ 20 ư> 49.\nư Tỷ lệ : 19 %\n2.1. Triệu chứng\n+ Cơ năng : Nghèo nàn, tự sờ thấy u hoặc vô tình khám định kỳ phát hiện.\n+ Thùc thÓ :\nư U tròn, chắc, ranh giới rõ, di động dễ, ấn không đau, kích thước thay đổi từ 2 ư> 3 cm.\nư Số lượng : Thường thì có 1 u nhưng có trường có nhiều u xuất hiện ở 1 hoặc 2 bên vú.\nư Khối u xuất hiện không liên quan đến chu kỳ kinh.\n+ Cận lâm sàng :\nư Chọc hút làm tế bào học. Xác định u lành tính hoặc ác tính.\n- Chôp  XQ\nư Siêu âm\nư Điều trị : Là u xơ tuyến vú lành tính : phẫu thuật cắt bỏ u.\nB. Các bệnh lành tính ở tuyến vú ít gặp\n1. Giãn ống dẫn sữa\n- Tuæi tõ : 35 -> 55.\nư Tỷ lệ : 4 %\n1.1. Triệu chứng\n+ Tiết dịch ở núm vú 1 bên hoặc 2 bên : vàng, trong.\n+ Các abcès quanh quầng vú tái phát là biến chứng của giãn ống dẫn sữa sau này.\n+ Cận lâm sàng : Xét nghiệm tế bào dịch ống dẫn sữa.\n2. U nhú trong ống dẫn sữa\nư Triệu chứng\n+ Cơ năng : Tiết dịch hoặc chảy máu ở 1 hoặc 2 bên núm vú.\n+ Thực thể : ép xung quanh quầng vú có thể thấy dịch hoặc từ núm vú chảy ra.\n+ Cận lâm sàng : Chụp XQ vú để loại trừ ung thư vú\nXét nghiệm tế bào học dịch núm vú để loại trừ ung thư.\n+ Điều trị : Phẫu thuật là phương pháp chủ yếu.\n3. U mỡ ở vú :    Điều trị bằng phẫu thuật\n4. Túi sữa\nư Nguyên nhân :\nDo tắc ống dẫn sữa ở người đang nuôi con bú ư> u bọc chứa sữa gọi là túi sữa hay gọi là tắc sữa gây nang hoá.\nư Tổn thương : U tròn, ranh giới rõ, di động.\nư Cận lâm sàng : Tế bào học để chẩn đoán.\nư Xử trí : Phẫu thuật ngoài thời kỳ cho con bú.\nIII.  Ung th­ tuyÕn vó\nư Là 1 khối u ác tính, hay gặp ở các nước công nghiệp phát triển. Trong cỏc yếu tố nguy cơ gõy UT vỳ, yếu tố nổi bật nhất là tiền sử gia đỡnh cú người mắc UT vỳ, đặc biệt trong gia đỡnh cú từ 2 người mắc UT vỳ trở lờn ở lứa tuổi trẻ, đột biến gen ức chế u BRCAư1 và BRCAư2 nằm trờn nhiễm sắc thể 17 và 13. UT vỳ ở nam giới chiếm dưới 1% trong tổng số bệnh nhõn mắc căn bệnh này.\n- ChiÕm 30 % trong ung th­ phô khoa.\nư Đứng thứ 2 sau ung thư cổ tử cung.\nư Tuổi :   Bắt đầu ở lứa tuổi 40\nHay gặp : 50 ư> 60 tuổi.\nư Các yếu tố nguy cơ :\n+ Chưa sinh đẻ\n+ Thai nghÐn muén sau tuæi 30.\n+ Tiền sử điều trị K cổ tử cung, K dạ dày, K đại tràng.\n+ Yếu tố gia đình.\nA. Giải phẫu bệnh : 2 loại\n1. Ung thư biểu mô tại chỗ\nư Thường không có dấu hiệu lâm sàng.\nư Các tế bào ác tính ở bên trong của tiểu thuỳ vú hoặc ở bên trong của ống dẫn sữa chưa xâm lấn.\n2. Ung th­ x©m lÊn\nư Các tế bào ác tính xâm lấn vào mô liên kết quanh ống dẫn sữa và quanh tiểu thuỳ vú.\n- Khèi u dÝnh víi tæ chøc xung quanh.\nB. TiÕn triÓn\nư Ung thư có thể lan tràn theo hệ bạch huyết, hạch nách, nhóm cơ ngực, hạch thượng đòn, hạch vú trong.\nư Di căn : Phổi, xương, gan. 1 gram khối u giải phóng vào tuần hoàn 3 triệu tế bào trong 24 giờ. Vì vậy, điều trị ung thư vú kết hợp tại chỗ và toàn thân.\n- Ung th­ víi Hormon:\n+ Ung thư vú : Có thụ thể Estrogen và Progesteron (+) : thì 80% đáp ứng với điều trị hormon.\n+ Ung thư vú : có thụ thể nội tiết (ư) : chỉ có 10% đáp ứng với điều trị hormon.\nC. Phân loại :  Theo hệ T.N.M\nTheo phân loại TNM lần thứ 7 của UICC (Union International Contre le Cancer) và AJCC (American Joint Committee on Cancer) năm 2010.\nT: U nguyên phát\nTx: \tKhông đánh giá được u nguyên phát\nTo:\tKhông có dấu hiệu u nguyên phát\nTis:\tCarcinoma tại chỗ, carcinoma nội ống (DCIS), carcinoma thùy tại chỗ (LCIS), hoặc bệnh Paget của núm vú nhưng không có u\nT1:\tĐường kính u ( 2 cm\nT1mic: Xâm lấn vi thể đường kính lớn nhất ( 0,1 cm.\nT1a:  \tU có đường kính lớn nhất > 0,1 cm nhưng ( 0,5 cm.\nT1b:   \tU có đường kính lớn nhất > 0,5 cm nhưng ( 1 cm\nT1c:  \tU có đường kính lớn nhất > 1 cm nhưng ( 2 cm\nT2:\tU có đường kính lớn nhất > 2cm nhưng ( 5cm\nT3:\tU có đường kính lớn nhất > 5cm\nT4:\tU với mọi kích thước nhưng xâm lấn trực tiếp tới thành ngực hoặc da (thành ngực bao gồm xương sườn, cơ gian sườn, cơ răng cưa trước, không tính cơ ngực)\nT4a:\tU xâm lấn tới thành ngực\nT4b:     Phù da cam, loét da vú, hoặc có nhiều u nhỏ vệ tinh trên da vú cùng bên\nT4c:\tBao gồm cả T4a và T4b\nT4d:\tUng thư vú dạng viêm\nN: hạch vùng\nNx:\tHạch vùng không xác định được (ví dụ hạch đã được lấy bỏ trước đó)\nNo:\tKhông có di căn tới hạch vùng\nN1:\tDi căn hạch nách cùng bên, di động\nN2:\tDi căn hạch nách cùng bên nhưng hạch dính nhau hoặc hạch dính vào tổ chức khác, hoặc chỉ di căn hạch vú trong cùng bên rõ trên lâm sàng nhưng không có di căn hạch nách.\nN2a:  \tDi căn hạch nách cùng bên nhưng hạch dính nhau hoặc dính vào tổ chức khác.\nN2b:  \tDi căn hạch vú trong cùng bên rõ trên lâm sàng nhưng không có di căn hạch nách\nN3: \tDi căn hạch hạ đòn cùng bên hoặc di căn hạch vú trong cùng bên rõ trên lâm sàng có kèm di căn hạch nách hoặc đã có di căn hạch thượng đòn cùng bên.\nN3a:   \tDi căn hạch hạ đòn cùng bên\nN3b:  \tDi căn hạch vú trong cùng bên rõ trên lâm sàng có kèm di căn hạch nách\nN3c:   \tDi căn hạch thượng đòn cùng bên\nM: Di căn xa\nMx: \tKhông xác định được di căn xa ở thời điểm chẩn đoán\nMo:\tKhông có di căn xa\nM1:\tDi căn xa\nGiai đoạn\nGiai đoạn\t\tU\t     Hạch vùng\t     Di căn xa\n0 \t\tTis\t\tN0\t\t\tM0\nI\t\tT1\t\tN0\t\t\tM0\nIIA\t\tT0\t\tN1\t\t\tM0\nT1\t\tN1\t\t\tM0\nT2\t\tN0\t\t\tM0\nIIB\t\tT2\t\tN1\t\t\tM0\nT3\t\tN0\t\t\tM0\nIIIA\t\tT0\t\tN2\t\t\tM0\nT1\t\tN2\t\t\tM0\nT2\t\tN2\t\t\tM0\nT3\t\tN1,\t\t\tM0\nT3\t\tN2\t\t\tM0\nIIIB\t\tT4\t\tN0\t\t            M0\nT4\t\tN1\t\t            M0\nT4\t\tN2\t\t            M0\nIIIC\t\tBất kỳ T \tN3\t\t\tM0\nIV\t\tBất kỳ T\tBất kỳ N\t\t M1\nD. Chẩn đoán\n1. Cơ năng\nTriệu chứng nghèo nàn, tự sờ thấy u, chiếm 80%.\n2. Thùc thÓ\nư Nhìn : Vùng da vú :   Biến đổi về màu sắc\nCo kÐo da, nóm vó\nCó vết trợt hoặc loét\n- Sê :\n+ Khối u : Rắn, chắc, di động hạn chế hoặc không di động, ranh giới rõ.\n+ Mảng cứng : Chắc, không di động.\n+ Một số trường hợp có tiết dịch hoặc chảy máu ở núm vú.\n+ Hạch nach có thể sờ thấy.\n3. Cận lâm sàng\nư Chọc hút tế bào mức độ chính xác tới 90%.\nư Chụp XQ vú : ở 3 tư thế : thẳng, nghiêng, xiên :\n. Hình ảnh gai đá.\n. Khối u không đều\n. Các điểm Canxi hoá nhỏ không đều tập trung thành đám.\n. Da vùng khối u dầy.\nư Siêu âm\nư Phát hiện di căn : chụp phổi, siêu âm gan, chụp XQ xương.\nE. Điều trị\nNguyên tắc : Kết hợp điều trị tại chỗ với điều trị các di căn xa.\n1. Điều trị tại chỗ\nư Phẫu thuật : Cắt bỏ u + cơ ngực lớn + Nạo hạch nách.\nư Tia xạ :\n+ Trên vùng ngực sau phẫu thuật u và nạo hạch nách.\n+ Trên da vùng ngực sau khi cắt bỏ vú.\n+ Tia xạ trên vùng hạch : Hạch nách, hạch vú trong và hạch thượng đòn.\n2. Điều trị di căn xa\nư Hoá trị liệu : Endoxan, MTX\nư Điều trị hormon : Chế phẩm kháng Estrogen : Tamoxifen.\nF. Dự phòng\nư Khám vú định kỳ 3 ư> 6 tháng 1 lần cùng với khám phụ khoa.\nư Tuyên truyền cộng đồng tự khám vú phát hiện dấu hiệu bất thường. Được đến cơ sở y tế khám và điều trị kịp thời.\nư Tích cực điều trị các u vú lành tính.\nCâu hỏi:\nMô tả các tổn thương giải phẫu bệnh trong bệnh vú lành tính?\nPhân biệt các dạng lâm sàng trong bệnh vú lành tính?\nXác định cách xử trí cho từng bệnh vú lành tính?\nTrình bày phân loại ung thư vú theo TNM?\nLiệt kê các yếu tố tiên lượng của ung thư vú?\nTrình bày chẩn đoán và đưa ra thái độ xử trí ung thư vú?", "priority": "Trung bình"}, {"id": "SK-44", "chapter": "Chương 3. Phụ khoa", "folder": "03_Phu_khoa", "title": "Rối loạn kinh nguyệt", "author": "Ths. Phạm Thị Quỳnh Như", "word_count": 3053, "line_count": 98, "key_numbers": ["0,05mg", "10 ngày", "10mg", "20mg", "21 ngày", "25mg", "28 ngày", "3 ngày", "3 tháng", "35 ngày", "4 ngày", "4 tháng", "5 ngày", "7 ngày"], "key_drugs": ["oxytocin", "prostaglandin"], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["RỐI LOẠN KINH NGUYỆT", "ngMục tiêu học tập", "Trình bày được tiêu chuẩn bình thường của kinh nguyệt", "Liệt kê được các hình thái của rối loạn kinh nguyệt", "Nêu được các nguyên nhân gây vô kinh", "Trình bày được chẩn đoán và xử trí một số tình huống rong kinh rong huyết"], "bullets": []}, {"heading": "1. ĐẠI CƯƠNG", "paragraphs": ["Bình thường người phụ nữ bắt đầu hành kinh vào tuổi 13 đến 16 và mãn kinh vào tuổi 45-50. Chu kỳ kinh trung bình là 28 ngày, thời gian hành kinh từ 3-4 ngày. Lượng máu kinh mất khoảng 50-100 gram. Vòng kinh bình thường có phóng noãn và chia làm hai giai đoạn, giai đoạn estrogen và giai đoạn estrogen kết hợp progesteron. Rối loạn kinh nguyệt là một từ chung để biểu thị những bất thường của kinh nguyệt về tuổi bắt đầu có kinh, tuổi mãn kinh, chu kỳ kinh, thời gian hành kinh, lượng máu kinh cũng như những bất thường kèm theo hiện tượng kinh nguyệt. Nhưng cũng có khi không có biểu hiện bất thường về lâm sàng (có kinh đều đặn, lượng kinh vừa, cũng không có biểu hiện lâm sàng bất thường,…) vẫn gọi là rối loạn kinh nguyệt. Đó là những chu kỳ kinh không phóng noãn, những vòng kinh bất thường về sinh lý, những vòng kinh không có chức năng sinh sản.", "Như vậy rối loạn kinh nguyệt bao gồm: vòng kinh không phóng noãn, kinh thưa, kinh mau, cường kinh, thiểu kinh, vô kinh, thống kinh, có kinh sớm, có kinh muộn. Đây chỉ là những triệu chứng chứ không phải là bệnh, tuy nhiên trên thực tế lâm sàng vẫn ghi vào phần chẩn đoán bệnh các danh từ trên do việc tìm nguyên nhân của rối loạn kinh nguyệt rất khó khăn. Đòi hỏi nhiều thời gian, kinh nghiệm, các xét nghiệm đầy đủ và chính xác, ngoài ra phải kết hợp điều trị thử mới chẩn đoán được nguyên nhân gây rối loạn kinh nguyệt."], "bullets": []}, {"heading": "2. VÒNG KINH KHÔNG PHÓNG NOÃN", "paragraphs": ["Trên lâm sàng, rất khó phân biệt giữa vòng kinh có phóng noãn và không phóng noãn.  Cơ chế ra máu kinh không cần có sự hiện diện của progesteron mà chỉ cần sự thay đổi đột ngột về nồng độ estrogen là đủ.", "Những vòng kinh không phóng noãn thường gặp ở những kỳ kinh đầu của tuổi dậy thì và trong thời kỳ tiền mãn kinh. Phát hiện những vòng kinh không phóng noãn cần dựa vào xét nghiệm, đặc biệt hình ảnh giải phẫu bệnh lý qua nạo sinh thiết nội mạc tử cung. Trên thực tế có đến 1/10 các vòng kinh là không có phóng noãn.", "Đối với những bệnh nhân vô sinh cần lưu ý phát hiện những vòng kinh không phóng noãn. Điều trị vòng kinh không phóng noãn bằng các phác đồ kích thích phóng noãn ( xem bài “THĂM DÒ PHÓNG NOÃN VÀ KÍCH THÍCH PHÓNG NOÃN”)."], "bullets": []}, {"heading": "3. VÔ KINH", "paragraphs": ["Vô kinh là hiện tượng không hành kinh trong tuổi hoạt động sinh dục. Chia làm hai loại, nguyên phát và thứ phát. Vô kinh nguyên phát nhằm chỉ trường hợp đã quá tuổi dậy thì thông thường (18-18 tuổi) mà vẫn chưa có hành kinh, có tác giả gọi là kinh muộn. Vô kinh thứ phát là mất kinh liên tiếp từ 3 tháng trở lên ở một người phụ nữ tiền sử đã có hành kinh.", "Người ta còn phân biệt vô kinh sinh lý, vô kinh giả và vô kinh bệnh lý.", "Vô kinh sinh lý là những trường hợp vô kinh ở phụ nữ có thai, đang cho con bú hoặc những phụ nữ mãn kinh.", "Vô kinh giả gặp trong trường hợp niêm mạc tử cung vẫn hoạt động, thay đổi theo chu kỳ, vẫn bong ra hàng tháng những không chảy ra ngoài được vì những nguyên nhân như: cổ tử cung bị bít, không có âm đạo, màng trinh không thủng. Vô kinh giả gây ứ huyết trong tử cung hoặc ứ huyết trong tử cung- âm đạo. Cần được can thiệp bằng thủ thuật tùy vào nguyên nhân như nong cổ tử cung hoặc rạch màng trinh,…", "Vô kinh bệnh lý: do nhiều nguyên nhân. Nguyên nhân toàn thân thường hay gặp hơn và gồm những nguyên nhân thuộc về thần kinh, nội tiết và dinh dưỡng. Tại chỗ thường là các nguyên nhân thực thể."], "bullets": []}, {"heading": "3.1. Vô kinh do nguyên nhân tử cung", "paragraphs": ["Dị dạng sinh dục như không có tử cung, không có tử cung và âm đạo.", "Dính buồng tử cung, nội mạc tử cung không đáp ứng với nội tiết của buồng trứng.", "Lao nội mạc tử cung, thường thứ phát sau lao phổi."], "bullets": []}, {"heading": "3.2. Vô kinh do nguyên nhân buồng trứng", "paragraphs": ["Do đã cắt bỏ 2 buồng trứng, buồng trứng không phát triển (hội chứng turner), hội chứng Stein – Leventhal, buồng trứng tinh hoàn ( tuyến sinh dục vừa có tổ chức tinh hoàn vừa có tổ chức buồng trứng), khối u nam tính của buồng trứng, các u thoái hóa của buồng trứng, suy buồng trứng sớm."], "bullets": []}, {"heading": "3.3. Vô kinh do nguyên nhân tuyến yên", "paragraphs": ["Bệnh suy toàn bộ tuyến yên ( bệnh Simmonds), u tuyến yên, hội chúng sheehan (thiểu năng tuyến yên do hoại tử tuyến yên, có thể xảy ra sau đẻ khi mất một lượng máu quá lớn), thiếu hoormon hướng sinh dục tuyến yên đơn thuần nguyên phát."], "bullets": []}, {"heading": "3.4. Vô kinh do nguyên nhân tuyến giáp", "paragraphs": ["Cường giáp và thiểu năng tuyến giáp đều có thể gây vô kinh. Nội tiết tố tuyến giáp có tính chất gây mẫn cảm niêm mạc tử cung đối với estrogen. Nhưng cơ chế gây vô kinh thế nào hiện chưa được rõ."], "bullets": []}, {"heading": "3.5. Vô kinh do nguyên nhân vỏ thượng thận", "paragraphs": ["Cường vỏ thượng thận gây vô kinh do tăng tiết androgen, ức chế phát triển các nang noãn ở buồng trứng.", "Bệnh Addison, vô kinh có thể xảy ra do cơ thể suy nhược, suy sụp các chuyển hóa đạm, mỡ, đường và nước."], "bullets": []}, {"heading": "3.6. Vô kinh do nguyên nhân thần kinh, dinh dưỡng, chuyển hóa và bệnh toàn thân", "paragraphs": ["Những khối u ở não, vùng não giữa đều có thể gây vô kinh. Ngoài ra những sang chấn về tinh thần, những rối loạn thần kinh thực vật cũng gây vô kinh. Thay đổi hoàn cảnh sinh hoạt, khí hậu cũng là nguyên nhân gây rối loạn kinh nguyệt trong đó có vô kinh.", "Những nguyên nhân toàn thân gây vô kinh bao giờ cũng cần được lưu ý, vì chiếm một tỷ lệ khá cao. Có thể kể đến như suy nhược cơ thể do nhiễm khuẩn, thiếu dinh dưỡng, thiếu vitamin, thiếu máu, bệnh lý gan thận, suy nhược thần kinh, tâm thần phân liệt, làm việc quá căng thẳng.", "Tùy thuộc vào từng nguyên nhân cụ thể mà phải điều trị nội tiết hoặc phẫu thuật. Tuy nhiên cũng có khi chỉ thay đổi hoàn cảnh sinh hoạt, điều kiện sống, giảm cân hợp lý, chế độ ăn uống kết hợp vật lý trị liệu cũng có thể có kết quả tốt."], "bullets": []}, {"heading": "4. THỐNG KINH", "paragraphs": ["Thống kinh là hiện tượng đau bụng khi hành kinh. Đau bụng dưới lan lên ức, đau lan xuống dưới đùi, có khi đau khắp bụng. Có thể ở cơ quan khác cũng có hiện tượng bất thường như đau đầu, tâm thàn bất an, cương vú…", "Trước đây, người ta cho rằng thống kinh là do tử cung kém phát triển nên không chịu đựng được nội mạc tử cung bị cương to, phù nề; hoặc cho rằng lỗ trong cổ tử cung bị co thắt nên máu kinh không chảy ẩ được kích thích tử cung tăng co bóp gây đau. Ngày nay, người ta cho rằng các tổ chức hoại tử khi hành kinh sẽ tạo ra menotoxine gây co thắt tử cung, đặc biệt là xung quanh lỗ trong cổ tử cung. Các mạch máu bị co thắt làm cho các tổ chức bị thiếu oxy, gây đau. Ngoài ra, nghiên cứu thấy nồng độ prostaglandine tại lớp nội mạc tử cung và máu kinh của những phụ nữ thống kinh cũng cao hơn so với những phụ nữ không có triệu chứng thống kinh.", "Trong kỳ hành kinh đầu tiên, nếu tinh thần của người phụ nữ bị căng thẳng cũng là nguyên nhân gây thống kinh. Đứng trước một tình trạng thống kinh, cần tìm những nguyên nhân thực thể như chít hẹp lỗ cổ tử cung, tư thế quá gập trước hoặc ngả sau của tử cung, viêm tử cung, u xơ tử cung, lạc nội mạc tử cung… Điều trị tùy theo nguyên nhân, nếu tạm thời chưa tìm ra nguyên nhân có thể dùng thuốc giảm đau thông thường.", "RONG KINH VÀ RONG HUYẾT", "Rong kinh là hiện tượng có kinh đúng chu kỳ, ra kéo dài trên 7 ngày. Nếu lượng máu kinh ra nhiều hơn bình thường thì gọi là cường kinh, nguyên nhân thường là do cường estrogen. Trên thực tế, rất khó để xác định cụ thể lượng máu hành kinh. Thường chỉ đánh giá gián tiếp dựa vào ảnh hưởng đến toàn trạng do thiếu máu ở bệnh nhân cường kinh. Trong chẩn đoán rong kinh, cần phân biệt với các trường hợp rong huyết. Rong huyết là hiện tượng ra huyết không có chu kéo dài trên 7 ngày, nhiều khi có thể lầm với kinh nguyệt không đều. Rong huyết thường do nguyên nhân thực thể nên việc đầu tiên cần là tìm các nguyên nhân thực thể, nhất là những nguyên nhân ác tính. Những nguyên nhân thực thể hay gây rong huyết là sẩy thai, sót rau, chửa ngoài tử cung, u xơ tử cung, ung thư thân và cổ tử cung, polyp cổ tử cung, polyp buồng tử cung, viêm loét, trợt tử cung và âm đaoh, lao sinh dục… Ngoài ra lưu ý những trường hợp nguyên nhân khác như rối loạn đông máu, sang chấn tinh thần, u lách, suy gan, các u phân tiết ở buồng trứng như u tế bào hạt…", "Rong kinh, rong huyết tuổi trẻ", "Thường quen gọi là rong kinh dậy thì vì thông thường hay gặp ở tuổi dậy", "thì. Nguyên nhân: Trước kia người ta cho rằng cường estrogen (tồn tại nang noãn) làm cho niêm mạc tử cung quá sản tuyến nang. Ngày nay, người ta thấy estrogen có thể thấp, bình thường hoặc cao. Cơ bản là do FSH và LH không đầy đủ để kích thích buồng trứng, nguyên do từ rối loạn hoạt động của vùng dưới đồi. Thường là giai đoạn hoàng thể kém, không phóng noãn, không có giai đoạn hoàng thể.", "Triệu chứng: Kinh nguyệt kéo dài, thường là huyết tươi xảy ra sau một vòng kinh dài. Toàn trạng thiếu máu. Khám thực thể nhiều khi tử cung to mềm, cổ tử cung hé mở (phân biệt sẩy thai)", "Điều trị: Bước đầu tiên là loại trừ những nguyên nhân ác tính, các bệnh về máu nhất là ở những người con gái trong lần thấy kinh đầu tiên đã bị rong kinh, sau đó mới đặt vấn đề điều trị cầm máu.", "Nạo bằng hormon: tiêm progesteron hoặc uống progestagen 20mg/ ngày. Thông thường 4 - 5 ngày cầm máu. Ngừng thuốc 2 - 3 ngày ra huyết trở lại làm bong triệt để niêm mạc tử cung. Thời gian và lượng máu khi ra huyết trở lại tương tự như huyết kinh của người bình thường. Đề phòng rong kinh trong vòng kinh sau cho tiếp vòng kinh nhân tạo, có thể cho progestagen đơn thuần vào nửa sau dự kiến của vòng kinh, có thể cho kết hợp estrogen với progestagen như kiểu viên thuốc tránh thai. Có thể cho thuốc kích thích phóng noãn như clomifen. Kết hợp với các thuốc cầm máu, thuốc co hồi tử cung (oxytocin, ergotamin).", "Trong những trường hợp rất hạn hữu, điều trị bằng mọi biện pháp không kết quả mới phải nạo buồng tử cung bằng dụng cụ. Để cầm máu nhanh có thể dùng loại estrogen phức hợp sulfat tan trong nước premarin 25mg, tiêm tĩnh mạch, có thể cầm máu trong vòng nửa giờ.", "Rong kinh, rong huyết tiền mãn kinh", "Trong tất cả những trường hợp rối loạn kinh nguyệt tiền mãn kinh đều phải", "nghi ngờ có nguyên nhân ác tính. Rong kinh tiền mãn kinh, sinh thiết niêm mạc tử cung phần lớn có hình ảnh phát triển. Trong giai đoạn sau mãn kinh hay gặp hình ảnh niêm mạc tử cung teo, niêm mạc tử cung không hoạt động.", "Ngày nạo được tính là ngày đầu tiên của kỳ kinh tới. Thông thường cho", "progestagen từ ngày thứ 16, mỗi ngày 10mg, uống trong 10 ngày, uống trong 3", "vòng kinh liền.", "Rong kinh, rong huyết tuổi sinh đẻ (18 - 45 tuổi)", "Trẻ tuổi: Tử cung co bóp kém: Thuốc co tử cung. Tử cung kém phát triển: vòng kinh nhân tạo hoặc cho viên thuốc tránh thai nữa sau chu kỳ kinh.", "Lớn tuổi: Nếu có tổn thương thực thể nhỏ chưa có chỉ định phẩu thuật có", "thể chỉ định progestagen vài ngày trước khi hành kinh. Cũng có thể cho progestagen liều cao (mất kinh 3 - 4 tháng liền. Trên 40 tuổi điều trị thuốc không hiệu quả nên mổ cắt tử cung.", "Trên 35 tuổi: nạo niêm mạc tử cung.", "Thuốc: progestagen hoặc viên thuốc tránh thai nữa sau vòng kinh.", "Rong kinh do quá sản tuyến nang niêm mạc tử cung.", "Nạo niêm mạc buồng tử cung (50% khỏi trong một thời gian dài)", "Thuốc: Progestagen 10mg/ngày trong 10 ngày, kể từ ngày thứ 16 của vòng kinh trong 3 tháng.", "CÁC RỐI LOẠN KINH NGUYỆT KHÁC", "Kinh ít", "Lượng máu kinh của mỗi kỳ kinh rất ít. Nguyên nhân do nội mac tử cung kém phát triển, hoặc do hoạt động nội tiết của buồng trứng kém, hoặc do dính buồng tử cung. Nếu nguyên nhân kinh ít do các bệnh lý thực thể, cần được xác định rõ nguyên nhân để diều trị vì ảnh hưởng đến khả năng sinh sản.", "Kinh thưa", "Chu kỳ kinh kéo dài trên 35 ngày, thường do kéo dài giai đoạn phát triển của nang noãn. Đa số trường hợp không cần điều trị.", "Kinh mau (Đa kinh)", "Chu kỳ kinh ngắn hớn 21 ngày, thường do nang noãn sớm trưởng thành nên giai đoạn phát triển ngắn lại. Nhưng cũng có thể dp hoàng thể chóng suy nên hành kinh sớm. Điều trị thường dùng estrogen đầu chu kỳ, dùng thêm progesteron ở nữa sau pha hoàng thể.", "Hội chứng tiền kinh", "Trước khi hành kinh vài ngày, người phụ nữ bị căng thẳng thần kinh, cương vú, nhức đầu, phù…đến khi ra kinh thì hiện tượng này giảm đi. Nguyên nhân có thể do mất cân bằng giữa estradiol và progesteron. Ngoài ra, hiện nay người ta còn quan tâm đến vai trò của prostaglandin. Lượng PGF2 VÀ PGE2 tăng cao trong giai đoạn hoàng thể ở những phụ nữ có hội chứng tiền kinh.", "Điều trị: có thể dùng các thuốc an thần liều thấp hoặc progesteron như duphaston từ ngày 16 đến ngày 25 của chu kỳ."], "bullets": ["- Điều trị triệu chứng tốt nhất là nạo niêm mạc tử cung, có 3 lợi ích;", "+ Cầm máu nhanh (đỡ mất máu).", "+ Giải phẫu bệnh lý (loại trừ ác tính).", "+ Xác định rõ ràng tình trạng quá sản niêm mạc tử cung (điều trị hormon tiếp theo).", "- Cường kinh (kinh nhiều): So với hành kinh bình thường, lượng huyết ra nhiều. Thường kèm với rong kinh.", "+ Nguyên nhân: Phần lớn do tổn thương thực thể ở tử cung, u xơ tử cung, polype tử cung, lạc nội mạc tử cung tại cơ tử cung làm tử cung không co bóp được, niêm mạc tử cung khó tái tạo nên khó cầm máu. Cũng có thể do tử cung kém phát triển. Cường kinh cơ năng ít gặp hơn.", "+ Điều trị:", "- Rong kinh do chảy máu trước kinh", "+ Nguyên nhân: Có thể do tổn thương thực thể như viêm niêm mạc tử cung, polype buồng tử cung. Nhưng có thể do giai đoạn hoàng thể ngắn vì hoàng thể teo sớm estrogen và progesteron giảm nhanh.", "+ Điều trị", "- Rong kinh do chảy máu sau kinh", "+ Nguyên nhân: Thực thể: không hiếm (viêm niêm mạc tử cung, u xơ tử cung, polype buồng tử cung, u ác tính trong buồng tử cung). Cơ năng: Có thể do niêm mạc tử cung có những vùng bong chậm hoặc có những vùng tái tạo chậm.", "+ Điều trị: Trước hết phải loại trừ nguyên nhân thực thể. Nếu do hoàng thể kéo dài thì cho progestagen hoặc estrogen kết hợp với progestagen vào các ngày 20 - 25 của vòng kinh. Sau khi ngưng thuốc vài ngày, niêm mạc tử cung sẽ bong gọn và không rong kinh. Nếu do niêm mạc tử cung tái tạo chậm có thể cho Ethinyl - estradiol 0,05mg mỗi ngày 1 - 2 viên trong các ngày 3 - 8 của vòng kinh.", "+ Biểu hiện kinh chậm, ra nhiều huyết và kéo dài. Niêm mạc tử cung dày, có những nhú nhỏ dài hoặc phình dạng polype trông mượt như nhung.", "+ Nguyên nhân Estrogen tác dụng kéo dài gây nên hình ảnh hang lỗ chỗ của niêm mạc tử cung.", "+ Điều trị:"]}, {"heading": "Câu hỏi:", "paragraphs": ["Trình bày tiêu chuẩn bình thường của kinh nguyệt?", "Liệt kê các hình thái của rối loạn kinh nguyệt?", "Nêu các nguyên nhân gây vô kinh?", "Trình bày nguyên nhân, triệu chứng lâm sàng và hướng xử trí rong kinh, rong huyết tuổi dậy thì?", "Trình bày nguyên nhân, triệu chứng lâm sàng và hướng xử trí rong kinh, rong huyết tuổi tiền mạn kinh?", "Trình bày nguyên nhân, triệu chứng lâm sàng và hướng xử trí rong kinh, rong huyết tuổi sinh đẻ?"], "bullets": []}], "raw_text": "RỐI LOẠN KINH NGUYỆT\nngMục tiêu học tập\nTrình bày được tiêu chuẩn bình thường của kinh nguyệt\nLiệt kê được các hình thái của rối loạn kinh nguyệt\nNêu được các nguyên nhân gây vô kinh\nTrình bày được chẩn đoán và xử trí một số tình huống rong kinh rong huyết\n1. ĐẠI CƯƠNG\nBình thường người phụ nữ bắt đầu hành kinh vào tuổi 13 đến 16 và mãn kinh vào tuổi 45-50. Chu kỳ kinh trung bình là 28 ngày, thời gian hành kinh từ 3-4 ngày. Lượng máu kinh mất khoảng 50-100 gram. Vòng kinh bình thường có phóng noãn và chia làm hai giai đoạn, giai đoạn estrogen và giai đoạn estrogen kết hợp progesteron. Rối loạn kinh nguyệt là một từ chung để biểu thị những bất thường của kinh nguyệt về tuổi bắt đầu có kinh, tuổi mãn kinh, chu kỳ kinh, thời gian hành kinh, lượng máu kinh cũng như những bất thường kèm theo hiện tượng kinh nguyệt. Nhưng cũng có khi không có biểu hiện bất thường về lâm sàng (có kinh đều đặn, lượng kinh vừa, cũng không có biểu hiện lâm sàng bất thường,…) vẫn gọi là rối loạn kinh nguyệt. Đó là những chu kỳ kinh không phóng noãn, những vòng kinh bất thường về sinh lý, những vòng kinh không có chức năng sinh sản.\nNhư vậy rối loạn kinh nguyệt bao gồm: vòng kinh không phóng noãn, kinh thưa, kinh mau, cường kinh, thiểu kinh, vô kinh, thống kinh, có kinh sớm, có kinh muộn. Đây chỉ là những triệu chứng chứ không phải là bệnh, tuy nhiên trên thực tế lâm sàng vẫn ghi vào phần chẩn đoán bệnh các danh từ trên do việc tìm nguyên nhân của rối loạn kinh nguyệt rất khó khăn. Đòi hỏi nhiều thời gian, kinh nghiệm, các xét nghiệm đầy đủ và chính xác, ngoài ra phải kết hợp điều trị thử mới chẩn đoán được nguyên nhân gây rối loạn kinh nguyệt.\n2. VÒNG KINH KHÔNG PHÓNG NOÃN\nTrên lâm sàng, rất khó phân biệt giữa vòng kinh có phóng noãn và không phóng noãn.  Cơ chế ra máu kinh không cần có sự hiện diện của progesteron mà chỉ cần sự thay đổi đột ngột về nồng độ estrogen là đủ.\nNhững vòng kinh không phóng noãn thường gặp ở những kỳ kinh đầu của tuổi dậy thì và trong thời kỳ tiền mãn kinh. Phát hiện những vòng kinh không phóng noãn cần dựa vào xét nghiệm, đặc biệt hình ảnh giải phẫu bệnh lý qua nạo sinh thiết nội mạc tử cung. Trên thực tế có đến 1/10 các vòng kinh là không có phóng noãn.\nĐối với những bệnh nhân vô sinh cần lưu ý phát hiện những vòng kinh không phóng noãn. Điều trị vòng kinh không phóng noãn bằng các phác đồ kích thích phóng noãn ( xem bài “THĂM DÒ PHÓNG NOÃN VÀ KÍCH THÍCH PHÓNG NOÃN”).\n3. VÔ KINH\nVô kinh là hiện tượng không hành kinh trong tuổi hoạt động sinh dục. Chia làm hai loại, nguyên phát và thứ phát. Vô kinh nguyên phát nhằm chỉ trường hợp đã quá tuổi dậy thì thông thường (18-18 tuổi) mà vẫn chưa có hành kinh, có tác giả gọi là kinh muộn. Vô kinh thứ phát là mất kinh liên tiếp từ 3 tháng trở lên ở một người phụ nữ tiền sử đã có hành kinh.\nNgười ta còn phân biệt vô kinh sinh lý, vô kinh giả và vô kinh bệnh lý.\nVô kinh sinh lý là những trường hợp vô kinh ở phụ nữ có thai, đang cho con bú hoặc những phụ nữ mãn kinh.\nVô kinh giả gặp trong trường hợp niêm mạc tử cung vẫn hoạt động, thay đổi theo chu kỳ, vẫn bong ra hàng tháng những không chảy ra ngoài được vì những nguyên nhân như: cổ tử cung bị bít, không có âm đạo, màng trinh không thủng. Vô kinh giả gây ứ huyết trong tử cung hoặc ứ huyết trong tử cung- âm đạo. Cần được can thiệp bằng thủ thuật tùy vào nguyên nhân như nong cổ tử cung hoặc rạch màng trinh,…\nVô kinh bệnh lý: do nhiều nguyên nhân. Nguyên nhân toàn thân thường hay gặp hơn và gồm những nguyên nhân thuộc về thần kinh, nội tiết và dinh dưỡng. Tại chỗ thường là các nguyên nhân thực thể.\n3.1. Vô kinh do nguyên nhân tử cung\nDị dạng sinh dục như không có tử cung, không có tử cung và âm đạo.\nDính buồng tử cung, nội mạc tử cung không đáp ứng với nội tiết của buồng trứng.\nLao nội mạc tử cung, thường thứ phát sau lao phổi.\n3.2. Vô kinh do nguyên nhân buồng trứng\nDo đã cắt bỏ 2 buồng trứng, buồng trứng không phát triển (hội chứng turner), hội chứng Stein – Leventhal, buồng trứng tinh hoàn ( tuyến sinh dục vừa có tổ chức tinh hoàn vừa có tổ chức buồng trứng), khối u nam tính của buồng trứng, các u thoái hóa của buồng trứng, suy buồng trứng sớm.\n3.3. Vô kinh do nguyên nhân tuyến yên\nBệnh suy toàn bộ tuyến yên ( bệnh Simmonds), u tuyến yên, hội chúng sheehan (thiểu năng tuyến yên do hoại tử tuyến yên, có thể xảy ra sau đẻ khi mất một lượng máu quá lớn), thiếu hoormon hướng sinh dục tuyến yên đơn thuần nguyên phát.\n3.4. Vô kinh do nguyên nhân tuyến giáp\nCường giáp và thiểu năng tuyến giáp đều có thể gây vô kinh. Nội tiết tố tuyến giáp có tính chất gây mẫn cảm niêm mạc tử cung đối với estrogen. Nhưng cơ chế gây vô kinh thế nào hiện chưa được rõ.\n3.5. Vô kinh do nguyên nhân vỏ thượng thận\nCường vỏ thượng thận gây vô kinh do tăng tiết androgen, ức chế phát triển các nang noãn ở buồng trứng.\nBệnh Addison, vô kinh có thể xảy ra do cơ thể suy nhược, suy sụp các chuyển hóa đạm, mỡ, đường và nước.\n3.6. Vô kinh do nguyên nhân thần kinh, dinh dưỡng, chuyển hóa và bệnh toàn thân\nNhững khối u ở não, vùng não giữa đều có thể gây vô kinh. Ngoài ra những sang chấn về tinh thần, những rối loạn thần kinh thực vật cũng gây vô kinh. Thay đổi hoàn cảnh sinh hoạt, khí hậu cũng là nguyên nhân gây rối loạn kinh nguyệt trong đó có vô kinh.\nNhững nguyên nhân toàn thân gây vô kinh bao giờ cũng cần được lưu ý, vì chiếm một tỷ lệ khá cao. Có thể kể đến như suy nhược cơ thể do nhiễm khuẩn, thiếu dinh dưỡng, thiếu vitamin, thiếu máu, bệnh lý gan thận, suy nhược thần kinh, tâm thần phân liệt, làm việc quá căng thẳng.\nTùy thuộc vào từng nguyên nhân cụ thể mà phải điều trị nội tiết hoặc phẫu thuật. Tuy nhiên cũng có khi chỉ thay đổi hoàn cảnh sinh hoạt, điều kiện sống, giảm cân hợp lý, chế độ ăn uống kết hợp vật lý trị liệu cũng có thể có kết quả tốt.\n4. THỐNG KINH\nThống kinh là hiện tượng đau bụng khi hành kinh. Đau bụng dưới lan lên ức, đau lan xuống dưới đùi, có khi đau khắp bụng. Có thể ở cơ quan khác cũng có hiện tượng bất thường như đau đầu, tâm thàn bất an, cương vú…\nTrước đây, người ta cho rằng thống kinh là do tử cung kém phát triển nên không chịu đựng được nội mạc tử cung bị cương to, phù nề; hoặc cho rằng lỗ trong cổ tử cung bị co thắt nên máu kinh không chảy ẩ được kích thích tử cung tăng co bóp gây đau. Ngày nay, người ta cho rằng các tổ chức hoại tử khi hành kinh sẽ tạo ra menotoxine gây co thắt tử cung, đặc biệt là xung quanh lỗ trong cổ tử cung. Các mạch máu bị co thắt làm cho các tổ chức bị thiếu oxy, gây đau. Ngoài ra, nghiên cứu thấy nồng độ prostaglandine tại lớp nội mạc tử cung và máu kinh của những phụ nữ thống kinh cũng cao hơn so với những phụ nữ không có triệu chứng thống kinh.\nTrong kỳ hành kinh đầu tiên, nếu tinh thần của người phụ nữ bị căng thẳng cũng là nguyên nhân gây thống kinh. Đứng trước một tình trạng thống kinh, cần tìm những nguyên nhân thực thể như chít hẹp lỗ cổ tử cung, tư thế quá gập trước hoặc ngả sau của tử cung, viêm tử cung, u xơ tử cung, lạc nội mạc tử cung… Điều trị tùy theo nguyên nhân, nếu tạm thời chưa tìm ra nguyên nhân có thể dùng thuốc giảm đau thông thường.\nRONG KINH VÀ RONG HUYẾT\nRong kinh là hiện tượng có kinh đúng chu kỳ, ra kéo dài trên 7 ngày. Nếu lượng máu kinh ra nhiều hơn bình thường thì gọi là cường kinh, nguyên nhân thường là do cường estrogen. Trên thực tế, rất khó để xác định cụ thể lượng máu hành kinh. Thường chỉ đánh giá gián tiếp dựa vào ảnh hưởng đến toàn trạng do thiếu máu ở bệnh nhân cường kinh. Trong chẩn đoán rong kinh, cần phân biệt với các trường hợp rong huyết. Rong huyết là hiện tượng ra huyết không có chu kéo dài trên 7 ngày, nhiều khi có thể lầm với kinh nguyệt không đều. Rong huyết thường do nguyên nhân thực thể nên việc đầu tiên cần là tìm các nguyên nhân thực thể, nhất là những nguyên nhân ác tính. Những nguyên nhân thực thể hay gây rong huyết là sẩy thai, sót rau, chửa ngoài tử cung, u xơ tử cung, ung thư thân và cổ tử cung, polyp cổ tử cung, polyp buồng tử cung, viêm loét, trợt tử cung và âm đaoh, lao sinh dục… Ngoài ra lưu ý những trường hợp nguyên nhân khác như rối loạn đông máu, sang chấn tinh thần, u lách, suy gan, các u phân tiết ở buồng trứng như u tế bào hạt…\nRong kinh, rong huyết tuổi trẻ\nThường quen gọi là rong kinh dậy thì vì thông thường hay gặp ở tuổi dậy\nthì. Nguyên nhân: Trước kia người ta cho rằng cường estrogen (tồn tại nang noãn) làm cho niêm mạc tử cung quá sản tuyến nang. Ngày nay, người ta thấy estrogen có thể thấp, bình thường hoặc cao. Cơ bản là do FSH và LH không đầy đủ để kích thích buồng trứng, nguyên do từ rối loạn hoạt động của vùng dưới đồi. Thường là giai đoạn hoàng thể kém, không phóng noãn, không có giai đoạn hoàng thể.\nTriệu chứng: Kinh nguyệt kéo dài, thường là huyết tươi xảy ra sau một vòng kinh dài. Toàn trạng thiếu máu. Khám thực thể nhiều khi tử cung to mềm, cổ tử cung hé mở (phân biệt sẩy thai)\nĐiều trị: Bước đầu tiên là loại trừ những nguyên nhân ác tính, các bệnh về máu nhất là ở những người con gái trong lần thấy kinh đầu tiên đã bị rong kinh, sau đó mới đặt vấn đề điều trị cầm máu.\nNạo bằng hormon: tiêm progesteron hoặc uống progestagen 20mg/ ngày. Thông thường 4 - 5 ngày cầm máu. Ngừng thuốc 2 - 3 ngày ra huyết trở lại làm bong triệt để niêm mạc tử cung. Thời gian và lượng máu khi ra huyết trở lại tương tự như huyết kinh của người bình thường. Đề phòng rong kinh trong vòng kinh sau cho tiếp vòng kinh nhân tạo, có thể cho progestagen đơn thuần vào nửa sau dự kiến của vòng kinh, có thể cho kết hợp estrogen với progestagen như kiểu viên thuốc tránh thai. Có thể cho thuốc kích thích phóng noãn như clomifen. Kết hợp với các thuốc cầm máu, thuốc co hồi tử cung (oxytocin, ergotamin).\nTrong những trường hợp rất hạn hữu, điều trị bằng mọi biện pháp không kết quả mới phải nạo buồng tử cung bằng dụng cụ. Để cầm máu nhanh có thể dùng loại estrogen phức hợp sulfat tan trong nước premarin 25mg, tiêm tĩnh mạch, có thể cầm máu trong vòng nửa giờ.\nRong kinh, rong huyết tiền mãn kinh\nTrong tất cả những trường hợp rối loạn kinh nguyệt tiền mãn kinh đều phải\nnghi ngờ có nguyên nhân ác tính. Rong kinh tiền mãn kinh, sinh thiết niêm mạc tử cung phần lớn có hình ảnh phát triển. Trong giai đoạn sau mãn kinh hay gặp hình ảnh niêm mạc tử cung teo, niêm mạc tử cung không hoạt động.\n- Điều trị triệu chứng tốt nhất là nạo niêm mạc tử cung, có 3 lợi ích;\n+ Cầm máu nhanh (đỡ mất máu).\n+ Giải phẫu bệnh lý (loại trừ ác tính).\n+ Xác định rõ ràng tình trạng quá sản niêm mạc tử cung (điều trị hormon tiếp theo).\nNgày nạo được tính là ngày đầu tiên của kỳ kinh tới. Thông thường cho\nprogestagen từ ngày thứ 16, mỗi ngày 10mg, uống trong 10 ngày, uống trong 3\nvòng kinh liền.\nRong kinh, rong huyết tuổi sinh đẻ (18 - 45 tuổi)\n- Cường kinh (kinh nhiều): So với hành kinh bình thường, lượng huyết ra nhiều. Thường kèm với rong kinh.\n+ Nguyên nhân: Phần lớn do tổn thương thực thể ở tử cung, u xơ tử cung, polype tử cung, lạc nội mạc tử cung tại cơ tử cung làm tử cung không co bóp được, niêm mạc tử cung khó tái tạo nên khó cầm máu. Cũng có thể do tử cung kém phát triển. Cường kinh cơ năng ít gặp hơn.\n+ Điều trị:\nTrẻ tuổi: Tử cung co bóp kém: Thuốc co tử cung. Tử cung kém phát triển: vòng kinh nhân tạo hoặc cho viên thuốc tránh thai nữa sau chu kỳ kinh.\nLớn tuổi: Nếu có tổn thương thực thể nhỏ chưa có chỉ định phẩu thuật có\nthể chỉ định progestagen vài ngày trước khi hành kinh. Cũng có thể cho progestagen liều cao (mất kinh 3 - 4 tháng liền. Trên 40 tuổi điều trị thuốc không hiệu quả nên mổ cắt tử cung.\n- Rong kinh do chảy máu trước kinh\n+ Nguyên nhân: Có thể do tổn thương thực thể như viêm niêm mạc tử cung, polype buồng tử cung. Nhưng có thể do giai đoạn hoàng thể ngắn vì hoàng thể teo sớm estrogen và progesteron giảm nhanh.\n+ Điều trị\nTrên 35 tuổi: nạo niêm mạc tử cung.\nThuốc: progestagen hoặc viên thuốc tránh thai nữa sau vòng kinh.\n- Rong kinh do chảy máu sau kinh\n+ Nguyên nhân: Thực thể: không hiếm (viêm niêm mạc tử cung, u xơ tử cung, polype buồng tử cung, u ác tính trong buồng tử cung). Cơ năng: Có thể do niêm mạc tử cung có những vùng bong chậm hoặc có những vùng tái tạo chậm.\n+ Điều trị: Trước hết phải loại trừ nguyên nhân thực thể. Nếu do hoàng thể kéo dài thì cho progestagen hoặc estrogen kết hợp với progestagen vào các ngày 20 - 25 của vòng kinh. Sau khi ngưng thuốc vài ngày, niêm mạc tử cung sẽ bong gọn và không rong kinh. Nếu do niêm mạc tử cung tái tạo chậm có thể cho Ethinyl - estradiol 0,05mg mỗi ngày 1 - 2 viên trong các ngày 3 - 8 của vòng kinh.\nRong kinh do quá sản tuyến nang niêm mạc tử cung.\n+ Biểu hiện kinh chậm, ra nhiều huyết và kéo dài. Niêm mạc tử cung dày, có những nhú nhỏ dài hoặc phình dạng polype trông mượt như nhung.\n+ Nguyên nhân Estrogen tác dụng kéo dài gây nên hình ảnh hang lỗ chỗ của niêm mạc tử cung.\n+ Điều trị:\nNạo niêm mạc buồng tử cung (50% khỏi trong một thời gian dài)\nThuốc: Progestagen 10mg/ngày trong 10 ngày, kể từ ngày thứ 16 của vòng kinh trong 3 tháng.\nCÁC RỐI LOẠN KINH NGUYỆT KHÁC\nKinh ít\nLượng máu kinh của mỗi kỳ kinh rất ít. Nguyên nhân do nội mac tử cung kém phát triển, hoặc do hoạt động nội tiết của buồng trứng kém, hoặc do dính buồng tử cung. Nếu nguyên nhân kinh ít do các bệnh lý thực thể, cần được xác định rõ nguyên nhân để diều trị vì ảnh hưởng đến khả năng sinh sản.\nKinh thưa\nChu kỳ kinh kéo dài trên 35 ngày, thường do kéo dài giai đoạn phát triển của nang noãn. Đa số trường hợp không cần điều trị.\nKinh mau (Đa kinh)\nChu kỳ kinh ngắn hớn 21 ngày, thường do nang noãn sớm trưởng thành nên giai đoạn phát triển ngắn lại. Nhưng cũng có thể dp hoàng thể chóng suy nên hành kinh sớm. Điều trị thường dùng estrogen đầu chu kỳ, dùng thêm progesteron ở nữa sau pha hoàng thể.\nHội chứng tiền kinh\nTrước khi hành kinh vài ngày, người phụ nữ bị căng thẳng thần kinh, cương vú, nhức đầu, phù…đến khi ra kinh thì hiện tượng này giảm đi. Nguyên nhân có thể do mất cân bằng giữa estradiol và progesteron. Ngoài ra, hiện nay người ta còn quan tâm đến vai trò của prostaglandin. Lượng PGF2 VÀ PGE2 tăng cao trong giai đoạn hoàng thể ở những phụ nữ có hội chứng tiền kinh.\nĐiều trị: có thể dùng các thuốc an thần liều thấp hoặc progesteron như duphaston từ ngày 16 đến ngày 25 của chu kỳ.\n\nCâu hỏi:\nTrình bày tiêu chuẩn bình thường của kinh nguyệt?\nLiệt kê các hình thái của rối loạn kinh nguyệt?\nNêu các nguyên nhân gây vô kinh?\nTrình bày nguyên nhân, triệu chứng lâm sàng và hướng xử trí rong kinh, rong huyết tuổi dậy thì?\nTrình bày nguyên nhân, triệu chứng lâm sàng và hướng xử trí rong kinh, rong huyết tuổi tiền mạn kinh?\nTrình bày nguyên nhân, triệu chứng lâm sàng và hướng xử trí rong kinh, rong huyết tuổi sinh đẻ?", "priority": "Trung bình"}, {"id": "SK-45", "chapter": "Chương 3. Phụ khoa", "folder": "03_Phu_khoa", "title": "Viêm sinh dục", "author": "TS. Bùi Minh Tiến", "word_count": 4908, "line_count": 298, "key_numbers": ["1 tháng", "10 ngày", "100 mg", "100mg", "106 UI", "14 ngày", "150mg", "1g", "2 ngày", "200 mg", "200mg", "21 ngày", "2g", "3 ngày", "3 tháng", "300 mg", "400 mg", "400mg", "500 mg", "500mg", "7 ngày", "800 mg"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["Viêm sinh dục"], "bullets": []}, {"heading": "Mục tiêu học tập", "paragraphs": ["Liệt kê các loại vi khuẩn gây bệnh thường gặp", "Kể được các thể lâm sàng của viêm âm đạo", "Xác định cách điều trị thích hợp cho mỗi loại viêm âm đạo."], "bullets": []}, {"heading": "1. Đại cương", "paragraphs": ["Viêm nhiễm cơ quan sinh dục là loại bệnh khá phổ biến trong dời sống của người phụ nữ, nguyên nhân đa dạng, diễn biến phức tạp dẫn đến việc điều trị khó khăn, đôi lúc để lại biến chứng như viêm tiểu khung, vô sinh, chửa ngoài tử cung, sẩy thai, đẻ non, viêm kết mạc mắt trẻ sơ sinh…"], "bullets": []}, {"heading": "1.1. Đặc điểm", "paragraphs": ["ưPhổ biến hay gặp trong độ tuổi hoạt động sinh dục.", "ưCác bộ phận của đường sinh dục dưới và trên đều có thể bị viêm nhiễm.", "ưHình thái cấp tính và mạn tính đều có thể gặp, hình thái mạn tính điều trị kéo dài, kém hiệu quả.", "ưPhát hiện bệnh sớm điều trị sẽ khỏi hẳn và tránh được những biến chứng xấu như viêm tắc vòi tử cung, đau trong viêm phần phụ mạn tính."], "bullets": []}, {"heading": "1.2. YÕu tè thuËn lîi", "paragraphs": ["ưLây qua đường tình dục (giao hợp với người bị bệnh lây truyền qua đường tình dục).", "ưSau các can thiệp thủ thuật như đình chỉ thai nghén, đặt dụng cụ tử cung, chụp tử cung vòi trứng.", "ưNhiễm khuẩn sau sẩy, sau đẻ.", "ưKém vệ sinh khi giao hợp, sau khi hành kinh."], "bullets": []}, {"heading": "1.3. KhÝ h­", "paragraphs": ["Bình thường ở CTC và ÂĐ có một chất dịch trắng trong hơi đặc, hoặc như lòng trắng trứng, lượng ít không chảy ra bên ngoài, không làm cho người phụ nữ để ý, đó là dịch sinh lý, dịch này có pH # 3,8ư4,6 tạo nên môi trường bảo vệ cho ÂĐ chống lại sự nhiễm khuẩn nhưng cũng có thể là yếu tố thuận lợi cho sự phát triển của mầm bệnh, pH này do sự chuyển hoá glycogen ở tế bào niêm mạc ÂĐ ư CTC thành acid lactic bởi trực khuẩn Doderlin.", "Khi ÂĐ bị viêm nhiễm, dịch tiết ra nhiều, gây khó chịu làm người phụ nữ lo lắng, trong trường hợp này dù màu sắc như thế nào, trắng hay vàng, có mùi hay không đều là bệnh lý."], "bullets": []}, {"heading": "1.4. Các loại tác nhân gây bệnh", "paragraphs": ["Các vi khuẩn Gr (ư), Gr (+) đều có thể có mặt trong viêm sinh dục."], "bullets": []}, {"heading": "1.4.1. Vi khuẩn không gây bệnh:", "paragraphs": [], "bullets": ["-Trùc khuÈn Doderlin.", "-Stphylococcus epidermidis."]}, {"heading": "1.4.2. Các vi khuẩn gây bệnh cơ hội:", "paragraphs": ["Các cầu khuẩn ái khí", "Các trực khuẩn ái khí", "Các vi khuẩn kỵ khí", "Streptococcus alpha", "Streptococcus tan huyÕt A, C, G", "Streptococcus aureus", "Streptococcus agaltiea", "Colibacille", "Coliforme", "Proteus, pseudomonas", "Klebsiella", "Enterobacter", "Streptocque beta", "Bacteroides", "Clostridium", "Fusobacterie"], "bullets": []}, {"heading": "1.4.3. Vi khuẩn, virus và ký sinh trùng luôn gây bệnh:", "paragraphs": ["ưCandida albicans: có thể là cộng sinh nhưng sẽ gây bệnh khi tăng sinh bất thường", "ưGardnerella vaginalis: có thể là cộng sinh, gây bệnh khi tăng sinh bất thường"], "bullets": ["-Neisseria gonorrhea", "-Trichomonas vaginalis", "-Chlamydia trachomatis", "-Treponema pallidum", "-Herpes simplex virus", "-Human papilloma virus", "-HIV"]}, {"heading": "1.4.4. Các mầm bệnh thường gặp gây viêm ÂĐ:", "paragraphs": ["ưNấm men gây viêm ÂH ư ÂĐ", "ưTrùng roi gây viêm ÂĐ", "ưVi khuẩn gây viêm ÂĐ do vi khuẩn", "ưLậu cầu khuẩn gây viêm CTC mủ nhầy và viêm niệu đạo", "ưChlamydia trachomatis gây viêm CTC mủ nhầy và viêm niệu đạo"], "bullets": []}, {"heading": "2. Viêm tuyến Bartholin", "paragraphs": ["Mầm bệnh thường do vi khuẩn lậu, các vi khuẩn khác như liên cầu, tụ cầu hoặc trực khuẩn Chlamydia từ viêm âm hộ lan đến tuyến Bartholin, có khi ống tuyến bị tắc, tuyến bị nang hoá và bị nhiễm khuẩn thứ phát, có thể gặp trong trường hợp cắt TSM."], "bullets": []}, {"heading": "2.1. Viêm tuyến Bartholin cấp", "paragraphs": ["Bệnh nhân đau ở vùng âm hộ, thường đau một bên, đi đứng đều đau. Viêm lúc đầu khu trú sau lan toả, phát triển có mủ.", "Khám bằng cách dùng ngón cái và ngón trỏ nắn môi bé thấy một khối có khi to bằng quả trứng rắn tròn đều. Nắn thấy đau, nặn sẽ thấy mủ chảy ra ở cửa tuyến (ở mặt trong môi bé)."], "bullets": []}, {"heading": "2.2. Viêm tuyến Bartholin mạn", "paragraphs": ["Thường xảy ra sau đợt điều trị viêm tuyến Bartholin cấp, điều trị không triệt để hoặc đã chích.", "Hoàn cảnh xuất hiện: sau kinh nguyệt, sau viêm âm hộ, sau giao hợp tuyến lại to lên, nắn thấy rắn, đau (không nhiều) và có ít mủ chảy ra."], "bullets": []}, {"heading": "2.3. Nang tuyÕn Bartholin", "paragraphs": ["Tuyến bị nang hoá sau viêm cấp, viêm mạn hoặc ống tuyến bị tắc. Khi nang hoá có thể sờ thấy khối cứng, khu trú ơ một bên, nang có thể ở vị trí nông, sâu. Nếu bị nhiễm khuẩn nang trở thành khối apxe mủ.", "Sau khi khám thực thể cần lấy mủ tiết để xác định loại vi khuẩn, đồng thời lấy bệnh phẩm cả ở niệu đạo, CTC để xét nghiệm.", "Điều trị:", "Néi khoa:", "Do vi khuẩn Gr(+), Gr(ư): dùng kháng sinh nhóm βư Lactam, nhóm Cephalosporin (1ư2 g/ngày)", "Do vi khuẩn kỵ khí Gr(+), Gr(ư) hay lậu cầu: Penicillin procain 5ì 106 UI/ngàyì 7 ngày hoặc Spectinomycin 2g/ ngày, 1 lần hoặc Pefloxacin 800 mg/ liều duy nhất", "Với Chlamydia: Doxycyclin 200 mg/ ngày trong 10 ngày", "Ngoại khoa: Chích dẫn lưu, mở rộng ống tiết, huỷ vách ngăn, dẫn lưu trong 2ư3 ngày.", "Với thể mạn tính hay nang hoá: bóc nang. Sau điều trị ngoại khoa, di chứng là giao hợp đau."], "bullets": []}, {"heading": "3.1. Viêm âm đạo do trùng roi (Trichomonas vaginalis): Là bệnh lây qua đường quan hệ tình dục là chủ yếu, ngoài ra có thể lây qua nguồn nước: bồn tắm, khăn tắm.", "paragraphs": ["ưTriệu chứng", "ưXét nghiệm", "ưĐiều trị", "*Chú ý: Metronidazole không dùng cho phụ nữ có thai 3 tháng đầu, không được uống rượu khi đang dùng thuốc cho đến 24h sau khi ngừng thuốc."], "bullets": ["+ủ bệnh từ 1ư4 tuần. 25% số người mắc không biểu hiện bệnh", "+Khí hư: số lượng nhiều, loãng, có bọt, màu vàng xanh, hôi.", "+Có thể kèm theo ngứa, đi tiểu khó và đau khi giao hợp.", "+Khám: âm hộ, âm đạo, cổ tử cung viêm đỏ, phù nề, có nhiều khí hư màu vàng xanh loãng và có bọt ở cùng đồ.", "+Lấy dịch khí hư cho vào nước muối sinh lý soi tươi thấy có trùng roi ÂĐ hình hạt chanh đang di động.", "+Chứng nghiệm Sniff (Whiff test): nhỏ một giọt KOH 10% vào dịch khí hư thấy có mùi cá ươn và mất đi nhanh.", "+Đo pH >4,5.", "+Vệ sinh ÂH, ÂĐ, quần áo lót phải được giặt sạch, phơi nắng hoặc là trước khi dùng.", "+Không giao hợp trong thời gian điều trị.", "+Metronidazole 2g uống liều duy nhất, hoặc", "+ Metronidazole 500mg uống 2 lần/ ngày x 7 ngày.", "+Có thể phối hợp đặt thuốc ÂĐ.", "+Cần điều trị cho chồng hoặc bạn tình: Metronidazole 2g liều duy nhất."]}, {"heading": "3.2. Viêm âm đạo do nấm: Là bệnh do nấm Candida gây nên (chủ yếu là Candida albicans). Chiếm khoảng 20% các trường hợp viêm ÂĐ.", "paragraphs": ["ưTriệu chứng", "ưXét nghiệm", "ưĐiều trị", "Fluconazole 150mg uống 1 viên duy nhất hoặc", "Miconazole 200mg, đặt ÂĐ 1 viên trước khi đi ngủ x 3 ngày hoặc", "Clotrimazole 500mg, đặt 1 viên ÂĐ duy nhất hoặc", "Econazole 150mg đặt 1 viên vào ÂĐ trước khi ngủ x 2 ngày hoặc", "Nystatin 100.000 đơn vị đặt 1 viên ÂĐ trước khi ngủ x14 ngày liên tục (kể cả khi có kinh)."], "bullets": ["+Ngứa nhiều vùng ÂH, ÂĐ.", "+Khí hư màu trắng đục như váng sữa, không hôi.", "+Có thể kèm theo đi tiểu khó, đau khi giao hợp.", "+Khám: ÂH, ÂĐ viêm đỏ, có thể xây xước nhiễm khuẩn do gãi, nếu nặng có thể bị viêm cả vùng TSM và đùi bẹn. Khí hư thường nhiều, màu trắng như váng sữa, thành mảng dày dính vào thành ÂĐ, ở dưới có vết trợt đỏ.", "+Soi tươi hoặc nhuộm Gram tìm nấm men. Nuôi cấy ở môi trường Sabouraud.", "+Sniff test (-).", "+Đo pH <4,5.", "+Vệ sinh ÂĐ, quần áo lót sạch, được phơi nắng hoặc là trước khi mặc.", "+Không giao hợp trong thời gian điều trị.", "+Itraconazole (Sporal) 100mg uống 2v/ ngày x 3 ngày hoặc", "+Tỷ lệ tái phát 15%."]}, {"heading": "3.3. Viêm âm đạo do tạp khuẩn", "paragraphs": ["Là bệnh viêm ÂĐ không dặc hiệu, không lây qua quan hệ tình dục nên không cần điều trị cho chồng hoặc bạn tình", "ưNguyên nhân: chủ yếu do Mycoplasma hominis, Mobiluncus có thể phối hợp với một số vi khuẩn yếm khí khác.", "ưYếu tố thuận lợi: hay gặp ở người mãn kinh, người bị cắt 2 buồng trứng, trẻ em gái trước tuổi dậy thì.", "ưTriệu chứng:", "ưXét nghiệm: chẩn đoán dựa vào nhuộm Gram hoặc có 3/4 tiêu chí của Amsel:", "ưĐiều trị: Metronidazole là thuốc có hiệu quả nhất", "*Chú ý: Metronidazole không dùng cho phụ nữ có thai 3 tháng đầu. Trong khi uống thuốc không được uống rượu, không quan hệ tình dục."], "bullets": ["+Ra nhiều khí hư mùi hôi như mùi tanh cá", "+Khám: khí hư mùi hôi như mùi cá ươn, màu xám trắng, đồng nhất như kem phết đều vào thành ÂĐ một lớp mỏng, không có viêm ÂĐ.", "+Ra khÝ h­.", "+pH > 4,5.", "+Soi tươi hoặc nhuộm Gram có tế bào ÂĐ dính các vi khuẩn (Clue cells).", "+Test Sniff (+).", "+ Vệ sinh ÂĐ, quần áo lót sạch, được phơi nắng hoặc là trước khi mặc.", "+Không giao hợp trong thời gian điều trị.", "+Metronidazole 2g uống liều duy nhất hoặc", "+ Metronidazole 500mg uống 2 lần/ ngày x 7 ngày hoặc", "+Kem Clindamycine 2% bôi tại chỗ trong 7 ngày hoặc", "+Clindamycine 300 mg uống 2 lần/ ngày x 7 ngày", "+Có thể phối hợp đặt thuốc âm đạo"]}, {"heading": "3.4. Viêm cổ tử cung mủ nhầy do lậu", "paragraphs": ["ưTriệu chứng", "ưXét nghiệm", "ưĐiều trị: có thể lựa chọn một trong các loại thuốc sau:", "*Chú ý: ở Việt Nam, lậu cầu khuẩn đã kháng lại các kháng sinh thuộc nhóm Quinolone, Penicilline, Kanamycin. Viêm âm đạo do lậu thường kèm theo các tác nhân gây bệnh khác nên thường phải điều trị phối hợp."], "bullets": ["+Biểu hiện cấp tính: đái buốt, mủ chảy ra từ niệu đạo, từ cổ tử cung; mủ màu vàng đặc hoặc vàng xanh, số lượng nhiều, mùi hôi. Bệnh nhân đau khi giao hợp, đau bụng dưới.", "+Khám mỏ vịt thấy: cổ tử cung đỏ, phù nề, chạm vào chảy máu. Mủ chảy ra từ ống cổ tử cung. Có thể thấy lỗ niệu đạo đỏ, có mủ hoặc dịch đục từ trong chảy ra.", "+Thể mãn tính: triệu chứng lâm sàng không rõ ràng mà thường kín đáo, thậm chí không biểu hiện triệu chứng bệnh (trên 50% trường hợp) vì vậy họ không biết mình bị bệnh nên dễ lây lan cho người khác và trẻ sơ sinh.", "+Thường lấy bệnh phẩm ở 2 vị trí là niệu đạo và cổ tử cung. Hậu môn, các tuyến Sken, Bartholin cũng là nơi thường có lậu cầu.", "+Nhuộm Gram: song cầu khuẩn hình hạt cafe, bắt màu gram (ư) nằm trong và ngoài bạch cầu đa nhân, tế bào mủ.", "+Cefixime 400 mg uèng liÒu duy nhÊt", "+Spectinomycin 2g tiêm bắp liều duy nhất", "+Cefotaxime 1g tiêm bắp liều duy nhất.", "+Điều trị cho cả bạn tình."]}, {"heading": "3.5. Viêm cổ tử cung và niệu đạo do Chlamydia trachomatis", "paragraphs": ["Nhiễm Chlamydia trachomatis ở sinh dục ư tiết niệu nữ thường không biểu hiện triệu chứng (70%), thông thường được phát hiện khi bạn tình có viêm niệu đạo.", "ưTriệu chứng", "ưXét nghiệm", "Cần lấy bệnh phẩm ở cổ tử cung, niệu đạo, hậu môn, tuyến Bartholin nuôi cấy tế bào, xét nghiệm PCR,v.v...", "ưĐiều trị: có thể lựa chọn một trong các loại thuốc sau:", "*Chú ý: Không dùng doxycycllin cho phụ nữ có thai và cho con bú. Đề phũng lậu mắt ở trẻ sơ sinh: ngay khi trẻ mới được đẻ ra phải nhỏ mắt cho trẻ dung dịch Nitrat bạc 1%. Nếu mẹ bị lậu chưa điều trị khỏi có thể điều trị phòng ngừa cho trẻ."], "bullets": ["+Có dịch tiết từ cổ tử cung: màu vàng hoặc xanh, số lượng không nhiều. Cổ tử cung đỏ, phù nề và chạm vào dễ chảy máu.", "+Ngứa âm đạo, tiểu khó.", "+Ngoài ra có thể tổn thương viêm niệu đạo, tuyến Bartholin, hậu môn hoặc nhiễm trùng cao hơn ở buông tử cung, vòi trứng ư buồng trứng.", "+Doxycycllin 100 mg uống 2 viên/ ngày trong 10 ngày", "+Erythromycin 500 mg uống 2 lần/ ngày trong 10 ngày", "+Azithromycin 1g uèng liÒu duy nhÊt"]}, {"heading": "3.6. Viêm âm đạo do Gardnerella vaginalis", "paragraphs": ["Là loại Gram (ư) hình que.", "ưTriệu chứng", "ưĐiều trị"], "bullets": ["+Khí hư nhiều, hôi, đục, ngứa, tăng lên quanh thời kỳ phóng noãn, trước kinh.", "+Niêm mạc âm đạo bình thường, khí hư đục dính vào âm đạo.", "+Lấy khí hư soi tươi sẽ thấy tập hợp tế bào có nhiều trực khuẩn hình gậy bám.", "+Trên tiêu bản có khí hư nhỏ dung dịch KOH 10% thấy có mùi tanh cá.", "+Ampicilline 2g/ ngày trong 10 ngày hoặc", "+Amoxycillin 1g/ ngày trong 10 ngày"]}, {"heading": "3.7. Lộ tuyến cổ tử cung", "paragraphs": ["Lộ tuyến cổ tử cung là tổn thương trong đó biểu mô trụ của ống cổ tử cung phát triển ra phía ngoài và thay thế biểu mô lát của mặt ngoài cổ tử cung bị huỷ hoại.", "ưTriệu chứng:", "Khi bôi cid acetic 3% vùng lộ tuyến trở nên trắng đục, có hình chùm nho hay ngón tay găng (chứng nghiệm Hinselmann dương tính)", "Khi bôi dung dịch Lugol: sau 1ư2 giây lugol sẽ bám vào biểu mô lát, bình thường biểu mô có màu nâu gụ. ở những vùng lộ tuyến không bắt màu Lugol (chứng nghiệm Schiller âm tính).", "ưĐiều trị: Cách điều trị thông thường là diệt tuyến (có thể bằng nhiệt, đốt điện, áp lạnh hoặc dùng laser) để gây ra quá trình tái tạo biểu mô phủ ngược lại."], "bullets": ["+Niêm mạc ống cổ tử cung lộ ra ngoài, bị kích thích bởi pH âm đạo toan nên chế tiết nhiều chất nhầy. Bệnh nhân thấy khí hư ra nhiều. Dễ bị nhiễm khuẩn do các mầm bệnh sẵn có trong âm đạo. Triệu chứng cơ năng điển hình nhất là khí hư đục ra nhiều và viêm  âm  đạo cổ tử cung tái phát nhiều lần, đặt thuốc nhiều mà không khỏi.", "+Khám: bằng mỏ vịt thấy niêm mạc ống cổ tử cung mọc bò ra ngoài, hơi sần, màu hồng, không có tính chất nhẵn bóng của biểu mô lát, chảy máu khi chạm vào, chất nhầy đục.", "+Trước khi diệt tuyến cần điều trị cho hết đợt viêm âm đạo cổ tử cung cấp (nếu có), nên làm Pap’smear trước khi đốt điện.", "+Nên thực hiện diệt tuyến sau sạch kinh 3ư4 ngày.", "+Kiêng quan hệ vợ chồng 1 tháng sau diệt tuyến, có thể đặt thuốc âm đạo kết hợp."]}, {"heading": "4. Viêm niêm mạc tử cung", "paragraphs": ["Trong phụ khoa, viêm niêm mạc tử cung ít gặp, mầm bệnh do vi khuẩn lậu và Chlamydia hoặc sau các can thiệp vào buồng tử cung (thường do tạp khuẩn)", "ưTriệu chứng", "ưĐiều trị: điều trị theo nguyên nhân."], "bullets": ["+Viêm niêm mạc tử cung do lậu: sau giao hợp vài ngày khí hư ra nhiều, như mủ, đặc, màu xanh. Tử cung to, nắn đau. Xét nghiệm hoặc nuôi cấy khí hư thấy vi khuẩn lậu.", "+Viêm niêm mạc tử cung do Chlamydia: thường chỉ gây khí hư nhầy, đục hoặc không có triệu chứng, chẩn đoán xác định dựa vào xét nghiệm khí hư lấy từ buồng tử cung."]}, {"heading": "5. Viêm phần phụ", "paragraphs": ["Viêm phần phụ là loại bệnh khá phổ biến. Vòi trứng, buồng trứng, các dây chằng đều có thể bị viêm nhiễm, nhưng tổn thương ở vòi trứng là quan trọng, tổn thương ở buồng trứng thường là xơ nang hoá."], "bullets": []}, {"heading": "5.1. Vi khuẩn gây bệnh chủ yếu", "paragraphs": ["ưLậu cầu (Neisseria gonorrhea): chiếm 20ư40% viêm nhiễm hố chậu, xét nghiệm trực tiếp sẽ phát hiện song cầu khuẩn hình hạt cafe, bắt màu gram âm.", "ưChlamydia trachomatis: tỷ lệ 40 ư 50% của viêm nhiễm hố chậu, khó phát hiện khi xét nghiệm trực tiếp. Miễn dịch huỳnh quang là biện pháp tốt để phát hiện.", "ưCác loại vi khuẩn khác có thể gặp trong một số điều kiện như: nhóm ái khí (Colibacille, lactobacille, proteus, staphylococcus), nhóm kỵ khí (Bacteroides, fragilis, clostridium).", "Trong thực tế thì phần lớn các trường hợp viêm sinh dục đều do nhiều loại vi khuẩn gây ra nên việc điều trị thường gặp nhiều khó khăn."], "bullets": ["-Mycoplasma hominis."]}, {"heading": "5.2.1. Triệu chứng", "paragraphs": ["ưViêm phần phụ cấp thường xảy ra sau đẻ, sau sẩy thai hoặc sau các can thiệp thủ thuật như: nạo hút, đặt tháo vòng… và sau viêm âm đạo cấp do vi khuẩn lậu.", "ưTriệu chứng lâm sàng nổi bật là đau vùng bụng dưới, đau tăng khi đi lại, thường đau cả 2 bên (chiếm 90%).", "ưSốt: nhiệt độ hình cao nguyên,ít khi sốt cao, mạch nhanh.", "ưRối loạn kinh nguyệt xảy ra trong 50% các trường hợp, các dấu hiệu kích thích bụng dưới như: mót rặn, đi ỉa lỏng, tiểu khó, tiểu không hết nước tiểu (chiếm 15ư25% các trường hợp).", "ưCó thể buồn nôn hoặc nôn.", "ưKhám bụng thấy phản ứng thành bụng dưới, da bụng nóng.", "ưĐặt mỏ vịt: ÂĐ có nhiều khí hư, có khi là mủ, chiếm từ 39 ư 65% các trường hợp, nên lấy dịch ÂĐ để làm xét nghiệm.", "ưThăm ÂĐ kết hợp với nắn bụng: thấy tử cung mềm, di động tử cung đau, 2 phần phụ nề đau. Đôi khi phát hiện thấy khối cạnh tử cung, thường ở mặt sau tử cung, dính không di động, không rõ ranh giới, ấn đau.", "ưCận lâm sàng:"], "bullets": ["+Công thức máu: bặch cầu tăng, đặc biệt bạch cầu đa nhân trung tính tăng cao.", "+CRP (C reactin protein) tăng.", "+Cấy máu: có thể phát hiện vi khuẩn gây bệnh. Xét nghiệm dịch cổ tử cung để phát hiện vi khuẩn lậu và Chlamydia. Trên thực tế xét nghiệm không phải lúc nào cũng cho kết quả dương tính vì viêm phần phụ có thể xảy ra do tập khuẩn. Siêu âm để phát hiện các khối viêm nhiễm và áp xe phần phụ."]}, {"heading": "5.2.2. Chẩn đoán", "paragraphs": ["ưChẩn đoán xác định: dựa vào tiền sử có bị bệnh lây truyền qua đường tình dục, nhiễm khuẩn sau một thủ thuật ở buồng tử cung và các triệu chứng đau hạ vị, sốt, có khối nề cạnh tử cung ấn đau.", "ưChẩn đoán phân biệt:"], "bullets": ["+Viêm ruột thừa: viêm phần phụ thường đau cả 2 bên, điểm đau của phần phụ bên phải thường thấp hơn điểm đau viêm ruột thừa. Trong viêm ruột thừa nắn cùng đồ bên không đau. Nằm nghỉ, chườm đá thì các triệu chứng viêm phần phụ sẽ giảm.", "+Viêm phúc mạc tiểu khung: thường xảy ra sau sẩy thai, sau đẻ. Thể trạng nhiễm khuẩn rõ, sốt cao dao động, có phản ứng thành bụng vùng hố chậu.", "+Viêm tổ chức quanh tiểu khung: Chỉ xảy ra do nhiễm khuẩn sau đẻ, trong trường hợp cổ tử cung bị rách kéo lên cao, sau sẩy thai. Nhiễm khuẩn từ dưới lan lên đáy dây chằng rộng. Ba bốn ngày sau đẻ hoặc sẩy thai, bệnh nhân sốt, đau hạ vị và vùng bẹn, có dấu hiệu viêm cơ đáy chậu. Khám thấy khối nề cứng, ở thấp hơn so với viêm phần phụ.", "+U nang buồng trứng xoắn: Đau bụng đột ngột, dữ dội hơn. Khám thấy ở phần phụ có một khối tròn, cùng đồ bên không đau. Không có tiền sử viêm nhiễm đường sinh dục. Siêu âm phát hiện u buồng trứng.", "+Chửa ngoài tử cung: Tiền sử chậm kinh hoặc rối loạn kinh nguyệt, đau ở một bên hố chậu, khám thấy khối đau bờ không rõ cạnh tử cung, hCG (+), không có dấu hiệu nhiễm khuẩn sinh dục. Siêu âm không thấy túi ối trong buồng tử cung."]}, {"heading": "5.2.3.1. Viêm cấp", "paragraphs": ["ưĐiều trị tuyến cơ sở:", "Chó ý:", "ưĐiều trị nội trú:"], "bullets": ["+Orfloxacin 400mg đường uống trong 14 ngày hoặc", "+Levofloxacin 500 mg/ ngày trong 14 ngày.", "+Có thể phối hợp với Metronidazole 500 mg uống trong 14 ngày.", "+Có thể phối hợp với Doxycycllin 100 mg , 2 viên/ ngày x 14 ngày.", "+Điều trị ngoại trú nếu sau 24 ư 48h không cải thiện, phải nhập viện điều trị.", "+Để tránh tái phát phải điều trị cả bạn tình.", "+Cephalosporin thế hệ III 2g tiêm tĩnh mạch mỗi 12h và Doxycycllin 100mg tiêm tĩnh mạch mỗi 12h cho đến khi cải thiện.", "+Sau đó Doxycycllin 100 mgì 2 viên uống/ ngàyì 14 ngày."]}, {"heading": "5.2.3.2. áp xe phần phụ ư viêm phúc mạc đáy chậu", "paragraphs": ["Sau khi dùng kháng sinh toàn thân, phối hợp (Ceftriaxon + Aminosid + Metronidazole). Có thể điều trị bằng nội soi giải phóng các sợi dính, chọc dò túi mủ, rửa ổ áp xe, cần thiết có thể dẫn lưu.", "Có một số tác giả khuyên nên dùng kháng sinh mạnh sau đó nội soi gỡ dính, tháo mủ và dẫn lưu ổ bụng."], "bullets": []}, {"heading": "5.2.3.3. Viêm phúc mạc toàn thể", "paragraphs": ["Do nhiễm khuẩn lan ra khỏi hố chậu nên phải can thiệp ngoại khoa để giải quyết nguyên nhân, làm sạch và dẫn lưu ổ bụng, lấy bệnh phẩm xét nghiệm vi khuẩn sau khi đã sử dụng kháng sinh liều cao để khu trú tổn thương, bồi phụ nước, điện giải."], "bullets": []}, {"heading": "5.3. Viêm phần phụ bán cấp", "paragraphs": ["Chiếm 30% các trường hợp:", "ưĐau âm ỉ vùng hạ vị hoặc thắt lưng, có khi đau chói.", "ưRong kinh thường hay gặp.", "ưKhí hư không rõ ràng và không đặc hiệu.", "ưKhám bụng: bụng mềm, có phản ứng cục bộ vùng bụng dưới.", "ưThăm ÂĐ: có thể thấy đau một hoặc 2 bên phần phụ, có khối nề khó phân biệt ranh giới với tử cung, đau khi di động CTC.", "ưKhám trực tràng: đau khi thăm khám.", "ưBạch cầu: tăng, bạch cầu đa nhân trung tính tăng (tăng vừa phải).", "ưCRP tăng.", "ưSiêu âm: xác định được khối phần phụ với âm vang hỗn hợp.", "ưNội soi ổ bụng: Có thể gặp các tổn thương phối hợp viêm phần phụ, viêm quanh gan dạng màng dính giữa gan và cơ hoành hoặc mặt trên gan với thành trước ổ bụng như các sợi dây đàn violon (hội chứng Fitz ư Hugh ư Curtis: viêm quanh gan thứ phát sau viêm sinh dục không đặc hiệu. Có các dấu hiệu sốt, đau hạ sườn phải lan lên vai, có các dấu hiệu ở tiểu khung nghĩ đến viêm phần phụ. Tuy nhiên không có vàng da, các xét nghiệm chức năng gan và siêu âm đường mật đều bình thường).", "Điều trị: Viêm phúc mạc dính cần phải ưu tiên điều trị Chlamydia trachomatis bằng cách phối hợp nhóm cyclin (Doxycycllin, Vibramycin) với Gentamycin hoặc Metronidazole. Thời gian điều trị khoảng 21 ngày. Trong tất cả các trường hợp nên phối hợp điều trị cả bạn tình."], "bullets": ["-Sèt nhÑ, 37,5 - 380c."]}, {"heading": "5.4.1. Triệu chứng", "paragraphs": ["ưNguyên nhân: do viêm phần phụ cấp tính không được điều trị đầy đủ, kịp thời.", "ưTriệu chứng:", "Đau vùng hạ vị hay hai bên hố chậu, thường có một bên trội hơn. Đau thay đổi về cường độ, thời gian, từng cơn hay liên tục, khi đi lại nhiều lần hay làm việc nặng thì đau tăng, khi nghỉ ngơi đau ít hơn.", "Khí hư: không nhiều, không đặc hiệu.", "Ra máu: có thể ra máu bất thường trước và sau khi hành kinh hoặc rong kinh.", "Tử cung di động hạn chế, đau khi di động.", "Có thể sờ thấy khối cạnh tử cung, ấn đau, ranh giới không rõ do vòi tử cung dính với buồng trứng thành 1 khối"], "bullets": ["+Cơ năng:", "+Thực thể: thăm ÂĐ kết hợp nắn bụng:"]}, {"heading": "5.4.2. Chẩn đoán", "paragraphs": ["ưChẩn đoán xác định: dựa vào có tiền sử viêm phần phụ cấp, triệu chứng cơ năng kết hợp khám thực thể có đau cạnh tử cung, tử cung kém di động.", "ưChẩn đoán phân biệt:"], "bullets": ["+U nang buồng trứng: Khi viêm phần phụ có ứ nước thì triệu chứng thực thể rất giống u nang buồng trứng.", "+Chửa ngoài tử cung (thể chưa vỡ): đôi khi viêm phần phụ có đau, ra huyết bất thường nên triệu chứng giống như chửa ngoài tử cung. Trong viêm phần phụ nếu bệnh nhân được nghỉ ngơi, chườm đá các triệu chứng sẽ giảm."]}, {"heading": "5.4.3. TiÕn triÓn", "paragraphs": ["Thường kéo dài, bệnh nhân hay bị đau tái phát sau lao động nặng, đi lại nhiều. Có khi tái phát cấp tính sau thủ thuật can thiệp buồng tử cung hay cổ tử cung."], "bullets": []}, {"heading": "5.4.4. Điều trị", "paragraphs": ["Nghỉ ngơi, làm việc nhẹ nhàng, tránh đi lại nhiều, sinh hoạt điều độ.", "Khi đau nhiều, khí hư đục: dùng kháng sinh nhóm Aminosid phối hợp với Lincosamid hoặc Metronidazole.", "Điều trị tại chỗ bằng lý liệu pháp sóng ngắn, các sóng ngắn tạo nên dòng điện có tần số cao kích thích khả năng trao đổi chất tế bào, tăng cường sức đề kháng tế bào, Chạy sóng ngắn từ 10 ư 12 buổi, mỗi lần từ 15ư30 phút. Không điều trị sóng ngắn ở hình thái bán cấp và trong lúc có kinh.", "Điều trị ngoại khoa: rất hãn hữu. áp dụng khi viêm phần phụ mãn có đau nhiều, liên tục, có khối rõ, ảnh hưởng rõ rệt đến sinh hoạt và khả năng lao động, bệnh nhân ko có nhu cầu sinh đẻ nữa( mổ cắt tử cung và cả khối phần phụ dính gồm vòi trứng ± buồng trứng."], "bullets": []}, {"heading": "5.5. TiÕn triÓn", "paragraphs": ["ưThuận lợi: Khi sử dụng kháng sinh sớm, phù hợp, bệnh sẽ diễn biến tốt: hết sốt, đỡ đau bụng, các xét nghiệm cân lâm sàng sẽ trở về bình thường trong một vài ngày. Nội soi có thể chỉ định nếu vẫn tồn tại một khối ở tiểu khung sau khi đã dùng kháng sinh phù hợp.", "ưViêm phúc mạc đáy chậu: Là hậu quả khi viêm phần phụ không được điều trị đúng cách, viêm phúc mạc khu trú ở đáy chậu, các tạng lân cận, đặc biệt là mạc nối lớn, đại tràng sigma cùng với các quai ruột dính lại che phủ làm hạn chế sự lan rộng của nhiễm khuẩn.", "ưÁp xe phần phụ: ổ áp xe được hình thành từ một viêm phần phụ không được điều trị đúng cách. Siêu âm cho hình ảnh khối cạnh tử cung, bờ dày, âm vang hỗn hợp. Soi ổ bụng cho phép chọc dò tháo mủ, rửa ổ áp xe kết hợp kháng sinh phổ rộng.", "ưÁp xe buồng trứng: hiếm gặp, bệnh cảnh lâm sàng giống như ứ mủ vòi trứng. Khi mổ phát hiện được phải cắt bỏ buồng trứng.", "ưViêm tấy lan toả đáy chậu: Nhiễm khuẩn có thể tại nên một khối áp xe dưới phúc mạc, có thể lan lên cao hơn trong dây chằng rộng hoặc xuống dưới ra phía TSM. Điều trị thường là phẫu thuật dẫn lưu ổ mủ.", "ưViêm phúc mạc toàn thể: Nhiễm khuẩn lan ra khỏi hố chậu gây viêm phúc mạc toàn thể. Có các dấu hiệu của nhiễm khuẩn nặng: sốt cao, nhiễm trùng nhiễm độc… Có các dấu hiệu bụng ngoại khoa: phản ứng thành bụng, cảm ứng phúc mạc.", "ưTiến triển lâu dài: Có thể có các đợt tái phát nặng nhẹ khi có nhiễm khuẩn cơ hội (trong hay ngoài cơ quan sinh dục)."], "bullets": []}, {"heading": "Câu hỏi:", "paragraphs": ["1: Trình bày triệu chứng lâm sàng, cận lâm sàng để chẩn đoán viêm âm đạo - cổ tử cung do nấm Candida albicans, Hướng điều trị?", "2: Trình bày triệu chứng lâm sàng, cận lâm sàng để chẩn đoán viêm âm đạo - cổ tử cung do Trichomonas, Hướng điều trị?", "3: Trình bày triệu chứng lâm sàng, cận lâm sàng để chẩn đoán viêm âm đạo - cổ tử cung do vi khuẩn, Hướng điều trị?", "4: Trình bày triệu chứng lâm sàng, cận lâm sàng để chẩn đoán viêm âm đạo - cổ tử cung do lậu cầu, Hướng điều trị?", "5: Trình bày triệu chứng lâm sàng, cận lâm sàng để chẩn đoán viêm âm đạo - cổ tử cung do Chlamdia trachomatis, Hướng điều trị?", "6: Trình bày triệu chứng chẩn đoán lộ tuyến cổ tử cung, hướng điều trị?", "7: Trình bày triệu chứng lâm sàng, cận lâm sàng để chẩn đoán xác định viêm phần phụ cấp, Hướng điều trị?", "8: Trình bày triệu chứng lâm sàng, cận lâm sàng để chẩn đoán xác định viêm phần phụ mạn, Hướng điều trị?"], "bullets": []}], "raw_text": "Viêm sinh dục\nMục tiêu học tập\nLiệt kê các loại vi khuẩn gây bệnh thường gặp\nKể được các thể lâm sàng của viêm âm đạo\nXác định cách điều trị thích hợp cho mỗi loại viêm âm đạo.\n4. Kể được các thể lâm sàng của viêm phần phụ.\n5. Trình bày được hướng xử trí của các dạng viêm phần phụ.\n1. Đại cương\nViêm nhiễm cơ quan sinh dục là loại bệnh khá phổ biến trong dời sống của người phụ nữ, nguyên nhân đa dạng, diễn biến phức tạp dẫn đến việc điều trị khó khăn, đôi lúc để lại biến chứng như viêm tiểu khung, vô sinh, chửa ngoài tử cung, sẩy thai, đẻ non, viêm kết mạc mắt trẻ sơ sinh…\n1.1. Đặc điểm\nưPhổ biến hay gặp trong độ tuổi hoạt động sinh dục.\nưCác bộ phận của đường sinh dục dưới và trên đều có thể bị viêm nhiễm.\nưHình thái cấp tính và mạn tính đều có thể gặp, hình thái mạn tính điều trị kéo dài, kém hiệu quả.\nưPhát hiện bệnh sớm điều trị sẽ khỏi hẳn và tránh được những biến chứng xấu như viêm tắc vòi tử cung, đau trong viêm phần phụ mạn tính.\n1.2. YÕu tè thuËn lîi\nưLây qua đường tình dục (giao hợp với người bị bệnh lây truyền qua đường tình dục).\nưSau các can thiệp thủ thuật như đình chỉ thai nghén, đặt dụng cụ tử cung, chụp tử cung vòi trứng.\nưNhiễm khuẩn sau sẩy, sau đẻ.\nưKém vệ sinh khi giao hợp, sau khi hành kinh.\n1.3. KhÝ h­\nBình thường ở CTC và ÂĐ có một chất dịch trắng trong hơi đặc, hoặc như lòng trắng trứng, lượng ít không chảy ra bên ngoài, không làm cho người phụ nữ để ý, đó là dịch sinh lý, dịch này có pH # 3,8ư4,6 tạo nên môi trường bảo vệ cho ÂĐ chống lại sự nhiễm khuẩn nhưng cũng có thể là yếu tố thuận lợi cho sự phát triển của mầm bệnh, pH này do sự chuyển hoá glycogen ở tế bào niêm mạc ÂĐ ư CTC thành acid lactic bởi trực khuẩn Doderlin.\nKhi ÂĐ bị viêm nhiễm, dịch tiết ra nhiều, gây khó chịu làm người phụ nữ lo lắng, trong trường hợp này dù màu sắc như thế nào, trắng hay vàng, có mùi hay không đều là bệnh lý.\n1.4. Các loại tác nhân gây bệnh\nCác vi khuẩn Gr (ư), Gr (+) đều có thể có mặt trong viêm sinh dục.\n1.4.1. Vi khuẩn không gây bệnh:\n-Trùc khuÈn Doderlin.\n-Stphylococcus epidermidis.\n1.4.2. Các vi khuẩn gây bệnh cơ hội:\n\nCác cầu khuẩn ái khí\nCác trực khuẩn ái khí\nCác vi khuẩn kỵ khí\n\nStreptococcus alpha\nStreptococcus tan huyÕt A, C, G\nStreptococcus aureus\nStreptococcus agaltiea\nColibacille\nColiforme\nProteus, pseudomonas\nKlebsiella\nEnterobacter\nStreptocque beta\nBacteroides\nClostridium\nFusobacterie\n\n\n1.4.3. Vi khuẩn, virus và ký sinh trùng luôn gây bệnh:\n-Neisseria gonorrhea\n-Trichomonas vaginalis\nưCandida albicans: có thể là cộng sinh nhưng sẽ gây bệnh khi tăng sinh bất thường\n-Chlamydia trachomatis\n-Treponema pallidum\nưGardnerella vaginalis: có thể là cộng sinh, gây bệnh khi tăng sinh bất thường\n-Herpes simplex virus\n-Human papilloma virus\n-HIV\n1.4.4. Các mầm bệnh thường gặp gây viêm ÂĐ:\nưNấm men gây viêm ÂH ư ÂĐ\nưTrùng roi gây viêm ÂĐ\nưVi khuẩn gây viêm ÂĐ do vi khuẩn\nưLậu cầu khuẩn gây viêm CTC mủ nhầy và viêm niệu đạo\nưChlamydia trachomatis gây viêm CTC mủ nhầy và viêm niệu đạo\n2. Viêm tuyến Bartholin\nMầm bệnh thường do vi khuẩn lậu, các vi khuẩn khác như liên cầu, tụ cầu hoặc trực khuẩn Chlamydia từ viêm âm hộ lan đến tuyến Bartholin, có khi ống tuyến bị tắc, tuyến bị nang hoá và bị nhiễm khuẩn thứ phát, có thể gặp trong trường hợp cắt TSM.\n2.1. Viêm tuyến Bartholin cấp\nBệnh nhân đau ở vùng âm hộ, thường đau một bên, đi đứng đều đau. Viêm lúc đầu khu trú sau lan toả, phát triển có mủ.\nKhám bằng cách dùng ngón cái và ngón trỏ nắn môi bé thấy một khối có khi to bằng quả trứng rắn tròn đều. Nắn thấy đau, nặn sẽ thấy mủ chảy ra ở cửa tuyến (ở mặt trong môi bé).\n2.2. Viêm tuyến Bartholin mạn\nThường xảy ra sau đợt điều trị viêm tuyến Bartholin cấp, điều trị không triệt để hoặc đã chích.\nHoàn cảnh xuất hiện: sau kinh nguyệt, sau viêm âm hộ, sau giao hợp tuyến lại to lên, nắn thấy rắn, đau (không nhiều) và có ít mủ chảy ra.\n2.3. Nang tuyÕn Bartholin\nTuyến bị nang hoá sau viêm cấp, viêm mạn hoặc ống tuyến bị tắc. Khi nang hoá có thể sờ thấy khối cứng, khu trú ơ một bên, nang có thể ở vị trí nông, sâu. Nếu bị nhiễm khuẩn nang trở thành khối apxe mủ.\nSau khi khám thực thể cần lấy mủ tiết để xác định loại vi khuẩn, đồng thời lấy bệnh phẩm cả ở niệu đạo, CTC để xét nghiệm.\nĐiều trị:\nNéi khoa:\nDo vi khuẩn Gr(+), Gr(ư): dùng kháng sinh nhóm βư Lactam, nhóm Cephalosporin (1ư2 g/ngày)\nDo vi khuẩn kỵ khí Gr(+), Gr(ư) hay lậu cầu: Penicillin procain 5ì 106 UI/ngàyì 7 ngày hoặc Spectinomycin 2g/ ngày, 1 lần hoặc Pefloxacin 800 mg/ liều duy nhất\nVới Chlamydia: Doxycyclin 200 mg/ ngày trong 10 ngày\nNgoại khoa: Chích dẫn lưu, mở rộng ống tiết, huỷ vách ngăn, dẫn lưu trong 2ư3 ngày.\nVới thể mạn tính hay nang hoá: bóc nang. Sau điều trị ngoại khoa, di chứng là giao hợp đau.\n3. Viêm âm đạo cổ tử cung\n3.1. Viêm âm đạo do trùng roi (Trichomonas vaginalis): Là bệnh lây qua đường quan hệ tình dục là chủ yếu, ngoài ra có thể lây qua nguồn nước: bồn tắm, khăn tắm.\nưTriệu chứng\n+ủ bệnh từ 1ư4 tuần. 25% số người mắc không biểu hiện bệnh\n+Khí hư: số lượng nhiều, loãng, có bọt, màu vàng xanh, hôi.\n+Có thể kèm theo ngứa, đi tiểu khó và đau khi giao hợp.\n+Khám: âm hộ, âm đạo, cổ tử cung viêm đỏ, phù nề, có nhiều khí hư màu vàng xanh loãng và có bọt ở cùng đồ.\nưXét nghiệm\n+Lấy dịch khí hư cho vào nước muối sinh lý soi tươi thấy có trùng roi ÂĐ hình hạt chanh đang di động.\n+Chứng nghiệm Sniff (Whiff test): nhỏ một giọt KOH 10% vào dịch khí hư thấy có mùi cá ươn và mất đi nhanh.\n+Đo pH >4,5.\nưĐiều trị\n+Vệ sinh ÂH, ÂĐ, quần áo lót phải được giặt sạch, phơi nắng hoặc là trước khi dùng.\n+Không giao hợp trong thời gian điều trị.\n+Metronidazole 2g uống liều duy nhất, hoặc\n+ Metronidazole 500mg uống 2 lần/ ngày x 7 ngày.\n+Có thể phối hợp đặt thuốc ÂĐ.\n+Cần điều trị cho chồng hoặc bạn tình: Metronidazole 2g liều duy nhất.\n*Chú ý: Metronidazole không dùng cho phụ nữ có thai 3 tháng đầu, không được uống rượu khi đang dùng thuốc cho đến 24h sau khi ngừng thuốc.\n3.2. Viêm âm đạo do nấm: Là bệnh do nấm Candida gây nên (chủ yếu là Candida albicans). Chiếm khoảng 20% các trường hợp viêm ÂĐ.\nưTriệu chứng\n+Ngứa nhiều vùng ÂH, ÂĐ.\n+Khí hư màu trắng đục như váng sữa, không hôi.\n+Có thể kèm theo đi tiểu khó, đau khi giao hợp.\n+Khám: ÂH, ÂĐ viêm đỏ, có thể xây xước nhiễm khuẩn do gãi, nếu nặng có thể bị viêm cả vùng TSM và đùi bẹn. Khí hư thường nhiều, màu trắng như váng sữa, thành mảng dày dính vào thành ÂĐ, ở dưới có vết trợt đỏ.\nưXét nghiệm\n+Soi tươi hoặc nhuộm Gram tìm nấm men. Nuôi cấy ở môi trường Sabouraud.\n+Sniff test (-).\n+Đo pH <4,5.\nưĐiều trị\n+Vệ sinh ÂĐ, quần áo lót sạch, được phơi nắng hoặc là trước khi mặc.\n+Không giao hợp trong thời gian điều trị.\n+Itraconazole (Sporal) 100mg uống 2v/ ngày x 3 ngày hoặc\nFluconazole 150mg uống 1 viên duy nhất hoặc\nMiconazole 200mg, đặt ÂĐ 1 viên trước khi đi ngủ x 3 ngày hoặc\nClotrimazole 500mg, đặt 1 viên ÂĐ duy nhất hoặc\nEconazole 150mg đặt 1 viên vào ÂĐ trước khi ngủ x 2 ngày hoặc\nNystatin 100.000 đơn vị đặt 1 viên ÂĐ trước khi ngủ x14 ngày liên tục (kể cả khi có kinh).\n+Tỷ lệ tái phát 15%.\n3.3. Viêm âm đạo do tạp khuẩn\nLà bệnh viêm ÂĐ không dặc hiệu, không lây qua quan hệ tình dục nên không cần điều trị cho chồng hoặc bạn tình\nưNguyên nhân: chủ yếu do Mycoplasma hominis, Mobiluncus có thể phối hợp với một số vi khuẩn yếm khí khác.\nưYếu tố thuận lợi: hay gặp ở người mãn kinh, người bị cắt 2 buồng trứng, trẻ em gái trước tuổi dậy thì.\nưTriệu chứng:\n+Ra nhiều khí hư mùi hôi như mùi tanh cá\n+Khám: khí hư mùi hôi như mùi cá ươn, màu xám trắng, đồng nhất như kem phết đều vào thành ÂĐ một lớp mỏng, không có viêm ÂĐ.\nưXét nghiệm: chẩn đoán dựa vào nhuộm Gram hoặc có 3/4 tiêu chí của Amsel:\n+Ra khÝ h­.\n+pH > 4,5.\n+Soi tươi hoặc nhuộm Gram có tế bào ÂĐ dính các vi khuẩn (Clue cells).\n+Test Sniff (+).\nưĐiều trị: Metronidazole là thuốc có hiệu quả nhất\n+ Vệ sinh ÂĐ, quần áo lót sạch, được phơi nắng hoặc là trước khi mặc.\n+Không giao hợp trong thời gian điều trị.\n+Metronidazole 2g uống liều duy nhất hoặc\n+ Metronidazole 500mg uống 2 lần/ ngày x 7 ngày hoặc\n+Kem Clindamycine 2% bôi tại chỗ trong 7 ngày hoặc\n+Clindamycine 300 mg uống 2 lần/ ngày x 7 ngày\n+Có thể phối hợp đặt thuốc âm đạo\n*Chú ý: Metronidazole không dùng cho phụ nữ có thai 3 tháng đầu. Trong khi uống thuốc không được uống rượu, không quan hệ tình dục.\n3.4. Viêm cổ tử cung mủ nhầy do lậu\nưTriệu chứng\n+Biểu hiện cấp tính: đái buốt, mủ chảy ra từ niệu đạo, từ cổ tử cung; mủ màu vàng đặc hoặc vàng xanh, số lượng nhiều, mùi hôi. Bệnh nhân đau khi giao hợp, đau bụng dưới.\n+Khám mỏ vịt thấy: cổ tử cung đỏ, phù nề, chạm vào chảy máu. Mủ chảy ra từ ống cổ tử cung. Có thể thấy lỗ niệu đạo đỏ, có mủ hoặc dịch đục từ trong chảy ra.\n+Thể mãn tính: triệu chứng lâm sàng không rõ ràng mà thường kín đáo, thậm chí không biểu hiện triệu chứng bệnh (trên 50% trường hợp) vì vậy họ không biết mình bị bệnh nên dễ lây lan cho người khác và trẻ sơ sinh.\nưXét nghiệm\n+Thường lấy bệnh phẩm ở 2 vị trí là niệu đạo và cổ tử cung. Hậu môn, các tuyến Sken, Bartholin cũng là nơi thường có lậu cầu.\n+Nhuộm Gram: song cầu khuẩn hình hạt cafe, bắt màu gram (ư) nằm trong và ngoài bạch cầu đa nhân, tế bào mủ.\nưĐiều trị: có thể lựa chọn một trong các loại thuốc sau:\n+Cefixime 400 mg uèng liÒu duy nhÊt\n+Spectinomycin 2g tiêm bắp liều duy nhất\n+Cefotaxime 1g tiêm bắp liều duy nhất.\n+Điều trị cho cả bạn tình.\n*Chú ý: ở Việt Nam, lậu cầu khuẩn đã kháng lại các kháng sinh thuộc nhóm Quinolone, Penicilline, Kanamycin. Viêm âm đạo do lậu thường kèm theo các tác nhân gây bệnh khác nên thường phải điều trị phối hợp.\n3.5. Viêm cổ tử cung và niệu đạo do Chlamydia trachomatis\nNhiễm Chlamydia trachomatis ở sinh dục ư tiết niệu nữ thường không biểu hiện triệu chứng (70%), thông thường được phát hiện khi bạn tình có viêm niệu đạo.\nưTriệu chứng\n+Có dịch tiết từ cổ tử cung: màu vàng hoặc xanh, số lượng không nhiều. Cổ tử cung đỏ, phù nề và chạm vào dễ chảy máu.\n+Ngứa âm đạo, tiểu khó.\n+Ngoài ra có thể tổn thương viêm niệu đạo, tuyến Bartholin, hậu môn hoặc nhiễm trùng cao hơn ở buông tử cung, vòi trứng ư buồng trứng.\nưXét nghiệm\nCần lấy bệnh phẩm ở cổ tử cung, niệu đạo, hậu môn, tuyến Bartholin nuôi cấy tế bào, xét nghiệm PCR,v.v...\nưĐiều trị: có thể lựa chọn một trong các loại thuốc sau:\n+Doxycycllin 100 mg uống 2 viên/ ngày trong 10 ngày\n+Erythromycin 500 mg uống 2 lần/ ngày trong 10 ngày\n+Azithromycin 1g uèng liÒu duy nhÊt\n*Chú ý: Không dùng doxycycllin cho phụ nữ có thai và cho con bú. Đề phũng lậu mắt ở trẻ sơ sinh: ngay khi trẻ mới được đẻ ra phải nhỏ mắt cho trẻ dung dịch Nitrat bạc 1%. Nếu mẹ bị lậu chưa điều trị khỏi có thể điều trị phòng ngừa cho trẻ.\n3.6. Viêm âm đạo do Gardnerella vaginalis\nLà loại Gram (ư) hình que.\nưTriệu chứng\n+Khí hư nhiều, hôi, đục, ngứa, tăng lên quanh thời kỳ phóng noãn, trước kinh.\n+Niêm mạc âm đạo bình thường, khí hư đục dính vào âm đạo.\n+Lấy khí hư soi tươi sẽ thấy tập hợp tế bào có nhiều trực khuẩn hình gậy bám.\n+Trên tiêu bản có khí hư nhỏ dung dịch KOH 10% thấy có mùi tanh cá.\nưĐiều trị\n+Ampicilline 2g/ ngày trong 10 ngày hoặc\n+Amoxycillin 1g/ ngày trong 10 ngày\n3.7. Lộ tuyến cổ tử cung\nLộ tuyến cổ tử cung là tổn thương trong đó biểu mô trụ của ống cổ tử cung phát triển ra phía ngoài và thay thế biểu mô lát của mặt ngoài cổ tử cung bị huỷ hoại.\nưTriệu chứng:\n+Niêm mạc ống cổ tử cung lộ ra ngoài, bị kích thích bởi pH âm đạo toan nên chế tiết nhiều chất nhầy. Bệnh nhân thấy khí hư ra nhiều. Dễ bị nhiễm khuẩn do các mầm bệnh sẵn có trong âm đạo. Triệu chứng cơ năng điển hình nhất là khí hư đục ra nhiều và viêm  âm  đạo cổ tử cung tái phát nhiều lần, đặt thuốc nhiều mà không khỏi.\n+Khám: bằng mỏ vịt thấy niêm mạc ống cổ tử cung mọc bò ra ngoài, hơi sần, màu hồng, không có tính chất nhẵn bóng của biểu mô lát, chảy máu khi chạm vào, chất nhầy đục.\nKhi bôi cid acetic 3% vùng lộ tuyến trở nên trắng đục, có hình chùm nho hay ngón tay găng (chứng nghiệm Hinselmann dương tính)\nKhi bôi dung dịch Lugol: sau 1ư2 giây lugol sẽ bám vào biểu mô lát, bình thường biểu mô có màu nâu gụ. ở những vùng lộ tuyến không bắt màu Lugol (chứng nghiệm Schiller âm tính).\nưĐiều trị: Cách điều trị thông thường là diệt tuyến (có thể bằng nhiệt, đốt điện, áp lạnh hoặc dùng laser) để gây ra quá trình tái tạo biểu mô phủ ngược lại.\n+Trước khi diệt tuyến cần điều trị cho hết đợt viêm âm đạo cổ tử cung cấp (nếu có), nên làm Pap’smear trước khi đốt điện.\n+Nên thực hiện diệt tuyến sau sạch kinh 3ư4 ngày.\n+Kiêng quan hệ vợ chồng 1 tháng sau diệt tuyến, có thể đặt thuốc âm đạo kết hợp.\n4. Viêm niêm mạc tử cung\nTrong phụ khoa, viêm niêm mạc tử cung ít gặp, mầm bệnh do vi khuẩn lậu và Chlamydia hoặc sau các can thiệp vào buồng tử cung (thường do tạp khuẩn)\nưTriệu chứng\n+Viêm niêm mạc tử cung do lậu: sau giao hợp vài ngày khí hư ra nhiều, như mủ, đặc, màu xanh. Tử cung to, nắn đau. Xét nghiệm hoặc nuôi cấy khí hư thấy vi khuẩn lậu.\n+Viêm niêm mạc tử cung do Chlamydia: thường chỉ gây khí hư nhầy, đục hoặc không có triệu chứng, chẩn đoán xác định dựa vào xét nghiệm khí hư lấy từ buồng tử cung.\nưĐiều trị: điều trị theo nguyên nhân.\n5. Viêm phần phụ\nViêm phần phụ là loại bệnh khá phổ biến. Vòi trứng, buồng trứng, các dây chằng đều có thể bị viêm nhiễm, nhưng tổn thương ở vòi trứng là quan trọng, tổn thương ở buồng trứng thường là xơ nang hoá.\n5.1. Vi khuẩn gây bệnh chủ yếu\nưLậu cầu (Neisseria gonorrhea): chiếm 20ư40% viêm nhiễm hố chậu, xét nghiệm trực tiếp sẽ phát hiện song cầu khuẩn hình hạt cafe, bắt màu gram âm.\nưChlamydia trachomatis: tỷ lệ 40 ư 50% của viêm nhiễm hố chậu, khó phát hiện khi xét nghiệm trực tiếp. Miễn dịch huỳnh quang là biện pháp tốt để phát hiện.\n-Mycoplasma hominis.\nưCác loại vi khuẩn khác có thể gặp trong một số điều kiện như: nhóm ái khí (Colibacille, lactobacille, proteus, staphylococcus), nhóm kỵ khí (Bacteroides, fragilis, clostridium).\nTrong thực tế thì phần lớn các trường hợp viêm sinh dục đều do nhiều loại vi khuẩn gây ra nên việc điều trị thường gặp nhiều khó khăn.\n5.2. Viêm phần phụ cấp\n5.2.1. Triệu chứng\nưViêm phần phụ cấp thường xảy ra sau đẻ, sau sẩy thai hoặc sau các can thiệp thủ thuật như: nạo hút, đặt tháo vòng… và sau viêm âm đạo cấp do vi khuẩn lậu.\nưTriệu chứng lâm sàng nổi bật là đau vùng bụng dưới, đau tăng khi đi lại, thường đau cả 2 bên (chiếm 90%).\nưSốt: nhiệt độ hình cao nguyên,ít khi sốt cao, mạch nhanh.\nưRối loạn kinh nguyệt xảy ra trong 50% các trường hợp, các dấu hiệu kích thích bụng dưới như: mót rặn, đi ỉa lỏng, tiểu khó, tiểu không hết nước tiểu (chiếm 15ư25% các trường hợp).\nưCó thể buồn nôn hoặc nôn.\nưKhám bụng thấy phản ứng thành bụng dưới, da bụng nóng.\nưĐặt mỏ vịt: ÂĐ có nhiều khí hư, có khi là mủ, chiếm từ 39 ư 65% các trường hợp, nên lấy dịch ÂĐ để làm xét nghiệm.\nưThăm ÂĐ kết hợp với nắn bụng: thấy tử cung mềm, di động tử cung đau, 2 phần phụ nề đau. Đôi khi phát hiện thấy khối cạnh tử cung, thường ở mặt sau tử cung, dính không di động, không rõ ranh giới, ấn đau.\nưCận lâm sàng:\n+Công thức máu: bặch cầu tăng, đặc biệt bạch cầu đa nhân trung tính tăng cao.\n+CRP (C reactin protein) tăng.\n+Cấy máu: có thể phát hiện vi khuẩn gây bệnh. Xét nghiệm dịch cổ tử cung để phát hiện vi khuẩn lậu và Chlamydia. Trên thực tế xét nghiệm không phải lúc nào cũng cho kết quả dương tính vì viêm phần phụ có thể xảy ra do tập khuẩn. Siêu âm để phát hiện các khối viêm nhiễm và áp xe phần phụ.\n5.2.2. Chẩn đoán\nưChẩn đoán xác định: dựa vào tiền sử có bị bệnh lây truyền qua đường tình dục, nhiễm khuẩn sau một thủ thuật ở buồng tử cung và các triệu chứng đau hạ vị, sốt, có khối nề cạnh tử cung ấn đau.\nưChẩn đoán phân biệt:\n+Viêm ruột thừa: viêm phần phụ thường đau cả 2 bên, điểm đau của phần phụ bên phải thường thấp hơn điểm đau viêm ruột thừa. Trong viêm ruột thừa nắn cùng đồ bên không đau. Nằm nghỉ, chườm đá thì các triệu chứng viêm phần phụ sẽ giảm.\n+Viêm phúc mạc tiểu khung: thường xảy ra sau sẩy thai, sau đẻ. Thể trạng nhiễm khuẩn rõ, sốt cao dao động, có phản ứng thành bụng vùng hố chậu.\n+Viêm tổ chức quanh tiểu khung: Chỉ xảy ra do nhiễm khuẩn sau đẻ, trong trường hợp cổ tử cung bị rách kéo lên cao, sau sẩy thai. Nhiễm khuẩn từ dưới lan lên đáy dây chằng rộng. Ba bốn ngày sau đẻ hoặc sẩy thai, bệnh nhân sốt, đau hạ vị và vùng bẹn, có dấu hiệu viêm cơ đáy chậu. Khám thấy khối nề cứng, ở thấp hơn so với viêm phần phụ.\n+U nang buồng trứng xoắn: Đau bụng đột ngột, dữ dội hơn. Khám thấy ở phần phụ có một khối tròn, cùng đồ bên không đau. Không có tiền sử viêm nhiễm đường sinh dục. Siêu âm phát hiện u buồng trứng.\n+Chửa ngoài tử cung: Tiền sử chậm kinh hoặc rối loạn kinh nguyệt, đau ở một bên hố chậu, khám thấy khối đau bờ không rõ cạnh tử cung, hCG (+), không có dấu hiệu nhiễm khuẩn sinh dục. Siêu âm không thấy túi ối trong buồng tử cung.\n5.2.3. Điều trị\n5.2.3.1. Viêm cấp\nưĐiều trị tuyến cơ sở:\n+Orfloxacin 400mg đường uống trong 14 ngày hoặc\n+Levofloxacin 500 mg/ ngày trong 14 ngày.\n+Có thể phối hợp với Metronidazole 500 mg uống trong 14 ngày.\n+Có thể phối hợp với Doxycycllin 100 mg , 2 viên/ ngày x 14 ngày.\nChó ý:\n+Điều trị ngoại trú nếu sau 24 ư 48h không cải thiện, phải nhập viện điều trị.\n+Để tránh tái phát phải điều trị cả bạn tình.\nưĐiều trị nội trú:\n+Cephalosporin thế hệ III 2g tiêm tĩnh mạch mỗi 12h và Doxycycllin 100mg tiêm tĩnh mạch mỗi 12h cho đến khi cải thiện.\n+Sau đó Doxycycllin 100 mgì 2 viên uống/ ngàyì 14 ngày.\n5.2.3.2. áp xe phần phụ ư viêm phúc mạc đáy chậu\nSau khi dùng kháng sinh toàn thân, phối hợp (Ceftriaxon + Aminosid + Metronidazole). Có thể điều trị bằng nội soi giải phóng các sợi dính, chọc dò túi mủ, rửa ổ áp xe, cần thiết có thể dẫn lưu.\nCó một số tác giả khuyên nên dùng kháng sinh mạnh sau đó nội soi gỡ dính, tháo mủ và dẫn lưu ổ bụng.\n5.2.3.3. Viêm phúc mạc toàn thể\nDo nhiễm khuẩn lan ra khỏi hố chậu nên phải can thiệp ngoại khoa để giải quyết nguyên nhân, làm sạch và dẫn lưu ổ bụng, lấy bệnh phẩm xét nghiệm vi khuẩn sau khi đã sử dụng kháng sinh liều cao để khu trú tổn thương, bồi phụ nước, điện giải.\n5.3. Viêm phần phụ bán cấp\nChiếm 30% các trường hợp:\nưĐau âm ỉ vùng hạ vị hoặc thắt lưng, có khi đau chói.\nưRong kinh thường hay gặp.\nưKhí hư không rõ ràng và không đặc hiệu.\n-Sèt nhÑ, 37,5 - 380c.\nưKhám bụng: bụng mềm, có phản ứng cục bộ vùng bụng dưới.\nưThăm ÂĐ: có thể thấy đau một hoặc 2 bên phần phụ, có khối nề khó phân biệt ranh giới với tử cung, đau khi di động CTC.\nưKhám trực tràng: đau khi thăm khám.\nưBạch cầu: tăng, bạch cầu đa nhân trung tính tăng (tăng vừa phải).\nưCRP tăng.\nưSiêu âm: xác định được khối phần phụ với âm vang hỗn hợp.\nưNội soi ổ bụng: Có thể gặp các tổn thương phối hợp viêm phần phụ, viêm quanh gan dạng màng dính giữa gan và cơ hoành hoặc mặt trên gan với thành trước ổ bụng như các sợi dây đàn violon (hội chứng Fitz ư Hugh ư Curtis: viêm quanh gan thứ phát sau viêm sinh dục không đặc hiệu. Có các dấu hiệu sốt, đau hạ sườn phải lan lên vai, có các dấu hiệu ở tiểu khung nghĩ đến viêm phần phụ. Tuy nhiên không có vàng da, các xét nghiệm chức năng gan và siêu âm đường mật đều bình thường).\nĐiều trị: Viêm phúc mạc dính cần phải ưu tiên điều trị Chlamydia trachomatis bằng cách phối hợp nhóm cyclin (Doxycycllin, Vibramycin) với Gentamycin hoặc Metronidazole. Thời gian điều trị khoảng 21 ngày. Trong tất cả các trường hợp nên phối hợp điều trị cả bạn tình.\n5.4. Viêm phần phụ mạn tính\n5.4.1. Triệu chứng\nưNguyên nhân: do viêm phần phụ cấp tính không được điều trị đầy đủ, kịp thời.\nưTriệu chứng:\n+Cơ năng:\nĐau vùng hạ vị hay hai bên hố chậu, thường có một bên trội hơn. Đau thay đổi về cường độ, thời gian, từng cơn hay liên tục, khi đi lại nhiều lần hay làm việc nặng thì đau tăng, khi nghỉ ngơi đau ít hơn.\nKhí hư: không nhiều, không đặc hiệu.\nRa máu: có thể ra máu bất thường trước và sau khi hành kinh hoặc rong kinh.\n+Thực thể: thăm ÂĐ kết hợp nắn bụng:\nTử cung di động hạn chế, đau khi di động.\nCó thể sờ thấy khối cạnh tử cung, ấn đau, ranh giới không rõ do vòi tử cung dính với buồng trứng thành 1 khối\n5.4.2. Chẩn đoán\nưChẩn đoán xác định: dựa vào có tiền sử viêm phần phụ cấp, triệu chứng cơ năng kết hợp khám thực thể có đau cạnh tử cung, tử cung kém di động.\nưChẩn đoán phân biệt:\n+U nang buồng trứng: Khi viêm phần phụ có ứ nước thì triệu chứng thực thể rất giống u nang buồng trứng.\n+Chửa ngoài tử cung (thể chưa vỡ): đôi khi viêm phần phụ có đau, ra huyết bất thường nên triệu chứng giống như chửa ngoài tử cung. Trong viêm phần phụ nếu bệnh nhân được nghỉ ngơi, chườm đá các triệu chứng sẽ giảm.\n5.4.3. TiÕn triÓn\nThường kéo dài, bệnh nhân hay bị đau tái phát sau lao động nặng, đi lại nhiều. Có khi tái phát cấp tính sau thủ thuật can thiệp buồng tử cung hay cổ tử cung.\n5.4.4. Điều trị\nNghỉ ngơi, làm việc nhẹ nhàng, tránh đi lại nhiều, sinh hoạt điều độ.\nKhi đau nhiều, khí hư đục: dùng kháng sinh nhóm Aminosid phối hợp với Lincosamid hoặc Metronidazole.\nĐiều trị tại chỗ bằng lý liệu pháp sóng ngắn, các sóng ngắn tạo nên dòng điện có tần số cao kích thích khả năng trao đổi chất tế bào, tăng cường sức đề kháng tế bào, Chạy sóng ngắn từ 10 ư 12 buổi, mỗi lần từ 15ư30 phút. Không điều trị sóng ngắn ở hình thái bán cấp và trong lúc có kinh.\nĐiều trị ngoại khoa: rất hãn hữu. áp dụng khi viêm phần phụ mãn có đau nhiều, liên tục, có khối rõ, ảnh hưởng rõ rệt đến sinh hoạt và khả năng lao động, bệnh nhân ko có nhu cầu sinh đẻ nữa( mổ cắt tử cung và cả khối phần phụ dính gồm vòi trứng ± buồng trứng.\n5.5. TiÕn triÓn\nưThuận lợi: Khi sử dụng kháng sinh sớm, phù hợp, bệnh sẽ diễn biến tốt: hết sốt, đỡ đau bụng, các xét nghiệm cân lâm sàng sẽ trở về bình thường trong một vài ngày. Nội soi có thể chỉ định nếu vẫn tồn tại một khối ở tiểu khung sau khi đã dùng kháng sinh phù hợp.\nưViêm phúc mạc đáy chậu: Là hậu quả khi viêm phần phụ không được điều trị đúng cách, viêm phúc mạc khu trú ở đáy chậu, các tạng lân cận, đặc biệt là mạc nối lớn, đại tràng sigma cùng với các quai ruột dính lại che phủ làm hạn chế sự lan rộng của nhiễm khuẩn.\nưÁp xe phần phụ: ổ áp xe được hình thành từ một viêm phần phụ không được điều trị đúng cách. Siêu âm cho hình ảnh khối cạnh tử cung, bờ dày, âm vang hỗn hợp. Soi ổ bụng cho phép chọc dò tháo mủ, rửa ổ áp xe kết hợp kháng sinh phổ rộng.\nưÁp xe buồng trứng: hiếm gặp, bệnh cảnh lâm sàng giống như ứ mủ vòi trứng. Khi mổ phát hiện được phải cắt bỏ buồng trứng.\nưViêm tấy lan toả đáy chậu: Nhiễm khuẩn có thể tại nên một khối áp xe dưới phúc mạc, có thể lan lên cao hơn trong dây chằng rộng hoặc xuống dưới ra phía TSM. Điều trị thường là phẫu thuật dẫn lưu ổ mủ.\nưViêm phúc mạc toàn thể: Nhiễm khuẩn lan ra khỏi hố chậu gây viêm phúc mạc toàn thể. Có các dấu hiệu của nhiễm khuẩn nặng: sốt cao, nhiễm trùng nhiễm độc… Có các dấu hiệu bụng ngoại khoa: phản ứng thành bụng, cảm ứng phúc mạc.\nưTiến triển lâu dài: Có thể có các đợt tái phát nặng nhẹ khi có nhiễm khuẩn cơ hội (trong hay ngoài cơ quan sinh dục).\nCâu hỏi:\n1: Trình bày triệu chứng lâm sàng, cận lâm sàng để chẩn đoán viêm âm đạo - cổ tử cung do nấm Candida albicans, Hướng điều trị?\n2: Trình bày triệu chứng lâm sàng, cận lâm sàng để chẩn đoán viêm âm đạo - cổ tử cung do Trichomonas, Hướng điều trị?\n3: Trình bày triệu chứng lâm sàng, cận lâm sàng để chẩn đoán viêm âm đạo - cổ tử cung do vi khuẩn, Hướng điều trị?\n4: Trình bày triệu chứng lâm sàng, cận lâm sàng để chẩn đoán viêm âm đạo - cổ tử cung do lậu cầu, Hướng điều trị?\n5: Trình bày triệu chứng lâm sàng, cận lâm sàng để chẩn đoán viêm âm đạo - cổ tử cung do Chlamdia trachomatis, Hướng điều trị?\n6: Trình bày triệu chứng chẩn đoán lộ tuyến cổ tử cung, hướng điều trị?\n7: Trình bày triệu chứng lâm sàng, cận lâm sàng để chẩn đoán xác định viêm phần phụ cấp, Hướng điều trị?\n8: Trình bày triệu chứng lâm sàng, cận lâm sàng để chẩn đoán xác định viêm phần phụ mạn, Hướng điều trị?", "priority": "Trung bình"}, {"id": "SK-46", "chapter": "Chương 3. Phụ khoa", "folder": "03_Phu_khoa", "title": "U xơ tử cung", "author": "TS. BS. Bùi Minh Tiến", "word_count": 2249, "line_count": 126, "key_numbers": ["10 ngày", "10mg", "15cm", "6 tháng", "8cm"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["U XƠ TỬ CUNG", "Ths. BSCK II. Hoàng Tiến Nam"], "bullets": []}, {"heading": "1. ĐẠI CƯƠNG", "paragraphs": [], "bullets": ["- U xơ tử cung (UXTC) là khối u lành tính, có nguồn gốc từ tế bào cơ trơn tử cung, tỷ lệ 20-30% ở các phụ nữ trong độ tuổi sinh đẻ, kích thước thường dưới 15cm. U xơ tử cung thường ít có triệu chứng. Tuy nhiên khi khối u lớn thì có thể gây rong kinh, rong huyết, đau và vô sinh. Nguyên nhân chưa được biết rõ, nhưng giả thuyết về cường estrogen được nhiều tác giả ủng hộ.", "- Thường gặp ở phụ nữ từ ≥ 40 tuổi", "- U xơ tử cung không gặp trước tuổi dậy thì."]}, {"heading": "2.1. Đại thể", "paragraphs": ["U xơ tử cung là một khối u đặc, không có vỏ, có hình tròn hoặc bầu dục, mật độ chắc, mặt cắt màu trắng, giới hạn rõ với lớp cơ tử cung bao quanh có màu hồng. Khối u có cấu trúc là cơ trơn.", "Số lượng u có thể chỉ có một hoặc nhiều nhân, kích thước không đều."], "bullets": []}, {"heading": "2.2. Vi thể", "paragraphs": ["Các sợi cơ trơn hợp thành bó, đan xen với nhau thành khối. Xen kẽ với sợi cơ trơn là tổ chức liên kết. Nhân tế bào có hình bầu dục, tròn, không có hình ảnh nhân chia. Khi mãn kinh khối u có thể nhỏ dần, sợi cơ giảm thay vào đó là các sợi collagen kèm canxi hoá. Ngoài ra niêm mạc tử cung dày lên kiểu quá sản.", "Hình 1. Bệnh phẩm u xơ tử cung: hình ảnh đại thể (trái) và hình ảnh vi thể (phải)"], "bullets": []}, {"heading": "3. VỊ TRÍ CỦA U XƠ TỬ CUNG", "paragraphs": ["Theo vị trí giải phẫu và cấu trúc của cơ tử cung thì u xơ tử cung được phân chia thành các loại sau:"], "bullets": []}, {"heading": "3.1. 1. U xơ dưới phúc mạc (10%)", "paragraphs": ["U ở dưới phúc mạc, có thể có cuống hoặc không có cuống. Triệu chứng lâm sàng nghèo nàn, u được phát hiện do biến chứng chèn ép các tạng xung quanh, làm thay đổi vị trí vòi tử cung, buồng trứng - loại này thường bị chẩn đoán nhầm với khối u buồng trứng."], "bullets": []}, {"heading": "3.1. 2. U xơ trong lớp cơ tử cung (60-70%)", "paragraphs": ["Loại này hay gặp nhất phát triển từ phần giữa của lớp cơ tử cung, u có thể lấn vào buồng tử cung, làm biến dạng buồng tử cung. Có thể có nhiều khối u, kích thước lớn, hình tròn và đối xứng."], "bullets": []}, {"heading": "3.1. 3. U xơ dưới niêm mạc (10-20%)", "paragraphs": ["Loại này thường chỉ có một khối u, hay phối hợp với các bất thường của niêm mạc tử cung, gây nhiều triệu chứng bất thường như ra huyết, kinh đau. U phát triển lấn vào buồng tử cung, niêm mạc tử cung bị hoại tử, chảy máu. Khi khối u có cuống, nó chui qua eo vào ống cổ tử cung hoặc nằm trong âm đạo, gọi là polyp buồng tử cung."], "bullets": []}, {"heading": "3.2. Ở cổ tử cung (10%)", "paragraphs": ["Loại này thường phát triển về phía âm đạo.  Nếu u xơ cổ tử cung phát triển ở thành sau, sẽ lấn vào cùng đồ Douglas gây chèn ép trực tràng. Nếu u xơ ở thành trước, nó sẽ phát triển trong hố chậu có thể đè vào bàng quang hoặc niệu đạo. Khối u có thể có cuống, được bao phủ bởi niêm mạc ống cổ tử cung, lấn ra ngoài lỗ cổ tử cung, cổ tử cung như bị xoá gọi là polyp ống cổ tử cung.", "Hình 2. Các vị trí của u xơ tử cung"], "bullets": []}, {"heading": "4. TRIỆU CHỨNG", "paragraphs": ["UXTC thường ít có triệu chứng và thường được phát hiện tình cờ. Các triệu chứng biểu hiện phụ thuộc vào vị trí và kích thước khối u."], "bullets": []}, {"heading": "4.1. Triệu chứng toàn thân:", "paragraphs": ["Có thể gặp tình trạng thiếu máu, mức độ thiếu máu phụ thuộc vào tình trạng mất máu"], "bullets": []}, {"heading": "4.2. Triệu chứng cơ năng", "paragraphs": ["Chèn ép trực tràng gây táo bón.", "Chèn ép bàng quang gầy đái buốt, đái rắt.", "Chèn ép niệu quản gây ứ nước thận", "U xơ tử cung dính vào ruột, chèn ép gây tắc ruột."], "bullets": ["- Khí hư loãng như nước.", "- Rong kinh, cường kinh là triệu chứng chính, gặp trong 60% trường hợp. Máu kinh thường có máu cục lẫn máu loãng. Kinh kéo dài ngày 7 - 10 ngày hoặc dài  hơn.", "- Đau vùng hạ vị hoặc vùng hố chậu, đau có thể tăng lên trước hoặc trong khi có kinh. Đau hoặc tức bụng kéo dài có thể do khối u chèn ép vào tạng lân cận."]}, {"heading": "4.3. Triệu chứng thực thể", "paragraphs": [], "bullets": ["- Nhìn: nếu khối u lớn có thể thấy khối u gồ lên ở vùng hạ vị", "- Sờ nắn bụng: khối u ở hạ vị có mật độ chắc, di động liên quan với tử cung.", "- Khám mỏ vịt: Nếu u xơ ở cổ tử cung có thể thấy polyp có cuống nằm ở lỗ ngoài cổ tử cung", "- Khám âm đạo phối hợp với nắn bụng: phát hiện toàn bộ tử cung to, chắc, nhẵn, đều (có khi gồ ghề) không đau. Nếu u xơ dưới thanh mạc có thể phát hiện cạnh tử cung một khối u tương tự như khối u phần phụ; Khi lay cổ tử cung, khối u di động theo.", "- Khám trực tràng: rất cần thiết để phân biệt u xơ tử cung phát triển về phía sau hay  khối u trực tràng."]}, {"heading": "4.4. Cận lâm sàng", "paragraphs": ["Hình 3. Hình ảnh u xơ tử cung dưới niêm mạc qua soi buồng"], "bullets": ["- Siêu âm : kích thước tử cung tăng, đo được kích thước của u xơ tử cung và kích thước của nhân xơ tử cung. Siêu âm cản quang (bơm nước muối hoặc dịch cản quang vào buồng tử cung) có thể phát hiện polyp buồng tử cung. Chẩn đoán siêu âm có thể khó khăn trong trường hợp u nang buồng trứng dính với tử cung, hoặc tử cung bị dị dạng.", "- Soi buồng tử cung để chẩn đoán và điều trị các u xơ dưới niêm mạc.", "- Xét nghiệm tế bào âm đạo để phát hiện các tổn thương cổ tử cung kèm theo.", "- CT- scan được chỉ định trong trường hợp cần phân biệt với các ung thư ở tiểu khung."]}, {"heading": "5.1. Chẩn đoán xác định", "paragraphs": ["Dựa vào triệu chứng cơ năng, thực thể và cận lâm sàng. Chẩn đoán thường dễ khi khối u lớn và có nhiều nhân xơ."], "bullets": []}, {"heading": "5.2. Chẩn đoán gián biệt", "paragraphs": [], "bullets": ["- Có thai: phải dựa vào xét nghiệm β hCG và siêu âm để phân biệt với có thai bình thường, doạ sẩy thai, thai chết lưu.", "- Khối u buồng trứng: thường biệt lập với tử cung, di động khối u không làm di chuyển cổ tử cung. Chẩn đoán phân biệt giữa khối u buồng trứng với u xơ tử cung dưới phúc mạc đôi khi khó khăn.", "- Ung thư thân tử cung: Tất cả những trường hợp ra huyết bất thường ở thời kỳ tiền mãn kinh, mãn kinh cần được loại trừ ung thư thân tử cung. Các xét nghiệm bổ sung như: soi buồng tử cung và nạo sinh thiết giúp chẩn đoán xác định."]}, {"heading": "6.1. Tiến triển", "paragraphs": ["U xơ tử cung thường tiến triển chậm, sau một thời gian khối u có thể tăng kích thước gây nên triệu chứng và biến chứng. Chỉ khoảng 0,05% trường hợp u xơ tử cung biến chứng thành sarcoma. Nếu khối u nhỏ không gây triệu chứng hoặc biến chứng gì đáng kể. Thời kỳ mãn kinh, u xơ tử cung có thể ngừng phát triển."], "bullets": []}, {"heading": "6.2.1. U xơ tử cung ở người không có thai", "paragraphs": [], "bullets": ["- Chảy máu:  rong kinh, rong huyết thường là biểu hiện chính, hay gặp trong u dưới niêm mạc. Ra huyết kéo dài dẫn đến thiếu máu.", "- Chèn ép:", "+ U xơ trong dây chằng rộng chèn ép vào niệu quản đưa đến ứ đọng đài bể thận. Biến cố nhẹ ở đường tiết niệu là đái rắt, đái khó...", "+ U xơ ở mặt sau tử cung chèn ép vào trực tràng gây táo bón.", "- Xoắn khối u dưới phúc mạc có cuống: đau dữ dội ở vùng hố chậu, kèm dấu hiệu kích thích phúc mạc(nôn, bí trung tiện). Toàn thân suy sụp, mạch nhanh, bụng chướng. Choáng có thể xảy ra do đau", "- Thoái hoá: một số trường hợp khối u to có thể có biến chứng thoái hoá hoại tử vô khuẩn hoặc thoái hoá kính.", "- Ung thư hoá: hiếm gặp"]}, {"heading": "6.2.2. U xơ tử cung và thai nghén", "paragraphs": [], "bullets": ["- Chậm có thai, hoặc vô sinh", "- Khi có thai: u xơ tử cung có thể gây sẩy thai tự nhiên, đẻ non", "- U xơ tử cung có thể gây rau tiền đạo, rau bám chặt.", "- Đẻ khó: tuỳ theo vị trí u xơ có thể gây ra ngôi thai bất thường, ngôi cúi không tốt hoặc trở thành khối u tiền đạo khi chuyển dạ", "- Khi chuyển dạ: thường gây chuyển dạ kéo dài, rối loạn cơn co. Thời kỳ sổ rau thường gây băng huyết, đờ tử cung.", "- Trong một số trường hợp vị trí của khối u có thể gây trở ngại cho đường rạch cơ tử cung khi mổ lấy thai. Ví dụ, thay vì phẫu thuật theo đường mổ ngang đoạn dưới có thể phải  rạch thân tử cung để lấy thai.", "- Thời kỳ hậu sản: u xơ có thể gây bế sản dịch, nhiễm khuẩn hậu sản, u xơ dưới thanh mạc có cuống có thể bị xoắn.", "- Biến chứng sau đẻ của u xơ", "+ Khối u bị kẹt ở cùng đồ Douglas gây chèn ép bàng quang, trực tràng", "+ Khối u dưới phúc mạc bị dính vào phúc mạc", "+ Biến chứng nhiễm khuẩn có thể xảy ra ở ngay khối u, niêm mạc tử cung và vòi tử cung. Bệnh nhân có những cơn đau bụng, sốt, bạch cầu tăng, toàn thân suy sụp."]}, {"heading": "7. ĐIỀU TRỊ", "paragraphs": ["Phương pháp điều trị phụ thuộc vào tuổi bệnh nhân, số lần có thai, tình trạng thai nghén, mong muốn có thai trong tương lai, vị trí và kích thước khối u."], "bullets": []}, {"heading": "7.1. Điều trị nội khoa", "paragraphs": ["Mục đích chủ yếu là hạn chế sự phát triển của khối u và các triệu chứng rong kinh, rong huyết."], "bullets": []}, {"heading": "7.1.1. Chỉ định", "paragraphs": [], "bullets": ["-Có một số u xơ nhỏ, không biến chứng chỉ cần theo dõi, không cần điều trị", "- U xơ nhỏ, không có biến chứng hoặc ở tuổi sắp mãn kinh hoặc chờ mổ vì một số bệnh lý nội khoa, nhưng phải ngừng điều trị trước phẫu thuật ít nhất 10 ngày."]}, {"heading": "7.1.2. Điều trị", "paragraphs": ["Có thể sử dụng một số thuốc như Medroxyprogesteron acetat, chất đồng vận GnRH, hoặc Danazol, Zoladex. Tác dụng của thuốc đạt được tối đa sau 3-6 tháng dùng thuốc khối u có thể giảm được 50% thể tích, sau đó thể tích khối u không giảm thêm. Nếu ngừng thuốc khối u sẽ dần dần tăng kích thước trở lại.", "Liều lượng:", "Medroxyprogesteron 10mg/ngày x 10 ngày, từ ngày 16-25 của vòng kinh.", "GnRH agonist"], "bullets": []}, {"heading": "7.2.1. Chỉ định", "paragraphs": [], "bullets": ["- U xơ có biến chứng: chảy máu, điều trị nội khoa thất bại, chèn ép, hoại tử, xoắn hay kết hợp với vô sinh", "- U xơ phối hợp tổn thương khác: sa sinh dục, u nang buồng trứng, nghịch sản cổ tử cung", "- U xơ tử cung to hay lớn dần lên (>8cm)", "- U xơ làm biến dạng buồng tử cung: u xơ dưới niêm mạc gây chảy máu và nhiễm khuẩn"]}, {"heading": "7.2.2. Điều trị bảo tồn", "paragraphs": [], "bullets": ["- Gây tắc mạch: người ta đã ứng dụng thành công phương pháp làm tắc mạch khối nhân xơ bằng một catheter đặt qua động mạch đùi, đưa lên động mạch tử cung và bơm chất gây tắc mạch như: hạt gelatin xốp(Gelfoam), hạt silicon, hạt polyvinyl alcohol  (PVA).", "- Bóc nhân xơ bảo tồn tử cung bằng mổ hở hoặc nội soi.", "- Cắt polyp buồng tử cung qua soi buồng hoặc mổ hở."]}, {"heading": "7.2.3. Điều trị triệt để", "paragraphs": ["Cắt tử cung hoàn toàn, có thể cắt hai hay một phần phụ tuỳ thuộc vào từng trường hợp cụ thể và tuổi người bệnh."], "bullets": []}, {"heading": "Câu hỏi:", "paragraphs": ["1: Phân loại theo giải phẫu của u xơ tử cung (có hình vẽ minh hoạ)?", "2: Trình bày các triệu chứng lâm sàng, cân lâm sàng để chẩn đoán xác định u xơ tử cung?", "3: Nêu tiến triển và biến chứng của u xơ tử cung? hướng xử trí ?"], "bullets": []}], "raw_text": "U XƠ TỬ CUNG\nThs. BSCK II. Hoàng Tiến Nam\nMục tiêu học tập\n1. Kể được các vị trí của u xơ tử cung.\n2. Mô tả được các triệu chứng lâm sàng và cận lâm sàng của u xơ tử cung.\n3. Kể được các ảnh hưởng của u xơ tử cung đối với thai nghén.\n4. Trình bày đượcthái độ và  các biện pháp xử trí u xơ tử cung.\n\n1. ĐẠI CƯƠNG\n- U xơ tử cung (UXTC) là khối u lành tính, có nguồn gốc từ tế bào cơ trơn tử cung, tỷ lệ 20-30% ở các phụ nữ trong độ tuổi sinh đẻ, kích thước thường dưới 15cm. U xơ tử cung thường ít có triệu chứng. Tuy nhiên khi khối u lớn thì có thể gây rong kinh, rong huyết, đau và vô sinh. Nguyên nhân chưa được biết rõ, nhưng giả thuyết về cường estrogen được nhiều tác giả ủng hộ.\n- Thường gặp ở phụ nữ từ ≥ 40 tuổi\n- U xơ tử cung không gặp trước tuổi dậy thì.\n\n2. GIẢI PHẪU BỆNH\n2.1. Đại thể\nU xơ tử cung là một khối u đặc, không có vỏ, có hình tròn hoặc bầu dục, mật độ chắc, mặt cắt màu trắng, giới hạn rõ với lớp cơ tử cung bao quanh có màu hồng. Khối u có cấu trúc là cơ trơn.\nSố lượng u có thể chỉ có một hoặc nhiều nhân, kích thước không đều.\n2.2. Vi thể\nCác sợi cơ trơn hợp thành bó, đan xen với nhau thành khối. Xen kẽ với sợi cơ trơn là tổ chức liên kết. Nhân tế bào có hình bầu dục, tròn, không có hình ảnh nhân chia. Khi mãn kinh khối u có thể nhỏ dần, sợi cơ giảm thay vào đó là các sợi collagen kèm canxi hoá. Ngoài ra niêm mạc tử cung dày lên kiểu quá sản.\n\nHình 1. Bệnh phẩm u xơ tử cung: hình ảnh đại thể (trái) và hình ảnh vi thể (phải)\n\n3. VỊ TRÍ CỦA U XƠ TỬ CUNG\nTheo vị trí giải phẫu và cấu trúc của cơ tử cung thì u xơ tử cung được phân chia thành các loại sau:\n3.1. Ở thân tử cung (90%)\n3.1. 1. U xơ dưới phúc mạc (10%)\nU ở dưới phúc mạc, có thể có cuống hoặc không có cuống. Triệu chứng lâm sàng nghèo nàn, u được phát hiện do biến chứng chèn ép các tạng xung quanh, làm thay đổi vị trí vòi tử cung, buồng trứng - loại này thường bị chẩn đoán nhầm với khối u buồng trứng.\n3.1. 2. U xơ trong lớp cơ tử cung (60-70%)\nLoại này hay gặp nhất phát triển từ phần giữa của lớp cơ tử cung, u có thể lấn vào buồng tử cung, làm biến dạng buồng tử cung. Có thể có nhiều khối u, kích thước lớn, hình tròn và đối xứng.\n3.1. 3. U xơ dưới niêm mạc (10-20%)\nLoại này thường chỉ có một khối u, hay phối hợp với các bất thường của niêm mạc tử cung, gây nhiều triệu chứng bất thường như ra huyết, kinh đau. U phát triển lấn vào buồng tử cung, niêm mạc tử cung bị hoại tử, chảy máu. Khi khối u có cuống, nó chui qua eo vào ống cổ tử cung hoặc nằm trong âm đạo, gọi là polyp buồng tử cung.\n3.2. Ở cổ tử cung (10%)\nLoại này thường phát triển về phía âm đạo.  Nếu u xơ cổ tử cung phát triển ở thành sau, sẽ lấn vào cùng đồ Douglas gây chèn ép trực tràng. Nếu u xơ ở thành trước, nó sẽ phát triển trong hố chậu có thể đè vào bàng quang hoặc niệu đạo. Khối u có thể có cuống, được bao phủ bởi niêm mạc ống cổ tử cung, lấn ra ngoài lỗ cổ tử cung, cổ tử cung như bị xoá gọi là polyp ống cổ tử cung.\n\nHình 2. Các vị trí của u xơ tử cung\n\n4. TRIỆU CHỨNG\nUXTC thường ít có triệu chứng và thường được phát hiện tình cờ. Các triệu chứng biểu hiện phụ thuộc vào vị trí và kích thước khối u.\n4.1. Triệu chứng toàn thân:\nCó thể gặp tình trạng thiếu máu, mức độ thiếu máu phụ thuộc vào tình trạng mất máu\n4.2. Triệu chứng cơ năng\n- Khí hư loãng như nước.\n- Rong kinh, cường kinh là triệu chứng chính, gặp trong 60% trường hợp. Máu kinh thường có máu cục lẫn máu loãng. Kinh kéo dài ngày 7 - 10 ngày hoặc dài  hơn.\n- Đau vùng hạ vị hoặc vùng hố chậu, đau có thể tăng lên trước hoặc trong khi có kinh. Đau hoặc tức bụng kéo dài có thể do khối u chèn ép vào tạng lân cận.\nChèn ép trực tràng gây táo bón.\nChèn ép bàng quang gầy đái buốt, đái rắt.\nChèn ép niệu quản gây ứ nước thận\nU xơ tử cung dính vào ruột, chèn ép gây tắc ruột.\n4.3. Triệu chứng thực thể\n- Nhìn: nếu khối u lớn có thể thấy khối u gồ lên ở vùng hạ vị\n- Sờ nắn bụng: khối u ở hạ vị có mật độ chắc, di động liên quan với tử cung.\n- Khám mỏ vịt: Nếu u xơ ở cổ tử cung có thể thấy polyp có cuống nằm ở lỗ ngoài cổ tử cung\n- Khám âm đạo phối hợp với nắn bụng: phát hiện toàn bộ tử cung to, chắc, nhẵn, đều (có khi gồ ghề) không đau. Nếu u xơ dưới thanh mạc có thể phát hiện cạnh tử cung một khối u tương tự như khối u phần phụ; Khi lay cổ tử cung, khối u di động theo.\n- Khám trực tràng: rất cần thiết để phân biệt u xơ tử cung phát triển về phía sau hay  khối u trực tràng.\n4.4. Cận lâm sàng\n- Siêu âm : kích thước tử cung tăng, đo được kích thước của u xơ tử cung và kích thước của nhân xơ tử cung. Siêu âm cản quang (bơm nước muối hoặc dịch cản quang vào buồng tử cung) có thể phát hiện polyp buồng tử cung. Chẩn đoán siêu âm có thể khó khăn trong trường hợp u nang buồng trứng dính với tử cung, hoặc tử cung bị dị dạng.\n- Soi buồng tử cung để chẩn đoán và điều trị các u xơ dưới niêm mạc.\n- Xét nghiệm tế bào âm đạo để phát hiện các tổn thương cổ tử cung kèm theo.\n- CT- scan được chỉ định trong trường hợp cần phân biệt với các ung thư ở tiểu khung.\n\nHình 3. Hình ảnh u xơ tử cung dưới niêm mạc qua soi buồng\n\n5. CHẨN ĐOÁN\n5.1. Chẩn đoán xác định\nDựa vào triệu chứng cơ năng, thực thể và cận lâm sàng. Chẩn đoán thường dễ khi khối u lớn và có nhiều nhân xơ.\n5.2. Chẩn đoán gián biệt\n- Có thai: phải dựa vào xét nghiệm β hCG và siêu âm để phân biệt với có thai bình thường, doạ sẩy thai, thai chết lưu.\n- Khối u buồng trứng: thường biệt lập với tử cung, di động khối u không làm di chuyển cổ tử cung. Chẩn đoán phân biệt giữa khối u buồng trứng với u xơ tử cung dưới phúc mạc đôi khi khó khăn.\n- Ung thư thân tử cung: Tất cả những trường hợp ra huyết bất thường ở thời kỳ tiền mãn kinh, mãn kinh cần được loại trừ ung thư thân tử cung. Các xét nghiệm bổ sung như: soi buồng tử cung và nạo sinh thiết giúp chẩn đoán xác định.\n\n6. TIẾN TRIỂN VÀ BIẾN CHỨNG\n6.1. Tiến triển\nU xơ tử cung thường tiến triển chậm, sau một thời gian khối u có thể tăng kích thước gây nên triệu chứng và biến chứng. Chỉ khoảng 0,05% trường hợp u xơ tử cung biến chứng thành sarcoma. Nếu khối u nhỏ không gây triệu chứng hoặc biến chứng gì đáng kể. Thời kỳ mãn kinh, u xơ tử cung có thể ngừng phát triển.\n6.2. Biến chứng\n6.2.1. U xơ tử cung ở người không có thai\n- Chảy máu:  rong kinh, rong huyết thường là biểu hiện chính, hay gặp trong u dưới niêm mạc. Ra huyết kéo dài dẫn đến thiếu máu.\n- Chèn ép:\n+ U xơ trong dây chằng rộng chèn ép vào niệu quản đưa đến ứ đọng đài bể thận. Biến cố nhẹ ở đường tiết niệu là đái rắt, đái khó...\n+ U xơ ở mặt sau tử cung chèn ép vào trực tràng gây táo bón.\n- Xoắn khối u dưới phúc mạc có cuống: đau dữ dội ở vùng hố chậu, kèm dấu hiệu kích thích phúc mạc(nôn, bí trung tiện). Toàn thân suy sụp, mạch nhanh, bụng chướng. Choáng có thể xảy ra do đau\n- Thoái hoá: một số trường hợp khối u to có thể có biến chứng thoái hoá hoại tử vô khuẩn hoặc thoái hoá kính.\n- Ung thư hoá: hiếm gặp\n6.2.2. U xơ tử cung và thai nghén\n- Chậm có thai, hoặc vô sinh\n- Khi có thai: u xơ tử cung có thể gây sẩy thai tự nhiên, đẻ non\n- U xơ tử cung có thể gây rau tiền đạo, rau bám chặt.\n- Đẻ khó: tuỳ theo vị trí u xơ có thể gây ra ngôi thai bất thường, ngôi cúi không tốt hoặc trở thành khối u tiền đạo khi chuyển dạ\n- Khi chuyển dạ: thường gây chuyển dạ kéo dài, rối loạn cơn co. Thời kỳ sổ rau thường gây băng huyết, đờ tử cung.\n- Trong một số trường hợp vị trí của khối u có thể gây trở ngại cho đường rạch cơ tử cung khi mổ lấy thai. Ví dụ, thay vì phẫu thuật theo đường mổ ngang đoạn dưới có thể phải  rạch thân tử cung để lấy thai.\n- Thời kỳ hậu sản: u xơ có thể gây bế sản dịch, nhiễm khuẩn hậu sản, u xơ dưới thanh mạc có cuống có thể bị xoắn.\n- Biến chứng sau đẻ của u xơ\n+ Khối u bị kẹt ở cùng đồ Douglas gây chèn ép bàng quang, trực tràng\n+ Khối u dưới phúc mạc bị dính vào phúc mạc\n+ Biến chứng nhiễm khuẩn có thể xảy ra ở ngay khối u, niêm mạc tử cung và vòi tử cung. Bệnh nhân có những cơn đau bụng, sốt, bạch cầu tăng, toàn thân suy sụp.\n\n7. ĐIỀU TRỊ\nPhương pháp điều trị phụ thuộc vào tuổi bệnh nhân, số lần có thai, tình trạng thai nghén, mong muốn có thai trong tương lai, vị trí và kích thước khối u.\n7.1. Điều trị nội khoa\nMục đích chủ yếu là hạn chế sự phát triển của khối u và các triệu chứng rong kinh, rong huyết.\n7.1.1. Chỉ định\n-Có một số u xơ nhỏ, không biến chứng chỉ cần theo dõi, không cần điều trị\n- U xơ nhỏ, không có biến chứng hoặc ở tuổi sắp mãn kinh hoặc chờ mổ vì một số bệnh lý nội khoa, nhưng phải ngừng điều trị trước phẫu thuật ít nhất 10 ngày.\n\n\n7.1.2. Điều trị\nCó thể sử dụng một số thuốc như Medroxyprogesteron acetat, chất đồng vận GnRH, hoặc Danazol, Zoladex. Tác dụng của thuốc đạt được tối đa sau 3-6 tháng dùng thuốc khối u có thể giảm được 50% thể tích, sau đó thể tích khối u không giảm thêm. Nếu ngừng thuốc khối u sẽ dần dần tăng kích thước trở lại.\nLiều lượng:\nMedroxyprogesteron 10mg/ngày x 10 ngày, từ ngày 16-25 của vòng kinh.\nGnRH agonist\n7.2. Điều trị ngoại khoa\n7.2.1. Chỉ định\n- U xơ có biến chứng: chảy máu, điều trị nội khoa thất bại, chèn ép, hoại tử, xoắn hay kết hợp với vô sinh\n- U xơ phối hợp tổn thương khác: sa sinh dục, u nang buồng trứng, nghịch sản cổ tử cung\n- U xơ tử cung to hay lớn dần lên (>8cm)\n- U xơ làm biến dạng buồng tử cung: u xơ dưới niêm mạc gây chảy máu và nhiễm khuẩn\n7.2.2. Điều trị bảo tồn\n- Gây tắc mạch: người ta đã ứng dụng thành công phương pháp làm tắc mạch khối nhân xơ bằng một catheter đặt qua động mạch đùi, đưa lên động mạch tử cung và bơm chất gây tắc mạch như: hạt gelatin xốp(Gelfoam), hạt silicon, hạt polyvinyl alcohol  (PVA).\n- Bóc nhân xơ bảo tồn tử cung bằng mổ hở hoặc nội soi.\n- Cắt polyp buồng tử cung qua soi buồng hoặc mổ hở.\n7.2.3. Điều trị triệt để\nCắt tử cung hoàn toàn, có thể cắt hai hay một phần phụ tuỳ thuộc vào từng trường hợp cụ thể và tuổi người bệnh.\nCâu hỏi:\n1: Phân loại theo giải phẫu của u xơ tử cung (có hình vẽ minh hoạ)?\n2: Trình bày các triệu chứng lâm sàng, cân lâm sàng để chẩn đoán xác định u xơ tử cung?\n3: Nêu tiến triển và biến chứng của u xơ tử cung? hướng xử trí ?\n4. Trỡnh bày hướng xử trớ và điều trị  u xơ tử cung?", "priority": "Cao (Trọng tâm BSNT)"}, {"id": "SK-47", "chapter": "Chương 3. Phụ khoa", "folder": "03_Phu_khoa", "title": "Khối u buồng trứng", "author": "TS. BS. Bùi Minh Tiến, TS. BS. Phan Văn Cương", "word_count": 2952, "line_count": 171, "key_numbers": ["15cm", "2 cm", "3 tháng", "30 ngày", "5 cm", "50 kg", "6cm"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["KHỐI U BUỒNG TRỨNG", "Ths. BSCK II. Hoàng Tiến Nam"], "bullets": []}, {"heading": "5. Xác định được hướng xử trí của u nang buồng trứng thực thể và ung thư buồng trứng.", "paragraphs": ["Phần I: U NANG BUỒNG TRỨNG"], "bullets": []}, {"heading": "1. ĐỊNH NGHĨA", "paragraphs": ["U nang buồng trứng là những khối u buồng trứng có vỏ mỏng, bên trong có chứa dịch đơn thuần hay phối hợp với các thành phần khác. Bệnh thường gặp ở mọi lứa tuổi, nhiều nhất từ 30- 45 tuổi. Chẩn đoán tương đối dễ nhưng triệu chứng và tiến triển phức tạp nên việc điều trị và tiên lượng còn gặp nhiều khó khăn."], "bullets": []}, {"heading": "2.1. U nang cơ năng", "paragraphs": ["Là loại u nang không có tổn thương giải phẫu, chỉ tổn thương về chức năng buồng trứng. Đường kính thường nhỏ hơn 6cm, có loại lớn nhanh nhưng mất sớm, chỉ tồn tại sau vài  chu kỳ kinh nguyệt.", "Có ba loại u nang cơ năng:"], "bullets": []}, {"heading": "2.1.1. Nang bọc noãn:", "paragraphs": ["Được sinh ra từ bọc De Graaf không vỡ vào ngày quy định, tiếp tục tiết estrogen, u thường nhỏ, kích thước thay đổi. Dịch trong nang có màu vàng, chứa nhiều estrogen."], "bullets": []}, {"heading": "2.1.2. U nang hoàng tuyến:", "paragraphs": ["Thường gặp ở người chửa trứng, chorio, do tăng hCG. Có khi gặp ở người đang điều trị vô sinh bằng hormon sinh dục của tuyến yên với liều cao. Khi khỏi bệnh nang hoàng tuyến sẽ biến mất."], "bullets": []}, {"heading": "2.1.3. Nang hoàng thể:", "paragraphs": ["Được sinh ra từ hoàng thể. Chỉ gặp trong thời kỳ thai nghén do chửa nhiều thai, u nang chế tiết nhiều estrogen, progesteron."], "bullets": []}, {"heading": "2.2. U nang thực thể", "paragraphs": ["Do tổn thương thực thể giải phẫu buồng trứng. U thường  phát triển chậm nhưng không bao giờ mất. Kích thước u nang  thường lớn, có vỏ dày đa số lành tính.", "Có 3 loại u nang thực thể"], "bullets": []}, {"heading": "2.2.3. U nang nhầy: Là loại u to nhất có khi nặng 40-50 kg. Hay dính các tạng xung quanh, u nang có nhiều túi. Dịch trong nang đặc hay dịch nhầy, màu vàng nhạt hay nâu.", "paragraphs": ["Hình 1. Bệnh phẩm đại thể u nang nước (trái) và u nang nhầy (phải)", "của buồng trứng."], "bullets": []}, {"heading": "3.1. Triệu chứng cơ năng", "paragraphs": [], "bullets": ["- U nang nhỏ: Triệu chứng nghèo nàn, khối u tiến triển nhiều năm bệnh nhân vẫn hoạt động bình thường, được phát hiện khi khám sức khoẻ, khám phụ khoa hay siêu âm.", "- Trường hợp u lớn: bệnh nhân cảm giác nặng bụng dưới, có dấu hiệu chèn ép các tạng xung quanh gây tiểu rắt, bí tiểu, bí đại tiện."]}, {"heading": "3.2. Triệu chứng thực thể", "paragraphs": [], "bullets": ["- U nang to, thấy bụng dưới to lên như mang thai, sờ thấy khối u di động, có khi đau. Khám âm đạo: Tử cung nhỏ, cạnh tử cung có khối tròn đều di động dễ dàng, ranh giới biệt lập với tử cung.", "- Trường hợp u nang dính hay u nang trong dây chằng rộng thì di động hạn chế có khi mắc kẹt trong tiểu khung. Chú ý khi khám không nên đè mạnh hay đẩy lên có thể gây vỡ nang."]}, {"heading": "3.3. Cận lâm sàng", "paragraphs": ["Làm CA 125: đánh giá mức độ ác tính của khối u nang.", "Làm αFetoprotein: giúp phân biệt bản chất khối u."], "bullets": ["- Phản ứng tìm hCG âm tính", "- Siêu âm thấy ranh giới khối u rõ", "- Soi ổ bụng chỉ làm khi khối u nhỏ, nghi ngờ với chửa ngoài tử cung", "- Chụp bụng không chuẩn bị nếu là u nang bì sẽ thấy cản quang.", "- Chụp tử cung - vòi tử cung với thuốc cản quang thấy tử cung lệnh một bên, vòi tử cung bên khối u kéo dài ôm lấy khối u."]}, {"heading": "4.1. Chẩn đoán xác định", "paragraphs": ["Dựa vào dấu hiệu thực thể và một số xét nghiệm cận lâm sàng"], "bullets": []}, {"heading": "4.2. Chẩn đoán phân biệt", "paragraphs": ["Nói chung các trường hợp khó, cần khám kỹ, kết hợp lâm sàng, siêu âm, hội chẩn với ngoại khoa để xác định thêm."], "bullets": ["- Có thai:Tiền sử tắt kinh, tử cung to, mềm, hCG (+)", "- Ứ dịch vòi tử cung: có tiền sử viêm nhiễm, thường viêm 2 bên", "- Chửa ngoài tử cung thể huyết tụ thành nang: Chậm kinh, rong huyết, có khối  cạnh tử cung đau", "- U xơ tử cung có cuống: Chụp tử cung cản quang thấy hai vòi tử cung bình thường", "- Cổ chướng: Gõ đục toàn bụng, khám khối u không rõ", "- Lách to: có tiền sử sốt rét hay các bệnh về máu, khối u ở cao.", "- Thận đa nang, u mạc treo: Khối u cao, chạm cực dưới khó khăn", "- Bàng quang đầy nước tiểu: Cần thông  tiểu trước khi khám."]}, {"heading": "5.1. Xoắn u nang", "paragraphs": ["Là biến chứng hay gặp nhất. Các khối u có đường kính trung bình (từ 8-15cm), cuống dài hay bị xoắn. Có 2 hình thức xoắn:"], "bullets": []}, {"heading": "5.1.1. Xoắn cấp tính:", "paragraphs": ["Bệnh cảnh xẩy ra đột ngột, đau bụng dữ dội, có thể ngất xỉu, mạch, huyết áp ổn định có thể nôn. buồn nôn, ấn. khôí u đau.", "Khi khám ấn vào khối u rất đau, di động hạn chế."], "bullets": []}, {"heading": "5.1.2. Xoắn bán cấp:", "paragraphs": ["Đau từ từ âm ỉ, khi thay đổi tư thế thì giảm hoặc hết đau, do tự tháo xoắn, nhưng thỉnh thoảng lại tái phát."], "bullets": []}, {"heading": "5.2. Chảy máu trong nang", "paragraphs": ["Là hậu quả của xoắn. Cơ chế như buộc ga-rô lỏng, máu ứ không trở về được gây vỡ mạch, nang to dần lên."], "bullets": []}, {"heading": "5.3. Vỡ u nang", "paragraphs": ["Do xoắn nang không được điều trị kịp thời, do sang chấn, thăm khám không nhẹ nhàng hay do tai nạn. Hậu quả là chảy máu ổ bụng cấp tính"], "bullets": []}, {"heading": "5.4. Viêm nhiễm", "paragraphs": ["U nang dính với các tạng xung quanh gây ra viêm phúc mạc khu trú"], "bullets": []}, {"heading": "5.5. Chèn ép", "paragraphs": ["U nang có thể chèn ép các tạng lân cận gây bán tắc ruột, đại, tiểu tiện khó."], "bullets": []}, {"heading": "5.6. Ung thư hoá", "paragraphs": ["Ung thư có thể xẩy ra ở cả 3 loại u nang thực thể, nhưng u nang nước thường gặp nhất: Bệnh nhân gầy, u to nhanh, nhiều thuỳ xâm lấn các tạng xung quanh."], "bullets": []}, {"heading": "5.7. U nang và thai nghén", "paragraphs": ["U nang có thể gây sẩy thai, đẻ non, u tiền đạo, ngôi bất thường, xoắn u nang sau đẻ."], "bullets": []}, {"heading": "6.1. U nang cơ năng", "paragraphs": ["Cần theo dõi định kỳ, chỉ  phẫu thuật khi biến chứng"], "bullets": []}, {"heading": "6.2. U nang thực thể", "paragraphs": ["Phẫu thuật là chủ yếu, tốt nhất nên mổ chương trình Trong trường hợp u lành tính, u ở 2 buồng trứng, bệnh nhân trẻ nên bóc u nang để lại phần lành. Khi mổ tốt nhất nên lấy cả khối, nếu u mắc kẹt hay quá to thì hút bớt dịch nên chèn gạc tốt để hạn chế dịch chảy vào ổ bụng.", "Khối u dính nên cẩn thận vì có thể gây tổn thương các tạng xung quanh", "Khi phẫu thuật  u nang buồng trứng xoắn phải tháo xoắn nếu thấy khối u hồng trở lại thì bóc u, còn nếu màu sắc vẫn tím đen thì cắt buồng trứng.", "Đối với u nang nhày: phải cắt buồng trứng bên khối u.", "Các khối u đều phải gửi làm giải phẫu bệnh để xác định lành hay ác tính.", "Trường hợp u ác tính phải cắt tử cung hoàn toàn, cắt bỏ phần phụ bên kia, cắt một phần mạc nối lớn và tiếp tục điều trị hoá chất.", "Phần II: UNG THƯ BUỒNG TRỨNG"], "bullets": []}, {"heading": "1. ĐẠI CƯƠNG", "paragraphs": ["Ung thư buồng trứng là loại ung thư thường gặp trong các bệnh ung thư phụ khoa, tỷ lệ tử vong cao. Ung thư buồng trứng xếp hàng thứ 3 sau ung thư vú và ung thư cổ tử cung, là loại ung thư ngày càng tăng, chẩn đoán sớm hơn nhưng điều trị khó khăn, tiên lượng xấu."], "bullets": []}, {"heading": "1.1. Yếu tố thuận lợi", "paragraphs": ["Ung thư buồng trứng thường gặp ở những phụ nữ có mức sinh hoạt cao và ở những nước công nghiệp. Phụ nữ da trắng có tỷ lệ mắc bệnh cao hơn. Nguy cơ tăng ở lứa tuổi sau 40, trung bình là 50 - 59 tuổi."], "bullets": []}, {"heading": "1.2. Nguyên nhân", "paragraphs": ["Cho đến nay, người ta chưa biết rõ nguyên nhân, tuy vậy những yếu tố như ô nhiễm môi trường đặc biệt là chất amian và bột talc (Hydrous magnesium silicate) là hai hóa chất hay gây ung thư buồng trứng.", "Hình 2. Ung thư biểu mô buồng trứng"], "bullets": []}, {"heading": "2.1. Triệu chứng", "paragraphs": ["Triệu chứng hay gặp là đau bụng, bụng lớn, cảm giác khó chịu, có thể ra máu ở tử cung. Ung thư buồng trứng thường thầm lặng, không có triệu chứng báo trước nên 70 % bệnh nhân đến khám vì tự sờ thấy khối u ở bụng hay do đi khám phụ khoa mà phát hiện ra.", "Một khối u có khuynh hướng ác tính khi khám thấy kích thước khối u phát triển nhanh, mật độ khối u chắc, di động hạn chế và  phát triển cả hai bên buồng trứng."], "bullets": ["- Những triệu chứng chèn ép liên quan với giai đoạn phát triển ban đầu.", "- Triệu chứng lan rộng vào ổ bụng  biểu hiện bằng hiện tượng cổ trướng", "- Những triệu chứng về nội tiết như mất kinh hoặc tăng tiết estrogen.", "- Thăm âm đạo: Nếu u nhỏ không có gì đặc biệt. Khi khối u to mà đường kính từ 5 cm ở những phụ nữ 40-60 tuổi. Khám thấy lổn nhổn, nhiều thùy, nhiều nhú, có thể có dịch ổ bụng, di động hạn chế, có thể phát triển cả hai buồng trứng."]}, {"heading": "2.2. Các giai đoạn của ung thư buồng trứng:", "paragraphs": ["Ia: U một bên, vỏ nguyên vẹn, u không lan ra mặt ngoài, không có cổ trướng", "Ib: U hai bên, vỏ nguyên vẹn, u không lan ra mặt ngoài, không có cổ trướng", "Ic: U ở giai đoạn Ia hay Ib, lan ra mặt ngoài ở một hay 2 buồng trứng (Vỏ bị vỡ, có cổ trướng, tế bào phúc mạc loại IV)", "IIa:\tU xâm lấn và/hoặc di căn tới tử cung và/hoặc vòi trứng nhưng tế bào dịch cổ chướng, dịch rửa ổ bụng âm tính.", "IIb:\tU xâm lấn tới tổ chức khác trong khung chậu nhưng tế bào dịch cổ chướng, dịch rửa ổ bụng âm tính.", "IIc:\tNhư giai đoạn IIA hoặc IIB nhưng tế bào dịch cổ chướng hoặc dịch rửa ổ bụng dương tính.", "IIIa:\tDi căn màng bụng ngoài chậu hông.", "IIIb:\tDi căn màng bụng ngoài chậu hông có kích thước < 2 cm.", "IIIc:\tDi căn màng bụng ngoài chậu hông có kích thước > 2 cm.", "Hình 3. Các giai đoạn của ung thư buồng trứng"], "bullets": ["- Giai đoạn I: U khu trú ở buồng trứng", "- Giai đoạn II: U xâm lấn một hay hai bên buồng trứng và xâm lấn đến chậu hông.", "- Giai đoạn III: U xâm lấn 1 hay 2 buồng trứng, có di căn ngoài tiểu khung: di căn màng bụng, di căn hạch. Di căn tới bề mặt gan vẫn được tính ở giai đoạn III.", "- Giai đoạn IV: Khối u ở 1 hay 2 buồng trứng và có di căn xa (không kể phúc mạc), bao gồm cả nhu mô gan, tràn dịch màng phổi ác tính."]}, {"heading": "2.3. Cận lâm sàng", "paragraphs": ["Nếu khối u buồng trứng có kèm theo cổ trướng thì cổ trướng có giá trị trong tiến triển và tiên lượng bệnh. Cổ trướng là nước vàng chanh có tiên lượng xấu, nếu nước cổ trướng lẫn máu thì tiên lượng rất xấu, 70 % bệnh nhân chết trong năm đầu."], "bullets": ["- Tế bào học âm đạo cổ tử cung: ít có giá trị trong chẩn đoán ung thư buồng trứng.", "- Tế bào nước cổ trướng: 96 % ung thư giai đoạn muộn có tế bào ung thư rụng, phiến đồ dương tính. Theo Graham có những trường hợp ung thư ở giai đoạn sớm, tế bào không rụng trong tiểu khung do đó có khoảng 34 % âm tính giả. Đây là phương pháp tốt để chẩn đoán và theo dõi sự tiến triển của bệnh.", "- Siêu âm: Khối u ở 1 hay 2 buồng trứng, có nhiều chồi, nhú, có nhiều hốc, u hỗn hợp, có thể kèm theo dịch ổ bụng sẽ gợi ý một u ác tính.", "- CA 125: Là chất chỉ điểm trong ung thư, đặc biệt khi  nồng độ CA 125 trong ung thư buồng trứng tăng là bệnh tiến triển và khi nồng độ CA 125 giảm là bệnh thoái triển, thông thường sau phẫu thuật nồng độ CA 125 trở lại bình thường sau 3 tháng. \t.", "- Alpha -fetoprotein huyết thanh và beta hCG giúp phân biệt bản chất của khối u."]}, {"heading": "3. ĐIỀU TRỊ", "paragraphs": ["Điều trị khối u ác tính buồng trứng vẫn còn được tranh cãi nhiều vì việc phát hiện bệnh sớm gặp khó khăn, do tính chất giải phẫu bệnh phức tạp, do tiến triển và tiên lượng khó lường trước."], "bullets": []}, {"heading": "3.1. Phẫu thuật", "paragraphs": ["Là biện pháp đầu tiên và quan trọng nhằm mục đích: đánh giá toàn bộ khối u, lấy tổ chức gửi giải phẫu bệnh hoặc giúp điều trị hóa liệu pháp bổ sung. Nếu trường hợp không cắt được toàn bộ khối u thì lấy mẫu sinh thiết,sau đó điều trị hóa chất cho khối u nhỏ đi để có thể mổ lại lần hai, lần 3. Nếu là ung thư thì cắt khối u, cắt buồng trứng bên kia, cắt mạc nối lớn, cắt tử cung hoàn toàn."], "bullets": []}, {"heading": "3.2. Hóa liệu pháp", "paragraphs": ["Là phương pháp điều trị bổ sung quan trọng, có tác dụng đặc biệt đối với các trường hợp có thương tổn ở nhiều nơi, hoặc ở sâu phẫu thuật khó khăn hay quang tuyến không tới được.", "Hóa liệu pháp có những ưu điểm sau:", "Nhưng hóa liệu pháp có những nhược điểm sau:"], "bullets": ["- Đa số bệnh nhân chịu được", "- Có thể điều trị kéo dài", "- Có thể điều trị trong nhiều tình huống khác nhau như tấn công, duy trì.", "- Tác dụng thay đổi trên từng bệnh nhân và từng loại ung thư.", "- Sau một thời gian có hiện tượng quen thuốc.", "- Độc cho hệ tạo huyết, gây giảm miễn dịch, do đó trước khi dùng phải kiểm tra chức năng gan, thận và công thức máu.", "- Phải điều trị kéo dài, nếu ngừng thuốc đột ngột thường nguy hiểm cho bệnh nhân. Có nhiều loại hóa chất điều trị ung thư buồng trứng, có thể xếp thành các nhóm chính.", "+ Nhóm các chất làm hủy hoại ADN có tác dụng trong toàn bộ chu kỳ sinh sản của tế bào. Ví dụ, Thiotepa, Alkeran, Cyclophopshamid, Chlorambuclil.", "+ Các chất chống chuyển hóa, chống lại sinh sản ADN bằng cách thay thế một chất khác vào chuỗi tổng hợp. Ví dụ: Fluouracil, Methotrexate.", "+ Các chất chống phân bào, tác dụng chủ yếu trong giai đoạn phân bào như: Cisplastin, Carboplatin, Đecarbasin.", "+ Kháng sinh chống ung thư Actinomyxin D, Adriamycin, Bleomycin, Platium"]}, {"heading": "3.3. Quang tuyến liệu pháp", "paragraphs": ["Là phương pháp điều trị đã có  từ lâu. Cơ sở của phương pháp này dùng tia xạ để  hủy diệt các tế bào đang phân chia (nhanh hơn 50 lần so với các tổ chức bình thường)", "Liều dùng 6000 Rad, thời gian 24 - 30 ngày.", "4.TIÊN LƯỢNG VÀ TƯ VẤN", "Vì khối u buồng trứng có nguy cơ ngày càng gia  tăng, triệu chứng cơ năng lại rất nghèo nàn, diễn biến lại  phức tạp. Chẩn đoán thường muộn, nên việc điều trị găp nhiều khó khăn. Vì vậy,việc tư vấn cho bệnh nhân có tính chất đặc biệt quan trọng. Công tác chăm sóc sức khoẻ phải làm tốt ở tuyến cơ sở. Tổ chức khám phụ khoa định kỳ để phát hiện sớm các khối u buồng trứng ở mọi lứa tuổi. Những khối u buồng trướng dù nhỏ  cũng cần được quản lý, theo dõi chặt chẽ. Nên gửi lên tuyến có đủ điều kiện để xác định chẩn đoán và xử lý kịp thời các trường hợp nghi ngờ ác tính để tránh các hậu quả không tốt  xẩy ra cho người bệnh."], "bullets": []}, {"heading": "3. Trình bày sự tiến triển và biến chứng của u nang buồng trứng?", "paragraphs": ["CHƯƠNG 4.  SƠ SINH"], "bullets": []}], "raw_text": "KHỐI U BUỒNG TRỨNG\nThs. BSCK II. Hoàng Tiến Nam\nMục tiêu học tập\n1. Phân biệt  u nang buồng trứng cơ năng và thực thể\n2. Mô tả được đặc điểm lâm sàng cận lâm sàng của u nang thực thể\n3. Liệt kê các biến chứng của u nang buồng trứng\n4. Kể được các dấu hiệu lâm sàng, cận lâm sàng của ung thư buồng trứng\n5. Xác định được hướng xử trí của u nang buồng trứng thực thể và ung thư buồng trứng.\n\nPhần I: U NANG BUỒNG TRỨNG\n\n1. ĐỊNH NGHĨA\nU nang buồng trứng là những khối u buồng trứng có vỏ mỏng, bên trong có chứa dịch đơn thuần hay phối hợp với các thành phần khác. Bệnh thường gặp ở mọi lứa tuổi, nhiều nhất từ 30- 45 tuổi. Chẩn đoán tương đối dễ nhưng triệu chứng và tiến triển phức tạp nên việc điều trị và tiên lượng còn gặp nhiều khó khăn.\n\n2. PHÂN LOẠI\n2.1. U nang cơ năng\nLà loại u nang không có tổn thương giải phẫu, chỉ tổn thương về chức năng buồng trứng. Đường kính thường nhỏ hơn 6cm, có loại lớn nhanh nhưng mất sớm, chỉ tồn tại sau vài  chu kỳ kinh nguyệt.\nCó ba loại u nang cơ năng:\n2.1.1. Nang bọc noãn:\nĐược sinh ra từ bọc De Graaf không vỡ vào ngày quy định, tiếp tục tiết estrogen, u thường nhỏ, kích thước thay đổi. Dịch trong nang có màu vàng, chứa nhiều estrogen.\n2.1.2. U nang hoàng tuyến:\nThường gặp ở người chửa trứng, chorio, do tăng hCG. Có khi gặp ở người đang điều trị vô sinh bằng hormon sinh dục của tuyến yên với liều cao. Khi khỏi bệnh nang hoàng tuyến sẽ biến mất.\n2.1.3. Nang hoàng thể:\nĐược sinh ra từ hoàng thể. Chỉ gặp trong thời kỳ thai nghén do chửa nhiều thai, u nang chế tiết nhiều estrogen, progesteron.\n2.2. U nang thực thể\nDo tổn thương thực thể giải phẫu buồng trứng. U thường  phát triển chậm nhưng không bao giờ mất. Kích thước u nang  thường lớn, có vỏ dày đa số lành tính.\nCó 3 loại u nang thực thể\n2.2.1. U nang bì: Thường gặp ở người trẻ, kích thước nhỏ, cuống dài, trong chứa tuyến bã, răng, tóc, dịch bã đậu là các tổ chức có nguồn gốc bào thai.\n2.2.2. U nang nước: Thường gặp ở người trẻ, u có cuống dài, vỏ mỏng, thường chỉ 1 túi, trơn, ít dính, có dịch trong hoặc vàng chanh.\n2.2.3. U nang nhầy: Là loại u to nhất có khi nặng 40-50 kg. Hay dính các tạng xung quanh, u nang có nhiều túi. Dịch trong nang đặc hay dịch nhầy, màu vàng nhạt hay nâu.\n\nHình 1. Bệnh phẩm đại thể u nang nước (trái) và u nang nhầy (phải)\ncủa buồng trứng.\n\n3. TRIỆU CHỨNG\n3.1. Triệu chứng cơ năng\n- U nang nhỏ: Triệu chứng nghèo nàn, khối u tiến triển nhiều năm bệnh nhân vẫn hoạt động bình thường, được phát hiện khi khám sức khoẻ, khám phụ khoa hay siêu âm.\n- Trường hợp u lớn: bệnh nhân cảm giác nặng bụng dưới, có dấu hiệu chèn ép các tạng xung quanh gây tiểu rắt, bí tiểu, bí đại tiện.\n3.2. Triệu chứng thực thể\n- U nang to, thấy bụng dưới to lên như mang thai, sờ thấy khối u di động, có khi đau. Khám âm đạo: Tử cung nhỏ, cạnh tử cung có khối tròn đều di động dễ dàng, ranh giới biệt lập với tử cung.\n- Trường hợp u nang dính hay u nang trong dây chằng rộng thì di động hạn chế có khi mắc kẹt trong tiểu khung. Chú ý khi khám không nên đè mạnh hay đẩy lên có thể gây vỡ nang.\n3.3. Cận lâm sàng\n- Phản ứng tìm hCG âm tính\n- Siêu âm thấy ranh giới khối u rõ\n- Soi ổ bụng chỉ làm khi khối u nhỏ, nghi ngờ với chửa ngoài tử cung\nLàm CA 125: đánh giá mức độ ác tính của khối u nang.\nLàm αFetoprotein: giúp phân biệt bản chất khối u.\n- Chụp bụng không chuẩn bị nếu là u nang bì sẽ thấy cản quang.\n- Chụp tử cung - vòi tử cung với thuốc cản quang thấy tử cung lệnh một bên, vòi tử cung bên khối u kéo dài ôm lấy khối u.\n\n4. CHẨN ĐOÁN\n4.1. Chẩn đoán xác định\nDựa vào dấu hiệu thực thể và một số xét nghiệm cận lâm sàng\n4.2. Chẩn đoán phân biệt\n- Có thai:Tiền sử tắt kinh, tử cung to, mềm, hCG (+)\n- Ứ dịch vòi tử cung: có tiền sử viêm nhiễm, thường viêm 2 bên\n- Chửa ngoài tử cung thể huyết tụ thành nang: Chậm kinh, rong huyết, có khối  cạnh tử cung đau\n- U xơ tử cung có cuống: Chụp tử cung cản quang thấy hai vòi tử cung bình thường\n- Cổ chướng: Gõ đục toàn bụng, khám khối u không rõ\n- Lách to: có tiền sử sốt rét hay các bệnh về máu, khối u ở cao.\n- Thận đa nang, u mạc treo: Khối u cao, chạm cực dưới khó khăn\n- Bàng quang đầy nước tiểu: Cần thông  tiểu trước khi khám.\nNói chung các trường hợp khó, cần khám kỹ, kết hợp lâm sàng, siêu âm, hội chẩn với ngoại khoa để xác định thêm.\n5. BIẾN CHỨNG\n5.1. Xoắn u nang\nLà biến chứng hay gặp nhất. Các khối u có đường kính trung bình (từ 8-15cm), cuống dài hay bị xoắn. Có 2 hình thức xoắn:\n5.1.1. Xoắn cấp tính:\nBệnh cảnh xẩy ra đột ngột, đau bụng dữ dội, có thể ngất xỉu, mạch, huyết áp ổn định có thể nôn. buồn nôn, ấn. khôí u đau.\nKhi khám ấn vào khối u rất đau, di động hạn chế.\n5.1.2. Xoắn bán cấp:\nĐau từ từ âm ỉ, khi thay đổi tư thế thì giảm hoặc hết đau, do tự tháo xoắn, nhưng thỉnh thoảng lại tái phát.\n5.2. Chảy máu trong nang\nLà hậu quả của xoắn. Cơ chế như buộc ga-rô lỏng, máu ứ không trở về được gây vỡ mạch, nang to dần lên.\n5.3. Vỡ u nang\nDo xoắn nang không được điều trị kịp thời, do sang chấn, thăm khám không nhẹ nhàng hay do tai nạn. Hậu quả là chảy máu ổ bụng cấp tính\n5.4. Viêm nhiễm\nU nang dính với các tạng xung quanh gây ra viêm phúc mạc khu trú\n5.5. Chèn ép\nU nang có thể chèn ép các tạng lân cận gây bán tắc ruột, đại, tiểu tiện khó.\n5.6. Ung thư hoá\nUng thư có thể xẩy ra ở cả 3 loại u nang thực thể, nhưng u nang nước thường gặp nhất: Bệnh nhân gầy, u to nhanh, nhiều thuỳ xâm lấn các tạng xung quanh.\n5.7. U nang và thai nghén\nU nang có thể gây sẩy thai, đẻ non, u tiền đạo, ngôi bất thường, xoắn u nang sau đẻ.\n6. ĐIỀU TRỊ\n6.1. U nang cơ năng\nCần theo dõi định kỳ, chỉ  phẫu thuật khi biến chứng\n6.2. U nang thực thể\nPhẫu thuật là chủ yếu, tốt nhất nên mổ chương trình Trong trường hợp u lành tính, u ở 2 buồng trứng, bệnh nhân trẻ nên bóc u nang để lại phần lành. Khi mổ tốt nhất nên lấy cả khối, nếu u mắc kẹt hay quá to thì hút bớt dịch nên chèn gạc tốt để hạn chế dịch chảy vào ổ bụng.\nKhối u dính nên cẩn thận vì có thể gây tổn thương các tạng xung quanh\nKhi phẫu thuật  u nang buồng trứng xoắn phải tháo xoắn nếu thấy khối u hồng trở lại thì bóc u, còn nếu màu sắc vẫn tím đen thì cắt buồng trứng.\nĐối với u nang nhày: phải cắt buồng trứng bên khối u.\nCác khối u đều phải gửi làm giải phẫu bệnh để xác định lành hay ác tính.\nTrường hợp u ác tính phải cắt tử cung hoàn toàn, cắt bỏ phần phụ bên kia, cắt một phần mạc nối lớn và tiếp tục điều trị hoá chất.\n\nPhần II: UNG THƯ BUỒNG TRỨNG\n\n1. ĐẠI CƯƠNG\nUng thư buồng trứng là loại ung thư thường gặp trong các bệnh ung thư phụ khoa, tỷ lệ tử vong cao. Ung thư buồng trứng xếp hàng thứ 3 sau ung thư vú và ung thư cổ tử cung, là loại ung thư ngày càng tăng, chẩn đoán sớm hơn nhưng điều trị khó khăn, tiên lượng xấu.\n1.1. Yếu tố thuận lợi\nUng thư buồng trứng thường gặp ở những phụ nữ có mức sinh hoạt cao và ở những nước công nghiệp. Phụ nữ da trắng có tỷ lệ mắc bệnh cao hơn. Nguy cơ tăng ở lứa tuổi sau 40, trung bình là 50 - 59 tuổi.\n1.2. Nguyên nhân\nCho đến nay, người ta chưa biết rõ nguyên nhân, tuy vậy những yếu tố như ô nhiễm môi trường đặc biệt là chất amian và bột talc (Hydrous magnesium silicate) là hai hóa chất hay gây ung thư buồng trứng.\n\nHình 2. Ung thư biểu mô buồng trứng\n\n2. TRIỆU CHỨNG VÀ CHẨN ĐOÁN\n2.1. Triệu chứng\nTriệu chứng hay gặp là đau bụng, bụng lớn, cảm giác khó chịu, có thể ra máu ở tử cung. Ung thư buồng trứng thường thầm lặng, không có triệu chứng báo trước nên 70 % bệnh nhân đến khám vì tự sờ thấy khối u ở bụng hay do đi khám phụ khoa mà phát hiện ra.\n- Những triệu chứng chèn ép liên quan với giai đoạn phát triển ban đầu.\n- Triệu chứng lan rộng vào ổ bụng  biểu hiện bằng hiện tượng cổ trướng\n- Những triệu chứng về nội tiết như mất kinh hoặc tăng tiết estrogen.\nMột khối u có khuynh hướng ác tính khi khám thấy kích thước khối u phát triển nhanh, mật độ khối u chắc, di động hạn chế và  phát triển cả hai bên buồng trứng.\n- Thăm âm đạo: Nếu u nhỏ không có gì đặc biệt. Khi khối u to mà đường kính từ 5 cm ở những phụ nữ 40-60 tuổi. Khám thấy lổn nhổn, nhiều thùy, nhiều nhú, có thể có dịch ổ bụng, di động hạn chế, có thể phát triển cả hai buồng trứng.\n2.2. Các giai đoạn của ung thư buồng trứng:\n- Giai đoạn I: U khu trú ở buồng trứng\nIa: U một bên, vỏ nguyên vẹn, u không lan ra mặt ngoài, không có cổ trướng\nIb: U hai bên, vỏ nguyên vẹn, u không lan ra mặt ngoài, không có cổ trướng\nIc: U ở giai đoạn Ia hay Ib, lan ra mặt ngoài ở một hay 2 buồng trứng (Vỏ bị vỡ, có cổ trướng, tế bào phúc mạc loại IV)\n- Giai đoạn II: U xâm lấn một hay hai bên buồng trứng và xâm lấn đến chậu hông.\nIIa:\tU xâm lấn và/hoặc di căn tới tử cung và/hoặc vòi trứng nhưng tế bào dịch cổ chướng, dịch rửa ổ bụng âm tính.\nIIb:\tU xâm lấn tới tổ chức khác trong khung chậu nhưng tế bào dịch cổ chướng, dịch rửa ổ bụng âm tính.\nIIc:\tNhư giai đoạn IIA hoặc IIB nhưng tế bào dịch cổ chướng hoặc dịch rửa ổ bụng dương tính.\n- Giai đoạn III: U xâm lấn 1 hay 2 buồng trứng, có di căn ngoài tiểu khung: di căn màng bụng, di căn hạch. Di căn tới bề mặt gan vẫn được tính ở giai đoạn III.\nIIIa:\tDi căn màng bụng ngoài chậu hông.\nIIIb:\tDi căn màng bụng ngoài chậu hông có kích thước < 2 cm.\nIIIc:\tDi căn màng bụng ngoài chậu hông có kích thước > 2 cm.\n- Giai đoạn IV: Khối u ở 1 hay 2 buồng trứng và có di căn xa (không kể phúc mạc), bao gồm cả nhu mô gan, tràn dịch màng phổi ác tính.\n\n\n\n\nHình 3. Các giai đoạn của ung thư buồng trứng\n2.3. Cận lâm sàng\n- Tế bào học âm đạo cổ tử cung: ít có giá trị trong chẩn đoán ung thư buồng trứng.\n- Tế bào nước cổ trướng: 96 % ung thư giai đoạn muộn có tế bào ung thư rụng, phiến đồ dương tính. Theo Graham có những trường hợp ung thư ở giai đoạn sớm, tế bào không rụng trong tiểu khung do đó có khoảng 34 % âm tính giả. Đây là phương pháp tốt để chẩn đoán và theo dõi sự tiến triển của bệnh.\n- Siêu âm: Khối u ở 1 hay 2 buồng trứng, có nhiều chồi, nhú, có nhiều hốc, u hỗn hợp, có thể kèm theo dịch ổ bụng sẽ gợi ý một u ác tính.\n- CA 125: Là chất chỉ điểm trong ung thư, đặc biệt khi  nồng độ CA 125 trong ung thư buồng trứng tăng là bệnh tiến triển và khi nồng độ CA 125 giảm là bệnh thoái triển, thông thường sau phẫu thuật nồng độ CA 125 trở lại bình thường sau 3 tháng. \t.\n- Alpha -fetoprotein huyết thanh và beta hCG giúp phân biệt bản chất của khối u.\nNếu khối u buồng trứng có kèm theo cổ trướng thì cổ trướng có giá trị trong tiến triển và tiên lượng bệnh. Cổ trướng là nước vàng chanh có tiên lượng xấu, nếu nước cổ trướng lẫn máu thì tiên lượng rất xấu, 70 % bệnh nhân chết trong năm đầu.\n\n3. ĐIỀU TRỊ\nĐiều trị khối u ác tính buồng trứng vẫn còn được tranh cãi nhiều vì việc phát hiện bệnh sớm gặp khó khăn, do tính chất giải phẫu bệnh phức tạp, do tiến triển và tiên lượng khó lường trước.\n3.1. Phẫu thuật\nLà biện pháp đầu tiên và quan trọng nhằm mục đích: đánh giá toàn bộ khối u, lấy tổ chức gửi giải phẫu bệnh hoặc giúp điều trị hóa liệu pháp bổ sung. Nếu trường hợp không cắt được toàn bộ khối u thì lấy mẫu sinh thiết,sau đó điều trị hóa chất cho khối u nhỏ đi để có thể mổ lại lần hai, lần 3. Nếu là ung thư thì cắt khối u, cắt buồng trứng bên kia, cắt mạc nối lớn, cắt tử cung hoàn toàn.\n3.2. Hóa liệu pháp\nLà phương pháp điều trị bổ sung quan trọng, có tác dụng đặc biệt đối với các trường hợp có thương tổn ở nhiều nơi, hoặc ở sâu phẫu thuật khó khăn hay quang tuyến không tới được.\nHóa liệu pháp có những ưu điểm sau:\n- Đa số bệnh nhân chịu được\n- Có thể điều trị kéo dài\n- Có thể điều trị trong nhiều tình huống khác nhau như tấn công, duy trì.\nNhưng hóa liệu pháp có những nhược điểm sau:\n- Tác dụng thay đổi trên từng bệnh nhân và từng loại ung thư.\n- Sau một thời gian có hiện tượng quen thuốc.\n- Độc cho hệ tạo huyết, gây giảm miễn dịch, do đó trước khi dùng phải kiểm tra chức năng gan, thận và công thức máu.\n- Phải điều trị kéo dài, nếu ngừng thuốc đột ngột thường nguy hiểm cho bệnh nhân. Có nhiều loại hóa chất điều trị ung thư buồng trứng, có thể xếp thành các nhóm chính.\n+ Nhóm các chất làm hủy hoại ADN có tác dụng trong toàn bộ chu kỳ sinh sản của tế bào. Ví dụ, Thiotepa, Alkeran, Cyclophopshamid, Chlorambuclil.\n+ Các chất chống chuyển hóa, chống lại sinh sản ADN bằng cách thay thế một chất khác vào chuỗi tổng hợp. Ví dụ: Fluouracil, Methotrexate.\n+ Các chất chống phân bào, tác dụng chủ yếu trong giai đoạn phân bào như: Cisplastin, Carboplatin, Đecarbasin.\n+ Kháng sinh chống ung thư Actinomyxin D, Adriamycin, Bleomycin, Platium\n3.3. Quang tuyến liệu pháp\nLà phương pháp điều trị đã có  từ lâu. Cơ sở của phương pháp này dùng tia xạ để  hủy diệt các tế bào đang phân chia (nhanh hơn 50 lần so với các tổ chức bình thường)\nLiều dùng 6000 Rad, thời gian 24 - 30 ngày.\n\n4.TIÊN LƯỢNG VÀ TƯ VẤN\nVì khối u buồng trứng có nguy cơ ngày càng gia  tăng, triệu chứng cơ năng lại rất nghèo nàn, diễn biến lại  phức tạp. Chẩn đoán thường muộn, nên việc điều trị găp nhiều khó khăn. Vì vậy,việc tư vấn cho bệnh nhân có tính chất đặc biệt quan trọng. Công tác chăm sóc sức khoẻ phải làm tốt ở tuyến cơ sở. Tổ chức khám phụ khoa định kỳ để phát hiện sớm các khối u buồng trứng ở mọi lứa tuổi. Những khối u buồng trướng dù nhỏ  cũng cần được quản lý, theo dõi chặt chẽ. Nên gửi lên tuyến có đủ điều kiện để xác định chẩn đoán và xử lý kịp thời các trường hợp nghi ngờ ác tính để tránh các hậu quả không tốt  xẩy ra cho người bệnh.\nCâu hỏi:\n1. Trình bày cách phân loại u nang buồng trứng nói chung và phân loại theo giải phẫu bệnh lý (đại thể) nói riêng?\n2. Trình bày triệu chứng lâm sàng và cận lâm sàng để chẩn đoán xác định u nang buồng trứng?\n3. Trình bày sự tiến triển và biến chứng của u nang buồng trứng?\n\nCHƯƠNG 4.  SƠ SINH", "priority": "Cao (Trọng tâm BSNT)"}, {"id": "SK-48", "chapter": "Chương 4. Sơ sinh", "folder": "04_So_sinh", "title": "Tử vong bà mẹ và trẻ sơ sinh", "author": "Ths. BSCK II. Hoàng Tiến Nam", "word_count": 1571, "line_count": 160, "key_numbers": ["4 tuần", "42 ngày"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["TỬ VONG BÀ MẸ VÀ TRẺ SƠ SINHSCK II. Hoàng Tiến Nam"], "bullets": []}, {"heading": "Mục tiêu học tập", "paragraphs": ["Nêu được định nghĩa và nguyên nhân gây tử vong mẹ", "Trình bày được nguyên nhân tử vong của trẻ sơ sinh", "Tóm tắt được các yếu tố ảnh hưởng đến tử vong mẹ và trẻ sơ sinh", "Nêu các biện pháp khắc phục tử vong mẹ và trẻ sơ sinh"], "bullets": []}, {"heading": "1. ĐỊNH NGHĨA", "paragraphs": ["\"Tử vong mẹ là tử vong của người phụ nữ trong khi mang thai hoặc trong vòng 42 ngày sau khi kết thúc thai kỳ, không phụ thuộc vào thời gian và địa điểm mang thai, do bất kỳ nguyên nhân nào có liên quan hoặc bị nặng lên bởi quá trình mang thai hoặc quản lý thai nghén. Các nguyên nhân tử vong mẹ trong trường hợp này không bao gồm các nguyên nhân do tai nạn hoặc sự cố bất ngờ\" (Tổ chức Y tế Thế giới WHO 1990)."], "bullets": []}, {"heading": "2.1. Tình hình bệnh tật và tử vong mẹ", "paragraphs": ["Các biến chứng của thai nghén và quá trình sinh đẻ là những nguyên nhân hàng đầu gây tử vong và ảnh hưởng sức khoẻ nghiêm trọng ở phụ nữ trong độ tuổi sinh đẻ tại các nước đang phát triển. Thống kê trên thế giới cho thấy một con số ước tính 529.000 phụ nữ chết hàng năm do các nguyên nhân liên quan tới thai nghén. Bên cạnh đó số trường hợp phụ nữ khác bị các ảnh hưởng sức khoẻ như tổn thương đường sinh dục, nhiễm khuẩn và tàn tật trong quá trình mang thai hoặc khi sinh đẻ cao gấp 20 lần so với tử vong mẹ. Điều này có nghĩa ít nhất 10 triệu phụ nữ mỗi năm bị ảnh hưởng đến sức khoẻ do sinh đẻ.", "Những phụ nữ đã từng bị suy dinh dưỡng mạn tính trong quá trình phát triển dễ có nguy cơ đẻ khó khi chuyển dạ. Thiếu máu cũng là yếu tố chỉ báo nguy cơ chảy máu và nhiễm trùng máu trong khi sinh nở và đã được xác định ít nhất trong 20% các trường hợp tử vong mẹ ở các nước đang phát triển.", "Các yếu tố gây ra bệnh tật và tử vong ở mẹ cũng ảnh hưởng tới khả năng sống sót của bào thai và trẻ sơ sinh, dẫn tới khoảng 8 triệu tử vong sơ sinh hàng năm (khoảng một nửa số này là tử vong bào thai).", "Bảng 1:  Tỉ lệ tử vong mẹ theo vùng", "Vùng", "Tỉ lệ tử vong (/100.000 trẻ sơ sinh sống)", "Toàn Thế giới", "400", "Châu Phi", "830", "Châu Á", "330", "Châu Âu", "24", "Tây Âu", "17", "Châu Mỹ La tinh", "190", "Bắc Mỹ", "8", "Úc và New Zealand", "6", "Nguồn: UNICEF/WHO 2005", "Tại Việt Nam, tỷ lệ tử vong mẹ năm 2000 được ước tính 130 ca tử vong trên 100.000 ca sinh sống. Tỷ lệ này đặc biệt cao ở các vùng sâu, vùng cao. Sự khác biệt giữa các vùng tử vong mẹ cũng rất cao: Tây Nguyên: 418/100.000, vùng núi phía Bắc 298/100.000, vùng ven biển phía Bắc và đồng bằng sông Cửu Long là 200/100.000. Nguyên nhân tử vong chủ yếu do năm tai biến sản khoa, đứng đầu là băng huyết sau sinh (41%) và nhiễm trùng hậu sản (20%)."], "bullets": []}, {"heading": "2.2.1.1. Băng huyết", "paragraphs": [], "bullets": ["- Băng huyết trước khi sinh xảy ra vào khoảng giữa tuần thứ 28 và 40 của thời kỳ mang thai, có thể do rau bong non, rau tiền đạo....", "- Băng huyết trong khi sinh: thường do vỡ tử cung và tổn thương đường sinh dục.", "- Băng huyết sau sinh: thường xuất hiện trong những giờ đầu sau sinh. Đây thường là kết quả do chảy máu thời kỳ sổ rau, tổn thương đường sinh dục.", "- Băng huyết do thủng tử cung trong nạo thai to."]}, {"heading": "2.2.1.2. Nhiễm trùng: thường dẫn đến bệnh cảnh nặng nề gây tử vong do nhiễm trùng huyết.", "paragraphs": [], "bullets": ["- Nhiễm trùng hậu sản", "- Nhiễm trùng sau nạo phá thai"]}, {"heading": "2.2.1.3. Tiền sản giật nặng - sản giật", "paragraphs": ["Bệnh nhân có thể tử vong trong bệnh cảnh phù phổi cấp, hội chứng HELLP, sản giật, băng huyết sau sinh...", "Bảng 2: Nguyên nhân tử vong của người mẹ", "Nguyên nhân", "Tỷ lệ (%)", "Số người chết/năm", "Băng huyết", "21", "111.090", "Nạo thai không an toàn", "14", "74.060", "Tăng huyết áp (sản giật)", "13", "68.770", "Đẻ khó", "8", "42.320", "Nhiễm trùng huyết", "8", "42.320", "Biến chứng phụ khoa", "11", "74.060", "Nguyên nhân gián tiếp", "25", "132.250", "Nguồn: UNFPA, 2001"], "bullets": []}, {"heading": "2.2.2. Nguyên nhân gián tiếp", "paragraphs": ["Nguyên nhân gián tiếp gây ra tử vong cho người mẹ có thể từ trước và do có thai nên là trầm trọng thêm, chiếm khoảng 15 - 20 % tỷ lệ tử vong.", "Ví dụ:bệnh tim và thai nghén, basedow và thai nghén, đái tháo đường và thai nghén, viêm gan siêu vi cấp, thiếu máu, bệnh sốt rét, HIV/AIDS.", "Tỷ lệ tử vong các bà mẹ ở các nước đang phát triển:", "Trước khi sinh: 23,9 %", "Trong khi sinh: 15,5 %", "Sau khi sinh:    60,6 %"], "bullets": []}, {"heading": "3. TỬ VONG CỦA TRẺ SƠ SINH", "paragraphs": ["Hàng năm trên toàn thế giới có 7,3 triệu thai nhi và trẻ sơ sinh chết vào những tháng cuối thai kỳ, lúc sinh và trong vòng 4 tuần sau sinh, trong đó có khoảng 3,3 triệu trẻ em chết khi mới sinh và 4 triệu chết trong giai đoạn sơ sinh và 4 triệu trẻ em khác chết trong năm đầu tiên của cuộc đời (WHO, 2005). Nguyên nhân chủ yếu là do suy hô hấp, nhiễm trùng, suy dinh dưỡng."], "bullets": []}, {"heading": "4.1. Các yếu tố ảnh hưởng đến tử vong mẹ", "paragraphs": [], "bullets": ["- Dân trí: thực hiện quản lý thai nghén trước sinh chưa đầy đủ; chăm sóc trước, trong và sau sinh chưa chặt chẽ; Sinh đẻ tại nhà…", "- Kinh tế: chất lượng cuộc sống không đảm bảo, dinh dưỡng kém", "- Mạng lưới y tế địa phương: Công tác tư vấn sức khỏe sinh sản, nạo phá thai không an toàn…"]}, {"heading": "4.2. Các yếu tố ảnh hưởng đến tử vong trẻ sơ sinh", "paragraphs": ["Bảng 4: Ảnh hưởng của một số bệnh của mẹ đối với trẻ sơ sinh", "Mẹ bị bệnh", "Ảnh hưởng nghiêm trọng", "đối với thai nhi và sơ sinh", "Thiếu máu nghiêm trọng", "Nhẹ cân, ngạt thở chết khi lọt lòng", "Băng huyết", "Ngạt thở, giảm lưu lượng máu, chết sau khi lọt lòng", "Tăng huyết áp khi mang thai", "Nhẹ cân, ngạt thở chết khi lọt lòng", "Nhiễm trùng máu", "Trẻ sơ sinh nhiễm trùng huyết", "Đẻ khó", "Ngạt thở, con chết khi lọt lòng, nhiễm trùng máu, thương tổn, khuyết tật", "Nhiễm trùng trong khi mang thai (STDs; HIV)", "Đẻ non, sơ sinh nhiễm khuẩn mắt, mù mắt, viêm phổi. Chết ngay khi lọt lòng, nhiễm bệnh giang mai, lây truyền HIV trực tiếp từ mẹ sang con", "Viêm gan", "Viêm gan", "Sốt rét", "Nhẹ cân, đẻ non, chậm lớn", "Có thai ngoài ý muốn", "Phát triển nguy cơ tật bệnh do sự sỉ nhục ngược đãi và sự bất chấp", "Sinh đẻ không đảm bảo vô khuẩn", "Trẻ sơ sinh bị nhiễm trùng, uốn ván"], "bullets": []}, {"heading": "4.3. Mô hình 3 chậm", "paragraphs": [], "bullets": ["- Chậm quyết định tìm kiếm sự chăm sóc (nhân tố văn hoá/ kinh tế xã hội/ trình độ giáo dục).", "- Chậm xác định và đi đến cơ sở y tế (khả năng tiếp cận với cơ sở y tế).", "- Chậm tiếp nhận điều trị đầy đủ và thích hợp (chất lượng chăm sóc)."]}, {"heading": "5. BIỆN PHÁP KHẮC PHỤC", "paragraphs": [], "bullets": ["- Tăng cường quản lý thai nghén trước đẻ để tuyên truyền giáo dục vận động các bà mẹ mang thai phải được khám đầy đủ tối thiểu 3 lần.", "- Tăng cường chăm sóc trong khi đẻ, bắt buộc theo dõi chặt chẽ sản phụ từ khi chuyển dạ tới khi đẻ. Thực hiện vô khuẩn sản khoa nghiêm túc.", "- Tăng cường đội ngũ cán bộ chuyên khoa sản - nữ hộ sinh tại tuyến cơ sở. Tăng cường bổ sung trang thiết bị.", "- Giảm nạo phá thai không an toàn.", "- Nâng cao vị thế của phụ nữ.", "- Giảm tử vong mẹ có thể thực hiện được bằng cách ngăn ngừa thai nghén không mong muốn ngăn ngừa các biến chứng xảy ra trong khi mang thai, xử trí thích hợp với bất kỳ một biến chứng nào xảy ra.", "- Nâng cao kỹ năng cho nữ hộ sinh bao gồm nâng cao năng lực xử trí ban đầu các biến chứng sản khoa và cấp cứu sản khoa.", "- Dịch vụ cấp cứu sản khoa phải đảm bảo chất lượng phương tiện chuyển tuyến lâm sàng.", "- Cung cấp đầy đủ thuốc thiết yếu và trang thiết bị."]}, {"heading": "Câu hỏi:", "paragraphs": ["Nêu định nghĩa và nguyên nhân gây tử vong mẹ?", "Trình bày nguyên nhân tử vong của trẻ sơ sinh?", "Tóm tắt được các yếu tố ảnh hưởng đến tử vong mẹ và trẻ sơ sinh?", "Nêu biện pháp khắc phục tử vong mẹ và trẻ sơ sinh?"], "bullets": []}], "raw_text": "TỬ VONG BÀ MẸ VÀ TRẺ SƠ SINHSCK II. Hoàng Tiến Nam\nMục tiêu học tập\nNêu được định nghĩa và nguyên nhân gây tử vong mẹ\nTrình bày được nguyên nhân tử vong của trẻ sơ sinh\nTóm tắt được các yếu tố ảnh hưởng đến tử vong mẹ và trẻ sơ sinh\nNêu các biện pháp khắc phục tử vong mẹ và trẻ sơ sinh\n\n1. ĐỊNH NGHĨA\n\"Tử vong mẹ là tử vong của người phụ nữ trong khi mang thai hoặc trong vòng 42 ngày sau khi kết thúc thai kỳ, không phụ thuộc vào thời gian và địa điểm mang thai, do bất kỳ nguyên nhân nào có liên quan hoặc bị nặng lên bởi quá trình mang thai hoặc quản lý thai nghén. Các nguyên nhân tử vong mẹ trong trường hợp này không bao gồm các nguyên nhân do tai nạn hoặc sự cố bất ngờ\" (Tổ chức Y tế Thế giới WHO 1990).\n\n2.  TỬ VONG CỦA BÀ MẸ\n2.1. Tình hình bệnh tật và tử vong mẹ\nCác biến chứng của thai nghén và quá trình sinh đẻ là những nguyên nhân hàng đầu gây tử vong và ảnh hưởng sức khoẻ nghiêm trọng ở phụ nữ trong độ tuổi sinh đẻ tại các nước đang phát triển. Thống kê trên thế giới cho thấy một con số ước tính 529.000 phụ nữ chết hàng năm do các nguyên nhân liên quan tới thai nghén. Bên cạnh đó số trường hợp phụ nữ khác bị các ảnh hưởng sức khoẻ như tổn thương đường sinh dục, nhiễm khuẩn và tàn tật trong quá trình mang thai hoặc khi sinh đẻ cao gấp 20 lần so với tử vong mẹ. Điều này có nghĩa ít nhất 10 triệu phụ nữ mỗi năm bị ảnh hưởng đến sức khoẻ do sinh đẻ.\nNhững phụ nữ đã từng bị suy dinh dưỡng mạn tính trong quá trình phát triển dễ có nguy cơ đẻ khó khi chuyển dạ. Thiếu máu cũng là yếu tố chỉ báo nguy cơ chảy máu và nhiễm trùng máu trong khi sinh nở và đã được xác định ít nhất trong 20% các trường hợp tử vong mẹ ở các nước đang phát triển.\nCác yếu tố gây ra bệnh tật và tử vong ở mẹ cũng ảnh hưởng tới khả năng sống sót của bào thai và trẻ sơ sinh, dẫn tới khoảng 8 triệu tử vong sơ sinh hàng năm (khoảng một nửa số này là tử vong bào thai).\nBảng 1:  Tỉ lệ tử vong mẹ theo vùng\nVùng\nTỉ lệ tử vong (/100.000 trẻ sơ sinh sống)\n\nToàn Thế giới\n400\n\nChâu Phi\n830\n\nChâu Á\n330\n\nChâu Âu\n24\n\nTây Âu\n17\n\nChâu Mỹ La tinh\n190\n\nBắc Mỹ\n8\n\nÚc và New Zealand\n6\n\nNguồn: UNICEF/WHO 2005\nTại Việt Nam, tỷ lệ tử vong mẹ năm 2000 được ước tính 130 ca tử vong trên 100.000 ca sinh sống. Tỷ lệ này đặc biệt cao ở các vùng sâu, vùng cao. Sự khác biệt giữa các vùng tử vong mẹ cũng rất cao: Tây Nguyên: 418/100.000, vùng núi phía Bắc 298/100.000, vùng ven biển phía Bắc và đồng bằng sông Cửu Long là 200/100.000. Nguyên nhân tử vong chủ yếu do năm tai biến sản khoa, đứng đầu là băng huyết sau sinh (41%) và nhiễm trùng hậu sản (20%).\n2.2. Nguyên nhân gây tử vong mẹ\n2.2.1. Nguyên nhân trực tiếp\n2.2.1.1. Băng huyết\n- Băng huyết trước khi sinh xảy ra vào khoảng giữa tuần thứ 28 và 40 của thời kỳ mang thai, có thể do rau bong non, rau tiền đạo....\n- Băng huyết trong khi sinh: thường do vỡ tử cung và tổn thương đường sinh dục.\n- Băng huyết sau sinh: thường xuất hiện trong những giờ đầu sau sinh. Đây thường là kết quả do chảy máu thời kỳ sổ rau, tổn thương đường sinh dục.\n- Băng huyết do thủng tử cung trong nạo thai to.\n2.2.1.2. Nhiễm trùng: thường dẫn đến bệnh cảnh nặng nề gây tử vong do nhiễm trùng huyết.\n- Nhiễm trùng hậu sản\n- Nhiễm trùng sau nạo phá thai\n2.2.1.3. Tiền sản giật nặng - sản giật\nBệnh nhân có thể tử vong trong bệnh cảnh phù phổi cấp, hội chứng HELLP, sản giật, băng huyết sau sinh...\nBảng 2: Nguyên nhân tử vong của người mẹ\nNguyên nhân\nTỷ lệ (%)\nSố người chết/năm\n\nBăng huyết\n21\n111.090\n\nNạo thai không an toàn\n14\n74.060\n\nTăng huyết áp (sản giật)\n13\n68.770\n\nĐẻ khó\n8\n42.320\n\nNhiễm trùng huyết\n8\n42.320\n\nBiến chứng phụ khoa\n11\n74.060\n\nNguyên nhân gián tiếp\n25\n132.250\n\nNguồn: UNFPA, 2001\n2.2.2. Nguyên nhân gián tiếp\nNguyên nhân gián tiếp gây ra tử vong cho người mẹ có thể từ trước và do có thai nên là trầm trọng thêm, chiếm khoảng 15 - 20 % tỷ lệ tử vong.\nVí dụ:bệnh tim và thai nghén, basedow và thai nghén, đái tháo đường và thai nghén, viêm gan siêu vi cấp, thiếu máu, bệnh sốt rét, HIV/AIDS.\nTỷ lệ tử vong các bà mẹ ở các nước đang phát triển:\nTrước khi sinh: 23,9 %\nTrong khi sinh: 15,5 %\nSau khi sinh:    60,6 %\n3. TỬ VONG CỦA TRẺ SƠ SINH\nHàng năm trên toàn thế giới có 7,3 triệu thai nhi và trẻ sơ sinh chết vào những tháng cuối thai kỳ, lúc sinh và trong vòng 4 tuần sau sinh, trong đó có khoảng 3,3 triệu trẻ em chết khi mới sinh và 4 triệu chết trong giai đoạn sơ sinh và 4 triệu trẻ em khác chết trong năm đầu tiên của cuộc đời (WHO, 2005). Nguyên nhân chủ yếu là do suy hô hấp, nhiễm trùng, suy dinh dưỡng.\n4. NHỮNG YẾU TỐ ẢNH HƯỞNG ĐẾN TỶ LỆ TỬ VONG CỦA BÀ MẸ VÀ TRẺ SƠ SINH\n4.1. Các yếu tố ảnh hưởng đến tử vong mẹ\n- Dân trí: thực hiện quản lý thai nghén trước sinh chưa đầy đủ; chăm sóc trước, trong và sau sinh chưa chặt chẽ; Sinh đẻ tại nhà…\n- Kinh tế: chất lượng cuộc sống không đảm bảo, dinh dưỡng kém\n- Mạng lưới y tế địa phương: Công tác tư vấn sức khỏe sinh sản, nạo phá thai không an toàn…\n4.2. Các yếu tố ảnh hưởng đến tử vong trẻ sơ sinh\nBảng 4: Ảnh hưởng của một số bệnh của mẹ đối với trẻ sơ sinh\nMẹ bị bệnh\nẢnh hưởng nghiêm trọng\nđối với thai nhi và sơ sinh\n\nThiếu máu nghiêm trọng\nNhẹ cân, ngạt thở chết khi lọt lòng\n\nBăng huyết\nNgạt thở, giảm lưu lượng máu, chết sau khi lọt lòng\n\nTăng huyết áp khi mang thai\nNhẹ cân, ngạt thở chết khi lọt lòng\n\nNhiễm trùng máu\nTrẻ sơ sinh nhiễm trùng huyết\n\nĐẻ khó\nNgạt thở, con chết khi lọt lòng, nhiễm trùng máu, thương tổn, khuyết tật\n\nNhiễm trùng trong khi mang thai (STDs; HIV)\nĐẻ non, sơ sinh nhiễm khuẩn mắt, mù mắt, viêm phổi. Chết ngay khi lọt lòng, nhiễm bệnh giang mai, lây truyền HIV trực tiếp từ mẹ sang con\n\nViêm gan\nViêm gan\n\nSốt rét\nNhẹ cân, đẻ non, chậm lớn\n\nCó thai ngoài ý muốn\nPhát triển nguy cơ tật bệnh do sự sỉ nhục ngược đãi và sự bất chấp\n\nSinh đẻ không đảm bảo vô khuẩn\nTrẻ sơ sinh bị nhiễm trùng, uốn ván\n\n4.3. Mô hình 3 chậm\n- Chậm quyết định tìm kiếm sự chăm sóc (nhân tố văn hoá/ kinh tế xã hội/ trình độ giáo dục).\n- Chậm xác định và đi đến cơ sở y tế (khả năng tiếp cận với cơ sở y tế).\n- Chậm tiếp nhận điều trị đầy đủ và thích hợp (chất lượng chăm sóc).\n5. BIỆN PHÁP KHẮC PHỤC\n- Tăng cường quản lý thai nghén trước đẻ để tuyên truyền giáo dục vận động các bà mẹ mang thai phải được khám đầy đủ tối thiểu 3 lần.\n- Tăng cường chăm sóc trong khi đẻ, bắt buộc theo dõi chặt chẽ sản phụ từ khi chuyển dạ tới khi đẻ. Thực hiện vô khuẩn sản khoa nghiêm túc.\n- Tăng cường đội ngũ cán bộ chuyên khoa sản - nữ hộ sinh tại tuyến cơ sở. Tăng cường bổ sung trang thiết bị.\n- Giảm nạo phá thai không an toàn.\n- Nâng cao vị thế của phụ nữ.\n- Giảm tử vong mẹ có thể thực hiện được bằng cách ngăn ngừa thai nghén không mong muốn ngăn ngừa các biến chứng xảy ra trong khi mang thai, xử trí thích hợp với bất kỳ một biến chứng nào xảy ra.\n- Nâng cao kỹ năng cho nữ hộ sinh bao gồm nâng cao năng lực xử trí ban đầu các biến chứng sản khoa và cấp cứu sản khoa.\n- Dịch vụ cấp cứu sản khoa phải đảm bảo chất lượng phương tiện chuyển tuyến lâm sàng.\n- Cung cấp đầy đủ thuốc thiết yếu và trang thiết bị.\nCâu hỏi:\nNêu định nghĩa và nguyên nhân gây tử vong mẹ?\nTrình bày nguyên nhân tử vong của trẻ sơ sinh?\nTóm tắt được các yếu tố ảnh hưởng đến tử vong mẹ và trẻ sơ sinh?\nNêu biện pháp khắc phục tử vong mẹ và trẻ sơ sinh?", "priority": "Trung bình"}, {"id": "SK-49", "chapter": "Chương 4. Sơ sinh", "folder": "04_So_sinh", "title": "Hồi sức sơ sinh ngạt", "author": "Ths. Đinh Văn Hoành", "word_count": 2557, "line_count": 244, "key_numbers": ["0 mmHg", "0,1mg", "0,1ml", "0,2mg", "0,3mg", "0,5 ml", "0,9 ml", "1 phút", "1,5 ml", "10 phút", "100 mmHg", "15 phút", "1phút", "2 phút", "20 ml", "40mmHg", "4ml", "5 phút", "5ml", "5phút", "70mmHg", "8 ml"], "key_drugs": ["Glucose"], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["HỒI SỨC SƠ SINH NGẠT", "Ths. Đinh Văn Hoành"], "bullets": []}, {"heading": "1. ĐẠI CƯƠNG", "paragraphs": ["Ngạt ở trẻ sơ sinh là tình trạng đứa bé thất bại trong việc khởi động và duy trì hô hấp lúc mới sinh dẫn đến hậu quả là thiếu oxy máu, thừa CO2 dẫn đến toan chuyển hoá. Ngạt có thể gây tử  vong sơ sinh hoặc để lại nhiều di chứng.", "Theo WHO có khoảng 3% trong tổng số 120 triệu trẻ sơ sinh mỗi năm ở các nước đang phát triển bị ngạt khi sinh cần được hồi sức. Mỗi năm có khoảng 900.000 trẻ tử vong do ngạt."], "bullets": []}, {"heading": "2. SINH LÝ BỆNH HỌC TRẺ SƠ SINH NGẠT", "paragraphs": ["Trường hợp trẻ bị ngạt sau khi sinh, do phổi của trẻ chưa hoạt động nên trao đổi khí không thể xảy ra ở phổi dẫn đến tình trạng thiếu oxy kéo dài. Trong khi đó, dây rốn đã bị cắt, sơ sinh không còn liên hệ với tuần hoàn mẹ. Do thiếu oxy mạch máu phổi càng co lại, máu về tim trái ít nên lỗ Botal không đóng lại được. Chỉ cần đứa trẻ ngạt trong vài phút sẽ dẫn đến nguy cơ:", "Nếu không được hồi sức hữu hiệu, tình trạng ngạt sơ sinh kéo dài sẽ đưa đến toan hô hấp rồi toan chuyển hoá.", "Trẻ bị ngạt thiếu oxy nên chuyển hoá Glucose phải đi theo con đường yếm khí, giải phóng nhiều acid lactic làm pH máu ngày càng giảm. Do đó, mục đích của phương pháp hồi sức sơ sinh là đưa không khí vào tận phế nang làm cho phổi hoạt động, cải thiện tình trạng thiếu oxy máu và toan chuyển hoá."], "bullets": ["- PaO2 giảm dần đến 0 mmHg", "- PaCO2 tăng dần đến 100 mmHg", "- pH máu giảm < 7,20"]}, {"heading": "3. PHƯƠNG PHÁP ĐÁNH GIÁ TRẺ SƠ SINH NGAY SAU ĐẺ", "paragraphs": ["Chỉ số APGAR: Là phương tiện hữu ích trong việc đánh giá trẻ sau sinh ở thời điểm 1 phút và lặp lại ở 5 phút sau sinh.", "Bảng điểm APGAR", "Dấu hiệu", "0 điểm", "1 điểm", "2 điểm", "Màu da", "Xanh, tím toàn thân", "Thân hồng, tay chân tím", "Toàn thân hồng", "Nhịp tim", "Không có", "< 100 lần/phút", "> 100 lần/phút", "Phản xạ", "Không đáp ứng", "Nhăn mặt", "Khóc to", "Trương lực cơ", "Mềm nhũn", "Có vài sự co cơ các chi", "Vận động tốt", "Hô hấp", "Không có", "Chậm, không đều", "Tốt, khóc", "Theo nhiều tác giả, chúng ta nên đánh giá chỉ số APGAR ở những thời điểm 1 phút, 5phút, 10 phút sau sinh.", "Trẻ tốt đạt 10 điểm là tối đa.", "Đánh giá điểm số APGAR sau 1 phút để xác định xem có cần hồi sức hay không?", "Hình 1. Đánh giá chỉ số Apgar", "Năm 1952 Bs. Virgina Apgar phát minh ra hệ thống điểm đánh giá sơ sinh ngay sau đẻ với 5 chỉ số và cho điểm 0,1,2. Tuy nhiên chỉ số Apgar có 1 số hạn chế sau:", "Mẹ dùng thuốc an thần, gây mê", "Sơ sinh bất thường bẩm sinh", "Tuổi thai: trẻ non tháng có thể có chỉ số Apgar thấp nhưng không bị ngạt.", "Chấn thương"], "bullets": ["- APGAR 8 - 10/1 phút: Tình trạng trẻ tốt, chỉ cần hút sạch dịch ở mũi - hầu", "- APGAR 4 - 7/1 phút: Trẻ ngạt từ nhẹ đến trung bình. Trẻ có hô hấp yếu, trương lực cơ nhão, màu sắc da xanh đến tím nhưng nhịp tim và kích thích phản xạ tốt. Cần phải hồi sức cho đứa bé.", "- APGAR 0 - 3/1phút: Trẻ ngạt nặng, không khóc, không thở, mạch rốn không đập hoặc đập dưới 80 lần/phút. Nhịp tim chậm hoặc không nghe được. Đáp ứng phản xạ yếu hay không có, phải hồi sức tích cực."]}, {"heading": "4.1. Điểm số APGAR 8 - 10/1phút", "paragraphs": ["Chỉ cần hút sạch nhớt ở mũi - hầu"], "bullets": []}, {"heading": "4.2. Điểm số APGAR 4 - 7/1phút", "paragraphs": ["Trẻ ngạt từ nhẹ đến trung bình còn gọi là ngạt tím"], "bullets": ["- Nếu trẻ chỉ tím tái nhưng nhịp tim > 100 lần/ phút thì làm theo các bước sau:", "+ Làm thông đường hô hấp bằng cách hút dịch ở miệng, mũi - hầu.", "+ Giúp thở bằng mặt nạ.", "+ Nếu sau đó trẻ thở tốt không cần tiêm thuốc.", "- Nếu sau hồi sức 5-10 phút mà tình trạng trẻ không cải thiện, thì:", "+ Tiêm Bicarbonat natri 4,2% (5ml/kg) và dung dịch Glucose 10% (3-4ml/kg) vào tĩnh mạch rốn.", "+ Theo dõi nhịp tim trẻ nếu chậm < 100 lần/phút thì thực hiện theo phác đồ (sơ đồ 2).\t+ Khám kỹ để phát hiện dị tật hẹp lỗ mũi sau hay thoát vị cơ hoành..."]}, {"heading": "4.3. Điểm số APGAR 0 - 3/1'", "paragraphs": ["Trẻ ngạt nặng hay còn gọi là ngạt trắng. Phải hồi sức tích cực, trong vài phút đầu tiên cần thực hiện ngay những động tác sau:", "Nếu kết quả tốt sau khi hồi sức, trẻ bắt đầu thở nấc rồi hồng hào dần. Khi đó vẫn tiếp tục xoa bóp kích thích tim, tiếp tục cho thở oxy 10 -15 phút, cho đến khi trẻ thở tốt, khóc to, có phản xạ tay chân tốt. Đánh giá lại chỉ số APGAR nếu trên 7 có thể rút ống nội khí quản.", "Kết quả xấu, nếu sau 5 phút hồi sức trẻ vẫn không tự thở được, tiêm Adrenalin 1/10.000 vào tĩnh mạch rốn hoặc bơm vào ống nội khí quản. Nếu sau khi bơm thuốc và 15 phút hồi sức tích cực mà tình trạng trẻ vẫn không tốt hơn, thì ngưng hồi sức."], "bullets": ["- Hút sạch hầu họng.", "- Thông khí hỗ trợ và đặt nội khí quản.", "- Giữ ấm cho trẻ.", "- Cùng một lúc: Vừa hỗ trợ hô hấp, vừa bóp tim ngoài lồng ngực.", "- Nếu nhịp tim < 60l/ phút, cho Adrenalin qua ống nội khí quản hay tiêm tĩnh mạch rốn.", "- Tiếp tục bóp bóng oxy 100% qua ống nội khí quản.", "- Đánh giá chỉ số APGAR lúc 5 phút và 10 phút."]}, {"heading": "5.1. Dụng cụ và phương tiện", "paragraphs": ["Đèn soi thanh quản (để đặt ống NKQ).", "Ống nội khí quản sơ sinh - kềm Magill", "Máy thở áp lực dương cho trẻ em (nếu có)"], "bullets": ["-  Quả bóp cao su (Poire)", "-  Ống hút nhớt", "-  Máy hút điện", "-  Mặt nạ sơ sinh nhiều cỡ", "-  Bóng ambu sơ sinh", "-  Thuốc:", "+ Dung dịch Glucose 10%, 5%", "+ Dung dịch Natri Bicarbonate 4,2%", "+ Calcium gluconate 10%", "+ Albumin 5%", "+ Adrenaline 1/1.000", "-  Lò sưởi điện hoặc túi nước nóng, bóng đèn sưởi.", "-  Giường ấm hoặc lồng kính để theo dõi sau khi hồi sức."]}, {"heading": "5.2. Kỹ thuật", "paragraphs": ["Các nguyên tắc hồi sức sơ sinh:", "A - (Airway)\t\t: Thông đường hô hấp", "B - (Breathing)\t: Hỗ trợ hô hấp", "C - (Circulation)\t: Bảo đảm tuần hoàn tối thiểu có hiệu quả"], "bullets": []}, {"heading": "5.2.1 Làm sạch đường hô hấp", "paragraphs": ["Đặt trẻ nằm đầu hơi thấp, nghiêng trái, hút nhớt ở hầu  và mũi. Nếu trẻ có hít phân su đặc, phải đặt nội khí quản để  hút  sạch phân su với ống hút cỡ lớn và cho thông khí áp lực dương sau khi đã làm sạch đường hô hấp. Khi đường hô hấp được làm sạch và tình trạng trẻ tốt hơn, đặt sonde dạ dày để hút hết những phân su còn đọng lại trong dạ dày."], "bullets": []}, {"heading": "5.2.2 Giữ ấm", "paragraphs": ["Đặt trẻ nơi khô ráo, có đèn sưởi bức xạ bên trên, lau khô ngay lập tức. Sự giảm nhiệt độ là một kích thích góp phần làm suy yếu trẻ. Nếu cần hồi sức, trẻ phải được sưởi ấm cho đến khi chuyển trẻ về phòng sơ sinh."], "bullets": []}, {"heading": "5.2.3 Hỗ trợ hô hấp", "paragraphs": ["Nếu trẻ không thở, kích thích trẻ bằng cách búng vào gan bàn chân hay xoa má, ngực, bụng, lưng đồng thời cho thở oxy 100% qua mặt nạ là đủ kích thích trẻ thở. Nếu hô hấp của trẻ không bắt đầu sau đẻ 30 giây, thì cho thở oxy qua mặt nạ, đủ để tạo sự di động của lồng ngực. Áp lực bóp bóng cho động tác thở đầu tiên là 30 - 35cmH2O. Đối với trẻ thiếu tháng, lúc đầu sử dụng áp lực cao hơn sau đó giảm dần để có được sự di động nhẹ nhàng của lồng ngực. Sự thông khí hỗ trợ cũng nên thực hiện khi nhịp tim của trẻ < 100 nhịp/phút. Sử dụng biện pháp thông khí với áp lực dương:", "*  Sau khi thông khí bằng bóng và mặt nạ thất bại.", "* Tắc nghẽn đường thở nghi ngờ do bướu giáp hoặc tật hàm nhỏ.", "*  Thông khí cho trẻ hít phải phân su sau khi đã hút sạch trong khí quản, thoát vị cơ hoành.", "* Phối hợp với bóp tim ngoài lồng ngực.", "Hình 1. Đặt nội khí quản sơ sinh"], "bullets": ["- Thông khí bằng bóng ambu và mặt nạ (mask): dễ thực hiện và thường có hiệu quả.", "+ Để đầu trẻ hơi ngửa ra sau, mặt nạ được giữ bởi ngón cái và 2 ngón trỏ và giữa của bàn tay trái, đặt mặt nạ phủ kín lên miệng, mũi của bé; Hai ngón tay còn lại dùng để nâng cằm. Bóp bóng bằng bàn tay phải, cung cấp khí giàu oxy với tần số 40 lần/phút. Người thực hiện tốt nhất là đứng về phía đầu của bé.", "+ Hiệu quả của thông khí được đánh giá bằng cách quan sát cử động lồng ngực của trẻ và sự tăng nhịp tim.", "- Thông khí qua ống nội khí quản", "+ Chỉ định:"]}, {"heading": "5.2.4 Bóp tim ngoài lồng ngực", "paragraphs": ["Thực hiện khi vừa mới nghe được tim thai trước khi sinh nhưng không nghe được tiếng tim hoặc tim ngừng đập sau khi sinh, hoặc trong khoảng 30 giây từ khi bắt đầu thông khí mà nhịp tim không đạt trên 100 nhịp/phút.", "Kỹ thuật: Dùng 2 ngón tay đặt trên thành ngực trước, tại vị trí 1/3 dưới đường giữa xương ức. Tần số bóp tim 100 - 120 lần/ phút, cứ 3 lần bóp tim xen kẽ một lần bóp bóng. Nếu trong vòng 30 giây thực hiện xoa bóp tim ngoài lồng ngực kết hợp với bóp bóng mà trẻ không đáp ứng tốt nên cho thuốc.", "Hình 2.  Hai kỹ thuật ép tim ngoài lồng ngực", "A. Dùng 2 ngón tay cái      B. Dùng ngón trỏ và ngón giữa"], "bullets": []}, {"heading": "6.1. Đường sử dụng", "paragraphs": [], "bullets": ["- Đường tĩnh mạch ngoại biên: Không có sẵn từ phút đầu.", "- Đường tĩnh mạch rốn: Chích thuốc trực tiếp, nhanh nhưng có thể có tai biến thiếu máu cục bộ hay huyết khối tại động mạch hạ vị.", "- Đường nội khí quản: Một vài loại thuốc có thể qua đường nội khí quản nhanh chóng và có hiệu quả tương đương đường tĩnh mạch."]}, {"heading": "6.2.1 Adrenalin", "paragraphs": [], "bullets": ["- Chỉ định: Khi nhịp tim < 60 lần/ phút sau 30 giây thông khí và xoa bóp tim ngoài lồng ngực.", "- Liều 0,1ml 10/00 pha loãng với 0,9 ml NaCl 9 0/00 tiêm tĩnh mạch rốn hay đường nội khí quản."]}, {"heading": "6.2.2 Bicarbonate Natri 4,2%", "paragraphs": [], "bullets": ["- Liều 2 - 8 ml/kg tiêm tĩnh mạch  có thể lặp lại sau 10 phút.", "- Chỉ dùng trong trường hợp bị toan chuyển hóa, không có lợi trong trường hợp chỉ có toan hô hấp đơn thuần.", "- Chỉ định:", "+  Ngưng tim kéo dài", "+  Rối loạn hô hấp kéo dài > 10 phút", "+ Chú ý: Tiêm bicarbonat chậm vào tĩnh mạch thời gian tối thiểu là trên 2 phút."]}, {"heading": "6.2.3 Glucose 10%", "paragraphs": [], "bullets": ["- Liều 3-5ml/kg, không nên cho quá nhiều Glucose, vì trong điều kiện thiếu oxy Gluose sẽ chuyển hóa theo con đường yếm khí tạo ra rất ít năng lượng mà giải phóng nhiều acid lactic gây toan chuyển hóa."]}, {"heading": "6.2.4. Naloxone", "paragraphs": [], "bullets": ["- Chỉ định khi trẻ bị ức chế hô hấp do các thuốc thuộc nhóm morphine. Liều 0,1mg/kg, # 0,3mg cho một lần tiêm.", "- Cách pha: lấy 0,5 ml (1/2ống = 0,2mg) pha với 1,5 ml NaCl 9 0/00.", "- Dùng liều 0,1ml dung dịch pha/kg tĩnh mạch, tiêm bắp hay đường nội khí quản.", "- Có thể cho nhiều lần vì thời gian tác dụng của thuốc ngắn hơn so với các thuốc nhóm Morphin."]}, {"heading": "6.2.5 Albumine 5%", "paragraphs": [], "bullets": ["- Chỉ định khi giảm thể tích tuần hoàn.", "- Liều 10 - 20 ml/kg tiêm tĩnh mạch trên 15 phút."]}, {"heading": "6.2.6. Isuprel", "paragraphs": [], "bullets": ["- Nếu tim chậm kéo dài.", "- Liều 5 - 20 (g/kg/liều tiêm tĩnh mạch với tốc độ 0,1 - 1 (g/kg/phút."]}, {"heading": "7. TIÊU CHUẨN ĐÁNH GIÁ HỒI SỨC", "paragraphs": [], "bullets": ["- Lâm sàng:", "+Trẻ hết tím tái, hồng hào, khóc được", "+ Trẻ thở đều, thở sâu, tự thở", "+ Nhịp tim > 100 lần phút, đều rõ.", "+ Phản xạ tốt, trương lực cơ bình thường", "- Sinh hóa:  Ổn định được tình trạng toan hóa trong máu.", "+ pH > 7.3", "+ PaCO2 < 40mmHg", "+ PaO2 = 60 - 70mmHg"]}, {"heading": "8. CHĂM SÓC TRẺ SAU HỒI SỨC", "paragraphs": ["Những trẻ được hồi sức có hiệu quả cần phải quan sát và theo dõi thêm sau đó. Các rối loạn bao gồm:"], "bullets": []}, {"heading": "8.1. Rối loạn chuyển hoá:", "paragraphs": ["Sơ đồ 1: Ảnh hưởng của hạ thân nhiệt đến hô hấp."], "bullets": ["- Tình trạng nhiễm toan.", "- Hạ đường huyết.", "- Hạ Calci huyết.", "- Hạ thân nhiệt."]}, {"heading": "8.2. Di chứng ở hệ thần kinh trung ương", "paragraphs": [], "bullets": ["- Phù não dẫn đến hôn mê hay co giật.", "- Xuất huyết não trước hết là xuất huyết trong não thất, có thể xảy ra ở trẻ thiếu tháng, tiên lượng xấu."]}, {"heading": "8.3. Di chứng ở thận", "paragraphs": [], "bullets": ["- Suy thận cấp: Hầu hết là do hoại tử ống thận cấp.", "- Hoại tử vỏ thận, huyết khối tĩnh mạch thận sẽ là nguyên nhân của suy thận sau ngạt."]}, {"heading": "8.4. Di chứng ở tim", "paragraphs": ["Ở trẻ ngạt, tim là cơ quan bị ảnh hưởng nhiều nhất và có thể gây tổn thương nặng gây tử vong trẻ."], "bullets": []}, {"heading": "8.5. Di chứng ở phổi", "paragraphs": ["Co thắt mạch ở phổi nên duy trì shunt phải - trái, máu qua ống động mạch hay lỗ bầu dục làm tồn tại tuần hoàn bào thai đưa đến tình trạng xanh tím nặng.", "PHÁC ĐỒ XỬ TRÍ HỒI SỨC SƠ SINH", "TRẺ SƠ SINH", "Sơ đồ 2. Phác đồ xử trí trẻ ngạt ngay sau sinh", "Cõu hỏi: 1.  Trình bầy các phương phỏp phải thực hiện để hồi sức sơ sịnh?"], "bullets": []}, {"heading": "2. Trình bầy các thuốc và dịch truyền để hồi sức sơ sịnh?", "paragraphs": ["CHƯƠNG 5. KẾ HOẠCH HÓA GIA ĐÌNH"], "bullets": []}], "raw_text": "HỒI SỨC SƠ SINH NGẠT\nThs. Đinh Văn Hoành\nMục tiêu học tập.\n1. Giải thích ảnh hưởng của tình trạng ngạt lên hệ tuần hoàn, chuyển hóa của thai nhi.\n2. Đánh giá mức độ trầm trọng của trẻ sau sinh dựa vào chỉ số  APGAR.\n3. Thực hiện kỹ thuật hồi sức trẻ sơ sinh bị ngạt\n\n1. ĐẠI CƯƠNG\nNgạt ở trẻ sơ sinh là tình trạng đứa bé thất bại trong việc khởi động và duy trì hô hấp lúc mới sinh dẫn đến hậu quả là thiếu oxy máu, thừa CO2 dẫn đến toan chuyển hoá. Ngạt có thể gây tử  vong sơ sinh hoặc để lại nhiều di chứng.\nTheo WHO có khoảng 3% trong tổng số 120 triệu trẻ sơ sinh mỗi năm ở các nước đang phát triển bị ngạt khi sinh cần được hồi sức. Mỗi năm có khoảng 900.000 trẻ tử vong do ngạt.\n\n2. SINH LÝ BỆNH HỌC TRẺ SƠ SINH NGẠT\nTrường hợp trẻ bị ngạt sau khi sinh, do phổi của trẻ chưa hoạt động nên trao đổi khí không thể xảy ra ở phổi dẫn đến tình trạng thiếu oxy kéo dài. Trong khi đó, dây rốn đã bị cắt, sơ sinh không còn liên hệ với tuần hoàn mẹ. Do thiếu oxy mạch máu phổi càng co lại, máu về tim trái ít nên lỗ Botal không đóng lại được. Chỉ cần đứa trẻ ngạt trong vài phút sẽ dẫn đến nguy cơ:\n- PaO2 giảm dần đến 0 mmHg\n- PaCO2 tăng dần đến 100 mmHg\n- pH máu giảm < 7,20\nNếu không được hồi sức hữu hiệu, tình trạng ngạt sơ sinh kéo dài sẽ đưa đến toan hô hấp rồi toan chuyển hoá.\nTrẻ bị ngạt thiếu oxy nên chuyển hoá Glucose phải đi theo con đường yếm khí, giải phóng nhiều acid lactic làm pH máu ngày càng giảm. Do đó, mục đích của phương pháp hồi sức sơ sinh là đưa không khí vào tận phế nang làm cho phổi hoạt động, cải thiện tình trạng thiếu oxy máu và toan chuyển hoá.\n\n3. PHƯƠNG PHÁP ĐÁNH GIÁ TRẺ SƠ SINH NGAY SAU ĐẺ\nChỉ số APGAR: Là phương tiện hữu ích trong việc đánh giá trẻ sau sinh ở thời điểm 1 phút và lặp lại ở 5 phút sau sinh.\nBảng điểm APGAR\nDấu hiệu\n0 điểm\n1 điểm\n2 điểm\n\nMàu da\nXanh, tím toàn thân\nThân hồng, tay chân tím\nToàn thân hồng\n\nNhịp tim\nKhông có\n< 100 lần/phút\n> 100 lần/phút\n\nPhản xạ\nKhông đáp ứng\nNhăn mặt\nKhóc to\n\nTrương lực cơ\nMềm nhũn\nCó vài sự co cơ các chi\nVận động tốt\n\nHô hấp\nKhông có\nChậm, không đều\nTốt, khóc\n\n\nTheo nhiều tác giả, chúng ta nên đánh giá chỉ số APGAR ở những thời điểm 1 phút, 5phút, 10 phút sau sinh.\nTrẻ tốt đạt 10 điểm là tối đa.\nĐánh giá điểm số APGAR sau 1 phút để xác định xem có cần hồi sức hay không?\n- APGAR 8 - 10/1 phút: Tình trạng trẻ tốt, chỉ cần hút sạch dịch ở mũi - hầu\n- APGAR 4 - 7/1 phút: Trẻ ngạt từ nhẹ đến trung bình. Trẻ có hô hấp yếu, trương lực cơ nhão, màu sắc da xanh đến tím nhưng nhịp tim và kích thích phản xạ tốt. Cần phải hồi sức cho đứa bé.\n- APGAR 0 - 3/1phút: Trẻ ngạt nặng, không khóc, không thở, mạch rốn không đập hoặc đập dưới 80 lần/phút. Nhịp tim chậm hoặc không nghe được. Đáp ứng phản xạ yếu hay không có, phải hồi sức tích cực.\n\nHình 1. Đánh giá chỉ số Apgar\nNăm 1952 Bs. Virgina Apgar phát minh ra hệ thống điểm đánh giá sơ sinh ngay sau đẻ với 5 chỉ số và cho điểm 0,1,2. Tuy nhiên chỉ số Apgar có 1 số hạn chế sau:\nMẹ dùng thuốc an thần, gây mê\nSơ sinh bất thường bẩm sinh\nTuổi thai: trẻ non tháng có thể có chỉ số Apgar thấp nhưng không bị ngạt.\nChấn thương\n4. CHỈ ĐỊNH HỒI SỨC\n4.1. Điểm số APGAR 8 - 10/1phút\nChỉ cần hút sạch nhớt ở mũi - hầu\n4.2. Điểm số APGAR 4 - 7/1phút\nTrẻ ngạt từ nhẹ đến trung bình còn gọi là ngạt tím\n- Nếu trẻ chỉ tím tái nhưng nhịp tim > 100 lần/ phút thì làm theo các bước sau:\n+ Làm thông đường hô hấp bằng cách hút dịch ở miệng, mũi - hầu.\n+ Giúp thở bằng mặt nạ.\n+ Nếu sau đó trẻ thở tốt không cần tiêm thuốc.\n- Nếu sau hồi sức 5-10 phút mà tình trạng trẻ không cải thiện, thì:\n+ Tiêm Bicarbonat natri 4,2% (5ml/kg) và dung dịch Glucose 10% (3-4ml/kg) vào tĩnh mạch rốn.\n+ Theo dõi nhịp tim trẻ nếu chậm < 100 lần/phút thì thực hiện theo phác đồ (sơ đồ 2).\t+ Khám kỹ để phát hiện dị tật hẹp lỗ mũi sau hay thoát vị cơ hoành...\n4.3. Điểm số APGAR 0 - 3/1'\nTrẻ ngạt nặng hay còn gọi là ngạt trắng. Phải hồi sức tích cực, trong vài phút đầu tiên cần thực hiện ngay những động tác sau:\n- Hút sạch hầu họng.\n- Thông khí hỗ trợ và đặt nội khí quản.\n- Giữ ấm cho trẻ.\n- Cùng một lúc: Vừa hỗ trợ hô hấp, vừa bóp tim ngoài lồng ngực.\n- Nếu nhịp tim < 60l/ phút, cho Adrenalin qua ống nội khí quản hay tiêm tĩnh mạch rốn.\n- Tiếp tục bóp bóng oxy 100% qua ống nội khí quản.\n- Đánh giá chỉ số APGAR lúc 5 phút và 10 phút.\nNếu kết quả tốt sau khi hồi sức, trẻ bắt đầu thở nấc rồi hồng hào dần. Khi đó vẫn tiếp tục xoa bóp kích thích tim, tiếp tục cho thở oxy 10 -15 phút, cho đến khi trẻ thở tốt, khóc to, có phản xạ tay chân tốt. Đánh giá lại chỉ số APGAR nếu trên 7 có thể rút ống nội khí quản.\nKết quả xấu, nếu sau 5 phút hồi sức trẻ vẫn không tự thở được, tiêm Adrenalin 1/10.000 vào tĩnh mạch rốn hoặc bơm vào ống nội khí quản. Nếu sau khi bơm thuốc và 15 phút hồi sức tích cực mà tình trạng trẻ vẫn không tốt hơn, thì ngưng hồi sức.\n5. PHƯƠNG PHÁP HỒI SỨC\n5.1. Dụng cụ và phương tiện\n-  Quả bóp cao su (Poire)\n-  Ống hút nhớt\n-  Máy hút điện\n-  Mặt nạ sơ sinh nhiều cỡ\n-  Bóng ambu sơ sinh\nĐèn soi thanh quản (để đặt ống NKQ).\nỐng nội khí quản sơ sinh - kềm Magill\nMáy thở áp lực dương cho trẻ em (nếu có)\n-  Thuốc:\n+ Dung dịch Glucose 10%, 5%\n+ Dung dịch Natri Bicarbonate 4,2%\n+ Calcium gluconate 10%\n+ Albumin 5%\n+ Adrenaline 1/1.000\n-  Lò sưởi điện hoặc túi nước nóng, bóng đèn sưởi.\n-  Giường ấm hoặc lồng kính để theo dõi sau khi hồi sức.\n5.2. Kỹ thuật\nCác nguyên tắc hồi sức sơ sinh:\nA - (Airway)\t\t: Thông đường hô hấp\nB - (Breathing)\t: Hỗ trợ hô hấp\nC - (Circulation)\t: Bảo đảm tuần hoàn tối thiểu có hiệu quả\n5.2.1 Làm sạch đường hô hấp\nĐặt trẻ nằm đầu hơi thấp, nghiêng trái, hút nhớt ở hầu  và mũi. Nếu trẻ có hít phân su đặc, phải đặt nội khí quản để  hút  sạch phân su với ống hút cỡ lớn và cho thông khí áp lực dương sau khi đã làm sạch đường hô hấp. Khi đường hô hấp được làm sạch và tình trạng trẻ tốt hơn, đặt sonde dạ dày để hút hết những phân su còn đọng lại trong dạ dày.\n5.2.2 Giữ ấm\nĐặt trẻ nơi khô ráo, có đèn sưởi bức xạ bên trên, lau khô ngay lập tức. Sự giảm nhiệt độ là một kích thích góp phần làm suy yếu trẻ. Nếu cần hồi sức, trẻ phải được sưởi ấm cho đến khi chuyển trẻ về phòng sơ sinh.\n5.2.3 Hỗ trợ hô hấp\nNếu trẻ không thở, kích thích trẻ bằng cách búng vào gan bàn chân hay xoa má, ngực, bụng, lưng đồng thời cho thở oxy 100% qua mặt nạ là đủ kích thích trẻ thở. Nếu hô hấp của trẻ không bắt đầu sau đẻ 30 giây, thì cho thở oxy qua mặt nạ, đủ để tạo sự di động của lồng ngực. Áp lực bóp bóng cho động tác thở đầu tiên là 30 - 35cmH2O. Đối với trẻ thiếu tháng, lúc đầu sử dụng áp lực cao hơn sau đó giảm dần để có được sự di động nhẹ nhàng của lồng ngực. Sự thông khí hỗ trợ cũng nên thực hiện khi nhịp tim của trẻ < 100 nhịp/phút. Sử dụng biện pháp thông khí với áp lực dương:\n- Thông khí bằng bóng ambu và mặt nạ (mask): dễ thực hiện và thường có hiệu quả.\n+ Để đầu trẻ hơi ngửa ra sau, mặt nạ được giữ bởi ngón cái và 2 ngón trỏ và giữa của bàn tay trái, đặt mặt nạ phủ kín lên miệng, mũi của bé; Hai ngón tay còn lại dùng để nâng cằm. Bóp bóng bằng bàn tay phải, cung cấp khí giàu oxy với tần số 40 lần/phút. Người thực hiện tốt nhất là đứng về phía đầu của bé.\n+ Hiệu quả của thông khí được đánh giá bằng cách quan sát cử động lồng ngực của trẻ và sự tăng nhịp tim.\n- Thông khí qua ống nội khí quản\n+ Chỉ định:\n*  Sau khi thông khí bằng bóng và mặt nạ thất bại.\n* Tắc nghẽn đường thở nghi ngờ do bướu giáp hoặc tật hàm nhỏ.\n*  Thông khí cho trẻ hít phải phân su sau khi đã hút sạch trong khí quản, thoát vị cơ hoành.\n* Phối hợp với bóp tim ngoài lồng ngực.\n\n\n\n\n\n\n\n\n\n\n\n\nHình 1. Đặt nội khí quản sơ sinh\n5.2.4 Bóp tim ngoài lồng ngực\nThực hiện khi vừa mới nghe được tim thai trước khi sinh nhưng không nghe được tiếng tim hoặc tim ngừng đập sau khi sinh, hoặc trong khoảng 30 giây từ khi bắt đầu thông khí mà nhịp tim không đạt trên 100 nhịp/phút.\nKỹ thuật: Dùng 2 ngón tay đặt trên thành ngực trước, tại vị trí 1/3 dưới đường giữa xương ức. Tần số bóp tim 100 - 120 lần/ phút, cứ 3 lần bóp tim xen kẽ một lần bóp bóng. Nếu trong vòng 30 giây thực hiện xoa bóp tim ngoài lồng ngực kết hợp với bóp bóng mà trẻ không đáp ứng tốt nên cho thuốc.\n\nHình 2.  Hai kỹ thuật ép tim ngoài lồng ngực\n\nA. Dùng 2 ngón tay cái      B. Dùng ngón trỏ và ngón giữa\n6. CÁC THUỐC SỬ DỤNG VÀ DỊCH TRUYỀN DÙNG CHO HỒI SỨC SƠ SINH\n6.1. Đường sử dụng\n- Đường tĩnh mạch ngoại biên: Không có sẵn từ phút đầu.\n- Đường tĩnh mạch rốn: Chích thuốc trực tiếp, nhanh nhưng có thể có tai biến thiếu máu cục bộ hay huyết khối tại động mạch hạ vị.\n- Đường nội khí quản: Một vài loại thuốc có thể qua đường nội khí quản nhanh chóng và có hiệu quả tương đương đường tĩnh mạch.\n6.2. Các loại thuốc thông thường\n6.2.1 Adrenalin\n- Chỉ định: Khi nhịp tim < 60 lần/ phút sau 30 giây thông khí và xoa bóp tim ngoài lồng ngực.\n- Liều 0,1ml 10/00 pha loãng với 0,9 ml NaCl 9 0/00 tiêm tĩnh mạch rốn hay đường nội khí quản.\n6.2.2 Bicarbonate Natri 4,2%\n- Liều 2 - 8 ml/kg tiêm tĩnh mạch  có thể lặp lại sau 10 phút.\n- Chỉ dùng trong trường hợp bị toan chuyển hóa, không có lợi trong trường hợp chỉ có toan hô hấp đơn thuần.\n- Chỉ định:\n+  Ngưng tim kéo dài\n+  Rối loạn hô hấp kéo dài > 10 phút\n+ Chú ý: Tiêm bicarbonat chậm vào tĩnh mạch thời gian tối thiểu là trên 2 phút.\n6.2.3 Glucose 10%\n- Liều 3-5ml/kg, không nên cho quá nhiều Glucose, vì trong điều kiện thiếu oxy Gluose sẽ chuyển hóa theo con đường yếm khí tạo ra rất ít năng lượng mà giải phóng nhiều acid lactic gây toan chuyển hóa.\n6.2.4. Naloxone\n- Chỉ định khi trẻ bị ức chế hô hấp do các thuốc thuộc nhóm morphine. Liều 0,1mg/kg, # 0,3mg cho một lần tiêm.\n- Cách pha: lấy 0,5 ml (1/2ống = 0,2mg) pha với 1,5 ml NaCl 9 0/00.\n- Dùng liều 0,1ml dung dịch pha/kg tĩnh mạch, tiêm bắp hay đường nội khí quản.\n- Có thể cho nhiều lần vì thời gian tác dụng của thuốc ngắn hơn so với các thuốc nhóm Morphin.\n6.2.5 Albumine 5%\n- Chỉ định khi giảm thể tích tuần hoàn.\n- Liều 10 - 20 ml/kg tiêm tĩnh mạch trên 15 phút.\n6.2.6. Isuprel\n- Nếu tim chậm kéo dài.\n- Liều 5 - 20 (g/kg/liều tiêm tĩnh mạch với tốc độ 0,1 - 1 (g/kg/phút.\n7. TIÊU CHUẨN ĐÁNH GIÁ HỒI SỨC\n- Lâm sàng:\n+Trẻ hết tím tái, hồng hào, khóc được\n+ Trẻ thở đều, thở sâu, tự thở\n+ Nhịp tim > 100 lần phút, đều rõ.\n+ Phản xạ tốt, trương lực cơ bình thường\n- Sinh hóa:  Ổn định được tình trạng toan hóa trong máu.\n+ pH > 7.3\n+ PaCO2 < 40mmHg\n+ PaO2 = 60 - 70mmHg\n\n8. CHĂM SÓC TRẺ SAU HỒI SỨC\nNhững trẻ được hồi sức có hiệu quả cần phải quan sát và theo dõi thêm sau đó. Các rối loạn bao gồm:\n8.1. Rối loạn chuyển hoá:\n- Tình trạng nhiễm toan.\n- Hạ đường huyết.\n- Hạ Calci huyết.\n- Hạ thân nhiệt.\nSơ đồ 1: Ảnh hưởng của hạ thân nhiệt đến hô hấp.\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n8.2. Di chứng ở hệ thần kinh trung ương\n- Phù não dẫn đến hôn mê hay co giật.\n- Xuất huyết não trước hết là xuất huyết trong não thất, có thể xảy ra ở trẻ thiếu tháng, tiên lượng xấu.\n8.3. Di chứng ở thận\n- Suy thận cấp: Hầu hết là do hoại tử ống thận cấp.\n- Hoại tử vỏ thận, huyết khối tĩnh mạch thận sẽ là nguyên nhân của suy thận sau ngạt.\n8.4. Di chứng ở tim\nỞ trẻ ngạt, tim là cơ quan bị ảnh hưởng nhiều nhất và có thể gây tổn thương nặng gây tử vong trẻ.\n8.5. Di chứng ở phổi\nCo thắt mạch ở phổi nên duy trì shunt phải - trái, máu qua ống động mạch hay lỗ bầu dục làm tồn tại tuần hoàn bào thai đưa đến tình trạng xanh tím nặng.\nPHÁC ĐỒ XỬ TRÍ HỒI SỨC SƠ SINH\nTRẺ SƠ SINH\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\nSơ đồ 2. Phác đồ xử trí trẻ ngạt ngay sau sinh\n\nCõu hỏi: 1.  Trình bầy các phương phỏp phải thực hiện để hồi sức sơ sịnh?\n2. Trình bầy các thuốc và dịch truyền để hồi sức sơ sịnh?\nCHƯƠNG 5. KẾ HOẠCH HÓA GIA ĐÌNH", "priority": "Cao (Trọng tâm BSNT)"}, {"id": "SK-50", "chapter": "Chương 5. Kế hoạch hóa gia đình", "folder": "05_Ke_hoach_hoa_gia_dinh", "title": "Các biện pháp tránh thai", "author": "Bs.CKII. Nguyễn Thị Tuyết", "word_count": 4425, "line_count": 228, "key_numbers": ["0,03mg", "0,125mg", "0,15mg", "0,5mg", "0,6mg", "0,75mg", "0.02mg", "1 giờ", "1 ngày", "1 tháng", "1 tuần", "10 ngày", "12 giờ", "12 tuần", "150mg", "16 ngày", "1mm", "2 cm", "2 ngày", "2 tuần", "200mg", "20mcg", "24 giờ", "3 ngày", "3 tháng", "314 mm", "33mm", "35 mcg", "36mg", "375mm", "380 mm", "4 tuần", "48 giờ", "5 ngày", "5 phút", "50mcg", "52 mg", "5mg", "6 tháng", "6 tuần", "68mg", "7 ngày", "72 giờ"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["CÁC BIỆN PHÁP TRÁNH THAI", "Bs.CKII.Nguyễn Thị Tuyết"], "bullets": []}, {"heading": "1. ĐẠI CƯƠNG", "paragraphs": ["Các biện pháp tránh thai là các biện pháp nhằm ngăn chặn sự thụ tinh và quá trình làm tổ. Nó có thể là một hàng rào cơ học hoặc hoá học ngăn cản sự thành lập giao tử, hoặc ngăn chặn sự làm tổ của trứng.", "Hiệu quả của các phương pháp tránh thai được tính theo chỉ số Pearl (P):", "Số trường hợp thất bại x 1000", "P =", "Tổng số vòng kinh được quan sát", "P: Số trường hợp thất bại có thai/ 100 phụ nữ sử dụng phương pháp tránh thai/ 1 năm", "Ngoài vấn đề hiệu quả tránh thai cao, các phương pháp tránh thai còn phải không ảnh hưởng đến người sử dụng và được chấp nhận sử dụng một cách rộng rãi."], "bullets": []}, {"heading": "2.1. Dụng cụ tử cung", "paragraphs": ["Dụng cụ tử cung (DCTC) đã được khẳng định là một phương pháp tránh thai cao, được công nhận để sử dụng rộng rãi. Cho đến nay DCTC là một trong những BPTT có hiệu quả cao và được sử dụng rộng rãi nhất."], "bullets": []}, {"heading": "2.1.1. Các loại dụng cụ tử cung", "paragraphs": ["DCTC được chia làm hai loại là vòng kín và vòng hở", "DCTC hở: (TCu, Multiload)", "DCTC kín: (Ota, Dana)", "Dụng cụ tử cung được làm bằng Polyethylene có Bari Sulfat để cản quang.", "Ở Việt nam loại được sử dụng rộng rãi là Multiload 375 (MLCu 375) với 2 cánh có thể gập vào thân, dây đồng 375mm và TCu 380A. hình chữ T với một dây đồng 314 mm quấn xung quanh thân T, 2 cánh ngang có 2 miếng đồng 33mm, chân T có dây không màu thắt nút tạo thành dây đôi.", "Hình 1. a. Hai loại vòng chữ T có đồng và không có đồng", "b. Vị trí đặt vòng trong tử cung", "Hình 2. Các loại dụng cụ tử cung"], "bullets": ["+ Chứa đồng", "+ Chứa thuốc", "- Hình dạng: DCTC có nhiều hình dạng khác nhau như: Vòng tròn (Ota), hình xoắn ốc (Margulies), hình chữ S (lippes, Dana), vòng chữ T (T, Tcu).", "- Kích cỡ: Một số dụng cụ tử cung có nhiều cỡ khác nhau.", "- Có 2 loại DCTC cơ bản: loại không có đồng hoặc tẩm thuốc (trơ) và loại có đồng hoặc tẩm thuốc. DCTC có đồng hoặc thuốc, để cho chất thuốc hoặc đồng phóng ra có tác dụng tránh thai cao hơn. Diện tích mặt đồng cuốn quanh DCTC có thể nhiều ít từ 120 - 380 mm. Diện tích đồng càng nhiều, tác dụng tránh thai càng cao. Loại có tẩm Levonorgestrel (Minera) chứa 52 mg Levonorgestrel giải phóng chậm 20mcg/ngày."]}, {"heading": "2.1.2. Cơ chế tác dụng", "paragraphs": ["Cơ chế tác dụng cơ bản của DCTC:"], "bullets": ["- Gây phản ứng viêm thứ phát tại niêm mạc tử cung, phá huỷ tinh trùng, ngăn cản sự làm tổ của noãn đã thụ tinh.", "- Làm đặc dịch nhầy ở cổ tử cung, cản trở sự di chuyển của tinh trùng (đối với dụng cụ có chứa nội tiết tố)."]}, {"heading": "2.1.3. Ưu điểm", "paragraphs": [], "bullets": ["- DCTC có hiệu quả tránh thai cao, đặc biệt loại Tcu 380A có tỷ lệ thất bại dưới 1%.", "- Dễ sử dụng, kinh tế, không ảnh hưởng đến sức khỏe, thời gian tránh thai lâu dài, chỉ đặt 1 lần tránh thai từ 10-12 năm (Tcu 380 A), dễ có thai sau khi tháo DCTC."]}, {"heading": "2.1.4. Chỉ định", "paragraphs": ["Chỉ định cho mọi đối tượng muốn tránh thai tạm thời hoặc lâu dài trong tuổi sinh đẻ (kể cả trong thời kỳ cho con bú).", "DCTC (loại chứa đồng) còn được dùng như một biện pháp tránh thai khẩn cấp."], "bullets": []}, {"heading": "2.1.5. Chống chỉ định", "paragraphs": [], "bullets": ["- Về phụ khoa: Rối loạn kinh nguyệt (rong kinh, rong huyết, đau bụng kinh), viêm nhiễm đường sinh dục trên, viêm âm đạo - cổ tử cung do vi khuẩn; nhiễm trùng hậu sản hoặc nhiễm trùng do nạo thai,  khối u lành tính hoặc ác tính ở cơ quan sinh dục, dị dạng tử cung.", "- Về sản khoa: đang có thai hoặc nghi ngờ có thai.", "- Các bệnh lý khác: viêm tắc tĩnh mạch sâu hoặc tắc mạch phổi, suy gan nặng hoặc các khối u gan (đối với DCTC chứa levonorgestrel)."]}, {"heading": "2.1.6. Thời điểm đặt DCTC", "paragraphs": ["Hình 3. Kỹ thuật đặt dụng cụ tử cung"], "bullets": ["- Thời điểm đặt DCTC thuận lợi nhất là sau khi sạch kinh 3 ngày vì thời điểm này ít có khả năng có thai, cổ tử cung mềm hơn và hé mở, có thể ít gây chảy máu. Tuy nhiên, có thể đặt DCTC bất kỳ ngày nào trong vòng kinh, khi đã chắc chắn người đó không có thai.", "- Sau đẻ: Có thể đặt sau 6 tuần (hết thời kỳ hậu sản). Phải chú ý là ở thời điểm này cơ tử cung rất mềm, dễ thủng tử cung. Ngoài ra cũng có thể đặt DCTC sau khi hút điều hoà kinh nguyệt hay sau khi nạo thai, nhưng với điều kiện chắc chắn là không sót rau và nhiễm khuẩn.", "- Đặt DCTC (loại chứa đồng) để tránh thai khẩn cấp: Cần đặt càng sớm càng tốt trong vòng 5 ngày sau khi giao hợp không được bảo vệ.", "- Sau khi đặt DCTC người phụ nữ cần kiêng giao hợp 1 tuần. Theo đúng lời hẹn khám lại của cán bộ y tế, thông thường khám lại vào các thời điểm:", "+ 1 tháng, 3 tháng sau khi đặt.", "+ 1 năm 1 lần đến kiểm tra lại.", "- Khi có các dấu hiệu bất thường như: người phụ nữ không sờ thấy dây của DCTC trong âm đạo của mình, chậm kinh (nghi có thai), rong huyết hoặc ra máu bất thường, đau bụng hoặc đau khi giao hợp, ra khí hư nhiều kèm theo sốt phải đi khám ngay tại các cơ sở y tế."]}, {"heading": "2.1.7.1. Tác dụng phụ có thể gặp", "paragraphs": ["Trường hợp sử dụng DCTC levonorgestrel có thể gặp hiện tượng ra máu thấm giọt nhẹ và không định kỳ trong 4-6 tháng, sau đó trở lại bình thường và lượng máu kinh có thể ít hơn."], "bullets": ["- Đau bụng: Người phụ nữ có thể cảm thấy đau thắt vài ngày sau khi đặt DCTC. Với loại chứa đồng nhiều phụ nữ có cảm giác đau bụng kinh nhiều hơn.", "- Ra máu: Ra máu ngay sau khi đặt DCTC hoặc đến kỳ kinh máu ra nhiều hơn thường lệ. Ra máu thường xảy ra trong 2 - 3 tháng đầu sau khi đặt, nếu quá 3 tháng triệu chứng chảy máu không giảm phải đến khám lại."]}, {"heading": "2.1.7.2. Biến chứng có thể gặp", "paragraphs": ["Một số biến chứng có thể gặp là thủng tử cung, nhiễm trùng, chảy máu nhiều, đau tiểu khung, thống kinh, DCTC chui vào ổ bụng và có thể có thai."], "bullets": []}, {"heading": "2.2. Thuốc tránh thai", "paragraphs": ["Từ năm 1950, sự xuất hiện thuốc tránh thai uống (Pincus) là một phát minh lớn. Đây là phương pháp tránh thai tạm thời, có hiệu quả cao. Cùng với phương pháp DCTC nó góp phần đáng kể làm giảm tỷ lệ phát triển dân số toàn cầu, và qua đó đã giảm tỷ lệ bệnh lý, tử vong các bà mẹ, các cặp vợ chồng đã chủ động được khoảng cách lần sinh con. Ở Việt Nam, từ thập kỷ 60 TTTU cũng đã được biết đến, nhưng trong vài năm gần đây TTTU mới được sử dụng một cách rộng rãi."], "bullets": []}, {"heading": "2.2.1.1. Viên thuốc tránh thai kết hợp (VKH)", "paragraphs": ["Progestin là thành phần tránh thai chủ yếu, tuy nhiên trong cơ chế tránh thai, estrogen và progestin đều có tác dụng đồng vận lên tuyến yên. Estrogen là thành phần nhằm giải quyết chảy máu thấm giọt do progestin đơn thuần gây ra, nhưng tác dụng phụ, tai biến của TTTU thường do estrogen gây ra.", "Liều của E.E là 50mcg cho loại viên cổ điển, 20 -35 mcg cho loại viên liều thấp. Tỷ lệ thất bại của VKH dao động từ 0,1% tới 5% chủ yếu do dùng không đúng.", "Trong các chương trình KHHGĐ, hiện nay thường sử dụng loại thuốc tránh thai viên kết hợp 1 giai đoạn: liều Progestin phối hợp kéo dài suốt vòng kinh:", "Loại 1 giai đoạn:", "Loại 2 giai đoạn: Liều progestatif tăng ở 10 ngày sau của vòng kinh (Gynophase, Adepal, miniphase)", "Loại 3 giai đoạn: Viên 3 pha cho phép giảm tổng liều steroid nhưng hiệu quả tránh thai không thay đổi (Tri-Regol, Tri-Mihulet, Tri-nordiol).", "Thuốc được đóng vỉ 21 viên hoặc vỉ 28 viên (trong đó có 21 viên có thành phần thuốc và 7 viên đệm không chứa thuốc tránh thai).", "Hình 4. Thành phần thuốc tránh thai", "Chỉ định: Tất cả phụ nữ muốn sử dụng một biện pháp tránh thai tạm thời, hiệu quả cao và không có chống chỉ định.", "Chống chỉ định:", "Các tác dụng phụ này thường chỉ xuất hiện trong thời gian đầu dùng thuốc."], "bullets": ["-  Thành phần: Viên thuốc tránh thai kết hợp gồm 2 thành phần là:", "+ Estrogen tổng hợp: Ethinyl-estradiol (E.E).", "+Progestin tổng hợp: 17 hydroxyprogosteron hoặc 19-nortestosteron. Xu hướng hiện nay sử dụng progestatif thuộc thế hệ 3 ít gây tác dụng không mong muốn.", "-  Cách trình bày của thuốc", "+ Microgynon, New choice, Ideal (Levonorgestrel 0,15mg, EE 0,03mg).", "+ Rigevidon (desonorgestrel 0,15mg, EE 0,03mg).", "+ Marvelon (desogestrel 0,15mg, EE 0,03mg).", "+ Mercilon (desogestrel 0,15mg, EE 0.02mg).", "- Cơ chế tránh thai", "+ Ức chế phóng noãn do ức chế giải phóng FSH, LH từ trục dưới đồi - tuyến yên.", "+ Cản trở sự làm tổ của trứng do biến đổi nội mạc tử cung không phù hợp.", "+ Ngăn cản sự di chuyển của tinh trùng do chất nhầy cổ tử cung đặc lại.", "- Chỉ định và chống chỉ định", "+ Có thai hoặc nghi ngờ có thai.", "+ Đang cho con bú và dưới 6 tuần sau sinh", "+ Ra máu âm đạo bất thường chưa rõ nguyên nhân.", "+ Đang theo dõi các loại khối u.", "+ Phụ nữ trên 35 tuổi hút thuốc lá.", "+ Các bệnh lý nội khoa như cao huyết áp, đái tháo đường, bệnh gan, thận...", "+ Điều trị với các thuốc chống co giật như Phenyltoin, Carbamazepin, Barbiturat hoặc kháng sinh như Griseofulvin, Rifampicin.", "- Tác dụng phụ", "+ Ra huyết thấm giọt thường hay gặp ở 2-3 chu kỳ kinh nguyệt đầu tiên ngay sau khi dùng thuốc.", "+ Cương vú, đau vùng tiểu khung (kiểu giả có thai).", "+ Nhức đầu, thay đổi tâm lý, ham muốn tình dục.", "+ Tăng cân nhẹ do giữ muối, giữ nước.", "- Cách sử dụng", "+ Bắt đầu uống viên thứ nhất từ ngày 1 đến ngày 5 của vòng kinh, uống mỗi ngày một viên vào một giờ nhất định theo chiều mũi tên trên vỉ thuốc. Với vỉ 28 viên, khi hết vỉ thì uống viên đầu tiên của vỉ tiếp theo vào ngày hôm sau dù đang còn kinh. Với vỉ 21 viên khi hết vỉ nghỉ 7 ngày rồi dùng tiếp vỉ sau.", "+ Sau đẻ không cho con bú: uống từ tuần thứ tư sau đẻ.", "+ Sau nạo, sau sẩy thai, có thể bắt đầu sớm trong vòng 5 ngày đầu sau nạo.", "+ Xử trí khi quên thuốc: Nếu quên thuốc 1 viên thì uống ngay khi nhớ ra và tiếp tục như bình thường. Nếu quên thuốc 2 viên liên tiếp thì phải uống mỗi ngày 2 viên trong hai ngày sau đó. Đồng thời dùng thêm biện pháp tránh thai hỗ trợ cho đến khi hết vỉ thuốc. Nếu quên từ 3 viên trở lên, bỏ vỉ thuốc và bắt đầu dùng vỉ mới. Dùng biện pháp hỗ trợ trong 7 ngày đầu tiên. Hàng năm, người phụ nữ cần phải đi khám kiểm tra 1 lần hoặc khi có dấu hiệu bất thường"]}, {"heading": "2.2.1.2. Viên tránh thai đơn thuần", "paragraphs": ["Viên thuốc tránh thai đơn thuần chỉ có Progestin, không có Estrogen. Ngoài tác dụng ngừa thai, còn thường được sử dụng với mục đích điều trị. Có 2 loại:", "Viên tránh thai progestin liều thấp hay được sử dụng là EXLUTON (lynestrenol 0,5mg), vỉ 28 viên. Ngoài ra còn có thể gặp ở thị trường: Microval (Levonorgestrel 0,03mg), Milligynon (Norethisterone Acetate, 0,6mg). Ogyline (norgestrienone).", "Làm đặc chất nhầy cổ tử cung, ngăn cản tinh trùng xâm nhập lên đường sinh dục trên. Làm teo nội mạc tử cung, giảm khả năng làm tổ.", "Các chế phẩm có thể là: Norluten (Noréthisterone 5mg), Orgametril (Lynestrenol 5mg). Một số thuốc có dẫn xuất từ progesteron như Lutenyl (Nomegestrol 5mg), Luteran (Chlomadinon 5mg), Surgestone (Promegeston 0,125mg) ít gây nam tính hoá khi sử dụng dài ngày. Các viên progestin liều cao ít sử dụng vì mục đích tránh thai và thường dùng trong điều trị."], "bullets": ["- Progestin liều thấp, liên tục (microprogestatif)", "+ Thành phần, cách trình bày của thuốc:", "+ Cơ chế tránh thai:", "+ Hiệu quả tránh thai cao đạt đến 97%.", "- Viên Progestin liều cao (macroprogestatif)"]}, {"heading": "2.2.1.3. Viên tránh thai khẩn cấp", "paragraphs": ["Viên tránh thai khẩn cấp còn gọi là viên thuốc tránh thai sáng hôm sau.", "Viên thuốc tránh thai kết hợp (Ideal, Choice, New choice, Tetragynon): Uống 4 viên thuốc tránh thai kết hợp trong vòng 72 giờ sau giao hợp, 12 giờ sau đó  uống tiếp 4 viên.", "Tác dụng phụ thường gặp triệu chứng chóng mặt, buồn nôn và nôn sau khi dùng viên tránh thai khẩn cấp."], "bullets": ["- Cơ chế tác dụng: làm niêm mạc tử cung phát triển không thuận lợi cho sự làm tổ.", "- Chỉ định: Trường hợp giao hợp không được bảo vệ, bị cưỡng dâm.", "- Cách sử dụng: viên tránh thai khẩn cấp chỉ có Progestin đơn thuần: Loại thường được sử dụng là Postinor (Levorgestrel 0,75mg) Viên đầu tiên uống càng sớm càng tốt trong vòng 72 giờ sau giao hợp không được bảo vệ, viên thứ hai uống sau viên thứ nhất 12 giờ."]}, {"heading": "2.2.2. Thuốc tiêm tránh thai", "paragraphs": ["Thuốc tiêm tránh thai DMPA là loại hormon progestin có tác dụng tránh thai 1 tháng hay 3 tháng.", "Cơ chế tác dụng: Thuốc tiêm DMPA liên tục ức chế phóng noãn, làm niêm mạc tử cung mỏng và làm đặc chất nhầy cổ tử cung.", "Chỉ định cho những người phụ nữ muốn dùng biện pháp tránh thai dài hạn, có hồi phục, hiệu quả cao mà không phải dùng thuốc hàng ngày. Ưu điểm: Hiệu quả cao, có tác dụng lâu dài, chỉ cần tiêm một lần cho 4 tuần, 12 tuần.", "Có thể hồi phục lại khả năng sinh sản. Không ảnh hưởng nhiều đến tim mạch, thích hợp cho phụ nữ trên 35 tuổi phải đề phòng với estrogen. Có thể dùng cho phụ nữ cho con bú, không ảnh hưởng đến giao hợp, dễ sử dụng.", "Tác dụng phụ: ra huyết thấm giọt, rong kinh giữa kỳ, vô kinh, tăng cân nhẹ. Việc sử dụng kéo dài thường đi kèm với việc giảm mật độ khoáng trong xương và sẽ trở lại bình thường sau khi ngừng sử dụng thuốc.", "Chống chỉ định: dưới 6 tuần sau sinh; Nhiều yếu tố nguy cơ bệnh tim mạch; Huyết áp cao không kiểm soát; Bệnh mạch; đang bị viêm tắc tĩnh mạch sâu; có tiền sử hoặc đang bị bệnh tim do thiếu máu; tiền sử đột quị; có tiền sử hoặc đang mắc ung thư vú; tiểu đường phụ thuộc insulin với những thay đổi mạch hoặc diễn biến bệnh trên 20 năm; đang bị viêm gan do virus, xơ gan nặng, các khối u gan.", "Nhược điểm: Vì thuốc có tác dụng kéo dài nên không thể ngưng tác dụng ngay hoặc lấy ra khỏi cơ thể khi có tai biến xảy ra hoặc muốn có thai trở lại.", "Tỷ lệ thất bại là 0,3%", "Thời điểm tiêm, liều lượng: Mũi tiêm có thể thực hiện vào bất cứ lúc nào trong chu kỳ kinh nguyệt với điều kiện là chắc chắn không có thai. Tốt nhất là trong vòng 7 ngày đầu của kỳ kinh hoặc sau nạo hút. Nếu cho con bú thì tiêm 6 tuần sau đẻ.", "Chế độ chuẩn là cứ 12 tuần dùng một liều 150mg DMPA, tiêm bắp sâu. Có thể sớm hoặc muộn hơn 2 tuần vẫn có tác dụng."], "bullets": ["- Depo-provera (medroxyprogesterone acetate) chế phẩm của progesteron tự nhiên được pha chế trong dung dịch nhũ tương tinh thể nhỏ do đó được hấp thu chậm.", "- Noristerat (noréthisterone) 200mg."]}, {"heading": "2.2.3. Thuốc cấy tránh thai", "paragraphs": ["Thuốc cấy tránh thai hiện nay có 2 loại:", "Nơi cấy: mặt trong cánh tay không thuận(thường là tay trái), cấy nông dưới da.", "Noplant cấy 6 nang hình nan quạt.", "Implanon cấy ở khoảng giữa mặt trong cánh tay. Тác dụng phụ chủ yếu là ra máu âm đạo thấm giọt.", "Hình 5. Cấu trúc của que cấy Implanon", "Hình 6. Kỹ thuật cấy Implanon"], "bullets": ["- Norplant: Loại này có 6 nang mềm, vỏ bằng chất dẻo sinh học, mỗi nang chứa 36mg Levonorgestrel. Hormon này thấm qua thành nang vào máu một cách liên tục đảm bảo tác dụng tránh thai kéo dài 5 năm. Tỷ lệ thất bại là 0,2%.", "- Implanon: Chỉ có một nang chứa 68mg Etonogestrel và có tác dụng 3 năm."]}, {"heading": "2.2.4. Thuốc diệt tinh trùng", "paragraphs": ["Là những loại chất có tác dụng hoá học để diệt hoặc làm mất khả năng di chuyển của tinh trùng. Ngoài ra nó có tác dụng như một dung môi tạo nên màng chắn, hoặc tạo bọt nhằm đẩy tinh trùng ra xa cổ tử cung.", "Các chất thường dùng: acid lactic, nicoceptin, nonoxynol 9, Chlorure benzalkonium (Pharmatex). Thuốc phải đảm bảo diệt tinh trùng nhanh, không gây cảm giác khó chịu, không làm giảm khoái cảm. Thuốc được sản xuất dưới dạng kem, nhũ tương, viên đạn, viên sủi bọt, loại khí dung sủi bọt để đặt vào âm đạo.", "Trước khi giao hợp 5 phút đặt hoặc bơm thuốc vào âm đạo, thuốc chỉ tác dụng trong vòng 1 giờ. Nhược điểm là gây nóng âm đạo, mỗi lần giao hợp phải đặt thuốc lại.", "Tỷ lệ thất bại khoảng 10%. Nên kết hợp thuốc diệt tinh trùng với một trong các tránh thai khác kết quả tránh thai sẽ cao hơn.", "Hình 7. Thuốc diệt tinh trùng"], "bullets": []}, {"heading": "3. CÁC PHƯƠNG PHÁP TRÁNH THAI TRUYỀN THỐNG", "paragraphs": ["Là những phương pháp tránh thai đơn giản, dễ áp dụng, có tác dụng tránh thai ngắn hạn. Đây là những phương pháp được sử dụng từ lâu và có tác dụng nhất định trong việc hạn chế phát triển dân số."], "bullets": []}, {"heading": "3.1.1. Phương pháp sử dụng bao cao su", "paragraphs": ["Bao cao su ngăn không cho tinh dịch vào âm đạo. Bao được làm bằng cao su latex rất mỏng có hoặc không phủ lớp diệt tinh trùng. Ngoài tác dụng tránh thai cao bao cao su còn có tác dụng phòng các bệnh lây truyền theo đường tình dục, đặc biệt là HIV/AIDS đang có nguy cơ lan tràn khắp thế giới.", "Chỉ định: Tất cả mọi người muốn tránh thai tạm thời mà không muốn dùng các biện pháp khác hoặc muốn phòng chống các bệnh lây truyền qua đường sinh dục, trừ trường hợp bị dị ứng với chất cao su khi dùng. Tỷ lệ thất bại: 14%."], "bullets": []}, {"heading": "3.1.2. Phương pháp xuất tinh ra ngoài âm đạo", "paragraphs": ["Xuất tinh ra ngoài âm đạo để không cho tinh trùng vào trong âm đạo để gặp trứng thụ tinh do đó còn gọi là phương pháp giao hợp ngắt quãng. Hiện nay nhiều cặp vợ chồng sử dụng phương pháp này.Tỷ lệ thất bại khá cao, khoảng 24%.", "Hình 8. Hướng dẫn mang bao cao su cho nam giới"], "bullets": []}, {"heading": "3.2.1. Phương pháp Ogino-Knauss", "paragraphs": ["Phương pháp Ogino-Knauss là phương pháp tránh thai cổ điển và hiện nay vẫn là một trong những phương pháp được quan tâm.", "Phương pháp dựa vào hiện tượng phóng noãn bao giờ cũng xảy ra ở thời gian cố định từ 12 - 16 ngày trước kỳ kinh tới. Ước tính thời gian có thể thụ tinh của noãn khoảng 10 - 24 giờ, thời gian thụ tinh của tinh trùng trong đường sinh dục nữ là 48 giờ. Vì vậy muốn tránh thai thì cần tránh giao hợp trước khi dự kiến có phóng noãn 2 ngày và sau phóng noãn 1 ngày.", "Ogino-Knauss là phương pháp tránh thai tự nhiên bằng cách tránh giao hợp vào thời kỳ rụng trứng. Hiệu quả của phương pháp này tuỳ thuộc theo từng người và mức độ theo dõi để xác định thời kỳ rụng trứng có chính xác hay không. Ngoài ra phương pháp này có đặc điểm là khó áp dụng đối với những phụ nữ không có thói quen theo dõi kinh nguyệt một cách đều đặn, ở người đang cho con bú, vô kinh. Tỷ lệ thất bại dao động từ 2-21%.", "Hình 9. Phương pháp Ogino-Knauss"], "bullets": ["- Cơ chế tác dụng"]}, {"heading": "3.2.2. Biện pháp cho bú vô kinh", "paragraphs": ["Có thể áp dụng ở những phụ nữ cho con bú hoàn toàn, chưa có kinh trở lại và con dưới 6 tháng tuổi. Hiệu quả tránh thai có thể tới 98%.", "Biện pháp dựa trên cơ sở trẻ bú mẹ tác động lên vùng dưới đồi, ảnh hưởng đến mức độ và nhịp điệu của sự tiết các hormon giải phóng, ức chế sự phóng noãn.", "Đây là phương pháp tránh thai rất được khuyến khích ở các nước đang phát triển."], "bullets": []}, {"heading": "3.2.3. Mũ cổ tử cung, màng ngăn âm đạo", "paragraphs": ["Dụng cụ làm bằng kim khí hoặc chất dẻo để ngăn cản không cho tinh trùng vào tử cung. Tỷ lệ thất bại của màng ngăn âm đạo, mũ cổ tử cung gần 20% cho mỗi loại. Các phương pháp này hiện nay rất ít được sử dụng.", "Hình 10. Mũ cổ tử cung", "Hình 11. Màng ngăn âm đạo"], "bullets": []}, {"heading": "4. PHƯƠNG PHÁP ĐÌNH SẢN TỰ NGUYỆN", "paragraphs": ["Đình sản là biện pháp hiệu quả cao, đơn giản và có thể hồi phục bằng can thiệp phẫu thuật."], "bullets": []}, {"heading": "4.1. Đình sản nữ", "paragraphs": ["Là phương pháp làm tắc vòi tử cung, ngăn cản vĩnh viễn không cho tinh trùng và trứng gặp nhau để thụ tinh."], "bullets": []}, {"heading": "4.1.1. Chỉ định và chống chỉ định", "paragraphs": ["Tất cả phụ nữ tự nguyện áp dụng."], "bullets": []}, {"heading": "4.1.2. Ưu, nhược điểm của phương pháp đình sản nữ", "paragraphs": ["Hiệu quả tránh thai có thể đạt đến 100% nếu như cắt và thắt đúng phương pháp, không ảnh hưởng đến kinh nguyệt, sức khoẻ, tâm sinh lý và hoạt động tình dục."], "bullets": []}, {"heading": "4.1.3. Thực hiện phương pháp đình sản nữ", "paragraphs": ["Hình 12. Đình sản nữ"], "bullets": ["- Thời điểm:", "+ Sau khi đẻ: Tiến hành từ 24 đến 48 giờ là dễ thực hiện nhất", "+ Sau nạo, sau sẩy thai.", "+ Kết hợp đình sản trong mổ lấy thai, phẫu thuật phụ khoa.", "- Kỹ thuật: Đình sản là một loại phẫu thuật nhỏ, chỉ cần rạch thành bụng khoảng 2 cm để cặp 2 vòi trứng lên thắt và cắt. Ngoài ra có thể đình sản nữ qua nội soi bằng ống soi, ống soi được đưa qua một điểm cắt nhỏ vào ổ bụng, sau đó là thủ thuật đốt điện vòi trứng. Phương pháp này đòi hỏi các trang thiết bị đắt tiền và phức tạp, đồng thời cũng không dễ thực hiện."]}, {"heading": "4.2. Đình sản nam", "paragraphs": ["Thắt ống dẫn tinh là một trong những biện pháp tránh thai ít phổ biến hiện nay trên toàn thế giới. Tuy nhiên đây là một trong những biện pháp có hiệu quả, an toàn, đơn giản và tiện lợi."], "bullets": []}, {"heading": "4.2.1. Cơ chế tác dụng", "paragraphs": ["Phương pháp thắt và cắt ống dẫn tinh làm cho tinh trùng không thể di chuyển từ tinh hoàn và mào tinh đi qua ống dẫn tinh và phóng vào âm đạo khi xuất tinh để gặp trứng.", "Sau khi thắt ống dẫn tinh, tinh hoàn vẫn hoạt động bình thường, tinh trùng vẫn được sản xuất, các hormon vẫn bình thường nên không ảnh hưởng đến giới tính và hoạt động sinh dục."], "bullets": []}, {"heading": "4.2.2. Chỉ định", "paragraphs": ["Nam giới tự nguyện áp dụng."], "bullets": []}, {"heading": "4.2.3. Kỹ thuật", "paragraphs": ["Kỹ thuật không dùng dao mổ đang trở thành biện pháp phổ biến. Với kỹ thuật này chỉ cần châm một vết nhỏ 1mm vào da bìu bằng kẹp, mở rộng ra để định vị và tách và thắt các ống dẫn tinh."], "bullets": []}, {"heading": "4.2.4. Theo dõi", "paragraphs": ["Phương pháp thắt ống dẫn tinh đạt hiệu quả 99 - 99,5%, tỷ lệ thất bại do giao hợp không được bảo vệ ngay sau khi tiến hành thủ thuật. Do đó nên tránh giao hợp trong 2-3 ngày và dùng bao cao su trong 20 lần xuất tinh sau khi đã cắt, thắt ống dẫn tinh. Nếu có điều kiện trước khi giao hợp bình thường nên đến bệnh viện thử lại tinh trùng, nếu còn tinh trùng thì phải tiếp tục dùng bao cao su hoặc phương pháp khác.", "Hình 13. Đình sản nam"], "bullets": []}, {"heading": "Câu hỏi:", "paragraphs": ["1: Kể tên các biện pháp tránh thai tạm thời hiện đang áp dụng ở Việt Nam, ưu và nhược điểm?", "2: Trình bày chỉ định, chống chỉ định đặt dụng cụ tử cung, bao cao su và viên thuốc tránh thai khẩn cấp?", "3: Trình bày chỉ định, chống chỉ định sử dụng viên thuốc tránh thai kết hợp và đơn thuần?", "4: Trình bày chỉ định, chống chỉ định của thuốc tiêm và thuốc cấy tránh thai?"], "bullets": []}, {"heading": "5. Trình bày chỉ định, chống chỉ định, kỹ thuật của biện phỏp triệt sản nam và nữ?", "paragraphs": ["CHƯƠNG 6. HỖ TRỢ SINH SẢN – SỨC KHỎE SINH SẢN"], "bullets": []}], "raw_text": "CÁC BIỆN PHÁP TRÁNH THAI\nBs.CKII.Nguyễn Thị Tuyết\nMục tiêu học tập\n1. Liệt kê được các biện pháp tránh thai.\n2. Xác định được chỉ định và chống chỉ định của từng phương pháp.\n3. Trình bày được cách phát hiện và xử trí các tác dụng phụ và biến chứng của từng phương pháp.\n1. ĐẠI CƯƠNG\nCác biện pháp tránh thai là các biện pháp nhằm ngăn chặn sự thụ tinh và quá trình làm tổ. Nó có thể là một hàng rào cơ học hoặc hoá học ngăn cản sự thành lập giao tử, hoặc ngăn chặn sự làm tổ của trứng.\nHiệu quả của các phương pháp tránh thai được tính theo chỉ số Pearl (P):\nSố trường hợp thất bại x 1000\nP =\nTổng số vòng kinh được quan sát\nP: Số trường hợp thất bại có thai/ 100 phụ nữ sử dụng phương pháp tránh thai/ 1 năm\nNgoài vấn đề hiệu quả tránh thai cao, các phương pháp tránh thai còn phải không ảnh hưởng đến người sử dụng và được chấp nhận sử dụng một cách rộng rãi.\n2. CÁC BIỆN PHÁP TRÁNH THAI\n2.1. Dụng cụ tử cung\nDụng cụ tử cung (DCTC) đã được khẳng định là một phương pháp tránh thai cao, được công nhận để sử dụng rộng rãi. Cho đến nay DCTC là một trong những BPTT có hiệu quả cao và được sử dụng rộng rãi nhất.\n2.1.1. Các loại dụng cụ tử cung\nDCTC được chia làm hai loại là vòng kín và vòng hở\nDCTC hở: (TCu, Multiload)\nDCTC kín: (Ota, Dana)\n+ Chứa đồng\n+ Chứa thuốc\nDụng cụ tử cung được làm bằng Polyethylene có Bari Sulfat để cản quang.\n- Hình dạng: DCTC có nhiều hình dạng khác nhau như: Vòng tròn (Ota), hình xoắn ốc (Margulies), hình chữ S (lippes, Dana), vòng chữ T (T, Tcu).\n- Kích cỡ: Một số dụng cụ tử cung có nhiều cỡ khác nhau.\n- Có 2 loại DCTC cơ bản: loại không có đồng hoặc tẩm thuốc (trơ) và loại có đồng hoặc tẩm thuốc. DCTC có đồng hoặc thuốc, để cho chất thuốc hoặc đồng phóng ra có tác dụng tránh thai cao hơn. Diện tích mặt đồng cuốn quanh DCTC có thể nhiều ít từ 120 - 380 mm. Diện tích đồng càng nhiều, tác dụng tránh thai càng cao. Loại có tẩm Levonorgestrel (Minera) chứa 52 mg Levonorgestrel giải phóng chậm 20mcg/ngày.\nỞ Việt nam loại được sử dụng rộng rãi là Multiload 375 (MLCu 375) với 2 cánh có thể gập vào thân, dây đồng 375mm và TCu 380A. hình chữ T với một dây đồng 314 mm quấn xung quanh thân T, 2 cánh ngang có 2 miếng đồng 33mm, chân T có dây không màu thắt nút tạo thành dây đôi.\n\nHình 1. a. Hai loại vòng chữ T có đồng và không có đồng\nb. Vị trí đặt vòng trong tử cung\n\n\nHình 2. Các loại dụng cụ tử cung\n2.1.2. Cơ chế tác dụng\nCơ chế tác dụng cơ bản của DCTC:\n- Gây phản ứng viêm thứ phát tại niêm mạc tử cung, phá huỷ tinh trùng, ngăn cản sự làm tổ của noãn đã thụ tinh.\n- Làm đặc dịch nhầy ở cổ tử cung, cản trở sự di chuyển của tinh trùng (đối với dụng cụ có chứa nội tiết tố).\n2.1.3. Ưu điểm\n- DCTC có hiệu quả tránh thai cao, đặc biệt loại Tcu 380A có tỷ lệ thất bại dưới 1%.\n- Dễ sử dụng, kinh tế, không ảnh hưởng đến sức khỏe, thời gian tránh thai lâu dài, chỉ đặt 1 lần tránh thai từ 10-12 năm (Tcu 380 A), dễ có thai sau khi tháo DCTC.\n2.1.4. Chỉ định\nChỉ định cho mọi đối tượng muốn tránh thai tạm thời hoặc lâu dài trong tuổi sinh đẻ (kể cả trong thời kỳ cho con bú).\nDCTC (loại chứa đồng) còn được dùng như một biện pháp tránh thai khẩn cấp.\n2.1.5. Chống chỉ định\n- Về phụ khoa: Rối loạn kinh nguyệt (rong kinh, rong huyết, đau bụng kinh), viêm nhiễm đường sinh dục trên, viêm âm đạo - cổ tử cung do vi khuẩn; nhiễm trùng hậu sản hoặc nhiễm trùng do nạo thai,  khối u lành tính hoặc ác tính ở cơ quan sinh dục, dị dạng tử cung.\n- Về sản khoa: đang có thai hoặc nghi ngờ có thai.\n- Các bệnh lý khác: viêm tắc tĩnh mạch sâu hoặc tắc mạch phổi, suy gan nặng hoặc các khối u gan (đối với DCTC chứa levonorgestrel).\n2.1.6. Thời điểm đặt DCTC\n- Thời điểm đặt DCTC thuận lợi nhất là sau khi sạch kinh 3 ngày vì thời điểm này ít có khả năng có thai, cổ tử cung mềm hơn và hé mở, có thể ít gây chảy máu. Tuy nhiên, có thể đặt DCTC bất kỳ ngày nào trong vòng kinh, khi đã chắc chắn người đó không có thai.\n- Sau đẻ: Có thể đặt sau 6 tuần (hết thời kỳ hậu sản). Phải chú ý là ở thời điểm này cơ tử cung rất mềm, dễ thủng tử cung. Ngoài ra cũng có thể đặt DCTC sau khi hút điều hoà kinh nguyệt hay sau khi nạo thai, nhưng với điều kiện chắc chắn là không sót rau và nhiễm khuẩn.\n- Đặt DCTC (loại chứa đồng) để tránh thai khẩn cấp: Cần đặt càng sớm càng tốt trong vòng 5 ngày sau khi giao hợp không được bảo vệ.\n- Sau khi đặt DCTC người phụ nữ cần kiêng giao hợp 1 tuần. Theo đúng lời hẹn khám lại của cán bộ y tế, thông thường khám lại vào các thời điểm:\n+ 1 tháng, 3 tháng sau khi đặt.\n+ 1 năm 1 lần đến kiểm tra lại.\n- Khi có các dấu hiệu bất thường như: người phụ nữ không sờ thấy dây của DCTC trong âm đạo của mình, chậm kinh (nghi có thai), rong huyết hoặc ra máu bất thường, đau bụng hoặc đau khi giao hợp, ra khí hư nhiều kèm theo sốt phải đi khám ngay tại các cơ sở y tế.\n\nHình 3. Kỹ thuật đặt dụng cụ tử cung\n\n2.1.7. Tác dụng phụ và biến chứng\n2.1.7.1. Tác dụng phụ có thể gặp\n- Đau bụng: Người phụ nữ có thể cảm thấy đau thắt vài ngày sau khi đặt DCTC. Với loại chứa đồng nhiều phụ nữ có cảm giác đau bụng kinh nhiều hơn.\n- Ra máu: Ra máu ngay sau khi đặt DCTC hoặc đến kỳ kinh máu ra nhiều hơn thường lệ. Ra máu thường xảy ra trong 2 - 3 tháng đầu sau khi đặt, nếu quá 3 tháng triệu chứng chảy máu không giảm phải đến khám lại.\nTrường hợp sử dụng DCTC levonorgestrel có thể gặp hiện tượng ra máu thấm giọt nhẹ và không định kỳ trong 4-6 tháng, sau đó trở lại bình thường và lượng máu kinh có thể ít hơn.\n2.1.7.2. Biến chứng có thể gặp\nMột số biến chứng có thể gặp là thủng tử cung, nhiễm trùng, chảy máu nhiều, đau tiểu khung, thống kinh, DCTC chui vào ổ bụng và có thể có thai.\n2.2. Thuốc tránh thai\nTừ năm 1950, sự xuất hiện thuốc tránh thai uống (Pincus) là một phát minh lớn. Đây là phương pháp tránh thai tạm thời, có hiệu quả cao. Cùng với phương pháp DCTC nó góp phần đáng kể làm giảm tỷ lệ phát triển dân số toàn cầu, và qua đó đã giảm tỷ lệ bệnh lý, tử vong các bà mẹ, các cặp vợ chồng đã chủ động được khoảng cách lần sinh con. Ở Việt Nam, từ thập kỷ 60 TTTU cũng đã được biết đến, nhưng trong vài năm gần đây TTTU mới được sử dụng một cách rộng rãi.\n2.2.1. Các loại thuốc viên tránh thai\n2.2.1.1. Viên thuốc tránh thai kết hợp (VKH)\n-  Thành phần: Viên thuốc tránh thai kết hợp gồm 2 thành phần là:\n+ Estrogen tổng hợp: Ethinyl-estradiol (E.E).\n+Progestin tổng hợp: 17 hydroxyprogosteron hoặc 19-nortestosteron. Xu hướng hiện nay sử dụng progestatif thuộc thế hệ 3 ít gây tác dụng không mong muốn.\nProgestin là thành phần tránh thai chủ yếu, tuy nhiên trong cơ chế tránh thai, estrogen và progestin đều có tác dụng đồng vận lên tuyến yên. Estrogen là thành phần nhằm giải quyết chảy máu thấm giọt do progestin đơn thuần gây ra, nhưng tác dụng phụ, tai biến của TTTU thường do estrogen gây ra.\nLiều của E.E là 50mcg cho loại viên cổ điển, 20 -35 mcg cho loại viên liều thấp. Tỷ lệ thất bại của VKH dao động từ 0,1% tới 5% chủ yếu do dùng không đúng.\n-  Cách trình bày của thuốc\nTrong các chương trình KHHGĐ, hiện nay thường sử dụng loại thuốc tránh thai viên kết hợp 1 giai đoạn: liều Progestin phối hợp kéo dài suốt vòng kinh:\nLoại 1 giai đoạn:\n+ Microgynon, New choice, Ideal (Levonorgestrel 0,15mg, EE 0,03mg).\n+ Rigevidon (desonorgestrel 0,15mg, EE 0,03mg).\n+ Marvelon (desogestrel 0,15mg, EE 0,03mg).\n+ Mercilon (desogestrel 0,15mg, EE 0.02mg).\nLoại 2 giai đoạn: Liều progestatif tăng ở 10 ngày sau của vòng kinh (Gynophase, Adepal, miniphase)\nLoại 3 giai đoạn: Viên 3 pha cho phép giảm tổng liều steroid nhưng hiệu quả tránh thai không thay đổi (Tri-Regol, Tri-Mihulet, Tri-nordiol).\nThuốc được đóng vỉ 21 viên hoặc vỉ 28 viên (trong đó có 21 viên có thành phần thuốc và 7 viên đệm không chứa thuốc tránh thai).\n\nHình 4. Thành phần thuốc tránh thai\n- Cơ chế tránh thai\n+ Ức chế phóng noãn do ức chế giải phóng FSH, LH từ trục dưới đồi - tuyến yên.\n+ Cản trở sự làm tổ của trứng do biến đổi nội mạc tử cung không phù hợp.\n+ Ngăn cản sự di chuyển của tinh trùng do chất nhầy cổ tử cung đặc lại.\n- Chỉ định và chống chỉ định\nChỉ định: Tất cả phụ nữ muốn sử dụng một biện pháp tránh thai tạm thời, hiệu quả cao và không có chống chỉ định.\nChống chỉ định:\n+ Có thai hoặc nghi ngờ có thai.\n+ Đang cho con bú và dưới 6 tuần sau sinh\n+ Ra máu âm đạo bất thường chưa rõ nguyên nhân.\n+ Đang theo dõi các loại khối u.\n+ Phụ nữ trên 35 tuổi hút thuốc lá.\n+ Các bệnh lý nội khoa như cao huyết áp, đái tháo đường, bệnh gan, thận...\n+ Điều trị với các thuốc chống co giật như Phenyltoin, Carbamazepin, Barbiturat hoặc kháng sinh như Griseofulvin, Rifampicin.\n- Tác dụng phụ\n+ Ra huyết thấm giọt thường hay gặp ở 2-3 chu kỳ kinh nguyệt đầu tiên ngay sau khi dùng thuốc.\n+ Cương vú, đau vùng tiểu khung (kiểu giả có thai).\n+ Nhức đầu, thay đổi tâm lý, ham muốn tình dục.\n+ Tăng cân nhẹ do giữ muối, giữ nước.\nCác tác dụng phụ này thường chỉ xuất hiện trong thời gian đầu dùng thuốc.\n- Cách sử dụng\n+ Bắt đầu uống viên thứ nhất từ ngày 1 đến ngày 5 của vòng kinh, uống mỗi ngày một viên vào một giờ nhất định theo chiều mũi tên trên vỉ thuốc. Với vỉ 28 viên, khi hết vỉ thì uống viên đầu tiên của vỉ tiếp theo vào ngày hôm sau dù đang còn kinh. Với vỉ 21 viên khi hết vỉ nghỉ 7 ngày rồi dùng tiếp vỉ sau.\n+ Sau đẻ không cho con bú: uống từ tuần thứ tư sau đẻ.\n+ Sau nạo, sau sẩy thai, có thể bắt đầu sớm trong vòng 5 ngày đầu sau nạo.\n+ Xử trí khi quên thuốc: Nếu quên thuốc 1 viên thì uống ngay khi nhớ ra và tiếp tục như bình thường. Nếu quên thuốc 2 viên liên tiếp thì phải uống mỗi ngày 2 viên trong hai ngày sau đó. Đồng thời dùng thêm biện pháp tránh thai hỗ trợ cho đến khi hết vỉ thuốc. Nếu quên từ 3 viên trở lên, bỏ vỉ thuốc và bắt đầu dùng vỉ mới. Dùng biện pháp hỗ trợ trong 7 ngày đầu tiên. Hàng năm, người phụ nữ cần phải đi khám kiểm tra 1 lần hoặc khi có dấu hiệu bất thường\n2.2.1.2. Viên tránh thai đơn thuần\nViên thuốc tránh thai đơn thuần chỉ có Progestin, không có Estrogen. Ngoài tác dụng ngừa thai, còn thường được sử dụng với mục đích điều trị. Có 2 loại:\n- Progestin liều thấp, liên tục (microprogestatif)\n+ Thành phần, cách trình bày của thuốc:\nViên tránh thai progestin liều thấp hay được sử dụng là EXLUTON (lynestrenol 0,5mg), vỉ 28 viên. Ngoài ra còn có thể gặp ở thị trường: Microval (Levonorgestrel 0,03mg), Milligynon (Norethisterone Acetate, 0,6mg). Ogyline (norgestrienone).\n+ Cơ chế tránh thai:\nLàm đặc chất nhầy cổ tử cung, ngăn cản tinh trùng xâm nhập lên đường sinh dục trên. Làm teo nội mạc tử cung, giảm khả năng làm tổ.\n+ Hiệu quả tránh thai cao đạt đến 97%.\n- Viên Progestin liều cao (macroprogestatif)\nCác chế phẩm có thể là: Norluten (Noréthisterone 5mg), Orgametril (Lynestrenol 5mg). Một số thuốc có dẫn xuất từ progesteron như Lutenyl (Nomegestrol 5mg), Luteran (Chlomadinon 5mg), Surgestone (Promegeston 0,125mg) ít gây nam tính hoá khi sử dụng dài ngày. Các viên progestin liều cao ít sử dụng vì mục đích tránh thai và thường dùng trong điều trị.\n2.2.1.3. Viên tránh thai khẩn cấp\nViên tránh thai khẩn cấp còn gọi là viên thuốc tránh thai sáng hôm sau.\n- Cơ chế tác dụng: làm niêm mạc tử cung phát triển không thuận lợi cho sự làm tổ.\n- Chỉ định: Trường hợp giao hợp không được bảo vệ, bị cưỡng dâm.\n- Cách sử dụng: viên tránh thai khẩn cấp chỉ có Progestin đơn thuần: Loại thường được sử dụng là Postinor (Levorgestrel 0,75mg) Viên đầu tiên uống càng sớm càng tốt trong vòng 72 giờ sau giao hợp không được bảo vệ, viên thứ hai uống sau viên thứ nhất 12 giờ.\nViên thuốc tránh thai kết hợp (Ideal, Choice, New choice, Tetragynon): Uống 4 viên thuốc tránh thai kết hợp trong vòng 72 giờ sau giao hợp, 12 giờ sau đó  uống tiếp 4 viên.\nTác dụng phụ thường gặp triệu chứng chóng mặt, buồn nôn và nôn sau khi dùng viên tránh thai khẩn cấp.\n2.2.2. Thuốc tiêm tránh thai\nThuốc tiêm tránh thai DMPA là loại hormon progestin có tác dụng tránh thai 1 tháng hay 3 tháng.\n- Depo-provera (medroxyprogesterone acetate) chế phẩm của progesteron tự nhiên được pha chế trong dung dịch nhũ tương tinh thể nhỏ do đó được hấp thu chậm.\n- Noristerat (noréthisterone) 200mg.\nCơ chế tác dụng: Thuốc tiêm DMPA liên tục ức chế phóng noãn, làm niêm mạc tử cung mỏng và làm đặc chất nhầy cổ tử cung.\nChỉ định cho những người phụ nữ muốn dùng biện pháp tránh thai dài hạn, có hồi phục, hiệu quả cao mà không phải dùng thuốc hàng ngày. Ưu điểm: Hiệu quả cao, có tác dụng lâu dài, chỉ cần tiêm một lần cho 4 tuần, 12 tuần.\nCó thể hồi phục lại khả năng sinh sản. Không ảnh hưởng nhiều đến tim mạch, thích hợp cho phụ nữ trên 35 tuổi phải đề phòng với estrogen. Có thể dùng cho phụ nữ cho con bú, không ảnh hưởng đến giao hợp, dễ sử dụng.\nTác dụng phụ: ra huyết thấm giọt, rong kinh giữa kỳ, vô kinh, tăng cân nhẹ. Việc sử dụng kéo dài thường đi kèm với việc giảm mật độ khoáng trong xương và sẽ trở lại bình thường sau khi ngừng sử dụng thuốc.\nChống chỉ định: dưới 6 tuần sau sinh; Nhiều yếu tố nguy cơ bệnh tim mạch; Huyết áp cao không kiểm soát; Bệnh mạch; đang bị viêm tắc tĩnh mạch sâu; có tiền sử hoặc đang bị bệnh tim do thiếu máu; tiền sử đột quị; có tiền sử hoặc đang mắc ung thư vú; tiểu đường phụ thuộc insulin với những thay đổi mạch hoặc diễn biến bệnh trên 20 năm; đang bị viêm gan do virus, xơ gan nặng, các khối u gan.\nNhược điểm: Vì thuốc có tác dụng kéo dài nên không thể ngưng tác dụng ngay hoặc lấy ra khỏi cơ thể khi có tai biến xảy ra hoặc muốn có thai trở lại.\nTỷ lệ thất bại là 0,3%\nThời điểm tiêm, liều lượng: Mũi tiêm có thể thực hiện vào bất cứ lúc nào trong chu kỳ kinh nguyệt với điều kiện là chắc chắn không có thai. Tốt nhất là trong vòng 7 ngày đầu của kỳ kinh hoặc sau nạo hút. Nếu cho con bú thì tiêm 6 tuần sau đẻ.\nChế độ chuẩn là cứ 12 tuần dùng một liều 150mg DMPA, tiêm bắp sâu. Có thể sớm hoặc muộn hơn 2 tuần vẫn có tác dụng.\n2.2.3. Thuốc cấy tránh thai\nThuốc cấy tránh thai hiện nay có 2 loại:\n- Norplant: Loại này có 6 nang mềm, vỏ bằng chất dẻo sinh học, mỗi nang chứa 36mg Levonorgestrel. Hormon này thấm qua thành nang vào máu một cách liên tục đảm bảo tác dụng tránh thai kéo dài 5 năm. Tỷ lệ thất bại là 0,2%.\n- Implanon: Chỉ có một nang chứa 68mg Etonogestrel và có tác dụng 3 năm.\nNơi cấy: mặt trong cánh tay không thuận(thường là tay trái), cấy nông dưới da.\nNoplant cấy 6 nang hình nan quạt.\nImplanon cấy ở khoảng giữa mặt trong cánh tay. Тác dụng phụ chủ yếu là ra máu âm đạo thấm giọt.\n\nHình 5. Cấu trúc của que cấy Implanon\n\n\n\nHình 6. Kỹ thuật cấy Implanon\n2.2.4. Thuốc diệt tinh trùng\nLà những loại chất có tác dụng hoá học để diệt hoặc làm mất khả năng di chuyển của tinh trùng. Ngoài ra nó có tác dụng như một dung môi tạo nên màng chắn, hoặc tạo bọt nhằm đẩy tinh trùng ra xa cổ tử cung.\nCác chất thường dùng: acid lactic, nicoceptin, nonoxynol 9, Chlorure benzalkonium (Pharmatex). Thuốc phải đảm bảo diệt tinh trùng nhanh, không gây cảm giác khó chịu, không làm giảm khoái cảm. Thuốc được sản xuất dưới dạng kem, nhũ tương, viên đạn, viên sủi bọt, loại khí dung sủi bọt để đặt vào âm đạo.\nTrước khi giao hợp 5 phút đặt hoặc bơm thuốc vào âm đạo, thuốc chỉ tác dụng trong vòng 1 giờ. Nhược điểm là gây nóng âm đạo, mỗi lần giao hợp phải đặt thuốc lại.\nTỷ lệ thất bại khoảng 10%. Nên kết hợp thuốc diệt tinh trùng với một trong các tránh thai khác kết quả tránh thai sẽ cao hơn.\n\nHình 7. Thuốc diệt tinh trùng\n\n3. CÁC PHƯƠNG PHÁP TRÁNH THAI TRUYỀN THỐNG\nLà những phương pháp tránh thai đơn giản, dễ áp dụng, có tác dụng tránh thai ngắn hạn. Đây là những phương pháp được sử dụng từ lâu và có tác dụng nhất định trong việc hạn chế phát triển dân số.\n3.1. Áp dụng ở nam giới\n3.1.1. Phương pháp sử dụng bao cao su\nBao cao su ngăn không cho tinh dịch vào âm đạo. Bao được làm bằng cao su latex rất mỏng có hoặc không phủ lớp diệt tinh trùng. Ngoài tác dụng tránh thai cao bao cao su còn có tác dụng phòng các bệnh lây truyền theo đường tình dục, đặc biệt là HIV/AIDS đang có nguy cơ lan tràn khắp thế giới.\nChỉ định: Tất cả mọi người muốn tránh thai tạm thời mà không muốn dùng các biện pháp khác hoặc muốn phòng chống các bệnh lây truyền qua đường sinh dục, trừ trường hợp bị dị ứng với chất cao su khi dùng. Tỷ lệ thất bại: 14%.\n3.1.2. Phương pháp xuất tinh ra ngoài âm đạo\nXuất tinh ra ngoài âm đạo để không cho tinh trùng vào trong âm đạo để gặp trứng thụ tinh do đó còn gọi là phương pháp giao hợp ngắt quãng. Hiện nay nhiều cặp vợ chồng sử dụng phương pháp này.Tỷ lệ thất bại khá cao, khoảng 24%.\n\nHình 8. Hướng dẫn mang bao cao su cho nam giới\n3.2. Áp dụng ở nữ giới\n3.2.1. Phương pháp Ogino-Knauss\nPhương pháp Ogino-Knauss là phương pháp tránh thai cổ điển và hiện nay vẫn là một trong những phương pháp được quan tâm.\n- Cơ chế tác dụng\nPhương pháp dựa vào hiện tượng phóng noãn bao giờ cũng xảy ra ở thời gian cố định từ 12 - 16 ngày trước kỳ kinh tới. Ước tính thời gian có thể thụ tinh của noãn khoảng 10 - 24 giờ, thời gian thụ tinh của tinh trùng trong đường sinh dục nữ là 48 giờ. Vì vậy muốn tránh thai thì cần tránh giao hợp trước khi dự kiến có phóng noãn 2 ngày và sau phóng noãn 1 ngày.\nOgino-Knauss là phương pháp tránh thai tự nhiên bằng cách tránh giao hợp vào thời kỳ rụng trứng. Hiệu quả của phương pháp này tuỳ thuộc theo từng người và mức độ theo dõi để xác định thời kỳ rụng trứng có chính xác hay không. Ngoài ra phương pháp này có đặc điểm là khó áp dụng đối với những phụ nữ không có thói quen theo dõi kinh nguyệt một cách đều đặn, ở người đang cho con bú, vô kinh. Tỷ lệ thất bại dao động từ 2-21%.\n\nHình 9. Phương pháp Ogino-Knauss\n3.2.2. Biện pháp cho bú vô kinh\nCó thể áp dụng ở những phụ nữ cho con bú hoàn toàn, chưa có kinh trở lại và con dưới 6 tháng tuổi. Hiệu quả tránh thai có thể tới 98%.\nBiện pháp dựa trên cơ sở trẻ bú mẹ tác động lên vùng dưới đồi, ảnh hưởng đến mức độ và nhịp điệu của sự tiết các hormon giải phóng, ức chế sự phóng noãn.\nĐây là phương pháp tránh thai rất được khuyến khích ở các nước đang phát triển.\n3.2.3. Mũ cổ tử cung, màng ngăn âm đạo\nDụng cụ làm bằng kim khí hoặc chất dẻo để ngăn cản không cho tinh trùng vào tử cung. Tỷ lệ thất bại của màng ngăn âm đạo, mũ cổ tử cung gần 20% cho mỗi loại. Các phương pháp này hiện nay rất ít được sử dụng.\n\nHình 10. Mũ cổ tử cung\n\nHình 11. Màng ngăn âm đạo\n\n4. PHƯƠNG PHÁP ĐÌNH SẢN TỰ NGUYỆN\nĐình sản là biện pháp hiệu quả cao, đơn giản và có thể hồi phục bằng can thiệp phẫu thuật.\n4.1. Đình sản nữ\nLà phương pháp làm tắc vòi tử cung, ngăn cản vĩnh viễn không cho tinh trùng và trứng gặp nhau để thụ tinh.\n4.1.1. Chỉ định và chống chỉ định\nTất cả phụ nữ tự nguyện áp dụng.\n4.1.2. Ưu, nhược điểm của phương pháp đình sản nữ\nHiệu quả tránh thai có thể đạt đến 100% nếu như cắt và thắt đúng phương pháp, không ảnh hưởng đến kinh nguyệt, sức khoẻ, tâm sinh lý và hoạt động tình dục.\n4.1.3. Thực hiện phương pháp đình sản nữ\n- Thời điểm:\n+ Sau khi đẻ: Tiến hành từ 24 đến 48 giờ là dễ thực hiện nhất\n+ Sau nạo, sau sẩy thai.\n+ Kết hợp đình sản trong mổ lấy thai, phẫu thuật phụ khoa.\n- Kỹ thuật: Đình sản là một loại phẫu thuật nhỏ, chỉ cần rạch thành bụng khoảng 2 cm để cặp 2 vòi trứng lên thắt và cắt. Ngoài ra có thể đình sản nữ qua nội soi bằng ống soi, ống soi được đưa qua một điểm cắt nhỏ vào ổ bụng, sau đó là thủ thuật đốt điện vòi trứng. Phương pháp này đòi hỏi các trang thiết bị đắt tiền và phức tạp, đồng thời cũng không dễ thực hiện.\n\nHình 12. Đình sản nữ\n4.2. Đình sản nam\nThắt ống dẫn tinh là một trong những biện pháp tránh thai ít phổ biến hiện nay trên toàn thế giới. Tuy nhiên đây là một trong những biện pháp có hiệu quả, an toàn, đơn giản và tiện lợi.\n4.2.1. Cơ chế tác dụng\nPhương pháp thắt và cắt ống dẫn tinh làm cho tinh trùng không thể di chuyển từ tinh hoàn và mào tinh đi qua ống dẫn tinh và phóng vào âm đạo khi xuất tinh để gặp trứng.\nSau khi thắt ống dẫn tinh, tinh hoàn vẫn hoạt động bình thường, tinh trùng vẫn được sản xuất, các hormon vẫn bình thường nên không ảnh hưởng đến giới tính và hoạt động sinh dục.\n4.2.2. Chỉ định\nNam giới tự nguyện áp dụng.\n4.2.3. Kỹ thuật\nKỹ thuật không dùng dao mổ đang trở thành biện pháp phổ biến. Với kỹ thuật này chỉ cần châm một vết nhỏ 1mm vào da bìu bằng kẹp, mở rộng ra để định vị và tách và thắt các ống dẫn tinh.\n4.2.4. Theo dõi\nPhương pháp thắt ống dẫn tinh đạt hiệu quả 99 - 99,5%, tỷ lệ thất bại do giao hợp không được bảo vệ ngay sau khi tiến hành thủ thuật. Do đó nên tránh giao hợp trong 2-3 ngày và dùng bao cao su trong 20 lần xuất tinh sau khi đã cắt, thắt ống dẫn tinh. Nếu có điều kiện trước khi giao hợp bình thường nên đến bệnh viện thử lại tinh trùng, nếu còn tinh trùng thì phải tiếp tục dùng bao cao su hoặc phương pháp khác.\n\nHình 13. Đình sản nam\nCâu hỏi:\n1: Kể tên các biện pháp tránh thai tạm thời hiện đang áp dụng ở Việt Nam, ưu và nhược điểm?\n2: Trình bày chỉ định, chống chỉ định đặt dụng cụ tử cung, bao cao su và viên thuốc tránh thai khẩn cấp?\n3: Trình bày chỉ định, chống chỉ định sử dụng viên thuốc tránh thai kết hợp và đơn thuần?\n4: Trình bày chỉ định, chống chỉ định của thuốc tiêm và thuốc cấy tránh thai?\n5. Trình bày chỉ định, chống chỉ định, kỹ thuật của biện phỏp triệt sản nam và nữ?\nCHƯƠNG 6. HỖ TRỢ SINH SẢN – SỨC KHỎE SINH SẢN", "priority": "Trung bình"}, {"id": "SK-51", "chapter": "Chương 6. Hỗ trợ sinh sản", "folder": "06_Ho_tro_sinh_san", "title": "Đại cương vô sinh", "author": "Bs.CK II. Nguyễn Thị Tuyết", "word_count": 2522, "line_count": 146, "key_numbers": ["10 giờ", "10mg", "28 ngày", "2ml", "37 tuần", "60 phút"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["ĐẠI CƯƠNG VÔ SINH", "Bs.CK II.Nguyễn Thị Tuyết"], "bullets": []}, {"heading": "1. MỞ ĐẦU", "paragraphs": ["Vô sinh là một trọng tâm trong chương trình chăm sóc sức khoẻ sinh sản. Điều trị vô sinh là một nhu cầu cấp thiết cho những cặp vợ chồng vô sinh nhằm đảm bảo hạnh phúc gia đình và phát triển hài hòa với xã hội.", "Bình thường sau một năm chung sống khoảng 80 - 85% các cặp vợ chồng có thể có thai tự nhiên. Theo thống kê trên thế giới, tỷ lệ vô sinh chiếm khoảng 8 - 15 % các cặp vợ chồng. Ở Việt Nam hiện nay, vô sinh chiếm 12 - 13 % tổng số cặp vợ chồng, tương đương với gần một triệu cặp vợ chồng."], "bullets": []}, {"heading": "2.1. Định nghĩa", "paragraphs": ["Theo Tổ chức Y tế thế giới một cặp vợ chồng gọi là vô sinh khi sống cùng nhau trên một năm và không dùng biện pháp tránh thai nào mà vẫn không có con.", "Khả năng sinh sản đạt đỉnh cao ở khoảng từ 20 - 25 tuổi và giảm dần sau 30 tuổi ở phụ nữ và sau 40 tuổi ở nam giới."], "bullets": []}, {"heading": "2.2.1. Vô sinh nguyên phát (Vô sinh I)", "paragraphs": ["Hai vợ chồng chưa bao giờ có thai, mặc dù đã sống với nhau trên một năm và không dùng biện pháp tránh thai nào."], "bullets": []}, {"heading": "2.2.2. Vô sinh thứ phát (Vô sinh II)", "paragraphs": ["Hai vợ chồng trước kia đã có con hoặc đã có thai, nhưng sau đó không thể có thai lại mặc dù đang sống với nhau trên một năm và không dùng biện pháp tránh thai nào."], "bullets": []}, {"heading": "3. NGUYÊN NHÂN", "paragraphs": ["Sự thụ thai có thể đạt được khi có các điều kiện đó là:", "Khi có rối loạn bất kỳ khâu nào trong chuỗi các hoạt động sinh sản này đều dẫn đến kết cục bất lợi.", "Như vậy một cặp vợ chồng vô sinh có thể do chồng. hoặc do người vợ hoặc cho cả hai. Các dữ liệu thu được cho thấy khoảng 30-40 % các trường hợp vô sinh do nguyên nhân nam giới đơn thuần, 40 % do nữ giới, 10 % do kết hợp cả nam và nữ và 10% không rõ nguyên nhân.", "Nói chung nguyên nhân vô sinh có thể phân như sau:"], "bullets": ["+ Có sự phát triển nang noãn và phóng noãn;", "+ Có sự sản xuất tinh trùng đảm bảo chất lượng", "+  Tinh trùng gặp được noãn", "+  Sự thụ tinh, làm tổ và phát triển tại tử cung cho đến đủ trên 37 tuần."]}, {"heading": "3.3. Vô sinh không rõ nguyên nhân", "paragraphs": ["Khoảng 10% vô sinh không thể tìm nguyên nhân chính xác sau khi đã thăm khám và làm tất cả các xét nghiệm cần thiết để thăm dò và chẩn đoán."], "bullets": []}, {"heading": "4.1. Thăm khám", "paragraphs": ["Nguyên tắc khám vô sinh là khám cả hai vợ chồng, đảm bảo riêng tư cá nhân, kín đáo."], "bullets": []}, {"heading": "4.1.1. Hỏi bệnh", "paragraphs": ["Mục đích của hỏi bệnh nhằm khai thác thông tin về cả hai vợ chồng:", "Tuổi, nghề nghiệp và địa dư.", "Thói quen hút thuốc, uống rượu", "Thời gian mong muốn có con và quá trình điều trị trước đây.", "Tiền sử sản khoa mang thai, sẩy, sinh đủ tháng hay nạo phá thai.", "Khả năng giao hợp, tần suất, tình trạng xuất tinh và những khó khăn gặp phải.", "Tiền sử mắc các bệnh nội ngoại khoa và các thuốc đang dùng hiện tại.", "Về phía người vợ cần hỏi thêm:", "Tuổi bắt đầu hành kinh, tính chất kinh nguyệt, thời gian của mỗi kỳ kinh, lượng kinh nhiều hay ít, có đau bụng khi hành kinh không.", "Tiền sử viêm nhiễm sinh dục và cách điều trị", "Tiền sử mắc các bệnh lý phụ khoa hay các phẫu thuật vùng tiểu khung."], "bullets": []}, {"heading": "4.1.2. Khám lâm sàng", "paragraphs": ["Về phía người vợ, cần khám:", "Quan sát về toàn thân: tầm vóc, tính chất sinh dục phụ như lông, tóc, lông mu, lông nách, mức độ phát triển của vú, âm vật, môi lớn, môi nhỏ...", "Khám phụ khoa gồm quan sát qua mỏ vịt, thăm âm đạo, kết hợp với nắn bụng nhằm phát hiện những tổn thương về đường sinh dục chủ yếu là tình trạng viêm nhiễm và các khối u phụ khoa. Chú ý tình trạng chế tiết của cổ tử cung, độ sạch và độ phát triển niêm mạc âm đạo... Ngoài ra tư thế bất thường của tử cung là một điểm cầm lưu ý, tử cung gấp về một phía là một nguyên nhân gây cản trở tinh trùng thâm nhập lên đường sinh dục trên. Tử cung có nhân xơ trong buồng tử cung cũng có thể là một nguyên nhân vô sinh.", "Về phía người chồng cần khám:", "Quan sát về toàn thân: tầm vóc, tính chất sinh dục phụ như lông, tóc, lông mu, lông nách, giọng nói.", "Tiền sử, bệnh sử có liên quan đến việc nhiễm sinh dục, tiền sử quai bị, lao tinh hoàn. Đối với quai bị cần lưu ý hỏi về tuổi mắc bệnh trước dậy thì hay sau tuổi dậy thì, có viêm tinh hoàn kèm theo không. Ngoài ra còn hỏi về tình trạng phẫu thuật liên quan đến sinh dục như thoát vị bẹn, tinh hoàn lạc chỗ.", "Kích thước dương vật, vị trí lỗ tiểu, biểu hiện viêm nhiễm.", "Khám bìu, sự hiện diện tinh hoàn trong bìu cũng như kích thước và mật độ, kiểm tra thừng tinh, mào tinh."], "bullets": []}, {"heading": "4.2.1. Thăm dò ở người nữ", "paragraphs": ["Xét nghiệm nội tiết: nội tiết tố hướng sinh dục (LH,FSH), nội tiết sinh dục (estrogen, progesteron), nội tiết thai nghén (hCG)...Tiến hành các thử nghiệm nội tiết để đánh giá chức năng của vùng dưới đồi - tuyến yên hay buồng trứng qua đáp ứng của nội tiết tố.", "Thăm dò phóng noãn: Đo thân nhiệt cơ sở, chỉ số tử cung, sinh thiết nội mạc tử cung định ngày...Khi có phóng noãn xảy ra, đường biểu diễn thân nhiệt có 2 thì, chỉ số cổ tử cung sau phóng noãn vài ngày phải giảm xuống 0.0.0.0 do hiện diện progesteron từ hoàng   thể tiết ra. Sinh thiết niêm mạc tử cung từ ngày 21 - 24 của chu kỳ kinh 28 ngày, tìm thấy hình ảnh chế tiết, chỉ sử dụng 1 lần trước khi điều trị để chẩn đoán khi các xét nghiệm nói trên không rõ ràng.", "Thử nghiệm sau giao hợp: Sự sống của tinh trùng trong đường sinh dục nữ phụ thuộc vào sự di chuyển nhanh chóng tinh trùng vào niêm dịch cổ tử cung. Đây là cơ sở của thử nghiệm sau giao hợp (Huhner test). Từ 2-10 giờ sau giao hợp hút dịch từ ống cổ tử cung. Thử nghiệm dương tính nếu ít nhất tìm thấy được 5 tinh trùng khoẻ trong một môi trường ở vật kính x 40. Thử nghiệm sau giao hợp đơn thuần không thay thế đánh giá khả năng sinh sản của chồng, và không thay thế xét nghiệm tinh dịch đồ được. Viêm âm đạo, cổ tử cung có thể sai lạc việc đánh giá nghiệm pháp, cần thiết điều trị khỏi viêm nhiễm trước khi thử thử nghiệm Huhner.", "Chẩn đoán hình ảnh: siêu âm phụ khoa, siêu âm theo dõi sự phát triển nang noãn, siêu âm thai sớm, chụp phim tử cung vòi tử cung, chụp tuyến yên bằng X quang thường quy hoặc cắt lớp vi tính.", "Phẫu thuật nội soi: chẩn đoán các bất thường sinh dục, nội soi gỡ dính vòi trứng, buồng trứng, bơm thông vòi trứng, đốt điểm buồng trứng...", "Xét nghiệm nhiễm sắc thể đồ phát hiện các bất thường di truyền."], "bullets": []}, {"heading": "4.2.2. Thăm dò ở người nam", "paragraphs": ["Xét nghiệm nội tiết: định lượng nội tiết tố hướng sinh dục (LH, FSH), nội tiết sinh dục (testosteron)...", "Xét nghiệm tinh dịch: Phân tích tinh dịch theo yêu cầu và kỹ thuật chuẩn hoá của Tổ chức y tế thế giới nhằm đánh giá một cách khách quan tinh dịch về các thông số như thể tích, đại thể, mật độ, độ di động, tỷ lệ sống, hình thái...Các thông số tinh dịch đồ bình thường:", "Chỉ số", "Giá trị bình thường", "Thể tích", "( 2ml", "PH"], "bullets": []}, {"heading": "7.2 đến 7.8", "paragraphs": ["Mật độ tinh trùng", "( 20 x 106/ml", "Tổng số tinh trùng", "( 40 x 106", "Độ di động", "> 50% di chuyển tới trước", "> 25% di chuyển theo đường thẳng nhanh trong vòng 60 phút sau khi lấy mẫu.", "Hình thái học", "> 30% có hình thái bình thường", "Sống sót", "> 50% tinh trùng sống.", "Bạch cầu", "<1 x 106/ml", "Kẽm (tổng số)", "≤ 2.4 micromol mỗi lần phóng tinh", "Acid citric (tổng số)", "≤ 52 micromol (10mg) mỗi lần phóng tinh", "Fructose (tổng số)", "≤ 13 micromol mỗi lần phóng tinh", "Thử nghiệm gắn antiglobulin", "< 10% tinh trùng gắn các hạt dính", "Thử nghiệm hạt miễn dịch", "< 10% tinh trùng gắn các hạt dính", "Các thông số tinh dịch đồ (theo Tổ chức Y tế thế giới - 1999)", "Chẩn đoán hình ảnh: Khảo sát bìu, tinh hoàn, thừng tinh qua siêu âm, chụp đường dẫn tinh.", "Sinh thiết tinh hoàn, mào tinh, thừng tinh tìm sự hiện diện của tinh trùng trong trường hợp mẫu tinh dịch vô tinh.", "Xét nghiệm nhiễm sắc thể đồ phát hiện các bất thường di truyền."], "bullets": []}, {"heading": "5. PHƯƠNG PHÁP ĐIỀU TRỊ", "paragraphs": ["Nguyên tắc điều trị vô sinh là điều trị cả hai vợ chồng và điều trị toàn diện. Nói chung, việc điều trị cụ thể tuỳ vào từng cá thể với các nguyên nhân khác nhau. Tuy nhiên, có thể phân theo các phương pháp chính sau:"], "bullets": []}, {"heading": "4.3.1. Về phía người vợ", "paragraphs": ["Loại 1: Suy dưới đồi – tuyến yên: chỉ định kích thích buồng trứng theo nhiều phác đồ khác nhau nhằm tăng sự phát triển nang noãn, tăng trưởng thành và phóng noãn.", "Loại 2: Rối loạn trục dưới đồi – tuyến yên: dùng clomiphen citrat, IUI, IVF.", "Loại 3: Suy buồng trứng: Hướng dẫn bn xin noãn làm IVF.", "Tắc vòi tử cung: phẫu thuật mổ thông vòi tử cung qua mở bụng hoặc qua nội soi."], "bullets": ["- Nếu có bất thường phóng noãn: Theo phân loại của WHO đã chia ra các bất thường phóng noãn như sau:", "- Điều trị viêm nhiễm đường sinh dục nếu có trước khi thăm dò nguyên nhân vô sinh. Có khoảng 5% bệnh nhân vô sinh có thai tự nhiên chỉ mới sau khi điều trị viêm âm đạo, cổ tử cung hoặc thay đổi môi trường âm đạo..", "- Các điều trị hỗ trợ cần thiết khác như chỉ định Bromocriptin trong trường hợp vô kinh tiết sữa, chế phẩm tăng nhạy cảm insulin (metformin) trong hội chứng buồng trứng đa nang...", "- Phẫu thuật có thể chỉ định như nội soi gỡ dính, đốt điểm buồng trứng đa nang, bóc u lạc nội mạc, sửa chữa các dị dạng sinh dục..."]}, {"heading": "4.3.2. Về phía người chồng", "paragraphs": [], "bullets": ["- Bất thường tinh dịch đồ: tuỳ vào mức độ bất thường mà chỉ định phương pháp can thiệp.", "+ Nội tiết tố: có thể cải thiện chất lượng tinh trùng trong những trường hợp do nguyên nhân nội tiết, bất thường mức trung bình, tuy nhiên quá trình điều trị thường dài ngày, tốn kém và không cải thiện nhiều.", "+ Thụ tinh nhân tạo với bơm tinh trùng sau lọc rửa vào trong buồng tử cung được ưu tiên chỉ định cho trường hợp bất thường tinh trùng trung bình. Đây là phương pháp đơn giản, dễ thực hiện, gần với sinh lý nhất và tỷ lệ có thai cộng dồn khá tốt.", "+ Thụ tinh trong ống nghiệm: là một thành tựu trong điều trị vô sinh với khả năng can thiệp tối đa, đặc biệt những người tinh trùng ít, yếu và dị dạng nặng. Những trường hợp vô tinh do tắc nghẽn, tinh trùng có thể được trích từ tinh hoàn, mào tinh để tiêm vào trong bào tương trứng. Đây cũng có thể là chỉ định trong trường hợp vô sinh do vòi trứng không có khả năng phẫu thuật, suy buồng trứng hay vô sinh không rõ nguyên nhân.", "- Bất thường chức năng tình dục: loại trừ các nguyên nhân thực thể (đái tháo đường, bất thường mạch máu, thần kinh, u xơ tiền liệt tuyến...), tâm lý liệu pháp, các chế phẩm kích thích tình dục chỉ được chỉ định sau khi đã loại trừ các bệnh lý thực thể và chỉ dùng hạn chế với sự theo dõi của thầy thuốc.", "- Có thể chỉ định phẫu thuật sửa chữa trong giãn tĩnh mạch thừng tinh, lỗ tiểu đóng thấp, tinh hoàn lạc chỗ..."]}], "raw_text": "ĐẠI CƯƠNG VÔ SINH\nBs.CK II.Nguyễn Thị Tuyết\nMục tiêu học tập\n1. Định nghĩa được vô sinh\n2. Xác định một số nguyên nhân vô sinh nữ, nam\n3. Trình bày được các bước trong thăm khám, chẩn đoán và điều trị vô sinh.\n1. MỞ ĐẦU\nVô sinh là một trọng tâm trong chương trình chăm sóc sức khoẻ sinh sản. Điều trị vô sinh là một nhu cầu cấp thiết cho những cặp vợ chồng vô sinh nhằm đảm bảo hạnh phúc gia đình và phát triển hài hòa với xã hội.\nBình thường sau một năm chung sống khoảng 80 - 85% các cặp vợ chồng có thể có thai tự nhiên. Theo thống kê trên thế giới, tỷ lệ vô sinh chiếm khoảng 8 - 15 % các cặp vợ chồng. Ở Việt Nam hiện nay, vô sinh chiếm 12 - 13 % tổng số cặp vợ chồng, tương đương với gần một triệu cặp vợ chồng.\n2. ĐỊNH NGHĨA VÀ PHÂN LOẠI VÔ SINH\n2.1. Định nghĩa\nTheo Tổ chức Y tế thế giới một cặp vợ chồng gọi là vô sinh khi sống cùng nhau trên một năm và không dùng biện pháp tránh thai nào mà vẫn không có con.\nKhả năng sinh sản đạt đỉnh cao ở khoảng từ 20 - 25 tuổi và giảm dần sau 30 tuổi ở phụ nữ và sau 40 tuổi ở nam giới.\n2.2. Phân loại vô sinh\n2.2.1. Vô sinh nguyên phát (Vô sinh I)\nHai vợ chồng chưa bao giờ có thai, mặc dù đã sống với nhau trên một năm và không dùng biện pháp tránh thai nào.\n2.2.2. Vô sinh thứ phát (Vô sinh II)\nHai vợ chồng trước kia đã có con hoặc đã có thai, nhưng sau đó không thể có thai lại mặc dù đang sống với nhau trên một năm và không dùng biện pháp tránh thai nào.\n3. NGUYÊN NHÂN\nSự thụ thai có thể đạt được khi có các điều kiện đó là:\n+ Có sự phát triển nang noãn và phóng noãn;\n+ Có sự sản xuất tinh trùng đảm bảo chất lượng\n+  Tinh trùng gặp được noãn\n+  Sự thụ tinh, làm tổ và phát triển tại tử cung cho đến đủ trên 37 tuần.\nKhi có rối loạn bất kỳ khâu nào trong chuỗi các hoạt động sinh sản này đều dẫn đến kết cục bất lợi.\nNhư vậy một cặp vợ chồng vô sinh có thể do chồng. hoặc do người vợ hoặc cho cả hai. Các dữ liệu thu được cho thấy khoảng 30-40 % các trường hợp vô sinh do nguyên nhân nam giới đơn thuần, 40 % do nữ giới, 10 % do kết hợp cả nam và nữ và 10% không rõ nguyên nhân.\nNói chung nguyên nhân vô sinh có thể phân như sau:\n3.1. Vô sinh do nam giới\n3.1.1. Bất thường tinh dịch: vô tinh do tắc nghẽn hoặc do bất sản, giảm chất lượng tinh trùng (tinh trùng ít, yếu, dị dạng).\n3.1.2. Bất thường giải phẫu: giãn tĩnh mạch thừng tinh, lỗ tiểu đóng thấp, đóng cao, tinh hoàn ẩn.\n3.1.3. Rối loạn chức năng: giảm ham muốn, rối loạn cương dương, rối loạn phóng tinh, chứng giao hợp đau.\n3.1.4. Các nguyên nhân khác: chấn thương tinh hoàn, phẩu thuật niệu sinh dục, triệt sản nam, viêm nhiễm niệu sinh dục hay nguyên nhân di truyền.\n3.2. Nguyên nhân do nữ giới\n3.2.1. Bất thường phóng noãn: Vòng kinh không phóng noãn do ảnh hưởng của trục dưới đồi - tuyến yên - buồng trứng, u tuyến yên.\n3.2.2. Nguyên nhân do vòi tử cung: Các bệnh lý có thể gây tổn thương vòi tử cung như viêm nhiễm đường sinh dục, bệnh lây qua đường tình dục, tiền sử phẫu thuật vùng chậu và vòi tử cung, lạc nội mạc tử cung ở vòi tử cung, bất thường bẩm sinh ở vòi tử cung hay do triệt sản.\n3.2.3. Nguyên nhân tại tử cung: U xơ tử cung, viêm dính buồng tử cung, bất thường bẩm sinh (dị dạng tử cung hai sừng, tử cung có vách ngăn, không có tử cung...)\n3.2.4. Nguyên nhân do cổ tử cung: chất nhầy kém, kháng thể kháng tinh trùng, tổn thương ở cổ tử cung do can thiệp thủ thuật (khoét chóp, đốt điện...), cổ tử cung ngắn.\n3.2.5 Nguyên nhân khác: Tâm lý tình dục, chứng giao hợp đau, các dị dạng bẩm sinh đường sinh dục dưới...\n3.3. Vô sinh không rõ nguyên nhân\nKhoảng 10% vô sinh không thể tìm nguyên nhân chính xác sau khi đã thăm khám và làm tất cả các xét nghiệm cần thiết để thăm dò và chẩn đoán.\n4. CÁC BƯỚC KHÁM VÀ THĂM DÒ CHẨN ĐOÁN\n4.1. Thăm khám\nNguyên tắc khám vô sinh là khám cả hai vợ chồng, đảm bảo riêng tư cá nhân, kín đáo.\n4.1.1. Hỏi bệnh\nMục đích của hỏi bệnh nhằm khai thác thông tin về cả hai vợ chồng:\nTuổi, nghề nghiệp và địa dư.\nThói quen hút thuốc, uống rượu\nThời gian mong muốn có con và quá trình điều trị trước đây.\nTiền sử sản khoa mang thai, sẩy, sinh đủ tháng hay nạo phá thai.\nKhả năng giao hợp, tần suất, tình trạng xuất tinh và những khó khăn gặp phải.\nTiền sử mắc các bệnh nội ngoại khoa và các thuốc đang dùng hiện tại.\nVề phía người vợ cần hỏi thêm:\nTuổi bắt đầu hành kinh, tính chất kinh nguyệt, thời gian của mỗi kỳ kinh, lượng kinh nhiều hay ít, có đau bụng khi hành kinh không.\nTiền sử viêm nhiễm sinh dục và cách điều trị\nTiền sử mắc các bệnh lý phụ khoa hay các phẫu thuật vùng tiểu khung.\n4.1.2. Khám lâm sàng\nVề phía người vợ, cần khám:\nQuan sát về toàn thân: tầm vóc, tính chất sinh dục phụ như lông, tóc, lông mu, lông nách, mức độ phát triển của vú, âm vật, môi lớn, môi nhỏ...\nKhám phụ khoa gồm quan sát qua mỏ vịt, thăm âm đạo, kết hợp với nắn bụng nhằm phát hiện những tổn thương về đường sinh dục chủ yếu là tình trạng viêm nhiễm và các khối u phụ khoa. Chú ý tình trạng chế tiết của cổ tử cung, độ sạch và độ phát triển niêm mạc âm đạo... Ngoài ra tư thế bất thường của tử cung là một điểm cầm lưu ý, tử cung gấp về một phía là một nguyên nhân gây cản trở tinh trùng thâm nhập lên đường sinh dục trên. Tử cung có nhân xơ trong buồng tử cung cũng có thể là một nguyên nhân vô sinh.\nVề phía người chồng cần khám:\nQuan sát về toàn thân: tầm vóc, tính chất sinh dục phụ như lông, tóc, lông mu, lông nách, giọng nói.\nTiền sử, bệnh sử có liên quan đến việc nhiễm sinh dục, tiền sử quai bị, lao tinh hoàn. Đối với quai bị cần lưu ý hỏi về tuổi mắc bệnh trước dậy thì hay sau tuổi dậy thì, có viêm tinh hoàn kèm theo không. Ngoài ra còn hỏi về tình trạng phẫu thuật liên quan đến sinh dục như thoát vị bẹn, tinh hoàn lạc chỗ.\nKích thước dương vật, vị trí lỗ tiểu, biểu hiện viêm nhiễm.\nKhám bìu, sự hiện diện tinh hoàn trong bìu cũng như kích thước và mật độ, kiểm tra thừng tinh, mào tinh.\n4.2. Cận lâm sàng\n4.2.1. Thăm dò ở người nữ\nXét nghiệm nội tiết: nội tiết tố hướng sinh dục (LH,FSH), nội tiết sinh dục (estrogen, progesteron), nội tiết thai nghén (hCG)...Tiến hành các thử nghiệm nội tiết để đánh giá chức năng của vùng dưới đồi - tuyến yên hay buồng trứng qua đáp ứng của nội tiết tố.\nThăm dò phóng noãn: Đo thân nhiệt cơ sở, chỉ số tử cung, sinh thiết nội mạc tử cung định ngày...Khi có phóng noãn xảy ra, đường biểu diễn thân nhiệt có 2 thì, chỉ số cổ tử cung sau phóng noãn vài ngày phải giảm xuống 0.0.0.0 do hiện diện progesteron từ hoàng   thể tiết ra. Sinh thiết niêm mạc tử cung từ ngày 21 - 24 của chu kỳ kinh 28 ngày, tìm thấy hình ảnh chế tiết, chỉ sử dụng 1 lần trước khi điều trị để chẩn đoán khi các xét nghiệm nói trên không rõ ràng.\nThử nghiệm sau giao hợp: Sự sống của tinh trùng trong đường sinh dục nữ phụ thuộc vào sự di chuyển nhanh chóng tinh trùng vào niêm dịch cổ tử cung. Đây là cơ sở của thử nghiệm sau giao hợp (Huhner test). Từ 2-10 giờ sau giao hợp hút dịch từ ống cổ tử cung. Thử nghiệm dương tính nếu ít nhất tìm thấy được 5 tinh trùng khoẻ trong một môi trường ở vật kính x 40. Thử nghiệm sau giao hợp đơn thuần không thay thế đánh giá khả năng sinh sản của chồng, và không thay thế xét nghiệm tinh dịch đồ được. Viêm âm đạo, cổ tử cung có thể sai lạc việc đánh giá nghiệm pháp, cần thiết điều trị khỏi viêm nhiễm trước khi thử thử nghiệm Huhner.\nChẩn đoán hình ảnh: siêu âm phụ khoa, siêu âm theo dõi sự phát triển nang noãn, siêu âm thai sớm, chụp phim tử cung vòi tử cung, chụp tuyến yên bằng X quang thường quy hoặc cắt lớp vi tính.\nPhẫu thuật nội soi: chẩn đoán các bất thường sinh dục, nội soi gỡ dính vòi trứng, buồng trứng, bơm thông vòi trứng, đốt điểm buồng trứng...\nXét nghiệm nhiễm sắc thể đồ phát hiện các bất thường di truyền.\n4.2.2. Thăm dò ở người nam\nXét nghiệm nội tiết: định lượng nội tiết tố hướng sinh dục (LH, FSH), nội tiết sinh dục (testosteron)...\nXét nghiệm tinh dịch: Phân tích tinh dịch theo yêu cầu và kỹ thuật chuẩn hoá của Tổ chức y tế thế giới nhằm đánh giá một cách khách quan tinh dịch về các thông số như thể tích, đại thể, mật độ, độ di động, tỷ lệ sống, hình thái...Các thông số tinh dịch đồ bình thường:\nChỉ số\nGiá trị bình thường\n\nThể tích\n( 2ml\n\nPH\n7.2 đến 7.8\n\nMật độ tinh trùng\n( 20 x 106/ml\n\nTổng số tinh trùng\n( 40 x 106\n\nĐộ di động\n> 50% di chuyển tới trước\n> 25% di chuyển theo đường thẳng nhanh trong vòng 60 phút sau khi lấy mẫu.\n\nHình thái học\n> 30% có hình thái bình thường\n\nSống sót\n> 50% tinh trùng sống.\n\nBạch cầu\n<1 x 106/ml\n\nKẽm (tổng số)\n≤ 2.4 micromol mỗi lần phóng tinh\n\nAcid citric (tổng số)\n≤ 52 micromol (10mg) mỗi lần phóng tinh\n\nFructose (tổng số)\n≤ 13 micromol mỗi lần phóng tinh\n\nThử nghiệm gắn antiglobulin\n< 10% tinh trùng gắn các hạt dính\n\nThử nghiệm hạt miễn dịch\n< 10% tinh trùng gắn các hạt dính\n\nCác thông số tinh dịch đồ (theo Tổ chức Y tế thế giới - 1999)\nChẩn đoán hình ảnh: Khảo sát bìu, tinh hoàn, thừng tinh qua siêu âm, chụp đường dẫn tinh.\nSinh thiết tinh hoàn, mào tinh, thừng tinh tìm sự hiện diện của tinh trùng trong trường hợp mẫu tinh dịch vô tinh.\nXét nghiệm nhiễm sắc thể đồ phát hiện các bất thường di truyền.\n\n5. PHƯƠNG PHÁP ĐIỀU TRỊ\nNguyên tắc điều trị vô sinh là điều trị cả hai vợ chồng và điều trị toàn diện. Nói chung, việc điều trị cụ thể tuỳ vào từng cá thể với các nguyên nhân khác nhau. Tuy nhiên, có thể phân theo các phương pháp chính sau:\n5.1. Về phía người vợ\n4.3.1. Về phía người vợ\n- Nếu có bất thường phóng noãn: Theo phân loại của WHO đã chia ra các bất thường phóng noãn như sau:\nLoại 1: Suy dưới đồi – tuyến yên: chỉ định kích thích buồng trứng theo nhiều phác đồ khác nhau nhằm tăng sự phát triển nang noãn, tăng trưởng thành và phóng noãn.\nLoại 2: Rối loạn trục dưới đồi – tuyến yên: dùng clomiphen citrat, IUI, IVF.\nLoại 3: Suy buồng trứng: Hướng dẫn bn xin noãn làm IVF.\nTắc vòi tử cung: phẫu thuật mổ thông vòi tử cung qua mở bụng hoặc qua nội soi.\n- Điều trị viêm nhiễm đường sinh dục nếu có trước khi thăm dò nguyên nhân vô sinh. Có khoảng 5% bệnh nhân vô sinh có thai tự nhiên chỉ mới sau khi điều trị viêm âm đạo, cổ tử cung hoặc thay đổi môi trường âm đạo..\n- Các điều trị hỗ trợ cần thiết khác như chỉ định Bromocriptin trong trường hợp vô kinh tiết sữa, chế phẩm tăng nhạy cảm insulin (metformin) trong hội chứng buồng trứng đa nang...\n- Phẫu thuật có thể chỉ định như nội soi gỡ dính, đốt điểm buồng trứng đa nang, bóc u lạc nội mạc, sửa chữa các dị dạng sinh dục...\n4.3.2. Về phía người chồng\n- Bất thường tinh dịch đồ: tuỳ vào mức độ bất thường mà chỉ định phương pháp can thiệp.\n+ Nội tiết tố: có thể cải thiện chất lượng tinh trùng trong những trường hợp do nguyên nhân nội tiết, bất thường mức trung bình, tuy nhiên quá trình điều trị thường dài ngày, tốn kém và không cải thiện nhiều.\n+ Thụ tinh nhân tạo với bơm tinh trùng sau lọc rửa vào trong buồng tử cung được ưu tiên chỉ định cho trường hợp bất thường tinh trùng trung bình. Đây là phương pháp đơn giản, dễ thực hiện, gần với sinh lý nhất và tỷ lệ có thai cộng dồn khá tốt.\n+ Thụ tinh trong ống nghiệm: là một thành tựu trong điều trị vô sinh với khả năng can thiệp tối đa, đặc biệt những người tinh trùng ít, yếu và dị dạng nặng. Những trường hợp vô tinh do tắc nghẽn, tinh trùng có thể được trích từ tinh hoàn, mào tinh để tiêm vào trong bào tương trứng. Đây cũng có thể là chỉ định trong trường hợp vô sinh do vòi trứng không có khả năng phẫu thuật, suy buồng trứng hay vô sinh không rõ nguyên nhân.\n- Bất thường chức năng tình dục: loại trừ các nguyên nhân thực thể (đái tháo đường, bất thường mạch máu, thần kinh, u xơ tiền liệt tuyến...), tâm lý liệu pháp, các chế phẩm kích thích tình dục chỉ được chỉ định sau khi đã loại trừ các bệnh lý thực thể và chỉ dùng hạn chế với sự theo dõi của thầy thuốc.\n- Có thể chỉ định phẫu thuật sửa chữa trong giãn tĩnh mạch thừng tinh, lỗ tiểu đóng thấp, tinh hoàn lạc chỗ...\n\nCâu hỏi:\n1. Trình bày các nguyên nhân vô sinh nữ, nam?\n2. Trình bày các bước trong thăm khám, chẩn đoán và điều trị vô sinh.", "priority": "Trung bình"}, {"id": "SK-52", "chapter": "Chương 6. Hỗ trợ sinh sản", "folder": "06_Ho_tro_sinh_san", "title": "Sức khoẻ sinh sản vị thành niên", "author": "THs. BSCKII. Lê Hải Dương", "word_count": 2812, "line_count": 253, "key_numbers": ["13cm", "18 tháng", "1cm", "2 tuần", "2,5cm", "2cm", "3,5cm", "4,5cm", "6 tháng"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["SỨC KHOẺ SINH SẢN VỊ THÀNH NIÊN"], "bullets": []}, {"heading": "1. ĐẠI CƯƠNG", "paragraphs": ["Tuổi vị thành niên (VTN) là những người ở sau tuổi thiếu nhi và trước tuổi trưởng thành. Đây là giai đoạn chuyển tiếp nhưng là một giai đoạn khác biệt và quan trọng trong cuộc sống con người. Giai đoạn này có rất nhiều thay đổi về tâm sinh lý, bước đầu hình thành nhân cách và là giai đoạn đánh dấu bước phát triển lớn từ phạm vi gia đình, họ bước đầu gia nhập vào xã hội cộng đồng, vào tập thể cùng nhóm tuổi và phát triển những kỹ năng. Với những đặc điểm sinh lý riêng biệt, họ muốn khẳng định mình nên dễ thay đổi tính cách, hành vi ứng xử. Sự thay đổi và phát triển này phụ thuộc rất nhiều vào các phong tục tập quán dân tộc của các nước mà trong từng nước, từng dân tộc lại có nhiều yếu tố ảnh hưởng đến sự phát triển.", "Năm 1998, Tổ chức y tế thế giới (WHO), Quỹ nhi đồng liên hiệp quốc (UNICEF) và Quỹ dân số liên hiệp quốc (UNFPA) đã thống nhất phân loại nam nữ còn trẻ tuổi thành 3 loại: vị thành niên (adolescent) 10-19 tuổi, thanh niên (youth) 15-24 tuổi, người trẻ (young people) 10-24 tuổi. Với định nghĩa này, vị thành niên (VTN) chiếm 20% dân số thế giới.", "Tuổi VTN được phân định thành 3 giai đoạn (hoặc 3 nhóm):"], "bullets": ["- VTN sớm:           từ 10-14 tuổi.", "- VTN trung bình: từ 15 - 17 tuổi.", "- VTN muộn:         từ 18 - 19 tuổi."]}, {"heading": "2.1. Sự thay đổi thể chất", "paragraphs": ["Nữ", "Nam"], "bullets": []}, {"heading": "1. Sự thay đổi đầu tiên", "paragraphs": ["Sự phát triển của tinh hoàn:"], "bullets": ["- Bắt đầu từ  8-13 tuổi.", "- Trung bình 15 tuổi.", "- Hoàn tất 13-18 tuổi.", "- Biểu hiện:", "+ Từ núm vú nhỏ đã nhô lên rõ hơn và hình thành quầng vú và bầu vú.", "+ Có thể một vú hơi to hơn bên đối diện, đó là hiện tượng bình thường.", "+ Vú phát triển đầy đủ sau 18 tháng.", "- Bắt đầu từ  10-15 tuổi.", "- Hoàn tất năm 15-18 tuổi", "- Biểu hiện:", "+ Tinh hoàn to lên.", "+ Da bìu màu đỏ, nhiều nếp nhăn.", "+ Tăng kích thước các ống sinh tinh.", "+ Sự thay đổi các tế bào trên các ống sinh tinh.", "+ Bắt đầu sản xuất tinh trùng."]}, {"heading": "2. Khung      chậu", "paragraphs": ["Khung chậu nữ tròn hơn và rộng hơn so với khung chậu của nam."], "bullets": []}, {"heading": "3. Phát triển hệ thống lông mu và lông nách.", "paragraphs": [], "bullets": ["- Lông mu mọc qua 5 giai đoạn:", "+ Lông tơ.", "+ Lông bắt đầu mọc thẳng.", "+ Lông bắt đầu xoăn và mọc về phía sau.", "+ Lông mọc rộng ra: thời gian 5-6 tháng.", "+ Hoàn chỉnh mọc tới vùng bẹn nhưng không vượt quá vòm mu, thời gian này kéo dài 18 tháng.", "- Chú ý: nếu lông mọc vượt quá vòm mu hoặc lên đến tận rốn cần xem có bị nam tính hoá hay không? Đôi khi là bình thường do di truyền.", "- Xuất hiện: 10-15 tuổi.", "- Lông mu thô, sẫm màu cong lên và mọc cao lên vùng bụng.", "- Lông nách: mọc như lông mu.", "- Râu: lúc đầu mọc ở góc môi rồi lan ra khắp môi trên, sau đó đến phần trên của má, và vùng môi dưới, dưới cằm. Số lượng lông ở mặt do di truyền."]}, {"heading": "4. Phát triển về chiều cao và cân nặng.", "paragraphs": [], "bullets": ["- Bắt đầu từ 10-11 tuổi.", "- Đạt đỉnh cao 12-13 tuổi.", "- Kết thúc 14-15 tuổi.", "- Sau 18 tuổi: ít phát triển chiều cao.", "- Chỉ phát triển nhanh hơn phần thân của cơ thể.", "- Cân nặng tăng không tương xứng với chiều cao.", "- Khi cơ quan sinh dục bắt đầu phát triển thì chiều cao phát triển nhanh hơn.", "- Nam phát triển nhiều nhất, chiều cao có thể tăng  từ 8-13cm.", "- Ngực và vú phát triển.", "- Các cơ vân chắc.", "- Cơ cánh tay đang phát triển rắn chắc."]}, {"heading": "5. Thay đổi về giọng nói.", "paragraphs": ["Tiếng nói trong và nhẹ, thanh hơn."], "bullets": ["- Thay đổi sớm: vỡ giọng xuất hiện trước khi xuất tinh lần đầu.", "- Giọng nói trở nên trầm sau khi lông nách, lông mu và chiều cao phát triển đầy đủ."]}, {"heading": "6. Hoạt động của tuyến bã", "paragraphs": ["Hoạt động tiết androgen cho cả nam và nữ, hậu quả là:"], "bullets": ["+ Tăng độ dày của da.", "+ Kích thích các tuyến bã phát triển.", "+ Các lỗ tuyến bã bít kín lại, phồng lên tạo thành trứng cá.", "+ Nếu trứng cá bị nhiễm khuẩn tạo thành mụn mủ.", "+ Mụn mủ và trứng cá làm họ lo ngại, càng nặn càng dễ bị nhiễm khuẩn.", "+ Tiết ra mùi đặc trưng cho từng cá thể."]}, {"heading": "7. Hoàn chỉnh sự phát triển cơ quan sinh dục.", "paragraphs": ["Âm hộ", "Âm đạo", "Tử cung", "Buồng trứng to lên,dài 3,5cm, rộng 2cm, dày 1cm.", "Hình 1. Các giai đoạn phát triển của vú ở nữ theo Marshall và Tanner", "Hình 2. Các giai đoạn phát triển lông mu ở nữ theo Marshall và Tanner"], "bullets": ["- Trẻ em hướng ra trước, nay hướng từ trên xuống dưới.", "- Da đổi màu thẫm hơn.", "- Tư thế đứng chỉ thấy được phần mu ở phần trước.", "- Môi bé và âm vật tăng sắc tố.", "- Môi bé phát triển.", "- Lớn hơn, thành dày hơn.", "- Môi trường từ kiềm chuyển dần sang  axít.", "- To hơn, thành dày hơn.", "- Tỉ lệ thân và CTC cũng thay đổi.", "+ Trẻ em: CTC và thân dài bằng nhau.", "+ VTN: thân dài gấp 2 lần CTC.", "- Mỗi bên có khoảng 500.000 nang nguyên thuỷ.", "- Mỗi tháng có 1 nang chín và phóng noãn.", "- Tinh hoàn trưởng thành dài 4,5cm, rộng 2,5cm", "- Da bìu nhăn nhiều hơn và trở thành màu đen hơn.", "- Dương vật bắt đầu phát triển ở tuổi 10,5-14 tuổi và hoàn thiện từ 12,5-16,5 tuổi. Tuy nhiên sự phát triển của dương vật còn phụ thuộc vào chủng người, dân tộc."]}, {"heading": "2.2.1. Nữ giới", "paragraphs": ["Trong khoảng 1 năm đầu: vòng kinh thường không có phóng noãn nên kinh nguyệt không đều, thời gian hành kinh cũng thay đổi."], "bullets": ["- Hoạt động ngoại tiết: thông thường hàng tháng 1 nang noãn phát triển đến trưởng thành, sau 2 tuần nang vỡ (phóng noãn), phần vỏ nang phát triển thành hoàng thể.", "- Hoạt động nội tiết: nang noãn tiết estrogen. Hoàng thể tiết progesteron."]}, {"heading": "2.2.2. Nam giới", "paragraphs": [], "bullets": ["- Hoạt động ngoại tiết", "+ Tinh bào được sản xuất từ ống sinh tinh trở thành tiền tinh trùng, qua mào tinh thành tinh trùng trưởng thành.", "+ Tinh trùng được tập kết tại túi tinh.", "- Hoạt động nội tiết:", "+ Tinh hoàn tiết testosteron.", "+ Túi tinh và tuyến tiền liệt sản xuất phần lỏng của tinh tương.", "+ Biểu hiện xuất tinh, những lần đầu là mộng tinh (xuất tinh khi ngủ).", "+ Tinh trùng được sản xuất liên tục."]}, {"heading": "2.3. Thay đổi về tâm lý ở tuổi VTN", "paragraphs": ["Bên cạnh những thay đổi về thể chất và sinh lý, lứa tuổi này có thể có những thay đổi về tâm lý được thể hiện như sau:"], "bullets": []}, {"heading": "2.3.1. Tính độc lập", "paragraphs": [], "bullets": ["- Bắt đầu có xu hướng tách ra, ít phụ thuộc vào cha mẹ.", "- Chuyển từ sinh hoạt gia đình, sang sinh hoạt bạn bè, tín ngưỡng để đạt được sự độc lập.", "- Đôi khi chống đối lại bố mẹ: Đây là một lĩnh vực cần quan tâm nhưng phải kiên trì, mềm dẻo, linh hoạt uốn nắn để tránh chạm tự ái đến tổn thương tinh thần."]}, {"heading": "2.3.2. Nhân cách", "paragraphs": [], "bullets": ["- Cố gắng khẳng định mình như một người lớn vì vậy có những hành vi bắt chước người lớn.", "- Thường tự đặt câu hỏi: Ta là ai? Ta có thể làm được cái gì.", "- Nhân cách giới cũng được phát triển."]}, {"heading": "2.3.3. Tình cảm", "paragraphs": [], "bullets": ["- Chuẩn bị cho mối quan hệ yêu đương: xuất hiện tình yêu bạn bè, khó phân biệt đâu là tình yêu, đâu là bạn bè. Dễ mơ mộng. Khi đổ vỡ niềm tin dễ chán nản.", "- Học cách biểu lộ tình cảm và điều khiển cảm xúc.", "- Phát triển khả năng yêu và được yêu.", "- Tỏ thái độ thân mật trong quan hệ với người khác."]}, {"heading": "2.3.4. Tính tích hợp", "paragraphs": ["Những thông tin thu thập được từ cha mẹ, nhà trường, xã hội, bạn bè, người trung gian, các hoạt động văn hoá là cơ sở để tạo ra giá trị của bản thân tạo niềm tự tin và cách ứng xử."], "bullets": []}, {"heading": "2.3.5. Trí tuệ", "paragraphs": ["Liên tục được phát triển từ những thu nhập và tích luỹ các kiến thức nhà trường, xã hội đến thay đổi những suy nghĩ. VTN thường thích lập luận, suy diễn nhìn sự vật theo quan điểm lý tưởng hoá. Giai đoạn phát triển đặc biệt này chịu ảnh hưởng rất mạnh mẽ của các điều kiện văn hoá, giáo dục, kinh tế của môi trường gia đình và xã hội đồng thời cũng là giai đoạn gây nhiều lo ngại cho các bậc cha mẹ và cho cộng đồng.  Tuổi VTN ở mỗi nền văn hoá có những đặc điểm riêng nhưng nói chung còn bộc lộ tính phụ thuộc, sự khủng hoảng về nhân cách và hoang mang về tâm lý mà như nhiều người đã nhận xét, các em đang muốn khám phá chính mình “Tôi là ai ?”.  Tuy trưởng thành về mặt cơ thể nhưng VTN còn phải được giúp đỡ, giáo dục để hình thành nhân cách xã hội và phát triển đúng hướng."], "bullets": []}, {"heading": "3. NHỮNG NGUY CƠ VỀ SỨC KHOẺ DO THAI NGHÉN VÀ CÁC BỆNH LÂY TRUYỀN ĐƯỜNG TÌNH DỤC Ở TUỔI VTN.", "paragraphs": ["Hành vi tình dục ở độ tuổi vị thành niên thường không kiểm soát và thường dẫn đến thai nghén ngoài ý muốn. Do sự phát triển cơ thể chưa hoàn chỉnh, mang thai tuổi vị thành niên có liên quan đến một số hậu quả nghiêm trọng cho sức khoẻ tình dục như nạo phá thai, sẩy thai, sinh thiếu cân, đẻ non, thai nhỏ so với tuổi thai, tử vong mẹ.", "Chính sự mang thai ở tuổi VTN lại ảnh hưởng nặng nề đến sự phát triển thể chất và tâm sinh lý cũng như phát triển trí tuệ sau này.", "Quan hệ tình dục không an toàn có nguy cơ mắc các bệnh lây truyền qua đường tình dục trong thanh thiếu niên đang là nỗi lo ngại của cộng đồng (lậu, giang mai, HIV...).", "Hậu quả về kinh tế, xã hội với vấn đề thai sản và sinh đẻ ở tuổi VTN bao gồm:"], "bullets": ["- Hạn chế khả năng học tập hoặc bỏ học dẫn đến giảm cơ hội tìm được việc làm tốt hoặc từ bỏ quyền làm mẹ, có khi giết đứa trẻ mới sinh hoặc bi quan tự sát, làm gái mại dâm...  Điều kiện kinh tế khó khăn sẽ ảnh hưởng chất lượng cuộc sống của cả mẹ và con.", "- Nhà nước phải chi trả trực tiếp trợ cấp về y tế, xã hội để giải quyết khó khăn cho mẹ và con.", "- Làm tăng tốc độ phát triển dân số."]}, {"heading": "4.1. Thông tin giáo dục truyền thông", "paragraphs": ["Xác định thái độ trách nhiệm của gia đình và xã hội đối với VTN.", "Chú trọng vào thiết kế chương trình có sự tham gia của vị thành niên và cộng đồng", "Đảm bảo tính bí mật thông tin, giải quyết các vấn đề tâm lý, nhận thức cũng như những nhu cầu thiết thực trong cuộc sống.", "Tư vấn phải đảm bảo không phán xét, tập trung tìm hiểu các yếu tố nguy cơ của một số tình trạng như: nghiện hút, tự tử, có thai ngoài ý muốn, bệnh lây truyền QĐTD...", "Tư vấn và giáo dục phải đảm bảo giúp cho vị thành niên tự lựa chọn các biện pháp tránh thai khi đã được cung cấp đầy đủ thông tin: biện pháp tránh thai bằng hóc môn, bao cao su hoặc kiêng quan hệ tình dục."], "bullets": ["- Đáp ứng những nhu cầu thông tin và những dịch vụ VTN cần biết."]}, {"heading": "4.2. Mục đích của việc giáo dục giới tính", "paragraphs": [], "bullets": ["- Sự hài hoà giữa quyền lợi cá nhân và trách nhiệm xã hội.", "- Xây dựng mối quan hệ nhân văn và có trách nhiệm bình đẳng giữa nam và nữ.", "- Yêu đương lành mạnh."]}, {"heading": "4.3. Nội dung thông tin giáo dục truyền thông", "paragraphs": ["Vị thành niên cần nhận được những hướng dẫn về sức khoẻ để có những hiểu biết tốt hơn về tâm sinh lý cũng như sự phát triển tâm lý tình dục của họ. Những hướng dẫn đó phải nhấn mạnh vào những chiến lược để nâng cao sức khoẻ và giảm thiểu nguy cơ.", "TÓM TẮT CÁC GIAI ĐOẠN PHÁT TRIỂN CỦA TUỔI VTN", "Sức lớn", "Sớm  (10-14 tuổi)", "Trung bình (15-17 tuổi)", "Muộn (18-19 tuổi)", "Nhận thức", "Tâm lý xã hội", "Gia đình", "Tư duy"], "bullets": ["- Giáo dục về giới tính, sức khoẻ tình dục và sinh sản ở tuổi VTN.", "- Những nguy cơ do thai sản ở tuổi VTN.", "- Cung cấp các thông tin về tránh thai ngoài ý muốn và phá thai không an toàn.", "- Cung cấp các thông tin và cách phòng tránh các bệnh LTQĐTD.", "- Phổ biến vệ sinh kinh nguyệt, vệ sinh bộ phận sinh dục.", "- Những nguy cơ dẫn đến vô sinh.", "- Giải thích các nguy cơ nghiện hút ma tuý.", "- Giải thích những đồn đại không đúng về tuổi VTN.", "-Tính sinh dục phụ phát sinh, phát triển.", "- Độ lớn tăng nhanh đến điểm cao nhất.", "- Phóng noãn và sản sinh tinh trùng.", "- Tính sinh dục phụ phát triển.", "- Độ lớn giảm dần và đạt được khoảng 95% mức người lớn", "- Phóng noãn và sinh tinh", "- Cơ thể đã trưởng thành", "- Trẻ gái hầu hết đã hành kinh.", "- Trẻ nam trưởng thành về sinh dục.", "- Suy nghĩ về những việc cụ thể.", "- Có định hướng của sự tồn tại", "- Chưa nhận thức các việc làm lâu dài.", "- Suy nghĩ trừu tượng hơn.", "- Quay lại tư duy cụ thể khi bị sức ép.", "- Cân nhắc việc lâu dài", "- Đã hình thành tư duy trừu tượng.", "- Hướng về tương lai", "- Nhận thức định hướng lâu dài.", "- Ưu tư suy nghĩ vì thân hình phát triển nhanh quá.", "- Quan tâm nhiều đến sự phát triển của cơ thể.", "- Xác định ranh giới của sự độc lập và phụ thuộc.", "- Hình ảnh đẹp đẽ con người.", "- Mở rộng và lý tưởng hoá", "- Cảm giác toàn năng.", "- Xung khắc, xung đột.", "- Kiềm chế và nhẫn nhục.", "- Xác định việc hình thành trí tuệ cá nhân", "- Chuyển đổi quan hệ  giữa cha mẹ con cái thành quan hệ người lớn và người lớn.", "- So sánh mình với bạn bè cùng lứa.", "- Tìm kiếm tính ổn định.", "- Xác định nhu cầu để khẳng định bản thân mình.", "- Nhóm cùng lứa tuổi xác định cách cư xử.", "- Nhóm cùng tuổi thoái lui dần.", "- Tình bạn cá thể với cá thể phát triển.", "- Tự tiến tới và tự    đánh giá.", "- Tò mò muốn biết rõ.", "- Tự tìm hiểu.", "- Vấn vương những chuyện mơ tưởng lãng mạn.", "- Khả năng hấp dẫn người khác.", "- Hình thành quan hệ bền vững giúp đỡ lẫn nhau.", "- Quan hệ 2 chiều.", "- Suy nghĩ đến kế hoạch cho tương lai."]}], "raw_text": "SỨC KHOẺ SINH SẢN VỊ THÀNH NIÊN\n\nMục tiêu học tập\n1. Định nghĩa và phân loại được tuổi vị thành niên (VTN).\n2. Trình bày được sự phát triển thể chất và thay đổi sinh lý ở tuổi VTN.\n3. Nêu được những nguy cơ về sức khoẻ do thai nghén và bệnh lây truyền đường tình dục ở tuổi VTN.\n\n1. ĐẠI CƯƠNG\nTuổi vị thành niên (VTN) là những người ở sau tuổi thiếu nhi và trước tuổi trưởng thành. Đây là giai đoạn chuyển tiếp nhưng là một giai đoạn khác biệt và quan trọng trong cuộc sống con người. Giai đoạn này có rất nhiều thay đổi về tâm sinh lý, bước đầu hình thành nhân cách và là giai đoạn đánh dấu bước phát triển lớn từ phạm vi gia đình, họ bước đầu gia nhập vào xã hội cộng đồng, vào tập thể cùng nhóm tuổi và phát triển những kỹ năng. Với những đặc điểm sinh lý riêng biệt, họ muốn khẳng định mình nên dễ thay đổi tính cách, hành vi ứng xử. Sự thay đổi và phát triển này phụ thuộc rất nhiều vào các phong tục tập quán dân tộc của các nước mà trong từng nước, từng dân tộc lại có nhiều yếu tố ảnh hưởng đến sự phát triển.\nNăm 1998, Tổ chức y tế thế giới (WHO), Quỹ nhi đồng liên hiệp quốc (UNICEF) và Quỹ dân số liên hiệp quốc (UNFPA) đã thống nhất phân loại nam nữ còn trẻ tuổi thành 3 loại: vị thành niên (adolescent) 10-19 tuổi, thanh niên (youth) 15-24 tuổi, người trẻ (young people) 10-24 tuổi. Với định nghĩa này, vị thành niên (VTN) chiếm 20% dân số thế giới.\nTuổi VTN được phân định thành 3 giai đoạn (hoặc 3 nhóm):\n- VTN sớm:           từ 10-14 tuổi.\n- VTN trung bình: từ 15 - 17 tuổi.\n- VTN muộn:         từ 18 - 19 tuổi.\n\n2. SỰ THAY ĐỔI THỂ CHẤT VÀ TÂM SINH LÝ Ở TUỔI VTN\n2.1. Sự thay đổi thể chất\n\n\nNữ\nNam\n\n1. Sự thay đổi đầu tiên\n- Bắt đầu từ  8-13 tuổi.\n- Trung bình 15 tuổi.\n- Hoàn tất 13-18 tuổi.\n- Biểu hiện:\n+ Từ núm vú nhỏ đã nhô lên rõ hơn và hình thành quầng vú và bầu vú.\n+ Có thể một vú hơi to hơn bên đối diện, đó là hiện tượng bình thường.\n+ Vú phát triển đầy đủ sau 18 tháng.\nSự phát triển của tinh hoàn:\n- Bắt đầu từ  10-15 tuổi.\n- Hoàn tất năm 15-18 tuổi\n- Biểu hiện:\n+ Tinh hoàn to lên.\n+ Da bìu màu đỏ, nhiều nếp nhăn.\n+ Tăng kích thước các ống sinh tinh.\n+ Sự thay đổi các tế bào trên các ống sinh tinh.\n+ Bắt đầu sản xuất tinh trùng.\n\n2. Khung      chậu\nKhung chậu nữ tròn hơn và rộng hơn so với khung chậu của nam.\n\n\n3. Phát triển hệ thống lông mu và lông nách.\n- Lông mu mọc qua 5 giai đoạn:\n+ Lông tơ.\n+ Lông bắt đầu mọc thẳng.\n+ Lông bắt đầu xoăn và mọc về phía sau.\n+ Lông mọc rộng ra: thời gian 5-6 tháng.\n+ Hoàn chỉnh mọc tới vùng bẹn nhưng không vượt quá vòm mu, thời gian này kéo dài 18 tháng.\n- Chú ý: nếu lông mọc vượt quá vòm mu hoặc lên đến tận rốn cần xem có bị nam tính hoá hay không? Đôi khi là bình thường do di truyền.\n- Xuất hiện: 10-15 tuổi.\n- Lông mu thô, sẫm màu cong lên và mọc cao lên vùng bụng.\n- Lông nách: mọc như lông mu.\n- Râu: lúc đầu mọc ở góc môi rồi lan ra khắp môi trên, sau đó đến phần trên của má, và vùng môi dưới, dưới cằm. Số lượng lông ở mặt do di truyền.\n\n4. Phát triển về chiều cao và cân nặng.\n- Bắt đầu từ 10-11 tuổi.\n- Đạt đỉnh cao 12-13 tuổi.\n- Kết thúc 14-15 tuổi.\n- Sau 18 tuổi: ít phát triển chiều cao.\n- Chỉ phát triển nhanh hơn phần thân của cơ thể.\n- Cân nặng tăng không tương xứng với chiều cao.\n- Khi cơ quan sinh dục bắt đầu phát triển thì chiều cao phát triển nhanh hơn.\n- Nam phát triển nhiều nhất, chiều cao có thể tăng  từ 8-13cm.\n- Ngực và vú phát triển.\n- Các cơ vân chắc.\n- Cơ cánh tay đang phát triển rắn chắc.\n\n5. Thay đổi về giọng nói.\nTiếng nói trong và nhẹ, thanh hơn.\n- Thay đổi sớm: vỡ giọng xuất hiện trước khi xuất tinh lần đầu.\n- Giọng nói trở nên trầm sau khi lông nách, lông mu và chiều cao phát triển đầy đủ.\n\n6. Hoạt động của tuyến bã\nHoạt động tiết androgen cho cả nam và nữ, hậu quả là:\n+ Tăng độ dày của da.\n+ Kích thích các tuyến bã phát triển.\n+ Các lỗ tuyến bã bít kín lại, phồng lên tạo thành trứng cá.\n+ Nếu trứng cá bị nhiễm khuẩn tạo thành mụn mủ.\n+ Mụn mủ và trứng cá làm họ lo ngại, càng nặn càng dễ bị nhiễm khuẩn.\n+ Tiết ra mùi đặc trưng cho từng cá thể.\n\n7. Hoàn chỉnh sự phát triển cơ quan sinh dục.\nÂm hộ\n- Trẻ em hướng ra trước, nay hướng từ trên xuống dưới.\n- Da đổi màu thẫm hơn.\n- Tư thế đứng chỉ thấy được phần mu ở phần trước.\n- Môi bé và âm vật tăng sắc tố.\n- Môi bé phát triển.\nÂm đạo\n- Lớn hơn, thành dày hơn.\n- Môi trường từ kiềm chuyển dần sang  axít.\nTử cung\n- To hơn, thành dày hơn.\n- Tỉ lệ thân và CTC cũng thay đổi.\n+ Trẻ em: CTC và thân dài bằng nhau.\n+ VTN: thân dài gấp 2 lần CTC.\nBuồng trứng to lên,dài 3,5cm, rộng 2cm, dày 1cm.\n- Mỗi bên có khoảng 500.000 nang nguyên thuỷ.\n- Mỗi tháng có 1 nang chín và phóng noãn.\n- Tinh hoàn trưởng thành dài 4,5cm, rộng 2,5cm\n- Da bìu nhăn nhiều hơn và trở thành màu đen hơn.\n- Dương vật bắt đầu phát triển ở tuổi 10,5-14 tuổi và hoàn thiện từ 12,5-16,5 tuổi. Tuy nhiên sự phát triển của dương vật còn phụ thuộc vào chủng người, dân tộc.\n\n\n\nHình 1. Các giai đoạn phát triển của vú ở nữ theo Marshall và Tanner\n\n\nHình 2. Các giai đoạn phát triển lông mu ở nữ theo Marshall và Tanner\n\n\n2.2. Thay đổi sinh lý ở tuổi VTN\n2.2.1. Nữ giới\n- Hoạt động ngoại tiết: thông thường hàng tháng 1 nang noãn phát triển đến trưởng thành, sau 2 tuần nang vỡ (phóng noãn), phần vỏ nang phát triển thành hoàng thể.\n- Hoạt động nội tiết: nang noãn tiết estrogen. Hoàng thể tiết progesteron.\nTrong khoảng 1 năm đầu: vòng kinh thường không có phóng noãn nên kinh nguyệt không đều, thời gian hành kinh cũng thay đổi.\n2.2.2. Nam giới\n- Hoạt động ngoại tiết\n+ Tinh bào được sản xuất từ ống sinh tinh trở thành tiền tinh trùng, qua mào tinh thành tinh trùng trưởng thành.\n+ Tinh trùng được tập kết tại túi tinh.\n- Hoạt động nội tiết:\n+ Tinh hoàn tiết testosteron.\n+ Túi tinh và tuyến tiền liệt sản xuất phần lỏng của tinh tương.\n+ Biểu hiện xuất tinh, những lần đầu là mộng tinh (xuất tinh khi ngủ).\n+ Tinh trùng được sản xuất liên tục.\n2.3. Thay đổi về tâm lý ở tuổi VTN\nBên cạnh những thay đổi về thể chất và sinh lý, lứa tuổi này có thể có những thay đổi về tâm lý được thể hiện như sau:\n2.3.1. Tính độc lập\n- Bắt đầu có xu hướng tách ra, ít phụ thuộc vào cha mẹ.\n- Chuyển từ sinh hoạt gia đình, sang sinh hoạt bạn bè, tín ngưỡng để đạt được sự độc lập.\n- Đôi khi chống đối lại bố mẹ: Đây là một lĩnh vực cần quan tâm nhưng phải kiên trì, mềm dẻo, linh hoạt uốn nắn để tránh chạm tự ái đến tổn thương tinh thần.\n2.3.2. Nhân cách\n- Cố gắng khẳng định mình như một người lớn vì vậy có những hành vi bắt chước người lớn.\n- Thường tự đặt câu hỏi: Ta là ai? Ta có thể làm được cái gì.\n- Nhân cách giới cũng được phát triển.\n2.3.3. Tình cảm\n- Chuẩn bị cho mối quan hệ yêu đương: xuất hiện tình yêu bạn bè, khó phân biệt đâu là tình yêu, đâu là bạn bè. Dễ mơ mộng. Khi đổ vỡ niềm tin dễ chán nản.\n- Học cách biểu lộ tình cảm và điều khiển cảm xúc.\n- Phát triển khả năng yêu và được yêu.\n- Tỏ thái độ thân mật trong quan hệ với người khác.\n2.3.4. Tính tích hợp\nNhững thông tin thu thập được từ cha mẹ, nhà trường, xã hội, bạn bè, người trung gian, các hoạt động văn hoá là cơ sở để tạo ra giá trị của bản thân tạo niềm tự tin và cách ứng xử.\n2.3.5. Trí tuệ\nLiên tục được phát triển từ những thu nhập và tích luỹ các kiến thức nhà trường, xã hội đến thay đổi những suy nghĩ. VTN thường thích lập luận, suy diễn nhìn sự vật theo quan điểm lý tưởng hoá. Giai đoạn phát triển đặc biệt này chịu ảnh hưởng rất mạnh mẽ của các điều kiện văn hoá, giáo dục, kinh tế của môi trường gia đình và xã hội đồng thời cũng là giai đoạn gây nhiều lo ngại cho các bậc cha mẹ và cho cộng đồng.  Tuổi VTN ở mỗi nền văn hoá có những đặc điểm riêng nhưng nói chung còn bộc lộ tính phụ thuộc, sự khủng hoảng về nhân cách và hoang mang về tâm lý mà như nhiều người đã nhận xét, các em đang muốn khám phá chính mình “Tôi là ai ?”.  Tuy trưởng thành về mặt cơ thể nhưng VTN còn phải được giúp đỡ, giáo dục để hình thành nhân cách xã hội và phát triển đúng hướng.\n\n\n\n3. NHỮNG NGUY CƠ VỀ SỨC KHOẺ DO THAI NGHÉN VÀ CÁC BỆNH LÂY TRUYỀN ĐƯỜNG TÌNH DỤC Ở TUỔI VTN.\nHành vi tình dục ở độ tuổi vị thành niên thường không kiểm soát và thường dẫn đến thai nghén ngoài ý muốn. Do sự phát triển cơ thể chưa hoàn chỉnh, mang thai tuổi vị thành niên có liên quan đến một số hậu quả nghiêm trọng cho sức khoẻ tình dục như nạo phá thai, sẩy thai, sinh thiếu cân, đẻ non, thai nhỏ so với tuổi thai, tử vong mẹ.\nChính sự mang thai ở tuổi VTN lại ảnh hưởng nặng nề đến sự phát triển thể chất và tâm sinh lý cũng như phát triển trí tuệ sau này.\nQuan hệ tình dục không an toàn có nguy cơ mắc các bệnh lây truyền qua đường tình dục trong thanh thiếu niên đang là nỗi lo ngại của cộng đồng (lậu, giang mai, HIV...).\nHậu quả về kinh tế, xã hội với vấn đề thai sản và sinh đẻ ở tuổi VTN bao gồm:\n- Hạn chế khả năng học tập hoặc bỏ học dẫn đến giảm cơ hội tìm được việc làm tốt hoặc từ bỏ quyền làm mẹ, có khi giết đứa trẻ mới sinh hoặc bi quan tự sát, làm gái mại dâm...  Điều kiện kinh tế khó khăn sẽ ảnh hưởng chất lượng cuộc sống của cả mẹ và con.\n- Nhà nước phải chi trả trực tiếp trợ cấp về y tế, xã hội để giải quyết khó khăn cho mẹ và con.\n- Làm tăng tốc độ phát triển dân số.\n\n4. CHĂM SÓC SỨC KHOẺ SINH SẢN Ở TUỔI VTN.\n4.1. Thông tin giáo dục truyền thông\n- Đáp ứng những nhu cầu thông tin và những dịch vụ VTN cần biết.\nXác định thái độ trách nhiệm của gia đình và xã hội đối với VTN.\nChú trọng vào thiết kế chương trình có sự tham gia của vị thành niên và cộng đồng\nĐảm bảo tính bí mật thông tin, giải quyết các vấn đề tâm lý, nhận thức cũng như những nhu cầu thiết thực trong cuộc sống.\nTư vấn phải đảm bảo không phán xét, tập trung tìm hiểu các yếu tố nguy cơ của một số tình trạng như: nghiện hút, tự tử, có thai ngoài ý muốn, bệnh lây truyền QĐTD...\nTư vấn và giáo dục phải đảm bảo giúp cho vị thành niên tự lựa chọn các biện pháp tránh thai khi đã được cung cấp đầy đủ thông tin: biện pháp tránh thai bằng hóc môn, bao cao su hoặc kiêng quan hệ tình dục.\n4.2. Mục đích của việc giáo dục giới tính\n- Sự hài hoà giữa quyền lợi cá nhân và trách nhiệm xã hội.\n- Xây dựng mối quan hệ nhân văn và có trách nhiệm bình đẳng giữa nam và nữ.\n- Yêu đương lành mạnh.\n4.3. Nội dung thông tin giáo dục truyền thông\nVị thành niên cần nhận được những hướng dẫn về sức khoẻ để có những hiểu biết tốt hơn về tâm sinh lý cũng như sự phát triển tâm lý tình dục của họ. Những hướng dẫn đó phải nhấn mạnh vào những chiến lược để nâng cao sức khoẻ và giảm thiểu nguy cơ.\n- Giáo dục về giới tính, sức khoẻ tình dục và sinh sản ở tuổi VTN.\n- Những nguy cơ do thai sản ở tuổi VTN.\n- Cung cấp các thông tin về tránh thai ngoài ý muốn và phá thai không an toàn.\n- Cung cấp các thông tin và cách phòng tránh các bệnh LTQĐTD.\n- Phổ biến vệ sinh kinh nguyệt, vệ sinh bộ phận sinh dục.\n- Những nguy cơ dẫn đến vô sinh.\n- Giải thích các nguy cơ nghiện hút ma tuý.\n- Giải thích những đồn đại không đúng về tuổi VTN.\n\n\n\n\n\n\n\nTÓM TẮT CÁC GIAI ĐOẠN PHÁT TRIỂN CỦA TUỔI VTN\nSức lớn\nSớm  (10-14 tuổi)\nTrung bình (15-17 tuổi)\nMuộn (18-19 tuổi)\n\n\n-Tính sinh dục phụ phát sinh, phát triển.\n- Độ lớn tăng nhanh đến điểm cao nhất.\n- Phóng noãn và sản sinh tinh trùng.\n- Tính sinh dục phụ phát triển.\n- Độ lớn giảm dần và đạt được khoảng 95% mức người lớn\n- Phóng noãn và sinh tinh\n- Cơ thể đã trưởng thành\n- Trẻ gái hầu hết đã hành kinh.\n- Trẻ nam trưởng thành về sinh dục.\n\nNhận thức\n- Suy nghĩ về những việc cụ thể.\n- Có định hướng của sự tồn tại\n- Chưa nhận thức các việc làm lâu dài.\n- Suy nghĩ trừu tượng hơn.\n- Quay lại tư duy cụ thể khi bị sức ép.\n- Cân nhắc việc lâu dài\n- Đã hình thành tư duy trừu tượng.\n- Hướng về tương lai\n- Nhận thức định hướng lâu dài.\n\nTâm lý xã hội\n- Ưu tư suy nghĩ vì thân hình phát triển nhanh quá.\n- Quan tâm nhiều đến sự phát triển của cơ thể.\n- Xác định ranh giới của sự độc lập và phụ thuộc.\n- Hình ảnh đẹp đẽ con người.\n- Mở rộng và lý tưởng hoá\n- Cảm giác toàn năng.\n- Xung khắc, xung đột.\n- Kiềm chế và nhẫn nhục.\n- Xác định việc hình thành trí tuệ cá nhân\n- Chuyển đổi quan hệ  giữa cha mẹ con cái thành quan hệ người lớn và người lớn.\n\nGia đình\n- So sánh mình với bạn bè cùng lứa.\n- Tìm kiếm tính ổn định.\n- Xác định nhu cầu để khẳng định bản thân mình.\n- Nhóm cùng lứa tuổi xác định cách cư xử.\n- Nhóm cùng tuổi thoái lui dần.\n- Tình bạn cá thể với cá thể phát triển.\n\nTư duy\n- Tự tiến tới và tự    đánh giá.\n- Tò mò muốn biết rõ.\n- Tự tìm hiểu.\n- Vấn vương những chuyện mơ tưởng lãng mạn.\n- Khả năng hấp dẫn người khác.\n- Hình thành quan hệ bền vững giúp đỡ lẫn nhau.\n- Quan hệ 2 chiều.\n- Suy nghĩ đến kế hoạch cho tương lai.\n\n\n\n\nCâu hỏi:\n1. Trình bày định nghĩa và phân loại tuổi vị thành niên?\n2.  Trình bày sự phát triển thể chất và thay đổi sinh lý ở tuổi vị thành niên?\n3.  Nêu những nguy cơ về sức khoẻ do thai nghén và bệnh lây truyền đường tình dục ở tuổi vị thành niên?", "priority": "Trung bình"}, {"id": "SK-53", "chapter": "Chương 6. Hỗ trợ sinh sản", "folder": "06_Ho_tro_sinh_san", "title": "Sức khoẻ sinh sản trong thời kỳ mãn kinh", "author": "THs. BSCKII. Lê Hải Dương", "word_count": 2070, "line_count": 97, "key_numbers": ["20 g", "3 cm", "5g"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["SỨC KHOẺ SINH SẢN TRONG THỜI KỲ MÃN KINH"], "bullets": []}, {"heading": "1. ĐẠI CƯƠNG", "paragraphs": ["Cuộc đời hoạt động sinh dục của người phụ nữ được chia làm bốn thời kỳ."], "bullets": []}, {"heading": "1.1 Thời kỳ trẻ em :", "paragraphs": ["Buồng trứng ở trong giai đoạn im lặng về mặt nội tiết là do sự “chưa chín muồi của vùng dưới đồi“."], "bullets": []}, {"heading": "1.2. Giai đoạn dậy thì:", "paragraphs": ["Chức năng nội tiết của buồng trứng bắt đầu hoạt động khi các tế bào thần kinh sản xuất GnRH của vùng dưới đồi đã có thể bắt đầu giải phóng GnRH một cách đồng bộ và theo xung nhịp vào hệ thống động mạch cửa tuyến yên"], "bullets": []}, {"heading": "1.3. Thời kỳ hoạt động sinh dục", "paragraphs": ["Tiếp theo tuổi dậy thì là thời kỳ hoạt động sinh dục, kéo dài đến khi mãn kinh. Trong thời kỳ này, người phụ nữ thường hành kinh đều đặn, tỉ lệ vòng kinh có phóng noãn tăng lên do hoạt động nội tiết của trục dưới đồi - tuyến yên - buồng trứng đã được hoàn chỉnh. Người phụ nữ có thể thụ thai được.", "Trong thời kỳ này, các tính chất sinh dục phụ cũng như toàn cơ thể của người phụ nữ vẫn tiếp tục phát triển đến mức tối đa. Thời kỳ hoạt động sinh dục kéo dài 30 - 35 năm."], "bullets": []}, {"heading": "1.4. Thời kỳ mãn kinh", "paragraphs": ["Mãn kinh là tình trạng không còn hành kinh của người phụ nữ. Nếu một thiếu nữ chưa hành kinh là do vùng dưới đổi hoạt động chưa chín muồi, thì một người phụ nữ không hành kinh ở tuổi mãn kinh là do buồng trứng đã suy kiệt, không còn nhạy cảm trước sự kích thích của các hormon hướng sinh dục, nên không còn chế tiết đủ hormon sinh dục. Kể từ khi mãn kinh, người phụ nữ không còn khả năng có thai nữa.", "Mãn kinh là tình trạng thôi hành kinh vĩnh viễn, một vô kinh thứ phát do suy giảm tự nhiên hoạt động của buồng trứng và không hồi phục. Tuổi mãn kinh trung bình: 45- 50.", "Người phụ nữ từ tuổi hoạt động sinh dục chuyển sang giai đoạn tắt dục và mãn kinh có một giai đoạn chuyển tiếp.Đó là giai đoạn tiền mãn kinh", "Giai đoạn tiền mãn kinh có đặc điểm hành kinh bất thường, vòng kinh có thể dài, ngắn, thường không phóng noãn. lượng máu kinh có thể nhiều, ít hoặc rong kinh. Giảm khả năng sinh dục,  thời gian có thể từ 1- 2 năm"], "bullets": []}, {"heading": "2.1. Buồng trứng", "paragraphs": [], "bullets": ["- Teo nhỏ, giảm về trọng lượng từ 20 g xuống còn 5g", "-  Về mặt mô học buồng trứng sau mãn kinh cho thấy có hiện tượng xơ hoá", "+ Số lượng nang noãn nguyên thuỷ giảm đáng kể, không còn hoạt động.", "+ Nhiều mạch máu ở rốn và tuỷ buồng trứng xơ hoá, thoái hoá"]}, {"heading": "2.2. Vòi tử cung", "paragraphs": [], "bullets": ["+\tKích thước của hai vòi tử cung giảm dần.", "+ Các lông mao giảm dần và cuối cùng là biến mất", "+  Khả năng chế tiết cũng dần mất đi.", "+  Nhu động của cơ vòi tử cung giảm đáng kể."]}, {"heading": "2.3. Tử cung", "paragraphs": [], "bullets": ["+Tử cung giảm dần kích thước và trọng lượng do mất dần lớp cơ tử cung.", "+ Thành tử cung mỏng dần, chiều cao có thể giảm còn 3 cm.", "+ Niêm mạc tử cung: mỏng, teo đét, thoái hoá"]}, {"heading": "2.4. Cổ tử cung", "paragraphs": [], "bullets": ["+ Cổ tử cung teo nhỏ dần, giảm rõ vài năm sau mãn kinh.", "+ Lớp niêm mạc ống cổ tử cung mỏng dần và nhạt màu.", "+ Lỗ cổ tử cung thu nhỏ lại, ranh giới giữa biểu mô trụ và biểu mô lát lùi sâu vào phía trong lỗ ngoài cổ tử cung.", "+ Ngay sau khi mãn kinh chất nhầy cổ tử cung có thể còn khá tốt nhưng khi nồng độ estrogen xuống thấp lượng chất nhầy sẽ giảm mạnh, chất nhầy đặc quánh, nhiều thành phần tế bào hơn và không kết tinh dương xỉ."]}, {"heading": "2.5. Âm đạo", "paragraphs": ["Sau mãn kinh các nếp gấp ngang giảm nhiều làm âm đạo dần trở nên chật hơn, ngắn hơn, các nhú quanh tiền đình và thành âm đạo trở nên phẳng. Niêm mạc âm đạo dần mỏng đi, nhạt màu, dễ bị loét trợt, giảm chế tiết và có thể phát triển các vùng dính."], "bullets": []}, {"heading": "2.6. Âm hộ", "paragraphs": ["Trong giai đoạn sớm sau mãn kinh chỉ xuất hiện một số biến đổi nhỏ ở âm hộ, nhưng các thay đổi này sẽ trở nên rõ rệt (65 tuổi trở đi). Môi lớn nhỏ lại và mỏng hơn do lớp mỡ dưới da bị mất đi, môi bé nhỏ, đôi khi mất hẳn hoặc dính lại với nhau phía dưới âm vật, âm vật nhỏ dần. Các tuyến Skene, Bartholin teo nhỏ và ngừng chế tiết. Một số trường hợp teo và xơ hoá nặng dẫn đến xơ teo âm hộ."], "bullets": []}, {"heading": "3.1. Các rối loạn vận mạch", "paragraphs": ["Cơn \"bốc hoả\": là cơn phừng nóng thoáng qua và tái diễn, kèm theo vã mồ hôi, cảm giác nóng toàn thân, hồi hộp đánh trống ngực, lo lắng, đôi khi kèm theo ớn lạnh sau đó."], "bullets": []}, {"heading": "3.2. Các thay đổi tâm lý", "paragraphs": ["Khoảng 20% các phụ nữ trong độ tuổi mãn kinh có các biểu hiện rối loạn dạng trầm cảm.", "Ở một số phụ nữ có thể gặp thay đổi tính tình, giảm ham muốn tình dục, giảm tập trung, mất ngủ."], "bullets": []}, {"heading": "3.3. Các thay đổi nội tiết", "paragraphs": ["Ở phụ nữ tiền mãn kinh - mãn kinh, buồng trứng teo nhỏ nhanh chóng và giảm số lượng noãn bào đáng kể. Buồng trứng trở nên kém nhạy cảm đối với những kích thích từ trục dưới đồi - tuyến yên dẫn đến giảm lượng 17-estradiol (E2). Đồng thời, nồng độ FSH tăng. Các androgen trong cơ thể phụ nữ bình thường được sản xuất từ tuyến thượng thận và mô liên kết của rốn và tuỷ buồng trứng. Hoạt động sản xuất androgen này vẫn tiếp tục cho đến giai đoạn sau mãn kinh. Một số mô trong cơ thể như gan, cơ, da, tử cung và đặc biệt là mô mỡ dưới da có thể chuyển hoá androgen thành estrogen nhờ men thơm hoá, chủ yếu là chuyển androstenedione thành estrone, do đó nồng độ estrone thay đổi không đáng kể sau mãn kinh."], "bullets": []}, {"heading": "4.1. Viêm âm hộ - âm đạo do thiểu dưỡng", "paragraphs": ["Khoảng 40% phụ nữ mãn kinh có triệu chứng của viêm âm đạo thiểu dưỡng, triệu chứng sớm nhất là giảm độ ẩm của môi trường âm đạo. Các triệu chứng ở âm đạo bao gồm khô, đau khi giao hợp và viêm nhiễm âm đạo tái diễn. Niêm mạc âm đạo và cổ tử cung bắt màu kém với dung dịch Lugol.", "Có nhiều yếu tố gây ra sự gia tăng rõ rệt các viêm nhiễm âm hộ - âm đạo ở độ tuổi này:", "Các triệu chứng lâm sàng có thể đơn thuần ở bộ phận sinh dục hoặc phối hợp với bệnh lý đường tiết niệu (buốt, đau khi tiểu tiện... ). Trong trường hợp có viêm âm đạo nhiễm khuẩn kèm theo, tác nhân thường gặp Gardnerella, Candida albican, vi khuẩn đường ruột (E. Coli), hiếm gặp Trichomonas vaginalis."], "bullets": ["- Thiểu năng estrogen làm giảm hệ vi khuẩn chí âm đạo, pH trở nên kiềm, tạo điều kiện cho sự xâm nhập của hệ vi khuẩn đường ruột vào môi trường âm đạo thiểu dưỡng niêm mạc âm đạo.", "- Sự suy giảm miễn dịch tế bào và miễn dịch thể dịch."]}, {"heading": "4.2. Són tiểu", "paragraphs": ["Ở phụ nữ tiền mãn kinh – mãn kinh, suy cơ thắt niệu đạo ảnh hưởng chức năng co thắt bình thường, niêm mạc niệu đạo thiểu dưỡng gây cảm giác són tiểu, tiểu lắt nhắt."], "bullets": []}, {"heading": "4.3. Loãng xương", "paragraphs": ["Như mọi tổ chức khác trong cơ thể, hệ xương cũng bị lão hoá. Các thay đổi của hệ xương xảy ra do tăng tiêu xương và kém hấp thu Canxi dẫn đến làm yếu các xương trong cơ thể, nên dễ gãy xương sau sang chấn và gãy xương bệnh lý. Có thể dự phòng loãng xương bằng một chế độ ăn giàu Canxi trong suốt đời người phụ nữ (từ thời thiếu niên) và tăng mức cung cấp sau mãn kinh và thường xuyên tập luyện thể dục tiếp sau mãn kinh."], "bullets": []}, {"heading": "4.4. Các bệnh lý hệ tim mạch", "paragraphs": ["Phụ nữ lớn tuổi có nguy cơ mắc phải các bệnh lý tim mạch với một tần suất ngày càng gia tăng. Nguyên nhân thường gặp nhất gây nên bệnh lý tim mạch của độ tuổi này là tình trạng xơ vữa mạch máu, nếu xảy ra trên thành động mạch sẽ gây nên xơ vữa động mạch. Nồng độ estrogen cao trong giai đoạn hoạt động sinh dục có vai trò bảo vệ trong các biểu hiện sớm của bệnh tim mạch thông qua một cơ chế duy trì nồng độ HDL cao và LDL thấp. Sự thiếu hụt estrogen nội sinh khi mãn kinh làm cho tỷ lệ này thay đổi theo hướng ngược lại, tạo điều kiện cho sự hình thành các tổn thương xơ vữa."], "bullets": []}, {"heading": "5.1. Ung thư niêm mạc tử cung", "paragraphs": ["Ung thư biểu mô tuyến niêm mạc tử cung phát triển trong thân tử cung, còn được gọi là ung thư thân tử cung. Đỉnh cao của bệnh ở tuổi 55 - 65.", "Chảy máu sau mãn kinh là triệu chứng thường gặp nhất và gặp sớm trong quá trình bệnh. Việc chẩn đoán dựa vào kết quả giải phẫu bệnh lý qua sinh thiết nội mạc tử cung."], "bullets": []}, {"heading": "5.2. Ung thư vú", "paragraphs": ["Cho đến nay, tình trạng tăng nồng độ estrogen kéo dài có thể là yếu tố nguy cơ gây ung thư vú. Đối với phụ nữ tiền mãn kinh – mãn kinh, nếu có ra máu âm đạo bất thường hay đau vú cần được khảo sát cẩn thận về bệnh lý tuyến vú, đặc biệt là ung thư vú."], "bullets": []}, {"heading": "5.3. Ung thư cổ tử cung", "paragraphs": ["Đây là một bệnh lý có thể gặp trong độ tuổi tiền mãn kinh – mãn kinh, nhưng nguyên nhân gây bệnh không phải do rối loạn nội tiết."], "bullets": []}, {"heading": "6.1. Các vấn đề cần tư vấn", "paragraphs": [], "bullets": ["- Khám phụ khoa định kỳ là quan trọng đối với người có tuổi", "- Cung cấp thông tin về giai đoạn tắt dục mãn kinh và tính chất bình thường của giai đoạn này trong đời người phụ nữ", "- Hỗ trợ cách đối phó với bệnh ác tính và các hậu quả của bệnh", "- Khuyên về dinh dưỡng", "- Khuyên phòng loãng xương", "- Khuyên về các hoạt động tình dục và tình dục an toàn", "- Tư vấn về các nhu cầu sau cắt bỏ vú, sau cắt tử cung.", "- Tư vấn này cần làm cho người phụ nữ và cả cho người chồng hoặc bạn tình.", "- Dinh dưỡng tốt và tập thể dục trong suốt cuộc đời sinh sản của phụ nữ sẽ phòng được một số vấn đề gặp sau mãn kinh cũng như cần có thói quen tiếp tục tập luyện khi đã có tuổi."]}], "raw_text": "SỨC KHOẺ SINH SẢN TRONG THỜI KỲ MÃN KINH\n\nMục tiêu bài học\n1. Trình bày được các thay đổi giải phẫu ở buồng trứng, âm hộ, âm đạo của người phụ nữ  trong thời kỳ mãn kinh.\n2. Trình bày được các thay đổi về nội tiết và tâm sinh lý của người phụ nữ  trong thời kỳ mãn kinh\n3. Trình bày được các bệnh lý thường gặp trong thời kỳ mãn kinh.\n\n1. ĐẠI CƯƠNG\n\nCuộc đời hoạt động sinh dục của người phụ nữ được chia làm bốn thời kỳ.\n1.1 Thời kỳ trẻ em :\nBuồng trứng ở trong giai đoạn im lặng về mặt nội tiết là do sự “chưa chín muồi của vùng dưới đồi“.\n1.2. Giai đoạn dậy thì:\nChức năng nội tiết của buồng trứng bắt đầu hoạt động khi các tế bào thần kinh sản xuất GnRH của vùng dưới đồi đã có thể bắt đầu giải phóng GnRH một cách đồng bộ và theo xung nhịp vào hệ thống động mạch cửa tuyến yên\n1.3. Thời kỳ hoạt động sinh dục\nTiếp theo tuổi dậy thì là thời kỳ hoạt động sinh dục, kéo dài đến khi mãn kinh. Trong thời kỳ này, người phụ nữ thường hành kinh đều đặn, tỉ lệ vòng kinh có phóng noãn tăng lên do hoạt động nội tiết của trục dưới đồi - tuyến yên - buồng trứng đã được hoàn chỉnh. Người phụ nữ có thể thụ thai được.\nTrong thời kỳ này, các tính chất sinh dục phụ cũng như toàn cơ thể của người phụ nữ vẫn tiếp tục phát triển đến mức tối đa. Thời kỳ hoạt động sinh dục kéo dài 30 - 35 năm.\n1.4. Thời kỳ mãn kinh\nMãn kinh là tình trạng không còn hành kinh của người phụ nữ. Nếu một thiếu nữ chưa hành kinh là do vùng dưới đổi hoạt động chưa chín muồi, thì một người phụ nữ không hành kinh ở tuổi mãn kinh là do buồng trứng đã suy kiệt, không còn nhạy cảm trước sự kích thích của các hormon hướng sinh dục, nên không còn chế tiết đủ hormon sinh dục. Kể từ khi mãn kinh, người phụ nữ không còn khả năng có thai nữa.\nMãn kinh là tình trạng thôi hành kinh vĩnh viễn, một vô kinh thứ phát do suy giảm tự nhiên hoạt động của buồng trứng và không hồi phục. Tuổi mãn kinh trung bình: 45- 50.\nNgười phụ nữ từ tuổi hoạt động sinh dục chuyển sang giai đoạn tắt dục và mãn kinh có một giai đoạn chuyển tiếp.Đó là giai đoạn tiền mãn kinh\nGiai đoạn tiền mãn kinh có đặc điểm hành kinh bất thường, vòng kinh có thể dài, ngắn, thường không phóng noãn. lượng máu kinh có thể nhiều, ít hoặc rong kinh. Giảm khả năng sinh dục,  thời gian có thể từ 1- 2 năm\n\n2. MỘT SỐ THAY ĐỔI VỀ GIẢI PHẪU HỌC CỦA CƠ QUAN SINH DỤC NỮ\n2.1. Buồng trứng\n- Teo nhỏ, giảm về trọng lượng từ 20 g xuống còn 5g\n-  Về mặt mô học buồng trứng sau mãn kinh cho thấy có hiện tượng xơ hoá\n+ Số lượng nang noãn nguyên thuỷ giảm đáng kể, không còn hoạt động.\n+ Nhiều mạch máu ở rốn và tuỷ buồng trứng xơ hoá, thoái hoá\n2.2. Vòi tử cung\n+\tKích thước của hai vòi tử cung giảm dần.\n+ Các lông mao giảm dần và cuối cùng là biến mất\n+  Khả năng chế tiết cũng dần mất đi.\n+  Nhu động của cơ vòi tử cung giảm đáng kể.\n2.3. Tử cung\n+Tử cung giảm dần kích thước và trọng lượng do mất dần lớp cơ tử cung.\n+ Thành tử cung mỏng dần, chiều cao có thể giảm còn 3 cm.\n+ Niêm mạc tử cung: mỏng, teo đét, thoái hoá\n2.4. Cổ tử cung\n+ Cổ tử cung teo nhỏ dần, giảm rõ vài năm sau mãn kinh.\n+ Lớp niêm mạc ống cổ tử cung mỏng dần và nhạt màu.\n+ Lỗ cổ tử cung thu nhỏ lại, ranh giới giữa biểu mô trụ và biểu mô lát lùi sâu vào phía trong lỗ ngoài cổ tử cung.\n+ Ngay sau khi mãn kinh chất nhầy cổ tử cung có thể còn khá tốt nhưng khi nồng độ estrogen xuống thấp lượng chất nhầy sẽ giảm mạnh, chất nhầy đặc quánh, nhiều thành phần tế bào hơn và không kết tinh dương xỉ.\n2.5. Âm đạo\nSau mãn kinh các nếp gấp ngang giảm nhiều làm âm đạo dần trở nên chật hơn, ngắn hơn, các nhú quanh tiền đình và thành âm đạo trở nên phẳng. Niêm mạc âm đạo dần mỏng đi, nhạt màu, dễ bị loét trợt, giảm chế tiết và có thể phát triển các vùng dính.\n2.6. Âm hộ\nTrong giai đoạn sớm sau mãn kinh chỉ xuất hiện một số biến đổi nhỏ ở âm hộ, nhưng các thay đổi này sẽ trở nên rõ rệt (65 tuổi trở đi). Môi lớn nhỏ lại và mỏng hơn do lớp mỡ dưới da bị mất đi, môi bé nhỏ, đôi khi mất hẳn hoặc dính lại với nhau phía dưới âm vật, âm vật nhỏ dần. Các tuyến Skene, Bartholin teo nhỏ và ngừng chế tiết. Một số trường hợp teo và xơ hoá nặng dẫn đến xơ teo âm hộ.\n3. MỘT SỐ THAY ĐỔI TÂM SINH LÝ\n3.1. Các rối loạn vận mạch\nCơn \"bốc hoả\": là cơn phừng nóng thoáng qua và tái diễn, kèm theo vã mồ hôi, cảm giác nóng toàn thân, hồi hộp đánh trống ngực, lo lắng, đôi khi kèm theo ớn lạnh sau đó.\n3.2. Các thay đổi tâm lý\nKhoảng 20% các phụ nữ trong độ tuổi mãn kinh có các biểu hiện rối loạn dạng trầm cảm.\nỞ một số phụ nữ có thể gặp thay đổi tính tình, giảm ham muốn tình dục, giảm tập trung, mất ngủ.\n3.3. Các thay đổi nội tiết\nỞ phụ nữ tiền mãn kinh - mãn kinh, buồng trứng teo nhỏ nhanh chóng và giảm số lượng noãn bào đáng kể. Buồng trứng trở nên kém nhạy cảm đối với những kích thích từ trục dưới đồi - tuyến yên dẫn đến giảm lượng 17-estradiol (E2). Đồng thời, nồng độ FSH tăng. Các androgen trong cơ thể phụ nữ bình thường được sản xuất từ tuyến thượng thận và mô liên kết của rốn và tuỷ buồng trứng. Hoạt động sản xuất androgen này vẫn tiếp tục cho đến giai đoạn sau mãn kinh. Một số mô trong cơ thể như gan, cơ, da, tử cung và đặc biệt là mô mỡ dưới da có thể chuyển hoá androgen thành estrogen nhờ men thơm hoá, chủ yếu là chuyển androstenedione thành estrone, do đó nồng độ estrone thay đổi không đáng kể sau mãn kinh.\n\n4. CÁC BỆNH LÝ THƯỜNG GẶP TRONG THỜI KỲ MÃN KINH\n4.1. Viêm âm hộ - âm đạo do thiểu dưỡng\nKhoảng 40% phụ nữ mãn kinh có triệu chứng của viêm âm đạo thiểu dưỡng, triệu chứng sớm nhất là giảm độ ẩm của môi trường âm đạo. Các triệu chứng ở âm đạo bao gồm khô, đau khi giao hợp và viêm nhiễm âm đạo tái diễn. Niêm mạc âm đạo và cổ tử cung bắt màu kém với dung dịch Lugol.\nCó nhiều yếu tố gây ra sự gia tăng rõ rệt các viêm nhiễm âm hộ - âm đạo ở độ tuổi này:\n- Thiểu năng estrogen làm giảm hệ vi khuẩn chí âm đạo, pH trở nên kiềm, tạo điều kiện cho sự xâm nhập của hệ vi khuẩn đường ruột vào môi trường âm đạo thiểu dưỡng niêm mạc âm đạo.\n- Sự suy giảm miễn dịch tế bào và miễn dịch thể dịch.\nCác triệu chứng lâm sàng có thể đơn thuần ở bộ phận sinh dục hoặc phối hợp với bệnh lý đường tiết niệu (buốt, đau khi tiểu tiện... ). Trong trường hợp có viêm âm đạo nhiễm khuẩn kèm theo, tác nhân thường gặp Gardnerella, Candida albican, vi khuẩn đường ruột (E. Coli), hiếm gặp Trichomonas vaginalis.\n\n4.2. Són tiểu\nỞ phụ nữ tiền mãn kinh – mãn kinh, suy cơ thắt niệu đạo ảnh hưởng chức năng co thắt bình thường, niêm mạc niệu đạo thiểu dưỡng gây cảm giác són tiểu, tiểu lắt nhắt.\n4.3. Loãng xương\nNhư mọi tổ chức khác trong cơ thể, hệ xương cũng bị lão hoá. Các thay đổi của hệ xương xảy ra do tăng tiêu xương và kém hấp thu Canxi dẫn đến làm yếu các xương trong cơ thể, nên dễ gãy xương sau sang chấn và gãy xương bệnh lý. Có thể dự phòng loãng xương bằng một chế độ ăn giàu Canxi trong suốt đời người phụ nữ (từ thời thiếu niên) và tăng mức cung cấp sau mãn kinh và thường xuyên tập luyện thể dục tiếp sau mãn kinh.\n4.4. Các bệnh lý hệ tim mạch\nPhụ nữ lớn tuổi có nguy cơ mắc phải các bệnh lý tim mạch với một tần suất ngày càng gia tăng. Nguyên nhân thường gặp nhất gây nên bệnh lý tim mạch của độ tuổi này là tình trạng xơ vữa mạch máu, nếu xảy ra trên thành động mạch sẽ gây nên xơ vữa động mạch. Nồng độ estrogen cao trong giai đoạn hoạt động sinh dục có vai trò bảo vệ trong các biểu hiện sớm của bệnh tim mạch thông qua một cơ chế duy trì nồng độ HDL cao và LDL thấp. Sự thiếu hụt estrogen nội sinh khi mãn kinh làm cho tỷ lệ này thay đổi theo hướng ngược lại, tạo điều kiện cho sự hình thành các tổn thương xơ vữa.\n\n5. CÁC UNG THƯ PHỤ KHOA\n5.1. Ung thư niêm mạc tử cung\nUng thư biểu mô tuyến niêm mạc tử cung phát triển trong thân tử cung, còn được gọi là ung thư thân tử cung. Đỉnh cao của bệnh ở tuổi 55 - 65.\nChảy máu sau mãn kinh là triệu chứng thường gặp nhất và gặp sớm trong quá trình bệnh. Việc chẩn đoán dựa vào kết quả giải phẫu bệnh lý qua sinh thiết nội mạc tử cung.\n5.2. Ung thư vú\nCho đến nay, tình trạng tăng nồng độ estrogen kéo dài có thể là yếu tố nguy cơ gây ung thư vú. Đối với phụ nữ tiền mãn kinh – mãn kinh, nếu có ra máu âm đạo bất thường hay đau vú cần được khảo sát cẩn thận về bệnh lý tuyến vú, đặc biệt là ung thư vú.\n5.3. Ung thư cổ tử cung\nĐây là một bệnh lý có thể gặp trong độ tuổi tiền mãn kinh – mãn kinh, nhưng nguyên nhân gây bệnh không phải do rối loạn nội tiết.\n\n6. TƯ VẤN SỨC KHOẺ CHO PHỤ NỮ TIỀN MÃN KINH - MÃN KINH\n6.1. Các vấn đề cần tư vấn\n- Khám phụ khoa định kỳ là quan trọng đối với người có tuổi\n- Cung cấp thông tin về giai đoạn tắt dục mãn kinh và tính chất bình thường của giai đoạn này trong đời người phụ nữ\n- Hỗ trợ cách đối phó với bệnh ác tính và các hậu quả của bệnh\n- Khuyên về dinh dưỡng\n- Khuyên phòng loãng xương\n- Khuyên về các hoạt động tình dục và tình dục an toàn\n- Tư vấn về các nhu cầu sau cắt bỏ vú, sau cắt tử cung.\n- Tư vấn này cần làm cho người phụ nữ và cả cho người chồng hoặc bạn tình.\n- Dinh dưỡng tốt và tập thể dục trong suốt cuộc đời sinh sản của phụ nữ sẽ phòng được một số vấn đề gặp sau mãn kinh cũng như cần có thói quen tiếp tục tập luyện khi đã có tuổi.\n\n\nCâu hỏi:\n1. Trình bày các thay đổi giải phẫu ở buồng trứng, âm hộ, âm đạo của người phụ nữ  trong thời kỳ mãn kinh?\n2. Trình bày các thay đổi về nội tiết và tâm sinh lý của người phụ nữ  trong thời kỳ mãn kinh?\n3. Trình bày các bệnh lý thường gặp trong thời kỳ mãn kinh", "priority": "Trung bình"}, {"id": "SK-54", "chapter": "Chương 6. Hỗ trợ sinh sản", "folder": "06_Ho_tro_sinh_san", "title": "Các phương pháp hỗ trợ sinh sản", "author": "Ths. Nguyễn Văn Hiền", "word_count": 3652, "line_count": 186, "key_numbers": ["0,5 ml", "1 ml", "1,5 ml", "1,5ml", "12 giờ", "15 phút", "150 mg", "1ml", "2 ml", "28 ngày", "2ml", "30 phút", "36 giờ", "5 ml", "5 ngày", "60 phút"], "key_drugs": [], "sections": [{"heading": "Đại cương / Giới thiệu", "paragraphs": ["CÁC PHƯƠNG PHÁP HỖ TRỢ SINH SẢN", "Ths. Nguyễn Văn Hiền"], "bullets": []}, {"heading": "Mục tiêu học tập", "paragraphs": ["1.Trình bày các phương pháp hỗ trợ sinh sản thường dùng", "2.Trình bày cơ chế phóng noãn và thăm dò phóng noãn, kích thích buồng trứng", "3.Trình bày tinh dịch đồ và các phương pháp lọc rửa", "4.Trình bày phương pháp bơm tinh tùng vào buồng tử cung IUI", "5.Trình bày phương pháp thụ tinh trong ống nghiệm và chuyển phôi IVF", "6.Trình bày phương pháp tiêm tinh trùng vào bào tương noãn ICSI", "7.Trình bày các phương pháp hỗ trợ sinh sản khác"], "bullets": []}, {"heading": "I. Các phương pháp hỗ trợ sinh sản thường dùng.", "paragraphs": ["Nam giới.", "Nữ giới."], "bullets": ["- Thụ tinh nhân tạo", "- Lọc rửa tinh trùng", "- Bơm tinh trùng vào buồng tử cung", "- Thụ tinh trong ống nghiệm và chuyển phôi IVF", "- Tiêm tinh trùng vào bào tương noãn ICSI", "- Phẩu thuật lấy tinh trùng", "- Phẩu thuật gỡ dính và tạo hình vòi tử cung", "- Kích thích phóng noãn", "- Đốt điểm và cắt góc buồng trứng", "- Bơm tinh trùng vào buồng tử cung", "- Thụ tinh trong ống nghiệm và chuyển phôi IVF", "- Tiêm tinh trùng vào bào tương noãn ICSI", "- Hỗ trợ phôi thoát màng", "- Nuôi trứng non trưởng thành trong ống nghiệm"]}, {"heading": "II. Cơ chế phóng noãn và thăm dò phóng noãn, kích thích buồng trứng.", "paragraphs": ["1.Cơ chế phóng noãn.", "Sự phóng noãn thường xảy ra vào ngày thứ 14 của chu kỳ kinh nguyệt đều 28 ngày. Nang noãn phát triển và trưởng thành phụ thuộc vào vùng dưới đồi tuyến yên (tiết ra FSH và LH), và buồng trứng. Hiện tượng vỡ nang noãn để giải phóng noãn trưởng thành gọi là hiện tượng phóng noãn.", "2.Thăm dò phóng noãn.", "Theo dõi đỉnh LH là một phương pháp chẩn đoán phóng noãn, sự phóng noãn xảy ra 34 đến 36 giờ sau khi có sự tăng nồng độ LH, và sau khi có đỉnh LH là 10 đến 12 giờ.", "Nếu có phóng noãn thì buồng trứng sẽ tăng tiết progesteron  làm tăng thân nhiệt lên từ 0,3 đến 0,5 độ. Đây là phương pháp ít tốn kém nhưng chỉ mang tính chất hồi cứu.", "Progesteron được tiết ra dưới dạng xung, nên ta xét nghiệm để tìm đỉnh của nồng độ progesteron (nồng độ > 3 ng/ml hoặc > 10 nmol/ ml), nên khi xét nghệm tại 1 thời điểm mà nồng độ thấp cũng không có giá trị loại trừ.", "Khi phóng noãn thì nang sẽ giảm kích thước, bờ sẽ méo mó, và xuất hiện dịch ở cùng đồ sau.", "Tiến hành ở giai đoạn hoàng thể vào ngày 21, niêm mạc tử cung có hình ảnh chế tiết. Nhưng hiện nay không dùng phương pháp này do độ chính xác không cao và chỉ có ý nghĩa hồi cứu."], "bullets": ["+ Định lượng LH.", "+ Theo dõi nhiệt độ.", "+ Định lượng progesteron giữa pha hoàng thể.(ngày 21 đến ngày thứ 23)", "+ Siêu âm theo dõi nang noãn.", "+ Sinh thiết niêm mạc tử cung."]}, {"heading": "3.1 Phác đồ Clomiphencitrat.", "paragraphs": ["Liều dùng 50- 150 mg, trong 5 ngày kể từ ngày thứ 2 của chu kỳ kinh nguyệt.", "Có thể bổ sung estrogen để cải thiện niêm mạc tử cung", "Tiêm hCG để trưởng thành noãn và phóng noãn."], "bullets": []}, {"heading": "3.2 Phác đồ Clomiphencitrat kết hợp với hMG/FSH", "paragraphs": ["Liều dùngClomiphencitrat 50- 150 mg, trong 5 ngày kể từ ngày thứ 2 của chu kỳ kinh nguyệt.", "Kết hợp tiêm hMG/FSH ở những ngày tiếp theo cho đến khi noang noãn đạt yêu cầu.", "Tiêm hCG để trưởng thành noãn và phóng noãn nếu đủ điều kiện."], "bullets": []}, {"heading": "3.3 Phác đồ hMG/FSH đơn thuần.", "paragraphs": ["Tiêm hMG/FSH bắt đầu từ ngày thứ 2 của chu kỳ kinh cho đến khi nang noãn đạt yêu cầu.", "Tiêm hCG để trưởng thành noãn và phóng noãn nếu đủ điều kiện."], "bullets": []}, {"heading": "3.4 Phác đồ GnRH + hMG/ FSH + hCG.", "paragraphs": ["Có 4 dạng là phác đồ cực ngắn, phác đồ ngắn, phác đồ dài, và phác đồ cực dài."], "bullets": []}, {"heading": "1. Tiêu chuẩn tinh dịch đồ theo WHO 2010", "paragraphs": [], "bullets": ["- Thời gian ly giải : Lúc mới xuất tinh, tinh dịch có chứa những hạt thạch giống như hạt rau câu, nhưng sau khoảng 30 phút chúng sẽ ly giải (hoá lỏng) hoàn toàn. Nếu quá 60 phút tinh dịch vẫn không ly giải là dấu hiện của sự bất thường.- pH tinh dịch:  ≥ 7,2- Thể tích tinh dịch cho một lần xuất tinh phải từ 1,5 ml trở lên.- Tổng số tinh trùng:  ≥ 39 triệu.- Mật độ tinh trùng: ít nhất 15 triệu tinh trùng trở lên trong 1 ml- Di động: phải có ít nhất 40% tinh trùng phải di chuyển hoặc 32% tinh trùng bơi về phía trước.- Hình dạng bình thường: có ít nhất 04% tinh trùng có hình dạng bình thường.- Tỉ lệ tinh trùng sống: 58% tinh trùng sống trở lên- Tế bào lạ: Ngoài tinh trùng, trong tinh dịch còn có các tế bào khác. Các tế bào lạ là các tế bào tròn, chúng có thể hiện diện trong tinh dịch với mật độ ≤ 1 triệu tế bào/ml. Nếu có các tế bào nhiều hơn, điều này có thể là một dấu hiệu của nhiễm trùng cơ quan sinh dục."]}, {"heading": "2. Các hình thái bất thường.", "paragraphs": [], "bullets": ["- Nhóm Oligospermia (chỉ có mật độ tinh trùng thấp hơn giới hạn tối thiểu)", "- Nhóm Athesnozoospermia (chỉ có độ di động của tinh trùng thấp hơn giới hạn tối thiểu)", "- Nhóm Teratospermia (chỉ có hình dạng tinh trùng bình thường thấp hơn giới hạn tối thiểu)", "- Nhóm Oligo - Athesnozoospermia (có đồng thời mật độ và độ di động của tinh trùng thấp hơn giới hạn tối thiểu)", "- Nhóm Oligo - Teratospermia (có đồng thời mật độ và hình dạng tinh trùng bình thường thấp hơn giới hạn tối thiểu)", "- Nhóm Athesno - Teratospermia (có đồng thời độ di động và hình dạng bình thường của tinh trùng thấp hơn giới hạn tối thiểu)", "- Nhóm OAT (Oligo Athesno Teratospermia): Nhóm tinh trùng ít, yếu và dị dạng", "- Nhóm Cryptozoospermia (có rất ít tinh trùng trong mẫu)", "- Nhóm Azoospermia (không tìm thấy tinh trùng trong cặn của mẫu xuất tinh)", "- Nhóm bình thường (các chỉ số về độ di động, mật độ và hình dạng bình thường của tinh trùng đều trên ngưỡng giới hạn tối thiểu)"]}, {"heading": "3. Các phương pháp loc rửa tinh trùng", "paragraphs": ["Có 2 phương pháp được áp dụng rộng rãi và đạt hiệu quả cao nhất là phương pháp bơi lên (Swim - up) và phương pháp sử dụng thang nồng độ percoll."], "bullets": []}, {"heading": "3.2  Phương pháp thang nồng độ percoll:Cách tiến hành:- Pha các dung môi percoll đẳng trương- Tạo thang môi trường: cho 2 lớp dung môi vào ống nghiệm, mỗi lớp 1ml- Cho 1,5 ml tinh dịch trên 2 lớp percoll thật nhẹ nhàng- Ly tâm 1500 vòng /phút trong 15 phút;- Hút bỏ những lớp trên, giữ lại 0,5 ml cặn ở đáy cho vào ống nghiệm mới với 2ml môi trường mới;- Ly tâm 1500 vòng /phút trong 15 phút;- Bỏ lớp môi trường giữ ở trên, giữ lại 0,3 - 0,5 ml cặn, trộn đều, lấy 1 giọt kiểm traNhận xét:Các dung môi percoll ở các nồng độ khác nhau có chức năng lọc, loại bỏ các tinh trùng yếu, chết, dị dạng, tinh trùng vận động kém và các thành phần khác trong tinh dịch. Phương pháp đơn giản, dễ thực hiện, với mẫu tinh trùng yếu hơn", "paragraphs": ["Thời gian thực hiện dài hơn Swim up."], "bullets": []}, {"heading": "IV. Bơm tinh trùng vào buồng tử cung IUI", "paragraphs": ["1.Khái niệm:", "Bơm tinh trùng vào buồng tử cung (intrauterine insemination - IUI) là kỹ thuật bơm mẫu tinh trùng đã được xử lý lọc rửa vào trong buồng tử cung. Đây là kỹ thuật được được áp dụng rộng rãi nhất trong điều trị vô sinh hiếm muộn, kỹ thuật này được Dickinson mô tả đầu tiên năm 1921 nhằm giảm một số  tác dụng có hại lên tinh trùng như pH acid của âm đạo, chất nhầy cổ tử cung không thuận lợi.", "Kỹ thuật này hiện tại trở thành kỹ thuật điều trị vô sinh hiếm muộn phổ biến và hiệu quả cho những trường hợp buồng trứng và vòi trứng còn hoạt động bình thường. Việc sử dụng tinh trùng qua lọc rửa đã làm tăng tỉ lệ thụ thai và giảm các tai biến như nhiễm trùng, co thắt tử cung, sốc phản vệ…"], "bullets": []}, {"heading": "2. Chỉ định IUI:", "paragraphs": [], "bullets": ["- Vô sinh do yếu tố cổ tử cung, kháng thể kháng tinh trùng, do chất nhầy cổ tử cung.", "- Vô sinh do rối loạn phóng noãn.", "- Vô sinh do tinh trùng ít, yếu, bất thường mức độ nhẹ.", "- Vô sinh do rối loạn xuất tinh, rối loạn cương dương.", "- Vô sinh không rõ nguyên nhân.", "- Phối hợp nhiều yếu tố bất thường trên."]}, {"heading": "3. Các bước thực hiện:", "paragraphs": [], "bullets": ["- Bệnh nhân nằm tư thế phụ khoa, trải săng vô trùng.", "- Lau âm hộ bằng nước muối sinh lý.", "- Đặt mỏ vịt, bộc lộ cổ tử cung.", "- Lau sạch âm đạo và cổ tử cung bằng nước muối sinh lý.", "- Hút mẫu tinh trùng đã lọc rửa vào bơm tiêm đã được gắn catheter.", "- Luồn catheter qua cổ tử cung vào buồng tử cung.", "- Bơm từ từ tinh trùng vào buồng tử cung.", "- Rút từ từ catheter ra khỏi buồng tử cung.", "- Tháo mỏ vịt, cho bệnh nhân nằm nghỉ 30 phút.", "- Trợ giúp pha hoàng thể."]}, {"heading": "4. Ưu điểm IUI", "paragraphs": [], "bullets": ["-  Kỹ thuật đơn giản, dễ thực hiện, có thể thực hiện nhiều lần, nếu có thể thực hiện nhiều lần (trung bình 3 lần), tỉ lệ có thai cộng dồn khá cao.", "-  Kết quả điều trị thay đổi tùy tiên lượng bệnh nhân và chỉ định điều trị."]}, {"heading": "5. Nhược điểm:", "paragraphs": [], "bullets": ["- Tỷ  lệ  thành công thay đổi rất nhiều tùy thuộc vào chỉ định điều trị và kỹ thuật thực hiện của từng trung tâm.", "- Thường phải thực hiện nhiều chu kỳ  điều trị, phối hợp kích thích buồng trứng.", "- Nguy cơ quá kích buồng trứng và đa thai."]}, {"heading": "V. Thụ tinh trong ống nghiệm và chuyển phôi - IVF(In-vitro Fertilization)", "paragraphs": ["Khái niệm:", "Kỹ thuật thụ tinh trong ống nghiệm và chuyển phôi có nghĩa là cho trứng và tinh trùng kết hợp với nhau trong phòng thí nghiệm, sau đó phôi hình thành sẽ được chuyển trở  lại vào buồng tửcung.", "Quá trình phát triển của phôi và thai sẽ diễn ra bình thường trong buồng tử cung của người mẹ.", "Khởi đầu, phương pháp này được chỉ định trong những trường hợp tắc ống dẫn trứng hai bên, hoặc hai vòi trứng đã bị cắt do phẫu thuật phụ khoa,làm cho tinh trùng và trứng không thể gặp nhau được trên vòi trứng và do đó không thể có sự  thụ  tinh. Nhưng sau đó phương pháp đã được mở  rộng ra những chỉ định khác, ngoài chỉ định tắc vòi trứng đơn thuần cổ điển như : Lạc nội mạc tử cung vùng chậu, vô sinh không rõ nguyên nhân thất bại nhiều chu kỳ với phương pháp bơm tinh trùng vào buồng tử cung, vô sinh nam do bất thường tinh trùng.", "Nguyên tắc của thụ  tinh trong ống nghiệm là kích thích buồng trứng để nhiều nang noãn phát triển trong một chu kỳ. Sau đó chọc hút nang noãn để lấy noãn ra bên ngoài cơ thể. Cho tinh trùng và noãn tiếp xúc với nhau bên ngoài cơ thể (trong phòng thí nghiệm). Khi phôi được hình thành sẽ được chuyển trở lại buồng tử cung người phụ nữ để phát triển thành thai bình thường."], "bullets": []}, {"heading": "2. Chỉ định:", "paragraphs": [], "bullets": ["- Tắc vòi trứng", "- Tinh trùng ít, yếu, dị dạng (không đủ để bơm tinh trùng vào buồng tử cung)", "- Phải lấy tinh trùng từ mào tinh, tinh hoàn", "- Vợ lớn tuổi", "- Bơm tinh trùng vào buồng tử cung nhiều lần thất bại."]}, {"heading": "2.6.  Sau khi có thai trên siêu âm, bệnh nhân được xem là có thai lâm sàng.", "paragraphs": ["3.Ưu điểm:"], "bullets": ["-  Ưu điểm lớn nhất của thụ  tinh trong ống nghiệm là hiệu quả điều trị cao hơn hẳn IUI. Hiệu quả của phương pháp điều trị này vượt trội so với các nguy cơ có thể xảy ra quá trình điều trị."]}, {"heading": "4. Nhược điểm:", "paragraphs": [], "bullets": ["-  Có một số nguy cơ có thể xảy ra cho người phụ nữ và trẻ như: hội chứng quá kích buồng trứng, đa thai, đẻ non…", "-  Chi phí điều trị cao.", "-  Thụ  tinh trong ống nghiệm không trực tiếp điều trị nguyên nhân gây vô sinh mà chỉ tạo điều kiện để quá trình thụ tinh diễn ra bên ngoài cơ thể."]}, {"heading": "VI. Bơm tinh trùng vào bào tương noãn - ICSI(Intracytoplasmic Sperm Injection)", "paragraphs": ["Khái niệm:", "Với chỉ 1 tinh trùng tiêm vào bào tương của một trứng, phương pháp này đã mở ra một cuộc cách mạng trong điều trị những trường hợp vô sinh do nguyên nhân Nam nặng mà với phương pháp thụ  tinh trong ống nghiệm thông thường không thể giải quyết được.", "Trên các bệnh nhân này, người ta có thể lấy ra một số  lượng rất ít tinh trùng từ  trong mào tinh, hoặc tinh hoàn, rồi sau đó thực hiện thủ thuật ICSI vào trứng của người vợ.", "Nguyên tắc của kỹ thuật ICSI là tiêm trực tiếp một tinh trùng vào bào tương noãn trưởng thành để tạo phôi. Phôi sau đó được chuyển vào tử cung người vợ và phát triển bình thường."], "bullets": []}, {"heading": "2. Ưu diểm và nhược điểm:", "paragraphs": [], "bullets": ["-  Tỷ lệ thụ tinh cao hơn, làm số phôi có được nhiều hơn", "-  Nhiều khả năng chọn lọc được phôi tốt để chuyển vào buồng tử cung khiến tỷ lệ có thai cao hơn", "- Nhiều yếu tố có thể ảnh hưởng đến tỷ lệ thành công của ICSI như tuổi người vợ, nguyên nhân vô sinh, số phôi chuyển, chất lượng phôi.", "- Tuy nhiên chi phí cao và đòi hỏi kỹ thuật phức tạp."]}, {"heading": "VII. Các phương pháp hỗ trợ sinh sản khác:", "paragraphs": ["Hiện  nay đã có nhiều phương pháp mới giúp nâng tỳ  lệ  thành công lên cao hơn.", "Nuôi trứng non trưởng thành trong ống nghiệm IVM (Invitro Maturation of Oocytes)", "Chọc hút trứng non từ buồng trứng vì nhiều lý do không thể kích thích buồng trứng của bệnh nhân. Sau đó cấy trứng trong môi trường chuyên biệt, thụ  tinh với trứng bằng kỹ thuật ICSI và chuyển phôi vào buồng tử cung.", "IVM thường áp dụng cho những trường hợp hội chứng buồng trứng đa nang cần làm thụ tinh trong ống nghiệm.", "Kỹ thuật hỗ trợ phôi thoát màng:", "Sau khi trứng và tinh trùng thụ tinh với kỹ thuật IVF hoặc ICSI, phôi được chuyển vào buồng tử cung để làm tổ và phát triển thành thai. Bao bên ngoài phôi là màng trong suốt. Trong một số trường hợp, lớp màng này bị cứng chắc bất thường hoặc không mỏng đi trong quá trình phôi phát triển, làm cho phôi không thể thoát ra ngoài và bám vào niêm mạc tử cung để làm tổ. Dựa trên giả thuyết đó, kỹ thuật làm mỏng hoặc làm thủng màng trong suốt bên ngoài phôi  đã giúp phôi dễ thoát ra ngoài và làm tổ vào tử cung. Nhờ đó giúp cải thiện tỉ lệ thành công khi làm thụ tinh trong ống nghiệm.", "Phương pháp này đặc biệt hiệu quả trong các trường hợp:", "Bệnh nhân thất bại nhiều lần mặc dù chất lượng phôi tốt", "Bệnh nhân chuyển phôi trữ lạnh", "Bệnh nhân ít phôi, lớn tuổi.", "Bệnh nhân có phôi có màng trong suốt dày bất thường"], "bullets": ["-   Bệnh nhân thực hiện kỹ thuật trưởng thành trứng non trong ống nghiệm (IVM)."]}, {"heading": "3. Phương pháp phẫu thuật lấy tinh trùng:", "paragraphs": ["Vô sinh do không có tinh trùng là trường hợp không tìm thấy tinh trùng trong tinh dịch. Không tinh trùng chia làm hai nhóm: tắc nghẽn và không tắc nghẽn.", "Trong trường hợp không tinh trùng do tắc, tinh hoàn vẫn sinh tinh bình thường nhưng tinh trùng không thể ra bên ngoài. Nguyên nhân thường gặp là do bẩm sinh, nhiễm trùng đường sinh dục hoặc do thắt ống dẫn tinh. Trong cả hai trường hợp vô sinh không có tinh trùng do tắc hay không do tắc, người ta đều có thể phẫu thuật để lấy tinh trùng và thực hiện ICSI.", "Lấy tinh trùng từ mào tinh bằng vi phẫu thuật (MESA): Là phương pháp thu tinh trùng qua phẫu thuật mào tinh. Tỷ lệ thành công của MESA trên 90% và tinh trùng thường thu được nhiều và có thể trữ lạnh.", "Kỹ thuật này chỉ thực hiện với trường hợp không có tinh trùng do tắc.", "Lấy tinh trùng từ mào tinh bằng xuyên kim qua da (PESA): Là phương pháp thu tinh trùng mà không cần phẫu thuật mở bao tinh hoàn và bộc lộ mào tinh.", "Lấy tinh trùng từ tinh hoàn bằng chọc hút (TESA): Sau khi gây tê và cố định tinh hoàn, phẫu thuật viên đâm kim qua da vào mô tinh hoàn và hút từ từ ra mẫu mô.", "Thường phải hút nhiều mẫu mô ở nhiều vị trí khác nhau.", "Kỹ thuật này có thể thực hiện cho cả 2 trường hợp không có tinh trùng do tắc hoặc không do tắc.", "Lấy tinh trùng từ tinh hoàn bằng phẫu thuật xẻ tinh hoàn (TESE):", "Kỹ thuật này tương tự sinh thiết tinh hoàn. Phẫu thuật bộc lộ tinh hoàn và lấy nhiều mẫu mô tinh hoàn. Các mẫu thu được sẽ được tách nhỏ hoặc sử dụng một số loại men để tăng khả", "năng thu được tinh trùng từ các ống sinh tinh. Tỷ lệ thu được tinh trùng khoảng 50% đối với các trường hợp không có tinh trùng không do tắc. Kỹ thuật này có thể thực hiện cho cả 2 trường hợp không có tinh trùng do tắc hoặc không do tắc."], "bullets": []}, {"heading": "7. Trình bày các phương pháp hỗ trợ sinh sản khác?", "paragraphs": ["Tài liệu tham khảo:"], "bullets": []}], "raw_text": "CÁC PHƯƠNG PHÁP HỖ TRỢ SINH SẢN\nThs. Nguyễn Văn Hiền\nMục tiêu học tập\n\n1.Trình bày các phương pháp hỗ trợ sinh sản thường dùng\n2.Trình bày cơ chế phóng noãn và thăm dò phóng noãn, kích thích buồng trứng\n3.Trình bày tinh dịch đồ và các phương pháp lọc rửa\n4.Trình bày phương pháp bơm tinh tùng vào buồng tử cung IUI\n5.Trình bày phương pháp thụ tinh trong ống nghiệm và chuyển phôi IVF\n6.Trình bày phương pháp tiêm tinh trùng vào bào tương noãn ICSI\n7.Trình bày các phương pháp hỗ trợ sinh sản khác\n\nI. Các phương pháp hỗ trợ sinh sản thường dùng.\nNam giới.\n- Thụ tinh nhân tạo\n- Lọc rửa tinh trùng\n- Bơm tinh trùng vào buồng tử cung\n- Thụ tinh trong ống nghiệm và chuyển phôi IVF\n- Tiêm tinh trùng vào bào tương noãn ICSI\n- Phẩu thuật lấy tinh trùng\nNữ giới.\n- Phẩu thuật gỡ dính và tạo hình vòi tử cung\n- Kích thích phóng noãn\n- Đốt điểm và cắt góc buồng trứng\n- Bơm tinh trùng vào buồng tử cung\n- Thụ tinh trong ống nghiệm và chuyển phôi IVF\n- Tiêm tinh trùng vào bào tương noãn ICSI\n- Hỗ trợ phôi thoát màng\n- Nuôi trứng non trưởng thành trong ống nghiệm\nII. Cơ chế phóng noãn và thăm dò phóng noãn, kích thích buồng trứng.\n1.Cơ chế phóng noãn.\nSự phóng noãn thường xảy ra vào ngày thứ 14 của chu kỳ kinh nguyệt đều 28 ngày. Nang noãn phát triển và trưởng thành phụ thuộc vào vùng dưới đồi tuyến yên (tiết ra FSH và LH), và buồng trứng. Hiện tượng vỡ nang noãn để giải phóng noãn trưởng thành gọi là hiện tượng phóng noãn.\n2.Thăm dò phóng noãn.\n+ Định lượng LH.\nTheo dõi đỉnh LH là một phương pháp chẩn đoán phóng noãn, sự phóng noãn xảy ra 34 đến 36 giờ sau khi có sự tăng nồng độ LH, và sau khi có đỉnh LH là 10 đến 12 giờ.\n+ Theo dõi nhiệt độ.\nNếu có phóng noãn thì buồng trứng sẽ tăng tiết progesteron  làm tăng thân nhiệt lên từ 0,3 đến 0,5 độ. Đây là phương pháp ít tốn kém nhưng chỉ mang tính chất hồi cứu.\n+ Định lượng progesteron giữa pha hoàng thể.(ngày 21 đến ngày thứ 23)\nProgesteron được tiết ra dưới dạng xung, nên ta xét nghiệm để tìm đỉnh của nồng độ progesteron (nồng độ > 3 ng/ml hoặc > 10 nmol/ ml), nên khi xét nghệm tại 1 thời điểm mà nồng độ thấp cũng không có giá trị loại trừ.\n+ Siêu âm theo dõi nang noãn.\nKhi phóng noãn thì nang sẽ giảm kích thước, bờ sẽ méo mó, và xuất hiện dịch ở cùng đồ sau.\n+ Sinh thiết niêm mạc tử cung.\nTiến hành ở giai đoạn hoàng thể vào ngày 21, niêm mạc tử cung có hình ảnh chế tiết. Nhưng hiện nay không dùng phương pháp này do độ chính xác không cao và chỉ có ý nghĩa hồi cứu.\n3. Phác đồ kích thích buồng trứng.\n3.1 Phác đồ Clomiphencitrat.\nLiều dùng 50- 150 mg, trong 5 ngày kể từ ngày thứ 2 của chu kỳ kinh nguyệt.\nCó thể bổ sung estrogen để cải thiện niêm mạc tử cung\nTiêm hCG để trưởng thành noãn và phóng noãn.\n3.2 Phác đồ Clomiphencitrat kết hợp với hMG/FSH\nLiều dùngClomiphencitrat 50- 150 mg, trong 5 ngày kể từ ngày thứ 2 của chu kỳ kinh nguyệt.\nKết hợp tiêm hMG/FSH ở những ngày tiếp theo cho đến khi noang noãn đạt yêu cầu.\nTiêm hCG để trưởng thành noãn và phóng noãn nếu đủ điều kiện.\n3.3 Phác đồ hMG/FSH đơn thuần.\nTiêm hMG/FSH bắt đầu từ ngày thứ 2 của chu kỳ kinh cho đến khi nang noãn đạt yêu cầu.\nTiêm hCG để trưởng thành noãn và phóng noãn nếu đủ điều kiện.\n3.4 Phác đồ GnRH + hMG/ FSH + hCG.\nCó 4 dạng là phác đồ cực ngắn, phác đồ ngắn, phác đồ dài, và phác đồ cực dài.\nIII. Tinh dịch đồ\n1. Tiêu chuẩn tinh dịch đồ theo WHO 2010\n- Thời gian ly giải : Lúc mới xuất tinh, tinh dịch có chứa những hạt thạch giống như hạt rau câu, nhưng sau khoảng 30 phút chúng sẽ ly giải (hoá lỏng) hoàn toàn. Nếu quá 60 phút tinh dịch vẫn không ly giải là dấu hiện của sự bất thường.- pH tinh dịch:  ≥ 7,2- Thể tích tinh dịch cho một lần xuất tinh phải từ 1,5 ml trở lên.- Tổng số tinh trùng:  ≥ 39 triệu.- Mật độ tinh trùng: ít nhất 15 triệu tinh trùng trở lên trong 1 ml- Di động: phải có ít nhất 40% tinh trùng phải di chuyển hoặc 32% tinh trùng bơi về phía trước.- Hình dạng bình thường: có ít nhất 04% tinh trùng có hình dạng bình thường.- Tỉ lệ tinh trùng sống: 58% tinh trùng sống trở lên- Tế bào lạ: Ngoài tinh trùng, trong tinh dịch còn có các tế bào khác. Các tế bào lạ là các tế bào tròn, chúng có thể hiện diện trong tinh dịch với mật độ ≤ 1 triệu tế bào/ml. Nếu có các tế bào nhiều hơn, điều này có thể là một dấu hiệu của nhiễm trùng cơ quan sinh dục.\n2. Các hình thái bất thường.\n- Nhóm Oligospermia (chỉ có mật độ tinh trùng thấp hơn giới hạn tối thiểu)\n- Nhóm Athesnozoospermia (chỉ có độ di động của tinh trùng thấp hơn giới hạn tối thiểu)\n- Nhóm Teratospermia (chỉ có hình dạng tinh trùng bình thường thấp hơn giới hạn tối thiểu)\n- Nhóm Oligo - Athesnozoospermia (có đồng thời mật độ và độ di động của tinh trùng thấp hơn giới hạn tối thiểu)\n- Nhóm Oligo - Teratospermia (có đồng thời mật độ và hình dạng tinh trùng bình thường thấp hơn giới hạn tối thiểu)\n- Nhóm Athesno - Teratospermia (có đồng thời độ di động và hình dạng bình thường của tinh trùng thấp hơn giới hạn tối thiểu)\n- Nhóm OAT (Oligo Athesno Teratospermia): Nhóm tinh trùng ít, yếu và dị dạng\n- Nhóm Cryptozoospermia (có rất ít tinh trùng trong mẫu)\n- Nhóm Azoospermia (không tìm thấy tinh trùng trong cặn của mẫu xuất tinh)\n- Nhóm bình thường (các chỉ số về độ di động, mật độ và hình dạng bình thường của tinh trùng đều trên ngưỡng giới hạn tối thiểu)\n3. Các phương pháp loc rửa tinh trùng\nCó 2 phương pháp được áp dụng rộng rãi và đạt hiệu quả cao nhất là phương pháp bơi lên (Swim - up) và phương pháp sử dụng thang nồng độ percoll.\n3.1 Phương pháp Swim - up:Cách tiến hành:- Cho vào ống nghiệm  môi trường nuôi cấy- Cho 1-1,5ml tinh dịch đã ly giải thật nhẹ nhàng xuống dưới lớp môi trường - Đặt ống nghiệm trong tủ cấy khoảng 45 - 60 phút- Lấy 0,7 - 1 ml phần trên của cột môi trường cho vào ống nghiệm loại 5 ml- Cho thêm 2 ml môi trường và trộn đều- Ly tâm 1500 vòng/phút trong 15 phút- Hút bỏ lớp môi trường ở, để lại 0,4 -0,5 ml- Trộn đều, lấy 1 giọt cho vào buồng đếm kiểm tra lạiNhận xét:- Chỉ những tinh trùng di động tốt sẽ bơi lên trên, thoát khỏi lớp tinh dịch phía dưới.- Phương pháp đơn giản dễ làm- Tinh trùng chọn lọc có chất lượng cao- Chỉ áp dụng mẫu tinh dịch mà tinh trùng chất lượng tương đối tốt\n3.2  Phương pháp thang nồng độ percoll:Cách tiến hành:- Pha các dung môi percoll đẳng trương- Tạo thang môi trường: cho 2 lớp dung môi vào ống nghiệm, mỗi lớp 1ml- Cho 1,5 ml tinh dịch trên 2 lớp percoll thật nhẹ nhàng- Ly tâm 1500 vòng /phút trong 15 phút;- Hút bỏ những lớp trên, giữ lại 0,5 ml cặn ở đáy cho vào ống nghiệm mới với 2ml môi trường mới;- Ly tâm 1500 vòng /phút trong 15 phút;- Bỏ lớp môi trường giữ ở trên, giữ lại 0,3 - 0,5 ml cặn, trộn đều, lấy 1 giọt kiểm traNhận xét:Các dung môi percoll ở các nồng độ khác nhau có chức năng lọc, loại bỏ các tinh trùng yếu, chết, dị dạng, tinh trùng vận động kém và các thành phần khác trong tinh dịch. Phương pháp đơn giản, dễ thực hiện, với mẫu tinh trùng yếu hơn\nThời gian thực hiện dài hơn Swim up.\nIV. Bơm tinh trùng vào buồng tử cung IUI\n1.Khái niệm:\nBơm tinh trùng vào buồng tử cung (intrauterine insemination - IUI) là kỹ thuật bơm mẫu tinh trùng đã được xử lý lọc rửa vào trong buồng tử cung. Đây là kỹ thuật được được áp dụng rộng rãi nhất trong điều trị vô sinh hiếm muộn, kỹ thuật này được Dickinson mô tả đầu tiên năm 1921 nhằm giảm một số  tác dụng có hại lên tinh trùng như pH acid của âm đạo, chất nhầy cổ tử cung không thuận lợi.\nKỹ thuật này hiện tại trở thành kỹ thuật điều trị vô sinh hiếm muộn phổ biến và hiệu quả cho những trường hợp buồng trứng và vòi trứng còn hoạt động bình thường. Việc sử dụng tinh trùng qua lọc rửa đã làm tăng tỉ lệ thụ thai và giảm các tai biến như nhiễm trùng, co thắt tử cung, sốc phản vệ…\n2. Chỉ định IUI:\n- Vô sinh do yếu tố cổ tử cung, kháng thể kháng tinh trùng, do chất nhầy cổ tử cung.\n- Vô sinh do rối loạn phóng noãn.\n- Vô sinh do tinh trùng ít, yếu, bất thường mức độ nhẹ.\n- Vô sinh do rối loạn xuất tinh, rối loạn cương dương.\n- Vô sinh không rõ nguyên nhân.\n- Phối hợp nhiều yếu tố bất thường trên.\n3. Các bước thực hiện:\n- Bệnh nhân nằm tư thế phụ khoa, trải săng vô trùng.\n- Lau âm hộ bằng nước muối sinh lý.\n- Đặt mỏ vịt, bộc lộ cổ tử cung.\n- Lau sạch âm đạo và cổ tử cung bằng nước muối sinh lý.\n- Hút mẫu tinh trùng đã lọc rửa vào bơm tiêm đã được gắn catheter.\n- Luồn catheter qua cổ tử cung vào buồng tử cung.\n- Bơm từ từ tinh trùng vào buồng tử cung.\n- Rút từ từ catheter ra khỏi buồng tử cung.\n- Tháo mỏ vịt, cho bệnh nhân nằm nghỉ 30 phút.\n- Trợ giúp pha hoàng thể.\n4. Ưu điểm IUI\n-  Kỹ thuật đơn giản, dễ thực hiện, có thể thực hiện nhiều lần, nếu có thể thực hiện nhiều lần (trung bình 3 lần), tỉ lệ có thai cộng dồn khá cao.\n-  Kết quả điều trị thay đổi tùy tiên lượng bệnh nhân và chỉ định điều trị.\n5. Nhược điểm:\n- Tỷ  lệ  thành công thay đổi rất nhiều tùy thuộc vào chỉ định điều trị và kỹ thuật thực hiện của từng trung tâm.\n- Thường phải thực hiện nhiều chu kỳ  điều trị, phối hợp kích thích buồng trứng.\n- Nguy cơ quá kích buồng trứng và đa thai.\n\nV. Thụ tinh trong ống nghiệm và chuyển phôi - IVF(In-vitro Fertilization)\nKhái niệm:\nKỹ thuật thụ tinh trong ống nghiệm và chuyển phôi có nghĩa là cho trứng và tinh trùng kết hợp với nhau trong phòng thí nghiệm, sau đó phôi hình thành sẽ được chuyển trở  lại vào buồng tửcung.\nQuá trình phát triển của phôi và thai sẽ diễn ra bình thường trong buồng tử cung của người mẹ.\nKhởi đầu, phương pháp này được chỉ định trong những trường hợp tắc ống dẫn trứng hai bên, hoặc hai vòi trứng đã bị cắt do phẫu thuật phụ khoa,làm cho tinh trùng và trứng không thể gặp nhau được trên vòi trứng và do đó không thể có sự  thụ  tinh. Nhưng sau đó phương pháp đã được mở  rộng ra những chỉ định khác, ngoài chỉ định tắc vòi trứng đơn thuần cổ điển như : Lạc nội mạc tử cung vùng chậu, vô sinh không rõ nguyên nhân thất bại nhiều chu kỳ với phương pháp bơm tinh trùng vào buồng tử cung, vô sinh nam do bất thường tinh trùng.\nNguyên tắc của thụ  tinh trong ống nghiệm là kích thích buồng trứng để nhiều nang noãn phát triển trong một chu kỳ. Sau đó chọc hút nang noãn để lấy noãn ra bên ngoài cơ thể. Cho tinh trùng và noãn tiếp xúc với nhau bên ngoài cơ thể (trong phòng thí nghiệm). Khi phôi được hình thành sẽ được chuyển trở lại buồng tử cung người phụ nữ để phát triển thành thai bình thường.\n2. Chỉ định:\n- Tắc vòi trứng\n- Tinh trùng ít, yếu, dị dạng (không đủ để bơm tinh trùng vào buồng tử cung)\n- Phải lấy tinh trùng từ mào tinh, tinh hoàn\n- Vợ lớn tuổi\n- Bơm tinh trùng vào buồng tử cung nhiều lần thất bại.\n3. Các bước thực hiện:\n2.1.  Tiêm thuốc kích trứng cho người vợ, với những liều thích hợp và với những phác đồ khác nhau tùy từng bệnh nhân để tạo nhiều nang noãn phát triển từ 2 buồng trứng.\n2.2.  Chọc hút qua đầu dò siêu âm để lấy những noãn bào trong các nang trứng đó.\n2.3.  Cho tinh trùng thụ tinh với trứng\n2.4.  Sau khi phát triển thành phôi, thực hiện việc chuyển phôi vào buồng tử cung. Sau thì này, việc có thai phụ thuộc vào sự làm tổ của phôi vào nội mạc tử cung.\n2.5.  Hai tuần sau chuyển phôi, định lượng beta HCG để xác định có thai hay không. Nếu beta HCG (+), bệnh nhân được xem là có thai sinh hóa.\n2.6.  Sau khi có thai trên siêu âm, bệnh nhân được xem là có thai lâm sàng.\n3.Ưu điểm:\n-  Ưu điểm lớn nhất của thụ  tinh trong ống nghiệm là hiệu quả điều trị cao hơn hẳn IUI. Hiệu quả của phương pháp điều trị này vượt trội so với các nguy cơ có thể xảy ra quá trình điều trị.\n4. Nhược điểm:\n-  Có một số nguy cơ có thể xảy ra cho người phụ nữ và trẻ như: hội chứng quá kích buồng trứng, đa thai, đẻ non…\n-  Chi phí điều trị cao.\n-  Thụ  tinh trong ống nghiệm không trực tiếp điều trị nguyên nhân gây vô sinh mà chỉ tạo điều kiện để quá trình thụ tinh diễn ra bên ngoài cơ thể.\n\nVI. Bơm tinh trùng vào bào tương noãn - ICSI(Intracytoplasmic Sperm Injection)\nKhái niệm:\nVới chỉ 1 tinh trùng tiêm vào bào tương của một trứng, phương pháp này đã mở ra một cuộc cách mạng trong điều trị những trường hợp vô sinh do nguyên nhân Nam nặng mà với phương pháp thụ  tinh trong ống nghiệm thông thường không thể giải quyết được.\nTrên các bệnh nhân này, người ta có thể lấy ra một số  lượng rất ít tinh trùng từ  trong mào tinh, hoặc tinh hoàn, rồi sau đó thực hiện thủ thuật ICSI vào trứng của người vợ.\nNguyên tắc của kỹ thuật ICSI là tiêm trực tiếp một tinh trùng vào bào tương noãn trưởng thành để tạo phôi. Phôi sau đó được chuyển vào tử cung người vợ và phát triển bình thường.\n2. Ưu diểm và nhược điểm:\n-  Tỷ lệ thụ tinh cao hơn, làm số phôi có được nhiều hơn\n-  Nhiều khả năng chọn lọc được phôi tốt để chuyển vào buồng tử cung khiến tỷ lệ có thai cao hơn\n- Nhiều yếu tố có thể ảnh hưởng đến tỷ lệ thành công của ICSI như tuổi người vợ, nguyên nhân vô sinh, số phôi chuyển, chất lượng phôi.\n- Tuy nhiên chi phí cao và đòi hỏi kỹ thuật phức tạp.\n\nVII. Các phương pháp hỗ trợ sinh sản khác:\nHiện  nay đã có nhiều phương pháp mới giúp nâng tỳ  lệ  thành công lên cao hơn.\nNuôi trứng non trưởng thành trong ống nghiệm IVM (Invitro Maturation of Oocytes)\nChọc hút trứng non từ buồng trứng vì nhiều lý do không thể kích thích buồng trứng của bệnh nhân. Sau đó cấy trứng trong môi trường chuyên biệt, thụ  tinh với trứng bằng kỹ thuật ICSI và chuyển phôi vào buồng tử cung.\nIVM thường áp dụng cho những trường hợp hội chứng buồng trứng đa nang cần làm thụ tinh trong ống nghiệm.\nKỹ thuật hỗ trợ phôi thoát màng:\nSau khi trứng và tinh trùng thụ tinh với kỹ thuật IVF hoặc ICSI, phôi được chuyển vào buồng tử cung để làm tổ và phát triển thành thai. Bao bên ngoài phôi là màng trong suốt. Trong một số trường hợp, lớp màng này bị cứng chắc bất thường hoặc không mỏng đi trong quá trình phôi phát triển, làm cho phôi không thể thoát ra ngoài và bám vào niêm mạc tử cung để làm tổ. Dựa trên giả thuyết đó, kỹ thuật làm mỏng hoặc làm thủng màng trong suốt bên ngoài phôi  đã giúp phôi dễ thoát ra ngoài và làm tổ vào tử cung. Nhờ đó giúp cải thiện tỉ lệ thành công khi làm thụ tinh trong ống nghiệm.\nPhương pháp này đặc biệt hiệu quả trong các trường hợp:\nBệnh nhân thất bại nhiều lần mặc dù chất lượng phôi tốt\nBệnh nhân chuyển phôi trữ lạnh\nBệnh nhân ít phôi, lớn tuổi.\nBệnh nhân có phôi có màng trong suốt dày bất thường\n-   Bệnh nhân thực hiện kỹ thuật trưởng thành trứng non trong ống nghiệm (IVM).\n3. Phương pháp phẫu thuật lấy tinh trùng:\nVô sinh do không có tinh trùng là trường hợp không tìm thấy tinh trùng trong tinh dịch. Không tinh trùng chia làm hai nhóm: tắc nghẽn và không tắc nghẽn.\nTrong trường hợp không tinh trùng do tắc, tinh hoàn vẫn sinh tinh bình thường nhưng tinh trùng không thể ra bên ngoài. Nguyên nhân thường gặp là do bẩm sinh, nhiễm trùng đường sinh dục hoặc do thắt ống dẫn tinh. Trong cả hai trường hợp vô sinh không có tinh trùng do tắc hay không do tắc, người ta đều có thể phẫu thuật để lấy tinh trùng và thực hiện ICSI.\nLấy tinh trùng từ mào tinh bằng vi phẫu thuật (MESA): Là phương pháp thu tinh trùng qua phẫu thuật mào tinh. Tỷ lệ thành công của MESA trên 90% và tinh trùng thường thu được nhiều và có thể trữ lạnh.\nKỹ thuật này chỉ thực hiện với trường hợp không có tinh trùng do tắc.\nLấy tinh trùng từ mào tinh bằng xuyên kim qua da (PESA): Là phương pháp thu tinh trùng mà không cần phẫu thuật mở bao tinh hoàn và bộc lộ mào tinh.\nLấy tinh trùng từ tinh hoàn bằng chọc hút (TESA): Sau khi gây tê và cố định tinh hoàn, phẫu thuật viên đâm kim qua da vào mô tinh hoàn và hút từ từ ra mẫu mô.\nThường phải hút nhiều mẫu mô ở nhiều vị trí khác nhau.\nKỹ thuật này có thể thực hiện cho cả 2 trường hợp không có tinh trùng do tắc hoặc không do tắc.\nLấy tinh trùng từ tinh hoàn bằng phẫu thuật xẻ tinh hoàn (TESE):\nKỹ thuật này tương tự sinh thiết tinh hoàn. Phẫu thuật bộc lộ tinh hoàn và lấy nhiều mẫu mô tinh hoàn. Các mẫu thu được sẽ được tách nhỏ hoặc sử dụng một số loại men để tăng khả\nnăng thu được tinh trùng từ các ống sinh tinh. Tỷ lệ thu được tinh trùng khoảng 50% đối với các trường hợp không có tinh trùng không do tắc. Kỹ thuật này có thể thực hiện cho cả 2 trường hợp không có tinh trùng do tắc hoặc không do tắc.\n\nCâu hỏi:\n1. Trình bày các phương pháp hỗ trợ sinh sản thường dùng?\n2. Trình bày cơ chế phóng noãn và thăm dò phóng noãn, kích thích buồng trứng?\n3. Trình bày phương pháp bơm tinh   trùng vào buồng tử cung IUI?\n4. Trình bày phương pháp thụ tinh trong ống nghiệm và chuyển phôi IVF?\n6. Trình bày phương pháp tiêm tinh trùng vào bào tương noãn ICSI?\n7. Trình bày các phương pháp hỗ trợ sinh sản khác?\nTài liệu tham khảo:\n1.\tHướng dẫn quốc gia về các dịch vụ chăm sóc sức khỏe sinh sản - Bộ Y Tế - Hà Nội 2009\n2.\tBài giảng Sản Phụ khoa tập 1 - Bộ môn Sản - Trường đại học Y Hà Nội - NXB Y học 2002\n3.\t Bài giảng Sản Phụ khoa tập 2 - Bộ môn Sản - Trường đại học Y Hà Nội - NXB Y học 2002\n4.\tSản Phụ khoa tập 1- Bộ môn Sản - Trường đại học Y Dược TP. Hồ Chí Minh - NXB Y học 2007\n5.\tSản Phụ khoa tập 2- Bộ môn Sản - Trường đại học Y Dược TP. Hồ Chí Minh - NXB Y học 2007\n6.\tSản Phụ khoa Sách đào tạo bác sĩ đa khoa - Bộ Y Tế - NXB Y học - Hà Nội 2007\n7. \tHướng dẫn quốc gia về các dịch vụ chăm sóc sức khỏe sinh sản - Bộ Y Tế - Hà Nội 2016\n8. \tWilliams Obstetrics, 25rd edition, Copyright © 2016 by McGraw-Hill Education. All rights reserved.\n9. \tWilliams gynecology third edition, Copyright © 2016, 2012, 2008 by McGraw-Hill Education. All rights reserved.", "priority": "Trung bình"}];